// 概要　　：マニュアルキャリブレーション : １秒タイマ.
void PManualCalibration::procSecond( uchar option )
{
	if( True == bl_isCalibrationStart ) {
		uc_TimerCount = 0;
		return;
	}
	uc_TimerCount++;
	if( 5 < uc_TimerCount ) {
		bl_isCalibrationStart = True;
#if !defined(DEF_MinervaPreEmu) && !defined(DEF_ZeusRevCus)
//		int buf;
// comment 2015/03/11 OPS1 Sky江波戸 [ZeusS][CQ510887] キャリブレーションの実行を指示する必要がある.
//		int buf = 0;
//		sysBspIoctlPanelSio( (void *)buf, EXDB_PanelCalibration );
// Comment 2019/11/27 [HCLT_Selvaraj] [IT6_EagleZplus] [OP_BTS-11276] Address Sanitizer correction for EagleZplus Models.
		uint64_t bl_request = 1;
		sysBspIoctlPanelSio( &bl_request, EXDB_PanelCalibration );
#endif
	}
}
// 概要　　：マニュアルキャリブレーション : 画面開始処理.
void PManualCalibration::startGamen()
{
	PBasicMessageProc::startGamen();

	uc_TimerCount = 0;
	bl_isCalibrationStart = False;
}

