{
	if( ( option == 18 ) || ( option == 19 ) ) {	// +,-キー
		procButtonOn( option );
	}
}
//================================================================================================
// 概要　　 ：サービス・マシン調整・副走査倍率調整(通紙方向倍率) : スタートキー.
//================================================================================================
void PServiceSubMagAdjustCLCD::procStart( uchar option )
{
	// 手差しの用紙種類を画面で設定した値にする.
	TYPE_PaperType _e_paper_type = ( TYPE_PaperType )getSRhein3PrtAreaPaperKind();
	TYPC_PaperType c_PaperType;
	//普通紙-ﾓﾉｸﾛ選択時はパネルDefine値がセットされているため【TYPE_PaperTypeNormal】を設定する.
// comment 2016/10/25 【HCLT-Gomathy】 【MinervaMLK】 【制御構成変更_No.1】 Removing MinervaMLK Compiler Switch. 
// comment 2016/03/11 OPS1-Sky石賀 [MinervaMLK] MinervaMLKビルド対応①.
// comment 2015/03/17 【HCLT_Prabakaran】【MinervaSBK】【機器構成変更_No.44】To store paper kind to NVD when Thin-Black key is selected and "Start" key pressed.
//#if defined(DEF_MINERVASBK_CUS)
//#if defined(DEF_MINERVASBK_CUS) || defined(DEF_MINERVAMLK_CUS)
#if defined(DEF_MINERVASBK_CUS)
	c_PaperType.setPaperType( _e_paper_type );
//#else //#if defined(DEF_MINERVASBK_CUS) || defined(DEF_MINERVAMLK_CUS).
#else //#if defined(DEF_MINERVASBK_CUS).
	if( PNLE_PaperTypeNormalMono == getSRhein3PrtAreaPaperKind() ) {
		c_PaperType.setPaperType( TYPE_PaperTypeNormal );
	} else {
		c_PaperType.setPaperType( _e_paper_type );
	}
//#endif //#if defined(DEF_MINERVASBK_CUS) || defined(DEF_MINERVAMLK_CUS).
#endif //#if defined(DEF_MINERVASBK_CUS).
// comment 2014/10/01 OPS1-Sky東島 [ZeusS][機器構成変更No.11] 普通紙用紙分割.
// comment 2014/11/28 OPS1-Sky東島 [ZeusS][機器構成変更No.11] 普通紙用紙分割.
//	if( TYPE_SystemType_JP == PnlComGetMachineSetting()->getSystemType()
//	 && True == PnlComGetPrintJobSetting()->getPaperTypeNormalEx()
//	 && TYPE_PaperTypeNormal == _e_paper_type ){
//		c_PaperType.setPaperTypeNormalEx( True );
//	}
	PnlComGetFeedTray()->setPaperType( TYPE_FeedTrayManual, c_PaperType );
	APIC_Job* pc_job = PnlComGetJobCopy();
	if( NULL != pc_job ) {
		TYPC_Scan*   pc_Scan   = pc_job->getJobSpec()->pc_Scan;
		pc_Scan->setAcsOn( False ); // ACS未使用にする.
		TYPC_Common* pc_Common = pc_job->getJobSpec()->pc_Common; // コピージョブ.
// [CQ528959] PH副倍補正機能の追加 SCD2 3G Sky西場 2016/05/11 start.
#ifdef DEF_A4_Cus
		pc_Common->setColorMode( TYPE_ColorModeBlack );	// カラーモードブラックをセット.
#else
		if( TYPE_PaperTypeNormal == getSRhein3PrtAreaPaperKind() ) {		// 普通紙-カラー選択時.
			pc_Common->setColorMode( TYPE_ColorModeFullColor );	// フルカラーモードをセット.
		} else {
			pc_Common->setColorMode( TYPE_ColorModeBlack );	// カラーモードブラックをセット.
		}
#endif
// [CQ528959] PH副倍補正機能の追加 SCD2 3G Sky西場 2016/05/11 end.
		pc_job->getJobSpec()->pc_Print->setNumOfCopies( 1 );		// 置数１とする.
//Comment 2018/07/02 [HCLT-Rajkumar]【IT6_Sparrow】Klockwork Changes ID:163593 and ID:163594 [NPD.CHECK.MUST].
	//}
// Comment 2018/01/30 HCLT-Basker [Sparrow] 制御構成変更_No.288[WP 187]
#ifdef DEF_SparrowCus
	if(ss_selectPaperType == 6 ) {	// 光沢モード/1200dpi (*368)
		pc_job->getJobSpec()->pc_Common->c_OriginalImageMode.setLusterCopyOn( True );
	}
	else{
		pc_job->getJobSpec()->pc_Common->c_OriginalImageMode.setLusterCopyOn( false );
	}
#endif	//DEF_SparrowCus
	}
	fixPrinterSubRegistNormal();	// トップマージン確定.
	fixPrinterAdjustMainRegist1();	// レフトマージン確定.
	fixPrinterAdjustMainRegist2();	// デュプレックスレフトマージン確定.
	fixPrinterSubRegistNormal2();	// トップマージン確定.
	fixPrinterAdjustSubMag();		// 通紙方向倍率確定.
#if (defined ( DEF_ZeusCus ) || defined ( DEF_ZeusEmu )) && !defined(DEF_DonauBKCus)
	fixPrinterAdjustTrayTopMargin();// トレイ印刷位置:先端.	2008/08/19 12北畑 Amur 管理No.1088(機器案件5).
#endif
	PServiceFunctionEnableStartCom::procStart( TYPE_FunctionStartTypePRINTPATTAN ); // コピージョブ.
	setupGamen();	// 表示部品のセットアップ.
}
//================================================================================================
// 概要　　 ：サービス・マシン調整・副走査倍率調整(通紙方向倍率) : 表示部品のセットアップ.
//================================================================================================
// comment 2016/10/25 【HCLT-Gomathy】 【MinervaMLK】 【制御構成変更_No.1】 Removing MinervaMLK Compiler Switch. 
// comment 2016/03/11 OPS1-Sky石賀 [MinervaMLK] MinervaMLKビルド対応①.
// comment 2015/04/16 【HCLT_Prabakaran】【MinervaSBK】【機器構成変更_No.44】Avoid compilation for MInervaSBK model.
//#if !defined(DEF_MINERVASBK_CUS)
//#if !defined(DEF_MINERVASBK_CUS) && !defined(DEF_MINERVAMLK_CUS)
