void PServiceSubMagAdjustCLCD::setupGamen( short option )
{
	register short kind = 0;
	short paperkind = getSRhein3PrtAreaPaperKind();
//2018/05/18 Comment [HCLT_Prashannaa][IT6_Sparrow][AR 1043597] Gloss 1200 selection issue
#ifdef DEF_SparrowCus
	APIC_Job* pc_Job = PnlComGetJobCopy();
	if( NULL == pc_Job ){ 
//2019/06/17 Comment [HCLT_Krishnakumar][EagleH][N Rank] Removed unwanted detailed code.
//		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if ( NULL != pc_BFW_System ) {
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x1900280100148801 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );	
		return;
	}
#endif
// Comment 2018/01/30 HCLT-Basker [Sparrow] 制御構成変更_No.288[WP 187]
#ifndef DEF_SparrowCus
//comment 2021/04/01 FPT.SaoVT [MinervaSSBK] [機器構成変更_No.21-5] Adding compilation for MinervaSSBK model.
	if(( TYPE_MachineTypeMinervaSSBKX          == PnlComGetSystemInfo()->getMachineType() )     // MinervaSSBKX.
		||( TYPE_MachineTypeMinervaSSBK0_US    == PnlComGetSystemInfo()->getMachineType() )     // MinervaSSBK0 and Region US.
		||( TYPE_MachineTypeMinervaSSBK0_EU    == PnlComGetSystemInfo()->getMachineType() )     // MinervaSSBK0 and Region EU.
		||( TYPE_MachineTypeMinervaSSBKEmu     == PnlComGetSystemInfo()->getMachineType() )){   // MinervaSSBK(Emu).
			switch( paperkind ){	// 選択用紙.
				case TYPE_PaperTypeNormal: 		kind = 1 ;	break;	// 普通紙-ブラック.
				case TYPE_PaperTypeThin1 : 		kind = 2 ;	break;	// 薄紙-ブラック.
				case TYPE_PaperTypeThick2: 		kind = 3 ;	break;	// 厚紙２／OHP.
				case TYPE_PaperTypeNormalPlus:	kind = 4 ;	break;	// 普通紙+.
				case TYPE_PaperTypeThick1: 		kind = 5 ;	break;	// 厚紙1/1+.	
				case TYPE_PaperTypeThick3: 		kind = 6 ;	break;	// 厚紙3.
				case TYPE_PaperTypeThick4: 		kind = 7 ;	break;	// 厚紙4.
				default:											// 上記以外
					kind = 1;	
					setSRhein3PrtAreaPaperKind( TYPE_PaperTypeNormal );	// 普通紙を設定.
					break;
			}
	} else {
	switch( paperkind ) {	// 選択用紙.
// comment 2018/03/15 SCD2 N.yamura [Eagle][RQ-722]用紙種別追加（厚紙1を2種類に分割）対応.
		case TYPE_PaperTypeNormal: kind = 1;	break;	// 普通紙.
//2019/10/24 Comment [HCLT_Selvaraj][IT6_HeliosMLK][機器構成変更_No.11] Paper type addition for HeliosMLK model.
#if !defined(DEF_HeliosMLKCus)
		case TYPE_PaperTypeNormalPlus: kind = 2;	break;	// 普通紙+.
		case TYPE_PaperTypeThick1Plus:								// 厚紙1+
		case TYPE_PaperTypeThick1: kind = 3;	break;	// 厚紙1/1+.
		case TYPE_PaperTypeThick2: kind = 4;	break;	// 厚紙2.
		case TYPE_PaperTypeThick3: kind = 5 ;	break;	// 厚紙3.
		case TYPE_PaperTypeThick4: kind = 6 ;	break;	// 厚紙4.
		case PNLE_PaperTypeNormalMono:	   kind = 7 ;	break;	// 普通紙-モノクロ(パネルDefine).
#else
// Comment 2019/11/14[HCLT-Ranjith] [IT6_HeliosMLK] [機器構成変更_No11] Index change due to Plainpaper+ removal..
		case TYPE_PaperTypeThick1Plus:	
		case TYPE_PaperTypeThick1: kind = 2;	break;	// 厚紙1/1+.
		case TYPE_PaperTypeThick2: kind = 3;	break;	// 厚紙2.
		case TYPE_PaperTypeThick3: kind = 4 ;	break;	// 厚紙3.
#endif
		default:													// 上記以外
			kind = 1;
			setSRhein3PrtAreaPaperKind( TYPE_PaperTypeNormal );	// 普通紙を設定.
			break;
	}
	}			
#if defined ( DEF_MinervaBKCus ) || defined ( DEF_MinervaBKEmu )
	Rbt_ServiceRhein3PrtAreaPaperKind3.select( static_cast<short>( kind -2 ) );							// 選択用紙を反転表示.
#else	// DEF_MonoCus.
	Rbt_ServiceRhein3PrtAreaPaperKind3.select( static_cast<short>( kind -1 ) );							// 選択用紙を反転表示.
#endif	// DEF_MonoCus.
	
#else	// DEF_SparrowCus

//	if( 1 == uc_NowPage ) {
//		Rbt_ServiceDonauPaperKind2.showEnable(False);
//		Rbt_ServiceDonauPaperKind3.showEnable(False);
//		Rbt_ServiceDonauPaperKind1.showEnable(True);
//	} else if (2 == uc_NowPage){
//		Rbt_ServiceDonauPaperKind1.showEnable(False);
//		Rbt_ServiceDonauPaperKind3.showEnable(False);
//		Rbt_ServiceDonauPaperKind2.showEnable(True);
//	} else if (3 == uc_NowPage){
//		Rbt_ServiceDonauPaperKind1.showEnable(False);
//		Rbt_ServiceDonauPaperKind2.showEnable(False);
//		Rbt_ServiceDonauPaperKind3.showEnable(True);
//	}

//	char stPage[4];
//	memset( stPage, 0, sizeof(stPage) );
//	snprintf( stPage, sizeof(stPage), "%d/%d", uc_NowPage, PNLD_SubMagAdjustTotalPage );
//	Tfd_ServiceDonauPaperKindPageNo.changeExternalText((uchar*)stPage, sizeof(stPage) );// /ジャム.

	switch( paperkind ){	// 用紙種類選択値.
		case TYPE_PaperTypeNormal:		// 普通紙 / 光沢モード/1200dpi (*368)
			if(ss_selectPaperType == 6) {
//2018/05/18 Comment [HCLT_Prashannaa][IT6_Sparrow][AR 1043597] Gloss 1200 selection issue
				pc_Job->getJobSpec()->pc_Common->c_OriginalImageMode.setLusterCopyOn( True );
				kind = 7;
			} else {
				kind = 1;
			}
			break;	
		case TYPE_PaperTypeThick1:		kind = 2;	break;	// 厚紙1.
		case TYPE_PaperTypeNormalPlus:	// 普通紙+.
//comment 2018/8/30 SCD2-Sky肥後 [Sparrow][RQ-722]普通紙+ 光沢ﾓｰﾄﾞ/1200dpi追加対応.
			if(ss_selectPaperType == 6) {
				pc_Job->getJobSpec()->pc_Common->c_OriginalImageMode.setLusterCopyOn( True );
				kind = 11;	// 普通紙+ 光沢ﾓｰﾄﾞ/1200dpi.
			} else {
				kind = 3;	// 普通紙+.
			}
			break;
		case TYPE_PaperTypeThick2:		kind = 4;	break;	// 厚紙2.
		case TYPE_PaperTypeEnvelope:	kind = 5;	break;	// 封筒.
		case TYPE_PaperTypeGloss1:		kind = 6;	break;	// 光沢紙１.
		case TYPE_PaperTypeGloss1Plus:	kind = 8;	break;	// 沢紙１+.
		case TYPE_PaperTypeGloss2:		kind = 9;	break;	// 光沢紙2.
		case TYPE_PaperPostCard:		kind = 10;	break;	// はがき.
		default: kind = 1; break;	// 普通紙.
	}
//2018/05/18 Comment [HCLT_Prashannaa][IT6_Sparrow][AR 1043597] Gloss 1200 selection issue
	if(ss_selectPaperType != 6){
		pc_Job->getJobSpec()->pc_Common->c_OriginalImageMode.setLusterCopyOn( False );
	}
	
//comment 2018/05/14 HCLT-Basker [Sparrow][機器構成変更_No.288 ] Layout change.	
//	if(ss_selectPaperType<=3){
//		Rbt_ServiceDonauPaperKind2.select(-1);
//		Rbt_ServiceDonauPaperKind3.select(-1);
//		Rbt_ServiceDonauPaperKind1.select(ss_selectPaperType);
//	} else if (ss_selectPaperType<=7){
//		Rbt_ServiceDonauPaperKind1.select(-1);
//		Rbt_ServiceDonauPaperKind3.select(-1);
//		Rbt_ServiceDonauPaperKind2.select(ss_selectPaperType-4);
//	} else if (ss_selectPaperType<=9){
//		Rbt_ServiceDonauPaperKind1.select(-1);
//		Rbt_ServiceDonauPaperKind2.select(-1);
//		Rbt_ServiceDonauPaperKind3.select(ss_selectPaperType-8);
//	} else {
//		Rbt_ServiceDonauPaperKind1.select(-1);
//		Rbt_ServiceDonauPaperKind2.select(-1);
//		Rbt_ServiceDonauPaperKind3.select(-1);
//	}
	Rbt_ServiceRhein3PrtAreaPaperKind3.select( static_cast<short>( kind -1 ) );							// 選択用紙を反転表示.
#endif // DEF_SparrowCus.

	setPrinterIndi( sc_SubMagAdjust[ kind ].indiSub );								// 用紙種類に応じた画質指定設定.
	Btx_SSubMagAdjust = ( float )getPrinterIndi( sc_SubMagAdjust[ kind ].indiSub );	// レベルの表示.
	PServiceFunctionCom::searchTrayNo( option );									// ファンクション画面共通処理.
	// [CQ529447] テストパターンの用紙サイズチェック SCD2 3G Sky西場 2016/05/18 start.
#ifdef DEF_A4_Cus
	TYPC_PaperSize c_PaperSize = PnlComGetFeedTray()->getPaperSize( TYPE_FeedTrayManual );
	if( (TYPE_SizeCodeA4Sef != c_PaperSize.e_SizeCode) &&
	    (TYPE_SizeCodeLetterSef != c_PaperSize.e_SizeCode) ){
		printLEDControl( False );			// スタートキーＬＥＤ橙.
	}
#endif
	// [CQ529447] テストパターンの用紙サイズチェック SCD2 3G Sky西場 2016/05/18 end.
	Rbt_ServiceSubMagTestPattern.select( ss_selectTestPattern );
}
//#endif	//#if !defined(DEF_MINERVASBK_CUS) && !defined(DEF_MINERVAMLK_CUS).
#endif	//#if !defined(DEF_MINERVASBK_CUS).
//================================================================================================
// 概要　　 ：サービス・マシン調整・副走査倍率調整(通紙方向倍率) : 終了設定.
//================================================================================================
void PServiceSubMagAdjustCLCD::endGamen()
{
	APIC_Job* pc_job = PnlComGetJobCopy();
	if( NULL != pc_job ) {
		TYPC_Scan*   pc_Scan   = pc_job->getJobSpec()->pc_Scan;
		pc_Scan->setAcsOn( False ); // ACS未使用にする
		TYPC_Common* pc_Common = pc_job->getJobSpec()->pc_Common;
		pc_Common->c_ColorSeparate.setColorMode( TYPE_ColorModeFullColor ); // カラーモード(フルカラー)
	}
	if( onlyPanel.ep_ForceChangeGamen != EP_ForceChangeGamen_Warning ) {
		rollback_density();	// バックアップ値に戻す（現在濃度のみ）
	}
	PServiceFunctionCom::endGamen();	// ファンクション共通終了処理
}
