void PServiceSkewAdjustCom::setupGamen( short option )
{
	PServiceChoiceAdjustCom10ToMachineAdjustModeMenuCom::setupGamen( option );	// 表示部品のセットアップ
}
//================================================================================================
// 概要		:サービス・マシン調整・スキュー調整・調整 : 初期設定.
//================================================================================================
void PServiceSkewAdjust::startGamen()
{
	PBasicMessageProc::startGamen();

	CheckAndExecInit();	// 初期化必要か否か取得して必要なら実行する.
	uchar i = 0; // フラグの初期化.
	for( i = 0; i < 3; i++ ) {
		bl_Fixed[i] = True;		// 確定フラグON.
	}
	for( i = 0; i < 3; i++ ) {
		bl_Direct[i] = True;		// ダイレクトinputフラグON.
	}

	// パーツ表示制御
	CheckShowParts();
}
//================================================================================================
// 概要		:サービス・マシン調整・スキュー調整・調整 : 変数などの初期化.
//================================================================================================
void PServiceSkewAdjust::init_value()
{
	setPrinterIndi( TYPE_PrinterAdjustPHSkewMotorInitC );	// シアン.
	ss_SkewAdjustCyan    = getPrinterIndiInSystem( TYPE_PrinterAdjustPHSkewMotorInitC );	// シアン.
	ss_SkewAdjustMagenta = getPrinterIndiInSystem( TYPE_PrinterAdjustPHSkewMotorInitM );	// マゼンタ.
	ss_SkewAdjustYellow  = getPrinterIndiInSystem( TYPE_PrinterAdjustPHSkewMotorInitY );	// イエロー.
	ss_SkewAdjustCyanInput    = ss_SkewAdjustCyan;
	ss_SkewAdjustMagentaInput = ss_SkewAdjustMagenta;
	ss_SkewAdjustYellowInput  = ss_SkewAdjustYellow;
}
//================================================================================================
// 概要		:サービス・マシン調整・スキュー調整・調整 : ボタン（押された）.
// 備考		:元に戻すキー処理:選択している項目のみ、画面に入ったときの値に戻す.
//================================================================================================
void PServiceSkewAdjust::procButtonOn( uchar option )
{
	switch( option ) {
		case 0:	setPrinterIndi( TYPE_PrinterAdjustPHSkewMotorInitC );	break;	// シアン.
		case 1:	setPrinterIndi( TYPE_PrinterAdjustPHSkewMotorInitM );	break;	// マゼンタ.
		case 2:	setPrinterIndi( TYPE_PrinterAdjustPHSkewMotorInitY );	break;	// イエロー.
		case 60:
			// 元に戻すキー処理:選択している項目のみ、画面に入ったときの値に戻す.
			switch( getIndiSelected() ) {
				case TYPE_PrinterAdjustPHSkewMotorInitC:	ss_SkewAdjustCyanInput    = ss_SkewAdjustCyan;		break;	// シアン.
				case TYPE_PrinterAdjustPHSkewMotorInitM:	ss_SkewAdjustMagentaInput = ss_SkewAdjustMagenta;	break;	// マゼンタ.
				case TYPE_PrinterAdjustPHSkewMotorInitY:	ss_SkewAdjustYellowInput  = ss_SkewAdjustYellow;	break;	// イエロー.
				default: break;
			}
			break;
		default:break;
	}
	setupGamen();	// 表示部品のセットアップ.
}
/*================================================================================================
// 概要　　：サービス・マシン調整・スキュー調整・調整 : Indi情報を確定しCommonAPIに書き込む関数.
================================================================================================*/
void PServiceSkewAdjust::fixPrinterIndi( TYPE_PrinterAdjust indi,short _ss_value )
{
	ss_SkewAdjustMinValue = getPrinterIndiMinValue( indi );	// 最小値取得.
	if( _ss_value >= ss_SkewAdjustMinValue ) {
		PnlComGetPrinterServiceSetting()->setPrinterAdjust( indi, _ss_value );
	}
}
