//==============================================================================
// 概要     ：サービス・マシン調整・LD発光遅延量調整・変数初期化.
//==============================================================================
void PServiceLDRelativePosition::init_value()
{
#if defined(DEF_MonoCus)
	setPrinterIndi( TYPE_PrinterAdjustLDRelativePositionK );
#else
	setPrinterIndi( TYPE_PrinterAdjustLDRelativePositionC );
#endif
	// ＡＰＩから値を取得する.
	ss_LDRelativePositionCValue = getPrinterIndiInSystem( TYPE_PrinterAdjustLDRelativePositionC );	// シアン.
	ss_LDRelativePositionMValue = getPrinterIndiInSystem( TYPE_PrinterAdjustLDRelativePositionM );	// マゼンタ.
	ss_LDRelativePositionYValue = getPrinterIndiInSystem( TYPE_PrinterAdjustLDRelativePositionY );	// イエロー.
	ss_LDRelativePositionKValue = getPrinterIndiInSystem( TYPE_PrinterAdjustLDRelativePositionK );	// ブラック.
}
//==========================================================================
// 概要     ：サービス・マシン調整・LD発光遅延量調整・ボタン(押された).
//==========================================================================
void PServiceLDRelativePosition::procButtonOn( uchar option )
{
	switch( option ) {
		case 0:	setPrinterIndi( TYPE_PrinterAdjustLDRelativePositionC );	break;	// シアン.
		case 1:	setPrinterIndi( TYPE_PrinterAdjustLDRelativePositionM );	break;	// マゼンタ.
		case 2:	setPrinterIndi( TYPE_PrinterAdjustLDRelativePositionY );	break;	// イエロー.
		case 3:	setPrinterIndi( TYPE_PrinterAdjustLDRelativePositionK );	break;	// ブラック.
		case 18:addIndi();	break;	// +キー.
		case 19:subIndi();	break;	// -キー.
		case 60:	// 元に戻すキー.
			// 選択している項目のみ、画面に入ったときの値に戻す.
			switch( getIndiSelected() ) {
				case TYPE_PrinterAdjustLDRelativePositionC: setPrinterIndi( TYPE_PrinterAdjustLDRelativePositionC,ss_LDRelativePositionCValue ); break;	// シアン.
				case TYPE_PrinterAdjustLDRelativePositionM: setPrinterIndi( TYPE_PrinterAdjustLDRelativePositionM,ss_LDRelativePositionMValue ); break;	// マゼンタ.
				case TYPE_PrinterAdjustLDRelativePositionY: setPrinterIndi( TYPE_PrinterAdjustLDRelativePositionY,ss_LDRelativePositionYValue ); break;	// イエロー.
				case TYPE_PrinterAdjustLDRelativePositionK: setPrinterIndi( TYPE_PrinterAdjustLDRelativePositionK,ss_LDRelativePositionKValue ); break;	// ブラック.
				default: break;
			}
			break;
		default:break;
	}
	setupGamen();	// 表示部品のセットアップ.
}
//==============================================================================
// 概要     ：サービス・マシン調整・LD発光遅延量調整・ボタン(押し続け、速く変化).
//==============================================================================
void PServiceLDRelativePosition::procButtonStillOnFast( uchar option )
{
	if( option == 18 || option == 19 ) {
		procButtonOn( option );
	}
}
