	ss_LDAdjustmentLightBalanceMValue = getPrinterIndiInSystem( TYPE_PrinterAdjustLDLightM );	// マゼンタ.
	ss_LDAdjustmentLightBalanceYValue = getPrinterIndiInSystem( TYPE_PrinterAdjustLDLightY );	// イエロー.
	ss_LDAdjustmentLightBalanceKValue = getPrinterIndiInSystem( TYPE_PrinterAdjustLDLightK );	// ブラック.
