//==========================================================================
// 概要     ：サービス・マシン調整・LD光量バランス調整・ボタン(押された).
//==========================================================================
void PServiceLDAdjustmentLightBalance::procButtonOn( uchar option )
{
	switch( option ) {
		case  0:	setPrinterIndi( TYPE_PrinterAdjustLDLightC );	break;	// シアン.
		case  1:	setPrinterIndi( TYPE_PrinterAdjustLDLightM );	break;	// マゼンタ.
		case  2:	setPrinterIndi( TYPE_PrinterAdjustLDLightY );	break;	// イエロー.
		case  3:	setPrinterIndi( TYPE_PrinterAdjustLDLightK );	break;	// ブラック.
		case 10: setFunctionCode( TYPD_FNC_LDLightAdjustPage1 ); 	break;	// LD光量バランス調整・調整用テストプリント.
		case 11: setFunctionCode( TYPD_FNC_LDLightAdjustPage2 ); 	break;	// LD光量バランス調整・確認用テストプリント.
		case 18:	addIndi();	break;	// +キー.
		case 19:	subIndi();	break;	// -キー.
		case 60:	// 元に戻すキー.
			// 選択している項目のみ、画面に入ったときの値に戻す.
			switch( getIndiSelected() ) {
				case TYPE_PrinterAdjustLDLightC: setPrinterIndi( TYPE_PrinterAdjustLDLightC,ss_LDAdjustmentLightBalanceCValue ); break;	// シアン.
				case TYPE_PrinterAdjustLDLightM: setPrinterIndi( TYPE_PrinterAdjustLDLightM,ss_LDAdjustmentLightBalanceMValue ); break;	// マゼンタ.
				case TYPE_PrinterAdjustLDLightY: setPrinterIndi( TYPE_PrinterAdjustLDLightY,ss_LDAdjustmentLightBalanceYValue ); break;	// イエロー.
				case TYPE_PrinterAdjustLDLightK: setPrinterIndi( TYPE_PrinterAdjustLDLightK,ss_LDAdjustmentLightBalanceKValue ); break;	// ブラック.
				default: break;
			}
			break;
		default:break;
	}
	setupGamen();	// 表示部品のセットアップ.
}
//==============================================================================
// 概要     ：サービス・マシン調整・LD光量バランス調整・ボタン(押し続け、速く変化).
//==============================================================================
void PServiceLDAdjustmentLightBalance::procButtonStillOnFast( uchar option )
{
	if( option == 18 || option == 19 ) {
		procButtonOn( option );
	}
}
//==========================================================================
// 概要     ：サービス・マシン調整・LD光量バランス調整・設定終了.
///==========================================================================
void PServiceLDAdjustmentLightBalance::procOk( uchar option )
{
	fixPrinterIndi( TYPE_PrinterAdjustLDLightC );	// シアン.
	fixPrinterIndi( TYPE_PrinterAdjustLDLightM );	// マゼンタ.
	fixPrinterIndi( TYPE_PrinterAdjustLDLightY );	// イエロー.
	fixPrinterIndi( TYPE_PrinterAdjustLDLightK );	// ブラック.
	nextGamen = &gp_ServiceMachineAdjustModeMenu;	// サービス・マシン調整・モードメニュー
}
//==============================================================================
// 概要     ：サービス・マシン調整・LD光量バランス調整・スタート.
//==============================================================================
void PServiceLDAdjustmentLightBalance::procStart( uchar option )
{
	if( printStartDisable() == False && NULL != PnlComGetJobCopy() ) {			// スタートキーが緑の場合.
		// 各調整値の確定.
		fixPrinterIndi( TYPE_PrinterAdjustLDLightC );	// シアン.
		fixPrinterIndi( TYPE_PrinterAdjustLDLightM );	// マゼンタ.
		fixPrinterIndi( TYPE_PrinterAdjustLDLightY );	// イエロー.
		fixPrinterIndi( TYPE_PrinterAdjustLDLightK );	// ブラック.
		TYPE_FeedTray e_selectedFeedTray = PnlComGetJobCopy()->getJobSpec()->pc_Print->c_PaperTray.getFeedTray();
		switch( e_selectedFeedTray ) {	// 給紙口指定の設定.
			case TYPE_FeedTray1: comENG.setENGFunction_FeedCode( EC_FeedCode_1 ); break;
			case TYPE_FeedTray2: comENG.setENGFunction_FeedCode( EC_FeedCode_2 ); break;
			case TYPE_FeedTray3: comENG.setENGFunction_FeedCode( EC_FeedCode_3 ); break;
			case TYPE_FeedTray4: comENG.setENGFunction_FeedCode( EC_FeedCode_4 ); break;
			case TYPE_FeedTrayManual: comENG.setENGFunction_FeedCode( EC_FeedCode_MANUAL ); break;
			case TYPE_FeedTray5: comENG.setENGFunction_FeedCode( EC_FeedCode_LCT ); break;	// LCT給紙口.
			default: comENG.setENGFunction_FeedCode( EC_FeedCode_1 ); break;
		}
		PServiceFunctionEnableStopCom::procStart( TYPE_FunctionStartTypeNORMAL ); // エンジンファンクション.
	}
	else {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );		// 拒否音.
	}
}
//==============================================================================
// 概要     ：サービス・マシン調整・LD光量バランス調整・表示部品のセットアップ.
//==============================================================================
void PServiceLDAdjustmentLightBalance::setupGamen( short option )
{
	register short _select = -1;
	switch( getFunctionCode() ) {
		case TYPD_FNC_LDLightAdjustPage1:	_select = 0;	break;	// 調整用選択.
		case TYPD_FNC_LDLightAdjustPage2:	_select = 1;	break;	// 確認用選択.
		default:break;
	}
	Rbt_LDAdjustmentLightBalance.select( _select );	// LD光量バランス調整・ローテーションボタン.
	_select = -1;
	switch( getIndiSelected() ) {
		case TYPE_PrinterAdjustLDLightC:	_select = 0;	break;	// シアン.
		case TYPE_PrinterAdjustLDLightM:	_select = 1;	break;	// マゼンタ.
		case TYPE_PrinterAdjustLDLightY:	_select = 2;	break;	// イエロー.
#ifdef DEF_MonoCus
		case TYPE_PrinterAdjustLDLightK:	_select = 0;	break;	// ブラック.
#else	// DEF_MonoCus.
		case TYPE_PrinterAdjustLDLightK:	_select = 3;	break;	// ブラック.
#endif	// DEF_MonoCus.
		default: break;
	}
	Rbt_LDRelativePosition.select( _select );	// ボタンの選択.
// comment 2014/12/26 HCLT_Akash [HeliosL][機器構成変更_No.15] Disable part in case of HeliosL.
// Comment 2019/07/26 [HCLT_Paul] [IT6_HeliosMLK] [ Seigyu.10 ] Adding the HeliosMLK compiler switch.
#ifndef DEF_HeliosMLKCus
	Rbt_LDAdjustment.select( 1 );				// LD調整キーの選択.
#endif // DEF_HeliosCus.
	Btx_LDAdjustmentLightBalanceC.set( ( float )getPrinterIndi( TYPE_PrinterAdjustLDLightC ), True );	// シアン.
	Btx_LDAdjustmentLightBalanceM.set( ( float )getPrinterIndi( TYPE_PrinterAdjustLDLightM ), True );	// マゼンタ.
	Btx_LDAdjustmentLightBalanceY.set( ( float )getPrinterIndi( TYPE_PrinterAdjustLDLightY ), True );	// イエロー.
	Btx_LDAdjustmentLightBalanceK.set( ( float )getPrinterIndi( TYPE_PrinterAdjustLDLightK ), True );	// ブラック.
#ifdef DEF_MonoCus
	// モノクロ機ではシアン、マゼンタ、イエローの値は非表示.
	Btx_LDAdjustmentLightBalanceC.showEnableAdd( False );
	Btx_LDAdjustmentLightBalanceM.showEnableAdd( False );
	Btx_LDAdjustmentLightBalanceY.showEnableAdd( False );
#endif	// DEF_MonoCus.
#ifndef DEF_ThamesCus // Thames以外.
	PServiceFunctionCom::searchTrayMan21A3Paper( option );		// ファンクション画面共通処理.
#else // Thames
	PServiceFunctionCom::searchTrayMan2341A3Paper( option );		// ファンクション画面共通処理.
#endif
}
