	PnlComGetPrinterServiceSetting()->setPrinterAdjust( TYPE_PrinterAdjustThickPaperFeedMode, ss_ThickPaperModeSelect );
	nextGamen = &gp_ServiceMachineAdjustModeMenu;	// サービス・マシン調整・モードメニュー
