{
	Rbt_ServiceThickPaperModeSelect.select( ss_ThickPaperModeSelect == False ? 0 : 1 ); // OFF/ON 選択ボタン・選択値.
	PServiceFunctionEnableStartCom::setupGamen( option );	// 表示部品のセットアップ
}
