// Comment 2019/01/10 HCLT_Ajit [IT6_EagleH] [機器構成変更_No.16] Implemented new class for PhotoConductor Auto Refreshing.
// ==========================================================================
// Overview: Q3B2000000_PhotoConductor Manual Refreshing. : Initial Setting:
// ===========================================================================
void PServicePhotoConductorRefreshingManual::startGamen()
{
	PServiceFunctionEnableStopCom::startGamen();
	m_ss_RefreshStrengthK = m_ss_RefreshStrengthK_Restore;
	CheckAndExecInit();															// 初期化必要か否か取得して必要なら実行する.
	Rbt_SPhotoConductorRefreshing.select( BTNID_ManualPhotoRefresh ); 			// Manual Refresh.
	Rbt_SPhotoConductorRefreshingK.select( BTNID_RefreshStrengthK ); 			// Default Selection of Refresh Strength of K.
// comment 2019/02/13 【HCLT-Tarun】【IT6_EagleH】【OP_BTS-3067】Checking initial value setting.
	init_value();	
}
// ============================================================================
// Overview: Q3B2000000_PhotoConductor Manual Refreshing.:Setup of display parts.
// =============================================================================

void PServicePhotoConductorRefreshingManual::setupGamen( short option )
{
	PServiceFunctionEnableStopCom::setupGamen( option );
	Btx_SPhotoConductorRefreshingKManual = ( float )( m_ss_RefreshStrengthK );			// Refresh Strength ok K.
	printLEDControl( ( isFunctionWorking()  == True )||( getFunctionCode() == TYPD_Photoreceptor_Drum_No_Refreshing ) ? False : True );
}
// ============================================================================
// Overview: Q3B2000000_PhotoConductor Manual Refreshing.:Button (pressed).
// =============================================================================
void PServicePhotoConductorRefreshingManual::procButtonOn( uchar option )
{
	switch( option ) {
		case  19: // Down Key.
		if ( m_ss_RefreshStrengthK ==  0) {
			setBuzzerType( PCGE_BuzzerType_InputNg );
			return;
		} 
		m_ss_RefreshStrengthK--;
		break;
		case  18: // UP Key.
		if ( m_ss_RefreshStrengthK ==  3) {
			setBuzzerType( PCGE_BuzzerType_InputNg );
			return;
		}
		m_ss_RefreshStrengthK++;
		break;
		case  60: // Restore Key.
			m_ss_RefreshStrengthK = m_ss_RefreshStrengthK_Restore;
		break;
		default: break;
	}
	switch( m_ss_RefreshStrengthK ) {
		case 0: setFunctionCode( TYPD_Photoreceptor_Drum_No_Refreshing ); break;
		case 1: setFunctionCode( TYPD_Photoreceptor_Drum_K_Refresh1 ); break;
		case 2: setFunctionCode( TYPD_Photoreceptor_Drum_K_Refresh2 ); break;
		case 3: setFunctionCode( TYPD_Photoreceptor_Drum_K_Refresh3 ); break;
		default:break;
	}
}
// ============================================================================
// Overview: Q3B2000000_PhotoConductor Manual Refreshing.:Initial Setting.
// =============================================================================
void PServicePhotoConductorRefreshingManual::init_value()
{
		switch( m_ss_RefreshStrengthK ) {
		case 0: setFunctionCode( TYPD_Photoreceptor_Drum_No_Refreshing ); break;
		case 1: setFunctionCode( TYPD_Photoreceptor_Drum_K_Refresh1 ); break;
		case 2: setFunctionCode( TYPD_Photoreceptor_Drum_K_Refresh2 ); break;
		case 3: setFunctionCode( TYPD_Photoreceptor_Drum_K_Refresh3 ); break;
		default:break;
	}
}
// ============================================================================
// Overview: Q3B2000000_PhotoConductor Manual Refreshing.:Screen Transition.
// =============================================================================
void PServicePhotoConductorRefreshingManual::procGoToPage( uchar option )
{
	switch( option ) {
		case BTNID_AutoPhotoRefresh:	// Auto Refresh.
			nextGamen = &gp_ServicePhotoConductorRefreshingAuto;
			break;
		default:break;
	}
}
// ============================================================================
// Overview: Q3B2000000_PhotoConductor Manual Refreshing.:OK key.
// =============================================================================

void PServicePhotoConductorRefreshingManual::procOk( uchar option )
{
	m_ss_RefreshStrengthK_Restore = m_ss_RefreshStrengthK;
	nextGamen = &gp_ServiceImageAdjustModeMenu;
}
// ============================================================================
// Overview: Q3B2000000_PhotoConductor Manual Refreshing.:Start key.
// =============================================================================
