void PServicePhotoConductorRefreshingManual::procClear( uchar option )
{
	if ( m_ss_RefreshStrengthK != 0 ) {
		m_ss_RefreshStrengthK = 0;
		setFunctionCode( TYPD_Photoreceptor_Drum_No_Refreshing );
	} 
	setupGamen( option );
}	
// ==========================================================================
// Overview: Q3B2000000_PhotoConductor Auto Refreshing. : Initial Setting:
// ===========================================================================
void PServicePhotoConductorRefreshingAuto::startGamen()
{
	PServiceFunctionEnableStopCom::startGamen();
	Rbt_SPhotoConductorRefreshing.select( BTNID_AutoPhotoRefresh );
	m_ss_DRPhotoRefreshMode = PnlComGetPrinterServiceSetting()->getPrinterAdjust( TYPE_PrinterAdjustDrumAutoRefleshChoice  );	// get the Drum Auto Refresh Choice value.
}
// ==========================================================================
// Overview: Q3B2000000_PhotoConductor Auto Refreshing. :Setup of display parts.
// ===========================================================================
void PServicePhotoConductorRefreshingAuto::setupGamen( short option )
{
	PServiceFunctionEnableStopCom::setupGamen( option );
	Rbt_SPhotoConductorAutoRefresh.select( m_ss_DRPhotoRefreshMode );
	printLEDControl( False );
}
// ==========================================================================
// Overview: Q3B2000000_PhotoConductor Auto Refreshing. :Screen Transition.
// ===========================================================================
void PServicePhotoConductorRefreshingAuto::procGoToPage( uchar option )
{
	switch( option ) {
		case BTNID_ManualPhotoRefresh:	// Manual Refresh.
			nextGamen = &gp_ServicePhotoConductorRefreshingManual;
			break;
		default:break;
	}
}
// ==========================================================================
// Overview: Q3B2000000_PhotoConductor Auto Refreshing. :Button (pressed)
// ===========================================================================
void PServicePhotoConductorRefreshingAuto::procButtonOn( uchar option )
{
	switch( option ) {
		case  0: m_ss_DRPhotoRefreshMode = 0; break;	// OFF.
		case  1: m_ss_DRPhotoRefreshMode = 1; break;	// Mode1.
		case  2: m_ss_DRPhotoRefreshMode = 2; break;	// Mode2.
		case  3: m_ss_DRPhotoRefreshMode = 3; break;	// Mode3.
		case  4: m_ss_DRPhotoRefreshMode = 4; break;	// Mode4.
		default:break;
	}
}
// ==========================================================================
// Overview: Q3B2000000_PhotoConductor Auto Refreshing. :OK Key.
// ===========================================================================
void PServicePhotoConductorRefreshingAuto::procOk( uchar option )
{
	PnlComGetPrinterServiceSetting()->setPrinterAdjust( TYPE_PrinterAdjustDrumAutoRefleshChoice, m_ss_DRPhotoRefreshMode );	// set the Drum Auto Refresh Choice value.
	nextGamen = &gp_ServiceImageAdjustModeMenu;
}
