// 概要 : ﾌﾟﾛｾｽ調整/転写出力微調/1次転写微調(91002) : 変数などの初期化.
//////////////////////////////////////////////////////////////
void PService1stTransferAdjustCom::init_value()
{
// A3A4FUM kawana-k 2015/02/18 Start.
#ifndef DEF_A4_Cus
//Comment 2020/01/27 [HCLT_Hemachander] [IT6_HeliosMLK] [ OP_BTS-18275 ] Default value change for HeliosMLK.
//setPrinterIndi( TYPE_PrinterAdjust1stTransferOutputAdjK ); //1次転写出力微調1面目
#ifndef DEF_MonoCus
setPrinterIndi( TYPE_PrinterAdjust1stTransferOutputAdjC ); //1次転写出力微調1面目
#else
setPrinterIndi( TYPE_PrinterAdjust1stTransferOutputAdjK ); //1次転写出力微調1面目
#endif //DEF_MonoCus.
// comment 2014/12/03 HCLT_Vinothini [HeliosL][機器構成変更_No.22] [WP 363] Initialization of new button to display 1st transfer output value and removal of other adjustment values.
//Comment 2020/01/27 [HCLT_Hemachander] [IT6_HeliosMLK] [ OP_BTS-18275 ] Removing  HeliosMLK compiler switch.
#ifndef DEF_MonoCus
// Comment 2019/07/26 [HCLT_Paul] [IT6_HeliosMLK] [ Seigyu.10 ] Adding the HeliosMLK compiler switch.
///#if !defined ( DEF_MonoCus ) || !defined ( DEF_HeliosMLKCus )
	ss_1stTransferOutputAdjC	= getPrinterIndiInSystem( TYPE_PrinterAdjust1stTransferOutputAdjC );  //１次転写出力調整値 シアン.
	ss_1stTransferOutputAdjM	= getPrinterIndiInSystem( TYPE_PrinterAdjust1stTransferOutputAdjM );  //１次転写出力調整値 マゼンタ.
	ss_1stTransferOutputAdjY	= getPrinterIndiInSystem( TYPE_PrinterAdjust1stTransferOutputAdjY );  //１次転写出力調整値 イエロー.
#endif	// DEF_MonoCus.
	ss_1stTransferOutputAdjK	= getPrinterIndiInSystem( TYPE_PrinterAdjust1stTransferOutputAdjK );  //１次転写出力調整値 ブラック.
#else
	setPrinterIndi( TYPE_PrinterAdjust1stTransferOutput ); //1次転写出力微調1面目
	ss_1stTransferOutputAdjALL	= getPrinterIndiInSystem( TYPE_PrinterAdjust1stTransferOutput	 ); //１次転写出力調整値 全色.
#endif // DEF_A4_Cus.
// A3A4FUM kawana-k 2015/02/18 End.
}
//////////////////////////////////////////////////////////////
// 概要 : ﾌﾟﾛｾｽ調整/転写出力微調/1次転写微調(91002) : ボタン（押された）.
//////////////////////////////////////////////////////////////
void PService1stTransferAdjustCom::procButtonOn( uchar option )
{
	switch( option ) {
// A3A4FUM kawana-k 2015/02/18 Start.
#ifndef DEF_A4_Cus
		case 0:	setPrinterIndi( TYPE_PrinterAdjust1stTransferOutputAdjC );	break;	// １次転写電流調整値Ｃ.
		case 1:	setPrinterIndi( TYPE_PrinterAdjust1stTransferOutputAdjM );	break;	// １次転写電流調整値Ｍ.
		case 2:	setPrinterIndi( TYPE_PrinterAdjust1stTransferOutputAdjY );	break;	// １次転写電流調整値Ｙ.
		case 3:	setPrinterIndi( TYPE_PrinterAdjust1stTransferOutputAdjK );	break;	// １次転写電流調整値Ｋ.
		case 60:	// 元に戻す.
			switch( getIndiSelected() ) {
				case TYPE_PrinterAdjust1stTransferOutputAdjC:
					setPrinterIndi( TYPE_PrinterAdjust1stTransferOutputAdjC,		ss_1stTransferOutputAdjC );  //１次転写電流調整値Ｃ.
					break;
				case TYPE_PrinterAdjust1stTransferOutputAdjM:
					setPrinterIndi( TYPE_PrinterAdjust1stTransferOutputAdjM,		ss_1stTransferOutputAdjM );  //１次転写電流調整値Ｍ.
					break;
				case TYPE_PrinterAdjust1stTransferOutputAdjY:
					setPrinterIndi( TYPE_PrinterAdjust1stTransferOutputAdjY,		ss_1stTransferOutputAdjY );  //１次転写電流調整値Ｙ.
					break;
				case TYPE_PrinterAdjust1stTransferOutputAdjK:
					setPrinterIndi( TYPE_PrinterAdjust1stTransferOutputAdjK,		ss_1stTransferOutputAdjK );  //１次転写電流調整値Ｋ.
					break;
				default: break;
			}
			break;
#else
		case 60:	// 元に戻す.
			setPrinterIndi( TYPE_PrinterAdjust1stTransferOutput,		ss_1stTransferOutputAdjALL	 ); //１次転写電流調整値全色.
			break;
#endif // DEF_A4_Cus.
// A3A4FUM kawana-k 2015/02/18 End.
		case 18:	addIndi();	break;	// 転写出力微調整値アップ.
		case 19:	subIndi();	break;	// 転写出力微調整値ダウン.
		default:break;
	}
	setupGamen();
}
//////////////////////////////////////////////////////////////
// 概要 : ﾌﾟﾛｾｽ調整/転写出力微調/1次転写微調(91002) : 画面遷移処理.
//////////////////////////////////////////////////////////////
void PService1stTransferAdjustCom::procGoToPage( uchar option )
{
	switch( option ) {
		case 102:	// 2次転写微調整.
// A3A4FUM kawana-k 2015/02/18 Start.
#ifndef DEF_A4_Cus
			fixPrinterIndi( TYPE_PrinterAdjust1stTransferOutputAdjC );	//１次転写出力調整値 シアン.
			fixPrinterIndi( TYPE_PrinterAdjust1stTransferOutputAdjM );	//１次転写出力調整値 マゼンタ.
			fixPrinterIndi( TYPE_PrinterAdjust1stTransferOutputAdjY );	//１次転写出力調整値 イエロー.
			fixPrinterIndi( TYPE_PrinterAdjust1stTransferOutputAdjK );	//１次転写出力調整値 ブラック.
#else
			fixPrinterIndi( TYPE_PrinterAdjust1stTransferOutput	 );	//１次転写出力調整値 全色.
#endif // DEF_A4_Cus.
// A3A4FUM kawana-k 2015/02/18 End.
			bl_isRequestInitialize = True;
			nextGamen = &gp_Service2ndTransferAdjust_DoAm;
			break;
		default:break;
	}
}
//////////////////////////////////////////////////////////////
// 概要 : ﾌﾟﾛｾｽ調整/転写出力微調/1次転写微調(91002) : 設定終了.
//////////////////////////////////////////////////////////////
void PService1stTransferAdjustCom::procOk( uchar option )
{
// A3A4FUM kawana-k 2015/02/18 Start.
#ifndef DEF_A4_Cus
// comment 2014/12/03 HCLT_Vinothini [HeliosL][機器構成変更_No.22] [WP 363] store 1st transfer output value and removal of other adjustment values.
//Comment 2020/01/27 [HCLT_Hemachander] [IT6_HeliosMLK] [ OP_BTS-18275 ] Removing  HeliosMLK compiler switch.
#ifndef DEF_DonauBKCus
// Comment 2019/07/26 [HCLT_Paul] [IT6_HeliosMLK] [ Seigyu.10 ] Adding the HeliosMLK compiler switch.
//#if !defined ( DEF_DonauBKCus ) || !defined ( DEF_HeliosMLKCus )
	fixPrinterIndi( TYPE_PrinterAdjust1stTransferOutputAdjC );	//１次転写出力調整値 シアン.
	fixPrinterIndi( TYPE_PrinterAdjust1stTransferOutputAdjM );	//１次転写出力調整値 マゼンタ.
	fixPrinterIndi( TYPE_PrinterAdjust1stTransferOutputAdjY );	//１次転写出力調整値 イエロー.
#endif
	fixPrinterIndi( TYPE_PrinterAdjust1stTransferOutputAdjK );	//１次転写出力調整値 ブラック.
#else
	fixPrinterIndi( TYPE_PrinterAdjust1stTransferOutput	 );	//１次転写出力調整値 全色.
#endif // DEF_A4_Cus.
// A3A4FUM kawana-k 2015/02/18 End.
	PServiceChoiceAdjustCom10ToImageAdjustModeMenuCom::procOk( option );
}
