// 概要 : ﾌﾟﾛｾｽ調整/転写出力微調/1次転写微調(91002) : 表示画面のセットアップ.
//////////////////////////////////////////////////////////////
void PService1stTransferAdjustCom::setupGamen( short option )
{

// A3A4FUM kawana-k 2015/02/18 Start.
#ifndef DEF_A4_Cus
//Comment 2019/02/08[HCLT_Catherine][IT6_HeliosMLK][Seigyu.10 ]Other than HeliosMLKCus member variable used, so it is blocked to HeliosMLKCus.
//Comment 2019/07/26 [HCLT_Hemachander] [IT6_HeliosMLK] [ OP_BTS-18275 ] Removing Compiler Switch added for HeliosMLK.
//#ifndef DEF_HeliosMLKCus
	register short _select = -1;
//#endif //DEF_HeliosMLKCus.
// comment 2014/12/03 HCLT_Vinothini [HeliosL][機器構成変更_No.22] [WP 363] Updating the display 1st transfer output value and removal of other adjustment values.
// Comment 2019/07/26 [HCLT_Paul] [IT6_HeliosMLK] [ Seigyu.10 ] Adding the HeliosMLK compiler switch.
//Comment 2019/07/26 [HCLT_Hemachander] [IT6_HeliosMLK] [ OP_BTS-18275 ] Removing Compiler Switch added for HeliosMLK.
//#ifdef DEF_HeliosMLKCus
//	Btx_S1stTransferOutputAdjust  = (float)getPrinterIndi( TYPE_PrinterAdjust1stTransferOutputAdjK );
//#else
#ifdef DEF_MonoCus
	_select = 0;	// ブラック固定.
	Btx_S1stTransferOutputAdjC.showEnableAdd( False );		// １次転写出力調整値を非表示 シアン.
	Btx_S1stTransferOutputAdjM.showEnableAdd( False );		// １次転写出力調整値を非表示 マゼンタ.
	Btx_S1stTransferOutputAdjY.showEnableAdd( False );		// １次転写出力調整値を非表示 イエロー.
#else	// DEF_MonoCus.
	switch( getIndiSelected() ) {
		case TYPE_PrinterAdjust1stTransferOutputAdjC:	_select = 0;	break;	// １次転写出力調整値 シアン.
		case TYPE_PrinterAdjust1stTransferOutputAdjM:	_select = 1;	break;	// １次転写出力調整値 マゼンタ.
		case TYPE_PrinterAdjust1stTransferOutputAdjY:	_select = 2;	break;	// １次転写出力調整値 イエロー.
		case TYPE_PrinterAdjust1stTransferOutputAdjK:	_select = 3;	break;	// １次転写出力調整値 ブラック.
		default:break;
	}

	Btx_S1stTransferOutputAdjC	 = ( float )getPrinterIndi( TYPE_PrinterAdjust1stTransferOutputAdjC );		// １次転写出力調整値 シアン.
	Btx_S1stTransferOutputAdjM	 = ( float )getPrinterIndi( TYPE_PrinterAdjust1stTransferOutputAdjM );		// １次転写出力調整値 マゼンタ.
	Btx_S1stTransferOutputAdjY	 = ( float )getPrinterIndi( TYPE_PrinterAdjust1stTransferOutputAdjY );		// １次転写出力調整値 イエロー.
	Rbt_S1stTransferOutputAdjPosition.select( _select );
#endif	// DEF_MonoCus.
//#endif		// DEF_HeliosCus.
// comment 第5回IT4マージ <- Sky松本 2010/10/08.
// comment 2014/12/03 HCLT_Vinothini [HeliosL][機器構成変更_No.22] [WP 363] Updating the display 1st transfer output value and removal of other adjustment values.
// Comment 2019/07/26 [HCLT_Paul] [IT6_HeliosMLK] [ Seigyu.10 ] Adding the HeliosMLK compiler switch.
//Comment 2019/07/26 [HCLT_Hemachander] [IT6_HeliosMLK] [ OP_BTS-18275 ] Removing Compiler Switch added for HeliosMLK.
//#if !defined ( DEF_HeliosMLKCus )
	Btx_S1stTransferOutputAdjK	 = ( float )getPrinterIndi( TYPE_PrinterAdjust1stTransferOutputAdjK );		// １次転写出力調整値 ブラック.
	Rbt_S1stTransferOutputAdjGamen.select( False );
	Rbt_S1stTransferOutputAdjPosition.select( _select );
//#else
//	Rbt_S1stTransferOutputAdjGamen.select( False );
//#endif		// !DEF_HeliosCus.
#else
	Btx_S1stTransferOutputAdjALL	 = (float)getPrinterIndi( TYPE_PrinterAdjust1stTransferOutput );		// １次転写出力調整値 全色.
	Rbt_S1stTransferOutputAdjGamen.select( False );
#endif // DEF_A4_Cus.
// A3A4FUM kawana-k 2015/02/18 End.
	PServiceNoFunctionCodeCom::setupGamen( option );	// 表示部品のセットアップ
}
