// ==========================================================================
// Overview: Q5B1000000_TrailEdgeCorrection. : OK key.
// ===========================================================================
void PServiceImageAdjustRearEdgeCorrection::procOk( uchar option )
{
	if ( m_bl_StartLEDflag == True )
		return;
#ifndef DEF_MonoCus
	fixPrinterIndi( TYPE_PrinterAdjustRearEdgeAdjCtrl_C );	
	fixPrinterIndi( TYPE_PrinterAdjustRearEdgeAdjCtrl_M );	
	fixPrinterIndi( TYPE_PrinterAdjustRearEdgeAdjCtrl_Y );
	if ( getPrinterIndi( TYPE_PrinterAdjustRearEdgeAdjCtrl_C ) ) {	
		fixPrinterIndi( TYPE_PrinterAdjustRearEdgeAdjVal_C );	
	}
	if ( getPrinterIndi( TYPE_PrinterAdjustRearEdgeAdjCtrl_M ) ) {
		fixPrinterIndi( TYPE_PrinterAdjustRearEdgeAdjVal_M );	
	}
	if ( getPrinterIndi( TYPE_PrinterAdjustRearEdgeAdjCtrl_Y ) ) {
		fixPrinterIndi( TYPE_PrinterAdjustRearEdgeAdjVal_Y );	
	}
#endif
	fixPrinterIndi( TYPE_PrinterAdjustRearEdgeAdjCtrl_K );	
	if ( getPrinterIndi( TYPE_PrinterAdjustRearEdgeAdjCtrl_K ) ) {
		fixPrinterIndi( TYPE_PrinterAdjustRearEdgeAdjVal_K );
	}

	// Service / process adjustment / screen transition to mode menu.
	nextGamen = &gp_ServiceImageAdjustModeMenu;
}

// ==========================================================================
// Overview: Q5B1000000_TrailEdgeCorrection. : Reset key.
// ===========================================================================
void PServiceImageAdjustRearEdgeCorrection::procReset( uchar option )
{
	if ( m_bl_StartLEDflag == True )
		return;
	
	PServiceFunctionEnableStartCom::procReset( option );
}
// ==========================================================================
// Overview: Q5B1000000_TrailEdgeCorrection. : Button (press and change quickly).
// ===========================================================================
void PServiceImageAdjustRearEdgeCorrection::procButtonStillOnFast( uchar option )
{
	if( option == BTNID_KEY_RearEdgeAdjCtrlSUBVal || option == BTNID_KEY_RearEdgeAdjCtrlADDVal ) { procButtonOn( option ); }
}
// ==========================================================================
// Overview: Q5B1000000_TrailEdgeCorrection. : Active notification.
// ===========================================================================
void PServiceImageAdjustRearEdgeCorrection::procActivate()
{
	Key_ServiceRearEdgeTstPtnPrinting.showEnableShow( True );
	Txt_ServiceRearEdgeArrow.showEnableShow ( True );
	Txt_ServiceRearEdgePaperSizeDisp.showEnableShow ( True );
}
// Comment 2019/09/06 [HCLT-Hanuman] [IT6_Eagle_Z+] Start key LED status correction based on paper existance in Trays.
// ==========================================================================
// Overview: Q5B1000000_TrailEdgeCorrection. : To Check paper status.
// ===========================================================================
Bool PServiceImageAdjustRearEdgeCorrection::isPaperExist( TYPE_FeedTray&  uc_TrayType  )
{
	Bool bl_PaperExist= False;
	uc_TrayType = TYPE_FeedTrayUnselect;
	static TYPE_FeedTray tbl_TraySearch[] = {
		TYPE_FeedTray1,
		TYPE_FeedTray2,
		TYPE_FeedTray3,
		TYPE_FeedTray4,
		TYPE_FeedTray5,
		TYPE_FeedTrayManual,
	};
	APIC_FeedTray* pc_FeedTray = PnlComGetFeedTray();
	for ( uchar ucTraySel = 0; ucTraySel < sizeof(tbl_TraySearch) / sizeof (TYPE_FeedTray); ucTraySel++ )
	{
		if ( ( TYPE_TrayStatusNon != pc_FeedTray->getTrayStatus(tbl_TraySearch[ucTraySel] ) )  
			&& ( TYPE_PaperStatusEmpty != pc_FeedTray->getPaperStatus( tbl_TraySearch[ucTraySel] ) ) ) {
			TYPC_PaperSize c_PaperSize = pc_FeedTray->getPaperSize( tbl_TraySearch[ucTraySel] );
			if ( ( ( c_PaperSize == TYPE_SizeCodeLedgerSef || c_PaperSize == TYPE_SizeCodeLetterLef )
				|| ( c_PaperSize == TYPE_SizeCodeA4Lef || c_PaperSize == TYPE_SizeCodeA3Sef ) ) 
				&& ( m_bl_TstPtnflag == True ) ) {
				bl_PaperExist =True;
				uc_TrayType = tbl_TraySearch[ucTraySel];
				break;
			}
		}
	}
	return bl_PaperExist;
}

// comment 2021/03/18 fp-CuongNT14 [IT6_2.2][EagleZ/X/Z+][機器No.7【EagleⅡ】【IT6_2.2】エッジ補正制御搭載].
// ========================================================================================================
// Overview: Q5B1000000_TrailEdgeCorrection. : Evaluate machine type are Eagle Z or X or Z+.
// ========================================================================================================
Bool PServiceImageAdjustRearEdgeCorrection::isEagleZXZp()
{
	TYPE_MachineType e_MachineType = PnlComGetSystemInfo()->getMachineType();
	// Supported machine  type : Eagle Z, X, Z+ only !.
	return ( e_MachineType == TYPE_MachineTypeEagleZ || 
			 e_MachineType == TYPE_MachineTypeEagleX ||
			 e_MachineType == TYPE_MachineTypeEagleZplus );
}
// comment 2021/03/29 fp-CuongNT14 [IT6_2.2][EagleZ/X/Z+][機器No.7【EagleⅡ】【IT6_2.2】エッジ補正制御搭載].
// ========================================================================================================
// Overview: Q5B1000000_TrailEdgeCorrection. : reload state of Solid/Half/Solid & Half buttons.
// ========================================================================================================
void PServiceImageAdjustRearEdgeCorrection::loadStateOfSolidHalfSolidAndHalf()
{
#ifndef DEF_MonoCus
	// Load state for C/M/Y/K.
	Rbt_ServiceRearEdgeAdjCtrlC.select( getPrinterIndi( TYPE_PrinterAdjustRearEdgeAdjCtrl_C ) > 0 ? 1 : 0 );
	Rbt_ServiceRearEdgeAdjCtrlM.select( getPrinterIndi( TYPE_PrinterAdjustRearEdgeAdjCtrl_M ) > 0 ? 1 : 0 );
	Rbt_ServiceRearEdgeAdjCtrlY.select( getPrinterIndi( TYPE_PrinterAdjustRearEdgeAdjCtrl_Y ) > 0 ? 1 : 0 );

    // Load state for Solid/Half-tone/Solid&Halftone.
	// At less C/M/Y/K have ON state and then select the current value
	Rbt_RearEdgeAdjCtrlColorDentisy.select( m_SolidHalfCurrSeleted - 1 );
#endif
	// Load state for Black.
	Rbt_ServiceRearEdgeAdjCtrlK.select( getPrinterIndi( TYPE_PrinterAdjustRearEdgeAdjCtrl_K ) > 0 ? 1 : 0 );
}

// ========================================================================================================
// Overview: Q5B1000000_TrailEdgeCorrection. : If all CMYK is OFF select to the 'solid' button.
// ========================================================================================================
void PServiceImageAdjustRearEdgeCorrection::checkAllCMYKisOFF()
{
	if ( TYPE_PrinterAdjustRearEdgeAdjCtrlType_OFF == getPrinterIndi( TYPE_PrinterAdjustRearEdgeAdjCtrl_C ) &&
		 TYPE_PrinterAdjustRearEdgeAdjCtrlType_OFF == getPrinterIndi( TYPE_PrinterAdjustRearEdgeAdjCtrl_M ) &&
		 TYPE_PrinterAdjustRearEdgeAdjCtrlType_OFF == getPrinterIndi( TYPE_PrinterAdjustRearEdgeAdjCtrl_Y ) &&
		 TYPE_PrinterAdjustRearEdgeAdjCtrlType_OFF == getPrinterIndi( TYPE_PrinterAdjustRearEdgeAdjCtrl_K )) {
		// Select default to Solid
		m_SolidHalfCurrSeleted = 1;
	}
}

// ========================================================================================================
// Overview: Q5B1000000_TrailEdgeCorrection. : Process when buttons Solid/Half/Solid and Half is clicked.
// ========================================================================================================
void PServiceImageAdjustRearEdgeCorrection::procButtonSolidHaflSolidAndHaf(  )
{
	// Validate current clicked state of buttons Solid/Half-tone/Solid&Halftone.
	if (m_SolidHalfCurrSeleted < 1 || m_SolidHalfCurrSeleted > 3){
		return;
	}
	// Change value for Cyan when current state is ON.
	if( getPrinterIndi( TYPE_PrinterAdjustRearEdgeAdjCtrl_C ) > 0){
		// Select solid/half/solid&half.
		setPrinterIndi( TYPE_PrinterAdjustRearEdgeAdjCtrl_C, m_SolidHalfCurrSeleted );
	}

	// Change value for Mangenta when current state is ON.
	if( getPrinterIndi( TYPE_PrinterAdjustRearEdgeAdjCtrl_M ) > 0){
		// Select solid/half/solid&half.
		setPrinterIndi( TYPE_PrinterAdjustRearEdgeAdjCtrl_M, m_SolidHalfCurrSeleted );
	}

	// Change value for Yellow when current state is ON.
	if( getPrinterIndi( TYPE_PrinterAdjustRearEdgeAdjCtrl_Y ) > 0){
		// Select solid/half/solid&half.
		setPrinterIndi( TYPE_PrinterAdjustRearEdgeAdjCtrl_Y, m_SolidHalfCurrSeleted );
	}

	// Change value for Black when current state is ON.
	if( getPrinterIndi( TYPE_PrinterAdjustRearEdgeAdjCtrl_K ) > 0){
		// Select solid/half/solid&half.
		setPrinterIndi( TYPE_PrinterAdjustRearEdgeAdjCtrl_K, m_SolidHalfCurrSeleted );
	}
}

