//				break;
//		case 3 : uc_TrayType = TYPE_FeedTray4;
//				break;
//		case 4 : uc_TrayType = TYPE_FeedTray5;
//				break;
//		case 5 : uc_TrayType = TYPE_FeedTrayManual;
//				break;
//		}
//			
//		if( uc_TrayType )
//		{		
//			if ( ( pc_FeedTray->getPaperSize( uc_TrayType ) == TYPE_SizeCodeLedgerSef ) 
//			|| ( pc_FeedTray->getPaperSize( uc_TrayType ) == TYPE_SizeCodeLetterLef )
//			|| ( pc_FeedTray->getPaperSize( uc_TrayType ) == TYPE_SizeCodeA4Lef )
//			|| ( pc_FeedTray->getPaperSize( uc_TrayType ) == TYPE_SizeCodeA3Sef ) ) {
//				bl_PeperExist =True;
//				break;				
//			}
//		}
//	}
	TYPE_FeedTray  uc_TrayType = TYPE_FeedTrayUnselect;
	Bool bl_PaperExist= isPaperExist(uc_TrayType);
//	if( False == bl_PeperExist){		
	if( False == bl_PaperExist){
		setBuzzerType( PCGE_BuzzerType_InputNg );	// 報知音設定 //Do Nothing.
		return;
	}
	setFunctionFeedCode( uc_TrayType );									
	setFunctionCode(TYPD_FNC_RearEdgeCorrection);
