	fixPrinterIndi( TYPE_PrinterAdjustRearEdgeAdjCtrl_C );	
	fixPrinterIndi( TYPE_PrinterAdjustRearEdgeAdjCtrl_M );	
	fixPrinterIndi( TYPE_PrinterAdjustRearEdgeAdjCtrl_Y );	
