//================================================================================================
// 概要		:サービス・システム設定1・不良箇所切り離し・共通 : 画面遷移
//================================================================================================
void PServiceSystemPartsCutCom::procGoToPage( uchar option )
{
// Comment 2019/11/12 [HCLT_hepzibah] [IT6_HeliosMLK] [ 機器構成変更_No20 ] Hiding Staple, Fold and Punch items for HeliosMLK_China.
#ifdef DEF_HeliosMLKCus
	TYPE_MachineType e_MachineType = PnlComGetSystemInfo()->getMachineType(); 
#endif
	switch( option ) {
		case 1:	uc_page = 0;	nextGamen = &gp_ServiceSystemPartsCut1;		break;	// 不良箇所切り離し1.
//comment 2018/06/08 HCLT-Neelima [Sparrow][機器構成変更No.1] Disable page3 for DenebMLK.
//Comment 2018/08/06 【HCLT-Chinna】【IT6_Sp】【AR-1046905】removing the finisher related items.
//		case 2:	uc_page = 1;	nextGamen = &gp_ServiceSystemPartsCut2; 	break;	// 不良箇所切り離し2.
		case 2:	uc_page = 1;
// Comment 2019/11/12 [HCLT_hepzibah] [IT6_HeliosMLK] [ 機器構成変更_No20 ] Hiding Staple, Fold and Punch items for HeliosMLK_China.
//Comment 2018/10/25 【HCLT-Neelima】【IT6_DenebMLK】【AR-1061372 】removing the finisher related items.
// Comment 2019/12/13 【HCLT_Hemachander】【HeliosMLK】【制御構成変更_No.52】 Adding Machine Type for China Models.
//#if !defined( DEF_DenebMLKCus ) || !defined( DEF_SparrowCus )
#if !defined( DEF_DenebMLKCus ) && !defined( DEF_SparrowCus )
#ifdef DEF_HeliosMLKCus
	if ( ( TYPE_MachineTypeHeliosMLK3_CN == e_MachineType ) 
		|| ( TYPE_MachineTypeHeliosMLK2_CNDF == e_MachineType )
		|| ( TYPE_MachineTypeHeliosMLK2_5_CN == e_MachineType )
		|| ( TYPE_MachineTypeHeliosMLK2_5_CNDF == e_MachineType )
		|| ( TYPE_MachineTypeHeliosMLKEmu800_CN == e_MachineType) ) {
		nextGamen = &gp_ServiceSystemPartsCut3;
	} else {
		nextGamen = &gp_ServiceSystemPartsCut2;
	}
#else	// DEF_HeliosMLKCus.
		nextGamen = &gp_ServiceSystemPartsCut2;
#endif	// DEF_HeliosMLKCus.
#else  //!defined( DEF_DenebMLKCus ) || !defined( DEF_SparrowCus ).
			if ( ! IsSFP() ) {
				nextGamen = &gp_ServiceSystemPartsCut3;
			}
#endif //!defined( DEF_DenebMLKCus ) || !defined( DEF_SparrowCus ).		
		break;	// 不良箇所切り離し2.
		case 3:	uc_page = 2;	nextGamen = &gp_ServiceSystemPartsCut3; 	break;	// 不良箇所切り離し3.
		default:	break;
	}
}
