//================================================================================================.
// 概要		:サービス・システム設定1・状態表示LED設定 : 初期設定.
// 戻り値	:なし.
//================================================================================================.
void PServiceSystemStateLEDSetting::startGamen()
{
	PBasicMessageProc::startGamen();

	APIC_LEDStatusSetting* pc_LEDStatusSetting = APIC_LEDStatusSetting::newInstance(); // インスタンス取得.
	// CommonAPIからLED設定タイプを取得.
	e_TypeWarningStatus		= pc_LEDStatusSetting->getWarningStatus();
	e_TypePaperRemainder	= pc_LEDStatusSetting->getRemainPaperStatus();

	// パーツ表示制御
	CheckShowParts();
}
//================================================================================================.
// 概要		:サービス・システム設定1・状態表示LED設定 : ボタン(押された).
// 戻り値	:なし.
//================================================================================================.
void PServiceSystemStateLEDSetting::procButtonOn( uchar option )
{
	switch( option ) {
		case 0: e_TypeWarningStatus = TYPE_LEDStatus_Type1; break;	// Type1ボタン押下.
		case 1: e_TypeWarningStatus = TYPE_LEDStatus_Type2; break;	// Type2ボタン押下.
		case 2: e_TypePaperRemainder = TYPE_LEDStatus_Type1; break;	// Type1ボタン押下.
		case 3: e_TypePaperRemainder = TYPE_LEDStatus_Type2; break;	// Type2ボタン押下.
		default: break;
	}
	setupGamen();	// 表示部品のセットアップ.
}
//================================================================================================.
// 概要		:サービス・システム設定1・状態表示LED設定 : OKキー.
// 戻り値	:なし.
//================================================================================================.
void PServiceSystemStateLEDSetting::procOk( uchar option )
{
	APIC_LEDStatusSetting* pc_LEDStatusSetting = APIC_LEDStatusSetting::newInstance(); // インスタンス取得.
	// CommonAPIへLED設定タイプを設定.
	pc_LEDStatusSetting->setWarningStatus( e_TypeWarningStatus );
	pc_LEDStatusSetting->setRemainPaperStatus( e_TypePaperRemainder );
	PServiceToSystemMenuCom::procOk( option );	// 親クラスの処理を呼ぶ.

}
//================================================================================================.
// 概要		:サービス・システム設定1・状態表示LED設定 : 表示画面のセットアップ.
// 戻り値	:なし.
//================================================================================================.
void PServiceSystemStateLEDSetting::setupGamen( short option )
{
	Rbt_StateLEDSettingWarningStatusType.select( e_TypeWarningStatus == TYPE_LEDStatus_Type1 ? 0 : 1 );	// 状態表示LED設定・選択(タイプ1/タイプ2)ボタン.
	Rbt_StateLEDSettingPaperRemainderType.select( e_TypePaperRemainder == TYPE_LEDStatus_Type1 ? 0 : 1 );	// 状態表示LED設定・選択(タイプ1/タイプ2)ボタン.
	PServiceToSystemMenuCom::setupGamen( option );	// 親クラスの処理を呼ぶ.
}
