void PServiceCounterJamCLCD::setClearCounter()
{
	if( clear_counter_name != TYPE_JamCntSize ) {
		cp_JamCnt->clear( counterDisp_Jam[counterGamenNum][counterSelectNum].name );	// カウンタ値のクリア実行.
		counter_back[ counterSelectNum ] = clear_counter_num;						// 変更したカウンタ値のバックアップ.
		// カウンタクリア対象を未選択にする.
		clear_counter_name = TYPE_JamCntSize;
	}
}
