void PServiceCounterJamCLCD::backupCounter()
{

	for( register ushort i = 0; i < COUNTER_TUPLE_NUM; i++ ) {
		counter_back[i] = cp_JamCnt->get( counterDisp_Jam[counterGamenNum][i].name );	// 各カウンタ値の取得.
	}
}
