//================================================================================================
//［機能設定］	サービス・カウンタ・区間トラブル : トラブルカウンタ取得処理.
//================================================================================================
void PServiceCounterSectionTrouble::GetCounterBackup()
{
//comment 2017/09/19 【HCLT-Hanuman】 【Eagel】【AR1028979】Invalid Counter Name.
//	APIC_TroubleTotalCnt* cp_TroubleTotalCnt = APIC_TroubleTotalCnt::newInstance();
//	for( register ushort i = 0; i < COUNTER_TUPLE_NUM; i++ )
//	{ counter_back[i] = cp_TroubleTotalCnt->get( GetTroubleCounterFromList( ss_NowPage, i ).name ); }
	APIC_TroubleTotalCnt* cp_TroubleTotalCnt = APIC_TroubleTotalCnt::newInstance();
	for ( register ushort i = 0; i < COUNTER_TUPLE_NUM; i++ ) {
		ushort us_CounterName = GetTroubleCounterFromList( ss_NowPage, i ).name;
		if ( TYPE_TroubleCntSize != us_CounterName ) {
			counter_back[i] = cp_TroubleTotalCnt->get( us_CounterName );
		}
	}
}

//================================================================================================
// 概要		：サービス・カウンタ・区間トラブル：表示画面のセットアップ
//================================================================================================
void PServiceCounterSectionTrouble::setupGamen( short option )
{
	PServiceCounterTrouble::setupGamen( option );
// Comment 2018/12/20 【HCLT-Ranjith】【IT6_EagleH】[制御構成変更_No.37] Reset information on Section Counter screen.
	if( True == PLBC_FuncVersionCheck::isOK_IT6_Type1() ) {
		APIC_TroubleTotalCnt* cp_TroubleTotalCnt = APIC_TroubleTotalCnt::newInstance();
		if( NULL == cp_TroubleTotalCnt ) {
			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
			return;
		}
		char sc_resetDateTime[PNLD_CounterresetDateTime];
		char sc_TotalCounter[PNLD_CounterTotalCounter];
		memset( sc_resetDateTime, 0x00, sizeof( sc_resetDateTime ) );
		memset( sc_TotalCounter, 0x00, sizeof( sc_TotalCounter ) );
		TYPS_CounterResetInfo c_cntResetInfo;
		cp_TroubleTotalCnt->getTroubleCntResetInfo( &c_cntResetInfo );					// Get section counter reset value.
		Txt_TitleServiceCounterResetDateTime.showEnable( True );
		Txt_TitleServiceCounterTotalCounter.showEnable( True );
		Tfd_ServiceCounterResetDateTime.showEnable( True );
		Tfd_ServiceCounterTotalCounter.showEnable( True );
		if ( ( c_cntResetInfo.c_Date.sc_Month == 0 ) && ( c_cntResetInfo.c_Date.sc_Day == 0 ) ){	// If counter resetnot occur.
			snprintf( ( char* )sc_resetDateTime, sizeof( sc_resetDateTime ),"----/--/--\n--:--");
			snprintf( ( char* )sc_TotalCounter, sizeof( sc_TotalCounter ),"-");
		} else {																	// If counter reset occur.								
			snprintf( ( char* )sc_resetDateTime, sizeof( sc_resetDateTime ),"%04d/%02d/%02d\n%02d:%02d",
		    c_cntResetInfo.c_Date.ss_Year,c_cntResetInfo.c_Date.sc_Month, c_cntResetInfo.c_Date.sc_Day, c_cntResetInfo.c_Date.sc_Hour, c_cntResetInfo.c_Date.sc_Minute );
			snprintf( ( char* )sc_TotalCounter, sizeof( sc_TotalCounter ),"%08d",c_cntResetInfo.ul_TotalCounter );
		}
		Tfd_ServiceCounterResetDateTime.changeExternalText( ( uchar* )sc_resetDateTime );	// Print counter reset date and time.
		Tfd_ServiceCounterTotalCounter.changeExternalText( ( uchar* )sc_TotalCounter );		// Print counter reset total counter.
	} else {
		Txt_TitleServiceCounterResetDateTime.showEnable( False );
		Txt_TitleServiceCounterTotalCounter.showEnable( False );
		Tfd_ServiceCounterResetDateTime.showEnable( False );
		Tfd_ServiceCounterTotalCounter.showEnable( False );
	}
	Txt_TitleServiceCounterTrouble1.changeText( s_TTLSectionServiceCallX16Y1 );
}
