void PServiceCounterPartsFixation::startGamen()
{
	PServiceCounterCom::startGamen();	// カウンタ共通初期化
	CheckAndExecInit();					// 初期化必要か否か取得して必要なら実行する
//Comment 2020/03/05 [HCL-Arun] [IT6_2.0MR2] [OP_BTS-18570] Based on finisher counter value will be updated	
	TYPE_FinisherType e_FinisherType = PnlComGetPrinterSystem()->getFinisherType();	// Declaring variable e_FinisherType to store the Finisher Type.
	{ memset( counterDisp_PartsFixation, '\0', sizeof( counterDisp_PartsFixation ) ); }
	if (TYPE_FinisherTypeFS533 ==  e_FinisherType ) {
    ushort i = 0;
	    for( i = 0; i < STRUCT_SIZE( counterDisp_PartsFixation_FS_533[0] );i++ ){
				counterDisp_PartsFixation[0][i].name=counterDisp_PartsFixation_FS_533[0][i].name;
	        	counterDisp_PartsFixation[0][i].ss_no=counterDisp_PartsFixation_FS_533[0][i].ss_no;
				counterDisp_PartsFixation[0][i].text=counterDisp_PartsFixation_FS_533[0][i].text;
				counterDisp_PartsFixation[0][i].pn =counterDisp_PartsFixation_FS_533[0][i].pn;
	           strncpy(	counterDisp_PartsFixation[0][i].ss_Limit,counterDisp_PartsFixation_FS_533[0][i].ss_Limit,STRUCT_SIZE( counterDisp_PartsFixation_FS_533[0] ));
		}
}
	else if (TYPE_FinisherTypeFS536 ==  e_FinisherType ) {
		   ushort i = 0;
	    for( i = 0; i < STRUCT_SIZE( counterDisp_PartsFixation_FS_536[0] );i++ ){
				counterDisp_PartsFixation[0][i].name=counterDisp_PartsFixation_FS_536[0][i].name;
	        	counterDisp_PartsFixation[0][i].ss_no=counterDisp_PartsFixation_FS_536[0][i].ss_no;
				counterDisp_PartsFixation[0][i].text=counterDisp_PartsFixation_FS_536[0][i].text;
				counterDisp_PartsFixation[0][i].pn =counterDisp_PartsFixation_FS_536[0][i].pn;
	           strncpy(	counterDisp_PartsFixation[0][i].ss_Limit,counterDisp_PartsFixation_FS_536[0][i].ss_Limit, STRUCT_SIZE( counterDisp_PartsFixation_FS_536[0] ));
		}
}	
	else if (TYPE_FinisherTypeFS539 ==  e_FinisherType ) {
		   ushort i = 0;
	    for( i = 0; i < STRUCT_SIZE( counterDisp_PartsFixation_FS_539[0] );i++ ){
				counterDisp_PartsFixation[0][i].name=counterDisp_PartsFixation_FS_539[0][i].name;
	        	counterDisp_PartsFixation[0][i].ss_no=counterDisp_PartsFixation_FS_539[0][i].ss_no;
				counterDisp_PartsFixation[0][i].text=counterDisp_PartsFixation_FS_539[0][i].text;
				counterDisp_PartsFixation[0][i].pn =counterDisp_PartsFixation_FS_539[0][i].pn;
	           strncpy(	counterDisp_PartsFixation[0][i].ss_Limit,counterDisp_PartsFixation_FS_539[0][i].ss_Limit,STRUCT_SIZE( counterDisp_PartsFixation_FS_539[0] ));
		}
	}
	else if (TYPE_FinisherTypeFS540 ==  e_FinisherType ) {
		   ushort i=0,j = 0;
	    for( i = 0; i < PARTS_FIXATION_COUNTER_GAMEN;i++ ){
	    	for ( j = 0; j < PARTS_FIXATION_COUNTER_NUM;j++ ){
				counterDisp_PartsFixation[i][j].name=counterDisp_PartsFixation_FS_540[i][j].name;
	        	counterDisp_PartsFixation[i][j].ss_no=counterDisp_PartsFixation_FS_540[i][j].ss_no;
				counterDisp_PartsFixation[i][j].text=counterDisp_PartsFixation_FS_540[i][j].text;
				counterDisp_PartsFixation[i][j].pn =counterDisp_PartsFixation_FS_540[i][j].pn;
	           strncpy(	counterDisp_PartsFixation[i][j].ss_Limit,counterDisp_PartsFixation_FS_540[i][j].ss_Limit,STRUCT_SIZE( counterDisp_PartsFixation_FS_540[0] ));
			}
	    }
	}
// Comment 2023/6/20 FPT-LONGTH32 [IT6_2.3]【OP_BTS-43982】Fix bug Parts Counter Fixed screen for FS542.
	else if ( TYPE_FinisherTypeFS542 == e_FinisherType ) {
			ushort i = 0;
		for( i = 0; i < STRUCT_SIZE( counterDisp_PartsFixation_FS_542[0] );i++ ){
				counterDisp_PartsFixation[0][i].name= counterDisp_PartsFixation_FS_542[0][i].name;
				counterDisp_PartsFixation[0][i].ss_no=counterDisp_PartsFixation_FS_542[0][i].ss_no;
				counterDisp_PartsFixation[0][i].text=counterDisp_PartsFixation_FS_542[0][i].text;
				counterDisp_PartsFixation[0][i].pn =counterDisp_PartsFixation_FS_542[0][i].pn;
				strncpy( counterDisp_PartsFixation[0][i].ss_Limit,counterDisp_PartsFixation_FS_542[0][i].ss_Limit,STRUCT_SIZE( counterDisp_PartsFixation_FS_542[0] ) );
		}
	}
}
//================================================================================================
// 概要		:サービス・カウンタ・固定パーツカウンタ ： 変数などの初期化.
//================================================================================================
void PServiceCounterPartsFixation::init_value()
{
	PServiceCounterCom::init_value();
	// ボタン未選択状態にする
	Rbt_ServiceCounter7typeLong.select( -1 );
	// 1ページ目を表示
	counterGamenNum = 0;
	// カウンタクリア対象を未選択にする
	clear_counter_name = TYPE_PartsCntSize;
}
//================================================================================================
// 概要		:サービス・カウンタ・固定パーツカウンタ ：クリアキー .
//================================================================================================
void PServiceCounterPartsFixation::procClear( uchar option )
{
	if( counterSelectNum == -1 ) {
		// 未選択状態なら何もせずリターン
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}
	// カウンタクリア対象を設定する
	clear_counter_name = counterDisp_PartsFixation[counterGamenNum][counterSelectNum].name;
	// 選択されたカウンタを０クリアする
	clear_counter_num = 0;
	setupGamen();	// 表示部品のセットアップ
}
//================================================================================================
// 概要		:サービス・カウンタ・固定パーツカウンタ ： 割り込みモード .
//================================================================================================
void PServiceCounterPartsFixation::procIntMode( uchar option )
{
	if( counterSelectNum == -1 ) {
		// 未選択状態なら何もせずリターン
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}
	// カウンタクリア対象を未選択にする
	clear_counter_name = TYPE_PartsCntSize;
	// ゼロクリアされたカウンタをクリア前の値に復帰する
	clear_counter_num = counter_back[counterSelectNum];
	setupGamen();	// 表示部品のセットアップ
}
// comment 2017/01/25 SCD2-2G Sky松下 [IT5_3.4][1012690] IDキーへの割り込み押下処理の割り当て.
//================================================================================================
// 概要		:サービス・カウンタ・固定パーツカウンタ : IDキー.
// 戻り値	:なし
// 備考		:
//================================================================================================
void PServiceCounterPartsFixation::procIDInput( uchar option )
{
	procIntMode( option );							// 割り込みキー押下処理をコール.
}
//================================================================================================
// 概要		:サービス・カウンタ・固定パーツカウンタ ：画面移動 .
//================================================================================================
void PServiceCounterPartsFixation::procGoToPage( uchar option )
{
	setClearCounter();	// カウンタ書き換え通知
	bl_isRequestInitialize = True;
	switch( option ) {
		case 1:	counterSelectNum = -1;	counterGamenNum = 0;	break;
		case 2:	counterSelectNum = -1;	counterGamenNum = 1;	break;
		case 3:	counterSelectNum = -1;	counterGamenNum = 2;	break;
		case 4:	counterSelectNum = -1;	counterGamenNum = 3;	break;
		default:break;
	}
	setupGamen();
}
//================================================================================================
// 概要		:サービス・カウンタ・固定パーツカウンタ ：表示画面のセットアップ .
//================================================================================================
void PServiceCounterPartsFixation::setupGamen( short option )
{
	register short num = counterGamenNum;		// カウンタ画面番号
	char sc_SCounterPartsFixation[ 8 + 1 ];		// 固定パーツカウンタ.
	register ushort i;
	//カウンタバックアップ値をとる
	for( i = 0; i < STRUCT_SIZE( counterDisp_PartsFixation[counterGamenNum] ); i++ ) {
		counter_back[i] = cp_PartsCnt->get( counterDisp_PartsFixation[counterGamenNum][i].name );	// 各カウンタ値の取得
	}
// comment 2014/01/08 HCLT_Rajanarender [HeliosL][Control Configuration Change No.6] Fixed parts counter screen number selection.	
//// comment 2014/06/30 【HCL-Thangachamy】 [Poseidon] 【制御構成変更_No.17&18&05】 Fixed parts counter screen number selection.
//#ifdef DEF_Zeus5BkCus
// Comment 2019/07/26 [HCLT_Paul] [IT6_HeliosMLK] [ Seigyu.10 ] Adding the HeliosMLK compiler switch.
#if (defined(DEF_Zeus5BkCus) || defined(DEF_HeliosMLKCus))
	Rbt_ServiceMoveGamen4.showEnable( False );	// Single page is needed for Zeus5BK.
#else
//Comment 2020/03/05 [HCL-Arun] [IT6_2.0MR2] [OP_BTS-18570] 4th page hidden for finishers
	TYPE_FinisherType e_FinisherType = PnlComGetPrinterSystem()->getFinisherType();	// Declaring variable e_FinisherType to store the Finisher Type.
// comment 2023/08/28 MSD2G Sky Murata [特ROM対応][OP_BTS-44335]FS542装着時に不要なページ選択ボタンが表示される.
//	if((TYPE_FinisherTypeFS533 ==  e_FinisherType )||(TYPE_FinisherTypeFS536 ==  e_FinisherType )||(TYPE_FinisherTypeFS539 ==  e_FinisherType )){
	if((TYPE_FinisherTypeFS533 ==  e_FinisherType )||(TYPE_FinisherTypeFS536 ==  e_FinisherType )||(TYPE_FinisherTypeFS539 ==  e_FinisherType )||(TYPE_FinisherTypeFS542 ==  e_FinisherType )){
	    Rbt_ServiceMoveGamen4.showEnable( False );	// Single page is needed for FS-533,FS-536,FS-539,FS-542.
	} else if(TYPE_FinisherTypeFS540 ==  e_FinisherType ) {
		Rbt_ServiceMoveGamen4.select( num );
		Key_SMoveGamen_4.showEnable( False );	// 右端の画面番号ボタン選択.
	} else{
		Rbt_ServiceMoveGamen4.select( num );	// 右端の画面番号ボタン選択.
	}
#endif //#if (defined(DEF_Zeus5BkCus) || defined(DEF_HeliosCus))
	for( i = 0; i < PARTS_FIXATION_COUNTER_NUM; i++ ) {
		if( counterDisp_PartsFixation[ num ][ i ].name == clear_counter_name ) {
			snprintf( ( char* )sc_SCounterPartsFixation, sizeof( sc_SCounterPartsFixation ),  "%8d", clear_counter_num );	// カウンタ.
		} else {
			snprintf( ( char* )sc_SCounterPartsFixation, sizeof( sc_SCounterPartsFixation ), "%8d", counter_back[i] );		// カウンタ.
		}
		Key_SCounter7typeLong[i].set( &Num_SCounterPartsFixationNo[i], ( short )counterDisp_PartsFixation[ num ][ i ].ss_no, True );
		Key_SCounter7typeLong[i].changeText( &Txt_SCounterPartsFixationName[i], counterDisp_PartsFixation[ num ][ i ].text );
		if( TYPE_PartsCntFNSStaplerFront == counterDisp_PartsFixation[ num ][ i ].name ) {
			// FNS平とじステープラー.
//Comment 2020/03/05 [HCL-Arun] [IT6_2.0MR2] [OP_BTS-18570] StaplerFront table changed	
			//CounterDisp_PartsFixation* p_StaplerFront = getPartsFixation_StaplerFront();	
			CounterDisp_PartsFixation* p_StaplerFront = &counterDisp_PartsFixation[ num ][ i ];//getPartsFixation_StaplerFront();
			if( NULL != p_StaplerFront ) {
				Key_SCounter7typeLong[i].changeText( &Inp_SCounterPartsFixationPN[i], p_StaplerFront->pn );								// P/N.
				Key_SCounter7typeLong[i].changeASCIIText( &Inp_SCounterPartsFixationLimit[i], ( const uchar* )p_StaplerFront->ss_Limit );	// リミット値.
			} else {
				// 非表示.
				Key_SCounter7typeLong[i].changeText( &Inp_SCounterPartsFixationPN[i], NULL );
				Key_SCounter7typeLong[i].changeASCIIText( &Inp_SCounterPartsFixationLimit[i], ( const uchar* )"" );
			}
		}
		else if( TYPE_PartsCntPK == counterDisp_PartsFixation[ num ][ i ].name ) {
			// PKカウンター.
			CounterDisp_PartsFixation* p_PK = getPartsFixation_PK();
			if( NULL != p_PK ) {
				Key_SCounter7typeLong[i].changeText( &Inp_SCounterPartsFixationPN[i], p_PK->pn );										// P/N.
				Key_SCounter7typeLong[i].changeASCIIText( &Inp_SCounterPartsFixationLimit[i], ( const uchar* )p_PK->ss_Limit );			// リミット値.
			} else {
				// 非表示.
				Key_SCounter7typeLong[i].changeText( &Inp_SCounterPartsFixationPN[i], NULL );
				Key_SCounter7typeLong[i].changeASCIIText( &Inp_SCounterPartsFixationLimit[i], ( const uchar* )"" );
			}
		} else if( counterDisp_PartsFixation[ num ][ i ].name == TYPE_PartsCntFNSMiddleFoldKnifeMortor ||
		           counterDisp_PartsFixation[ num ][ i ].name == TYPE_PartsCntFNSMiddleFoldKnifeMortor2 ) {
			//本来は機能仕様書に合わせてテーブルの値を変更することになるが、ZeusMLK対応としては、機能拡張1以降時の表示を変更することとしている。
			if( True == PLBC_FuncVersionCheck::isOK_TypeMLK() ) {
				//Zeus機能拡張1,ZeusMLK基本,ZeusBK基本はこちら.
				Key_SCounter7typeLong[i].changeASCIIText( &Inp_SCounterPartsFixationLimit[i], ( const uchar* )PNLD_PartsCntFNSMiddleFoldKnifeMortorLimit );
			} else {
				//それ以外はこちら.
				Key_SCounter7typeLong[i].changeASCIIText( &Inp_SCounterPartsFixationLimit[i], ( const uchar* )counterDisp_PartsFixation[ num ][ i ].ss_Limit );
			}
			Key_SCounter7typeLong[i].changeText( &Inp_SCounterPartsFixationPN[i], counterDisp_PartsFixation[ num ][ i ].pn );
		} else {
			Key_SCounter7typeLong[i].changeText( &Inp_SCounterPartsFixationPN[i], counterDisp_PartsFixation[ num ][ i ].pn );
			Key_SCounter7typeLong[i].changeASCIIText( &Inp_SCounterPartsFixationLimit[i], ( const uchar* )counterDisp_PartsFixation[ num ][ i ].ss_Limit );
		}

		Key_SCounter7typeLong[i].changeExternalText( &Inp_SCounterPartsFixationCount[i], ( uchar* )sc_SCounterPartsFixation );
		if( counterDisp_PartsFixation[ num ][ i ].text == NULL ) {	// キーの文字列が無い場合は非表示.
			Key_SCounter7typeLong[i].showEnable( False );
		} else {
			Key_SCounter7typeLong[i].showEnable( True );
		}
	}
	Rbt_ServiceCounter7typeLong.select( counterSelectNum );
	PServiceNoFunctionCodeCom::setupGamen( option );	// 表示部品のセットアップ
}

//================================================================================================
// 概要		:サービス・カウンタ・固定パーツカウンタ ：パーツ情報取得 (FNS平とじステープラー).
//================================================================================================
// comment 2015/05/05 【HCLT_Thangachamy】【MinervaSBK】【制御構成変更_No.14 & 制御構成変更_No.15】 Adding Finisher support for FS-536 and FS-537.
// 装着パーツによる切替があるパーツ情報の取得する.
CounterDisp_PartsFixation* PServiceCounterPartsFixation::getPartsFixation_StaplerFront()
{
	CounterDisp_PartsFixation* p_PartsFixation = NULL;
	// フィニッシャーのタイプ.
	switch( PnlComGetPrinterSystem()->getFinisherType() ) {
		case TYPE_FinisherTypeFS533:	// FS-533.
			p_PartsFixation = &counterDisp_PartsFixation_StaplerFront[PNLE_PARTS_FIXATION_FINISHER_533];
			break;
		case TYPE_FinisherTypeFS534:	// FS-534.
		case TYPE_FinisherTypeFS536:	// FS-536.
//comment 2018/10/24 HCLT-Hepzibah [IT6_Eagle] [機器構成変更_No.5] Adding Finisher support for FS-539.
		case TYPE_FinisherTypeFS539:	// FS-539.
			p_PartsFixation = &counterDisp_PartsFixation_StaplerFront[PNLE_PARTS_FIXATION_FINISHER_534];
			break;
		case TYPE_FinisherTypeFS535:	// FS-535.
		case TYPE_FinisherTypeFS537:	// FS-537.
//comment 2018/10/24 HCLT-Hepzibah [IT6_Eagle] [機器構成変更_No.5] Adding Finisher support for FS-540.
		case TYPE_FinisherTypeFS540:	// FS-540.
			p_PartsFixation = &counterDisp_PartsFixation_StaplerFront[PNLE_PARTS_FIXATION_FINISHER_535];
			break;
		default:
			// 上記以外は、NULLを返却.
			break;
	}
	return p_PartsFixation;
}

//================================================================================================
// 概要		:サービス・カウンタ・固定パーツカウンタ ：パーツ情報取得 (PKカウンター).
//================================================================================================
CounterDisp_PartsFixation* PServiceCounterPartsFixation::getPartsFixation_PK()
{
	PNLE_PARTS_FIXATION_PK_TYPE e_PKType = 0;	// パンチキットのタイプ(配列インデックス).
	Bool bl_NotSupport = False;					// 非サポートかどうか.

// Comment 2015/10/07 HCLT_Anusha [MiSBK][制御構成変更_No.1-2] Hole settings of PK-523 is acquired from API for showing the PK Counter values of PK-523.
	// パンチキットのタイプ
	switch( PnlComGetMachineSetting()->getPunchKitType() ) {
		case TYPE_PunchKitType_PK_519:	// PK-519.
			switch( PnlComGetMachineSetting()->getPunchHoleType() ) {
				case TYPE_PunchHoleType_2_3Holes :	e_PKType = PNLE_PARTS_FIXATION_PK_519_2_3HOLE;		break;	// ２／３穴.
				case TYPE_PunchHoleType_2_4Holes :																// ２／４穴.
				case TYPE_PunchHoleType_4Holes   :	e_PKType = PNLE_PARTS_FIXATION_PK_519_2_4HOLE;		break;	// ４穴.
				case TYPE_PunchHoleType_4HolesSWE:	e_PKType = PNLE_PARTS_FIXATION_PK_519_2_4HOLESWE;	break;	// ４穴ＳＷＥ.
				case TYPE_PunchHoleType_2Holes   :	e_PKType = PNLE_PARTS_FIXATION_PK_519_2HOLE;		break;	// ２穴.
				default							 :	bl_NotSupport = True;								break;	// その他.
			}
			break;
		case TYPE_PunchKitType_PK_520:	// PK-520.
			switch( PnlComGetMachineSetting()->getPunchHoleType() ) {
				case TYPE_PunchHoleType_2_3Holes :	e_PKType = PNLE_PARTS_FIXATION_PK_520_2_3HOLE;		break;	// ２／３穴.
				case TYPE_PunchHoleType_2_4Holes :																// ２／４穴.
				case TYPE_PunchHoleType_4Holes   :	e_PKType = PNLE_PARTS_FIXATION_PK_520_2_4HOLE;		break;	// ４穴.
				case TYPE_PunchHoleType_4HolesSWE:	e_PKType = PNLE_PARTS_FIXATION_PK_520_2_4HOLESWE;	break;	// ４穴ＳＷＥ.
				case TYPE_PunchHoleType_2Holes   :	e_PKType = PNLE_PARTS_FIXATION_PK_520_2HOLE;		break;	// ２穴.
				default							 :	bl_NotSupport = True;								break;	// その他.
			}
			break;
		case TYPE_PunchKitType_PK_521:	// PK-521.
			switch( PnlComGetMachineSetting()->getPunchHoleType() ) {
				case TYPE_PunchHoleType_2_3Holes :	e_PKType = PNLE_PARTS_FIXATION_PK_521_2_3HOLE;		break;	// ２／３穴.
				case TYPE_PunchHoleType_2_4Holes :																// ２／４穴.
				case TYPE_PunchHoleType_4Holes   :	e_PKType = PNLE_PARTS_FIXATION_PK_521_2_4HOLE;		break;	// ４穴.
				case TYPE_PunchHoleType_4HolesSWE:	e_PKType = PNLE_PARTS_FIXATION_PK_521_2_4HOLESWE;	break;	// ４穴ＳＷＥ.
				case TYPE_PunchHoleType_2Holes   :	e_PKType = PNLE_PARTS_FIXATION_PK_521_2HOLE;		break;	// ２穴.
				default							 :	bl_NotSupport = True;								break;	// その他.
			}
			break;
		case TYPE_PunchKitType_PK_523:	// PK-523.
			switch( PnlComGetMachineSetting()->getPunchHoleType() ){
				case TYPE_PunchHoleType_2_3Holes :	e_PKType = PNLE_PARTS_FIXATION_PK_523_2_3HOLE;		break;	// ２／３穴.
				case TYPE_PunchHoleType_2_4Holes :																// ２／４穴.
				case TYPE_PunchHoleType_4Holes   :	e_PKType = PNLE_PARTS_FIXATION_PK_523_2_4HOLE;		break;	// ４穴.
				case TYPE_PunchHoleType_4HolesSWE:	e_PKType = PNLE_PARTS_FIXATION_PK_523_2_4HOLESWE;	break;	// ４穴ＳＷＥ.
				case TYPE_PunchHoleType_2Holes   :	e_PKType = PNLE_PARTS_FIXATION_PK_523_2HOLE;		break;	// ２穴.
				default							 :	bl_NotSupport = True;								break;	// その他.
			}
			break;
//comment 2018/10/24 HCLT-Hepzibah [IT6_Eagle] [機器構成変更_No.5] Adding Punch kit support of PK-524/PK-526.
		case TYPE_PunchKitType_PK_524:	// PK-524.
// comment 2020/02/20 【HCLT_Prabakaran】【EagleZ+】【OP_BTS-20493】Removed the PK-524 support as this counter not applicable for EagleZ+ Model.
//			switch( PnlComGetMachineSetting()->getPunchHoleType() ) {
//				case TYPE_PunchHoleType_2_3Holes :	e_PKType = PNLE_PARTS_FIXATION_PK_524_2_3HOLE;		break;	// ２／３穴.
//				case TYPE_PunchHoleType_2_4Holes :																// ２／４穴.
//				case TYPE_PunchHoleType_4Holes   :	e_PKType = PNLE_PARTS_FIXATION_PK_524_2_4HOLE;		break;	// ４穴.
//				case TYPE_PunchHoleType_4HolesSWE:	e_PKType = PNLE_PARTS_FIXATION_PK_524_2_4HOLESWE;	break;	// ４穴ＳＷＥ.
//				case TYPE_PunchHoleType_2Holes   :	e_PKType = PNLE_PARTS_FIXATION_PK_524_2HOLE;		break;	// ２穴.
//				default							 :	bl_NotSupport = True;								break;	// その他.
//			}
			bl_NotSupport = True;
			break;
		case TYPE_PunchKitType_PK_526:	// PK-526.
			switch( PnlComGetMachineSetting()->getPunchHoleType() ){
				case TYPE_PunchHoleType_2_3Holes :	e_PKType = PNLE_PARTS_FIXATION_PK_526_2_3HOLE;		break;	// ２／３穴.
				case TYPE_PunchHoleType_2_4Holes :																// ２／４穴.
				case TYPE_PunchHoleType_4Holes   :	e_PKType = PNLE_PARTS_FIXATION_PK_526_2_4HOLE;		break;	// ４穴.
				case TYPE_PunchHoleType_4HolesSWE:	e_PKType = PNLE_PARTS_FIXATION_PK_526_2_4HOLESWE;	break;	// ４穴ＳＷＥ.
				case TYPE_PunchHoleType_2Holes   :	e_PKType = PNLE_PARTS_FIXATION_PK_526_2HOLE;		break;	// ２穴.
				default							 :	bl_NotSupport = True;								break;	// その他.
			}
			break;
// Comment 2023/6/20 FPT-LONGTH32 [IT6_2.3]【OP_BTS-43982】Fix bug Parts Counter Fixed screen for FS542.
		case TYPE_PunchKitType_PK_527:	// PK-527.
			switch( PnlComGetMachineSetting()->getPunchHoleType() ){
				case TYPE_PunchHoleType_2_3Holes :	e_PKType = PNLE_PARTS_FIXATION_PK_527_2_3HOLE;		break;	// ２／３穴.
				case TYPE_PunchHoleType_2_4Holes :																// ２／４穴.
				case TYPE_PunchHoleType_4Holes   :	e_PKType = PNLE_PARTS_FIXATION_PK_527_2_4HOLE;		break;	// ４穴.
				case TYPE_PunchHoleType_4HolesSWE:	e_PKType = PNLE_PARTS_FIXATION_PK_527_2_4HOLESWE;	break;	// ４穴ＳＷＥ.
				case TYPE_PunchHoleType_2Holes   :	e_PKType = PNLE_PARTS_FIXATION_PK_527_2HOLE;		break;	// ２穴.
				default							 :	bl_NotSupport = True;								break;	// その他.
			}
			break;
		default:
			// 上記以外は、非サポート.
			bl_NotSupport = True;
			break;
	}

	if( True == bl_NotSupport ) {
		// 非サポート時は、NULLを返却.
		return NULL;
	} else {
		// 対応するテーブルポインタを返却.
		return &counterDisp_PartsFixation_PKCounter[e_PKType];
	}
}

