//================================================================================================
// 概要		:82B92090 カウンタ／データ・時系列電源瞬断リブートデータ : 日付表示文字列取得.
// 戻り値	:なし.
// 備考		:
// 変更履歴	:
//================================================================================================
void PCGC_ServiceInstantaneousPowerFailure::getDayTimeDisplay( char* sc_DateTime, const TYPC_Time& c_Date )
{

	if( NULL == sc_DateTime ) {
//2019/06/17 Comment [HCLT_Krishnakumar][EagleH][N Rank] Removed unwanted detailed code.
//// 2015/11/05 【HCLT-Dhivya】 【ZeusS_ZX0】 【制御構成変更_No.76-1】Detail macro is passed in API.
//		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if (NULL != pc_BFW_System){
//    		pc_BFW_System->registDetailCode(PNLD_DetailCode_Service_0x1900660100716301);
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}
	TYPE_SystemType e_SystemType = PnlComGetMachineSetting()->getSystemType();		//現在の仕向け設定.

	//仕向けにより表示文字列を変更する.
	switch( e_SystemType ) {
		case TYPE_SystemType_US:	// ＭＣ仕向け.
		case TYPE_SystemType_JP:	// 日本仕向け.
			sprintf( sc_DateTime,"%02d/%02d  %02d:%02d", c_Date.sc_Month, c_Date.sc_Day, c_Date.sc_Hour, c_Date.sc_Minute );
			break;
		case TYPE_SystemType_EU:	//ＥＵ仕向け.
		default:
			sprintf( sc_DateTime,"%02d/%02d  %02d:%02d", c_Date.sc_Day, c_Date.sc_Month, c_Date.sc_Hour, c_Date.sc_Minute );
			break;
	}
}


//================================================================================================
// 概要		:82B92090 カウンタ／データ・時系列電源瞬断リブートデータ : 表示データ設定.
// 戻り値	:なし.
// 備考		:
// 変更履歴	:
//================================================================================================
void PCGC_ServiceInstantaneousPowerFailure::setDispData()
{
	APIC_LogMomentaryPowerOff* cp_PowerOff = APIC_LogMomentaryPowerOff::newInstance();

	if( NULL == cp_PowerOff ) {
//2019/06/17 Comment [HCLT_Krishnakumar][EagleH][N Rank] Removed unwanted detailed code.
//// 2015/11/05 【HCLT-Dhivya】 【ZeusS_ZX0】 【制御構成変更_No.76-1】Detail macro is passed in API.
//		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if (NULL != pc_BFW_System){
//    		pc_BFW_System->registDetailCode(PNLD_DetailCode_Service_0x1900660100716401);
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}

	short ss_getDataIndex = cp_PowerOff->newestDataPos();	// 時系列電源瞬断データ 最新データ位置 取得(1～10).

	static const char DISP_NUM_SIZE = 3;	// 二桁+NULL終端.
	static const char DISP_DATE_SIZE = 13;	// MM/DD  HH:MM+NULL終端.

	char  sc_Number[ DISP_NUM_SIZE ];		// データ(No)表示文字列.
	char  sc_Date[ DISP_DATE_SIZE ];		// データ(発生日時)表示文字列.

	for( short i = 0; i < PNLD_InstPowerFailureMaxDisp; i++ ) {
		memset( sc_Number, '\0', sizeof( sc_Number ) );
		snprintf( ( char* )sc_Number, sizeof(sc_Number), "%02d", i + 1 );
		Tfd_ServiceInstPowerFailureDispNumber[i].changeExternalText( ( uchar* )sc_Number );		// 表示文字列変更(No.).

		if( PNLD_InstPowerFailureMinIndex > ss_getDataIndex ) {
			ss_getDataIndex = PNLD_InstPowerFailureMaxIndex;
		}
		if( ( PNLD_InstPowerFailureMinIndex <= ss_getDataIndex ) && ( PNLD_InstPowerFailureMaxIndex >= ss_getDataIndex ) ) {
			// インデックスの位置指定は、1～TYPD_MaxLogMomentaryPowerOff(10)まで可能.
			TYPS_LogMomentaryPowerOff s_PowerOffData = cp_PowerOff->getMomentaryPowerOff( ss_getDataIndex );

			if( 0x00 != s_PowerOffData.us_Code ) {
				// データが存在する場合のみ処理を行う.
				TYPC_Time c_Time = s_PowerOffData.c_Date;
				memset( sc_Date, '\0', sizeof( sc_Date ) );

				getDayTimeDisplay( sc_Date, c_Time );	// 発生日時表示用文字列を仕向けに合わせて取得.

				Tfd_ServiceInstPowerFailureDispData[i].changeExternalText( ( uchar* )sc_Date );		// 表示文字列変更(発生日時).
			}
		}
		ss_getDataIndex--;	// インデックスをデクリメント.
	}
}

//================================================================================================
// 概要		：B3B00260_カウンタ／データ／詳細コード履歴(共通処理)  初期設定.
//================================================================================================
void PServiceCounterDetailCodeHistoryCom::startGamen()
{
	PServiceCounterCom::startGamen();
	uc_TotalPage = 1;
	uc_NowPage = 1;
}
//================================================================================================
// 概要		：B3B00260_カウンタ／データ／詳細コード履歴(共通処理)  表示画面のセットアップ.
//================================================================================================
void PServiceCounterDetailCodeHistoryCom::setupGamen( short option )
{
	PServiceCounterCom::setupGamen( option );

	Num_ServiceCounterDetailCodeHistoryTotalPage = ( float )uc_TotalPage;	// ページ数をセット.
	Num_ServiceCounterDetailCodeHistoryNowPage = ( float )uc_NowPage;		// ページ番号をセット.
}
//================================================================================================
// 概要		：B3B00260_カウンタ／データ／詳細コード履歴(共通処理)  ボタン(押された).
//================================================================================================
void PServiceCounterDetailCodeHistoryCom::procButtonOn( uchar option )
{
	switch( option ) {
		case BTNID_ServiceCounterDetailHistoryPageUp: 		// ↑キー押下時.
			uc_NowPage = static_cast<uchar>( uc_NowPage - 1 );
			if( 1 > uc_NowPage ) {							// 1ページ目にて↑キー押下時
				uc_NowPage = uc_TotalPage;
			}
			break;
		case BTNID_ServiceCounterDetailHistoryPageDown: 	// ↓キー押下時.
			uc_NowPage = static_cast<uchar>( uc_NowPage + 1 );
			if( uc_TotalPage < uc_NowPage ) {				// 最終ページにて↓キー押下時
				uc_NowPage = 1;
			}
			break;
		default: break;
	}
	setupGamen();
}
//================================================================================================
// 概要		：B3B00260_カウンタ／データ／詳細コード履歴(共通処理)  画面遷移.
//================================================================================================
void PServiceCounterDetailCodeHistoryCom::procGoToPage( uchar option )
{
	switch( option ) {
		case BTNID_ServiceCounterDetailHistoryTimeSeries: 	// 時系列順キー押下時.
			nextGamen = &gp_ServiceCounterDetailCodeHistoryTimeSeries;
			break;
		case BTNID_ServiceCounterDetailHistoryMonths: 		// 発生月順キー押下時.
			nextGamen = &gp_ServiceCounterDetailCodeHistoryDifferentMonth;
			break;
		case BTNID_ServiceCounterDetailHistoryDetailCode: 	// 詳細コード別キー押下時.
			nextGamen = &gp_ServiceCounterDetailCodeHistoryDifferentCode;
			break;
		default: break;
	}
}
//================================================================================================
// 概要		：B3B00260_カウンタ／データ／詳細コード履歴(時系列順選択時)  初期設定.
//================================================================================================
void PServiceCounterDetailCodeHistoryTimeSeries::startGamen()
{
	PServiceCounterDetailCodeHistoryCom::startGamen();

	// スレッドFA14データ(API)のインスタンスが取得できなかった場合は処理中断.
	if( NULL == PnlComGetLogThreadAssert() ) {
// 2015/11/05 【HCLT-Dhivya】 【ZeusS_ZX0】 【制御構成変更_No.76-1】Detail macro is passed in API.
		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
		if (NULL != pc_BFW_System){
    		pc_BFW_System->registDetailCode(PNLD_DetailCode_Service_0x1900650100716501);
		}
		return;
	}

	for( uchar uc_i = 0; TYPD_MaxLogThreadAssert > uc_i; uc_i++ ) {
		st_LogThreadAssert[uc_i].us_Code = 0;
		st_LogThreadAssert[uc_i].ul_TotalCounter = 0;
		st_LogThreadAssert[uc_i].ul_ScanCounter = 0;
		st_LogThreadAssert[uc_i].c_Date.ss_Year = 0;
		st_LogThreadAssert[uc_i].c_Date.sc_Month = 0;
		st_LogThreadAssert[uc_i].c_Date.sc_Day = 0;
		st_LogThreadAssert[uc_i].c_Date.sc_Hour = 0;
		st_LogThreadAssert[uc_i].c_Date.sc_Minute = 0;
		st_LogThreadAssert[uc_i].c_Date.sc_Second = 0;
	}

	// 発生日時順にソートされたFA14詳細コード履歴を取得する.
	PnlComGetLogThreadAssert()->lock();
	PnlComGetLogThreadAssert()->getLogThreadAssertSortTime( st_LogThreadAssert );
	PnlComGetLogThreadAssert()->unlock();

	// FA14詳細コード履歴件数を算出する.
	uchar uc_DetailCodeCount = 0;
	//for( uchar uc_DetailCodeCount = 0 ; TYPD_MaxLogThreadAssert > uc_DetailCodeCount ; uc_DetailCodeCount++ ) {
	for( uc_DetailCodeCount = 0 ; TYPD_MaxLogThreadAssert > uc_DetailCodeCount ; uc_DetailCodeCount++ ) {
		if( 0 == st_LogThreadAssert[uc_DetailCodeCount].us_Code ) { break; }		// コードが0の場合、件数取得終了.
	}

	// FA14詳細コード履歴件数よりページ数を算出する.
	if( 0 == uc_DetailCodeCount ) {
		setTotalPage( 1 );
	} else {
		setTotalPage( static_cast<uchar>( ( uc_DetailCodeCount + ( PNLD_MaxRowDisplayed - 1 ) ) / PNLD_MaxRowDisplayed ) );
	}

	// FA14詳細コード履歴件数を保持する.
	setDetailCodeCount( uc_DetailCodeCount );
}
//================================================================================================
// 概要		：B3B00260_カウンタ／データ／詳細コード履歴(時系列順選択時)  表示画面のセットアップ.
//================================================================================================
void PServiceCounterDetailCodeHistoryTimeSeries::setupGamen( short option )
{
	char sc_Code[6+PCGD_EndCode];				// コード(0x????).
	char sc_TotalCounter[8+PCGD_EndCode];		// トータルカウンタ(最大99999999).
	char sc_ScanCounter[8+PCGD_EndCode];		// ADF通紙枚数(最大99999999).
	char sc_Date[16+PCGD_EndCode];				// 発生日時(YYYY/MM/DD hh:mm).
	uchar uc_DetailCodeHistoryIndex = 0;		// FA14詳細履歴データのIndex番号.

	memset( sc_Code, 0x00, sizeof( sc_Code ) );
	memset( sc_TotalCounter, 0x00, sizeof( sc_TotalCounter ) );
	memset( sc_ScanCounter, 0x00, sizeof( sc_ScanCounter ) );
	memset( sc_Date, 0x00, sizeof( sc_Date ) );

	PServiceCounterDetailCodeHistoryCom::setupGamen( option );
	Rbt_ServiceCounterDetailHistory.select( BTNID_ServiceCounterDetailHistoryTimeSeries );

	for( uchar uc_DisplayIndex  = 0 ; PNLD_MaxRowDisplayed > uc_DisplayIndex ; uc_DisplayIndex++ ) {
		uc_DetailCodeHistoryIndex = static_cast<uchar>( ( getNowPage() -1 )*PNLD_MaxRowDisplayed + uc_DisplayIndex );	// ページ番号と行番号より表示データのIndexを算出
		if( getDetailCodeCount() > uc_DetailCodeHistoryIndex )	// 表示データのIndex番号が総件数より少ない場合、表示処理を行う.
		{
			// データをバッファにコピー.
			snprintf( ( char* )sc_Code, sizeof(sc_Code), "0x%04X",st_LogThreadAssert[uc_DetailCodeHistoryIndex].us_Code );					// コード.
			snprintf( ( char* )sc_TotalCounter, sizeof(sc_TotalCounter), "%08d",st_LogThreadAssert[uc_DetailCodeHistoryIndex].ul_TotalCounter );	// トータルカウンタ.
			snprintf( ( char* )sc_ScanCounter, sizeof(sc_ScanCounter), "%08d",st_LogThreadAssert[uc_DetailCodeHistoryIndex].ul_ScanCounter );		// ADF通紙枚数.
			switch( PnlComGetDestination() ) {		// 仕向けによって発生日時の表示を切り替える.
				case TYPE_SystemType_JP : 	// 日本仕向け時.
					snprintf( ( char* )sc_Date, sizeof( sc_Date ), "%04d/%02d/%02d %02d:%02d",														// 発生日時.
					          st_LogThreadAssert[uc_DetailCodeHistoryIndex].c_Date.ss_Year, st_LogThreadAssert[uc_DetailCodeHistoryIndex].c_Date.sc_Month, st_LogThreadAssert[uc_DetailCodeHistoryIndex].c_Date.sc_Day,
					          st_LogThreadAssert[uc_DetailCodeHistoryIndex].c_Date.sc_Hour, st_LogThreadAssert[uc_DetailCodeHistoryIndex].c_Date.sc_Minute );
					break;
				case TYPE_SystemType_US :	// US仕向け時.
					snprintf( ( char* )sc_Date, sizeof( sc_Date ), "%02d/%02d/%04d %02d:%02d",														// 発生日時.
					          st_LogThreadAssert[uc_DetailCodeHistoryIndex].c_Date.sc_Month, st_LogThreadAssert[uc_DetailCodeHistoryIndex].c_Date.sc_Day, st_LogThreadAssert[uc_DetailCodeHistoryIndex].c_Date.ss_Year,
					          st_LogThreadAssert[uc_DetailCodeHistoryIndex].c_Date.sc_Hour, st_LogThreadAssert[uc_DetailCodeHistoryIndex].c_Date.sc_Minute );
					break;
				case TYPE_SystemType_EU : 	// 欧州仕向け時.
					snprintf( ( char* )sc_Date, sizeof( sc_Date ), "%02d/%02d/%04d %02d:%02d",														// 発生日時.
					          st_LogThreadAssert[uc_DetailCodeHistoryIndex].c_Date.sc_Day, st_LogThreadAssert[uc_DetailCodeHistoryIndex].c_Date.sc_Month, st_LogThreadAssert[uc_DetailCodeHistoryIndex].c_Date.ss_Year,
					          st_LogThreadAssert[uc_DetailCodeHistoryIndex].c_Date.sc_Hour, st_LogThreadAssert[uc_DetailCodeHistoryIndex].c_Date.sc_Minute );
					break;
				default :
					LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
					break;
			}

			// 表示パーツに設定値を反映.
			Tfd_ServiceCounterDetailHistoryCode[uc_DisplayIndex].changeExternalText( ( uchar* )sc_Code );						// コード.
			Tfd_ServiceCounterDetailHistoryTotalCounter[uc_DisplayIndex].changeExternalText( ( uchar* )sc_TotalCounter );		// トータルカウンタ.
			Tfd_ServiceCounterDetailHistoryADFPaperPages[uc_DisplayIndex].changeExternalText( ( uchar* )sc_ScanCounter );		// ADF通紙枚数.
			Tfd_ServiceCounterDetailHistoryOccur[uc_DisplayIndex].changeExternalText( ( uchar* )sc_Date );					// 発生日時.

			// 詳細コード履歴を表示.
			Tfd_ServiceCounterDetailHistoryCode[uc_DisplayIndex].showEnable( True );
			Tfd_ServiceCounterDetailHistoryTotalCounter[uc_DisplayIndex].showEnable( True );
			Tfd_ServiceCounterDetailHistoryADFPaperPages[uc_DisplayIndex].showEnable( True );
			Tfd_ServiceCounterDetailHistoryOccur[uc_DisplayIndex].showEnable( True );

		} else {
			// 詳細コード履歴を非表示.
			Tfd_ServiceCounterDetailHistoryCode[uc_DisplayIndex].showEnable( False );
			Tfd_ServiceCounterDetailHistoryTotalCounter[uc_DisplayIndex].showEnable( False );
			Tfd_ServiceCounterDetailHistoryADFPaperPages[uc_DisplayIndex].showEnable( False );
			Tfd_ServiceCounterDetailHistoryOccur[uc_DisplayIndex].showEnable( False );
		}
	}
//2018/04/18 HCLT_Monisha for SparrowSFP [制御構成変更_No.206] removing copy, scan fax related items starts
 	if ( IsSFP() ) {
		Txt_ServiceCounterDetailHistoryADFPaperPages.showEnable(False);
//comment 2019/03/14 HCLT-Basker [IT6MR2][AR1074378] Enable Datetime details in Detail code history for SparrowSFP.
//		Txt_ServiceCounterDetailHistoryOccur.showEnable(False);
		Grp_ServiceCounterDetailHistoryADFPaperPages.showEnable(False);
//		Grp_ServiceCounterDetailHistoryOccur.showEnable(False);
    } else {
		Txt_ServiceCounterDetailHistoryADFPaperPages.showEnable(True);
//comment 2019/03/14 HCLT-Basker [IT6MR2][AR1074378] Enable Datetime details in Detail code history for SparrowSFP.
//		Txt_ServiceCounterDetailHistoryOccur.showEnable(True);
		Grp_ServiceCounterDetailHistoryADFPaperPages.showEnable(True);
//		Grp_ServiceCounterDetailHistoryOccur.showEnable(True);
    }
//2018/04/18 HCLT_Monisha for SparrowSFP [制御構成変更_No.206] removing copy, scan fax related items ends
}
//================================================================================================
// 概要		：B3B00260_カウンタ／データ／詳細コード履歴(発生月別選択時)  初期設定.
//================================================================================================
void PServiceCounterDetailCodeHistoryDifferentMonth::startGamen()
{
	PServiceCounterDetailCodeHistoryCom::startGamen();

	// スレッドFA14データ(API)のインスタンスが取得できなかった場合は処理中断.
	if( NULL == PnlComGetLogThreadAssert() ) {
// 2015/11/05 【HCLT-Dhivya】 【ZeusS_ZX0】 【制御構成変更_No.76-1】Detail macro is passed in API.
		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
		if (NULL != pc_BFW_System){
    		pc_BFW_System->registDetailCode(PNLD_DetailCode_Service_0x1900650100716601);
		}		
		return;
	}

	for( uchar uc_i = 0; TYPD_MaxLogThreadAssert > uc_i; uc_i++ ) {
		st_LogThreadAssertFreqPerTime[uc_i].ss_Year = 0;
		st_LogThreadAssertFreqPerTime[uc_i].sc_Month = 0;
		st_LogThreadAssertFreqPerTime[uc_i].sc_Day = 0;
		st_LogThreadAssertFreqPerTime[uc_i].uc_Freq = 0;
	}

	// 発生日時順にソートされたFA14詳細コード履歴を取得する.
	PnlComGetLogThreadAssert()->lock();
	PnlComGetLogThreadAssert()->getLogThreadAssertFreqPerMonth( st_LogThreadAssertFreqPerTime );
	PnlComGetLogThreadAssert()->unlock();

	// FA14詳細コード履歴件数を算出する.
	uchar uc_DetailCodeCount = 0;
	//for( uchar uc_DetailCodeCount = 0 ; TYPD_MaxLogThreadAssert > uc_DetailCodeCount ; uc_DetailCodeCount++ ) {
	for( uc_DetailCodeCount = 0 ; TYPD_MaxLogThreadAssert > uc_DetailCodeCount ; uc_DetailCodeCount++ ) {
		if( 0 == st_LogThreadAssertFreqPerTime[uc_DetailCodeCount].uc_Freq ) { break; }		// コードが0の場合、件数取得終了.
	}

	// FA14詳細コード履歴件数よりページ数を算出する.
	if( 0 == uc_DetailCodeCount ) {
		setTotalPage( 1 );
	} else {
		setTotalPage( static_cast<uchar>( ( uc_DetailCodeCount + ( PNLD_MaxRowDisplayed - 1 ) ) / PNLD_MaxRowDisplayed ) );
	}

	// FA14詳細コード履歴件数を保持する.
	setDetailCodeCount( uc_DetailCodeCount );
}
//================================================================================================
// 概要		：B3B00260_カウンタ／データ／詳細コード履歴(発生月別選択時)  表示画面のセットアップ.
//================================================================================================
void PServiceCounterDetailCodeHistoryDifferentMonth::setupGamen( short option )
{
	char sc_YearMonth[7+PCGD_EndCode];					// 年月(YYYY/MM).
	char sc_NumberOfTimes[8+PCGD_EndCode];				// 発生回数(最大99999999).
	uchar uc_DetailCodeHistoryIndex = 0;				// FA14詳細履歴データのIndex番号.

	memset( sc_YearMonth, 0x00, sizeof( sc_YearMonth ) );
	memset( sc_NumberOfTimes, 0x00, sizeof( sc_NumberOfTimes ) );

	PServiceCounterDetailCodeHistoryCom::setupGamen( option );
	Rbt_ServiceCounterDetailHistory.select( BTNID_ServiceCounterDetailHistoryMonths );

	for( uchar uc_DisplayIndex = 0 ; PNLD_MaxRowDisplayed > uc_DisplayIndex ; uc_DisplayIndex++ ) {
		uc_DetailCodeHistoryIndex = static_cast<uchar>( ( getNowPage() -1 )*PNLD_MaxRowDisplayed + uc_DisplayIndex );	// ページ番号と行番号より表示データのIndexを算出
		if( getDetailCodeCount() > uc_DetailCodeHistoryIndex )	// 表示データのIndex番号が総件数より少ない場合、表示処理を行う.
		{
			// データをバッファにコピー.
			switch( PnlComGetDestination() ) {		// 仕向けによって年月の表示を切り替える.
				case TYPE_SystemType_JP : 	// 日本仕向け時.
					snprintf( ( char* )sc_YearMonth, sizeof( sc_YearMonth ), "%04d/%02d",																	// 年月.
					          st_LogThreadAssertFreqPerTime[uc_DetailCodeHistoryIndex].ss_Year, st_LogThreadAssertFreqPerTime[uc_DetailCodeHistoryIndex].sc_Month );
					break;
				case TYPE_SystemType_US :	// US仕向け時.
				case TYPE_SystemType_EU :	// 欧州仕向け時.
					snprintf( ( char* )sc_YearMonth, sizeof( sc_YearMonth ), "%02d/%04d",																	// 年月.
					          st_LogThreadAssertFreqPerTime[uc_DetailCodeHistoryIndex].sc_Month, st_LogThreadAssertFreqPerTime[uc_DetailCodeHistoryIndex].ss_Year );
					break;
				default :
					LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
					break;
			}
			snprintf( ( char* )sc_NumberOfTimes, sizeof(sc_NumberOfTimes), "%08d",st_LogThreadAssertFreqPerTime[uc_DetailCodeHistoryIndex].uc_Freq );	// 発生回数.

			// 表示パーツに反映.
			Tfd_ServiceCounterDetailHistoryYearMonth[uc_DisplayIndex].changeExternalText( ( uchar* )sc_YearMonth );			// 年月.
			Tfd_ServiceCounterDetailHistoryNumberOfTimes[uc_DisplayIndex].changeExternalText( ( uchar* )sc_NumberOfTimes );	// 発生回数.

			// 詳細コード履歴を表示.
			Tfd_ServiceCounterDetailHistoryYearMonth[uc_DisplayIndex].showEnable( True );
			Tfd_ServiceCounterDetailHistoryNumberOfTimes[uc_DisplayIndex].showEnable( True );

		} else {
			// 詳細コード履歴を非表示.
			Tfd_ServiceCounterDetailHistoryYearMonth[uc_DisplayIndex].showEnable( False );
			Tfd_ServiceCounterDetailHistoryNumberOfTimes[uc_DisplayIndex].showEnable( False );
		}
	}

}
