struct PNLS_ServiceCounterSeparate {
	TYPE_TemporaryRescueUnit	e_TemporaryRescueUnit;	// 切り離し種別.
	TEXT_ID						textID;					// 表示文字列.
	PSelectButtonAdd* 			key;					// キー
	PSinglePartsText*  			text;					// テキスト
};
PNLS_ServiceCounterSeparate st_ServiceCounterSeparate[] = {
	{ TYPE_TemporaryRescueUnit_DeleteOfHddBackUpData, s_ITMServiceManagementDevIsolation, &Key_SCounter8typeL1, &Ktx_SCounter8typeL1	},	// ８個（分）の左１位置・キー.
};
/*================================================================================================
［機能設定］	サービス・カウンタ・トラブル : 変数などの初期化
================================================================================================*/
void PServiceCounterSeparate::init_value()
{
	PServiceCounterCom::init_value();
	// カウンタクリア対象を未選択にする
	clear_counter_name = TYPE_TemporaryRescueUnitNone;
}
//================================================================================================
// 概要		:サービス・カウンタ・切り離しカウンタ : 初期設定.
//================================================================================================
void PServiceCounterSeparate::startGamen()
{
	PServiceCounterCom::startGamen();	// カウンタ共通初期化.
	init_value();

	APIC_TemporaryRescueUnitCnt* pc_TemporaryRescueUnitCnt = APIC_TemporaryRescueUnitCnt::newInstance();
	if( NULL != pc_TemporaryRescueUnitCnt ) {
		// カウンタデータのバックアップ.
		for( register uchar i = 0; i < ( sizeof( st_ServiceCounterSeparate ) / sizeof( PNLS_ServiceCounterSeparate ) ); i++ ) {
			counter_back[i] = pc_TemporaryRescueUnitCnt->get( st_ServiceCounterSeparate[i].e_TemporaryRescueUnit );
		}
	}
}
//================================================================================================
// 概要		:サービス・カウンタ・切り離しカウンタ : 表示画面のセットアップ.
//================================================================================================
void PServiceCounterSeparate::setupGamen( short option )
{
	PServiceCounterCom::setupGamen();	// カウンタ共通初期化.

	for( register uchar i = 0; i < ( sizeof( st_ServiceCounterSeparate ) / sizeof( PNLS_ServiceCounterSeparate ) ); i++ ) {
		// カウンタ名の設定.
		st_ServiceCounterSeparate[i].text->changeText( st_ServiceCounterSeparate[i].textID );
		// カウンタ数値の設定.
		if( clear_counter_name == st_ServiceCounterSeparate[i].e_TemporaryRescueUnit ) {
			// procClear実行後はクリアされた値を入れておく(この時点ではクリアされていない).
			*( st_ServiceCounterSeparate[i].key ) = static_cast<float>( clear_counter_num );
		} else {
			// クリア選択されていない状態の場合はAPIから取得したデータを入れておく.
			*( st_ServiceCounterSeparate[i].key ) = static_cast<float>( counter_back[i] );
		}
	}
	// キー選択状態を反映.
	Rbt_SelectServiceCounterSeparate.select( counterSelectNum );
}
/*================================================================================================
// 概要		:サービス・カウンタ・切り離しカウンタ : 割り込みモード.
================================================================================================*/
void PServiceCounterSeparate::procIntMode( uchar option )
{
	if( -1 == counterSelectNum ) {
		// 未選択状態なら何もせずリターン.
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}
	// カウンタクリア対象を未選択にする.
	clear_counter_name = TYPE_TemporaryRescueUnitNone;
	// ゼロクリアされたカウンタをクリア前の値に復帰する
	clear_counter_num = counter_back[counterSelectNum];
	setupGamen();				// 表示部品のセットアップ
}
// comment 2017/01/25 SCD2-2G Sky松下 [IT5_3.4][1012690] IDキーへの割り込み押下処理の割り当て.
//================================================================================================
// 概要		:サービス・カウンタ・切り離しカウンタ : IDキー.
// 戻り値	:なし.
// 備考		:
//================================================================================================
void PServiceCounterSeparate::procIDInput( uchar option )
{
	procIntMode( option );							// 割り込みキー押下処理をコール.
}
/*================================================================================================
［機能設定］	サービス・カウンタ・切り離しカウンタ : クリア
================================================================================================*/
void PServiceCounterSeparate::procClear( uchar option )
{
	if( -1 == counterSelectNum ) {
		// 未選択状態なら何もせずリターン.
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}
	// カウンタクリア対象を設定する.
	clear_counter_name = st_ServiceCounterSeparate[counterSelectNum].e_TemporaryRescueUnit;
	// 選択されたカウンタを０クリアする.
	clear_counter_num = 0;
	setupGamen();				// 表示部品のセットアップ
}
/*================================================================================================
［機能設定］	サービス・カウンタ・切り離しカウンタ : トラブルカウンタ書き換え通知
================================================================================================*/
void PServiceCounterSeparate::setClearCounter()
{
	if( TYPE_TemporaryRescueUnitNone != clear_counter_name ) {
		APIC_TemporaryRescueUnitCnt* pc_TemporaryRescueUnitCnt = APIC_TemporaryRescueUnitCnt::newInstance();
		if( NULL != pc_TemporaryRescueUnitCnt ) {
			pc_TemporaryRescueUnitCnt->clear( st_ServiceCounterSeparate[counterSelectNum].e_TemporaryRescueUnit );	// カウンタ値のクリア実行
			// バックアップ領域も0に変更.
			counter_back[ counterSelectNum ] = 0;
		}
	}
	// カウンタクリア対象を未選択にする
	clear_counter_name = TYPE_TemporaryRescueUnitNone;
}

