//Comment 2018/01/29 HCLT-Muneendra 機器構成変更No.51[WP 1547] Function Modification for Replace the "AUTO" Text Set "ON/OFF" will be displayed under corrent control coloum. 
/**
* @brief  : update 2nd tranfer and current control data.
* @note   : None.
* @param  : [in] PNLS_InpFieldCurrentCtlType* , ushort
* @return : None.
*/
void PServiceAdjustDataCatalogueComForCLCD::setupFunc( PNLS_InpFieldCurrentCtlType* pst_TblData, ushort us_TblSize )
{
	if ( NULL != pst_TblData ) {
		for( ushort us_Cnt = 0; us_Cnt < us_TblSize; us_Cnt++ ) {
			*pst_TblData[ us_Cnt ].pc_Number = ( float )( getPrinterIndiInSystem( pst_TblData[ us_Cnt ].ss_PrinterAdjust ) );
			if( getPrinterIndiInSystem( pst_TblData[ us_Cnt ].ss_PrinterAdjustAuto ) ) {
				if ( NULL != pst_TblData[ us_Cnt ]. pc_Text){
					pst_TblData[ us_Cnt ]. pc_Text->changeText( s_OFFService );
				}
			} else {
				if ( NULL != pst_TblData[ us_Cnt ]. pc_Text){
					pst_TblData[ us_Cnt ]. pc_Text->changeText( s_ONService );
				}
			}
		}
	}
}

