//================================================================================================.
void PServiceDSCBusCheck::startGamen()
{
	PServiceMemoryHDDAdjustCom::startGamen();	// メモリ/HDD調整共通初期設定.
	uc_pageNum = 1; // 1ページ目.

	bl_isIRtoDSCSelected = False;			// スキャナ→DSCボタンを非選択中にする
	bl_isIRtoDSCComplete = False;			// スキャナ→DSC未完了
	bl_isIRtoDSCSelectedBack = False;		// スキャナ→DSCボタン(裏面)を非選択中にする.
	bl_isIRtoDSCCompleteBack = False;		// スキャナ→DSC(裏面)未完了.
}
//================================================================================================.
// 概要		:サービス・マシン状態＆確認・メモリ/ＨＤＤ調整・DSCバスチェック : ボタン(押された).
// 戻り値	:なし.
// 作成者	:.
// レビュー	:.
//================================================================================================.
void PServiceDSCBusCheck::procButtonOn( uchar option )
{
	switch( option ) {
		case BTNID_ServiceDSCBusCheckFront:	bl_isIRtoDSCSelected = ( bl_isIRtoDSCSelected ? False : True );	break;			// スキャナ→DSCキーの選択状態を反転.
		case BTNID_ServiceDSCBusCheckBack:	bl_isIRtoDSCSelectedBack = ( bl_isIRtoDSCSelectedBack ? False : True );	break;	// スキャナ→DSCキー(裏面)の選択状態を反転.
		default:	break;
	}

	setupGamen();	// 表示画面のセットアップ.
}

//================================================================================================.
// 概要		:サービス・マシン状態＆確認・メモリ/ＨＤＤ調整・DSCバスチェック : スタートボタン押下.
// 戻り値	:なし.
// 作成者	:.
// レビュー	:.
//================================================================================================.
void PServiceDSCBusCheck::procStart( uchar option )
{
	ushort nowFuncCode = TYPD_FNC_CPSToDSCBusCheck; 		// ファンクションコード.
	if( False == bl_isIRtoDSCSelected && True == bl_isIRtoDSCSelectedBack ) {	// 表面は未選択、裏面は選択の場合.
		nowFuncCode =TYPD_FNC_EDH2Side_BusCheckDSCBack; 		// ファンクションコード 裏面のファンクションをセットする.
	}
	ushort us_nowFunction  = static_cast<ushort>( toFunctionCode( nowFuncCode ) ); // ファンクションコードを取得.
	ushort us_nowParameter = static_cast<ushort>( toParameter( nowFuncCode ) );	// ファンクションパラメータを取得.

	// ファンクションのスタート
	if( False == printStartDisable() ) {		// スタートキー緑.
		if( False == pc_SystemControl.startFunction( us_nowFunction, us_nowParameter ) ) {	//サービスファンクション実行開始.
			// 既に他のファンクションが実行されていた時の処理.
			return;
		}

		procTimerWakeUp( 0 );			// ファンクション終了ﾁｪｯｸ.
		bl_NoAcceptBtnFlag = True;		// ボタン受付不可にする.
	}
	else {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );		// 拒否音.
	}

	setupGamen();	// 表示画面のセットアップ.
}

//================================================================================================.
// 概要		:サービス・マシン状態＆確認・メモリ/ＨＤＤ調整・DSCバスチェック : ファンクション終了.
// 戻り値	:なし.
// 作成者	:.
// レビュー	:.
//================================================================================================.
void PServiceDSCBusCheck::procFunctionEnd( uchar option )
{
	if( True == bl_isIRtoDSCSelected && True == bl_isIRtoDSCSelectedBack ) {	// 表、裏両方選択時の表が完了(表を必ず先にやるようにしている).
		bl_isIRtoDSCSelected = False;
		bl_isIRtoDSCComplete = True;
		pc_SystemControl.startFunction( static_cast<ushort>( toFunctionCode( TYPD_FNC_EDH2Side_BusCheckDSCBack ) ), static_cast<ushort>( toParameter( TYPD_FNC_EDH2Side_BusCheckDSCBack ) ) );	//サービスファンクション実行開始.
		procTimerWakeUp( 0 );			// ファンクション終了ﾁｪｯｸ.
	} else if( True == bl_isIRtoDSCSelected ) {								// 表面のみ選択時の完了.
		bl_isIRtoDSCSelected = False;
		bl_isIRtoDSCComplete = True;
	} else if( True == bl_isIRtoDSCSelectedBack ) {							// 裏面のみ選択時の完了.
		bl_isIRtoDSCSelectedBack = False;
		bl_isIRtoDSCCompleteBack = True;
	}
	if( bl_isIRtoDSCSelected == False && bl_isIRtoDSCSelectedBack == False ) {
		bl_NoAcceptBtnFlag = False;	// ボタン受付許可にする.
	}
	setupGamen();	// 表示画面のセットアップ.
}
//================================================================================================.
// 概要		:サービス・マシン状態＆確認・メモリ/ＨＤＤ調整・DSCバスチェック : 表示部品のセットアップ.
// 戻り値	:なし.
// 作成者	:.
// レビュー	:.
//================================================================================================.
void PServiceDSCBusCheck::setupGamen( short option )
{
	PServiceMemoryHDDAdjustCom::setupGamen( option );

	Txt_ServiceMemoryHddCounterPage.changeText( s_SvcsCounterPage1_2 ) ;	// 表示ページを更新(1/2)

	Rbt_ServiceMemoryHDDAdjust.select( PNLD_DSCBusCheckSelect );	// DSCバスチェック選択.

	Key_SIRToDSC.select( bl_isIRtoDSCSelected );	// スキャナ→DSCキー選択状態.

	if( True == bl_isIRtoDSCComplete ) {
		switch( PnlComGetScannerServiceInfo()->getScannerInfo( TYPE_ScannerInfoCPSToDSCBusCheckResult ) ) {
			case TYPE_CPSToDSCCheckResult_OK:
				Txt_SIRToDSC_OKNG.changeText( s_ServiceMemoryCheck_OK );
				Txt_SIRToDSC_OKNG.showEnable( True );
				Txt_SIRToDSC_NG2.showEnable( False );
				break;

			case TYPE_CPSToDSCCheckResult_NG1:
				Txt_SIRToDSC_OKNG.changeText( s_EXPNG1X3Y1 );
				Txt_SIRToDSC_OKNG.showEnable( True );
				Txt_SIRToDSC_NG2.showEnable( False );
				break;

			case TYPE_CPSToDSCCheckResult_NG2:
				Txt_SIRToDSC_OKNG.showEnable( False );
				Txt_SIRToDSC_NG2.showEnable( True );
				break;

			default:
				bl_isIRtoDSCComplete = False;
				LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
				break;
		}
	}
	else {
		Txt_SIRToDSC_OKNG.showEnable( False );
		Txt_SIRToDSC_NG2.showEnable( False );
	}
	Key_SIRToDSCBack.select( bl_isIRtoDSCSelectedBack );	// スキャナ→DSCキー(裏面)選択状態.

	if( True == bl_isIRtoDSCCompleteBack ) {
		switch( PnlComGetScannerServiceInfo()->getScannerInfo( TYPE_ScannerInfoCPSToDSCBusCheckResultBack ) ) {
			case TYPE_CPSToDSCCheckResult_OK:
				Txt_SIRToDSCBack_OKNG.changeText( s_ServiceMemoryCheck_OK );
				Txt_SIRToDSCBack_OKNG.showEnable( True );
				Txt_SIRToDSCBack_NG2.showEnable( False );
				break;

			case TYPE_CPSToDSCCheckResult_NG1:
				Txt_SIRToDSCBack_OKNG.changeText( s_EXPNG1X3Y1 );
				Txt_SIRToDSCBack_OKNG.showEnable( True );
				Txt_SIRToDSCBack_NG2.showEnable( False );
				break;

			case TYPE_CPSToDSCCheckResult_NG2:
				Txt_SIRToDSCBack_OKNG.showEnable( False );
				Txt_SIRToDSCBack_NG2.showEnable( True );
				break;

			default:
				bl_isIRtoDSCComplete = False;
				LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
				break;
		}
	}
	else {
		Txt_SIRToDSCBack_OKNG.showEnable( False );
		Txt_SIRToDSCBack_NG2.showEnable( False );
	}
	// DS装着状態に応じて表示内容を設定する.
	Bool bl_DSstat = PnlComGetSystemInfo()->isDSModel();	// DS装着状態.
	if( False == bl_DSstat ) {	// DS非装着時はサブタイトルを「DSCﾊﾞｽﾁｪｯｸ」に変更.
		Txt_TitleServiceDSCBusCheck.changeText( s_KEYDSCBusCheck_1 );
	}
	else {	// サブタイトル「DSCﾊﾞｽﾁｪｯｸ / 表面」.
		Txt_TitleServiceDSCBusCheck.changeText( s_ITMServiceMemoryBusCheckFront );
	}
	Gra_ropHLineServiceMemoryBassCheck.showEnable( bl_DSstat );	// 境界線（横線）.
	Txt_TitleServiceDSCBusCheckBack.showEnable( bl_DSstat );	// サブタイトル（裏面用）.
	Gra_ServiceMemoryBassCheck2.showEnable( bl_DSstat );		// 裏面結果エリア(枠).
	Key_SIRToDSCBack.showEnable( bl_DSstat );					//  スキャナ→DSCキー(裏面用).
	Txt_ServiceMemoryBassCheckArrow2.showEnable( bl_DSstat );	// →表示(裏面用).
	Txt_ServiceMemoryBassCheckResult2.showEnable( bl_DSstat );	// 結果(裏面用).

	if( ( False == bl_isIRtoDSCSelected && False == bl_isIRtoDSCSelectedBack ) 					// 表面、裏面両方キーが選択されていない or.
	    || ( False == PnlComGetSystemInfo()->isDSModel() && True == bl_isIRtoDSCSelectedBack )	// DS非装着なのに裏面を選択時 or.
	    || ( False == ppc_SystemInfo->getDSC1Exist() && True == bl_isIRtoDSCSelected )			// DSC1基板設定が非装着なのに表面を選択時 or.
	    || ( False == ppc_SystemInfo->getDSC2Exist() && True == bl_isIRtoDSCSelectedBack )		// DSC2基板設定が非装着なのに裏面を選択時 or.
	    || PnlComGetScannerWarning()->isOccurFatal() || True == bl_NoAcceptBtnFlag ) {			// チェック実行時orFatal発生時.
		printLEDControl( False );	// スタートＬＥＤ赤.
	} else {
		// IRがFatalではなく、スキャナ→DSCキー選択されているなら.
		printLEDControl( True );	// スタートＬＥＤ緑.
	}
// Comment 2017/12/01 [HCLT-Gomathy] [IT6_Eagle] 【制御構成変更_No.6】 Removed the machine type condition since it is applicable for all the Eagle machine type.
// Comment 2017/10/10 【IT6_Eagle】【HCL_Satheesh】 【制御構成変更_No.1】 Compiler Switch Activity.
//#if defined( DEF_EaglePanel_Low )
// TBD - EagleBK
//	TYPE_MachineType e_MachineType = PnlComGetSystemInfo()->getMachineType();
//	if( ( TYPE_MachineTypeZeusS1 == e_MachineType )		// In case of ZeusS1.
//	||( TYPE_MachineTypeZeusS2	 == e_MachineType )		// In case of ZeusS2.
//	||( TYPE_MachineTypeZeusS2_5 == e_MachineType )		// In case of ZeusS2_5.
//	||( TYPE_MachineTypeZeusSBK1 == e_MachineType )		// In case of ZeusSBK1st 1.
//	|| ( TYPE_MachineTypeZeusSBK2 == e_MachineType )		// In case of ZeusSBK1st 2. 
//	|| ( TYPE_MachineTypeZeusSBK2nd2 == e_MachineType )
//	|| ( TYPE_MachineTypeZeusSBK2nd1 == e_MachineType ) ) {
//		Key_GoToJPEGCheck.showEnable( False );
//	}
//#endif //DEF_EaglePanel_Low
}

//////////////////////////////////////////////////////////////
// 概要 : 50C00070_ADF調整　／混載原稿サイズ調整(50C00070) : OKキー.
//////////////////////////////////////////////////////////////
void PServiceMixedOriginalSize::procOk( uchar option )
{
	nextGamen = &gp_ServiceADFCheckMenu;	// ADF調整・モードメニュー.
}
//////////////////////////////////////////////////////////////
// 概要 : 50C00070_ADF調整　／混載原稿サイズ調整(50C00070) : 画面開始処理.
//////////////////////////////////////////////////////////////
void PServiceMixedOriginalSize::startGamen()
{
	PServiceFunctionEnableStopCom::startGamen();	// 親クラスの処理を呼ぶ.
	bl_showResult = False;	// 調整結果非表示.
	Txt_ADFAdjustResult.changeText( s_ServiceResultBlank );	// 実行結果表示をブランクに変更.
	setFunctionCode( TYPD_FNC_EDH_DetectFDSizeLong );		// コードセット・ＡＤＦ FD長検出調整モード(通紙FD長 大).
}
//////////////////////////////////////////////////////////////
// 概要 : 50C00070_ADF調整　／混載原稿サイズ調整(50C00070) : スタートキー.
//////////////////////////////////////////////////////////////
void PServiceMixedOriginalSize::procStart( uchar option )
{
// 調整結果表示をTrueにしないため、スタートキー赤の場合何もしないようにする.
	if( printStartDisable() == True ) {	// スタートキー赤なら何もしない.
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );		// 拒否音.
		return;
	}
	bl_showResult = True;	// 調整結果表示.
	PServiceFunctionEnableStopCom::procStart( TYPE_FunctionStartTypeSCANNER );	// スキャナファンクションとして実行.
}
//////////////////////////////////////////////////////////////
// 概要 : 50C00070_ADF調整　／混載原稿サイズ調整(50C00070) : 表示画面のセットアップ.
//////////////////////////////////////////////////////////////
void PServiceMixedOriginalSize::setupGamen( short option )
{
	switch( bl_showResult ) {
		case True:	// スタートキー押下後.
			Gra_ServiceADFAutoAdjustTop.showEnable( False );		 // 非表示・調整チャート説明画像.
			Txt_ServiceADFAutoAdjustAdjustChart.showEnable( False ); // 非表示・「調整チャート」文字列.
			Grp_ServiceMixedOriginalSizeResult.showEnableShow( True );	//   表示・結果表示関連パーツ.
			break;
		case False:	// スタートキー押下前.
			Grp_ServiceMixedOriginalSizeResult.showEnableShow( False );	//   表示・結果表示関連パーツ.
			Gra_ServiceADFAutoAdjustTop.showEnable( True );		 // 非表示・調整チャート説明画像.
			Txt_ServiceADFAutoAdjustAdjustChart.showEnable( True ); // 非表示・「調整チャート」文字列.
			break;
		default: break;
	}

	// ＡＤＦに原稿がセットされているか.
	APIC_Original* pc_Original = PnlComGetOriginal();  // 原稿情報（ＡＰＩ）.
	if( pc_Original->isAdfOriginalExist() == True && pc_Original->getAdfOriginalSize() == TYPD_SizeCodeA4Sef ) {	// ADFに原稿が存在する＆サイズがA4SEFの場合.
		// ＡＤＦに原稿がセットされている時.
		PServiceFunctionCom::searchWithoutPaper_IR( option );	// ファンクション画面共通処理.
	} else {
		// ＡＤＦに原稿がセットされていない時.
		// ライン/OKキー更新のため、ベースクラスをCall.
		PServiceFunctionEnableStopCom::setupGamen( option );
		printLEDControl( False );			// プリントキー・バックライト赤.
	}
	PServiceFunctionEnableStopCom::setupGamen( option );	// 親クラスの処理を呼ぶ.
}
//////////////////////////////////////////////////////////////
// 概要 : 50C00070_ADF調整　／混載原稿サイズ調整(50C00070) : ファンクション終了.
//////////////////////////////////////////////////////////////
void PServiceMixedOriginalSize::procFunctionEnd( uchar option )
{
	us_funcResult = pc_SystemControl.getFunctionResult( static_cast<ushort>( toFunctionCode( TYPD_FNC_EDH_DetectFDSizeLong ) ) ); // コードセット・ＡＤＦ FD長検出調整モード(通紙FD長 大).
	switch( us_funcResult ) {
		case TYPD_FNC_ADF_OK:	// 実行結果「OK」.
			Txt_ADFAdjustResult.changeText( s_ServiceResultOK );	// 結果文字列・「OK」にする.
			break;
		case TYPD_FNC_ADF_NG:	// 実行結果「NG」.
		default:
			Txt_ADFAdjustResult.changeText( s_ServiceResultNG );	// 結果文字列・「NG」にする.
			break;
	}
	Txt_ADFAdjustResult.showEnable( True );	// 実行結果表示
	setupGamen();	// 表示画面のセットアップ
}
