//================================================================================================
// 概要		：サービス・ＡＤＦ調整・主走査方向倍率・主走査方向倍率調整：ボタン（押された）.
// 作成者	：Hamada.
// 備考		：Donau_3rd 管理No.29_3 新規実装.
//================================================================================================
void PServiceADFMainMagZoomAdj::procButtonOn( uchar option )
{
	short ss_prevIndi = 0, ss_currentIndi = 0;
	switch( option )
	{
		case 10:	// －キー.
			ss_prevIndi = getScannerIndi( ss_CurrentScannerIndi );
			ss_currentIndi = setScannerIndi( ss_CurrentScannerIndi, static_cast<short>( getScannerIndi( ss_CurrentScannerIndi ) - 1 ) );
			if( ss_prevIndi == ss_currentIndi ) {
				setBuzzerType( PCGE_BuzzerType_InputNg );
			}
			break;
		case 11:	// ＋キー.
			ss_prevIndi = getScannerIndi( ss_CurrentScannerIndi );
			ss_currentIndi = setScannerIndi( ss_CurrentScannerIndi, static_cast<short>( getScannerIndi( ss_CurrentScannerIndi ) + 1 ) );
			if( ss_prevIndi == ss_currentIndi ) {
				setBuzzerType( PCGE_BuzzerType_InputNg );
			}
			break;
		case 60:	// 元に戻すキー.
			setScannerIndi( TYPE_ScannerAdjustMainMagBack, m_ss_zoomMag_backup );	// 主走査方向倍率調整.
			break;
		default:
			break;
	}
	setupGamen( option );
}

