//================================================================================================
// 概要		：サービス・ＡＤＦ調整・自動調整：表示画面のセットアップ.
// 作成者	：Hamada.
// 備考		：Donau_3rd 管理No.29_3 新規実装.
//			　ADF調整の作りとしてIRは、副走査調整時には前回の調整値からの差分が返ってきて.
//			　主走査調整時には調整結果がそのまま返ってくる。今回は主走査方向倍率調整であるため.
//			　倍率チェック値には調整結果と前回の設定値との差分を、倍率補正値には調整結果を.
//================================================================================================
void PServiceADFMainMagZoomAutoAdj::setupGamen( short option )
{
	Key_ADFAdjustDataSave.select( False );				// セーブキーの選択.

	// ＡＤＦに原稿がセットされているか.
	APIC_Original* pc_Original = PnlComGetOriginal();  // 原稿情報（ＡＰＩ）.
	if( pc_Original->isAdfOriginalExist() == True ) {
		// ＡＤＦに原稿がセットされている時.
		PServiceFunctionCom::searchWithoutPaper_IR( option );	// ファンクション画面共通処理.
	} else {
		// ＡＤＦに原稿がセットされていない時.
		PServiceFunctionEnableStopCom::setupGamen( option );
		printLEDControl( False );			// プリントキー・バックライト赤.
	}

	// キー、調整値の表示制御.
	if( _bl_isAdjustChartFlag == True ) {
		Gra_ServiceADFAutoAdjustTopRev.showEnable( True );			// 調整チャート説明画像表示.
		Txt_ServiceADFAutoAdjustAdjustChart.showEnable( True );		// 調整チャート」文字列表示.
		Grp_FeedZoomAutoAdj.showEnable( False );					// 結果表示関連パーツ非表示.
	} else {
		Gra_ServiceADFAutoAdjustTopRev.showEnable( False );			// 調整チャート説明画像非表示.
		Txt_ServiceADFAutoAdjustAdjustChart.showEnable( False );	// 調整チャート」文字列非表示.
		Grp_FeedZoomAutoAdj.showEnable( True );						// 結果表示関連パーツ表示.
	}

	Num_EDHFeedZoomCheckAuto = ( float )( _getSetValue() - ( getIndi() - 1000 ) * 10 ) / 100;		// 倍率チェック値.
	Num_EDHFeedZoomCorrectionAuto = ( float )( _getSetValue() ) / 100;		// 倍率補正値.
	Num_EDHFeedZoomCheckAuto.showEnable( _bl_isIndicateAdjustValue );		// 倍率チェック表示.
	Num_EDHFeedZoomCorrectionAuto.showEnable( _bl_isIndicateAdjustValue );	// 倍率補正表示.

	Txt_ADFAdjustResult.showEnable( _bl_isFunctionAct );	// 実行結果表示.
	Txt_ADFAutoAdjustArrow.showEnable( _bl_isRequestSave );	// 矢印.
	Key_ADFAdjustDataSave.showEnable( _bl_isRequestSave );	// セーブキー.

	Rbt_ADFMainMagZoomMenu.select( 1 );						// 自動調整キーの選択.
}

//================================================================================================
// 概要		：サービス・ＡＤＦ調整・自動調整：表示画面のセットアップ.
// 作成者	：Hamada.
// 備考		：Donau_3rd 管理No.29_3 新規実装.
//================================================================================================
void PServiceADFMainMagZoomAutoAdj::procFunctionEnd( uchar option )
{
	// ファンクション実行結果取得.
	us_funcResult = pc_SystemControl.getFunctionResult( static_cast<ushort>( toFunctionCode( TYPD_FNC_EDH2SideMagAdjustCD ) ) );	// 主走査方向倍率/自動調整.

	// ファンクション実行結果による場合分け.
	switch( us_funcResult ) {
		case TYPD_FNC_OK:	// ファンクション実行成功.
			Txt_ADFAdjustResult.changeText( s_ServiceResultOK );	// 結果文字列・「OK」にする.
			_bl_isIndicateAdjustValue = True;		// 調整値表示.
			_bl_isRequestSave = True;				// 矢印、登録キーを表示.
			break;
		case TYPD_FNC_NG:	// ファンクション実行失敗.
		default:
			Txt_ADFAdjustResult.changeText( s_ServiceResultUnable );	// 結果文字列・「Unable」にする.
			_bl_isIndicateAdjustValue = False;		// 調整値非表示.
			_bl_isRequestSave = False;				// 矢印、登録キーを非表示.
			break;
	}

	_bl_isFunctionAct = True;			// 実行後にフラグを立てて実行結果を表示する.

	APIC_ScannerServiceInfo* pc_ScannerServiceInfo = PnlComGetScannerServiceInfo();
	_ss_AdjustValue = pc_ScannerServiceInfo->getScannerInfo( TYPE_ScannerInfo1PassDFMagCDBack );	// 主走査方向倍率・自動調整.
	setupGamen();	// 表示画面のセットアップ.
}

//================================================================================================
// 概要		：サービス・ＡＤＦ調整・自動調整：設定終了.
// 作成者	：Hamada.
// 備考		：Donau_3rd 管理No.29_3 新規実装.
//================================================================================================
void PServiceADFMainMagZoomAutoAdj::procOk( uchar option )
{
	nextGamen = &gp_ServiceADFCheckMenu;	// ADF調整・モードメニュー.
}

//================================================================================================
// 概要		：サービス・ＡＤＦ調整・自動調整：ボタン（押された）.
// 作成者	：Hamada.
// 備考		：Donau_3rd 管理No.29_3 新規実装.
//================================================================================================
void PServiceADFMainMagZoomAutoAdj::procButtonOn( uchar option )
{
	switch( option )
	{
		case 0:	// 登録キー.
			// パネル表示用の値-1.00%～1.00%からバックアップする値990～1010へ変換する.
			setIndi( static_cast<short>( ( _getSetValue() / 10 ) + 1000 ) );
			fixIndi();

			_bl_isIndicateAdjustValue = False;     // 調整値を表示するかどうかのフラグ.
			Txt_ADFAdjustResult.changeText( s_ServiceResultBlank );	// 実行結果非表示.
			setupGamen();	// 表示画面のセットアップ.
			break;
		default:
			break;
	}
}

//================================================================================================
// 概要		：サービス・ＡＤＦ調整・自動調整：スタートキー.
// 作成者	：Hamada.
// 備考		：Donau_3rd 管理No.29_3 新規実装.
//================================================================================================
void PServiceADFMainMagZoomAutoAdj::procStart( uchar option )
{
	if( True == isFunctionWorking() ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );		// 拒否音.
		return;
	}

	_bl_isAdjustChartFlag = False;		// 調整チャートは非表示で、結果表示関連パーツは表示.

	_bl_isFunctionAct = False;			// 実行前にフラグを落とす.

	PServiceFunctionEnableStopCom::procStart( TYPE_FunctionStartTypeSCANNER );
}

//================================================================================================
// 概要		：サービス・ＡＤＦ調整・自動調整：ストップキー.
// 作成者	：Hamada.
// 備考		：Donau_3rd 管理No.29_3 新規実装.
