void PServiceFeedDirectionZoomBackAdj::init_value()
{
	m_ss_zoomMag_backup = getScannerIndiInSystem( TYPE_ScannerAdjustSubMagBack );	// 裏面通紙方向倍率調整.
}
// サービス・ＡＤＦ調整・裏面通紙方向倍率・通紙方向倍率調整：設定終了.
void PServiceFeedDirectionZoomBackAdj::procOk( uchar option )
{
	fixScannerIndi( TYPE_ScannerAdjustSubMagBack );	// 裏面通紙方向倍率調整.
	nextGamen = &gp_ServiceADFCheckMenu;	// サービス・ＡＤＦ調整・モードメニュー.
}
// サービス・ＡＤＦ調整・裏面通紙方向倍率・通紙方向倍率調整：ボタン（押された）.
void PServiceFeedDirectionZoomBackAdj::procButtonOn( uchar option )
{
	switch( option ) {
		case 10:	subIndi();	break;	// －キー.
		case 11:	addIndi();	break;	// ＋キー.
		case 60:	// 元に戻すキー.
			setScannerIndi( TYPE_ScannerAdjustSubMagBack, m_ss_zoomMag_backup );	// 裏面通紙方向倍率調整.
			break;
		default:
			break;
	}
	setupGamen( option );
}
// サービス・ＡＤＦ調整・裏面通紙方向倍率・通紙方向倍率調整：ボタン（押し続け）.
void PServiceFeedDirectionZoomBackAdj::procButtonStillOnFast( uchar option )
{
	if( 10 == option || 11 == option ) {
		procButtonOn( option );
	}
}
