// サービス・ＡＤＦ調整・裏面通紙方向倍率・自動調整：設定値の取得.
short PServiceFeedDirectionZoomBackAutoAdj::_getSetValue()
{
	register short _SetValue = _ss_AdjustValue;
	// パネル表示用に値を補正する.
	_SetValue = static_cast<short>( ( _SetValue - 1000 ) * 10 );
	// 設定範囲が-2.00～2.00%なのでそれ以外なら値を丸める.
	if( _SetValue < -200 ) {
		_SetValue = -200;
	}
	if( _SetValue > 200 ) {
		_SetValue = 200;
	}
	_SetValue = static_cast<short>( _SetValue + ( getScannerIndiInSystem( TYPE_ScannerAdjustSubMagBack ) - 1000 ) * 10 );
	// 設定範囲が-2.00～2.00%なのでそれ以外なら値を丸める.
	if( _SetValue < -200 ) {
		_SetValue = -200;
	}
	if( _SetValue > 200 ) {
		_SetValue = 200;
	}
	return( _SetValue );
}
