//comment 2022/07/06 [IT6_2.3] [FPT-LinhNV46] [機器構成変更_No.7].
//================================================================================================
// PServiceLimitBundlesDischar : サービス・フィニッシャ調整・束排出枚数制限 : 画面開始処理.
//================================================================================================
void PServiceLimitBundlesDischar::startGamen()
{
	PServiceNoFunctionCodeCom::startGamen();
	uc_SelectType = 0;												// キー選択種類.
	uc_BakPlain = PnlComGetSystemSetting()->getLimitSheetNumBundle( TYPE_BundlePaperTypePlain );	// Value backup "普通紙/普通紙＋/再生紙".
	uc_BakThick = PnlComGetSystemSetting()->getLimitSheetNumBundle( TYPE_BundlePaperTypeThick );	// Value backup "厚紙1/1+/2/3/4".
	uc_BakThin = PnlComGetSystemSetting()->getLimitSheetNumBundle( TYPE_BundlePaperTypeThin );		// Value backup "薄紙".
	uc_CurrentPlain = uc_BakPlain;									// 普通紙/普通紙＋/再生紙.
	uc_CurrentThick = uc_BakThick;									// 厚紙1/1+/2/3/4.
	uc_CurrentThin = uc_BakThin;									// 薄紙.
}
//================================================================================================
// PServiceLimitBundlesDischar : サービス・フィニッシャ調整・束排出枚数制限 : ボタン（押された）.
//================================================================================================
void PServiceLimitBundlesDischar::procButtonOn( uchar option )
{
	switch( option ) {
		case 0:						// 普通紙/普通紙＋/再生紙キー.
			uc_SelectType = 0;		// 普通紙/普通紙＋/再生紙キー選択.
			break;
		case 1:						// 厚紙1/1+/2/3/4キー.
			uc_SelectType = 1;		// 厚紙1/1+/2/3/4キー選択.
			break;
		case 2:						// 薄紙キー.
			uc_SelectType = 2;		// 薄紙キー選択.
			break;
		case BTNID_KEY_ADD_VALUE:	// ＋キー.
			switch( uc_SelectType ) {
				case 0: 			// 普通紙/普通紙＋/再生紙キー.
					if( uc_CurrentPlain >= PCGD_LimitBundlesDischarRangeMax ){
						setBuzzerType( PCGE_BuzzerType_InputNg );
						return;
					}
					uc_CurrentPlain = uc_CurrentPlain + 1;
					break;
				case 1:				// 厚紙1/1+/2/3/4キー.
					if( uc_CurrentThick >= PCGD_LimitBundlesDischarRangeMax ){
						setBuzzerType( PCGE_BuzzerType_InputNg );
						return;
					}
					uc_CurrentThick = uc_CurrentThick + 1 ;
					break;
				case 2:				// 薄紙キー.
					if( uc_CurrentThin >= PCGD_LimitBundlesDischarRangeMax ){
						setBuzzerType( PCGE_BuzzerType_InputNg );
						return;
					}
					uc_CurrentThin = uc_CurrentThin + 1;
					break;
				default: break;
			}
			break;
		case BTNID_KEY_SUB_VALUE:	// －キー.
			switch( uc_SelectType ) {
				case 0:				// 普通紙/普通紙＋/再生紙キー.
					if( uc_CurrentPlain <= PCGD_LimitBundlesDischarRangeMin ){
						setBuzzerType( PCGE_BuzzerType_InputNg );
						return;
					}
					uc_CurrentPlain = uc_CurrentPlain - 1;
					break;
				case 1:				// 厚紙1/1+/2/3/4キー.
					if( uc_CurrentThick <= PCGD_LimitBundlesDischarRangeMin ){
						setBuzzerType( PCGE_BuzzerType_InputNg );
						return;
					}
					uc_CurrentThick = uc_CurrentThick - 1 ;
					break;
				case 2:				// 薄紙キー.
					if( uc_CurrentThin <= PCGD_LimitBundlesDischarRangeMin ){
						setBuzzerType( PCGE_BuzzerType_InputNg );
						return;
					}
					uc_CurrentThin = uc_CurrentThin - 1;
					break;
				default: break;
			}
			break;
		case 60:		// 元に戻すキー.
			switch( uc_SelectType ) {
				case 0:	// 普通紙/普通紙＋/再生紙キー.
					uc_CurrentPlain = uc_BakPlain;
					break;
				case 1:	// 厚紙1/1+/2/3/4キー.
					uc_CurrentThick = uc_BakThick;
					break;
				case 2:	// 薄紙キー.
					uc_CurrentThin = uc_BakThin;
					break;
				default: break;
			}
			break;
		default: break;
	}
	setupGamen( option );
}
//================================================================================================
// PServiceLimitBundlesDischar : サービス・フィニッシャ調整・束排出枚数制限 : ＯＫキー.
//================================================================================================
void PServiceLimitBundlesDischar::procOk( uchar option )
{
	PnlComGetSystemSetting()->setLimitSheetNumBundle( TYPE_BundlePaperTypePlain, uc_CurrentPlain );				// 普通紙/普通紙＋/再生紙.
	PnlComGetSystemSetting()->setLimitSheetNumBundle( TYPE_BundlePaperTypeThick, uc_CurrentThick );				// 厚紙1/1+/2/3/4.
	PnlComGetSystemSetting()->setLimitSheetNumBundle( TYPE_BundlePaperTypeThin, uc_CurrentThin );				// 薄紙.
	nextGamen = &gp_ServiceFinisherAdjustmentMenu;																// サービス・フィニッシャ調整・メニュー.
}
//================================================================================================
// PServiceLimitBundlesDischar : サービス・フィニッシャ調整・束排出枚数制限 : 表示画面のセットアップ.
//================================================================================================
void PServiceLimitBundlesDischar::setupGamen( short option )
{
	PServiceNoFunctionCodeCom::setupGamen( option );
	Bak_SvcsAdjustValueArea1.changeGraphic( PB_SvcsAwNewB );		//new B.
	Bak_SvcsAdjustRangeArea1.changeGraphic( PB_SvcsAwNewW );		//new W.
	Bak_SvcsAdjustValueArea1.changePosition( 492,232 );
	Bak_SvcsAdjustRangeArea1.changePosition( 492, 280 );;
	Txt_SvcsFNSAdjStep1.changePosition( 528, 314 );
	Key_PServiceAdjustValueUp.changePosition( 568, 348 );
	Key_PServiceAdjustValueDown.changePosition( 492, 348 );	

	Rbt_ServiceLimitBundlesDischar.select( uc_SelectType );			// 選択キーの表示.
	Btx_ServiceLimitBundlesDischarNormal = (float) uc_CurrentPlain;
	Btx_ServiceLimitBundlesDischarNotNormal = (float) uc_CurrentThick;
	Btx_ServiceLimitBundlesDischarThin = (float) uc_CurrentThin;
	switch( uc_SelectType ) {
		case 0:	// 普通紙/普通紙＋/再生紙キー.
			Inp_LimitBundlesDischarAdjValue = (float) uc_CurrentPlain;
			break;
		case 1:	// 厚紙1/1+/2/3/4キー.
			Inp_LimitBundlesDischarAdjValue = (float) uc_CurrentThick;
			break;
		case 2:	// 薄紙キー.
			Inp_LimitBundlesDischarAdjValue = (float) uc_CurrentThin;
			break;
		default: break;
	}
}
