//================================================================================================
// 概要		:サービス・フィニッシャ調整・FSFN調整・中央ステープル位置調整 : 画面遷移キー.
//================================================================================================
void PServiceFinisherCStapleAdj::procGoToPage( uchar option )
{
	switch( option )
	{
		case 99 :			// テストコピーボタン押下.
			// 調整値確定.
			fixPrinterIndi( TYPE_FS526_AD_CenterStapleAdj_All	);	// 全体.
			fixPrinterIndi( TYPE_FS535_AD_CenterStapleAdj_SRA3	);	// SRA3SEF.
			fixPrinterIndi( TYPE_FS526_AD_CenterStapleAdj_A3SEF	);	// A3SEF.
			fixPrinterIndi( TYPE_FS526_AD_CenterStapleAdj_B4SEF	);	// B4SEF.
			fixPrinterIndi( TYPE_FS526_AD_CenterStapleAdj_A4SEF	);	// A4SEF.
			fixPrinterIndi( TYPE_FS526_AD_CenterStapleAdj_12x18SEF	);	// 12x18SEF.
			fixPrinterIndi( TYPE_FS526_AD_CenterStapleAdj_11x17SEF	);	// 11X17SEF.
			fixPrinterIndi( TYPE_FS526_AD_CenterStapleAdj_85x14SEF	);	// 8.5X14SEF.
			fixPrinterIndi( TYPE_FS526_AD_CenterStapleAdj_85x11SEF	);	// 8.5X11SEF.
			fixPrinterIndi( TYPE_FS526_AD_CenterStapleAdj_F4	);	// Foolscap.
			fixPrinterIndi( TYPE_FS526_AD_CenterStapleAdj_8KSEF	);	// 8K.
			fixPrinterIndi( TYPE_FS526_AD_CenterStapleAdj_CustomL	);	// 不定形大.
			fixPrinterIndi( TYPE_FS526_AD_CenterStapleAdj_CustomM	);	// 不定形中.
			gp_ServiceTestCopy.setRetGamen( this );		// 戻り先画面.
			nextGamen = &gp_ServiceTestCopy;	// サービス・テストコピー.
			break;
		default:
			// 親クラスの呼出し.
			PServiceFinisherAdjCom::procGoToPage( option );
			break;
	}
}


