//================================================================================================
// 概要		:サービス・フィニッシャ調整・FSFN調整・中折り位置調整 : 表示画面のセットアップ.
//================================================================================================
void PServiceFinisherCFoldAdj::setupGamen( short option )
{
	short ss_LocalData = 0;							// ローカルデータ.
	// 親クラスの呼出し.
	PServiceFinisherAdjCom::setupGamen( option );
	// 各値を表示
	Bak_SvcsFNSCStapleFoldNowValueArea01 = ( float )getPrinterIndi( TYPE_FS526_AD_CenterFoldPositionAdj_All ) / 10.0f;	// 全体.
//comment 2014/09/18 HCLT-Vivek [Poseidon] [CQ503159] Condition for "SRA3" key Background Value updation.
// 2015/01/08 【HeliosL】 【機器構成変更_No_.13】 【HCLT-Chandrasekar】 Deletion of SRA3 Key.
// Comment 2019/07/26 [HCLT_Paul] [IT6_HeliosMLK] [ Seigyu.10 ] Adding the HeliosMLK compiler switch.
#if  ( !defined (DEF_Zeus5BkCus) &&  !defined (DEF_HeliosMLKCus) )
	Bak_SvcsFNSCStapleFoldNowValueArea02 = ( float )getPrinterIndi( TYPE_FS535_AD_CenterFoldPositionAdj_SRA3 ) / 10.0f;	// SRA3SEF.
#endif // #if  ( !defined (DEF_Zeus5BkCus) &&  !defined (DEF_HeliosCus) ).
	Bak_SvcsFNSCStapleFoldNowValueArea03 = ( float )getPrinterIndi( TYPE_FS526_AD_CenterFoldPositionAdj_A3SEF ) / 10.0f;	// A3SEF.
	Bak_SvcsFNSCStapleFoldNowValueArea04 = ( float )getPrinterIndi( TYPE_FS526_AD_CenterFoldPositionAdj_B4SEF ) / 10.0f;	// B4SEF.
	Bak_SvcsFNSCStapleFoldNowValueArea05 = ( float )getPrinterIndi( TYPE_FS526_AD_CenterFoldPositionAdj_A4SEF ) / 10.0f;	// A4SEF.
// 2015/01/08 【HeliosL】 【機器構成変更_No_.13】 【HCLT-Chandrasekar】 Deletion of 12x18SEF Key.
////comment 2014/09/18 HCLT-Vivek [Poseidon] [CQ503159] Condition for "12x18" key Background Value updation.
// #ifndef DEF_Zeus5BkCus.
// Comment 2019/07/26 [HCLT_Paul] [IT6_HeliosMLK] [ Seigyu.10 ] Adding the HeliosMLK compiler switch.
#if  ( !defined (DEF_Zeus5BkCus) &&  !defined (DEF_HeliosMLKCus) )
	Bak_SvcsFNSCStapleFoldNowValueArea06 = ( float )getPrinterIndi( TYPE_FS526_AD_CenterFoldPositionAdj_12x18SEF ) / 10.0f;	// 12x18SEF.
#endif // #if  ( !defined (DEF_Zeus5BkCus) &&  !defined (DEF_HeliosCus) ).
	Bak_SvcsFNSCStapleFoldNowValueArea07 = ( float )getPrinterIndi( TYPE_FS526_AD_CenterFoldPositionAdj_11x17SEF ) / 10.0f;	// 11X17SEF.
	Bak_SvcsFNSCStapleFoldNowValueArea08 = ( float )getPrinterIndi( TYPE_FS526_AD_CenterFoldPositionAdj_85x14SEF ) / 10.0f;	// 8.5X14SEF.
	Bak_SvcsFNSCStapleFoldNowValueArea09 = ( float )getPrinterIndi( TYPE_FS526_AD_CenterFoldPositionAdj_85x11SEF ) / 10.0f;	// 8.5X11SEF.
	Bak_SvcsFNSCStapleFoldNowValueArea10 = ( float )getPrinterIndi( TYPE_FS526_AD_CenterFoldPositionAdj_F4 ) / 10.0f;	// Foolscap.
	Bak_SvcsFNSCStapleFoldNowValueArea11 = ( float )getPrinterIndi( TYPE_FS526_AD_CenterFoldPositionAdj_8KSEF ) / 10.0f;	// 8K.
	Bak_SvcsFNSCStapleFoldNowValueArea12 = ( float )getPrinterIndi( TYPE_FS526_AD_CenterFoldPositionAdj_CustomL ) / 10.0f;	// 不定形大.
	Bak_SvcsFNSCStapleFoldNowValueArea13 = ( float )getPrinterIndi( TYPE_FS526_AD_CenterFoldPositionAdj_CustomM ) / 10.0f;	// 不定形中.
	// Foolscapキー/現在値の表示状態設定.
	ushort us_TextID = s_8Hx13T;	// キー名称テキストID（既定値：ブランク).
	Bool bl_DisplayFoolscap = True;	// 表示状態フラグ(既定値：表示).
	switch( e_FLSType ) {
		case TYPE_FLSType85x13:		us_TextID = s_8Hx13T;		break;	// 8_1/2 x 13.
		case TYPE_FLSType220x330:	us_TextID = s_220x330T;		break;	// 220x330.
		case TYPE_FLSType85x135:	us_TextID = s_EXP8Hx13HT;	break;	// 8.5x13.5.
		case TYPE_FLSType825x13:	// 8_1/4 x 13.
		case TYPE_FLSType8125x1325:	// 8_1/8 x 13.
		case TYPE_FLSType8x13:		// 8 x 13.
		default:					// 上記以外.
			bl_DisplayFoolscap = False;	// 非表示設定.
			break;
	}
// comment 2015/03/05 HCLT_SunilNP [HeliosL][CQ509894] adjusting the positions.
// Comment 2017/11/29 【HCLT-Vishal】【Eagle】【制御構成変更_No.4】 Removing old function version check and else portion.
	Bak_SvcsAdjustValueArea1.changeGraphic( PB_SvcsAwNewB  );
	Bak_SvcsAdjustRangeArea1.changeGraphic( PB_SvcsAwNewW );
	Bak_SvcsAdjustValueArea1.changePosition( 492,232 );
	Bak_SvcsAdjustRangeArea1.changePosition( 492, 280 );
	Inp_SvcsFNSCStapleFoldAdjValue.changePosition( 517,244 );
	Txt_SvcsFNSAdjUnit_mm.changePosition( 562,244 );
	Txt_SvcsFNSAdjRangeMinus12_8ToPlus12_7.changePosition( 500, 292 );
	Txt_SvcsFNSAdjStep01.changePosition( 508, 314 );
	Key_SvcsSetPlus1.changePosition( 568, 348 );
	Key_SvcsSetMinus1.changePosition( 492, 348 );
	Key_SvcsFNSCStapleFoldPaperKey10.changeText( us_TextID );					// Foolscapキー名称(用紙名称)設定.
	Key_SvcsFNSCStapleFoldPaperKey10.showEnable( bl_DisplayFoolscap );		// Foolscapキー表示状態設定.
	Bak_SvcsFNSCStapleFoldNowValueArea10.showEnable( bl_DisplayFoolscap );	// 現在値フィールド表示状態設定.
	// 調整値取得
	switch( getIndiSelected() ) {
		case TYPE_FS526_AD_CenterFoldPositionAdj_All:			ss_LocalData = getPrinterIndi( TYPE_FS526_AD_CenterFoldPositionAdj_All ); break;	// ALL.
		case TYPE_FS535_AD_CenterFoldPositionAdj_SRA3:			ss_LocalData = getPrinterIndi( TYPE_FS535_AD_CenterFoldPositionAdj_SRA3 ); break;	// SRA3.
		case TYPE_FS526_AD_CenterFoldPositionAdj_A3SEF:			ss_LocalData = getPrinterIndi( TYPE_FS526_AD_CenterFoldPositionAdj_A3SEF ); break;	// A3.
		case TYPE_FS526_AD_CenterFoldPositionAdj_B4SEF:			ss_LocalData = getPrinterIndi( TYPE_FS526_AD_CenterFoldPositionAdj_B4SEF ); break;	// B4.
		case TYPE_FS526_AD_CenterFoldPositionAdj_A4SEF:			ss_LocalData = getPrinterIndi( TYPE_FS526_AD_CenterFoldPositionAdj_A4SEF ); break;	// A4R.
		case TYPE_FS526_AD_CenterFoldPositionAdj_12x18SEF:		ss_LocalData = getPrinterIndi( TYPE_FS526_AD_CenterFoldPositionAdj_12x18SEF ); break;	// 12x18.
		case TYPE_FS526_AD_CenterFoldPositionAdj_11x17SEF:		ss_LocalData = getPrinterIndi( TYPE_FS526_AD_CenterFoldPositionAdj_11x17SEF ); break;	// 11x17.
		case TYPE_FS526_AD_CenterFoldPositionAdj_85x14SEF:		ss_LocalData = getPrinterIndi( TYPE_FS526_AD_CenterFoldPositionAdj_85x14SEF ); break;	// 85x14.
		case TYPE_FS526_AD_CenterFoldPositionAdj_85x11SEF:		ss_LocalData = getPrinterIndi( TYPE_FS526_AD_CenterFoldPositionAdj_85x11SEF ); break;	// 85x11R.
		case TYPE_FS526_AD_CenterFoldPositionAdj_F4:			ss_LocalData = getPrinterIndi( TYPE_FS526_AD_CenterFoldPositionAdj_F4 ); break;	// Foolscap.
		case TYPE_FS526_AD_CenterFoldPositionAdj_8KSEF:			ss_LocalData = getPrinterIndi( TYPE_FS526_AD_CenterFoldPositionAdj_8KSEF ); break;	// 8K.
		case TYPE_FS526_AD_CenterFoldPositionAdj_CustomL:		ss_LocalData = getPrinterIndi( TYPE_FS526_AD_CenterFoldPositionAdj_CustomL ); break;	// 不定形大.
		case TYPE_FS526_AD_CenterFoldPositionAdj_CustomM:		ss_LocalData = getPrinterIndi( TYPE_FS526_AD_CenterFoldPositionAdj_CustomM ); break;	// 不定形中.
		default: LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); break;
	}
// comment 2015/03/05 HCLT_SunilNP [HeliosL][CQ509894] adjusting the positions.
//	Bak_SvcsFNSCStapleFoldNowValueAreaAdj = ss_LocalData / 10.0f;	// 調整値入力.
	Inp_SvcsFNSCStapleFoldAdjValue = ss_LocalData / 10.0f;
	// キーを選択表示.


	if( False == PLBC_FuncVersionCheck::isOK_MiZe_Type2() ) {
		Key_ServiceTestCopy.showEnable( False );			// テストコピーボタン非表示.
	}

}
//================================================================================================
// 概要		:サービス・フィニッシャ調整・FSFN調整・中折り位置調整 : OKキー.
//================================================================================================
void PServiceFinisherCFoldAdj::procOk( uchar option )
{
	// 調整値確定.
	fixPrinterIndi( TYPE_FS526_AD_CenterFoldPositionAdj_All	);	// 全体.
	fixPrinterIndi( TYPE_FS535_AD_CenterFoldPositionAdj_SRA3	);	// SRA3SEF.
	fixPrinterIndi( TYPE_FS526_AD_CenterFoldPositionAdj_A3SEF	);	// A3SEF.
	fixPrinterIndi( TYPE_FS526_AD_CenterFoldPositionAdj_B4SEF	);	// B4SEF.
	fixPrinterIndi( TYPE_FS526_AD_CenterFoldPositionAdj_A4SEF	);	// A4SEF.
	fixPrinterIndi( TYPE_FS526_AD_CenterFoldPositionAdj_12x18SEF	);	// 12x18SEF.
	fixPrinterIndi( TYPE_FS526_AD_CenterFoldPositionAdj_11x17SEF	);	// 11X17SEF.
	fixPrinterIndi( TYPE_FS526_AD_CenterFoldPositionAdj_85x14SEF	);	// 8.5X14SEF.
	fixPrinterIndi( TYPE_FS526_AD_CenterFoldPositionAdj_85x11SEF	);	// 8.5X11SEF.
	fixPrinterIndi( TYPE_FS526_AD_CenterFoldPositionAdj_F4	);	// Foolscap.
	fixPrinterIndi( TYPE_FS526_AD_CenterFoldPositionAdj_8KSEF	);	// 8K.
	fixPrinterIndi( TYPE_FS526_AD_CenterFoldPositionAdj_CustomL	);	// 不定形大.
	fixPrinterIndi( TYPE_FS526_AD_CenterFoldPositionAdj_CustomM	);	// 不定形中.
	// 親クラスの呼出し.
	PServiceFinisherAdjCom::procOk( option );
}
