				case TYPE_FS526_AD_CenterFoldPositionAdj_A3SEF:			setPrinterIndi( TYPE_FS526_AD_CenterFoldPositionAdj_A3SEF, ss_BakFinisherCFoldA3 );					break;	// A3.
				case TYPE_FS526_AD_CenterFoldPositionAdj_B4SEF:			setPrinterIndi( TYPE_FS526_AD_CenterFoldPositionAdj_B4SEF, ss_BakFinisherCFoldB4 );					break;	// B4.
