				case TYPE_FS526_AD_CenterFoldPositionAdj_11x17SEF:		setPrinterIndi( TYPE_FS526_AD_CenterFoldPositionAdj_11x17SEF, ss_BakFinisherCFold11x17 );			break;	// 11x17.
				case TYPE_FS526_AD_CenterFoldPositionAdj_85x14SEF:		setPrinterIndi( TYPE_FS526_AD_CenterFoldPositionAdj_85x14SEF, ss_BakFinisherCFold85x14 );			break;	// 85x14.
				case TYPE_FS526_AD_CenterFoldPositionAdj_85x11SEF:		setPrinterIndi( TYPE_FS526_AD_CenterFoldPositionAdj_85x11SEF, ss_BakFinisherCFold85x11R );			break;	// 85x11R.
				case TYPE_FS526_AD_CenterFoldPositionAdj_F4:			setPrinterIndi( TYPE_FS526_AD_CenterFoldPositionAdj_F4, ss_BakFinisherCFoldFoolscap );				break;	// Foolscap.
				case TYPE_FS526_AD_CenterFoldPositionAdj_8KSEF:			setPrinterIndi( TYPE_FS526_AD_CenterFoldPositionAdj_8KSEF, ss_BakFinisherCFold8K );					break;	// 8K.
				case TYPE_FS526_AD_CenterFoldPositionAdj_CustomL:		setPrinterIndi( TYPE_FS526_AD_CenterFoldPositionAdj_CustomL, ss_BakFinisherCFoldCustomLarge );		break;	// 不定形大.
