				case TYPE_FS526_AD_PunchAdjDepth_B5LEF:		setPrinterIndi( TYPE_FS526_AD_PunchAdjDepth_B5LEF,	 	ss_BakFinisherPunchHeightB5 );			break;	// B5.
				case TYPE_FS526_AD_PunchAdjDepth_B5SEF:		setPrinterIndi( TYPE_FS526_AD_PunchAdjDepth_B5SEF,	 	ss_BakFinisherPunchHeightB5R );			break;	// B5R.
				case TYPE_FS526_AD_PunchAdjDepth_A5LEF:		setPrinterIndi( TYPE_FS526_AD_PunchAdjDepth_A5LEF, 	 	ss_BakFinisherPunchHeightA5 );			break;	// A5.
				case TYPE_FS526_AD_PunchAdjDepth_A5SEF:		setPrinterIndi( TYPE_FS526_AD_PunchAdjDepth_A5SEF, 	 	ss_BakFinisherPunchHeightA5R );			break;	// A5R.
				case TYPE_FS526_AD_PunchAdjDepth_11x17SEF:	setPrinterIndi( TYPE_FS526_AD_PunchAdjDepth_11x17SEF, 	ss_BakFinisherPunchHeight11x17 );		break;	// 11x17.
				case TYPE_FS526_AD_PunchAdjDepth_85x14SEF:	setPrinterIndi( TYPE_FS526_AD_PunchAdjDepth_85x14SEF, 	ss_BakFinisherPunchHeight85x14 );		break;	// 85x14.
				case TYPE_FS526_AD_PunchAdjDepth_85x11LEF:	setPrinterIndi( TYPE_FS526_AD_PunchAdjDepth_85x11LEF, 	ss_BakFinisherPunchHeight85x11 );		break;	// 85x11.
				case TYPE_FS526_AD_PunchAdjDepth_85x11SEF:	setPrinterIndi( TYPE_FS526_AD_PunchAdjDepth_85x11SEF,  	ss_BakFinisherPunchHeight85x11R );		break;	// 85x11R.
				case TYPE_FS526_AD_PunchAdjDepth_55x85LEF:	setPrinterIndi( TYPE_FS526_AD_PunchAdjDepth_55x85LEF, 	ss_BakFinisherPunchHeight55x85 );		break;	// 55x85.
				case TYPE_FS526_AD_PunchAdjDepth_55x85SEF:	setPrinterIndi( TYPE_FS526_AD_PunchAdjDepth_55x85SEF,  	ss_BakFinisherPunchHeight55x85R );		break;	// 55x85R.
				case TYPE_FS526_AD_PunchAdjDepth_F4:		setPrinterIndi( TYPE_FS526_AD_PunchAdjDepth_F4,  		ss_BakFinisherPunchHeight55x85R );		break;	// Foolscap.
				case TYPE_FS526_AD_PunchAdjDepth_8KSEF:		setPrinterIndi( TYPE_FS526_AD_PunchAdjDepth_8KSEF, 		ss_BakFinisherPunchHeight8K );			break;	// 8K.
				case TYPE_FS526_AD_PunchAdjDepth_16KLEF:	setPrinterIndi( TYPE_FS526_AD_PunchAdjDepth_16KLEF, 	ss_BakFinisherPunchHeight16K );			break;	// 16K.
				case TYPE_FS526_AD_PunchAdjDepth_16KSEF:	setPrinterIndi( TYPE_FS526_AD_PunchAdjDepth_16KSEF, 	ss_BakFinisherPunchHeight16KR );		break;	// 16KR.
