//================================================================================================
// 概要		:サービス・フィニッシャ調整・FSFN調整・パンチ縦位置調整・共通：画面遷移.
//================================================================================================
void PServiceFinisherPunchHeightPositionCom::procGoToPage( uchar option )
{
	// 調整値確定.
	fixPrinterIndi( TYPE_FS526_AD_PunchAdjDepth_All	);	// 全体.
	fixPrinterIndi( TYPE_FS526_AD_PunchAdjDepth_A3SEF	);	// A3.
	fixPrinterIndi( TYPE_FS526_AD_PunchAdjDepth_B4SEF	);	// B4.
	fixPrinterIndi( TYPE_FS526_AD_PunchAdjDepth_A4LEF	);	// A4.
	fixPrinterIndi( TYPE_FS526_AD_PunchAdjDepth_A4SEF	);	// A4R.
	fixPrinterIndi( TYPE_FS526_AD_PunchAdjDepth_B5LEF	);	// B5.
	fixPrinterIndi( TYPE_FS526_AD_PunchAdjDepth_B5SEF	);	// B5R.
	fixPrinterIndi( TYPE_FS526_AD_PunchAdjDepth_A5LEF	);	// A5.
	fixPrinterIndi( TYPE_FS526_AD_PunchAdjDepth_A5SEF	);	// A5R.
	fixPrinterIndi( TYPE_FS526_AD_PunchAdjDepth_11x17SEF	);	// 11x17.
	fixPrinterIndi( TYPE_FS526_AD_PunchAdjDepth_85x14SEF	);	// 85x14.
	fixPrinterIndi( TYPE_FS526_AD_PunchAdjDepth_85x11LEF	);	// 85x11.
	fixPrinterIndi( TYPE_FS526_AD_PunchAdjDepth_85x11SEF	);	// 85x11R.
	fixPrinterIndi( TYPE_FS526_AD_PunchAdjDepth_55x85LEF	);	// 55x85.
	fixPrinterIndi( TYPE_FS526_AD_PunchAdjDepth_55x85SEF	);	// 55x85R.
	fixPrinterIndi( TYPE_FS526_AD_PunchAdjDepth_F4	);	// Foolscap.
	fixPrinterIndi( TYPE_FS526_AD_PunchAdjDepth_8KSEF	);	// 8K.
	fixPrinterIndi( TYPE_FS526_AD_PunchAdjDepth_16KLEF	);	// 16K.
	fixPrinterIndi( TYPE_FS526_AD_PunchAdjDepth_16KSEF	);	// 16KR.
	// 画面遷移.
	switch( option ) {
		case 1:
			bl_isRequestInitialize = True;	// 初期化必要.
			nextGamen = &gp_SvcsPunchHeightPositionAdj;
			break;
		case 2:
			bl_isRequestInitialize = True;	// 初期化必要.
			nextGamen = &gp_SvcsPunchHeightPositionAdjP2;
			break;
		case 99 :			// テストコピーボタン押下.
			gp_ServiceTestCopy.setRetGamen( this );		// 戻り先画面.
			nextGamen = &gp_ServiceTestCopy;	// サービス・テストコピー.
			break;
		default:		break;
	}
}
