void PServiceFinisherPunchHeightPositionAdjP2::procButtonOn( uchar option )
{
	switch( option ) {
		case BTNID_KEY_SERV_HEIGHT_PUNCH_85x14:
			setPrinterIndi( TYPE_FS526_AD_PunchAdjDepth_85x14SEF	);	// 85x14.
			ss_select = 0;
			break;
		case BTNID_KEY_SERV_HEIGHT_PUNCH_85x11:
			setPrinterIndi( TYPE_FS526_AD_PunchAdjDepth_85x11LEF	);	// 85x11.
			ss_select = 1;
			break;
		case BTNID_KEY_SERV_HEIGHT_PUNCH_85x11R:
			setPrinterIndi( TYPE_FS526_AD_PunchAdjDepth_85x11SEF	);	// 85x11R.
			ss_select = 2;
			break;
		case BTNID_KEY_SERV_HEIGHT_PUNCH_55x85:
			setPrinterIndi( TYPE_FS526_AD_PunchAdjDepth_55x85LEF	);	// 55x85.
			ss_select = 3;
			break;
		case BTNID_KEY_SERV_HEIGHT_PUNCH_55x85R:
			setPrinterIndi( TYPE_FS526_AD_PunchAdjDepth_55x85SEF	);	// 55x85R.
			ss_select = 4;
			break;
		case BTNID_KEY_SERV_HEIGHT_PUNCH_FOOLSCAP:
			setPrinterIndi( TYPE_FS526_AD_PunchAdjDepth_F4	);	// Foolscap.
			ss_select = 5;
			break;
		case BTNID_KEY_SERV_HEIGHT_PUNCH_8K:
			setPrinterIndi( TYPE_FS526_AD_PunchAdjDepth_8KSEF	);	// 8K.
			ss_select = 6;
			break;
		case BTNID_KEY_SERV_HEIGHT_PUNCH_16K:
			setPrinterIndi( TYPE_FS526_AD_PunchAdjDepth_16KLEF	);	// 16K.
			ss_select = 7;
			break;
		case BTNID_KEY_SERV_HEIGHT_PUNCH_16KR:
			setPrinterIndi( TYPE_FS526_AD_PunchAdjDepth_16KSEF	);	// 16KR.
			ss_select = 8;
			break;
		default: PServiceFinisherPunchHeightPositionCom::procButtonOn( option ); break;
	}
	setupGamen();
}
