				case TYPE_PrinterAdjustPZPunchDepth85x11R: setPrinterIndi( TYPE_PrinterAdjustPZPunchDepth85x11R, ss_BakFinisherPZPunchHeight85x11R ); break;	// 85x11R.
				case TYPE_PrinterAdjustPZPunchDepth55x85: setPrinterIndi( TYPE_PrinterAdjustPZPunchDepth55x85, ss_BakFinisherPZPunchHeight55x85 ); break;	// 55x85.
