				case TYPE_PrinterAdjustPZPunchDepth8x13: setPrinterIndi( TYPE_PrinterAdjustPZPunchDepth8x13, ss_BakFinisherPZPunchHeight8x13 ); break;	// 8x13.
				case TYPE_PrinterAdjustPZPunchDepth8125x1325: setPrinterIndi( TYPE_PrinterAdjustPZPunchDepth8125x1325, ss_BakFinisherPZPunchHeight8125x1325 ); break;	// 8125x1325.
				case TYPE_PrinterAdjustPZPunchDepth85x13: setPrinterIndi( TYPE_PrinterAdjustPZPunchDepth85x13, ss_BakFinisherPZPunchHeight85x13 ); break;	// 85x13.
				case TYPE_PrinterAdjustPZPunchDepth825x13: setPrinterIndi( TYPE_PrinterAdjustPZPunchDepth825x13, ss_BakFinisherPZPunchHeight825x13 ); break;	// 825x13.
