// 概要		:サービス・フィニッシャ調整・FSFN調整・パンチユニット縦位置調整・共通：画面遷移.
//================================================================================================
void PServiceFinisherPZPunchHeightPositionCom::procGoToPage( uchar option )
{
	// 調整値確定.
	fixPrinterIndi( TYPE_PrinterAdjustPZPunchDepthALL	);	// 全体.
	fixPrinterIndi( TYPE_PrinterAdjustPZPunchDepthA3	);	// A3.
	fixPrinterIndi( TYPE_PrinterAdjustPZPunchDepthB4	);	// B4.
	fixPrinterIndi( TYPE_PrinterAdjustPZPunchDepthA4	);	// A4.
	fixPrinterIndi( TYPE_PrinterAdjustPZPunchDepthA4R	);	// A4R.
	fixPrinterIndi( TYPE_PrinterAdjustPZPunchDepthB5	);	// B5.
	fixPrinterIndi( TYPE_PrinterAdjustPZPunchDepthB5R	);	// B5R.
	fixPrinterIndi( TYPE_PrinterAdjustPZPunchDepthA5	);	// A5.
	fixPrinterIndi( TYPE_PrinterAdjustPZPunchDepthA5R	);	// A5R.
	fixPrinterIndi( TYPE_PrinterAdjustPZPunchDepth11x17	);	// 11x17.
	fixPrinterIndi( TYPE_PrinterAdjustPZPunchDepth85x14	);	// 85x14.
	fixPrinterIndi( TYPE_PrinterAdjustPZPunchDepth85x11	);	// 85x11.
	fixPrinterIndi( TYPE_PrinterAdjustPZPunchDepth85x11R	);	// 85x11R.
	fixPrinterIndi( TYPE_PrinterAdjustPZPunchDepth55x85	);	// 55x85.
	fixPrinterIndi( TYPE_PrinterAdjustPZPunchDepth55x85R	);	// 55x85R.
	fixPrinterIndi( TYPE_PrinterAdjustPZPunchDepth8x13	);	// 8x13.
	fixPrinterIndi( TYPE_PrinterAdjustPZPunchDepth8125x1325	);	// 8125x1325
	fixPrinterIndi( TYPE_PrinterAdjustPZPunchDepth85x13	);	// 85x13.
	fixPrinterIndi( TYPE_PrinterAdjustPZPunchDepth825x13	);	// 825x13.
	fixPrinterIndi( TYPE_PrinterAdjustPZPunchDepth220x330	);	// 220x330.
	fixPrinterIndi( TYPE_PrinterAdjustPZPunchDepth8K	);	// 8K.
	fixPrinterIndi( TYPE_PrinterAdjustPZPunchDepth16K	);	// 16K.
	fixPrinterIndi( TYPE_PrinterAdjustPZPunchDepth16KR	);	// 16KR.
	switch( option ) {
		case 1:
			bl_isRequestInitialize = True;	// 初期化必要.
			nextGamen = &gp_SvcsPZPunchHeightPositionAdj;
			break;
		case 2:
			bl_isRequestInitialize = True;	// 初期化必要.
			nextGamen = &gp_SvcsPZPunchHeightPositionAdjP2;
			break;
		case 99 :			// テストコピーボタン押下.
			gp_ServiceTestCopy.setRetGamen( this );		// 戻り先画面.
			nextGamen = &gp_ServiceTestCopy;	// サービス・テストコピー.
			break;
		default:		break;
	}
}
