			setPrinterIndi( TYPE_PrinterAdjustPZPunchDepthA5R	);	// A5R.
			ss_select = 8;
			break;
		case BTNID_KEY_SERV_HEIGHT_PUNCH_11x17:
			setPrinterIndi( TYPE_PrinterAdjustPZPunchDepth11x17	);	// 11x17.
