//================================================================================================
// 概要		:サービス・フィニッシャ調整・FSFN調整・パンチユニット縦位置調整・1ページ目：画面表示セットアップ.
//================================================================================================
void PServiceFinisherPZPunchHeightPositionAdjP1::setupGamen( short option )
{
	short ss_LocalData = 0;							// ローカルデータ.
	Txt_Svcs93303PunchHeightPositionAdj.changeText( ( ushort )s_TTLServicePunchUnitHeightPositionAdj );
	// 親クラスの呼出し.
	PServiceFinisherAdjCom::setupGamen( option );
	Bak_Svcs93303NowValue00 = ( float )getPrinterIndi( TYPE_PrinterAdjustPZPunchDepthALL ) / 10.0f;	// 現在値表示エリア(All).
	Bak_Svcs93303NowValue01 = ( float )getPrinterIndi( TYPE_PrinterAdjustPZPunchDepthA3 ) / 10.0f;	// 現在値表示エリア(A3).
	Bak_Svcs93303NowValue02 = ( float )getPrinterIndi( TYPE_PrinterAdjustPZPunchDepthB4 ) / 10.0f;	// 現在値表示エリア(B4).
	Bak_Svcs93303NowValue03 = ( float )getPrinterIndi( TYPE_PrinterAdjustPZPunchDepthA4 ) / 10.0f;	// 現在値表示エリア(A4).
	Bak_Svcs93303NowValue04 = ( float )getPrinterIndi( TYPE_PrinterAdjustPZPunchDepthA4R ) / 10.0f;	// 現在値表示エリア(A4R).
	Bak_Svcs93303NowValue05 = ( float )getPrinterIndi( TYPE_PrinterAdjustPZPunchDepthB5 ) / 10.0f;	// 現在値表示エリア(B5).
	Bak_Svcs93303NowValue06 = ( float )getPrinterIndi( TYPE_PrinterAdjustPZPunchDepthB5R ) / 10.0f;	// 現在値表示エリア(B5R).
	Bak_Svcs93303NowValue07 = ( float )getPrinterIndi( TYPE_PrinterAdjustPZPunchDepthA5 ) / 10.0f;	// 現在値表示エリア(A5).
	Bak_Svcs93303NowValue08 = ( float )getPrinterIndi( TYPE_PrinterAdjustPZPunchDepthA5R ) / 10.0f;	// 現在値表示エリア(A5R).
	Bak_Svcs93303NowValue09 = ( float )getPrinterIndi( TYPE_PrinterAdjustPZPunchDepth11x17 ) / 10.0f;	// 現在値表示エリア(11×17).
	// 調整値取得
	switch( getIndiSelected() ) {
		case TYPE_PrinterAdjustPZPunchDepthALL:		ss_LocalData = getPrinterIndi( TYPE_PrinterAdjustPZPunchDepthALL );		break;	// 全体.
		case TYPE_PrinterAdjustPZPunchDepthA3:		ss_LocalData = getPrinterIndi( TYPE_PrinterAdjustPZPunchDepthA3 );		break;	// A3.
		case TYPE_PrinterAdjustPZPunchDepthB4:		ss_LocalData = getPrinterIndi( TYPE_PrinterAdjustPZPunchDepthB4 );		break;	// B4.
		case TYPE_PrinterAdjustPZPunchDepthA4:		ss_LocalData = getPrinterIndi( TYPE_PrinterAdjustPZPunchDepthA4 );		break;	// A4.
		case TYPE_PrinterAdjustPZPunchDepthA4R:		ss_LocalData = getPrinterIndi( TYPE_PrinterAdjustPZPunchDepthA4R );		break;	// A4R.
		case TYPE_PrinterAdjustPZPunchDepthB5:		ss_LocalData = getPrinterIndi( TYPE_PrinterAdjustPZPunchDepthB5 );		break;	// B5.
		case TYPE_PrinterAdjustPZPunchDepthB5R:		ss_LocalData = getPrinterIndi( TYPE_PrinterAdjustPZPunchDepthB5R );		break;	// B5R.
		case TYPE_PrinterAdjustPZPunchDepthA5:		ss_LocalData = getPrinterIndi( TYPE_PrinterAdjustPZPunchDepthA5 );		break;	// A5.
		case TYPE_PrinterAdjustPZPunchDepthA5R:		ss_LocalData = getPrinterIndi( TYPE_PrinterAdjustPZPunchDepthA5R );		break;	// A5R.
		case TYPE_PrinterAdjustPZPunchDepth11x17:	ss_LocalData = getPrinterIndi( TYPE_PrinterAdjustPZPunchDepth11x17 );	break;	// 11x17.
		default: LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); break;
	}
	Bak_Svcs93303NowValueAdj = ss_LocalData / 10.0f;
	// キーを選択表示.
	Rbt_Svcs93303PaperSel.select( ss_select );
	// ページキー選択表示.
	Rbt_ServiceMoveGamen2.select( ss_PageSelect );
	if( False == PLBC_FuncVersionCheck::isOK_MiZe_Type2() ) {
		Key_ServiceTestCopy.showEnable( False );			// テストコピーボタン非表示.
	}
}
