void PServiceFinisherPZPunchHeightPositionAdjP2::procButtonOn( uchar option )
{
	switch( option ) {
		case BTNID_KEY_SERV_HEIGHT_PUNCH_85x14:
			setPrinterIndi( TYPE_PrinterAdjustPZPunchDepth85x14	);	// 85x14.
			ss_select = 0;
			break;
		case BTNID_KEY_SERV_HEIGHT_PUNCH_85x11:
			setPrinterIndi( TYPE_PrinterAdjustPZPunchDepth85x11	);	// 85x11.
			ss_select = 1;
			break;
		case BTNID_KEY_SERV_HEIGHT_PUNCH_85x11R:
			setPrinterIndi( TYPE_PrinterAdjustPZPunchDepth85x11R	);	// 85x11R.
			ss_select = 2;
			break;
		case BTNID_KEY_SERV_HEIGHT_PUNCH_55x85:
			setPrinterIndi( TYPE_PrinterAdjustPZPunchDepth55x85	);	// 55x85.
			ss_select = 3;
			break;
		case BTNID_KEY_SERV_HEIGHT_PUNCH_55x85R:
			setPrinterIndi( TYPE_PrinterAdjustPZPunchDepth55x85R	);	// 55x85R.
			ss_select = 4;
			break;
		case BTNID_KEY_SERV_HEIGHT_PUNCH_FOOLSCAP:
			switch( e_FLSType ) {
				case TYPE_FLSType8x13:		setPrinterIndi( TYPE_PrinterAdjustPZPunchDepth8x13	);	break;	// 8inch x 13inch.			// 8x13.
				case TYPE_FLSType8125x1325:	setPrinterIndi( TYPE_PrinterAdjustPZPunchDepth8125x1325	);	break;	// 8_1/8inch x 13_1/4inch.	// 8125x1325.
				case TYPE_FLSType85x13:		setPrinterIndi( TYPE_PrinterAdjustPZPunchDepth85x13	);	break;	// 8_1/2inch x 13inch.		// 85x13.
				case TYPE_FLSType825x13:	setPrinterIndi( TYPE_PrinterAdjustPZPunchDepth825x13	);	break;	// 8_1/4inch x 13inch.		// 825x13.
				case TYPE_FLSType220x330:	setPrinterIndi( TYPE_PrinterAdjustPZPunchDepth220x330	);	break;	// 220x330.					// 220x330.
				default:	break;
			}
			ss_select = 5;
			break;
		case BTNID_KEY_SERV_HEIGHT_PUNCH_8K:
			setPrinterIndi( TYPE_PrinterAdjustPZPunchDepth8K	);	// 8K.
			ss_select = 6;
			break;
		case BTNID_KEY_SERV_HEIGHT_PUNCH_16K:
			setPrinterIndi( TYPE_PrinterAdjustPZPunchDepth16K	);	// 16K.
			ss_select = 7;
			break;
		case BTNID_KEY_SERV_HEIGHT_PUNCH_16KR:
			setPrinterIndi( TYPE_PrinterAdjustPZPunchDepth16KR	);	// 16KR.
			ss_select = 8;
			break;
		default: PServiceFinisherPZPunchHeightPositionCom::procButtonOn( option ); break;
	}
	setupGamen();
}
