// 概要		:サービス・フィニッシャ調整・FSFN調整・パンチユニット縦位置調整・2ページ目：.
//================================================================================================
void PServiceFinisherPZPunchHeightPositionAdjP2::setupGamen( short option )
{
	short ss_LocalData = 0;							// ローカルデータ.
	Txt_Svcs93303PunchHeightPositionAdj.changeText( ( ushort )s_TTLServicePunchUnitHeightPositionAdj );
	// 親クラスの呼出し.
	PServiceFinisherAdjCom::setupGamen( option );
	Bak_Svcs93303NowValue10 = ( float )getPrinterIndi( TYPE_PrinterAdjustPZPunchDepth85x14	) / 10.0f;	// 現在値表示エリア(8.5×14).
	Bak_Svcs93303NowValue11 = ( float )getPrinterIndi( TYPE_PrinterAdjustPZPunchDepth85x11	) / 10.0f;	// 現在値表示エリア(8.5×11).
	Bak_Svcs93303NowValue12 = ( float )getPrinterIndi( TYPE_PrinterAdjustPZPunchDepth85x11R	) / 10.0f;	// 現在値表示エリア(8.5×11R).
	Bak_Svcs93303NowValue13 = ( float )getPrinterIndi( TYPE_PrinterAdjustPZPunchDepth55x85	) / 10.0f;	// 現在値表示エリア(5.5×8.5).
	Bak_Svcs93303NowValue14 = ( float )getPrinterIndi( TYPE_PrinterAdjustPZPunchDepth55x85R	) / 10.0f;	// 現在値表示エリア(5.5×8.5R).
	Bak_Svcs93303NowValue16 = ( float )getPrinterIndi( TYPE_PrinterAdjustPZPunchDepth8K	) / 10.0f;	// 現在値表示エリア(8K).
	Bak_Svcs93303NowValue17 = ( float )getPrinterIndi( TYPE_PrinterAdjustPZPunchDepth16K	) / 10.0f;	// 現在値表示エリア(16K).
	Bak_Svcs93303NowValue18 = ( float )getPrinterIndi( TYPE_PrinterAdjustPZPunchDepth16KR	) / 10.0f;	// 現在値表示エリア(16KR).
	switch( e_FLSType ) {
		case TYPE_FLSType85x13:		// 8_1/2inch x 13inch.
			Bak_Svcs93303NowValue15 = ( float )getPrinterIndi( TYPE_PrinterAdjustPZPunchDepth85x13	) / 10.0f;
			Key_Svcs93303PaperKey15.changeText( s_8Hx13T );
			break;
		case TYPE_FLSType825x13:	// 8_1/4inch x 13inch.
			Bak_Svcs93303NowValue15 = ( float )getPrinterIndi( TYPE_PrinterAdjustPZPunchDepth825x13	) / 10.0f;
			Key_Svcs93303PaperKey15.changeText( s_8Qx13T );
			break;
		case TYPE_FLSType8125x1325:	// 8_1/8inch x 13_1/4inch.
			Bak_Svcs93303NowValue15 = ( float )getPrinterIndi( TYPE_PrinterAdjustPZPunchDepth8125x1325 ) / 10.0f;
			Key_Svcs93303PaperKey15.changeText( s_88x13QT );
			break;
		case TYPE_FLSType8x13:		// 8inch x 13inch.
			Bak_Svcs93303NowValue15 = ( float )getPrinterIndi( TYPE_PrinterAdjustPZPunchDepth8x13	) / 10.0f;
			Key_Svcs93303PaperKey15.changeText( s_8x13T );
			break;
		case TYPE_FLSType220x330:	// 220x330.
			Bak_Svcs93303NowValue15 = ( float )getPrinterIndi( TYPE_PrinterAdjustPZPunchDepth220x330	) / 10.0f;
			Key_Svcs93303PaperKey15.changeText( s_220x330T );
			break;
		default:	break;
	}
	// 調整値取得
	switch( getIndiSelected() ) {
		case TYPE_PrinterAdjustPZPunchDepth85x14: ss_LocalData = getPrinterIndi( TYPE_PrinterAdjustPZPunchDepth85x14 ); break;
		case TYPE_PrinterAdjustPZPunchDepth85x11: ss_LocalData = getPrinterIndi( TYPE_PrinterAdjustPZPunchDepth85x11 ); break;
		case TYPE_PrinterAdjustPZPunchDepth85x11R: ss_LocalData = getPrinterIndi( TYPE_PrinterAdjustPZPunchDepth85x11R ); break;
		case TYPE_PrinterAdjustPZPunchDepth55x85: ss_LocalData = getPrinterIndi( TYPE_PrinterAdjustPZPunchDepth55x85 ); break;
		case TYPE_PrinterAdjustPZPunchDepth55x85R: ss_LocalData = getPrinterIndi( TYPE_PrinterAdjustPZPunchDepth55x85R ); break;
		case TYPE_PrinterAdjustPZPunchDepth85x13: ss_LocalData = getPrinterIndi( TYPE_PrinterAdjustPZPunchDepth85x13 ); break;
		case TYPE_PrinterAdjustPZPunchDepth825x13: ss_LocalData = getPrinterIndi( TYPE_PrinterAdjustPZPunchDepth825x13 ); break;
		case TYPE_PrinterAdjustPZPunchDepth8125x1325: ss_LocalData = getPrinterIndi( TYPE_PrinterAdjustPZPunchDepth8125x1325 ); break;
		case TYPE_PrinterAdjustPZPunchDepth8x13: ss_LocalData = getPrinterIndi( TYPE_PrinterAdjustPZPunchDepth8x13 ); break;
		case TYPE_PrinterAdjustPZPunchDepth220x330: ss_LocalData = getPrinterIndi( TYPE_PrinterAdjustPZPunchDepth220x330 ); break;
		case TYPE_PrinterAdjustPZPunchDepth8K: ss_LocalData = getPrinterIndi( TYPE_PrinterAdjustPZPunchDepth8K ); break;
		case TYPE_PrinterAdjustPZPunchDepth16K: ss_LocalData = getPrinterIndi( TYPE_PrinterAdjustPZPunchDepth16K ); break;
		case TYPE_PrinterAdjustPZPunchDepth16KR: ss_LocalData = getPrinterIndi( TYPE_PrinterAdjustPZPunchDepth16KR ); break;
		default: LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); break;
	}
	Bak_Svcs93303NowValueAdj = ss_LocalData / 10.0f;
	// キーを選択表示.
	Rbt_Svcs93303PaperSelP2.select( ss_select );
	// ページキー選択表示.
	Rbt_ServiceMoveGamen2.select( ss_PageSelect );
	if( False == PLBC_FuncVersionCheck::isOK_MiZe_Type2() ) {
		Key_ServiceTestCopy.showEnable( False );			// テストコピーボタン非表示.
	}
}
