// 概要		:サービス・フィニッシャ調整・FSFN調整・パンチ横位置調整 ： キー押.
//================================================================================================
void PServiceFinisherPunchWidthPositionAdj::procButtonOn( uchar option )
{
	switch( option ) {
		case BTNID_KEY_SERV_WIDTH_PUNCH_REVERSE:
			setPrinterIndi( TYPE_FS526_AD_PunchAdjCenter_All	);	// 本体.
			ss_select = 0;
			break;
		case BTNID_KEY_SERV_WIDTH_PUNCH_ADU:
			setPrinterIndi( TYPE_FS526_AD_PunchAdjCenter_PI	);	// PI.
			ss_select = 1;
			break;
		case 100:	addIndi();	break;	// +キー.
		case 101:	subIndi();	break;	// -キー.
		case 60:	// 元に戻すキー.
			switch( getIndiSelected() ) {
				case TYPE_FS526_AD_PunchAdjCenter_All: setPrinterIndi( TYPE_FS526_AD_PunchAdjCenter_All, ss_BakFinisherPunchWidthMain ); break;	// 全体.
				case TYPE_FS526_AD_PunchAdjCenter_PI: setPrinterIndi( TYPE_FS526_AD_PunchAdjCenter_PI, ss_BakFinisherPunchWidthPI ); break;	// A3.
			}
			break;
		default: PServiceFinisherAdjCom::procButtonOn( option ); break;
	}
	setupGamen();
}
