//================================================================================================
void PServiceFinisherPunchWidthPositionAdj::setupGamen( short option )
{
	short ss_LocalData = 0;							// ローカルデータ.
	Rbt_Svcs93304UnitSel.showEnable( True );
	Bak_Svcs93304NowValueArea1.showEnable( True );
	Txt_Svcs93304PunchWidthPositionAdj.changeText( ( ushort )s_SvcsPunchWidthPositionAdj );
	// 親クラスの呼出し.
	PServiceFinisherAdjCom::setupGamen( option );
	Bak_Svcs93304NowValueArea1 = ( float )getPrinterIndi( TYPE_FS526_AD_PunchAdjCenter_All	) / 10.0f;	// 現在値表示エリア(本体).
	Bak_Svcs93304NowValueArea2 = ( float )getPrinterIndi( TYPE_FS526_AD_PunchAdjCenter_PI	) / 10.0f;	// 現在値表示エリア(PI).
// comment 2015/03/05 HCLT_SunilNP [HeliosL][CQ509894] adjusting the positions.
// Comment 2017/11/29 【HCLT-Vishal】【Eagle】【制御構成変更_No.4】 Removing old function version check and else portion.
	Bak_SvcsAdjustValueArea1.changeGraphic( PB_SvcsAwNewB );		//new B
	Bak_SvcsAdjustRangeArea1.changeGraphic( PB_SvcsAwNewW );
	Bak_SvcsAdjustValueArea1.changePosition( 492,232 );
	Bak_SvcsAdjustRangeArea1.changePosition( 492, 280 );
	Inp_Svcs93304AdjValue.changePosition( 517,244 );
	Txt_SvcsFNSAdjUnit_mm.changePosition( 562,244 );
	Txt_SvcsFNSAdjRangeMinus5_0ToPlus5_0.changePosition( 504, 290 );
	Txt_SvcsFNSAdjStep01.changePosition( 512, 314 );
	Key_SvcsSetPlus1.changePosition( 568, 348 );
	Key_SvcsSetMinus1.changePosition( 492, 348 );	
	switch( getIndiSelected() ) {
		case TYPE_FS526_AD_PunchAdjCenter_All:	ss_LocalData = getPrinterIndi( TYPE_FS526_AD_PunchAdjCenter_All	); break;
		case TYPE_FS526_AD_PunchAdjCenter_PI:	ss_LocalData = getPrinterIndi( TYPE_FS526_AD_PunchAdjCenter_PI	); break;
		default: LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); break;
	}
	Inp_Svcs93304AdjValue = ss_LocalData / 10.0f;
	// キーを選択表示.
	Rbt_Svcs93304UnitSel.select( ss_select );
	if( False == PLBC_FuncVersionCheck::isOK_MiZe_Type2() ) {
		Key_ServiceTestCopy.showEnable( False );			// テストコピーボタン非表示.
	}
}
