void PServiceFinisherPunchWidthPositionAdj::procGoToPage( uchar option )
{
	switch( option )
	{
		case 99 :			// テストコピーボタン押下.
			// 調整値確定.
			fixPrinterIndi( TYPE_FS526_AD_PunchAdjCenter_All	);	// 本体.
			fixPrinterIndi( TYPE_FS526_AD_PunchAdjCenter_PI	);	// PI.
			gp_ServiceTestCopy.setRetGamen( this );		// 戻り先画面.
			nextGamen = &gp_ServiceTestCopy;	// サービス・テストコピー.
			break;
		default:
			// 親クラスの呼出し.
			PServiceFinisherAdjCom::procGoToPage( option );
			break;
	}
}

