//================================================================================================
// 概要		:サービス・フィニッシャ調整・FSFN調整・パンチレジストループ量調整(PI) ：キー押下 .
//================================================================================================
void PServiceFinisherPunchRegistLoopAdjPI::procButtonOn( uchar option )
{
	switch( option ) {
		case BTNID_KEY_SERV_PUNCH_RESIST_UPPER:				// 上段.
			if( ss_select_NT == 0 )	{ setPrinterIndi( TYPE_FS526_AD_RegLoopAdjPI_UpperTray_Normal	); }	// 上段／普通紙.
			else					{ setPrinterIndi( TYPE_FS526_AD_RegLoopAdjPI_UpperTray_Thick	); }	// 上段／厚紙1/1+/2/3/4.
			ss_select_UL = 0;
			Txt_Svcs93306UpperStandDo.changeText( s_SvcsUpperStand );
			break;
		case BTNID_KEY_SERV_PUNCH_RESIST_LOWER:				// 下段.
			if( ss_select_NT == 0 )	{ setPrinterIndi( TYPE_FS526_AD_RegLoopAdjPI_LowerTray_Normal	); }	// 下段／普通紙.
			else					{ setPrinterIndi( TYPE_FS526_AD_RegLoopAdjPI_LowerTray_Thick	); }	// 下段／厚紙1/1+/2/3/4.
			ss_select_UL = 1;
			Txt_Svcs93306UpperStandDo.changeText( s_SvcsLowerStand );
			break;
		case BTNID_KEY_SERV_PUNCH_RESIST_PNORMAL:			// 項目選択キー(普通紙).
			if( ss_select_UL == 0 )	{ setPrinterIndi( TYPE_FS526_AD_RegLoopAdjPI_UpperTray_Normal	); }	// 上段／普通紙.
			else					{ setPrinterIndi( TYPE_FS526_AD_RegLoopAdjPI_LowerTray_Normal	); }	// 下段／普通紙.
			ss_select_NT = 0;
			break;
		case BTNID_KEY_SERV_PUNCH_RESIST_P1TO4:				// 項目選択キー(厚紙1/1+/2/3/4).
			if( ss_select_UL == 0 )	{ setPrinterIndi( TYPE_FS526_AD_RegLoopAdjPI_UpperTray_Thick	); }	// 上段／厚紙1/1+/2/3/4.
			else					{ setPrinterIndi( TYPE_FS526_AD_RegLoopAdjPI_LowerTray_Thick	); }	// 下段／厚紙1/1+/2/3/4.
			ss_select_NT = 1;
			break;
		case 100:	addIndi();	break;	// +キー.
		case 101:	subIndi();	break;	// -キー.
		case 60:	// 元に戻すキー.
			switch( getIndiSelected() ) {
				case TYPE_FS526_AD_RegLoopAdjPI_UpperTray_Normal:	setPrinterIndi( TYPE_FS526_AD_RegLoopAdjPI_UpperTray_Normal,ss_BakFinisherPunchRegistLoopPIUpperNormal );	break;
				case TYPE_FS526_AD_RegLoopAdjPI_UpperTray_Thick:	setPrinterIndi( TYPE_FS526_AD_RegLoopAdjPI_UpperTray_Thick, ss_BakFinisherPunchRegistLoopPIUpperThick );	break;
				case TYPE_FS526_AD_RegLoopAdjPI_LowerTray_Normal:	setPrinterIndi( TYPE_FS526_AD_RegLoopAdjPI_LowerTray_Normal,ss_BakFinisherPunchRegistLoopPILowerNormal );	break;
				case TYPE_FS526_AD_RegLoopAdjPI_LowerTray_Thick:	setPrinterIndi( TYPE_FS526_AD_RegLoopAdjPI_LowerTray_Thick, ss_BakFinisherPunchRegistLoopPILowerThick );	break;
			}
			break;
		default: PServiceFinisherAdjCom::procButtonOn( option ); break;
	}
	setupGamen();
}
