void PServiceFinisherZFoldFirstAdj::procButtonOn( uchar option )
{
	switch( option ) {
		case BTNID_KEY_SERV_NFNS_Z_FOLD_KEY_00:
			setPrinterIndi( TYPE_FS526_AD_ZUFirstZFold_All	);	// 全体.
			ss_select = 0;
			break;
		case BTNID_KEY_SERV_NFNS_Z_FOLD_KEY_01:
			setPrinterIndi( TYPE_FS526_AD_ZUFirstZFold_A3SEF	);	// A3.
			ss_select = 1;
			break;
		case BTNID_KEY_SERV_NFNS_Z_FOLD_KEY_02:
			setPrinterIndi( TYPE_FS526_AD_ZUFirstZFold_B4SEF	);	// B4.
			ss_select = 2;
			break;
		case BTNID_KEY_SERV_NFNS_Z_FOLD_KEY_03:
			setPrinterIndi( TYPE_FS526_AD_ZUFirstZFold_11x17SEF	);	// 11x17.
			ss_select = 3;
			break;
		case BTNID_KEY_SERV_NFNS_Z_FOLD_KEY_04:
			setPrinterIndi( TYPE_FS526_AD_ZUFirstZFold_85x14SEF	);	// 8.5x14.
			ss_select = 4;
			break;
		case BTNID_KEY_SERV_NFNS_Z_FOLD_KEY_05:
			setPrinterIndi( TYPE_FS526_AD_ZUFirstZFold_8KSEF	);	// 8K.
			ss_select = 5;
			break;
		case 100:	addIndi();	break;	// +キー.
		case 101:	subIndi();	break;	// -キー.
		case 60:	// 元に戻すキー.
			switch( getIndiSelected() ) {
				case TYPE_FS526_AD_ZUFirstZFold_All:		setPrinterIndi( TYPE_FS526_AD_ZUFirstZFold_All, ss_BakFinisherZFoldFirst00 );		break;
				case TYPE_FS526_AD_ZUFirstZFold_A3SEF:		setPrinterIndi( TYPE_FS526_AD_ZUFirstZFold_A3SEF, ss_BakFinisherZFoldFirst01 );		break;
				case TYPE_FS526_AD_ZUFirstZFold_B4SEF:		setPrinterIndi( TYPE_FS526_AD_ZUFirstZFold_B4SEF, ss_BakFinisherZFoldFirst02 );		break;
				case TYPE_FS526_AD_ZUFirstZFold_11x17SEF:	setPrinterIndi( TYPE_FS526_AD_ZUFirstZFold_11x17SEF, ss_BakFinisherZFoldFirst03 );	break;
				case TYPE_FS526_AD_ZUFirstZFold_85x14SEF:	setPrinterIndi( TYPE_FS526_AD_ZUFirstZFold_85x14SEF, ss_BakFinisherZFoldFirst04 );	break;
				case TYPE_FS526_AD_ZUFirstZFold_8KSEF:		setPrinterIndi( TYPE_FS526_AD_ZUFirstZFold_8KSEF, ss_BakFinisherZFoldFirst05 );		break;
				default:		break;
			}
			break;
		default: PServiceFinisherAdjCom::procButtonOn( option ); break;
	}
	setupGamen();
}
