		case TYPE_FS526_AD_ZUFirstZFold_A3SEF:		ss_LocalData = getPrinterIndi( TYPE_FS526_AD_ZUFirstZFold_A3SEF	);	break;
		case TYPE_FS526_AD_ZUFirstZFold_B4SEF:		ss_LocalData = getPrinterIndi( TYPE_FS526_AD_ZUFirstZFold_B4SEF	);	break;
