//================================================================================================
// 概要		:サービス・フィニッシャ調整・FSFN調整・第1三つ折り位置調整 ： キー押下.
//================================================================================================
void PServiceFinisherThreeFoldPosiAdj1::procButtonOn( uchar option )
{
	switch( option ) {
		case BTNID_KEY_SERV_THREE_FOLD_All:
			setPrinterIndi( TYPE_FS526_AD_TriFoldPositionAdj_All	);	// (All).
			ss_select = 0;
			break;
		case BTNID_KEY_SERV_THREE_FOLD_A4R:
			setPrinterIndi( TYPE_FS526_AD_TriFoldPositionAdj_A4SEF	);	// (A4R)..
			ss_select = 1;
			break;
		case BTNID_KEY_SERV_THREE_FOLD_85x11:
			setPrinterIndi( TYPE_FS526_AD_TriFoldPositionAdj_85x11SEF	);	// (8.5×11R)..
			ss_select = 2;
			break;
		case BTNID_KEY_SERV_THREE_FOLD_16K:
			setPrinterIndi( TYPE_FS526_AD_TriFoldPositionAdj_16KSEF	);	// (16KR)..
			ss_select = 3;
			break;
		case 100:	addIndi();	break;	// +キー.
		case 101:	subIndi();	break;	// -キー.
		case 60:	// 元に戻すキー.
			switch( getIndiSelected() ) {
				case TYPE_FS526_AD_TriFoldPositionAdj_All:		setPrinterIndi( TYPE_FS526_AD_TriFoldPositionAdj_All, ss_BakFinisherThreeFoldPosiAdj00 );		break;	// (All).
				case TYPE_FS526_AD_TriFoldPositionAdj_A4SEF:	setPrinterIndi( TYPE_FS526_AD_TriFoldPositionAdj_A4SEF, ss_BakFinisherThreeFoldPosiAdj01 );		break;	// (A4R).
				case TYPE_FS526_AD_TriFoldPositionAdj_85x11SEF:	setPrinterIndi( TYPE_FS526_AD_TriFoldPositionAdj_85x11SEF, ss_BakFinisherThreeFoldPosiAdj02 );	break;	// (8.5×11R).
				case TYPE_FS526_AD_TriFoldPositionAdj_16KSEF:	setPrinterIndi( TYPE_FS526_AD_TriFoldPositionAdj_16KSEF, ss_BakFinisherThreeFoldPosiAdj03 );	break;	// (16KR).
				default:		break;
			}
			break;
		default: PServiceFinisherAdjCom::procButtonOn( option ); break;
	}
	setupGamen();
}
