//================================================================================================
void PServiceFinisherThreeFoldPosiAdj1::setupGamen( short option )
{
	float f_LocalData = 0;							// ローカルデータ.
	// 親クラスの呼出し.
	PServiceFinisherAdjCom::setupGamen( option );
	Bak_SvcsThreeFoldPosiNowValueArea0 = ( float )getPrinterIndi( TYPE_FS526_AD_TriFoldPositionAdj_All	) / 10.0f;	// 現在値表示エリア((All).
	Bak_SvcsThreeFoldPosiNowValueArea1 = ( float )getPrinterIndi( TYPE_FS526_AD_TriFoldPositionAdj_A4SEF	) / 10.0f;	// 現在値表示エリア((A4R).
	Bak_SvcsThreeFoldPosiNowValueArea2 = ( float )getPrinterIndi( TYPE_FS526_AD_TriFoldPositionAdj_85x11SEF	) / 10.0f;	// 現在値表示エリア((8.5×11R).
	Bak_SvcsThreeFoldPosiNowValueArea3 = ( float )getPrinterIndi( TYPE_FS526_AD_TriFoldPositionAdj_16KSEF	) / 10.0f;	// 現在値表示エリア((16KR).
	switch( getIndiSelected() ) {
		case TYPE_FS526_AD_TriFoldPositionAdj_All:		f_LocalData = ( float )getPrinterIndi( TYPE_FS526_AD_TriFoldPositionAdj_All	); break;	// (All).
		case TYPE_FS526_AD_TriFoldPositionAdj_A4SEF:	f_LocalData = ( float )getPrinterIndi( TYPE_FS526_AD_TriFoldPositionAdj_A4SEF	); break;	// (A4R).
		case TYPE_FS526_AD_TriFoldPositionAdj_85x11SEF:	f_LocalData = ( float )getPrinterIndi( TYPE_FS526_AD_TriFoldPositionAdj_85x11SEF	); break;	// (8.5×11R).
		case TYPE_FS526_AD_TriFoldPositionAdj_16KSEF:	f_LocalData = ( float )getPrinterIndi( TYPE_FS526_AD_TriFoldPositionAdj_16KSEF	); break;	// (16KR).
		default: LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); break;
	}
	Inp_SvcsThreeFoldPosiAdjValue = f_LocalData / 10.0f;
	// キーを選択表示.
	Rbt_SvcsThreeFoldPosiItemSel.select( ss_select );
// comment 2015/02/12 HCLT_Chandrasekar  [Helios] [CQ 509894] Increased size of  Backgroundparts to display "Adjust value" in the input areas.
// Comment 2017/11/29 【HCLT-Vishal】【Eagle】【制御構成変更_No.4】 Removing old function version check and else portion.
	Bak_SvcsAdjustValueArea1.changeGraphic( PB_SvcsAwNewB );
    Bak_SvcsAdjustRangeArea1.changeGraphic( PB_SvcsAwNewW );
    Bak_SvcsAdjustValueArea1.changePosition( 492,232 );
    Bak_SvcsAdjustRangeArea1.changePosition( 492, 280 );
    Txt_ServiceAdjustM10ToP10.changePosition( 504, 292 );
    Txt_SvcsFNSAdjStep01.changePosition( 512, 314 );
    Key_SvcsSetPlus1.changePosition( 568, 348 );
    Key_SvcsSetMinus1.changePosition( 492, 348 );
	Txt_SvcsFNSAdjUnit_mm.changePosition( 562,244 );
	Inp_SvcsThreeFoldPosiAdjValue.changePosition( 517, 244 );
	if( False == PLBC_FuncVersionCheck::isOK_MiZe_Type2() ) {
		Key_ServiceTestCopy.showEnable( False );			// テストコピーボタン非表示.
	}
}
