// ===============================================================================================
//	［クラス］	PServiceFinisherCoverSheetTraySizeAdj : 93302カバーシートトレイサイズ調整
//	概要     : 通常ボタン（押された）メッセージ処理
// ===============================================================================================
void PServiceFinisherCoverSheetTraySizeAdj::procButtonOn( uchar option )
{
	switch( option ) {
		// 上段トレイキー押下時.
		case	BTNID_KEY_SERV_COVER_SHEET_TRAY_SIZE_UPPER:		us_CovSheTraySizeAdjFlg = BTNID_KEY_SERV_COVER_SHEET_TRAY_SIZE_UPPER;		break;	// 下段トレイキー押下時.
		case	BTNID_KEY_SERV_COVER_SHEET_TRAY_SIZE_LOWER:		us_CovSheTraySizeAdjFlg = BTNID_KEY_SERV_COVER_SHEET_TRAY_SIZE_LOWER;		break;	// A4キー押下時.
		case	BTNID_KEY_SERV_COVER_SHEET_TRAY_SIZE_SIZE_A4:	us_CobSheTraySizePaperSize = BTNID_KEY_SERV_COVER_SHEET_TRAY_SIZE_SIZE_A4;	break;	//8_1/2x11キー押下時.
		case	BTNID_KEY_SERV_COVER_SHEET_TRAY_SIZE_SIZE_8511:	us_CobSheTraySizePaperSize = BTNID_KEY_SERV_COVER_SHEET_TRAY_SIZE_SIZE_8511; break;
		default: break;
	}
	// ファンクションコード設定.
	if( BTNID_KEY_SERV_COVER_SHEET_TRAY_SIZE_UPPER == option || BTNID_KEY_SERV_COVER_SHEET_TRAY_SIZE_LOWER == option
	    || BTNID_KEY_SERV_COVER_SHEET_TRAY_SIZE_SIZE_A4 == option || BTNID_KEY_SERV_COVER_SHEET_TRAY_SIZE_SIZE_8511 == option ) {
		// 調整状態を未調整(待機中)に設定.
		us_AdjState = PNLD_SvcsAdjustStateWait;
		if( BTNID_KEY_SERV_COVER_SHEET_TRAY_SIZE_UPPER == us_CovSheTraySizeAdjFlg
		    // 上段＆A4.
		    && BTNID_KEY_SERV_COVER_SHEET_TRAY_SIZE_SIZE_A4 == us_CobSheTraySizePaperSize ) {
			setFunctionCode( TYPD_FNC_CoverSheetUpper_A4 );	// ファンクション設定.
		} else if( BTNID_KEY_SERV_COVER_SHEET_TRAY_SIZE_UPPER == us_CovSheTraySizeAdjFlg
		           && BTNID_KEY_SERV_COVER_SHEET_TRAY_SIZE_SIZE_8511 == us_CobSheTraySizePaperSize ) {
			// 上段＆(8_1/2x11).
			setFunctionCode( TYPD_FNC_CoverSheetUpper_Letter );	// ファンクション設定.
		} else if( BTNID_KEY_SERV_COVER_SHEET_TRAY_SIZE_LOWER == us_CovSheTraySizeAdjFlg
		           && BTNID_KEY_SERV_COVER_SHEET_TRAY_SIZE_SIZE_A4 == us_CobSheTraySizePaperSize ) {
			// 下段＆A4.
			setFunctionCode( TYPD_FNC_CoverSheetLower_A4 );	// ファンクション設定.
		} else {
			// 下段＆(8_1/2x11).
			setFunctionCode( TYPD_FNC_CoverSheetLower_Letter );	// ファンクション設定.
		}
	}
	// 表示画面のセットアップ.
	setupGamen();
}
// ===============================================================================================
//	［クラス］	PServiceFinisherCoverSheetTraySizeAdj : 93302カバーシートトレイサイズ調整
//	概要     : サービス・フィニッシャ調整 : スタートキー押下処理
// ===============================================================================================
void PServiceFinisherCoverSheetTraySizeAdj::procStart( uchar option )
{
	us_AdjState = PNLD_SvcsAdjustStateExec;	// 実行中.
	PServiceFunctionEnableStartCom::procStart( TYPE_FunctionStartTypeNORMAL );
}
// ===============================================================================================
//	［クラス］	PServiceFinisherCoverSheetTraySizeAdj : 93302カバーシートトレイサイズ調整
//	概要     : 設定終了（ＯＫ）ボタン押下メッセージ処理
// ===============================================================================================
void PServiceFinisherCoverSheetTraySizeAdj::procOk( uchar option )
{
	nextGamen = &gp_SvcsFinisherAdjMenu;	// FSFN調整メニューへ遷移.
}
// ===============================================================================================
//	［クラス］	PServiceFinisherCoverSheetTraySizeAdj : 93302カバーシートトレイサイズ調整
//	概要     : 表示画面のセットアップ
// ===============================================================================================
void PServiceFinisherCoverSheetTraySizeAdj::setupGamen( short option )
{
	// 親クラスを呼出す.
	PServiceFunctionEnableStartCom::setupGamen( option );
	// キー状態表示.
	Rbt_Svcs93302TraySel.select( us_CovSheTraySizeAdjFlg );				// トレイ.
	Rbt_Svcs93302TraySelSize.select( static_cast<short>( us_CobSheTraySizePaperSize-2 ) );	// 用紙サイズ.
	// メッセージ表示エリア(1行目)を表示状態設定する.
	Txt_SvcsMsgAreaFirst38.showEnable( True ) ;
	// メッセージ表示エリア(2行目)を表示状態設定する.
	Txt_SvcsMsgAreaSecond38.showEnable( True ) ;
	// メッセージ表示エリアに文字列を表示する(カバーシートトレイサイズ調整用メッセージ).
	Txt_SvcsMsgAreaFirst38.changeText( s_MSGSvcsMsgPostInserterTraySize );	// メッセージ表示内容(1行目).
	Txt_SvcsMsgAreaSecond38.changeText( s_SvcsMsgAdjStart );				// メッセージ表示内容(2行目).
	TEXT_ID uc_ptr2 = NULL ;	// 結果表示文字.
	// 調整状態で分岐.
	switch( us_AdjState ) {
		case	PNLD_SvcsAdjustStateExec:	uc_ptr2 = s_SvcsExecNow ;			break ;		// 実行中・・・.
		case	PNLD_SvcsAdjustStateOk:		uc_ptr2 = s_SvcsFunctionResultOk ;	break ;		// OK.
		case	PNLD_SvcsAdjustStateNg:		uc_ptr2 = s_SvcsFunctionResultNg ;	break ;		// NG.
		default: uc_ptr2 = s_SvcsResultValue4 ; break ;	// ---.
	}
	Txt_Svcs93302Result.changeText( uc_ptr2 );			// 調整結果	表示.
	// ファンクション実行可能チェック.
	APIC_FeedTray* c_pFeedTray = PnlComGetFeedTray();				// 給紙トレイ情報（ＡＰＩ）・インスタンス取得.
	TYPE_PaperStatus	e_paperStatus = TYPE_PaperStatusEmpty;		// 用紙状態.
	// ファンクションコードが上段トレイキーの場合.
	if( TYPD_FNC_CoverSheetUpper_A4     == getFunctionCode() ||
	    TYPD_FNC_CoverSheetUpper_Letter == getFunctionCode() ) {
		e_paperStatus = c_pFeedTray->getPaperStatus( TYPE_FeedTrayPI1 );	// PIトレイ(上段)用紙状態取得.
	} else {
		e_paperStatus = c_pFeedTray->getPaperStatus( TYPE_FeedTrayPI2 );	// PIトレイ(下段)用紙状態取得.
	}
	if( TYPE_PaperStatusEmpty != e_paperStatus ) {	// ペーパーエンプティ以外.
		PServiceFunctionCom::searchWithoutPaper_ENG( option );	// ファンクション画面共通処理.
	} else {	// ペーパーエンプティ.
		PServiceFunctionEnableStartCom::setupGamen( option );	// 親クラスを呼ぶ.
		printLEDControl( False );	// プリントキー・バックライト赤.
	}
}
// ===============================================================================================
//	［クラス］	PServiceFinisherCoverSheetTraySizeAdj : 93302カバーシートトレイサイズ調整
//	概要	 : サービス・フィニッシャ調整 : 調整(ファンクション)実行完了(通知受信)処理
// ===============================================================================================
void PServiceFinisherCoverSheetTraySizeAdj::procFunctionEnd( uchar option )
{
	ushort	us_funcResult = 0;	// ファンクション実行結果.
	ushort	us_nowFuncCode = 0;	// 保持しているファンクションコード取得用.
	ushort	us_code = 0;		// ファンクションコード.
	// ファンクションコードを元にファンクション実行結果を取得.
	us_nowFuncCode = getFunctionCode();			// 保持しているファンクションコードを取得.
	us_code = static_cast<ushort>( toFunctionCode( us_nowFuncCode ) );	// Apiコール時のファンクションコードに変換.
	// ファンクション実行結果を受け取る.
	us_funcResult = pc_SystemControl.getFunctionResult( us_code ) ;
	switch( us_funcResult ) {	// ファンクション実行結果で分岐.
		case	TYPD_FNC_OK: us_AdjState = PNLD_SvcsAdjustStateOk; break ;	// 結果:OK.
		case	TYPD_FNC_NG: us_AdjState = PNLD_SvcsAdjustStateNg; break;	// 結果:NG.
		default:	// 不正値.
			// 結果なしの場合.
			// 不正値の場合.
			//		→結果:NG扱い(暫定).
			us_AdjState = PNLD_SvcsAdjustStateNg;
			break;
	}
	setupGamen();
}
// ===============================================================================================
//	［クラス］	PServiceFinisherCoverSheetTraySizeAdj : 93302カバーシートトレイサイズ調整
//	概要	 : 画面終了処理
// ===============================================================================================
void PServiceFinisherCoverSheetTraySizeAdj::endGamen()
{
	PServiceFunctionEnableStartCom::endGamen();
	// ファンクション実行に必要として行った設定等を戻す.
	// →保持しているファンクションコードのクリア.
	setFunctionCode( TYPD_FNC_NotSet ) ;	// ファンクションコード未設定.
	pc_SystemControl.FunctionCodeClear() ;
}
