//================================================================================================.
// 概要		:サービス・	マシン調整・PPM制御 : 変数初期化用.
//================================================================================================.
void PServicePPMManageChoice::init_value()
{
	// CommonAPIから薄紙PPMチョイス値を取得.
	short ss_ThinPPM = PnlComGetPrinterServiceSetting()->getPrinterAdjust( TYPE_PrinterAdjustThinPPM );

	if( 0 == ss_ThinPPM ) {
		uc_select = BTNID_ServicePPMManageChoice70Percent;
	} else {
		uc_select = BTNID_ServicePPMManageChoice100Percent;
	}
}

//================================================================================================.
// 概要		:サービス・	マシン調整・PPM制御 : 選択ボタン押下.
//================================================================================================.
void PServicePPMManageChoice::procButtonOn( uchar option )
{
	uc_select = option;

	// 表示画面のセットアップ.
	setupGamen();
}
//================================================================================================.
// 概要		:サービス・	マシン調整・PPM制御 : OKキー押下.
//================================================================================================.
void PServicePPMManageChoice::procOk( uchar option )
{
	// CommonAPIに選択されている薄紙PPMを設定.
	short ss_ThinPPM;
	if( BTNID_ServicePPMManageChoice70Percent == uc_select ) {
		ss_ThinPPM = 0;
	} else {
		ss_ThinPPM = 1;
	}

	PnlComGetPrinterServiceSetting()->setPrinterAdjust( TYPE_PrinterAdjustThinPPM, ss_ThinPPM );
// Comment 2017/01/07 【HCLT-Vishnu】【IT5_4.1】【機器構成変更_No.8】Adding PPM制御チョイス key to second page.
#ifdef DEF_MINERVASBK_CUS
	nextGamen = &gp_ServiceMachineAdjustModeMenu2P;				// サービス・マシン調整・モードメニュー 2nd page.
#else // DEF_MINERVASBK_CUS.
// Comment 2017/11/29 【HCLT-Vishal】【Eagle】【制御構成変更_No.4】 Removing old function version check and else portion.
	nextGamen = &gp_ServiceMachineAdjustModeMenu2P;			// サービス・マシン調整・モードメニュー 2nd page.
#endif // DEF_MINERVASBK_CUS.
}
