//====================================================================================================.
// 概要			: サービス・	マシン調整・ｽｷｬﾅｰﾎｰﾑ移動
// 戻り値		: None.
// 備考			: Button Handling.
// 作成者		: HCLT- Vinod.
// レビュー		: None.
//====================================================================================================.
void  PServiceScannerHomeMove::procButtonOn( uchar option )
{
// comment 2017/01/31 【HCLT-Vinod】【IT5_4.2】 【AR1038187】 To make scanner slider to home position.
//	APIC_SystemServiceFunction* pc_ServFunc = APIC_SystemServiceFunction::newInstance();
	ENGC_ScannerImpColor* pc_ScannerImpColor = ENGC_ScannerImpColor::newInstance();
// comment 2017/01/31 【HCLT-Vinod】【IT5_4.2】 【AR1038187】 To make scanner slider to home position.
//	if ( NULL == pc_ServFunc ) {
	if ( NULL == pc_ScannerImpColor ) {
		LOGF_debug_PutEventLog	( LOGF_DEBUG_EVENT_KIND_ALL, 0, 3, "Assert Failed!" );
		return;
	}
	switch( option ) {
		case BTNID_ServiceHomeMoveStart:	
			{
// comment 2017/01/31 【HCLT-Vinod】【IT5_4.2】 【AR1038187】 To make scanner slider to home position.
//				ushort us_Code  = toFunctionCode( TYPD_FNC_IRHomePositionMove);
//				ushort us_nowParameter = toParameter( TYPD_FNC_IRHomePositionMove );
//				pc_ServFunc -> req_startFunction( us_Code, us_nowParameter, ans_startHomePositionMove ); // Call back.
				ushort us_Code  = TYPD_FNC_IRHomePositionMove >> 8;
				ushort us_nowParameter = TYPD_FNC_IRHomePositionMove & 0xFF;
				pc_ScannerImpColor -> req_startFunction( us_Code, us_nowParameter, ans_startHomePositionMove ); // Call back.
			}
			break;
		default:
			break;
	}
	setupGamen( option );	
}
void PServiceScannerHomeMove::procReset( uchar option )
{
	// スタートキーが押下されていなければ効かせる.
	if( m_bl_ScannerHomeMove == False ) {
		PServiceNoFunctionCodeCom::procReset( option );
	} else {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
	}
}
