// comment 2022/10/06 FPT_LinhNV46 [IT6_2.3] [RQ-940]メディアセンサ学習機能.
//============================================================================================.
// PServiceLearningFuncMode: 90509 サービス・マシン調整・紙種学習機能ﾓｰﾄﾞ: 画面開始処理.
//============================================================================================.
struct TYPS_ServiceLearningFuncModePaperTypeInfo {
	uchar							uc_optionPaperType;				// ID key.
	TYPE_PaperType					e_PaperType;					// PaperType.
	TYPE_PrinterAdjust				e_PrinterAdjust;				// プリンタ調整.
	TYPE_PrinterInfoTypeFloat		e_PrinterInfoTypeFloat;			// プリンタ情報項目.
};

static const TYPS_ServiceLearningFuncModePaperTypeInfo tbl_ServiceLearningFuncModePaperTypeInfo[] {
	{ BTNID_ServiceCorrect_Thin,				TYPE_PaperTypeThin1,		TYPE_PrinterAdjustBasicWeightThresholdAdjustThin,			TYPE_PrinterInfoTypeFloatBasicWeightShiftThin		},		// 薄紙(1).
	{ BTNID_ServiceCorrect_PlainPaper,			TYPE_PaperTypeNormal,		TYPE_PrinterAdjustBasicWeightThresholdAdjustNormal,			TYPE_PrinterInfoTypeFloatBasicWeightShiftNormal		},		// 普通紙.
	{ BTNID_ServiceCorrect_PlainPaperPlus,		TYPE_PaperTypeNormalPlus,	TYPE_PrinterAdjustBasicWeightThresholdAdjustNormalPlus,		TYPE_PrinterInfoTypeFloatBasicWeightShiftNormalPlus	},		// 普通紙+.
	{ BTNID_ServiceCorrect_Thick1,				TYPE_PaperTypeThick1,		TYPE_PrinterAdjustBasicWeightThresholdAdjustThick1,			TYPE_PrinterInfoTypeFloatBasicWeightShiftThick1		},		// 厚紙1.
	{ BTNID_ServiceCorrect_Thick1Plus,			TYPE_PaperTypeThick1Plus,	TYPE_PrinterAdjustBasicWeightThresholdAdjustThick1Plus,		TYPE_PrinterInfoTypeFloatBasicWeightShiftThick1Plus	},		// 厚紙1+.
	{ BTNID_ServiceCorrect_Thick2,				TYPE_PaperTypeThick2,		TYPE_PrinterAdjustBasicWeightThresholdAdjustThick2,			TYPE_PrinterInfoTypeFloatBasicWeightShiftThick2		},		// 厚紙2.
	{ BTNID_ServiceCorrect_Thick3,				TYPE_PaperTypeThick3,		TYPE_PrinterAdjustBasicWeightThresholdAdjustThick3,			TYPE_PrinterInfoTypeFloatBasicWeightShiftThick3		},		// 厚紙3.
	{ BTNID_ServiceCorrect_Thick4,				TYPE_PaperTypeThick4,		NULL,														NULL												},		// 厚紙4.
	{ BTNID_ServiceCorrect_Envelope,			TYPE_PaperTypeEnvelope,		NULL,														NULL												},		// 封筒.
	{ BTNID_ServiceCorrect_OHP,					TYPE_PaperTypeOHP,			NULL,														NULL												},		// ＯＨＰ.
	{ BTNID_ServiceCorrect_Recycled,			TYPE_PaperRecycle1,			NULL,														NULL												},		// 再生紙(1).
// comment 2023/02/02 FPT_LinhNV46 [IT6_2.3] [RQ-940_3]紙種自動検知対応.	
	{ BTNID_ServiceCorrect_Color,				TYPE_PaperTypeColor,		NULL,														NULL												},		// 色紙キー.
	{ BTNID_ServiceCorrect_UserPaper07,			TYPE_PaperTypeUser7,		NULL,														NULL												},		// ユーザー紙7（コート紙用).
};
ushort 				PServiceLearningFuncMode::m_us_ResultDetected = 0;
TYPE_FeedTray 		PServiceLearningFuncMode::m_e_FeedTray = TYPE_FeedTrayUnselect;

// 画面開始処理.
void PServiceLearningFuncMode::startGamen()
{
	PBasicMessageProc::startGamen();
	initValue();
// comment 2023/03/23 FPT.DungPT53 [IT6_2.3] [OP_BTS-42360] Comment out the code that hides the display of the button [コート紙] for EagleLIII, EagleHIII, EagleLBKIII, EagleHBKIII.
//	TYPE_MachineType e_MachineType = PnlComGetSystemInfo()->getMachineType();
//	if ( ( TYPE_MachineTypeEagleZplus != e_MachineType ) && ( TYPE_MachineTypeEagleBKZplus != e_MachineType ) ) {
//		Key_ServiceCorrectUserPaper07.showEnable( False );				// ユーザー紙7キー.
//	}
}

// 初期設定.
void PServiceLearningFuncMode::initValue()
{
	m_ss_printNum = 1; 													// 置数０を入力させない為、１を初期値とする.
	m_bl_SetNumOn = False;												// 通紙枚数キーOFF.
	m_bl_DirectOn = True;												// ダイレクト入力ON.
	m_bl_SetPaperBrandOn = False;										// 用紙銘柄入力キーOFF.
	m_us_ResultDetected = 0;											// Result from call back.
	m_e_FeedTray = TYPE_FeedTrayUnselect;								// Data Tray from call back.
	m_bl_isWaitPrint = False; 											// スタートボタン押下後、コールバックが返るまでTrueにするフラグ.
	m_ss_LearningFuncModeState = TYPD_ServiceLearningFuncModeInit;	    // ファンクションコードを設定.
	m_e_DetectedPaperType = TYPE_PaperTypeNormal;						// Results PaperType 「メディア検知学習用通紙ファンクション」.
	m_e_CorrectPaperType = TYPE_PaperTypeNormal;						// PaperType 「メディア検知学習ファンクション」.
	m_us_MediaDetectionID = 0;											// メディア検知ID.
	m_sc_SelectPaperType = -1;
	m_bl_ShowWeightDetect = False;
	m_bl_ShowEnvDetect = False;
	m_bl_IsWrongBasisWeight = False;
	m_bl_IsWrongEnv = False;
	m_bl_IsWrongPaperType = False;
// comment 2023/05/22 FPT.ThinhND40 [IT6_2.3][OP_BTS-43559] Learning function, does not allow to select correct paper twice.
	m_bl_IsSelectCorrectPaper = False;
	clearString( ( uchar* )m_sc_PaperBrand, TYPD_FormBrandInformation_MAX_LENGTH );
}

// 表示部品のセットアップ.
void PServiceLearningFuncMode::setupGamen( short ss_option )
{
	PServiceFunctionCom::setupGamen( ss_option );
	if( m_sc_PaperBrand[0] != '\0' ) {
		Key_ServiceLearningFuncModeSave.showEnable( True );								// 保存キー.
	} else {
		Key_ServiceLearningFuncModeSave.showEnable( False );							// 保存キー.
	}
	printLEDControl( isEnableStart() );
	if( m_ss_LearningFuncModeState == TYPD_ServiceLearningFuncModeInit ){	
		setupGamenModeInit();
		return;
	}
	setupGamenModeGetResults();
}

// メディア検知学習用通紙ファンクション.
void PServiceLearningFuncMode::setupGamenModeInit()
{
	Key_NumberOfSheets.set( m_ss_printNum, m_bl_SetNumOn == True ? False : True );	// 通紙枚数(テストプリント出力枚数).
	Key_NumberOfSheets.select( m_bl_SetNumOn );										// 通紙枚数キー反転.
	Grp_ServiceNumberOfSheets.showEnable( True );									// 通紙枚数.
	Rbt_ServiceCorrectPaperType.showEnable( False );								// 正解紙種選択キー.
	Grp_ServicePaperBrand.showEnable( False );										// 用紙銘柄入力.
	Grp_ServiceLearningFuncMode_Item.showEnable( False );
	Grp_ServiceBasisWeightDetectionResult_Status.showEnable( False );				// 坪量検知結果.
	Grp_ServiceBasisWeightShiftCorrectionSteps_Status.showEnable( False );			// 坪量ｼﾌﾄ量/補正STEP数 .
	Grp_ServiceEnvelopeDetectionResult_Status.showEnable( False );					// 封筒検知結果.
	Grp_ServiceEnvelopeShiftVoltageCorrectionSteps_Status.showEnable( False );		// 封筒ｼﾌﾄ電圧/補正STEP数.
	Grp_ServiceRecycledPaperJugmentThresholdSteps_Status.showEnable( False );		// 再生紙判別閾値STEP数.
	Grp_ServicePlainPaperAdjustmentSteps_Status.showEnable( False );				// 普通紙識別調整STEP数.
	Grp_ServiceColorPaperJugmentThresholdSteps_Status.showEnable( False );			// 色紙判別閾値STEP数.
// 画面上に手差し、またはトレイ1に用紙をセットするように促すメッセージを表示する。
	if( isManualOrTray1Useable() ){
		Txt_ServiceMsgInputPaperManualOrTray1.showEnable( False );
	} else {
		Txt_ServiceMsgInputPaperManualOrTray1.showEnable( True );
	}
}

// メディア検知学習ファンクション.
void PServiceLearningFuncMode::setupGamenModeGetResults()
{
	Txt_ServiceMsgInputPaperManualOrTray1.showEnable( False );
	Grp_ServiceNumberOfSheets.showEnable( False );									// 通紙枚数.
	Grp_ServicePaperBrand.showEnable( True );										// 用紙銘柄入力.
	Key_PaperBrandInput.select( m_bl_SetPaperBrandOn );								// 用紙銘柄入力キー.
	if( m_bl_SetPaperBrandOn == True || m_sc_PaperBrand[0] != '\0' ){
		Btx_PaperBrand.showEnable( True );
		Btx_PaperBrand.changeExternalText( ( uchar* )m_sc_PaperBrand, sizeof( m_sc_PaperBrand ) );		// 用紙銘柄入力.
	} else {
		Btx_PaperBrand.showEnable( False );
	}
	Grp_ServiceLearningFuncMode_Item.showEnable( True );
	Rbt_ServiceCorrectPaperType.showEnable( True );									// 正解紙種選択キー.
	Rbt_ServiceCorrectPaperType.select( m_sc_SelectPaperType );
	Grp_ServiceBasisWeightDetectionResult_Status.showEnable( m_bl_ShowWeightDetect );						// 坪量検知結果.
	Grp_ServiceEnvelopeDetectionResult_Status.showEnable( m_bl_ShowEnvDetect );								// 封筒検知結果.
	Grp_ServiceBasisWeightShiftCorrectionSteps_Status.showEnable( m_bl_IsWrongBasisWeight );				// 坪量ｼﾌﾄ量/補正STEP数 .
	Grp_ServiceEnvelopeShiftVoltageCorrectionSteps_Status.showEnable( m_bl_IsWrongEnv );					// 封筒ｼﾌﾄ電圧/補正STEP数.
	Grp_ServiceRecycledPaperJugmentThresholdSteps_Status.showEnable( m_bl_IsWrongPaperType );				// 再生紙判別閾値STEP数.
	Grp_ServicePlainPaperAdjustmentSteps_Status.showEnable( m_bl_IsWrongPaperType );						// 普通紙識別調整STEP数.
	Grp_ServiceColorPaperJugmentThresholdSteps_Status.showEnable( m_bl_IsWrongPaperType );					// 色紙判別閾値STEP数.	
}

// 印刷は手差し、またはトレイ1で行う。
Bool PServiceLearningFuncMode::isManualOrTray1Useable()
{
	Bool b_result = False;
	if ( True == isFeedTrayUseable( TYPE_FeedTrayManual ) || True == isFeedTrayUseable( TYPE_FeedTray1 )){
		b_result = True;
	}
	return b_result;
}

// 手差し、トレイ1両方に紙がセットされていない場合、スタートキー実行は不可とする.
Bool PServiceLearningFuncMode::isEnableStart()
{
	Bool bl_isEnableStart = False;
	if( m_ss_LearningFuncModeState == TYPD_ServiceLearningFuncModeInit ){
		if ( isManualOrTray1Useable() ){
			bl_isEnableStart = True;
		}
		if ( m_bl_isWaitPrint == True ){
			bl_isEnableStart = False;
		}
// comment 2023/06/16 FPT.ThinhND40 [IT6_2.3][OP_BTS-43560] メディアセンサのエラーが発生している際には、学習機能の実行を不可とする必要が.
		if( PnlComGetPrinterWarning()->isPRTWarning( TYPE_PRTWarningCode_MediaSensorTrouble )				// P-35「メディアセンサ異常」.
			|| PnlComGetPrinterWarning()->isPRTWarning( TYPE_PRTWarningCode_MediaSensorTrouble2 ) ){		// P-36「メディアセンサ異常2」.
			bl_isEnableStart = False;
		}
	}
	return bl_isEnableStart;
}

// 手差しトレイで印刷を行う。但し、手差しトレイに紙がセットされていない場合は、トレイ1で印刷を行う。
EC_FeedCode PServiceLearningFuncMode::getFeedTrayLearningFunc()
{
	EC_FeedCode ec_FeedCode = EC_FeedCode_1;
	if ( True == isFeedTrayUseable( TYPE_FeedTrayManual ) ){
		ec_FeedCode = EC_FeedCode_MANUAL;
	}
	return ec_FeedCode;
}

// スタートボタンを押下時、指定された通紙枚数にて、「メディア検知学習用通紙ファンクション」の実行指示を行う.
void PServiceLearningFuncMode::req_paperTransferFunc()
{
	bl_NoAcceptBtnFlag = True;												// ボタン受付不可にする.
	m_bl_isWaitPrint = True;												// スタート押下後画像生成終了まで立っているフラグ.
	comENG.setENGFunction_FeedCode( getFeedTrayLearningFunc() );			// どの給紙トレイから給紙させるかを指定する.
	comENG.setENGFunction_FuncSetNum( m_ss_printNum );						// メディア検知学習用通紙ファンクションを動かす枚数.		
	ushort us_currentFunction = ( TYPD_FNC_Media_PaperPassingLearningFunction & 0x7f00 ) >> 8 ;	// CommonAPI用のFunctionCodeを取得.
	ushort us_currentParameter = TYPD_FNC_Media_PaperPassingLearningFunction & 0x00ff;			// CommonAPI用のFunctionParameterを取得.
	APIC_SystemServiceFunction::newInstance()->req_startFunction( us_currentFunction, us_currentParameter, ans_paperTransferFunc );
}

// スタート.
void PServiceLearningFuncMode::procStart( uchar option )
{
	if( False == printStartDisable() ) {
// comment 2022/01/05 FPT.DungDV14 [IT6_2.3] [制御構成変更_No.39-2] Frequency counter type value Increment.
		PnlComIncreaseOperateCnt( TYPE_OperateCnt_PaperTypeAutoDetection );
		req_paperTransferFunc();
		return;
	}
	MCR_setBuzzerType( PCGE_BuzzerType_InputNg );		// 拒否音.
}

// 紙種の選択を契機として、「メディア検知学習ファンクション」の実行指示を行う.
void PServiceLearningFuncMode::req_mediaDetectionLearningFunc()
{
	for( int i = 0; i < STRUCT_SIZE( tbl_ServiceLearningFuncModePaperTypeInfo ); i++ ) {
		if( m_sc_SelectPaperType == tbl_ServiceLearningFuncModePaperTypeInfo[i].uc_optionPaperType ){
			m_e_CorrectPaperType = tbl_ServiceLearningFuncModePaperTypeInfo[i].e_PaperType;
			break;
		}
	}
// comment 2023/03/23 FPT.DungPT53 [IT6_2.3] [OP_BTS-42360] メディア検知学習ファンクション実行目的での給紙トレイ設定変更である.

	PnlComGetFeedTray()->setMediaLearnFuncFeedChg(True);	//メディア検知学習ファンクション実行目的での給紙トレイ設定変更である.

// comment 2023/03/03 FPT.LinhNV46 [IT6_2.3] [OP_BTS-42222] 再生紙は再生紙としてボタン表示して欲しい。
	TYPC_PaperType c_PaperType;
// 用紙種別に、再生紙が設定されている場合.
	if( TYPE_PaperRecycle1 == m_e_CorrectPaperType ) {
		c_PaperType.setPaperType( TYPE_PaperTypeNormal );
		c_PaperType.setCustomPaperType( TYPE_CustomPaperType20 );
	} else {
		c_PaperType.setPaperType( m_e_CorrectPaperType );
	}
	PnlComGetFeedTray()->setPaperType( m_e_FeedTray, c_PaperType );


	bl_NoAcceptBtnFlag = True;															// ボタン受付不可にする.
// comment 2023/03/03 FPT.LinhNV46 [IT6_2.3] [OP_BTS-42222] 再生紙は再生紙としてボタン表示して欲しい。
//		TYPC_PaperType c_PaperType;
//		c_PaperType.setPaperType( m_e_CorrectPaperType );
//		PnlComGetFeedTray()->setPaperType( m_e_FeedTray, c_PaperType );
	ushort us_currentFunction = ( TYPD_FNC_Media_LearningFunction & 0x7f00 ) >> 8 ;			// CommonAPI用のFunctionCodeを取得.
	ushort us_currentParameter = TYPD_FNC_Media_LearningFunction & 0x00ff;					// CommonAPI用のFunctionParameterを取得.
	APIC_SystemServiceFunction::newInstance()->req_startFunction( us_currentFunction, us_currentParameter, ans_mediaDetectionLearningFunc );

}

// ボタン押下.
void PServiceLearningFuncMode::procButtonOn( uchar uc_option )
{
	switch( uc_option ) {
		case BTNID_ServiceNumberOfSheets:												// 通紙枚数キー.
			m_bl_SetNumOn = ( m_bl_SetNumOn == True ) ? False : True;					// 通紙枚数キーＯＮ.
			break;
		case BTNID_ServicePaperBrandInput:												// 用紙銘柄入力キー.
			m_bl_SetPaperBrandOn = ( m_bl_SetPaperBrandOn == True ) ? False : True;		// 用紙銘柄入力キーＯＮ.
			break;
// 「メディア検知学習用通紙ファンクション」の実行結果の紙種が異なる場合、正しい紙種を選択する.
		case BTNID_ServiceCorrect_Thin:
		case BTNID_ServiceCorrect_PlainPaper:
		case BTNID_ServiceCorrect_PlainPaperPlus:
		case BTNID_ServiceCorrect_Thick1:
		case BTNID_ServiceCorrect_Thick1Plus:
		case BTNID_ServiceCorrect_Thick2:
		case BTNID_ServiceCorrect_Thick3:
		case BTNID_ServiceCorrect_Thick4:
		case BTNID_ServiceCorrect_Envelope:
		case BTNID_ServiceCorrect_OHP:
		case BTNID_ServiceCorrect_Recycled:
// comment 2023/02/02 FPT_LinhNV46 [IT6_2.3] [RQ-940_3]紙種自動検知対応.
		case BTNID_ServiceCorrect_Color:
		case BTNID_ServiceCorrect_UserPaper07:
// comment 2023/05/22 FPT.ThinhND40 [IT6_2.3][OP_BTS-43559] Learning function, does not allow to select correct paper twice.
			if( m_bl_IsSelectCorrectPaper == True ) {
				setBuzzerType( PCGE_BuzzerType_InputNg );
			} else {
	// 検知後に結果が間違っていた際の、OHPボタン押下による紙種の切り替えは不可とする.
				if( BTNID_ServiceCorrect_OHP == uc_option || TYPE_PaperTypeOHP == m_e_DetectedPaperType ){
					setBuzzerType( PCGE_BuzzerType_InputNg );
				} else {
					m_bl_IsSelectCorrectPaper = True;
					m_bl_SetPaperBrandOn = False;
					m_sc_SelectPaperType = uc_option;
					req_mediaDetectionLearningFunc();
				}
			}
			break;
 		default: break;
	}
	// 描画更新.
	setupGamen();
}

// comment 2023/02/02 FPT_LinhNV46 [IT6_2.3] [OP_BTS-42961].
// Call back Function 「メディア検知学習用通紙ファンクション」.
// 第一引数：TYPD_FNC_OK.
// 第二引数：
//	0ｘ0000：エラー時など.
//	0ｘ0001：手差しトレイ.
//	0ｘ0002：給紙トレイ1.
void PServiceLearningFuncMode::ans_paperTransferFunc( ushort us_Result, ushort us_Data )
{
	printf( "[LocalUI] us_Result: %d, us_Data: %d\n", us_Result, us_Data );
	m_us_ResultDetected = us_Result;
	if( us_Data == 1 ){
		m_e_FeedTray = TYPE_FeedTrayManual;								// 手差しトレイ.
	} else if( us_Data == 2 ){
		m_e_FeedTray = TYPE_FeedTray1;									// 給紙トレイ1.
	} else {
		m_us_ResultDetected = TYPD_FNC_NG;								// エラー時など.
	}
  	CallBackIndi( TYPE_PNL_CallBack_functionEnd );						// コールバックイベント発生.
}

// Call back Function「メディア検知学習ファンクション」.
// 第一引数：TYPD_FNC_OK
// 第二引数：0固定
void PServiceLearningFuncMode::ans_mediaDetectionLearningFunc( ushort us_Result, ushort us_Data )
{
	m_us_ResultDetected = us_Result;
  	CallBackIndi( TYPE_PNL_CallBack_functionEnd );						// コールバックイベント発生.
}

// ファンクション終了.
void PServiceLearningFuncMode::procFunctionEnd( uchar option )
{
	bl_NoAcceptBtnFlag = False;	// ボタン操作受付不許可フラグ(True→受付不可).
	m_bl_isWaitPrint = False;	// スタートボタン押下後、コールバックが返るまでTrueにするフラグ.
	if( m_us_ResultDetected == TYPD_FNC_OK ){
		displayResultsLearningFuncMode();
	} else {
		startGamen();													// 本機能実行中、警告が発生した場合は学習機能モードを中断し、Step1実行前の状態とする。
	}
}

// Display Results.
void PServiceLearningFuncMode::displayResultsLearningFuncMode()
{
	m_bl_SetNumOn = False;
	m_bl_ShowWeightDetect = False;
	m_bl_ShowEnvDetect = False;
	m_bl_IsWrongBasisWeight = False;
	m_bl_IsWrongEnv = False;
	m_bl_IsWrongPaperType = False;
//「メディア検知学習用通紙ファンクション」の実行結果を受け取り、検知した紙種と、坪量検知結果（封筒の場合は、封筒検知結果）を表示する.
	if( m_ss_LearningFuncModeState == TYPD_ServiceLearningFuncModeInit ){
		m_ss_LearningFuncModeState 	= TYPD_GetResultsLearningFunction;
		displayResultsPaperTransferFunc();
		setupGamen();
		return;
	}
// 「メディア検知学習ファンクション」の実行結果を受け取り、補正値算出の結果を表示する.
	displayResultsMediaDetectionLearningFunc();
	setupGamen();
}

//「メディア検知学習用通紙ファンクション」の実行結果を受け取り、検知した紙種と、坪量検知結果（封筒の場合は、封筒検知結果）を表示する.
void PServiceLearningFuncMode::displayResultsPaperTransferFunc()
{
	m_us_MediaDetectionID 		= PnlComGetPrinterServiceInfo()->getPrinterInfo( TYPE_PrinterInfoMediaDetectID );
	m_e_DetectedPaperType 		= PnlComGetFeedTray()->getPaperType( m_e_FeedTray ).getPaperType();
// comment 2023/03/03 FPT.LinhNV46 [IT6_2.3] [OP_BTS-42222] 再生紙は再生紙としてボタン表示して欲しい。
	TYPE_CustomPaperType e_CustomPaperType	= PnlComGetFeedTray()->getPaperType( m_e_FeedTray ).getCustomPaperType();
// 用紙属性が普通紙かつ、カスタム用紙が20に設定されている場合
	if( ( TYPE_PaperTypeNormal == m_e_DetectedPaperType ) && ( TYPE_CustomPaperType20 == e_CustomPaperType ) ) {
		m_e_DetectedPaperType = TYPE_PaperRecycle1;
	}
	m_e_CorrectPaperType 		= m_e_DetectedPaperType;
	for( int i = 0; i < STRUCT_SIZE( tbl_ServiceLearningFuncModePaperTypeInfo ); i++ ) {
		if( m_e_DetectedPaperType == tbl_ServiceLearningFuncModePaperTypeInfo[i].e_PaperType ){
			m_sc_SelectPaperType = tbl_ServiceLearningFuncModePaperTypeInfo[i].uc_optionPaperType;
			break;
		}
	}
	if( m_e_DetectedPaperType == TYPE_PaperTypeEnvelope ){
		if(	m_e_FeedTray == TYPE_FeedTrayManual ){
			Num_ServiceEnvelopeDetectionResult_Value = PnlComGetPrinterServiceInfo()->getPrinterInfoTypeFloat( TYPE_PrinterInfoTypeFloatEnvelopeDistinctionManual );
		} else if( m_e_FeedTray == TYPE_FeedTray1 ){
			Num_ServiceEnvelopeDetectionResult_Value = PnlComGetPrinterServiceInfo()->getPrinterInfoTypeFloat( TYPE_PrinterInfoTypeFloatEnvelopeDistinction1st );
		}
		m_bl_ShowEnvDetect = True;
	} else {
		if(	m_e_FeedTray == TYPE_FeedTrayManual ){
			Num_ServiceBasisWeightDetectionResult_Value = PnlComGetPrinterServiceInfo()->getPrinterInfoTypeFloat( TYPE_PrinterInfoTypeFloatBasicWeightDetectManual );
		} else if( m_e_FeedTray == TYPE_FeedTray1 ){
			Num_ServiceBasisWeightDetectionResult_Value = PnlComGetPrinterServiceInfo()->getPrinterInfoTypeFloat( TYPE_PrinterInfoTypeFloatBasicWeightDetect1st );
		}
		m_bl_ShowWeightDetect = True;
	}
}

// 「メディア検知学習ファンクション」の実行結果を受け取り、補正値算出の結果を表示する.
void PServiceLearningFuncMode::displayResultsMediaDetectionLearningFunc()
{
	if( m_e_DetectedPaperType == TYPE_PaperTypeEnvelope ){
		m_bl_ShowEnvDetect = True;
	} else {
		m_bl_ShowWeightDetect = True;
	}
// 封筒誤検知の場合.
	if( m_e_CorrectPaperType == TYPE_PaperTypeEnvelope || m_e_DetectedPaperType == TYPE_PaperTypeEnvelope ){
		Num_ServiceEnvelopeShiftVoltage_Value = PnlComGetPrinterServiceInfo()->getPrinterInfoTypeFloat( TYPE_PrinterInfoTypeFloatEnvelopeShiftVoltage );
		Num_ServiceEnvelopeCorrectionSteps_Value = getPrinterIndiInSystem( TYPE_PrinterAdjustEnvelopeThresholdAdjust );
		m_bl_IsWrongEnv = True;
// 紙種間違いの場合.
// comment 2023/02/02 FPT_LinhNV46 [IT6_2.3] [RQ-940_3]紙種自動検知対応.
	} else if( m_e_CorrectPaperType == TYPE_PaperTypeUser7 || m_e_CorrectPaperType == TYPE_PaperRecycle1 || m_e_CorrectPaperType == TYPE_PaperTypeColor
			|| m_e_DetectedPaperType == TYPE_PaperTypeUser7 || m_e_DetectedPaperType == TYPE_PaperRecycle1 || m_e_DetectedPaperType == TYPE_PaperTypeColor ){
		Num_ServicePlainPaperAdjustmentSteps_Value = getPrinterIndiInSystem( TYPE_PrinterAdjustCoatedPaperBasicWeightAdjust );
		Num_ServiceRecycledPaperJugmentThresholdSteps_Value = getPrinterIndiInSystem( TYPE_PrinterAdjustRecyclePaperThresholdAdjust );
		Num_ServiceColorPaperJugmentThresholdSteps_Value = getPrinterIndiInSystem( TYPE_PrinterAdjustColorPaperDiscrimination );
		m_bl_IsWrongPaperType = True;
	} else {
// comment 2023/05/30 FPT.ThinhND40 [IT6_2.3][OP_BTS-43052] 学習機能の結果について、保存するデータは調整時に画面表示しているものと同じパラメータだけ保存する.
// 坪量間違いの場合.
// 薄紙/普通紙.
		if( ( m_e_DetectedPaperType == TYPE_PaperTypeNormal && m_e_CorrectPaperType == TYPE_PaperTypeThin1 )
			|| ( m_e_DetectedPaperType == TYPE_PaperTypeThin1 && m_e_CorrectPaperType == TYPE_PaperTypeNormal ) ){
			Num_ServiceBasisWeightShift_Value = PnlComGetPrinterServiceInfo()->getPrinterInfoTypeFloat( TYPE_PrinterInfoTypeFloatBasicWeightShiftThin );
			Num_ServiceBasisWeightCorrectionSteps_Value = getPrinterIndiInSystem( TYPE_PrinterAdjustBasicWeightThresholdAdjustThin );
// 普通紙/普通紙+.
		} else if( ( m_e_DetectedPaperType == TYPE_PaperTypeNormalPlus && m_e_CorrectPaperType == TYPE_PaperTypeNormal )
			|| ( m_e_DetectedPaperType == TYPE_PaperTypeNormal && m_e_CorrectPaperType == TYPE_PaperTypeNormalPlus ) ){
			Num_ServiceBasisWeightShift_Value = PnlComGetPrinterServiceInfo()->getPrinterInfoTypeFloat( TYPE_PrinterInfoTypeFloatBasicWeightShiftNormal );
			Num_ServiceBasisWeightCorrectionSteps_Value = getPrinterIndiInSystem( TYPE_PrinterAdjustBasicWeightThresholdAdjustNormal );
// 普通紙+/厚紙1.
		} else if( ( m_e_DetectedPaperType == TYPE_PaperTypeThick1 && m_e_CorrectPaperType == TYPE_PaperTypeNormalPlus )
			|| ( m_e_DetectedPaperType == TYPE_PaperTypeNormalPlus && m_e_CorrectPaperType == TYPE_PaperTypeThick1 ) ){
			Num_ServiceBasisWeightShift_Value = PnlComGetPrinterServiceInfo()->getPrinterInfoTypeFloat( TYPE_PrinterInfoTypeFloatBasicWeightShiftNormalPlus );
			Num_ServiceBasisWeightCorrectionSteps_Value = getPrinterIndiInSystem( TYPE_PrinterAdjustBasicWeightThresholdAdjustNormalPlus );
// 厚紙1/厚紙1+.
		} else if( ( m_e_DetectedPaperType == TYPE_PaperTypeThick1Plus && m_e_CorrectPaperType == TYPE_PaperTypeThick1 )
			|| ( m_e_DetectedPaperType == TYPE_PaperTypeThick1 && m_e_CorrectPaperType == TYPE_PaperTypeThick1Plus ) ){
			Num_ServiceBasisWeightShift_Value = PnlComGetPrinterServiceInfo()->getPrinterInfoTypeFloat( TYPE_PrinterInfoTypeFloatBasicWeightShiftThick1 );
			Num_ServiceBasisWeightCorrectionSteps_Value = getPrinterIndiInSystem( TYPE_PrinterAdjustBasicWeightThresholdAdjustThick1 );
// 厚紙1+/厚紙2.
		} else if( ( m_e_DetectedPaperType == TYPE_PaperTypeThick2 && m_e_CorrectPaperType == TYPE_PaperTypeThick1Plus )
			|| ( m_e_DetectedPaperType == TYPE_PaperTypeThick1Plus && m_e_CorrectPaperType == TYPE_PaperTypeThick2 ) ){
			Num_ServiceBasisWeightShift_Value = PnlComGetPrinterServiceInfo()->getPrinterInfoTypeFloat( TYPE_PrinterInfoTypeFloatBasicWeightShiftThick1Plus );
			Num_ServiceBasisWeightCorrectionSteps_Value = getPrinterIndiInSystem( TYPE_PrinterAdjustBasicWeightThresholdAdjustThick1Plus );
// 厚紙2/厚紙3.
		} else if( ( m_e_DetectedPaperType == TYPE_PaperTypeThick3 && m_e_CorrectPaperType == TYPE_PaperTypeThick2 )
			|| ( m_e_DetectedPaperType == TYPE_PaperTypeThick2 && m_e_CorrectPaperType == TYPE_PaperTypeThick3 ) ){
			Num_ServiceBasisWeightShift_Value = PnlComGetPrinterServiceInfo()->getPrinterInfoTypeFloat( TYPE_PrinterInfoTypeFloatBasicWeightShiftThick2 );
			Num_ServiceBasisWeightCorrectionSteps_Value = getPrinterIndiInSystem( TYPE_PrinterAdjustBasicWeightThresholdAdjustThick2 );
// 厚紙3/厚紙4.
		} else if( ( m_e_DetectedPaperType == TYPE_PaperTypeThick4 && m_e_CorrectPaperType == TYPE_PaperTypeThick3 )
			|| ( m_e_DetectedPaperType == TYPE_PaperTypeThick3 && m_e_CorrectPaperType == TYPE_PaperTypeThick4 ) ){
			Num_ServiceBasisWeightShift_Value = PnlComGetPrinterServiceInfo()->getPrinterInfoTypeFloat( TYPE_PrinterInfoTypeFloatBasicWeightShiftThick3 );
			Num_ServiceBasisWeightCorrectionSteps_Value = getPrinterIndiInSystem( TYPE_PrinterAdjustBasicWeightThresholdAdjustThick3 );
		} else {
			Num_ServiceBasisWeightShift_Value = 0;
			Num_ServiceBasisWeightCorrectionSteps_Value = 0;
		}
		m_bl_IsWrongBasisWeight = True;
	}
}

// 画面移動.
void PServiceLearningFuncMode::procGoToPage( uchar option )
{
	switch( option ) {
		case BTNID_GoTo_ServiceLearningFuncModeSave:					// 保存キー.
			setDataRecord();
			nextGamen = &gp_ServiceMachineAdjustModeMenu2P;				// サービス・マシン調整・モードメニュー 2nd page.
			break;
		default:
			break;
	}
}

// 用紙銘柄と下記データを紐づけ. CommonAPIのAPIにてデータの保存を要求する.
void PServiceLearningFuncMode::setDataRecord()
{
// 用紙銘柄と下記データを紐づけ.
	TYPS_MediaDetectionLearning st_MediaDetectionLearning;
	memset( &st_MediaDetectionLearning, 0x00, sizeof( TYPS_MediaDetectionLearning ) );
	strcpy( st_MediaDetectionLearning.sc_FormBrandInfo, m_sc_PaperBrand );			// 用紙銘柄情報.
// comment 2023/02/02 FPT_LinhNV46 [IT6_2.3] [RQ-940_3]紙種自動検知対応.
// 検知した紙種.
	TYPC_PaperType c_DetectedType;
// comment 2023/03/03 FPT.LinhNV46 [IT6_2.3] [OP_BTS-42222] 再生紙は再生紙としてボタン表示して欲しい。
//	c_DetectedType.setPaperType( m_e_DetectedPaperType );
// 用紙種別に、再生紙が設定されている場合.
	if( TYPE_PaperRecycle1 == m_e_DetectedPaperType ) {
		c_DetectedType.setPaperType( TYPE_PaperTypeNormal );
		c_DetectedType.setCustomPaperType( TYPE_CustomPaperType20 );
	} else {
		c_DetectedType.setPaperType( m_e_DetectedPaperType );
	}
	st_MediaDetectionLearning.c_DetectPaperType = c_DetectedType;
// 正解紙種.
	TYPC_PaperType c_CorrectType;
// comment 2023/03/03 FPT.LinhNV46 [IT6_2.3] [OP_BTS-42222] 再生紙は再生紙としてボタン表示して欲しい。
//	c_CorrectType.setPaperType( m_e_CorrectPaperType );
// 用紙種別に、再生紙が設定されている場合.
	if( TYPE_PaperRecycle1 == m_e_CorrectPaperType ) {
		c_CorrectType.setPaperType( TYPE_PaperTypeNormal );
		c_CorrectType.setCustomPaperType( TYPE_CustomPaperType20 );
	} else {
		c_CorrectType.setPaperType( m_e_CorrectPaperType );
	}
	st_MediaDetectionLearning.c_CorrectPaperType = c_CorrectType;
// メディア検知ID.
	st_MediaDetectionLearning.us_MDID = m_us_MediaDetectionID;
// comment 2023/05/30 FPT.ThinhND40 [IT6_2.3][OP_BTS-43052] 学習機能の結果について、保存するデータは調整時に画面表示しているものと同じパラメータだけ保存する.
	if( m_bl_IsWrongEnv ){
		st_MediaDetectionLearning.us_EnvShiftVoltage = (ushort)( 100 * ( PnlComGetPrinterServiceInfo()->getPrinterInfoTypeFloat( TYPE_PrinterInfoTypeFloatEnvelopeShiftVoltage ) ) );		// Enveシフト電圧(±**V).
		st_MediaDetectionLearning.ss_EnvelopeIdentificationAdjust = getPrinterIndiInSystem( TYPE_PrinterAdjustEnvelopeThresholdAdjust );													// Enve識別閾値(±**STEP).
	} else if( m_bl_IsWrongPaperType ){
		st_MediaDetectionLearning.ss_PlainPaperIdentificationAdjust = getPrinterIndiInSystem( TYPE_PrinterAdjustCoatedPaperBasicWeightAdjust );												// plain paper識別調整（coated paper識別調整）(±**STEP).
		st_MediaDetectionLearning.ss_RecycledPaperIdentificationAdjust = getPrinterIndiInSystem( TYPE_PrinterAdjustRecyclePaperThresholdAdjust );											// recycled paper判別閾値(±**STEP).
		st_MediaDetectionLearning.ss_ColoredPaperIdentificationAdjust = getPrinterIndiInSystem( TYPE_PrinterAdjustColorPaperDiscrimination );												// colored paper判別閾値(±**STEP).
	} else if( m_bl_IsWrongBasisWeight ){
		if( ( m_e_DetectedPaperType == TYPE_PaperTypeNormal && m_e_CorrectPaperType == TYPE_PaperTypeThin1 )
			|| ( m_e_DetectedPaperType == TYPE_PaperTypeThin1 && m_e_CorrectPaperType == TYPE_PaperTypeNormal ) ){
				st_MediaDetectionLearning.us_WeightShiftAmount = (ushort)( 10 * ( PnlComGetPrinterServiceInfo()->getPrinterInfoTypeFloat( TYPE_PrinterInfoTypeFloatBasicWeightShiftThin ) ) );						// 坪量シフト量(±**g／m?).
				st_MediaDetectionLearning.ss_BoundaryAdjustThinPaperPlain = getPrinterIndiInSystem( TYPE_PrinterAdjustBasicWeightThresholdAdjustThin );																// 坪量区分境界値調整(thin paper/plain paper)(±**STEP).
		} else if( ( m_e_DetectedPaperType == TYPE_PaperTypeNormalPlus && m_e_CorrectPaperType == TYPE_PaperTypeNormal )
			|| ( m_e_DetectedPaperType == TYPE_PaperTypeNormal && m_e_CorrectPaperType == TYPE_PaperTypeNormalPlus ) ){
				st_MediaDetectionLearning.us_WeightShiftAmount = (ushort)( 10 * ( PnlComGetPrinterServiceInfo()->getPrinterInfoTypeFloat( TYPE_PrinterInfoTypeFloatBasicWeightShiftNormal ) ) );					// 坪量シフト量(±**g／m?).
				st_MediaDetectionLearning.ss_BoundaryAdjustPlainPaperPlainPlus = getPrinterIndiInSystem( TYPE_PrinterAdjustBasicWeightThresholdAdjustNormal );														// 坪量区分境界値調整(plain paper/plain paper+)(±**STEP).
		} else if( ( m_e_DetectedPaperType == TYPE_PaperTypeThick1 && m_e_CorrectPaperType == TYPE_PaperTypeNormalPlus )
			|| ( m_e_DetectedPaperType == TYPE_PaperTypeNormalPlus && m_e_CorrectPaperType == TYPE_PaperTypeThick1 ) ){
				st_MediaDetectionLearning.us_WeightShiftAmount = (ushort)( 10 * ( PnlComGetPrinterServiceInfo()->getPrinterInfoTypeFloat( TYPE_PrinterInfoTypeFloatBasicWeightShiftNormalPlus ) ) );				// 坪量シフト量(±**g／m?).
				st_MediaDetectionLearning.ss_BoundaryAdjustPlainPlusPaperThick1 = getPrinterIndiInSystem( TYPE_PrinterAdjustBasicWeightThresholdAdjustNormalPlus );													// 坪量区分境界値調整(plain paper+/Thick紙1)(±**STEP).
		} else if( ( m_e_DetectedPaperType == TYPE_PaperTypeThick1Plus && m_e_CorrectPaperType == TYPE_PaperTypeThick1 )
			|| ( m_e_DetectedPaperType == TYPE_PaperTypeThick1 && m_e_CorrectPaperType == TYPE_PaperTypeThick1Plus ) ){
				st_MediaDetectionLearning.us_WeightShiftAmount = (ushort)( 10 * ( PnlComGetPrinterServiceInfo()->getPrinterInfoTypeFloat( TYPE_PrinterInfoTypeFloatBasicWeightShiftThick1 ) ) );					// 坪量シフト量(±**g／m?).
				st_MediaDetectionLearning.ss_BoundaryAdjustThick1PaperThick1Plus = getPrinterIndiInSystem( TYPE_PrinterAdjustBasicWeightThresholdAdjustThick1 );													// 坪量区分境界値調整(Thick紙1/Thick紙1+)(±**STEP).
		} else if( ( m_e_DetectedPaperType == TYPE_PaperTypeThick2 && m_e_CorrectPaperType == TYPE_PaperTypeThick1Plus )
			|| ( m_e_DetectedPaperType == TYPE_PaperTypeThick1Plus && m_e_CorrectPaperType == TYPE_PaperTypeThick2 ) ){
				st_MediaDetectionLearning.us_WeightShiftAmount = (ushort)( 10 * ( PnlComGetPrinterServiceInfo()->getPrinterInfoTypeFloat( TYPE_PrinterInfoTypeFloatBasicWeightShiftThick1Plus ) ) );				// 坪量シフト量(±**g／m?).
				st_MediaDetectionLearning.ss_BoundaryAdjustThick1PlusPaperThick2 = getPrinterIndiInSystem( TYPE_PrinterAdjustBasicWeightThresholdAdjustThick1Plus );												// 坪量区分境界値調整(Thick紙1+/Thick紙2)(±**STEP).
		} else if( ( m_e_DetectedPaperType == TYPE_PaperTypeThick3 && m_e_CorrectPaperType == TYPE_PaperTypeThick2 )
			|| ( m_e_DetectedPaperType == TYPE_PaperTypeThick2 && m_e_CorrectPaperType == TYPE_PaperTypeThick3 ) ){
				st_MediaDetectionLearning.us_WeightShiftAmount = (ushort)( 10 * ( PnlComGetPrinterServiceInfo()->getPrinterInfoTypeFloat( TYPE_PrinterInfoTypeFloatBasicWeightShiftThick2 ) ) );					// 坪量シフト量(±**g／m?).
				st_MediaDetectionLearning.ss_BoundaryAdjustThick2PaperThick3 = getPrinterIndiInSystem( TYPE_PrinterAdjustBasicWeightThresholdAdjustThick2 );														// 坪量区分境界値調整(Thick紙2/Thick紙3)(±**STEP).
		} else if( ( m_e_DetectedPaperType == TYPE_PaperTypeThick4 && m_e_CorrectPaperType == TYPE_PaperTypeThick3 )
			|| ( m_e_DetectedPaperType == TYPE_PaperTypeThick3 && m_e_CorrectPaperType == TYPE_PaperTypeThick4 ) ){
				st_MediaDetectionLearning.us_WeightShiftAmount = (ushort)( 10 * ( PnlComGetPrinterServiceInfo()->getPrinterInfoTypeFloat( TYPE_PrinterInfoTypeFloatBasicWeightShiftThick3 ) ) );					// 坪量シフト量(±**g／m?).
				st_MediaDetectionLearning.ss_BoundaryAdjustThick3PaperThick4 = getPrinterIndiInSystem( TYPE_PrinterAdjustBasicWeightThresholdAdjustThick3 );														// 坪量区分境界値調整(Thick紙3/Thick紙4)(±**STEP).
		}
	}
// CommonAPIのAPIにてデータの保存を要求する.
	PnlComGetSystemSetting()->setMediaDetectionLearning( &st_MediaDetectionLearning );
}

// テンキー（押された）.
void PServiceLearningFuncMode::proc10Key( uchar option )
{
	if( m_ss_LearningFuncModeState == TYPD_ServiceLearningFuncModeInit ){
// 通紙枚数の指定は最大10枚とする（1～10の指定）.
		if( m_bl_SetNumOn == True ) {							// 通紙枚数キーがＯＮ.
			if( option <= 9 ) {	// 10キーの#,*を排除
				if( m_bl_DirectOn == True && option != 0 ) {	// ダイレクト入力、かつ、０以外の時（置数０を入力させない為）
					m_ss_printNum = option; 					// テストプリント出力枚数.
					m_bl_DirectOn = False;						// ダイレクト入力OFF
				} else if( m_bl_DirectOn == False && ( ( m_ss_printNum * 10 + option ) <= PNLD_MAX_ServiceNumberOfSheets ) ) {	// ダイレクト入力OFF、かつ、10を超えなかったら入力を許可する
					m_ss_printNum = static_cast<short>( m_ss_printNum * 10 + option ); 	// テストプリント出力枚数.
				} else {
					setBuzzerType( PCGE_BuzzerType_InputNg );
				}
			}
			setupGamen();
		} else {
			setBuzzerType( PCGE_BuzzerType_InputNg );
		}
	} else {
// 用紙銘柄情報(バーコード番号)の文字数、入力可能文字は以下とする。
// 入力可能文字：数字.
		if( m_bl_SetPaperBrandOn == True ) {		// 用紙銘柄入力キーがＯＮ.
			if( 9 < option ) {
				MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
				return;
			}
			setStringWithCheck( ( uchar* )m_sc_PaperBrand, static_cast<uchar>( option + '0' ), getPaperBrandLength(), False );
			setupGamen();	// 表示部品のセットアップ
		} else {
			setBuzzerType( PCGE_BuzzerType_InputNg );
		}
	}
}

// 選択されているシリアル番号の桁数を取得する.
short PServiceLearningFuncMode::getPaperBrandLength()
{
// 最大文字数：北米仕向：12桁、北米仕向以外：13桁.
	short ss_resultLenght = 0;
	if( TYPE_SystemType_US == PnlComGetMachineSetting()->getSystemType()){
		ss_resultLenght = PNLD_MAX_ServicePaperBrand_US;
	} else {
		ss_resultLenght = PNLD_MAX_ServicePaperBrand_OtherUS;
	}
	return ss_resultLenght;
}

// クリアキー.
void PServiceLearningFuncMode::procClear( uchar option )
{
	if( m_ss_LearningFuncModeState == TYPD_ServiceLearningFuncModeInit ){
		if( m_bl_SetNumOn == True ) {		// 通紙枚数キーがＯＮ.
			m_ss_printNum = 1;				// 置数０を入力させない為、１を初期値とする.
			m_bl_DirectOn = True;			// ダイレクト入力ON.
			setupGamen();
		} else {
			setBuzzerType( PCGE_BuzzerType_InputNg );
		}
	} else {
		if( m_bl_SetPaperBrandOn == True ) {		// 用紙銘柄入力キーがＯＮ.
			clearString( ( uchar* )m_sc_PaperBrand, TYPD_FormBrandInformation_MAX_LENGTH );
			setupGamen();
		} else {
			setBuzzerType( PCGE_BuzzerType_InputNg );
		}
	}
}

// 設定終了.
void PServiceLearningFuncMode::procOk( uchar option )
{
	nextGamen = &gp_ServiceMachineAdjustModeMenu2P;			// サービス・マシン調整・モードメニュー 2nd page.
}
//================================================================================================.
//概要    : サービス・マシン調整・紙種自動検出設定.
//================================================================================================.
#define	PNLD_KEY_ServiceWeightTableTargetSetting			0 	// 坪量テーブル仕向切替.
#define	PNLD_KEY_ServiceBasisWeightDetectionAdj				1	// 坪量検出調整.
#define	PNLD_KEY_ServiceWeightBoundaryAdj					2	// 坪量区分値調整.
#define	PNLD_KEY_ServiceWeightClassVariationCorrection		3	// 坪量区分ばらつき補正.
#define	PNLD_KEY_ServiceRecyclePaperDistinctionThreshold	4	// 再生紙識別調整.
#define	PNLD_KEY_ServiceEnvelopeDiscriminationAdj			5	// 封筒識別調整.
#define	PNLD_KEY_ServicePlainPaperIdentificationAdj			0	// 普通紙識別調整.
#define	PNLD_KEY_ServiceColorPaperIdentificationAdj			1	// 色紙識別調整.
#define	PNLD_KEY_ServiceRegularDetectionAdj					2	// 常時検知調整.
uchar PServiceAutoPaperDetectSetting::uc_pageNum = 0;	// 自己診断のページ番号.(1:1ページ、2:2ページ).
//================================================================================================.
//概要    : サービス・マシン調整・紙種自動検出設定: 画面開始処理.
//================================================================================================.
