{
	PBasicMessageProc::startGamen();
}
//================================================================================================.
//概要    : サービス・マシン調整・紙種自動検出設定 : 設定終了.
//================================================================================================.
void PServiceAutoPaperDetectSetting::procOk( uchar option )
{
	bl_isRequestInitialize = True;	// 初期設定フラグON.
	nextGamen = &gp_ServiceMachineAdjustModeMenu2P;			// サービス・マシン調整・モードメニュー 2nd page.
}
