//概要    : サービス・マシン調整・紙種自動検出設定 : スタート.
//================================================================================================.
void PServiceAutoPaperDetectSetting::procStart( uchar option )
{
	if( True == printStartDisable() ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );		// 拒否音.
	}
}
//================================================================================================.
//概要    : サービス・マシン調整・紙種自動検出設定 : 画面移動.
//================================================================================================.
void PServiceAutoPaperDetectSetting::procGoToPage( uchar option )
{
	bl_isRequestInitialize = True;	// 初期設定フラグON.
	switch( option ) {
		case BTNID_GoTo_ServiceWeightTableTargetSetting:
			nextGamen = &gp_ServiceWeightTableTargetSetting;			// 90510 サービス・マシン調整・紙種自動検出設定・坪量テーブル仕向切替.
			break;
		case BTNID_GoTo_ServiceBasisWeightDetectionAdj:
			nextGamen = &gp_ServiceBasisWeightDetectionAdj;				// 90511 サービス・マシン調整・紙種自動検出設定・坪量検出調整.
			break;
		case BTNID_GoTo_ServiceWeightBoundaryAdj:
			nextGamen = &gp_ServiceWeightBoundaryAdj;					// 90512 サービス・マシン調整・紙種自動検出設定・坪量区分値調整.
			break;
		case BTNID_GoTo_ServiceWeightClassVariationCorrection:
			nextGamen = &gp_ServiceWeightClassVariationCorrection;		// 90513 サービス・マシン調整・紙種自動検出設定・坪量区分ばらつき補正.
			break;
		case BTNID_GoTo_ServiceRecyclePaperDistinctionThreshold:
			nextGamen = &gp_ServiceRecyclePaperDistinctionThreshold;	// 90514 サービス・マシン調整・紙種自動検出設定・再生紙識別調整.
			break;
		case BTNID_GoTo_ServiceEnvelopeDiscriminationAdj:
			nextGamen = &gp_ServiceEnvelopeDiscriminationAdj;			// 90515 サービス・マシン調整・紙種自動検出設定・封筒識別調整.
			break;
		case BTNID_GoTo_ServicePlainPaperIdentificationAdj:
			nextGamen = &gp_ServicePlainPaperIdentificationAdj;			// 90516 サービス・マシン調整・紙種自動検出設定・普通紙識別調整.
			break;
		case BTNID_GoTo_ServiceColorPaperIdentificationAdj:
			nextGamen = &gp_ServiceColorPaperIdentificationAdj;			// 90517 サービス・マシン調整・紙種自動検出設定・色紙識別調整.
			break;
		case BTNID_GoTo_ServiceRegularDetectionAdj:
			nextGamen = &gp_ServiceRegularDetectionAdj;					// 90518 サービス・マシン調整・紙種自動検出設定・常時検知調整.
			break;				
		case BTNID_KEY_ServiceAutoPaperDetectSettingPageChangeUp:
		case BTNID_KEY_ServiceAutoPaperDetectSettingPageChangeDown:
			if( uc_pageNum == 1 ) {
				nextGamen = &gp_ServicePlainPaperIdentificationAdj;		// 90510 サービス・マシン調整・紙種自動検出設定・坪量テーブル仕向切替.
			} else {
				nextGamen = &gp_ServiceWeightTableTargetSetting;		// 90516 サービス・マシン調整・紙種自動検出設定・普通紙識別調整.
			}
			break;
		default:break;
	}
}

