{
	// 設定値を保存する.
	for( int i = 0; i < STRUCT_SIZE( tbl_ServiceAutoDetectMeasuredSettingInfo ); i++ ) {
		fixPrinterIndi( tbl_ServiceAutoDetectMeasuredSettingInfo[i].e_PrinterAdjust );
	}
	PServiceAutoPaperDetectSetting::procOk( uc_option );
}
