//================================================================================================.
// PServiceWeightBoundaryAdj: 90512 サービス・マシン調整・紙種自動検出設定・坪量区分値調整 : 初期設定.
//================================================================================================.
void PServiceWeightBoundaryAdj::init_value()
{
	// APIから値を取得.
	m_ss_BakWeightBoundaryAdjThin 		= getPrinterIndiInSystem( TYPE_PrinterAdjustBasicWeightThresholdAdjustThin );		// 薄紙/普通紙境界値.
	m_ss_BakWeightBoundaryAdjNormal 	= getPrinterIndiInSystem( TYPE_PrinterAdjustBasicWeightThresholdAdjustNormal );		// 普通紙/普通紙+境界値.
	m_ss_BakWeightBoundaryAdjNormalPlus = getPrinterIndiInSystem( TYPE_PrinterAdjustBasicWeightThresholdAdjustNormalPlus );	// 普通紙+/厚紙1境界値.
	m_ss_BakWeightBoundaryAdjThick1 	= getPrinterIndiInSystem( TYPE_PrinterAdjustBasicWeightThresholdAdjustThick1 );		// 厚紙1/厚紙1+境界値.
	m_ss_BakWeightBoundaryAdjThick1Plus = getPrinterIndiInSystem( TYPE_PrinterAdjustBasicWeightThresholdAdjustThick1Plus );	// 厚紙1+/厚紙2境界値.
	m_ss_BakWeightBoundaryAdjThick2 	= getPrinterIndiInSystem( TYPE_PrinterAdjustBasicWeightThresholdAdjustThick2 );		// 厚紙2/厚紙3境界値.
	m_ss_BakWeightBoundaryAdjThick3 	= getPrinterIndiInSystem( TYPE_PrinterAdjustBasicWeightThresholdAdjustThick3 );		// 厚紙3/厚紙4境界値.
	m_ss_NowPage = 1;		// 表示ページを1ページ目にする.
	m_ss_SelectIndex = 0;	// トレイキーを未選択にする.
}
//============================================================================================.
// PServiceWeightBoundaryAdj: 90512 サービス・マシン調整・紙種自動検出設定・坪量区分値調整 : 画面開始処理.
//============================================================================================.
void PServiceWeightBoundaryAdj::startGamen()
{
	PServiceAutoPaperDetectSetting::startGamen();	// 紙種自動検出設定.
	Rbt_ServiceAutoPaperDetectSettingP1.select( PNLD_KEY_ServiceWeightBoundaryAdj );
	CheckAndExecInit(); 	// 初期化必要か否か取得して必要なら実行する. 
	setPrinterIndi( TYPE_PrinterAdjustBasicWeightThresholdAdjustThin );
}
//================================================================================================.
// PServiceWeightBoundaryAdj: 90512 サービス・マシン調整・紙種自動検出設定・坪量区分値調整 : 画面更新処理.
//================================================================================================.
void PServiceWeightBoundaryAdj::setupGamen( short ss_option )
{
	PServiceAutoPaperDetectSetting::setupGamen( ss_option );

	// 1ページ目パーツ表示状態更新.
	Bool bl_isShowP1 = ( m_ss_NowPage == 1 ) ? True : False;
	Rbt_ServiceWeightBoundaryAdj_PaperKeysP1.showEnableAll( bl_isShowP1 );		// 設定値.
	Grp_ServiceWeightBoundaryAdj_StatusP1.showEnableAll( bl_isShowP1 );	// 紙種キー.
	Grp_ServiceWeightBoundaryAdj_RangeP1.showEnableAll( bl_isShowP1 );	// 紙種キー.
	Txt_ServiceWeightBoundaryAdj_CounterPage1_2.showEnable( bl_isShowP1 );	// 紙種キー.
	Rbt_ServiceWeightBoundaryAdj_PaperKeysP1.select( m_ss_SelectIndex );		// 紙種キー選択.
	
	// 2ページ目パーツ表示状態更新.
	Bool bl_isShowP2 = ( m_ss_NowPage == 2 ) ? True : False;
	Rbt_ServiceWeightBoundaryAdj_PaperKeysP2.showEnableAll( bl_isShowP2 );		// 設定値.
	Grp_ServiceWeightBoundaryAdj_StatusP2.showEnableAll( bl_isShowP2 );	// 紙種キー.
	Grp_ServiceWeightBoundaryAdj_RangeP2.showEnableAll( bl_isShowP2 );	// 紙種キー.
	Txt_ServiceWeightBoundaryAdj_CounterPage2_2.showEnable( bl_isShowP2 );	// 紙種キー.
	Rbt_ServiceWeightBoundaryAdj_PaperKeysP2.select( m_ss_SelectIndex );		// 紙種キー選択.
	
	for( int i = 0; i < STRUCT_SIZE( tbl_ServiceWeightBoundarySettingInfo ); i++ ) {
		float f_value = getPrinterIndi( tbl_ServiceWeightBoundarySettingInfo[i].e_PrinterAdjust );	// 設定値取得.
		tbl_ServiceWeightBoundarySettingInfo[i].m_pc_ValueField->set( f_value, True );				// 値更新.
	}
}
//================================================================================================.
// PServiceWeightBoundaryAdj: 90512 サービス・マシン調整・紙種自動検出設定・坪量区分値調整 : ボタン押下処理.
//================================================================================================.
void PServiceWeightBoundaryAdj::procButtonOn( uchar uc_option )
{
	switch( uc_option ) {
		case BTNID_ServiceWeightBoundaryAdj_ThinNormal:				// 薄紙/普通紙境界値.
		case BTNID_ServiceWeightBoundaryAdj_NormalNormalP:			// 普通紙/普通紙+境界値.
		case BTNID_ServiceWeightBoundaryAdj_NormalPThick1:			// 普通紙+/厚紙1境界値.
		case BTNID_ServiceWeightBoundaryAdj_Thick1Thick1P:			// 厚紙1/厚紙1+境界値.
		case BTNID_ServiceWeightBoundaryAdj_Thick1PThick2:			// 厚紙1+/厚紙2境界値.
		case BTNID_ServiceWeightBoundaryAdj_Thick2Thick3:			// 厚紙2/厚紙3境界値.
		case BTNID_ServiceWeightBoundaryAdj_Thick3Thick4:			// 厚紙3/厚紙4境界値.
			m_ss_SelectIndex = uc_option - ( PNLD_ServiceWeightBoundaryAdj_PAGE_PARTS * ( m_ss_NowPage -1 ) );
			setPrinterIndi( tbl_ServiceWeightBoundarySettingInfo[ uc_option ].e_PrinterAdjust );
			break;
		case  BTNID_KEY_ServiceWeightBoundaryAdj_PageChangeUp:		// ↑キー.
		case  BTNID_KEY_ServiceWeightBoundaryAdj_PageChangeDown:	// ↓キー.
			m_ss_NowPage = ( m_ss_NowPage == 1 ) ? 2 : 1;
			m_ss_SelectIndex = 0;
			if( m_ss_NowPage == 1 ){
				setPrinterIndi( TYPE_PrinterAdjustBasicWeightThresholdAdjustThin );
			} else {
				setPrinterIndi( TYPE_PrinterAdjustBasicWeightThresholdAdjustThick1Plus );
			}
			break;
		case BTNID_ServiceAutoPaperDetectSetting_BelowPlus:				// ＋キー押下時.
			addIndi();
			break;
		case BTNID_ServiceAutoPaperDetectSetting_BelowMinus:				// －キー押下時.
			subIndi();
			break;
		case 60:	// 元に戻すキー.
			switch( getIndiSelected() ) {
				case TYPE_PrinterAdjustBasicWeightThresholdAdjustThin:
					setPrinterIndi( TYPE_PrinterAdjustBasicWeightThresholdAdjustThin, m_ss_BakWeightBoundaryAdjThin );
					break;
				case TYPE_PrinterAdjustBasicWeightThresholdAdjustNormal:
					setPrinterIndi( TYPE_PrinterAdjustBasicWeightThresholdAdjustNormal, m_ss_BakWeightBoundaryAdjNormal );
					break;
				case TYPE_PrinterAdjustBasicWeightThresholdAdjustNormalPlus:
					setPrinterIndi( TYPE_PrinterAdjustBasicWeightThresholdAdjustNormalPlus, m_ss_BakWeightBoundaryAdjNormalPlus );
					break;
				case TYPE_PrinterAdjustBasicWeightThresholdAdjustThick1:
					setPrinterIndi( TYPE_PrinterAdjustBasicWeightThresholdAdjustThick1, m_ss_BakWeightBoundaryAdjThick1 );
					break;
				case TYPE_PrinterAdjustBasicWeightThresholdAdjustThick1Plus:
					setPrinterIndi( TYPE_PrinterAdjustBasicWeightThresholdAdjustThick1Plus, m_ss_BakWeightBoundaryAdjThick1Plus );
					break;
				case TYPE_PrinterAdjustBasicWeightThresholdAdjustThick2:
					setPrinterIndi( TYPE_PrinterAdjustBasicWeightThresholdAdjustThick2, m_ss_BakWeightBoundaryAdjThick2 );
					break;
				case TYPE_PrinterAdjustBasicWeightThresholdAdjustThick3:
					setPrinterIndi( TYPE_PrinterAdjustBasicWeightThresholdAdjustThick3, m_ss_BakWeightBoundaryAdjThick3 );
					break;									
				default:
					break;
			}
		default: break;
	}
	// 描画更新.
	setupGamen();
}
//================================================================================================.
// PServiceWeightBoundaryAdj: 90512 サービス・マシン調整・紙種自動検出設定・坪量区分値調整 : ボタン（押し続け、速く変化）.
//================================================================================================.
