{
	if( option == BTNID_ServiceAutoPaperDetectSetting_BelowPlus || option == BTNID_ServiceAutoPaperDetectSetting_BelowMinus ) {	// ＋キー、－キー. 
		 procButtonOn( option ); 
	}
}
//================================================================================================.
// PServiceWeightBoundaryAdj: 90512 サービス・マシン調整・紙種自動検出設定・坪量区分値調整 : 設定終了.
//================================================================================================.
