{
	// 設定値を保存する.
	for( int i = 0; i < STRUCT_SIZE( tbl_ServiceWeightBoundarySettingInfo ); i++ ) {
		fixPrinterIndi( tbl_ServiceWeightBoundarySettingInfo[i].e_PrinterAdjust );
	}
	PServiceAutoPaperDetectSetting::procOk( uc_option );
}
