// comment 2023/02/02 FPT_LinhNV46 [IT6_2.3] [RQ-940_3]「－」「＋」のボタンでの調整ではなく、スライドバーでの調整に画面を修正する。
//	常時検知調整-メディア検知機能無効チョイス【 TYPE_PrinterAdjustMediaAlwaysDetectOffChoice 】.
//	0：OFF　メディア検知機能有効（デフォルト）.
//	1：ON　　メディア検知機能無効.
#define PNLD_ServiceMediaDetectionFunc_ON				0
#define PNLD_ServiceMediaDetectionFunc_OFF				1

struct TYPS_ServiceConstantDetect_Level{
	uchar					uc_LevelSelect;			// ID key.
	short					ss_AdjValue;			// Adjustment value.
};
static const TYPS_ServiceConstantDetect_Level tbl_ServiceConstantDetect_Level[] {
	{ BTNID_ServiceConstantDetectHardDetectLevel5,		5	},
	{ BTNID_ServiceConstantDetectHardDetectLevel4,		4	},
	{ BTNID_ServiceConstantDetectHardDetectLevel3,		3	},
	{ BTNID_ServiceConstantDetectHardDetectLevel2,		2	},
	{ BTNID_ServiceConstantDetectHardDetectLevel1,		1	},
	{ BTNID_ServiceConstantDetectStandard,				0	},
	{ BTNID_ServiceConstantDetectEasyDetectLevel1,		-1	},
	{ BTNID_ServiceConstantDetectEasyDetectLevel2,		-2	},
	{ BTNID_ServiceConstantDetectEasyDetectLevel3,		-3	},
	{ BTNID_ServiceConstantDetectEasyDetectLevel4,		-4	},
	{ BTNID_ServiceConstantDetectEasyDetectLevel5,		-5	},
};
void PServiceRegularDetectionAdj::init_value()
{
// comment 2023/02/02 FPT_LinhNV46 [IT6_2.3] [RQ-940_3]「－」「＋」のボタンでの調整ではなく、スライドバーでの調整に画面を修正する。
	m_ss_OnOffMediaDetectionFunc = PnlComGetPrinterServiceSetting()->getPrinterAdjust( TYPE_PrinterAdjustMediaAlwaysDetectOffChoice );
	m_ss_BakAdjustmentValue = getPrinterIndiInSystem( TYPE_PrinterAdjustMediaAddJudgment );
}

//============================================================================================.
// PServiceRegularDetectionAdj: 90518 サービス・マシン調整・紙種自動検出設定・常時検知調整.
//============================================================================================.
void PServiceRegularDetectionAdj::startGamen()
{
	PServiceAutoPaperDetectSetting::startGamen();	// 紙種自動検出設定.
	Rbt_ServiceAutoPaperDetectSettingP2.select( PNLD_KEY_ServiceRegularDetectionAdj );
	CheckAndExecInit(); 							// 初期化必要か否か取得して必要なら実行する.
	setPrinterIndi( TYPE_PrinterAdjustMediaAddJudgment );
// comment 2023/02/02 FPT_LinhNV46 [IT6_2.3] [RQ-940_3]「－」「＋」のボタンでの調整ではなく、スライドバーでの調整に画面を修正する。
	m_uc_LevelSelect = getIDKeySelect( m_ss_BakAdjustmentValue );
}

//============================================================================================.
// PServiceRegularDetectionAdj: 90518 サービス・マシン調整・紙種自動検出設定・常時検知調整.
//============================================================================================.
void PServiceRegularDetectionAdj::setupGamen( short ss_option )
{
	PServiceAutoPaperDetectSetting::setupGamen( ss_option );
// comment 2023/02/02 FPT_LinhNV46 [IT6_2.3] [RQ-940_3]「－」「＋」のボタンでの調整ではなく、スライドバーでの調整に画面を修正する。
//	Bool bl_isSelected = 0 != m_ss_getKeySelect ? True : False;
//	Rbt_ServiceRegularDetectionAdj.select( m_ss_getKeySelect );
//	Key_ServiceBasisWeightDiscriminationAdj_Plus.showEnable( bl_isSelected );
//	Key_ServiceBasisWeightDiscriminationAdj_Minus.showEnable( bl_isSelected );
//	Txt_WeightServiceThick.showEnable( bl_isSelected );
//	Txt_WeightServiceThin.showEnable( bl_isSelected );
//	Btx_ServiceMainScanDirectionZoomAdj.activate( bl_isSelected );
//	Key_ServiceCancel.showEnable( bl_isSelected );
//	Btx_ServiceMainScanDirectionZoomAdj.set( getPrinterIndi( TYPE_PrinterAdjustMediaAddJudgment ), True );	// 設定値取得.
	if( m_ss_OnOffMediaDetectionFunc == PNLD_ServiceMediaDetectionFunc_ON ){
		Rbt_ServiceRegularDetectionAdj.select( 0 );
		Rbt_ServiceConstantDetect_Level.select( m_uc_LevelSelect );
		Grp_ServiceConstantDetect_Area.showEnable( True );
	} else {
		Rbt_ServiceRegularDetectionAdj.select( 1 );
		Grp_ServiceConstantDetect_Area.showEnable( False );
	}
}

