//============================================================================================.
// PServiceRegularDetectionAdj: 90518 サービス・マシン調整・紙種自動検出設定・常時検知調整.
//============================================================================================.
uchar PServiceRegularDetectionAdj::getIDKeySelect( short ss_value )
{
	uchar uc_IDKeySelect = 0;
	for( uchar uc_LoopCnt = 0; uc_LoopCnt < STRUCT_SIZE( tbl_ServiceConstantDetect_Level ); uc_LoopCnt++ ) {
		if( tbl_ServiceConstantDetect_Level[uc_LoopCnt].ss_AdjValue == ss_value ){
			uc_IDKeySelect = tbl_ServiceConstantDetect_Level[uc_LoopCnt].uc_LevelSelect;
			break;
		}
	}
	return uc_IDKeySelect;
}
