//================================================================================================
void PServiceFSFNCoverSheetTraySizeDetection::procOk( uchar option )
{
	PnlComGetMachineSetting()->setPIDetectSize1( cs_CoverSheetTraySizeMode1Tbl[( uchar )piSizeDetect1].piMode );	// モード1を保存.
	PnlComGetMachineSetting()->setPIDetectSize2( cs_CoverSheetTraySizeMode2Tbl[( uchar )piSizeDetect2].piMode );	// モード2を保存.
	PnlComGetMachineSetting()->setPIDetectSize3( cs_CoverSheetTraySizeMode3Tbl[( uchar )piSizeDetect3].piMode );	// モード3を保存.
	PnlComGetMachineSetting()->setPIDetectSize4( cs_CoverSheetTraySizeMode4Tbl[( uchar )piSizeDetect4].piMode );	// モード4を保存.
	PnlComGetMachineSetting()->setPIDetectSize5( cs_CoverSheetTraySizeMode5Tbl[( uchar )piSizeDetect5].piMode );	// モード5を保存.
	PnlComGetMachineSetting()->setPIDetectSize6( cs_CoverSheetTraySizeMode6Tbl[( uchar )piSizeDetect6].piMode );	// モード6を保存.
	PServiceFinisherAdjCom::procOk( option );
}
//================================================================================================
// 概要		:サービス・フィニッシャ調整・FSFN調整・カバーシートトレイサイズ検知 ： .
//================================================================================================
void PServiceFSFNCoverSheetTraySizeDetection::procGoToPage( uchar option )
{
	switch( option ) {
		case BTNID_KEY_SERV_COVER_SHEET_MODE0: uc_ModeSelect = BTNID_KEY_SERV_COVER_SHEET_MODE0; break;	// モード1を選択.
		case BTNID_KEY_SERV_COVER_SHEET_MODE1: uc_ModeSelect = BTNID_KEY_SERV_COVER_SHEET_MODE1; break;	// モード2を選択.
		case BTNID_KEY_SERV_COVER_SHEET_MODE2: uc_ModeSelect = BTNID_KEY_SERV_COVER_SHEET_MODE2; break;	// モード3を選択.
		case BTNID_KEY_SERV_COVER_SHEET_MODE3: uc_ModeSelect = BTNID_KEY_SERV_COVER_SHEET_MODE3; break;	// モード4を選択.
		case BTNID_KEY_SERV_COVER_SHEET_MODE4: uc_ModeSelect = BTNID_KEY_SERV_COVER_SHEET_MODE4; break;	// モード5を選択.
		case BTNID_KEY_SERV_COVER_SHEET_MODE5: uc_ModeSelect = BTNID_KEY_SERV_COVER_SHEET_MODE5; break;	// モード6を選択.
		default: break;
	}
	PnlComGetMachineSetting()->setPIDetectSize1( cs_CoverSheetTraySizeMode1Tbl[( uchar )piSizeDetect1].piMode );	// モード1を保存.
	PnlComGetMachineSetting()->setPIDetectSize2( cs_CoverSheetTraySizeMode2Tbl[( uchar )piSizeDetect2].piMode );	// モード2を保存.
	PnlComGetMachineSetting()->setPIDetectSize3( cs_CoverSheetTraySizeMode3Tbl[( uchar )piSizeDetect3].piMode );	// モード3を保存.
	PnlComGetMachineSetting()->setPIDetectSize4( cs_CoverSheetTraySizeMode4Tbl[( uchar )piSizeDetect4].piMode );	// モード4を保存.
	PnlComGetMachineSetting()->setPIDetectSize5( cs_CoverSheetTraySizeMode5Tbl[( uchar )piSizeDetect5].piMode );	// モード5を保存.
	PnlComGetMachineSetting()->setPIDetectSize6( cs_CoverSheetTraySizeMode6Tbl[( uchar )piSizeDetect6].piMode );	// モード6を保存.
	setupGamen();
}
//================================================================================================
// 概要		:サービス・フィニッシャ調整・FSFN調整・カバーシートトレイサイズ検知 ： .
//================================================================================================
void PServiceFSFNCoverSheetTraySizeDetection::procButtonOn( uchar option )
{
	switch( option ) {
		case BTNID_KEY_SERV_COVER_SHEET_TYPE0:
		case BTNID_KEY_SERV_COVER_SHEET_TYPE1:
		case BTNID_KEY_SERV_COVER_SHEET_TYPE2:
		case BTNID_KEY_SERV_COVER_SHEET_TYPE3:
		case BTNID_KEY_SERV_COVER_SHEET_TYPE4:
		case BTNID_KEY_SERV_COVER_SHEET_TYPE5:
			switch( uc_ModeSelect ) {
				case BTNID_KEY_SERV_COVER_SHEET_MODE0: piSizeDetect1 = option; break;	// 1番上の用紙選択.
				case BTNID_KEY_SERV_COVER_SHEET_MODE1: piSizeDetect2 = option; break;	// 2番上の用紙選択.
				case BTNID_KEY_SERV_COVER_SHEET_MODE2: piSizeDetect3 = option; break;	// 3番上の用紙選択.
				case BTNID_KEY_SERV_COVER_SHEET_MODE3: piSizeDetect4 = option; break;	// 4番上の用紙選択.
				case BTNID_KEY_SERV_COVER_SHEET_MODE4: piSizeDetect5 = option; break;	// 5番上の用紙選択.
				case BTNID_KEY_SERV_COVER_SHEET_MODE5: piSizeDetect6 = option; break;	// 6番上の用紙選択.
			}
			break;
		default: break;
	}
	setupGamen();
}
//================================================================================================
// 概要		:サービス・フィニッシャ調整・FSFN調整・カバーシートトレイサイズ検知 ： .
//================================================================================================
void PServiceFSFNCoverSheetTraySizeDetection::init_value( )
{
	uint i = 0;
	uc_ModeSelect = BTNID_KEY_SERV_COVER_SHEET_MODE0;		// モード1を選択.
	for( i = 0; i < STRUCT_SIZE( cs_CoverSheetTraySizeMode1Tbl ); i++ ) {	// モード1を取得.
		if( PnlComGetMachineSetting()->getPIDetectSize1() == cs_CoverSheetTraySizeMode1Tbl[i].piMode
		    && cs_CoverSheetTraySizeMode1Tbl[i].text != NULL ) {
			piSizeDetect1 = ( TYPE_PIDetectSize1 )i;
		}
	}
	for( i = 0; i < STRUCT_SIZE( cs_CoverSheetTraySizeMode2Tbl ); i++ ) {	// モード2を取得.
		if( PnlComGetMachineSetting()->getPIDetectSize2() == cs_CoverSheetTraySizeMode2Tbl[i].piMode
		    && cs_CoverSheetTraySizeMode2Tbl[i].text != NULL ) {
			piSizeDetect2 = ( TYPE_PIDetectSize2 )i;
		}
	}
	for( i = 0; i < STRUCT_SIZE( cs_CoverSheetTraySizeMode3Tbl ); i++ ) {	// モード3を取得.
		if( PnlComGetMachineSetting()->getPIDetectSize3() == cs_CoverSheetTraySizeMode3Tbl[i].piMode
		    && cs_CoverSheetTraySizeMode3Tbl[i].text != NULL ) {
			piSizeDetect3 = ( TYPE_PIDetectSize3 )i;
		}
	}
	for( i = 0; i < STRUCT_SIZE( cs_CoverSheetTraySizeMode4Tbl ); i++ ) {	// モード4を取得.
		if( PnlComGetMachineSetting()->getPIDetectSize4() == cs_CoverSheetTraySizeMode4Tbl[i].piMode
		    && cs_CoverSheetTraySizeMode4Tbl[i].text != NULL ) {
			piSizeDetect4 = ( TYPE_PIDetectSize4 )i;
		}
	}
	for( i = 0; i < STRUCT_SIZE( cs_CoverSheetTraySizeMode5Tbl ); i++ ) {	// モード5を取得.
		if( PnlComGetMachineSetting()->getPIDetectSize5() == cs_CoverSheetTraySizeMode5Tbl[i].piMode
		    && cs_CoverSheetTraySizeMode5Tbl[i].text != NULL ) {
			piSizeDetect5 = ( TYPE_PIDetectSize5 )i;
		}
	}
	for( i = 0; i < STRUCT_SIZE( cs_CoverSheetTraySizeMode6Tbl ); i++ ) {	// モード6を取得.
		if( PnlComGetMachineSetting()->getPIDetectSize6() == cs_CoverSheetTraySizeMode6Tbl[i].piMode
		    && cs_CoverSheetTraySizeMode6Tbl[i].text != NULL ) {
			piSizeDetect6 = ( TYPE_PIDetectSize6 )i;
		}
	}
}
