//================================================================================================
void PServiceFSFNCoverSheetTraySizeDetection::setupGamen( short option )
{
	uint i = 0;
	PServiceFinisherAdjCom::setupGamen( option );
	switch( uc_ModeSelect ) {
		case BTNID_KEY_SERV_COVER_SHEET_MODE0:				// モード1の場合
			for( i = 0; i < STRUCT_SIZE( cs_CoverSheetTraySizeMode1Tbl ); i++ ) {
				if( cs_CoverSheetTraySizeMode1Tbl[i].text == NULL ) {	// キーの文字列がない場合、キーを非表示.
					cs_CoverSheetTraySizeMode1Tbl[i].selectButton->showEnable( False );
				} else {
					cs_CoverSheetTraySizeMode1Tbl[i].selectButton->showEnable( True );
					cs_CoverSheetTraySizeMode1Tbl[i].selectButton->changeText( cs_CoverSheetTraySizeMode1Tbl[i].text );
				}
			}
			// 用紙選択.
			Rbt_CoverSheetTraySizeDetectionType.select( piSizeDetect1 );
			break;
		case BTNID_KEY_SERV_COVER_SHEET_MODE1:				// モード2の場合
			for( i = 0; i < STRUCT_SIZE( cs_CoverSheetTraySizeMode2Tbl ); i++ ) {
				if( cs_CoverSheetTraySizeMode2Tbl[i].text == NULL ) {	// キーの文字列がない場合、キーを非表示.
					cs_CoverSheetTraySizeMode2Tbl[i].selectButton->showEnable( False );
				} else {
					cs_CoverSheetTraySizeMode2Tbl[i].selectButton->showEnable( True );
					cs_CoverSheetTraySizeMode2Tbl[i].selectButton->changeText( cs_CoverSheetTraySizeMode2Tbl[i].text );
				}
			}
			// 用紙選択.
			Rbt_CoverSheetTraySizeDetectionType.select( piSizeDetect2 );
			break;
		case BTNID_KEY_SERV_COVER_SHEET_MODE2:				// モード3の場合
			for( i = 0; i < STRUCT_SIZE( cs_CoverSheetTraySizeMode3Tbl ); i++ ) {
				if( cs_CoverSheetTraySizeMode3Tbl[i].text == NULL ) {	// キーの文字列がない場合、キーを非表示.
					cs_CoverSheetTraySizeMode3Tbl[i].selectButton->showEnable( False );
				} else {
					cs_CoverSheetTraySizeMode3Tbl[i].selectButton->showEnable( True );
					cs_CoverSheetTraySizeMode3Tbl[i].selectButton->changeText( cs_CoverSheetTraySizeMode3Tbl[i].text );
				}
			}
			// 用紙選択.
			Rbt_CoverSheetTraySizeDetectionType.select( piSizeDetect3 );
			break;
		case BTNID_KEY_SERV_COVER_SHEET_MODE3:				// モード4の場合
			for( i = 0; i < STRUCT_SIZE( cs_CoverSheetTraySizeMode4Tbl ); i++ ) {
				if( cs_CoverSheetTraySizeMode4Tbl[i].text == NULL ) {	// キーの文字列がない場合、キーを非表示.
					cs_CoverSheetTraySizeMode4Tbl[i].selectButton->showEnable( False );
				} else {
					cs_CoverSheetTraySizeMode4Tbl[i].selectButton->showEnable( True );
					cs_CoverSheetTraySizeMode4Tbl[i].selectButton->changeText( cs_CoverSheetTraySizeMode4Tbl[i].text );
				}
			}
			// 用紙選択.
			Rbt_CoverSheetTraySizeDetectionType.select( piSizeDetect4 );
			break;
		case BTNID_KEY_SERV_COVER_SHEET_MODE4:				// モード5の場合
			for( i = 0; i < STRUCT_SIZE( cs_CoverSheetTraySizeMode5Tbl ); i++ ) {
				if( cs_CoverSheetTraySizeMode5Tbl[i].text == NULL ) {	// キーの文字列がない場合、キーを非表示.
					cs_CoverSheetTraySizeMode5Tbl[i].selectButton->showEnable( False );
				} else {
					cs_CoverSheetTraySizeMode5Tbl[i].selectButton->showEnable( True );
					cs_CoverSheetTraySizeMode5Tbl[i].selectButton->changeText( cs_CoverSheetTraySizeMode5Tbl[i].text );
				}
			}
			// 用紙選択.
			Rbt_CoverSheetTraySizeDetectionType.select( piSizeDetect5 );
			break;
		case BTNID_KEY_SERV_COVER_SHEET_MODE5:				// モード6の場合
			for( i = 0; i < STRUCT_SIZE( cs_CoverSheetTraySizeMode6Tbl ); i++ ) {
				if( cs_CoverSheetTraySizeMode6Tbl[i].text == NULL ) {	// キーの文字列がない場合、キーを非表示.
					cs_CoverSheetTraySizeMode6Tbl[i].selectButton->showEnable( False );
				} else {
					cs_CoverSheetTraySizeMode6Tbl[i].selectButton->showEnable( True );
					cs_CoverSheetTraySizeMode6Tbl[i].selectButton->changeText( cs_CoverSheetTraySizeMode6Tbl[i].text );
				}
			}
			// 用紙選択.
			Rbt_CoverSheetTraySizeDetectionType.select( piSizeDetect6 );
			break;
		default: break;
	}
	// モード選択.
	Rbt_SvcsFSFNCoverSheetTraySizeDetectionMode.select( static_cast<short>( uc_ModeSelect - BTNID_KEY_SERV_COVER_SHEET_MODE0 ) );
}
//================================================================================================================
// 概要     : サービス・CS Remote Care・基本設定・E-Mail2(片方向通信)：.
// 戻り値   :.
//================================================================================================================
void PServiceRDModeDTSettingE2Com::startGamen()
{
	PServiceRDModeRegistCom::startGamen();
	// KMRDS共通遷移.
	TYPE_RdsMode  e_RdsMode    = PnlComGetRdsSetting()->getRdsMode();	// 現在のシステム選択値を取得する。

	if( e_RdsMode == TYPE_RdsModeMailForOne )		// E-mail2設定の場合.
	{	Rbt_SRDModeComGoToButton.select( 0 );	}
	else if( e_RdsMode == TYPE_RdsModeHttp )		// http2設定の場合.
	{	Rbt_SRDModeComGoToButton.select( 5 );	}

	// ローカル変数初期化.
// comment 2014/12/12 【HCL-Rajeev】【CQ-506924】  Klockwork Changes ID:28968/28960/28955 [ABV.GENERAL].
//	clearString( uc_CenterID, DEF_CenterID + 1 );	    // センタID初期化.
//	clearString( uc_DeviceID, DEF_DeviceID + 1 );		// ﾃﾞﾊﾞｲｽID初期化.
//	clearString( uc_EMailADD, DEF_EMailADD + 1 );	    // Emailｱﾄﾞﾚｽ初期化.
	clearString( uc_CenterID, DEF_CenterID );	    // センタID初期化.
	clearString( uc_DeviceID, DEF_DeviceID );		// ﾃﾞﾊﾞｲｽID初期化.
	clearString( uc_EMailADD, DEF_EMailADD );	    // Emailｱﾄﾞﾚｽ初期化.
	b_Coding				= False;					// 暗号化の有無.
	us_CenterNotification	= -1;						// ｾﾝﾀｰ通知項目.
	// 初期値取得.
	APIC_RdsSetting* pc_RdsSetting = PnlComGetRdsSetting();
	pc_RdsSetting->getHostID( ( uchar* )uc_CenterID );		// センタID取得.
	pc_RdsSetting->getMachineID( ( uchar* )uc_DeviceID );		// ﾃﾞﾊﾞｲｽID取得.
	pc_RdsSetting->getHostMailAdr( ( uchar* )uc_EMailADD );		// メールアドレス取得.
	b_Coding = pc_RdsSetting->getEncryptionKeyStat();			// 暗号化状態取得.
	us_CenterNotification = pc_RdsSetting->getCsrcCenterSendSetting();	// センター通知項目.
	for( short i = 0; i < DEF_Schedule; i++ ) {
		cs_Schedule[i] = pc_RdsSetting->getCsrcSendCycle( i );		// スケジュール取得.
	}
}
//================================================================================================================
// 概要     : サービス・CS Remote Care・基本設定・E-Mail2(片方向通信)：.
// 戻り値   :.
//================================================================================================================
void PServiceRDModeDTSettingE2Com::procOk( uchar option )
{
	// CommonAPIに設定.
	// 親クラスを呼ぶ.
	PServiceRDModeRegistCom::procOk( option );
}
//================================================================================================================
// 概要     : サービス・CS Remote Care・基本設定・E-Mail2(片方向通信)：.
// 戻り値   :.
//================================================================================================================
void PServiceRDModeDTSettingE2Com::procGoToPage( uchar option )
{
	// CommonAPIに設定.
	switch( option ) {
		case 80: nextGamen = &gp_ServiceRDModeDTSettingE2; break;	// センター設定.
		case 81:
			if( True == PLBC_FuncVersionCheck::isOK_Type4() ) {
				nextGamen = &gp_ServiceRDModeDTSettingE2Schedule_MZ2nd;		// スケジュール(Minerva/Zeus 2nd用).
			} else {
				nextGamen = &gp_ServiceRDModeDTSettingE2Schedule;			// スケジュール.
			}
			break;
		case 82: nextGamen = &gp_ServiceRDModeDTSettingE2CenterNotification; break;	// センター通知項目.
		case 83: nextGamen = &gp_ServiceRDModeDTSettingE2InitialTransmission; break;	// 初期発信.
		case 90: nextGamen = &gp_ServiceRDModeDTSettingE2CenterIDInput; break;	// センターID.
		case 91: nextGamen = &gp_ServiceRDModeDTSettingE2EMailAddInput; break;	// E-Mailｱﾄﾞﾚｽ.
		default: PServiceRDModeExistMenuCom::procGoToPage( option ); break;
	}
	setupGamen();
}
