	setupInputString( 3, DEF_SizeRDMail2_LineMax, ( char* )uc_EMailADD, ( char* )uc_localEAdd, 0, EP_CharSet_USASCII );
	Btx_SRDModeDTSettingE2EMailAdd.changeExternalText( ( uchar* )uc_localEAdd );
	// 暗号化.
