//================================================================================================
// 概要		: サービス・CS Remote Care・基本設定・E-Mail2(片方向通信)・センターID入力: 全０時クリア処理.
// 戻り値	:Bool False = 全０でない.	True = 全０でクリア.
//			 short	size_string		最大桁数.
//			 Bool	format			全０時にクリアする	False = クリアしない : True = クリアする(Default)
//================================================================================================
Bool PServiceRDModeDTSettingE2CenterIDInput::setZeroCheck( uchar* string, short size_string, Bool format )
{
	Bool b_Check = False;
	// 文字列が最大桁数なら.
	if( ( short )strlen( ( char* )string ) == size_string ) {
		for( register short i = 0; i < size_string; i++ ) {
			if( string[i] != '0' ) {
				b_Check = False;
				break;
			} else {
				b_Check = True;
			}
		}
		// 全０ならば.
		if( b_Check == True && format == True ) {
			// 文字列の初期化.
			memset(	sc_StrKeyboard, 0, sizeof( sc_StrKeyboard ) );
			// スライド文字列管理クラスの初期化.
			c_SlideTextMgr.init_CLCD( sc_StrKeyboard, sc_KeyboardWidth, ss_MaxInputNum, pa_DispField, EP_CharSet_USASCII );
		}
	}
	return b_Check;
}
