//================================================================================================
// 概要     : サービス・CS Remote Care・基本設定・E-Mail2(片方向通信)・Emailアドレス入力: アカウント名確認.
// 戻り値	:Bool TrueならOK FalseならNG.
//================================================================================================
Bool PServiceRDModeDTSettingE2EMailAddInput::CheckLocalPartLength( char* sc_String )
{
	Bool b_result = True;		// チェック結果.
	Bool b_FindAtmark = False;  // @マーク見つけたかのフラグ.
	ushort i = 0;
	for( i = 0; i < strlen( sc_String ); i++ ) {
		if( sc_String[i] == '@' ) {
			b_FindAtmark = True;
			break;
		}
	}
	// 現在の入力箇所が@マークより手前の時はチェックを行う.
	if( ss_CursorPos <= i ) {
		if( ( b_FindAtmark == True ) && ( i < 64 ) ) { // @マークの位置が63(64文字目)以下ならＯＫ.
			b_result = True;
		} else if( ( b_FindAtmark == False ) && ( strlen( sc_String ) < 64 ) ) { // @マークがなくて文字列全体が64文字未満ならＯＫ.
			b_result = True;
		} else {
			b_result = False;
		}
	}
	return b_result;
}
//================================================================================================
// 概要     : サービス・CS Remote Care・基本設定・E-Mail2(片方向通信)・Emailアドレス入力: ドメイン名確認.
// 戻り値	:Bool TrueならOK FalseならNG.
//================================================================================================
Bool PServiceRDModeDTSettingE2EMailAddInput::CheckDomainLength( char* sc_String )
{
	Bool b_result = True;		// チェック結果.
	Bool b_FindAtmark = False;  // @マーク見つけたかのフラグ.
	ushort i = 0;
	for( i = 0; i < strlen( sc_String ); i++ ) {
		if( sc_String[i] == '@' ) {
			b_FindAtmark = True;
			break;
		}
	}
	// @マークがあり、かつ現在の入力箇所が@マークより後のとき
	if( b_FindAtmark == True && i < ss_CursorPos ) {
		if( strlen( sc_String ) - i - 1 < 64 ) {	// @マーク以降63文字以下ならＯＫ.
			b_result = True;
		} else {
			b_result = False;
		}
	} else {
		// @マークなし.
		b_result = True;
	}
	return b_result;
}
//================================================================================================
// 概要     : サービス・CS Remote Care・基本設定・E-Mail2(片方向通信)・Emailアドレス入力: テンキー.
// 戻り値	:なし
//================================================================================================
void PServiceRDModeDTSettingE2EMailAddInput::proc10Key( uchar option )
{
	// Local-part が64文字以上になるようなら受け付けない.
	if( CheckLocalPartLength( ( char* )sc_StrKeyboard ) == False ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}
	// Domain が64文字以上になるようなら受け付けない.
	if( CheckDomainLength( ( char* )sc_StrKeyboard ) == False ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}
	if( option <= 9 ) {
		// 入力された文字を現在位置に挿入.
		if( CheckStringInMedium( ( uchar* )sc_StrKeyboard, DEF_EMailADD + 3, DEF_SizeRDMail2_LineMax_Input ) == True ) {
			// カーソルを一つ進める.
			ss_CursorPos++;
			PServiceRDModeNtKeybordCom::proc10Key( option );
		}
	}
}
//================================================================================================
// 概要     : サービス・CS Remote Care・基本設定・E-Mail2(片方向通信)・Emailアドレス入力: キーボード入力.
// 戻り値	:なし
//================================================================================================
void PServiceRDModeDTSettingE2EMailAddInput::procKeyBoard( uchar option )
{
	// local-part が64文字以上になるようなら受け付けない.
	// ただし、@マークキー、削除キー、←→キーは受け付ける.
	Bool b_CheckOk = True;
	b_CheckOk = CheckLocalPartLength( ( char* )sc_StrKeyboard );
	// Domain が64文字以上になるようなら受け付けない.
	if( b_CheckOk == True ) {
		b_CheckOk = CheckDomainLength( ( char* )sc_StrKeyboard );
	}
	// キーコードを取得.
	char	sc_keyCode[3];
	Kbd_ServiceInputKeybord.getKeyString( option, sc_keyCode );
	switch( sc_keyCode[0] ) {
		case '@':						// @マークキー.
		case PLBD_ArrowLeftKeyCode:		// ←キー押下：カーソル位置を左に移動.
		case PLBD_ArrowRighKeyCode: b_CheckOk = True; break;	// →キー押下：カーソル位置を右に移動.
		case PLBD_DeleteKeyCode:		// Delキー押下：一文字消去.
			// アドレス全体が65文字以上であれば、@マークの削除は出来ない.
			if( 65 < strlen( ( char* )sc_StrKeyboard )
			    && sc_StrKeyboard[ ss_CursorPos ] == '@' )
			{
				b_CheckOk = False;
			} else {
				b_CheckOk = True;
			}
			break;
		default: break;
	}
	// キー受付禁止.
	if( b_CheckOk == False ) {
		return;
	}
	// カーソル位置の計算.
	switch( sc_keyCode[0] ) {
		case PLBD_ArrowLeftKeyCode:			// ←キー押下：カーソル位置を左に移動.
			if( 0 < ss_CursorPos ) {
				ss_CursorPos--;		// カーソルの指す文字位置を移動.
			}
			if( sc_StrKeyboard[ ss_CursorPos ] == '\n' ) { // 改行文字は飛ばす.
				ss_CursorPos--;
			}
			break;
		case PLBD_ArrowRighKeyCode:			// →キー押下：カーソル位置を右に移動.
			if( sc_StrKeyboard[ ss_CursorPos ] != '\0' ) {
				ss_CursorPos++;
			}
			if( sc_StrKeyboard[ ss_CursorPos ] == '\n' ) { // 改行文字は飛ばす.
				ss_CursorPos++;
			}
			break;
		case PLBD_DeleteKeyCode:	// Delキー押下：一文字消去
			if( 0 < ss_CursorPos - 1 ) {
				ss_CursorPos--;
			}
			break;
		default:	// その他のキー押下：入力文字列表示.
			if( ss_CursorPos == ( short )strlen( ( char* )sc_StrKeyboard ) ) { // 現在位置が最後尾の場合.
				// カーソルを一つ進める.
				ss_CursorPos++;
			} else {
				// 入力された文字を現在位置に挿入.
				if( CheckStringInMedium( ( uchar* )sc_StrKeyboard, DEF_EMailADD + 3, DEF_SizeRDMail2_LineMax_Input ) == True ) {
					// カーソルを一つ進める.
					ss_CursorPos++;
				}
			}
			break;
	}
	PServiceRDModeNtKeybordCom::procKeyBoard( option );
}
//================================================================================================
// 概要		:サービス・CS Remote Care・基本設定・E-Mail2(片方向通信)・Emailアドレス入力 : クリアー.
// 戻り値	:なし
//================================================================================================
void PServiceRDModeDTSettingE2EMailAddInput::procClear( uchar option )
{
	// カーソル位置を先頭へ.
	ss_CursorPos = 0;
	// 親クラスを呼ぶ.
	PServiceRDModeNtKeybordCom::procClear( option );
}
//================================================================================================
// 概要		:サービス・CS Remote Care・基本設定・E-Mail2(片方向通信)・Emailアドレス入力 : 文字挿入判定.
// 戻り値	:Bool (True:挿入でる False:挿入できない).
//================================================================================================
Bool PServiceRDModeDTSettingE2EMailAddInput::CheckStringInMedium( uchar* string, short size_stringMax, short ss_Max1LineString )
{
	Bool result = False; // 文字を挿入できたか返すための変数.
	short ss_strLength = static_cast<short>( strlen( ( char* )string ) );
	if( ( ss_strLength <= ss_Max1LineString && ss_strLength < size_stringMax )
	    || ( ss_Max1LineString < ss_strLength && ss_strLength < size_stringMax ) )
	{	// 一文字分以上、空きがある場合.
		result = True; // 文字を挿入できた.
	} else {
		result = False; // 文字を挿入できなかった.
	}
	return( result );
}
//================================================================================================
// 概要     : サービス・CS Remote Care・基本設定・E-Mail2(片方向通信)・Emailアドレス入力: 画面移動.
// 戻り値	:なし
//================================================================================================
void PServiceRDModeDTSettingE2EMailAddInput::procGoToPage( uchar option )
{
	switch( option ) {
		case 60: nextGamen = &gp_ServiceRDModeDTSettingE2; break;	// .
		default: break;
	}
}
//================================================================================================
// 概要     : サービス・CS Remote Care・基本設定・E-Mail2(片方向通信)・Emailアドレス入力: ＯＫキー.
// 戻り値	:なし.
//================================================================================================
void PServiceRDModeDTSettingE2EMailAddInput::procOk( uchar option )
{
	// CommonAPIに設定値を登録.
	APIC_RdsSetting* pc_RdsSetting = PnlComGetRdsSetting();
	pc_RdsSetting->setHostMailAdr( ( uchar* )sc_StrKeyboard );
	nextGamen = &gp_ServiceRDModeDTSettingE2;	// .
}
//■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■.
//================================================================================================================
// 概要     : サービス・CS Remote Care・基本設定・E-Mail2(片方向通信)：.
// 引数		: uchar uc_Num		スケジュール登録番号.
// 戻り値   :.
//================================================================================================================
void PServiceRDModeDTSettingE2Schedule::fixServiceRDModeDTSettingE2Schedule( uchar uc_Num )
{
	// 設定を保存.
	APIC_RdsSetting* pc_RdsSetting = PnlComGetRdsSetting();
	// 日周期.
	if( 1 <= SettingDayCycle.nowValue && SettingDayCycle.nowValue <= 31 ) {	// 範囲内.
		cs_Schedule[ uc_Num ].sc_DayInterval	= ( char )SettingDayCycle.nowValue;
	} else {	// 範囲外.
		cs_Schedule[ uc_Num ].sc_DayInterval	= 1;								// 設定値を「1」に設定.
		inputDigit( 1, &SettingDayCycle );											// ローカル設定値を「1」に設定.
	}
	// 週周期.
	if( 1 <= SettingWeakCycle.nowValue && SettingWeakCycle.nowValue <= 6 ) {	// 範囲内.
		cs_Schedule[ uc_Num ].sc_WeekInterval	= ( char )SettingWeakCycle.nowValue;
	} else {	// 範囲外.
		cs_Schedule[ uc_Num ].sc_WeekInterval	= 1;								// 設定値を「1」に設定.
		inputDigit( 1, &SettingWeakCycle );											// ローカル設定値を「1」に設定.
	}
	// 月周期.
	if( 1 <= SettingMonthCycle.nowValue && SettingMonthCycle.nowValue <= 6 ) {	// 範囲内.
		cs_Schedule[ uc_Num ].sc_MonthInterval	= ( char )SettingMonthCycle.nowValue;
	} else {	// 範囲外.
		cs_Schedule[ uc_Num ].sc_MonthInterval	= 1;								// 設定値を「1」に設定.
		inputDigit( 1, &SettingMonthCycle );										// ローカル設定値を「1」に設定.
	}
	// 日付設定.
	if( 1 <= SettingDaySetting.nowValue && SettingDaySetting.nowValue <= 31 ) {	// 範囲内.
		cs_Schedule[ uc_Num ].sc_Day			= ( char )SettingDaySetting.nowValue;
	} else {	// 範囲外.
		cs_Schedule[ uc_Num ].sc_Day			= 1;								// 設定値を「1」に設定.
		inputDigit( 1, &SettingDaySetting ); 										// ローカル設定値を「1」に設定.
	}
	if( ( cs_Schedule[ uc_ScheduleNo ].b_Schedule != False ) && ( cs_Schedule[ uc_ScheduleNo ].b_Schedule != True ) ) {
		cs_Schedule[ uc_ScheduleNo ].b_Schedule = False;
	}
	if(	( cs_Schedule[ uc_ScheduleNo ].e_CsrcSendCycle != TYPE_CsrcSendCycleNone )		// 未設定.
	    &&	( cs_Schedule[ uc_ScheduleNo ].e_CsrcSendCycle != TYPE_CsrcSendCycleDay )		// 日周期.
	    &&	( cs_Schedule[ uc_ScheduleNo ].e_CsrcSendCycle != TYPE_CsrcSendCycleWeek )		// 週周期.
	    &&	( cs_Schedule[ uc_ScheduleNo ].e_CsrcSendCycle != TYPE_CsrcSendCycleMonth )		// 月周期.
	  )
	{
		cs_Schedule[ uc_ScheduleNo ].e_CsrcSendCycle = TYPE_CsrcSendCycleNone;					// 未設定に設定.
	}
	if(	( cs_Schedule[ uc_ScheduleNo ].e_Week != TYPE_WeekSun )		// 日曜日.
	    &&	( cs_Schedule[ uc_ScheduleNo ].e_Week != TYPE_WeekMon )		// 月曜日.
	    &&	( cs_Schedule[ uc_ScheduleNo ].e_Week != TYPE_WeekTue )		// 火曜日.
	    &&	( cs_Schedule[ uc_ScheduleNo ].e_Week != TYPE_WeekWed )		// 水曜日.
	    &&	( cs_Schedule[ uc_ScheduleNo ].e_Week != TYPE_WeekThr )		// 木曜日.
	    &&	( cs_Schedule[ uc_ScheduleNo ].e_Week != TYPE_WeekFri )		// 金曜日.
	    &&	( cs_Schedule[ uc_ScheduleNo ].e_Week != TYPE_WeekSat )		// 土曜日.
	  )
	{
		cs_Schedule[ uc_ScheduleNo ].e_Week = TYPE_WeekSun;					// 日曜日に設定.
	}
	if( 0 < SettingTimeHour.nowValue && SettingTimeHour.nowValue <= 23 ) {	// 範囲内.
		cs_Schedule[ uc_Num ].uc_Hour			= ( uchar )SettingTimeHour.nowValue;
	} else {	// 範囲外.
		cs_Schedule[ uc_Num ].uc_Hour			= 0;							// 設定値を「0」に設定.
		SettingTimeHour.nowDigit	= 2;										// 現在の桁.
	}
	if( 0 < SettingTimeMinute.nowValue && SettingTimeMinute.nowValue <= 59 ) {	// 範囲内.
		cs_Schedule[ uc_Num ].uc_Minute			= ( uchar )SettingTimeMinute.nowValue;
	} else {	// 範囲外.
		cs_Schedule[ uc_Num ].uc_Minute			= 0;							// 設定値を「0」に設定.
		SettingTimeMinute.nowDigit	= 2;										// 現在の桁.
	}
	pc_RdsSetting->setCsrcSendCycle( uc_Num, cs_Schedule[ uc_Num ] );			// CommonAPIに設定.
	pc_RdsSetting->indRenewalSchedule( uc_Num );								// オブサーバーコール.
}
//================================================================================================================
// 概要     : サービス・CS Remote Care・基本設定・E-mail2・スケジュール：10キー.
// 戻り値   :.
//================================================================================================================
void PServiceRDModeDTSettingE2Schedule::proc10Key( uchar option )
{
	if( option <= 9 ) {
		if( PNLE_CSRCScheduleInputDay == e_ScheduleInput ) {					// 日付設定.
			if( True == PLBC_FuncVersionCheck::isOK_Type4() ) {
				if( 1 != Num_SRDModeDTSettingE2NowPage_MZ2nd.getNumber() ) {
					setBuzzerType( PCGE_BuzzerType_InputNg );
					setupGamen();
					return;
				}
			}
			inputDigit( option, &SettingDaySetting );
		} else if( PNLE_CSRCScheduleInputHour == e_ScheduleInput ) {			// 時刻指定(時).
			inputDigit( option, &SettingTimeHour );
		} else if( PNLE_CSRCScheduleInputMin == e_ScheduleInput ) {			// 時刻指定(分).
			inputDigit( option, &SettingTimeMinute );
		} else if( PNLE_CSRCScheduleInputCycle == e_ScheduleInput ) {			// 日,週,月周期設定.
			if( True == PLBC_FuncVersionCheck::isOK_Type4() ) {
				if( 1 != Num_SRDModeDTSettingE2NowPage_MZ2nd.getNumber() ) {
					setBuzzerType( PCGE_BuzzerType_InputNg );
					setupGamen();
					return;
				}
			}
			switch( cs_Schedule[ uc_ScheduleNo ].e_CsrcSendCycle ) {	// 通知周期の状態.
				case TYPE_CsrcSendCycleDay:		inputDigit( option, &SettingDayCycle );		break;	// 日周期.
				case TYPE_CsrcSendCycleWeek:	inputDigit( option, &SettingWeakCycle );	break;	// 週周期.
				case TYPE_CsrcSendCycleMonth:	inputDigit( option, &SettingMonthCycle );	break;	// 月周期.
				case TYPE_CsrcSendCycleNone:	// 未設定.
				default:
					setBuzzerType( PCGE_BuzzerType_InputNg );
					break;


			}
		}
	}
	setupGamen();
}
//================================================================================================================
// 概要     : サービス・CS Remote Care・基本設定・E-mail2・スケジュール：クリアキー.
// 戻り値   :.
//================================================================================================================
void PServiceRDModeDTSettingE2Schedule::procClear( uchar option )
{
	if( PNLE_CSRCScheduleInputDay == e_ScheduleInput ) {					// 日付設定.
		if( True == PLBC_FuncVersionCheck::isOK_Type4() ) {
			if( 1 != Num_SRDModeDTSettingE2NowPage_MZ2nd.getNumber() ) {
				setBuzzerType( PCGE_BuzzerType_InputNg );
				setupGamen();
				return;
			}
		}
		SettingDaySetting.nowDigit  = -1;		// 現在の桁.
		SettingDaySetting.nowValue  = 0;		// 現在の設定値.
		SettingDaySetting.fixed  = False;		// 確定･不確定フラグ.
	} else if( PNLE_CSRCScheduleInputHour == e_ScheduleInput ) {			// 時刻指定(時).
		SettingTimeHour.nowDigit  = -1;			// 現在の桁.
		SettingTimeHour.nowValue  = 0;			// 現在の設定値.
		SettingTimeHour.fixed  = False;			// 確定･不確定フラグ.
	} else if( PNLE_CSRCScheduleInputMin == e_ScheduleInput ) {			// 時刻指定(分).
		SettingTimeMinute.nowDigit  = -1;		// 現在の桁.
		SettingTimeMinute.nowValue  = 0;		// 現在の設定値.
		SettingTimeMinute.fixed  = False;		// 確定･不確定フラグ.
	} else if( PNLE_CSRCScheduleInputCycle == e_ScheduleInput ) {			// 日,週,月周期設定.
		if( True == PLBC_FuncVersionCheck::isOK_Type4() ) {
			if( 1 != Num_SRDModeDTSettingE2NowPage_MZ2nd.getNumber() ) {
				setBuzzerType( PCGE_BuzzerType_InputNg );
				setupGamen();
				return;
			}
		}
		switch( cs_Schedule[ uc_ScheduleNo ].e_CsrcSendCycle ) {	// 通知周期の状態.
			case TYPE_CsrcSendCycleDay:		// 日周期.
				SettingDayCycle.nowDigit  = -1;			// 現在の桁.
				SettingDayCycle.nowValue  = 0;			// 現在の設定値.
				SettingDayCycle.fixed  = False;			// 確定･不確定フラグ.
				break;
			case TYPE_CsrcSendCycleWeek:	// 週周期.
				SettingWeakCycle.nowDigit  = -1;		// 現在の桁.
				SettingWeakCycle.nowValue  = 0;			// 現在の設定値.
				SettingWeakCycle.fixed  = False;		// 確定･不確定フラグ.
				break;
			case TYPE_CsrcSendCycleMonth:	// 月周期.
				SettingMonthCycle.nowDigit  = -1;		// 現在の桁.
				SettingMonthCycle.nowValue  = 0;		// 現在の設定値.
				SettingMonthCycle.fixed  = False;		// 確定･不確定フラグ.
				break;
			case TYPE_CsrcSendCycleNone:	// 未設定.
			default:
				setBuzzerType( PCGE_BuzzerType_InputNg );
				break;

		}
	}
	setupGamen();
}
//================================================================================================================
// 概要     : サービス・CS Remote Care・基本設定・E-mail2・スケジュール：ボタン押下.
// 戻り値   :.
//================================================================================================================
void PServiceRDModeDTSettingE2Schedule::procButtonOn( uchar option )
{
	switch( option ) {
		case 51:		// 1 キー.
		case 52:		// 2 キー.
		case 53:		// 3 キー.
			// 登録番号を変更.
			uc_ScheduleNo = static_cast<uchar>( option - 51 );
			b_SetScheduleFlg = False;	// 登録フラグ;
			// 日周期.
			SettingDayCycle.nowValue	= cs_Schedule[ uc_ScheduleNo ].sc_DayInterval;	// 現在の設定値.
			SettingDayCycle.nowDigit	= calcDigit( SettingDayCycle.nowValue );		// 現在の桁.
			// 週周期.
			SettingWeakCycle.nowValue	= cs_Schedule[ uc_ScheduleNo ].sc_WeekInterval;	// 現在の設定値.
			SettingWeakCycle.nowDigit	= calcDigit( SettingWeakCycle.nowValue );		// 現在の桁.
			// 月周期.
			SettingMonthCycle.nowValue	= cs_Schedule[ uc_ScheduleNo ].sc_MonthInterval;// 現在の設定値.
			SettingMonthCycle.nowDigit	= calcDigit( SettingMonthCycle.nowValue );		// 現在の桁.
			// 日付設定.
			SettingDaySetting.nowValue	= cs_Schedule[ uc_ScheduleNo ].sc_Day;			// 現在の設定値.
			SettingDaySetting.nowDigit	= calcDigit( SettingDaySetting.nowValue );		// 現在の桁.
			SettingTimeHour.nowValue	= cs_Schedule[ uc_ScheduleNo ].uc_Hour;			// 現在の設定値.
			SettingTimeHour.nowDigit	= 2;											// 現在の桁.
			SettingTimeMinute.nowValue	= cs_Schedule[ uc_ScheduleNo ].uc_Minute;		// 現在の設定値.
			SettingTimeMinute.nowDigit	= 2;											// 現在の桁.
			e_ScheduleInput = PNLE_CSRCScheduleInputCycle;	// 入力状態をクリア	// UV-00756 2010/1/7 柳川.
			break;
		case 20: cs_Schedule[ uc_ScheduleNo ].b_Schedule = True;							break;	// 有効 キー.
		case 21: cs_Schedule[ uc_ScheduleNo ].b_Schedule = False;							break;	// 無効 キー.
		case 22: cs_Schedule[ uc_ScheduleNo ].e_CsrcSendCycle = TYPE_CsrcSendCycleNone;		break;	// 未設定 キー.
		case 23: cs_Schedule[ uc_ScheduleNo ].e_CsrcSendCycle = TYPE_CsrcSendCycleDay;				// 日 キー.
			e_ScheduleInput = PNLE_CSRCScheduleInputCycle;																		// 入力状態を「日/週/月周期」にする UV-00756 2010/1/7 柳川.
			if( True == PLBC_FuncVersionCheck::isOK_Type4() ) {
				Num_SRDModeDTSettingE2NowPage_MZ2nd = 1;	// 1ページ目を表示.
			}
			break;
		case 24: cs_Schedule[ uc_ScheduleNo ].e_CsrcSendCycle = TYPE_CsrcSendCycleWeek;				// 週 キー.
			e_ScheduleInput = PNLE_CSRCScheduleInputCycle;																		// 入力状態を「日/週/月周期」にする UV-00756 2010/1/7 柳川.
			if( True == PLBC_FuncVersionCheck::isOK_Type4() ) {
				Num_SRDModeDTSettingE2NowPage_MZ2nd = 1;	// 1ページ目を表示.
			}
			break;
		case 25: cs_Schedule[ uc_ScheduleNo ].e_CsrcSendCycle = TYPE_CsrcSendCycleMonth;			// 月 キー.
			e_ScheduleInput = PNLE_CSRCScheduleInputCycle;																		// 入力状態を「日/週/月周期」にする UV-00756 2010/1/7 柳川.
			if( True == PLBC_FuncVersionCheck::isOK_Type4() ) {
				Num_SRDModeDTSettingE2NowPage_MZ2nd = 1;	// 1ページ目を表示.
			}
			break;
		case 30: cs_Schedule[ uc_ScheduleNo ].e_Week = TYPE_WeekSun; 						break;	// 日曜.
		case 31: cs_Schedule[ uc_ScheduleNo ].e_Week = TYPE_WeekMon; 						break;	// 月曜.
		case 32: cs_Schedule[ uc_ScheduleNo ].e_Week = TYPE_WeekTue; 						break;	// 火曜.
		case 33: cs_Schedule[ uc_ScheduleNo ].e_Week = TYPE_WeekWed; 						break;	// 水曜.
		case 34: cs_Schedule[ uc_ScheduleNo ].e_Week = TYPE_WeekThr; 						break;	// 木曜.
		case 35: cs_Schedule[ uc_ScheduleNo ].e_Week = TYPE_WeekFri; 						break;	// 金曜.
		case 36: cs_Schedule[ uc_ScheduleNo ].e_Week = TYPE_WeekSat; 						break;	// 土曜.
		case 40: e_ScheduleInput = PNLE_CSRCScheduleInputCycle;									break;	// 日/週/月周期:入力 UV-00756 2010/1/7 柳川.
		case 41: e_ScheduleInput = PNLE_CSRCScheduleInputDay;									break;	// 日付設定:入力 UV-00756 2010/1/7 柳川.
		case BTNID_CSRCScheduleTimeInputHour: e_ScheduleInput = PNLE_CSRCScheduleInputHour;		break;	// 時刻設定(時):入力 UV-00756 2010/1/7 柳川.
		case BTNID_CSRCScheduleTimeInputMin: e_ScheduleInput = PNLE_CSRCScheduleInputMin;		break;	// 時刻設定(分):入力 UV-00756 2010/1/7 柳川.
		case 60:
		case 61:
		case 62:
			if( uc_ScheduleNo == option - 60 ) {
				// スケジュールの登録.
				fixServiceRDModeDTSettingE2Schedule( static_cast<uchar>( option - 60 ) );
				b_SetScheduleFlg = True;	// 登録フラグ;
			} else {
				setBuzzerType( PCGE_BuzzerType_InputNg );	// 拒否音.
			}
			break;
		case BTNID_CSRCScheduleTimeAuto:		// 「時間帯」キー.
			cs_Schedule[ uc_ScheduleNo ].b_TimeManualSetting = False;			// 「時間帯」設定にする.
			e_ScheduleInput = PNLE_CSRCScheduleInputCycle;						// 入力状態を「日/週/月周期」にする.
			break;
		case BTNID_CSRCScheduleTimeManual:		// 「時刻」キー.
			cs_Schedule[ uc_ScheduleNo ].b_TimeManualSetting = True;			// 「時刻」設定にする.
			e_ScheduleInput = PNLE_CSRCScheduleInputCycle;						// 入力状態を「日/週/月周期」にする.
			if( True == PLBC_FuncVersionCheck::isOK_Type4() ) {
				e_ScheduleInput = PNLE_CSRCScheduleInputHour;
			}
			break;
		case BTNID_CSRCScheduleTime0023: cs_Schedule[ uc_ScheduleNo ].e_CsrcTimeRange = TYPE_CsrcTimeRange0To24;	break;	// 「指定無し」キー.
		case BTNID_CSRCScheduleTime0003: cs_Schedule[ uc_ScheduleNo ].e_CsrcTimeRange = TYPE_CsrcTimeRange0To4;		break;	// 00-03キー.
		case BTNID_CSRCScheduleTime0407: cs_Schedule[ uc_ScheduleNo ].e_CsrcTimeRange = TYPE_CsrcTimeRange4To8;		break;	// 04-07キー.
		case BTNID_CSRCScheduleTime0811: cs_Schedule[ uc_ScheduleNo ].e_CsrcTimeRange = TYPE_CsrcTimeRange8To12;	break;	// 08-11キー.
		case BTNID_CSRCScheduleTime1215: cs_Schedule[ uc_ScheduleNo ].e_CsrcTimeRange = TYPE_CsrcTimeRange12To16;	break;	// 12-15キー.
		case BTNID_CSRCScheduleTime1619: cs_Schedule[ uc_ScheduleNo ].e_CsrcTimeRange = TYPE_CsrcTimeRange16To20;	break;	// 16-19キー.
		case BTNID_CSRCScheduleTime2023: cs_Schedule[ uc_ScheduleNo ].e_CsrcTimeRange = TYPE_CsrcTimeRange20To24;	break;	// 20-23キー.
		case 90:
		case 91:
			// 「日/週/月周期」のページめくり.
			if( True == PLBC_FuncVersionCheck::isOK_Type4() ) {
				if( 1 == Num_SRDModeDTSettingE2NowPage_MZ2nd.getNumber() ) {
					Num_SRDModeDTSettingE2NowPage_MZ2nd = 2;
					// 「時刻」の場合は、入力状態を時刻設定(時)に設定する.
					if( True == cs_Schedule[ uc_ScheduleNo ].b_TimeManualSetting ) {
						e_ScheduleInput = PNLE_CSRCScheduleInputHour;
					}
				} else {
					Num_SRDModeDTSettingE2NowPage_MZ2nd = 1;
					switch( cs_Schedule[ uc_ScheduleNo ].e_CsrcSendCycle ) {
						case TYPE_CsrcSendCycleDay:		e_ScheduleInput = PNLE_CSRCScheduleInputCycle;		break;
						case TYPE_CsrcSendCycleWeek:	e_ScheduleInput = PNLE_CSRCScheduleInputCycle;		break;
						case TYPE_CsrcSendCycleMonth:	e_ScheduleInput = PNLE_CSRCScheduleInputCycle;		break;
						case TYPE_CsrcSendCycleNone:	break;
						default:						break;
					}
				}
			}
			break;
		default:		break;
	}
	setupGamen();
}
