void PServiceRDModeDTSettingE2CenterNotification::procButtonOn( uchar option )
{
	switch( option ) {
		case 100:		// 通知しないキー.
			b_CSRCCN[0] = !b_CSRCCN[0];
			if( b_CSRCCN[0] == True ) {
				for( int i = 1; i < DEF_CenterNotificationKey; i++ ) {
					b_CSRCCN[i] = False;
				}
			}
			break;
		case 101:		// 1キー.
		case 102:		// 2キー.
		case 103:		// 3キー.
		case 104:		// 4キー.
		case 105:		// 5キー.
		case 106:		// 6キー.
		case 107:		// 7キー.
		case 108:		// 8キー.
		case 109:		// 9キー.
		case 110:		// 10キー.
		case 111:		// 11キー.
		case 112:		// 12キー.
			b_CSRCCN[ 0 ] = False;
			b_CSRCCN[ option - 100 ] = !b_CSRCCN[ option - 100 ];
			break;
		default: break;	// .
	}
	setupGamen();
}
