// 戻り値   :.
//================================================================================================================
void PServiceRDModeDTSettingE2CenterNotification::fixServiceRDModeDTSettingE2CenterNotification()
{
	// CommonAPIに設定.
	APIC_RdsSetting* pc_RdsSetting = PnlComGetRdsSetting();
	us_CenterNotification =	static_cast<ushort>( DEF_CenterNotification_00 * ( b_CSRCCN[0] == True ? 1 : 0 ) +
	                        DEF_CenterNotification_01 * ( b_CSRCCN[1] == True ? 1 : 0 ) +
	                        DEF_CenterNotification_02 * ( b_CSRCCN[2] == True ? 1 : 0 ) +
	                        DEF_CenterNotification_03 * ( b_CSRCCN[3] == True ? 1 : 0 ) +
	                        DEF_CenterNotification_04 * ( b_CSRCCN[4] == True ? 1 : 0 ) +
	                        DEF_CenterNotification_05 * ( b_CSRCCN[5] == True ? 1 : 0 ) +
	                        DEF_CenterNotification_06 * ( b_CSRCCN[6] == True ? 1 : 0 ) +
	                        DEF_CenterNotification_07 * ( b_CSRCCN[7] == True ? 1 : 0 ) +
	                        DEF_CenterNotification_08 * ( b_CSRCCN[8] == True ? 1 : 0 ) +
	                        DEF_CenterNotification_09 * ( b_CSRCCN[9] == True ? 1 : 0 ) +
	                        DEF_CenterNotification_10 * ( b_CSRCCN[10] == True ? 1 : 0 ) +
	                        DEF_CenterNotification_11 * ( b_CSRCCN[11] == True ? 1 : 0 ) +
	                        DEF_CenterNotification_12 * ( b_CSRCCN[12] == True ? 1 : 0 ) );
	pc_RdsSetting->setCsrcCenterSendSetting( us_CenterNotification );	// センター通知項目.
}
//================================================================================================================
// 概要     : サービス・CS Remote Care・基本設定・E-Mail2(片方向通信)・ｾﾝﾀｰ通知項目：.
// 戻り値   :.
//================================================================================================================
void PServiceRDModeDTSettingE2CenterNotification::startGamen()
{
	// 親クラスを呼ぶ.
	PServiceRDModeDTSettingE2Com::startGamen();
	//初期化.
	for( int i = 0; i < DEF_CenterNotificationKey; i++ ) {
		b_CSRCCN[i] = False;
	}
	if( us_CenterNotification == DEF_CenterNotification_00 ) {
		b_CSRCCN[0] = True;
	} else {
		if( us_CenterNotification & DEF_CenterNotification_01 )		{ b_CSRCCN[1] = True; }
		if( us_CenterNotification & DEF_CenterNotification_02 )		{ b_CSRCCN[2] = True; }
		if( us_CenterNotification & DEF_CenterNotification_03 )		{ b_CSRCCN[3] = True; }
		if( us_CenterNotification & DEF_CenterNotification_04 )		{ b_CSRCCN[4] = True; }
		if( us_CenterNotification & DEF_CenterNotification_05 )		{ b_CSRCCN[5] = True; }
		if( us_CenterNotification & DEF_CenterNotification_06 )		{ b_CSRCCN[6] = True; }
		if( us_CenterNotification & DEF_CenterNotification_07 )		{ b_CSRCCN[7] = True; }
		if( us_CenterNotification & DEF_CenterNotification_08 )		{ b_CSRCCN[8] = True; }
		if( us_CenterNotification & DEF_CenterNotification_09 )		{ b_CSRCCN[9] = True; }
		if( us_CenterNotification & DEF_CenterNotification_10 )		{ b_CSRCCN[10] = True; }
		if( us_CenterNotification & DEF_CenterNotification_11 )		{ b_CSRCCN[11] = True; }
		if( us_CenterNotification & DEF_CenterNotification_12 )		{ b_CSRCCN[12] = True; }
	}
	// E-Mail2の共通遷移.
	TYPE_RdsMode  e_RdsMode    = PnlComGetRdsSetting()->getRdsMode();	// 現在のシステム選択値を取得する。
	if( e_RdsMode == TYPE_RdsModeMailForOne )	// E-mail2設定の場合.
	{	Rbt_SRDModeDTSettingE2Com.select( 2 );	}
	else if( e_RdsMode == TYPE_RdsModeHttp )	// http2設定の場合.
	{	Rbt_SRDModeDTSettinghttp2Com.select( 1 );	}	// http2(片)上部選択キー.
}
//================================================================================================================
// 概要     : サービス・CS Remote Care・基本設定・E-Mail2(片方向通信)・ｾﾝﾀｰ通知項目：.
// 戻り値   :.
//================================================================================================================
void PServiceRDModeDTSettingE2CenterNotification::setupGamen( short option )
{
	// 親クラスを呼ぶ.
	PServiceRDModeDTSettingE2Com::setupGamen( option );
	// 各キーの選択.
	Key_SRDModeDTSettingE2NoNotification.select( b_CSRCCN[0] );		// 通知しないキー.
	Key_SRDModeDTSettingE2_01.select( b_CSRCCN[1] );					// 1キー .
	Key_SRDModeDTSettingE2_02.select( b_CSRCCN[2] );				 	// 2キー .
	Key_SRDModeDTSettingE2_03.select( b_CSRCCN[3] );				 	// 3キー .
	Key_SRDModeDTSettingE2_04.select( b_CSRCCN[4] );					// 4キー .
	Key_SRDModeDTSettingE2_05.select( b_CSRCCN[5] );					// 5キー .
	Key_SRDModeDTSettingE2_06.select( b_CSRCCN[6] );					// 6キー .
	Key_SRDModeDTSettingE2_07.select( b_CSRCCN[7] );					// 7キー .
	Key_SRDModeDTSettingE2_08.select( b_CSRCCN[8] );					// 8キー .
	Key_SRDModeDTSettingE2_09.select( b_CSRCCN[9] );				 	// 9キー .
	Key_SRDModeDTSettingE2_10.select( b_CSRCCN[10] );				 	// 10キー .
	Key_SRDModeDTSettingE2_11.select( b_CSRCCN[11] );					// 11キー .
	Key_SRDModeDTSettingE2_12.select( b_CSRCCN[12] );					// 12キー .

	TYPE_RdsMode  e_RdsMode    = PnlComGetRdsSetting()->getRdsMode();	// 現在のシステム選択値を取得する。
	if( e_RdsMode == TYPE_RdsModeMailForOne ) {	// E-mail2設定の場合.
		Rbt_SRDModeDTSettinghttp2Com.showEnable( False );			// http2(片)上部選択キー.
		Rbt_SRDModeDTSettingE2Com.showEnable( True );				// E-Mail2設定ボタン.
	} else if( e_RdsMode == TYPE_RdsModeHttp ) {	// http2設定の場合.
		Rbt_SRDModeDTSettingE2Com.showEnable( False );				// E-Mail2設定ボタン.
		Rbt_SRDModeDTSettinghttp2Com.showEnable( True );			// http2(片)上部選択キー.
	}

}
