// 概要     : サービス・CS Remote Care・基本設定・E-Mail1(双方向通信)：.
// 戻り値   :.
//================================================================================================================
void PServiceRDModeDTSettingE1Com::procGoToPage( uchar option )
{
	switch( option ) {
		case 80: nextGamen = &gp_ServiceRDModeDTSettingE1; break;	// センター設定.
		case 83: nextGamen = &gp_ServiceRDModeDTSettingE1InitialTransmission; break;	// 初期発信.
		case 90: nextGamen = &gp_ServiceRDModeDTSettingE1CenterIDInput; break;	// センターID.
		case 91: nextGamen = &gp_ServiceRDModeDTSettingE1EMailAddInput; break;	// E-Mailｱﾄﾞﾚｽ.
		default: PServiceRDModeExistMenuCom::procGoToPage( option ); break;
	}
	setupGamen();//表示画面のｾｯﾄｱｯﾌﾟ.
}
//================================================================================================================
// 概要     : サービス・CS Remote Care・基本設定・E-Mail1(双方向通信)：.
// 戻り値   :.
//================================================================================================================
void PServiceRDModeDTSettingE1Com::setupGamen( short option )
{
	// 親クラスを呼ぶ.
	PServiceRDModeRegistCom::setupGamen( option );//表示画面のｾｯﾄｱｯﾌﾟ.
	TYPE_HostStat e_HostStat = PnlComGetRdsSetting()->getHostStat();  // 現在の登録状態を取得する.
	// センタ登録済みの場合.
	if( e_HostStat == TYPE_HostStatRgst ) {
		Key_SRDModeDTSettingE1Transmission.showEnable( False );//初期発信キー非表示.
	} else {
		Key_SRDModeDTSettingE1Transmission.showEnable( True );//初期発信キー表示.
	}
}
