// 概要     : サービス・CS Remote Care・基本設定・E-Mail1(双方向通信)：.
// 戻り値   :.
//================================================================================================================
void PServiceRDModeDTSettingE1::setupGamen( short option )
{
	// 親クラスを呼ぶ.
	PServiceRDModeDTSettingE1Com::setupGamen( option );//表示画面のｾｯﾄｱｯﾌﾟ,初期発信キー表示/非表示.
	APIC_RdsSetting* pc_RdsSetting = PnlComGetRdsSetting();
	TYPE_HostStat e_HostStat = pc_RdsSetting->getHostStat();  // 現在の登録状態を取得する.
	// ｾﾝﾀｰID.
	Btx_SRDModeDTSettingE1CenterIDSet.changeASCIIText( uc_CenterID, DEF_CenterID );	// ｾﾝﾀｰ未登録時キー表示.
	Tfd_SRDModeDTSettingE1CenterIDFix.changeASCIIText( uc_CenterID, DEF_CenterID );	// ｾﾝﾀｰ登録時テキスト表示.
	// ﾃﾞﾊﾞｲｽID.
	Tfd_SRDModeDTSettingE1DeviceID.changeASCIIText( uc_DeviceID, DEF_DeviceID );
	// E-Mailｱﾄﾞﾚｽ.
	uchar	uc_localEAdd[DEF_EMailADD + 3];// Emailｱﾄﾞﾚｽ.
	setupInputString( 3, DEF_SizeRDMail1_LineMax, ( char* )uc_EMailADD, ( char* )uc_localEAdd, 0, EP_CharSet_USASCII ); //文字列の整形,改行.
	Btx_SRDModeDTSettingE1EMailAdd.changeExternalText( ( uchar* )uc_localEAdd ); //ボタン共通パーツ表示.
	// 暗号化.
	Rbt_SRDModeDTSettingE1CodingKey.select( b_Coding );// ｾﾝﾀｰ未登録時キー表示.
	Txt_SRDModeDTSettingE1CodingAnswer.changeText( b_Coding == False ? s_SystemUnitChangeNotDo : s_SystemUnitChangeDo );// ｾﾝﾀｰ登録時テキスト表示.
	// センタ登録済みの場合.
	if( e_HostStat == TYPE_HostStatRgst ) {
		Grp_SRDModeDTSettingE1StatClear.showEnable( False );	// センター未登録(センターID・暗号化のキー表示).
		Grp_SRDModeDTSettingE1StatRgst.showEnable( True );		// センター登録済(センターID・暗号化のテキスト表示).
	} else {
		Grp_SRDModeDTSettingE1StatRgst.showEnable( False );		// センター登録済(センターID・暗号化のテキスト表示).
		Grp_SRDModeDTSettingE1StatClear.showEnable( True );		// センター未登録(センターID・暗号化のキー表示).
	}
}
