//================================================================================================
// 概要     : サービス・CS Remote Care・基本設定・E-Mail1(双方向通信)・Emailアドレス入力: アカウント名確認.
// 戻り値	:Bool TrueならOK FalseならNG.
//================================================================================================
Bool PServiceRDModeDTSettingE1EMailAddInput::CheckLocalPartLength( char* sc_String )
{
	Bool b_result = True;		// チェック結果.
	Bool b_FindAtmark = False;  // @マーク見つけたかのフラグ.
	ushort i;
	for( i = 0; i < strlen( sc_String ); i++ ) {
		if( sc_String[i] == '@' ) {
			b_FindAtmark = True;
			break;
		}
	}
	// 現在の入力箇所が@マークより手前の時はチェックを行う.
	if( ss_CursorPos <= i ) {
		if( ( b_FindAtmark == True ) && ( i < 64 ) ) { // @マークの位置が63(64文字目)以下ならＯＫ.
			b_result = True;
		} else if( ( b_FindAtmark == False ) && ( strlen( sc_String ) < 64 ) ) { // @マークがなくて文字列全体が64文字未満ならＯＫ.
			b_result = True;
		} else {
			b_result = False;
		}
	}
	return b_result;
}
//================================================================================================
// 概要     : サービス・CS Remote Care・基本設定・E-Mail1(片方向通信)・Emailアドレス入力: ドメイン名確認.
// 戻り値	:Bool TrueならOK FalseならNG.
//================================================================================================
Bool PServiceRDModeDTSettingE1EMailAddInput::CheckDomainLength( char* sc_String )
{
	Bool b_result = True;		// チェック結果.
	Bool b_FindAtmark = False;  // @マーク見つけたかのフラグ.
	ushort i = 0;
	for( i = 0; i < strlen( sc_String ); i++ ) {
		if( sc_String[i] == '@' ) {
			b_FindAtmark = True;
			break;
		}
	}
	// @マークがあり、かつ現在の入力箇所が@マークより後のとき
	if( b_FindAtmark == True && i < ss_CursorPos ) {
		if( strlen( sc_String ) - i - 1 < 64 ) {	// @マーク以降63文字以下ならＯＫ.
			b_result = True;
		} else {
			b_result = False;
		}
	} else {
		// @マークなし.
		b_result = True;
	}
	return b_result;
}
//================================================================================================
// 概要     : サービス・CS Remote Care・基本設定・E-Mail1(片方向通信)・Emailアドレス入力: テンキー.
// 戻り値	:なし
//================================================================================================
void PServiceRDModeDTSettingE1EMailAddInput::proc10Key( uchar option )
{
	// Local-part が64文字以上になるようなら受け付けない.
	if( CheckLocalPartLength( ( char* )sc_StrKeyboard ) == False ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );//ブザー音セット.
		return;
	}
	// Domain が64文字以上になるようなら受け付けない.
	if( CheckDomainLength( ( char* )sc_StrKeyboard ) == False ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );//ブザー音セット.
		return;
	}
	if( option <= 9 ) { //数字キーが押されたとき
		// 入力された文字を現在位置に挿入.
		if( CheckStringInMedium( ( uchar* )sc_StrKeyboard, DEF_EMailADD + 3, DEF_SizeRDMail1_LineMax_Input ) == True ) {
			// カーソルを一つ進める.
			ss_CursorPos++;
			PServiceRDModeNtKeybordCom::proc10Key( option );//10キー.キーボード入力共通処理.
		}
	}
}
//================================================================================================
// 概要     : サービス・CS Remote Care・基本設定・E-Mail1(双方向通信)・Emailアドレス入力: キーボード入力.
// 戻り値	:なし
//================================================================================================
void PServiceRDModeDTSettingE1EMailAddInput::procKeyBoard( uchar option )
{
	// local-part が64文字以上になるようなら受け付けない.
	// ただし、@マークキー、削除キー、←→キーは受け付ける.
	Bool b_CheckOk = True;
	b_CheckOk = CheckLocalPartLength( ( char* )sc_StrKeyboard ); //local-partが64文字以内であることをチェック.
	// Domain が64文字以上になるようなら受け付けない.
	if( b_CheckOk == True ) {
		b_CheckOk = CheckDomainLength( ( char* )sc_StrKeyboard );//domainが64文字以内であることをチェック.
	}
	// キーコードを取得.
	char	sc_keyCode[3];
	Kbd_ServiceInputKeybord.getKeyString( option, sc_keyCode );//文字を取得.
	switch( sc_keyCode[0] ) {
		case '@':						// @マークキー.
		case PLBD_ArrowLeftKeyCode:		// ←キー押下：カーソル位置を左に移動.
		case PLBD_ArrowRighKeyCode: b_CheckOk = True; break;	// →キー押下：カーソル位置を右に移動.
		case PLBD_DeleteKeyCode:		// Delキー押下：一文字消去.
			// アドレス全体が65文字以上であれば、@マークの削除は出来ない.
			if( 65 < strlen( ( char* )sc_StrKeyboard )
			    && sc_StrKeyboard[ ss_CursorPos ] == '@' )
			{
				b_CheckOk = False;
			} else {
				b_CheckOk = True;
			}
			break;
		default: break;
	}
	// キー受付禁止.
	if( b_CheckOk == False ) {
		return;
	}
	// カーソル位置の計算.
	switch( sc_keyCode[0] ) {
		case PLBD_ArrowLeftKeyCode:			// ←キー押下：カーソル位置を左に移動.
			if( 0 < ss_CursorPos ) {
				ss_CursorPos--;		// カーソルの指す文字位置を移動.
			}
			if( sc_StrKeyboard[ ss_CursorPos ] == '\n' ) { // 改行文字は飛ばす.
				ss_CursorPos--;
			}
			break;
		case PLBD_ArrowRighKeyCode:			// →キー押下：カーソル位置を右に移動.
			if( sc_StrKeyboard[ ss_CursorPos ] != '\0' ) {
				ss_CursorPos++;
			}
			if( sc_StrKeyboard[ ss_CursorPos ] == '\n' ) { // 改行文字は飛ばす.
				ss_CursorPos++;
			}
			break;
		case PLBD_DeleteKeyCode:	// Delキー押下：一文字消去
			if( 0 < ss_CursorPos - 1 ) {
				ss_CursorPos--;
			}
			break;
		default:	// その他のキー押下：入力文字列表示.
			if( ss_CursorPos == ( short )strlen( ( char* )sc_StrKeyboard ) ) { // 現在位置が最後尾の場合.
				// カーソルを一つ進める.
				ss_CursorPos++;
			} else {
				// 入力された文字を現在位置に挿入.
				if( CheckStringInMedium( ( uchar* )sc_StrKeyboard, DEF_EMailADD + 3, DEF_SizeRDMail1_LineMax_Input ) == True ) {
					// カーソルを一つ進める.
					ss_CursorPos++;
				}
			}
			break;
	}
	PServiceRDModeNtKeybordCom::procKeyBoard( option );
}
//================================================================================================
// 概要		:サービス・CS Remote Care・基本設定・E-Mail1(双方向通信)・Emailアドレス入力 : クリアー.
// 戻り値	:なし
//================================================================================================
void PServiceRDModeDTSettingE1EMailAddInput::procClear( uchar option )
{
	// カーソル位置を先頭へ.
	ss_CursorPos = 0;
	// 親クラスを呼ぶ.
	PServiceRDModeNtKeybordCom::procClear( option );//文字列の初期化処理.
}
//================================================================================================
// 概要		:サービス・CS Remote Care・基本設定・E-Mail1(双方向通信)・Emailアドレス入力 : 文字挿入判定.
// 戻り値	:Bool (True:挿入でる False:挿入できない).
//================================================================================================
Bool PServiceRDModeDTSettingE1EMailAddInput::CheckStringInMedium( uchar* string, short size_stringMax, short ss_Max1LineString )
{
	Bool result = False; // 文字を挿入できたか返すための変数.
	short ss_strLength = static_cast<short>( strlen( ( char* )string ) );
	if( ( ss_strLength <= ss_Max1LineString && ss_strLength < size_stringMax )
	    || ( ss_Max1LineString < ss_strLength && ss_strLength < size_stringMax ) )
	{	// 一文字分以上、空きがある場合.
		result = True; // 文字を挿入できた.
	} else {
		result = False; // 文字を挿入できなかった.
	}
	return( result );
}
