//================================================================================================================
// 概要     : サービス・CS Remote Care・基本設定・E-Mail1(双方向通信)・初期発信：.
// 戻り値   :.
//================================================================================================================
void PServiceRDModeDTSettingE1InitialTransmission::setupGamen( short option )
{
	// 親クラスを呼ぶ.
	PServiceRDModeDTSettingE1Com::setupGamen( option );//表示画面のｾｯﾄｱｯﾌﾟ,初期発信キー表示/非表示.
	APIC_Rds* pc_Rds = PnlComGetRds();
	// 初期発信中なら押下状態.
	if( pc_Rds->isNowTrans( TYPE_RdsTrgKindIni ) == True ) {
		bl_InitSending = True;//初期発信キーのフラグ押下.
	} else {
		bl_InitSending = False;//初期発信キーのフラグ未押下.
	}
	Key_SRDModeInitTrans.select( bl_InitSending );	// 初期発信キー・選択状態.
	Tfd_SRDModeDTSettingE1ITCenterID.changeASCIIText( uc_CenterID, DEF_CenterID );//センターIDテキスト表示.
	Tfd_SRDModeDTSettingE1ITDeviceID.changeASCIIText( uc_DeviceID, DEF_DeviceID );//デバイスIDテキスト表示.
	// Emailｱﾄﾞﾚｽ.
// comment 2015/07/23 OPS1 Sky東島 [Helios][CQ516365].
//	uchar	uc_localEAdd[DEF_EMailADD + 3];
	uchar	uc_localEAdd[DEF_EMailADD + 3 + 1];		// アドレス+改行コード+NULL文字.
	memset( uc_localEAdd, '\0', sizeof( uc_localEAdd ) );

	setupInputString( 3, DEF_SizeRDMail1_LineMax_Transmission, ( char* )uc_EMailADD, ( char* )uc_localEAdd, 0, EP_CharSet_USASCII ); //文字列の整形,改行.
	Tfd_SRDModeDTSettingE1ITEMailAdd.changeExternalText( uc_localEAdd, DEF_EMailADD + 3 );//ボタン共通パーツ表示.
	// 暗号化.
	Txt_SRDModeDTSettingE1ITCodingAnswer.changeText( b_Coding == False ? s_SystemUnitChangeNotDo : s_SystemUnitChangeDo );//暗号化する/しないテキスト表示.
	Bool bl_AllZeroCenterID = True;	// センタＩＤオール０フラグ.
	Bool bl_AllZeroEMailADD = True;	// Emailアドレスオール０フラグ.
	int i;
	// センタＩＤオール０チェック.
	for( i = 0; i < DEF_SizeRDCenterID; i++ ) {
		if(	uc_CenterID[ i ] != '0' ) {
			bl_AllZeroCenterID = False;	// オール０でない.
			break;
		}
	}

	Bool bl_AllZeroDeviceID = True;	// デバイスIDオール０フラグ.
	// デバイスＩＤオール０チェック.
	for( i = 0; i < DEF_DeviceID; i++ ) {
		if(	'0' != uc_DeviceID[ i ] ) {
			bl_AllZeroDeviceID = False;	// オール０でない.
		}
	}

	// E-Mailアドレスオール０チェック.
	for( i = 0; i < DEF_EMailADD; i++ ) {
		if(	uc_EMailADD[ i ] != '0' ) {
			bl_AllZeroEMailADD = False;	// オール０でない.
			break;
		}
	}
	// どれか一つでも未入力であれば、初期発信キーを非表示.
	// センタIDとマシンIDが、オール0(初期値)の場合も初期発信キーを非表示.
	if( strlen( ( char* )uc_CenterID )     != DEF_CenterID ||
	    strlen( ( char* )uc_EMailADD )     == 0 ||
	    ( strlen( ( char* )uc_DeviceID )    != DEF_DeviceID ) ||		// 2009/04/30 第1OSW小尾 DonauDS問題点対応_CQ316979対応 初期発信ボタンの表示条件変更.
	    bl_AllZeroCenterID  == True ||
	    ( bl_AllZeroDeviceID == True ) ||								// 2009/04/30 第1OSW小尾 DonauDS問題点対応_CQ316979対応 初期発信ボタンの表示条件変更.
	    bl_AllZeroEMailADD == True
	  )
	{
		Key_SRDModeInitTrans.showEnable( False );//初期発信キー非表示.
	} else {
		Key_SRDModeInitTrans.showEnable( True );//初期発信キー表示.
	}
}
//////////////////////////////////////////////////////////////
// 概要 : CSRemoteCore／基本設定(http)／共通 : 表示画面のセットアップ.
//////////////////////////////////////////////////////////////
void PServiceRDModeDTSettingHttpCom::setupGamen( short option )
{
	Rbt_SRDModeComGoToButton.select( 0 );			// 「基本設定」を選択状態にする.
	PServiceRDModeRegistCom::setupGamen( option );	// 表示画面のセットアップ

	APIC_RdsSetting* pc_RdsSetting = PnlComGetRdsSetting();
	if( NULL == pc_RdsSetting ) { 
//2019/06/17 Comment [HCLT_Krishnakumar][EagleH][N Rank] Removed unwanted detailed code.
//// 2015/11/05 【HCLT-Dhivya】 【ZeusS_ZX0】 【制御構成変更_No.76-1】Detail macro is passed in API.
//		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if (NULL != pc_BFW_System){
//    		pc_BFW_System->registDetailCode(PNLD_DetailCode_Service_0x1900660100418801);
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" ); 
		return; 
	}
	TYPE_HostStat e_HostStat = pc_RdsSetting->getHostStat();  // 現在の登録状態を取得する。

	// センタ登録済みのときは「初期発信キー」非表示
	if( e_HostStat == TYPE_HostStatRgst ) {
		Key_SRDModeDTSettingInitCallhttp.showEnable( False );
	} else {
		Key_SRDModeDTSettingInitCallhttp.showEnable( True );
	}
	if( False == pc_RdsSetting->getCsrcCommunicationMethod() ) {	// False：(http2選択時(片方向)).
		Key_KEYServiceHeartBeat.showEnable( False );				// HeartBeatキー非表示.
		Key_KEYServicePollingInterval.showEnable( False );			// ポーリング間隔キー非表示.
	}
}

