// 概要 : CSRemoteCore／基本設定(http)／センター／デバイスID(50B00010) : 画面開始処理.
//////////////////////////////////////////////////////////////
void PServiceRDModeDTSettingHttpCtID::startGamen()
{
	PBasicMessageProc::startGamen();

	ss_KeySelect = -1;	// 選択されているボタン（未選択）

	clearString( uc_CenterID,  DEF_SizeRDCenterID );	// センタID初期化(ローカル値)
	clearString( uc_MachineID, DEF_SizeRDMachineID );	// マシンID初期化(ローカル値)

	// キーボード表示.
	Kbd_ServiceInputKeybord.setChangeEnlKeybord( PLBD_Enl_KBD_Initial );
#ifdef DEF_LCD_7INCH
	Kbd_ServiceInputKeybord = PLBC_ConvertKeybord( PLBD_KBT_Alphabet_L, 177, 256, False, True ); // キーボード種類、配置位置設定.
#else //  DEF_LCD_7INCH.
	Kbd_ServiceInputKeybord = PLBC_ConvertKeybord( PLBD_KBT_Alphabet_L, 192, 248, False, True ); // キーボード種類、配置位置設定.
#endif  //  DEF_LCD_7INCH.
	// カーソルクラスへパーツポインタを渡す.
	Kbd_ServiceInputKeybord.GetCursor( NULL );
	startGamenKeybordServiceA();
	// 確定したキーボードに切り替える
	Kbd_ServiceInputKeybord.setKeybordType( PLBD_KBT_Alphabet_L );
	Kbd_ServiceInputKeybord.showKeybord();	// キーボード表示.

	PnlComGetRdsSetting()->getHostID( ( uchar* )uc_CenterID );  // センタID取得.
	PnlComGetRdsSetting()->getMachineID( ( uchar* )uc_MachineID ); // マシンID取得.
}

