//////////////////////////////////////////////////////////////
// 概要 : CSRemoteCore／基本設定(http)／センター／デバイスID(50B00010) : ボタン（押された）.
//////////////////////////////////////////////////////////////
void PServiceRDModeDTSettingHttpCtID::procButtonOn( uchar option )
{
	short i = 0;
	APIC_RdsSetting* pc_RdsSetting = PnlComGetRdsSetting();
	TYPE_HostStat e_HostStat = pc_RdsSetting->getHostStat();  // 現在の登録状態を取得する。
	APIC_Rds* pc_Rds = PnlComGetRds(); // ＲＤＳ(ＡＰＩ)インスタンス取得.

	switch( option ) {
		case 0:	// センタIDキー.
			if( e_HostStat != TYPE_HostStatRgst ) { // センタ未登録なら設定許可
				ss_KeySelect = 0;
			}
			break;

		case SRds_DELETE:// Del.キー
			if( pc_Rds->isNowTrans( TYPE_RdsTrgKindIni ) == True ) {  // 初期発信中ならばキー受付不可.
				MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
				return;
			}

			switch( ss_KeySelect ) {
				case 0: // センタID選択時
					for( i = 0; uc_CenterID[i] != '\0'; i++ );
					if( 0!=i ) {
						i--;
						uc_CenterID[i] = '\0';
					}
					break;
				case 1:	// マシンID選択時
					for( i = 0; uc_MachineID[i] != '\0'; i++ );
					if( 0!=i ) {
						i--;
						uc_MachineID[i] = '\0';
					}
					break;
				default:
					break;
			}
			break;
		default: break;
	}
	setupGamen();	// 表示部品のセットアップ
}

//////////////////////////////////////////////////////////////
// 概要 : CSRemoteCore／基本設定(http)／センター／デバイスID(50B00010) : キーボード.
//////////////////////////////////////////////////////////////
void PServiceRDModeDTSettingHttpCtID::procKeyBoard( uchar option )
{
	APIC_Rds*		 pc_Rds = PnlComGetRds(); // ＲＤＳ(ＡＰＩ)インスタンス取得.
	if( pc_Rds->isNowTrans( TYPE_RdsTrgKindIni ) == True ) {  // 初期発信中ならばキー受付不可.
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}

	char	sc_keyCode[3];
	memset( sc_keyCode, 0x00, sizeof( sc_keyCode ) );
	// キーコードを取得
	Kbd_ServiceInputKeybord.getKeyString( option, sc_keyCode );
	short   i = 0;

	switch( ss_KeySelect ) {
		case 0:	// センタＩＤ選択時
			if( sc_keyCode[0] == PLBD_DeleteKeyCode ) {							// Delキー押下：一文字消去
				for( i = 0; uc_CenterID[i] != '\0'; i++ );
				if( 0!=i ) {
					i--;
					uc_CenterID[i] = '\0';
				}
				else {
					MCR_setBuzzerType( PCGE_BuzzerType_InputNg );		// 拒否音.
					break;
				}
			} else {
				setStringWithCheck( uc_CenterID, sc_keyCode[0], DEF_SizeRDCenterID );
			}
			break;
		case 1:	// マシンＩＤ選択時
			if( sc_keyCode[0] == PLBD_DeleteKeyCode ) {							// Delキー押下：一文字消去
				for( i = 0; uc_MachineID[i] != '\0'; i++ );
				if( 0!=i ) {
					i--;
					uc_MachineID[i] = '\0';
				}
			} else {
				setStringWithCheck( uc_MachineID, sc_keyCode[0], DEF_SizeRDMachineID );
			}
			break;
		default:
			setBuzzerType( PCGE_BuzzerType_InputNg );
			break;
	}
	setupGamen();				// 表示部品のセットアップ
}

//////////////////////////////////////////////////////////////
// 概要 : CSRemoteCore／基本設定(http)／センター／デバイスID(50B00010) : テンキー.
//////////////////////////////////////////////////////////////
void PServiceRDModeDTSettingHttpCtID::proc10Key( uchar option )
{
	APIC_Rds*		 pc_Rds = PnlComGetRds(); // ＲＤＳ(ＡＰＩ)インスタンス取得.
	if( pc_Rds->isNowTrans( TYPE_RdsTrgKindIni ) == True ) {  // 初期発信中ならばキー受付不可.
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}

	switch( ss_KeySelect ) {
		case 0:	// センタＩＤ選択時
			if( option <= 9 ) {
				setStringWithCheck( uc_CenterID, static_cast<uchar>( option+'0' ), DEF_SizeRDCenterID );
			}
			break;
		case 1:	// マシンＩＤ選択時
			if( option <= 9 ) {
				setStringWithCheck( uc_MachineID, static_cast<uchar>( option+'0' ), DEF_SizeRDMachineID );
			}
			break;
		default:
			setBuzzerType( PCGE_BuzzerType_InputNg );
			break;
	}
	setupGamen();	// 表示部品のセットアップ
}

//////////////////////////////////////////////////////////////
// 概要 : CSRemoteCore／基本設定(http)／センター／デバイスID(50B00010) : クリアキー.
//////////////////////////////////////////////////////////////
void PServiceRDModeDTSettingHttpCtID::procClear( uchar option )
{
	APIC_Rds*		 pc_Rds = PnlComGetRds(); // ＲＤＳ(ＡＰＩ)インスタンス取得.
	if( pc_Rds->isNowTrans( TYPE_RdsTrgKindIni ) == True ) {  // 初期発信中ならばキー受付不可.
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}

	switch( ss_KeySelect ) {
		case 0:
		//Comment 2014/11/12 HCLT-Arun [CQ_501039] For Rejection Sound.
		if(*uc_CenterID != '\0')
			clearString( uc_CenterID, DEF_SizeRDCenterID );	
		else
			setBuzzerType( PCGE_BuzzerType_InputNg ); 
		break;	// センタIDのクリア
		case 1:
			clearString( uc_MachineID, DEF_SizeRDMachineID );	break;	// マシンIDのクリア
		default:
			setBuzzerType( PCGE_BuzzerType_InputNg );
			break;
	}
	setupGamen();				// 表示部品のセットアップ
}

//////////////////////////////////////////////////////////////
// 概要 : CSRemoteCore／基本設定(http)／センター／デバイスID(50B00010) : データ登録処理.
//////////////////////////////////////////////////////////////
void PServiceRDModeDTSettingHttpCtID::setRegistData()
{
	// センタＩＤ、マシンＩＤが指定桁数に満たない場合はクリアする.
// Comment 2017/12/12 [HCLT-Suribabu][AR1030248] Preserving the  Default value upto 5 Digits.
//	if( strlen( ( char* )uc_CenterID ) < DEF_SizeRDCenterID )
//	{	clearString( uc_CenterID, DEF_SizeRDCenterID );		}	// センタID初期化.
	uchar	uc_CenterID_tmp[ DEF_CenterID + 1 ];		// Center ID.
	memset( uc_CenterID_tmp, 0, DEF_CenterID + 1 );		// Center ID.
	PnlComGetRdsSetting()->getHostID( ( uchar* )uc_CenterID_tmp );
	if( 0 != strcmp( ( char* )uc_CenterID_tmp, ( char* )uc_CenterID ) ){
	 	if( strlen( ( char* )uc_CenterID ) < DEF_SizeRDCenterID ){			// Checking the CenterID size.
	 		clearString( uc_CenterID, DEF_SizeRDCenterID );	  				// Clearing the CenterID value, if less than 5 digits.
	 	}
	 }
	if( strlen( ( char* )uc_MachineID ) < DEF_SizeRDMachineID )
	{	clearString( uc_MachineID, DEF_SizeRDMachineID );	}	// マシンID初期化.

	PnlComGetRdsSetting()->setHostID( ( uchar* )uc_CenterID );  // センタID設定.
	PnlComGetRdsSetting()->setMachineID( ( uchar* )uc_MachineID ); // マシンID設定.
}

//////////////////////////////////////////////////////////////
// 概要 : CSRemoteCore／基本設定(http)／センター／デバイスID(50B00010) : 終了処理.
//////////////////////////////////////////////////////////////
void PServiceRDModeDTSettingHttpCtID::endGamen()
{
	PBasicMessageProc::endGamen();
	Kbd_ServiceInputKeybord = PLBC_ConvertKeybord( PLBD_KBT_Alphabet_L, 192, 230, False, True ); // キーボード種類、配置位置設定.
}
// -----------------------------------------------------------------------------------------------
// クラス	：PServiceRDModeDTSettingHttpCtID.
// 関数名	：procRMPStrInput.
// 引数		：uchar option.
// 戻り値	：なし.
// 備考		：.
// 作成者	：OPS1 棚.
// -----------------------------------------------------------------------------------------------
void PServiceRDModeDTSettingHttpCtID::procRMPStrInput( uchar option )
{
	switch( ss_KeySelect ) {
		case 0:	// センタＩＤ選択時.
			PNLC_RMPStrInputMng::newInstance()->setStringToBuffer_TypeCenterID( ( char* )uc_CenterID, ( ushort )DEF_SizeRDCenterID );
			break;
		case 1:	// マシンＩＤ選択時.
			PNLC_RMPStrInputMng::newInstance()->setStringToBuffer_TypeCenterID( ( char* )uc_MachineID, ( ushort )DEF_SizeRDMachineID );
			break;
		default:
			break;
	}
	setupGamen();
}

