//////////////////////////////////////////////////////////////
// 概要 : Core／基本設定(http)／HeartBeat(50B00030_CS_Remote) : テンキー.
//////////////////////////////////////////////////////////////
void PServiceRDModeDTSettingHB::proc10Key( uchar option )
{
	Bool b_isError = False;
	switch( ss_InputSelect ) {
		case 0:	// 通信間隔が入力状態の場合.
			if( ( True == b_Direct[0] ) && ( 0 == option ) ) { // If 0 is pressed after screen startup, it should give NG.
				setBuzzerType( PCGE_BuzzerType_InputNg );
			}
			ss_CommunicationInterval = ( short )proc10KeyInput( ss_CommunicationInterval, 256, option, b_Direct[0], EP_InputMaxLimitPattern_Refuse, &b_isError );
			b_Direct[0] = False;
			break;
		case 1:	// 時が入力状態の場合.
			if( ( True == b_Direct[1] ) && ( 0 == option ) ) {	// When "0" is pressed first time
				if( 0 != c_Time.sc_Hour ) { 					// When other than "0" was present.
					setBuzzerType( PCGE_BuzzerType_InputNg );
				} else { // If "0" was present initially, then it should break from here, to not to pass False to the set() function.
					break;
				}
			}
			c_Time.sc_Hour = ( schar )proc10KeyInput( c_Time.sc_Hour, 23, option, b_Direct[1], EP_InputMaxLimitPattern_Refuse, &b_isError );
			b_Direct[1] = False;
			break;
		case 2:	// 分が入力状態の場合.
			if( ( True == b_Direct[2] ) && ( 0 == option ) ) {	// When "0" is pressed first time
				if( 0 != c_Time.sc_Minute ) { 				// When other than "0" was present.
					setBuzzerType( PCGE_BuzzerType_InputNg );
				} else { // If "0" was present initially, then it should break from here, to not to pass False to the set() function.
					break;
				}
			}
			c_Time.sc_Minute = ( schar )proc10KeyInput( c_Time.sc_Minute, 59, option, b_Direct[2], EP_InputMaxLimitPattern_Refuse, &b_isError );
			b_Direct[2] = False;
			break;
		default:
			setBuzzerType( PCGE_BuzzerType_InputNg );
			break;
	}
	if( True == b_isError ) {
		setBuzzerType( PCGE_BuzzerType_InputNg );
	}
	setupGamen();	//表示画面のセットアップ.
}

//////////////////////////////////////////////////////////////
// 概要 : Core／基本設定(http)／HeartBeat(50B00030_CS_Remote) : クリアキー.
//////////////////////////////////////////////////////////////
void PServiceRDModeDTSettingHB::procClear( uchar option )
{
	switch( ss_InputSelect ) {
		case 0:	// 通信間隔が入力状態の場合.
			ss_CommunicationInterval = 1;
			b_Direct[0] = True;
			break;
		case 1:	// 時が入力状態の場合.
			c_Time.sc_Hour = 0;
			b_Direct[1] = True;
			break;
		case 2:	// 分が入力状態の場合.
			c_Time.sc_Minute = 0;
			b_Direct[2] = True;
			break;
		default:	break;
	}
	setupGamen();	//表示画面のセットアップ.
}

//////////////////////////////////////////////////////////////
// 概要 : Core／基本設定(http)／HeartBeat(50B00030_CS_Remote) : 表示画面のセットアップ.
//////////////////////////////////////////////////////////////
void PServiceRDModeDTSettingHB::setupGamen( short option )
{
	Rbt_SRDModeDTSettingComhttp.select( 2 );							// CSRemoteCore／基本設定(http) 上側のローテーションボタン.
	Rbt_SRDTimeDispatch.select( b_TimeDispatch );						// 指定時刻発信する/しない.
	Rbt_CommunicationDoNotDo.select( b_Communication );					// 通信する/しない.
	Rbt_SRDModeDTSettingHBInputSelect.select( ss_InputSelect );			// テンキー入力 通信間隔/時/分.
	Bak_CommunicationInterval.set( ss_CommunicationInterval, b_Direct[0] );	// 通信間隔：黒エリア.
	Bak_ITMSpecifyTimeSendHour.set( ( short )c_Time.sc_Hour, b_Direct[1] );		// 指定時刻発信：時：黒エリア.
	Bak_ITMSpecifyTimeSendMinute.set( ( short )c_Time.sc_Minute, b_Direct[2] );	// 指定時刻発信：分：黒エリア.

	PServiceRDModeDTSettingHttpCom::setupGamen( option );				// 表示画面のセットアップ
}
//////////////////////////////////////////////////////////////
// 概要 : Core／基本設定(http)／HeartBeat(50B00030_CS_Remote) : データ登録処理.
//////////////////////////////////////////////////////////////
void PServiceRDModeDTSettingHB::setRegistData()
{
	PnlComGetRdsSetting()->setHeartBeatOn( b_Communication );						// Heart Beat通信設定.
	PnlComGetRdsSetting()->setHeartBeatTimerDispatchOn( b_TimeDispatch );			// Heart Beat指定時刻発信設定.
	PnlComGetRdsSetting()->setHeartBeatCommInterval( ss_CommunicationInterval );	// Heart Beat通信間隔設定 （分）.
	PnlComGetRdsSetting()->setHeartBeatStartTime( c_Time );							// Heart Beat指定時刻発信設定.
}

