//================================================================================================.
void PServiceRDModeDTSettingPollingInterval::startGamen()
{
	PServiceRDModeDTSettingHttpCom::startGamen();	// 親クラスを呼ぶ.

	// HTTPポーリング間隔を取得する.
	if( NULL != PnlComGetRdsSetting() ) {
		m_usHttpPollingInterval = PnlComGetRdsSetting()->getPollingTimeForHTTP();
	} else {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	m_bl_Direct = False;		// ダイレクト入力OFF.
}

//================================================================================================.
// 概要		: D0B0000070 CS Remote Care／基本設定(http)／ポーリング間隔 : OKキー.
// 戻り値	:なし.
// 備考		:.
//================================================================================================.
void PServiceRDModeDTSettingPollingInterval::procOk( uchar option )
{
	if( m_usHttpPollingInterval < PNLD_ServiceRDModeDTSettingPollingInterval_MIN || PNLD_ServiceRDModeDTSettingPollingInterval_MAX < m_usHttpPollingInterval ) {
		setBuzzerType( PCGE_BuzzerType_InputNg );			// ブザー音セット.
		return;
	}
	// HTTPポーリング間隔を設定する.
	if( NULL != PnlComGetRdsSetting() ) {
		PnlComGetRdsSetting()->setPollingTimeForHTTP( m_usHttpPollingInterval );
	}
	PServiceRDModeDTSettingHttpCom::procOk( option );		// 親クラスを呼ぶ.
}

//================================================================================================.
// 概要		: D0B0000070 CS Remote Care／基本設定(http)／ポーリング間隔 : テンキー.
// 戻り値	:なし.
// 備考		:.
//================================================================================================.
void PServiceRDModeDTSettingPollingInterval::proc10Key( uchar option )
{
	Bool bl_Error = False;
	m_usHttpPollingInterval = ( ushort )proc10KeyInput( m_usHttpPollingInterval, PNLD_ServiceRDModeDTSettingPollingInterval_MAX, option, m_bl_Direct, EP_InputMaxLimitPattern_Refuse, &bl_Error );
	if( True == bl_Error ) {
		setBuzzerType( PCGE_BuzzerType_InputNg );
	} else {
		if( ( True == m_bl_Direct ) && ( 0 == option ) ) {  // 最初の入力が０を押されたら.
			setBuzzerType( PCGE_BuzzerType_InputNg );
		} else {
			m_bl_Direct = False;	// ダイレクト入力OFF.
		}
	}
	setupGamen();	//表示画面のセットアップ.
}

