//////////////////////////////////////////////////////////////
// 概要 : CS_Remote_Core／基本設定(http)／初期発信(50B00040) : 画面開始処理.
//////////////////////////////////////////////////////////////
void PServiceRDModeDTSettingInitialT::startGamen()
{
	PServiceRDModeDTSettingHttpCom::startGamen();	// 親クラスを呼ぶ.
	// 設定値の取得処理.
	// ローカル変数初期化.
// comment 2014/12/12 【HCL-Rajeev】【CQ-506924】  Klockwork Changes ID:28966/28949/28950 [ABV.GENERAL].
//	clearString( uc_CenterID, DEF_SizeRDCenterID + 1 );		// センタID初期化.
//	clearString( uc_MachineID, DEF_SizeRDMachineID + 1 );	// ﾃﾞﾊﾞｲｽID初期化.
//	clearString( uc_UrlADD, DEF_URLADD + 1 );				// URLlｱﾄﾞﾚｽ初期化.
	clearString( uc_CenterID, DEF_SizeRDCenterID );		// センタID初期化.
	clearString( uc_MachineID, DEF_SizeRDMachineID );	// ﾃﾞﾊﾞｲｽID初期化.
	clearString( uc_UrlADD, DEF_URLADD );				// URLlｱﾄﾞﾚｽ初期化.
	b_Coding				= False;						// 暗号化の有無を初期化(無に設定).

	PnlComGetRdsSetting()->getHostID( ( uchar* )uc_CenterID );		// センタID取得.
	PnlComGetRdsSetting()->getMachineID( ( uchar* )uc_MachineID );		// ﾃﾞﾊﾞｲｽID取得.
	b_Coding = PnlComGetRdsSetting()->getCsrcTextEncryptionOn();		// 暗号化状態のフラグ取得.

	// プロダクト認証の有無を判定.
	if( TYPE_EnableProductCertificationOn == PnlComGetRdsSetting()->getEnableProductCertification() ) {
		// プロダクト認証有効時、プロダクト認証で使用しているWebサーバURLアドレス情報.
		PnlComGetRdsSetting()->getCsrcWebServerUrlAddressForProductCert( uc_UrlADD );
	} else {
		// 通常時のWebサーバURLアドレス情報.
		PnlComGetRdsSetting()->getCsrcWebServerUrlAddress( uc_UrlADD );
	}

	Bool bl_AllZeroCenterID  = True;	// センタＩＤオール０フラグ.
	Bool bl_AllZeroMachineID = True;	// マシンＩＤオール０フラグ.

	// センタＩＤオール０チェック.
	short i = 0;	// カウンタ用.
	for( i = 0; i < DEF_SizeRDCenterID; i++ ) {
		if(	uc_CenterID[ i ] != '0' )
		{	bl_AllZeroCenterID = False;	}	// オール０でない.
	}

	// マシンＩＤオール０チェック.
	for( i = 0; i < DEF_SizeRDMachineID; i++ ) {
		if(	uc_MachineID[ i ] != '0' )
		{	bl_AllZeroMachineID = False;	}	// オール０でない.
	}

	// どれか一つでも未入力であれば、初期発信キーを非表示
	// センタIDとマシンIDが、オール0(初期値)の場合も初期発信キーを非表示.
	if( strlen( ( char* )uc_CenterID )     != DEF_SizeRDCenterID ||
	    strlen( ( char* )uc_MachineID )    != DEF_SizeRDMachineID ||
	    bl_AllZeroCenterID  == True || bl_AllZeroMachineID == True ||
	    strlen( ( char* )uc_UrlADD ) == 0 )
	{	Key_SRDInitialTransmissionStart.showEnable( False );	}
	else
	{	Key_SRDInitialTransmissionStart.showEnable( True );	}
}
//////////////////////////////////////////////////////////////
// 概要 : CS_Remote_Core／基本設定(http)／初期発信(50B00040) : ボタン（押された）.
//////////////////////////////////////////////////////////////
void PServiceRDModeDTSettingInitialT::procButtonOn( uchar option )
{
	if( option == 13 ) { // 初期発信キー押下.
		PnlComGetRds()->indTrg( TYPE_RdsTrgKindIni );	// 初期発信開始メッセージ発信.
		// EMIテストモードでなければ初期発信キーを押下状態にする.
		if( PnlComGetRdsSetting()->getEMITestMode() == 0 ) { // EMIテストモードでない場合.
			bl_InitSending = True;	 // 初期発信キーを押下状態にする.
		}
	}
}
//////////////////////////////////////////////////////////////
// 概要 : CS_Remote_Core／基本設定(http)／初期発信(50B00040) : 画面遷移ボタン（押された）.
//////////////////////////////////////////////////////////////
void PServiceRDModeDTSettingInitialT::procGoToPage( uchar option )
{
	PServiceRDModeDTSettingHttpCom::procGoToPage( option );
}

//////////////////////////////////////////////////////////////
// 概要 : CS_Remote_Core／基本設定(http)／初期発信(50B00040) : 表示画面のセットアップ.
//////////////////////////////////////////////////////////////
void PServiceRDModeDTSettingInitialT::setupGamen( short option )
{
	Rbt_SRDModeDTSettingComhttp.select( 4 );							// CSRemoteCore／基本設定(http) 上側のローテーションボタン.
	Tfd_SRDInitialTCenterMachineID.changeASCIIText( uc_CenterID );		// ｾﾝﾀｰID値表示
	Tfd_SRDInitialTDeviceID.changeASCIIText( uc_MachineID );			// ﾃﾞﾊﾞｲｽID値表示

	uchar uc_UrlADDDisp[ DEF_URLADD + 6 ];								// URLアドレス表示用.
	memset( uc_UrlADDDisp, 0, sizeof( uc_UrlADDDisp ) );
	setupInputString( 6, DEF_SizeRDMail2_LineMax_Transmission, ( char* )uc_UrlADD, ( char* )uc_UrlADDDisp, 0 ,EP_CharSet_USASCII );	// 6行にする.
	Tfd_SRDInitialTURLAddress.changeExternalText( uc_UrlADDDisp );		// URLアドレス値表示
	Txt_SRDInitialTEncryptionState.changeText( True == b_Coding ? s_SystemUnitChangeDo : s_SystemUnitChangeNotDo );	// 暗号化設定値表示.

	// 初期発信中なら押下状態.
	APIC_Rds* pc_Rds = PnlComGetRds();
	if( pc_Rds->isNowTrans( TYPE_RdsTrgKindIni ) == True ) {
		bl_InitSending = True;
	} else {
		bl_InitSending = False;
	}
	Key_SRDInitialTransmissionStart.select( bl_InitSending );

	PServiceRDModeDTSettingHttpCom::setupGamen( option );				// 表示画面のセットアップ
}
// ==================================================================
// PServiceRDModeNtHttpUrlAdd : 50B00100 CS_Remote_Core／サーバ設定(http)／URLアドレス／画面開始処理.
// ==================================================================
void PServiceRDModeNtHttpUrlAdd::startGamen()
{
	PServiceRDModeNtIPInputcom::startGamen();

	// ComonAPIから設定情報取得.
	PnlComGetRdsSetting()->getCsrcWebServerUrlAddress( uc_Address );		// WebサーバURLアドレス情報.

	if( isIPAddress( ( char* )uc_Address, ( ushort )strlen( ( char* )uc_Address ) ) ) {
		bl_InputIPAddress = True;
		CharToIPAddress( ( char* )uc_Address, ( uchar* )uc_AdressValue );	// 取得した文字列をIPアドレス形式に変換.
	} else {
		bl_InputIPAddress = False;
	}
}

// ==================================================================
// PServiceRDModeNtHttpUrlAdd : 50B00100 CS_Remote_Core／サーバ設定(http)／URLアドレス／画面移動.
