void PServiceRDModeNtHttpUrlAdd::procGoToPage( uchar option )
{
	setRegistData(); // データ登録処理.
	switch( option ) {
		case 10:
			nextGamen = &gp_ServiceRDModeNtHttpUrlFQDN;			break;	// サービス・KMRDS・サーバ設定(http)／URLアドレスFQDN入力.
		default:
			PServiceRDModeNtIPInputcom::procGoToPage( option );	break;
	}
}
