uchar PServiceRDModeProductCertificateCom::uc_SelectMenu = 0;
//================================================================================================
// 概要		：サービス・CS_Remote_Core・プロダクト認証設定共通：画面開始処理.
//================================================================================================
void PServiceRDModeProductCertificateCom::startGamen()
{
	PServiceNoFunctionCodeCom::startGamen();
	e_InstallSts 	= InstallDeleteExecution_None;
	e_DeleteSts 	= InstallDeleteExecution_None;
	e_VerificationSts = InstallDeleteExecution_None;
}
/*================================================================================================
//概要    :サービス・CSRemoteCare・プロダクト認証設定共通 : OKキー.
================================================================================================*/
void PServiceRDModeProductCertificateCom::procOk( uchar option )
{
	// インストール実行中時は移動不可.
	if( InstallDeleteExecution_Executing == e_InstallSts
	    || InstallDeleteExecution_Executing == e_VerificationSts
	    || InstallDeleteExecution_Executing == e_DeleteSts ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );		// 拒否音.
		return;
	}
// comment 2017/06/05 日立 田中 [MAv5-1][RQ-710] CSRA接続.
//	nextGamen = &gp_ServiceCSRemoteCaremMenu;	//サービス・CSRemoteCare.
	nextGamen = &gp_ServiceCSRemoteCareMenu;	// zcB0011000_CS Remote Care／メニュー.
}
/*================================================================================================
//概要    :サービス・CSRemoteCare・プロダクト認証設定共通 : 表示画面のセットアップ.
================================================================================================*/
void PServiceRDModeProductCertificateCom::setupGamen( short option )
{
	PServiceNoFunctionCodeCom::setupGamen( option );
	Rbt_RDModeProductCertificateMenu.select( uc_SelectMenu );

	Rbt_RDModePcWebdavMenu.select( uc_SelectWebDAVMenu );

	// 削除キーの表示/非表示
	bool DeleteShowFlg = False;
	if( ( TYPE_EnableProductCertificationOff == PnlComGetRdsSetting()->getEnableProductCertification() 	// プロダクト認証 = 「しない」& 証明書登録済み.
	      && True == PnlComGetRdsSetting()->getProductCertStatus() )
	    || 3 == uc_SelectMenu ) {					// 削除画面にいる場合.
		DeleteShowFlg = True;
	}
	Key_IndexRDModePcDelete.showEnable( DeleteShowFlg );
}
//================================================================================================
// 概要		：サービス・CS_Remote_Core・プロダクト認証設定共通：リセットキー.
//================================================================================================
void PServiceRDModeProductCertificateCom::procReset( uchar option )
{
	// インストール実行中時は移動不可.
	if( InstallDeleteExecution_Executing == e_InstallSts
	    || InstallDeleteExecution_Executing == e_VerificationSts
	    || InstallDeleteExecution_Executing == e_DeleteSts ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );		// 拒否音.
		return;
	}
	PServiceNoFunctionCodeCom::procReset( option );
}
//================================================================================================
// 概要		：サービス・CS_Remote_Core・プロダクト認証設定共通：インデックスボタン.
//================================================================================================
void PServiceRDModeProductCertificateCom::procIndexButton( uchar option )
{
	// インストール実行中時は移動不可.
	if( InstallDeleteExecution_Executing == e_InstallSts
	    || InstallDeleteExecution_Executing == e_VerificationSts
	    || InstallDeleteExecution_Executing == e_DeleteSts ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );		// 拒否音.
		return;
	}
	switch( option ) {
		case BTNID_KEY_IndexRDModePcSetting:				// ﾌﾟﾛﾀﾞｸﾄ認証.
			nextGamen = &gp_ServiceRDModePcSetting;
			break;
		case BTNID_KEY_IndexRDModePcWebDAVAdd:				// WebDAV(URL).
			nextGamen = &gp_ServiceRDModePcWebDAVAdd;
			break;
		case BTNID_KEY_IndexRDModePcInstall:				// 手動登録.
			nextGamen = &gp_ServiceRDModePcInstall;
			break;
		case BTNID_KEY_IndexRDModePcDelete:					// 削除.
			nextGamen = &gp_ServiceRDModePcDelete;
			break;
		default:
			break;
	}
}
//================================================================================================
// 概要		：サービス・CS_Remote_Core・プロダクト認証設定共通：ラインキー.
//================================================================================================
void PServiceRDModeProductCertificateCom::procGoToMag( uchar option )
{
	// インストール実行中時は移動不可.
	if( InstallDeleteExecution_Executing == e_InstallSts
	    || InstallDeleteExecution_Executing == e_VerificationSts
	    || InstallDeleteExecution_Executing == e_DeleteSts ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );		// 拒否音.
		return;
	}
	PServiceNoFunctionCodeCom::procGoToMag( option );
}
//================================================================================================
// 概要		：サービス・CS_Remote_Core・プロダクト認証設定共通：パーツ設定.
//================================================================================================
void PServiceRDModeProductCertificateCom::settingStatusParts( PNLE_ProductCert e_ProductCert )
{
	// インストールステータス毎のパーツの表示関連定義.
	struct PNLS_StatusPartsDisp {
		Bool	bl_GroupPartsEnable;		// グループパーツ表示/非表示.
		ushort	us_showStatusTxtID;		// インストール状態表示用シンボル.
	};
	const PNLS_StatusPartsDisp st_StatusPartsDispTbl[] = {
		//  GroupParts	    ｲﾝｽﾄｰﾙ状態表示用.
		//  表示/非表示	    ｼﾝﾎﾞﾙ(0は非表示).
		{ False,		NULL						},	// インストールしていない.
		{ False,		NULL						},	// インストール予約.
		{ True,			s_ITMServiceRunning			},	// インストール中.
		{ True,			s_Ok						},	// インストール成功.
		{ True,			s_NG						},	// インストール失敗.
	};

	// パーツ定義構造体.
	struct PNLS_StatusParts {
		PGroupParts*		pc_Grp_Parts;		// グループパーツ.
		PSinglePartsText*	pc_Txt_Parts;		// インストール状態表示用.
	};
	PNLS_StatusParts st_StatusPartsTbl[] = {
		{ &Grp_ServieProductCertInstalling,	&Txt_RDModePcInstallingSts},	// インストール.
		{ &Grp_ServieProductCertVerifying,	&Txt_RDModePcVerifyingSts},		// 検証.
		{ &Grp_ServieProductCertDeleting,	&Txt_RDModePcDeletingSts},		// 削除.
	};

	InstallDeleteExecutionStatus e_Status = InstallDeleteExecution_None;
	switch( e_ProductCert ) {
		case PNLE_ProductCertInstalling	: e_Status = e_InstallSts;			break;
		case PNLE_ProductCertVerifying 	: e_Status = e_VerificationSts;		break;
		case PNLE_ProductCertDeleting 	: e_Status = e_DeleteSts;			break;
		default : break;
	}


	// グループパーツの表示/非表示.
	st_StatusPartsTbl[e_ProductCert].pc_Grp_Parts->showEnable( st_StatusPartsDispTbl[e_Status].bl_GroupPartsEnable );

	// インストール状態表示用パーツの表示設定.
	st_StatusPartsTbl[e_ProductCert].pc_Txt_Parts->changeText( st_StatusPartsDispTbl[e_Status].us_showStatusTxtID );

}
