//================================================================================================
void PServiceRDModePcSetting::procObserver( TYPE_PNL_Observer e_PNL_Observer )
{
	// 上位クラスのオブザーバー通知処理をコール.
	PServiceRDModeProductCertificateCom::procObserver( e_PNL_Observer );
	if( True == bl_SelectProductCertificateOn ) {
		if( TYPE_PNL_Observer_ProductCertificate == e_PNL_Observer ) {
			if( TYPE_LcaDispCode_NormalEnd == onlyPanel.getProductCertificate() ) {
				e_VerificationSts = InstallDeleteExecution_OK;
			} else {
				e_VerificationSts = InstallDeleteExecution_NG;
			}
			bl_SelectStart = False;
		}
	}
}
//================================================================================================
// 概要		：サービス・CS_Remote_Core・プロダクト認証設定・プロダクト認証(80B93500)：表示画面のセットアップ.
//================================================================================================
void PServiceRDModePcSetting::setupGamen( short option )
{
	Bool bl_StartShow = True;
	Bool bl_OKShow = True;
	Bool bl_LicenceAbnormal = True;

	PServiceRDModeProductCertificateCom::setupGamen( option );

	// ライセンス管理異常時
	if( True == PnlComGetEnabler()->isLicenseManagementAbnormal() ) {
		bl_StartShow = False;
		bl_LicenceAbnormal = True;
	} else {
		bl_LicenceAbnormal = False;
	}
	// 「しない」キー選択時
	if( False == bl_SelectProductCertificateOn ) {
		bl_StartShow = False;
	}
	// する選択かつRAMのプロダクト認証設定情報がするでない場合
	else if( ( True == bl_SelectProductCertificateOn )
	         && ( TYPE_EnableProductCertificationOn != PnlComGetRdsSetting()->getEnableProductCertification() ) ) {
		bl_OKShow = False;
	}

	// エラーコードの表示
	if( TYPE_LcaDispCode_NormalEnd != onlyPanel.getProductCertificate() ) {
		NtError();
	} else {
		Txt_RDModePcErrorCodeMessage.changeText( NULL );
	}
	Rbt_RDModePcSetting.select( bl_SelectProductCertificateOn );			// ﾌﾟﾛﾀﾞｸﾄ認証する/しない・選択.
	Key_OkService.showEnable( bl_OKShow );									// OKキーの表示非表示.
	Txt_RDModePcSettingLicenceAbnormal.showEnable( bl_LicenceAbnormal );		// ﾗｲｾﾝｽ管理異常の表示・非表示.
//2016/11/20 HCLT_Prashannaa WP 11_15 Hide Line mode Starts
#ifndef DEF_KRONOSS_Cus
	if( True == bl_isFactoryThroughMode || True == comSystem.bl_FactoryAdjustMode ) {
		Key_ServiceToLine.showEnable( bl_OKShow );
	}
#else
	Key_ServiceToLine.showEnable( False );
#endif
//2016/11/20 HCLT_Prashannaa WP 11_15 Hide Line mode Ends
	Key_RDModePcSettingStart.showEnable( bl_StartShow );					// 証明書検証スタート表示・非表示.
	Key_RDModePcSettingStart.select( bl_SelectStart );						// 証明書検証スタート・選択.

	settingStatusParts( PNLE_ProductCertVerifying );
}
