//================================================================================================
PServiceRDModePcKeybordInputCom::PServiceRDModePcKeybordInputCom( PDisplayParts** partsTable, short partsNumber, Bool isNoWarning )
	: PServiceRDModeProductCertificateCom( partsTable, partsNumber, isNoWarning )
{
	ss_MaxString = 130 + 1;		// 最大入力文字数.
	ss_Max1LineString = 70;		// 1行に表示できる文字数.
	clearString( uc_LocalString, ss_MaxString );
	ss_CursorPos = 0;  // 入力カーソルの指す文字位置.
	bl_Password = False;		// パスワード表示フラグ.
	bl_ShowPass = False;		// パスワード変更フラグ.
}
//================================================================================================
// 概要		：サービス・CS_Remote_Core・プロダクト認証・WebDAV・キーボード入力共通 : 画面開始処理.
//================================================================================================
void PServiceRDModePcKeybordInputCom::startGamen()
{
	PBasicMessageProc::startGamen();

	ss_MaxString = 130 + 1;		// 最大入力文字数.
	ss_Max1LineString = 70;		// 1行に表示できる文字数.
	memset( uc_LocalString , 0 , sizeof( uc_LocalString ) );
	clearString( uc_LocalString, ss_MaxString );
	ss_CursorPos = 0;  // 入力カーソルの指す文字位置.
	// キーボード表示.
	Kbd_ServiceInputKeybord.setChangeEnlKeybord( PLBD_Enl_KBD_Initial );
	Kbd_ServiceInputKeybord = PLBC_ConvertKeybord( PLBD_KBT_EMail, 184, 206, True, True );	// キーボード種類、配置位置設定(矢印あり、削除ｷｰあり).
	// カーソルクラスへパーツポインタを渡す.
	Kbd_ServiceInputKeybord.GetCursor( NULL );
	startGamenKeybordService9E();
	Kbd_ServiceInputKeybord.showKeybord();	// キーボード表示.
	// 削除キー位置設定.
	Key_ServiceKeybordDelete.changePosition( 34, 103, 0, 0 );
}
//================================================================================================
// 概要		：サービス・CS_Remote_Core・プロダクト認証・WebDAV・キーボード入力共通 : 表示画面のセットアップ.
//================================================================================================
void PServiceRDModePcKeybordInputCom::setupGamen( short option )
{
	PServiceRDModeProductCertificateCom::setupGamen( option );
	short ss_Xpos =  8;	// 入力カーソルＸ座標.
// Comment 2018/01/06 [HCL_Rengaraaj] [IT5-4.2][AR1030544] Adjusting Position to match with username.
//	short ss_Ypos = 76;	// 入力カーソルＹ座標.
	short ss_Ypos = 72;	// 入力カーソルＹ座標.
	// キーボード表示 .
	setupGamenKeybordService();
	Kbd_ServiceInputKeybord.showKeybord();		// 変換用キーボードの表示.
	// 入力文字列の表示.
	uchar uc_StringShow[ DEF_RDModeNtSetSMTPRealmSize + 2 ]; // +2 は改行と'\0'のぶん.
	setupInputString( 2, ss_Max1LineString, ( char* )uc_LocalString, ( char* )uc_StringShow, 0, EP_CharSet_USASCII );
	Tfd_ServiceKeybordInputArea.changeExternalText( uc_StringShow );		// 入力フィールド.
	// パスワード表示.
	if( bl_Password == True ) {
		char _sc_Password[ DEF_RDModeNtSetSMTPRealmSize + 2 ]; // +2 は改行と'\0'のぶん.
		memset( _sc_Password, 0, sizeof( _sc_Password )/sizeof( _sc_Password[0] ) );
		if( bl_ShowPass == True ) {	// 「*」を10個表示する.
			if( uc_StringShow[0]  != '\0' ) {			// パスワードが設定されている時 .
				strcpy( _sc_Password , "**********" );	// 10個"*"を表示する.
			} else {									// パスワードが設定されていない時.
				strcpy( _sc_Password , "\0" );
			}
		} else {
			ushort i = 0;			// Qt4対応:VC固有スコープ処理を回避.
			for( i = 0; i < strlen( ( char* )uc_StringShow ); i++ ) {
// comment 2015/07/23 OPS1-Sky浜野 [MinervaSBK][制御構成変更No.75] パスワード入力文字表示対応.
				// パスワード入力文字を表示する場合.
				if( 0 <= m_ss_PassInsertPos ) {
					// 入力文字は、そのまま表示する.
					if( i == m_ss_PassInsertPos ) {
						strncpy( &_sc_Password[i], ( char* )( &uc_StringShow[i] ), 1 );
						continue;
					}
				}
				_sc_Password[ i ] = '*';
			}
			_sc_Password[ i ] = '\0';
		}
		Tfd_ServiceKeybordInputArea.changeExternalText( ( uchar* )_sc_Password );		// 入力フィールド.
	}
	// カーソルの指す文字位置が表示している文字列内に収まるように補正(念のため).
	if( ss_MaxString <= ss_CursorPos ) {
		ss_CursorPos = static_cast<short>( ss_MaxString - 1 );
	}
	if( ss_CursorPos < 0 ) {
		ss_CursorPos = 0;
	}
	// カーソルの指す文字位置により、カーソル位置を移動.
	Gra_SRdsServerSettingCursor.showEnable( False ); // 入力カーソル表示.
	if( 0 <= ss_CursorPos && ss_CursorPos < ss_Max1LineString && ss_CursorPos < ss_MaxString ) { // 0～(1行目の最大文字数) のとき.
//Comment [2020/10/14][HCL_Hemachander][OP_BTS-28426]Multiplier value update.
//		ss_Xpos = static_cast<short>( 8 + ( ss_CursorPos * 8 ) ) ;		// 1 は先頭座標.
		ss_Xpos = static_cast<short>( 8 + ( ss_CursorPos * PNLD_CURSOR_POSITION_MULTIPLIER ) ) ;		// 1 は先頭座標.
		ss_Ypos = 72;
	} else if( ss_Max1LineString <= ss_CursorPos && ss_CursorPos <= ss_MaxString ) {
//Comment [2020/10/14][HCL_Hemachander][OP_BTS-28426]Multiplier value update.
//		ss_Xpos = static_cast<short>( 8 + ( ( ss_CursorPos - ss_Max1LineString ) * 8 ) ); // 始めの 1 は先頭座標.
		ss_Xpos = static_cast<short>( 8 + ( ( ss_CursorPos - ss_Max1LineString ) * PNLD_CURSOR_POSITION_MULTIPLIER ) ); // 始めの 1 は先頭座標.
		ss_Ypos = 88;
	}
	if( bl_Password == True && bl_ShowPass == True ) { // 「*」を10個表示する状態.
		if( uc_StringShow[0]  != '\0' ) {			// パスワードが設定されている時.
//Comment [2020/10/14][HCL_Hemachander][OP_BTS-28426]Multiplier value update.
//			ss_Xpos = 8 + ( 10 * 8 );		// 8 は先頭座標.
			ss_Xpos = 8 + ( 10 * PNLD_CURSOR_POSITION_MULTIPLIER );		// 8 は先頭座標.
		} else {									// パスワードが設定されていない時.
			ss_Xpos = 8;		// 8 は先頭座標.
		}
// Comment 2018/01/06 [HCL_Rengaraaj] [IT5-4.2][AR1030544] Adjusting Position to match with username.
//		ss_Ypos = 76;
		ss_Ypos = 72;
	}
	Gra_SRdsServerSettingCursor.changePosition( ss_Xpos, ss_Ypos );// 入力カーソル位置移動.
	Gra_SRdsServerSettingCursor.showEnable( True ); // 入力カーソル表示.
}
//================================================================================================
// 概要		：サービス・CS_Remote_Core・プロダクト認証・WebDAV・キーボード入力共通 : 文字挿入.
//================================================================================================
Bool PServiceRDModePcKeybordInputCom::setStringInMedium( uchar* string, short insertPos, uchar input, short size_stringMax, short ss_Max1LineString )
{
	Bool result = False; // 文字を挿入できたか返すための変数.
	short ss_strLength = static_cast<short>( strlen( ( char* )string ) );
	if( ( ss_strLength <= ss_Max1LineString && ss_strLength < size_stringMax )
	    || ( ss_Max1LineString < ss_strLength && ss_strLength < size_stringMax ) ) { // 一文字分以上、空きがある場合.
		// 現在位置以降の文字列を一文字分後ろにずらす.
		for( short i = static_cast<short>( strlen( ( char* )string ) ); i >= insertPos; i-- ) {
			string[ i ] = string[ i-1 ];
		}
		// 現在位置に入力された文字を入れる.
		string[ insertPos ] = input;

// comment 2015/07/10 OPS1-Sky浜野 [MinervaSBK][制御構成変更No.75] パスワード入力文字表示対応.
		// パスワード入力表示開始.
		judgePassInsert( insertPos );

		result = True; // 文字を挿入できた.
	} else {
		result = False; // 文字を挿入できなかった.
	}
	return( result );
}
//================================================================================================
// 概要		：サービス・CS_Remote_Core・プロダクト認証・WebDAV・キーボード入力共通 : テンキー.
//================================================================================================
void PServiceRDModePcKeybordInputCom::proc10Key( uchar option )
{
	if( bl_Password == True && bl_ShowPass == True ) {
		bl_ShowPass = False;		// 「*」10個表示を止める.
		// 入力中状態に変更.
		procClear( 0 );			// 表示をクリアする.
	}
	if( option <= 9 ) {
		// 入力された文字を現在位置に挿入.
		if( setStringInMedium( ( uchar* )uc_LocalString, ss_CursorPos, static_cast<uchar>( option + '0' ), ss_MaxString, ss_Max1LineString ) == True ) {
			// カーソルを一つ進める.
			ss_CursorPos++;
//Comment [2020/10/14][HCL_Hemachander][OP_BTS-28426]Raised NG Buzzer.
//		}
		} else {
			setBuzzerType( PCGE_BuzzerType_InputNg );
		}
	}
	setupGamen();
}
//================================================================================================
// 概要		：サービス・CS_Remote_Core・プロダクト認証・WebDAV・キーボード入力共通 : キーボード入力.
//================================================================================================
void PServiceRDModePcKeybordInputCom::procKeyBoard( uchar option )
{
	if( bl_Password == True && bl_ShowPass == True ) {
		bl_ShowPass = False;		// 「*」10個表示を止める.
		// 入力中状態に変更.
		procClear( 0 );			// 表示をクリアする.
	}
	char	sc_keyCode[3];
	memset( sc_keyCode, 0x00, sizeof( sc_keyCode ) );
	short   i = 0;
	// キーコードを取得.
	Kbd_ServiceInputKeybord.getKeyString( option, sc_keyCode );
	switch( sc_keyCode[0] ) {
		case PLBD_ArrowLeftKeyCode:			// ←キー押下：カーソル位置を左に移動.
			if( 0 < ss_CursorPos ) {
				ss_CursorPos--;		// カーソルの指す文字位置を移動.
			} else {
				MCR_setBuzzerType( PCGE_BuzzerType_InputNg );		// 拒否音.
				break;
			}
			if( uc_LocalString[ ss_CursorPos ] == '\n' ) { // 改行文字は飛ばす.
				ss_CursorPos--;
			}
			break;
		case PLBD_ArrowRighKeyCode:			// →キー押下：カーソル位置を右に移動.
			if( uc_LocalString[ ss_CursorPos ] != '\0' ) {
				ss_CursorPos++;
			} else {
				MCR_setBuzzerType( PCGE_BuzzerType_InputNg );		// 拒否音.
				break;
			}
			if( uc_LocalString[ ss_CursorPos ] == '\n' ) { // 改行文字は飛ばす.
				ss_CursorPos++;
			}
			break;
		case PLBD_DeleteKeyCode:	// Delキー押下：一文字消去.
			if( uc_LocalString[ ss_CursorPos ] == '\0' ) { // 文字列の最後尾の場合.
				// カーソルを一つ戻して一文字クリア.
				if( 0 < ss_CursorPos ) {
					ss_CursorPos--;
				} else {
					MCR_setBuzzerType( PCGE_BuzzerType_InputNg );	// 拒否音.
					break;
				}
				uc_LocalString[ ss_CursorPos ] = '\0';
			} else { // 文字列の最後尾でない場合.
				// 現在位置の文字をクリアする(一文字ずつ前に詰める).
				for( i = ss_CursorPos; uc_LocalString[i] != '\0'; i++ ) {
					uc_LocalString[ i ] = uc_LocalString[ i + 1 ];
				}
			}
// comment 2015/07/23 OPS1-Sky浜野 [MinervaSBK][制御構成変更No.75] パスワード入力文字表示対応.
			// パスワード入力表示位置を更新.
			adjustPassInsert( ss_CursorPos, 1 );
			break;
		default:	// その他のキー押下：入力文字列表示.
			if( ss_CursorPos == ( short )strlen( ( char* )uc_LocalString ) ) { // 現在位置が最後尾の場合.
				setStringWithCheck( uc_LocalString, sc_keyCode[0], ss_MaxString );
// comment 2015/07/23 OPS1-Sky浜野 [MinervaSBK][制御構成変更No.75] パスワード入力文字表示対応.
				// パスワード入力表示開始.
				judgePassInsert( ss_CursorPos );
				// カーソルを一つ進める.
				ss_CursorPos++;
			} else {
				// 入力された文字を現在位置に挿入.
				if( setStringInMedium( ( uchar* )uc_LocalString, ss_CursorPos, sc_keyCode[0], ss_MaxString, ss_Max1LineString ) == True ) {
					// カーソルを一つ進める.
					ss_CursorPos++;
//Comment [2020/10/14][HCL_Hemachander][OP_BTS-28426]Raised NG Buzzer.
//				}
				} else {
					setBuzzerType( PCGE_BuzzerType_InputNg );
				}
			}
			break;
	}
	setupGamen();
}
//================================================================================================
// 概要		：サービス・CS_Remote_Core・プロダクト認証・WebDAV・キーボード入力共通: クリアー.
//================================================================================================
void PServiceRDModePcKeybordInputCom::procClear( uchar option )
{
	// パスワード入力＋「*」を10個表示状態の場合.
	if( bl_Password == True && bl_ShowPass == True ) {
		bl_ShowPass = False;		// 「*」10個表示を止める.
	}
	// 文字列の初期化.
	clearString( uc_LocalString, ss_MaxString );

// comment 2015/07/23 OPS1-Sky浜野 [MinervaSBK][制御構成変更No.75] パスワード入力文字表示対応.
	fixPassInput();

	ss_CursorPos = 0; // 入力カーソル位置.
	setupGamen();
}
