//================================================================================================
void PServiceRDModePc10KeyInputcom::proc10Key( uchar option )
{
	Bool bl_Error = False;
	if( ( True == bl_Direct ) && ( 0 == option ) ) { // 最初入力が０を押されたら.
		setBuzzerType( PCGE_BuzzerType_InputNg );
		if( 0 == us_LocalValue ) {
			return;
		}
	}
	us_LocalValue = ( ushort )proc10KeyInput( us_LocalValue, us_MaxValue, option, bl_Direct, EP_InputMaxLimitPattern_Refuse, &bl_Error );
	if( True == bl_Error ) {
		setBuzzerType( PCGE_BuzzerType_InputNg );
	}
	bl_Direct = False;
	bl_Fixed  = False;		// 確定フラグOFF.
	setupGamen();
}
