/*================================================================================================
//概要    :サービス・CSRemoteCare・プロダクト認証・キーボード入力共通 : 画面開始処理.
================================================================================================*/
void PServiceRDModePcKeybordCom::startGamen()
{
	// キーボード表示.
	Kbd_ServiceInputKeybord.setChangeEnlKeybord( PLBD_Enl_KBD_Initial );
	Kbd_ServiceInputKeybord = PLBC_ConvertKeybord( PLBD_KBT_EMail, 32, 194, True, True ); // キーボード種類、配置位置設定(矢印あり、削除ｷｰあり).
	// カーソルクラスへパーツポインタを渡す.
	Kbd_ServiceInputKeybord.GetCursor( NULL );
	startGamenKeybordService9E();
	Kbd_ServiceInputKeybord.showKeybord();	// キーボード表示.
	// 削除キー位置設定.
	Key_ServiceKeybordDelete.changePosition( 24, 97, 0, 0 );
	// 文字列入力フィールドの登録.
	pa_DispField = &Btx_SRdsServerSettingKeybordInput;
	// パス入力選択クラス.
	c_SlideTextMgr.setSelectProc( bl_Password );
	if( True == bl_Password ) {
		c_SlideTextMgr.initStatus( sc_StrKeyboard );
	} else {
		c_SlideTextMgr.setStatus( False );
	}
	// スライド文字列管理クラスの初期化.
	c_SlideTextMgr.init_CLCD( sc_StrKeyboard, sc_KeyboardWidth, ss_MaxInputNum, pa_DispField, EP_CharSet_USASCII );

	PServiceRDModeProductCertificateCom::startGamen();
}
/*================================================================================================
//概要    :サービス・CSRemoteCare・プロダクト認証・キーボード入力共通 : 表示画面のセットアップ.
/===============================================================================================*/
void PServiceRDModePcKeybordCom::setupGamen( short option )
{
	PServiceRDModeProductCertificateCom::setupGamen( option );
	// サービス専用キーボード共通セットアップ.
	setupGamenKeybordService();
	Kbd_ServiceInputKeybord.showKeybord();		// 変換用キーボードの表示.
	c_SlideTextMgr.drawStr( sc_StrKeyboard );
}
/*================================================================================================
//概要    :サービス・CSRemoteCare・プロダクト認証・キーボード入力共通 : テンキー.
================================================================================================*/
void PServiceRDModePcKeybordCom::proc10Key( uchar option )
{
	if( True == bl_Password && True == bl_ShowPass ) {
		bl_ShowPass = False;		// 「*」10個表示を止める.
		// 入力中状態に変更(パス入力状態(=既存文字なし)を設定).
		c_SlideTextMgr.setStatus( False );
		procClear( 0 );			// 表示をクリアする.
	}
	Kbd_ServiceInputKeybord.proc10Key( &option );
	if( ss_MaxInputNum <= ( ushort )strlen( sc_StrKeyboard ) ) {
		// 最大入力長まで行っているならば入力しない.
		return;
	}
	char _sc_Num[ 3 ];
	memset( _sc_Num, '\0', sizeof( _sc_Num ) );
	// 入力されたのが0-9キーの時のみ処理を受け付ける.
	if( 9 >= option ) {
		// 数値を文字に変換.
// Comment 2015/10/21【HCLT-Meera】【CQ519679】【ID: 28746, 28747】ABV.GENERAL.
//		sprintf( ( char* )_sc_Num, "%d", option );
        snprintf( ( char* )_sc_Num, sizeof( _sc_Num ), "%d", option );
		// 文字を追加.
		c_SlideTextMgr.insertStr( sc_StrKeyboard, ( char* )_sc_Num );
	}
	// 画面セットアップ.
	setupGamen();
}
/*================================================================================================
//概要    :サービス・CSRemoteCare・プロダクト認証・キーボード入力共通 : クリアー.
================================================================================================*/
void PServiceRDModePcKeybordCom::procClear( uchar option )
{
	if( True == bl_Password && True == bl_ShowPass ) {
		bl_ShowPass = False;		// 「*」10個表示を止める.
		// 入力中状態に変更(パス入力状態(=既存文字なし)を設定).
		c_SlideTextMgr.setStatus( False );
	}
	// 文字列の初期化.
	memset( sc_StrKeyboard, 0, sizeof( sc_StrKeyboard ) );
	// スライド文字列管理クラスの初期化.
	c_SlideTextMgr.init_CLCD( sc_StrKeyboard, sc_KeyboardWidth, ss_MaxInputNum, pa_DispField, EP_CharSet_USASCII );
	setupGamen();
}
/*================================================================================================
//概要    :サービス・CSRemoteCare・プロダクト認証・キーボード入力共通 : キーボード.
================================================================================================*/
void PServiceRDModePcKeybordCom::procKeyBoard( uchar option )
{
	if( True == bl_Password && True == bl_ShowPass ) {
		bl_ShowPass = False;		// 「*」10個表示を止める.
		// 入力中状態に変更(パス入力状態(=既存文字なし)を設定).
		procClear( 0 );			// 表示をクリアする.
	}
	if( True == c_SlideTextMgr.getStatus() ) {
		// 入力中状態に変更(パス入力状態(=既存文字なし)を設定).
		c_SlideTextMgr.setStatus( False );
		// スライド文字列管理クラスの初期化.
		c_SlideTextMgr.init_CLCD( sc_StrKeyboard, sc_KeyboardWidth, ss_MaxInputNum, pa_DispField, EP_CharSet_USASCII );
	}
	Kbd_ServiceInputKeybord.procCursorPosition( ( char* )&c_SlideTextMgr, sc_StrKeyboard, option, True );	// カーソル位置処理
	setupGamen();
}
/*================================================================================================
//概要    :サービス・CSRemoteCare・プロダクト認証・キーボード入力共通 : ボタン（押された）.
================================================================================================*/
void PServiceRDModePcKeybordCom::procButtonOn( uchar option )
{
	if( True == bl_Password && True == bl_ShowPass ) {
		bl_ShowPass = False;		// 「*」10個表示を止める.
		// 入力中状態に変更(パス入力状態(=既存文字なし)を設定).
		c_SlideTextMgr.setStatus( False );
		procClear( 0 );			// 表示をクリアする.
	}
	// サービス・キーボード共通ボタン押下処理.
	procButtonOnKeybordService( option );
	setupGamen();		// 画面セットアップ.
}
/*================================================================================================
//概要    :サービス・CSRemoteCare・プロダクト認証・キーボード入力共通 : 表示領域にデータをセット.
================================================================================================*/
void PServiceRDModePcKeybordCom::setKeyboardData(
    char*	sc_InputData,		// キーボードの初期文字列.
    short	ss_InputMax,		// キーボードの最大入力文字数.
    char	sc_InputWidth )		// キーボードの幅(char単位).
{
	strncpy( sc_StrKeyboard, sc_InputData, sizeof( sc_StrKeyboard )-1 );
	sc_StrKeyboard[sizeof( sc_StrKeyboard )- 1] = '\0';
	ss_MaxInputNum = ss_InputMax;
	sc_KeyboardWidth = sc_InputWidth;
}

