// 戻り値	:なし
//================================================================================================.
void PServiceCSRemoteCaremMenu::startGamen()
{
	PServiceMenuExistCom::startGamen();
	Rbt_ServiceMenu.select( 11 );	// CSRemoteCare選択.
}
//================================================================================================.
//［機能設定］	サービス・CS Remote Care・メニュー(80B93400) ： 画面移動.
// 戻り値	:なし
//================================================================================================.
void PServiceCSRemoteCaremMenu::procGoToPage( uchar option )
{
	TYPE_RdsMode  e_RdsMode    = PnlComGetRdsSetting()->getRdsMode();	// 現在のシステム選択値を取得する。
	switch( option ) {
		case  BTNID_KEY_MaintenanceDefaultSettings:	// メンテナンス/初期設定 .
			nextGamen = &gp_ServiceRDModeSystem;	// サービス・CS Remote Care/ID入力.
			break;
		case  BTNID_KEY_ServerSettings:				// サーバー設定.
			switch( e_RdsMode ) {
				case TYPE_RdsModeMail:			// E-mail1選択時.
				case TYPE_RdsModeMailForOne:	// E-mail2選択時.
					PServiceRDModeNetworkcom::ep_RDModeNowGamen = EP_RDModeNetworkGamen_POP3Server;
					nextGamen = &gp_ServiceRDModeNtPOP3Server;	// KMRDS・ﾈｯﾄﾜｰｸ設定・受信用サーバー.
					break;
				case TYPE_RdsModeHttp:			// Http選択時.
					PServiceRDModeNetworkcom::ep_RDModeNowGamen = EP_RDModeNetworkGamen_HTTPUrlAddress;
					nextGamen = &gp_ServiceRDModeNtHttpUrlAdd;	// サーバ設定(http)／URLアドレス.
					break;
				default:break;
			}
			break;
		case  BTNID_KEY_ProductAuthSettings:		// プロダクト認証設定 .
			nextGamen = &gp_ServiceRDModePcSetting;		// 【UV-00781, 2011.03.09, 細見 】.
			break;
		case  BTNID_KEY_MaintenanceStart:			// メンテナンス開始 .
			if( True == PnlComGetRdsSetting()->getMaintStat() ) {		// ﾒﾝﾃﾅﾝｽ中.
				PnlComGetRds()->indTrg( TYPE_RdsTrgKindMnteEnd );	// メンテナンス終了メッセージ発信.
				nextGamen = &gp_ServiceMenu;   // サービスメニュー.
			} else {
				nextGamen = &gp_ServiceCSRemoteCaremMaintenanceStart;
			}
			break;
		case  BTNID_KEY_DetailSettings:				// 詳細設定 .
			switch( e_RdsMode ) {
				case TYPE_RdsModeMail:			nextGamen = &gp_ServiceRDModeDTSettingE1;		break;	// 基本設定(e-mail)両方向通信対応.
				case TYPE_RdsModeTelephony:	// モデムモード↓
				case TYPE_RdsModeFax:			nextGamen = &gp_ServiceRDModeDTSettingDtCtID;	break;	// 基本設定(モデム/Fax)
				case TYPE_RdsModeMailForOne:	nextGamen = &gp_ServiceRDModeDTSettingE2;		break;	// 基本設定(e-mail2)
				case TYPE_RdsModeHttp:			nextGamen = &gp_ServiceRDModeDTSettingHttpCtID;	break; // 基本設定(http)
				default: break;
			}
			break;
		case  BTNID_KEY_ImpExpSettings:				// エクスポート/インポート設定 .
			nextGamen = &gp_ServiceCSRemoteCareForImportExportWebDavUrlAdd;		// サービス・ CS Remote Care／ｴｸｽﾎﾟｰﾄ/ｲﾝﾎﾟｰﾄ設定／URLアドレス.
			break;
// 2014/10/30 [MAv3][RQ-251] 指示サーバとの連携によるセットアップ性改善 CSRCの自動初期発信 日立 村上(幸).
		case  BTNID_KEY_AutoInitDialSettings:			// 自動初期発信設定.
			nextGamen = &gp_ServiceCSRCAutoInitDial;	// サービス・ CS Remote Care／自動初期発信設定.
			break;	
		default: break;
	}
}
//================================================================================================.
//［機能設定］	サービス・CS Remote Care・メニュー(80B93400) ： 画面セットアップ.
// 戻り値	:なし
//================================================================================================.
void PServiceCSRemoteCaremMenu::setupGamen( short option )
{
	PServiceMenuExistCom::setupGamen( option );	// 親クラスの処理を呼ぶ.
	APIC_Rds* pc_Rds = PnlComGetRds();
	TYPS_RdsCommResult st_RdsCommResult;	//RDS通信結果（構造体）
	uchar uc_RdsStatNo[5];
	pc_Rds->getRdsCommResult( &st_RdsCommResult.e_RdsDispCode, &st_RdsCommResult.ul_StatNo ); // RDSの通信結果を受け取る
	snprintf( ( char* )uc_RdsStatNo, sizeof( uc_RdsStatNo ), "%04X", st_RdsCommResult.ul_StatNo );
	Bool bl_showStatNo = True;	// ステータスNo.を表示するか否かのフラグ.
	if( st_RdsCommResult.ul_StatNo == 0 ) {		// ステータスNo.が0の時は非表示.
		bl_showStatNo = False;
	} else {
		bl_showStatNo = True;
	}
	// メッセージ部に通信結果内容を表示する
	for( register ushort i = 0; i < us_dtResultCodeSize; i++ ) {
		if( st_RdsCommResult.e_RdsDispCode == tbl_dtResultCode[ i ].code ) {
			Txt_ServiceCSRemoteCareMenuDispAreaLine1.showEnable( bl_showStatNo );		// 通信結果ステータスNo.表示状態.
			Txt_ServiceCSRemoteCareMenuDispAreaLine2.changeText( tbl_dtResultCode[ i ].msg );	// RDS通信結果文字列表示.
			Txt_ServiceCSRemoteCareMenuDispAreaLine1.changeASCIIText( uc_RdsStatNo );	// 通信結果ステータスNo.
			break;
		}
	}

	// サーバー設定キー 表示/非表示判定
	uchar uc_ServiceID[ DEF_SizeRDServiceID + 1 ];	// サービスID.
	clearString( uc_ServiceID, DEF_SizeRDServiceID );			 // サービスＩＤクリア(ローカル値).
	PnlComGetRdsSetting()->getServiceID( ( uchar* )uc_ServiceID ); // サービスＩＤ取得.
	Num_CSRemoteCareMenuIDCode.changeASCIIText( uc_ServiceID );	// ＩＤコード表示.

	TYPE_RdsMode  e_RdsMode    = TYPE_RdsModeTelephony;
	e_RdsMode = PnlComGetRdsSetting()->getRdsMode();	// 現在のシステム選択値を取得する。
	// KMRDS/システム選択ボタン・選択状態
	switch( e_RdsMode ) {
		case TYPE_RdsModeMail:       		// E-mail選択時.
			Txt_CSRemoteCareSystemSettingType.changeText( s_KEYServiceCSRCE2EMail1 );
			Key_GoToServerSettings.showEnable( True ); // 表示・サーバー設定キー
			break;
		case TYPE_RdsModeMailForOne:		// E-mail2選択時.
			Txt_CSRemoteCareSystemSettingType.changeText( s_KEYServiceCSRCE2EMail2 );
			Key_GoToServerSettings.showEnable( True ); // 表示・サーバー設定キー
			break;
		case TYPE_RdsModeHttp:				// http1,2選択時.
			if( True == PnlComGetRdsSetting()->getCsrcCommunicationMethod() ) {	// 双方向(True)の場合、http1.
				Txt_CSRemoteCareSystemSettingType.changeText( s_KEYServiceHttp1 );
			} else {	// 片方向(False)の場合、 http2.
				Txt_CSRemoteCareSystemSettingType.changeText( s_KEYServiceHttp2 );
			}
			Key_GoToServerSettings.showEnable( True ); // 表示・サーバー設定キー
			break;
		case TYPE_RdsModeTelephony:			// モデム選択時.
			Txt_CSRemoteCareSystemSettingType.changeText( s_SRdsSystemModem );
			Key_GoToServerSettings.showEnable( False ); // 非表示・サーバー設定キー
			break;
		case TYPE_RdsModeFax:				// Fax選択時.
			Txt_CSRemoteCareSystemSettingType.changeText( s_SRdsSystemFax );
			Key_GoToServerSettings.showEnable( False ); // 非表示・サーバー設定キー
			break;
		default:							// 未選択.
			Txt_CSRemoteCareSystemSettingType.showEnable( False );
			Key_GoToServerSettings.showEnable( False ); 	// 非表示・サーバー設定キー・非表示.
			break;
	}
	// メンテナンス開始キー 表示/非表示判定
	TYPE_HostStat 	e_HostStat = PnlComGetRdsSetting()->getHostStat();  // 登録状態を取得する.
	if( pc_Rds->isNowTrans( TYPE_RdsTrgKindIni ) == False
	    && e_HostStat == TYPE_HostStatRgst ) {							// 初期発信終了かつ登録完了.
		Key_GoToMaintenanceDefaultSettings.showEnable( False );			// メンテナンス/初期設定非表示.
		Key_GoToMaintenanceStart.showEnable( True );					// メンテナンス開始キー表示.
	} else {
		Key_GoToMaintenanceDefaultSettings.showEnable( True );			// メンテナンス/初期設定表示.
		Key_GoToMaintenanceStart.showEnable( False );					// メンテナンス開始キー非表示.
	}
	if( True == PnlComGetRdsSetting()->getMaintStat() ) {		// ﾒﾝﾃﾅﾝｽ中.
		Grp_ServiceCSRemoteCareEndTime.showEnable( True );
		Key_GoToMaintenanceStart.changeText( s_RDModeMaintenanceEnd );
		Num_CSRemoteCareMenuIDCode.showEnable( True );
		Key_GoToDetailSettings.showEnable( True );
		TYPC_Time c_Time;
		PnlComGetRdsSetting()->getMaintEndScheduleTime( &c_Time );
		Nfd_CSRemoteCareHour = c_Time.sc_Hour;
		Nfd_CSRemoteCareMinute = c_Time.sc_Minute;
	} else {
		Grp_ServiceCSRemoteCareEndTime.showEnable( False );
		Key_GoToMaintenanceStart.changeText( s_KEYMaintenanceStart );
		Num_CSRemoteCareMenuIDCode.showEnable( False );
		Key_GoToDetailSettings.showEnable( False );
	}
}
