// ==================================================================.
// 概要		：サービス・CS_Remote_Core／ｴｸｽﾎﾟｰﾄ/ｲﾝﾎﾟｰﾄ設定／URLアドレス(80B93600)：表示画面のセットアップ.
// 戻り値	:なし
// ==================================================================.
void PServiceCSRemoteCareForImportExportWebDavUrlAdd::setupGamen( short option )
{
	PServiceRDModeNetworkcom::setupGamen( option );
	// 一旦全て非表示にする.
	Grp_ServiceInputIPAdressParts.showEnable( False );			// IPアドレス入力用パーツ群.
	Grp_ServiceInputIPAdress.showEnable( False );				// IPアドレスの入力値.
	Grp_ServiceCursorIPAdress.showEnable( False );				// 入力カーソル.
	Btx_RDReceiveSeverHttpFQDNDisp.showEnable( False );			// KMRDS/POP3サーバー・FQDN表示領域.
	// 一旦非選択状態にする.
	Key_SRdsServerSettingPOP3ServerIPAddress.select( False );	// ＩＰアドレスキー.
	Key_SRdsServerSettingPOP3ServerFQDNInput.select( False );	// FQDN入力キー.
	// 現在の入力形式に応じてパーツを表示する.
	if( bl_InputIPAddress == True ) {	// IPアドレス形式の場合.
		Grp_ServiceInputIPAdressParts.showEnable( True );			// IPアドレス入力用パーツ群(矢印、黒枠).
		Grp_ServiceInputIPAdress.showEnable( True );				// IPアドレスの入力値.
		Grp_ServiceCursorIPAdress.showEnable( True );				// 入力カーソル.
		Key_SRdsServerSettingPOP3ServerIPAddress.select( True );	// ＩＰアドレスキー.
	} else {	// FQDN形式の場合.
		Btx_RDReceiveSeverHttpFQDNDisp.showEnable( True );			// KMRDS/POP3サーバー・FQDN表示領域.
		Key_SRdsServerSettingPOP3ServerFQDNInput.select( True );	// FQDN入力キー.
		uchar uc_LocalString[ DEF_RDModeNtSetFQDNHttpSize + 5 ]; // +5 は改行と'\0'のぶん.
		setupInputString( 5, PNLD_ServiceWebDAVFQDN1LineMax, ( char* )uc_Address, ( char* )uc_LocalString, 0, EP_CharSet_USASCII );
		Btx_RDReceiveSeverHttpFQDNDisp.changeExternalText( ( uchar* )uc_LocalString );
	}
	for( register short i = 0 ; i < 4 ; i++ ) {				// ＩＰアドレスの数値を順に表示&カーソル表示する.
		Inp_ServiceNetworkIPAdress[i].set( uc_AdressValue[i] , bl_Fixed[i] );	// 入力で扱うアドレス値を表示.
		Gra_ServiceCursorIPAdress[i].showEnable( i == ss_InputPosition ? True : False );	// カーソルの表示（入力選択位置）（左から０～３）.
	}
}
// ==================================================================.
// 概要		：サービス・CS_Remote_Core／ｴｸｽﾎﾟｰﾄ/ｲﾝﾎﾟｰﾄ設定／フォルダ名(80B93620)：画面開始処理.
// 戻り値	:なし
// ==================================================================.
void PServiceCSRemoteCareForImportExportWebDavFolderName::startGamen()
{
	b_Password = False;		// パスワード表示フラグ.
	b_ShowPass = False;		// パスワード変更フラグ.

	PServiceRDModeNtKeybordInputcom::startGamen();	// 画面開始処理（1行に表示できる文字数と最大表示行数の決定）.
	ss_MaxString = TYPD_MaxStrCsrcWebDavForImportExportDir;				// 最大文字数.

	// ComonAPIから設定情報取得.
	PnlComGetRdsSetting()->getCsrcWebDavForImportExport( &m_st_WebDavForImportExportInfo );		// WebDAVサーバーアドレス情報.
	memcpy( sc_LocalString, m_st_WebDavForImportExportInfo.uc_Dir, TYPD_MaxStrCsrcWebDavForImportExportDir + 1 );

	// カーソルを最後尾に移動.
	ss_CursorPos = ( short )strlen( ( char* )sc_LocalString );

	Rbt_CSRemoteCareForImportExportWebDavMenu.select( BTNID_KEY_CSRemoteCareForImportExportWebDavServer );					//WebDav選択.
	Rbt_CSRemoteCareForImportExportWebDavSeverMenu.select( BTNID_KEY_CSRemoteCareForImportExportWebDavSeverFolderName );	//フォルダ名選択.
}
