/*================================================================================================
// 概要		:80B93680_CS Remote Care／ﾒﾝﾃﾅﾝｽ時間設定 : ボタン（押された）.
// 戻り値	: なし.
// 備考		:.
================================================================================================*/
void PServiceCSRemoteCaremMaintenanceStart::procButtonOn( uchar option )
{
	TYPE_HostStat e_HostStat   = PnlComGetRdsSetting()->getHostStat();  // 現在の登録状態を取得する。
	APIC_Rds*		 pc_Rds = PnlComGetRds(); // ＲＤＳ(ＡＰＩ)インスタンス取得.
	if( pc_Rds->isNowTrans( TYPE_RdsTrgKindIni ) == True || e_HostStat == TYPE_HostStatWaitRes ) { // 初期発信中、初期応答中ならばキー受付不可.
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}
	// ＫＭＲＤＳシステム選択
	switch( option ) {
		case PNLE_ServiceCSRemoteCaremMaintenanceStart_2hour: //2時間キー.
		case PNLE_ServiceCSRemoteCaremMaintenanceStart_4hour: //4時間キー.
		case PNLE_ServiceCSRemoteCaremMaintenanceStart_6hour: //6時間キー.
		case PNLE_ServiceCSRemoteCaremMaintenanceStart_8hour: //8時間キー.
		case PNLE_ServiceCSRemoteCaremMaintenanceStart_10hour: //10時間キー.
		case PNLE_ServiceCSRemoteCaremMaintenanceStart_12hour: //12時間キー.
			m_e_selectEndTime = ( PNLE_MaintenanceEndTime )option;
			break;
		default: break;
	}
	setupGamen();	// 表示部品のセットアップ
}

