void PServiceCMMPattern::startGamen()
{
	PServiceFactoryTestPrintToFactoryTopCom::startGamen();

	CheckAndExecInit();	// 初期化必要か否か取得して必要なら実行する.


	testprintSM = 0;		// 必ずシングル.
	_select = 0;
	ss_CMMFunctionStartType = TYPE_FunctionStartTypePRINTPATTAN;
	setFunctionCode( testPatternTable_CMM[ testprintGK ].funcS );
	if( NULL != PnlComGetJobCopy() ) {
		TYPC_Common* pc_Common = PnlComGetJobCopy()->getJobSpec()->pc_Common;
		pc_Common->setColorMode( testprintGK == 7 ? TYPE_ColorModeBlack : TYPE_ColorModeFullColor );	// PCGC_CopyAuxilColorSeparation::procButtonOnを参考に作成.
	}

	PServiceFactoryTestPrintToFactoryTopCom::init_value_for_startGamen();
}
//================================================================================================
// 概要		:サービス・テストプリント・CMMパターン出力 : 変数などの初期化.
// 戻り値	:なし.
//================================================================================================
void PServiceCMMPattern::init_value()
{
	PServiceTestPrintCom::init_value();
	setPrinterIndi( TYPE_PrinterAdjustLimosMode , 1 );	// リモスモード HYPER
	setPrinterIndi( TYPE_PrinterAdjustLineParameter , 3 );
	setPrinterIndi( TYPE_PrinterAdjustLineParameter );
	// シングルなら置数1、マルチなら置数999とする.
	if( testprintSM == 1 ) {	// マルチ.
		ss_printNum = 999;	// マルチ押下時は常に置数999.
		bl_MtoS = True;		// マルチ → シングル押下時.
	} else {	// シングル.
		ss_printNum = 1;	// シングル押下時は1にする.
		bl_MtoS = False;	// シングル → マルチ押下時.
	}
	bl_isCMYKMode = False;	// ４枚連続印刷(CMYBk)モードか否か.
}
//================================================================================================
// 概要		:サービス・テストプリント・CMMパターン出力 : テンキー.
// 戻り値	:なし.
//================================================================================================
void PServiceCMMPattern::proc10Key( uchar option )
{
	if( bl_isFactoryModeNow == True ) {	// 工場調整テストプリントのとき受付ける.
		PServiceTestPrintCom::proc10Key( option );
	}
	else {
		setBuzzerType( PCGE_BuzzerType_InputNg );
	}
}
//================================================================================================
// 概要		:サービス・テストプリント・CMMパターン出力 : クリア.
// 戻り値	:なし.
//================================================================================================
void PServiceCMMPattern::procClear( uchar option )
{
	if( bl_SetNumOn == True ) {	// 置数キーがＯＮの時は置数のみの入力とする.
		ss_printNum = 1;		// 置数を1にする.
		bl_DirectOn = True;		// ダイレクﾄ入力ON.
		setupGamen();
	} else {
		if( bl_isFactoryModeNow == True ) {	// 工場調整テストプリントのとき受付ける.
			PServiceTestPrintCom::procClear( option );
		} else { // Test Mode
			setBuzzerType( PCGE_BuzzerType_InputNg );
		}
	}
}
//================================================================================================
// 概要		:サービス・テストプリント・CMMパターン出力 : ボタン（押された）.
// 戻り値	:なし.
//================================================================================================
void PServiceCMMPattern::procButtonOn( uchar option )
{
	switch( option ) {
		case 0:	// 「0度」↓.
		case 1:	// 「90度」↓.
		case 2:	// 「180度」↓.
		case 3:	// 「270度」↓.
			testprintGK = option;
			testprintBk = False; // テストプリントカラーモード・ブラックフラグ・オフ.
			bl_isCMYKMode = False;	// ４枚連続印刷(CMYBk)モードか否か.
			break;
		case 20:	// テストプリントシングル.
			testprintSM = 0;
			if( bl_MtoS == True ) {	// マルチ → シングル押下時.
				ss_printNum = 1;	// 置数1.
				bl_MtoS = False;	// シングル → マルチ押下時.
			}
			break;
		case 21:	// テストプリントマルチ.
			testprintSM = 1;
			bl_SetNumOn = False;	// 置数設定キーOFF.
			bl_MtoS = True;			//マルチ → シングル押下.
			ss_printNum = 999;		// マルチ選択時は置数999に固定.
			break;
		case 30:	// 誤差拡散.
			ss_CMMFunctionStartType = TYPE_FunctionStartTypePRINTPATTAN;
			_select = 0;
			break;
		case 31:	// 階調優先.
			ss_CMMFunctionStartType = TYPE_FunctionStartTypeNORMAL;
			_select = 1;
			break;
		case 32:	// 解像度優先.
			ss_CMMFunctionStartType = TYPE_FunctionStartTypeNORMAL;
			_select = 2;
			break;
		case BTNID_KEY_SERV_CMM_HYBRIDDIFFUSION:	// ﾊｲﾌﾞﾘｯﾄﾞ誤差拡散.
			ss_CMMFunctionStartType = TYPE_FunctionStartTypePRINTPATTAN;
			_select = 3;
			break;
		case 100:
			setBuzzerType( PCGE_BuzzerType_InputNg );
			break;
		default: break;
	}
	setFunctionCode( testPatternTable_CMM[ testprintGK + 4 * _select ].funcS );	// テーブル順にするための計算.
	setupGamen();	// 表示部品のセットアップ.
}
//================================================================================================
// 概要		:サービス・テストプリント・CMMパターン出力 : 表示部品のセットアップ.
// 戻り値	:なし.
//================================================================================================
void PServiceCMMPattern::setupGamen( short option )
{
	Bak_ModeTP = ( float )getPrinterIndi( TYPE_PrinterAdjustLineParameter );	// モードの値を表示(工場調整のみ).
	Rbt_ServiceCMMPattern.select( testprintGK );			// テストプリント画面キー.
	Rbt_ServiceCMMPrintPattern.select( _select );			// テストプリント画面キー.
	PServiceTestPrintCom::setupGamenScreenPattern( option );	// スクリーンパターン関連表示.
	PServiceTestPrintCom::setupGamen( option );
	PServiceFactoryTestPrintToFactoryTopCom::setupGamen( option );

}
//================================================================================================
// 概要		:サービス・テストプリント・CMMパターン出力 : スタートキー.
// 戻り値	:なし.
//================================================================================================
void PServiceCMMPattern::procStart( uchar option )
{
	fixPrinterIndi( TYPE_PrinterAdjustLineParameter );	// 線数パラメータ(サービス:階調優先/解像度優先 ライン:モード).
	fixPrinterIndi( TYPE_PrinterAdjustLimosMode );		// リモスモード.
	fixPrinterIndi( TYPE_PrinterAdjustDensity );		// 濃度レベル.
	if( NULL != PnlComGetJobCopy() ) {
		TYPC_Common* pc_Common = PnlComGetJobCopy()->getJobSpec()->pc_Common; // コピージョブ.
		TYPC_Scan*   pc_Scan   = PnlComGetJobCopy()->getJobSpec()->pc_Scan;
		pc_Scan->setAcsOn( False ); // ACS未使用にする
		pc_Common->setColorMode( ( testprintBk == True ) ? TYPE_ColorModeBlack : TYPE_ColorModeFullColor );	// カラーモードをセット.
		PnlComGetJobCopy()->getJobSpec()->pc_Print->setNumOfCopies( ss_printNum );		// 置数.
		if( TYPE_FunctionStartTypeNORMAL == ss_CMMFunctionStartType ) {
			TYPE_FeedTray e_selectedFeedTray = PnlComGetJobCopy()->getJobSpec()->pc_Print->c_PaperTray.getFeedTray();
			switch( e_selectedFeedTray ) {	// 給紙口指定の設定.
				case TYPE_FeedTray1: comENG.setENGFunction_FeedCode( EC_FeedCode_1 ); break;
				case TYPE_FeedTray2: comENG.setENGFunction_FeedCode( EC_FeedCode_2 ); break;
				case TYPE_FeedTray3: comENG.setENGFunction_FeedCode( EC_FeedCode_3 ); break;
				case TYPE_FeedTray4: comENG.setENGFunction_FeedCode( EC_FeedCode_4 ); break;
				case TYPE_FeedTrayManual: comENG.setENGFunction_FeedCode( EC_FeedCode_MANUAL ); break;
				case TYPE_FeedTray5: comENG.setENGFunction_FeedCode( EC_FeedCode_LCT ); break;	// LCT給紙口.
				default: comENG.setENGFunction_FeedCode( EC_FeedCode_1 ); break;
			}
		}
	}
	PServiceFunctionEnableStartCom::procStart( ss_CMMFunctionStartType );
}
//◆◆◆◆◆◆◆◆◆◆◆◆◆◆◆◆◆◆◆◆◆◆◆◆◆◆◆◆◆◆◆◆◆◆◆◆◆◆◆◆◆◆◆◆◆◆◆◆◆◆◆◆
//////////////////////////////////////////////////////////////
// 概要 : テストモード／トレイ選択(50C00010) : 画面開始処理.
//////////////////////////////////////////////////////////////
void PServiceTestSelectTray::startGamen()
{
	PServiceFunctionEnableStartCom::startGamen();	// ファンクション共通開始処理
	CheckAndExecInit();								// 初期化必要か否か取得して必要なら実行する

	ss_dispFeedTray = PServiceFunctionEnableStartCom::getInitSelectFeedTray();	// 表示パターン取得.
	e_SelectFeedTray = PServiceFunctionEnableStartCom::getSelectFeedTray();		// 選択中のトレイ取得.
}
//////////////////////////////////////////////////////////////
// 概要 : テストモード／トレイ選択(50C00010) : ボタン（押された）.
//////////////////////////////////////////////////////////////
void PServiceTestSelectTray::procButtonOn( uchar option )
{
	switch( option )
	{
		// 給紙口選択キー.
		case 0:	// １段目.
			if( ppc_FeedTray->getTrayStatus( TYPE_FeedTray1 ) != TYPE_TrayStatusNon ) {
				e_SelectFeedTray = TYPE_FeedTray1;
			}
			break;
		case 1:	// ２段目.
			if( ppc_FeedTray->getTrayStatus( TYPE_FeedTray2 ) != TYPE_TrayStatusNon ) {
				e_SelectFeedTray = TYPE_FeedTray2;
			}
			break;
		case 2:	// ３段目.
			if( ppc_FeedTray->getTrayStatus( TYPE_FeedTray3 ) != TYPE_TrayStatusNon ) {
				e_SelectFeedTray = TYPE_FeedTray3;
			}
			break;
		case 3:	// ４段目.
			if( ppc_FeedTray->getTrayStatus( TYPE_FeedTray4 ) != TYPE_TrayStatusNon ) {
				e_SelectFeedTray = TYPE_FeedTray4;
			}
			break;
		case 4:	// 手差し.
			if( ppc_FeedTray->getTrayStatus( TYPE_FeedTrayManual ) != TYPE_TrayStatusNon ) {
				e_SelectFeedTray = TYPE_FeedTrayManual;
			}
			break;
// comment 2014/09/30 HCLT-Kiran [Poseidon][CQ_503165] Hiding the LCT Paper Feed Slot on the screen, for Poseidon model.		
// Comment 2015/01/31 HCLT_SunilNP [Compilation Switch ID: 1521] for HeliosL support.
//#ifndef DEF_Zeus5BkCus
//comment 2018/5/18 SCD2-Sky肥後 [DenebMLK][機器構成変更No.7]5段目トレイ追加対応.
//#if !defined(DEF_Zeus5BkCus) && !defined(DEF_HeliosCus)		
// Comment 2019/07/26 [HCLT_Paul] [IT6_HeliosMLK] [ Seigyu.10 ] Adding the HeliosMLK compiler switch.
#if !defined(DEF_Zeus5BkCus) && !defined(DEF_HeliosMLKCus) || defined(DEF_DenebMLKCus)
		case 5:	// LCT.
			if( ppc_FeedTray->getTrayStatus( TYPE_FeedTray5 ) != TYPE_TrayStatusNon ) {
				e_SelectFeedTray = TYPE_FeedTray5;
			}
			break;
#endif
		case 10: // 自動.
			e_SelectFeedTray = 10;
			break;
		default:	break;
	}
	setupGamen();	// 表示部品のセットアップ
}
//////////////////////////////////////////////////////////////
// 概要 : テストモード／トレイ選択(50C00010) : 設定終了.
//////////////////////////////////////////////////////////////
void PServiceTestSelectTray::procOk( uchar option )
{
	PServiceFunctionEnableStartCom::setCheckComSetBackFlg( PNLE_SelectBackGamentoTray );	// 戻り元画面フラグの設定.
	PServiceFunctionEnableStartCom::setSelectFeedTray( e_SelectFeedTray );
	nextGamen = PServiceFunctionEnableStartCom::prevServiceComGamen;		// 呼び出し元画面へ遷移.
}
//////////////////////////////////////////////////////////////
// 概要 : テストモード／トレイ選択(50C00010) : 表示画面のセットアップ.
//////////////////////////////////////////////////////////////
void PServiceTestSelectTray::setupGamen( short option )
{
	register short _select = -1;

	switch( e_SelectFeedTray )
	{
		case TYPE_FeedTray1:		_select = 1;		break;	// 1段目給紙口.
		case TYPE_FeedTray2:		_select = 2;		break;	// 2段目給紙口.
		case TYPE_FeedTray3:		_select = 3;		break;	// 3段目給紙口.
		case TYPE_FeedTray4:		_select = 4;		break;	// 4段目給紙口.
		case TYPE_FeedTrayManual:	_select = 5;		break;	// 手差し給紙口.
// comment 2014/09/30 HCLT-Kiran [Poseidon][CQ_503165] Hiding the LCT Paper Feed Slot on the screen, for Poseidon model. 
// Comment 2015/01/31 HCLT_SunilNP [Compilation Switch ID: 1522] for HeliosL support.
//#ifndef DEF_Zeus5BkCus
//comment 2018/5/18 SCD2-Sky肥後 [DenebMLK][機器構成変更No.7]5段目トレイ追加対応.
//#if !defined(DEF_Zeus5BkCus) && !defined(DEF_HeliosCus)	
// Comment 2019/07/26 [HCLT_Paul] [IT6_HeliosMLK] [ Seigyu.10 ] Adding the HeliosMLK compiler switch.
#if !defined(DEF_Zeus5BkCus) && !defined(DEF_HeliosMLKCus) || defined(DEF_DenebMLKCus)
		case TYPE_FeedTray5:		_select = 6;		break;	// LCT給紙口.
#endif
		case 10:					_select = 0;		break;	// 自動.
		default:					_select = -1;		break;	// 上記以外のときは未選択.
	}
	// エンプティ状態でない場合エンプティ表示を消す｡
	Rbt_TrayServiceTest.select( _select ); // 対象トレイを選択.
	Key_1stTrayServiceTest.showEnableAdd( &Ktx_1stTrayServiceTestEmpty, isFeedTrayUseable( TYPE_FeedTray1 ) ? False : True );
	Key_2ndTrayServiceTest.showEnableAdd( &Ktx_2ndTrayServiceTestEmpty, isFeedTrayUseable( TYPE_FeedTray2 ) ? False : True );
	Key_3rdTrayServiceTest.showEnableAdd( &Ktx_3rdTrayServiceTestEmpty, isFeedTrayUseable( TYPE_FeedTray3 ) ? False : True );
	Key_4thTrayServiceTest.showEnableAdd( &Ktx_4thTrayServiceTestEmpty, isFeedTrayUseable( TYPE_FeedTray4 ) ? False : True );
	Key_ManTrayServiceTest.showEnableAdd( &Ktx_ManTrayServiceTestEmpty, isFeedTrayUseable( TYPE_FeedTrayManual ) ? False : True );
	Key_LCTTrayServiceTest.showEnableAdd( &Ktx_LCTTrayServiceTestEmpty, isFeedTrayUseable( TYPE_FeedTray5 ) ? False : True );

	for( register ushort i = 0; i<uc_SelectTrayNum; i++ ) {
		if( ss_dispFeedTray == sc_SelectTrayTbl[i].dispType ) {	// 表示パターン判定.
			if( sc_SelectTrayTbl[i].typeFeedAuto	== False ){ Key_AutoTrayServiceTest.showEnable( False ); }
//2018/04/09 comment [HCLT_Prashannaa][IT6_Sparrow][制御構成変更_No.212] remove tray 3
			if( (sc_SelectTrayTbl[i].typeFeedTray1	== False)||
				(ppc_FeedTray->getTrayStatus(TYPE_FeedTray1 ) == TYPE_TrayStatusNon ))
				{ Key_1stTrayServiceTest.showEnable( False ); }

			if( (sc_SelectTrayTbl[i].typeFeedTray2	== False) ||
				(ppc_FeedTray->getTrayStatus(TYPE_FeedTray2 ) == TYPE_TrayStatusNon ))
				{ Key_2ndTrayServiceTest.showEnable( False ); }

			if(( sc_SelectTrayTbl[i].typeFeedTray3	== False ) ||
				(ppc_FeedTray->getTrayStatus(TYPE_FeedTray3 ) == TYPE_TrayStatusNon ))
				{ Key_3rdTrayServiceTest.showEnable( False ); }

			if(( sc_SelectTrayTbl[i].typeFeedTray4	== False ) ||
				(ppc_FeedTray->getTrayStatus(TYPE_FeedTray4 ) == TYPE_TrayStatusNon ))
				{ Key_4thTrayServiceTest.showEnable( False ); }

			if(( sc_SelectTrayTbl[i].typeFeedManual	== False )||
				(ppc_FeedTray->getTrayStatus(TYPE_FeedTrayManual ) == TYPE_TrayStatusNon ))
				{ Key_ManTrayServiceTest.showEnable( False ); }

			if(( sc_SelectTrayTbl[i].typeFeedLCT	== False ) ||
				(ppc_FeedTray->getTrayStatus(TYPE_FeedTray5 ) == TYPE_TrayStatusNon ))
				{ Key_LCTTrayServiceTest.showEnable( False ); }

		}
	}
	if( False == isShowManTray() ) {
		Key_ManTrayServiceTest.showEnable( False );
	}
	PServiceFunctionEnableStartCom::setupGamen( option );
	printLEDControl( False );	// LED赤
}
