//////////////////////////////////////////////////////////////
// 概要 : テストモード／用紙サイズ(50C00020) : ボタン（押された）.
//////////////////////////////////////////////////////////////
void PServiceTestSelectPaperSize::procButtonOn( uchar option )
{
	switch( option )
	{
		// 用紙サイズのキー.
		case 0:		e_SelectPaperSize = TYPE_SizeCodeA3Sef;				break;	// Ａ３Ｔキー.
		case 1:		e_SelectPaperSize = TYPE_SizeCodeA4Sef;				break;	// Ａ４Ｔキー.
		case 2:		e_SelectPaperSize = TYPE_SizeCodeA4Lef;				break;	// Ａ４Ｙキー.
		case 3:		e_SelectPaperSize = TYPE_SizeCodeLedgerSef;			break;	// １１×１７Ｔ.
		case 4:		e_SelectPaperSize = TYPE_SizeCodeLetterSef;			break;	// ＬｅｔｔｅｒＴキー.
		case 5:		e_SelectPaperSize = TYPE_SizeCodeLetterLef;			break;	// ＬｅｔｔｅｒＹキー.
		case 6:		e_SelectPaperSize = TYPE_SizeCodePostcard_JpSef;	break;	// はがき.
		case 7:		e_SelectPaperSize = TYPE_SizeCodeA6Sef;				break;	// Ａ６Ｔカード.
		case 8:		e_SelectPaperSize = TYPE_SizeCodeIN4x6Sef;			break;	// ４×６Ｔ.
		default :	break;
	}
	setupGamen();	// 表示画面のセットアップ
}
