void PServiceTestSelectPaperKind::startGamen()
{
	PServiceFunctionEnableStartCom::startGamen();	// ファンクション共通開始処理
	CheckAndExecInit();								// 初期化必要か否か取得して必要なら実行する

	ss_dispPaperKind = PServiceFunctionEnableStartCom::getInitSelectPaperKind();	// 表示パターン取得.
	e_SelectPaperKind = PServiceFunctionEnableStartCom::getSelectPaperKind();		// 選択中の用紙種類取得.
}
//////////////////////////////////////////////////////////////
// 概要 : テストモード／用紙種類(50C00030) : ボタン（押された）.
//////////////////////////////////////////////////////////////
void PServiceTestSelectPaperKind::procButtonOn( uchar option )
{
	TYPE_PaperType e_backSelectPaperKind = TYPE_FeedTray1;
	switch( option ) {
		// 用紙種類選択キー.
		case 0:		e_backSelectPaperKind = TYPE_PaperTypeNormal;		break;	// 普通紙キー.
		case 1:		e_backSelectPaperKind = TYPE_PaperTypeThick1;		break;	// 厚紙１キー.
		case 2: 	e_backSelectPaperKind = TYPE_PaperTypeThick1Plus;	break;	// 厚紙１+キー.
		case 3: 	e_backSelectPaperKind = TYPE_PaperTypeThick2;		break;	// 厚紙２キー.
		case 4: 	e_backSelectPaperKind = TYPE_PaperTypeThick3;		break;	// 厚紙３キー.
		case 5: 	e_backSelectPaperKind = TYPE_PaperTypeThick4;		break;	// 厚紙４キー.
		case 6: 	e_backSelectPaperKind = TYPE_PaperTypeOHP;			break;	// OHPキー.
		case 7:		e_backSelectPaperKind = TYPE_PaperTypeEnvelope;		break;	// 封筒キー.
		case 8:		e_backSelectPaperKind = TYPE_PaperTypeUser1;		break;	// ユーザー紙1キー.
		case 9:		e_backSelectPaperKind = TYPE_PaperTypeUser2;		break;	// ユーザー紙2キー.
		case 10:	e_backSelectPaperKind = TYPE_PaperTypeUser3;		break;	// ユーザー紙3キー.
		case 11:	e_backSelectPaperKind = TYPE_PaperTypeUser4;		break;	// ユーザー紙4キー.
		case 12:	e_backSelectPaperKind = TYPE_PaperTypeUser5;		break;	// ユーザー紙5キー.
		case 13:	e_backSelectPaperKind = TYPE_PaperTypeUser6;		break;	// ユーザー紙6キー.
		case 14:	e_backSelectPaperKind = TYPE_PaperTypeThin1;		break;	// 薄紙.
// comment 2018/03/15 SCD2 N.yamura [Eagle][RQ-722]用紙種別追加（厚紙1を2種類に分割）対応.
		case 15:	e_backSelectPaperKind = TYPE_PaperTypeNormalPlus;	break;	// 普通紙+.
		default: break;
	}

	// 組み合わせ禁止チェック.
	if( False == PServiceFunctionEnableStartCom::getServiceDuplexMode() ) {		// 片面選択中.
		e_SelectPaperKind = e_backSelectPaperKind;
	} else {
		if( ( option < 5 || 8 <= option )
		    && option != 14 ) {	// 厚紙４、OHP、封筒、薄紙以外.
			e_SelectPaperKind = e_backSelectPaperKind;
		}
	}
	setupGamen();	// 表示部品のセットアップ.
}
