{
	PServiceFunctionEnableStartCom::setCheckComSetBackFlg( PNLE_SelectBackGamentoPaperKind );	// 戻り元画面フラグの設定.
	PServiceFunctionEnableStartCom::setSelectPaperKind( e_SelectPaperKind );
	nextGamen = PServiceFunctionEnableStartCom::prevServiceComGamen;		// 呼び出し元画面へ遷移.
}
