//================================================================================================
// 概要		:サービス・課金設定・ライセンス管理共通 : コードに5文字毎「-」を代入.
//================================================================================================
void PServiceLicenseManagementCom::addHyphen(
    const uchar* _uc_Code,		// コード文字列.
    uchar* _uc_CodeAddHyphen	// 「-」代入後格納用.
)
{
	register char _ss_buff[PNLD_CodeBlockLenMax];
	memset( _ss_buff, '\0', sizeof( _ss_buff ) );
	uchar uc_Len = static_cast<uchar>( strlen( ( char* )_uc_Code ) );	// コード文字長.
	uchar uc_cnt = 0;
	for( uc_cnt = 0; uc_cnt < uc_Len/PNLD_CodeBlockLenMax; uc_cnt++ ) {
		strncpy( ( char* )_uc_CodeAddHyphen+( PNLD_CodeBlockLenMax*uc_cnt+uc_cnt ), ( char* )( _uc_Code )+( PNLD_CodeBlockLenMax*uc_cnt ), PNLD_CodeBlockLenMax );
		if( uc_Len/PNLD_CodeBlockLenMax-1 == uc_cnt ) {
			if( 0 != ( uc_Len%PNLD_CodeBlockLenMax ) ) {
				strcat( ( char* )_uc_CodeAddHyphen, "-" );
			}
		} else {
			strcat( ( char* )_uc_CodeAddHyphen, "-" );
		}
	}
}
//================================================================================================
// 概要		:サービス・課金設定・ライセンス管理共通 : 結果表示.
//================================================================================================
void PServiceLicenseManagementCom::licenseManagementResultDisp( TYPE_EnablerResult e_startLicenseResult )
{
	TEXT_ID ps_ResultMsg = s_MSGServiceMainPowerOffOnMes;	// 結果メッセージ.
	if( TYPE_EnablerResult_OK == e_startLicenseResult ) {	// 結果：OK.
		ps_ResultMsg = s_MSGServiceMainPowerOffOnMes;	// 必ず主電源をOFF/ONしてください.
	} else if( TYPE_EnablerResult_ParamError == e_startLicenseResult ) {	// 結果：パラメータエラー.
		ps_ResultMsg = s_MSGServiceSettingErrorMes2;	// 確定できませんでした.
	} else {	// 結果：OK、パラメータエラー以外.
		ps_ResultMsg = s_MSGServiceSettingErrorMes;		// 設定が正しくありません.
	}
	Txt_ServiceLicenseManagementFixMsg.changeText( ps_ResultMsg );	// 必ず主電源をOFF/ONしてください.

	Grp_ServiceLicenseManagementFix.showEnable( ( PNLD_LicenseManagement_Complete == _uc_LicenseManagementState )? True: False );	// ライセンス管理・確定キー押下メッセージ.
}
