//================================================================================================
// 概要		:サービス・課金設定・ライセンス管理共通 : インデックスボタン.
//================================================================================================
void PServiceLicenseManagementCom::procIndexButton( uchar option )
{
	switch( option ) {
		case BTNID_GOTO_ServiceLicenseManagementMenuEnabler:		// 有効化.
			bl_isRequestInitialize = True;	// 初期化必要.
			nextGamen = &gp_ServiceLicenseManagementEnabler;			// サービス・課金設定・ライセンス管理・有効化画面.
			break;
		case BTNID_GOTO_ServiceLicenseManagementMenuDisabler:		// 無効化.
			bl_isRequestInitialize = True;	// 初期化必要.
			nextGamen = &gp_ServiceLicenseManagementDisabler;			// サービス・課金設定・ライセンス管理・無効化画面.
			break;
		case BTNID_GOTO_ServiceLicenseManagementMenuRepair:			// 修復.
			bl_isRequestInitialize = True;	// 初期化必要.
			nextGamen = &gp_ServiceLicenseManagementRepair;				// サービス・課金設定・ライセンス管理・修復画面.
			break;
		case BTNID_GOTO_ServiceLicenseManagementMenuIitialization:	// 初期化.
			bl_isRequestInitialize = True;	// 初期化必要.
			nextGamen = &gp_ServiceLicenseManagementInitialCodeInput;	// サービス・課金設定・ライセンス管理・初期化コード入力画面.
			break;
		case BTNID_GOTO_ServiceLicenseManagementMenuRequestCode:	// リクエストコード.
			nextGamen = &gp_ServiceLicenseManagementWait;				// サービス・課金設定・ライセンス管理・処理中画面.
			PnlComGetEnabler()->req_startGetRequestCode( ans_startGetRequestCode );	// リクエストコード取得要求.
			break;
		case BTNID_GOTO_ServiceLicenseManagementMenuList: nextGamen = &gp_ServiceLicenseManagementList; break;	// サービス・課金設定・ライセンス管理・一覧画面.
		case BTNID_GOTO_ServiceLicenseManagementMenuFCodeList:
			nextGamen = &gp_ServiceLicenseManagementFCodeList;	// サービス・課金設定・ライセンス管理・機能コード一覧.
			break;
		default: break;
	}
}
//================================================================================================
// 概要		:サービス・課金設定・ライセンス管理共通 : コールバック処理.
//================================================================================================
void PServiceLicenseManagementCom::procCallBack( TYPE_PNL_CallBack e_PNL_CallBack )
{
	_uc_LicenseManagementState = PNLD_LicenseManagement_Complete;	// コールバック状態:完了状態.
	switch( e_PNL_CallBack ) {
		case TYPE_PNL_CallBack_LicenseManagement_Enabler:				// 有効化.
			if( TYPE_EnablerResult_OK == _e_startEnablerResult ) {	// 結果:OK.
				bl_NoAcceptBtnFlag = True;	// ボタン受付不可にする.
			} else {	// 結果:OK以外.
				bl_NoAcceptBtnFlag = False;	// ボタン受付可にする.
			}
			break;
		case TYPE_PNL_CallBack_LicenseManagement_Disabler:				// 無効化.
			if( TYPE_EnablerResult_OK == _e_startDisablerResult ) {	// 結果:OK.
				gp_ServiceLicenseManagementDisablerCompletionCode.setNoAcceptBtnFlag( False );	// ボタン受付可にする.
				nextGamen = &gp_ServiceLicenseManagementDisablerCompletionCode;		// サービス・課金設定・ライセンス管理・無効化完了コード表示画面.
			} else {	// 結果:OK以外.
				bl_DisplayErrorCode = True;	// エラーコードを表示するか否か.
				gp_ServiceLicenseManagementDisabler.setNoAcceptBtnFlag( False );	// ボタン受付可にする.
				nextGamen = &gp_ServiceLicenseManagementDisabler;	// サービス・課金設定・ライセンス管理・無効化画面.
			}
			break;
		case TYPE_PNL_CallBack_LicenseManagement_GetRepairRequestCode:	// 修復要求コード.
			gp_ServiceLicenseManagementRepair.setNoAcceptBtnFlag( False );	// ボタン受付可にする.
			nextGamen = &gp_ServiceLicenseManagementRepairRequestCode;			// サービス・課金設定・ライセンス管理・修復要求コード表示画面.
			break;
		case TYPE_PNL_CallBack_LicenseManagement_Repair:					// 修復.
			gp_ServiceLicenseManagementRepair.setNoAcceptBtnFlag( False );	// ボタン受付可にする.
			_uc_LicenseManagementState = PNLD_LicenseManagement_PostProc;	// コールバック状態:後処理状態.
			nextGamen = &gp_ServiceLicenseManagementRepair;	// サービス・課金設定・ライセンス管理・修復画面.
			break;
		case TYPE_PNL_CallBack_LicenseManagement_EnablerByUSB:				// USBによる有効化.
			gp_ServiceLicenseManagementEnabler.setNoAcceptBtnFlag( ( TYPE_EnablerResult_OK == _e_startEnablerResult ) );	// ボタン受付設定.
			break;
		case TYPE_PNL_CallBack_LicenseManagement_DisablerByUSB:				// USBによる無効化.
			gp_ServiceLicenseManagementDisabler.setNoAcceptBtnFlag( ( TYPE_EnablerResult_OK == _e_startDisablerResult ) );	// ボタン受付設定.
			break;
		case TYPE_PNL_CallBack_LicenseManagement_GetRepairRequestCodeByUSB:	// USBによる修復要求コード.
			gp_ServiceLicenseManagementRepair.setNoAcceptBtnFlag( False );	// ボタン受付可にする.
			break;
		case TYPE_PNL_CallBack_LicenseManagement_RepairByUSB:				// USBによる修復.
			gp_ServiceLicenseManagementRepair.setNoAcceptBtnFlag( False );	// ボタン受付可にする.
			break;
		case TYPE_PNL_CallBack_LicenseManagement_Initialization:		// 初期化.
			if( TYPE_EnablerResult_OK == _e_startLicenseInitializationResult ) {	// 結果:OK.
				gp_ServiceLicenseManagementInitialCodeInput.setNoAcceptBtnFlag( True );		// ボタン受付不可にする.
			} else {	// 結果:OK以外.
				gp_ServiceLicenseManagementInitialCodeInput.setNoAcceptBtnFlag( False );	// ボタン受付可にする.
			}
			nextGamen = &gp_ServiceLicenseManagementInitialCodeInput;			// サービス・課金設定・ライセンス管理・初期化コード入力画面.
			break;
		case TYPE_PNL_CallBack_LicenseManagement_RequestCode:			// リクエストコード.
			gp_ServiceLicenseManagementRequestCode.setNoAcceptBtnFlag( False );	// ボタン受付可にする.
			if( TYPE_EnablerResult_OK == _e_startGetRequestCodeResult ) {	// 結果:OK.
				nextGamen = &gp_ServiceLicenseManagementRequestCode;			// サービス・課金設定・ライセンス管理・リクエストコード表示画面.
			} else {	// 結果:OK以外.
				nextGamen = &gp_ServiceLicenseManagementRequestCodeError;		// サービス・課金設定・ライセンス管理・リクエストコード発行エラー表示画面.
			}
			break;
		case TYPE_PNL_CallBack_LicenseManagement_GetFileName:				// ライセンス管理ファイル名取得.
			uchar uc_LicenseManagementType;	// ライセンス管理種類.
			// ライセンス管理種別の判定.
			for( uc_LicenseManagementType = PNLD_LicenseManagementType_Enable; uc_LicenseManagementType < PNLD_LicenseManagementType_Num; uc_LicenseManagementType++ ) {
				if( _sc_LicenseManagementFileName[uc_LicenseManagementType] == _pc_GetLicenseManagementFileName ) {break;}
				if( uc_LicenseManagementType == ( PNLD_LicenseManagementType_Num - 1 ) ) {return;}	// ありえない状態.
			}
			switch( _e_GetLicenseManagementFileNameResult ) {
				case SAAE_ResultOK:	_uc_LicenseManagementFileState[uc_LicenseManagementType] = PNLD_LicenseManagementFileState_Acquired;	break;	// 正常.
				case SAAE_ResultFileNotFound:	_uc_LicenseManagementFileState[uc_LicenseManagementType] = PNLD_LicenseManagementFileState_NoAcquisition;	break;	// 一致ファイル無し.
				case SAAE_ResultFoundFileNumErr:	// USBメモリ内のファイル数がSAAの検索能力上限値を超過している.
					// 本エラーが発生していても、ファイルが取得できていたら正常終了と同等扱い.
					// ∵取得できる中で最新のものを使用するのが現在の仕様であるため.
					if( *_sc_LicenseManagementFileName[uc_LicenseManagementType] == '\0' ) {
						_uc_LicenseManagementFileState[uc_LicenseManagementType] = PNLD_LicenseManagementFileState_NoAcquisition;
					} else {
						_uc_LicenseManagementFileState[uc_LicenseManagementType] = PNLD_LicenseManagementFileState_Acquired;
					}
					break;
				case SAAE_ResultParameterErr:		// API引数異常(default処理と同等のためbreakは省略).
				case SAAE_ResultOtherErr:			// SAA内部エラー(default処理と同等のためbreakは省略).
				default:
					_uc_LicenseManagementFileState[uc_LicenseManagementType] = PNLD_LicenseManagementFileState_NoAcquisition;
					break;
			}
			_uc_LicenseManagementState = PNLD_LicenseManagement_Init;	// コールバック状態:初期状態.
			break;
		default:	// その他.
			// 何もしない.
			PServiceFunctionEnableStartCom::procCallBack( e_PNL_CallBack );	// 継承元(親)のprocCallBackを呼び出す.
	}
}
//================================================================================================.
// 概要		:サービス・課金設定・ライセンス管理共通 : オブザーバー処理.
//================================================================================================.
void PServiceLicenseManagementCom::procObserver( TYPE_PNL_Observer e_PNL_Observer )
{
	APIC_Lca* pc_Lca = APIC_Lca::newInstance();
	char	sc_ErrorCodeResult[PNLD_ErrorCodeLenMax + 1];	// エラーコード+終端.
	memset( sc_ErrorCodeResult, '\0', sizeof( sc_ErrorCodeResult ) );	// エラーコードクリア.

	_uc_LicenseManagementState = PNLD_LicenseManagement_Complete;	// コールバック状態:完了状態.
	switch( e_PNL_Observer ) {
		case TYPE_PNL_Observer_LcaDispCode_Success: // トークンコードによる有効化、無効化成功.
			if( TYPE_LcaTrgKind_Enovation == _e_LcaTrgKind ) {
				gp_ServiceLicenseManagementRepair.setNoAcceptBtnFlag( False );	// ボタン受付可にする.
			}
			break;
		case TYPE_PNL_Observer_LcaDispCode_TokenCodeError:	// トークンコード誤り.
			bl_NoAcceptBtnFlag = False;
			gp_ServiceLicenseManagementDisabler.setNoAcceptBtnFlag( False );	// ボタン受付可にする.
			nextGamen = &gp_ServiceLicenseManagementErrorTokenCodeList;	// サービス・課金設定・ライセンス管理・有効化画面・トークンコードエラー画面.
			break;
		case TYPE_PNL_Observer_LcaDispCode_SerialNumberError:		// シリアルナンバーNGエラー.
		case TYPE_PNL_Observer_LcaDispCode_RequestCodeError:		// リクエストコードNGエラー.
		case TYPE_PNL_Observer_LcaDispCode_ServerConnectionError:	// サーバー接続エラー.
		case TYPE_PNL_Observer_LcaDispCode_ServerError:				// サーバーエラー.
		case TYPE_PNL_Observer_LcaDispCode_Error:					// その他のエラー.
			pc_Lca->getErrorCodeResult( sc_ErrorCodeResult );	// エラーコード取得.
			PNLC_TokenCodeSetting::getInstance()->setErrorCode( sc_ErrorCodeResult );	// エラーコードを設定.
			if( TYPE_LcaTrgKind_Activation == _e_LcaTrgKind ) {	// 機能有効化か無効化か？.
				bl_NoAcceptBtnFlag = False;	// ボタン受付可にする.
				_uc_LicenseManagementState = PNLD_LicenseManagement_Error;	// コールバック状態:エラー状態.
			} else if( TYPE_LcaTrgKind_Disablement == _e_LcaTrgKind ) {
				bl_DisplayErrorCode = True;	// エラーコードを表示するか否か.
				gp_ServiceLicenseManagementDisabler.setNoAcceptBtnFlag( False );	// ボタン受付可にする.
				nextGamen = &gp_ServiceLicenseManagementDisabler;	// サービス・課金設定・ライセンス管理・無効化画面.
			} else if( TYPE_LcaTrgKind_Enovation == _e_LcaTrgKind ) {
				gp_ServiceLicenseManagementRepair.setNoAcceptBtnFlag( False );	// ボタン受付可にする.
				_uc_LicenseManagementState = PNLD_LicenseManagement_Error;	// コールバック状態:エラー状態.
			}
			break;
		default:	// その他.
			// 何もしない.
			PServiceFunctionEnableStartCom::procObserver( e_PNL_Observer );	// 継承元(親)のprocObserverを呼び出す.
			break;
	}
}
//================================================================================================
// 概要		:サービス・課金設定・ライセンス管理共通 : タブレット端末切断によりサービスモードを終了する
//================================================================================================
void PServiceLicenseManagementCom::procTabletDisconnect( uchar option )
{

	if( ( TYPE_EnablerResult_OK == _e_startLicenseInitializationResult )
	    || ( ( PNLD_LicenseManagement_Complete == _uc_LicenseManagementState ) && ( TYPE_EnablerResult_OK == _e_startDisablerResult ) ) ) {
		return;
	}
	PServiceCom::procTabletDisconnect( option );
}
//================================================================================================
// 概要		:サービス・課金設定・ライセンス管理共通 : 表示部品のセットアップ.
//================================================================================================
void PServiceLicenseManagementCom::setupGamen( short option )
{
	// ライセンス管理異常状態の場合、修復キーを表示(True(異常)/False(正常)).
	Key_ServiceLicenseManagementMenuRepair.showEnable( PnlComGetEnabler()->isLicenseManagementAbnormal() );	// 修復キー.
	Key_ServiceLicenseManagementMenuRequestCode.showEnable( !( PnlComGetEnabler()->isLicenseManagementAbnormal() ) );	// リクエストコードキー.
	PNLC_TokenCodeSetting* cp_TokenCodeSetting = PNLC_TokenCodeSetting::getInstance();	// トークンコード管理クラス.
	Rbt_ServiceLicenseManagementMenuEnablerMode.select( ss_select );	// 機能/ライセンスコード・USB・トークンコード切り替え.
	if( 0 == ss_select ) {
		// 機能/ライセンスコード選択時の表示/非表示.
		Grp_ServiceLicenseManagementEnablerTokenCodeP1.showEnable( False );	// トークンコード選択時1P.
		Grp_ServiceLicenseManagementEnablerTokenCodeP2.showEnable( False );	// トークンコード選択時2P.
		Grp_ServiceLicenseManagementEnablerTokenCodePageChange.showEnable( False );	// ページ切り替え.
		Key_ServiceLicenseListFunctionCode.showEnable( True );	// 機能コードキー.
		Key_ServiceLicenseListLicenseCode.showEnable( True );	// ライセンスコードキー.
		Key_ServiceLicenseListDisablerCode.showEnable( True );	// 無効化コードキー.
		Bak_ServiceLicenseListFunctionCode.showEnable( True );	// 機能コード入力値表示.
		Bak_ServiceLicenseListLicenseCode.showEnable( True );	// ライセンスコード入力値表示.
	} else if( 1 == ss_select ) {
		// USB選択時の表示/非表示.
		Grp_ServiceLicenseManagementEnablerTokenCodeP1.showEnable( False );	// トークンコード選択時1P.
		Grp_ServiceLicenseManagementEnablerTokenCodeP2.showEnable( False );	// トークンコード選択時2P.
		Grp_ServiceLicenseManagementEnablerTokenCodePageChange.showEnable( False );	// ページ切り替え.
		Key_ServiceLicenseListFunctionCode.showEnable( False );	// 機能コードキー.
		Key_ServiceLicenseListLicenseCode.showEnable( False );	// ライセンスコードキー.
		Key_ServiceLicenseListDisablerCode.showEnable( False );	// 無効化コードキー.
		Bak_ServiceLicenseListFunctionCode.showEnable( False );	// 機能コード入力値表示.
		Bak_ServiceLicenseListLicenseCode.showEnable( False );	// ライセンスコード入力値表示.
	} else if( 2 == ss_select ) {
		// トークンコード選択時の表示/非表示.
		Key_ServiceLicenseListFunctionCode.showEnable( False );	// 機能コードキー.
		Key_ServiceLicenseListLicenseCode.showEnable( False );	// ライセンスコードキー.
		Key_ServiceLicenseListDisablerCode.showEnable( False );	// 無効化コードキー.
		Bak_ServiceLicenseListFunctionCode.showEnable( False );	// 機能コード入力値表示.
		Bak_ServiceLicenseListLicenseCode.showEnable( False );	// ライセンスコード入力値表示.
		Grp_ServiceLicenseManagementEnablerTokenCodePageChange.showEnable( True );	// ページ切り替え.
		if( 1 == ss_NowPage ) {
			Grp_ServiceLicenseManagementEnablerTokenCodeP2.showEnable( False );	// トークンコード選択時2P.
			Grp_ServiceLicenseManagementEnablerTokenCodeP1.showEnable( True );	// トークンコード選択時1P.
			Txt_ServiceTokenCodePage.changeText( s_SvcsCounterPage1_2 );		// ページ数変更.
			Bak_ServiceLicenseManagementEnablerTokenCode_01.changeExternalText( ( uchar* )cp_TokenCodeSetting->getTokenCodeAddHyphen( 0 ), PNLD_TokenCodeAddHyphenLenMax );	// 指定した番号のトークンコード(ハイフン付)を取得して表示.
			Bak_ServiceLicenseManagementEnablerTokenCode_02.changeExternalText( ( uchar* )cp_TokenCodeSetting->getTokenCodeAddHyphen( 1 ), PNLD_TokenCodeAddHyphenLenMax );	// 指定した番号のトークンコード(ハイフン付)を取得して表示.
			Bak_ServiceLicenseManagementEnablerTokenCode_03.changeExternalText( ( uchar* )cp_TokenCodeSetting->getTokenCodeAddHyphen( 2 ), PNLD_TokenCodeAddHyphenLenMax );	// 指定した番号のトークンコード(ハイフン付)を取得して表示.
			Bak_ServiceLicenseManagementEnablerTokenCode_04.changeExternalText( ( uchar* )cp_TokenCodeSetting->getTokenCodeAddHyphen( 3 ), PNLD_TokenCodeAddHyphenLenMax );	// 指定した番号のトークンコード(ハイフン付)を取得して表示.
			Bak_ServiceLicenseManagementEnablerTokenCode_05.changeExternalText( ( uchar* )cp_TokenCodeSetting->getTokenCodeAddHyphen( 4 ), PNLD_TokenCodeAddHyphenLenMax );	// 指定した番号のトークンコード(ハイフン付)を取得して表示.
		} else {
			Grp_ServiceLicenseManagementEnablerTokenCodeP1.showEnable( False );	// トークンコード選択時1P.
			Grp_ServiceLicenseManagementEnablerTokenCodeP2.showEnable( True );	// トークンコード選択時2P.
			Txt_ServiceTokenCodePage.changeText( s_SvcsCounterPage2_2 );		// ページ数変更.
			Bak_ServiceLicenseManagementEnablerTokenCode_05.changeExternalText( ( uchar* )cp_TokenCodeSetting->getTokenCodeAddHyphen( 4 ), PNLD_TokenCodeAddHyphenLenMax );	// 指定した番号のトークンコード(ハイフン付)を取得して表示.
			Bak_ServiceLicenseManagementEnablerTokenCode_06.changeExternalText( ( uchar* )cp_TokenCodeSetting->getTokenCodeAddHyphen( 5 ), PNLD_TokenCodeAddHyphenLenMax );	// 指定した番号のトークンコード(ハイフン付)を取得して表示.
			Bak_ServiceLicenseManagementEnablerTokenCode_07.changeExternalText( ( uchar* )cp_TokenCodeSetting->getTokenCodeAddHyphen( 6 ), PNLD_TokenCodeAddHyphenLenMax );	// 指定した番号のトークンコード(ハイフン付)を取得して表示.
			Bak_ServiceLicenseManagementEnablerTokenCode_08.changeExternalText( ( uchar* )cp_TokenCodeSetting->getTokenCodeAddHyphen( 7 ), PNLD_TokenCodeAddHyphenLenMax );	// 指定した番号のトークンコード(ハイフン付)を取得して表示.
			Bak_ServiceLicenseManagementEnablerTokenCode_09.changeExternalText( ( uchar* )cp_TokenCodeSetting->getTokenCodeAddHyphen( 8 ), PNLD_TokenCodeAddHyphenLenMax );	// 指定した番号のトークンコード(ハイフン付)を取得して表示.
		}
	}
	PServiceCom::setupGamen( option );	// 親クラスの処理を呼ぶ.
	printLEDControl( False );	// プリントキー・バックライトの赤.
}
//================================================================================================
//［機能］	：ライセンス管理・有効な機能コードがあるか(True：有る).
//================================================================================================
Bool PServiceLicenseManagementCom::isFunctionCode()
{
	uchar uc_FunctionStatus[8];			// 機能コードの状態.
	uchar uc_FunctionWaitStatus[8];		// 機能コード電源OFF/ON待ち状態(使わない).
	memset( uc_FunctionStatus, '\0',sizeof( uc_FunctionStatus ) );
	memset( uc_FunctionWaitStatus, '\0',sizeof( uc_FunctionWaitStatus ) );
	PnlComGetEnabler()->getFunctionEnablerStatus( uc_FunctionStatus , uc_FunctionWaitStatus );	// 機能状態取得（FEK）.

	short ss_Byte = 0;		// チェックしているByte.
	short ss_Bit = 0;		// チェックしているbit.
	uchar uc_Mask = 0x01;	// マスク用.
	Bool b_Result = False;	// 表示する数.
	uchar uc_PrebitNumber = 0;	// bit番号格納用.

	for( short i = 0 ; i < DEF_FunctionCodeListTbl ; i++ ) {
		uc_PrebitNumber = static_cast<uchar>( functionCodeListTbl[i].bitNumber - 1 );	// bit番号を配列計算用に-1しておく.
		ss_Byte =( uc_PrebitNumber / 8 );	// チェックするbitがどこにあるか算出.
		ss_Bit = ( uc_PrebitNumber % 8 );	// チェックするbitがどこにあるか算出.

		uc_Mask = 0x01;	// マスクを初期化.
		uc_Mask = ( uchar )( uc_Mask << ss_Bit );
		if( ( uc_FunctionStatus[ss_Byte] & uc_Mask ) != 0 ) {	// 対象bitが「1」か判断.
			b_Result = True;
		}
	}
	return	b_Result;
}

