//================================================================================================
//概要    :サービス・課金設定・ライセンス管理・有効化画面(FEK/DLK) : 初期設定.
//================================================================================================
void PServiceLicenseManagementEnabler::startGamen()
{
	PBasicMessageProc::startGamen();

	CheckAndExecInit();	// 初期化必要か否か取得して必要なら実行する.
	licenseManagementRetGamen = this;	// 戻り画面の設定.
	pc_functionManagementRetGamen = this;	//  戻り画面の設定.
	_uc_LicenseManagementState = PNLD_LicenseManagement_Init;	// コールバック状態初期化.
	uc_enablerWaitTime = 0;			// 有効化待ち時間.
// Comment 2015/07/20 HCLT-Surajit RQ-163[WP 1376]  Hide the USB key .
// Comment 2017/11/29 【HCLT-Vishal】【Eagle】【制御構成変更_No.4】 Removing old function version check condition.
	PNLC_USBConnectionPermission c_UsbPermission;
	PNLE_EnableUSBConnectionPermissionForAll e_usbAll = c_UsbPermission.getEnableUSBConnectionPermissionForAll();
	PNLE_EnableUSBConnectionPermissionForService e_usbforService = c_UsbPermission.getEnableUSBConnectionPermissionForService();
	if(( PNLE_EnableUSBConnectionPermissionForAll_Disable == e_usbAll ) || ( PNLE_EnableUSBConnectionPermissionForService_Disable == e_usbforService )) {
		m_bl_USBConnectionPermissionFlag = False;
	} else {
		m_bl_USBConnectionPermissionFlag = True;
	}

}
//================================================================================================
//概要    :サービス・課金設定・ライセンス管理・有効化画面(FEK/DLK) : 変数などの初期化.
//================================================================================================
void PServiceLicenseManagementEnabler::init_value()
{
	// 有効化選択状態初期化.
	ss_select	= 0;	// 選択キー.
	ss_NowPage	= 1;	// 現在のページ番号.
	_e_LcaTrgKind = TYPE_LcaTrgKind_Activation;		// 有効化.
	PNLC_TokenCodeSetting::getInstance()->clearTokenCode(); // トークンコードとトークンコード(ハイフン付)クリア.
	memset(	uc_LicenseCode, '\0', sizeof( uc_LicenseCode ) );					// ライセンスコード.
	memset(	uc_FunctionCode, '\0', sizeof( uc_FunctionCode ) );	// 機能コード.
	// ライセンス管理ファイル(有効化)の取得.
	_uc_LicenseManagementFileState[PNLD_LicenseManagementType_Enable] = PNLD_LicenseManagementFileState_Unacquisition;
	memset( _sc_LicenseManagementFileName,'\0',sizeof( _sc_LicenseManagementFileName[PNLD_LicenseManagementType_Enable] ) );
	APIF_SaaGetLicenseManagementFileName( SAAE_LicenseManagementModeValid, _sc_LicenseManagementFileName[PNLD_LicenseManagementType_Enable], ans_getLicenseManagementFileName );
//comment 2018/04/16 HCLT-Haribhaskar [IT6_Eagle] [RQ-698-2] [WP-3681] Removing WebLicense Management.
//	m_bl_WebBrowser = False;	// Webブラウザーが選択されているか.
}
//================================================================================================.
//概要    :サービス・課金設定・ライセンス管理・有効化画面(FEK/DLK) : １秒タイマ.
//================================================================================================.
void PServiceLicenseManagementEnabler::procSecond( uchar option )
{
	if( True == bl_NoAcceptBtnFlag && 0 == ss_select ) {			// 秒数カウント開始条件.
		++uc_enablerWaitTime;										// 秒数をカウント.
		if( PNLD_EnablerWaitTime == uc_enablerWaitTime ) {			// 画面開始後5秒経過.
			PnlComGetEnabler()->req_startEnabler( ( uchar* )uc_FunctionCode,	// 有効化選択状態.
			                                      uc_LicenseCode,			// ライセンスコード.
			                                      ans_startEnabler );		// コールバック.
		}
	}
}
