//================================================================================================
// 概要		:サービス・課金設定・ライセンス管理・有効化画面(FEK/DLK) : 結果表示.
//================================================================================================
void PServiceLicenseManagementEnabler::licenseManagementResultDisp()
{
	TEXT_ID ps_ResultMsg = s_MSGServiceMainPowerOffOnMes;	// 結果メッセージ.
	Bool bl_display = False;								// 結果欄への表示判断.
	Bool bl_DisplayError = False;	// エラーコード表示判断.
	Bool bl_slash = False;	// 処理中の表示判断.
	switch( _uc_LicenseManagementState ) {
		case PNLD_LicenseManagement_Init:	// 初期状態.
			break;
		case PNLD_LicenseManagement_Wait:	// 待ち状態.
			ps_ResultMsg = s_MSGServicePleaseWaitRestartAfterCompletion;	// お待ちください完了後再起動します.
			bl_slash = True;
			bl_display = True;
			break;
		case PNLD_LicenseManagement_Complete:	// 完了状態.
			uc_enablerWaitTime = 0; // 有効化待ち時間.
			if( TYPE_EnablerResult_ParamError == _e_startEnablerResult ) {	// 結果：パラメータエラー.
				ps_ResultMsg = s_MSGServiceSettingErrorMes;		// 設定が正しくありません.
			} else if( TYPE_EnablerResult_OK != _e_startEnablerResult ) {	// 結果：OK、パラメータエラー以外.
				ps_ResultMsg = s_MSGServiceSettingErrorMes2;	// 確定できませんでした.
			} else {	// 結果：OK.
				ps_ResultMsg = s_MSGServicePleaseWaitRestartAfterCompletion;	// お待ちください完了後再起動します.
			}
			bl_display = True;
			break;
		case PNLD_LicenseManagement_Error:	// エラー状態.
			bl_DisplayError = True;					// エラーコード表示判断.
			break;
		default:									// 不正な状態.
			PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "PServiceLicenseManagementEnabler::licenseManagementResultDisp", UC_PNL_ERROR_IMPOSSIBLE );
			break;
	}
	Txt_ServiceLicenseManagementEnablerScreenSlash.showEnable( bl_slash );	// 処理中の表示.
	if( True == bl_slash ) { showExecuting(); }	// 処理中の表示.
	if( ss_select == 2 ) {
		Grp_ServiceLicenseManagementFix.showEnable( False );			// 結果表示.
		if( True == bl_DisplayError ) {
			Grp_ServiceLicenseManagementTokenFix.showEnable( False );	// 結果表示.
			Grp_ServiceLicenseManagementErrorCodeMsg.showEnable( True );		// エラーコード表示.
			Tfd_ServiceLicenseManagementErrorCodeMsg.changeExternalText( ( uchar* )PNLC_TokenCodeSetting::getInstance()->getErrorCode() );	// エラーコード.
		} else {
			Grp_ServiceLicenseManagementErrorCodeMsg.showEnable( False );		// エラーコード表示.
			Grp_ServiceLicenseManagementTokenFix.showEnable( bl_display );		// 結果表示.
			if( True == bl_display ) { Txt_ServiceLicenseManagementTokenFixMsg.changeText( ps_ResultMsg ); }	// 表示内容設定.
		}
	} else {
		Grp_ServiceLicenseManagementTokenFix.showEnable( False );		// 結果表示.
		Grp_ServiceLicenseManagementErrorCodeMsg.showEnable( False );		// エラーコード表示.
		Grp_ServiceLicenseManagementFix.showEnable( bl_display );		// 結果表示.
		if( True == bl_display ) { Txt_ServiceLicenseManagementFixMsg.changeText( ps_ResultMsg ); }	// 表示内容設定.
	}
}
//================================================================================================
//概要    :サービス・課金設定・ライセンス管理・有効化画面(FEK/DLK) : 表示部品のセットアップ.
//================================================================================================
void PServiceLicenseManagementEnabler::setupGamen( short option )
{
	Rbt_ServiceLicenseManagementMenu.select( 0 );							// ライセンス管理・左側メニューローテンションボタン.
	Key_ServiceLicenseManagementEnablerFunctionOrLicenseCode.changeText( s_KEYServiceFunctionOrLicenseCode );	// 機能/ライセンスコード.
	// ライセンスコード表示.
	uchar uc_LocalLicenseCodeAddHyphen[ PNLD_LicenseCodeMax + 6 + 1 ];	// ライセンスコード+ハイフン.
	memset( uc_LocalLicenseCodeAddHyphen, '\0',sizeof( uc_LocalLicenseCodeAddHyphen ) );	// 変数の初期化.
	addHyphen( uc_LicenseCode, uc_LocalLicenseCodeAddHyphen );	// コードに5文字毎「-」を代入.
	Bak_ServiceLicenseListLicenseCode.changeExternalText( uc_LocalLicenseCodeAddHyphen, sizeof( uc_LocalLicenseCodeAddHyphen ) );	// ライセンスコード表示エリア.
	Bak_ServiceLicenseListFunctionCode.changeExternalText( uc_FunctionCode, sizeof( uc_FunctionCode ) );	// 機能コード表示エリア.
	Bool bl_UsbKeyShow = False;
	if( PNLD_LicenseManagementFileState_Acquired == _uc_LicenseManagementFileState[PNLD_LicenseManagementType_Enable] ) {
		bl_UsbKeyShow = True;				// USBでの有効化キー表示.
	} else {
		bl_UsbKeyShow = False;	// USBでの有効化キー非表示.
	}
//Comment 2015/07/20 HCLT-Surajit RQ-163[WP 1376]  Hide the USB key to avoid flicker issue.
//	Key_ServiceLicenseManagementEnablerUsb.showEnable( bl_UsbKeyShow );	// USBでの有効化キー表示/非表示.
	if( False == bl_UsbKeyShow && 1 == ss_select ) {	// 途中でUSBが引き抜かれたときの対応.
		ss_select = 0;
		_uc_LicenseManagementState = PNLD_LicenseManagement_Init;	// オブザーバー状態:初期状態.
	}
	licenseManagementResultDisp();		// 結果表示.

	Key_ServiceLicenseManagementEnablerTokenCode.changeText( s_KEYServiceTokenCode );	// トークンコード.
//comment 2018/04/16 HCLT-Haribhaskar [IT6_Eagle] [RQ-698-2] [WP-3681] Removing WebLicense Management.
	// Webブラウザーキーの選択.
//	if( 2 == ss_select && 1 == ss_NowPage && True == m_bl_WebBrowser )
//	{
//		Key_ServiceLicenseManagementEnablerWebBrowser.select( True );
//	} else {
//		Key_ServiceLicenseManagementEnablerWebBrowser.select( False );
//	} 

	PServiceLicenseManagementCom::setupGamen( option );	// 親クラスの処理を呼ぶ.
// Comment 2015/07/20 HCLT-Surajit RQ-163[WP 1376]  Hide the USB key .
// Comment 2017/11/29 【HCLT-Vishal】【Eagle】【制御構成変更_No.4】 Removing old function version check and else portion.
	if( False == m_bl_USBConnectionPermissionFlag ){ 						//USB接続許可設定の[一括設定]または[外部メモリー(サービス)]が[禁止]の場合.
		Key_ServiceLicenseManagementEnablerUsb.showEnable(False);			// USBでの有効化キー非表示.
	} else {
// Comment 2015/07/20 HCLT-Surajit RQ-163[WP 1376] [ UTCT Fix]  Hide the USB key .
//		Key_ServiceLicenseManagementEnablerUsb.showEnable(True);			// USBでの有効化キー表示.
		Key_ServiceLicenseManagementEnablerUsb.showEnable( bl_UsbKeyShow );		// USBでの有効化キー表示/非表示.
	}
}
//================================================================================================
//概要    :サービス・課金設定・ライセンス管理・有効化画面(FEK/DLK) : 有効化中表示処理.
//================================================================================================
void PServiceLicenseManagementEnabler::showExecuting()
{
	static	Bool	b_ExecutingAnimeSts = False;	// 処理中であることを示す表示を行うためのフラグ.
	TEXT_ID			executingTextId;

	if( True == b_ExecutingAnimeSts ) {
		executingTextId = s_EXPSlash;
		b_ExecutingAnimeSts = False;
	} else {
		executingTextId = s_EXPBackslash;
		b_ExecutingAnimeSts = True;
	}
	Txt_ServiceLicenseManagementEnablerScreenSlash.changeText( executingTextId );
}
