//================================================================================================
//概要    :サービス・課金設定・ライセンス管理・無効化画面 : 初期設定.
//================================================================================================
void PServiceLicenseManagementDisabler::startGamen()
{
	PBasicMessageProc::startGamen();

	CheckAndExecInit();	// 初期化必要か否か取得して必要なら実行する.
	licenseManagementRetGamen = this;	// 戻り画面の設定.
	if( True == bl_DisplayErrorCode ) {
		_uc_LicenseManagementState = PNLD_LicenseManagement_Complete; // コールバック完了フラグ:完了保持.
		bl_DisplayErrorCode = False;
	} else {
		_uc_LicenseManagementState = PNLD_LicenseManagement_Init; // コールバック完了フラグ:OFF.
	}

	uc_disablerWaitTime = 0;	// 無効化待ち時間.
// Comment 2015/07/20 HCLT-Surajit RQ-163[WP 1376]  Hide the USB Key.	
// Comment 2017/11/29 【HCLT-Vishal】【Eagle】【制御構成変更_No.4】 Removing old function version check condition.
	PNLC_USBConnectionPermission c_UsbPermission;
	PNLE_EnableUSBConnectionPermissionForAll e_usbAll = c_UsbPermission.getEnableUSBConnectionPermissionForAll();
	PNLE_EnableUSBConnectionPermissionForService e_usbforService = c_UsbPermission.getEnableUSBConnectionPermissionForService();
	if(( PNLE_EnableUSBConnectionPermissionForAll_Disable == e_usbAll ) || ( PNLE_EnableUSBConnectionPermissionForService_Disable == e_usbforService )) {
		m_bl_USBConnectionPermissionFlag = False;
	} else {
		m_bl_USBConnectionPermissionFlag = True;
	}
}
//================================================================================================
//概要    :サービス・課金設定・ライセンス管理・無効化画面 : 変数などの初期化.
//================================================================================================
void PServiceLicenseManagementDisabler::init_value()
{
	// 無効化選択状態初期化.
	memset(	uc_DisablerCode, '\0', sizeof( uc_DisablerCode ) );				// 無効化コード.
	memset(	sc_FunctionCodeDisable, '\0', sizeof( sc_FunctionCodeDisable ) );	// 機能コード.
	ss_select	= 0;	// 選択キー.
	ss_NowPage	= 1;	// 現在のページ番号.
	_e_LcaTrgKind = TYPE_LcaTrgKind_Disablement;	// 無効化.
	PNLC_TokenCodeSetting* cp_TokenCodeSetting = PNLC_TokenCodeSetting::getInstance(); // トークンコード管理クラス.
	cp_TokenCodeSetting->clearTokenCode();			// トークンコードとトークンコード(ハイフン付)クリア.
	cp_TokenCodeSetting->setSelectTokenCode( False ); // トークンコードキーの選択状態を設定.
	// ライセンス管理ファイル(無効化)の取得.
	_uc_LicenseManagementFileState[PNLD_LicenseManagementType_Disable] = PNLD_LicenseManagementFileState_Unacquisition;
	memset( _sc_LicenseManagementFileName,'\0',sizeof( _sc_LicenseManagementFileName[PNLD_LicenseManagementType_Disable] ) );
	APIF_SaaGetLicenseManagementFileName( SAAE_LicenseManagementModeInvalid, _sc_LicenseManagementFileName[PNLD_LicenseManagementType_Disable], ans_getLicenseManagementFileName );
//comment 2018/04/16 HCLT-Haribhaskar [IT6_Eagle] [RQ-698-2] Removing Web Browser Functionality.
//	m_bl_WebBrowser = False;	// Webブラウザーが選択されているか.
}
