//================================================================================================
void PServiceLicenseManagementDisabler::procGoToPage( uchar option )
{
	switch( option ) {
		case BTNID_GOTO_ServiceLicenseManagementEnablerFunctionCode: nextGamen = &gp_ServiceLicenseManagementFunctionCodeDisableInput; break;	// サービス・課金設定・ライセンス管理・機能コード入力画面.
		case BTNID_GOTO_ServiceLicenseManagementDisablerCode: nextGamen = &gp_ServiceLicenseManagementDisablerCodeInput; break;					// サービス・課金設定・ライセンス管理・無効化コード入力画面.
		case BTNID_GOTO_ServiceLicenseManagementEnablerTokenCode_01:		// トークンコード1押下.
		case BTNID_GOTO_ServiceLicenseManagementEnablerTokenCode_02:		// トークンコード2押下.
		case BTNID_GOTO_ServiceLicenseManagementEnablerTokenCode_03:		// トークンコード3押下.
		case BTNID_GOTO_ServiceLicenseManagementEnablerTokenCode_04:		// トークンコード4押下.
		case BTNID_GOTO_ServiceLicenseManagementEnablerTokenCode_05:		// トークンコード5押下.
		case BTNID_GOTO_ServiceLicenseManagementEnablerTokenCode_06:		// トークンコード6押下.
		case BTNID_GOTO_ServiceLicenseManagementEnablerTokenCode_07:		// トークンコード7押下.
		case BTNID_GOTO_ServiceLicenseManagementEnablerTokenCode_08:		// トークンコード8押下.
		case BTNID_GOTO_ServiceLicenseManagementEnablerTokenCode_09:		// トークンコード9押下.
			PNLC_TokenCodeSetting::getInstance()->setSelectTokenCodeNum( static_cast<uchar>( option - BTNID_GOTO_ServiceLicenseManagementEnablerTokenCode_01 ) );	// 選択されているトークンコードの番号を設定.
			nextGamen = &gp_ServiceLicenseManagementTokenCodeEnableInput;	// サービス・課金設定・ライセンス管理・トークンコード入力画面.
			break;
		default: break;
	}
}
//================================================================================================
//概要    :サービス・課金設定・ライセンス管理・無効化画面 : ボタン（押された）.
//================================================================================================
void PServiceLicenseManagementDisabler::procButtonOn( uchar option )
{
	PNLC_TokenCodeSetting* cp_TokenCodeSetting = PNLC_TokenCodeSetting::getInstance();	// トークンコード管理クラス.

	switch( option ) {
		case BTNID_ServiceLicenseManagementEnablerFunctionOrLicenseCode:	// 機能/無効化コードキー.
			ss_select = 0;
			cp_TokenCodeSetting->setSelectTokenCode( False );		// トークンコードキーの選択状態を設定.
			_uc_LicenseManagementState = PNLD_LicenseManagement_Init;	// コールバック状態:初期状態.
			break;
		case BTNID_ServiceLicenseManagementEnablerUsb:			// USBキー.
			ss_select = 1;
			cp_TokenCodeSetting->setSelectTokenCode( False );		// トークンコードキーの選択状態を設定.
			_uc_LicenseManagementState = PNLD_LicenseManagement_Init;	// コールバック状態:初期状態.
			break;
		case BTNID_ServiceLicenseManagementEnablerTokenCode:	// トークンコードキー.
			ss_select = 2;
			cp_TokenCodeSetting->setSelectTokenCode( True );		// トークンコードキーの選択状態を設定.
			_uc_LicenseManagementState = PNLD_LicenseManagement_Init;	// コールバック状態:初期状態.
			break;
		case BTNID_KEY_UP_SERVICE_TOKENCODE:	// ページ切り替え(上).
			ss_NowPage--;
			if( ss_NowPage < 1 ) {
				ss_NowPage = 2;
			}
			break;
		case BTNID_KEY_DOWN_SERVICE_TOKENCODE:	// ページ切り替え(下).
			ss_NowPage++;
			if( ss_NowPage > 2 ) {
				ss_NowPage = 1;
			}
			break;
		case BTNID_ServiceLicenseManagementFix:	// 確定キー.
			if( NULL == PnlComGetEnablerSetting() ) {
//2019/06/17 Comment [HCLT_Krishnakumar][EagleH][N Rank] Removed unwanted detailed code.
//// 2015/11/05 【HCLT-Dhivya】 【ZeusS_ZX0】 【制御構成変更_No.76-1】Detail macro is passed in API.
//				LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//				if (NULL != pc_BFW_System){
//    				pc_BFW_System->registDetailCode(PNLD_DetailCode_Service_0x19000A0101319001);
//				}				
				LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
				return;	// 取得失敗.
			}

			bl_NoAcceptBtnFlag = True;	// ボタン受付不可にする.
			_uc_LicenseManagementState = PNLD_LicenseManagement_Wait;	// コールバック中.
			if( 0 == ss_select ) {
				// 無効化実行.
				nextGamen = &gp_ServiceLicenseManagementWait;	// サービス・課金設定・ライセンス管理・処理中画面.
				PnlComGetEnabler()->req_startDisabler( ( uchar* )sc_FunctionCodeDisable,	// 無効化選択状態.
				                                       uc_DisablerCode,			// 無効化コード.
				                                       ans_startDisabler );		// コールバック.
			} else if( 1 == ss_select ) {
				// USBによる有効化実行.
				PnlComGetEnabler()->req_StartDisablerForUsb( ( uchar* )( _sc_LicenseManagementFileName[PNLD_LicenseManagementType_Disable] ),	// ライセンス管理無効化ファイル名.
				        ans_startDisablerByUSB );		// コールバック.
			} else if( 2 == ss_select ) {
//comment 2018/04/16 HCLT-Haribhaskar [IT6_Eagle] [RQ-698-2] Removing WebLicense Management.
				// Webブラウザー選択時で、Webブラウザーのライセンスが無効状態の時.
//				if( True == m_bl_WebBrowser ) {
//					// ブラウザ有効時、電源OFF/ONの時のみ、選択可能.
//					TYPE_CategoryState	e_CategoryState = TYPE_CategoryState_NONE;
//					// 現在ライセンス状態取得.
//					e_CategoryState = PnlComGetEnablerSetting()->getFEK_CotegoryState( TYPE_FEKType01 );	// Webブラウザ.
//					if( ( TYPE_CategoryState_ENABLE  == e_CategoryState )
//					    || ( TYPE_CategoryState_RESTART == e_CategoryState ) ) {
//						// 連動設定ON.
//						PnlComGetEnablerSetting()->setInterlock( True );
//
//						PNLC_TokenCodeSetting::getInstance()->setSelectTokenCodeNum( 9 );	// 選択されているトークンコードの番号を設定.
//						char	sc_FileName[PNLD_TokenCodeLenMax + 1];
//						memset( sc_FileName, 0, sizeof( sc_FileName ) );
//						memcpy( &sc_FileName, PNLD_TokenCodeWebBrowser, sizeof( sc_FileName ) );
//						PNLC_TokenCodeSetting::getInstance()->setTokenCode( sc_FileName );	// 設定されている番号のインデックスにトークンコードを設定.
//					}
//				} 
				nextGamen = &gp_ServiceLicenseManagementWait;	// サービス・課金設定・ライセンス管理・処理中画面.
				PnlComGetEnablerSetting()->indTrg( _e_LcaTrgKind, cp_TokenCodeSetting->getLcaTokenCode() ); // トークンコードによる機能無効化実行要求.
			}
			break;
//comment 2018/04/16 HCLT-Haribhaskar [IT6_Eagle] [RQ-698-2] Removing WebLicense Management.
//		case BTNID_ServiceLicenseManagementEnablerWebBrowser:
//			if( False == m_bl_WebBrowser ) {
//				m_bl_WebBrowser = True;
//			} else {
//				m_bl_WebBrowser = False;
//			}
//			break; 
		default : break;
	}
	setupGamen();
}
//================================================================================================
// 概要		:サービス・課金設定・ライセンス管理・無効化画面 : 結果表示.
//================================================================================================
void PServiceLicenseManagementDisabler::licenseManagementResultDisp()
{
	TEXT_ID ps_ResultMsg = s_MSGServiceMainPowerOffOnMes;	// 結果メッセージ.
	Bool bl_display = False;								// 結果欄への表示判断.
	Bool bl_displayUSB = False;								// 結果欄への表示判断(USBでの無効化).
	switch( _uc_LicenseManagementState ) {
		case PNLD_LicenseManagement_Init:	// 初期状態.
			break;
		case PNLD_LicenseManagement_Wait:	// 待ち状態.
		case PNLD_LicenseManagement_Timer:	// タイマー待ち状態.
			ps_ResultMsg = s_ITMServiceOperating;	// 実行中.
			bl_display = True;
			break;
		case PNLD_LicenseManagement_Complete:	// 完了状態.
			if( TYPE_EnablerResult_OK == _e_startDisablerResult ) {	// 結果：OK.
				ps_ResultMsg = s_MSGServiceMainPowerOffOnMes;	// 必ず主電源をOFF/ONしてください.
				// UBSで無効化の場合のみ「無効化完了コードをLMSへ登録してください」を表示.
				bl_displayUSB = True;
			} else if( TYPE_EnablerResult_ParamError == _e_startDisablerResult ) {	// 結果：パラメータエラー.
				ps_ResultMsg = s_MSGServiceSettingErrorMes;		// 設定が正しくありません.
			} else {	// 結果：OK、パラメータエラー以外.
				ps_ResultMsg = s_MSGServiceSettingErrorMes2;	// 確定できませんでした.
			}
			bl_display = True;
			break;
		default:									// 不正な状態.
			PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "PServiceLicenseManagementDisabler::licenseManagementResultDisp", UC_PNL_ERROR_IMPOSSIBLE );
			break;
	}
	if( ss_select == 2 ) {
		Grp_ServiceLicenseManagementFix.showEnable( False );		// 結果表示.
		Txt_ServiceLicenseManagementFixMsgLMS.showEnable( False );	// USBでの無効化用結果表示.
		Grp_ServiceLicenseManagementErrorCodeMsg.showEnable( bl_display );		// エラーコード表示.
		if( True == bl_display ) {
			Tfd_ServiceLicenseManagementErrorCodeMsg.changeExternalText( ( uchar* )PNLC_TokenCodeSetting::getInstance()->getErrorCode() );	// エラーコード.
		}
	} else {
		Grp_ServiceLicenseManagementErrorCodeMsg.showEnable( False );		// エラーコード表示.
		Grp_ServiceLicenseManagementFix.showEnable( bl_display );			// 結果表示.
		if( True == bl_display ) { Txt_ServiceLicenseManagementFixMsg.changeText( ps_ResultMsg ); }		// 表示内容設定.
		Txt_ServiceLicenseManagementFixMsgLMS.showEnable( bl_displayUSB );	// USBでの無効化用結果表示.
	}
}
//================================================================================================
//概要    :サービス・課金設定・ライセンス管理・無効化画面 : 表示部品のセットアップ.
//================================================================================================
void PServiceLicenseManagementDisabler::setupGamen( short option )
{
	Rbt_ServiceLicenseManagementMenu.select( 1 );	// ライセンス管理・左側メニューローテンションボタン.
	Key_ServiceLicenseManagementEnablerFunctionOrLicenseCode.changeText( s_KEYFunctionOrCancellationCode );	// 機能/無効化コード
	// 無効化コード表示.
	uchar uc_LocalDisablerCodeAddHyphen[ PNLD_DisablerCodeMax + 7 + 1 ];	// 無効化コード+ハイフン.
	memset( uc_LocalDisablerCodeAddHyphen, '\0',sizeof( uc_LocalDisablerCodeAddHyphen ) );	// 変数の初期化.
	addHyphen( uc_DisablerCode, uc_LocalDisablerCodeAddHyphen );	// コードに5文字毎「-」を代入.
	Bak_ServiceLicenseListLicenseCode.changeExternalText( uc_LocalDisablerCodeAddHyphen, sizeof( uc_LocalDisablerCodeAddHyphen ) );	// 無効化コード表示エリア.
	Bak_ServiceLicenseListFunctionCode.changeExternalText( sc_FunctionCodeDisable, sizeof( sc_FunctionCodeDisable ) );	// 機能コード表示エリア.
	Bool bl_UsbKeyShow = False;
	if( PNLD_LicenseManagementFileState_Acquired == _uc_LicenseManagementFileState[PNLD_LicenseManagementType_Disable] ) {
		bl_UsbKeyShow = True;	// USBでの無効化キー表示.
	} else {
		bl_UsbKeyShow = False;	// USBでの無効化キー非表示.
	}
// Comment 2015/07/20 HCLT-Surajit RQ-163[WP 1376]  Hide the USB Key to avoid flicker issue.
//	Key_ServiceLicenseManagementEnablerUsb.showEnable( bl_UsbKeyShow );	// USBでの無効化キー表示/非表示.
	if( False == bl_UsbKeyShow && 1 == ss_select ) {	// 途中でUSBが引き抜かれたときの対応.
		ss_select = 0;
		_uc_LicenseManagementState = PNLD_LicenseManagement_Init;	// コールバック、オブザーバー状態:初期状態.
	}
	Key_ServiceLicenseManagementEnablerTokenCode.changeText( s_KEYServiceTokenCode );	// トークンコード.
	licenseManagementResultDisp();	// 結果表示.
//comment 2018/04/16 HCLT-Haribhaskar [IT6_Eagle] [RQ-698-2] Removing WebLicense Management.
	// Webブラウザーキーの選択.
//	if( 2 == ss_select && 1 == ss_NowPage && True == m_bl_WebBrowser )
//	{
//		Key_ServiceLicenseManagementEnablerWebBrowser.select( True );
//	} else {
//		Key_ServiceLicenseManagementEnablerWebBrowser.select( False );
//	} 

	PServiceLicenseManagementCom::setupGamen( option );	// 親クラスの処理を呼ぶ.
// Comment 2015/07/20 HCLT-Surajit RQ-163[WP 1376]  Hide the USB Key.
// Comment 2017/11/29 【HCLT-Vishal】【Eagle】【制御構成変更_No.4】 Removing old function version check and else portion.
	if( False == m_bl_USBConnectionPermissionFlag ){ 								//USB接続許可設定の[一括設定]または[外部メモリー(サービス)]が[禁止]の場合.
    	Key_ServiceLicenseManagementEnablerUsb.showEnable(False);					// USBでの無効化キー非表示.
	} else {
// Comment 2015/07/20 HCLT-Surajit RQ-163[WP 1376] [ UTCT Fix]  Hide the USB key .
//		Key_ServiceLicenseManagementEnablerUsb.showEnable(True);				// USBでの有効化キー表示.
		Key_ServiceLicenseManagementEnablerUsb.showEnable( bl_UsbKeyShow );		// USBでの有効化キー表示/非表示.
	}
}
//================================================================================================.
//概要    :サービス・課金設定・ライセンス管理・無効化画面 : １秒タイマ.
//================================================================================================.
void PServiceLicenseManagementDisabler::procSecond( uchar option )
{
	PServiceLicenseManagementCom::procSecond( option );

	if( PNLD_LicenseManagement_Timer == _uc_LicenseManagementState ) {
		++uc_disablerWaitTime;										// 秒数をカウント.
		if( PNLD_LicenseManagement_TimerWait <= uc_disablerWaitTime ) {
			CallBackIndi( TYPE_PNL_CallBack_LicenseManagement_DisablerByUSB );	// コールバックイベント発生.
			uc_disablerWaitTime = 0;
		}
	}
}

