//概要    :サービス・課金設定・ライセンス管理・有効化画面・機能コード入力画面 : 初期設定.
//================================================================================================
void PServiceLicenseManagementFunctionCodeEnableInput::startGamen()
{
	PServiceLicenseManagementFunctionCodeInputCom::startGamen();	// 親クラスの処理を呼ぶ.
// comment 2019/01/21 SCD2-Sky辰巳 [EagleH][OP_BTS-2227]【RQ-272】IP-FAXライセンスの機能コード【BAAAAA】を入力できない.
//	setKeyboardData( ( char* )uc_FunctionCode, 5, 64 );
	setKeyboardData( ( char* )uc_FunctionCode, PNLD_FunctionCodeLenMax, 64 );
	Kbd_ServiceInputKeybord.setChangeEnlKeybord( PLBD_Enl_KBD_Initial );
	Kbd_ServiceInputKeybord = PLBC_ConvertKeybord( PLBD_KBT_Alphabet_L, 88, 124, True, True ); // キーボード種類、配置位置設定.
	Kbd_ServiceInputKeybord.GetCursor( NULL ); //カーソルのアドレス取得.
	startGamenKeybordServiceA();
	Kbd_ServiceInputKeybord.showKeybord();	// キーボード表示.
	pa_DispField = &Btx_FunctionCodeKeybordInput;
	c_SlideTextMgr.init_CLCD( sc_StrKeyboard, sc_KeyboardWidth, ss_MaxInputNum, pa_DispField, EP_CharSet_USASCII );
	pa_DispField->setCursorPosition( ( short )strlen( sc_StrKeyboard ) );	// カーソルを文字列の最後尾に設定する.
	Kbd_ServiceInputKeybord.setKeybordType( PLBD_KBT_Alphabet_L );	// 確定したキーボードに切り替える.
}
