PServiceLicenseManagementRepair::PServiceLicenseManagementRepair(
    PDisplayParts** partsTable,
    short partsNumber,
    Bool isNoWarningGamen )
	: PServiceLicenseManagementCom( partsTable, partsNumber, isNoWarningGamen )
	,sc_ReapirByUSB( PNLD_RepairByUSB_NoSelect )
{
	memset(	uc_LicenseCode, '\0', sizeof( uc_LicenseCode ) );				// ライセンスコード.
	memset(	uc_RepairAcceptCode, '\0', sizeof( uc_RepairAcceptCode ) );	// 修復許可コード.
	uc_repairWaitTime = 0;	// 修復待ち時間.
// Comment 2015/07/20 HCLT-Surajit RQ-163[WP 1376]  Hide the USB Key.	
	m_bl_USBConnectionPermissionFlag = True;
}
//================================================================================================
//概要    :サービス・課金設定・ライセンス管理・修復画面 : 初期設定.
//================================================================================================
void PServiceLicenseManagementRepair::startGamen()
{
	PBasicMessageProc::startGamen();

	CheckAndExecInit();	// 初期化必要か否か取得して必要なら実行する.
	licenseManagementRetGamen = this;	// 戻り画面の設定.
	pc_functionManagementRetGamen = this;	//  戻り画面の設定.
	if( PNLD_LicenseManagement_PostProc == _uc_LicenseManagementState )	// 後処理状態の場合のみ完了状態に.
	{
		_uc_LicenseManagementState = PNLD_LicenseManagement_Complete;	// コールバック状態:完了状態.
	} else {
		_uc_LicenseManagementState = PNLD_LicenseManagement_Init;		// コールバック状態:初期状態.
	}
	sc_ReapirByUSB = PNLD_RepairByUSB_NoSelect;		// UBSでの修復/修復要求キー押下状態.
	uc_repairWaitTime = 0;	// 修復待ち時間.
// Comment 2015/07/20 HCLT-Surajit RQ-163[WP 1376]  Hide the USB Key.	
// Comment 2017/11/29 【HCLT-Vishal】【Eagle】【制御構成変更_No.4】 Removing old function version check condition.
	PNLC_USBConnectionPermission c_UsbPermission;
	PNLE_EnableUSBConnectionPermissionForAll e_usbAll = c_UsbPermission.getEnableUSBConnectionPermissionForAll();
	PNLE_EnableUSBConnectionPermissionForService e_usbforService = c_UsbPermission.getEnableUSBConnectionPermissionForService();
	if(( PNLE_EnableUSBConnectionPermissionForAll_Disable == e_usbAll ) || ( PNLE_EnableUSBConnectionPermissionForService_Disable == e_usbforService )) {
		m_bl_USBConnectionPermissionFlag = False;
	} else {
		m_bl_USBConnectionPermissionFlag = True;
	}
}
//================================================================================================
//概要    :サービス・課金設定・ライセンス管理・修復画面 : 変数などの初期化.
//================================================================================================
void PServiceLicenseManagementRepair::init_value()
{
	ss_select	= 0;	// 選択キー.
	_e_LcaTrgKind = TYPE_LcaTrgKind_Enovation;		// 修復.
	PNLC_TokenCodeSetting::getInstance()->clearTokenCode(); // トークンコードとトークンコード(ハイフン付)クリア.
	APIC_UsbMemDeviceInfo* pc_UsbMemDeviceInfo = APIC_UsbMemDeviceInfo::newInstance();
	if( 0 != pc_UsbMemDeviceInfo->getStatus() ) {
		ss_select = 1;
	}
	memset(	uc_LicenseCode, '\0', sizeof( uc_LicenseCode ) );				// ライセンスコード.
	memset(	uc_RepairAcceptCode, '\0', sizeof( uc_RepairAcceptCode ) );	// 修復許可コード.
	memset(	uc_FunctionCode, '\0', sizeof( uc_FunctionCode ) );				// 機能コード.
	// ライセンス管理ファイル(修復)の取得.
	_uc_LicenseManagementFileState[PNLD_LicenseManagementType_Repair] = PNLD_LicenseManagementFileState_Unacquisition;
	memset( _sc_LicenseManagementFileName,'\0',sizeof( _sc_LicenseManagementFileName[PNLD_LicenseManagementType_Repair] ) );
	APIF_SaaGetLicenseManagementFileName( SAAE_LicenseManagementModeRestoration, _sc_LicenseManagementFileName[PNLD_LicenseManagementType_Repair], ans_getLicenseManagementFileName );
}
//================================================================================================
//概要    :サービス・課金設定・ライセンス管理・修復画面 : 画面移動.
//================================================================================================
void PServiceLicenseManagementRepair::procGoToPage( uchar option )
{
	switch( option ) {
		case BTNID_GOTO_ServiceLicenseManagementRepairRequestCode:	// 修復要求コード.
			bl_NoAcceptBtnFlag = True;	// ボタン受付不可にする.
			PnlComGetEnabler()->req_startGetRepairRequestCode( ans_startGetRepairRequestCode );	// 修復要求コード生成取得要求.
			break;
		case BTNID_GOTO_ServiceLicenseManagementRepairAcceptCode:	nextGamen = &gp_ServiceLicenseManagementRepairAcceptCodeInput;	break;	// サービス・課金設定・ライセンス管理・修復許可コード入力画面.
		case BTNID_GOTO_ServiceLicenseManagementRepairLicenseCode:	nextGamen = &gp_ServiceLicenseManagementLicenseCodeInput;		break;	// サービス・課金設定・ライセンス管理・ライセンスコード入力画面.
		case BTNID_GOTO_ServiceLicenseManagementRepairFunctionCode:	nextGamen = &gp_ServiceLicenseManagementFunctionCodeEnableInput;	break;// サービス・課金設定・ライセンス管理・機能コード入力画面.
		default: break;
	}
}
//================================================================================================
//概要    :サービス・課金設定・ライセンス管理・修復画面 : ボタン（押された）.
//================================================================================================
void PServiceLicenseManagementRepair::procButtonOn( uchar option )
{
	uchar uc_localRepairRequestCode[PNLD_RepairRequestCodeMax + 1];	// 修復要求コード.
	memset( uc_localRepairRequestCode, '\0', sizeof( uc_localRepairRequestCode ) );	// 変数初期化.
	PnlComGetEnabler()->getRepairRequestCode( uc_localRepairRequestCode );	// 修復要求コード取得.
	switch( option ) {
		case BTNID_ServiceLicenseManagementEnablerFunctionOrLicenseCode:	// 機能/ライセンスコードキー.
			ss_select = 0;
			_uc_LicenseManagementState = PNLD_LicenseManagement_Init;	// コールバック状態:初期状態.
			break;
		case BTNID_ServiceLicenseManagementEnablerUsb:			// USBキー.
			ss_select = 1;
			_uc_LicenseManagementState = PNLD_LicenseManagement_Init;	// コールバック状態:初期状態.
			break;
		case BTNID_ServiceLicenseManagementEnablerTokenCode:	// LMSキー.
			ss_select = 2;
			_uc_LicenseManagementState = PNLD_LicenseManagement_Init;	// コールバック状態:初期状態.
			break;
		case BTNID_ServiceLicenseManagementFix:	// 確定キー.
			bl_NoAcceptBtnFlag = True;	// ボタン受付不可にする.
			if( 2 == ss_select ) {
				_uc_LicenseManagementState = PNLD_LicenseManagement_Wait;	// 修復中.
				PnlComGetEnablerSetting()->indTrg( _e_LcaTrgKind, PNLC_TokenCodeSetting::getInstance()->getLcaTokenCode() ); 	// LMS通信修復実行要求.
			} else {
				switch( sc_ReapirByUSB ) {
					case PNLD_RepairByUSB_NoSelect:		// 修復実行.
						nextGamen = &gp_ServiceLicenseManagementWait;	// サービス・課金設定・ライセンス管理・処理中画面.
						_uc_LicenseManagementState = PNLD_LicenseManagement_Wait;	// コールバック中.
						PnlComGetEnabler()->req_startRepair( uc_localRepairRequestCode,	// 修復要求コード.
						                                     uc_RepairAcceptCode,		// 修復許可コード.
						                                     uc_LicenseCode,			// ライセンスコード.
						                                     ans_startRepair, 			// コールバック.
						                                     uc_FunctionCode );			// 機能コード.
						break;
					case PNLD_RepairByUSB_RepairRequestCode:	// USBによる修復要求.
						_uc_LicenseManagementState = PNLD_LicenseManagement_Wait;	// コールバック中.
						PnlComGetEnabler()->req_CreateRepairCodeForUsb( ans_startGetRepairRequestCodeByUSB );
						break;
					case PNLD_RepairByUSB_Repair:				// USBによる修復実行.
						_uc_LicenseManagementState = PNLD_LicenseManagement_Wait;	// コールバック中.
						PnlComGetEnabler()->req_StartRepairForUsb( ( uchar* )_sc_LicenseManagementFileName[PNLD_LicenseManagementType_Repair],
						        ans_startRepairByUSB );
						break;
					default:break;
				}
			}
			break;
		case BTNID_ServiceLicenseManagementMenuRequestCodeByUSB:		// 修復要求キー.
			sc_ReapirByUSB = PNLD_RepairByUSB_RepairRequestCode;	// UBSでの修復要求キー押下状態.
			Rbt_ServiceLicenseManagementMenuRepairMode.select( sc_ReapirByUSB );	// 修復要求・実行切り替え.
			_uc_LicenseManagementState = PNLD_LicenseManagement_Init;	// コールバック状態初期化.
			break;
		case BTNID_ServiceLicenseManagementMenuRepairByUSB:			// 修復キー.
			sc_ReapirByUSB = PNLD_RepairByUSB_Repair;			// UBSでの修復キー押下状態.
			Rbt_ServiceLicenseManagementMenuRepairMode.select( sc_ReapirByUSB );	// 修復要求・実行切り替え.
			_uc_LicenseManagementState = PNLD_LicenseManagement_Init;	// コールバック状態初期化.
			break;
		default : break;
	}
	setupGamen();
}
//================================================================================================
// 概要		:サービス・課金設定・ライセンス管理・修復画面 : 結果表示.
//================================================================================================
void PServiceLicenseManagementRepair::licenseManagementResultDisp()
{
	TEXT_ID ps_ResultMsg = s_MSGServiceMainPowerOffOnMes;	// 結果メッセージ.
	Bool bl_display = False;								// 結果欄への表示判断.
	TYPE_EnablerResult e_Result = TYPE_EnablerResult_OK;	// 修復要求or修復実行結果.
	Bool bl_slash = False;	// 処理中の表示判断.
	Bool bl_DisplayError = False;	// エラーコード表示判断.

	// 修復要求 or 修復実行 の確定.
	if( sc_ReapirByUSB == PNLD_RepairByUSB_RepairRequestCode ) {
		e_Result = _e_startGetRepairRequestCodeResult;
	} else if( sc_ReapirByUSB == PNLD_RepairByUSB_Repair ) {
		e_Result = _e_startRepairResult;
	} else {
		// 未選択時(UBSでの修復でない).
		e_Result = _e_startRepairResult;
	}

	switch( _uc_LicenseManagementState ) {
		case PNLD_LicenseManagement_Init:	// 初期状態.
		case PNLD_LicenseManagement_PostProc:	// 後処理状態.
			break;
		case PNLD_LicenseManagement_Wait:	// 待ち状態.
		case PNLD_LicenseManagement_Timer:	// タイマー待ち状態.
			if( 1 == ss_select ) {						// USB選択時.
				ps_ResultMsg = s_ITMServiceOperating;	// 実行中.
			} else {									// USB以外選択時.
				ps_ResultMsg = s_MSGServicePleaseWaitRestartAfterCompletion;	// お待ちください完了後再起動します.
			}
			bl_display = True;
			bl_slash = True;
			break;
		case PNLD_LicenseManagement_Complete:	// 完了状態.
			if( 2 == ss_select ) {
				ps_ResultMsg = s_MSGServicePleaseWaitRestartAfterCompletion;	// お待ちください完了後再起動します.
			} else {								// LMS以外の時.
				if( TYPE_EnablerResult_OK == e_Result ) {	// 結果：OK.
					if( 1 == ss_select ) {					// USBの時.
						ps_ResultMsg = s_ServiceResultOK;	// Ok.
					} else {
						ps_ResultMsg = s_MSGServicePleaseWaitRestartAfterCompletion;	// お待ちください完了後再起動します.
					}
				} else if( TYPE_EnablerResult_ParamError == e_Result ) {	// 結果：パラメータエラー.
					ps_ResultMsg = s_MSGServiceSettingErrorMes;		// 設定が正しくありません.
				} else {	// 結果：OK、パラメータエラー以外.
					ps_ResultMsg = s_MSGServiceSettingErrorMes2;	// 確定できませんでした.
				}
			}
			bl_display = True;
			break;
		case PNLD_LicenseManagement_Error:	// エラー状態.
			ps_ResultMsg = s_MSGServiceErrorCode;	// エラーコード : .
			bl_display = True;
			bl_DisplayError = True;					// エラーコード表示判断.
			break;
		default:									// 不正な状態.
			PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "PServiceLicenseManagementRepair::licenseManagementResultDisp", UC_PNL_ERROR_IMPOSSIBLE );
			break;
	}
	Txt_ServiceLicenseManagementRepairScreenSlash.showEnable( bl_slash );	// 処理中の表示.
	if( True == bl_slash ) { showExecuting(); }	// 処理中の表示.

	if( True == bl_DisplayError ) {
		Tfd_ServiceLicenseManagementRepairErrorCode.changeExternalText( ( uchar* )PNLC_TokenCodeSetting::getInstance()->getErrorCode() );	// エラーコード.
		Tfd_ServiceLicenseManagementRepairErrorCode.showEnable( True );	// エラーコード.
	} else {
		Tfd_ServiceLicenseManagementRepairErrorCode.showEnable( False );	// エラーコード.
	}
	Grp_ServiceLicenseManagementFix.showEnable( bl_display );		// 結果表示.
	if( True == bl_display ) { Txt_ServiceLicenseManagementFixMsg.changeText( ps_ResultMsg ); }	// 表示内容設定.
}
//================================================================================================
//概要    :サービス・課金設定・ライセンス管理・修復画面 : 表示部品のセットアップ..
//================================================================================================
void PServiceLicenseManagementRepair::setupGamen( short option )
{
	Rbt_ServiceLicenseManagementMenu.select( 2 );	// ライセンス管理・左側メニューローテンションボタン.
	Key_ServiceLicenseManagementEnablerFunctionOrLicenseCode.changeText( s_KEYServiceRestoreRequest );	// 修復/修復要求.
	// 修復許可コード表示.
	uchar uc_LocalRepairAcceptCodeAddHyphen[ PNLD_RepairAcceptCode + 7 + 1 ];	// 修復許可コード+ハイフン.
	memset( uc_LocalRepairAcceptCodeAddHyphen, '\0',sizeof( uc_LocalRepairAcceptCodeAddHyphen ) );	// 変数の初期化.
	addHyphen( uc_RepairAcceptCode, uc_LocalRepairAcceptCodeAddHyphen );	// コードに5文字毎「-」を代入.
	Btx_ServiceLicenseManagementRepairAcceptCode.changeExternalText( uc_LocalRepairAcceptCodeAddHyphen, sizeof( uc_LocalRepairAcceptCodeAddHyphen ) );	// 修復許可コード表示エリア.
	// ライセンスコード表示.
	uchar uc_LocalLicenseCodeAddHyphen[ PNLD_LicenseCodeMax + 6 + 1 ];	// ライセンスコード+ハイフン.
	memset( uc_LocalLicenseCodeAddHyphen, '\0',sizeof( uc_LocalLicenseCodeAddHyphen ) );	// 変数の初期化.
	addHyphen( uc_LicenseCode, uc_LocalLicenseCodeAddHyphen );	// コードに5文字毎「-」を代入.
	Btx_ServiceLicenseManagementRepairLicenseCode.changeExternalText( uc_LocalLicenseCodeAddHyphen, sizeof( uc_LocalLicenseCodeAddHyphen ) );	// ライセンスコード表示エリア.
	//機能コード表示.
	Btx_ServiceLicenseManagementRepairFunctionCode.changeExternalText( uc_FunctionCode, sizeof( uc_FunctionCode ) );	// 機能コード表示エリア.

	// USBでの修復.
	APIC_UsbMemDeviceInfo* pc_UsbMemDeviceInfo = APIC_UsbMemDeviceInfo::newInstance();
	Bool bl_UsbKeyShow = False;
	Bool bl_RepairByUsbShow = False;
	if( 0 != pc_UsbMemDeviceInfo->getStatus() ) {
		bl_UsbKeyShow = True;	// USBでの修復キー表示.
		if( PNLD_LicenseManagementFileState_Acquired == _uc_LicenseManagementFileState[PNLD_LicenseManagementType_Repair] ) {
			Key_ServiceLicenseManagementMenuRepairByUSB.select( sc_ReapirByUSB );	// USBでの修復/修復要求キー押下状態.
			bl_RepairByUsbShow = True;
		} else {
			bl_RepairByUsbShow = False;
		}
	} else {
		bl_UsbKeyShow = False;	// USBでの修復キー非表示.
	}
// Comment 2015/07/20 HCLT-Surajit RQ-163[WP 1376]  Hide the USB Key to avoid flicker issue.	
//	Key_ServiceLicenseManagementEnablerUsb.showEnable( bl_UsbKeyShow );	// USBでの有効化キー表示/非表示.
	if( False == bl_UsbKeyShow && 1 == ss_select ) {	// 途中でUSBが引き抜かれたときの対応.
		ss_select = 0;
		_uc_LicenseManagementState = PNLD_LicenseManagement_Init;	// オブザーバー状態:初期状態.
	}

	Rbt_ServiceLicenseManagementMenuEnablerMode.select( ss_select );	// 修復許可コード・USB切り替え.
	Key_ServiceLicenseManagementEnablerTokenCode.changeText( s_NOTKEYLMS );	// LMS.
	if( 0 == ss_select ) {
		// 機能/ライセンスコード選択時の表示/非表示.
		Key_ServiceLicenseManagementMenuRepairRequestCodeByUSB.showEnable( False );	// 修復要求キー.
		Key_ServiceLicenseManagementMenuRepairByUSB.showEnable( False );			// 修復実行キー.
		Key_ServiceLicenseManagementRepairRequestCode.showEnable( True );			// 修復要求コードキー.
		Key_ServiceLicenseManagementRepairAcceptCode.showEnable( True );			// 修復許可コードキー.
		Btx_ServiceLicenseManagementRepairAcceptCode.showEnable( True );			// 修復許可コード表示エリア.
		Key_ServiceLicenseManagementRepairFunctionCode.showEnable( True );	// 機能コードキー.
		Btx_ServiceLicenseManagementRepairFunctionCode.showEnable( True );	// 機能コード表示エリア.
		Key_ServiceLicenseManagementRepairLicenseCode.showEnable( True );	// ライセンスコードキー.
		Btx_ServiceLicenseManagementRepairLicenseCode.showEnable( True );	// ライセンスコード表示エリア.
	} else if( 1 == ss_select ) {
		// USB選択時の表示/非表示.
		Key_ServiceLicenseManagementRepairRequestCode.showEnable( False );			// 修復要求コードキー.
		Key_ServiceLicenseManagementRepairAcceptCode.showEnable( False );			// 修復許可コードキー.
		Btx_ServiceLicenseManagementRepairAcceptCode.showEnable( False );			// 修復許可コード表示エリア.
		Key_ServiceLicenseManagementRepairFunctionCode.showEnable( False );	// 機能コードキー.
		Btx_ServiceLicenseManagementRepairFunctionCode.showEnable( False );	// 機能コード表示エリア.
		Key_ServiceLicenseManagementRepairLicenseCode.showEnable( False );	// ライセンスコードキー.
		Btx_ServiceLicenseManagementRepairLicenseCode.showEnable( False );	// ライセンスコード表示エリア.
		Key_ServiceLicenseManagementMenuRepairRequestCodeByUSB.showEnable( True );	// 修復要求キー.
		Key_ServiceLicenseManagementMenuRepairByUSB.showEnable( bl_RepairByUsbShow );		// USBでの修復キー表示.
	} else if( 2 == ss_select ) {
		// LMS選択時の表示/非表示.
		Key_ServiceLicenseManagementMenuRepairRequestCodeByUSB.showEnable( False );	// 修復要求キー.
		Key_ServiceLicenseManagementMenuRepairByUSB.showEnable( False );			// 修復実行キー.
		Key_ServiceLicenseManagementRepairRequestCode.showEnable( False );			// 修復要求コードキー.
		Key_ServiceLicenseManagementRepairAcceptCode.showEnable( False );			// 修復許可コードキー.
		Btx_ServiceLicenseManagementRepairAcceptCode.showEnable( False );			// 修復許可コード表示エリア.
		Key_ServiceLicenseManagementRepairFunctionCode.showEnable( False );	// 機能コードキー.
		Btx_ServiceLicenseManagementRepairFunctionCode.showEnable( False );	// 機能コード表示エリア.
		Key_ServiceLicenseManagementRepairLicenseCode.showEnable( False );	// ライセンスコードキー.
		Btx_ServiceLicenseManagementRepairLicenseCode.showEnable( False );	// ライセンスコード表示エリア.
	}
	licenseManagementResultDisp();	// 結果表示.

	PServiceLicenseManagementCom::setupGamen( option );	// 親クラスの処理を呼ぶ.
// Comment 2015/07/20 HCLT-Surajit RQ-163[WP 1376]  Hide the USB Key.	
// Comment 2017/11/29 【HCLT-Vishal】【Eagle】【制御構成変更_No.4】 Removing old function version check and else portion.
	if( False == m_bl_USBConnectionPermissionFlag ){ 							//USB接続許可設定の[一括設定]または[外部メモリー(サービス)]が[禁止]の場合.
    	Key_ServiceLicenseManagementEnablerUsb.showEnable(False);				//USBでの有効化キー表示/非表示.
	} else {
// Comment 2015/07/20 HCLT-Surajit RQ-163[WP 1376] [ UTCT Fix]  Hide the USB key .
//		Key_ServiceLicenseManagementEnablerUsb.showEnable(True);				// USBでの有効化キー表示.
		Key_ServiceLicenseManagementEnablerUsb.showEnable(bl_UsbKeyShow);		//USBでの有効化キー表示.
	}
}
//================================================================================================
//概要    :サービス・課金設定・ライセンス管理・修復画面 : 修復中表示処理.
//================================================================================================
void PServiceLicenseManagementRepair::showExecuting()
{
	static	Bool	b_ExecutingAnimeSts = False;	// 処理中であることを示す表示を行うためのフラグ.
	TEXT_ID			executingTextId;

	if( True == b_ExecutingAnimeSts ) {
		executingTextId = s_EXPSlash;
		b_ExecutingAnimeSts = False;
	} else {
		executingTextId = s_EXPBackslash;
		b_ExecutingAnimeSts = True;
	}
	Txt_ServiceLicenseManagementRepairScreenSlash.changeText( executingTextId );
}
//================================================================================================
//概要    :サービス・課金設定・ライセンス管理・修復画面 : 1秒タイマ.
//================================================================================================
void PServiceLicenseManagementRepair::procSecond( uchar option )
{
	PServiceLicenseManagementCom::procSecond( option );

	if( PNLD_LicenseManagement_Timer == _uc_LicenseManagementState ) {
		++uc_repairWaitTime;										// 秒数をカウント.
		if( PNLD_LicenseManagement_TimerWait <= uc_repairWaitTime ) {
			if( PNLD_RepairByUSB_RepairRequestCode == sc_ReapirByUSB ) {
				// 修復要求.
				CallBackIndi( TYPE_PNL_CallBack_LicenseManagement_GetRepairRequestCodeByUSB );	// コールバックイベント発生.
			} else if( PNLD_RepairByUSB_Repair == sc_ReapirByUSB ) {
				// 修復.
				CallBackIndi( TYPE_PNL_CallBack_LicenseManagement_RepairByUSB );				// コールバックイベント発生.
			}
			uc_repairWaitTime = 0;
		}
	}
}

