//================================================================================================
PServiceLicenseManagementCodeInputCom::PServiceLicenseManagementCodeInputCom(
    PDisplayParts** partsTable,
    short partsNumber,
    Bool isNoWarningGamen )
	: PServiceLicenseManagementCom( partsTable, partsNumber, isNoWarningGamen )
{
	sc_CodeLenType = PNLD_CodeLenType6Block;	// コード長タイプ.
	ss_CodeInputPosition = 0;	// 入力エリア.
	memset( sc_Code, '\0', sizeof( sc_Code ) );	// コード入力値.
	memset( bl_FixedCode, '\0', sizeof( bl_FixedCode ) );	// 確定フラグ.
	memset( bl_DirectCode, '\0', sizeof( bl_DirectCode ) );	// ダイレクト入力.
}
//================================================================================================
//概要    :サービス・課金設定・ライセンス管理・コード入力共通 : コード長取得.
//================================================================================================
uchar PServiceLicenseManagementCodeInputCom::getCodeLenNum() {
	uchar uc_CodeLen = PNLD_6BlockCodeLenMax;	// コード長.
	if( PNLD_CodeLenType6Block == sc_CodeLenType ) {	// 6ブロックコードの場合.
		uc_CodeLen = PNLD_6BlockCodeLenMax;	// コード長：30.
	} else {	// 7ブロックコードの場合.
		uc_CodeLen = PNLD_7BlockCodeLenMax;	// コード長：35.
	}
	return( uc_CodeLen );	// コード長を返す.
}
//================================================================================================
//概要    :サービス・課金設定・ライセンス管理・コード入力共通 : コードブロック数取得.
//================================================================================================
uchar PServiceLicenseManagementCodeInputCom::getCodeBlockNum() {
	uchar uc_CodeBlock = PNLD_6BlockCode;	// コードブロック数.
	if( PNLD_CodeLenType6Block == sc_CodeLenType ) {	// 6ブロックコードの場合.
		uc_CodeBlock = PNLD_6BlockCode;	// ブロック数:6.
	} else {	// 7ブロックコードの場合.
		uc_CodeBlock = PNLD_7BlockCode;	// ブロック数:7.
	}
	return( uc_CodeBlock );	// コードブロック数.
}
//================================================================================================
//概要    :サービス・課金設定・ライセンス管理・コード入力共通 : テンキー.
//================================================================================================
uchar PServiceLicenseManagementCodeInputCom::NowInputCodeState( char sc_InputCode[][PNLD_CodeBlockLenMax + 1] )
{
	Bool uc_Result = False;	// 結果:NG.
	char sc_TempCode[PNLD_CodeLenMax + 1] = {0};	// コード.
	memset( sc_TempCode, '\0', sizeof( sc_TempCode ) );
	uchar uc_StrLen = 0;	// コード長.
	snprintf( sc_TempCode, sizeof( sc_TempCode ), "%s%s%s%s%s%s%s", sc_InputCode[0],sc_InputCode[1],sc_InputCode[2],sc_InputCode[3],sc_InputCode[4],sc_InputCode[5],sc_InputCode[6] );	// コード生成.
	uc_StrLen = ( uchar )strlen( sc_TempCode );	// コード長取得.
	if( getCodeLenNum() == uc_StrLen ) {	// コード長チェック.
		uc_Result = True;	// 結果:OK.
	}
	return( uc_Result );
}
//================================================================================================
//概要    :サービス・課金設定・ライセンス管理・コード入力共通 : テンキー.
//================================================================================================
void PServiceLicenseManagementCodeInputCom::proc10Key( uchar option )
{
	if( option > 1 ) {	// 0、1の時は受け付けない.
		char _sc_CharAddress[2];
		memset( _sc_CharAddress, '\0', sizeof( _sc_CharAddress ) );
		snprintf( _sc_CharAddress, sizeof(_sc_CharAddress), "%d", option );	// 10キー入力された数値を文字に変換.
		if( True == bl_DirectCode[ ss_CodeInputPosition ] ) {	// ダイレクト入力がTrueの場合、エリア内の値をクリアしてから入力.
			memset( sc_Code[ ss_CodeInputPosition ], '\0', sizeof( sc_Code[ ss_CodeInputPosition ] ) );
		}
		uchar uc_StringLen = static_cast<uchar>( strlen( sc_Code[ ss_CodeInputPosition ] ) );	// 現在エリア内にどれだけ文字列が入力されているか？.
		if( uc_StringLen < PNLD_CodeBlockLenMax ) {	// エリア内の文字が5文字に達している場合は受付けない.
			sc_Code[ ss_CodeInputPosition ][uc_StringLen] = _sc_CharAddress[0];	// 現在の文字列の末尾に文字を追加する.
			bl_DirectCode[ ss_CodeInputPosition ] = False;	// ダイレクト入力解除.
			bl_FixedCode[ ss_CodeInputPosition ] = True;	// 表示を確定表示.
		} else {
			setBuzzerType( PCGE_BuzzerType_InputNg );
		}
		if( uc_StringLen+1 > PNLD_CodeBlockLenMax-1 ) {	// エリア内の文字が5文字の場合は、入力エリアを1つずらしておく.
			if( ss_CodeInputPosition < getCodeBlockNum()-1 ) {	// 最右端の場合はずらさない.
				bl_DirectCode[ss_CodeInputPosition] = True;		// ダイレクト入力.
				bl_FixedCode[ ss_CodeInputPosition] = True;		// 確定フラグON.
				ss_CodeInputPosition++;
				bl_FixedCode[ ss_CodeInputPosition] = False;	// 確定フラグOFF.
			}
		}
		setupGamen();
	} else {
		setBuzzerType( PCGE_BuzzerType_InputNg );	// 報知音設定.
	}
}
//================================================================================================
//概要    :サービス・課金設定・ライセンス管理・コード入力共通 : クリアー.
//================================================================================================
void PServiceLicenseManagementCodeInputCom::procClear( uchar option )
{
	memset(	sc_Code, '\0', sizeof( sc_Code ) );	// 入力値を初期化.
	for( uchar i = 0; i < getCodeBlockNum(); i++ ) {
		bl_DirectCode[ ss_CodeInputPosition ] = True;	// ダイレクト入力ON.
		bl_FixedCode[ ss_CodeInputPosition ] = False;	// 未確定.
	}
	ss_CodeInputPosition = 0;	// 入力位置を初期化.
	setupGamen();
}
//================================================================================================
//概要    :サービス・課金設定・ライセンス管理・コード入力共通 : キーボード入力.
//================================================================================================
void PServiceLicenseManagementCodeInputCom::procKeyBoard( uchar option )
{
	char _sc_keyCode[3];	// キーコード.
	memset( _sc_keyCode, '\0', sizeof( _sc_keyCode ) );	// キーコード初期化.
	// キーコードを取得.
	Kbd_ServiceInputKeybord.getKeyString( option, _sc_keyCode );
	uchar uc_StringLen = 0;	// 文字列の長さを測る用.
	uchar i = 0 ;	// 初期化用.
	switch( _sc_keyCode[0] ) {	// キーコード.
		case PLBD_ArrowLeftKeyCode:			// ←キー押下：カーソル位置を左に移動.
			if( ss_CodeInputPosition > 0 ) {
				bl_DirectCode[ss_CodeInputPosition] = True;		// ダイレクト入力.
				bl_FixedCode[ ss_CodeInputPosition] = True;		// 確定フラグON.
				ss_CodeInputPosition--;
				bl_FixedCode[ ss_CodeInputPosition] = False;	// 確定フラグOFF.
			} else {
				setBuzzerType( PCGE_BuzzerType_InputNg );
			}
			break;
		case PLBD_ArrowRighKeyCode:			// →キー押下：カーソル位置を右に移動.
			if( ss_CodeInputPosition < getCodeBlockNum()-1 ) {
				bl_DirectCode[ss_CodeInputPosition] = True;		// ダイレクト入力.
				bl_FixedCode[ ss_CodeInputPosition] = True;		// 確定フラグON.
				ss_CodeInputPosition++;
				bl_FixedCode[ ss_CodeInputPosition] = False;	// 確定フラグOFF.
			} else {
				setBuzzerType( PCGE_BuzzerType_InputNg );
			}
			break;
		case PLBD_DeleteKeyCode:			// Delキー押下.
			for( i = 0; i < PNLD_CodeBlockLenMax; i++ ) {
				sc_Code[ss_CodeInputPosition][i] = 0;		// 入力値.
			}
			bl_DirectCode[ ss_CodeInputPosition ] = True;		// ダイレクト入力ON
			bl_FixedCode[  ss_CodeInputPosition ] = False;		// 未確定
			break;
		default:							// その他のキー押下：入力文字列表示.
			if( True == bl_DirectCode[ ss_CodeInputPosition ] ) {	// ダイレクト入力がTrueの場合、エリア内の値をクリアしてから入力.
				memset( sc_Code[ ss_CodeInputPosition ], 0, sizeof( sc_Code[ ss_CodeInputPosition ] ) );
			}
			uc_StringLen = ( uchar )strlen( sc_Code[ ss_CodeInputPosition ] );	// 現在エリア内にどれだけ文字列が入力されているか？
			if( uc_StringLen < PNLD_CodeBlockLenMax ) {	// エリア内の文字が5文字に達している場合は受付けない.
				sc_Code[ ss_CodeInputPosition ][uc_StringLen] = _sc_keyCode[0];
				bl_DirectCode[ ss_CodeInputPosition ] = False;	// ダイレクト入力解除.
			}
			if( uc_StringLen+1 > PNLD_CodeBlockLenMax-1 ) {	// エリア内の文字が5文字の場合は、入力エリアを1つずらしておく.
				if( ss_CodeInputPosition < getCodeBlockNum()-1 ) {	// 最右端の場合はずらさない.
					bl_DirectCode[ss_CodeInputPosition] = True;		// ダイレクト入力.
					bl_FixedCode[ ss_CodeInputPosition] = True;		// 確定フラグON.
					ss_CodeInputPosition++;
					bl_FixedCode[ ss_CodeInputPosition] = False;	// 確定フラグOFF.
				}
			}
			break;
	}
	setupGamen();
}
//================================================================================================
//概要    :サービス・課金設定・ライセンス管理・コード入力共通 : 初期設定.
//================================================================================================
void PServiceLicenseManagementCodeInputCom::startGamen()
{
	PBasicMessageProc::startGamen();

	// キーボード表示.
	Kbd_ServiceInputKeybord.setChangeEnlKeybord( PLBD_Enl_KBD_Initial );
	Kbd_ServiceInputKeybord = PLBC_ConvertKeybord( PLBD_KBT_Alphabet_L, 88, 124, True, True ); // キーボード種類、配置位置設定.
	Kbd_ServiceInputKeybord.GetCursor( NULL );	// カーソルクラスへパーツポインタを渡す.
	startGamenKeybordServiceA();
	Kbd_ServiceInputKeybord.setKeybordType( PLBD_KBT_Alphabet_L );	// 確定したキーボードに切り替える.
	// コード入力変数初期化.
	ss_CodeInputPosition = 0;	// 入力エリア.
	memset(	sc_Code, '\0', sizeof( sc_Code ) );	// コード入力値.
	for( register short j = 0 ; j < getCodeBlockNum(); j++ ) {
		bl_FixedCode[j] = True;		// コード確定フラグ.
		bl_DirectCode[j] = True;	// コードダイレクト入力.
	}
	bl_FixedCode[0] = False;		// コード確定フラグOFF.


}
//================================================================================================
//概要    :サービス・課金設定・ライセンス管理・コード入力共通 : 表示部品のセットアップ.
//================================================================================================
void PServiceLicenseManagementCodeInputCom::setupGamen( short option )
{
	PServiceLicenseManagementCom::setupGamen( option );	// 親クラスの処理を呼ぶ.
	// キーボード表示.
	Kbd_ServiceInputKeybord.showKeybord();
	// 入力できないキーを非表示にする.
	Tfd_Keybord[0].showEnable( False );	Kty_Keybord[0].showEnable( False );	// 「1」.
	Tfd_Keybord[9].showEnable( False );	Kty_Keybord[9].showEnable( False );	// 「0」.
	Tfd_Keybord[20].showEnable( False );	Kty_Keybord[20].showEnable( False );	// 「I」.
	Tfd_Keybord[21].showEnable( False );	Kty_Keybord[21].showEnable( False );	// 「O」.
	// コード表示エリアにてコード長により必要無いパーツを非表示.
	if( PNLD_CodeLenType6Block == sc_CodeLenType ) {	// 5×6ブロックの場合.
		Btx_ServiceLicenseManagementCode.showEnableAdd( &Txt_LicenseManagementCodeInputHyphen6, False );	// 5×7ブロック用ハイフン非表示.
		Btx_ServiceLicenseManagementCode.showEnableAdd( &Tfd_LicenseManagementCursorCode[6], False );		// 入力で扱うアドレス値7ブロック目を非表示.
		Btx_ServiceLicenseManagementCode.showEnableAdd( &Gra_LicenseManagementCursorCode[6], False );		// カーソル7ブロック目を非表示.
	} else {	// 5×6ブロック以外の場合.
		Btx_ServiceLicenseManagementCode.showEnableAdd( &Txt_LicenseManagementCodeInputHyphen5, False );	// 5×6ブロック用ハイフン非表示.
	}
	// コード表示.
	for( register short i = 0 ; i < getCodeBlockNum(); i++ ) {	// コードを順に表示&カーソル表示する.
		Btx_ServiceLicenseManagementCode.changeExternalText( &Tfd_LicenseManagementCursorCode[i], ( uchar* )sc_Code[i], sizeof( sc_Code[i] ) );		// 入力で扱うアドレス値を表示.
		Btx_ServiceLicenseManagementCode.showEnableAdd( &Gra_LicenseManagementCursorCode[i], ( i == ss_CodeInputPosition ? True : False ) );	// カーソルの表示（入力選択位置）（左から０～６）.
	}
}
// -----------------------------------------------------------------------------------------------
// クラス	：PServiceLicenseManagementCodeInputCom.
// 関数名	：procRMPStrInput.
// 引数		：uchar option.
// 戻り値	：なし.
// 備考		：.
// 作成者	：OPS1 棚.
// -----------------------------------------------------------------------------------------------
void PServiceLicenseManagementCodeInputCom::procRMPStrInput( uchar option )
{
	ushort us_CodeLenNum = ( ushort )getCodeLenNum();					// (ハイフンを無視した)最大文字列長.
	uchar  uc_CodeBlockNum = getCodeBlockNum();						// ブロック数.
	uchar  uc_BlockLen = ( uchar )us_CodeLenNum / uc_CodeBlockNum;	// ブロック内の文字数.

	PNLC_RMPStrInputMng::newInstance()->setStringToSeparateBuffer( ( char* )sc_Code, us_CodeLenNum, uc_CodeBlockNum, uc_BlockLen );
	setupGamen();
}

