//================================================================================================
//概要    :サービス・課金設定・ライセンス管理・ライセンスコード入力画面 : 初期設定.
//================================================================================================
void PServiceLicenseManagementLicenseCodeInput::startGamen()
{
	PServiceLicenseManagementCodeInputCom::startGamen();	// 親クラスの処理を呼ぶ.
	sc_CodeLenType = PNLD_CodeLenType6Block;	// コード長:30.
	uchar uc_CodeBlock = 0;	// コードブロック数.
	for( uc_CodeBlock = 0; uc_CodeBlock < getCodeBlockNum(); uc_CodeBlock++ ) {
		strncpy( sc_Code[uc_CodeBlock],
		         ( char* )( gp_ServiceLicenseManagementEnabler.uc_LicenseCode+( ( sizeof( sc_Code[uc_CodeBlock] )-1 )*uc_CodeBlock ) ),
		         sizeof( sc_Code[uc_CodeBlock] )-1 );	// ライセンスコード設定.
	}
}
//================================================================================================
//概要    :サービス・課金設定・ライセンス管理・ライセンスコード入力画面 : 画面移動.
//================================================================================================
void PServiceLicenseManagementLicenseCodeInput::procGoToPage( uchar option )
{
	switch( option ) {
		case 60:   // キャンセルキー.
			nextGamen = licenseManagementRetGamen;	// 戻り画面.
			licenseManagementRetGamen = NULL;	// 戻り画面初期化.
			break;
		default: break;
	}
}
//================================================================================================
//概要    :サービス・課金設定・ライセンス管理・ライセンスコード入力画面 : OKキー（押された）.
//================================================================================================
void PServiceLicenseManagementLicenseCodeInput::procOk( uchar option )
{
	if( True == NowInputCodeState( sc_Code ) ) {	// 条件を満たしている場合、遷移.
		sprintf( ( char* )gp_ServiceLicenseManagementEnabler.uc_LicenseCode, "%5s%5s%5s%5s%5s%5s", sc_Code[0],sc_Code[1],sc_Code[2],sc_Code[3],sc_Code[4],sc_Code[5] );	// 有効化画面へ設定値を渡す.
		sprintf( ( char* )gp_ServiceLicenseManagementRepair.uc_LicenseCode, "%5s%5s%5s%5s%5s%5s", sc_Code[0],sc_Code[1],sc_Code[2],sc_Code[3],sc_Code[4],sc_Code[5] );		// 修復画面へ設定値を渡す.
		nextGamen = licenseManagementRetGamen;	// 戻り画面.
		licenseManagementRetGamen = NULL;		// 戻り画面初期化.
	} else {	// 条件を満たしていないので、報知音を鳴らして、遷移しない.
		setBuzzerType( PCGE_BuzzerType_InputNg );	// 報知音設定.
	}
}
