//概要    :サービス・課金設定・ライセンス管理・トークンコード入力画面 : コード入力ＯＫかどうか判断.
//================================================================================================.
uchar PServiceLicenseManagementTokenCodeEnableInput::NowInputCodeState( char sc_InputCode[][PNLD_TokenCodeBlockLenMax + 1] )
{
	Bool uc_Result = False;	// 結果:NG.
	char sc_TempCode[PNLD_TokenCodeLenMax + 1] = {0};	// コード.
	memset( sc_TempCode, '\0', sizeof( sc_TempCode ) );
	uchar uc_StrLen = 0;	// コード長.
	snprintf( sc_TempCode, sizeof( sc_TempCode ), "%s%s%s%s%s", sc_InputCode[0],sc_InputCode[1],sc_InputCode[2],sc_InputCode[3],sc_InputCode[4] );	// コード生成.
	uc_StrLen = ( uchar )strlen( sc_TempCode );	// コード長取得.
	if( PNLD_TokenCodeLenMax == uc_StrLen || 0 == uc_StrLen ) {	// コード長チェック.
		uc_Result = True;	// 結果:OK.
	}
	return( uc_Result );
}
//================================================================================================.
//概要    :サービス・課金設定・ライセンス管理・トークンコード入力画面 : 初期設定.
//================================================================================================.
void PServiceLicenseManagementTokenCodeEnableInput::startGamen()
{
	PBasicMessageProc::startGamen();

	// キーボード表示.
	Kbd_ServiceInputKeybord.setChangeEnlKeybord( PLBD_Enl_KBD_Initial );
	Kbd_ServiceInputKeybord = PLBC_ConvertKeybord( PLBD_KBT_Alphabet_L, 88, 124, True, True ); // キーボード種類、配置位置設定.
	Kbd_ServiceInputKeybord.GetCursor( NULL );	// カーソルクラスへパーツポインタを渡す.
	startGamenKeybordServiceA();				// アルファベットキーボード.
	Kbd_ServiceInputKeybord.setKeybordType( PLBD_KBT_Alphabet_L );	// 確定したキーボードに切り替える.
	// コード入力変数初期化.
	ss_CodeInputPosition = 0;	// 入力エリア.
	memset(	sc_Code, '\0', sizeof( sc_Code ) );	// コード入力値.
	for( register short j = 0 ; j < PNLD_TokenCodeBlockNumMax; j++ ) {
		bl_DirectCode[j] = True;	// コードダイレクト入力.
	}

	// すでに入力されているトークンコードをセットする.
	for( uchar uc_CodeBlock = 0; uc_CodeBlock < PNLD_TokenCodeBlockNumMax; uc_CodeBlock++ ) {
		strncpy( sc_Code[uc_CodeBlock],
		         ( char* )( PNLC_TokenCodeSetting::getInstance()->getTokenCode() + ( PNLD_TokenCodeBlockLenMax * uc_CodeBlock ) ),
		         PNLD_TokenCodeBlockLenMax );	// トークンコード設定.
	}
}
//================================================================================================.
//概要    :サービス・課金設定・ライセンス管理・トークンコード入力画面 : 表示部品のセットアップ.
//================================================================================================.
void PServiceLicenseManagementTokenCodeEnableInput::setupGamen( short option )
{
	PServiceLicenseManagementCom::setupGamen( option );	// 親クラスの処理を呼ぶ.
	// キーボード表示.
	Kbd_ServiceInputKeybord.showKeybord();
	// 入力できないキーを非表示にする.
	Tfd_Keybord[0].showEnable( False );	Kty_Keybord[0].showEnable( False );	// 「1」.
	Tfd_Keybord[9].showEnable( False );	Kty_Keybord[9].showEnable( False );	// 「0」.
	Tfd_Keybord[20].showEnable( False );	Kty_Keybord[20].showEnable( False );	// 「I」.
	Tfd_Keybord[21].showEnable( False );	Kty_Keybord[21].showEnable( False );	// 「O」.

	// 選択されているトークンコードの番号を取得して、タイトルを変更する.
	switch( PNLC_TokenCodeSetting::getInstance()->getSelectTokenCodeNum() ) {
		case 0:
			Txt_TitleServiceLicenseManagementTokenCode.changeText( s_KEYServiceTokenCode1 );
			break;
		case 1:
			Txt_TitleServiceLicenseManagementTokenCode.changeText( s_KEYServiceTokenCode2 );
			break;
		case 2:
			Txt_TitleServiceLicenseManagementTokenCode.changeText( s_KEYServiceTokenCode3 );
			break;
		case 3:
			Txt_TitleServiceLicenseManagementTokenCode.changeText( s_KEYServiceTokenCode4 );
			break;
		case 4:
			Txt_TitleServiceLicenseManagementTokenCode.changeText( s_KEYServiceTokenCode5 );
			break;
		case 5:
			Txt_TitleServiceLicenseManagementTokenCode.changeText( s_KEYServiceTokenCode6 );
			break;
		case 6:
			Txt_TitleServiceLicenseManagementTokenCode.changeText( s_KEYServiceTokenCode7 );
			break;
		case 7:
			Txt_TitleServiceLicenseManagementTokenCode.changeText( s_KEYServiceTokenCode8 );
			break;
		case 8:
			Txt_TitleServiceLicenseManagementTokenCode.changeText( s_KEYServiceTokenCode9 );
			break;
		case 9:
			Txt_TitleServiceLicenseManagementTokenCode.changeText( s_KEYServiceTokenCode10 );
			break;
	}

	// コード表示.
	for( register short i = 0 ; i < PNLD_TokenCodeBlockNumMax; i++ ) {	// コードを順に表示&カーソル表示する.
		Btx_ServiceLicenseManagementTokenCode.changeExternalText( &Tfd_LicenseManagementCursorTokenCode[i], ( uchar* )sc_Code[i], sizeof( sc_Code[i] ) );	// 入力で扱うアドレス値を表示.
		Btx_ServiceLicenseManagementTokenCode.showEnableAdd( &Gra_LicenseManagementCursorTokenCode[i], ( i == ss_CodeInputPosition ? True : False ) );	// カーソルの表示（入力選択位置）（左から０～６）.
	}
}
//================================================================================================.
//概要    :サービス・課金設定・ライセンス管理・トークンコード入力画面 : 画面移動.
//================================================================================================.
void PServiceLicenseManagementTokenCodeEnableInput::procGoToPage( uchar option )
{
	switch( option ) {
		case 60:   // キャンセルキー.
			nextGamen = licenseManagementRetGamen;	// 戻り画面.
			licenseManagementRetGamen = NULL;	// 戻り画面初期化.
			break;
		default: break;
	}
}
//================================================================================================.
//概要    :サービス・課金設定・ライセンス管理・トークンコード入力画面 : OKキー（押された）.
//================================================================================================.
void PServiceLicenseManagementTokenCodeEnableInput::procOk( uchar option )
{
	char	sc_FileName[PNLD_TokenCodeLenMax + 1];
	memset( sc_FileName, 0, sizeof( sc_FileName ) );
	if( True == NowInputCodeState( sc_Code ) ) {	// 条件を満たしている場合、遷移.
		for( char i = 0 ; PNLD_TokenCodeBlockNumMax > i ; i++ ) {
			strncat( sc_FileName, sc_Code[( uchar )i], PNLD_TokenCodeBlockLenMax );
		}
		PNLC_TokenCodeSetting::getInstance()->setTokenCode( sc_FileName );	// 設定されている番号のインデックスにトークンコードを設定.
		nextGamen = licenseManagementRetGamen;	// 戻り画面.
		licenseManagementRetGamen = NULL;		// 戻り画面初期化.
	} else {	// 条件を満たしていないので、報知音を鳴らして、遷移しない.
		setBuzzerType( PCGE_BuzzerType_InputNg );	// 報知音設定.
	}
}
//================================================================================================.
//概要    :サービス・課金設定・ライセンス管理・トークンコード入力画面 : テンキー.
//================================================================================================.
void PServiceLicenseManagementTokenCodeEnableInput::proc10Key( uchar option )
{
	if( option > 1 ) {	// 0、1の時は受け付けない.
		char _sc_CharAddress[2];
		memset( _sc_CharAddress, '\0', sizeof( _sc_CharAddress ) );
		snprintf( _sc_CharAddress, sizeof(_sc_CharAddress), "%d", option );	// 10キー入力された数値を文字に変換.
		if( True == bl_DirectCode[ ss_CodeInputPosition ] ) {	// ダイレクト入力がTrueの場合、エリア内の値をクリアしてから入力.
			memset( sc_Code[ ss_CodeInputPosition ], '\0', sizeof( sc_Code[ ss_CodeInputPosition ] ) );
		}
		uchar uc_StringLen = static_cast<uchar>( strlen( sc_Code[ ss_CodeInputPosition ] ) );	// 現在エリア内にどれだけ文字列が入力されているか？.
		if( uc_StringLen < PNLD_TokenCodeBlockLenMax ) {	// エリア内の文字が4文字に達している場合は受付けない.
			sc_Code[ ss_CodeInputPosition ][uc_StringLen] = _sc_CharAddress[0];	// 現在の文字列の末尾に文字を追加する.
			bl_DirectCode[ ss_CodeInputPosition ] = False;	// ダイレクト入力解除.
		}
		if( uc_StringLen + 1 == PNLD_TokenCodeBlockLenMax ) {	// エリア内の文字が4文字の場合は、入力エリアを1つずらしておく.
			if( ss_CodeInputPosition < PNLD_TokenCodeBlockNumMax - 1 ) {	// 最右端の場合はずらさない.
				bl_DirectCode[ss_CodeInputPosition] = True;		// ダイレクト入力.
				ss_CodeInputPosition++;
			}
		}
		setupGamen();
	} else {
		setBuzzerType( PCGE_BuzzerType_InputNg );	// 報知音設定.
	}
}
//================================================================================================.
//概要    :サービス・課金設定・ライセンス管理・トークンコード入力画面 : クリアー.
//================================================================================================.
void PServiceLicenseManagementTokenCodeEnableInput::procClear( uchar option )
{
	memset(	sc_Code, '\0', sizeof( sc_Code ) );	// 入力値を初期化.
	for( uchar i = 0; i < PNLD_TokenCodeBlockNumMax; i++ ) {
		bl_DirectCode[ ss_CodeInputPosition ] = True;	// ダイレクト入力ON.
	}
	ss_CodeInputPosition = 0;	// 入力位置を初期化.
	setupGamen();
}
//================================================================================================.
//概要    :サービス・課金設定・ライセンス管理・トークンコード入力画面 : キーボード入力.
//================================================================================================.
void PServiceLicenseManagementTokenCodeEnableInput::procKeyBoard( uchar option )
{
	char _sc_keyCode[3];	// キーコード.
	memset( _sc_keyCode, '\0', sizeof( _sc_keyCode ) );	// キーコード初期化.
	// キーコードを取得.
	Kbd_ServiceInputKeybord.getKeyString( option, _sc_keyCode );
	uchar uc_StringLen = 0;	// 文字列の長さを測る用.
	uchar i = 0 ;	// 初期化用.
	switch( _sc_keyCode[0] ) {	// キーコード.
		case PLBD_ArrowLeftKeyCode:			// ←キー押下：カーソル位置を左に移動.
			if( ss_CodeInputPosition > 0 ) {
				bl_DirectCode[ss_CodeInputPosition] = True;		// ダイレクト入力.
				ss_CodeInputPosition--;
			}
			break;
		case PLBD_ArrowRighKeyCode:			// →キー押下：カーソル位置を右に移動.
			if( ss_CodeInputPosition < PNLD_TokenCodeBlockNumMax - 1 ) {
				bl_DirectCode[ss_CodeInputPosition] = True;		// ダイレクト入力.
				ss_CodeInputPosition++;
			}
			break;
		case PLBD_DeleteKeyCode:			// Delキー押下.
			for( i = 0; i < PNLD_TokenCodeBlockLenMax; i++ ) {
				sc_Code[ss_CodeInputPosition][i] = 0;		// 入力値.
			}
			bl_DirectCode[ ss_CodeInputPosition ] = True;		// ダイレクト入力ON
			break;
		default:							// その他のキー押下：入力文字列表示.
			if( True == bl_DirectCode[ ss_CodeInputPosition ] ) {	// ダイレクト入力がTrueの場合、エリア内の値をクリアしてから入力.
				memset( sc_Code[ ss_CodeInputPosition ], 0, sizeof( sc_Code[ ss_CodeInputPosition ] ) );
			}
			uc_StringLen = ( uchar )strlen( sc_Code[ ss_CodeInputPosition ] );	// 現在エリア内にどれだけ文字列が入力されているか？
			if( uc_StringLen < PNLD_TokenCodeBlockLenMax ) {	// エリア内の文字が4文字に達している場合は受付けない.
				sc_Code[ ss_CodeInputPosition ][uc_StringLen] = _sc_keyCode[0];
				bl_DirectCode[ ss_CodeInputPosition ] = False;	// ダイレクト入力解除.
			}
			if( uc_StringLen + 1 == PNLD_TokenCodeBlockLenMax ) {	// エリア内の文字が4文字の場合は、入力エリアを1つずらしておく.
				if( ss_CodeInputPosition < PNLD_TokenCodeBlockNumMax - 1 ) {	// 最右端の場合はずらさない.
					bl_DirectCode[ss_CodeInputPosition] = True;		// ダイレクト入力.
					ss_CodeInputPosition++;
				}
			}
			break;
	}
	setupGamen();
}
// -----------------------------------------------------------------------------------------------
// クラス	：PServiceLicenseManagementTokenCodeEnableInput.
// 関数名	：procRMPStrInput.
// 引数		：uchar option.
// 戻り値	：なし.
// 備考		：.
// 作成者	：OPS1 棚.
// -----------------------------------------------------------------------------------------------
void PServiceLicenseManagementTokenCodeEnableInput::procRMPStrInput( uchar option )
{
	ushort us_CodeLenNum = PNLD_TokenCodeBlockLenMax * PNLD_TokenCodeBlockNumMax;	// (ハイフンを無視した)最大文字列長.

	PNLC_RMPStrInputMng::newInstance()->setStringToSeparateBuffer( ( char* )sc_Code, us_CodeLenNum, ( uchar )PNLD_TokenCodeBlockNumMax, ( uchar )PNLD_TokenCodeBlockLenMax );
	setupGamen();
}

//関数------------------------------------------------------------------------------------------------------------------.
//概要    ：画面開始処理.
//備考    ：.
//戻値    ：なし.
//作成者  ：OPS1大西.
//================================================================================================.
//概要    :サービス・課金設定・ライセンス管理・トークンコードエラー画面 : 画面開始処理.
//================================================================================================.
void PServiceLicenseManagementErrorTokenCodeList::startGamen()
{
	PServiceLicenseManagementCom::startGamen();

	LCAS_LcaTokenCode*	ps_LcaInputTokenCode;										// 入力したトークンコード構造体.
	LCAS_LcaTokenCode*	ps_LcaErrorTokenCode;										// エラートークンコード構造体.
	LCAS_LcaTokenCode	s_LcaErrorTokenCode;										// エラートークンコード構造体.

	ps_LcaInputTokenCode = PNLC_TokenCodeSetting::getInstance()->getLcaTokenCode();	// 入力したトークンコード取得.
	PnlComGetEnablerSetting()->getErrorTokenCodeList( &s_LcaErrorTokenCode );			// エラートークンコード取得.
	ps_LcaErrorTokenCode = &s_LcaErrorTokenCode;

	memset( bl_isEnableStatus, False, sizeof( bl_isEnableStatus ) );

	uchar i = 0;
	uchar j = 0;

	for( i = 0; PNLD_TokenCodeMaxNum > i; i++ ) {

		// エラートークンコードが存在する場合.
		if( '\0' != ps_LcaErrorTokenCode->sc_TokenCode[i][0] ) {

			// 入力したトークンコード構造体を走査.
			while( PNLD_TokenCodeMaxNum > j ) {
				if( 0 == strcmp( ps_LcaInputTokenCode->sc_TokenCode[j], ps_LcaErrorTokenCode->sc_TokenCode[i] ) ) {
					bl_isEnableStatus[j] = True;
					j++;
					break;
				}
				j++;
			}
		}
	}
}
//================================================================================================.
//概要    :サービス・課金設定・ライセンス管理・トークンコードエラー画面 : 表示部品のセットアップ.
//================================================================================================.
void PServiceLicenseManagementErrorTokenCodeList::setupGamen( short option )
{
	for( uchar i = 0; i < PNLD_TokenCodeMaxNum; i++ ) {
		if( True == bl_isEnableStatus[i] ) {
			Txt_ServiceLicenseManagementErrorTokenCode[i].showEnable( True );	// トークンコード表示.
			Tfd_ServiceLicenseManagementErrorTokenCode[i].changeExternalText( ( uchar* )PNLC_TokenCodeSetting::getInstance()->getTokenCodeAddHyphen( i ), PNLD_TokenCodeAddHyphenLenMax );	// 指定した番号のトークンコード(ハイフン付)を取得して表示.
			Tfd_ServiceLicenseManagementErrorTokenCode[i].showEnable( True );	// トークンコード表示.
		} else {
			Txt_ServiceLicenseManagementErrorTokenCode[i].showEnable( False );	// トークンコード非表示.
			Tfd_ServiceLicenseManagementErrorTokenCode[i].showEnable( False );	// トークンコード非表示.
		}
	}
	PServiceLicenseManagementCom::setupGamen( option );	// 親クラスの処理を呼ぶ.
}
