//================================================================================================
//概要    :サービス・課金設定・ライセンス管理・初期化コード入力画面 : 画面移動.
//================================================================================================
void PServiceLicenseManagementInitialCodeInput::procGoToPage( uchar option )
{
	switch( option ) {
		case 60:   // キャンセルキー.
			if( &gp_ServiceLicenseManagementEnabler  == licenseManagementRetGamen || 	// サービス・課金設定・ライセンス管理・有効化画面.
			    &gp_ServiceLicenseManagementDisabler == licenseManagementRetGamen || 	// サービス・課金設定・ライセンス管理・無効化画面.
			    &gp_ServiceLicenseManagementRepair   == licenseManagementRetGamen		// サービス・課金設定・ライセンス管理・修復画面.
			  ) {	// 有効化、無効化、修復画面へ遷移は初期化必要 (問題点_No.83398 初期化コード確定失敗後、キャンセルキー押下にて画面を抜けると不要なメッセージが表示される問題点対応).
				bl_isRequestInitialize = True;	// 初期化必要.
			}

			nextGamen = licenseManagementRetGamen;	// 戻り画面.
			licenseManagementRetGamen = NULL;	// 戻り画面初期化.
			break;
		default: break;
	}
}
//================================================================================================
//概要    :サービス・課金設定・ライセンス管理・初期化コード入力画面 : ボタン（押された）.
//================================================================================================
void PServiceLicenseManagementInitialCodeInput::procButtonOn( uchar option )
{
	switch( option ) {
		case BTNID_ServiceLicenseManagementFix:	// 確定キー.
			// 初期化実行.
			if( True == NowInputCodeState( sc_Code ) ) {	// 条件を満たしている場合、遷移.
				sprintf( ( char* )uc_InitialCode, "%5s%5s%5s%5s%5s%5s%5s", sc_Code[0],sc_Code[1],sc_Code[2],sc_Code[3],sc_Code[4],sc_Code[5],sc_Code[6] );	// 設定値を渡す.
				nextGamen = &gp_ServiceLicenseManagementWait;	// サービス・課金設定・ライセンス管理・処理中画面.
				bl_NoAcceptBtnFlag = True;	// ボタン受付不可にする.
				PnlComGetEnabler()->req_startLicenseInitialization( uc_InitialCode, ans_startLicenseInitialization );	// 初期化実行(ライセンス初期化コード入力).
			} else {	// 条件を満たしていないので、報知音を鳴らして、遷移しない.
				setBuzzerType( PCGE_BuzzerType_InputNg );	// 報知音設定.
			}
			break;
		default : break;
	}
	setupGamen();
}
