//================================================================================================
//概要    :サービス・課金設定・ライセンス管理・リストプリント共通 : スタート（押された）.
//================================================================================================
void PServiceLicenseManagementListOutputCom::ans_startListOutput( ushort us_Result )
{
	_bl_isWaitPrint = False;
}
void PServiceLicenseManagementListOutputCom::procStart( uchar option )
{
	// プリント許可の時.
	if( printStartDisable() == False ) {
		// システム状態（ＡＰＩ）・インスタンス取得
		APIC_SystemStatus* pc_SystemStatus = APIC_SystemStatus::newInstance();
		if( pc_SystemStatus->checkJobReserve() == False ) { // ジョブ予約不可のときは何もせずリターン.
			MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
			return;
		}
		_bl_isWaitPrint = True;	// スタート押下後画像生成終了まで立っているフラグ.
		bl_NoAcceptBtnFlag = True;	// ボタン操作受付不許可フラグ(True→受付不可).
		APIC_ListPrint*	pc_ListPrint = APIC_ListPrint::newInstance();
		pc_ListPrint->req_startListPrint(
		    e_ListPrint,					// 印字指定.
		    ( uint32_t )e_FeedTrayListPrint,		// トレイ指定.
		    ans_startListOutput,			// コールバック.
		    -1,								// ボックス番号.
		    0,								// ドキュメント番号.
		    NULL,							// 構造体へのポインタ.
		    0,								// 片面(0)/両面(1).
		    TYPE_JobEntryIF_Panel );		// インタフェース番号.
		setupGamen();	// 表示画面のセットアップ.
	}
	else {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );		// 拒否音.
	}
}
//================================================================================================
//概要    :サービス・課金設定・ライセンス管理・リストプリント共通 : ファンクション終了.
//================================================================================================
void PServiceLicenseManagementListOutputCom::procFunctionEnd( uchar option )
{
	bl_NoAcceptBtnFlag = False;	// ボタン操作受付不許可フラグ(True→受付不可).
}
//================================================================================================
//概要    :サービス・課金設定・ライセンス管理・リストプリント共通 : 表示部品のセットアップ.
//================================================================================================
void PServiceLicenseManagementListOutputCom::setupGamen( short option )
{
	// シリアル番号表示.
	uchar uc_SerialNumber[TYPD_MAX_SerialNoPrinter];	// シリアル番号.
	// 変数の初期化.
	memset( uc_SerialNumber, '\0',sizeof( uc_SerialNumber ) );
	ppc_SystemInfo->getSerialNoPrinter( ( char* )uc_SerialNumber );	// シリアル番号・プリンタの取得.
	Tfd_ServiceLicenseManagementListOutputSerialNumber.changeExternalText( uc_SerialNumber, sizeof( uc_SerialNumber ) );	// シリアル番号・プリンタ表示.
	APIC_ActiveJobList* pc_ActiveJobList = APIC_ActiveJobList::newInstance();
	APIC_Job* pc_currentJob = pc_ActiveJobList->getCurrentPrintJob();
	// プリント完了を監視.
	if( bl_NoAcceptBtnFlag == True		// ボタン受付禁止中.
	    && _bl_isWaitPrint == False		// 画像生成中ではない.
	    && pc_currentJob == NULL ) {		// 実行中のプリントジョブが無い.
//Comment 2016/01/07 HCL_Krithika [ZeusS_ZX0][制御構成変更_No.76-1] Not required case.
//// Comment 2015/11/02 【ZeusS_ZX0】【HCL_Vasu】【制御構成変更_No.76-1】Adding Error Code macro.
//		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//		if (NULL !=pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x1900660101367D01);
//		}
//		APIC_FeedTray* pc_FeedTray = PnlComGetFeedTray();	// 給紙トレイ情報（ＡＰＩ）・インスタンス取得
//		TYPE_TrayStatus  e_TrayStatus  = pc_FeedTray->getTrayStatus( e_FeedTrayListPrint );	// 給紙トレイ状態
//		TYPE_PaperStatus e_PaperStatus = pc_FeedTray->getPaperStatus( e_FeedTrayListPrint );	// 用紙状態
//		Bool bl_isTrayOpenEmpty = False; // トレイ空きか紙切れのフラグ.
//		if( ( e_TrayStatus == TYPE_TrayStatusOpen ) || ( e_PaperStatus == TYPE_PaperStatusEmpty ) ) {
//			bl_isTrayOpenEmpty = True; //トレイ空きか紙切れ.
//		}
		CallBackIndi( TYPE_PNL_CallBack_functionEnd );		// コールバックイベント発生
	}
	// スタート可能状態の判定.
	if( onlyPanel.ep_PanelStatus != EP_PNS_Setting
	    || _bl_isWaitPrint == True	// 画像生成中.
	    || pc_currentJob != NULL ) {	// プリント動作中.
		PServiceFunctionEnableStartCom::setupGamen( option );	// ライン/OKキー更新のため、ベースクラスをCall.
		printLEDControl( False );	// スタートキーＬＥＤの制御(赤).
	} else {
		e_FeedTrayListPrint = searchTrayListPrint( 0 );	// 片面印字指定.
	}
}
