//================================================================================================
PServiceLicenseManagementFCodeList::PServiceLicenseManagementFCodeList(
    PDisplayParts** partsTable,
    short partsNumber,
    Bool isNoWarningGamen )
	: PServiceLicenseManagementCom( partsTable, partsNumber, isNoWarningGamen )
{
	memset( uc_DispList, '\0',sizeof( uc_DispList ) );
	uc_NowPage = 1;		// 現在のページ.
	uc_MaxPage = 1;		// 最大ページ数.
	ss_mCommandOkCount[0] = 0;
}
//================================================================================================
//概要    :サービス・課金設定・ライセンス管理・機能コード一覧 :ボタン（押された）.
//================================================================================================
void PServiceLicenseManagementFCodeList::procButtonOn( uchar option )
{
	switch( option ) {
		case 20:
			if( uc_MaxPage > uc_NowPage ) {
				uc_NowPage++;
			} else {
				uc_NowPage = 1;
			}
			break;
		case 21:
			if( 1 < uc_NowPage ) {
				uc_NowPage--;
			} else {
				uc_NowPage = uc_MaxPage;
			}
			break;
		default: break;
	}
	setupGamen();
}
