//================================================================================================
//概要    :サービス・課金設定・ライセンス管理・機能コード一覧 : 初期設定.
//================================================================================================
void PServiceLicenseManagementFCodeList::startGamen()
{
	PServiceLicenseManagementCom::startGamen();			// ファンクション共通初期処理.
	memset( uc_DispList, '\0',sizeof( uc_DispList ) );
	uchar uc_FunctionStatus[8];			// 機能コードの状態.
	uchar uc_FunctionWaitStatus[8];		// 機能コード電源OFF/ON待ち状態(使わない).
	memset( uc_FunctionStatus, '\0',sizeof( uc_FunctionStatus ) );
	memset( uc_FunctionWaitStatus, '\0',sizeof( uc_FunctionWaitStatus ) );
	PnlComGetEnabler()->getFunctionEnablerStatus( uc_FunctionStatus , uc_FunctionWaitStatus );	// 機能状態取得（FEK）.

	short ss_Byte = 0;		// チェックしているByte.
	short ss_Bit = 0;		// チェックしているbit.
	uchar uc_Mask = 0x01;	// マスク用.
	short ss_DispCount = 0;	// 表示する数.
	uchar uc_PrebitNumber = 0;	// bit番号格納用.

	for( short i = 0 ; i < DEF_FunctionCodeListTbl ; i++ ) {
		uc_PrebitNumber = static_cast<uchar>( functionCodeListTbl[i].bitNumber - 1 );	// bit番号を配列計算用に-1しておく.
		ss_Byte =( uc_PrebitNumber / 8 );	// チェックするbitがどこにあるか算出.
		ss_Bit = ( uc_PrebitNumber % 8 );	// チェックするbitがどこにあるか算出.

		uc_Mask = 0x01;	// マスクを初期化.
		uc_Mask = ( uchar )( uc_Mask << ss_Bit );
		if( ( uc_FunctionStatus[ss_Byte] & uc_Mask ) != 0 ) {	// 対象bitが「1」か判断.
			uc_DispList[ss_DispCount] = functionCodeListTbl[i].bitNumber;	// bitが「1」の場合、表示するbit番号を格納.
			ss_DispCount++;
		}
	}

	uc_NowPage = 1;		// 現在のページ.
	uc_MaxPage = ( uchar )( ss_DispCount / PNLE_ServFunctionListMax );		// 最大ページ数.
	if( 0 != ( ss_DispCount  % PNLE_ServFunctionListMax ) ) { uc_MaxPage = static_cast<uchar>( uc_MaxPage + 1 ); }	// 割り切れるときは +1しない.
	setFunctionCode( TYPD_FNC_Counter );	// ファンクションコード設定.
	ss_mCommandOkCount[0] = 0;
}
//================================================================================================
//概要    :サービス・課金設定・ライセンス管理・機能コード一覧 : 表示部品のセットアップ.
//================================================================================================
void PServiceLicenseManagementFCodeList::setupGamen( short option )
{
	Rbt_ServiceLicenseManagementMenu.select( 6 );	// ライセンス管理・左側メニューローテンションボタン.
	// ライセンス管理異常状態の場合、修復キーを表示(True(異常)/False(正常)).
	Key_ServiceLicenseManagementMenuRepair.showEnable( PnlComGetEnabler()->isLicenseManagementAbnormal() );	// 修復キー.
	Key_ServiceLicenseManagementMenuRequestCode.showEnable( !( PnlComGetEnabler()->isLicenseManagementAbnormal() ) );	// リクエストコードキー.
	Inp_SMoveNowPageDo = uc_NowPage;	//  現ページ数.
	Inp_SMoveMaxPageDo = uc_MaxPage;	//  総ページ数.
// Comment 2019/08/05 [HCLT-Ranjith] [IT6_EagleZ+_BKZ+] [?§??No.36_Sparrow-AIODeneb-MLK] Adding machine type support for Sparrow AIODeneb-MLK.					
////comment 2019/04/01 HCLT-Shalini [IT6_EagleH] [RQ-797] [WP-2187] Show/Hide condition of ｳｲﾙｽｽｷｬﾝ機能.
//	Bool bl_bitEnabled = 0;
	short i = 0,j = 0;	// カウント用.
	uchar uc_Disp = 0;

	for( i = 0; i < PNLE_ServFunctionListMax ; i++ ) {
// comment 2016/09/15 【HCL-Gadiya sai】【1002990】Klockwork Changes ID: 74960 [ABV.GENERAL].check for buffer overflow is kept.
		if( uc_NowPage > 0 ) { 
			uc_Disp = uc_DispList[i + ( ( uc_NowPage - 1 )*PNLE_ServFunctionListMax )];
		}
		if( uc_Disp > 0 ) {	// 有効な機能があった場合、表示する.
			for( j = 0; j < DEF_FunctionCodeListTbl ; j++ ) {	// 表示する文字列の配列番号を取得する.
				if( functionCodeListTbl[j].bitNumber == uc_Disp ) {
					Tfd_ServiceLicenseManagementFunctionCodeList[i].changeText( functionCodeListTbl[ j ].text_serv );	//
					Tfd_ServiceLicenseManagementFunctionCodeList[i].showEnable( True );
// Comment 2019/08/05 [HCLT-Ranjith] [IT6_EagleZ+_BKZ+] [?§??No.36_Sparrow-AIODeneb-MLK] Adding machine type support for Sparrow AIODeneb-MLK.					
////comment 2019/04/01 HCLT-Shalini [IT6_EagleH] [RQ-797] [WP-2187] Show/Hide condition of ｳｲﾙｽｽｷｬﾝ機能.
					if ( True == PLBC_FuncVersionCheck::isOK_IT6_Type1() ) {
						TYPE_MachineType e_MachineType = PnlComGetSystemInfo()->getMachineType();
						Bool bl_bitEnabled = 0;
						if( ( TYPE_MachineTypeSparrow1SFP == e_MachineType ) || (TYPE_MachineTypeSparrow2SFP == e_MachineType)) {	// DEF_SparrowAIOSFPCus
							if( PNLE_ServiceFEKBIT25 == uc_Disp )	bl_bitEnabled = True;
								if( ( bl_bitEnabled == uc_Disp ) || ( PNLE_ServiceFEKBIT27 == uc_Disp ) ){
									Tfd_ServiceLicenseManagementFunctionCodeList[i].showEnable( False );
							}
						} else {
							if( PNLE_ServiceFEKBIT25 == uc_Disp )	bl_bitEnabled = True;
								if ( (  True == bl_bitEnabled ) && ( PNLE_ServiceFEKBIT27 == uc_Disp ) ) {
									Tfd_ServiceLicenseManagementFunctionCodeList[i].showEnable( False );
								}
						}
					}
					break;
				}
			}
		} else {
			Tfd_ServiceLicenseManagementFunctionCodeList[i].showEnable( False );
		}
	}
	if( 1 >= uc_MaxPage ) {
		Grp_ServiceMovePageUpDownDo.showEnable( False );
	}
	PServiceLicenseManagementCom::setupGamen( option );	// 親クラスの処理を呼ぶ.
}
struct SP_OneKeyCode {
	EP_Service_KeyCode	ep_KeyCode;
	short				ss_Option;
};
