SP_OneKeyCode sp_MagicSequencePrintSpeedInfo[] = {
	{ EP_Service_KeyCode_Stop,		0 },	// ストップキー.
	{ EP_Service_KeyCode_10Key,		5 },	// 5（テンキー）.
	{ EP_Service_KeyCode_10Key,		9 },	// 9（テンキー）.
	{ EP_Service_KeyCode_10Key,		7 },	// 7（テンキー）.
	{ EP_Service_KeyCode_10Key,		9 },	// 9（テンキー）.
	{ EP_Service_KeyCode_None,	   -1 },	// マジックシーケンス最後を示す.
};
/*================================================================================================
// 概要		:サービス・課金設定・ライセンス管理・機能コード一覧 : 速度情報画面移行チェック.
// 戻り値	:なし.
// 備考		:.
================================================================================================*/
Bool PServiceLicenseManagementFCodeList::checkServiceMode( EP_Service_KeyCode _ep_KeyCode, short _ss_option )
{
	if( sp_MagicSequencePrintSpeedInfo[ ss_mCommandOkCount[PNLE_MagicSequencesPrintSpeedInfo] ].ep_KeyCode == _ep_KeyCode
	    && sp_MagicSequencePrintSpeedInfo[ ss_mCommandOkCount[PNLE_MagicSequencesPrintSpeedInfo] ].ss_Option  == _ss_option ) {
		ss_mCommandOkCount[PNLE_MagicSequencesPrintSpeedInfo] = static_cast<short>( ss_mCommandOkCount[PNLE_MagicSequencesPrintSpeedInfo] + 1 );	// コマンドＯＫ.
	} else {
		ss_mCommandOkCount[PNLE_MagicSequencesPrintSpeedInfo]  = 0;	// コマンドＮＧ.
	}
// comment 2016/02/26 【HCLT-Juned】 【ZeusSBK】 【CQ525401】 Revert back the changes done for the display of Speed Change Key and added  ZeusSBK x/0/1/2 machine type for display and non display of SpeedChange Key.
//// comment 2016/02/12 【HCLT-Prasanjeet】 【ZeusSBK】 【制御構成変更_No.26】 Screen is removed for all IT5 models.
////	if( sp_MagicSequencePrintSpeedInfo[ ss_mCommandOkCount[PNLE_MagicSequencesPrintSpeedInfo] ].ep_KeyCode == EP_Service_KeyCode_None
////	    && sp_MagicSequencePrintSpeedInfo[ ss_mCommandOkCount[PNLE_MagicSequencesPrintSpeedInfo] ].ss_Option  == -1 ) {
////		// コマンドの最後まできているので、コマンド入力成功.
////#ifndef DEF_A4_Cus	// 速度変更不可対応 2015.02.05 st_yamura
////		nextGamen = &gp_ServiceLicenseManagementPrintSpeedInfo;		// 速度情報.
////#endif	// DEF_A4_Cus
////	}
	if( sp_MagicSequencePrintSpeedInfo[ ss_mCommandOkCount[PNLE_MagicSequencesPrintSpeedInfo] ].ep_KeyCode == EP_Service_KeyCode_None
	    && sp_MagicSequencePrintSpeedInfo[ ss_mCommandOkCount[PNLE_MagicSequencesPrintSpeedInfo] ].ss_Option  == -1 ) {
		// コマンドの最後まできているので、コマンド入力成功.
#ifndef DEF_A4_Cus	// 速度変更不可対応 2015.02.05 st_yamura
// comment 2017/07/25 【IT5_4.1】 【HCLT_Gomathy】 【1026882】 Condition added not to launch 90B00260 screen for ZeusSBK_2nd 0 Machine Type.
// comment 2017/09/26 【Eagle】【HCLT_Pavani】【制御構成変更_No.11】【WP 275】Condition added not to launch 90B00260 screen for Eagle Z/X/0 Machine Types.		
		TYPE_MachineType e_MachineType = PnlComGetSystemInfo()->getMachineType();
		if ( ( TYPE_MachineTypeEagleZ != e_MachineType )
		  	&& ( TYPE_MachineTypeMinervaSBKX != e_MachineType )
		 	&& ( TYPE_MachineTypeMinervaSBK0_US != e_MachineType )
		  	&& ( TYPE_MachineTypeMinervaSBK0_EU != e_MachineType )
		  	&& ( TYPE_MachineTypeMinervaSBK0_JP != e_MachineType )
		  	&& ( TYPE_MachineTypeMinervaSBKEmu3 != e_MachineType )
		  	&& ( TYPE_MachineTypeMinervaSBKEmu72 != e_MachineType )
		  	&& ( TYPE_MachineTypeMinervaSBKEmu73 != e_MachineType )
		  	&& ( TYPE_MachineTypeZeusSZ_US_JP != e_MachineType )
		  	&& ( TYPE_MachineTypeZeusSZ_EU != e_MachineType )
		  	&& ( TYPE_MachineTypeZeusSX_US_JP != e_MachineType )
		  	&& ( TYPE_MachineTypeZeusSX_EU != e_MachineType )
		  	&& ( TYPE_MachineTypeZeusS0 != e_MachineType )
		 	&& ( TYPE_MachineTypeEagleX != e_MachineType )
		 	&& ( TYPE_MachineTypeEagle0 != e_MachineType ) 
			&& ( TYPE_MachineTypeZeusSZX0Emu3 != e_MachineType )
		  	&& ( TYPE_MachineTypeZeusSZX0Emu72 != e_MachineType )
		  	&& ( TYPE_MachineTypeZeusSBKX != e_MachineType )
		  	&& ( TYPE_MachineTypeZeusSBK0 != e_MachineType )
		  	&& ( TYPE_MachineTypeZeusSBK2ndZ != e_MachineType )
		  	&& ( TYPE_MachineTypeZeusSBK2ndX != e_MachineType )
// Comment 2019/04/17 HCLT_Hepzibah [IT6_EagleBK] [制御構成変更_No.6] Adding machine type to support for EagleBK.
		  	&& ( TYPE_MachineTypeEagleBKZ != e_MachineType )
		  	&& ( TYPE_MachineTypeEagleBKX != e_MachineType )
		  	&& ( TYPE_MachineTypeEagleBK0 != e_MachineType )
			&& ( TYPE_MachineTypeEagleBKH_Emu800 != e_MachineType )
// Comment 2019/05/02 HCLT_AppalaRaju [IT6_EagleZ+] [制御構成変更_No.6] Adding EagleZ+ machine type.
			&& ( TYPE_MachineTypeEagleZplus != e_MachineType )
		  	&& ( TYPE_MachineTypeEagleBKZplus != e_MachineType )
		  	&& ( TYPE_MachineTypeEagleZplusEmu800 != e_MachineType )
			&& ( TYPE_MachineTypeEagleBKZplusEmu800 != e_MachineType )
//2018/05/18 HCLT_Arvind DenebMLK [制御構成変更_No.11] Condition added not to launch 90B00260 screen for DenebMLK Machine Types.		
//		  	&& ( TYPE_MachineTypeZeusSBK2nd0 != e_MachineType ) ) {
			&& ( TYPE_MachineTypeZeusSBK2nd0 != e_MachineType )
			&& ( TYPE_MachineTypeDenebMLK1 != e_MachineType )
			&& ( TYPE_MachineTypeDenebMLK2 != e_MachineType )
			&& ( TYPE_MachineTypeDenebMLK3 != e_MachineType )
			&& ( TYPE_MachineTypeDenebMLK4 != e_MachineType )
//Comment 2019/07/22 HCLT-Aruna [IT6_HeliosMLK] [制御構成変更_No.11] [WP-HELIOSMLK-194] Condition added not to launch 90B00260 screen for  HeliosMLK model.
            && ( TYPE_MachineTypeHeliosMLK2 != e_MachineType )
            && ( TYPE_MachineTypeHeliosMLK2_5 != e_MachineType )
//Comment 2019/09/19 HCLT-Hemachander [IT6_HeliosMLK][制御構成変更_No.6] Machine Type addition to HeliosMLK model for China Destination			
// Comment 2019/12/13 【HCLT_Hemachander】【HeliosMLK】【制御構成変更_No.52】 Adding Machine Type for  China Model.
//          && ( TYPE_MachineTypeHeliosMLK3 != e_MachineType )){
			&& ( TYPE_MachineTypeHeliosMLK3 != e_MachineType )
			&& ( TYPE_MachineTypeHeliosMLK2_CNDF != e_MachineType )
			&& ( TYPE_MachineTypeHeliosMLKEmu800 != e_MachineType)
            && ( TYPE_MachineTypeHeliosMLK2_5_CN != e_MachineType )
            && ( TYPE_MachineTypeHeliosMLK2_5_CNDF != e_MachineType )
            && ( TYPE_MachineTypeHeliosMLK3_CN != e_MachineType )
			&& ( TYPE_MachineTypeHeliosMLKEmu800_CN != e_MachineType )
// comment 2021/02/23 【FPT-LinhNV46】 【MinervaSSBK】 【制御構成変更_No.11】 Adding machine type to support for MinervaSSBK.
			&& ( TYPE_MachineTypeMinervaSSBKX != e_MachineType )
		 	&& ( TYPE_MachineTypeMinervaSSBK0_US != e_MachineType )
		  	&& ( TYPE_MachineTypeMinervaSSBK0_EU != e_MachineType )
		  	&& ( TYPE_MachineTypeMinervaSSBKEmu != e_MachineType )){
				nextGamen = &gp_ServiceLicenseManagementPrintSpeedInfo;		// 速度情報.
	    }
#endif	// DEF_A4_Cus
	}
	return ( ss_mCommandOkCount[PNLE_MagicSequencesPrintSpeedInfo] == 0 ) ? False : True;	// カウントが０ならコマンド失敗なのでFalse を返す.
}
