//================================================================================================
//概要    :サービス・課金設定・ライセンス管理・速度情報 : 初期設定.
//================================================================================================
void PServiceLicenseManagementPrintSpeedInfo::startGamen()
{
	PServiceLicenseManagementCom::startGamen();			// ファンクション共通初期処理.
	uchar uc_FunctionStatus[TYPD_PUCFUNCTION_MAX];			// 機能コードの状態.
	uchar uc_FunctionWaitStatus[TYPD_PUCFUNCTION_MAX];		// 機能コード電源OFF/ON待ち状態(使わない).
	memset( uc_FunctionStatus, '\0',sizeof( uc_FunctionStatus ) );
	memset( uc_FunctionWaitStatus, '\0',sizeof( uc_FunctionWaitStatus ) );
	PnlComGetEnabler()->getFunctionEnablerStatus( uc_FunctionStatus , uc_FunctionWaitStatus );	// 機能状態取得（FEK）.
	short ss_Byte = 0;		// チェックしているByte.
	short ss_Bit = 0;		// チェックしているbit.
	uchar uc_Mask = 0x01;	// マスク用.
	uchar uc_PrebitNumber = 0;	// bit番号格納用.

	short ss_i, ss_j;			// ループカウンタ.

	ss_j = 0;
	for( ss_i = 0; PNLD_PrintSpeedListTbl > ss_i; ss_i++ ) {
		uc_PrebitNumber = static_cast<uchar>( printSpeedListTbl[ss_i].bitNumber - 1 );	// bit番号を配列計算用に-1しておく.
		ss_Byte =( uc_PrebitNumber / 8 );	// チェックするbitがどこにあるか算出.
		ss_Bit = ( uc_PrebitNumber % 8 );	// チェックするbitがどこにあるか算出.

		uc_Mask = 0x01;	// マスクを初期化.
		uc_Mask = ( uchar )( uc_Mask << ss_Bit );
		if( 0 != ( uc_FunctionStatus[ss_Byte] & uc_Mask ) ) {	// 対象bitが「1」か判断.
			uc_DispList[ss_j++] = printSpeedListTbl[ss_i].bitNumber;	// bitが「1」の場合、表示するbit番号を格納.
		}
	}
	setFunctionCode( TYPD_FNC_Counter );	// ファンクションコード設定.
}
//================================================================================================
//概要    :サービス・課金設定・ライセンス管理・速度情報 : 表示部品のセットアップ.
//================================================================================================
void PServiceLicenseManagementPrintSpeedInfo::setupGamen( short option )
{
	short ss_i = 0, ss_j = 0;	// ループカウンタ.
	uchar uc_Disp = 0;

	PServiceLicenseManagementCom::setupGamen( option );	// 親クラスの処理を呼ぶ.

	for( ss_i = 0; ss_i < PNLD_ServPrintSpeedListTblMax; ss_i++ ) {
		uc_Disp = uc_DispList[ss_i];
		if( uc_Disp > 0 ) {	// 有効な機能があった場合、表示する.
			for( ss_j = 0; ss_j < PNLD_PrintSpeedListTbl ; ss_j++ ) {	// 表示する文字列の配列番号を取得する.
				if( printSpeedListTbl[ss_j].bitNumber == uc_Disp ) {
					Txt_ServiceLicenseManagementPrintSpeedList[ss_i].changeText( printSpeedListTbl[ss_j].text_speed );
					Txt_ServiceLicenseManagementPrintSpeedList[ss_i].showEnable( True );
					break;
				}
			}
		} else {
			Txt_ServiceLicenseManagementPrintSpeedList[ss_i].showEnable( False );
		}
	}
}
