//================================================================================================
//概要    :サービス・課金設定・WebDAVサーバー設定・サーバー設定・入力画面 : 画面開始処理.
//================================================================================================
void PServiceWebDAVServerSettingServerInput::startGamen()
{
	// 文字列のクリア.
	memset( sc_StrKeyboard, 0, sizeof( sc_StrKeyboard ) );
	TYPS_WebDavAddressForLMS st_WebDavAddressForLMS = PnlComGetEnablerSetting()->getWebDAVAddressForLMS();		// LMS通信用のWebDAVサーバーアドレス 取得.
	switch( getServiceWebDAVNowGamen() ) {
		case PNLE_ServiceWebDAVGamen_HostName:		// ホスト名.
			strncpy( sc_StrKeyboard, st_WebDavAddressForLMS.sc_HostAddress, sizeof( sc_StrKeyboard ) );
			setKeyboardData( ( char* )sc_StrKeyboard, PNLD_ServiceWebDAVHostNameSize, 66 );	// 表示領域に文字列をセット.
			bl_Password = False;
			bl_ShowPass = False;
			break;
		case PNLE_ServiceWebDAVGamen_FilePath:		// ファイルパス.
			strncpy( sc_StrKeyboard, st_WebDavAddressForLMS.sc_Dir, sizeof( sc_StrKeyboard ) );
			setKeyboardData( ( char* )sc_StrKeyboard, PNLD_ServiceWebDAVFilePathSize, 66 );	// 表示領域に文字列をセット.
			bl_Password = False;
			bl_ShowPass = False;
			break;
		case PNLE_ServiceWebDAVGamen_UserName:		// ユーザー名.
			strncpy( sc_StrKeyboard, st_WebDavAddressForLMS.sc_LoginName, sizeof( sc_StrKeyboard ) );
			setKeyboardData( ( char* )sc_StrKeyboard, PNLD_ServiceWebDAVUserNameSize, 66 );	// 表示領域に文字列をセット.
			bl_Password = False;
			bl_ShowPass = False;
			break;
		case PNLE_ServiceWebDAVGamen_Password:		// パスワード.
			strncpy( sc_StrKeyboard, st_WebDavAddressForLMS.sc_Password, sizeof( sc_StrKeyboard ) );
			setKeyboardData( ( char* )sc_StrKeyboard, PNLD_ServiceWebDAVPasswordSize, 66 );	// 表示領域に文字列をセット.
			bl_Password = True;
			bl_ShowPass = True;
			break;
		default: break;
	}
	PServiceWebDAVServerSettingKeybordInputCom::startGamen();
}
/*================================================================================================
//概要    :サービス・課金設定・WebDAVサーバー設定・サーバー設定・入力画面 : 設定値の確定.
================================================================================================*/
void PServiceWebDAVServerSettingServerInput::registData()
{
	TYPS_WebDavAddressForLMS st_WebDavAddressForLMS = PnlComGetEnablerSetting()->getWebDAVAddressForLMS();		// LMS通信用のWebDAVサーバーアドレス 取得.
	switch( getServiceWebDAVNowGamen() ) {
		case PNLE_ServiceWebDAVGamen_HostName:		// ホスト名.
			memset( st_WebDavAddressForLMS.sc_HostAddress, 0, sizeof( st_WebDavAddressForLMS.sc_HostAddress ) );
			strncpy( st_WebDavAddressForLMS.sc_HostAddress, sc_StrKeyboard, sizeof( st_WebDavAddressForLMS.sc_HostAddress ) -1 );
			break;
		case PNLE_ServiceWebDAVGamen_FilePath:		// ファイルパス.
			memset( st_WebDavAddressForLMS.sc_Dir, 0, sizeof( st_WebDavAddressForLMS.sc_Dir ) );
			strncpy( st_WebDavAddressForLMS.sc_Dir, sc_StrKeyboard, sizeof( st_WebDavAddressForLMS.sc_Dir ) -1 );
			break;
		case PNLE_ServiceWebDAVGamen_UserName:		// ユーザー名.
			memset( st_WebDavAddressForLMS.sc_LoginName, 0, sizeof( st_WebDavAddressForLMS.sc_LoginName ) );
			strncpy( st_WebDavAddressForLMS.sc_LoginName, sc_StrKeyboard, sizeof( st_WebDavAddressForLMS.sc_LoginName ) -1 );
			break;
		case PNLE_ServiceWebDAVGamen_Password:		// パスワード.
			memset( st_WebDavAddressForLMS.sc_Password, 0, sizeof( st_WebDavAddressForLMS.sc_Password ) );
			strncpy( st_WebDavAddressForLMS.sc_Password, sc_StrKeyboard, sizeof( st_WebDavAddressForLMS.sc_Password )-1 );
			break;
		default: break;
	}
	PnlComGetEnablerSetting()->setWebDAVAddressForLMS( st_WebDavAddressForLMS );		// LMS通信用のWebDAVサーバーアドレス 設定.
}
/*================================================================================================
//概要    :サービス・課金設定・WebDAVサーバー設定・１０キー入力共通(複数入力対応) : コンストラクタ.
================================================================================================*/
PServiceWebDAVServerSetting10KeyInputMultiCom::PServiceWebDAVServerSetting10KeyInputMultiCom( PDisplayParts** partsTable, short partsNumber, Bool isNoWarning )
	: PServiceWebDAVServerSettingCom( partsTable, partsNumber, isNoWarning )
{
	ps_Info = NULL;			// 10キー入力情報ポインタ.
	uc_InputMax = 1;		// 入力箇所個数.
	uc_SelectInput = 0;		// 選択入力箇所.
}
/*================================================================================================
//概要    :サービス・課金設定・WebDAVサーバー設定・サーバー設定・１０キー入力共通(複数入力対応) : 画面開始処理.
================================================================================================*/
void PServiceWebDAVServerSetting10KeyInputMultiCom::startGamen()
{
	PServiceWebDAVServerSettingCom::startGamen();
	for( uchar i=0; i<uc_InputMax; i++ ) {		// 入力箇所個数.
		ps_Info[i].bl_Direct = True;			// ダイレクト入力ON.
		ps_Info[i].bl_Fixed  = True;			// 確定フラグON.
		ps_Info[i]._Btx_10KeyInput = NULL;		// 10キー入力した値(PActivatable用).
		ps_Info[i]._Btx_Add_10KeyInput = NULL;	// 10キー入力した値(PActivatableAdd用).
	}
	uc_SelectInput = 0;		// 選択入力箇所.
}
/*================================================================================================
//概要    :サービス・課金設定・WebDAVサーバー設定・サーバー設定・１０キー入力共通(複数入力対応) : 表示画面のセットアップ.
================================================================================================*/
void PServiceWebDAVServerSetting10KeyInputMultiCom::setupGamen( short option )
{
	PServiceWebDAVServerSettingCom::setupGamen( option );
	for( uchar i=0; i<uc_InputMax; i++ ) {		// 入力箇所個数.
		// PActivatable用表示.
		if( NULL != ps_Info[i]._Btx_10KeyInput ) {
			ps_Info[i]._Btx_10KeyInput->set( ( float )ps_Info[i].us_LocalValue, ps_Info[i].bl_Fixed );
			ps_Info[i]._Btx_10KeyInput->show();
		}
		// PActivatableAdd用表示.
		if( NULL != ps_Info[i]._Btx_Add_10KeyInput ) {
			ps_Info[i]._Btx_Add_10KeyInput->set( ( float )ps_Info[i].us_LocalValue, ps_Info[i].bl_Fixed );
			ps_Info[i]._Btx_Add_10KeyInput->show();
		}
	}
}
/*================================================================================================
//概要    :サービス・課金設定・WebDAVサーバー設定・サーバー設定・１０キー入力共通(複数入力対応) : テンキー.
================================================================================================*/
void PServiceWebDAVServerSetting10KeyInputMultiCom::proc10Key( uchar option )
{
	if( ( True == ps_Info[uc_SelectInput].bl_Direct ) && ( 0 == option ) ) { // 最初入力が０を押されたら.
		setBuzzerType( PCGE_BuzzerType_InputNg );
		if( 0 == ps_Info[uc_SelectInput].us_LocalValue )  {
			return;
		}
	}
	Bool bl_Error = False;
	ps_Info[uc_SelectInput].us_LocalValue = ( ushort )proc10KeyInput( ps_Info[uc_SelectInput].us_LocalValue, ps_Info[uc_SelectInput].us_MaxValue, option, ps_Info[uc_SelectInput].bl_Direct, EP_InputMaxLimitPattern_Refuse, &bl_Error );
	if( True == bl_Error ) {
		setBuzzerType( PCGE_BuzzerType_InputNg );
	}
	ps_Info[uc_SelectInput].bl_Direct = False;
	ps_Info[uc_SelectInput].bl_Fixed  = False;		// 確定フラグOFF.
	setupGamen();
}
/*================================================================================================
//概要    :サービス・課金設定・WebDAVサーバー設定・サーバー設定・１０キー入力共通(複数入力対応) : クリアー.
================================================================================================*/
void PServiceWebDAVServerSetting10KeyInputMultiCom::procClear( uchar option )
{
	ps_Info[uc_SelectInput].us_LocalValue = 0;		// 現在値.
	ps_Info[uc_SelectInput].bl_Direct = True;		// ダイレクト入力ON.
	ps_Info[uc_SelectInput].bl_Fixed  = False;		// 確定フラグOFF.
	setupGamen();
}
/*================================================================================================
//概要    :サービス・課金設定・WebDAVサーバー設定・サーバー設定・ポート番号 : コンストラクタ.
================================================================================================*/
PServiceWebDAVServerSettingPortNum::PServiceWebDAVServerSettingPortNum( PDisplayParts** partsTable, short partsNumber, Bool isNoWarning )
	: PServiceWebDAVServerSetting10KeyInputMultiCom( partsTable, partsNumber, isNoWarning )
{
	st_Info.us_MaxValue = 0;				// 最大入力値.
	st_Info.us_MinValue = 0;				// 最小入力値.
	st_Info.us_LocalValue = 0;				// 現在値.
	st_Info.bl_Direct = False;				// ダイレクト入力.
	st_Info.bl_Fixed = False;				// 確定フラグ.
	st_Info._Btx_10KeyInput = NULL;			// 10キー入力した値(PActivatable用).
	st_Info._Btx_Add_10KeyInput = NULL;		// 10キー入力した値(PActivatableAdd用).
}
/*================================================================================================
//概要    :サービス・課金設定・WebDAVサーバー設定・サーバー設定・ポート番号 : 画面開始処理.
================================================================================================*/
void PServiceWebDAVServerSettingPortNum::startGamen()
{
	// 親クラスコール前に入力箇所個数の確定、10キー入力情報の設定をしておく.
	uc_InputMax = PNLD_ServiceWebDAVPortNumInputMax;	// 入力箇所個数.
	ps_Info = &st_Info;									// 10キー入力情報.
	PServiceWebDAVServerSetting10KeyInputMultiCom::startGamen();

	ps_Info->us_MaxValue = PNLD_ServiceWebDAVPortNumMax;		// 最大入力値.
	ps_Info->us_MinValue = PNLD_ServiceWebDAVPortNumMin;		// 最小入力値.
	// 現在の設定値を取得.
	TYPS_WebDavAddressForLMS st_WebDavAddressForLMS = PnlComGetEnablerSetting()->getWebDAVAddressForLMS();		// LMS通信用のWebDAVサーバーアドレス 取得.
	ps_Info->us_LocalValue = st_WebDavAddressForLMS.us_PortNo;	// ポート番号.
	ps_Info->_Btx_10KeyInput = &Btx_ServerWebDAVPortNumber;
}
/*================================================================================================
//概要    :サービス・課金設定・WebDAVサーバー設定・サーバー設定・ポート番号 : 設定値の確定.
================================================================================================*/
void PServiceWebDAVServerSettingPortNum::registData()
{
	// ブランクで抜ける時は設定値を更新しない.
	if( 0 != ps_Info->us_LocalValue ) {
		// 最小値以下の時は、最小値に丸め込む.
		if( ps_Info->us_LocalValue < ps_Info->us_MinValue ) {
			ps_Info->us_LocalValue = ps_Info->us_MinValue;
		}
		TYPS_WebDavAddressForLMS st_WebDavAddressForLMS = PnlComGetEnablerSetting()->getWebDAVAddressForLMS();		// LMS通信用のWebDAVサーバーアドレス 取得.
		st_WebDavAddressForLMS.us_PortNo = ps_Info->us_LocalValue;	// ポート番号.
		PnlComGetEnablerSetting()->setWebDAVAddressForLMS( st_WebDavAddressForLMS );		// LMS通信用のWebDAVサーバーアドレス 設定.
	}
}
