/*================================================================================================
//概要    :サービス・課金設定・WebDAVサーバー設定・ポーリング : 画面開始処理.
================================================================================================*/
void PServiceWebDAVServerSettingPolling::startGamen()
{
	// 親クラスコール前に入力箇所個数の確定、10キー入力情報の設定をしておく.
	uc_InputMax = PNLD_ServiceWebDAVPollingInputMax;	// 入力箇所個数.
	ps_Info = &st_Info[0];								// 10キー入力情報.
	PServiceWebDAVServerSetting10KeyInputMultiCom::startGamen();

	ps_Info[0].us_MaxValue = PNLD_ServiceWebDAVPollingTimesMax;			// 最大入力値.
	ps_Info[0].us_MinValue = PNLD_ServiceWebDAVPollingTimesMin;			// 最小入力値.
	ps_Info[1].us_MaxValue = PNLD_ServiceWebDAVPollingIntervalMax;		// 最大入力値.
	ps_Info[1].us_MinValue = PNLD_ServiceWebDAVPollingIntervalMin;		// 最小入力値.
	// 現在の設定値を取得.
	ps_Info[0].us_LocalValue = PnlComGetEnablerSetting()->getPollingNumForLMS();		// ポーリング回数.
	ps_Info[1].us_LocalValue = PnlComGetEnablerSetting()->getPollingTimerForLMS();		// ポーリング間隔.
	ps_Info[0]._Btx_Add_10KeyInput = &Btx_ServerWebDAVPollingTimes;
	ps_Info[1]._Btx_Add_10KeyInput = &Btx_ServerWebDAVPollingInterval;
	sc_Select = 0;			// 選択キー.
}
/*================================================================================================
//概要    :サービス・課金設定・WebDAVサーバー設定・ポーリング : 表示画面のセットアップ.
================================================================================================*/
void PServiceWebDAVServerSettingPolling::setupGamen( short option )
{
	Rbt_ServiceWebDAVPolling.select( sc_Select );		// WebDAVサーバー設定/ポーリング選択キー.
	if( TYPE_EnableWebDAVServerFixedAddress == PnlComGetEnablerSetting()->getEnableWebDAVServerForLMS() ) {
		Key_ServiceWebDAVServer.showEnable( False );
	} else {
		Key_ServiceWebDAVServer.showEnable( True );
	}
	PServiceWebDAVServerSetting10KeyInputMultiCom::setupGamen( option );	// 表示部品のセットアップ.
}
/*================================================================================================
//概要    :サービス・課金設定・WebDAVサーバー設定・ポーリング : ボタン(押された).
================================================================================================*/
void PServiceWebDAVServerSettingPolling::procButtonOn( uchar option )
{
	switch( option ) {
		case BTNID_ServiceWebDAVPollingTimes:		// ポーリング回数.
			sc_Select = 0;			// 選択キー.
			uc_SelectInput = 0;		// 選択入力箇所.
			break;
		case BTNID_ServiceWebDAVPollingInterval:	// ポーリング間隔.
			sc_Select = 1;			// 選択キー.
			uc_SelectInput = 1;		// 選択入力箇所.
			break;
		default:break;
	}
	setupGamen();	// 表示部品のセットアップ.
}
/*================================================================================================
//概要    :サービス・課金設定・WebDAVサーバー設定・ポーリング : 設定値の確定.
================================================================================================*/
void PServiceWebDAVServerSettingPolling::registData()
{
	for( uchar i=0; i<uc_InputMax; i++ ) {		// 入力箇所個数.
		// ブランクで抜ける時は設定値を更新しない.
		if( 0 != ps_Info[i].us_LocalValue ) {
			// 最小値以下の時は、最小値に丸め込む.
			if( ps_Info[i].us_LocalValue < ps_Info[i].us_MinValue ) {
				ps_Info[i].us_LocalValue = ps_Info[i].us_MinValue;
			}
			switch( i ) {
				case 0:
					PnlComGetEnablerSetting()->setPollingNumForLMS( ( uchar )ps_Info[i].us_LocalValue );	// ポーリング回数.
					break;
				case 1:
					PnlComGetEnablerSetting()->setPollingTimerForLMS( ( uchar )ps_Info[i].us_LocalValue );	// ポーリング間隔.
					break;
				default: break;
			}
		}
	}
}
/*================================================================================================
//概要    :サービス・課金設定・WebDAVサーバー設定・アドレス選択 : コンストラクタ.
================================================================================================*/
PServiceWebDAVServerSettingAddSelect::PServiceWebDAVServerSettingAddSelect( PDisplayParts** partsTable, short partsNumber, Bool isNoWarning )
	: PServiceWebDAVServerSettingCom( partsTable, partsNumber, isNoWarning )
{
	sc_Select = -1;		// 選択キー.
}
/*================================================================================================
//概要    :サービス・課金設定・WebDAVサーバー設定・アドレス選択 : 画面開始処理.
================================================================================================*/
void PServiceWebDAVServerSettingAddSelect::startGamen()
{
	PServiceWebDAVServerSettingCom::startGamen();
	switch( PnlComGetEnablerSetting()->getEnableWebDAVServerForLMS() ) {		// LMS通信用のWebDAVサーバ使用設定 取得.
		case TYPE_EnableWebDAVServerFixedAddress:		sc_Select = 0;	break;	// 固定のアドレスを使う.
		case TYPE_EnableWebDAVServerSettingAddress:		sc_Select = 1;	break;	// 設定したアドレスを使う.
		default :	break;
	}
}
/*================================================================================================
//概要    :サービス・課金設定・WebDAVサーバー設定・アドレス選択 : 表示画面のセットアップ.
================================================================================================*/
void PServiceWebDAVServerSettingAddSelect::setupGamen( short option )
{
	Rbt_ServiceWebDAVAddSelect.select( sc_Select );		// WebDAVサーバー設定/アドレス選択選択キー.
	if( 0 == sc_Select ) {
		Key_ServiceWebDAVServer.showEnable( False );
	} else {
		Key_ServiceWebDAVServer.showEnable( True );
	}
	PServiceWebDAVServerSettingCom::setupGamen( option );	// 表示部品のセットアップ.
}
/*================================================================================================
//概要    :サービス・課金設定・WebDAVサーバー設定・アドレス選択 : ボタン(押された).
================================================================================================*/
void PServiceWebDAVServerSettingAddSelect::procButtonOn( uchar option )
{
	switch( option ) {
		case BTNID_ServiceWebDAVFixedAdd:	sc_Select = 0;	break;	// 固定アドレス.
		case BTNID_ServiceWebDAVInputAdd:	sc_Select = 1;	break;	// 指定アドレス.
		default:break;
	}
	setupGamen();	// 表示部品のセットアップ.
}
/*================================================================================================
//概要    :サービス・課金設定・WebDAVサーバー設定・アドレス選択 : 設定値の確定.
================================================================================================*/
void PServiceWebDAVServerSettingAddSelect::registData()
{
	TYPE_EnableWebDAVServer e_EnableWebDAVServer = PnlComGetEnablerSetting()->getEnableWebDAVServerForLMS();
	switch( sc_Select ) {
		case 0:		e_EnableWebDAVServer = TYPE_EnableWebDAVServerFixedAddress;		break;	// 固定アドレス.
		case 1:		e_EnableWebDAVServer = TYPE_EnableWebDAVServerSettingAddress;	break;	// 設定アドレス.
		default :	break;
	}
	PnlComGetEnablerSetting()->setEnableWebDAVServerForLMS( e_EnableWebDAVServer );		// LMS通信用のWebDAVサーバ使用設定 設定.
}

