//================================================================================================
// 概要		:サービス・セキュリティ設定・操作禁止解除時間 : 画面開始処理.
// 戻り値	:なし.
//================================================================================================
void PServicePenaltyLockTimer::startGamen()
{
	PServiceNoFunctionCodeCom::startGamen();
	bl_Direct = True;		// ダイレクト入力ON
	bl_Fixed = True;		// 確定フラグON
	// セキュリティ強化モードの取得.
	Bool b_HardeningSecurityMode = PnlComGetSystemSetting()->getSecurityLevelUpOn();
	// セキュリティ強化モードに依って操作禁止解除最小時間を設定する.
	Txt_PenaltyLockTimer.changeText( b_HardeningSecurityMode ? s_ITM5to60 : s_UtiltyLimit1to60 );	// 設定範囲.
	// 操作禁止解除時間の取得.
	us_ReleaseTime = PnlComGetOperationSetting()->getAutoResetseServiceTime();
	us_ReleaseTimeBkUp = PnlComGetOperationSetting()->getAutoResetseServiceTime();
}
//================================================================================================
// 概要		:サービス・セキュリティ設定・操作禁止解除時間 : ボタン（押された）.
// 戻り値	:なし.
//================================================================================================
void PServicePenaltyLockTimer::procButtonOn( uchar option )
{
	switch( option ) {
		case 60: us_ReleaseTime = us_ReleaseTimeBkUp; break;	// 操作禁止解除時間.
		default: break;
	}
}
//================================================================================================
// 概要		:サービス・セキュリティ設定・操作禁止解除時間 : テンキー.
//================================================================================================
void PServicePenaltyLockTimer::proc10Key( uchar option )
{
	if( ( True == bl_Direct ) && ( 0 == option ) ) { // 最初の０入力を受け付けない.
		setBuzzerType( PCGE_BuzzerType_InputNg );
		if( 0 == us_ReleaseTime ) {
			return;
		}
	}
	Bool bl_Error = False;
	// 操作禁止解除時間の設定
	us_ReleaseTime = ( ushort )proc10KeyInput( us_ReleaseTime, 60, option, bl_Direct, EP_InputMaxLimitPattern_Refuse, &bl_Error );
	if( True ==  bl_Error ) {
		setBuzzerType( PCGE_BuzzerType_InputNg );
	}
	bl_Direct = False;		// ダイレクト入力OFF.
	bl_Fixed = False;		// 確定フラグOFF.
	setupGamen( option );
}
//================================================================================================
// 概要		:サービス・セキュリティ設定・操作禁止解除時間 : クリア.
//================================================================================================
void PServicePenaltyLockTimer::procClear( uchar option )
{
	us_ReleaseTime = 0;		// 0クリア.
	bl_Direct = True;		// ダイレクト入力ON.
	bl_Fixed = False;		// 確定フラグOFF.
	setupGamen( option );
}
//================================================================================================
// 概要		:サービス・セキュリティ設定・操作禁止解除時間 : ＯＫキー.
//================================================================================================
void PServicePenaltyLockTimer::procOk( uchar option )
{
	// セキュリティ強化モードの取得.
	Bool b_HardeningSecurityMode = PnlComGetSystemSetting()->getSecurityLevelUpOn();
	ushort us_MinTime = b_HardeningSecurityMode ? 5 : 1; // 最小時間を設定.
	// 禁止解除時間を設定.
	if( us_ReleaseTime >= us_MinTime ) {	// 最小時間以上なら設定.
		PnlComGetOperationSetting()->setAutoResetseServiceTime( us_ReleaseTime, JLGE_InspectLogIfOperationPanel );
	}
	nextGamen = &gp_ServiceSecuritySettingMenu;	// サービス・セキュリティ設定 ・モードメニュー.
}
//================================================================================================
// 概要		:サービス・セキュリティ設定・操作禁止解除時間 : 表示画面のセットアップ.
//================================================================================================
void PServicePenaltyLockTimer::setupGamen( short option )
{
	PServiceNoFunctionCodeCom::setupGamen( option );
	// 操作禁止解除時間設定の表示
	Btx_PenaltyLockTimer.set( us_ReleaseTime, bl_Fixed );
	Btx_PenaltyLockTimer.showEnableAdd( True );
}
//================================================================================================
// 概要		:サービス・セキュリティ設定・管理者認証ロック解除 : 画面開始処理.
//================================================================================================
