{
	PServiceNoFunctionCodeCom::startGamen();
	b_PenaltyLockCancel = False;	// 管理者認証ロック解除フラグ.
// comment 2017/03/09 【HCL-AppalaRaju】【IT54.1】【1015743】 Initializing the variable.
	m_ss_CommandOkCount  = 0;
}
//================================================================================================
// 概要		：サービス・セキュリティ設定・管理者認証ロック解除：ボタン（押された）.
//================================================================================================
void PServiceAdminiPenaltyLockCancel::procButtonOn( uchar option )
{
	switch( option ) {
		case 0:	// ロック解除キー.
		{
			// 管理者ユーザのペナルティ解除

			APIC_User* pc_TrackAdmin = APIC_User::newInstance( TYPD_IndexTrackAdmin );
			APIC_User* pc_UserLMU = APIC_User::newInstance( TYPD_IndexUserLMU );
			if( NULL == pc_TrackAdmin || NULL == pc_UserLMU ) {
// 2015/11/05 【HCLT-Dhivya】 【ZeusS_ZX0】 【制御構成変更_No.76-1】Detail macro is passed in API.
				LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
				if (NULL != pc_BFW_System){
    				pc_BFW_System->registDetailCode(PNLD_DetailCode_Service_0x19000A0101419101);
				}				
				return;
			}

			pc_TrackAdmin->lock();
			pc_TrackAdmin->setTimesOfAuthenticationFailure( 0, JLGE_InspectLogIfOperationPanel );
			pc_TrackAdmin->unlock();
			pc_UserLMU->lock();
			pc_UserLMU->setTimesOfAuthenticationFailure( 0, JLGE_InspectLogIfOperationPanel );
			pc_UserLMU->unlock();
			b_PenaltyLockCancel = True;	// 管理者認証ロック解除フラグ.
			break;
		}
		default: break;
	}
}
//================================================================================================
// 概要		：サービス・セキュリティ設定・管理者認証ロック解除：設定終了.
//================================================================================================
void PServiceAdminiPenaltyLockCancel::procOk( uchar option )
{
	nextGamen = &gp_ServiceSecuritySettingMenu;
}
//================================================================================================
// 概要		：サービス・セキュリティ設定・管理者認証ロック解除：表示部品のセットアップ.
//================================================================================================
void PServiceAdminiPenaltyLockCancel::setupGamen( short option )
{
	PServiceNoFunctionCodeCom::setupGamen( option );
	Txt_AdminiPenaltyLockCancelDownArrow.showEnable( b_PenaltyLockCancel );	// ↓.
	Txt_AdminiPenaltyLockCancelOk.showEnable( b_PenaltyLockCancel );		// OK.
}
// comment 2017/03/09 【HCL-AppalaRaju】【IT54.1】【1015743】 Adding the magic sequence number for diplaying the 90000 screen.	
SP_OneKeyCode sp_MagicSequenceAdminPenaltyLockCancel[] = {
	{ EP_Service_KeyCode_Stop,   0 }, // ストップキー.
	{ EP_Service_KeyCode_10Key,  8 }, // 8（テンキー）.
	{ EP_Service_KeyCode_10Key,  9 }, // ９（テンキー）.
	{ EP_Service_KeyCode_10Key,  1 }, // 1（テンキー）.
	{ EP_Service_KeyCode_10Key,  0 }, // 0（テンキー）.
	{ EP_Service_KeyCode_10Key,  1 }, // 1（テンキー）.
	{ EP_Service_KeyCode_None,  -1 }, // マジックシーケンス最後を示す.
};
//================================================================================================
/**
	  * @ Brief Magic sequence transition check.
	  * @ note  None.
      * @ Param EP_Service_KeyCode Key code.
      * @ Param short option.
      * @retval Bool result.
*/
//================================================================================================
Bool PServiceAdminiPenaltyLockCancel::checkServiceMode( EP_Service_KeyCode ep_KeyCode, short ss_option )
{
	if ( (ep_KeyCode == sp_MagicSequenceAdminPenaltyLockCancel[m_ss_CommandOkCount].ep_KeyCode)
	    && ( ss_option == sp_MagicSequenceAdminPenaltyLockCancel[m_ss_CommandOkCount].ss_Option ) ) {
		m_ss_CommandOkCount += 1;	// コマンドＯＫ.
	} else {
		m_ss_CommandOkCount  = 0;	// コマンドＮＧ.
	}
	if ( (EP_Service_KeyCode_None == sp_MagicSequenceAdminPenaltyLockCancel[m_ss_CommandOkCount].ep_KeyCode)
	    && ( -1 == sp_MagicSequenceAdminPenaltyLockCancel[m_ss_CommandOkCount ].ss_Option ) ) {
	    	if ( 0 != ( 0x01 & getSwDipSwitch( DEFSOFTWARESW2 ) ) ) {
				bl_isFactoryThroughMode = True;
				nextGamen = &gp_ServiceMenu;	// 不揮発メモリクリア選択画面.
	   		}
	}
	return ( 0 == m_ss_CommandOkCount  ) ? False : True;	// カウントが０ならコマンド失敗なのでFalse を返す.
}
//=======================================================================================
//Summary: Service ・ Security setting ・ Administrator authentication unlocking: Stop key.
//note   : None.
//Param: short option.
// Returned value: None.
//=======================================================================================
void PServiceAdminiPenaltyLockCancel::procStop( uchar option )
{
	checkServiceMode( EP_Service_KeyCode_Stop, option );
	setBuzzerType( PCGE_BuzzerType_InputNg );
}
