Bool	PServiceHDDBackupRestoreInfo::bl_GeneralFormat = True;
uchar	PServiceHDDBackupRestoreInfo::uc_Password[ PNLD_HDDBackupPassMax + 1 ];

//===============================================================================================.
// 概要		：サービス・セキュリティ設定・HDDデータバックアップ：データクラス・初期化.
//===============================================================================================.
void PServiceHDDBackupRestoreInfo::initData()
{
	bl_GeneralFormat = True;
	memset( uc_Password, 0, sizeof( uc_Password ) );
}
//===============================================================================================.
// 概要		：サービス・セキュリティ設定・HDDデータバックアップ：共通クラス.
//===============================================================================================.

PNLE_HDDBackupRestoreSts	PServiceHDDBackupRestore::uc_BackupRestoreSts = PNLE_HDDBackupRestoreStsStop;

//===============================================================================================.
// 概要		：サービス・セキュリティ設定・HDDデータバックアップ：共通クラス・画面開始処理.
//===============================================================================================.
void PServiceHDDBackupRestore::startGamen()
{
	PBasicMessageProc::startGamen();

	bl_StsToggle = False;											// 進行状態表示トグルの初期化.
	// バージョンチェックによりテンキーを非表示にする.
	PServiceCom::CheckShowParts();
}
//===============================================================================================.
// 概要		：サービス・セキュリティ設定・HDDデータバックアップ：共通クラス・表示部品のセットアップ.
//===============================================================================================.
void PServiceHDDBackupRestore::setupGamen( short option )
{
	PServiceFunctionCom::setupGamen( option );

	Bool	bl_showStartKey = False;
	Bool	bl_showCancelKey = False;
	ushort	us_dispStatusMessage = s_Space1;
	ushort	us_dispProgMessage = s_Space1;
	ushort	us_dispNgMessage = s_Space1;
	Bool	bl_showOffOnMessage = False;
	uchar	uc_chkPass[ PNLD_HDDBackupPassMax + 1 ];
	memset( uc_chkPass, 0, sizeof( uc_chkPass ) );

	PServiceHDDBackupRestoreInfo::getPassword( uc_chkPass );

	switch( uc_BackupRestoreSts ) {
		case PNLE_HDDBackupRestoreStsStop:							//【バックアップ・リストア停止中】.
		{
			// USBメモリー挿入状態チェック.
			APIC_UsbMemDeviceInfo* pc_UsbMemDeviceInfo = APIC_UsbMemDeviceInfo::newInstance();
			if( NULL == pc_UsbMemDeviceInfo ) { 
//2019/06/17 Comment [HCLT_Krishnakumar][EagleH][N Rank] Removed unwanted detailed code.
//// 2015/11/05 【HCLT-Dhivya】 【ZeusS_ZX0】 【制御構成変更_No.76-1】Detail macro is passed in API.
//				LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//				if (NULL != pc_BFW_System){
//    				pc_BFW_System->registDetailCode(PNLD_DetailCode_Service_0x1900660101519201);
//				}
				LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" ); 
				return; 
			}
			if( True == pc_UsbMemDeviceInfo->isUsbMemDevice() ) {
				// パスワード入力状態チェック.
				if( ( '\0' != uc_chkPass[0] )
				    && ( False == PnlComGetSystemSetting()->getSecurityLevelUpOn() )						// セキュリティー強化モード OFF.
				    && ( True == PnlComGetSystemSetting()->getEnableHddDataBackup() ) ) {					// HDDデータバックアップが許可.
					bl_showStartKey = True;
				}
			} else {
				us_dispStatusMessage = s_ITMServiceUSBN_a;		// 「USB　NG」.
			}
		}
		break;

		case PNLE_HDDBackupRestoreStsProc:							//【バックアップ・リストア処理中】.
			bl_showCancelKey = True;
		case PNLE_HDDBackupRestoreStsFormatProc:					//【フォーマット処理中】 comment 2012/05/18 OPS1大西 [ZeusMLK][管理No.383/UV-01224]フォーマット処理中のcaseを追加.
			us_dispStatusMessage = s_ITMServiceOperating;			// 「実行中」.
			// 進行状態表示トグルに応じて表示更新.
			if( True == bl_StsToggle ) {
				us_dispProgMessage = s_EXPSlash;					// 「／」.
				bl_StsToggle = False;
			} else {
				us_dispProgMessage = s_EXPBackslash;				// 「＼」.
				bl_StsToggle = True;
			}
			Txt_HDDBackupRestoreProgress.changePosition( 249, 295 );
			break;

		case PNLE_HDDBackupRestoreStsFormatError:					//【フォーマット異常終了】.
			us_dispStatusMessage = s_MSGServiceHDDBackupResultNG;	// 「結果 NG」.
			us_dispNgMessage = s_MSGServiceFailedToFormat;			// 「ﾌｫｰﾏｯﾄに失敗しました」.
			bl_showOffOnMessage = True;								// 「必ず電源OFF/ONしてください」.
			break;

		case PNLE_HDDBackupRestoreStsCanselProc:					//【バックアップ・リストア中断中】.
			us_dispStatusMessage = s_MSGServiceItStops2;			// 「中止します」.
			// 進行状態表示トグルに応じて表示更新.
			if( True == bl_StsToggle ) {
				us_dispProgMessage = s_EXPSlash;					// 「／」.
				bl_StsToggle = False;
			} else {
				us_dispProgMessage = s_EXPBackslash;				// 「＼」.
				bl_StsToggle = True;
			}
			Txt_HDDBackupRestoreProgress.changePosition( 265, 295 );
			break;

		case PNLE_HDDBackupRestoreStsComplete:						//【バックアップ・リストア正常終了】.
			us_dispStatusMessage = s_MSGServiceHDDBackupResultOK;	// 「結果 OK」.
			bl_showOffOnMessage = True;								// 「必ず電源OFF/ONしてください」.
			break;

		case PNLE_HDDBackupRestoreStsCanselComp:					//【バックアップ・リストア中断終了】.
			us_dispStatusMessage = s_MSGServiceHDDBackupResultNG;	// 「結果 NG」.
			bl_showOffOnMessage = True;								// 「必ず電源OFF/ONしてください」.
			break;

		case PNLE_HDDBackupRestoreStsBackupCapaError:				//【バックアップ・リストア異常終了（バックアップ領域不足エラー）】.
			us_dispStatusMessage = s_MSGServiceHDDBackupResultNG;	// 「結果 NG」.
			us_dispNgMessage = s_MSGServiceBackupCapasityNG;		// 「バックアップ領域が不足しています」.
			bl_showOffOnMessage = True;								// 「必ず電源OFF/ONしてください」.
			break;

		case PNLE_HDDBackupRestoreStsRestoreCapaError:				//【バックアップ・リストア異常終了（リストア領域不足エラー）】.
			us_dispStatusMessage = s_MSGServiceHDDBackupResultNG;	// 「結果 NG」.
//comment [HCL-Sam Sundar] [IT6_Eagle] [RQ-537] - Changing the Symbol ID.
//			us_dispNgMessage = s_MSGServiceHddCapacityNG;			// 「HDDの容量が不足しています」.
			us_dispNgMessage = s_pMSGServicestorageCapacityNG_W296H016I;			// 「HDDの容量が不足しています」.
			bl_showOffOnMessage = True;								// 「必ず電源OFF/ONしてください」.
			break;

		case PNLE_HDDBackupRestoreStsSystemError:					//【バックアップ・リストア異常終了（システムエラー）】.
			us_dispStatusMessage = s_MSGServiceHDDBackupResultNG;	// 「結果 NG」.
			bl_showOffOnMessage = True;								// 「必ず電源OFF/ONしてください」.
			break;

// comment 2016/06/23 [MAv4][CQ530697]KMフォーマット選択時に汎用フォーマットでバックアップしたデータをリストアできない場合エラー表示する 日立 田中.
		case PNLE_HDDBackupRestoreStsRestoreSizeError:				//【バックアップ・リストア異常終了（リストアデータ使用不可）】.
			us_dispStatusMessage = s_MSGServiceHDDBackupResultNG;	// 「結果 NG」.
//comment [HCL-Sam Sundar] [IT6_Eagle] [RQ-537] - Changing the Symbol ID.
//			us_dispNgMessage = s_MSGServiceRestoreSizeNG;			// 「ボックス文書によるHDD容量不足です」.
			us_dispNgMessage = s_pMSGServiceRestoreSizeNG_HDDTextChange_W280H016I;			// 「ボックス文書によるHDD容量不足です」.
			bl_showOffOnMessage = True;								// 「必ず電源OFF/ONしてください」.
			break;

		default:
			break;
	}

	Key_HDDBackupRestoreStart.showEnable( bl_showStartKey );			// 「ｽﾀｰﾄ」キー表示更新.
	Key_HDDBackupRestoreCancel.showEnable( bl_showCancelKey );			// 「中止」キー表示更新.
	Txt_HDDBackupRestoreStatus.changeText( us_dispStatusMessage );		// バックアップ・リストア状態メッセージ表示更新.
	Txt_HDDBackupRestoreProgress.changeText( us_dispProgMessage );		// バックアップ・リストア進行メッセージ表示更新.
	Txt_HDDBackupRestoreNG.changeText( us_dispNgMessage );				// バックアップ・リストアNGメッセージ.
	Txt_HDDBackupRestorePowerOffOn.showEnable( bl_showOffOnMessage );	// 「必ず電源OFF/ONしてください」メッセージ表示更新.

	// パスワード表示／非表示.
	uchar uc_DispPass[ 10 + 1 ];
	memset( uc_DispPass, 0, sizeof( uc_DispPass ) );
	if( '\0' != uc_chkPass[0] ) {									// パスワードが入力されている時.
		memcpy( uc_DispPass , "**********", sizeof( uc_DispPass ) );
	}
	Btx_HDDBackupRestorePass.changeExternalText( uc_DispPass );
}
//===============================================================================================.
// 概要		：サービス・セキュリティ設定・HDDデータバックアップ：共通クラス・停止処理.
//===============================================================================================.
void PServiceHDDBackupRestore::procStop( uchar option )
{
	switch( option ) {
		case BTNID_KEY_HDDBackupRestoreStop:						// 「中止」キー押下.
		{
			// バックアップ・リストアのキャンセルを要求.
			APIC_Backup* pc_Backup = APIC_Backup::newInstance();
			if( NULL == pc_Backup ) { 
//2019/06/17 Comment [HCLT_Krishnakumar][EagleH][N Rank] Removed unwanted detailed code.
//// 2015/11/05 【HCLT-Dhivya】 【ZeusS_ZX0】 【制御構成変更_No.76-1】Detail macro is passed in API.
//				LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//				if (NULL != pc_BFW_System){
//    				pc_BFW_System->registDetailCode(PNLD_DetailCode_Service_0x1900290101519301);
//				}
				LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" ); 
				return; 
			}
			Bool bl_Result = pc_Backup->req_HddDataCancel();

			if( True == bl_Result ) {
				// バックアップ・リストア状態を中断中に更新.
				uc_BackupRestoreSts = PNLE_HDDBackupRestoreStsCanselProc;
			}
		}
		break;
		default:
			MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
			break;
	}
}
//===============================================================================================.
// 概要		：サービス・セキュリティ設定・HDDデータバックアップ：共通クラス・コールバック処理.
//===============================================================================================.
void PServiceHDDBackupRestore::procCallBack( TYPE_PNL_CallBack e_PNL_CallBack )
{
	// バックアップ・リストア状態を更新.
	switch( e_PNL_CallBack ) {
		case TYPE_PNL_CallBack_HddBackupResult_Ok:					// 正常終了.
			uc_BackupRestoreSts = PNLE_HDDBackupRestoreStsComplete;
			break;
		case TYPE_PNL_CallBack_HddBackupResult_Cancel:				// 中断終了.
			uc_BackupRestoreSts = PNLE_HDDBackupRestoreStsCanselComp;
			break;
		case TYPE_PNL_CallBack_HddBackupResult_BackupCapaError:		// 正常終了（バックアップ領域不足エラー）.
			uc_BackupRestoreSts = PNLE_HDDBackupRestoreStsBackupCapaError;
			break;
		case TYPE_PNL_CallBack_HddBackupResult_RestoreCapaError:	// 正常終了（リストア領域不足エラー）.
			uc_BackupRestoreSts = PNLE_HDDBackupRestoreStsRestoreCapaError;
			break;
		case TYPE_PNL_CallBack_HddBackupResult_SystemError:			// 正常終了（システムエラー）.
			uc_BackupRestoreSts = PNLE_HDDBackupRestoreStsSystemError;
			break;
// comment 2016/06/23 [MAv4][CQ530697]KMフォーマット選択時に汎用フォーマットでバックアップしたデータをリストアできない場合エラー表示する 日立 田中.
		case TYPE_PNL_CallBack_HddBackupResult_RestoreSizeError:	// 正常終了（リストアデータ使用不可）.
			uc_BackupRestoreSts = PNLE_HDDBackupRestoreStsRestoreSizeError;
			break;
		default:
			break;
	}
}
//===============================================================================================.
// 概要		：サービス・セキュリティ設定・HDDデータバックアップ：共通クラス・OKボタン押下時の処理.
//===============================================================================================.
void PServiceHDDBackupRestore::procOk( uchar option )
{
	// 97000_セキュリティー設定／メニュー画面に遷移.
	nextGamen = &gp_ServiceSecuritySettingMenu;
}
//===============================================================================================.
// 概要		：サービス・セキュリティ設定・HDDデータバックアップ：共通クラス・タブ押下時処理.
//===============================================================================================.
void PServiceHDDBackupRestore::procIndexButton( uchar option )
{
	uchar uc_initPass[ PNLD_HDDBackupPassMax + 1 ];
	memset( uc_initPass, 0, sizeof( uc_initPass ) );

	// パスワードとフォーマット形式を更新.
	switch( option ) {
		case BTNID_KEY_HDDBackupGeneralFormat:						//「汎用ﾌｫｰﾏｯﾄﾊﾞｯｸｱｯﾌﾟ」キー.
			PServiceHDDBackupRestoreInfo::setPassword( uc_initPass );
			PServiceHDDBackupRestoreInfo::setFormat( True );
			break;
		case BTNID_KEY_HDDBackupInternalFormat:						//「内部ﾌｫｰﾏｯﾄﾊﾞｯｸｱｯﾌﾟ」キー.
			PServiceHDDBackupRestoreInfo::setPassword( uc_initPass );
			PServiceHDDBackupRestoreInfo::setFormat( False );
			break;
		case BTNID_KEY_HDDRestore:									//「ﾘｽﾄｱ」キー.
			PServiceHDDBackupRestoreInfo::setPassword( uc_initPass );
			break;
		default:
			break;
	}
}
//===============================================================================================.
// 概要		：サービス・セキュリティ設定・HDDデータバックアップ・バックアップ.
//===============================================================================================.

short PServiceHDDBackup::ss_FormatBackupResult = -1;

//関数------------------------------------------------------------------------------------------------------------------.
//概要    ：画面開始処理.
//備考    ：.
//戻値    ：なし.
//作成者  ：OPS1大西.
//===============================================================================================.
// 概要		：サービス・セキュリティ設定・HDDデータバックアップ・バックアップ：画面開始処理.
//===============================================================================================.
void PServiceHDDBackup::startGamen()
{
	PServiceHDDBackupRestore::startGamen();

	// フォーマット/バックアップ結果未処理の場合は処理する.
	// 全画面警告中にコールバックが返ってきていた場合の処理.
	if( -1 != ss_FormatBackupResult ) {
		procCallBack( ss_FormatBackupResult );
	}
}
//関数------------------------------------------------------------------------------------------------------------------.
//概要    ：アクティブ状態の通知.
//備考    ：.
//戻値    ：なし.
//作成者  ：OPS1大西.
//================================================================================================.
// 概要		：サービス・セキュリティ設定・HDDデータバックアップ・バックアップ：アクティブ状態の通知.
//================================================================================================.
void PServiceHDDBackup::procActivate()
{
	// フォーマット/バックアップ結果未処理の場合は処理する.
	// 全画面警告中にコールバックが返ってきていた場合の処理.
	if( -1 != ss_FormatBackupResult ) {
		procCallBack( ss_FormatBackupResult );
	}
}
//===============================================================================================.
// 概要		：サービス・セキュリティ設定・HDDデータバックアップ・バックアップ：表示部品のセットアップ.
//===============================================================================================.
void PServiceHDDBackup::setupGamen( short option )
{
	PServiceHDDBackupRestore::setupGamen( option );

	// フォーマット形式の表示を更新.
	if( True == PServiceHDDBackupRestoreInfo::getFormat() ) {
		Rbt_HDDBackupRestoreMenu.select( 0 );								// 「汎用ﾌｫｰﾏｯﾄﾊﾞｯｸｱｯﾌﾟ」キー選択.
		Txt_TitleHDDFormat.changeText( s_TTLServiceGeneralFormatBackup );	// 「汎用ﾌｫｰﾏｯﾄﾊﾞｯｸｱｯﾌﾟ」タイトル.
	} else {
		Rbt_HDDBackupRestoreMenu.select( 1 );								// 「内部ﾌｫｰﾏｯﾄﾊﾞｯｸｱｯﾌﾟ」キー選択.
		Txt_TitleHDDFormat.changeText( s_TTLServiceKMFormatBackup );		// 「内部ﾌｫｰﾏｯﾄﾊﾞｯｸｱｯﾌﾟ」タイトル.
	}
}
//===============================================================================================.
// 概要		：サービス・セキュリティ設定・HDDデータバックアップ・バックアップ：スタートキー押下処理.
//===============================================================================================.
void PServiceHDDBackup::procStart( uchar option )
{
	switch( option ) {
		case BTNID_KEY_HDDBackupRestoreStart:								// 「ｽﾀｰﾄ」キー押下.
		{
			// フォーマット開始時処理.
			uc_BackupRestoreSts = PNLE_HDDBackupRestoreStsFormatProc;		// バックアップ状態をフォーマット処理中に更新.
			bl_NoAcceptBtnFlag = True;										// キー入力/画面遷移の受付を不可にする.

			// フォーマット開始要求.
			Bool bl_Result = PnlComGetHddInfo()->req_FormatOfUsbHdd( ans_FormatOfUsbHdd );
			if( False == bl_Result ) {										// フォーマット開始要求NGの場合.
				uc_BackupRestoreSts = PNLE_HDDBackupRestoreStsFormatError;	// バックアップ状態をフォーマット異常終了に更新.
			}
		}
		onlyPanel.bl_PowerOffOnMesage = True;
		turnGamen = NULL;
		break;
		default:
			MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
			break;
	}
}
//関数------------------------------------------------------------------------------------------------------------------.
//概要    ：フォーマット・コールバック関数.
//備考    ：.
//戻値    ：なし.
//作成者  ：OPS1大西.
//===============================================================================================.
// 概要		：サービス・セキュリティ設定・HDDデータバックアップ・バックアップ：フォーマット・コールバック関数.
//===============================================================================================.
void PServiceHDDBackup::ans_FormatOfUsbHdd( TYPE_FormatUsbHddResult e_Result, int si_errno )
{
	switch( e_Result ) {
		case TYPE_FormatUsbHddResult_OK:													//【フォーマット成功】.
			ss_FormatBackupResult = TYPE_PNL_CallBack_HddFormatResult_Ok;
			break;
		case TYPE_FormatUsbHddResult_DevChkErr:												//【フォーマット失敗：デバイス検出エラー】.
		case TYPE_FormatUsbHddResult_UmountErr:												//【フォーマット失敗：アンマウントエラー】.
		case TYPE_FormatUsbHddResult_PartErr:												//【フォーマット失敗：パーティションエラー】.
		case TYPE_FormatUsbHddResult_FormatErr:												//【フォーマット失敗：フォーマットエラー】.
		case TYPE_FormatUsbHddResult_MountErr:												//【フォーマット失敗：マウントエラー】.
			ss_FormatBackupResult = TYPE_PNL_CallBack_HddFormatResult_Error;
			break;
		default:																			//【例外】.
			ss_FormatBackupResult = TYPE_PNL_CallBack_HddFormatResult_Error;
			break;
	}

	CallBackIndi( ss_FormatBackupResult );
}
//関数------------------------------------------------------------------------------------------------------------------.
//概要    ：コールバック処理.
//備考    ：.
//戻値    ：なし.
//作成者  ：OPS1大西.
//===============================================================================================.
// 概要		：サービス・セキュリティ設定・HDDデータバックアップ・バックアップ：コールバック処理.
//===============================================================================================.
void PServiceHDDBackup::procCallBack( TYPE_PNL_CallBack e_PNL_CallBack )
{
	switch( e_PNL_CallBack ) {
		case TYPE_PNL_CallBack_HddFormatResult_Ok:								//【フォーマット：成功】.
		{
			// バックアップフォーマット形式を取得.
			TYPE_HddDataBackupFileFormat en_BackupFormat = TYPE_HddDataBackupFileFormat_GeneralPurpose;
			if( True == PServiceHDDBackupRestoreInfo::getFormat() ) {
				en_BackupFormat = TYPE_HddDataBackupFileFormat_GeneralPurpose;
			} else {
				en_BackupFormat = TYPE_HddDataBackupFileFormat_Inside;
			}

			// バックアップパスワードを取得.
			uchar uc_BackupPass[ PNLD_HDDBackupPassMax + 1 ];
			memset( uc_BackupPass, 0, sizeof( uc_BackupPass ) );
			PServiceHDDBackupRestoreInfo::getPassword( uc_BackupPass );

			// バックアップ開始時処理.
			uc_BackupRestoreSts = PNLE_HDDBackupRestoreStsProc;				// バックアップ状態をバックアップ処理中に更新.
			ss_FormatBackupResult = -1;										// フォーマット結果を処理済みに更新.

			// バックアップを要求.
			Bool bl_Result = PnlComGetBackup()->req_HddDataBackup( en_BackupFormat, uc_BackupPass, ans_HddDataBackup );
			if( False == bl_Result ) {
				uc_BackupRestoreSts = PNLE_HDDBackupRestoreStsSystemError;	// バックアップ状態をバックアップ異常終了に更新.
			}
		}
		break;
		case TYPE_PNL_CallBack_HddFormatResult_Error:							//【フォーマット：失敗】.
			uc_BackupRestoreSts = PNLE_HDDBackupRestoreStsFormatError;			// バックアップ状態をフォーマット異常終了に更新.
			ss_FormatBackupResult = -1;											// フォーマット結果を処理済みに更新.
			break;
		default:
			// バックアップ完了時のコールバックメッセージ処理（リストアと共通）.
			PServiceHDDBackupRestore::procCallBack( e_PNL_CallBack );
			ss_FormatBackupResult = -1;											// バックアップ結果を処理済みに更新.
			break;
	}
}
//===============================================================================================.
// 概要		：サービス・セキュリティ設定・HDDデータバックアップ・バックアップ：バックアップ・コールバック関数.
//===============================================================================================.
void PServiceHDDBackup::ans_HddDataBackup( TYPE_HddDataBackupResult e_Result )
{
	switch( e_Result ) {
		case TYPE_HddDataBackupResult_Ok:													//【バックアップ成功】.
			ss_FormatBackupResult = TYPE_PNL_CallBack_HddBackupResult_Ok;
			break;
		case TYPE_HddDataBackupResult_Cancel:												//【バックアップ中断】.
			ss_FormatBackupResult = TYPE_PNL_CallBack_HddBackupResult_Cancel;
			break;
		case TYPE_HddDataBackupResult_Error:												//【バックアップ失敗】.
		{
			APIC_UsbMemDeviceInfo* pc_UsbMemDeviceInfo = APIC_UsbMemDeviceInfo::newInstance();
//2019/06/17 Comment [HCLT_Krishnakumar][EagleH][N Rank] Removed unwanted detailed code.
//// 2015/11/05 【HCLT-Dhivya】 【ZeusS_ZX0】 【制御構成変更_No.76-1】Detail macro is passed in API.
//			LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
			if( NULL == pc_UsbMemDeviceInfo ) { 
//2019/06/17 Comment [HCLT_Krishnakumar][EagleH][N Rank] Removed unwanted detailed code.
//				if (NULL != pc_BFW_System){
//				    pc_BFW_System->registDetailCode(PNLD_DetailCode_Service_0x1900690101519401);
//				}
				LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" ); 
				return; 
			}
			APIC_Backup* pc_Backup = APIC_Backup::newInstance();
			if( NULL == pc_Backup ) { 
//2019/06/17 Comment [HCLT_Krishnakumar][EagleH][N Rank] Removed unwanted detailed code.
//				if (NULL != pc_BFW_System){
//				    pc_BFW_System->registDetailCode(PNLD_DetailCode_Service_0x1900690101519501);
//				}
				LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" ); 
				return; 
			}

			STATUS  e_Result 		= ERROR;											// USB空き容量取得結果.
			Bool	bl_CapaCheck	= False;											// USB空き容量確認用変数.
			char**	ppsc_device		= NULL;												// デバイス名取得用ポインタ.
			char*	psc_device		= NULL;												// デバイス名取得用ポインタ.
			char	sc_device[ PNLD_DeviceNameMax ];									// デバイス名格納用配列.
			memset( sc_device, 0, PNLD_DeviceNameMax );

			// USB空き容量の取得.
			ppsc_device = &psc_device;
			*ppsc_device = sc_device;
			SYSC_GetBulkDeviceNames( ppsc_device, 1 );									// デバイス名の取得.
			e_Result = pc_UsbMemDeviceInfo->checkFreeSpaceOfHddBackup( sc_device, &bl_CapaCheck );	// USB空き容量の取得.


			// バックアップ領域不足チェック.
			if( ( ( e_Result == OK ) && ( False == bl_CapaCheck ) ) ||				// USB容量不足.
			    ( False == pc_Backup->getHddCapacityLackCheckResult() ) ) {			// 事前チェックによるUSB容量不足.
				ss_FormatBackupResult = TYPE_PNL_CallBack_HddBackupResult_BackupCapaError;

				// その他のエラー.
			} else {
				ss_FormatBackupResult = TYPE_PNL_CallBack_HddBackupResult_SystemError;
			}
		}
		break;
		default:																			//【例外】.
			ss_FormatBackupResult = TYPE_PNL_CallBack_HddBackupResult_SystemError;
			break;
	}

	CallBackIndi( ss_FormatBackupResult );
}
