//===============================================================================================.
// 概要		：サービス・セキュリティ設定・HDDデータバックアップ・バックアップパスワード入力：表示部品のセットアップ.
//===============================================================================================.
void PServiceHDDBackupPassInput::setupGamen( short option )
{
	// キーボードの表示を設定（"ユーロ文字を非表示）.
	PServicePasswordSettingCom::setupGamenSetup( KC_DisableKeyPattern15 );	// 禁止文字パターン15("ユーロ記号).
	PServicePasswordSettingCom::setupGamen( option );

	// フォーマット形式の表示を更新.
	if( True == PServiceHDDBackupRestoreInfo::getFormat() ) {
		Txt_TitleHDDFormat_PassInput.changeText( s_TTLServiceGeneralFormatBackup );	// 「汎用ﾌｫｰﾏｯﾄﾊﾞｯｸｱｯﾌﾟ」タイトル.
	} else {
		Txt_TitleHDDFormat_PassInput.changeText( s_TTLServiceKMFormatBackup );		// 「内部ﾌｫｰﾏｯﾄﾊﾞｯｸｱｯﾌﾟ」タイトル.
	}
}
