//===============================================================================================.
// 概要		：サービス・セキュリティ設定・HDDデータバックアップ・リストア：スタートキー押下処理.
//===============================================================================================.
void PServiceDataMigrationRestore::procStart( uchar option )
{
	if( True == ( APIC_NetworkDevice::newInstance()->isNetworkInitialing() ) ) {
		//ネットワーク初期化中は拒否音を出す.
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
	} else {
		//ネットワーク初期化完了.
		switch( option ) {
			case BTNID_KEY_DataMigrationBackupRestoreStart:						// 「ｽﾀｰﾄ」キー押下.
			{
				// リストアパスワードを取得.
				uchar uc_RestorePass[ PNLD_HDDBackupPassMax + 1 ];
				memset( uc_RestorePass, 0, sizeof( uc_RestorePass ) );
				PServiceDataMigrationBackupRestoreInfo::getPassword( uc_RestorePass );

				// リストアを要求.
				APIC_Backup* pc_Backup = APIC_Backup::newInstance();		//API issue
				if( NULL == pc_Backup ) {
//2019/06/17 Comment [HCLT_Krishnakumar][EagleH][N Rank] Removed unwanted detailed code.
//					LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//					if (NULL != pc_BFW_System){
//    					pc_BFW_System->registDetailCode(PNLD_DetailCode_Service_0x1900280101519601);
//					}
					LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" ); 
					return; 
				}
// Comment 05/07/2018 HCLT-Jagadeesh [IT6_Eagle] [制御構成変更_No.101] Ssd data migration Restore Request API change.
//				Bool bl_Result = PnlComGetSsdDataTransfer()->reqRestore( (char*)uc_RestorePass, ans_HddDataRestore );
				Bool bl_Result = PnlComGetSsdDataTransfer()->reqRestore( (char*)uc_RestorePass, ans_SsdDataRestore );
				if( True == bl_Result ) {
					uc_BackupRestoreSts = PNLE_HDDBackupRestoreStsProc;		// バックアップ・リストア状態を処理中に更新.
					bl_NoAcceptBtnFlag = True;								// キー入力/画面遷移の受付を不可にする.
					onlyPanel.bl_PowerOffOnMesage = True;
					turnGamen = NULL;
				}
			}
			break;
			default:
				MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
				break;
		}
	}
}
//===============================================================================================.
// 概要		：サービス・セキュリティ設定・HDDデータバックアップ・バックアップ：コールバック処理.
//===============================================================================================.
void PServiceDataMigrationRestore::procCallBack( TYPE_PNL_CallBack e_PNL_CallBack )
{
	// リストア完了時のコールバックメッセージ処理（リストアと共通）.
	PServiceDataMigrationBackupRestore::procCallBack( e_PNL_CallBack );
	ss_RestoreResult = -1;													// リストア結果を処理済みに更新.
}
// Comment 05/07/2018 HCLT-Jagadeesh [IT6_Eagle] [制御構成変更_No.101] Ssd data migration Restore callback resopnse function change.
//void PServiceDataMigrationRestore::ans_HddDataRestore( Bool e_Result )
void PServiceDataMigrationRestore::ans_SsdDataRestore( TYPE_SsdDataTransferResult e_Result )
{
	switch( e_Result ) {
//		case True:																		//【バックアップ成功】.
		case TYPE_SsdDataTransferResult_Ok:												//【Restore Success】.
			ss_RestoreResult = TYPE_PNL_CallBack_HddBackupResult_Ok;
			break;
// Comment 05/07/2018 HCLT-Jagadeesh [IT6_Eagle] [制御構成変更_No.101] Ssd data migration Backup callback Result update for Cancel.
		case TYPE_SsdDataTransferResult_Cancel:											//【Restore Abort/Cancel】.
			ss_RestoreResult = TYPE_PNL_CallBack_HddBackupResult_Cancel;
			break;
//		case False:																		//【バックアップ失敗】.
		case TYPE_SsdDataTransferResult_Ng:												//【Restore Fail】.
		{
			APIC_UsbMemDeviceInfo* pc_UsbMemDeviceInfo = APIC_UsbMemDeviceInfo::newInstance();
//2019/06/17 Comment [HCLT_Krishnakumar][EagleH][N Rank] Removed unwanted detailed code.
//			LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
			if( NULL == pc_UsbMemDeviceInfo ) { 
//2019/06/17 Comment [HCLT_Krishnakumar][EagleH][N Rank] Removed unwanted detailed code.
//				if (NULL != pc_BFW_System){
//   					pc_BFW_System->registDetailCode(PNLD_DetailCode_Service_0x1900690101519701);
//				}
				LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" ); 
				return; 
			}
			APIC_HddInfo* pc_HddInfo = APIC_HddInfo::newInstance();
			if( NULL == pc_HddInfo ) { 
//2019/06/17 Comment [HCLT_Krishnakumar][EagleH][N Rank] Removed unwanted detailed code.
//				if (NULL != pc_BFW_System){
//   					pc_BFW_System->registDetailCode(PNLD_DetailCode_Service_0x1900690101519801);
//				}
				LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" ); 
				return; 
			}
			APIC_Backup* pc_Backup = APIC_Backup::newInstance();
			if( NULL == pc_Backup ) { 
//2019/06/17 Comment [HCLT_Krishnakumar][EagleH][N Rank] Removed unwanted detailed code.
//				if (NULL != pc_BFW_System){
//   					pc_BFW_System->registDetailCode(PNLD_DetailCode_Service_0x1900690101519901);
//				}
				LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" ); 
				return; 
			}

			// リストア領域不足チェック.
			if( ( TYPE_HddStatusFull == pc_HddInfo->getHddStatus() ) || 		// MFP HDD容量不足.
			    ( False == pc_Backup->getHddCapacityLackCheckResult() ) ) {		// 事前チェックによるMFP HDD容量不足.
				ss_RestoreResult = TYPE_PNL_CallBack_HddBackupResult_RestoreCapaError;

			} else if( True == pc_Backup->getHddDataRestoreSizeError() ) {		// リストアするサイズとMFP本体のサイズが異なる.
				ss_RestoreResult = TYPE_PNL_CallBack_HddBackupResult_RestoreSizeError;

				// その他のエラー.
			} else {
				ss_RestoreResult = TYPE_PNL_CallBack_HddBackupResult_SystemError;
			}
		}
		break;
		default:																		//【例外】.
			ss_RestoreResult = TYPE_PNL_CallBack_HddBackupResult_SystemError;
			break;
	}
	CallBackIndi( ss_RestoreResult );
}

