void PServiceSecuritySettingTPMCom::procGoToPage( uchar option )
{
	if( False == bl_isKeyAccept ) {
		setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}
	switch( option ) {
		case BTNID_ServiceSecurityTPMInitialize:		// 初期化.
			nextGamen = &gp_ServiceSecuritySettingTPMInitialize;		// D0B0097090 セキュリティ設定・TPM設定・初期化.
			break;
		case BTNID_ServiceSecurityTPMSelfCheckReport:	// 自己診断ﾚﾎﾟｰﾄ.
			nextGamen = &gp_ServiceSecuritySettingTPMSelfCheckReport;	// D0B0097091 セキュリティ設定・TPM設定・ｽﾃｰﾀｽﾚﾎﾟｰﾄ.
			break;
		default: break;
	}
}
