PNLE_ServiceTPMInitState PServiceSecuritySettingTPMInitialize::e_InitialStatus = PNLE_ServiceTPMInitStateDefault;
//================================================================================================.
// 概要		: D0B0097090  : セキュリティー設定／TPM設定／初期化 画面開始処理.
// 戻り値	:なし.
// 備考		:.
//================================================================================================.
void PServiceSecuritySettingTPMInitialize::startGamen()
{
	PServiceSecuritySettingTPMCom::startGamen();			// 親クラスをコールする.
	e_InitialStatus = PNLE_ServiceTPMInitStateDefault;		// 初期化状態変数を未処理にする.
}
//================================================================================================.
// 概要		: D0B0097090  : セキュリティー設定／TPM設定／初期化 セットアップ処理.
// 戻り値	:なし.
// 備考		:.
//================================================================================================.
void PServiceSecuritySettingTPMInitialize::setupGamen( short option )
{
	PServiceSecuritySettingTPMCom::setupGamen( option );

	Rbt_ServiceTPMSettingMenu.select( 0 );			// TPM設定メニュー・初期化キー選択.

	// スタートＬＥＤ制御.
	if( ( PNLE_ServiceTPMInitStateRunning == e_InitialStatus ) || ( PNLE_ServiceTPMInitStateOK == e_InitialStatus ) ) {
		printLEDControl( False );	// スタートキーＬＥＤの制御(赤).
	} else {
		printLEDControl( True );	// スタートキーＬＥＤの制御(緑).
	}

	// 状態表示.
	if( PNLE_ServiceTPMInitStateRunning == e_InitialStatus ) {
		// 初期化実行中.
		static Bool bl_InitNow = False;
		Txt_ServiceTPMInitProgress.changeText( True == bl_InitNow ? s_EXPSlash : s_EXPBackslash );
		Txt_ServiceTPMInitProgress.showEnable( True );
		bl_InitNow = ( True == bl_InitNow ) ? False : True;			// 「／」「＼」を交互に表示.
		Txt_ServiceTPMInitStatus.changeText( s_ITMServiceRunning );	// 「実行中」.
		Txt_ServiceTPMInitStatus.showEnable( True );				// 初期化結果表示.
		Grp_ServiceTPMInitMsgPowerOffOn.showEnable( False );		// 「↓」「必ず電源OFF/ONしてください」非表示.
	} else if( PNLE_ServiceTPMInitStateOK == e_InitialStatus ) {
		// 結果OK.
		Txt_ServiceTPMInitProgress.showEnable( False );				// 「／」「＼」非表示.
		Txt_ServiceTPMInitStatus.changeText( s_OKService );			// 「OK」.
		Txt_ServiceTPMInitStatus.showEnable( True );				// 初期化結果表示.
		Grp_ServiceTPMInitMsgPowerOffOn.showEnable( True );			// 「↓」「必ず電源OFF/ONしてください」表示.
	} else if( PNLE_ServiceTPMInitStateNG == e_InitialStatus ) {
		// 結果NG.
		Txt_ServiceTPMInitProgress.showEnable( False );				// 「／」「＼」非表示.
		Txt_ServiceTPMInitStatus.changeText( s_NGService );			// 「NG」.
		Txt_ServiceTPMInitStatus.showEnable( True );				// 初期化結果表示.
		Grp_ServiceTPMInitMsgPowerOffOn.showEnable( False );		// 「↓」「必ず電源OFF/ONしてください」非表示.
	} else {
		Txt_ServiceTPMInitProgress.showEnable( False );				// 「／」「＼」非表示.
		Txt_ServiceTPMInitStatus.showEnable( False );				// 初期化結果非表示.
		Grp_ServiceTPMInitMsgPowerOffOn.showEnable( False );		// 「↓」「必ず電源OFF/ONしてください」非表示.
	}
}
//================================================================================================.
// 概要		: D0B0097090  : セキュリティー設定／TPM設定／初期化 スタート押下.
// 戻り値	:なし.
// 備考		:.
//================================================================================================.
void PServiceSecuritySettingTPMInitialize::procStart( uchar option )
{
	if( False == printStartDisable() ) {			// スタートLED緑のとき.
		e_InitialStatus = PNLE_ServiceTPMInitStateRunning;		// 初期化中を設定する.
		bl_isKeyAccept = False;					// キー受付「不可」を設定.
		APIC_TPM* pc_TPM = PnlComGetTPM();
		if( NULL == pc_TPM ) {
//2019/06/17 Comment [HCLT_Krishnakumar][EagleH][N Rank] Removed unwanted detailed code.
//// 2015/11/05 【HCLT-Dhivya】 【ZeusS_ZX0】 【制御構成変更_No.76-1】Detail macro is passed in API.
//			LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//			if (NULL != pc_BFW_System){
//    			pc_BFW_System->registDetailCode(PNLD_DetailCode_Service_0x1900280101470001);
//			}			
			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" ); 
			return; 
		}
		pc_TPM->req_InitTPM( ans_TPMInitialize );		// TPM初期化要求.
	} else {
		setBuzzerType( PCGE_BuzzerType_InputNg );
	}
}
//================================================================================================.
// 概要		: D0B0097090  : セキュリティー設定／TPM設定／初期化 コールバック関数.
// 戻り値	:なし.
// 備考		:.
//================================================================================================.
void PServiceSecuritySettingTPMInitialize::ans_TPMInitialize( TYPE_TPMResult e_TPMResult )
{
	if( TYPE_TPMResult_SUCCESS == e_TPMResult ) {
		e_InitialStatus = PNLE_ServiceTPMInitStateOK;			// 初期化成功.
	} else {
		e_InitialStatus = PNLE_ServiceTPMInitStateNG;			// 初期化失敗.
		bl_isKeyAccept = True;		// キー受付「可」を設定.
	}
}

PNLE_ServiceTPMSelfCheckUSBSaveState PServiceSecuritySettingTPMSelfCheckReport::e_USBSaveStatus = PNLE_ServiceTPMSelfCheckUSBSaveStateDefault;
Bool PServiceSecuritySettingTPMSelfCheckReport::bl_isWaitPrint = False;
//================================================================================================.
// 概要		: D0B0097091  : セキュリティー設定／TPM設定／ｽﾃｰﾀｽﾚﾎﾟｰﾄ 画面開始処理.
// 戻り値	:なし.
// 備考		:.
//================================================================================================.
void PServiceSecuritySettingTPMSelfCheckReport::startGamen()
{
	PServiceSecuritySettingTPMCom::startGamen();	// 親クラスをコールする.
	e_USBSaveStatus = PNLE_ServiceTPMSelfCheckUSBSaveStateDefault;		// 未処理状態にする.
	sc_OutputKeySelected = 0;		// リスト出力を選択状態にする.
	bl_isWaitPrint = False;			// スタート押下後プリント開始まで立っているフラグ.
	e_FeedTrayListPrint = TYPE_FeedTrayUnselect;	// リスト出力トレイ.
// comment 2015/07/29 HCLT-Ezhil [ZeusS_ZX0][RQ-163][WP1400] Display condition of USB Storage Key.	
// Comment 2017/11/29 【HCLT-Vishal】【Eagle】【制御構成変更_No.4】 Removing old function version check condition.
	PNLC_USBConnectionPermission c_UsbPermission;
	PNLE_EnableUSBConnectionPermissionForAll e_usbAll = c_UsbPermission.getEnableUSBConnectionPermissionForAll();
	PNLE_EnableUSBConnectionPermissionForService e_usbforService = c_UsbPermission.getEnableUSBConnectionPermissionForService();
	if(( PNLE_EnableUSBConnectionPermissionForAll_Disable == e_usbAll ) || ( PNLE_EnableUSBConnectionPermissionForService_Disable == e_usbforService )) {
		m_bl_USBConnectionPermissionFlag = False;
	} else {
		m_bl_USBConnectionPermissionFlag = True;
	}
	// ファンクションコード設定(リスト出力において本来は不要だがスタートLEDを緑点灯するのための共通関数で何かがセットされている必要があるので、適当にセットする).
	setFunctionCode( TYPD_FNC_Counter );	// ファンクションコード設定.
}
//================================================================================================.
// 概要		: D0B0097091  : セキュリティー設定／TPM設定／ｽﾃｰﾀｽﾚﾎﾟｰﾄ USBメモリ有効無効チェック.
// 戻り値	:なし.
// 備考		:.
//================================================================================================.
Bool PServiceSecuritySettingTPMSelfCheckReport::isEnableListToUSB()
{
	APIC_SystemInfo* pc_SystemInfo = APIC_SystemInfo::newInstance();
	APIC_UsbMemDeviceInfo* pc_UsbMemDeviceInfo = APIC_UsbMemDeviceInfo::newInstance();
	Bool bl_Result = True;

	// USBホスト基盤装着確認.
	if( False == pc_SystemInfo->isUSBHostExist() ) {
		bl_Result = False;
	}
	// USBメモリー複数検知の場合.
	if( True == pc_UsbMemDeviceInfo->isWarning( TYPE_UsbMemWarningTwoInsert ) ) {
		bl_Result = False;
	}
	// USBメモリーが接続されていない、未対応USBが装着されている場合.
	if( False == pc_UsbMemDeviceInfo->isUsbMemDevice()	// USB非装着.
	    || True == PnlComGetSystemStatus()->getNotSupportUSBConnectBsp()		// 未対応USB（BSP用）.
	    || True == PnlComGetSystemStatus()->getNotSupportUSBConnectSaa() ) {	// 未対応USB（SAA用）.
		bl_Result = False;
	}
	return bl_Result;
}
//================================================================================================.
// 概要		: D0B0097091  : セキュリティー設定／TPM設定／ｽﾃｰﾀｽﾚﾎﾟｰﾄ セットアップ処理.
// 戻り値	:なし.
// 備考		:.
//================================================================================================.
void PServiceSecuritySettingTPMSelfCheckReport::setupGamen( short option )
{
	PServiceSecuritySettingTPMCom::setupGamen( option );

	Rbt_ServiceTPMSettingMenu.select( 1 );							// TPM設定メニュー・ｽﾃｰﾀｽﾚﾎﾟｰﾄキー選択.
	Rbt_ServiceTPMSelfCheckRep.select( sc_OutputKeySelected );		// 出力方式キー選択.

	APIC_ActiveJobList* pc_ActiveJobList = APIC_ActiveJobList::newInstance();
	APIC_Job* pc_currentJob = pc_ActiveJobList->getCurrentPrintJob();
	// プリント完了を監視.
	if( False == bl_isKeyAccept			// キー受付「不可」中.
	    && False == bl_isWaitPrint			// 画像生成中ではない.
	    && 1 != sc_OutputKeySelected		// USB保存ではない.
	    && NULL == pc_currentJob ) {		// 実行中のプリントジョブが無い.
		CallBackIndi( TYPE_PNL_CallBack_functionEnd );		// コールバックイベント発生.
	}
// comment 2015/07/29 HCLT-Ezhil [ZeusS_ZX0][RQ-163][WP1400] Display condition of USB Storage Key.	
// Comment 2017/11/29 【HCLT-Vishal】【Eagle】【制御構成変更_No.4】 Removing old function version check condition.
	if( True == m_bl_USBConnectionPermissionFlag ) {
		Key_ServiceTPMSelfCheckRepUSBSave.showEnable(True);			//USB保存キー表示.
	} else {
		Key_ServiceTPMSelfCheckRepUSBSave.showEnable(False);		//USB保存キー非表示.
	}
	// 状態表示.
	if( EP_PNS_Setting != onlyPanel.ep_PanelStatus						// 設定状態ではない.
	    || True == bl_isWaitPrint											// 画像生成中.
	    || PNLE_ServiceTPMSelfCheckUSBSaveStateSaving == e_USBSaveStatus	// USB保存中.
	    || NULL != pc_currentJob ) {										// プリントジョブ動作中.
		// 動作中.
		printLEDControl( False );		// スタートキーＬＥＤの制御(赤).
		if( 1 == sc_OutputKeySelected ) {
			// USB保存.
			static Bool bl_SaveNow = False;
			Txt_ServiceTPMSelfCheckRepProgress.changeText( True == bl_SaveNow ? s_EXPSlash : s_EXPBackslash );
			Txt_ServiceTPMSelfCheckRepProgress.showEnable( True );
			bl_SaveNow = ( True == bl_SaveNow ) ? False : True;					// 「／」「＼」交互表示.
			Txt_ServiceTPMSelfCheckRepStatus.changeText( s_ITMServiceSaving );	// 「保存中」.
			Txt_ServiceTPMSelfCheckRepStatus.showEnable( True );
			Txt_ServiceTPMSelfCheckRepDownArrow.showEnable( True );				// 「↓」表示.
		} else {
			// ﾘｽﾄ出力.
			Txt_ServiceTPMSelfCheckRepProgress.showEnable( False );				// 「／」「＼」非表示.
			Txt_ServiceTPMSelfCheckRepStatus.showEnable( False );
			Txt_ServiceTPMSelfCheckRepDownArrow.showEnable( False );			// 「↓」非表示.
		}
	} else {
		// 停止中.
		if( 1 == sc_OutputKeySelected ) {
			// USB保存.
			if( False == isEnableListToUSB() ) {
				// USB未挿入またはUSBに問題あり状態.
				printLEDControl( False ) ;		// スタートキーＬＥＤの制御.
				Txt_ServiceTPMSelfCheckRepProgress.showEnable( False );
				Txt_ServiceTPMSelfCheckRepStatus.changeText( s_ITMServiceUSBN_a );	// 「USB NG」.
				Txt_ServiceTPMSelfCheckRepStatus.showEnable( True );
				Txt_ServiceTPMSelfCheckRepDownArrow.showEnable( True );				// 「↓」表示.
			} else {
				// USB挿入状態.
				printLEDControl( True ) ;		// スタートキーＬＥＤの制御.
				if( PNLE_ServiceTPMSelfCheckUSBSaveStateOK == e_USBSaveStatus ) {
					// USB保存OK.
					Txt_ServiceTPMSelfCheckRepProgress.showEnable( False );
					Txt_ServiceTPMSelfCheckRepStatus.changeText( s_OKService );	// 「OK」.
					Txt_ServiceTPMSelfCheckRepStatus.showEnable( True );
					Txt_ServiceTPMSelfCheckRepDownArrow.showEnable( True );		// 「↓」表示.
				} else if( PNLE_ServiceTPMSelfCheckUSBSaveStateNG == e_USBSaveStatus ) {
					// USB保存NG.
					Txt_ServiceTPMSelfCheckRepProgress.showEnable( False );
					Txt_ServiceTPMSelfCheckRepStatus.changeText( s_NGService );	// 「NG」.
					Txt_ServiceTPMSelfCheckRepStatus.showEnable( True );
					Txt_ServiceTPMSelfCheckRepDownArrow.showEnable( True );		// 「↓」表示.
				} else {
					Txt_ServiceTPMSelfCheckRepProgress.showEnable( False );
					Txt_ServiceTPMSelfCheckRepStatus.showEnable( False );
					Txt_ServiceTPMSelfCheckRepDownArrow.showEnable( False );	// 「↓」非表示.
				}
			}
		} else {
			// ﾘｽﾄ出力.
			printLEDControl( True ) ;			// スタートキーＬＥＤの制御.
			Txt_ServiceTPMSelfCheckRepProgress.showEnable( False );
			Txt_ServiceTPMSelfCheckRepStatus.showEnable( False );
			Txt_ServiceTPMSelfCheckRepDownArrow.showEnable( False );	// 「↓」非表示.
			e_FeedTrayListPrint = searchTrayListPrint( 0 );		// 片面印字を指定して給紙トレイ検索（トレイ開き/紙なしチェック）.
		}
	}
}
//================================================================================================.
// 概要		: D0B0097091  : セキュリティー設定／TPM設定／ｽﾃｰﾀｽﾚﾎﾟｰﾄ キー押下処理.
// 戻り値	:なし.
// 備考		:.
//================================================================================================.
void PServiceSecuritySettingTPMSelfCheckReport::procButtonOn( uchar option )
{
	if( False == bl_isKeyAccept ) {
		setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}
	switch( option ) {
		case BTNID_ServiceSecurityTPMSelfCheckListOutput:	sc_OutputKeySelected = 0;	break;	// ﾘｽﾄ出力押下.
		case BTNID_ServiceSecurityTPMSelfCheckUSBOutput:	sc_OutputKeySelected = 1;	break;	// USB保存押下.
		default: break;
	}
	setupGamen();
}
//================================================================================================.
// 概要		: D0B0097091  : セキュリティー設定／TPM設定／ｽﾃｰﾀｽﾚﾎﾟｰﾄ スタート押下.
// 戻り値	:なし.
// 備考		:.
//================================================================================================.
void PServiceSecuritySettingTPMSelfCheckReport::procStart( uchar option )
{
	APIC_ListPrint*	pc_ListPrint = APIC_ListPrint::newInstance();
	if( NULL == pc_ListPrint ) { 
//2019/06/17 Comment [HCLT_Krishnakumar][EagleH][N Rank] Removed unwanted detailed code.
//// 2015/11/05 【HCLT-Dhivya】 【ZeusS_ZX0】 【制御構成変更_No.76-1】Detail macro is passed in API.
//		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if (NULL != pc_BFW_System){
//    		pc_BFW_System->registDetailCode(PNLD_DetailCode_Service_0x1900280101470201);
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" ); 
		return; 
	}

	if( False == printStartDisable() ) {			// スタートLED緑のとき.
		bl_isKeyAccept = False;						// キー受付「不可」を設定.
		if( 0 == sc_OutputKeySelected ) {			// ﾘｽﾄ出力のとき.
			bl_isWaitPrint = True;					// 画像生成中.
			pc_ListPrint->req_startListPrint(	TYPE_ListPrintTPMSelfCheck,		// リスト「ｽﾃｰﾀｽﾚﾎﾟｰﾄ」.
			                                    ( uint32_t )e_FeedTrayListPrint,		// トレイ.
			                                    ans_startTPMListOutput,			// コールバック.
			                                    -1,								// ボックスID.
			                                    0,								// DOCID.
			                                    NULL,							// オプション（回線指定）.
			                                    False,							// False:片面/True:両面.
			                                    TYPE_JobEntryIF_Panel );		// インターフェース.

		} else if( 1 == sc_OutputKeySelected ) {		// USB保存のとき.
			e_USBSaveStatus = PNLE_ServiceTPMSelfCheckUSBSaveStateSaving;		// USB保存中を設定.
			pc_ListPrint->writeTPMSelfCheckToUsb( ans_WriteTPMListToUsb, NULL );
		}
	} else {
		setBuzzerType( PCGE_BuzzerType_InputNg );
	}
}
//================================================================================================.
// 概要		: D0B0097091  : セキュリティー設定／TPM設定／ｽﾃｰﾀｽﾚﾎﾟｰﾄ ファンクション終了.
// 戻り値	:なし.
// 備考		:.
//================================================================================================.
void PServiceSecuritySettingTPMSelfCheckReport::procFunctionEnd( uchar option )
{
	PServiceSecuritySettingTPMCom::procFunctionEnd( option );
	bl_isKeyAccept = True;				// キー受付「可」を設定.
}
//================================================================================================.
// 概要		: D0B0097091  : セキュリティー設定／TPM設定／ｽﾃｰﾀｽﾚﾎﾟｰﾄ コールバック関数（ﾘｽﾄ出力）.
// 戻り値	:なし.
// 備考		:.
//================================================================================================.
void PServiceSecuritySettingTPMSelfCheckReport::ans_startTPMListOutput( ushort us_Result )
{
	bl_isWaitPrint = False;				// 画像生成中フラグを落とす.
}
//================================================================================================.
// 概要		: D0B0097091  : セキュリティー設定／TPM設定／ｽﾃｰﾀｽﾚﾎﾟｰﾄ コールバック関数（USB保存）.
// 戻り値	:なし.
// 備考		:.
//================================================================================================.
void PServiceSecuritySettingTPMSelfCheckReport::ans_WriteTPMListToUsb( char sc_Result )
{
	if( LSTE_WriteUsbOK == sc_Result ) {
		e_USBSaveStatus = PNLE_ServiceTPMSelfCheckUSBSaveStateOK;		// USB保存成功.
	} else {
		e_USBSaveStatus = PNLE_ServiceTPMSelfCheckUSBSaveStateNG;		// USB保存失敗.
	}
	CallBackIndi( TYPE_PNL_CallBack_functionEnd );		// コールバックイベント発生.
}

