void PFactoryMarginAdjustDupTop::startGamen()
{
// comment 2014/11/28 OPS1-Sky_nozaki [Poseidon][CQ507074] 手差し用紙検出画面表示後、設定が元に戻る問題.
//	if( PServiceFunctionEnableStartCom::getCheckComSetBackFlg() == PNLE_SelectBackGamenInit ){	// 戻り元画面フラグ取得.
	if( ( PServiceFunctionEnableStartCom::getCheckComSetBackFlg() == PNLE_SelectBackGamenInit )	// 戻り元画面フラグ初期化.
	 && ( False == m_bl_isReturnPaperSizeGamen ) ){												// 手差し用紙検出画面からの遷移ではない.
		PFactoryMarginAdjustCom::startGamen();	// 開始処理.
		CheckAndExecInit();						// 初期化必要か否か取得して必要なら実行する.

		PServiceFunctionEnableStartCom::setServiceDuplexMode( TYPE_DuplexModeOff );	// デフォルト片面設定.
	}
	else
	{
		// 基底クラスのstartGamen()を実施
		PBasicMessageProc::startGamen();
	}

// A3A4FUM kawana-k 2015/02/24 Start.
#ifdef DEF_A4_Cus
	Key_GlossmodeSelect.showEnable( True );			// 光沢モードキー表示
#endif // DEF_A4_Cus.
// A3A4FUM kawana-k 2015/02/24 End.
	Rbt_FactoryMarginAdjust.select( 3 );	// 両面先端タイミング調整.
// comment MiZe 2011/06/07 ▼Sky松本 [346124]薄紙追加漏れ.
//	setFunctionFeedCode( TYPE_FeedTrayManual );	// 手差しを設定.
//	// 給紙トレイ情報へのポインタを取得.
//	APIC_FeedTray* pc_FeedTray = PnlComGetFeedTray();
//	TYPC_PaperType c_PaperType = pc_FeedTray->getPaperType( TYPE_FeedTrayManual );
// comment MiZe 2011/06/07 ▲Sky松本 [346124]薄紙追加漏れ.
// comment 2014/11/28 OPS1-Sky_nozaki [Poseidon][CQ507074] 手差し用紙検出画面表示後、設定が元に戻る問題.
//	if( PServiceFunctionEnableStartCom::getCheckComSetBackFlg() != PNLE_SelectBackGamenInit ){	// 戻り元画面フラグ取得.
	if( ( PServiceFunctionEnableStartCom::getCheckComSetBackFlg() != PNLE_SelectBackGamenInit )	// 戻り元画面フラグ初期化以外.
	 || ( True == m_bl_isReturnPaperSizeGamen ) ){												// 手差し用紙検出画面からの遷移である.
// 2011/09/13(火) 第1OSW開発部 長谷川(伸)【Minerva/Zeus問題点】[CQ355067] ▼start▼.
#if (defined ( DEF_ZeusCus ) || defined ( DEF_ZeusEmu )) && !defined(DEF_DonauBKCus)	// Zeus時.
		// Zeusでは用紙種類薄紙選択時は手差しを使えないのでトレイ1を使用する。それ以外の種類は手差しを使用する。.
		if( TYPE_PaperTypeThin1 == PServiceFunctionEnableStartCom::getSelectPaperKind() ) {
			setFunctionFeedCode( TYPE_FeedTray1 );
		} else {
			setFunctionPaperKind( TYPE_PaperTypeNormal, TYPE_FeedTray1 );	// 薄紙を指定していない場合はトレイ1に薄紙アイコンを表示させない為の対応.
			setFunctionFeedCode( TYPE_FeedTrayManual );
		}
#else		// Zeus以外(Minerva時).
		setFunctionFeedCode( TYPE_FeedTrayManual );
#endif
// 2015/5/11 HCLT-Reshmi 管理No.1434_1_27 Paper selection control Start
#ifdef DEF_A4_Cus
TYPE_SizeCode eSizeCode = PServiceFunctionEnableStartCom::getSelectPaperSize();
	 	switch( eSizeCode ) {
			case TYPE_SizeCodeA4Sef:		
				_bl_isPanelPaperSet = True;	
				setFunctionPaperSize( TYPE_SizeCodeA4Sef );
				ss_isSelectedAdjustPaperSize = 1;
				break;
			case TYPE_SizeCodeLetterSef:	
				_bl_isPanelPaperSet = True;	
				setFunctionPaperSize( TYPE_SizeCodeLetterSef );
				ss_isSelectedAdjustPaperSize = 4;
				break;
			case TYPE_SizeCodePostcard_JpSef:	
				_bl_isPanelPaperSet = True;	
//2016/04/26 HCL_Gowthami CQ525846 ★A3共通問題★ PostCard paper size supported for Manual Tray in 98009 Start.
//				setFunctionPaperSize( TYPE_SizeCodeA4Sef );
	 			setFunctionPaperSize( TYPE_SizeCodePostcard_JpSef );
//2016/04/26 HCL_Gowthami CQ525846 ★A3共通問題★ PostCard paper size supported for Manual Tray in 98009 End.
				ss_isSelectedAdjustPaperSize = 6;
				break;
			default:	ss_isSelectedAdjustPaperSize = -1;		break;	
		}
	 	
#else 
		switch( PServiceFunctionEnableStartCom::getSelectPaperSize() ) {	// 選択済みの用紙サイズ.
			case TYPE_SizeCodeA3Sef:			// Ａ３Ｔ.
				_bl_isPanelPaperSet = True;	// パネルから用紙サイズをセットしている.
				setFunctionPaperSize( TYPE_SizeCodeA3Sef );
				ss_isSelectedAdjustPaperSize = 0;
				break;
			case TYPE_SizeCodeA4Sef:			// Ａ４Ｔ.
				_bl_isPanelPaperSet = True;	// パネルから用紙サイズをセットしている.
				setFunctionPaperSize( TYPE_SizeCodeA4Sef );
				ss_isSelectedAdjustPaperSize = 1;
				break;
			case TYPE_SizeCodeA4Lef:			// Ａ４Ｙ.
				_bl_isPanelPaperSet = True;	// パネルから用紙サイズをセットしている.
				setFunctionPaperSize( TYPE_SizeCodeA4Lef );
				ss_isSelectedAdjustPaperSize = 2;
				break;
			case TYPE_SizeCodeLedgerSef:		// １１×１７.
				_bl_isPanelPaperSet = True;	// パネルから用紙サイズをセットしている.
				setFunctionPaperSize( TYPE_SizeCodeLedgerSef );
				ss_isSelectedAdjustPaperSize = 3;
				break;
			case TYPE_SizeCodeLetterSef:		// ＬｅｔｔｅｒＴ.
				_bl_isPanelPaperSet = True;	// パネルから用紙サイズをセットしている.
				setFunctionPaperSize( TYPE_SizeCodeLetterSef );
				ss_isSelectedAdjustPaperSize = 4;
				break;
			case TYPE_SizeCodeLetterLef:		// ＬｅｔｔｅｒＹ.
				_bl_isPanelPaperSet = True;	// パネルから用紙サイズをセットしている.
				setFunctionPaperSize( TYPE_SizeCodeLetterLef );
				ss_isSelectedAdjustPaperSize = 5;
				break;
			case TYPE_SizeCodePostcard_JpSef:	// はがき.
				_bl_isPanelPaperSet = True;	// パネルから用紙サイズをセットしている.
				setFunctionPaperSize( TYPE_SizeCodePostcard_JpSef );
				ss_isSelectedAdjustPaperSize = 6;
				break;
			default:	ss_isSelectedAdjustPaperSize = -1;		break;	// 上記以外のときは未選択.
		}
#endif
// 2015/5/11 HCLT-Reshmi 管理No.1434_1_27 Paper selection control End
		// 用紙サイズ非選択時以外は、自動検出フラグを落とす.
		if( -1 != ss_isSelectedAdjustPaperSize ) {
			APIC_Job* pc_Job = PnlComGetJobCopy();
			APIC_FeedTray* pc_FeedTray = PnlComGetFeedTray();
			if( NULL == pc_Job || NULL == pc_FeedTray ) { 
//2019/06/17 Comment [HCLT_Krishnakumar][EagleH][N Rank] Removed unwanted detailed code.
//// 2015/11/05 【HCLT-Dhivya】 【ZeusS_ZX0】 【制御構成変更_No.76-1】Detail macro is passed in API.
//				LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//				if (NULL != pc_BFW_System){
//    				pc_BFW_System->registDetailCode(PNLD_DetailCode_Service_0x1900650100170301);
//				}
				LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
				return; 
			}

			updateTrayInfoBackup( pc_Job->getJobSpec()->pc_Print->c_PaperTray.getFeedTray() );		// トレイ情報のバックアップ更新.
			pc_FeedTray->setPaperSizeAutoDetectOn( pc_Job->getJobSpec()->pc_Print->c_PaperTray.getFeedTray(), False );			// 用紙サイズをパネル設定にする.
		}
	} else {
		// 初期選択トレイ.
		setFunctionFeedCode( TYPE_FeedTrayManual );
//2016/04/26 HCL_Gowthami CQ525846 ★A3共通問題★ Paper size display while lauching 98009 for Manual tray Start.
//		ss_isSelectedAdjustPaperSize = -1;	// 未選択.
//		PServiceFunctionEnableStartCom::setSelectPaperSize( 0 ); // 用紙サイズ選択初期化(未選択).
		PNLS_MarginAdjustPaperSize st_AdjustPaperInfo;
		getAdjustPaperSize( _Backup_PaperSize_MANUAL.e_SizeCode, st_AdjustPaperInfo, bl_isImageCombinationSet );
		ss_isSelectedAdjustPaperSize = st_AdjustPaperInfo.ss_SelectedPaperSize;
		PServiceFunctionEnableStartCom::setSelectPaperSize( st_AdjustPaperInfo.e_SizeCode );
//2016/04/26 HCL_Gowthami CQ525846 ★A3共通問題★ Paper size display while lauching 98009 for Manual tray End.
		//	カードラインモード時.
		if( comSystem.getFactoryAdjustMode() ) {
//ZeusMLKPre mfp_archi_merge 2011.02.21 triarc 渡邊 end
			// comment [CQ342040] 2011.05.23 cec_wada start.
			// comment ss_isSelectedAdjustPaperSize = 0;	// A3T.
//2016/04/26 HCL_Gowthami CQ525846 ★A3共通問題★ Paper size display in 98009 for Manual tray Start.
// AS-PVD_14_15 用紙サイズ設定 kuroda Start.
//#ifdef DEF_A4_Cus
//			ss_isSelectedAdjustPaperSize = ( e_SystemType == TYPE_SystemType_US ? 4 : 1 );
//			TYPE_SizeCode e_SelectPaperSize = ( e_SystemType == TYPE_SystemType_US ? TYPE_SizeCodeLetterSef : TYPE_SizeCodeA4Sef );
//			PServiceFunctionEnableStartCom::setSelectPaperSize( e_SelectPaperSize );
//#else
// comment 2014/12/19 OPS1-Sky浜野 [Poseidon][CQ508302] 初期表示サイズ変更.
//			ss_isSelectedAdjustPaperSize = ( e_SystemType == TYPE_SystemType_US ? 3 : 0 );
//			// comment [CQ342040] 2011.05.23 cec_wada end.
//			TYPE_SizeCode e_SelectPaperSize = ( e_SystemType == TYPE_SystemType_US ? TYPE_SizeCodeLedgerSef : TYPE_SizeCodeA3Sef );
//			PServiceFunctionEnableStartCom::setSelectPaperSize( e_SelectPaperSize );
			// 丸め用紙サイズ取得.
			PNLS_MarginAdjustPaperSize st_AdjustPaperInfo;
			getAdjustPaperSize( _Backup_PaperSize_MANUAL.e_SizeCode, st_AdjustPaperInfo, True );
			// 用紙サイズ設定.
			ss_isSelectedAdjustPaperSize = st_AdjustPaperInfo.ss_SelectedPaperSize;
			PServiceFunctionEnableStartCom::setSelectPaperSize( st_AdjustPaperInfo.e_SizeCode );
//#endif
// AS-PVD_14_15 用紙サイズ設定 kuroda End.
//2016/04/26 HCL_Gowthami CQ525846 ★A3共通問題★ Paper size display in 98009 for Manual tray End.
		}
	}
//2016/04/26 HCL_Gowthami CQ525846 ★A3共通問題★ Adjusted Paper size display in 98009 for Tray1 Start.
	if ( PServiceFunctionEnableStartCom::getCheckComSetBackFlg() != PNLE_SelectBackGamenInit ) {
		PNLS_MarginAdjustPaperSize st_AdjustPaperInfo;
		getAdjustPaperSize( _Backup_PaperSize_MPC.e_SizeCode, st_AdjustPaperInfo, bl_isImageCombinationSet );
		setFunctionPaperSize( st_AdjustPaperInfo.e_SizeCode, TYPE_FeedTray1 );
		PnlComGetFeedTray()->setPaperSizeAutoDetectOn( TYPE_FeedTray1, False );		// 用紙サイズをパネル設定にする.
	}
//2016/04/26 HCL_Gowthami CQ525846 ★A3共通問題★ Adjusted Paper size display in 98009 for Tray1 End.
	TYPE_PaperType sc_SelectPaperType = TYPE_PaperTypeNormal;
// comment 2014/11/28 OPS1-Sky_nozaki [Poseidon][CQ507074] 手差し用紙検出画面表示後、設定が元に戻る問題.
//	if( PServiceFunctionEnableStartCom::getCheckComSetBackFlg() != PNLE_SelectBackGamenInit ){	// 戻り元画面フラグ取得.
	if( ( PServiceFunctionEnableStartCom::getCheckComSetBackFlg() != PNLE_SelectBackGamenInit )	// 戻り元画面フラグ初期化以外.
	 || ( True == m_bl_isReturnPaperSizeGamen ) ){												// 手差し用紙検出画面からの遷移である.
		sc_SelectPaperType = PServiceFunctionEnableStartCom::getSelectPaperKind();
	} else {
		// 用紙種類の既定値は普通紙.
		PServiceFunctionEnableStartCom::setSelectPaperKind( sc_SelectPaperType );	// 用紙種類設定.
	}
	switch( sc_SelectPaperType ) {	// 選択済みの用紙種類.
		case TYPE_PaperTypeNormal:		ss_isSelectedAdjustPaperKind = 0;		break;	// 普通紙.
		case TYPE_PaperTypeThick1:		ss_isSelectedAdjustPaperKind = 1;		break;	// 厚紙1.
		case TYPE_PaperTypeThick1Plus:	ss_isSelectedAdjustPaperKind = 2;		break;	// 厚紙1+.
		case TYPE_PaperTypeThick2:		ss_isSelectedAdjustPaperKind = 3;		break;	// 厚紙2.
		case TYPE_PaperTypeThick3:		ss_isSelectedAdjustPaperKind = 4;		break;	// 厚紙3.
		// 両面先端では厚紙4、OHP、封筒なし.
		case TYPE_PaperTypeThin1:		ss_isSelectedAdjustPaperKind = 8;		break;	// 薄紙.
// Comment 2017/12/06 HCLT-Prashannaa [Sparrow] 制御構成変更_No.331[WP 218]
// comment 2018/04/10 SCD2 H.Koike [Eagle][RQ-722]用紙種別追加（厚紙1を2種類に分割）対応 IT6共通の為、コンパイルSw削除.
//#ifdef DEF_SparrowCus
		case TYPE_PaperTypeNormalPlus:	ss_isSelectedAdjustPaperKind = 5;		break;	// 普通紙+.
//#endif		
		default:	ss_isSelectedAdjustPaperKind = -1;	break;	// 上記以外のときは未選択.
	}
	setFunctionFeedCodePaperType( sc_SelectPaperType );	// 給紙口設定.
	setFunctionPaperKind( sc_SelectPaperType );	// 用紙種類設定（既定値：普通紙）.
	setDupMarginAdjustFunc();					// 両面トップマージン用ファンクション設定.
	PServiceFunctionEnableStartCom::setCheckComSetBackFlg( PNLE_SelectBackGamenInit );		// 戻り元画面フラグの設定初期化.
	if( comSystem.getFactoryAdjustMode() ) {
		_bl_isPanelPaperSet = True;	// ﾊﾟﾈﾙから設定している。
	}
	// 統合パターンの印字条件.
	st_ImageCombinationData.bl_isDuplexMode = True; // 両面.
#if defined(SIMULATOR) && !defined(FUM_LINUX)
	isImageCombinationDuplex = False; // 画像統合パターンの両面印字か否か(PrintProcessの判断のため).
#else	/* #if defined(SIMULATOR) && !defined(FUM_LINUX) */
	setIsImageCombinationDuplex( False );
#endif	/* #if defined(SIMULATOR) && !defined(FUM_LINUX) */
	// パーツ表示制御
	CheckShowParts();
}
//================================================================================================
// 概要		：工場調整・マージン調整・両面先端タイミング調整：変数の初期化.
//================================================================================================
void PFactoryMarginAdjustDupTop::init_value()
{
// A3A4FUM kawana-k 2015/02/24 Start.
#ifndef DEF_A4_Cus
	// 両面先端タイミング調整・CommonAPI値を取得.
	getPrinterIndiInSystem( TYPE_PrinterAdjust2ndSubRegistNormal );	// 1 ：用紙送出し位置（普通紙）.
	getPrinterIndiInSystem( TYPE_PrinterAdjust2ndSubRegistHeavy1 );	// 3 ：用紙送出し位置（厚紙１/１＋）.
	getPrinterIndiInSystem( TYPE_PrinterAdjust2ndSubRegistHeavy2 );	// 4 ：用紙送出し位置（厚紙２）.
	getPrinterIndiInSystem( TYPE_PrinterAdjust2ndSubRegistHeavy3 );	// 5 : 用紙送出し位置（厚紙３）.
	getPrinterIndiInSystem( TYPE_PrinterAdjust2ndSubRegistThin );	// 8 : 用紙送出し位置（薄紙） .
#else
	// 両面先端タイミング調整・CommonAPI値を取得.
	getPrinterIndiInSystem( TYPE_PrinterAdjust2ndSubRegistNormal );	// 用紙送出し位置（普通紙）.
	getPrinterIndiInSystem( TYPE_PrinterAdjust2ndSubRegistGlossy );	// 用紙送出し位置（普通紙(光沢モード)）.
	getPrinterIndiInSystem( TYPE_PrinterAdjust2ndSubRegistHeavy1 );	// 用紙送出し位置（厚紙１）.
// Comment 2017/12/06 HCLT-Prashannaa [Sparrow] 制御構成変更_No.331[WP 218]
// comment 2018/04/10 SCD2 H.Koike [Eagle][RQ-722]用紙種別追加（厚紙1を2種類に分割）対応 IT6共通の為、普通紙+をコンパイルSwの外へ移動.
#ifdef DEF_SparrowCus
	getPrinterIndiInSystem( TYPE_PrinterAdjust2ndSubRegistHeavy2 );	// 用紙送出し位置（厚紙2）.
#endif
#endif // DEF_A4_Cus.
// A3A4FUM kawana-k 2015/02/24 End.
	getPrinterIndiInSystem( TYPE_PrinterAdjust2ndSubRegistNormalPlus );	// 用紙送出し位置（普通紙+）.
}
//================================================================================================
// 概要		：工場調整・マージン調整・両面先端タイミング調整：ＯＫボタン.
//================================================================================================
void PFactoryMarginAdjustDupTop::procOk( uchar option )
{
// A3A4FUM kawana-k 2015/02/24 Start.
#ifndef DEF_A4_Cus
	// 両面トップマージン調整値確定.
	fixPrinterIndi( TYPE_PrinterAdjust2ndSubRegistNormal );	// 1 ：用紙送出し位置（普通紙）.
	fixPrinterIndi( TYPE_PrinterAdjust2ndSubRegistHeavy1 );	// 3 ：用紙送出し位置（厚紙１/１+）.
	fixPrinterIndi( TYPE_PrinterAdjust2ndSubRegistHeavy2 );	// 4 ：用紙送出し位置（厚紙２）.
	fixPrinterIndi( TYPE_PrinterAdjust2ndSubRegistHeavy3 );	// 5 : 用紙送出し位置（厚紙３）.
	fixPrinterIndi( TYPE_PrinterAdjust2ndSubRegistThin );	// 8 : 用紙送出し位置（薄紙） .
#else
	// 両面トップマージン調整値確定.
	fixPrinterIndi( TYPE_PrinterAdjust2ndSubRegistNormal );	// 用紙送出し位置（普通紙）.
	fixPrinterIndi( TYPE_PrinterAdjust2ndSubRegistGlossy );	// 用紙送出し位置（普通紙(光沢モード)）.
	fixPrinterIndi( TYPE_PrinterAdjust2ndSubRegistHeavy1 );	// 用紙送出し位置（厚紙１(For Sparrow  厚紙1/1+)）.
// Comment 2017/12/06 HCLT-Prashannaa [Sparrow] 制御構成変更_No.331[WP 218]
// comment 2018/04/10 SCD2 H.Koike [Eagle][RQ-722]用紙種別追加（厚紙1を2種類に分割）対応 IT6共通の為、普通紙+をコンパイルSwの外へ移動.
#ifdef DEF_SparrowCus
	fixPrinterIndi( TYPE_PrinterAdjust2ndSubRegistHeavy2 );	// 用紙送出し位置（厚紙2）.
#endif
#endif // DEF_A4_Cus.
// A3A4FUM kawana-k 2015/02/24 End.
	fixPrinterIndi( TYPE_PrinterAdjust2ndSubRegistNormalPlus );	// 用紙送出し位置（普通紙+）.
	
	PFactoryMarginAdjustCom::procOk( option );	// 親クラスの共通処理を呼ぶ.
}
//================================================================================================
// 概要		：工場調整・マージン調整・両面先端タイミング調整：スタートキー（押された）.
//================================================================================================
void PFactoryMarginAdjustDupTop::procStart( uchar option )
{
	fixPrinterIndi( TYPE_PrinterAdjustCDWidth );				// CD方向線幅レベル.
	fixPrinterIndi( TYPE_PrinterAdjustFDWidth );				// FD方向線幅レベル.
	fixPrinterIndi( TYPE_PrinterAdjustDensity );				// 濃度レベル.
	fixPrinterIndi( TYPE_PrinterAdjustLatticeMode );			// 格子パターンモード.
	fixPrinterIndi( TYPE_PrinterAdjustLimosMode );				// リモスモード.
	fixPrinterIndi( TYPE_PrinterAdjustLineParameter );			// 線数パラメータ.
// A3A4FUM kawana-k 2015/02/24 Start.
#ifndef DEF_A4_Cus
	// 両面先端タイミング調整・CommonAPI値を取得.
	fixPrinterIndi( TYPE_PrinterAdjust2ndSubRegistNormal );	// 1 ：用紙送出し位置（普通紙）.
	fixPrinterIndi( TYPE_PrinterAdjust2ndSubRegistHeavy1 );	// 3 ：用紙送出し位置（厚紙１/１+）.
	fixPrinterIndi( TYPE_PrinterAdjust2ndSubRegistHeavy2 );	// 4 ：用紙送出し位置（厚紙２）.
	fixPrinterIndi( TYPE_PrinterAdjust2ndSubRegistHeavy3 );	// 5 : 用紙送出し位置（厚紙３）.
	fixPrinterIndi( TYPE_PrinterAdjust2ndSubRegistThin );	// 8 : 用紙送出し位置（薄紙）.
#else
	fixPrinterIndi( TYPE_PrinterAdjust2ndSubRegistNormal );	// 用紙送出し位置（普通紙）.
	fixPrinterIndi( TYPE_PrinterAdjust2ndSubRegistGlossy );	// 用紙送出し位置（普通紙(光沢モード)）.
	fixPrinterIndi( TYPE_PrinterAdjust2ndSubRegistHeavy1 );	// 用紙送出し位置（厚紙１(For Sparrow  厚紙1/1+)）.
// Comment 2017/12/06 HCLT-Prashannaa [Sparrow] 制御構成変更_No.331[WP 218]
// comment 2018/04/10 SCD2 H.Koike [Eagle][RQ-722]用紙種別追加（厚紙1を2種類に分割）対応 IT6共通の為、普通紙+をコンパイルSwの外へ移動.
#ifdef DEF_SparrowCus
	fixPrinterIndi( TYPE_PrinterAdjust2ndSubRegistHeavy2 );	// 用紙送出し位置（厚紙2）.
#endif
#endif // DEF_A4_Cus.
// A3A4FUM kawana-k 2015/02/24 End.
	fixPrinterIndi( TYPE_PrinterAdjust2ndSubRegistNormalPlus );	// 用紙送出し位置（普通紙+）.
	TYPE_PaperType e_SelectPaperType = getPaperTypeCom();	// 設定されている用紙種類.
	switch( e_SelectPaperType ) {
// A3A4FUM kawana-k 2015/02/24 Start.
#ifndef DEF_A4_Cus
		case TYPE_PaperTypeNormal:		// 普通紙.
		case TYPE_PaperTypeThick1:		// 厚紙1.
		case TYPE_PaperTypeThick1Plus:	// 厚紙1+.
		case TYPE_PaperTypeThick2:		// 厚紙2.
		case TYPE_PaperTypeThick3:		// 厚紙3.
		// 両面先端では厚紙4、OHP、封筒なし.
		case TYPE_PaperTypeThin1:		// 薄紙.
#else
	case TYPE_PaperTypeNormal:		// 普通紙.
	case TYPE_PaperTypeThick1:		// 厚紙1.(For Sparrow  厚紙1/1+)
// Comment 2017/12/06 HCLT-Prashannaa [Sparrow] 制御構成変更_No.331[WP 218]
// comment 2018/04/10 SCD2 H.Koike [Eagle][RQ-722]用紙種別追加（厚紙1を2種類に分割）対応 IT6共通の為、普通紙+をコンパイルSwの外へ移動.
#ifdef DEF_SparrowCus
	case TYPE_PaperTypeThick2:		// 厚紙2.
#endif
#endif // DEF_A4_Cus.
// A3A4FUM kawana-k 2015/02/12 End.
	case TYPE_PaperTypeNormalPlus:	// 普通紙+.
			break;
		default:
			ss_isSelectedAdjustPaperKind = 0;
			PServiceFunctionEnableStartCom::setSelectPaperKind( TYPE_PaperTypeNormal );	// 用紙種類設定.
			setFunctionPaperKind( TYPE_PaperTypeNormal );
			break;
	}
// A3A4FUM kawana-k 2015/03/26 Start.
#ifdef DEF_A4_Cus
	// 普通紙(光沢モード)時のみジョブスペックをTrueに設定する.
	APIC_Job* pc_Job = PnlComGetJobCopy();
	if( NULL == pc_Job ){ 
//2019/06/17 Comment [HCLT_Krishnakumar][EagleH][N Rank] Removed unwanted detailed code.
//// 2015/11/05 【HCLT-Dhivya】 【ZeusS_ZX0】 【制御構成変更_No.76-1】Detail macro is passed in API.
//		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if (NULL != pc_BFW_System){
//    		pc_BFW_System->registDetailCode(PNLD_DetailCode_Service_0x1900280100170401);
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );	
		return; 
	}
	if( bl_isSelectedGlossMode == True){
		pc_Job->getJobSpec()->pc_Common->c_OriginalImageMode.setLusterCopyOn( True );
	}else{
		pc_Job->getJobSpec()->pc_Common->c_OriginalImageMode.setLusterCopyOn( False );
	}
#endif // DEF_A4_Cus.
// A3A4FUM kawana-k 2015/03/26 End.
#if defined(SIMULATOR) && !defined(FUM_LINUX)
	isImageCombinationDuplex = True; // 画像統合パターンの両面印字か否か(PrintProcessの判断のため).
#else	/* #if defined(SIMULATOR) && !defined(FUM_LINUX) */
	setIsImageCombinationDuplex( True );
#endif	/* #if defined(SIMULATOR) && !defined(FUM_LINUX) */
	PFactoryMarginAdjustCom::procStart( option );	// 親クラスの処理を呼ぶ
}
