			setDupMarginAdjustFunc();	// 両面トップマージン用ファンクション設定(ハーフトーン選択).
			_bl_isPanelPaperSet = True;
//2016/04/26 HCL_Gowthami CQ525846 ★A3共通問題★ Adjusted Paper size display in 98009 for Manual Tray Start.
