void PFactoryMarginAdjustDupTop::endGamen()
{
#if defined(SIMULATOR) && !defined(FUM_LINUX)
	isImageCombinationDuplex = False; // 画像統合パターンの両面印字か否か(PrintProcessの判断のため).
#else	/* #if defined(SIMULATOR) && !defined(FUM_LINUX) */
	setIsImageCombinationDuplex( False );
#endif	/* #if defined(SIMULATOR) && !defined(FUM_LINUX) */
	PFactoryMarginAdjustCom::endGamen();	// 親クラスの処理を呼ぶ
}
//================================================================================================.
// 概要		：工場調整・マージン調整・両面先端タイミング調整：アクティブ状態の通知.
// 戻り値	：.
//================================================================================================.
void PFactoryMarginAdjustDupTop::procActivate()
{
	PFactoryMarginAdjustCom::procActivate();
#if (defined ( DEF_ZeusCus ) || defined ( DEF_ZeusEmu )) && !defined(DEF_DonauBKCus)	// Zeus時.
	// Zeusでは用紙種類薄紙選択時は手差しを使えないのでトレイ1を使用する。それ以外の種類は手差しを使用する。.
	if( TYPE_PaperTypeThin1 == PServiceFunctionEnableStartCom::getSelectPaperKind() ) {
		setFunctionFeedCode( TYPE_FeedTray1 );
	} else {
		setFunctionPaperKind( TYPE_PaperTypeNormal, TYPE_FeedTray1 );	// 薄紙を指定していない場合はトレイ1に薄紙アイコンを表示させない為の対応.
		setFunctionFeedCode( TYPE_FeedTrayManual );
	}
#else		// Zeus以外(Minerva時).
	setFunctionFeedCode( TYPE_FeedTrayManual );
#endif
}
