static const ushort demagCoilFuncCode[] = { TYPD_FNC_DelMagCoilOn1, TYPD_FNC_DelMagCoilOn2 ,TYPD_FNC_DelMagCoilOn3 };
void PFactoryDemagCoil::startGamen( )
{
	PServiceFunctionEnableStopCom::startGamen(); // ファンクション共通開始処理.
	CheckAndExecInit(); // 初期化必要か否か取得して必要なら実行する.
}
//================================================================================================
// 概要		:工場調整・消磁コイル ： 変数初期化.
//================================================================================================
void PFactoryDemagCoil::init_value( )
{
	ss_Selected = 0;	// 1キー選択に設定.
	setFunctionCode( demagCoilFuncCode[ ss_Selected ] );	// ファンクションコード設定.
}
//================================================================================================
// 概要		:工場調整・消磁コイル ： スタートキー.
//================================================================================================
