//================================================================================================
void PFactoryDemagCoil::procOk( uchar option )
{
	nextGamen = &gp_FactoryTestPrintMenu;	// 工場調整・テストプリント・メニュー.
}
//================================================================================================
// 概要		:工場調整・消磁コイル ： キー押下.
//================================================================================================
void PFactoryDemagCoil::procButtonOn( uchar option )
{
	switch( option ) {
		case 0: ss_Selected = 0; break;	// 1キー選択.
		case 1: ss_Selected = 1; break;	// 2キー選択.
		case 2: ss_Selected = 2; break;	// 3キー選択.
		default :	break;
	}
	setFunctionCode( demagCoilFuncCode[ ss_Selected ] );	// ファンクションコード設定.
	setupGamen();
}
//================================================================================================
// 概要		:工場調整・消磁コイル ： 画面セットアップ.
//================================================================================================
void PFactoryDemagCoil::setupGamen( short option )
{
// Comment 【01-08-2015】【HCLT-Poongothai】 【ZeusS_ZX0】 【機器構成変更_No.52】 Demagnetizing coil operation confirmation function addition support.
//	Rbt_DemagCoil.select( ss_Selected );	// 消磁コイル選択キー.
	TYPE_MachineType e_MachineType = PnlComGetSystemInfo()->getMachineType();
	if( TYPE_MachineTypeZeusSZ_US_JP == e_MachineType || TYPE_MachineTypeZeusSZ_EU == e_MachineType || 
// comment 2016/01/11【HCLT_Vishnu】【ZeusSBK】【制御構成変更_No.6】 Addition of Machine Type for ZeusSBKX.
//		TYPE_MachineTypeZeusSX_US_JP == e_MachineType || TYPE_MachineTypeZeusSX_EU == e_MachineType ) {
		( TYPE_MachineTypeZeusSX_US_JP == e_MachineType ) || ( TYPE_MachineTypeZeusSX_EU == e_MachineType ) ||
		( TYPE_MachineTypeZeusSBKX == e_MachineType ) 		// Incase of machine type ZeusSBKX.
// Comment  2016/12/19 SCD2-2G南波 [IT5_4.1][AR.1007166][機器構成変更_No.46]ZeusSBK_2ndZ 追加対応.
	 || ( TYPE_MachineTypeZeusSBK2ndZ == e_MachineType ) // ZeusSBK_2ndZ.
// Comment 2019/04/17 HCLT_Hepzibah [IT6_EagleBK] [制御構成変更_No.6] Adding machine type to support for EagleBK.
	 ||( TYPE_MachineTypeEagleBKZ == e_MachineType )
	 ||( TYPE_MachineTypeEagleBKX == e_MachineType )
	 ||( TYPE_MachineTypeEagleBKH_Emu800 == e_MachineType )
// Comment 2017/11/27 HCLT_Gomathy [IT6_Eagle] [制御構成変更_No.6] Adding machine type to support for Eagle.
	 ||( TYPE_MachineTypeEagleZ == e_MachineType )
	 ||( TYPE_MachineTypeEagleX == e_MachineType )
// Comment 2019/05/02 HCLT_AppalaRaju [IT6_EagleZ+] [制御構成変更_No.6] Adding EagleZ+ machine type.
	 ||( TYPE_MachineTypeEagleZplus == e_MachineType )
	 ||( TYPE_MachineTypeEagleBKZplus == e_MachineType )
	 ||( TYPE_MachineTypeEagleZplusEmu800 == e_MachineType )
	 ||( TYPE_MachineTypeEagleBKZplusEmu800 == e_MachineType )
		) {
		Rbt_DemagCoil2.showEnable( True );
		Rbt_DemagCoil.showEnable( False );
		Rbt_DemagCoil2.select( ss_Selected );
	} else {
        Rbt_DemagCoil2.showEnable( False );
		Rbt_DemagCoil.showEnable( True );
		Rbt_DemagCoil.select( ss_Selected );	
	}
	PServiceFunctionCom::searchWithoutPaper_ENG( option );	// ファンクション画面共通処理.
}

