//////////////////////////////////////////////////////////////
// 概要 : 工場調整モード／トレイ選択(50E00011) : 画面開始処理.
//////////////////////////////////////////////////////////////
void PFactorySelectTray::startGamen()
{
	PServiceFunctionEnableStartCom::startGamen();	// ファンクション共通開始処理
	CheckAndExecInit();								// 初期化必要か否か取得して必要なら実行する

	ss_dispFeedTray = PServiceFunctionEnableStartCom::getInitSelectFeedTray();	// 表示パターン取得.
	e_SelectFeedTray = PServiceFunctionEnableStartCom::getSelectFeedTray();		// 選択中のトレイ取得.
}
//////////////////////////////////////////////////////////////
// 概要 : 工場調整モード／トレイ選択(50E00011) : ボタン（押された）.
//////////////////////////////////////////////////////////////
void PFactorySelectTray::procButtonOn( uchar option )
{
	switch( option )
	{
		// 給紙口選択キー.
		case 0:	// １段目.
			if( ppc_FeedTray->getTrayStatus( TYPE_FeedTray1 ) != TYPE_TrayStatusNon ) {
				e_SelectFeedTray = TYPE_FeedTray1;		// 給紙口をトレイ１に設定.
			}
			break;
		case 1:	// ２段目.
			if( ppc_FeedTray->getTrayStatus( TYPE_FeedTray2 ) != TYPE_TrayStatusNon ) {
				e_SelectFeedTray = TYPE_FeedTray2;		// 給紙口をトレイ２に設定.
			}
			break;
		case 2:	// ３段目.
			if( ppc_FeedTray->getTrayStatus( TYPE_FeedTray3 ) != TYPE_TrayStatusNon ) {
				e_SelectFeedTray = TYPE_FeedTray3;		// 給紙口をトレイ３に設定.
			}
			break;
		case 3:	// ４段目.
			if( ppc_FeedTray->getTrayStatus( TYPE_FeedTray4 ) != TYPE_TrayStatusNon ) {
				e_SelectFeedTray = TYPE_FeedTray4;		// 給紙口をトレイ４に設定.
			}
			break;
		case 4:	// 手差し.
			if( ppc_FeedTray->getTrayStatus( TYPE_FeedTrayManual ) != TYPE_TrayStatusNon ) {
				e_SelectFeedTray = TYPE_FeedTrayManual;	// 給紙口を手差しに設定.
			}
			break;

// comment 2015/01/31 HCLT-Durga [Compilation Switch ID: 1535] for HeliosL support.
// comment 2014/09/30 HCLT-Kiran [Poseidon][CQ_503165] Hiding the LCT Paper Feed Slot on the screen, for Poseidon model.		
//#ifndef DEF_Zeus5BkCus
//comment 2018/5/18 SCD2-Sky肥後 [DenebMLK][機器構成変更No.7]5段目トレイ追加対応.
//#if !defined( DEF_Zeus5BkCus ) && !defined( DEF_HeliosCus )
// Comment 2019/07/26 [HCLT_Paul] [IT6_HeliosMLK] [ Seigyu.10 ] Adding the HeliosMLK compiler switch.
#if !defined( DEF_Zeus5BkCus ) && !defined( DEF_HeliosMLKCus ) || defined(DEF_DenebMLKCus)
		case 5:	// LCT.
			if( ppc_FeedTray->getTrayStatus( TYPE_FeedTray5 ) != TYPE_TrayStatusNon ) {
				e_SelectFeedTray = TYPE_FeedTray5;		// 給紙口をLCTに設定.
			}
			break;
#endif
		case 10: // 自動.
			e_SelectFeedTray = 10;
			break;
		default:	break;
	}
	setupGamen();	// 表示部品のセットアップ
}
//////////////////////////////////////////////////////////////
// 概要 : 工場調整モード／トレイ選択(50E00011)  : 設定終了.
//////////////////////////////////////////////////////////////
void PFactorySelectTray::procOk( uchar option )
{
	PServiceFunctionEnableStartCom::setCheckComSetBackFlg( PNLE_SelectBackGamentoTray );	// 戻り元画面フラグの設定.
	PServiceFunctionEnableStartCom::setSelectFeedTray( e_SelectFeedTray );
	nextGamen = PServiceFunctionEnableStartCom::prevServiceComGamen;		// 呼び出し元画面へ遷移.
}
//////////////////////////////////////////////////////////////
// 概要 : 工場調整モード／トレイ選択(50E00011) : 表示画面のセットアップ.
//////////////////////////////////////////////////////////////
void PFactorySelectTray::setupGamen( short option )
{
	register short _select = -1;

	switch( e_SelectFeedTray )
	{
		case TYPE_FeedTray1:		_select = 1;		break;	// 1段目給紙口.
		case TYPE_FeedTray2:		_select = 2;		break;	// 2段目給紙口.
		case TYPE_FeedTray3:		_select = 3;		break;	// 3段目給紙口.
		case TYPE_FeedTray4:		_select = 4;		break;	// 4段目給紙口.
		case TYPE_FeedTrayManual:	_select = 5;		break;	// 手差し給紙口.
// comment 2015/01/31 HCLT-Durga [Compilation Switch ID: 1536] for HeliosL support.
// comment 2014/09/30 HCLT-Kiran [Poseidon][CQ_503165] Hiding the LCT Paper Feed Slot on the screen, for Poseidon model.		
//#ifndef DEF_Zeus5BkCus		
//comment 2018/5/18 SCD2-Sky肥後 [DenebMLK][機器構成変更No.7]5段目トレイ追加対応.
//#if !defined( DEF_Zeus5BkCus ) && !defined( DEF_HeliosCus )
// Comment 2019/07/26 [HCLT_Paul] [IT6_HeliosMLK] [ Seigyu.10 ] Adding the HeliosMLK compiler switch.
#if !defined( DEF_Zeus5BkCus ) && !defined( DEF_HeliosMLKCus ) || defined(DEF_DenebMLKCus)
		case TYPE_FeedTray5:		_select = 6;		break;	// LCT給紙口.
#endif
		case 10:					_select = 0;		break;	// 自動.
		default:					_select = -1;		break;	// 上記以外のときは未選択.
	}
	// エンプティ状態でない場合エンプティ表示を消す｡
	Rbt_TrayServiceTest.select( _select ); // 対象トレイを選択.
	Key_1stTrayServiceTest.showEnableAdd( &Ktx_1stTrayServiceTestEmpty, isFeedTrayUseable( TYPE_FeedTray1 ) ? False : True );
	Key_2ndTrayServiceTest.showEnableAdd( &Ktx_2ndTrayServiceTestEmpty, isFeedTrayUseable( TYPE_FeedTray2 ) ? False : True );
	Key_3rdTrayServiceTest.showEnableAdd( &Ktx_3rdTrayServiceTestEmpty, isFeedTrayUseable( TYPE_FeedTray3 ) ? False : True );
	Key_4thTrayServiceTest.showEnableAdd( &Ktx_4thTrayServiceTestEmpty, isFeedTrayUseable( TYPE_FeedTray4 ) ? False : True );
	Key_ManTrayServiceTest.showEnableAdd( &Ktx_ManTrayServiceTestEmpty, isFeedTrayUseable( TYPE_FeedTrayManual ) ? False : True );
	Key_LCTTrayServiceTest.showEnableAdd( &Ktx_LCTTrayServiceTestEmpty, isFeedTrayUseable( TYPE_FeedTray5 ) ? False : True );

	for( register ushort i = 0; i<uc_SelectTrayNum; i++ ) {
		if( ss_dispFeedTray == sc_SelectTrayTbl[i].dispType ) {	// 表示パターン判定.
			if( sc_SelectTrayTbl[i].typeFeedAuto	== False ) { Key_AutoTrayServiceTest.showEnable( False ); }
//2018/04/09 comment [HCLT_Prashannaa][IT6_Sparrow][制御構成変更_No.212] remove tray 3			
			if(( sc_SelectTrayTbl[i].typeFeedTray1	== False )||
				(ppc_FeedTray->getTrayStatus(TYPE_FeedTray1 ) == TYPE_TrayStatusNon ))
				{ Key_1stTrayServiceTest.showEnable( False ); }
			
			if(( sc_SelectTrayTbl[i].typeFeedTray2	== False )|| 
				(ppc_FeedTray->getTrayStatus(TYPE_FeedTray2 ) == TYPE_TrayStatusNon ))
				{ Key_2ndTrayServiceTest.showEnable( False ); }
			
			if(( sc_SelectTrayTbl[i].typeFeedTray3	== False )||
				(ppc_FeedTray->getTrayStatus(TYPE_FeedTray3 ) == TYPE_TrayStatusNon ))
				{ Key_3rdTrayServiceTest.showEnable( False ); }
			
			if(( sc_SelectTrayTbl[i].typeFeedTray4	== False )||
				(ppc_FeedTray->getTrayStatus(TYPE_FeedTray4 ) == TYPE_TrayStatusNon ))
				{ Key_4thTrayServiceTest.showEnable( False ); }
			
			if((sc_SelectTrayTbl[i].typeFeedManual	== False )||
				(ppc_FeedTray->getTrayStatus(TYPE_FeedTrayManual ) == TYPE_TrayStatusNon ))
				{ Key_ManTrayServiceTest.showEnable( False ); }
		
			if((sc_SelectTrayTbl[i].typeFeedLCT		== False )||
				(ppc_FeedTray->getTrayStatus(TYPE_FeedTray5 ) == TYPE_TrayStatusNon ))
				{ Key_LCTTrayServiceTest.showEnable( False ); }
		}
	}
	if( False == isShowManTray() ) {
		Key_ManTrayServiceTest.showEnable( False );
	}
	PServiceFunctionEnableStartCom::setupGamen( option );
	printLEDControl( False );	// LED赤
}
//////////////////////////////////////////////////////////////
// 概要 : 工場調整モード／トレイ選択(50E00011) : パネルリセット.
//////////////////////////////////////////////////////////////
void PFactorySelectTray::procReset( uchar option )
{
	PServiceFunctionEnableStartCom::setCheckComSetBackFlg( PNLE_SelectBackGamenInit );		// 戻り元画面フラグの設定初期化.
	PServiceFunctionEnableStartCom::procReset( option );
}
//////////////////////////////////////////////////////////////
// 概要 : 工場調整モード／トレイ選択(50E00011) : 出力トレイテーブル設定用.
//////////////////////////////////////////////////////////////
void PFactorySelectTray::setSelectTrayTable( const SelectTrayComTbl* sc_tbl, uchar us_tbl )
{
	uc_SelectTrayNum = us_tbl;

	for( register ushort i = 0; i < uc_SelectTrayNum; i++ ) {	// テーブル1面目の値渡し.
		sc_SelectTrayTbl[i].dispType		= sc_tbl[i].dispType;
		sc_SelectTrayTbl[i].typeFeedAuto	= sc_tbl[i].typeFeedAuto;
		sc_SelectTrayTbl[i].typeFeedTray1	= sc_tbl[i].typeFeedTray1;
		sc_SelectTrayTbl[i].typeFeedTray2	= sc_tbl[i].typeFeedTray2;
		sc_SelectTrayTbl[i].typeFeedTray3	= sc_tbl[i].typeFeedTray3;
		sc_SelectTrayTbl[i].typeFeedTray4	= sc_tbl[i].typeFeedTray4;
		sc_SelectTrayTbl[i].typeFeedManual	= sc_tbl[i].typeFeedManual;
		sc_SelectTrayTbl[i].typeFeedLCT		= sc_tbl[i].typeFeedLCT;
	}
}

//////////////////////////////////////////////////////////////
// 概要 : 工場調整モード／用紙サイズ(50E00021) : 画面開始処理.
//////////////////////////////////////////////////////////////
void PFactorySelectPaperSize::startGamen()
{
// comment 2014/11/28 OPS1-Sky_nozaki [Poseidon][CQ507074] 手差し用紙検出画面表示後、設定が元に戻る問題.
	if( False == m_bl_isReturnPaperSizeGamen ){
	PServiceFunctionEnableStartCom::startGamen();	// ファンクション共通開始処理
	CheckAndExecInit();								// 初期化必要か否か取得して必要なら実行する

	ss_dispPaperSize = PServiceFunctionEnableStartCom::getInitSelectPaperSize();	// 表示パターン取得.
	e_SelectPaperSize = PServiceFunctionEnableStartCom::getSelectPaperSize();		// 選択中の用紙サイズ取得.
	}else{
		// 基底クラスのstartGamen()をコール.
		PBasicMessageProc::startGamen();
	}
}
//////////////////////////////////////////////////////////////
// 概要 : 工場調整モード／用紙サイズ(50E00021) : ボタン（押された）.
//////////////////////////////////////////////////////////////
void PFactorySelectPaperSize::procButtonOn( uchar option )
{
	switch( option )
	{
		// 用紙サイズのキー.
		case 0:		e_SelectPaperSize = TYPE_SizeCodeA3Sef;				break;	// Ａ３Ｔキー.
		case 1:		e_SelectPaperSize = TYPE_SizeCodeA4Sef;				break;	// Ａ４Ｔキー.
		case 2:		e_SelectPaperSize = TYPE_SizeCodeA4Lef;				break;	// Ａ４Ｙキー.
		case 3:		e_SelectPaperSize = TYPE_SizeCodeLedgerSef;			break;	// １１×１７Ｔ.
		case 4:		e_SelectPaperSize = TYPE_SizeCodeLetterSef;			break;	// ＬｅｔｔｅｒＴキー.
		case 5:		e_SelectPaperSize = TYPE_SizeCodeLetterLef;			break;	// ＬｅｔｔｅｒＹキー.
		case 6:		e_SelectPaperSize = TYPE_SizeCodePostcard_JpSef;	break;	// はがき.
//2016/05/30 CQ529920 sky草柳 ﾄﾚｲ毎の印刷位置調整の対応用紙サイズにA6SEFを追加 start.
#ifdef DEF_A4_Cus
		case 7:		e_SelectPaperSize = TYPE_SizeCodeA6Sef;				break;	// A6sefキー.
#endif //DEF_A4_Cus.
//2016/05/30 CQ529920 sky草柳 ﾄﾚｲ毎の印刷位置調整の対応用紙サイズにA6SEFを追加 end.
		default :	break;
	}
	setupGamen();	// 表示画面のセットアップ
}
