void PFactorySelectPaperSize::procOk( uchar option )
{
	PServiceFunctionEnableStartCom::setCheckComSetBackFlg( PNLE_SelectBackGamentoPaperSize );	// 戻り元画面フラグの設定.
	PServiceFunctionEnableStartCom::setSelectPaperSize( e_SelectPaperSize );
	nextGamen = PServiceFunctionEnableStartCom::prevServiceComGamen;		// 呼び出し元画面へ遷移.
}
//////////////////////////////////////////////////////////////
// 概要 : 工場調整モード／用紙サイズ(50E00021) : 表示画面のセットアップ.
//////////////////////////////////////////////////////////////
void PFactorySelectPaperSize::setupGamen( short option )
{
	register short _select = -1;

	switch( e_SelectPaperSize )
	{
		case TYPE_SizeCodeA3Sef:			_select = 0;		break;	// Ａ３Ｔ.
		case TYPE_SizeCodeA4Sef:			_select = 1;		break;	// Ａ４Ｔ.
		case TYPE_SizeCodeA4Lef:			_select = 2;		break;	// Ａ４Ｙ+.
		case TYPE_SizeCodeLedgerSef:		_select = 3;		break;	// １１×１７Ｔ.
		case TYPE_SizeCodeLetterSef:		_select = 4;		break;	// ＬｅｔｔｅｒＴ.
		case TYPE_SizeCodeLetterLef:		_select = 5;		break;	// ＬｅｔｔｅｒＹ.
		case TYPE_SizeCodePostcard_JpSef:	_select = 6;		break;	// はがき.
//2016/05/30 CQ529920 sky草柳 ﾄﾚｲ毎の印刷位置調整の対応用紙サイズにA6SEFを追加 start.
#ifdef DEF_A4_Cus
		case TYPE_SizeCodeA6Sef:			_select = 7;		break;	// A6sef.
#endif //DEF_A4_Cus.
//2016/05/30 CQ529920 sky草柳 ﾄﾚｲ毎の印刷位置調整の対応用紙サイズにA6SEFを追加 end.
		default:							_select = -1;		break;	// 上記以外のときは未選択.
	}
	Rbt_ServicePaperSizeSelection2.select( _select ); // 対象トレイを選択.

	for( register ushort i = 0; i<uc_SelectPaperSizeNum; i++ ) {
		if( ss_dispPaperSize == sc_SelectPaperSizeTbl[i].dispType ) {	// 表示パターン判定.
			if( sc_SelectPaperSizeTbl[i].typeSizeCodeA3Sef		== False ) { Key_ServicePaperSizeA3SEF.showEnable( False ); }
			if( sc_SelectPaperSizeTbl[i].typeCodeA4Sef			== False ) { Key_ServicePaperSizeA4SEF.showEnable( False ); }
			if( sc_SelectPaperSizeTbl[i].typeSizeCodeA4Lef		== False ) { Key_ServicePaperSizeA4LEF.showEnable( False ); }
			if( sc_SelectPaperSizeTbl[i].typeSizeCodeLedgerSef	== False ) { Key_ServicePaperSize11_17SEF.showEnable( False ); }
			if( sc_SelectPaperSizeTbl[i].typeSizeCodeLetterSef	== False ) { Key_ServicePaperSize8Half_11InchT.showEnable( False ); }
			if( sc_SelectPaperSizeTbl[i].typeSizeCodeLetterLef	== False ) { Key_ServicePaperSize8Half_11InchY.showEnable( False ); }
			if( sc_SelectPaperSizeTbl[i].typeSizeCodePostcard	== False ) { Key_ServicePaperSizePostcardSEF.showEnable( False ); }
//2016/05/30 CQ529920 sky草柳 ﾄﾚｲ毎の印刷位置調整の対応用紙サイズにA6SEFを追加 start.
#ifdef DEF_A4_Cus
			if( sc_SelectPaperSizeTbl[i].typeSizeCodeA6Sef		== False ) { Key_ServicePaperSizeA6SEF.showEnable( False ); }
#endif //DEF_A4_Cus.
//2016/05/30 CQ529920 sky草柳 ﾄﾚｲ毎の印刷位置調整の対応用紙サイズにA6SEFを追加 end.
		}
	}
	PServiceFunctionEnableStartCom::setupGamen( option );
	printLEDControl( False );	// LED赤.
}
//////////////////////////////////////////////////////////////
// 概要 : 工場調整モード／用紙サイズ(50E00021) : パネルリセット.
//////////////////////////////////////////////////////////////
void PFactorySelectPaperSize::procReset( uchar option )
{
	PServiceFunctionEnableStartCom::setCheckComSetBackFlg( PNLE_SelectBackGamenInit );		// 戻り元画面フラグの設定初期化.
	PServiceFunctionEnableStartCom::procReset( option );
}
//////////////////////////////////////////////////////////////
// 概要 : 工場調整モード／用紙サイズ(50E00021) : 用紙サイズテーブル設定用.
//////////////////////////////////////////////////////////////
void PFactorySelectPaperSize::setSelectPaperSizeTable( const SelectPaperSizeComTbl* sc_tbl, uchar us_tbl )
{
	uc_SelectPaperSizeNum = us_tbl;

	for( register ushort i = 0; i < uc_SelectPaperSizeNum; i++ ) {	// テーブル1面目の値渡し.
		sc_SelectPaperSizeTbl[i].dispType				= sc_tbl[i].dispType;
		sc_SelectPaperSizeTbl[i].typeSizeCodeA3Sef		= sc_tbl[i].typeSizeCodeA3Sef;
		sc_SelectPaperSizeTbl[i].typeCodeA4Sef			= sc_tbl[i].typeCodeA4Sef;
		sc_SelectPaperSizeTbl[i].typeSizeCodeA4Lef		= sc_tbl[i].typeSizeCodeA4Lef;
		sc_SelectPaperSizeTbl[i].typeSizeCodeLedgerSef	= sc_tbl[i].typeSizeCodeLedgerSef;
		sc_SelectPaperSizeTbl[i].typeSizeCodeLetterSef	= sc_tbl[i].typeSizeCodeLetterSef;
		sc_SelectPaperSizeTbl[i].typeSizeCodeLetterLef	= sc_tbl[i].typeSizeCodeLetterLef;
		sc_SelectPaperSizeTbl[i].typeSizeCodePostcard	= sc_tbl[i].typeSizeCodePostcard;
		sc_SelectPaperSizeTbl[i].typeSizeCodeA6Sef		= sc_tbl[i].typeSizeCodeA6Sef;
		sc_SelectPaperSizeTbl[i].typeSizeCodeIN4x6Sef	= sc_tbl[i].typeSizeCodeIN4x6Sef;
	}
}

