//////////////////////////////////////////////////////////////
// 概要		: カウンタ／データ／新品解除(50C00050) : 画面開始処理.
//////////////////////////////////////////////////////////////
void PServiceCounterNewReleaseBase::startGamen()
{
	PServiceFunctionEnableStartCom::startGamen();
	CheckAndExecInit(); // 初期化必要か否か取得して必要なら実行する
	ss_ButtonChoice = -1;
	setFunctionCode( TYPD_FNC_NotSet );     // ファンクションコード・未設定
}
//////////////////////////////////////////////////////////////
// 概要 	: カウンタ／データ／新品解除(50C00050) : ボタン（押された）.
//////////////////////////////////////////////////////////////
void PServiceCounterNewReleaseBase::procButtonOn( uchar option )
{
	switch( option ) {
// 2017/01/12 HCLT Vandana Modification for CQ 1011206 Start
#ifndef DEF_KRONOSS_Cus
		case 0:	// 定着ユニットを新品解除する.
			setFunctionCode( TYPD_FNC_FuserUnitCounterClear );
			break;
		case 1:	// 転写ベルトユニットを新品解除する.
			setFunctionCode( TYPD_FNC_TransBeltUnitCounterClear );
			break;
//Comment 2018/07/11 HCLT_Monisha [機器構成変更_No.21] adding drum unit and developing unit.
#ifdef DEF_DenebMLKCus
  		case 2:
   			setFunctionCode( TYPD_FNC_DrumUnitCounterClear );
   			break;
  		case 3:
   			setFunctionCode( TYPD_FNC_DevUnitCounterClear );
  			 break;
#endif
#ifdef DEF_A4_Cus
	case 2:	// 転写ローラーユニットを新品解除する.
		setFunctionCode( TYPD_FNC_2ndTransferRollerUnitCounterClear );
		break;
#endif // DEF_A4_Cus
#else
		case 0:	
				setFunctionCode( TYPD_FNC_FuserUnitCounterClear );
				break;
		case 1:	
				setFunctionCode( TYPD_FNC_FinisherCounterClear );
				break;
#endif // DEF_KRONOSS_Cus
// 2017/01/12 HCLT Vandana Modification for CQ 1011206 End
		default:
			break;
	}
	ss_ButtonChoice = option;
	setupGamen();
}
//////////////////////////////////////////////////////////////
// 概要 	: カウンタ／データ／新品解除(50C00050) : スタートキー.
//////////////////////////////////////////////////////////////
void PServiceCounterNewReleaseBase::procStart( uchar option )
{
	PServiceFunctionEnableStartCom::procStart( TYPE_FunctionStartTypeNORMAL );
}
//////////////////////////////////////////////////////////////
// 概要 	: カウンタ／データ／新品解除(50C00050) : 表示画面のセットアップ.
//////////////////////////////////////////////////////////////
void PServiceCounterNewReleaseBase::setupGamen( short option )
{
	Rbt_ServiceCounterNewReleaseSelectUnit.select( ss_ButtonChoice );
	PServiceFunctionCom::searchWithoutPaper_ENG( option );	// ファンクション画面共通処理.
}

//////////////////////////////////////////////////////////////
// 概要 	: カウンタ／データ／新品解除(50C00050) : OKキー通知.
//////////////////////////////////////////////////////////////
void PServiceCounterNewReleaseBase::procOk( uchar option )
{
	if( NULL != p_TurnGamen ) {
		nextGamen = p_TurnGamen;
	}
}

//////////////////////////////////////////////////////////////
// 概要 	: カウンタ／データ／新品解除(50C00050) : ファンクション終了.
