void PServiceSystemUserPaper::procButtonOn( uchar option )
{

// comment 2018/08/21 SCD2-4G吉田 [Eagle][1052786] 1200dpiの追加及び追加に伴う修正.
// comment 2018/11/05 【IT6_Sparrow】【HCLT_Taqiuddin】【AR1029580】 Warning Removal Fix.										
// Comment 2019/1/21 [HCL-Harish] [IT6 EagleH][Complier Switch handeling for EagleL and EagleH].
//#if defined( DEF_EaglePanel_Low )
//	ushort us_Select = 0;
//#endif
	switch( option ) {
		// ユーザー紙キー.
		case BTNID_ServiceUserPaper01:		// ユーザー紙1キー.
		case BTNID_ServiceUserPaper02:		// ユーザー紙2キー.
		case BTNID_ServiceUserPaper03:		// ユーザー紙3キー.
		case BTNID_ServiceUserPaper04:		// ユーザー紙4キー.
		case BTNID_ServiceUserPaper05:		// ユーザー紙5キー.
		case BTNID_ServiceUserPaper06:		// ユーザー紙6キー.
//	2019/08/03 SCD2 一ノ瀬【機器No.7】EagleZ+/Z+BK ユーザー紙7対応.
		case BTNID_ServiceUserPaper07:		// ユーザー紙7キー.
			// 値を設定する.
			FixedValues();
			// ユーザー紙種別を選択する.
			if ( option == BTNID_ServiceUserPaper07 ) {			//	2019/08/03 SCD2 一ノ瀬【機器No.7】EagleZ+/Z+BK ユーザー紙7対応.
// comment 2021/02/24 Sky東島 [MinervaSSBK][制御No10].
//#if defined( DEF_EagleZpCus ) || defined( DEF_EagleZBKpCus )
#if defined( DEF_EagleZpCus ) || defined( DEF_EagleZBKpCus ) || defined( DEF_MinervaSSBKCus )
				sc_selectUserPaper = PNLE_UserPaper07;
#endif	// defined( DEF_EagleZpCus ) || defined( DEF_EagleZBKpCus ) .
			} else {
				sc_selectUserPaper = option;
			}
			// 設定項目を坪量に設定する.
			sc_selectSettingItem = PNLE_SettingItemGramPerArea;
			uc_2ndTransferAdjustNowPage = 1;
			setPrinterIndi( GetDefinitionParameter( sc_selectUserPaper, sc_selectSettingItem ) );
			// 元の値を保持する.
			SetOriginalValue( sc_selectUserPaper );
			break;
		// 選択項目キー.
// comment 2018/08/21 SCD2-4G吉田 [Eagle][1052786] 1200dpiの追加及び追加に伴う修正.
// Comment 2018/11/28 【HCLT-Ranjith】【IT6_EagleH】 folder movement from EagleHi to common.
// #if defined( DEF_EaglePanel_Low )
// Comment 2019/1/29 [HCL-AppalaRaju] [IT6 EagleH][Complier Switch handeling for EagleL and EagleH].
//#if defined( DEF_EagleCus )
// Comment 2019/02/08[HCLT_Catherine][IT6_HeliosMLK][Seigyu.10 ]Blocking the common code for HeliosMLK.
//#if defined( DEF_EagleCus  ) || defined( DEF_EaglePanel_Low  ) || defined( DEF_EaglePanel_Hi )
#if ( defined( DEF_EagleCus  ) || defined( DEF_EaglePanel_Low  ) || defined( DEF_EaglePanel_Hi ) ) && !defined ( DEF_HeliosMLKCus )
		case BTNID_ServiceUserPaper1stColor:		// 1面目-ｶﾗｰキー.
		case BTNID_ServiceUserPaper1stBlack:		// 1面目-ﾌﾞﾗｯｸキー.
		case BTNID_ServiceUserPaper2ndColor:		// 2面目-ｶﾗｰキー.
		case BTNID_ServiceUserPaper2ndBlack:		// 2面目-ﾌﾞﾗｯｸキー.
		case BTNID_ServiceUserPaper600dpi1st:		// 600dpi-1面目キー.
		case BTNID_ServiceUserPaper600dpi2nd:		// 600dpi-2面目キー.
		case BTNID_ServiceUserPaper1200dpi1st:		// 1200dpi-1面目キー.
		case BTNID_ServiceUserPaper1200dpi2nd:		// 1200dpi-2面目キー.
		{
			for( ushort us_Select = 0 ; us_Select < us_UserPaperControl; us_Select++ ) {
				if ( ( option == st_UserPaperControl[us_Select].ss_option )
				&& ( sc_selectUserPaper == st_UserPaperControl[us_Select].e_UserSettingItem )
				&& ( uc_2ndTransferAdjustNowPage ==  st_UserPaperControl[us_Select].uc_2ndTransferAdjustNowPage ) ){
					sc_selectSettingItem = st_UserPaperControl[us_Select].e_SettingItem;
					setPrinterIndi( GetDefinitionParameter( sc_selectUserPaper, sc_selectSettingItem ) );
					break;
				}
			}
			break;
		}
#else
		case BTNID_ServiceUserPaper1stColor:		// 1面目-ｶﾗｰキー.
			sc_selectSettingItem = ( 1 == uc_2ndTransferAdjustNowPage ? PNLE_SettingItem600dpi1stColor : PNLE_SettingItem1200dpi1stColor );
			setPrinterIndi( GetDefinitionParameter( sc_selectUserPaper, sc_selectSettingItem ) );
			break;
		case BTNID_ServiceUserPaper1stBlack:		// 1面目-ﾌﾞﾗｯｸキー.
			sc_selectSettingItem = ( 1 == uc_2ndTransferAdjustNowPage ? PNLE_SettingItem600dpi1stBlack : PNLE_SettingItem1200dpi1stBlack );
			setPrinterIndi( GetDefinitionParameter( sc_selectUserPaper, sc_selectSettingItem ) );
			break;
		case BTNID_ServiceUserPaper2ndColor:		// 2面目-ｶﾗｰキー.
			sc_selectSettingItem = ( 1 == uc_2ndTransferAdjustNowPage ? PNLE_SettingItem600dpi2ndColor : PNLE_SettingItem1200dpi2ndColor );
			setPrinterIndi( GetDefinitionParameter( sc_selectUserPaper, sc_selectSettingItem ) );
			break;
		case BTNID_ServiceUserPaper2ndBlack:		// 2面目-ﾌﾞﾗｯｸキー.
			sc_selectSettingItem = ( 1 == uc_2ndTransferAdjustNowPage ? PNLE_SettingItem600dpi2ndBlack : PNLE_SettingItem1200dpi2ndBlack );
			setPrinterIndi( GetDefinitionParameter( sc_selectUserPaper, sc_selectSettingItem ) );
			break;
		case BTNID_ServiceUserPaper600dpi1st:		// 600dpi-1面目キー.
			sc_selectSettingItem =PNLE_SettingItem600dpi1st;
			setPrinterIndi( GetDefinitionParameter( sc_selectUserPaper, sc_selectSettingItem ) );
			break;
		case BTNID_ServiceUserPaper600dpi2nd:		// 600dpi-2面目キー.
			sc_selectSettingItem =PNLE_SettingItem600dpi2nd;
			setPrinterIndi( GetDefinitionParameter( sc_selectUserPaper, sc_selectSettingItem ) );
			break;
		case BTNID_ServiceUserPaper1200dpi1st:		// 1200dpi-1面目キー.
			sc_selectSettingItem =PNLE_SettingItem1200dpi1st;
			setPrinterIndi( GetDefinitionParameter( sc_selectUserPaper, sc_selectSettingItem ) );
			break;
		case BTNID_ServiceUserPaper1200dpi2nd:		// 1200dpi-2面目キー.
			sc_selectSettingItem =PNLE_SettingItem1200dpi2nd;
			setPrinterIndi( GetDefinitionParameter( sc_selectUserPaper, sc_selectSettingItem ) );
			break;
#endif
		case BTNID_ServiceUserPaperGramPerArea:		// 坪量キー.
			sc_selectSettingItem =PNLE_SettingItemGramPerArea;
			setPrinterIndi( GetDefinitionParameter( sc_selectUserPaper, sc_selectSettingItem ) );
			break;
		case BTNID_ServiceUserPaperTemp600dpi:		// 加熱側600dpiキー.
			sc_selectSettingItem =PNLE_SettingItem1stTemp600dpi;
			setPrinterIndi( GetDefinitionParameter( sc_selectUserPaper, sc_selectSettingItem ) );
			break;
		case BTNID_ServiceUserPaperTemp1200dpi:		// 加熱側1200dpiキー.
			sc_selectSettingItem =PNLE_SettingItem1stTemp1200dpi;
			setPrinterIndi( GetDefinitionParameter( sc_selectUserPaper, sc_selectSettingItem ) );
			break;
		case BTNID_ServiceUserPaperDown:			// サービスダウン.
			// 設定項目が坪量の場合.
			if( PNLE_SettingItemGramPerArea == sc_selectSettingItem ) {
				ushort i = 0;
				for( i = 0 ; i < uc_UserPaperConvSize; i++ ) {
					if( sc_selectUserPaper == st_UserPaperConv[i].sc_selectUserPaper ) {
						// Suppressed warning "Overrunning static array st_UserPaperConv, with 6 elements, at position 6 with index variable i".
						for( register ushort j = 0; j < us_PrinterIndiParameter; j++ ) {
							if( st_UserPaperConv[i].e_PrinterAdjust == sc_PrinterIndiParameter[ j ].indi ) {
								// 範囲指定外の場合は値をここで丸める.
								if( ( sc_PrinterIndiParameter[ j ].min > sc_PrinterIndiParameter[ j ].local_value )
								    || ( sc_PrinterIndiParameter[ j ].Max < sc_PrinterIndiParameter[ j ].local_value ) ) {
									sc_PrinterIndiParameter[ j ].local_value = sc_PrinterIndiParameter[ j ].min + sc_PrinterIndiParameter[ j ].step;
								}
								break;
							}
						}
						break;
					}
				}
				for( register ushort j = 0; j < us_PrinterIndiParameter; j++ ) {
					if( st_UserPaperConv[( uc_UserPaperConvSize == i ) ? i-1 : i].e_PrinterAdjust == sc_PrinterIndiParameter[ j ].indi ) {

						// 範囲指定外の場合は値をここで丸める.
						if( ( sc_PrinterIndiParameter[ j ].min > sc_PrinterIndiParameter[ j ].local_value )
						    || ( sc_PrinterIndiParameter[ j ].Max < sc_PrinterIndiParameter[ j ].local_value ) ) {
							sc_PrinterIndiParameter[ j ].local_value = sc_PrinterIndiParameter[ j ].min + sc_PrinterIndiParameter[ j ].step;
						}
						break;
					}
				}
			}
			subIndi(); break;
		case BTNID_ServiceUserPaperUp:	// サービスアップ.
			// 設定項目が坪量の場合.
			if( PNLE_SettingItemGramPerArea == sc_selectSettingItem ) {
				ushort i = 0;
				for( i = 0 ; i < uc_UserPaperConvSize; i++ ) {
					if( sc_selectUserPaper == st_UserPaperConv[i].sc_selectUserPaper ) {
						break;
					}
				}
				if( uc_UserPaperConvSize == i )	{
					i--;
				}
				for( register ushort j = 0; j < us_PrinterIndiParameter; j++ ) {
					if( st_UserPaperConv[i].e_PrinterAdjust == sc_PrinterIndiParameter[ j ].indi ) {
						// 範囲指定外の場合は値をここで丸める.
						if( ( sc_PrinterIndiParameter[ j ].min > sc_PrinterIndiParameter[ j ].local_value )
						    || ( sc_PrinterIndiParameter[ j ].Max < sc_PrinterIndiParameter[ j ].local_value ) ) {
							sc_PrinterIndiParameter[ j ].local_value = sc_PrinterIndiParameter[ j ].min - sc_PrinterIndiParameter[ j ].step;
						}
						break;
					}
				}
			}
			addIndi();	break;
		// 元に戻すキー.
		case 60:	// 元に戻すキー.
			// 復元対象の項目が有効であることを確認する.
			if( 0 < GetDefinitionParameter( sc_selectUserPaper, sc_selectSettingItem ) ) {
				// 復元対象の項目を、CommonAPIに保存されている値に変更する.
				if( PNLE_SettingItemGramPerArea == sc_selectSettingItem ) {	// 設定項目が坪量の場合は値を 0 （範囲外）に戻す可能性がある為setPrinterIndiをコールせず直接変更する.
					short ss_indi = GetDefinitionParameter( sc_selectUserPaper, sc_selectSettingItem );
					for( register ushort i = 0; i < us_PrinterIndiParameter; i++ ) {
						if( ss_indi == sc_PrinterIndiParameter[ i ].indi ) {
							sc_PrinterIndiParameter[ i ].local_value = GetOriginalValue( sc_selectSettingItem );
							break;
						}
					}
				} else {	// 設定項目が坪量以外の場合.
// Comment  2018/02/02 HCLT-Ravi [機器構成変更No.51][WP 1542] Modified to get the selected indi.
				    short ss_indi = GetDefinitionParameter( sc_selectUserPaper, sc_selectSettingItem );
//					setPrinterIndi( GetDefinitionParameter( sc_selectUserPaper, sc_selectSettingItem ), GetOriginalValue( sc_selectSettingItem ) );
					setPrinterIndi( ss_indi, GetOriginalValue( sc_selectSettingItem ) );
// Comment 2020/05/04 [HCLT-Hemachander] [IT6_2.0MR2][OP_BTS-22281] Restricting CurrentControl for Sparrow Model 
#if !defined(DEF_SparrowCus)
					for ( ushort us_Select = 0 ; us_Select < uc_userPaperCurrentCtlOnOffSize; us_Select++ ) {
			     		if  ( ss_indi == st_userPaperCurrentCtlOnOff[us_Select]. sc_2ndTransferIndi ){
							setPrinterIndi( st_userPaperCurrentCtlOnOff[us_Select].sc_currentCtlIndi,getPrinterIndiInSystem( st_userPaperCurrentCtlOnOff[us_Select].sc_currentCtlIndi ));
				       		 break;
						}
					}
#endif //DEF_SparrowCus.
				}
			}
			break;
		case BTNID_ServiceUserPaperSingleSide:	sc_selectPaperSide = 0;	break;	// 片面.
		case BTNID_ServiceUserPaper2Side:		sc_selectPaperSide = 1;	break;	// 両面1.
// comment 2015/03/13 HCL_Senthil [Helios][CQ510833] Paper interval is not applicable for Helios.
//// comment 2015/01/31 HCLT-Durga [Compilation Switch ID: 1543] for HeliosL support.
////#if (defined(DEF_TaigaCus) && !defined(DEF_DonauBKCus) ) || defined( DEF_Zeus5BkCus ).
//#if (defined(DEF_TaigaCus) && !defined(DEF_DonauBKCus) ) || defined( DEF_Zeus5BkCus ) || defined( DEF_HeliosCus ).
#if (defined(DEF_TaigaCus) && !defined(DEF_DonauBKCus) ) || defined( DEF_Zeus5BkCus )
		case BTNID_ServiceUserPaperInterval:	// 紙間側キー  - Print interval key.
			sc_selectSettingItem =PNLE_SettingItemPaperInterval;
			setPrinterIndi( GetDefinitionParameter( sc_selectUserPaper, sc_selectSettingItem ) );
			break;
#endif // DEF_TaigaSky <- Sky桑山 機器要望28 用紙種類の変更   [ #if (defined(DEF_TaigaCus) && !defined(DEF_DonauBKCus) ) || defined( DEF_Zeus5BkCus ) ].
		case BTNID_ServiceUserPaperPageChangeUp:
// comment 2018/08/21 SCD2-4G吉田 [Eagle][1052786] 1200dpiの追加及び追加に伴う修正.
// Comment 2019/1/29 [HCL-AppalaRaju] [IT6 EagleH][Complier Switch handeling for EagleL and EagleH].
//// Comment 2018/11/28 【HCLT-Ranjith】【IT6_EagleH】 folder movement from EagleHi to common.
//// #if defined( DEF_EaglePanel_Low )
//#if defined( DEF_EagleCus )
#if defined( DEF_EagleCus  ) || defined( DEF_EaglePanel_Low  ) || defined( DEF_EaglePanel_Hi )
			if ( ( 0 <= sc_selectUserPaper )&& ( 2 > sc_selectUserPaper ) ) {

				if( 1 == uc_2ndTransferAdjustNowPage ) {
					uc_2ndTransferAdjustNowPage = 3;		// 3ページ目.
				} else {
					uc_2ndTransferAdjustNowPage--;			// 1・2ページ目.
				}		
			}else if ( ( 2 <= sc_selectUserPaper ) && ( MaxUserPaper > sc_selectUserPaper ) ){
				if( 1 == uc_2ndTransferAdjustNowPage ) {
					uc_2ndTransferAdjustNowPage++;			// 2ページ目.
				} else {
					uc_2ndTransferAdjustNowPage--;			// 1ページ目.
				}
			}
			break;
#endif
		case BTNID_ServiceUserPaperPageChangeDown:
// Comment 2019/1/29 [HCL-AppalaRaju] [IT6 EagleH][Complier Switch handeling for EagleL and EagleH].
//// Comment 2018/11/28 【HCLT-Ranjith】【IT6_EagleH】 folder movement from EagleHi to common.
//// #if defined( DEF_EaglePanel_Low )
//#if defined( DEF_EagleCus )
#if defined( DEF_EagleCus  ) || defined( DEF_EaglePanel_Low  ) || defined( DEF_EaglePanel_Hi )
			if (0 <= sc_selectUserPaper && 2 > sc_selectUserPaper) {

				if( 3 == uc_2ndTransferAdjustNowPage ) {
					uc_2ndTransferAdjustNowPage = 1;		// 1ページ目.
				} else {
					uc_2ndTransferAdjustNowPage++;			// 2・3ページ目.
				}
			}else if ( 2 <= sc_selectUserPaper && MaxUserPaper > sc_selectUserPaper){
				if( 1 == uc_2ndTransferAdjustNowPage ) {
					uc_2ndTransferAdjustNowPage++;			// 2ページ目.
				} else {
					uc_2ndTransferAdjustNowPage--;			// 1ページ目.
				}
			}
			break;			
#else
			if( 1 == uc_2ndTransferAdjustNowPage ) {
				uc_2ndTransferAdjustNowPage++;			// 2ページ目.
			} else {
				uc_2ndTransferAdjustNowPage--;			// 1ページ目.
			}
			break;
#endif
// Comment  2018/02/02 HCLT-Ravi [機器構成変更No.51][WP 1542] Added current control key.
// Comment 2020/05/04 [HCLT-Hemachander] [IT6_2.0MR2][OP_BTS-22281] Restricting CurrentControl for Sparrow Model 
#if !defined(DEF_SparrowCus)
		case BTNID_ServiceUserPaperOn:
		case BTNID_ServiceUserPaperOff:
			{
				short ss_indi = GetDefinitionParameter( sc_selectUserPaper, sc_selectSettingItem );
				for ( ushort us_Select = 0 ; us_Select < uc_userPaperCurrentCtlOnOffSize; us_Select++ ) {
					if  ( ss_indi == st_userPaperCurrentCtlOnOff[us_Select]. sc_2ndTransferIndi ) {
							setPrinterIndi( st_userPaperCurrentCtlOnOff[us_Select].sc_currentCtlIndi,(option == BTNID_ServiceUserPaperOff) ? 1 : 0 );
					        break;
					}
				}
			}
			break;
#endif // DEF_SparrowCus.
		default: break;
	}
	setupGamen();
}
// comment 2015/08/25 OPS1-Sky_後藤 [ZeusS_ZX0][機器No.60]2次転写微調整-光沢追加対応.
