//////////////////////////////////////////////////////////////
// 概要		: システム設定／ユーザー紙設定(50C91560) : 画面開始処理.
//////////////////////////////////////////////////////////////
void PServiceSystemUserPaper::startGamen()
{
	PServiceFunctionEnableStartCom::startGamen();
	setFunctionFeedCode( TYPE_FeedTrayManual );	// コピージョブの給紙口を手差しに設定.
	setSelectFeedTray( TYPE_FeedTrayManual );											// 給紙口は手差し固定.
	setFunctionCode( TYPD_FNC_UserPaperAdjustPrint );									// ユーザー指定紙調整からのテストプリント.
	// 初期表示を設定する.
	sc_selectUserPaper = 0;		// ユーザー紙1キー.
	sc_selectSettingItem =PNLE_SettingItemGramPerArea;	// 坪量キー.
	uc_2ndTransferAdjustNowPage = 1;					// 2次転写微調ページ数.
	sc_selectPaperSide = 0;		// 片面.
	LoadValues();
	setPrinterIndi( GetDefinitionParameter( sc_selectUserPaper, sc_selectSettingItem ) );
	SetOriginalValue( sc_selectUserPaper );	// 2008/11/25 12下島 登録No.311040 テーブル初期化漏れ対応.

	for( ushort i = 0; i < us_PrinterIndiParameter; i++ ) {
		if( TYPE_PrinterAdjustFuserTempUser6Upper == sc_PrinterIndiParameter[ i ].indi ) {
			if( TYPE_CategoryState_ENABLE == PnlComGetEnablerSetting()->getFEK_CotegoryState( TYPE_FEKType19 ) ) {
				// ラミネート.
				sc_PrinterIndiParameter[ i ].Max =  10;
				// 範囲指定外の場合は値をここで丸める.
				if( sc_PrinterIndiParameter[ i ].Max < sc_PrinterIndiParameter[ i ].local_value ) {
					sc_PrinterIndiParameter[ i ].local_value = sc_PrinterIndiParameter[ i ].Max;
				}
			} else {
				// ユーザー紙6.
// comment 2016/10/25 【HCLT-Gomathy】 【MinervaMLK】 【制御構成変更_No.1】 Removing MinervaMLK Compiler Switch. 
// comment 2016/03/11 OPS1-Sky石賀 [MinervaMLK] MinervaMLKビルド対応①.
// comment 2015/02/13 【HCLT-Dhivya】 【MinervaSBK】 【制御構成変更_No.1】 Adding Compiler Switch for MinervaSBK.
//#if defined(DEF_MinervaBKCus) || defined(DEF_MinervaBKEmu) || defined ( DEF_MINERVASBK_CUS )
//#if defined(DEF_MinervaBKCus) || defined(DEF_MinervaBKEmu) || defined ( DEF_MINERVASBK_CUS ) || defined ( DEF_MINERVAMLK_CUS )
#if defined(DEF_MinervaBKCus) || defined(DEF_MinervaBKEmu) || defined ( DEF_MINERVASBK_CUS )
				sc_PrinterIndiParameter[ i ].Max = 15;
#else
				sc_PrinterIndiParameter[ i ].Max = 10;
#endif
			}
		} else if( TYPE_PrinterAdjustFuserTemp1200dpiUser6Upper == sc_PrinterIndiParameter[ i ].indi ) {
			if( TYPE_CategoryState_ENABLE == PnlComGetEnablerSetting()->getFEK_CotegoryState( TYPE_FEKType19 ) ) {
				// ラミネート.
				sc_PrinterIndiParameter[ i ].Max =  10;
				// 範囲指定外の場合は値をここで丸める.
				if( sc_PrinterIndiParameter[ i ].Max < sc_PrinterIndiParameter[ i ].local_value ) {
					sc_PrinterIndiParameter[ i ].local_value = sc_PrinterIndiParameter[ i ].Max;
				}
			} else {
				// ユーザー紙6.
// comment 2016/10/25 【HCLT-Gomathy】 【MinervaMLK】 【制御構成変更_No.1】 Removing MinervaMLK Compiler Switch. 
// comment 2016/03/11 OPS1-Sky石賀 [MinervaMLK] MinervaMLKビルド対応①.
// comment 2015/02/13 【HCLT-Dhivya】 【MinervaSBK】 【制御構成変更_No.1】 Adding Compiler Switch for MinervaSBK.
//#if defined(DEF_MinervaBKCus) || defined(DEF_MinervaBKEmu) || defined ( DEF_MINERVASBK_CUS )
//#if defined(DEF_MinervaBKCus) || defined(DEF_MinervaBKEmu) || defined ( DEF_MINERVASBK_CUS ) || defined ( DEF_MINERVAMLK_CUS )
#if defined(DEF_MinervaBKCus) || defined(DEF_MinervaBKEmu) || defined ( DEF_MINERVASBK_CUS )
				sc_PrinterIndiParameter[ i ].Max = 15;
#else
				sc_PrinterIndiParameter[ i ].Max = 10;
#endif
			}
		}
	}
}

//////////////////////////////////////////////////////////////
// 概要		: システム設定／ユーザー紙設定(50C91560) : ボタン（押し続け、速く変化）.
//////////////////////////////////////////////////////////////
void PServiceSystemUserPaper::procButtonStillOnFast( uchar option )
{
	// サービス ダウン/アップキーが連続で押された場合、procButtonOnメソッドを呼び出す.
	if( 15 == option || 16 == option ) { procButtonOn( option ); }
}

//////////////////////////////////////////////////////////////
// 概要		: システム設定／ユーザー紙設定(50C91560) : ﾕｰｻﾞｰ紙定義取得.
//////////////////////////////////////////////////////////////
// Comment 2017/10/10 【IT6_Eagle】【HCL_Satheesh】 【制御構成変更_No.1】 Compiler Switch Activity.
// Comment 2018/11/28 【HCLT-Ranjith】【IT6_EagleH】 folder movement from EagleHi to common.
// #if !defined( DEF_EaglePanel_Hi )  // 暫定：ZeusSMLKEmuはZeusSZX0を流用。ZeusSMLK/ZeusSBkMLK機種では正式対応が必要.
short PServiceSystemUserPaper::GetDefinitionParameter( const char& selectedUserPaper, const char& selectedSettingItem ) const
{
	//	引数の妥当性を確認する.
//	if( 0 > selectedUserPaper || 5 < selectedUserPaper ) { return ( -1 ); }
	if( 0 > selectedUserPaper || MaxUserPaper < selectedUserPaper ) { return ( -1 ); }		//	2019/08/02 SCD2 一ノ瀬【機器No.7】EagleZ+/Z+BK ユーザー紙7対応.

	const uchar uc_selectedUserPaper = ( const uchar )selectedUserPaper;

	if( 0 > selectedSettingItem || MaxSettingItem < selectedSettingItem ) { return ( -1 ); }	// Taiga_Sky Sky清水 CQ319074.
	short retValue = -1;
	switch( selectedSettingItem ) {
		case PNLE_SettingItem600dpi1stColor: retValue = tbl_userPaper[uc_selectedUserPaper].ss_PrinterAdjust600dpi1stColor; break;		// 600dpi-1面目-ｶﾗｰキー.
		case PNLE_SettingItem600dpi1stBlack: retValue = tbl_userPaper[uc_selectedUserPaper].ss_PrinterAdjust600dpi1stBlack; break;		// 600dpi-1面目-ﾌﾞﾗｯｸキー.
		case PNLE_SettingItem600dpi2ndColor: retValue = tbl_userPaper[uc_selectedUserPaper].ss_PrinterAdjust600dpi2ndColor; break;		// 600dpi-2面目-ｶﾗｰキー.
// comment 2018/08/22 SCD2-4G吉田 [Eagle][1052786] 1200dpiの追加及び追加に伴う修正.
// Comment 2018/11/28 【HCLT-Ranjith】【IT6_EagleH】 folder movement from EagleHi to common.
// #if defined( DEF_EaglePanel_Low )
// Comment 2019/1/29 [HCL-AppalaRaju] [IT6 EagleH][Complier Switch handeling for EagleL and EagleH].
//#if defined( DEF_EagleCus )
// Comment 2019/10/17 [HCL-Thangachamy] [IT6_HeliosMLK] [機器構成変更_No.1] Restrict glossy paper for HeliosMLK.
//#if defined( DEF_EagleCus  ) || defined( DEF_EaglePanel_Low  ) || defined( DEF_EaglePanel_Hi )
#if ( defined( DEF_EagleCus  ) || defined( DEF_EaglePanel_Low  ) || defined( DEF_EaglePanel_Hi ) ) && !defined DEF_HeliosMLKCus
		case PNLE_SettingItem600dpi1stLightGloss: retValue = tbl_userPaper[uc_selectedUserPaper].ss_PrinterAdjust600dpiLightGloss; break;	// 600dpi-光沢キー.
#endif //#if defined( DEF_EaglePanel_Low )
		case PNLE_SettingItem600dpi2ndBlack: retValue = tbl_userPaper[uc_selectedUserPaper].ss_PrinterAdjust600dpi2ndBlack; break;		// 600dpi-2面目-ﾌﾞﾗｯｸキー.
		case PNLE_SettingItem1200dpi1stColor: retValue = tbl_userPaper[uc_selectedUserPaper].ss_PrinterAdjust1200dpi1stColor; break;	// 1200dpi-1面目-ｶﾗｰキー.
		case PNLE_SettingItem1200dpi1stBlack: retValue = tbl_userPaper[uc_selectedUserPaper].ss_PrinterAdjust1200dpi1stBlack; break;	// 1200dpi-1面目-ﾌﾞﾗｯｸキー.
		case PNLE_SettingItem1200dpi2ndColor: retValue = tbl_userPaper[uc_selectedUserPaper].ss_PrinterAdjust1200dpi2ndColor; break;	// 1200dpi-2面目-ｶﾗｰキー.
		case PNLE_SettingItem1200dpi2ndBlack: retValue = tbl_userPaper[uc_selectedUserPaper].ss_PrinterAdjust1200dpi2ndBlack; break;	// 1200dpi-2面目-ﾌﾞﾗｯｸキー.
		case PNLE_SettingItem600dpi1st: retValue = tbl_userPaper[uc_selectedUserPaper].ss_PrinterAdjust600dpi1st;		break;			// 600dpi-1面目キー.
		case PNLE_SettingItem600dpi2nd: retValue = tbl_userPaper[uc_selectedUserPaper].ss_PrinterAdjust600dpi2nd;		break;			// 600dpi-2面目キー.
		case PNLE_SettingItem1200dpi1st: retValue = tbl_userPaper[uc_selectedUserPaper].ss_PrinterAdjust1200dpi1st;	break;			// 1200dpi-1面目キー.
		case PNLE_SettingItem1200dpi2nd: retValue = tbl_userPaper[uc_selectedUserPaper].ss_PrinterAdjust1200dpi2nd;	break;			// 1200dpi-2面目キー.
		case PNLE_SettingItemGramPerArea: retValue = tbl_userPaper[uc_selectedUserPaper].ss_PrinterAdjustGramPerArea;		break;		// 坪量キー.
		case PNLE_SettingItem1stTemp600dpi: retValue = tbl_userPaper[uc_selectedUserPaper].ss_PrinterAdjustTemp600dpi;		break;		// 加熱側600dpiキー.
		case PNLE_SettingItem1stTemp1200dpi: retValue = tbl_userPaper[uc_selectedUserPaper].ss_PrinterAdjustTemp1200dpi;	break;		// 加熱側1200dpiキー.
// comment 2015/03/13 HCL_Senthil [Helios][CQ510833] Paper interval is not applicable for Helios.
//// comment 2015/01/31 HCLT-Durga [Compilation Switch ID: 1545] for HeliosL support.		
////// comment 2014/07/31 HCLT-Vikash [Poseidon][機器構成変更_No.8] Adding Compiler switch to enable setting up Paper Interval value.
////#if ( defined(DEF_TaigaCus) && !defined(DEF_DonauBKCus) ) || defined( DEF_Zeus5BkCus )
//#if ( defined(DEF_TaigaCus) && !defined(DEF_DonauBKCus) ) || defined( DEF_Zeus5BkCus ) || defined( DEF_HeliosCus ).
#if ( defined(DEF_TaigaCus) && !defined(DEF_DonauBKCus) ) || defined( DEF_Zeus5BkCus )
		case PNLE_SettingItemPaperInterval: retValue = tbl_userPaper[uc_selectedUserPaper].ss_PrinterAdjustPaperInterval; break;	// 紙間キー  - Paper key.
#endif // #if ( defined(DEF_TaigaCus) && !defined(DEF_DonauBKCus) ) || defined( DEF_Zeus5BkCus ) || defined( DEF_HeliosCus ) .
		default: break;
	}
	return ( retValue );
}

