//////////////////////////////////////////////////////////////
// 概要		: システム設定／ユーザー紙設定(50C91560) : 調整値の確定.
//////////////////////////////////////////////////////////////
void PServiceSystemUserPaper::FixedValues()
{
	// ﾕｰｻﾞ-指定紙.
	for( char sc_indexUserPaper = 0; MaxUserPaper > sc_indexUserPaper; ++sc_indexUserPaper ) {
		// 選択項目.
		for( char sc_indexSettingItem = 0; MaxSettingItem > sc_indexSettingItem; ++sc_indexSettingItem ) {
			// 確定対象の項目が有効であることを確認する.
			if( 0 < GetDefinitionParameter( sc_indexUserPaper, sc_indexSettingItem ) ) {
// Comment  2018/02/02 HCLT-Ravi [機器構成変更No.51][WP 1542] Check for current control fixed value.
				short ss_indi = GetDefinitionParameter( sc_indexUserPaper, sc_indexSettingItem );
				// 確定対象の項目を、CommonAPIに設定する.
//				fixPrinterIndi( GetDefinitionParameter( sc_indexUserPaper, sc_indexSettingItem ) );
				fixPrinterIndi( ss_indi );
// Comment  2018/02/02 HCLT-Ravi [機器構成変更No.51][WP 1542] Check for current control fixed value.
// Comment 2020/05/04 [HCLT-Hemachander] [IT6_2.0MR2][OP_BTS-22281] Restricting CurrentControl for Sparrow Model 
#if !defined(DEF_SparrowCus)
				for ( ushort us_Select = 0 ; us_Select < uc_userPaperCurrentCtlOnOffSize; us_Select++ ) {
			     	if  ( ss_indi == st_userPaperCurrentCtlOnOff[us_Select]. sc_2ndTransferIndi ) {
							fixPrinterIndi( st_userPaperCurrentCtlOnOff[us_Select].sc_currentCtlIndi);
				       		 break;
					}
				}
#endif //DEF_SparrowCus.
			}
		}
	}
}

//////////////////////////////////////////////////////////////
// 概要		: システム設定／ユーザー紙設定(50C91560) : 調整値の読込.
//////////////////////////////////////////////////////////////
void PServiceSystemUserPaper::LoadValues()
{
	// ﾕｰｻﾞ-指定紙.
	for( char sc_indexUserPaper = 0; MaxUserPaper > sc_indexUserPaper; ++sc_indexUserPaper ) {
		// 選択項目.
		for( char sc_indexSettingItem = 0; MaxSettingItem > sc_indexSettingItem; ++sc_indexSettingItem ) {
			// 読込対象の項目が有効であることを確認する.
			if( 0 < GetDefinitionParameter( sc_indexUserPaper, sc_indexSettingItem ) ) {
				// Comment  2018/02/02 HCLT-Ravi [機器構成変更No.51][WP 1542] Check for current control load value.
				short ss_indi = GetDefinitionParameter( sc_indexUserPaper, sc_indexSettingItem );
				// 読込対象の項目を、CommonAPIに設定する.
//				setPrinterIndi( GetDefinitionParameter( sc_indexUserPaper, sc_indexSettingItem ), getPrinterIndiInSystem( GetDefinitionParameter( sc_indexUserPaper, sc_indexSettingItem ) ) );
				setPrinterIndi( ss_indi, getPrinterIndiInSystem( GetDefinitionParameter( sc_indexUserPaper, sc_indexSettingItem ) ) );
// Comment 2020/05/04 [HCLT-Hemachander] [IT6_2.0MR2][OP_BTS-22281] Restricting CurrentControl for Sparrow Model 
#if !defined(DEF_SparrowCus)
				for ( ushort us_Select = 0 ; us_Select < uc_userPaperCurrentCtlOnOffSize; us_Select++ ) {
			     	if  ( ss_indi == st_userPaperCurrentCtlOnOff[us_Select]. sc_2ndTransferIndi ){
							setPrinterIndi( st_userPaperCurrentCtlOnOff[us_Select].sc_currentCtlIndi,getPrinterIndiInSystem( st_userPaperCurrentCtlOnOff[us_Select].sc_currentCtlIndi ));
				       		 break;
					}
				}
#endif //DEF_SparrowCus.
			}
		}
	}
}

//////////////////////////////////////////////////////////////
// 概要		: システム設定／ユーザー紙設定(50C91560) : 調整値(元の値)の設定.
//////////////////////////////////////////////////////////////
void PServiceSystemUserPaper::SetOriginalValue( const short& ss_userPaper )
{
	if( 0 <= ss_userPaper && MaxUserPaper > ss_userPaper ) {
		// 選択項目.
		const char sc_userPaper = static_cast<const char>( ss_userPaper );
		char sc_indexSettingItem = 0;
		for( short ss_indexSettingItem = 0; MaxSettingItem > ss_indexSettingItem; ++ss_indexSettingItem ) {
			// 読込対象の項目が有効であることを確認する.
			sc_indexSettingItem = static_cast<char>( ss_indexSettingItem );
			if( 0 < GetDefinitionParameter( sc_userPaper, sc_indexSettingItem ) ) {
				ss_keepValues[ ss_indexSettingItem] = getPrinterIndiInSystem( GetDefinitionParameter( sc_userPaper, sc_indexSettingItem ) );
			}
		}
	}
}

//////////////////////////////////////////////////////////////
// 概要		: システム設定／ユーザー紙設定(50C91560) : 調整値(元の値)の取得.
//////////////////////////////////////////////////////////////
short PServiceSystemUserPaper::GetOriginalValue( const short& ss_settingItem )
{
	if( 0 <= ss_settingItem && MaxSettingItem > ss_settingItem ) {
		return ( ss_keepValues[ss_settingItem] );
	} else {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );	// 上記以外はありえない.
		return 0;
	}
}

