// 概要 ： 52C91580 システム設定／CIS画質調整 : 変数初期化.
void PServiceCISImageAdjust::init_value()
{
	setScannerIndi( TYPE_ScannerAdjustLightnessAdjustBack );	// 明度.
	// ＡＰＩから値を取得する.
	getScannerIndiInSystem( TYPE_ScannerAdjustLightnessAdjustBack );	// 明度.
	getScannerIndiInSystem( TYPE_ScannerAdjustChromaAdjustBack );		// 彩度.
	getScannerIndiInSystem( TYPE_ScannerAdjustHueAdjustBack );			// 色相.
}
// 概要 ： 52C91580 システム設定／CIS画質調整 : 設定終了.
void PServiceCISImageAdjust::procOk( uchar option )
{
	fixScannerIndi( TYPE_ScannerAdjustLightnessAdjustBack );	// 明度.
	fixScannerIndi( TYPE_ScannerAdjustChromaAdjustBack );		// 彩度.
	fixScannerIndi( TYPE_ScannerAdjustHueAdjustBack );			// 色相.
	nextGamen = &gp_ServiceSystemMenu2P2_DoAm;	// 91500b-2_Do システム設定2／メニュー 2P選択時.
}
// 概要 ： 52C91580 システム設定／CIS画質調整 : ボタン(押された).
void PServiceCISImageAdjust::procButtonOn( uchar option )
{
	switch( option ) {
		case BTNID_ServiceCISImageAdjustBrightness:		setScannerIndi( TYPE_ScannerAdjustLightnessAdjustBack );	break;	// 明度.
		case BTNID_ServiceCISImageAdjustChromaLevel:	setScannerIndi( TYPE_ScannerAdjustChromaAdjustBack );		break;	// 彩度.
		case BTNID_ServiceCISImageAdjustHueLevel:		setScannerIndi( TYPE_ScannerAdjustHueAdjustBack );			break;	// 色相.
// comment 2015/08/13 HCLT_Anusha [MiSBK][CQ517148] Changed the Button ID to receive the message properly for "+" and "-" buttons.
//		case 18:addIndi();	break;	// +キー.
//		case 19:subIndi();	break;	// -キー.
		case BTNID_PrinterAdjustFuserTempUp:	addIndi();	break;	// +キー.
		case BTNID_PrinterAdjustFuserTempDown:	subIndi();	break;	// -キー.
		case 60:	// 元に戻すキー.
			// 選択している項目のみ、画面に入ったときの値に戻す.
			switch( getIndiSelected() ) {
				case TYPE_ScannerAdjustLightnessAdjustBack: getScannerIndiInSystem( TYPE_ScannerAdjustLightnessAdjustBack ); break;	// 明度.
				case TYPE_ScannerAdjustChromaAdjustBack: getScannerIndiInSystem( TYPE_ScannerAdjustChromaAdjustBack ); break;		// 彩度.
				case TYPE_ScannerAdjustHueAdjustBack: getScannerIndiInSystem( TYPE_ScannerAdjustHueAdjustBack ); break;				// 色相.
				default: break;
			}
			break;
		default:break;
	}
	setupGamen();	// 表示部品のセットアップ.
}
