			m_e_DFType = APIE_DFTypeNoDF;
			break;
		case BTNID_KEY_ServiceADFSettingOneSideScan:	// 循環.
			m_e_DFType = APIE_DFTypeOneSideScan;
			break;
		case BTNID_KEY_ServiceADFSettingDualScan:		// 両面同時.
			m_e_DFType = APIE_DFTypeDualScan;
			break;
		default:
			break;
