// ================================================================================================.
void PServiceADFSetting::setupGamen( short option )
{
	PServiceToSystemMenu2P2Com::setupGamen( option );	// 表示部品のセットアップ.
	short sc_select = -1;
	switch( m_e_DFType ) {
		case APIE_DFTypeNoDF:				// 非装着.
			sc_select = BTNID_KEY_ServiceADFSettingNoDF;
			break;
		case APIE_DFTypeOneSideScan:		// 循環.
			sc_select = BTNID_KEY_ServiceADFSettingOneSideScan;
			break;
		case APIE_DFTypeDualScan:			// 両面同時.
			sc_select = BTNID_KEY_ServiceADFSettingDualScan;
			break;
		default:
			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
			break;
	}
	Rbt_ADFSetting.select( sc_select );	// ADF装着設定ローテーションボタンの選択.
// comment 2016/04/06 OPS1-Sky秋口 [特ROM][CQ527278]ADF設定で[両面同時読取装置] を設定するとトラブルコードC-6001.
// Comment 2019/07/26 [HCLT_Paul] [IT6_HeliosMLK] [ Seigyu.10 ] Adding the HeliosMLK compiler switch.
// Comment 2021/12/10 Sky牧瀬 [MinervaSSBK][TAS000000008366].
// [両面読取原稿送り]はDenebMLKでも非表示が仕様の為、条件追加.
//#if defined(DEF_Zeus5BkCus) || defined(DEF_HeliosMLKCus) || defined ( DEF_ICARUS_CUS )
#if defined(DEF_Zeus5BkCus) || defined(DEF_HeliosMLKCus) || defined ( DEF_ICARUS_CUS ) || defined( DEF_DenebMLKCus )
	PDisplayParts* pKey_ADFSettingDualScan = Rbt_ADFSetting.getPartsAddress(BTNID_KEY_ServiceADFSettingDualScan);
	if ( NULL != pKey_ADFSettingDualScan ) {
		pKey_ADFSettingDualScan->showEnable( False );
	}
#endif // #if defined(DEF_Zeus5BkCus) || defined(DEF_HeliosCus) || defined ( DEF_ICARUS_CUS )
}
const char PServiceAdjustSidePosition::KEY_BIND_UP_ADJUST = 0;			// 平とじ整合.
const char PServiceAdjustSidePosition::KEY_CENTER_STAPLE_ADJUST = 1;	// 中とじ整合.

//////////////////////////////////////////////////////////////
// 概要 : 整合横位置調整(50C00190) : 画面開始処理.
//////////////////////////////////////////////////////////////
void PServiceAdjustSidePosition::startGamen()
{
	// 親クラスの呼出し.
	PServiceFinisherAdjCom::startGamen();
	// システム値をローカルに取得する.
	getPrinterIndiInSystem( TYPE_FS526_AD_AdjustFlatStaple );		// 平とじ整合.
	getPrinterIndiInSystem( TYPE_FS526_AD_AdjustCenterStaple );	// 中とじ整合.
	// 初期は"平とじ整合"を選択する.
	sc_selectedKey = KEY_BIND_UP_ADJUST;
	setPrinterIndi( TYPE_FS526_AD_AdjustFlatStaple );
}

//////////////////////////////////////////////////////////////
// 概要 : 整合横位置調整(50C00190) : ボタン（押された）.
//////////////////////////////////////////////////////////////
void PServiceAdjustSidePosition::procButtonOn( uchar option )
{
	switch( option ) {
		case BTNID_KEY_ADD_VALUE:	addIndi();	break;	// +キー.
		case BTNID_KEY_SUB_VALUE:	subIndi();	break;	// -キー.
		case BTNID_KEY_BIND_ADJUST:				// 平とじ整合.
			sc_selectedKey = KEY_BIND_UP_ADJUST;
			setPrinterIndi( TYPE_FS526_AD_AdjustFlatStaple );
			break;
		case BTNID_KEY_CENTER_STAPLE_ADJUST:	// 中とじ整合.
			sc_selectedKey = KEY_CENTER_STAPLE_ADJUST;
			setPrinterIndi( TYPE_FS526_AD_AdjustCenterStaple );
			break;
		case 60:								// 元に戻すキー.
			if( KEY_BIND_UP_ADJUST == sc_selectedKey ) { setPrinterIndi( TYPE_FS526_AD_AdjustFlatStaple, getPrinterIndiInSystem( TYPE_FS526_AD_AdjustFlatStaple ) ); }
			else if( KEY_CENTER_STAPLE_ADJUST == sc_selectedKey ) { setPrinterIndi( TYPE_FS526_AD_AdjustCenterStaple, getPrinterIndiInSystem( TYPE_FS526_AD_AdjustCenterStaple ) ); }
			break;
		default: PServiceFinisherAdjCom::procButtonOn( option ); break;
	}
	setupGamen();
}
//////////////////////////////////////////////////////////////
// 概要 ：整合横位置調整(50C00190) : ボタン（押し続け、速く変化）.
//////////////////////////////////////////////////////////////
void PServiceAdjustSidePosition::procButtonStillOnFast( uchar option )
{
	if( option == BTNID_KEY_ADD_VALUE || option == BTNID_KEY_SUB_VALUE ) { procButtonOn( option ); }
}
//////////////////////////////////////////////////////////////
// 概要 : 整合横位置調整(50C00190) : OKボタン（押された）.
//////////////////////////////////////////////////////////////
void PServiceAdjustSidePosition::procOk( uchar option )
{
	// 設定値を確定する.
	fixPrinterIndi( TYPE_FS526_AD_AdjustFlatStaple );		// 平とじ整合.
	fixPrinterIndi( TYPE_FS526_AD_AdjustCenterStaple );	// 中とじ整合.
	// 親クラスを呼び出す.
	PServiceFinisherAdjCom::procOk( option );
}

//////////////////////////////////////////////////////////////
// 概要 : 整合横位置調整(50C00190) : 表示画面のセットアップ.
//////////////////////////////////////////////////////////////
void PServiceAdjustSidePosition::setupGamen( short option )
{
	// 親クラスを呼び出す.
	PServiceFinisherAdjCom::setupGamen( option );
	// ｻﾄﾞﾙﾕﾆｯﾄ非装着時は中とじ整合非表示.
	if( ( False == isHalfFoldEnable() ) && ( False == isCenterStapleFoldEnable() ) && ( False == isTriFoldEnable() ) ) {
		Key_ServiceCenterStapleAdjust.showEnable( False );
		Bak_Svcs93304NowValueArea2.showEnable( False );
	} else {
		Key_ServiceCenterStapleAdjust.showEnable( True );
		Bak_Svcs93304NowValueArea2.showEnable( True );
	}

	// 設定項目種別を表示する.
	if( KEY_BIND_UP_ADJUST == sc_selectedKey ) { Rbt_ServiceCenterUpAdjust.select( 0 ); }
	else if( KEY_CENTER_STAPLE_ADJUST == sc_selectedKey ) { Rbt_ServiceCenterUpAdjust.select( 1 ); }
	// 現在値を表示する.
	Bak_Svcs93304NowValueArea1 = ( float )getPrinterIndi( TYPE_FS526_AD_AdjustFlatStaple ) / 10.0f;		// 現在値表示エリア(平とじ整合).
	Bak_Svcs93304NowValueArea2 = ( float )getPrinterIndi( TYPE_FS526_AD_AdjustCenterStaple ) / 10.0f;	// 現在値表示エリア(中とじ整合).
	// 調整値を表示する.
	if( KEY_BIND_UP_ADJUST == sc_selectedKey ) { Inp_SvcsFNSPunchloopAdjValue = ( float )getPrinterIndi( TYPE_FS526_AD_AdjustFlatStaple ) / 10.0f; }
	else if( KEY_CENTER_STAPLE_ADJUST == sc_selectedKey ) { Inp_SvcsFNSPunchloopAdjValue = ( float )getPrinterIndi( TYPE_FS526_AD_AdjustCenterStaple ) / 10.0f; }
// comment 2015/02/12 HCLT_Chandrasekar  [Helios] [CQ 509894] Increased size of  Backgroundparts to display "Adjust value" in the input areas.
// Comment 2017/11/29 【HCLT-Vishal】【Eagle】【制御構成変更_No.4】 Removing old function version check and else portion.
	Bak_SvcsAdjustValueArea1.changeGraphic( PB_SvcsAwNewB );
    Bak_SvcsAdjustRangeArea1.changeGraphic( PB_SvcsAwNewW );
    Bak_SvcsAdjustValueArea1.changePosition( 492,232 );
    Bak_SvcsAdjustRangeArea1.changePosition( 492, 280 );
    Txt_ServiceAdjustM10ToP10.changePosition( 504, 292 );
    Txt_SvcsFNSAdjStep01.changePosition( 512, 314 );
    Key_PServiceAdjustValueUp.changePosition( 568, 348 );
    Key_PServiceAdjustValueDown.changePosition( 492, 348 );
	Txt_SvcsFNSAdjUnit_mm.changePosition( 562,244 );
	Inp_SvcsFNSPunchloopAdjValue.changePosition( 517, 244 );
}

TYPS_DirEntryInfo	PServiceUSBFileCheck::m_localinfo[ServiceUSBInfo_MaxGetFileCnt];	// ファイル情報.
short				PServiceUSBFileCheck::m_ssMaxFileCnt;								// USB内のファイル総数.
short				PServiceUSBFileCheck::m_ssFilePoint;								// 取得したファイル数.
//////////////////////////////////////////////////////////////
// 概要		:USBファイルチェック  チェックしたいファイルの設定.
//////////////////////////////////////////////////////////////
// 2018/09/13 Hikita RQ-676 OSS単独更新.
void PServiceUSBFileCheck::setCheckFiles( USBCheckFile* pUsbFiles, short ssFileCnt, Bool bAllMatch )
{
	m_pUsbFiles		 = pUsbFiles;
	m_ssCheckFileCnt = ssFileCnt;
	m_bAllMatch		 = bAllMatch;
	m_eUsbInfoStatus = ServiceUSBInfo_None;
}
//////////////////////////////////////////////////////////////
// 概要		:USBファイルチェック :  USBメモリの状態を表示するSinglePartsText設定.
//////////////////////////////////////////////////////////////
void PServiceUSBFileCheck::setUSBStatusText( PSinglePartsText* pText )
{
	m_pUSBStatusText = pText;
}

//////////////////////////////////////////////////////////////
// 概要		:USBファイルチェック :  USBメモリの状態で表示/非表示の切替が必要なパーツ設定.
//////////////////////////////////////////////////////////////
void PServiceUSBFileCheck::setShowEnableParts( PDisplayParts** ppParts, short ssPartsCnt )
{
	m_ppShowEnableParts		= ppParts;
	m_ssShowEnablePartsCnt	= ssPartsCnt;
}

//////////////////////////////////////////////////////////////
// 概要		:USBファイルチェック :  USBメモリチェックのみ(setupGamenから実行すること).
// 戻り値	:USBの状態.
// 変更履歴	:
//////////////////////////////////////////////////////////////
ServiceUSBInfo PServiceUSBFileCheck::checkOnly()
{
	ServiceUSBInfo e_usbInfo = ServiceUSBInfo_None;

	APIC_UsbMemDeviceInfo* pc_UsbMemDeviceInfo = APIC_UsbMemDeviceInfo::newInstance();

	if( pc_UsbMemDeviceInfo->getStatus() == 0 ) {
		// USBが刺さっていない.
		e_usbInfo = ServiceUSBInfo_Uninsertion;
	} else {
		if( m_eUsbInfoStatus == ServiceUSBInfo_None ||
		    m_eUsbInfoStatus == ServiceUSBInfo_Uninsertion ) {
			// 先ほどまで、USBメモリが未装着状態であったのであれば.
			// 装着されたUSBに必要なファイルがあるかどうかチェックする.
			checkUSB( );
			e_usbInfo = ServiceUSBInfo_Checking;
		} else if( m_eUsbInfoStatus == ServiceUSBInfo_Checking ) {
			// USBメモリチェック中.
			if( m_bUsbCheckingFlg == True ) {
				// チェック中の時は、そのままチェック中とする.
				e_usbInfo = ServiceUSBInfo_Checking;
			} else {
				// チェック完了の時は、チェック完とする.
				e_usbInfo = ServiceUSBInfo_CheckComplete;
			}
		} else {
			e_usbInfo = m_eUsbInfoStatus;
		}
	}

	m_eUsbInfoStatus = e_usbInfo;

	return e_usbInfo;
}
//////////////////////////////////////////////////////////////
// 概要		:USBファイルチェック :  USBメモリチェック及び表示(setupGamenから実行すること).
//////////////////////////////////////////////////////////////
void PServiceUSBFileCheck::checkAndShow( )
{
	ServiceUSBInfo e_usbInfo = checkOnly();		//  USBメモリチェックのみ.

	if( e_usbInfo == ServiceUSBInfo_Uninsertion ) {
		// USBメモリ未挿入.
		m_pUSBStatusText->changeText( s_ITMServiceUSBN );
		m_pUSBStatusText->showEnable( True );
		settingShowEnableParts( m_bForceShowFlg );
	} else {
		// USBメモリ挿入.
		Bool bFileOkFlg = True;

		for( int i=0; i<m_ssCheckFileCnt; i++ ) {
			if( m_pUsbFiles[i].bCheckEnableFlg == True ) {
				// ファイル存在チェックがONの場合は、ファイル存在チェックを行う.
				if( e_usbInfo == ServiceUSBInfo_Checking ) {
					// ファイル存在チェック中はひとまずエラーとしておく.
					bFileOkFlg = False;
					break;
				} else {
					// 2018/09/13 Hikita RQ-676 OSS単独更新.
					// 部分一致の場合は、ファイルが存在した時点でチェック終了.
					if( m_bAllMatch == False ) {
						if ( m_pUsbFiles[i].bFileExistence == True ) {
							bFileOkFlg = True;
							break;
						} else {
							bFileOkFlg = False;
						}
					}
					// ファイル存在チェック完了後は、ファイルが存在しなければエラー.
					else if( m_pUsbFiles[i].bFileExistence == False ) {
						bFileOkFlg = False;
						break;
					}
				}
			}
		}
		if( bFileOkFlg == True ) {
			// USB内にファイルが存在する場合.
			m_pUSBStatusText->showEnable( False );
			settingShowEnableParts( True );
		} else {
			// USB内にファイルが存在しない場合( ファイルＮＧを表示).
			m_pUSBStatusText->changeText( s_ITMServiceFileNG );
			m_pUSBStatusText->showEnable( ( e_usbInfo == ServiceUSBInfo_CheckComplete ) ); // ファイルチェック完了の時のみファイルNGを表示.

			settingShowEnableParts( False );
		}
	}
}

//////////////////////////////////////////////////////////////
// 概要		:USBファイルチェック : パーツの表示/非表示設定.
//////////////////////////////////////////////////////////////
void PServiceUSBFileCheck::settingShowEnableParts( Bool bEnable )
{
	for( int i=0; i<m_ssShowEnablePartsCnt; i++ ) {
		m_ppShowEnableParts[i]->showEnable( bEnable );

		if( bEnable == False ) {
			POnOffButton* pOnOffBtn = dynamic_cast<POnOffButton*>( m_ppShowEnableParts[i] );
			if( pOnOffBtn != NULL ) {
				// 表示を消す際はON/OFFボタンの選択状態は解除しておく.
				pOnOffBtn->select( False );
			}
		}
	}
}

//////////////////////////////////////////////////////////////
// 概要		:USBファイルチェック : setShowEnableParts()で指定したパーツの表示チェックを指定ファイルの有無でチェックするか否か.
//////////////////////////////////////////////////////////////
void PServiceUSBFileCheck::setEnableCheckFile( short ssFileId, Bool bCheckFlg )
{
	USBCheckFile* pUSBCheckFile = getUSBCheckFile( ssFileId );
	if( pUSBCheckFile != NULL ) {
		pUSBCheckFile->bCheckEnableFlg	= bCheckFlg;
	}
	setForceShow( False );
}

//////////////////////////////////////////////////////////////
// 概要		:USBファイルチェック : setShowEnableParts()で指定したパーツの強制表示設定.
//////////////////////////////////////////////////////////////
void PServiceUSBFileCheck::setForceShow( Bool bForceShowFlg )
{
	m_bForceShowFlg = bForceShowFlg;
}

//////////////////////////////////////////////////////////////
// 概要		:USBファイルチェック : ファイルIDより、USBCheckFileを取得.
//////////////////////////////////////////////////////////////
PServiceUSBFileCheck::USBCheckFile* PServiceUSBFileCheck::getUSBCheckFile( short ssFileId )
{
	for( int i=0; i<m_ssCheckFileCnt; i++ ) {
		if( m_pUsbFiles[i].ssFileID == ssFileId ) {
			return &m_pUsbFiles[i];
		}
	}
	return NULL;
}

//////////////////////////////////////////////////////////////
// 概要 : USBファイルチェック : 装着されたUSBチェック.
//////////////////////////////////////////////////////////////
void PServiceUSBFileCheck::checkUSB( )
{
	static TYPS_UsbMemAddress usbMemAddress; // 255+1バイトｻｲｽﾞの構造体と結構大きめなので Stackに用意せずStaticにしておく.
	static char dir[ sizeof( usbMemAddress.sc_DeviceName ) ];

	m_bUsbCheckingFlg = True;			// USBファイル存在チェック中とする.
	m_bForceShowFlg	  = False;			// 強制表示フラグはOFFにする.

	// USBメモリルートディレクトリアドレス取得.
	APIC_UsbMemDeviceInfo* pc_UsbMemDeviceInfo = APIC_UsbMemDeviceInfo::newInstance();
	usbMemAddress = pc_UsbMemDeviceInfo->getUsbMemAddress();

	memset( dir, '\0', sizeof( dir ) );
	strncpy( dir, usbMemAddress.sc_DeviceName, sizeof( dir )-1 );

	memset( m_localinfo, 0, sizeof( m_localinfo ) );

	// インストール済みファイルか否かの初期化.
	for( int i=0; i<m_ssCheckFileCnt; i++ ) {
		m_pUsbFiles[i].bFileExistence = False;
	}

	// ファイル数取得.
	m_ssFilePoint = 0;
	if( False != PLBC_FuncVersionCheck::isOK_Type3() ) {				// Donau拡張機能3、Amur機能拡張2以降.
		m_ssMaxFileCnt = APIF_SaaNumOfDirEntryUsb( TYPE_CharSetUTF8, usbMemAddress.sc_DeviceName );
	} else {
		m_ssMaxFileCnt = APIF_SaaNumOfDirEntryUsb( getCharSetForCAPI(), usbMemAddress.sc_DeviceName );
	}
	if( m_ssMaxFileCnt == 0 ) {
		// ファイルがひとつも存在しないUSBメモリは、必要なファイルも当然ないのでここまで.
		m_bUsbCheckingFlg = False;
		return;
	}

	if( False != PLBC_FuncVersionCheck::isOK_Type3() ) {				// Donau拡張機能3、Amur機能拡張2以降.
		// ファイル一覧取得(100個までしか取得しない).
		APIF_SaaGetDirEntryUsb( TYPE_CharSetUTF8, dir, m_localinfo, 0, ServiceUSBInfo_MaxGetFileCnt, ans_getFileForUSB );
	} else {
		// ファイル一覧取得(100個までしか取得しない).
		APIF_SaaGetDirEntryUsb( getCharSetForCAPI(), dir, m_localinfo, 0, ServiceUSBInfo_MaxGetFileCnt, ans_getFileForUSB );
	}


}

//////////////////////////////////////////////////////////////
// 概要 : USBファイルチェック : ファイル一覧取得通知.
//////////////////////////////////////////////////////////////
void PServiceUSBFileCheck::ans_getFileForUSB( TYPS_DirEntryInfo* s_DirEntryInfo, short ss_num )
{
	static char dir[ sizeof( m_localinfo[0].sc_name )];
	int i,j;
	for( i=0; i<ss_num; i++ ) {
		if( m_localinfo[i].s_stat.st_mode & S_IFDIR ) {
			// フォルダは無視.
		} else {
			strncpy( dir, m_localinfo[i].sc_name, sizeof( dir )-1 );
			// 大文字・小文字あわせ.
			for( j=0; static_cast<uint>( j )<strlen( dir ); j++ ) {
				//				　下のstrcmpで一致することなく、ファイルが存在しないと判断されていたのを修正
				dir[j] = ( char )tolower( dir[j] );
			}

			for( j=0; j<gp_ServiceUSBFileCheck.m_ssCheckFileCnt; j++ ) {

				if( strcmp( dir, gp_ServiceUSBFileCheck.m_pUsbFiles[j].pcCheckFile ) == 0 ) {
					// 必要なファイルが存在すれば、ファイル存在フラグを立てる.
					gp_ServiceUSBFileCheck.m_pUsbFiles[j].bFileExistence = True;
				}
			}
		}
	}

	m_ssFilePoint = static_cast<short>( m_ssFilePoint + ss_num );
	if( m_ssFilePoint < m_ssMaxFileCnt ) {
		/*
		 * 全ファイル取得が終わっていない場合は.
		 *  指定されたファイルが全部見つかっていなければ、次の100ファイルを取得しにいく.
		 */

		// 指定ファイルが全て見つかったかどうかチェック.
		Bool bAllCheckFlg = True;
		for( i=0; i<gp_ServiceUSBFileCheck.m_ssCheckFileCnt; i++ ) {
			if( gp_ServiceUSBFileCheck.m_pUsbFiles[i].bFileExistence == False ) {
				bAllCheckFlg = False;
				break;
			}
		}

		if( bAllCheckFlg == False ) {
			// 指定ファイル全て発見できていない場合は、更に100ファイル取得.
			memset( m_localinfo, 0, sizeof( m_localinfo ) );
			if( False != PLBC_FuncVersionCheck::isOK_Type3() ) {				// Donau拡張機能3、Amur機能拡張2以降.
				APIF_SaaGetDirEntryUsb( TYPE_CharSetUTF8, dir, m_localinfo, m_ssFilePoint, ServiceUSBInfo_MaxGetFileCnt, ans_getFileForUSB );
			} else {
				APIF_SaaGetDirEntryUsb( getCharSetForCAPI(), dir, m_localinfo, m_ssFilePoint, ServiceUSBInfo_MaxGetFileCnt, ans_getFileForUSB );
			}
			return;
		}
	}

	// USBファイルチェック完了(チェック中フラグをOFFにする).
	gp_ServiceUSBFileCheck.m_bUsbCheckingFlg = False;
}
