//////////////////////////////////////////////////////////////
// 概要		:USBファイルチェック :  USBメモリチェック及び表示(setupGamenから実行すること).
//////////////////////////////////////////////////////////////
void PServiceUSBFileCheckVariableSearch::checkAndShow( )
{
	ServiceUSBInfo e_usbInfo = ServiceUSBInfo_None;

	APIC_UsbMemDeviceInfo* pc_UsbMemDeviceInfo = APIC_UsbMemDeviceInfo::newInstance();

	if( pc_UsbMemDeviceInfo->getStatus() == 0 ) {
		// USBが刺さっていない.
		e_usbInfo = ServiceUSBInfo_Uninsertion;
	} else {
		if( m_eUsbInfoStatus == ServiceUSBInfo_None ||
		    m_eUsbInfoStatus == ServiceUSBInfo_Uninsertion ) {
			// 先ほどまで、USBメモリが未装着状態であったのであれば.
			// 装着されたUSBに必要なファイルがあるかどうかチェックする.
			checkUSB( );
			e_usbInfo = ServiceUSBInfo_Checking;
		} else if( m_eUsbInfoStatus == ServiceUSBInfo_Checking ) {
			// USBメモリチェック中.
			if( m_bUsbCheckingFlg == True ) {
				// チェック中の時は、そのままチェック中とする.
				e_usbInfo = ServiceUSBInfo_Checking;
			} else {
				// チェック完了の時は、チェック完とする.
				e_usbInfo = ServiceUSBInfo_CheckComplete;
			}
		} else {
			e_usbInfo = m_eUsbInfoStatus;
		}
	}

	m_eUsbInfoStatus = e_usbInfo;


	if( e_usbInfo == ServiceUSBInfo_Uninsertion ) {
		// USBメモリ未挿入.
		m_pUSBStatusText->changeText( s_ITMServiceUSBN );
		m_pUSBStatusText->showEnable( True );
		settingShowEnableParts( m_bForceShowFlg );
		
// Comment 2019/01/31 [HCL-Rajkumar] [IT6_EagleH] [AROP_BTS-2319] Reset the pUsbFiles files when unplug the USB.
		setCheckFiles( m_pUsbFiles, m_ssCheckFileCnt );
//comment 2019/02/26 HCLT-Naveena [IT6_EagleH] Warning Removal
//		if( BOOTUP_SCREEN_INSTALL_FILENAME_PREFIX == m_pUsbFiles[0].pcPrefix ) {
		if( 0 == strcmp( BOOTUP_SCREEN_INSTALL_FILENAME_PREFIX, m_pUsbFiles[0].pcPrefix ) ) {
			m_bl_MultipleFile	=	True;		//	Enable Multiple File Detection Flag.
		}

	} else {
		// USBメモリ挿入.
		Bool bFileOkFlg = True;

		for( int i=0; i<m_ssCheckFileCnt; i++ ) {
			if( m_pUsbFiles[i].bCheckEnableFlg == True ) {
				// ファイル存在チェックがONの場合は、ファイル存在チェックを行う.
				if( e_usbInfo == ServiceUSBInfo_Checking ) {
					// ファイル存在チェック中はひとまずエラーとしておく.
					bFileOkFlg = False;
					break;
				} else {
					// ファイル存在チェック完了後は、ファイルが存在しなければエラー.
					if( m_pUsbFiles[i].bFileExistence == False ) {
						bFileOkFlg = False;
						break;
					}
				}
			}
		}
//	comment 2014/12/14 HCLT_Naveen [HeliosL][制御構成変更_No.30] .Bin and .Zip Multiple File Detection.
		if ( True == m_bl_MultipleFile ) {							//	When Multiple File Detection Flag is Enable.
			for( int j=0; j<m_ssCheckFileCnt; j++ ){
				if ( m_pUsbFiles[j].bFileExistence == True ) {
					//	Do Not Show File NG When any one file Extension is Available.
					//	Show File NG Only when None of the Specified File Extensions Available.
					bFileOkFlg = True;
					break;
				}
			}
		}
		if( bFileOkFlg == True ) {
			// USB内にファイルが存在する場合.
			m_pUSBStatusText->showEnable( False );
			settingShowEnableParts( True );
		} else {
			// USB内にファイルが存在しない場合( ファイルＮＧを表示).
			// ファイルチェック完了の時のみファイルNGを表示.
			m_pUSBStatusText->changeText( s_ITMServiceFileNG );
			m_pUSBStatusText->showEnable( ( e_usbInfo == ServiceUSBInfo_CheckComplete ) );
			settingShowEnableParts( False );
		}
	}
}
//////////////////////////////////////////////////////////////
// 概要 : USBファイルチェック : 装着されたUSBチェック.
//////////////////////////////////////////////////////////////
void PServiceUSBFileCheckVariableSearch::checkUSB( )
{
	static TYPS_UsbMemAddress usbMemAddress; // 255+1バイトｻｲｽﾞの構造体と結構大きめなので Stackに用意せずStaticにしておく.
	static char dir[ sizeof( usbMemAddress.sc_DeviceName ) ];

	m_bUsbCheckingFlg = True;			// USBファイル存在チェック中とする.
	m_bForceShowFlg	  = False;			// 強制表示フラグはOFFにする.

	// USBメモリルートディレクトリアドレス取得.
	APIC_UsbMemDeviceInfo* pc_UsbMemDeviceInfo = APIC_UsbMemDeviceInfo::newInstance();
	usbMemAddress = pc_UsbMemDeviceInfo->getUsbMemAddress();

	memset( dir, '\0', sizeof( dir ) );
	strncpy( dir, usbMemAddress.sc_DeviceName, sizeof( dir )-1 );

	memset( m_localinfo, 0, sizeof( m_localinfo ) );

	// インストール済みファイルか否かの初期化.
	for( int i=0; i<m_ssCheckFileCnt; i++ ) {
		m_pUsbFiles[i].bFileExistence = False;
	}

	// ファイル数取得.
	m_ssFilePoint = 0;
	m_ssMaxFileCnt = APIF_SaaNumOfDirEntryUsb( TYPE_CharSetUTF8, usbMemAddress.sc_DeviceName );
	if( m_ssMaxFileCnt == 0 ) {
		// ファイルがひとつも存在しないUSBメモリは、必要なファイルも当然ないのでここまで.
		m_bUsbCheckingFlg = False;
		return;
	}
	// ファイル一覧取得(100個までしか取得しない).
	APIF_SaaGetDirEntryUsb( TYPE_CharSetUTF8, dir, m_localinfo, 0, ServiceUSBInfo_MaxGetFileCnt, ans_getFileForUSB );
}
//////////////////////////////////////////////////////////////
// 概要 : USBファイルチェック : ファイル取得通知(1件：可変検索).
//////////////////////////////////////////////////////////////
void PServiceUSBFileCheckVariableSearch::ans_getFileForUSB( TYPS_DirEntryInfo* s_DirEntryInfo, short ss_num )
{
	static char dirEntryUsb[ sizeof( m_localinfo[0].sc_name )];
	char dir[ sizeof( m_localinfo[0].sc_name ) ];

	int i,j;
	for( i=0; i<ss_num; i++ ) {
		if( m_localinfo[i].s_stat.st_mode & S_IFDIR ) {
			// フォルダは無視.
		} else {
			memset( dirEntryUsb, 0x0000, sizeof( m_localinfo[0].sc_name ) );
			strncpy( dirEntryUsb, m_localinfo[i].sc_name, sizeof( dirEntryUsb )-1 );
			int iDirLen =  static_cast<int>( strlen( dirEntryUsb ) );
			// 大文字・小文字あわせ.
			memset( dir, 0x0000, sizeof( m_localinfo[0].sc_name ) );
			for( j=0; j<iDirLen; j++ ) {
				dir[j] = ( char )tolower( dirEntryUsb[j] );
			}

			for( j=0; j<gp_ServiceUSBFileCheckVariableSearch.m_ssCheckFileCnt; j++ ) {
				if( 0 != strlen( gp_ServiceUSBFileCheckVariableSearch.m_pUsbFiles[j].pcSearchedFileName ) ) {
					// すでにファイル名が格納済みであれば、とばす。
					continue;
				}

				if( dir == strstr( dir, gp_ServiceUSBFileCheckVariableSearch.m_pUsbFiles[j].pcPrefix ) ) {
					// 接頭辞が一致した場合は拡張子を判定.
					char* pcPrefix = gp_ServiceUSBFileCheckVariableSearch.m_pUsbFiles[j].pcPrefix;
					char* pcExtension = gp_ServiceUSBFileCheckVariableSearch.m_pUsbFiles[j].pcExtension;
					char* pcConnection = gp_ServiceUSBFileCheckVariableSearch.m_pUsbFiles[j].pcConnection;
					int iExtensionLen = static_cast<int>( strlen( pcExtension ) );
					int iPrefixLen = static_cast<int>( strlen( pcPrefix ) );
					if( 0 == strcmp( &dir[ iDirLen - iExtensionLen], pcExtension ) ) {
						// 拡張子も一致した場合は文字数が規定以下であることを判定.
						uchar ucBaseLen = gp_ServiceUSBFileCheckVariableSearch.m_pUsbFiles[j].m_uc_BaseLen;				// Length of file name.
						uchar ucMinLen = static_cast<uchar>( ucBaseLen + gp_ServiceUSBFileCheckVariableSearch.m_pUsbFiles[j].m_uc_ConLen ); 	// Minimum length of search file name, Fixed part_(0-10character).bin.
						uchar ucMaxLen = gp_ServiceUSBFileCheckVariableSearch.m_pUsbFiles[j].m_uc_MaxLen;				// Maximum length of search file name.

						char* pcSearchedFileName = gp_ServiceUSBFileCheckVariableSearch.m_pUsbFiles[j].pcSearchedFileName;
						if( ucBaseLen == iDirLen ) {
							// 基準名.
							gp_ServiceUSBFileCheckVariableSearch.m_pUsbFiles[j].bFileExistence = True;
							strncpy( pcSearchedFileName, dirEntryUsb, iDirLen );
							break;
						} else if( ( ucMinLen <= iDirLen ) && ( iDirLen <= ucMaxLen ) ) {
							// 可変名称(接頭辞と可変部の間には接続文字があること。).
							if( &dir[iPrefixLen] == strstr( &dir[iPrefixLen], pcConnection ) ) {
								gp_ServiceUSBFileCheckVariableSearch.m_pUsbFiles[j].bFileExistence = True;
								strncpy( pcSearchedFileName, dirEntryUsb, iDirLen );
								break;
							}
						}
					}
				}
			}
		}
	}

	m_ssFilePoint = static_cast<short>( m_ssFilePoint + ss_num );
	if( m_ssFilePoint < m_ssMaxFileCnt ) {
		/*
		 * 全ファイル取得が終わっていない場合は.
		 *  指定されたファイルが全部見つかっていなければ、次の100ファイルを取得しにいく.
		 */
		// 指定ファイルが全て見つかったかどうかチェック.
		Bool bAllCheckFlg = True;
		for( i=0; i<gp_ServiceUSBFileCheckVariableSearch.m_ssCheckFileCnt; i++ ) {
			if( gp_ServiceUSBFileCheckVariableSearch.m_pUsbFiles[i].bFileExistence == False ) {
				bAllCheckFlg = False;
				break;
			}
		}
		if( bAllCheckFlg == False ) {
			// 指定ファイル全て発見できていない場合は、更に100ファイル取得.
			memset( m_localinfo, 0, sizeof( m_localinfo ) );
			APIF_SaaGetDirEntryUsb( TYPE_CharSetUTF8, dir, m_localinfo, m_ssFilePoint, ServiceUSBInfo_MaxGetFileCnt, ans_getFileForUSB );
			return;
		}
	}
	// USBファイルチェック完了(チェック中フラグをOFFにする).
	gp_ServiceUSBFileCheckVariableSearch.m_bUsbCheckingFlg = False;
}

