//////////////////////////////////////////////////////////////
// 概要 : システム設定／BootUpScreen(50C00130) : 画面開始処理.
//////////////////////////////////////////////////////////////
void PServiceBootUpScreen::startGamen()
{
	// ステータス初期化.
	memset( &m_status, 0, sizeof( m_status ) );
	memset( pcInstallFileName, 0x0000, ( BOOTUP_SCREEN_INSTALL_FILENAME_MAXLEN + 1 ) );

//	comment 2014/12/14 HCLT_Naveen [HeliosL][制御構成変更_No.30] .Bin and .Zip Multiple File Deduction.
	memset( pcInstallZipFileName , 0, sizeof( pcInstallZipFileName ) );				//	initialization.
	memset( m_sc_Version , 0 , sizeof( m_sc_Version ) );							//	BootUp Screen Image Version.
	// BootUpScreen画像読み込みフラグ.
	m_bLoadingFlg = True;
	APIC_BootupScreenSetting::newInstance()->readBootupScreen( ans_ReadBootUpScreen );

	// 削除関連パーツの設定.
	settingDeleteParts( );

	// USBチェック初期化.
// comment 2018/07/06 【IT6_Eagle】【HCLT_Pavani】【AR 1029580】 Jenkins Build Error Fix.
//	static PServiceUSBFileCheckVariableSearch::USBCheckFileVariable usbCheckFiles[] = {
//		{	0, True, True,
//			BOOTUP_SCREEN_INSTALL_FILENAME_PREFIX,
//			BOOTUP_SCREEN_INSTALL_FILENAME_CONNECTION,
//			BOOTUP_SCREEN_INSTALL_FILENAME_EXTENSION,
//			BOOTUP_SCREEN_INSTALL_FILENAME_VARIABLELEN,
//			pcInstallFileName,
//			BOOTUP_SCREEN_INSTALL_FILENAME_BASELEN,
//			BOOTUP_SCREEN_INSTALL_FILENAME_CONNECTLEN,
//			BOOTUP_SCREEN_INSTALL_FILENAME_MAXLEN
//		}
//	};
//	comment 2014/12/14 HCLT_Naveen [HeliosL][制御構成変更_No.30] .Bin and .Zip Multiple File Deduction.
	static PServiceUSBFileCheckVariableSearch::USBCheckFileVariable usbZip_BinCheckFiles[] = {
		{ 0, True, True,
		  BOOTUP_SCREEN_INSTALL_FILENAME_PREFIX,
		  BOOTUP_SCREEN_INSTALL_FILENAME_CONNECTION,
		  BOOTUP_SCREEN_INSTALL_FILENAME_EXTENSION_ZIP,
		  BOOTUP_SCREEN_INSTALL_FILENAME_VARIABLELEN,
		  pcInstallZipFileName,
		  BOOTUP_SCREEN_INSTALL_FILENAME_BASELEN,
		  BOOTUP_SCREEN_INSTALL_FILENAME_CONNECTLEN,
		  BOOTUP_SCREEN_INSTALL_FILENAME_MAXLEN },
		{ 1, True, True,
		  BOOTUP_SCREEN_INSTALL_FILENAME_PREFIX,
		  BOOTUP_SCREEN_INSTALL_FILENAME_CONNECTION,
		  BOOTUP_SCREEN_INSTALL_FILENAME_EXTENSION,
		  BOOTUP_SCREEN_INSTALL_FILENAME_VARIABLELEN,
		  pcInstallFileName,
		  BOOTUP_SCREEN_INSTALL_FILENAME_BASELEN,
		  BOOTUP_SCREEN_INSTALL_FILENAME_CONNECTLEN,
		  BOOTUP_SCREEN_INSTALL_FILENAME_MAXLEN },
	};
// Comment 2017/11/29 【HCLT-Vishal】【Eagle】【制御構成変更_No.4】 Removing old function version check and else portion.
	gp_ServiceUSBFileCheckVariableSearch.setCheckFiles( usbZip_BinCheckFiles, sizeof(usbZip_BinCheckFiles) / sizeof(usbZip_BinCheckFiles[0]) );
	gp_ServiceUSBFileCheckVariableSearch.m_bl_MultipleFile	=	True;		//	Enable Multiple File Detection Flag.

	static PDisplayParts* pUSBCheckShowEnableParts[] = {
		&Key_BootUpScreenEntry,
	};
//	comment 2014/12/14 HCLT_Naveen [HeliosL][制御構成変更_No.30] .Bin and .Zip Multiple File Deduction.
//	gp_ServiceUSBFileCheckVariableSearch.setCheckFiles( usbCheckFiles, sizeof( usbCheckFiles ) / sizeof( usbCheckFiles[0] ) );
	gp_ServiceUSBFileCheckVariableSearch.setUSBStatusText( &Txt_BootUpScreenUSBStatus );
	gp_ServiceUSBFileCheckVariableSearch.setShowEnableParts( pUSBCheckShowEnableParts, sizeof( pUSBCheckShowEnableParts )/sizeof( PDisplayParts** ) );
	// 実行処理ステータスの表示設定.
	settingExecParts();

	// 登録キーは最初は非表示.
	Key_BootUpScreenEntry.showEnable( False );

	PServiceToSystemMenu2P2Com::startGamen( );

// Comment 2015/07/20 HCLT-Surajit RQ-163[WP 1379]  Hide the registration  area(registeration key, frame, USBNG, File NG).	
// Comment 2017/11/29 【HCLT-Vishal】【Eagle】【制御構成変更_No.4】 Removing old function version check condition.
	PNLC_USBConnectionPermission c_UsbPermission;
	PNLE_EnableUSBConnectionPermissionForAll e_usbAll = c_UsbPermission.getEnableUSBConnectionPermissionForAll();
	PNLE_EnableUSBConnectionPermissionForService e_usbforService = c_UsbPermission.getEnableUSBConnectionPermissionForService();
	if(( PNLE_EnableUSBConnectionPermissionForAll_Disable == e_usbAll ) || ( PNLE_EnableUSBConnectionPermissionForService_Disable == e_usbforService )) {
		m_bl_USBConnectionPermissionFlag = False;
	} else {
		m_bl_USBConnectionPermissionFlag = True;
	}
}

//////////////////////////////////////////////////////////////
// 概要 : システム設定／BootUpScreen(50C00130) : BootUpScreen画像読み込み通知.
//////////////////////////////////////////////////////////////
void PServiceBootUpScreen::ans_ReadBootUpScreen( Bool bSts, uintptr_t )
{
	// サービスのBootUpScreen画面では、読み込んだ画像は使用しない。.
	// (ただ単に、ファイルがあるかどうかを調べるだけ).
	m_bSaveBootUpScreenFlg = bSts;
	m_bLoadingFlg = False;
}

//////////////////////////////////////////////////////////////
// 概要 : システム設定／BootUpScreen(50C00130) : ボタン（押された）.
//////////////////////////////////////////////////////////////
void PServiceBootUpScreen::procButtonOn( uchar option )
{
	// インストール、削除中は押下不可.
	if( getStatus() == InstallDeleteExecution_Executing ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );		// 拒否音.
		return;
	}

	Bool bOnOffFlg;
	switch( option ) {
		case 1:		// 登録キー.
			bOnOffFlg = !( Key_BootUpScreenEntry.isSelect() );
			Key_BootUpScreenEntry.select( bOnOffFlg );

			if( bOnOffFlg == True ) {
				settingOnOffDeleteKey( False );
			}

			settingDeleteParts( True );	// 削除関連パーツの設定(初期化込み).
			break;
		case 2:		// 削除キー.
			bOnOffFlg = !( Key_BootUpScreenDelete.isSelect() );
			settingOnOffDeleteKey( bOnOffFlg );

			if( bOnOffFlg == True ) {
				Key_BootUpScreenEntry.select( False );
			}
			break;
		case 3:		// 確定キー.
			if( m_bSaveBootUpScreenFlg == False ) {
				// BootUpScreen画像がない場合は、選択不可
				bOnOffFlg = False;
			} else {
				bOnOffFlg = !( Key_BootUpScreenDecide.isSelect() );
			}
			Key_BootUpScreenDecide.select( bOnOffFlg );

			if( bOnOffFlg == True && m_bSaveBootUpScreenFlg == True ) {
				// 選択状態かつBootUpScreen画像が存在するときのみ、削除処理開始可能.
				deleteExec();
			}
			break;
	}

	setupGamen();
}
//////////////////////////////////////////////////////////////
// 概要 : システム設定／BootUpScreen(50C00130) : 画面遷移ボタン（押された）.
//////////////////////////////////////////////////////////////
void PServiceBootUpScreen::settingOnOffDeleteKey( Bool bSelectFlg )
{
	Key_BootUpScreenDelete.select( bSelectFlg );

	// 確定キーの設定.
	//   確定キーは、削除キーの選択状態に応じて表示/非表示が切り替わる.
	Key_BootUpScreenDecide.select( False );
	Key_BootUpScreenDecide.showEnable( bSelectFlg );
}

