// comment 2015/01/22 HCLT-Kavaskar [Helios][CQ509072] Bootup Screen file path acquisition.	
//===================================================================. 
/** 
* @brief 	: Identification of USB root directory.
* @note 	: None. 
* @param 	: None. 
* @return 	: USB root directory path. 
* @author 	: 2015/01/22 HCLT-Kavaskar. 
*/ 
//===================================================================.
char* PServiceBootUpScreen::devicePath()
{
#ifdef TORNADO
// comment 2015/03/30 MSE永野 [Helios][CQ510921] Warning除去対応.
//	 char sc_DeviceName[PNLD_BULK_MAX_DRV_NAME_SZ];
	 static char sc_DeviceName[PNLD_BULK_MAX_DRV_NAME_SZ];
     memset( sc_DeviceName, '\0', PNLD_BULK_MAX_DRV_NAME_SZ );
     char **psc_Names,*psc_tmp;
     ushort us_Num;

     us_Num = SYSC_GetBulkDeviceNames( NULL, 0 );       //デバイス数取得.
     if( us_Num != 1 ) { return (char*)sc_DevPathNone; }                          //デバイス数が1でない場合はエラー.

     psc_Names = &psc_tmp; 
	 *psc_Names = (char*)sc_DeviceName;
     SYSC_GetBulkDeviceNames( psc_Names, 1 );            //デバイス名取得.
     return (char*)sc_DeviceName;
#else   // #ifdef TORNADO
        //simWinの場合はルートディレクトリを返す.
        return "/";
#endif  // #ifdef TORNADO
}
//////////////////////////////////////////////////////////////
// 概要 : システム設定／BootUpScreen(50C00130) : スタートキー.
//////////////////////////////////////////////////////////////
void PServiceBootUpScreen::procStart( uchar option )
{
	if( printStartDisable() == True ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );		// 拒否音.
		return;
	}

	// インストール開始.
	APIC_BootupScreenSetting* pBootupScreen = APIC_BootupScreenSetting::newInstance();
//2019/06/17 Comment [HCLT_Krishnakumar][EagleH][N Rank] Removed unwanted detailed code.
//	comment 2014/12/14 HCLT_Naveen [HeliosL][制御構成変更_No.30] .Bin and .Zip Multiple File Deduction.
// 2015/11/05 【HCLT-Dhivya】 【ZeusS_ZX0】 【制御構成変更_No.76-1】Detail macro is passed in API.
//	LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
	if( NULL == pBootupScreen ) { 
//2019/06/17 Comment [HCLT_Krishnakumar][EagleH][N Rank] Removed unwanted detailed code.
//		if (NULL != pc_BFW_System){
//    		pc_BFW_System->registDetailCode(PNLD_DetailCode_Service_0x1900280100670601);
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" ); 
		return; 
	}
//	comment 2014/12/14 HCLT_Naveen [HeliosL][制御構成変更_No.30] .Bin and .Zip Multiple File Deduction.
// Comment 2017/11/29 【HCLT-Vishal】【Eagle】【制御構成変更_No.4】 Removing old function version check and else portion.
	APIC_UsbMemDeviceInfo* pc_UsbMemDeviceInfo = APIC_UsbMemDeviceInfo::newInstance();
	if( NULL == pc_UsbMemDeviceInfo ) { 
//2019/06/17 Comment [HCLT_Krishnakumar][EagleH][N Rank] Removed unwanted detailed code.
////2015/11/05 【HCLT-Dhivya】 【ZeusS_ZX0】 【制御構成変更_No.76-1】Detail macro is passed in API.
//		if (NULL != pc_BFW_System){
//			pc_BFW_System->registDetailCode(PNLD_DetailCode_Service_0x1900280100670701);
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" ); 
		return; 
	}
		
	TYPS_BootUpScreenZipFileName	st_BootUpScreenZipFileName;							//	Structure for BootUp Screen Zip file
	TYPS_BootUpScreenBinFileName	st_BootUpScreenBinFileName;							//	Structure for BootUp Screen Bin file
		
	char sc_FileName[ BOOTUP_SCREEN_INSTALL_FILENAME_MAXLEN + 1 ];						//	File Name.
		
	memset( &st_BootUpScreenZipFileName, 0, sizeof( TYPS_BootUpScreenZipFileName ) );	//	initialization.
	memset( &st_BootUpScreenBinFileName, 0, sizeof( TYPS_BootUpScreenBinFileName ) );	//	initialization.
	memset( sc_FileName, 0, sizeof(sc_FileName) );
		
	TYPS_UsbMemAddress st_usbMemAddress;												//	Structure for USB Root Directory.
	char sc_dir[ sizeof( st_usbMemAddress.sc_DeviceName ) ];							//	USB Root Directory Path.
	memset( sc_dir, '\0', sizeof(sc_dir) ); 											//	initialization.
		
	//	USB memory root directory Path Acquisition.
// comment 2015/01/22 HCLT-Kavaskar [Helios][CQ509072] Bootup Screen file path acquisition.
	// st_usbMemAddress = pc_UsbMemDeviceInfo->getUsbMemAddress();
	//	Copy USB memory root directory Path.
	//strncpy( sc_dir, st_usbMemAddress.sc_DeviceName, sizeof(sc_dir)-1 );
	strncpy( sc_dir, devicePath(), sizeof(sc_dir)-1 );
		
	if ( 0 != strlen(pcInstallZipFileName) ) {																	//	Zip File.
		SplitFileName( pcInstallZipFileName, sc_FileName );														//	Get the File Name and remove the Extension(.zip).
		st_BootUpScreenZipFileName.psc_ZipFileName		=	sc_FileName;										//	File Name.
		st_BootUpScreenZipFileName.psc_ZipFileExtension	=	BOOTUP_SCREEN_INSTALL_FILENAME_ZIPEXTENSION;		//	zip.
		st_BootUpScreenZipFileName.psc_RecFileExtension	=	BOOTUP_SCREEN_INSTALL_FILENAME_BINEXTENSION;		//	bin.
	} else if ( 0 != strlen(pcInstallFileName) ) {																//	Bin File.
		SplitFileName( pcInstallFileName, sc_FileName );														//	Get the File Name and remove the Extension(.bin).
		st_BootUpScreenBinFileName.psc_BinFileName		=	sc_FileName;										//	File Name.
		st_BootUpScreenBinFileName.psc_BinFileExtension	=	BOOTUP_SCREEN_INSTALL_FILENAME_BINEXTENSION;		//	bin.
	}
	//	API Call the Install the BootUp Screen Image.
	pBootupScreen->writeBootupScreen( sc_dir , st_BootUpScreenZipFileName , st_BootUpScreenBinFileName , BOOTUP_SCREEN_INSTALL_BOOTUPVERSION_FILENAME , ans_SetBootUpScreen );
		
//	comment 2014/12/14 HCLT_Naveen [HeliosL][制御構成変更_No.30] .Bin and .Zip Multiple File Deduction.

	m_status.e_InstallSts = InstallDeleteExecution_Executing;	 // ステータス変更(インストール中).
	m_status.e_DeleteSts  = InstallDeleteExecution_None;		 // ステータス変更(削除していない).
	settingExecParts();											 // 表示パーツの設定.

	setupGamen();
}
//////////////////////////////////////////////////////////////
// 概要 : システム設定／BootUpScreen(50C00130) : インストール完了通知.
//////////////////////////////////////////////////////////////
void PServiceBootUpScreen::ans_SetBootUpScreen( Bool bStatus )
{
	m_bInstallCompleteStatus = bStatus;
	m_bSaveBootUpScreenFlg	 = bStatus;

	CallBackIndi( TYPE_PNL_CallBack_BootUpScreenInstallComplete );
}

//////////////////////////////////////////////////////////////
// 概要 : システム設定／BootUpScreen(50C00130) : 削除処理開始.
//////////////////////////////////////////////////////////////
void PServiceBootUpScreen::deleteExec( )
{
	// 削除開始.
	APIC_BootupScreenSetting* pBootupScreen = APIC_BootupScreenSetting::newInstance();
	pBootupScreen->eraseBootupScreen( ans_EraseBootUpScreen );

	m_status.e_DeleteSts  = InstallDeleteExecution_Executing;	 // ステータス変更(削除中).
	m_status.e_InstallSts = InstallDeleteExecution_None;		 // ステータス変更(インストールしていない).

	settingExecParts();	// 表示パーツの設定.
}

//////////////////////////////////////////////////////////////
// 概要 : システム設定／BootUpScreen(50C00130) : 削除完了通知.
//////////////////////////////////////////////////////////////
void PServiceBootUpScreen::ans_EraseBootUpScreen( Bool bStatus )
{
	m_bDeleteCompleteStatus = bStatus;
	if( bStatus == True ) {
		// 削除が成功していたら、BootUpScreen画像存在フラグを落とす.
		m_bSaveBootUpScreenFlg = False;
	}

	CallBackIndi( TYPE_PNL_CallBack_BootUpScreenDeleteComplete );
}


//////////////////////////////////////////////////////////////
// 概要 : システム設定／BootUpScreen(50C00130) : コールバック.
//////////////////////////////////////////////////////////////
void PServiceBootUpScreen::procCallBack( TYPE_PNL_CallBack option )
{
// 2015/11/05 【HCLT-Dhivya】 【ZeusS_ZX0】 【制御構成変更_No.76-1】Detail macro is passed in API.
//2019/06/17 Comment [HCLT_Krishnakumar][EagleH][N Rank] Removed unwanted detailed code.
//	LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
	switch( option ) {
		case TYPE_PNL_CallBack_BootUpScreenInstallComplete:
			// インストール完了.
			if( m_bInstallCompleteStatus == True ) {
//	comment 2014/12/14 HCLT_Naveen [HeliosL][制御構成変更_No.30] BootUp Screen Version Display Support.
// Comment 2017/11/29 【HCLT-Vishal】【Eagle】【制御構成変更_No.4】 Removing old function version check and else portion.
//Comment 2015/01/30 HCLT_Senthil [HeliosL][CQ509594] Delete the Version when downloading the bin file.
			//	if ( 0 != strlen(pcInstallZipFileName) ) {
					//	To Get the BootUp Screen Image Version.
					APIC_BootupScreenSetting* pBootupScreen = APIC_BootupScreenSetting::newInstance();
// 2015/11/05 【HCLT-Dhivya】 【ZeusS_ZX0】 【制御構成変更_No.76-1】Detail macro is passed in API.
				if( NULL == pBootupScreen ) {
//2019/06/17 Comment [HCLT_Krishnakumar][EagleH][N Rank] Removed unwanted detailed code.
//					if (NULL != pc_BFW_System){
//						pc_BFW_System->registDetailCode(PNLD_DetailCode_Service_0x1900690100670801);
//					}
					LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" ); 
					return; 
				}
					//	API call to Get the BootUp Screen Image Version.
					pBootupScreen->getBootupScreenVersion( ans_BootupScreenVersion );
//Comment 2015/01/30 HCLT_Senthil [HeliosL][CQ509594] Delete the version when downloading the bin file.
			//	} else {
			//		m_status.e_InstallSts = InstallDeleteExecution_OK;
			//	}
//	comment 2014/12/14 HCLT_Naveen [HeliosL][制御構成変更_No.30] BootUp Screen Version Display Support.
			} else {
				m_status.e_InstallSts = InstallDeleteExecution_NG;
			}
			settingExecParts();
			settingDeleteParts();
			break;
		case TYPE_PNL_CallBack_BootUpScreenDeleteComplete:
			// 削除完了.
			if( m_bDeleteCompleteStatus == True ) {
//	comment 2014/12/14 HCLT_Naveen [HeliosL][制御構成変更_No.30] BootUp Screen Version Display Support.
// Comment 2017/11/29 【HCLT-Vishal】【Eagle】【制御構成変更_No.4】 Removing old function version check and else portion.
				// Display of Version.
				char sc_RomVersion[ DEF_BootUpScreenVersionMax + 1 ];							//	Version.
				memset( sc_RomVersion, 0, sizeof(sc_RomVersion) );								//	initialization.
				if ( NULL != ppc_SystemInfo ) {
					ppc_SystemInfo->getRomVersion( TYPE_RomBootupScreen , sc_RomVersion );		//	Get the Bootup Screen Image Version.
				} else {
					LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
				}
				if ( 0 != strlen(sc_RomVersion) ) {
					//	To Erase the BootUp Screen Image Version.
					APIC_BootupScreenSetting* pBootupScreen = APIC_BootupScreenSetting::newInstance();
					if( NULL == pBootupScreen ) {
//2019/06/17 Comment [HCLT_Krishnakumar][EagleH][N Rank] Removed unwanted detailed code.
//						if (NULL != pc_BFW_System){
//							pc_BFW_System->registDetailCode(PNLD_DetailCode_Service_0x1900690100670901);
//						}
						LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" ); 
						return; 
					}
					//	API Call to Erase the BootUp Screen Image Version.
					pBootupScreen->eraseBootupScreenVersion( ans_EraseBootUpScreenVersion );
				} else {
			m_status.e_DeleteSts = InstallDeleteExecution_OK;
				}
//	comment 2014/12/14 HCLT_Naveen [HeliosL][制御構成変更_No.30] BootUp Screen Version Display Support.
			} else {
				m_status.e_DeleteSts = InstallDeleteExecution_NG;
			}
			settingExecParts();
			break;
//	comment 2014/12/14 HCLT_Naveen [HeliosL][制御構成変更_No.30] BootUp Screen Version Display Support.
		case TYPE_PNL_CallBack_BootUpScreenVersionInstallComplete:							//	Ans for Fetching BooUp Screen Version.
			m_status.e_InstallSts = InstallDeleteExecution_OK;								//	BootUp Screen Image Installation Completed successfully.
			if ( NULL != m_sc_Version ) {
				ppc_SystemInfo->setRomVersion( TYPE_RomBootupScreen, m_sc_Version );	//	Set the BootUp Screen Image Version to the Version Setting API.
//Comment 2015/01/30 HCLT_Senthil [HeliosL][CQ509594] Delete the Version when downloading the bin file.
//			}
			} else {
				ppc_SystemInfo->setRomVersion( TYPE_RomBootupScreen, "" );					//	Set the BootUp Screen Image Version to the Version Setting API.
			}
			settingExecParts();
			settingDeleteParts();
			break;
		case TYPE_PNL_CallBack_BootUpScreenVersionDeleteComplete:							//	Ans for Erasing BooUp Screen Version.
			m_status.e_DeleteSts = InstallDeleteExecution_OK;								//	BootUp Screen Image Deletion Completed successfully.
			if ( ( True == m_bl_Status ) && ( NULL != ppc_SystemInfo ) ){
				ppc_SystemInfo->setRomVersion( TYPE_RomBootupScreen, "" );					//	Set the BootUp Screen Image Version to the Version Setting API.
			}
			settingExecParts();
			break;
		default:
			break;
	}

	setupGamen();
}
//	comment 2014/12/14 HCLT_Naveen [HeliosL][制御構成変更_No.30] BootUp Screen Version Display Support.
//====================================================================================================================.
/**
* @brief  : Ans for BootUp Screen Version Acquisition.
* @note   : PServiceBootUpScreen : 50C00130 システム設定／BootUpScreen.
* @param1 : const Bool bl_Status - True: Version acquisition success, False: Version acquisition failure.
* @param2 : const char* sc_VersionInfo - Contains the BootUp Screen Image Version.
* @return : None.
* @author :	2014/12/14 HCLT_Naveen [HeliosL][制御構成変更_No.30].
*/
//====================================================================================================================.
void PServiceBootUpScreen::ans_BootupScreenVersion( const Bool bl_Status , const char* sc_VersionInfo )
{
	if( ( True == bl_Status ) && ( NULL != sc_VersionInfo ) ){
		strncpy( m_sc_Version , sc_VersionInfo , sizeof( m_sc_Version ) -1 );		//	Copy BootUp Screen Image Version.
	}

	CallBackIndi( TYPE_PNL_CallBack_BootUpScreenVersionInstallComplete );			//	Call Back.

}

//====================================================================================================================.
/**
* @brief  : Ans for BootUp Screen Version Infomation deletion.
* @note   : PServiceBootUpScreen : 50C00130 システム設定／BootUpScreen.
* @param  : Bool - True: Version Erase Success , False: Version Erase failure.
* @return : None.
* @author :	2014/12/14 HCLT_Naveen [HeliosL][制御構成変更_No.30].
*/
//====================================================================================================================.
void PServiceBootUpScreen::ans_EraseBootUpScreenVersion( Bool bl_Status )
{
	m_bl_Status	=	bl_Status;
	
	CallBackIndi( TYPE_PNL_CallBack_BootUpScreenVersionDeleteComplete );			//	Call Back.

}

//====================================================================================================================.
/**
* @brief  : To Seperate filename from its extension and return only the filename.
* @note   : PServiceBootUpScreen : 50C00130 システム設定／BootUpScreen.
* @param1 : char* psc_InputName - Whole File Name with Extension will be send in this parameter.
* @param2 : char *psc_FileName  - File Name without Extension will be updated in this parameter.
* @return : None.
* @author :	2014/12/14 HCLT_Naveen [HeliosL][制御構成変更_No.30].
*/
//====================================================================================================================.
void PServiceBootUpScreen::SplitFileName( char* psc_InputName, char *psc_FileName )
{
	char *psc_ret	=	NULL;
	//	Find '.' in the Input file name.
	psc_ret = strstr(psc_InputName, ".");
	//	Calculate Length.
	size_t sz_Length = static_cast<size_t>( psc_ret - psc_InputName );
	//	Copy the all the words before '.'
	strncpy(psc_FileName, psc_InputName, sz_Length);
}

//////////////////////////////////////////////////////////////
// 概要 : システム設定／BootUpScreen(50C00130) : 表示画面のセットアップ.
//////////////////////////////////////////////////////////////
void PServiceBootUpScreen::setupGamen( short option )
{
	// USB状態のチェック & 表示.
	gp_ServiceUSBFileCheckVariableSearch.checkAndShow( );

	if( getStatus() == InstallDeleteExecution_Executing ) {
		// インストールor削除中の表示処理.
		showExecuting();
	}

	// 表示部品のセットアップ.
	PServiceToSystemMenu2P2Com::setupGamen( option );
//	comment 2014/12/14 HCLT_Naveen [HeliosL][制御構成変更_No.30]  BootUp Screen Version Display Support.
// Comment 2017/11/29 【HCLT-Vishal】【Eagle】【制御構成変更_No.4】 Removing old function version check and else portion.
	Grp_MachineDiagramVersionParts.showEnable( True );								//	Show the Version Gooup Parts.
	//	Display Ver. if BootUp Screen is installed.
	if ( NULL != ppc_SystemInfo ) {
		// Display of Version.
		char sc_RomVersion[ DEF_BootUpScreenVersionMax + 1 ];						//	Version.
		memset( sc_RomVersion, 0, sizeof(sc_RomVersion) );							//	initialization.
		ppc_SystemInfo->getRomVersion( TYPE_RomBootupScreen , sc_RomVersion );		//	Get the Bootup Screen Image Version.
		if ( 0 != strlen(sc_RomVersion) ) {
			//	Display the Bootup Screen Image Version.
			Tfd_MachineDiagramVersion.showEnable( True );
			Tfd_MachineDiagramVersion.changeExternalText((uchar*)sc_RomVersion, sizeof(sc_RomVersion));
		} else {
			Tfd_MachineDiagramVersion.showEnable( False );
		}
	} else {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
	}

	/*
	 * スタートキーの制御.
	 */
	Bool bLEDControlFlg = False;
	if( getStatus() != InstallDeleteExecution_Executing ) {
		// インストールor削除中でなければ、Startキーは押下できる可能性がある.
		if( Key_BootUpScreenEntry.isSelect() == True &&
		    gp_ServiceUSBFileCheckVariableSearch.getUSBInfo() == ServiceUSBInfo_CheckComplete ) {
			// USBチェックが完了し、かつ登録キーが選択状態になっていればStartキー押下可能	.
			bLEDControlFlg = True;
		}
	}
	printLEDControl( bLEDControlFlg );
// Comment 2015/07/20 HCLT-Surajit RQ-163[WP 1379]  Hide the registration  area(registeration key, frame, USBNG, File NG).	

// Comment 2017/11/29 【HCLT-Vishal】【Eagle】【制御構成変更_No.4】 Removing old function version check condition.
	if( False == m_bl_USBConnectionPermissionFlag ){ 			//USB接続許可設定の[一括設定]または[外部メモリー(サービス)]が[禁止]の場合.
   		Key_BootUpScreenEntry.showEnable(False);				//登録キー非表示.
		Txt_BootUpScreenUSBStatus.showEnable( False );			//Hide USB search result status updation(USB NG/File NG).
		Bak_BootUpScreenInstall.showEnable( False ); 			//枠非表示.
// comment 2015/10/06 HCL_Senthil[ZeusS_ZX0] [CQ519630]To remove the registeration display parts.
//		} else {
//			Key_BootUpScreenEntry.showEnable(True);					//登録キー表示.
//   		Txt_BootUpScreenUSBStatus.showEnable( True );			//Show USB search result status updation(USB NG/File NG).
//   		Bak_BootUpScreenInstall.showEnable( True ); 			//枠表示.
	}
}

//////////////////////////////////////////////////////////////
// 概要 : システム設定／BootUpScreen(50C00130) : 削除関連パーツの設定.
//////////////////////////////////////////////////////////////
void PServiceBootUpScreen::settingDeleteParts( Bool bInitFlg )
{
	if( bInitFlg == True ) {
		// 初期化フラグがONの時は、削除ステータスを「処理していない」に変更.
		m_status.e_DeleteSts = InstallDeleteExecution_None;
	}

	if( m_status.e_DeleteSts == InstallDeleteExecution_OK ||
	    m_status.e_DeleteSts == InstallDeleteExecution_NG ) {
		// 削除処理が完了していれば、削除ステータスを表示するパーツの設定.
		Txt_BootUpScreenResultStatus.showEnable( True );
		TEXT_ID textId;
		if( m_status.e_DeleteSts == InstallDeleteExecution_OK ) {
			textId = s_Ok;
		} else {
			textId = s_NG;
		}
		Txt_BootUpScreenResultStatus.changeText( textId );
	}
	else {
		// 確定キーの表示は削除キーの選択状況による.
		Bool bDeleteSelect = Key_BootUpScreenDelete.isSelect();
		Key_BootUpScreenDecide.showEnable( bDeleteSelect );

		if( m_bLoadingFlg == True || m_bSaveBootUpScreenFlg == False ) {
			// BootUpScreen画像が無ければ削除関連パーツは表示しない.
			// (BootUpScreen画像の読み込み処理が完了していない時も非表示).
			Grp_BootUpScreenDelete.showEnable( False );
		} else {
			Grp_BootUpScreenDelete.showEnable( True );
		}
	}
}

//////////////////////////////////////////////////////////////
// 概要 : システム設定／BootUpScreen(50C00130) : インストールor削除中表示処理.
//////////////////////////////////////////////////////////////
void PServiceBootUpScreen::showExecuting()
{
	static	Bool	b_InstallingAnimeSts = False;	// インストール中であることを示す表示を行うためのフラグ.
	TEXT_ID			executingTextId;

	if( b_InstallingAnimeSts == True ) {
		executingTextId = s_EXPSlash;
		b_InstallingAnimeSts = False;
	} else {
		executingTextId = s_EXPBackslash;
		b_InstallingAnimeSts = True;
	}
	Txt_BootUpScreenSlash.changeText( executingTextId );
}

//////////////////////////////////////////////////////////////
// 概要 : システム設定／BootUpScreen(50C00130) : 削除関連パーツの設定.
//////////////////////////////////////////////////////////////
void PServiceBootUpScreen::settingExecParts()
{
	struct ShowResultParamStruct {
		TEXT_ID	resultTextId;		// 結果表示(0の時は非表示).
		Bool	b_ExecutionFlg;		// 実行中かどうかを示すパーツの表示設定.
	};

	static ShowResultParamStruct showResultParam[] = {
		{ 0,		False },			// 何もしていない.
		{ 0,		False },			// 処理予約(未使用).
		{ 0,		True  },			// 処理中.
		{ s_Ok,		False },			// インストールor削除成功.
		{ s_NG,		False },			// インストールor削除失敗.
	};

	InstallDeleteExecutionStatus eExecSts = getStatus();

	// 結果表示パーツの設定.
	if( showResultParam[eExecSts].resultTextId == 0 ) {
		Txt_BootUpScreenResultStatus.showEnable( False );
	} else {
		Txt_BootUpScreenResultStatus.showEnable( True );
		Txt_BootUpScreenResultStatus.changeText( showResultParam[eExecSts].resultTextId );
	}

	// 処理中表示用パーツの設定.
	Txt_BootUpScreenSlash.showEnable( showResultParam[eExecSts].b_ExecutionFlg );
}

//////////////////////////////////////////////////////////////
// 概要 : システム設定／BootUpScreen(50C00130) : インストールor削除状態取得(インストールか削除のどちらかが動作していれば、そのステータスを返す).
//			戻り値　InstallDeleteExecution_None		：	何も処理を行っていない.
//					InstallDeleteExecution_Executing：	インストールor削除中.
//					InstallDeleteExecution_OK		：	インストールor削除成功.
//					InstallDeleteExecution_NG		：	インストールor削除失敗.
//////////////////////////////////////////////////////////////
InstallDeleteExecutionStatus PServiceBootUpScreen::getStatus()
{
	if( m_status.e_InstallSts != InstallDeleteExecution_None ) {
		// インストール最中or完了時は、インストール状態を返す.
		return m_status.e_InstallSts;
	}
	if( m_status.e_DeleteSts != InstallDeleteExecution_None ) {
		// 削除最中or完了時は、削除状態を返す.
		return m_status.e_DeleteSts;
	}
	// インストールも削除も行っていない場合は、InstallDeleteExecution_None を返す.
	return InstallDeleteExecution_None;
}

