/**
* @brief 	: Process of soft key events for Transition.
* @note 	: None.
* @param 	: [in] option	Soft Key event(Button ID).
* @return 	: None.
* @author 	: 2013/12/19 HCLT_Senthil.
*/
//===================================================================.

void PServiceCustomScreen::procGoToPage( uchar option )
{
	switch( option ) {
		case BTNID_BootUpScreen: 	nextGamen = &gp_ServiceBootUpScreen;		break;		// 50C00130_BootUp Screenキー.
		case BTNID_MachineDiagram: 	nextGamen = &gp_ServiceMachineDiagram;		break;		// E0B0C00B00_システム設定／マシン画像.
		case BTNID_AuthCustomizeDataInstall: 
			nextGamen = &gp_ServiceAuthCustomizeDataInstall;								// E0B0C00C00_システム設定／認証カスタマイズ.
			break;
		default:
			break;
	}
}
// Comment 2015/09/05 HCLT-Surajit RQ-163[WP 1379, WP 1381] Changing the flag name.
//// Comment 2015/07/20 HCLT-Surajit RQ-163[WP 1379, WP 1381]  Hide マシン画像 key If machine graphic is not registered , BootUp Screen key If BootUp Screen is not registered .
//Bool	PServiceCustomScreen::m_bl_bootUpScreenFlg	= True;
Bool	PServiceCustomScreen::m_bl_bootUpScreenFlag = True;
//===================================================================.
/**
* @brief 	: To launch the screen.
* @note 	: None.
* @param 	: option.
* @return 	: None.
* @author 	: 2015/07/20 HCLT_Surajit.
*/
//===================================================================.
void PServiceCustomScreen::startGamen()
{
	PServiceToSystemMenu2P2Com::startGamen();

// Comment 2017/11/29 【HCLT-Vishal】【Eagle】【制御構成変更_No.4】 Removing old function version check condition.
// Comment 2015/09/05 HCLT-Surajit RQ-163[WP 1379, WP 1381] Changing the flag name and initialize the auth customize flag.
//		m_bl_bootUpScreenFlg = False;				//Since system side call back will be called, to avoid flag becoming invalid, intialization done in startup gamen also.
	m_bl_bootUpScreenFlag = False;				//Since system side call back will be called, to avoid flag becoming invalid, intialization done in startup gamen also.
	m_bl_SaveAuthCustomizeDataFlag = False;		//Since system side call back will be called, to avoid flag becoming invalid, intialization done in startup gamen also.
	PNLC_USBConnectionPermission c_UsbPermission;
	PNLE_EnableUSBConnectionPermissionForAll e_usbAll = c_UsbPermission.getEnableUSBConnectionPermissionForAll();
	PNLE_EnableUSBConnectionPermissionForService e_usbforService = c_UsbPermission.getEnableUSBConnectionPermissionForService();
	APIC_MachineSetting* pc_MachineSetting = PnlComGetMachineSetting();
// Comment 2015/09/05 HCLT-Surajit RQ-163[WP 1379, WP 1381] Getting the instance of APIC_AuthCust class.
	APIC_AuthCust* pc_AuthCust = APIC_AuthCust::newInstance();		
	if( ( PNLE_EnableUSBConnectionPermissionForAll_Disable == e_usbAll ) || ( PNLE_EnableUSBConnectionPermissionForService_Disable == e_usbforService ) ) {
		m_bl_USBConnectionPermissionFlag = False;
	} else {
		m_bl_USBConnectionPermissionFlag = True;
	}
		
	// check the machine diagram registration status.
	if ( ( NULL != pc_MachineSetting ) && ( False == pc_MachineSetting->getOEMMachineFigDataInstallFlgInfo() ) ) {
		m_bl_machineImageFlag = False;
	} else {
		m_bl_machineImageFlag = True;
	}
// Comment 2015/09/05 HCLT-Surajit RQ-163[WP 1379, WP 1381] Hide マシン画像/BootUp/AuthCustomize keys If machine graphic/Bootup/Authorization Customization not registered.
	// check the Authorization Customization Registration status.
	if( NULL != pc_AuthCust) {
		m_bl_SaveAuthCustomizeDataFlag = pc_AuthCust->chkInstallAuthCustomMaster();
	}
	// check the Boot up screen registration status.
	APIC_BootupScreenSetting::newInstance()->readBootupScreen( ans_ReadBootUpScreen );
}
// Comment 2015/07/20 HCLT-Surajit RQ-163[WP 1379, WP 1381]  Hide マシン画像 key If machine graphic is not registered , BootUp Screen key If BootUp Screen is not registered .
//===================================================================.
/**
* @brief 	: Dispaly the screen Parts.
* @note 	: None.
* @param 	: option.
* @return 	: None.
* @author 	: 2015/07/20 HCLT_Surajit.
*/
//===================================================================.
void PServiceCustomScreen::setupGamen( short option )
{
	PServiceToSystemMenu2P2Com::setupGamen(option);
// Comment 2017/11/29 【HCLT-Vishal】【Eagle】【制御構成変更_No.4】 Removing old function version check and else portion.
// Comment 2015/09/24 HCLT-Kshitish [CQ519063] To Show /設定データインポート Title from "5G-3.0" or later.
	Txt_SubTitleSettingDataImport.changeText( s_TTLServiceConfigurationDataImport );		// /設定ﾃﾞｰﾀｲﾝﾎﾟｰﾄ.
	//マシン画像が登録されていないかつUSB接続許可設定の[一括設定]または[外部メモリー(サービス)]が[禁止]の場合.
	if( ( False == m_bl_USBConnectionPermissionFlag ) && ( False == m_bl_machineImageFlag ) ) {
    	Key_MachineDiagram.showEnable(False);  				//マシン画像キー非表示.
	} else {
		Key_MachineDiagram.showEnable(True);  				//マシン画像キー表示.
	}
	//BootUp Screenが登録されていないかつUSB接続許可設定の[一括設定]または[外部メモリー(サービス)]が[禁止]の場合.
// Comment 2015/09/05 HCLT-Surajit RQ-163[WP 1379, WP 1381] Changing the flag name.
//		if( ( False == m_bl_USBConnectionPermissionFlag ) && ( False == m_bl_bootUpScreenFlg ) ) {
	if( ( False == m_bl_USBConnectionPermissionFlag ) && ( False == m_bl_bootUpScreenFlag ) ) {
		Key_BootUpScreen.showEnable(False);   				//Bootup screenキー非表示.
	} else {
		Key_BootUpScreen.showEnable(True);   				//Bootup screenキー表示.
	}
// Comment 2015/08/25 HCLT-Surajit RQ-163[WP 1379][Phase 2] Hide BootUp Screen Key,マシン画像 key,Authorization Customize key If machine graphic/BootUp Screen/Authorization Customize data is not registered .
	if( ( False == m_bl_USBConnectionPermissionFlag ) && ( False == m_bl_SaveAuthCustomizeDataFlag ) ) {
		Key_AuthCustomizeDataInstall.showEnable(False);   				//Authorization Customization screenキー非表示.
	} else {
		Key_AuthCustomizeDataInstall.showEnable(True);   				//Authorization Customizationキー表示.
	}
}
// Comment 2015/07/20 HCLT-Surajit RQ-163[WP 1379, WP 1381]  Hide マシン画像 key If machine graphic is not registered , BootUp Screen key If BootUp Screen is not registered .
