//===================================================================.
/**
* @brief 	: Screen start processing.
* @note 	: None.
* @param 	: None.
* @return 	: None.
* @author 	: 2013/12/19 HCLT_Senthil.
*/
//===================================================================.
void PServiceMachineDiagram::startGamen()
{
	// Initialization of status.
	memset( &m_st_status, 0, sizeof( m_st_status ) );
	memset( sc_DictInstallFileName, '\0', ( CUSTOM_SCREEN_INSTALL_FILENAME_MAXLEN + 1 ) );

	// To get the machine diagram exists status.
	m_bl_SaveCustomImageFlg = PnlComGetMachineSetting()->getOEMMachineFigDataInstallFlgInfo();

	// USB Initialization.
	static PServiceUSBFileCheckVariableSearch::USBCheckFileVariable st_usbCheckFiles[] = {
		{	0, True, True,
			CUSTOM_SCREEN_INSTALL_FILENAME_PREFIX,
			CUSTOM_SCREEN_INSTALL_FILENAME_CONNECTION,
			CUSTOM_SCREEN_INSTALL_FILENAME_EXTENSION,
			CUSTOM_SCREEN_INSTALL_FILENAME_VARIABLELEN,
			sc_DictInstallFileName,
			CUSTOM_SCREEN_INSTALL_FILENAME_BASELEN,
			CUSTOM_SCREEN_INSTALL_FILENAME_CONNECTLEN,
			CUSTOM_SCREEN_INSTALL_FILENAME_MAXLEN
		}
	};

	// 登録キー show/hide updated based on USB status.
	static PDisplayParts* pUSBCheckShowEnableParts[] = {
		&Key_MachineDiagramEntry,
	};

	gp_ServiceUSBFileCheckVariableSearch.setCheckFiles( st_usbCheckFiles, sizeof( st_usbCheckFiles ) / sizeof( st_usbCheckFiles[0] ) );					//	Input of file search in USB.
	gp_ServiceUSBFileCheckVariableSearch.setUSBStatusText( &Txt_MachineDiagramUSBStatus );															// USB search result status updation(USB NG/File NG).
	gp_ServiceUSBFileCheckVariableSearch.setShowEnableParts( pUSBCheckShowEnableParts, sizeof( pUSBCheckShowEnableParts )/sizeof( PDisplayParts** ) );	// show/hide of  登録キー.


	//Initially update the deselected state for 登録キー,削除キー,確定キー.
	m_bl_OnOffSETKey	 = False;							// 登録キー.
	m_bl_OnOffDelKey	 = False;							// 削除キー.
	m_bl_OnOffFIXKey	 = False;							// 確定キー.

	// Call Base class.
	PServiceToSystemMenu2P2Com::startGamen( );
// Comment 2015/07/20 HCLT-Surajit RQ-163[WP 1381]   Hide the registration  area(registeration key, frame, USBNG).
// Comment 2017/11/29 【HCLT-Vishal】【Eagle】【制御構成変更_No.4】 Removing old function version check condition.
	PNLC_USBConnectionPermission c_UsbPermission;
	PNLE_EnableUSBConnectionPermissionForAll e_usbAll = c_UsbPermission.getEnableUSBConnectionPermissionForAll();
	PNLE_EnableUSBConnectionPermissionForService e_usbforService = c_UsbPermission.getEnableUSBConnectionPermissionForService();
	if(( PNLE_EnableUSBConnectionPermissionForAll_Disable == e_usbAll ) || ( PNLE_EnableUSBConnectionPermissionForService_Disable == e_usbforService )) {
		m_bl_USBConnectionPermissionFlag = False;
	} else {
		m_bl_USBConnectionPermissionFlag = True;
	}
}

//===================================================================.
/**
* @brief 	: Dispaly the screen Parts.
* @note 	: None.
* @param 	: option.
* @return 	: None.
* @author 	: 2013/12/19 HCLT_Senthil.
*/
//===================================================================.
void PServiceMachineDiagram::setupGamen( short option )
{
	// Check and display the USB state. Show/Hide the 登録キー and display the "USB NG"or ファイル　NG.
	gp_ServiceUSBFileCheckVariableSearch.checkAndShow( );

	// During Download/Delete time display the executing parts.
	if( InstallDeleteExecution_Executing == getStatus() ) {
		// Display of Download/Delete processing..
		showExecuting();
	}

	// Call Base class.
	PServiceToSystemMenu2P2Com::setupGamen( option );

	// Dis Ver. if Machine diagram installed.
	if( NULL != ppc_SystemInfo ) {
		// Display of Binary ROM Version.
		char sc_RomVersion[40 + 1];
		memset( sc_RomVersion, 0, sizeof( sc_RomVersion ) );
		ppc_SystemInfo->getRomVersion( TYPE_RomOEMMachineFigData, sc_RomVersion );
		if( 0 != strlen( sc_RomVersion ) ) {
			Tfd_MachineDiagramVersion.changeExternalText( ( uchar* )sc_RomVersion, sizeof( sc_RomVersion ) );
			Grp_MachineDiagramVersionParts.showEnable( True );
		}
	}

	// Display of result parts.
	settingExecParts();

	// Select/Deselect of  登録,  削除, 確定 keys.
	Key_MachineDiagramEntry.select( m_bl_OnOffSETKey );				// 登録キー.
	// 削除, 確定 keys applicable only when machine data's exists.
	settingDeleteParts();

	Bool bl_LEDControlFlg = False;
	if( InstallDeleteExecution_Executing != getStatus() ) {
		// When 登録キー is selected and Download/Delete process complete.
		if( True == m_bl_OnOffSETKey &&
		    ServiceUSBInfo_CheckComplete == gp_ServiceUSBFileCheckVariableSearch.getUSBInfo() ) {
			bl_LEDControlFlg = True;
		}
	}
	printLEDControl( bl_LEDControlFlg );
// Comment 2015/07/20 HCLT-Surajit RQ-163[WP 1381]   Hide the registration  area(registeration key, frame, USBNG).
// Comment 2017/11/29 【HCLT-Vishal】【Eagle】【制御構成変更_No.4】 Removing old function version check condition.
	if( False == m_bl_USBConnectionPermissionFlag ){ 			//USB接続許可設定の[一括設定]または[外部メモリー(サービス)]が[禁止]の場合.
	    Key_MachineDiagramEntry.showEnable(False);				//登録,  削除, 確定キー非表示.
   		Txt_MachineDiagramUSBStatus.showEnable( False );		//USB search result status updation(USB NG/File NG)非表示.
		Bak_MachineDiagramInstall.showEnable( False );			//Background非表示.
// comment 2015/10/06 HCL_Senthil[ZeusS_ZX0] [CQ519630]To remove the registeration display parts.
//	}else {
//			Key_MachineDiagramEntry.showEnable(True);				//登録,  削除, 確定キー表示.
//     		Txt_MachineDiagramUSBStatus.showEnable( True );			//USB search result status updation(USB NG/File NG)表示.
// 			Bak_MachineDiagramInstall.showEnable( True );			//Background表示.
	}
}

//===================================================================.
/**
* @brief 	: Process soft key events. IT will receive the 登録キー, 削除キー and 確定キー key events.
* @note 	: None.
* @param 	: option (button ID).
* @return 	: None.
* @author 	: 2013/12/19 HCLT_Senthil.
*/
//===================================================================.
void PServiceMachineDiagram::procButtonOn( uchar option )
{
	// During Download/Delete time not allowed to process the key events.
	if( InstallDeleteExecution_Executing == getStatus() ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );				// 拒否音.
		return;
	}

	Bool bl_OnOffFlg = False;										// Key status flag.

	switch( option ) {
		case BTNID_MachineDiagramSET :									// 登録キー.
			bl_OnOffFlg = !( Key_MachineDiagramEntry.isSelect() );
			m_bl_OnOffSETKey = bl_OnOffFlg;
			// 削除キー is deselected when 登録キー in selected state.
			if( True == m_bl_OnOffSETKey ) {
				m_bl_OnOffDelKey = False;
			}
			break;

		case BTNID_MachineDiagramDelete :								// 削除キー.
			bl_OnOffFlg = !( Key_MachineDiagramDelete.isSelect() );
			m_bl_OnOffDelKey = bl_OnOffFlg;
			// 登録キー is deselected when 削除キー in selected state.
			if( True == m_bl_OnOffDelKey ) {
				m_bl_OnOffSETKey = False;
			}
			break;

		case BTNID_MachineDiagramFIX :									// 確定キー.
			bl_OnOffFlg = !( Key_MachineDiagramDecide.isSelect() );
			m_bl_OnOffFIXKey = bl_OnOffFlg;
			if( ( True == bl_OnOffFlg ) && ( True == m_bl_SaveCustomImageFlg ) ) {
				// Can able to delete only machine diagram exists and 確定キー is selected state,
				deleteExec();
			}
			break;
		default:
			break;
	}

	// To set Download/Delete status none for clear the result parts.
	m_st_status.e_InstallSts = InstallDeleteExecution_None;			// Status changed (Not Download).
	m_st_status.e_DeleteSts  = InstallDeleteExecution_None;		 	// Status changed (Not Deleted).

	setupGamen();
}

//===================================================================.
/**
* @brief 	: Process of OK key events.
* @note 	: None.
* @param 	: [in] option	Ok Key event(Button ID).
* @return 	: None.
* @author 	: 2013/12/19 HCLT_Senthil.
*/
//===================================================================.
void PServiceMachineDiagram::procOk( uchar option )
{
	// During Download/Delete time not allowed to process the key events.
	if( InstallDeleteExecution_Executing == getStatus() ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );		// 拒否音.
		return;
	}
	nextGamen = &gp_ServiceCustomizeScreen; 		// To Open  E0B0C00A00_スクリーンカスタマイズ／メニュー.
}

//===================================================================.
/**
* @brief 	: Process of Line key events.
* @note 	: None.
* @param 	: [in] option	Line Key event(Button ID).
* @return 	: None.
* @author 	: 2013/12/19 HCLT_Senthil.
*/
//===================================================================.
void PServiceMachineDiagram::procGoToMag( uchar option )
{
	// During Download/Delete time not allowed to process the key events.
	if( InstallDeleteExecution_Executing == getStatus() ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );		// 拒否音.
		return;
	}

	PServiceToSystemMenu2P2Com::procGoToMag( option );
}

