//===================================================================.
/**
* @brief 	: Process of START key events.
* @note 	: None.
* @param 	: [in] option	START Key event.
* @return 	: None.
* @author 	: 2013/12/19 HCLT_Senthil.
*/
//===================================================================.
void PServiceMachineDiagram::procStart( uchar option )
{
	if( True == printStartDisable() ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );		// 拒否音.
		return;
	}

	PnlComGetMachineSetting()->saveHDDdata( TYPE_CharSetUTF8, ( char* )sc_DictInstallFileName, ( char* )sc_SSDdir, ans_SetMachineDiagram, True );

	m_st_status.e_InstallSts = InstallDeleteExecution_Executing;	// Status changed (During Download).
	m_st_status.e_DeleteSts  = InstallDeleteExecution_None;		 	// Status changed (NotDeleted).

	setupGamen();
}

//===================================================================.
/**
* @brief 	: Download complete notification (Callback function).
* @note 	: None.
* @param 	: [in]Bool Download result(True if success else False).
* @return 	: None.
* @author 	: 2013/12/19 HCLT_Senthil.
*/
//===================================================================.
void PServiceMachineDiagram::ans_SetMachineDiagram( Bool bl_Status )
{
	m_bl_InstallCompleteStatus = bl_Status;		// To set Download status.
	if( True == bl_Status ) {
		m_bl_SaveCustomImageFlg	 = True;		// To set the file exists status.
	}

	CallBackIndi( TYPE_PNL_CallBack_MachineDiagramInstallComplete );
}

//===================================================================.
/**
* @brief 	: Delete the machine diagram.
* @note 	: None.
* @param 	: [in]Bool Delete result(True if success else False).
* @return 	: None.
* @author 	: 2013/12/19 HCLT_Senthil.
*/
//===================================================================.
void PServiceMachineDiagram::deleteExec( )
{
	// Delete exists machine diagram.
	PnlComGetMachineSetting()->eraseHddArea( ( char* )sc_SSDdirWithFilename, ans_EraseMachineDiagram, True );

	m_st_status.e_DeleteSts  = InstallDeleteExecution_Executing;	// Status changed (During Delete).
	m_st_status.e_InstallSts = InstallDeleteExecution_None;		 	// Status changed (Not Download).

}

//===================================================================.
/**
* @brief 	: Delete complete notification (Callback function).
* @note 	: None.
* @param 	: [in]Bool Delete result(True if success else False).
* @return 	: None.
* @author 	: 2013/12/19 HCLT_Senthil.
*/
//===================================================================.
void PServiceMachineDiagram::ans_EraseMachineDiagram( Bool bl_Status )
{
	m_bl_DeleteCompleteStatus = bl_Status;
	if( True == bl_Status ) {
		// Deletion is success, to update the exists flag status.
		m_bl_SaveCustomImageFlg = False;
	}

	CallBackIndi( TYPE_PNL_CallBack_MachineDiagramDeleteComplete );
}

//===================================================================.
/**
* @brief 	: To get the Download/Delete notification.
* @note 	: None.
* @param 	: [in]option TYPE_PNL_CallBack.
* @return 	: None.
* @author 	: 2013/12/19 HCLT_Senthil.
*/
//===================================================================.
void PServiceMachineDiagram::procCallBack( TYPE_PNL_CallBack option )
{
	switch( option ) {
		case TYPE_PNL_CallBack_MachineDiagramInstallComplete:
			// Download Complete.
			if( True == m_bl_InstallCompleteStatus ) {
				PnlComGetMachineSetting()->setOEMMachineFigDataInstallFlgInfo( m_bl_SaveCustomImageFlg );		// To set Data exist's in memory.
				m_st_status.e_InstallSts = InstallDeleteExecution_OK;		// Download Success.
			} else {
				m_st_status.e_InstallSts = InstallDeleteExecution_NG;		// Download Failure.
			}
			m_bl_OnOffSETKey = False;    									// Delselect the  登録キー.
			break;
		case TYPE_PNL_CallBack_MachineDiagramDeleteComplete:
			// Delete Complete.
			if( True == m_bl_DeleteCompleteStatus ) {
				PnlComGetMachineSetting()->setOEMMachineFigDataInstallFlgInfo( m_bl_SaveCustomImageFlg );		// To set Data not exist's in memorry.
				m_st_status.e_DeleteSts = InstallDeleteExecution_OK;		// Delete Success.
			} else {
				m_st_status.e_DeleteSts = InstallDeleteExecution_NG;		// Delete Failure.
			}
			m_bl_OnOffDelKey = False;    									// Delselect the   削除キー.
			m_bl_OnOffFIXKey = False;										// Delselect the   確定キー.
			break;
		default:
			break;
	}
	setupGamen();
}

//===================================================================.
/**
* @brief 	: Display of delete related group parts.
* @note 	: None.
* @param 	: [in]None.
* @return 	: None.
* @author 	: 2013/12/19 HCLT_Senthil.
*/
//===================================================================.
void PServiceMachineDiagram::settingDeleteParts()
{
	// Display delete parts only when exists machine diagram available.
	if( True == m_bl_SaveCustomImageFlg ) {
		Grp_MachineDiagramDelete.showEnable( True );
		Key_MachineDiagramDelete.select( m_bl_OnOffDelKey );		// 削除キー.
		// Show 確定キー, when 削除キー is selected state.
		Key_MachineDiagramDecide.showEnable( m_bl_OnOffDelKey );
		Key_MachineDiagramDecide.select( m_bl_OnOffFIXKey );		// 確定キー.
	} else {
		Grp_MachineDiagramDelete.showEnable( False );
	}
}

//===================================================================.
/**
* @brief 	: Display of Download/Delete processing.
* @note 	: None.
* @param 	: [in]None.
* @return 	: None.
* @author 	: 2013/12/19 HCLT_Senthil.
*/
//===================================================================.
void PServiceMachineDiagram::showExecuting()
{
	static	Bool	bl_InstallingAnimeSts = False;		// Flag for Sequentially displaying the  "/","＼".
	TEXT_ID			executingTextId;

	if( True == bl_InstallingAnimeSts ) {
		executingTextId = s_EXPSlash;
		bl_InstallingAnimeSts = False;
	} else {
		executingTextId = s_EXPBackslash;
		bl_InstallingAnimeSts = True;
	}
	Txt_MachineDiagramSlash.changeText( executingTextId ); // displaying the  "/" or "＼".
}

//===================================================================.
/**
* @brief 	: Dispaly of Downlaod/Delete result parts.
* @note 	: None.
* @param 	: [in]None.
* @return 	: None.
* @author 	: 2013/12/19 HCLT_Senthil.
*/
//===================================================================.
void PServiceMachineDiagram::settingExecParts()
{
	struct PNLS_ShowResultParamStruct {
		TEXT_ID	resultTextId;			// Download/delete completion status (OK or NG message).
		Bool	bl_ExecutionFlg;		// Show/hide the parts.
	};
	static PNLS_ShowResultParamStruct st_showResultParam[] = {
		{ 0,		False },			//  InstallDeleteExecution_None		- Do not Download/Delete.
		{ 0,		False },			//  InstallDeleteExecution_Reserved	- Download/Delete reserved.
		{ 0,		True  },			//  InstallDeleteExecution_Executing- Download/Delete Execution.
		{ s_Ok,		False },			//  InstallDeleteExecution_OK		- Download/Delete success.
		{ s_NG,		False },			//  InstallDeleteExecution_NG 		- Download/Delete failure.
	};

	// Get current status of download/delete.
	InstallDeleteExecutionStatus eExecSts = getStatus();

	Bool bl_NotifyMsg = False;			// Machine diagram download/delete completion status.
	// Display of result part. Hide the result(OK/NG message) when status is not a InstallDeleteExecution_OK or InstallDeleteExecution_NG.
	if( 0 == st_showResultParam[eExecSts].resultTextId ) {
		Txt_MachineDiagramResultStatus.showEnable( False );
	} else {
		// Dispaly the result(OK/NG message) when status is InstallDeleteExecution_OK or InstallDeleteExecution_NG.
		Txt_MachineDiagramResultStatus.showEnable( True );
		Txt_MachineDiagramResultStatus.changeText( st_showResultParam[eExecSts].resultTextId );
		if( s_Ok == st_showResultParam[eExecSts].resultTextId ) {
			bl_NotifyMsg = True;
		}
	}
	// Display the notification message.
	Txt_MachineDiagramFinishMessage.showEnable( bl_NotifyMsg );
	Txt_MachineDiagramDownArrow.showEnable( bl_NotifyMsg );

	// Display of "/" or "＼".
	Txt_MachineDiagramSlash.showEnable( st_showResultParam[eExecSts].bl_ExecutionFlg );
}

//===================================================================.
/**
* @brief 	: Download/Delete state acquisition.
* @note 	: None.
* @param 	: [in]None.
* @return	:InstallDeleteExecution_None		：	何も処理を行っていない.
*			:InstallDeleteExecution_Executing	：	インストールor削除中.
*			:InstallDeleteExecution_OK			：	インストールor削除成功.
*			:InstallDeleteExecution_NG			：	インストールor削除失敗.
* @author 	: 2013/12/19 HCLT_Senthil.
*/
//===================================================================.
InstallDeleteExecutionStatus PServiceMachineDiagram::getStatus()
{
	if( InstallDeleteExecution_None != m_st_status.e_InstallSts ) {
		// Download status.
		return m_st_status.e_InstallSts;
	}
	if( InstallDeleteExecution_None != m_st_status.e_DeleteSts ) {
		// Delete status.
		return m_st_status.e_DeleteSts;
	}
	// Download/Delete not perform return,InstallDeleteExecution_None state.
	return InstallDeleteExecution_None;
}

//================================================================================================.
//［Class］	PServiceAuthCustomizeDataInstall :   E0B0C00C00_システム設定／認証カスタマイズデータ.
//================================================================================================.
Bool PServiceAuthCustomizeDataInstall::m_bl_InstallCompleteStatus = False;			// インストール完了通知が来たときの通知結果.
Bool PServiceAuthCustomizeDataInstall::m_bl_DeleteCompleteStatus = False;			// 削除完了通知が来たときの通知結果.
Bool PServiceAuthCustomizeDataInstall::m_bl_SaveAuthCustomizeDataFlg = False;		// 認証カスタマイズデータコンフィグレーションファイル存在フラグ.

char PServiceAuthCustomizeDataInstall::sc_DictInstallFileName[ PNLD_SERV_AUTH_CUSTOMIZE_DATA_FILENAME_MAXLEN + 1 ];		// 認証カスタマイズデータコンフィグレーションファイル名.

//===================================================================.
/**
* @brief   : コンストラクタ.
* @param   : partsTable パーツテーブル.
* @param   : partsNumber パーツ数.
* @param   : isNoWarningGamen 警告表示禁止画面設定.
* @return  : -.
*/
//===================================================================.
PServiceAuthCustomizeDataInstall::PServiceAuthCustomizeDataInstall( PDisplayParts** partsTable, short partsNumber, Bool isNoWarningGamen )
	:PServiceToSystemMenu2P2Com( partsTable, partsNumber, isNoWarningGamen )
{
	memset( &m_st_status, 0x00, sizeof( m_st_status ) );		// インストール/削除状態.
	m_bl_OnOffRegistKey = False;		// 登録キー選択状態.
	m_bl_OnOffDelKey = False;			// 削除キー選択状態.
	m_bl_OnOffFixKey = False;			// 確定キー選択状態.
	memset( sc_DictInstallFileName, '\0', ( PNLD_SERV_AUTH_CUSTOMIZE_DATA_FILENAME_MAXLEN + 1 ) );		// 認証カスタマイズデータコンフィグレーションファイル名.
// Comment 2015/10/08【HCLT-Meera】【CQ519679】【ID: 28739】UNINIT.CTOR.MUST.
    m_bl_USBConnectionPermissionFlag = True;
}

//===================================================================.
/**
* @brief   : 画面開始処理.
* @param   : -.
* @return  : -.
*/
//===================================================================.
void PServiceAuthCustomizeDataInstall::startGamen()
{
	// 初期化.
	memset( &m_st_status, 0x00, sizeof( m_st_status ) );		// インストール/削除状態.
	m_bl_OnOffRegistKey = False;		// 登録キー選択状態.
	m_bl_OnOffDelKey = False;			// 削除キー選択状態.
	m_bl_OnOffFixKey = False;			// 確定キー選択状態.
	memset( sc_DictInstallFileName, '\0', ( PNLD_SERV_AUTH_CUSTOMIZE_DATA_FILENAME_MAXLEN + 1 ) );		// 認証カスタマイズデータコンフィグレーションファイル名.

	// マスター設定認証カスタマイズデータインストール済み判定.
	m_bl_SaveAuthCustomizeDataFlg = False;
	APIC_AuthCust* pc_AuthCust = APIC_AuthCust::newInstance();
	if( NULL != pc_AuthCust) {
		m_bl_SaveAuthCustomizeDataFlg = pc_AuthCust->chkInstallAuthCustomMaster();
	}

	// ファイル検索条件を生成.
	static PServiceUSBFileCheckVariableSearch::USBCheckFileVariable st_usbCheckFiles[] = {
		{
			0,														// ファイルID.
			True,													// ファイル存在の有無.
			True,													// setShowEnableParts()で設定したパーツの表示の判断にこのファイルの存在有無チェックを行うか否か.
			PNLD_SERV_AUTH_CUSTOMIZE_DATA_FILENAME_PREFIX,			// 検索対象ファイル名(接頭辞).
			PNLD_SERV_AUTH_CUSTOMIZE_DATA_FILENAME_CONNECTION,		// 検索対象ファイル名(可変部との接続文字).
			PNLD_SERV_AUTH_CUSTOMIZE_DATA_FILENAME_EXTENSION,		// 検索対象ファイル名(拡張子).
			PNLD_SERV_AUTH_CUSTOMIZE_DATA_FILENAME_VARIABLELEN,		// 検索対象ファイル名(可変部の最大文字数).
			sc_DictInstallFileName,									// 検索結果ファイル名.
// comment 2015/9/2 OPS1-MSE永野[ZeusS_ZX0][RQ-257][CQ518229]可変部なしのファイルをファイル有と判断しないように修正.
//			PNLD_SERV_AUTH_CUSTOMIZE_DATA_FILENAME_BASELEN,			// Length of search file name.
			0,														// Length of search file name. 可変部なしは不可のため、基準名サイズをダミーで埋める.
			PNLD_SERV_AUTH_CUSTOMIZE_DATA_FILENAME_CONNECTLEN,		// Conection length of search file Name.
			PNLD_SERV_AUTH_CUSTOMIZE_DATA_FILENAME_MAXLEN			// Maximum length of search file Name.
		}
	};	

	// USBメモリの状態で表示/非表示の切替が必要なパーツテーブルを生成.
	static PDisplayParts* pUSBCheckShowEnableParts[] ={
		&Key_AuthCustomizeDataInstallRegist,
	};

	// ファイル検索条件の設定.
	gp_ServiceUSBFileCheckVariableSearch.setCheckFiles( st_usbCheckFiles, sizeof( st_usbCheckFiles ) / sizeof( st_usbCheckFiles[ 0 ] ) );

	// USBの状態表示テキストを設定.
	gp_ServiceUSBFileCheckVariableSearch.setUSBStatusText( &Txt_AuthCustomizeDataInstallUSBStatus );

	// USBメモリの状態で表示/非表示の切替が必要なパーツテーブルを設定.
	gp_ServiceUSBFileCheckVariableSearch.setShowEnableParts( pUSBCheckShowEnableParts, sizeof( pUSBCheckShowEnableParts ) / sizeof( PDisplayParts** ) );

	PServiceToSystemMenu2P2Com::startGamen( );
	
// Comment 2015/07/20 HCLT-Surajit RQ-163[WP 1383]   Hide the registration  area(registeration key, frame, USBNG).
// Comment 2017/11/29 【HCLT-Vishal】【Eagle】【制御構成変更_No.4】 Removing old function version check condition.
	PNLC_USBConnectionPermission c_UsbPermission;
	PNLE_EnableUSBConnectionPermissionForAll e_usbAll = c_UsbPermission.getEnableUSBConnectionPermissionForAll();
	PNLE_EnableUSBConnectionPermissionForService e_usbforService = c_UsbPermission.getEnableUSBConnectionPermissionForService();
	if(( PNLE_EnableUSBConnectionPermissionForAll_Disable == e_usbAll ) || ( PNLE_EnableUSBConnectionPermissionForService_Disable == e_usbforService )) {
		m_bl_USBConnectionPermissionFlag = False;
	} else {
		m_bl_USBConnectionPermissionFlag = True;
	}
}

//===================================================================.
/**
* @brief   : 表示部品のセットアップ.
* @param   : option オプション.
* @return  : -.
*/
//===================================================================.
void PServiceAuthCustomizeDataInstall::setupGamen( short option )
{
	// USB内のファイルチェックと表示制御.
	gp_ServiceUSBFileCheckVariableSearch.checkAndShow();

	// インストール/削除状態が実行中の場合.
	if( InstallDeleteExecution_Executing == getStatus() ){
		// インストール/削除実行中表示処理.
		showExecuting();
	}

	PServiceToSystemMenu2P2Com::setupGamen( option );

	if( NULL != ppc_SystemInfo ){
		char sc_RomVersion[40 + 1];
		memset( sc_RomVersion, 0x00, sizeof( sc_RomVersion ) );
		//ROMバージョン取得.
		ppc_SystemInfo->getRomVersion( TYPE_RomMasterConfigSetting, sc_RomVersion );
//	Comment 2015/11/23 HCLT_Anusha [ZeusS_ZX0][CQ519970] Else part is added to hide the "Ver." when custom data is not installed.
		if( 0 != strlen( sc_RomVersion ) ){
			// バージョンデータテキストにROMバージョンを設定.
			Tfd_AuthCustomizeDataInstallVersion.changeExternalText( ( uchar* )sc_RomVersion, sizeof( sc_RomVersion ) );
			// バージョングループを表示.
			Grp_AuthCustomizeDataInstallVersionParts.showEnable( True );
		} else{
			// Hide Version group.
			Grp_AuthCustomizeDataInstallVersionParts.showEnable( False );
		}
	}

	// 結果グループパーツ表示処理.
	settingExecParts();

	// 登録キーに選択状態を設定.
	Key_AuthCustomizeDataInstallRegist.select( m_bl_OnOffRegistKey );

	// 削除グループパーツ表示処理.
	settingDeleteParts();

	// スタートキー用のLEDフラグを生成.
	Bool bl_LEDControlFlg = False;

	// インストール/削除状態が実行中ではない場合.
	if( InstallDeleteExecution_Executing != getStatus() ){

		if( True == m_bl_OnOffRegistKey && ServiceUSBInfo_CheckComplete == gp_ServiceUSBFileCheckVariableSearch.getUSBInfo() ){
			bl_LEDControlFlg = True;
		}
	}

	// プリントキーLEDの制御.
	printLEDControl( bl_LEDControlFlg );
	
// Comment 2015/07/20 HCLT-Surajit RQ-163[WP 1383]   Hide the registration  area(registeration key, frame, USBNG).
// Comment 2017/11/29 【HCLT-Vishal】【Eagle】【制御構成変更_No.4】 Removing old function version check condition.
	if( False == m_bl_USBConnectionPermissionFlag ){ 						//USB接続許可設定の[一括設定]または[外部メモリー(サービス)]が[禁止]の場合.
	    Key_AuthCustomizeDataInstallRegist.showEnable(False);				//登録,  削除, 確定キー非表示.
   		Txt_AuthCustomizeDataInstallResultStatus.showEnable( False );		//USB search result status updation(USB NG/File NG)非表示.
		Bak_AuthCustomizeDataInstallRegist.showEnable( False );				//Background非表示.
// comment 2015/10/06 HCL_Senthil[ZeusS_ZX0] [CQ519630]To remove the registeration display parts.
//		}else {
//			Key_AuthCustomizeDataInstallRegist.showEnable(True);				//登録,  削除, 確定キー表示.
//    		Txt_AuthCustomizeDataInstallResultStatus.showEnable( True );		//USB search result status updation(USB NG/File NG)表示.
// 			Bak_AuthCustomizeDataInstallRegist.showEnable( True );				//Background表示.
	}
}

//===================================================================.
/**
* @brief   : ボタン押下処理.
* @param   : option オプション.
* @return  : -.
*/
//===================================================================.
void PServiceAuthCustomizeDataInstall::procButtonOn( uchar option )
{
	// インストール/削除状態が実行中の場合.
	if( InstallDeleteExecution_Executing == getStatus() ){
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}

	switch( option ){
		case BTNID_AuthCustomizeDataInstallRegist:				// 登録キー.

			// 登録キー選択状態フラグを変更.
			if( True == Key_AuthCustomizeDataInstallRegist.isSelect() ){
				m_bl_OnOffRegistKey = False;
			}else{
				m_bl_OnOffRegistKey = True;

				// 削除キー選択状態フラグを未選択に変更.
				m_bl_OnOffDelKey = False;
			}
			break;

		case BTNID_AuthCustomizeDataInstallDelete:				// 削除キー.

			// 削除キー選択状態フラグを変更.
			if( True == Key_AuthCustomizeDataInstallDelete.isSelect() ){
				m_bl_OnOffDelKey = False;
			}else{
				m_bl_OnOffDelKey = True;

				// 登録キー選択状態フラグを未選択に変更.
				m_bl_OnOffRegistKey = False;
			}
			break;

		case BTNID_AuthCustomizeDataInstallFix :				// 確定キー.

			// 確定キー選択状態フラグを変更.
			if( True == Key_AuthCustomizeDataInstallFix.isSelect() ){
				m_bl_OnOffFixKey = False;
			}else{
				m_bl_OnOffFixKey = True;
			}
			if( ( True == m_bl_OnOffFixKey ) && ( True == m_bl_SaveAuthCustomizeDataFlg ) ){
				// 認証カスタマイズデータコンフィグレーションファイル削除処理.
				deleteExec();
			}
			break;

		default:
			break;

	}
	// インストール状態を初期化.
	m_st_status.e_InstallSts = InstallDeleteExecution_None;

// comment 2015/08/28 OPS1-MSE永野 [ZeusS_ZX0][RQ-257][CQ518114]認証カスタマイズの追加.
//	// 削除状態を初期化.
//	m_st_status.e_DeleteSts  = InstallDeleteExecution_None;

	setupGamen();
}

//===================================================================.
/**
* @brief   : インストール完了通知.
* @param   : bl_Status インストール結果.
* @return  : -.
*/
//===================================================================.
void PServiceAuthCustomizeDataInstall::ans_startInstall( Bool bl_Status )
{
	// インストール完了通知結果にインストール結果を設定.
	m_bl_InstallCompleteStatus = bl_Status;

	if( True == bl_Status ){
		// 認証カスタマイズデータコンフィグレーションファイル存在フラグにTrueを設定.
		m_bl_SaveAuthCustomizeDataFlg = True;
	}

	CallBackIndi( TYPE_PNL_CallBack_AuthCustomizeDataInstallComplete );

}

//===================================================================.
/**
* @brief   : スタートキー押下処理.
* @param   : option オプション.
* @return  : -.
*/
//===================================================================.
void PServiceAuthCustomizeDataInstall::procStart( uchar option )
{
	// スタートキー禁止チェック.
	if( True == printStartDisable() ){
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}

	static char sc_FilePath[PNLD_FILEPATH_MAX];
	memset( sc_FilePath, '\0', PNLD_FILEPATH_MAX );
	APIC_AuthCust* pc_AuthCust = APIC_AuthCust::newInstance();
	if( NULL == pc_AuthCust ) {
//2019/06/17 Comment [HCLT_Krishnakumar][EagleH][N Rank] Removed unwanted detailed code.
//// 2015/11/05 【HCLT-Dhivya】 【ZeusS_ZX0】 【制御構成変更_No.76-1】Detail macro is passed in API.
//		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if (NULL != pc_BFW_System){
//    		pc_BFW_System->registDetailCode(PNLD_DetailCode_Service_0x1900280100671001);
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}
	char** psc_Names = NULL;
	char* psc_Tmp = NULL;
	char sc_DeviceName[PNLD_USB_DEVICEPATH_MAX];
//comment 2023/4/28 FPT.HungDM17 【IT6_2.3】【ALL MACHINE】【OP_BTS-39182】認証カスタマイズデータインポート時、ウイルス検知でインポートOKとなる問題対策.
	APIC_UsbImportExportOperation* pc_UsbImportExportOperation = APIC_UsbImportExportOperation::newInstance();
	if( NULL == pc_UsbImportExportOperation )
	{
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}

	memset( sc_DeviceName, '\0', PNLD_USB_DEVICEPATH_MAX );
	psc_Names = &psc_Tmp;
	*psc_Names = (char*)sc_DeviceName;
	SYSC_GetBulkDeviceNames( psc_Names, PNLD_USB_DEVICEMOUNT_NUM );
	pc_AuthCust->searchAuthCustomFile( sc_FilePath, ACID_AuthCustomInfo_Master_File, sc_DeviceName );
//comment 2023/4/28 FPT.HungDM17 【IT6_2.3】【ALL MACHINE】【OP_BTS-39182】認証カスタマイズデータインポート時、ウイルス検知でインポートOKとなる問題対策.
	// ウィルススキャンチェック.
	if ( True != pc_UsbImportExportOperation->chkMasterConfigSettingVirusScan( TYPE_UsbImportExportKind_Import, sc_FilePath) ) {
		// インストール状態を実行中に変更.
		m_st_status.e_InstallSts = InstallDeleteExecution_Executing;
		// 削除状態を初期化.
		m_st_status.e_DeleteSts = InstallDeleteExecution_None;
		// ウィルスを検知した場合は、結果NGとする.
		ans_startInstall(false);
	} else {
		SAAG_startInstall( SAAE_InstallDataKindConfiguration, ans_startInstall, sc_FilePath );

		// インストール状態を実行中に変更.
		m_st_status.e_InstallSts = InstallDeleteExecution_Executing;

		// 削除状態を初期化.
		m_st_status.e_DeleteSts = InstallDeleteExecution_None;
	}
	setupGamen();
}

//===================================================================.
/**
* @brief   : OKキー押下処理.
* @param   : option オプション.
* @return  : -.
*/
//===================================================================.
void PServiceAuthCustomizeDataInstall::procOk( uchar option )
{
	// インストール/削除状態が実行中の場合.
	if( InstallDeleteExecution_Executing == getStatus() ){
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}

	nextGamen = &gp_ServiceCustomizeScreen; 		// E0B0C00A00_スクリーンカスタマイズ／メニュー.
}

