//===================================================================.
/**
* @brief   : コールバック.
* @param   : option コールバックの種類.
* @return  : -.
*/
//===================================================================.
void PServiceAuthCustomizeDataInstall::procCallBack( TYPE_PNL_CallBack option )
{
	switch( option ){
		case TYPE_PNL_CallBack_AuthCustomizeDataInstallComplete:

			// インストール完了結果.
			if( True == m_bl_InstallCompleteStatus ){
				m_st_status.e_InstallSts = InstallDeleteExecution_OK;		// インストール成功.
// comment 2015/09/08 MSE岡田 [ZeusS_ZX0][CQ518352] インストール成功時にバージョンを更新する処理を追加.
				// インストール直後にマスター設定コンフィグレーションファイルのバージョン取得する場合は、バージョン読込みAPIを呼ぶ.
				APIC_AuthCust* pc_AuthCust = APIC_AuthCust::newInstance();
				if( NULL != pc_AuthCust) {
					pc_AuthCust->readConfigVersionMaster();
				}
			}else{
				m_st_status.e_InstallSts = InstallDeleteExecution_NG;		// インストール失敗.
			}
			m_bl_OnOffRegistKey = False;		// 登録キー選択状態フラグを未選択に変更.
			break;

		default:
			break;
	}

	setupGamen();
}

//===================================================================.
/**
* @brief   : 認証カスタマイズデータコンフィグレーションファイル削除処理.
* @param   : -.
* @return  : -.
*/
//===================================================================.
void PServiceAuthCustomizeDataInstall::deleteExec()
{
	// アンインストール結果を異常終了で初期化.
	ACIE_AuthCustomFileResult e_AuthCustomFileResult = ACIE_AuthCustomFileResult_NG;
	APIC_AuthCust* pc_AuthCust = APIC_AuthCust::newInstance();
	if( NULL != pc_AuthCust ) {
		// コンフィグファイル削除.
		e_AuthCustomFileResult = pc_AuthCust->deleteAuthCustomFile( ACIE_DeleteCustom_MasterAndUser );
	}

	// 削除完了結果.
	if( ACIE_AuthCustomFileResult_OK == e_AuthCustomFileResult ){
		m_st_status.e_DeleteSts = InstallDeleteExecution_OK;		// 削除成功.
// comment 2015/08/28 OPS1-MSE永野 [ZeusS_ZX0][RQ-257][CQ518114]削除結果OK/NGが表示されない.
		// インストール状態を初期化.
		m_st_status.e_InstallSts = InstallDeleteExecution_None;
		// コンフィグファイル存在フラグ更新.
		m_bl_SaveAuthCustomizeDataFlg = False;
		
//	Comment 2015/11/23 HCLT_Anusha [ZeusS_ZX0][CQ519970] Delete the ROM version when the custom data is removed.
		ppc_SystemInfo->setRomVersion( TYPE_RomMasterConfigSetting, "" );
	}else{
		m_st_status.e_DeleteSts = InstallDeleteExecution_NG;		// 削除失敗.
	}
	m_bl_OnOffDelKey = False;		// 削除キー選択状態フラグを未選択に変更.
	m_bl_OnOffFixKey = False;		// 確定キー選択状態フラグを未選択に変更.

}

//===================================================================.
/**
* @brief   : 結果グループパーツ表示処理.
* @param   : -.
* @return  : -.
*/
//===================================================================.
void PServiceAuthCustomizeDataInstall::settingExecParts()
{
	// 結果関連パーツの設定用構造体.
	struct PNLS_AuthCustomizeDataInstallShowResultParamStruct {
		TEXT_ID	resultTextId;			// 結果表示(0の時は非表示).
		Bool	bl_ExecutionFlg;		// 実行中かどうかを示すパーツの表示設定.
	};

	// 結果関連パーツの設定用テーブル.
	static PNLS_AuthCustomizeDataInstallShowResultParamStruct st_AuthCustomizeDataInstallShowResultParam[] = {
		{ 0,		False },			//  InstallDeleteExecution_None - 何もしていない.
		{ 0,		False },			//  InstallDeleteExecution_Reserved - 処理予約(未使用).
		{ 0,		True  },			//  InstallDeleteExecution_Executing - 処理中.
		{ s_Ok,		False },			//  InstallDeleteExecution_OK - インストールor削除成功.
		{ s_NG,		False },			//  InstallDeleteExecution_NG - インストールor削除失敗.
	};

	// メッセージ表示フラグ.
	Bool bl_NotifyMsg = False;

	InstallDeleteExecutionStatus eExecSts = getStatus();

	if( 0 == st_AuthCustomizeDataInstallShowResultParam[ eExecSts ].resultTextId ){
		// 実行結果テキストを非表示.
		Txt_AuthCustomizeDataInstallResultStatus.showEnable( False );
	}else{
		// 実行結果テキストを表示.
		Txt_AuthCustomizeDataInstallResultStatus.showEnable( True );

		// 実行結果テキストに文字列を変更.
		Txt_AuthCustomizeDataInstallResultStatus.changeText( st_AuthCustomizeDataInstallShowResultParam[ eExecSts ].resultTextId );

		if( s_Ok == st_AuthCustomizeDataInstallShowResultParam[ eExecSts ].resultTextId ){
			bl_NotifyMsg = True;
		}
	}

	// 下矢印テキストの表示状態を変更.
	Txt_AuthCustomizeDataInstallDownArrow.showEnable( bl_NotifyMsg );
	// 「本体主電源をOFF/ONしてください」メッセージの表示状態を変更.
	Txt_AuthCustomizeDataInstallFinishMessage.showEnable( bl_NotifyMsg );

	// 「／or＼」テキストの表示状態を変更.
	Txt_AuthCustomizeDataInstallSlash.showEnable( st_AuthCustomizeDataInstallShowResultParam[ eExecSts ].bl_ExecutionFlg );
}

//===================================================================.
/**
* @brief   : 削除グループパーツ表示処理.
* @param   : -.
* @return  : -.
*/
//===================================================================.
void PServiceAuthCustomizeDataInstall::settingDeleteParts()
{
	// 認証カスタマイズデータコンフィグレーションファイル存在フラグをチェック.
	if( True == m_bl_SaveAuthCustomizeDataFlg ){
		// 削除グループを表示.
		Grp_AuthCustomizeDataInstallDelete.showEnable( True );

		// 削除キーの選択状態を変更.
		Key_AuthCustomizeDataInstallDelete.select( m_bl_OnOffDelKey );

		// 削除キーの選択状態に合わせて、確定キーの表示状態を変更.
		Key_AuthCustomizeDataInstallFix.showEnable( m_bl_OnOffDelKey );

		// 確定キーの選択状態を変更.
		Key_AuthCustomizeDataInstallFix.select( m_bl_OnOffFixKey );
	} else {
		// 削除グループを非表示.
		Grp_AuthCustomizeDataInstallDelete.showEnable( False );
	}
}

//===================================================================.
/**
* @brief   : インストール/削除実行中表示処理.
* @param   : -.
* @return  : -.
*/
//===================================================================.
void PServiceAuthCustomizeDataInstall::showExecuting()
{
	static Bool bl_InstallingAnimeSts = False;		// インストール中であることを示す表示を行うためのフラグ.
	TEXT_ID executingTextId;						// テキストID.

	if( True == bl_InstallingAnimeSts ){
		executingTextId = s_EXPSlash;		// 「／」.
		bl_InstallingAnimeSts = False;
	}else{
		executingTextId = s_EXPBackslash;	// 「＼」.
		bl_InstallingAnimeSts = True;
	}

	// 「／or＼」テキストの文字列を変更.
	Txt_AuthCustomizeDataInstallSlash.changeText( executingTextId );
}

//===================================================================.
/**
* @brief   : インストール/削除状態取得.
* @param   : -.
* @return  : インストール/削除状態.
*/
//===================================================================.
InstallDeleteExecutionStatus PServiceAuthCustomizeDataInstall::getStatus()
{
	if( InstallDeleteExecution_None != m_st_status.e_InstallSts ){
		// インストールの状態.
		return m_st_status.e_InstallSts;
	}
	if( InstallDeleteExecution_None != m_st_status.e_DeleteSts ){
		// 削除の状態.
		return m_st_status.e_DeleteSts;
	}
	// 何も行っていない状態.
	return InstallDeleteExecution_None;
}

