void PServiceFinisherPunchRegistLoopAdjMainZet::procButtonOn( uchar option )
{
	switch( option ) {
		case 100:	addIndi();	break;	// +キー.
		case 101:	subIndi();	break;	// -キー.
		case 60:	// 元に戻すキー.
			setPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldRegLoopZU_ADU, ss_BakFinisherPunchRegistRegLoopZUADU );
			break;
		default: PServiceFinisherAdjCom::procButtonOn( option ); break;
	}
	setupGamen();
}
