	ss_BakFinisherZPunchHeightA4R			= getPrinterIndiInSystem( TYPE_FS526_AD_PunchAdjZFoldDepth_A4SEF	);	// A4R.
	ss_BakFinisherZPunchHeightB5			= getPrinterIndiInSystem( TYPE_FS526_AD_PunchAdjZFoldDepth_B5LEF	);	// B5.
	ss_BakFinisherZPunchHeightB5R			= getPrinterIndiInSystem( TYPE_FS526_AD_PunchAdjZFoldDepth_B5SEF	);	// B5R.
	ss_BakFinisherZPunchHeightA5			= getPrinterIndiInSystem( TYPE_FS526_AD_PunchAdjZFoldDepth_A5LEF	);	// A5.
	ss_BakFinisherZPunchHeightA5R			= getPrinterIndiInSystem( TYPE_FS526_AD_PunchAdjZFoldDepth_A5SEF	);	// A5R.
	ss_BakFinisherZPunchHeight11x17			= getPrinterIndiInSystem( TYPE_FS526_AD_PunchAdjZFoldDepth_11x17SEF	);	// 11x17.
	ss_BakFinisherZPunchHeight8_5x14		= getPrinterIndiInSystem( TYPE_FS526_AD_PunchAdjZFoldDepth_85x14SEF	);	// 8.5x14.
	ss_BakFinisherZPunchHeight8_5x11		= getPrinterIndiInSystem( TYPE_FS526_AD_PunchAdjZFoldDepth_85x11LEF	);	// 8.5x11.
	ss_BakFinisherZPunchHeight8_5x11R		= getPrinterIndiInSystem( TYPE_FS526_AD_PunchAdjZFoldDepth_85x11SEF	);	// 8.5x11R.
	ss_BakFinisherZPunchHeight5_5x8_5		= getPrinterIndiInSystem( TYPE_FS526_AD_PunchAdjZFoldDepth_55x85LEF	);	// 5.5x8.5.
