//================================================================================================
// 概要		:フィニッシャー調整／FS-FN調整／パンチ(Z折り)縦位置調整(50C00200)・ボタン押下.
//================================================================================================
void PServiceFinisherZPunchHeightPositionAdjCom::procButtonOn( uchar option )
{
	switch( option ) {
		case 100:	addIndi();	break;	// +キー.
		case 101:	subIndi();	break;	// -キー.
		case 60:	// 元に戻すキー.
			switch( getIndiSelected() ) {
				case TYPE_FS526_AD_PunchAdjZFoldDepth_All:				setPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_All,				ss_BakFinisherZPunchHeightALL	);	break;	// 全体.
				case TYPE_FS526_AD_PunchAdjZFoldDepth_A3SEF:			setPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_A3SEF,				ss_BakFinisherZPunchHeightA3	);	break;	// A3.
				case TYPE_FS526_AD_PunchAdjZFoldDepth_B4SEF:			setPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_B4SEF,				ss_BakFinisherZPunchHeightB4	);	break;	// B4.
				case TYPE_FS526_AD_PunchAdjZFoldDepth_A4LEF:			setPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_A4LEF,				ss_BakFinisherZPunchHeightA4	);	break;	// A4.
				case TYPE_FS526_AD_PunchAdjZFoldDepth_A4SEF:			setPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_A4SEF,				ss_BakFinisherZPunchHeightA4R	);	break;	// A4R.
				case TYPE_FS526_AD_PunchAdjZFoldDepth_B5LEF:			setPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_B5LEF,				ss_BakFinisherZPunchHeightB5	);	break;	// B5.
				case TYPE_FS526_AD_PunchAdjZFoldDepth_B5SEF:			setPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_B5SEF,				ss_BakFinisherZPunchHeightB5R	);	break;	// B5R.
				case TYPE_FS526_AD_PunchAdjZFoldDepth_A5LEF:			setPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_A5LEF,				ss_BakFinisherZPunchHeightA5	);	break;	// A5.
				case TYPE_FS526_AD_PunchAdjZFoldDepth_A5SEF:			setPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_A5SEF,				ss_BakFinisherZPunchHeightA5R	);	break;	// A5R.
				case TYPE_FS526_AD_PunchAdjZFoldDepth_11x17SEF:			setPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_11x17SEF,			ss_BakFinisherZPunchHeight11x17	);	break;	// 11x17.
				case TYPE_FS526_AD_PunchAdjZFoldDepth_85x14SEF:			setPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_85x14SEF,			ss_BakFinisherZPunchHeight8_5x14	);	break;	// 8.5x14.
				case TYPE_FS526_AD_PunchAdjZFoldDepth_85x11LEF:			setPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_85x11LEF,			ss_BakFinisherZPunchHeight8_5x11	);	break;	// 8.5x11.
				case TYPE_FS526_AD_PunchAdjZFoldDepth_85x11SEF:			setPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_85x11SEF,			ss_BakFinisherZPunchHeight8_5x11R	);	break;	// 8.5x11R.
				case TYPE_FS526_AD_PunchAdjZFoldDepth_55x85LEF:			setPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_55x85LEF,			ss_BakFinisherZPunchHeight5_5x8_5	);	break;	// 5.5x8.5.
				case TYPE_FS526_AD_PunchAdjZFoldDepth_55x85SEF:			setPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_55x85SEF,			ss_BakFinisherZPunchHeight5_5x8_5R	);	break;	// 5.5x8.5R.
				case TYPE_FS526_AD_PunchAdjZFoldDepth_F4_8125x1325SEF:	setPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_F4_8125x1325SEF,	ss_BakFinisherZPunchHeight8_125x13_25R	);	break;	// 8.125x13.25R.
				case TYPE_FS526_AD_PunchAdjZFoldDepth_F4_8x13SEF:		setPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_F4_8x13SEF,		ss_BakFinisherZPunchHeight8x13R	);	break;	// 8x13R.
				case TYPE_FS526_AD_PunchAdjZFoldDepth_F4_825x13SEF:		setPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_F4_825x13SEF,		ss_BakFinisherZPunchHeight8_25x13R	);	break;	// 8.25x13R.
				case TYPE_FS526_AD_PunchAdjZFoldDepth_F4_85x13SEF:		setPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_F4_85x13SEF,		ss_BakFinisherZPunchHeight8_5x13R	);	break;	// 8.5x13R.
				case TYPE_FS526_AD_PunchAdjZFoldDepth_F4_85x135SEF:		setPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_F4_85x135SEF,		ss_BakFinisherZPunchHeight8_5x13_5R	);	break;	// 8.5x13.5R.
				case TYPE_FS526_AD_PunchAdjZFoldDepth_220x330SEF:		setPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_220x330SEF,		ss_BakFinisherZPunchHeight220x330R	);	break;	// 220x330.
				case TYPE_FS526_AD_PunchAdjZFoldDepth_8KSEF:			setPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_8KSEF,				ss_BakFinisherZPunchHeight8K	);	break;	// 8K.
				case TYPE_FS526_AD_PunchAdjZFoldDepth_16KLEF:			setPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_16KLEF,			ss_BakFinisherZPunchHeight16K	);	break;	// 16K.
				case TYPE_FS526_AD_PunchAdjZFoldDepth_16KSEF:			setPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_16KSEF,			ss_BakFinisherZPunchHeight16KR	);	break;	// 16KR.
				default:												LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );									break;
			}
			break;
		default: PServiceFinisherAdjCom::procButtonOn( option ); break;
	}
	setupGamen();

}

