// 概要		:フィニッシャー調整／FS-FN調整／パンチ(Z折り)縦位置調整(50C00200)・画面遷移.
//================================================================================================
void PServiceFinisherZPunchHeightPositionAdjCom::procGoToPage( uchar option )
{
	// 調整値確定.
	fixPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_All	);	// 全体.
	fixPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_A3SEF	);	// A3.
	fixPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_B4SEF	);	// B4.
	fixPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_A4LEF	);	// A4.
	fixPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_A4SEF	);	// A4R.
	fixPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_B5LEF	);	// B5.
	fixPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_B5SEF	);	// B5R.
	fixPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_A5LEF	);	// A5.
	fixPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_A5SEF	);	// A5R.
	fixPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_11x17SEF	);	// 11x17.
	fixPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_85x14SEF	);	// 8.5x14.
	fixPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_85x11LEF	);	// 8.5x11.
	fixPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_85x11SEF	);	// 8.5x11R.
	fixPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_55x85LEF	);	// 5.5x8.5.
	fixPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_55x85SEF	);	// 5.5x8.5R.
	fixPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_F4_8125x1325SEF	);	// 8.125x13.25R.
	fixPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_F4_8x13SEF	);	// 8x13R.
	fixPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_F4_825x13SEF	);	// 8.25x13R.
	fixPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_F4_85x13SEF	);	// 8.5x13R.
	fixPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_F4_85x135SEF	);	// 8.5x13.5R.
	fixPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_220x330SEF	);	// 220x330.
	fixPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_8KSEF	);	// 8K.
	fixPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_16KLEF	);	// 16K.
	fixPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_16KSEF	);	// 16KR.

	// 画面遷移.
	switch( option ) {
		case 1:
			bl_isRequestInitialize = True;	// 初期化必要.
			nextGamen = &gp_ServiceFinisherZPunchHeightPositionAdj;
			break;
		case 2:
			bl_isRequestInitialize = True;	// 初期化必要.
			nextGamen = &gp_ServiceFinisherZPunchHeightPositionAdjP2;
			break;
		case 99 :			// テストコピーボタン押下.
			gp_ServiceTestCopy.setRetGamen( this );		// 戻り先画面.
			nextGamen = &gp_ServiceTestCopy;	// サービス・テストコピー.
			break;
		default:		break;
	}
}

