//================================================================================================
// 概要 : フィニッシャー調整／FS-FN調整／パンチ(Z折り)縦位置調整(50C00200) : 表示画面のセットアップ.
//================================================================================================
void PServiceFinisherZPunchHeightPositionAdj::setupGamen( short option )
{
	short ss_LocalData = 0;							// ローカルデータ.
	// 親クラスの呼出し.
	PServiceFinisherZPunchHeightPositionAdjCom::setupGamen( option );
	// 各値を表示
	Bak_Svcs93303NowValue00Do = ( float )getPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_All	) / 10.0f;	// 全体.
	Bak_Svcs93303NowValue01Do = ( float )getPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_A3SEF	) / 10.0f;	// A3.
	Bak_Svcs93303NowValue02Do = ( float )getPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_B4SEF	) / 10.0f;	// B4.
	Bak_Svcs93303NowValue03Do = ( float )getPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_A4LEF	) / 10.0f;	// A4.
	Bak_Svcs93303NowValue04Do = ( float )getPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_A4SEF	) / 10.0f;	// A4R.
	Bak_Svcs93303NowValue05Do = ( float )getPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_B5LEF	) / 10.0f;	// B5.
	Bak_Svcs93303NowValue06Do = ( float )getPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_B5SEF	) / 10.0f;	// B5R.
	Bak_Svcs93303NowValue07Do = ( float )getPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_A5LEF	) / 10.0f;	// A5.
	Bak_Svcs93303NowValue08Do = ( float )getPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_A5SEF	) / 10.0f;	// A5R.
	Bak_Svcs93303NowValue09Do = ( float )getPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_11x17SEF	) / 10.0f;	// 11x17.
// comment 2015/03/05 HCLT_SunilNP [HeliosL][CQ509894] adjusting the positions.
// Comment 2017/11/29 【HCLT-Vishal】【Eagle】【制御構成変更_No.4】 Removing old function version check and else portion.
	Bak_SvcsAdjustValueArea1Do.changeGraphic( PB_SvcsAwNewB );		//new B
	Bak_SvcsAdjustRangeArea1.changeGraphic( PB_SvcsAwNewW );
	Bak_SvcsAdjustValueArea1Do.changePosition( 482, 232 );
	Bak_SvcsAdjustRangeArea1.changePosition( 492, 280 );
	Inp_SvcsFNSPunchloopAdjValueDo.changePosition( 517, 244 );
	Txt_SvcsFNSAdjUnit_mmDo.changePosition( 562, 244 );
	Txt_FExtentM5P5TM_SubDo.changePosition( 504, 296 );
	Txt_SvcsFNSAdjStep01Do.changePosition( 512, 312 );
	Key_SvcsSetPlus1.changePosition( 558, 348 );
	Key_SvcsSetMinus1.changePosition( 482, 348 );
	// 調整値取得
	switch( getIndiSelected() ) {
		case TYPE_FS526_AD_PunchAdjZFoldDepth_All:				ss_LocalData = getPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_All	); break;	// 全体.
		case TYPE_FS526_AD_PunchAdjZFoldDepth_A3SEF:			ss_LocalData = getPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_A3SEF	); break;	// A3.
		case TYPE_FS526_AD_PunchAdjZFoldDepth_B4SEF:			ss_LocalData = getPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_B4SEF	); break;	// B4.
		case TYPE_FS526_AD_PunchAdjZFoldDepth_A4LEF:			ss_LocalData = getPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_A4LEF	); break;	// A4.
		case TYPE_FS526_AD_PunchAdjZFoldDepth_A4SEF:			ss_LocalData = getPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_A4SEF	); break;	// A4R.
		case TYPE_FS526_AD_PunchAdjZFoldDepth_B5LEF:			ss_LocalData = getPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_B5LEF	); break;	// B5.
		case TYPE_FS526_AD_PunchAdjZFoldDepth_B5SEF:			ss_LocalData = getPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_B5SEF	); break;	// B5R.
		case TYPE_FS526_AD_PunchAdjZFoldDepth_A5LEF:			ss_LocalData = getPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_A5LEF	); break;	// A5.
		case TYPE_FS526_AD_PunchAdjZFoldDepth_A5SEF:			ss_LocalData = getPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_A5SEF	); break;	// A5R.
		case TYPE_FS526_AD_PunchAdjZFoldDepth_11x17SEF:			ss_LocalData = getPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_11x17SEF	); break;	// 11x17.
		default: LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); break;
	}
	Bak_SvcsAdjustValueArea1Do = ss_LocalData / 10.0f;
	// キーを選択表示.
	Rbt_ServiceFinisherPunchHeightPosition.select( ss_select );
	// ページキー選択表示.
	Rbt_ServiceMoveGamen2.select( ss_PageSelect );
	if( False == PLBC_FuncVersionCheck::isOK_MiZe_Type2() ) {
		Key_ServiceTestCopy.showEnable( False );			// テストコピーボタン非表示.
	}
}

