	Bak_Svcs93303NowValue11Do = ( float )getPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_85x11LEF	) / 10.0f;	// 8.5x11.
	Bak_Svcs93303NowValue12Do = ( float )getPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_85x11SEF	) / 10.0f;	// 8.5x11R.
	Bak_Svcs93303NowValue13Do = ( float )getPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_55x85LEF	) / 10.0f;	// 5.5x8.5.
	Bak_Svcs93303NowValue14Do = ( float )getPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_55x85SEF	) / 10.0f;	// 5.5x8.5R.
	Bak_Svcs93303NowValue16Do = ( float )getPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_8KSEF	) / 10.0f;	// 8K.
	Bak_Svcs93303NowValue17Do = ( float )getPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_16KLEF	) / 10.0f;	// 16K.
	Bak_Svcs93303NowValue18Do = ( float )getPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_16KSEF	) / 10.0f;	// 16KR.

	// 設定されているFLSの種類の判定
	switch( PnlComGetMachineSetting()->getFLSType() ) {
		case TYPE_FLSType8125x1325:
			Bak_Svcs93303NowValue15Do = ( float )getPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_F4_8125x1325SEF ) / 10.0f;
			Key_Svcs93303PaperKey15Do.changeText( s_88x13QT );
			break;
		case TYPE_FLSType8x13:
			Bak_Svcs93303NowValue15Do = ( float )getPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_F4_8x13SEF ) / 10.0f;
			Key_Svcs93303PaperKey15Do.changeText( s_8x13T );
			break;
		case TYPE_FLSType825x13:
			Bak_Svcs93303NowValue15Do = ( float )getPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_F4_825x13SEF ) / 10.0f;
			Key_Svcs93303PaperKey15Do.changeText( s_8Qx13T );
			break;
		case TYPE_FLSType85x13:
			Bak_Svcs93303NowValue15Do = ( float )getPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_F4_85x13SEF	) / 10.0f;
			Key_Svcs93303PaperKey15Do.changeText( s_8Hx13T );
			break;
		case TYPE_FLSType85x135:
			Bak_Svcs93303NowValue15Do = ( float )getPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_F4_85x135SEF	) / 10.0f;
			Key_Svcs93303PaperKey15Do.changeText( s_EXP8Hx13HT );	// No321103対応.
			break;
		case TYPE_FLSType220x330:
			Bak_Svcs93303NowValue15Do = ( float )getPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_220x330SEF	) / 10.0f;
			Key_Svcs93303PaperKey15Do.changeText( s_220x330T );
			break;
		default: LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );				break;
	}


	// 調整値取得
	switch( getIndiSelected() ) {
		case TYPE_FS526_AD_PunchAdjZFoldDepth_85x14SEF:			ss_LocalData = getPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_85x14SEF	); break;	// 8.5x14.
		case TYPE_FS526_AD_PunchAdjZFoldDepth_85x11LEF:			ss_LocalData = getPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_85x11LEF	); break;	// 8.5x11.
		case TYPE_FS526_AD_PunchAdjZFoldDepth_85x11SEF:			ss_LocalData = getPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_85x11SEF	); break;	// 8.5x11R.
		case TYPE_FS526_AD_PunchAdjZFoldDepth_55x85LEF:			ss_LocalData = getPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_55x85LEF	); break;	// 5.5x8.5.
		case TYPE_FS526_AD_PunchAdjZFoldDepth_55x85SEF:			ss_LocalData = getPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_55x85SEF	); break;	// 5.5x8.5R.
		case TYPE_FS526_AD_PunchAdjZFoldDepth_F4_8125x1325SEF:	ss_LocalData = getPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_F4_8125x1325SEF	); break;	// 8.125x13.25R.
		case TYPE_FS526_AD_PunchAdjZFoldDepth_F4_8x13SEF:		ss_LocalData = getPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_F4_8x13SEF	); break;	// 8x13R.
		case TYPE_FS526_AD_PunchAdjZFoldDepth_F4_825x13SEF:		ss_LocalData = getPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_F4_825x13SEF	); break;	// 8.25x13R.
		case TYPE_FS526_AD_PunchAdjZFoldDepth_F4_85x13SEF:		ss_LocalData = getPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_F4_85x13SEF	); break;	// 8.5x13R.
		case TYPE_FS526_AD_PunchAdjZFoldDepth_F4_85x135SEF:		ss_LocalData = getPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_F4_85x135SEF	); break;	// 8.5x13.5R.
		case TYPE_FS526_AD_PunchAdjZFoldDepth_220x330SEF:		ss_LocalData = getPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_220x330SEF	); break;	// 220x330.
		case TYPE_FS526_AD_PunchAdjZFoldDepth_8KSEF:			ss_LocalData = getPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_8KSEF	); break;	// 8K.
		case TYPE_FS526_AD_PunchAdjZFoldDepth_16KLEF:			ss_LocalData = getPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_16KLEF	); break;	// 16K.
		case TYPE_FS526_AD_PunchAdjZFoldDepth_16KSEF:			ss_LocalData = getPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_16KSEF	); break;	// 16KR.
		default: LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); break;
	}
	Bak_SvcsAdjustValueArea1Do = ss_LocalData / 10.0f;
	// キーを選択表示.
