void PServiceFinisherZPunchHeightPositionAdjP2::procButtonOn( uchar option )
{
	switch( option ) {
		case BTNID_KEY_SERV_ZPUNCH_HEIGHT_85x14:
			setPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_85x14SEF );
			ss_select = 0;
			break;
		case BTNID_KEY_SERV_ZPUNCH_HEIGHT_85x11:
			setPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_85x11LEF );
			ss_select = 1;
			break;
		case BTNID_KEY_SERV_ZPUNCH_HEIGHT_85x11R:
			setPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_85x11SEF );
			ss_select = 2;
			break;
		case BTNID_KEY_SERV_ZPUNCH_HEIGHT_55x85:
			setPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_55x85LEF );
			ss_select = 3;
			break;
		case BTNID_KEY_SERV_ZPUNCH_HEIGHT_55x85R:
			setPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_55x85SEF );
			ss_select = 4;
			break;
		case BTNID_KEY_SERV_ZPUNCH_HEIGHT_FOOLS:
			// 設定されているFLSの種類の判定
			switch( PnlComGetMachineSetting()->getFLSType() ) {
				case TYPE_FLSType8125x1325:
					setPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_F4_8125x1325SEF );
					break;
				case TYPE_FLSType8x13:
					setPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_F4_8x13SEF );
					break;
				case TYPE_FLSType825x13:
					setPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_F4_825x13SEF );
					break;
				case TYPE_FLSType85x13:
					setPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_F4_85x13SEF );
					break;
				case TYPE_FLSType85x135:
					setPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_F4_85x135SEF );
					break;
				case TYPE_FLSType220x330:
					setPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_220x330SEF );
					break;
				default: LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
					break;
			}
			ss_select = 5;
			break;
		case BTNID_KEY_SERV_ZPUNCH_HEIGHT_8K:
			setPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_8KSEF );
			ss_select = 6;
			break;
		case BTNID_KEY_SERV_ZPUNCH_HEIGHT_16K:
			setPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_16KLEF );
			ss_select = 7;
			break;
		case BTNID_KEY_SERV_ZPUNCH_HEIGHT_16KR:
			setPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldDepth_16KSEF );
			ss_select = 8;
			break;
		default: PServiceFinisherZPunchHeightPositionAdjCom::procButtonOn( option );
			break;
	}
	setupGamen();
}

