//================================================================================================
// 概要 : フィニッシャー調整／FS-FN調整／パンチ(Z折り)横位置調整(50C00210) : ボタン（押された）.
//================================================================================================
void PServiceFinisherZPunchWidthPositionAdj::procButtonOn( uchar option )
{
	switch( option ) {
		case 100:	addIndi();	break;	// +キー.
		case 101:	subIndi();	break;	// -キー.
		case 60:	// 元に戻すキー.
			switch( getIndiSelected() ) {
				case TYPE_FS526_AD_PunchAdjZFoldCenter_All:			setPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldCenter_All, ss_BakFinisherZPunchWidthALL );		break;	// 現在値.
			}
			break;
		default: PServiceFinisherAdjCom::procButtonOn( option ); break;
	}
	setupGamen();
}
