// 概要 : フィニッシャー調整／FS-FN調整／パンチ(Z折り)横位置調整(50C00210) : 画面遷移キー
//================================================================================================
void PServiceFinisherZPunchWidthPositionAdj::procGoToPage( uchar option )
{
	switch( option )
	{
		case 99 :			// テストコピーボタン押下.
			// 調整値確定.
			fixPrinterIndi( TYPE_FS526_AD_PunchAdjZFoldCenter_All	);	// 現在値.
			gp_ServiceTestCopy.setRetGamen( this );		// 戻り先画面.
			nextGamen = &gp_ServiceTestCopy;	// サービス・テストコピー.
			break;
		default:
			// 親クラスの呼出し.
			PServiceFinisherAdjCom::procGoToPage( option );
			break;
	}
}
