////////////////////////////////////////////////////////////////////////.
// 概要		: システム設定／データインストール(50C00150_MiB) : コンストラクタ.
// 変更履歴	:.
////////////////////////////////////////////////////////////////////////.
PServiceDataInstall_MiB::PServiceDataInstall_MiB( PDisplayParts** partsTable, short partsNumber, Bool isNoWarningGamen )
	: PServiceToSystemMenu2P2Com( partsTable, partsNumber, isNoWarningGamen )
{
	// インストール／アンインストール実行状況.
	static PNLS_ServiceDataInstall_ExecuteInfo st_ExecuteInfo[] = {
		{ 0, 0, InstallDeleteExecution_None, InstallDeleteExecution_None },
		{ 0, 0, InstallDeleteExecution_None, InstallDeleteExecution_None },
		{ 0, 0, InstallDeleteExecution_None, InstallDeleteExecution_None },
		{ 0, 0, InstallDeleteExecution_None, InstallDeleteExecution_None },
		{ 0, 0, InstallDeleteExecution_None, InstallDeleteExecution_None },
		{ 0, 0, InstallDeleteExecution_None, InstallDeleteExecution_None },
	};
	// インストールパラメータ.
	static PNLS_ServiceDataInstall_InstallParam st_InstallParam[] = {
		// バージョン表示・設定値.		インストールファイル名.			MFPインストール先.  アンインストールフォルダ.	 USBCheck.
		{ TYPE_RomVoice,	( char* )PNL_VoiceInstallFileName,		"/",	PNLE_VoiceInstallDirctory,		True		},	// 音声.
		{ TYPE_RomAnimation,	( char* )PNL_AnimeInstallFileName,		"/",	PNLE_AnimeInstallDirctory,		True		},	// 動画.
		{ TYPE_RomSearchablePDFDictionaryData,	( char* )PNL_DictInstallFileName,	"/",	PNLE_DictInstallDirctory,		True		},	// OCR辞書.
		{ TYPE_RomPDFAFont,	( char* )PNL_PDFAFontInstallFileName,		"/",	PNLE_PDFAFontInstallDirctory,	True		},	// PDFAフォント.
		{ TYPE_RomPanelSoundData,	( char* )PNL_PanelSoundDataFileName,		NULL,	NULL,							True		},	// パネル音データ.
		{ 0,							NULL,									NULL,	NULL,							False		},	// OEMドライバ.
	};
	// インストールデータ情報.
	static PNLS_ServiceDataInstall_InstallInfo st_InstallInfo[] = {
		{ PNLE_ServiceDataInstall_DataKindAudio,		True, False, False, &st_ExecuteInfo[0], &st_InstallParam[0], &Grp_ServiceDataInstall_Line[0] },
		{ PNLE_ServiceDataInstall_DataKindAnime,		True, False, False, &st_ExecuteInfo[1], &st_InstallParam[1], &Grp_ServiceDataInstall_Line[1] },
		{ PNLE_ServiceDataInstall_DataKindOCRDict,		True, False, False, &st_ExecuteInfo[2], &st_InstallParam[2], &Grp_ServiceDataInstall_Line[2] },
		{ PNLE_ServiceDataInstall_DataKindPDFA,			True, False, False, &st_ExecuteInfo[3], &st_InstallParam[3], &Grp_ServiceDataInstall_Line[3] },
		{ PNLE_ServiceDataInstall_DataKindPanelSound,	True, False, False, &st_ExecuteInfo[4], &st_InstallParam[4], &Grp_ServiceDataInstall_Line[4] },
		{ PNLE_ServiceDataInstall_DataKindOEMDriver,	True, False, False, &st_ExecuteInfo[5], &st_InstallParam[5], &Grp_ServiceDataInstall_Line[5] },
	};

	// メンバーの初期化.
	m_pst_InstallInfo = st_InstallInfo;
	m_ss_InstallInfoCount = ( short )( sizeof( st_InstallInfo )/sizeof( PNLS_ServiceDataInstall_InstallInfo ) );
	m_bl_SelectedEntryKey	= False;
	m_bl_SelectedDeleteKey	= False;
	m_bl_SelectedDecideKey	= False;
	m_uc_InstallingAnime	= 0;
	m_bl_InstallResult		= False;
	m_bl_DeleteResult		= False;
	m_e_ErrorCode			= 0;
}

////////////////////////////////////////////////////////////////////////.
// 概要		: システム設定／データインストール(50C00150_MiB) : 初期化処理.
// 戻り値	: なし.
////////////////////////////////////////////////////////////////////////.
void PServiceDataInstall_MiB::initialize()
{
	// インストール情報を初期化する.
	PNLS_ServiceDataInstall_ExecuteInfo st_initExecuteInfo =
	{  0, 0, InstallDeleteExecution_None, InstallDeleteExecution_None, False };

	for( short ss_index = 0; ss_index < m_ss_InstallInfoCount; ss_index++ ) {
		// サポート.
		if( PNLE_ServiceDataInstall_DataKindPanelSound == m_pst_InstallInfo[ss_index].e_DataKind ) {
			// パネル音源データの場合は、音楽IC搭載チェック.
			if( 0 != ( TYPD_PanelOptionSoundIC & ppc_SystemInfo->getSlidelessPanelOptionInfo() ) ) {
				m_pst_InstallInfo[ss_index].bl_Support = True;
			} else {
				m_pst_InstallInfo[ss_index].bl_Support = False;
			}
		} else {
			m_pst_InstallInfo[ss_index].bl_Support = True;
		}
		// データの有無.
		m_pst_InstallInfo[ss_index].bl_FileExist = False;
		// 選択解除.
		m_pst_InstallInfo[ss_index].bl_Selected = False;
		// 実行状態の初期化.
		*( m_pst_InstallInfo[ss_index].pst_ExecuteInfo ) = st_initExecuteInfo;
	}

	// 状態フラグを初期化する.
	m_bl_SelectedEntryKey	= False;
	m_bl_SelectedDeleteKey	= False;
	m_bl_SelectedDecideKey	= False;
	m_uc_InstallingAnime	= 0;
	m_bl_InstallResult		= False;
	m_bl_DeleteResult		= False;
}

////////////////////////////////////////////////////////////////////////.
// 概要		: システム設定／データインストール(50C00150_MiB) : USBメモリチェック初期化.
// 戻り値	: なし.
// 変更履歴	:.
////////////////////////////////////////////////////////////////////////.
void PServiceDataInstall_MiB::startUsbCheck()
{
	// USBチェック初期化.
	static PServiceUSBFileCheck::USBCheckFile st_usbCheckFiles[PNLE_ServiceDataInstall_DataKindCount];

	short ss_count = 0;
	for( short ss_index = 0; ss_index < m_ss_InstallInfoCount; ss_index++ ) {
		// サポートかつUSBチェック対象.
		if( ( True == m_pst_InstallInfo[ss_index].bl_Support ) && ( True == m_pst_InstallInfo[ss_index].pst_InstallParam->bl_UsbCheck ) ) {
			if( NULL != m_pst_InstallInfo[ss_index].pst_InstallParam->pc_SrcInstallFileName ) {
				st_usbCheckFiles[ss_count].ssFileID = ( short )m_pst_InstallInfo[ss_index].e_DataKind;
				st_usbCheckFiles[ss_count].pcCheckFile = m_pst_InstallInfo[ss_index].pst_InstallParam->pc_SrcInstallFileName;
				st_usbCheckFiles[ss_count].bFileExistence = False;
				st_usbCheckFiles[ss_count].bCheckEnableFlg = False;
				ss_count++;
			}
		}
	}

	// チェックファイルの設定.
	gp_ServiceUSBFileCheck.setCheckFiles( &st_usbCheckFiles[0], ss_count );
	gp_ServiceUSBFileCheck.setUSBStatusText( NULL );			// パーツ表示制御なし.
	gp_ServiceUSBFileCheck.setShowEnableParts( NULL, 0 );		// 表示なし.
}
////////////////////////////////////////////////////////////////////////.
// 概要		: システム設定／データインストール(50C00150_MiB) : 画面開始処理.
// 戻り値	: なし.
// 変更履歴	:.
////////////////////////////////////////////////////////////////////////.
void PServiceDataInstall_MiB::startGamen()
{
	// 親クラスのメソッドコール.
	PServiceToSystemMenu2Com::startGamen( );

	// 初期化処理.
	initialize();

	// USBチェック登録.
	startUsbCheck();

	// 非サポートのインストールデータ欄を非表示しておく.
	for( short ss_index = 0; ss_index < m_ss_InstallInfoCount; ss_index++ ) {
		m_pst_InstallInfo[ss_index].pc_GroupParts->showEnable( m_pst_InstallInfo[ss_index].bl_Support );
	}
}
////////////////////////////////////////////////////////////////////////.
// 概要		: システム設定／データインストール(50C00150_MiB) : 画面セットアップ.
// 戻り値	: なし.
// 変更履歴	:.
////////////////////////////////////////////////////////////////////////.
void PServiceDataInstall_MiB::setupGamen( short option )
{
	short ss_index = 0;

	// USBの状態チェック更新.
	ServiceUSBInfo e_usbInfo = gp_ServiceUSBFileCheck.checkOnly();

	// インストール中にUSB抜けた場合は、失敗とする.
	if( ( True == isInstalling() ) && ( ServiceUSBInfo_Uninsertion == e_usbInfo ) ) {
		for( ss_index = 0; ss_index < m_ss_InstallInfoCount; ss_index++ ) {
			// 実行中 → NGに変更する.
			if( InstallDeleteExecution_Executing == m_pst_InstallInfo[ss_index].pst_ExecuteInfo->e_InstallStatus ) {
				m_pst_InstallInfo[ss_index].pst_ExecuteInfo->e_InstallStatus = InstallDeleteExecution_NG;
			}
		}
	}

	// 各データ種別の状態更新.
	for( ss_index = 0; ss_index < m_ss_InstallInfoCount; ss_index++ ) {
		setupOneInstallData( &m_pst_InstallInfo[ss_index] );
	}

	// 登録キーエリアの更新.
	setupEntryArea();

	// 削除キーエリアの更新.
	setupDeleteArea();

	Txt_ServiceDataInstallPowerOffOn.showEnable( isNeedPowerOffOn() );

	// 表示部品のセットアップ.
	PServiceToSystemMenu2Com::setupGamen( option );

	// スタートキーの制御.
	Bool bl_LEDControlFlg = False;
	if( False == isExecuting() && False == isNeedPowerOffOn() ) {			// インストール・削除中でない.かつ、電源OFF/ONは不要.
		if( ( True == m_bl_SelectedEntryKey ) && ( ServiceUSBInfo_CheckComplete == e_usbInfo ) ) {
			for( ss_index = 0; ss_index < m_ss_InstallInfoCount; ss_index++ ) {
				if( !m_pst_InstallInfo[ss_index].bl_Support ) {
					continue;	// 非サポート.
				}
				// 選択かつ、ファイルが存在する場合、
				if( m_pst_InstallInfo[ss_index].bl_Selected && m_pst_InstallInfo[ss_index].bl_FileExist ) {
					bl_LEDControlFlg = True;
					break;
				}
			}
		}
	}
	printLEDControl( bl_LEDControlFlg );
}

////////////////////////////////////////////////////////////////////////.
// 概要		: システム設定／データインストール(50C00150_MiB) : 画面セットアップ(1データ種別).
// 戻り値	: なし.
// 変更履歴	:.
////////////////////////////////////////////////////////////////////////.
void PServiceDataInstall_MiB::setupOneInstallData( PNLS_ServiceDataInstall_InstallInfo* pst_InstallInfo )
{
	// サポートされていない場合は、終了.
	if( ! pst_InstallInfo->bl_Support ) {
		return;
	}

	// ファイルの存在チェック.
	if( pst_InstallInfo->pst_InstallParam->bl_UsbCheck ) {
		// USBチェック.
		pst_InstallInfo->bl_FileExist = gp_ServiceUSBFileCheck.isFile( ( short )pst_InstallInfo->e_DataKind );
	} else {
		if( PNLE_ServiceDataInstall_DataKindOEMDriver == pst_InstallInfo->e_DataKind ) { // OEMドライバ.
			pst_InstallInfo->bl_FileExist = ( FALSE == isExistOemData( NULL ) ) ? False : True;
		} else {
			pst_InstallInfo->bl_FileExist = False;
		}
	}

	Bool bl_ShowInstalling	= False;
	Bool bl_ShowSize		= False;
	Bool bl_ShowVersion		= True;

	TEXT_ID us_StatusSymbolID = s_Space1;
	char romVersion[40 + 1];
	memset( romVersion, 0, sizeof( romVersion ) );

	// データ種別キーのセットアップ.
	TEXT_ID us_DataKindId = s_Space1;
	switch( pst_InstallInfo->e_DataKind ) {
		case PNLE_ServiceDataInstall_DataKindAudio:		us_DataKindId = s_ITMServiceAudioData;	break;				// 音声.
		case PNLE_ServiceDataInstall_DataKindAnime:		us_DataKindId = s_ITMServiceAnimeData;	break;				// 動画.
		case PNLE_ServiceDataInstall_DataKindOCRDict:	us_DataKindId = s_ITMOCRDictionary;		break;				// OCR辞書.
		case PNLE_ServiceDataInstall_DataKindPDFA:		us_DataKindId = s_KEYServicePDFAFont;	break;				// PDFAフォント.
		case PNLE_ServiceDataInstall_DataKindPanelSound:us_DataKindId = s_KEYServicePanelSoundSourceData;	break;	// パネル音データ.
		case PNLE_ServiceDataInstall_DataKindOEMDriver:	us_DataKindId = s_KEYOEM;				break;				// OEMドライバ.
		default: break;
	}

	// キー選択時.
	if( pst_InstallInfo->bl_Selected ) {
		// ファイルなし.
		if( !pst_InstallInfo->bl_FileExist ) {
			us_StatusSymbolID = s_ITMServiceFileNG;		// ファイルNG.
		}

		// インストール状態.
		InstallDeleteExecutionStatus e_installStatus = pst_InstallInfo->pst_ExecuteInfo->e_InstallStatus;

		if( InstallDeleteExecution_Executing == e_installStatus ) {  // インストール中.
			us_StatusSymbolID = s_ITMServiceRunning;	// 動作中.
			// サイズ表示.
			bl_ShowSize = True;
			switch( pst_InstallInfo->e_DataKind ) {
				case PNLE_ServiceDataInstall_DataKindAudio:		// 音声.
				case PNLE_ServiceDataInstall_DataKindAnime:		// 動画.
					pst_InstallInfo->pst_ExecuteInfo->ul_NowSize = PnlComGetMachineSetting()->getSavedVoiceAnimationFileSize();
					break;
				case PNLE_ServiceDataInstall_DataKindOCRDict:	//OCR辞書.
					pst_InstallInfo->pst_ExecuteInfo->ul_NowSize = PnlComGetSearchablePDFSetting()->getSavedHddFileSize();
					break;
				case PNLE_ServiceDataInstall_DataKindPDFA:		// PDFAフォント.
					pst_InstallInfo->pst_ExecuteInfo->ul_NowSize = PnlComGetMachineSetting()->getSavedHDDfilesize();
					break;
				case PNLE_ServiceDataInstall_DataKindPanelSound:// パネル音データ.
				case PNLE_ServiceDataInstall_DataKindOEMDriver:	// OEMドライバ.
				default:
					pst_InstallInfo->pst_ExecuteInfo->ul_NowSize = 0;	// サイズなし
					bl_ShowSize = False;								// 非表示.
					break;
			}
			bl_ShowInstalling = True;	// インストール中.
			bl_ShowVersion = False;		// バージョン非表示.
		} else if( InstallDeleteExecution_OK == e_installStatus ) {	// インストールOK.
			us_StatusSymbolID = s_Ok;		// OK.
		} else if( InstallDeleteExecution_NG == e_installStatus ) {	// インストールNG.
			us_StatusSymbolID = s_NG;		// NG.
		}
	}

	// バージョン情報の取得.
	if( bl_ShowVersion ) {
		switch( pst_InstallInfo->e_DataKind ) {
			case PNLE_ServiceDataInstall_DataKindOEMDriver:	// OEMドライバ.
				bl_ShowVersion = False;	// バージョン表示なし.
				break;
			default:
				// バージョン取得.
				ppc_SystemInfo->getRomVersion( pst_InstallInfo->pst_InstallParam->e_VerRom, romVersion );
				break;
		}
	}

	//
	// パーツに反映.
	//
	PGroupParts* pc_group = pst_InstallInfo->pc_GroupParts;
	POnOffButton*		pKey_DataKind	= dynamic_cast<POnOffButton*>( pc_group->getPartsAddress( PNLE_ServiceDataInstallPartsDataKind ) );	// データ種別(OnOffボタン).
	PSinglePartsText*	pTxt_Status		= dynamic_cast<PSinglePartsText*>( pc_group->getPartsAddress( PNLE_ServiceDataInstallPartsStatus ) );	// インストール状態表示用.
	PSinglePartsText*	pTxt_Installing	= dynamic_cast<PSinglePartsText*>( pc_group->getPartsAddress( PNLE_ServiceDataInstallPartsExecuting ) ); // インストール中であることを示す
	PNumberField*		pNum_NowSize	= dynamic_cast<PNumberField*>( pc_group->getPartsAddress( PNLE_ServiceDataInstallPartsSizeNow ) );	// インストール済みファイル数表示.
	PSinglePartsText*	pTxt_SizePar	= dynamic_cast<PSinglePartsText*>( pc_group->getPartsAddress( PNLE_ServiceDataInstallPartsSizePar ) ); // インストール済みファイル数表示.
	PNumberField*		pNum_TotalSize	= dynamic_cast<PNumberField*>( pc_group->getPartsAddress( PNLE_ServiceDataInstallPartsSizeTotal ) );	// インストール済みファイル数表示.
	PTextField*			pTfd_Version	= dynamic_cast<PTextField*>( pc_group->getPartsAddress( PNLE_ServiceDataInstallPartsVersion ) );		// バージョン表示.

	// パーツ重なりがあるパーツは、先に消去制御を行っておく.
	if( !bl_ShowSize ) {
		if( pNum_NowSize )	{ pNum_NowSize->showEnable( False ); }
		if( pTxt_SizePar )	{ pTxt_SizePar->showEnable( False ); }
		if( pNum_TotalSize ) { pNum_TotalSize->showEnable( False ); }
	}
	if( !bl_ShowVersion )	{
		if( pTfd_Version )	{ pTfd_Version->showEnable( False ); }
	}
	if( !bl_ShowInstalling ) {
		if( pTxt_Installing ) { pTxt_Installing->showEnable( False ); }
	}

	// データ種別キー.
	if( pKey_DataKind ) {
		pKey_DataKind->changeText( us_DataKindId );
		pKey_DataKind->select( pst_InstallInfo->bl_Selected );
	}
	// 状態表示.
	if( pTxt_Status ) {
		pTxt_Status->changeText( us_StatusSymbolID );
	}
	// インストール中表示.
	if( bl_ShowInstalling ) {
		if( pTxt_Installing ) {
			TEXT_ID us_AnimeTextId = ( 0 == m_uc_InstallingAnime )? s_EXPSlash: s_EXPBackslash;
			if( ++m_uc_InstallingAnime > 1 ) { m_uc_InstallingAnime = 0; }	// アニメーション更新.
			pTxt_Installing->changeText( us_AnimeTextId );
			pTxt_Installing->showEnable( True );
		}
	}
	// バージョン表示とサイズ表示は、パーツ重なっている為、消去→表示の順に制御する.
	if( bl_ShowSize ) {		// サイズ表示.
		if( pNum_NowSize ) {
			*pNum_NowSize = ( float )pst_InstallInfo->pst_ExecuteInfo->ul_NowSize;
			pNum_NowSize->showEnable( True );
		}
		if( pTxt_SizePar ) { pTxt_SizePar->showEnable( True ); }
		if( pNum_TotalSize ) {
			*pNum_TotalSize = ( float )pst_InstallInfo->pst_ExecuteInfo->ul_TotalSize;
			pNum_TotalSize->showEnable( True );
		}
	}
	if( bl_ShowVersion ) {	// バージョン表示.
		if( pTfd_Version ) {
			pTfd_Version->changeTextString( ( uchar* )romVersion );
			pTfd_Version->showEnable( True );
		}
	}
}
////////////////////////////////////////////////////////////////////////.
// 概要		: システム設定／データインストール(50C00150_MiB) : 登録キーエリアのセットアップ.
// 戻り値	: なし.
// 変更履歴	:.
////////////////////////////////////////////////////////////////////////.
void PServiceDataInstall_MiB::setupEntryArea()
{
	// 削除中は、更新しない.
	if( isDeleteing() ) {
		return;
	}

	// パーツポインタの取得.
	POnOffButton* pc_EntryKey = dynamic_cast<POnOffButton*>( Grp_ServiceDataInstall_EntryArea.getPartsAddress( PNLE_ServiceDataInstallPartsEntryKey ) );
	PSinglePartsText* pc_USBNgTxt = dynamic_cast<PSinglePartsText*>( Grp_ServiceDataInstall_EntryArea.getPartsAddress( PNLE_ServiceDataInstallPartsUsbStatus ) );

	// USBNGの状態.
	Bool bl_USBNg = ( ServiceUSBInfo_Uninsertion == gp_ServiceUSBFileCheck.getUSBInfo() );

	if( bl_USBNg ) {
		if( pc_EntryKey ) { pc_EntryKey->showEnable( False ); }
		if( pc_USBNgTxt ) { pc_USBNgTxt->showEnable( True ); }
	} else {
		if( pc_USBNgTxt ) { pc_USBNgTxt->showEnable( False ); }
		// ファイルNGの状態である場合は、登録キーを表示しない.
		Bool bl_ShowEntryKey = True;
		for( short ss_index = 0; ss_index < m_ss_InstallInfoCount; ss_index++ ) {
			if( !m_pst_InstallInfo[ss_index].bl_Support ) {
				continue;	// 非サポート.
			}
			// 選択かつ、ファイルが存在しない場合、
			if( m_pst_InstallInfo[ss_index].bl_Selected && !m_pst_InstallInfo[ss_index].bl_FileExist ) {
				bl_ShowEntryKey = False;
				break;
			}
		}
		if( pc_EntryKey ) {
			pc_EntryKey->select( m_bl_SelectedEntryKey );
			pc_EntryKey->showEnable( bl_ShowEntryKey );
		}
	}
}
////////////////////////////////////////////////////////////////////////.
// 概要		: システム設定／データインストール(50C00150_MiB) : 削除キーエリアのセットアップ.
// 戻り値	: なし.
// 変更履歴	:.
////////////////////////////////////////////////////////////////////////.
void PServiceDataInstall_MiB::setupDeleteArea()
{
	// インストール中は、更新しない.
	if( isInstalling() ) {
		return;
	}

	// 削除実行状態.
	InstallDeleteExecutionStatus eDelStatus = getDeleteStatus();

	// インストール済みのデータのチェック
	Bool bl_Installed = False;
	short ss_index = 0;
	for( ss_index = 0; ss_index < m_ss_InstallInfoCount; ss_index++ ) {
		if( !m_pst_InstallInfo[ss_index].bl_Support ) {
			continue;	// 非サポート.
		}
		// 選択かつ、ファイルが存在する場合、
		if( True == isEnableDelete( m_pst_InstallInfo[ss_index].e_DataKind ) ) {
			bl_Installed = True;
			break;
		}
	}

	// 削除キーエリア全体の表示判定.
	if( bl_Installed || ( InstallDeleteExecution_OK == eDelStatus || InstallDeleteExecution_NG == eDelStatus ) ) {
		// インストールデータあり、もしくは、削除完了状態の場合は、表示.
		Grp_ServiceDataInstall_DeleteArea.showEnable( True );
	} else {
		// 上記以外は、非表示.
		Grp_ServiceDataInstall_DeleteArea.showEnable( False );
		// 非表示時は、選択状態を解除.
		m_bl_SelectedDeleteKey = False;
		m_bl_SelectedDecideKey = False;
		return;
	}

	// 削除キーの非表示条件.
	Bool bl_ShowDeleteKey = True;
	for( ss_index = 0; ss_index < m_ss_InstallInfoCount; ss_index++ ) {
		if( !m_pst_InstallInfo[ss_index].bl_Support ) {
			continue;	// 非サポート.
		}
		if( ( PNLE_ServiceDataInstall_DataKindPanelSound == m_pst_InstallInfo[ss_index].e_DataKind )	// パネル音データ.
		    && ( True == m_pst_InstallInfo[ss_index].bl_Selected ) ) {										// 選択時.
			// 削除キー、確定キーの選択を解除.
			m_bl_SelectedDeleteKey = False;
			m_bl_SelectedDecideKey = False;
			// 非表示.
			bl_ShowDeleteKey = False;
			break;
		}
	}

	// パーツポインタの取得.
	POnOffButton* pc_DeleteKey = dynamic_cast<POnOffButton*>( Grp_ServiceDataInstall_DeleteArea.getPartsAddress( PNLE_ServiceDataInstallPartsDeleteKey ) );
	POnOffButton* pc_DecideKey = dynamic_cast<POnOffButton*>( Grp_ServiceDataInstall_DeleteArea.getPartsAddress( PNLE_ServiceDataInstallPartsDecideKey ) );
	PSinglePartsText* pc_StatusTxt = dynamic_cast<PSinglePartsText*>( Grp_ServiceDataInstall_DeleteArea.getPartsAddress( PNLE_ServiceDataInstallPartsDeleteStatus ) );
	PSinglePartsText* pc_DeletingTxt = dynamic_cast<PSinglePartsText*>( Grp_ServiceDataInstall_DeleteArea.getPartsAddress( PNLE_ServiceDataInstallPartsDeleting ) );
	PSinglePartsText* pc_DeleteResult = dynamic_cast<PSinglePartsText*>( Grp_ServiceDataInstall_DeleteArea.getPartsAddress( PNLE_ServiceDataInstallPartsDeleteResult ) );

	// 重なりがあるパーツは、一旦消去する.
	if( pc_StatusTxt ) { pc_StatusTxt->showEnable( False ); }
	if( pc_DeletingTxt ) { pc_DeletingTxt->showEnable( False ); }
	if( pc_DeleteResult ) { pc_DeleteResult->showEnable( False ); }

	if( InstallDeleteExecution_OK == eDelStatus ||
	    InstallDeleteExecution_NG == eDelStatus ) {
		// 削除処理が完了していれば　削除ステータスを表示するパーツの設定.
		TEXT_ID textId = ( InstallDeleteExecution_OK == eDelStatus )? s_Ok: s_NG;
		if( pc_DeleteResult ) {		// OK / NG.
			pc_DeleteResult->changeText( textId );
			pc_DeleteResult->showEnable( True );
		}
	} else {
		// 削除処理を行っていない、若しくは削除処理中は各パーツの表示/非表示設定を行う.
		if( InstallDeleteExecution_Executing == eDelStatus ) {
			if( pc_StatusTxt ) {		// 「実行中」.
				pc_StatusTxt->changeText( s_ITMServiceRunning );
				pc_StatusTxt->showEnable( True );
			}
			if( pc_DeletingTxt ) {	// 「／」「＼」.
				TEXT_ID us_AnimeTextId = ( 0 == m_uc_InstallingAnime )? s_EXPSlash: s_EXPBackslash;
				if( ++m_uc_InstallingAnime > 1 ) { m_uc_InstallingAnime = 0; }	// アニメーション更新.
				pc_DeletingTxt->changeText( us_AnimeTextId );
				pc_DeletingTxt->showEnable( True );
			}
		}
	}

	if( pc_DeleteKey ) {	// 削除キー.
		pc_DeleteKey->select( m_bl_SelectedDeleteKey );
		pc_DeleteKey->showEnable( bl_ShowDeleteKey );
	}
	if( pc_DecideKey ) {	// 確定キー.
		if( m_bl_SelectedDeleteKey ) {	// 削除キー選択時のみ表示.
			pc_DecideKey->select( m_bl_SelectedDecideKey );
			pc_DecideKey->showEnable( True );
		} else {						// 非表示時.
			pc_DecideKey->showEnable( False );
			m_bl_SelectedDecideKey = False;		// 選択解除.
		}
	}
}
////////////////////////////////////////////////////////////////////////.
// 概要		: システム設定／データインストール(50C00150_MiB) : ボタン押下.
// 戻り値	: なし.
////////////////////////////////////////////////////////////////////////.
void PServiceDataInstall_MiB::procButtonOn( uchar uc_option )
{
	Bool bl_OnOffFlg;
	Bool bl_DeleteInit = False;

	if( isExecuting() || isNeedPowerOffOn() ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );		// 拒否音.
		// インストール・削除中はボタン押下不可.
		return;
	}

	switch( uc_option ) {
		case BTNID_KEY_DATAINSTALL_ENTRY:	// 登録キー.
			// トグル切替.
			bl_OnOffFlg = !m_bl_SelectedEntryKey;
			m_bl_SelectedEntryKey = bl_OnOffFlg;
			if( bl_OnOffFlg ) {	// 削除キーを選択解除.
				m_bl_SelectedDeleteKey = False;
			}
			bl_DeleteInit = True;	// 削除ステイタスの初期化.
			break;

		case BTNID_KEY_DATAINSTALL_DELETE:	// 削除キー.
			// トグル切替.
			bl_OnOffFlg = !m_bl_SelectedDeleteKey;
			m_bl_SelectedDeleteKey = bl_OnOffFlg;
			if( bl_OnOffFlg ) {	// 登録キーを選択解除.
				m_bl_SelectedEntryKey= False;
			}
			// 削除キーを操作時は、確定キーの選択解除.
			m_bl_SelectedDecideKey = False;
			break;

		case BTNID_KEY_DATAINSTALL_DECIDE:	// 確定キー.
			// 削除実行できるか判断する.
			if( isDecideEnableSelected() ) {
				bl_OnOffFlg = !m_bl_SelectedDecideKey;
				m_bl_SelectedDecideKey = bl_OnOffFlg;
			} else {
				// 削除できない状態であれば、確定キーは押下不可.
				bl_OnOffFlg = False;
				MCR_setBuzzerType( PCGE_BuzzerType_InputNg );	// 拒否音.
			}
			// 削除実行.
			if( bl_OnOffFlg ) {
				deleteExec();
			}
			break;

		default: // 各データ種類キー.
		{
			uchar uc_index = uc_option - BTNID_KEY_DATAINSTALL_1;
			if( ( uc_index >= m_ss_InstallInfoCount )			// インデックスエラー.
			    || ( !m_pst_InstallInfo[uc_index].bl_Support ) ) { // 非サポート.
				break;
			}
			// トグル切替.
			bl_OnOffFlg = !( m_pst_InstallInfo[uc_index].bl_Selected );
			m_pst_InstallInfo[uc_index].bl_Selected = bl_OnOffFlg;

			bl_DeleteInit = True;	// 削除ステイタスの初期化.
		}
		break;
	}

	// 削除ステイタスの初期化.
	if( bl_DeleteInit ) {
		// 削除の実行ステイタスをクリアする.
		for( short ss_index = 0; ss_index < m_ss_InstallInfoCount; ss_index++ ) {
			m_pst_InstallInfo[ss_index].pst_ExecuteInfo->e_DeleteStatus = InstallDeleteExecution_None;
		}
		m_bl_SelectedDecideKey = False;		// 確定キー選択解除.
	}


	setupGamen();		// 表示部品のセットアップ.
}
////////////////////////////////////////////////////////////////////////.
// 概要		: システム設定／データインストール(50C00150_MiB) : 画面遷移.
// 戻り値	: なし.
// 変更履歴	:.
////////////////////////////////////////////////////////////////////////.
void PServiceDataInstall_MiB::procGoToPage( uchar uc_option )
{
	if( isExecuting() || isNeedPowerOffOn() ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );		// 拒否音.
		// インストール・削除中はボタン押下不可.
		return;
	}
}
////////////////////////////////////////////////////////////////////////.
// 概要		: システム設定／データインストール(50C00150_MiB) : スタートキー押下.
// 戻り値	: なし.
// 変更履歴	:.
////////////////////////////////////////////////////////////////////////.
void PServiceDataInstall_MiB::procStart( uchar uc_option )
{
	if( printStartDisable() ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );		// 拒否音.
		return;
	}

	// インストール開始.
	installExec();

	// 画面再描画.
	setupGamen();
}
