////////////////////////////////////////////////////////////////////////.
// 概要		: システム設定／データインストール(50C00150_MiB) : 定期起床.
// 戻り値	: なし.
// 変更履歴	:.
////////////////////////////////////////////////////////////////////////.
void PServiceDataInstall_MiB::procTimerWakeUp( uchar uc_option )
{
	// インストール中かつ実行遅延待ちの場合.
	const PNLS_ServiceDataInstall_InstallInfo* pst_InstallInfo = getInstallingInfo();
	if( pst_InstallInfo && pst_InstallInfo->pst_ExecuteInfo->bl_ExecuteDelay ) {
		// インストールを実行する.
		startInstall( ( PNLS_ServiceDataInstall_InstallInfo* )pst_InstallInfo );
	}
	PServiceToSystemMenu2Com::procTimerWakeUp( uc_option );
}
////////////////////////////////////////////////////////////////////////.
// 概要		: システム設定／データインストール(50C00150_MiB) : オートリセット要求.
// 戻り値	: なし.
// 変更履歴	:.
////////////////////////////////////////////////////////////////////////.
void PServiceDataInstall_MiB::procAutoResetReq( uchar uc_option )
{
	if( isExecuting() || isNeedPowerOffOn() ) {
		return;
	}
	PServiceToSystemMenu2Com::procAutoResetReq( uc_option );
}
