////////////////////////////////////////////////////////////////////////.
// 概要		: システム設定／データインストール(50C00150_MiB) : インストール実行.
// 戻り値	: なし.
////////////////////////////////////////////////////////////////////////.
void PServiceDataInstall_MiB::installExec()
{
	short ss_index;
	PNLS_ServiceDataInstall_ExecuteInfo st_initExecuteInfo =
	{ 0, 0, InstallDeleteExecution_None, InstallDeleteExecution_None, False };

	// 実行状態の初期設定.
	for( ss_index = 0; ss_index < m_ss_InstallInfoCount; ss_index++ ) {
		*( m_pst_InstallInfo[ss_index].pst_ExecuteInfo ) = st_initExecuteInfo;
	}

	for( ss_index = 0; ss_index < m_ss_InstallInfoCount; ss_index++ ) {
		if( m_pst_InstallInfo[ss_index].bl_Selected ) {
			// データ種別キーが選択状態になっている場合.
			if( isInstalling() ) {
				// インストールしている物が既にある場合は、インストール予約とする.
				m_pst_InstallInfo[ss_index].pst_ExecuteInfo->e_InstallStatus = InstallDeleteExecution_Reserved;
			} else {
				// インストール開始.
				startInstall( &m_pst_InstallInfo[ss_index] );
			}
		}
	}
}

//////////////////////////////////////////////////////////////.
// 概要		: システム設定／データインストール(50C00150_MiB) : インストール開始.
// 戻り値	: なし.
//////////////////////////////////////////////////////////////.
void PServiceDataInstall_MiB::startInstall( PNLS_ServiceDataInstall_InstallInfo* pst_InstallInfo )
{
	// 実行中をセット.
	pst_InstallInfo->pst_ExecuteInfo->e_InstallStatus = InstallDeleteExecution_Executing;

	// 結果をクリアする.
	m_bl_InstallResult		= False;
	m_e_ErrorCode			= 0;

	PNLS_ServiceDataInstall_InstallParam* pst_param = pst_InstallInfo->pst_InstallParam;
	// データ種別ごとに実装.
	switch( pst_InstallInfo->e_DataKind ) {
		case PNLE_ServiceDataInstall_DataKindAudio:			// 音声.
		case PNLE_ServiceDataInstall_DataKindAnime:			// 動画.
			// ファイルサイズ取得.
			pst_InstallInfo->pst_ExecuteInfo->ul_TotalSize = PnlComGetMachineSetting()->getVoiceAnimationFileSize(
			            TYPE_CharSetUTF8, pst_param->pc_SrcInstallFileName );
			// データ保存要求.
			PnlComGetMachineSetting()->saveVoiceAnimationData( TYPE_CharSetUTF8,
			        pst_param->pc_SrcInstallFileName, pst_param->pc_DestInstallPath, ans_installComplete );
			break;
		case PNLE_ServiceDataInstall_DataKindOCRDict:		// OCR辞書.
			// ファイルサイズ取得.
			pst_InstallInfo->pst_ExecuteInfo->ul_TotalSize =
			    PnlComGetSearchablePDFSetting()->getHddFileSize( TYPE_CharSetUTF8, pst_param->pc_SrcInstallFileName );
			// データ保存要求.
			PnlComGetSearchablePDFSetting()->saveHddData( TYPE_CharSetUTF8,
			        pst_param->pc_SrcInstallFileName, pst_param->pc_DestInstallPath, ans_installComplete );
			break;
		case PNLE_ServiceDataInstall_DataKindPDFA:			// PDFAフォント.
			// ファイルサイズ取得.
			pst_InstallInfo->pst_ExecuteInfo->ul_TotalSize =
			    PnlComGetMachineSetting()->getHDDfilesize( TYPE_CharSetUTF8, pst_param->pc_SrcInstallFileName );
			// データ保存要求.
			PnlComGetMachineSetting()->saveHDDdata( TYPE_CharSetUTF8,
			                                        pst_param->pc_SrcInstallFileName, pst_param->pc_DestInstallPath, ans_installComplete );
			break;
		case PNLE_ServiceDataInstall_DataKindPanelSound:	// パネル音データ.
		{
			// ファイルサイズ。なし.
			// データ保存要求.
			if( ppc_PanelHard ) {
				// 遅延実行が未実施の場合は、フラグを設定して処理を抜ける(procTimerWakeUpでもう一度コールされるのを待つ).
				if( False == pst_InstallInfo->pst_ExecuteInfo->bl_ExecuteDelay ) {
					pst_InstallInfo->pst_ExecuteInfo->bl_ExecuteDelay = True;
				} else {
					void ( *resultCallback )( CNVE_DOWNLOAD_RESULT, ushort );
					resultCallback = ( void ( * )( CNVE_DOWNLOAD_RESULT, ushort ) )ans_installCompletePanelSound;
					ppc_PanelHard->downloadSoundData( ( uchar* )pst_param->pc_SrcInstallFileName, 0, 0, resultCallback );
					pst_InstallInfo->pst_ExecuteInfo->bl_ExecuteDelay = False;
				}
			} else {
				pst_InstallInfo->pst_ExecuteInfo->e_InstallStatus = InstallDeleteExecution_NG;
			}
		}
		break;
		case PNLE_ServiceDataInstall_DataKindOEMDriver:		// OEMドライバ.
			// ファイルサイズ。なし.
			// 同期で書き込み要求.
			if( True == downloadOemData( NULL ) ) {				// OEMドライバダウンロード.現状はファイルパスがデフォルトのためNULLを指定.
				pst_InstallInfo->pst_ExecuteInfo->e_InstallStatus = InstallDeleteExecution_OK;	// 成功.
			} else {
				pst_InstallInfo->pst_ExecuteInfo->e_InstallStatus = InstallDeleteExecution_NG;	// 失敗.
			}
			break;
		default:
			pst_InstallInfo->pst_ExecuteInfo->e_InstallStatus = InstallDeleteExecution_NG;
			break;
	}
}

//////////////////////////////////////////////////////////////.
// 概要		: システム設定／データインストール(50C00150_MiB) : インストール完了.
// 戻り値	: なし.
// 変更履歴	:.
//////////////////////////////////////////////////////////////.
void PServiceDataInstall_MiB::installComplete()
{
	short ss_index;
	for( ss_index = 0; ss_index < m_ss_InstallInfoCount; ss_index++ ) {
		if( InstallDeleteExecution_Executing == m_pst_InstallInfo[ss_index].pst_ExecuteInfo->e_InstallStatus ) {
			break;
		}
	}

	// 実行中のデータはなし.
	if( ss_index == m_ss_InstallInfoCount ) {
		return;
	}

	if( True == m_bl_InstallResult ) {
		// インストール成功.
		m_pst_InstallInfo[ss_index].pst_ExecuteInfo->e_InstallStatus = InstallDeleteExecution_OK;

		// CommonAPIへインストール済みフラグを設定する.
		switch( m_pst_InstallInfo[ss_index].e_DataKind ) {
			case PNLE_ServiceDataInstall_DataKindAudio:		// 音声.
				PnlComGetMachineSetting()->setVoiceInstallFlgInfo( True );
				break;
			case PNLE_ServiceDataInstall_DataKindAnime:		// 動画.
				PnlComGetMachineSetting()->setAnimationInstallFlgInfo( True );
				break;
			case PNLE_ServiceDataInstall_DataKindOCRDict:	// OCR辞書.
				PnlComGetSearchablePDFSetting()->setSearchablePDFDictionaryDataInstallFlg( True );
				break;
			case PNLE_ServiceDataInstall_DataKindPDFA:		// PDFAフォント.
				if( True == PnlComGetMachineSetting()->chkPdfaFontInstall() ) {		// PDF/Aフォントデータのチェックサム確認.
					PnlComGetMachineSetting()->setPdfAFontInstallFlgInfo( True );
				} else {		// チェックサム異常の場合は、NG.
					m_pst_InstallInfo[ss_index].pst_ExecuteInfo->e_InstallStatus = InstallDeleteExecution_NG;
				}
				break;
			case PNLE_ServiceDataInstall_DataKindPanelSound:// パネル音データ.
			{
				ushort us_CheckSum = 0;
				uchar uc_Version[20+1];
				memset( uc_Version, 0, sizeof( uc_Version ) );

				TYPE_Rom e_VerRom = m_pst_InstallInfo[ss_index].pst_InstallParam->e_VerRom;	// ROMタイプ.
				if( ppc_PanelHard ) {
					// BSPからパネル音データのバージョン、チェックサムを取得する.
					ppc_PanelHard->getSoundDataVersion( uc_Version );					// バージョン.
					us_CheckSum = ppc_PanelHard->getSoundDataCheckSum();				// チェックサム.
				}
				// システム情報に設定する.
				ppc_SystemInfo->setRomVersion( e_VerRom, ( char* )uc_Version );
				ppc_SystemInfo->setRomCheckSum( e_VerRom, us_CheckSum );
				// インストール済み.
				PnlComGetMachineSetting()->setPanelSoundDataInstallFlgInfo( True );
			}
			break;
			case PNLE_ServiceDataInstall_DataKindOEMDriver:	// OEMドライバ.
			default:
				// フラグなし.
				break;
		}
	} else {
		// CommonAPIへインストール済みフラグを設定する.
		switch( m_pst_InstallInfo[ss_index].e_DataKind ) {
			case PNLE_ServiceDataInstall_DataKindAudio:		// 音声.
			case PNLE_ServiceDataInstall_DataKindAnime:		// 動画.
			case PNLE_ServiceDataInstall_DataKindOCRDict:	// OCR辞書.
			case PNLE_ServiceDataInstall_DataKindPDFA:		// PDFAフォント.
				break;
			case PNLE_ServiceDataInstall_DataKindPanelSound:// パネル音データ.
			{
				// エラーコードチェック.
				switch( ( CNVE_DOWNLOAD_RESULT )m_e_ErrorCode ) {
					case CNVE_DOWNLOAD_RESULT_DO_NOT_UPDATE:	// ダウンロード不可(対応していないパネル).
					case CNVE_DOWNLOAD_RESULT_INVALID_PARAM:	// パラメータ異常.
					case CNVE_DOWNLOAD_RESULT_FILE_ERROR:		// ファイルオープンエラー(ファイルがないなど).
						// パネルマイコンへの書き込みシーケンス前のエラーである為、情報を更新しない.
						break;
					case CNVE_DOWNLOAD_RESULT_CHECKSUM_ERROR:	// チェックサム不一致.
					case CNVE_DOWNLOAD_RESULT_WRITE_ERROR:		// 書き込み失敗.
					case CNVE_DOWNLOAD_RESULT_SEQUENCE_ERROR:	// シーケンス異常(パネルから応答がなくなったなど).
					default:	// その他のエラー.
						// パネルマイコンへの書き込みシーケンス後のエラーの場合は、未インストール状態にする.
						// システム情報にバージョン(空文字列)、チェックサム(0)を設定する.
						TYPE_Rom e_VerRom = m_pst_InstallInfo[ss_index].pst_InstallParam->e_VerRom;	// ROMタイプ.
						ppc_SystemInfo->setRomVersion( e_VerRom, "" );
						ppc_SystemInfo->setRomCheckSum( e_VerRom, 0 );
						// 未インストール状態にする.
						PnlComGetMachineSetting()->setPanelSoundDataInstallFlgInfo( False );
						break;
				}
			}
			break;
			default:
				break;
		}
		//　インストール結果ＮＧ.
		m_pst_InstallInfo[ss_index].pst_ExecuteInfo->e_InstallStatus = InstallDeleteExecution_NG;
	}

	ss_index++;
	for( ; ss_index < m_ss_InstallInfoCount; ss_index++ ) {
		// 次のインストールを開始する.
		if( InstallDeleteExecution_Reserved == m_pst_InstallInfo[ss_index].pst_ExecuteInfo->e_InstallStatus ) {
			// ステータスがインストール予約になっている場合、インストールを開始する.
			startInstall( &m_pst_InstallInfo[ss_index] );
			break;
		}
	}
}

//////////////////////////////////////////////////////////////.
// 概要		: システム設定／データインストール(50C00150_MiB) : 削除実行.
// 戻り値	: なし.
//////////////////////////////////////////////////////////////.
void PServiceDataInstall_MiB::deleteExec()
{
	short ss_index;
	PNLS_ServiceDataInstall_ExecuteInfo st_initExecuteInfo =
	{ 0, 0, InstallDeleteExecution_None, InstallDeleteExecution_None, False };

	// 実行状態の初期設定.
	for( ss_index = 0; ss_index < m_ss_InstallInfoCount; ss_index++ ) {
		*( m_pst_InstallInfo[ss_index].pst_ExecuteInfo ) = st_initExecuteInfo;
	}

	for( ss_index = 0; ss_index < m_ss_InstallInfoCount; ss_index++ ) {
		if( m_pst_InstallInfo[ss_index].bl_Selected ) {
			// 削除可能で無い場合、
			if( !isEnableDelete( m_pst_InstallInfo[ss_index].e_DataKind ) ) {
				continue;
			}

			// データ種別キーが選択状態になっている場合.
			if( True == isDeleteing() ) {
				// 削除している物が既にある場合は、削除予約とする.
				m_pst_InstallInfo[ss_index].pst_ExecuteInfo->e_DeleteStatus = InstallDeleteExecution_Reserved;
			} else {
				// 削除開始.
				startDelete( &m_pst_InstallInfo[ss_index] );
			}
		}
	}
}
//////////////////////////////////////////////////////////////.
// 概要		: システム設定／データインストール(50C00150_MiB) :  削除開始.
// 戻り値	: なし.
//////////////////////////////////////////////////////////////.
void PServiceDataInstall_MiB::startDelete( PNLS_ServiceDataInstall_InstallInfo* pst_InstallInfo )
{
	// 実行中をセット.
	pst_InstallInfo->pst_ExecuteInfo->e_DeleteStatus = InstallDeleteExecution_Executing;

	// 結果をクリアする.
	m_bl_DeleteResult		= False;
	m_e_ErrorCode			= 0;

	PNLS_ServiceDataInstall_InstallParam* pst_param = pst_InstallInfo->pst_InstallParam;
	// データ種別ごとに実装.
	switch( pst_InstallInfo->e_DataKind ) {
		case PNLE_ServiceDataInstall_DataKindAudio:			// 音声.
		case PNLE_ServiceDataInstall_DataKindAnime:			// 動画.
			PnlComGetMachineSetting()->eraseVoiceAnimationHDDArea( pst_param->pc_UninstallPath, ans_deleteComplete );
			break;
		case PNLE_ServiceDataInstall_DataKindOCRDict:		// OCR辞書.
			PnlComGetSearchablePDFSetting()->eraseHddArea( pst_param->pc_UninstallPath, ans_deleteComplete );
			break;
		case PNLE_ServiceDataInstall_DataKindPDFA:			// PDFAフォント.
			PnlComGetMachineSetting()->eraseHddArea( pst_param->pc_UninstallPath, ans_deleteComplete );
			break;
		case PNLE_ServiceDataInstall_DataKindOEMDriver:		// OEMドライバ.
			if( True == APIC_OEMDriverCustomizeSetting::newInstance()->removeOEMData() ) {	// OEMドライバ名称カスタマイズデータを削除.
				pst_InstallInfo->pst_ExecuteInfo->e_DeleteStatus = InstallDeleteExecution_OK;
			} else {
				pst_InstallInfo->pst_ExecuteInfo->e_DeleteStatus = InstallDeleteExecution_NG;
			}
			break;
		case PNLE_ServiceDataInstall_DataKindPanelSound:	// パネル音データ.
		// 削除なし.
		default:
			pst_InstallInfo->pst_ExecuteInfo->e_DeleteStatus = InstallDeleteExecution_NG;
			break;
	}
}

//////////////////////////////////////////////////////////////.
// 概要		: システム設定／データインストール(50C00150_MiB) : 削除完了.
// 戻り値	: なし.
// 変更履歴	:.
//////////////////////////////////////////////////////////////.
void PServiceDataInstall_MiB::deleteComplete()
{
	short ss_index;
	for( ss_index = 0; ss_index < m_ss_InstallInfoCount; ss_index++ ) {
		if( InstallDeleteExecution_Executing == m_pst_InstallInfo[ss_index].pst_ExecuteInfo->e_DeleteStatus ) {
			break;
		}
	}

	// 実行中のデータはなし.
	if( ss_index == m_ss_InstallInfoCount ) {
		return;
	}

	if( True == m_bl_DeleteResult ) {
		// インストール成功.
		m_pst_InstallInfo[ss_index].pst_ExecuteInfo->e_DeleteStatus = InstallDeleteExecution_OK;

		// SystemInfoのバージョンをクリアしておく.
		ppc_SystemInfo->setRomVersion( m_pst_InstallInfo[ss_index].pst_InstallParam->e_VerRom, "" );

		// CommonAPIへインストールなしを設定する.
		switch( m_pst_InstallInfo[ss_index].e_DataKind ) {
			case PNLE_ServiceDataInstall_DataKindAudio:		// 音声.
				PnlComGetMachineSetting()->setVoiceInstallFlgInfo( False );
				break;
			case PNLE_ServiceDataInstall_DataKindAnime:		// 動画.
				PnlComGetMachineSetting()->setAnimationInstallFlgInfo( False );
				break;
			case PNLE_ServiceDataInstall_DataKindOCRDict:	// OCR辞書.
				PnlComGetSearchablePDFSetting()->setSearchablePDFDictionaryDataInstallFlg( False );
				break;
			case PNLE_ServiceDataInstall_DataKindPDFA:		// PDFAフォント.
				PnlComGetMachineSetting()->setPdfAFontInstallFlgInfo( False );
				break;
			case PNLE_ServiceDataInstall_DataKindPanelSound:// パネル音データ.
			// 削除なし.
			case PNLE_ServiceDataInstall_DataKindOEMDriver:	// OEMドライバ.
			default:
				// フラグなし.
				break;
		}
	} else {
		m_pst_InstallInfo[ss_index].pst_ExecuteInfo->e_DeleteStatus = InstallDeleteExecution_NG;
	}

	ss_index++;
	for( ; ss_index < m_ss_InstallInfoCount; ss_index++ ) {
		// 次のインストールを開始する.
		if( InstallDeleteExecution_Reserved == m_pst_InstallInfo[ss_index].pst_ExecuteInfo->e_DeleteStatus ) {
			// ステータスがインストール予約になっている場合、インストールを開始する.
			startDelete( &m_pst_InstallInfo[ss_index] );
			break;
		}
	}
}

