//////////////////////////////////////////////////////////////.
// 概要		: システム設定／データインストール(50C00150_MiB) : 電源OFF/ONが必要か.
// 戻り値	: True: 電源OFF/ONが必要 / False: 電源OFF/ONは不要.
//////////////////////////////////////////////////////////////.
Bool PServiceDataInstall_MiB::isNeedPowerOffOn()
{
	if( True == m_pst_InstallInfo[PNLE_ServiceDataInstall_DataKindOEMDriver].bl_Selected					// OEMが選択されている.
	    && ( InstallDeleteExecution_OK == 																	// OEMのインストールまたは削除が成功している.
	         m_pst_InstallInfo[PNLE_ServiceDataInstall_DataKindOEMDriver].pst_ExecuteInfo->e_InstallStatus
	         || InstallDeleteExecution_OK ==
	         m_pst_InstallInfo[PNLE_ServiceDataInstall_DataKindOEMDriver].pst_ExecuteInfo->e_DeleteStatus )
	    && False == isExecuting()																			// インストール/削除が実行中でない.
	    && False == isReserved()																			// インストール/削除が予約中でない.
	  ) {
		return True;
	}
	return False;
}
//////////////////////////////////////////////////////////////.
// 概要		: システム設定／データインストール(50C00150_MiB) :  削除可能であるかチェック.
// 戻り値	: True: 削除可能 / False: 削除不可能.
//////////////////////////////////////////////////////////////.
Bool PServiceDataInstall_MiB::isEnableDelete( PNLE_ServiceDataInstall_DataKind e_DataKind )
{
	Bool bl_EnableDelete = False;	// 削除可能であるか.
	APIC_OEMDriverCustomizeSetting* pc_OEMDriverCustomizeSetting;

	switch( e_DataKind ) {
		case PNLE_ServiceDataInstall_DataKindAudio:		// 音声.
			bl_EnableDelete = PnlComGetMachineSetting()->getVoiceInstallFlgInfo();
			break;
		case PNLE_ServiceDataInstall_DataKindAnime:		// 動画.
			bl_EnableDelete = PnlComGetMachineSetting()->getAnimationInstallFlgInfo();
			break;
		case PNLE_ServiceDataInstall_DataKindOCRDict:	// OCR辞書.
			bl_EnableDelete = PnlComGetSearchablePDFSetting()->getSearchablePDFDictionaryDataInstallFlg();
			break;
		case PNLE_ServiceDataInstall_DataKindPDFA:		// PDFAフォント.
			bl_EnableDelete = PnlComGetMachineSetting()->getPdfAFontInstallFlgInfo();
			break;
		case PNLE_ServiceDataInstall_DataKindOEMDriver:	// OEMドライバ.
			pc_OEMDriverCustomizeSetting = APIC_OEMDriverCustomizeSetting::newInstance();
			if( NULL == pc_OEMDriverCustomizeSetting ) {
//2019/06/17 Comment [HCLT_Krishnakumar][EagleH][N Rank] Removed unwanted detailed code.
// 2015/11/05 【HCLT-Dhivya】 【ZeusS_ZX0】 【制御構成変更_No.76-1】Detail macro is passed in API.
//				LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//				if (NULL != pc_BFW_System){
//    				pc_BFW_System->registDetailCode(PNLD_DetailCode_Service_0x1900660100671101);
//				}				
				LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
				return False;
			}
			bl_EnableDelete = pc_OEMDriverCustomizeSetting->isOEMNameCustomizeDataExist();
			break;
		case PNLE_ServiceDataInstall_DataKindPanelSound:// パネル音データ.
		default:
			// フラグなし.
			break;
	}

	return bl_EnableDelete;
}
//////////////////////////////////////////////////////////////.
// 概要		: システム設定／データインストール(50C00150_MiB) :  全体の削除ステータス取得.
// 戻り値	: 削除の実行状態.
// 変更履歴	:.
//////////////////////////////////////////////////////////////.
InstallDeleteExecutionStatus PServiceDataInstall_MiB::getDeleteStatus()
{
	Bool bl_Exec = False;
	Bool bl_OK   = False;
	Bool bl_NG   = False;

	short ss_index;
	for( ss_index = 0; ss_index < m_ss_InstallInfoCount; ss_index++ ) {
		InstallDeleteExecutionStatus e_Status = m_pst_InstallInfo[ss_index].pst_ExecuteInfo->e_DeleteStatus;
		switch( e_Status ) {
			case InstallDeleteExecution_None:
				break;
			case InstallDeleteExecution_Reserved:
			case InstallDeleteExecution_Executing:
				bl_Exec = True;
				break;
			case InstallDeleteExecution_OK:
				bl_OK = True;
				break;
			case InstallDeleteExecution_NG:
				bl_NG = True;
		}
	}
	// 優先度( 実行中 > NG > OK > None ).
	if( bl_Exec ) {
		return InstallDeleteExecution_Executing;
	}
	if( bl_NG ) {
		return InstallDeleteExecution_NG;
	}
	if( bl_OK ) {
		return InstallDeleteExecution_OK;
	}
	return InstallDeleteExecution_None;
}
//////////////////////////////////////////////////////////////.
// 概要		: システム設定／データインストール(50C00150_MiB) :  確定キー選択可能か否か..
// 戻り値	: True:選択可能 / False:選択不可.
// 変更履歴	:.
//////////////////////////////////////////////////////////////.
Bool PServiceDataInstall_MiB::isDecideEnableSelected()
{
	Bool bl_Enable = False;

	for( short ss_index = 0; ss_index < m_ss_InstallInfoCount; ss_index++ ) {
		if( !m_pst_InstallInfo[ss_index].bl_Support ) { continue; }	// 非サポート.
		// 選択状態.
		if( m_pst_InstallInfo[ss_index].bl_Selected ) {
			bl_Enable = True;
			// 削除できないキーが選択されている場合.
			if( False == isEnableDelete( m_pst_InstallInfo[ss_index].e_DataKind ) ) {
				bl_Enable = False;
				break;
			}
		}
	}

	return bl_Enable;
}
