//////////////////////////////////////////////////////////////.
// 概要		: システム設定／データインストール(50C00150_MiB) :  インストール完了コールバック通知.
// 戻り値	: なし.
// 変更履歴	:.
//////////////////////////////////////////////////////////////.
void PServiceDataInstall_MiB::ans_installComplete( Bool bl_Result )
{
	const PNLS_ServiceDataInstall_InstallInfo* pst_InstallInfo = gp_ServiceDataInstall.getInstallingInfo();

	// インストール中のデータが無い場合は、無視する.
	if( NULL == pst_InstallInfo ) {
// 2015/11/05 【HCLT-Dhivya】 【ZeusS_ZX0】 【制御構成変更_No.76-1】Detail macro is passed in API.
		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
		if (NULL != pc_BFW_System){
    		pc_BFW_System->registDetailCode(PNLD_DetailCode_Service_0x1900280100671201);
		}				
		return;
	}

	// インストール結果を設定.
	gp_ServiceDataInstall.setInstallResult( bl_Result );

	char cVersion[40+1];
	char cGetVersionFilePath[80];
	memset( cVersion,			 0, sizeof( cVersion ) );
	memset( cGetVersionFilePath, 0, sizeof( cGetVersionFilePath ) );

	TYPE_Rom e_VerRom = pst_InstallInfo->pst_InstallParam->e_VerRom;				// ROMタイプ.
	char* pc_uninstallPath = pst_InstallInfo->pst_InstallParam->pc_UninstallPath;	// アンインストールパス.

	switch( pst_InstallInfo->e_DataKind ) {
		case PNLE_ServiceDataInstall_DataKindAudio:		// 音声.
		case PNLE_ServiceDataInstall_DataKindAnime:		// 動画.
		{
			// 音声/動画の場合.
			snprintf( cGetVersionFilePath, sizeof( cGetVersionFilePath ), "/ata04/%s/%s", pc_uninstallPath, PNLE_VersionTextFileName );
			if( PnlComGetMachineSetting()->getVoiceAnimationFileVersion( cGetVersionFilePath, cVersion ) == True ) {
				ppc_SystemInfo->setRomVersion( e_VerRom, cVersion );
			}
			else {
				ppc_SystemInfo->setRomVersion( e_VerRom, "" );
			}
		}
		break;
		case PNLE_ServiceDataInstall_DataKindOCRDict:	// OCR辞書.
		{
			// 辞書データの場合.
			snprintf( cGetVersionFilePath, sizeof( cGetVersionFilePath ), "/ata04/%s/%s", pc_uninstallPath, PNLE_VersionTextFileName );
			if( PnlComGetSearchablePDFSetting()->getHddFileVersion( cGetVersionFilePath, cVersion ) == True ) {
				ppc_SystemInfo->setRomVersion( e_VerRom, cVersion );
			}
			else {
				ppc_SystemInfo->setRomVersion( e_VerRom, "" );
			}
		}
		break;
		case PNLE_ServiceDataInstall_DataKindPDFA:		// PDFAフォント.
		{
			// PDF/Aフォントデータの場合.
			snprintf( cGetVersionFilePath, sizeof( cGetVersionFilePath ), "/ata04/%s/%s", pc_uninstallPath, PNLE_PDFAFontVersionTextFileName );
			if( PnlComGetMachineSetting()->getFileVersion( cGetVersionFilePath, cVersion ) == True ) {
				ppc_SystemInfo->setRomVersion( e_VerRom, cVersion );
			}
			else {
				ppc_SystemInfo->setRomVersion( e_VerRom, "" );
			}
		}
		break;
		case PNLE_ServiceDataInstall_DataKindPanelSound:// パネル音データ.
		case PNLE_ServiceDataInstall_DataKindOEMDriver:	// OEMドライバ.
		default:
			break;
	}

	CallBackIndi( TYPE_PNL_CallBack_AudioAnimeInstall );
}
//////////////////////////////////////////////////////////////.
// 概要		: システム設定／データインストール(50C00150_MiB) :  インストール完了コールバック通知(パネル音データ).
// 戻り値	: なし.
// 変更履歴	:.
//////////////////////////////////////////////////////////////.
void PServiceDataInstall_MiB::ans_installCompletePanelSound( int i_Result, ushort us_CheckSum )
{
	const PNLS_ServiceDataInstall_InstallInfo* pst_InstallInfo = gp_ServiceDataInstall.getInstallingInfo();

	// インストール中のデータが無い場合は、無視する.
	if( NULL == pst_InstallInfo ) {
// 2015/11/05 【HCLT-Dhivya】 【ZeusS_ZX0】 【制御構成変更_No.76-1】Detail macro is passed in API.
		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
		if (NULL != pc_BFW_System){
    		pc_BFW_System->registDetailCode(PNLD_DetailCode_Service_0x1900280100671301);
		}
		return;
	}

	CNVE_DOWNLOAD_RESULT e_Result = ( CNVE_DOWNLOAD_RESULT )i_Result;

	// インストール結果を設定.
	gp_ServiceDataInstall.setInstallResult( ( CNVE_DOWNLOAD_RESULT_OK == e_Result ), i_Result );

	// エラー出力.
	switch( e_Result ) {
		case CNVE_DOWNLOAD_RESULT_DO_NOT_UPDATE:	printf( "PanelSoundData Download Error: DO_NOT_UPDATE\n" );	break;	// ダウンロード不可(対応していないパネル).
		case CNVE_DOWNLOAD_RESULT_CHECKSUM_ERROR:	printf( "PanelSoundData Download Error: CHECKSUM_ERROR\n" );	break;	// チェックサム不一致.
		case CNVE_DOWNLOAD_RESULT_WRITE_ERROR:		printf( "PanelSoundData Download Error: WRITE_ERROR\n" );	break;	// 書き込み失敗.
		case CNVE_DOWNLOAD_RESULT_INVALID_PARAM:	printf( "PanelSoundData Download Error: INVALID_PARAM\n" );	break;	// パラメータ異常.
		case CNVE_DOWNLOAD_RESULT_SEQUENCE_ERROR:	printf( "PanelSoundData Download Error: SEQUENCE_ERROR\n" );	break;	// シーケンス異常(パネルから応答がなくなったなど).
		case CNVE_DOWNLOAD_RESULT_FILE_ERROR:		printf( "PanelSoundData Download Error: FILE_ERROR\n" );		break;	// ファイルオープンエラー(ファイルがないなど).
		default:break;
	}

	CallBackIndi( TYPE_PNL_CallBack_AudioAnimeInstall );
}
//////////////////////////////////////////////////////////////.
// 概要		: システム設定／データインストール(50C00150_MiB) :  インストール完了コールバック通知.
// 戻り値	: なし.
// 変更履歴	:.
//////////////////////////////////////////////////////////////.
void PServiceDataInstall_MiB::ans_deleteComplete( Bool bl_Result )
{
	gp_ServiceDataInstall.setDeleteResult( bl_Result );

	CallBackIndi( TYPE_PNL_CallBack_AudioAnimeDelete );
}

