{
	if( isExecuting() || isNeedPowerOffOn() ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );		// 拒否音.
		// インストール・削除中はボタン押下不可.
		return;
	}
}
////////////////////////////////////////////////////////////////////////.
// 概要		: システム設定／データインストール(50C00150_Mi-K3) : スタートキー押下.
// 戻り値	: なし.
// 変更履歴	:.
////////////////////////////////////////////////////////////////////////.
void PServiceDataInstall_ZM3rd::procStart( uchar uc_option )
{
	if( printStartDisable() ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );		// 拒否音.
		return;
	}

	// インストール開始.
	installExec();

	// 画面再描画.
	setupGamen();
}
