////////////////////////////////////////////////////////////////////////.
// 概要		: システム設定／データインストール(50C00150_Mi-K3) : コールバック通知.
// 戻り値	: なし.
// 変更履歴	:.
////////////////////////////////////////////////////////////////////////.
void PServiceDataInstall_ZM3rd::procCallBack( TYPE_PNL_CallBack e_option )
{
	switch( e_option ) {
		case TYPE_PNL_CallBack_AudioAnimeInstall:	// 音声・動画インストール完了通知.
			installComplete();
			setupGamen();
			break;
		case TYPE_PNL_CallBack_AudioAnimeDelete:	// 音声・動画削除通知.
			deleteComplete();
			setupGamen();
			break;
		default:
			break;
	}
}
