Bool PServiceDataInstall_ZM3rd::isInstalling()
{
	short ss_index;
	for( ss_index = 0; ss_index < m_ss_InstallInfoCount; ss_index++ ) {
		if( InstallDeleteExecution_Executing == m_pst_InstallInfo[ss_index].pst_ExecuteInfo->e_InstallStatus ) {
			return True;
		}
	}
	return False;
}

