//////////////////////////////////////////////////////////////.
// 概要		: システム設定／データインストール(50C00150_Mi-K3) : 電源OFF/ONが必要か.
// 戻り値	: True: 電源OFF/ONが必要 / False: 電源OFF/ONは不要.
//////////////////////////////////////////////////////////////.
Bool PServiceDataInstall_ZM3rd::isNeedPowerOffOn()
{
#if defined( DEF_EagleCus  ) || defined( DEF_EaglePanel_Low  ) || defined( DEF_EaglePanel_Hi ) || defined( DEF_A4_Cus )	
	if ( True== PnlComIsEagleHiModel() ) {
		
	if( True == m_pst_InstallInfo[PNLE_ServiceDataInstall_DataKindOEMDriver_EglH].bl_Selected					// OEMが選択されている.
	    && ( InstallDeleteExecution_OK == 																	// OEMのインストールまたは削除が成功している.
	         m_pst_InstallInfo[PNLE_ServiceDataInstall_DataKindOEMDriver_EglH].pst_ExecuteInfo->e_InstallStatus
	         || InstallDeleteExecution_OK ==
	         m_pst_InstallInfo[PNLE_ServiceDataInstall_DataKindOEMDriver_EglH].pst_ExecuteInfo->e_DeleteStatus )
	    && False == isExecuting()																			// インストール/削除が実行中でない.
	    && False == isReserved()																			// インストール/削除が予約中でない.
	  ) {
		return True;
	}

	if( True == m_pst_InstallInfo[PNLE_ServiceDataInstall_DataKindFWData_HIGH].bl_Selected	// FWデータが選択されている.
	    && InstallDeleteExecution_OK == m_pst_InstallInfo[PNLE_ServiceDataInstall_DataKindFWData_HIGH].pst_ExecuteInfo->e_InstallStatus	// FWデータのインストールが成功している.
	    && False == isExecuting()															// インストール/削除が実行中でない.
	    && False == isReserved()															// インストール/削除が予約中でない.
	  ) {
		return True;
	}
	if( True == m_pst_InstallInfo[PNLE_ServiceDataInstall_DataKindIPFax_HIGH].bl_Selected						// IP-FAXが選択されている.
		&& ( InstallDeleteExecution_OK == 																	// IP-FAXのインストールまたは削除が成功している.
			 m_pst_InstallInfo[PNLE_ServiceDataInstall_DataKindIPFax_HIGH].pst_ExecuteInfo->e_InstallStatus
			 || InstallDeleteExecution_OK ==
			 m_pst_InstallInfo[PNLE_ServiceDataInstall_DataKindIPFax_HIGH].pst_ExecuteInfo->e_DeleteStatus )
		&& False == isExecuting()																			// インストール/削除が実行中でない.
		&& False == isReserved()																			// インストール/削除が予約中でない.
	  ) {
		return True;
	}
	}else{
			if( True == m_pst_InstallInfo[PNLE_ServiceDataInstall_DataKindOEMDriver].bl_Selected					// OEMが選択されている.
	    && ( InstallDeleteExecution_OK == 																	// OEMのインストールまたは削除が成功している.
	         m_pst_InstallInfo[PNLE_ServiceDataInstall_DataKindOEMDriver].pst_ExecuteInfo->e_InstallStatus
	         || InstallDeleteExecution_OK ==
	         m_pst_InstallInfo[PNLE_ServiceDataInstall_DataKindOEMDriver].pst_ExecuteInfo->e_DeleteStatus )
	    && False == isExecuting()																			// インストール/削除が実行中でない.
	    && False == isReserved()																			// インストール/削除が予約中でない.
	  ) {
		return True;
	}

	if( True == m_pst_InstallInfo[PNLE_ServiceDataInstall_DataKindFWData].bl_Selected	// FWデータが選択されている.
	    && InstallDeleteExecution_OK == m_pst_InstallInfo[PNLE_ServiceDataInstall_DataKindFWData].pst_ExecuteInfo->e_InstallStatus	// FWデータのインストールが成功している.
	    && False == isExecuting()															// インストール/削除が実行中でない.
	    && False == isReserved()															// インストール/削除が予約中でない.
	  ) {
		return True;
	}

// comment 2018/12/26 SCD2-Sky高垣 [EagleH][RQ-272] Fax機能をもつ全製品のT38Faxプロトコルの対応.
	if( True == m_pst_InstallInfo[PNLE_ServiceDataInstall_DataKindIPFax].bl_Selected						// IP-FAXが選択されている.
		&& ( InstallDeleteExecution_OK == 																	// IP-FAXのインストールまたは削除が成功している.
			 m_pst_InstallInfo[PNLE_ServiceDataInstall_DataKindIPFax].pst_ExecuteInfo->e_InstallStatus
			 || InstallDeleteExecution_OK ==
			 m_pst_InstallInfo[PNLE_ServiceDataInstall_DataKindIPFax].pst_ExecuteInfo->e_DeleteStatus )
		&& False == isExecuting()																			// インストール/削除が実行中でない.
		&& False == isReserved()																			// インストール/削除が予約中でない.
	  ) {
		return True;
	}
	}
#else
			if( True == m_pst_InstallInfo[PNLE_ServiceDataInstall_DataKindOEMDriver].bl_Selected					// OEMが選択されている.
	    && ( InstallDeleteExecution_OK == 																	// OEMのインストールまたは削除が成功している.
	         m_pst_InstallInfo[PNLE_ServiceDataInstall_DataKindOEMDriver].pst_ExecuteInfo->e_InstallStatus
	         || InstallDeleteExecution_OK ==
	         m_pst_InstallInfo[PNLE_ServiceDataInstall_DataKindOEMDriver].pst_ExecuteInfo->e_DeleteStatus )
	    && False == isExecuting()																			// インストール/削除が実行中でない.
	    && False == isReserved()																			// インストール/削除が予約中でない.
	  ) {
		return True;
	}

	if( True == m_pst_InstallInfo[PNLE_ServiceDataInstall_DataKindFWData].bl_Selected	// FWデータが選択されている.
	    && InstallDeleteExecution_OK == m_pst_InstallInfo[PNLE_ServiceDataInstall_DataKindFWData].pst_ExecuteInfo->e_InstallStatus	// FWデータのインストールが成功している.
	    && False == isExecuting()															// インストール/削除が実行中でない.
	    && False == isReserved()															// インストール/削除が予約中でない.
	  ) {
		return True;
	}

	if( True == m_pst_InstallInfo[PNLE_ServiceDataInstall_DataKindIPFax].bl_Selected						// IP-FAXが選択されている.
		&& ( InstallDeleteExecution_OK == 																	// IP-FAXのインストールまたは削除が成功している.
			 m_pst_InstallInfo[PNLE_ServiceDataInstall_DataKindIPFax].pst_ExecuteInfo->e_InstallStatus
			 || InstallDeleteExecution_OK ==
			 m_pst_InstallInfo[PNLE_ServiceDataInstall_DataKindIPFax].pst_ExecuteInfo->e_DeleteStatus )
		&& False == isExecuting()																			// インストール/削除が実行中でない.
		&& False == isReserved()																			// インストール/削除が予約中でない.
	  ) {
		return True;
	}
#endif
		
	return False;
}
