		case PNLE_ServiceDataInstall_DataKindWaitBGM:	// 待機中BGM.
			bl_EnableDelete = PnlComGetMachineSetting()->getBGMInstallFlgInfo( TYPE_RomBGMWait );
			break;
		case PNLE_ServiceDataInstall_DataKindJobBGM:	// ジョブ中BGM.
