// comment 2022/01/13 Sky中野 [IT6_2.2MR2] 制御No.33_サービスレスメンテナンス対応.
//////////////////////////////////////////////////////////////.
// 概要		: システム設定／データインストール(50C00150_Mi-K3) :  最大ページ数の設定.
// 戻り値	: なし.
//////////////////////////////////////////////////////////////.
void PServiceDataInstall_ZM3rd::setupPageMax()
{
	// 2ページ目以降に表示するデータキーがあるか確認.
	short ss_Count = 0;
	uchar uc_startnum = 0;
	uchar uc_endnum   = 0;
	for( uchar uc_Page = 2; PNLE_ServiceDataInstall_PageMax >= uc_Page; ++uc_Page ) {
		ss_Count = 0;
		uc_startnum = static_cast<uchar>( ( uc_Page - 1 ) * PNLE_ServiceDataInstall_DispCount );
		uc_endnum = static_cast<uchar>( uc_startnum + PNLE_ServiceDataInstall_DispCount - 1 );
		// 範囲チェック.
		if( m_ss_InstallInfoCount <= uc_startnum ) {
			// 開始位置がデータ数を超えた場合、終了.
			break;
		}
		if( m_ss_InstallInfoCount <= uc_endnum ) {
			// 終了位置がデータ数を超えた場合、データ数分まで判定処理を実施する.
			uc_endnum = static_cast<uchar>( m_ss_InstallInfoCount - 1 );
		}
		// 表示有無を判定.
		for( uchar uc_index = uc_startnum; uc_endnum >= uc_index; ++uc_index ) {
			if( True == m_pst_InstallInfo[uc_index].bl_Support ) {
				++ ss_Count;
			}
		}
		if( 0 < ss_Count ) {
			m_uc_PageMax = uc_Page;
		}
	}
}

