			nextGamen = &gp_SvcsCStapleAdj;
			break ;
		case	BTNID_KEY_SERV_HALF_FOLD_PASITION:			// サービス・フィニッシャ調整・中折り位置.
			bl_isRequestInitialize = True ;	// 初期設定フラグON.
			// 中折り位置調整を設定.
			nextGamen = &gp_SvcsHalfFoldAdj ;
			break ;
		case	BTNID_KEY_SERV_THREE_FOLD_POSITION1:		// サービス・フィニッシャ調整・第1三つ折り位置
			bl_isRequestInitialize = True ;	// 初期設定フラグON
			// 第1三つ折り位置調整を設定
			nextGamen = &gp_SvcsThreeFoldPosiAdj1 ;
			break ;
		case	BTNID_KEY_SERV_THREE_FOLD_POSITION2:		// サービス・フィニッシャ調整・第2三つ折り位置
			bl_isRequestInitialize = True ;	// 初期設定フラグON
			// 第2三つ折り位置調整を設定
			nextGamen = &gp_SvcsThreeFoldPosiAdj2 ;
			break ;
		case	BTNID_KEY_SERV_PUNCH_WIDTH_POSITION:		// サービス・フィニッシャ調整・パンチ横位置.
			bl_isRequestInitialize = True ;	// 初期設定フラグON.
			// パンチ横位置調整を設定.
			nextGamen = &gp_SvcsPunchHeightPositionAdjFS527 ;
			break ;
		case	BTNID_KEY_SERV_PUNCH_REGIST_LOOP_MAIN:		// サービス・フィニッシャ調整・パンチレジスト量(本体).
			bl_isRequestInitialize = True ;	// 初期設定フラグON.
			// パンチレジストループ量調整(本体)を設定.
			nextGamen = &gp_SvcsPunchRegistLoopAdjMainOther ;
