//================================================================================================.
// 概要 : EC0003 フィニッシャー調整／FS－FN調整(FS-534接続時) ：画面開始処理.
//================================================================================================.
void PServiceFinisherAdjMenuFS534::setupGamen( short option )
{
	// 中折り・中とじ・三つ折りの何れかが有効であれば、フィニッシャーの紙折り有効と判定.
	if( ( False == isHalfFoldEnable() ) && ( False == isCenterStapleFoldEnable() ) && ( False == isTriFoldEnable() ) ) {
		Key_GoToHalfFoldPosition.showEnable( False );				// 中折り位置調整.
		Key_GoToThreeFoldPosition1FS534.showEnable( False );		// 第1三つ折り位置調整.
		Key_GoToThreeFoldPosition2FS534.showEnable( False );		// 第2三つ折り位置調整.
		Key_GoToCenterStaplePosition.showEnable( False );			// 中央ｽﾃ-ﾌﾟﾙ位置.
	} else {
		Key_GoToHalfFoldPosition.showEnable( True );				// 中折り位置調整.
		Key_GoToThreeFoldPosition1FS534.showEnable( True );			// 第1三つ折り位置調整.
		Key_GoToThreeFoldPosition2FS534.showEnable( True );			// 第2三つ折り位置調整.
		Key_GoToCenterStaplePosition.showEnable( True );			// 中央ｽﾃ-ﾌﾟﾙ位置.
	}

	// パンチキット非装着時、非表示.
	if( TYPE_PunchKitType_None != PnlComGetMachineSetting()->getPunchKitType() ) {	// パンチキットが非装着でない.
		Key_GoToPunchWidthPositionFS534.showEnable( True );				// パンチ横位置.
		Key_GoToPunchRegistLoopMainFS527.showEnable( True );		// パンチレジストループ量(本体)(FS-534接続時).
// comment 2018/09/05 【HCL-Rajesh】【AR1058404】 【IT6_Eagle】Rivert the changes Because  "punch centering fine Adj" key is not applicable for Eagle.
//// comment 2018/07/05 【HCL-Rajesh】【AR1046969】 【IT6_Eagle】Enable the "punch centering fine Adj" key.
//		Key_GoToPunchHeightPositionFS534.showEnable( True );
	}
	else {
		Key_GoToPunchWidthPositionFS534.showEnable( False );				// パンチ横位置.
		Key_GoToPunchRegistLoopMainFS527.showEnable( False );		// パンチレジストループ量(本体)(FS-534接続時).
// comment 2018/09/05 【HCL-Rajesh】【AR1058404】 【IT6_Eagle】Rivert the changes Because  "punch centering fine Adj" key is not applicable for Eagle.
//// comment 2018/07/05 【HCL-Rajesh】【AR1046969】 【IT6_Eagle】Disable the "punch centering fine Adj" key.
//		Key_GoToPunchHeightPositionFS534.showEnable( False );
	}
	// 親クラスを呼ぶ.
	PServiceNoFunctionCodeCom::setupGamen( option );
}
