//================================================================================================.
// 概要		:サービス・フィニッシャー調整・FS-FN調整・パンチ縦位置(FS-527接続時)：ボタン(押された).
//================================================================================================.
void PServiceFinisherPunchHeightPositionAdjFS527::procButtonOn( uchar option )
{
	switch( option ) {
		case 18:	// +キー.
			addIndi();
			break;
		case 19:	// -キー.
			subIndi();
			break;
		case 60:	// 元に戻すキー.
			switch( getIndiSelected() ) {
				case TYPE_FS527_AD_PunchAdjDepth_Normal:
					setPrinterIndi( TYPE_FS527_AD_PunchAdjDepth_Normal,			ss_BakFinisherPunchHeightNormal	);
					break;
				case TYPE_FS527_AD_PunchAdjDepth_Thick1_1Plus:
					setPrinterIndi( TYPE_FS527_AD_PunchAdjDepth_Thick1_1Plus,	ss_BakFinisherPunchHeightThick1_1Plus	);
					break;
				case TYPE_FS527_AD_PunchAdjDepth_Thick2:
					setPrinterIndi( TYPE_FS527_AD_PunchAdjDepth_Thick2,			ss_BakFinisherPunchHeightThick2	);
					break;
				case TYPE_FS527_AD_PunchAdjDepth_Thick3:
					setPrinterIndi( TYPE_FS527_AD_PunchAdjDepth_Thick3,			ss_BakFinisherPunchHeightThick3	);
					break;
				case TYPE_FS534_AD_PunchAdjCenter_Thick4:
					setPrinterIndi( TYPE_FS534_AD_PunchAdjCenter_Thick4,		ss_BakFinisherPunchHeightThick4	);
					break;
				case TYPE_FS534_AD_PunchAdjCenter_Thin:
					setPrinterIndi( TYPE_FS534_AD_PunchAdjCenter_Thin,			ss_BakFinisherPunchHeightThin	);
					break;
				default:
					break;
			}
			break;
		case 0:		// 普通紙キー.
			setPrinterIndi( TYPE_FS527_AD_PunchAdjDepth_Normal	);
			break;
		case 1:		// 厚紙1/1+キー.
			setPrinterIndi( TYPE_FS527_AD_PunchAdjDepth_Thick1_1Plus	);
			break;
		case 2:		// 厚紙2キー.
			setPrinterIndi( TYPE_FS527_AD_PunchAdjDepth_Thick2	);
			break;
		case 3:		// 厚紙3キー.
			setPrinterIndi( TYPE_FS527_AD_PunchAdjDepth_Thick3	);
			break;
		case BTNID_KEY_SERV_PUCCH_ADJ_CENTER_THICK4:	// 厚紙4キー.
			setPrinterIndi( TYPE_FS534_AD_PunchAdjCenter_Thick4	);
			break;
		case BTNID_KEY_SERV_PUCCH_ADJ_CENTER_THIN:		// 薄紙キー.
			setPrinterIndi( TYPE_FS534_AD_PunchAdjCenter_Thin	);
			break;
		default:
			break;
	}
	setupGamen();
}
