//================================================================================================.
// 概要		:サービス・フィニッシャー調整・FS-FN調整・パンチ縦位置(FS-527接続時)：画面表示セットアップ.
//================================================================================================.
void PServiceFinisherPunchHeightPositionAdjFS527::setupGamen( short option )
{

	// 親クラスの呼出し.
	PServiceFinisherAdjCom::setupGamen( option );
	// 設定値の表示.
	Btx_PunchStopPosValueNormal = ( float )getPrinterIndi( TYPE_FS527_AD_PunchAdjDepth_Normal	);
	Btx_PunchYPosValueThick1 = ( float )getPrinterIndi( TYPE_FS527_AD_PunchAdjDepth_Thick1_1Plus	);
	Btx_PunchYPosValueThick2 = ( float )getPrinterIndi( TYPE_FS527_AD_PunchAdjDepth_Thick2	);
	Btx_PunchYPosValueThick3 = ( float )getPrinterIndi( TYPE_FS527_AD_PunchAdjDepth_Thick3	);
	Btx_PunchYPosValueThick4 = ( float )getPrinterIndi( TYPE_FS534_AD_PunchAdjCenter_Thick4	);
	Btx_PunchYPosValueThin   = ( float )getPrinterIndi( TYPE_FS534_AD_PunchAdjCenter_Thin	);
	// キーを選択表示.
	switch( getIndiSelected() ) {
		case TYPE_FS527_AD_PunchAdjDepth_Normal:
			Rbt_PunchStopPosPaperType.select( 0 );
			break;
		case TYPE_FS527_AD_PunchAdjDepth_Thick1_1Plus:
			Rbt_PunchStopPosPaperType.select( 1 );
			break;
		case TYPE_FS527_AD_PunchAdjDepth_Thick2:
			Rbt_PunchStopPosPaperType.select( 2 );
			break;
		case TYPE_FS527_AD_PunchAdjDepth_Thick3:
			Rbt_PunchStopPosPaperType.select( 3 );
			break;
		case TYPE_FS534_AD_PunchAdjCenter_Thick4:
			Rbt_PunchStopPosPaperType.select( BTNID_KEY_SERV_PUCCH_ADJ_CENTER_THICK4 );
			break;
		case TYPE_FS534_AD_PunchAdjCenter_Thin:
			Rbt_PunchStopPosPaperType.select( BTNID_KEY_SERV_PUCCH_ADJ_CENTER_THIN );
			break;
		default:
			break;
	}
	if( False == PLBC_FuncVersionCheck::isOK_MiZe_Type2() ) {
		Key_ServiceTestCopy.showEnable( False );			// テストコピーボタン非表示.
	}
}
//================================================================================================.
// 概要		:サービス・フィニッシャー調整・FS-FN調整・パンチ縦位置(FS-527接続時)：画面遷移キー.
//================================================================================================.
void PServiceFinisherPunchHeightPositionAdjFS527::procGoToPage( uchar option )
{
	switch( option )
	{
		case 99 :			// テストコピーボタン押下.
			// 調整値確定.
			fixPrinterIndi( TYPE_FS527_AD_PunchAdjDepth_Normal	);	// 普通紙.
			fixPrinterIndi( TYPE_FS527_AD_PunchAdjDepth_Thick1_1Plus	);	// 厚紙1.
			fixPrinterIndi( TYPE_FS527_AD_PunchAdjDepth_Thick2	);	// 厚紙2.
			fixPrinterIndi( TYPE_FS527_AD_PunchAdjDepth_Thick3	);	// 厚紙3.
			fixPrinterIndi( TYPE_FS534_AD_PunchAdjCenter_Thick4	);	// 厚紙4.
			fixPrinterIndi( TYPE_FS534_AD_PunchAdjCenter_Thin	);	// 薄紙.
			gp_ServiceTestCopy.setRetGamen( this );		// 戻り先画面.
			nextGamen = &gp_ServiceTestCopy;	// サービス・テストコピー.
			break;
		default:
			// 親クラスの呼出し.
			PServiceFinisherAdjCom::procGoToPage( option );
			break;
	}
}

