//================================================================================================.
// 概要		:サービス・フィニッシャー調整・FS-FN調整・パンチレジストループ量(FS-527(FS-534)接続時)：変数初期化.
//================================================================================================.
void PServiceFinisherPunchRegistLoopAdjMainOther::init_value()
{
	// APIから値取得.
	ss_BakFinisherPunchRegistLoop               = getPrinterIndiInSystem( TYPE_FS534_AD_RegLoopAdjNormal_Normal );
	ss_BakFinisherPunchRegistLoopExcludingNomal = getPrinterIndiInSystem( TYPE_FS534_AD_RegLoopAdjNormal_Thick );	// 2009/1/13 12北畑 管理No.1243(機器案件125).
	ss_BakFinisherPunchRegistLoopThin           = getPrinterIndiInSystem( TYPE_FS534_AD_RegLoopAdjNormal_Thin );
}
//================================================================================================.
// 概要		:サービス・フィニッシャー調整・FS-FN調整・パンチレジストループ量(FS-527接続時)：OKキー.
//================================================================================================.
void PServiceFinisherPunchRegistLoopAdjMainOther::procOk( uchar option )
{
	// 調整値確定.
	fixPrinterIndi( TYPE_FS534_AD_RegLoopAdjNormal_Normal );
	fixPrinterIndi( TYPE_FS534_AD_RegLoopAdjNormal_Thick );	// 2009/1/13 12北畑 管理No.1243(機器案件125).
	fixPrinterIndi( TYPE_FS534_AD_RegLoopAdjNormal_Thin );
// comment 2015/05/05 【HCLT_Thangachamy】【MinervaSBK】【制御構成変更_No.14】 Adding Finisher support for FS-536.
	// 装着フィニッシャーにより画面遷移先を変える
//comment 2018/10/24 HCLT-Jagadeesh [IT6_Eagle] [機器構成変更_No.5] Adding Finisher support for FS-539.
//	if( TYPE_FinisherTypeFS534 == PnlComGetPrinterSystem()->getFinisherType() || TYPE_FinisherTypeFS536 == PnlComGetPrinterSystem()->getFinisherType() ) {
	if( (TYPE_FinisherTypeFS534 == PnlComGetPrinterSystem()->getFinisherType()) || (TYPE_FinisherTypeFS536 == PnlComGetPrinterSystem()->getFinisherType())
		|| (TYPE_FinisherTypeFS539 == PnlComGetPrinterSystem()->getFinisherType()) ) {
		nextGamen = &gp_SvcsFinisherAdjMenuFS534;
	} else {
		nextGamen = &gp_SvcsFinisherAdjMenuFS533;
	}
	// 親クラス呼出し.
	PServiceFinisherAdjCom::procOk( option );
}
//================================================================================================.
// 概要		:サービス・フィニッシャー調整・FS-FN調整・パンチレジストループ量(FS-527接続時)：ボタン(押された).
//================================================================================================.
void PServiceFinisherPunchRegistLoopAdjMainOther::procButtonOn( uchar option )
{
	switch( option ) {
		case BTNID_KEY_ADD_VALUE:					// ＋キー.
			addIndi();
			break;
		case BTNID_KEY_SUB_VALUE:					// －キー.
			subIndi();
			break;
		case BTNID_KEY_SERV_FS534_PUNCH_NORMAL:		// 普通紙キー.
			setPrinterIndi( TYPE_FS534_AD_RegLoopAdjNormal_Normal );
			break;
		case BTNID_KEY_SERV_FS534_PUNCH_THICK:	// 厚紙1/2/3/4キー.
			setPrinterIndi( TYPE_FS534_AD_RegLoopAdjNormal_Thick );
			break;
		case BTNID_KEY_SERV_FS534_PUNCH_THIN:	// 薄紙キー.
			setPrinterIndi( TYPE_FS534_AD_RegLoopAdjNormal_Thin );
			break;
		case 60:									// 元に戻すキー.
			switch( getIndiSelected() ) {
				case TYPE_FS534_AD_RegLoopAdjNormal_Normal:	// 普通紙が選択されている.
					setPrinterIndi( TYPE_FS534_AD_RegLoopAdjNormal_Normal, ss_BakFinisherPunchRegistLoop );
					break;
				case TYPE_FS534_AD_RegLoopAdjNormal_Thick:	// 厚紙1/2/3/4が選択されている.
					setPrinterIndi( TYPE_FS534_AD_RegLoopAdjNormal_Thick, ss_BakFinisherPunchRegistLoopExcludingNomal );
					break;
				case TYPE_FS534_AD_RegLoopAdjNormal_Thin:	// 薄紙が選択されている.
					setPrinterIndi( TYPE_FS534_AD_RegLoopAdjNormal_Thin, ss_BakFinisherPunchRegistLoopThin );
					break;
				default:
					break;
			}
			break;
		default:
			break;
	}
	setupGamen();
}
//================================================================================================.
// 概要		:サービス・フィニッシャー調整・FS-FN調整・パンチレジストループ量(FS-527接続時)：ボタン(押し続け、速く変化).
