void PServiceFinisherPunchRegistLoopAdjMainOther::procButtonStillOnFast( uchar option )
{
	if( BTNID_KEY_ADD_VALUE == option || BTNID_KEY_SUB_VALUE == option ) {	// 2009/1/13 12北畑 管理No.1243(機器案件125).
		procButtonOn( option );
	}
}
//================================================================================================.
// 概要		:サービス・フィニッシャー調整・FS-FN調整・パンチレジストループ量(FS-527接続時)：画面表示セットアップ.
//================================================================================================.
void PServiceFinisherPunchRegistLoopAdjMainOther::setupGamen( short option )
{
	// 親クラスの呼出し.
	PServiceFinisherAdjCom::setupGamen( option );
// comment 2015/03/05 HCLT_SunilNP [HeliosL][CQ509894] adjusting the positions.
// Comment 2017/11/29 【HCLT-Vishal】【Eagle】【制御構成変更_No.4】 Removing old function version check and else portion.
	Bak_SvcsAdjustValueArea1.changeGraphic( PB_SvcsAwNewB );		//new B
	Bak_SvcsAdjustRangeArea1.changeGraphic( PB_SvcsAwNewW );
	Bak_SvcsAdjustValueArea1.changePosition( 492,232 );
	Bak_SvcsAdjustRangeArea1.changePosition( 492, 280 );
	Inp_SvcsFS527PunchAdjValue.changePosition( 530, 244);
	Txt_ServiceAdjustM4ToP4.changePosition( 504, 290 );
	Txt_SvcsFNSAdjStep1.changePosition( 528, 314 );
	Key_PServiceAdjustValueUp.changePosition( 568, 348 );
	Key_PServiceAdjustValueDown.changePosition( 492, 348 );		
	// 調整値エリア.
	Inp_SvcsFS527PunchAdjValue          = ( float )getPrinterIndi( getIndiSelected() );
	Bak_SvcsFS527PunchNowValueNormal    = ( float )getPrinterIndi( TYPE_FS534_AD_RegLoopAdjNormal_Normal );
	Bak_SvcsFS527PunchNowValueNotNormal = ( float )getPrinterIndi( TYPE_FS534_AD_RegLoopAdjNormal_Thick );
	Bak_SvcsTepe1PunchNowValueThin 		= ( float )getPrinterIndi( TYPE_FS534_AD_RegLoopAdjNormal_Thin );
	switch( getIndiSelected() ) {
		case TYPE_FS534_AD_RegLoopAdjNormal_Normal:	Rbt_SvcsFS527PunchPaperKindSel.select( 0 );	break;
		case TYPE_FS534_AD_RegLoopAdjNormal_Thick:	Rbt_SvcsFS527PunchPaperKindSel.select( 1 );	break;
		case TYPE_FS534_AD_RegLoopAdjNormal_Thin:	Rbt_SvcsFS527PunchPaperKindSel.select( 2 );	break;
		default:	break;
	}
}
