void PServiceFinisherAdjMenuFS533::procGoToPage( uchar option )
{
	switch( option ) {
		case	BTNID_KEY_SERV_FS_FINISHER_CHECK:	// サービス・フィニッシャ調整・フィニッシャチェック
			bl_isRequestInitialize = True ;	// 初期設定フラグON
			// フィニッシャチェック.
			nextGamen = &gp_ServiceFSFNFinisherCheck ;
			break ;
		case	BTNID_KEY_SERV_ALIGNMENT_PLATE_POSITION:		// サービス・フィニッシャー調整・整合板位置.
			bl_isRequestInitialize = True;	// 初期設定フラグON.
			// 整合板位置.
			nextGamen = &gp_ServiceFinisherAlignmentPlatePosition;
			break;
		case	BTNID_KEY_SERV_PUNCH_REGIST_LOOP_MAIN:			// サービス・フィニッシャー調整・パンチレジスト量.
			bl_isRequestInitialize = True;	// 初期設定フラグON.
			// パンチレジストループ調整.
			nextGamen = &gp_SvcsPunchRegistLoopAdjMainOther;
			break;
		default:
			break;
	}
}
