//================================================================================================.
// 概要 : 60C00190 フィニッシャー調整／FS－FN調整／整合板位置調整 : ボタン(押された).
//================================================================================================.
void PServiceFinisherAlignmentPlatePosition::procButtonOn( uchar option )
{
	switch( option ) {
// 2016/02/15 HCLT-Pushp Raj CQ524365. Screen No:-60C00190_VeM START.
#ifndef DEF_A4_Cus
		case BTNID_KEY_SERV_ALIGN_PLATE_POS_BACK:
			setPrinterIndi( TYPE_FS529_AD_AdjustBoardPosR );	// 整合板位置(奥).
			break;
		case BTNID_KEY_SERV_ALIGN_PLATE_POS_FRONT:
			setPrinterIndi( TYPE_FS529_AD_AdjustBoardPosF );	// 整合板位置(手前).
			break;
#else
		case BTNID_KEY_SERV_ALIGN_PLATE_POS_BACK:
			setPrinterIndi( TYPE_PrinterAdjustVenusFinisherPlatePositionRear );	// フィニッシャー調整値【全体】先端整合位置調整.
			break;
		case BTNID_KEY_SERV_ALIGN_PLATE_POS_FRONT:
			setPrinterIndi( TYPE_PrinterAdjustVenusFinisherPlatePositionFront );	// フィニッシャー調整値【全体】手前整合位置調整.
			break;
#endif
// 2016/02/15 HCLT-Pushp Raj CQ524365. Screen No:-60C00190_VeM END.
		case 100:	// +キー.
			addIndi();
			break;
		case 101:	// -キー.
			subIndi();
			break;
		case 60:	// 元に戻すキー.
			switch( getIndiSelected() ) {
// 2016/02/15 HCLT-Pushp Raj CQ524365. Screen No:-60C00190_VeM START.
#ifndef DEF_A4_Cus
				case TYPE_FS529_AD_AdjustBoardPosR:
					setPrinterIndi( TYPE_FS529_AD_AdjustBoardPosR, ss_BakFinisherAlignmentPlatePositionBack );
					break;
				case TYPE_FS529_AD_AdjustBoardPosF:
					setPrinterIndi( TYPE_FS529_AD_AdjustBoardPosF, ss_BakFinisherAlignmentPlatePositionFront );
					break;
#else
				case TYPE_PrinterAdjustVenusFinisherPlatePositionRear:
					setPrinterIndi( TYPE_PrinterAdjustVenusFinisherPlatePositionRear, ss_BakFinisherAlignmentPlatePositionBack );
					break;
				case TYPE_PrinterAdjustVenusFinisherPlatePositionFront:
					setPrinterIndi( TYPE_PrinterAdjustVenusFinisherPlatePositionFront, ss_BakFinisherAlignmentPlatePositionFront );
					break;
#endif
// 2016/02/15 HCLT-Pushp Raj CQ524365. Screen No:-60C00190_VeM END.
				default:
					break;
			}
			break;
		default:
			break;
	}
	setupGamen();
}
