// 備考	:	2015/02/04 Sky大熊 AS-PDV_38.
//==============================================================================================.
void PServiceFSVenusAdjustHorizontalPosition::procButtonOn( uchar option )
{
	switch( option ){
	case BTNID_VFNS_BINDINGPOSITION_KEY_00:
		setPrinterIndi( TYPE_PrinterAdjustVenusFinisherHorizontalPositionAll		);	// 全体.
		ss_select = 0;
		break;
	case BTNID_VFNS_BINDINGPOSITION_KEY_01:
		setPrinterIndi( TYPE_PrinterAdjustVenusFinisherHorizontalPositionA4SEF		);	// A4.
		ss_select = 1;
		break;
	case BTNID_VFNS_BINDINGPOSITION_KEY_02:
		setPrinterIndi( TYPE_PrinterAdjustVenusFinisherHorizontalPositionB5SEF		);	// B5.
		ss_select = 2;
		break;
	case BTNID_VFNS_BINDINGPOSITION_KEY_03:
		setPrinterIndi( TYPE_PrinterAdjustVenusFinisherHorizontalPositionLegalSEF	);	// 8.5x14 SEF.
		ss_select = 3;
		break;
	case BTNID_VFNS_BINDINGPOSITION_KEY_04:
		setPrinterIndi( TYPE_PrinterAdjustVenusFinisherHorizontalPositionLetterSEF	);	// 8.5x11 SEF.
		ss_select = 4;
		break;
	case BTNID_VFNS_BINDINGPOSITION_KEY_05:
		setPrinterIndi( TYPE_PrinterAdjustVenusFinisherHorizontalPositionCustom		);	// 不定形.
		ss_select = 5;
		break;
	case 100:	addIndi();	break;	// +キー.
	case 101:	subIndi();	break;	// -キー.
	case 60:	// 元に戻すキー.
		switch( getIndiSelected() ){
		case TYPE_PrinterAdjustVenusFinisherHorizontalPositionAll:			setPrinterIndi( TYPE_PrinterAdjustVenusFinisherHorizontalPositionAll,       ss_BakFinisherHorizontalPosition00 );	break;
		case TYPE_PrinterAdjustVenusFinisherHorizontalPositionA4SEF:		setPrinterIndi( TYPE_PrinterAdjustVenusFinisherHorizontalPositionA4SEF,     ss_BakFinisherHorizontalPosition01 );	break;
		case TYPE_PrinterAdjustVenusFinisherHorizontalPositionB5SEF:		setPrinterIndi( TYPE_PrinterAdjustVenusFinisherHorizontalPositionB5SEF,     ss_BakFinisherHorizontalPosition02 );	break;
		case TYPE_PrinterAdjustVenusFinisherHorizontalPositionLegalSEF:		setPrinterIndi( TYPE_PrinterAdjustVenusFinisherHorizontalPositionLegalSEF,  ss_BakFinisherHorizontalPosition03 );	break;
		case TYPE_PrinterAdjustVenusFinisherHorizontalPositionLetterSEF:	setPrinterIndi( TYPE_PrinterAdjustVenusFinisherHorizontalPositionLetterSEF, ss_BakFinisherHorizontalPosition04 );	break;
		case TYPE_PrinterAdjustVenusFinisherHorizontalPositionCustom:		setPrinterIndi( TYPE_PrinterAdjustVenusFinisherHorizontalPositionCustom,    ss_BakFinisherHorizontalPosition05 );	break;
		default:		break;
		}
		break;
	default: PServiceFinisherAdjCom::procButtonOn( option ); break;
	}
	setupGamen();
}
