void PServiceFSVenusAlignmentPlatePosition::init_value()
{
	//APIから設定値を取得.
	ss_BakFinisherAlignmentPlatePositionBack = getPrinterIndiInSystem( TYPE_PrinterAdjustVenusFinisherPlatePositionRear );		// 整合板位置(奥).
	ss_BakFinisherAlignmentPlatePositionFront = getPrinterIndiInSystem( TYPE_PrinterAdjustVenusFinisherPlatePositionFront );	// 整合板位置(手前).
}
//================================================================================================.
// 概要 : 201F4000 フィニッシャー調整／FSFN調整／整合板位置調整 : ボタン(押された).
// 備考 : 2015/02/03 Sky大熊 AS-PDV_37.
//================================================================================================.
void PServiceFSVenusAlignmentPlatePosition::procButtonOn( uchar option )
{
	switch( option ){
	case BTNID_KEY_SERV_ALIGN_PLATE_POS_BACK:
		setPrinterIndi( TYPE_PrinterAdjustVenusFinisherPlatePositionRear );		// 整合板位置(奥).
		break;
	case BTNID_KEY_SERV_ALIGN_PLATE_POS_FRONT:
		setPrinterIndi( TYPE_PrinterAdjustVenusFinisherPlatePositionFront );	// 整合板位置(手前).
		break;
	case 100:	// +キー.
		addIndi();
		break;
	case 101:	// -キー.
		subIndi();
		break;
	case 60:	// 元に戻すキー.
		switch( getIndiSelected() ) {
		case TYPE_PrinterAdjustVenusFinisherPlatePositionRear:
			setPrinterIndi( TYPE_PrinterAdjustVenusFinisherPlatePositionRear, ss_BakFinisherAlignmentPlatePositionBack );
			break;
		case TYPE_PrinterAdjustVenusFinisherPlatePositionFront:
			setPrinterIndi( TYPE_PrinterAdjustVenusFinisherPlatePositionFront, ss_BakFinisherAlignmentPlatePositionFront );
			break;
		default: 
			break;
		}
		printf( "[%s] %d: indi=[%d].\n", __PRETTY_FUNCTION__, __LINE__, getIndiSelected() );
		break;
	default: 
		break;
	}
	setupGamen();
}
//================================================================================================.
// 概要 : 201F4000 フィニッシャー調整／FSFN調整／整合板位置調整  : ボタン(押し続け、速く変化).
// 備考 : 2015/02/03 Sky大熊 AS-PDV_37.
//================================================================================================.
void PServiceFSVenusAlignmentPlatePosition::procButtonStillOnFast( uchar option )
{
	if( option == 100 || option == 101 ) { procButtonOn( option ); }
}
