//================================================================================================.
// 概要	:	201F5000 フィニッシャー調整／FSFN調整／用紙カール補正 ローカル定数定義.
// 備考	:	2015/02/09 Sky大熊 AS-PDV_38.
//================================================================================================.
#define	PNLD_PaperCurlNone				0		// 補正しない.
#define	PNLD_PaperCurlConditionally		1		// 高温高湿時のみ.
#define	PNLD_PaperCurlAlways			2		// 常に補正.
#define	PNLD_PaperCurlEffectSmall		0		// 小さい.
#define	PNLD_PaperCurlEffectBig			1		// 大きい.
#define	PNLD_PaperCurlEnableButtons		3		// 補正条件 ボタン数.
#define	PNLD_PaperCurlEffectButtons		2		// 補正効果 ボタン数.
//================================================================================================.
// 概要	:	201F5000 フィニッシャー調整／FSFN調整／用紙カール補正.
// 備考	:	2015/02/09 Sky大熊 AS-PDV_38.
//================================================================================================.
void PServiceFSVenusSmoothPaperCurling::startGamen()
{
	PBasicMessageProc::startGamen();
	// カール低減PPMチョイス取得.
	ss_Select = PnlComGetPrinterServiceSetting()->getPrinterAdjust( TYPE_PrinterAdjustCurlChoice );
// Comment 2020/01/29 [HCLT-Ranjith] [IT6_SparrowBK] [KLOC ID:74611]  Switch without break.
	switch( ss_Select ) {
	case TYPE_PaperCurlingPreventModeOff:			// なし(デフォルト).
		uc_Mode = PNLD_PaperCurlNone;				// 補正しない.
		uc_Effect = PNLD_PaperCurlEffectSmall;		// 小さい.
		break;
	case TYPE_PaperCurlingPreventMode1:				// 補正弱(高温高湿時のみ).
		uc_Mode = PNLD_PaperCurlConditionally;		// 高温高湿時のみ補正.
		uc_Effect = PNLD_PaperCurlEffectSmall;		// 小さい.
		break;
	case TYPE_PaperCurlingPreventMode2:				// 補正強(高温高湿時のみ).
		uc_Mode = PNLD_PaperCurlConditionally;		// 高温高湿時のみ補正.
		uc_Effect = PNLD_PaperCurlEffectBig;		// 大きい.
		break;
	case TYPE_PaperCurlingPreventMode3:				// 補正弱(常時).
		uc_Mode = PNLD_PaperCurlAlways;				// 常に補正.
		uc_Effect = PNLD_PaperCurlEffectSmall;		// 小さい.
		break;
	case TYPE_PaperCurlingPreventMode4:				// 補正強(常時).
		uc_Mode = PNLD_PaperCurlAlways;				// 常に補正.
		uc_Effect = PNLD_PaperCurlEffectBig;		// 大きい.
		break;
//	default:	;									// エラー処理.
	default:	break;								// エラー処理.
	}
}
//================================================================================================.
// 概要	:	201F5000 フィニッシャー調整／FSFN調整／用紙カール補正.
// 備考	:	2015/02/09 Sky大熊 AS-PDV_38.
//================================================================================================.
void PServiceFSVenusSmoothPaperCurling::procButtonOn( uchar option )
{
	static short ss_ChoiceTable[PNLD_PaperCurlEnableButtons][PNLD_PaperCurlEffectButtons] = {
		{ TYPE_PaperCurlingPreventModeOff,	TYPE_PaperCurlingPreventModeOff },
		{ TYPE_PaperCurlingPreventMode1,	TYPE_PaperCurlingPreventMode2   },
		{ TYPE_PaperCurlingPreventMode3,	TYPE_PaperCurlingPreventMode4   },
	};
	// 押下されたボタンを調べて選択状態を更新する.
// Comment 2020/01/29 [HCLT-Ranjith] [IT6_SparrowBK] [KLOC ID:74612]  Switch without break.
	switch( option ) {
	case BTNID_ServicePaperCurlNone:						// 補正しない.
		uc_Mode = PNLD_PaperCurlNone;
		uc_Effect = PNLD_PaperCurlEffectSmall;
		ss_Select = ss_ChoiceTable[uc_Mode][uc_Effect];
		break;
	case BTNID_ServicePaperCurlConditionally:				// 高温高湿時のみ補正.
		uc_Mode = PNLD_PaperCurlConditionally;
		ss_Select = ss_ChoiceTable[uc_Mode][uc_Effect];
		break;
	case BTNID_ServicePaperCurlAlways:						// 常に補正.
		uc_Mode = PNLD_PaperCurlAlways;
		ss_Select = ss_ChoiceTable[uc_Mode][uc_Effect];
		break;
	case BTNID_ServicePaperCurlEffectSmall:					// 小さい.
		uc_Effect = PNLD_PaperCurlEffectSmall;
		ss_Select = ss_ChoiceTable[uc_Mode][uc_Effect];
		break;
	case BTNID_ServicePaperCurlEffectBig:					// 大きい.
		uc_Effect = PNLD_PaperCurlEffectBig;
		ss_Select = ss_ChoiceTable[uc_Mode][uc_Effect];
		break;
//	default:	;									// エラー処理.
	default:	break;								// エラー処理.
	}
	setupGamen( option );
}
//================================================================================================.
// 概要	:	201F5000 フィニッシャー調整／FSFN調整／用紙カール補正.
// 備考	:	2015/02/09 Sky大熊 AS-PDV_38.
//================================================================================================.
void PServiceFSVenusSmoothPaperCurling::procOk( uchar option )
{
	// カール低減PPMチョイス設定.
	PnlComGetPrinterServiceSetting()->setPrinterAdjust( TYPE_PrinterAdjustCurlChoice, ss_Select );

	// サービス・フィニッシャ調整.
	nextGamen = &gp_ServiceFSVenusAdjustMenu;
}
//================================================================================================.
// 概要	:	201F5000 フィニッシャー調整／FSFN調整／用紙カール補正.
// 備考	:	2015/02/09 Sky大熊 AS-PDV_38.
//================================================================================================.
void PServiceFSVenusSmoothPaperCurling::setupGamen( short option )
{
	// 親クラスの呼出し.
	PServiceFinisherAdjCom::setupGamen( option );

	// 表示状態更新.
	if( PNLD_PaperCurlNone == uc_Mode ) {
		Txt_ServiceFSVenusSmoothingEffect.showEnable( False );
		Rbt_ServiceSmoothingEffectSelect.showEnable( False );
	} else {
		Txt_ServiceFSVenusSmoothingEffect.showEnable( True );
		Rbt_ServiceSmoothingEffectSelect.showEnable( True );
	}
	Rbt_ServiceSmoothingEnableSelect.select( uc_Mode );
	Rbt_ServiceSmoothingEffectSelect.select( uc_Effect );
}
#endif
