/*================================================================================================
// 概要		:サービス・課金設定・OpenAPI認証管理設定・禁止コード設定 : ボタン(押された).
// 戻り値	:なし.
// 備考		:
================================================================================================*/
void PServiceActionOAPAttestationRestrictionCodeList::procButtonOn( uchar option )
{
	if( option >= 1 && option <= 10 ) {							// 禁止コードを選択した場合.
		ss_Select = ( short )option;
	} else if( option == 11 ) {									// 削除キーを押下した場合.
		if( ss_Select != 0 ) {									// 禁止コードが選択さている場合.
			APIC_LicenseInfoSetting* pc_LicenseInfoSetting = APIC_LicenseInfoSetting::newInstance();		// インスタンス生成.
			pc_LicenseInfoSetting->deleteRestrictionCode( ( uchar )( ss_Select - 1 ) );						// 禁止コード削除処理を呼ぶ.
			APIC_JLG* pc_JLG = APIC_JLG::newInstance();														// インスタンス生成.
			if( pc_JLG != NULL ) {
				JLGS_OpeLogCom s_OpeLogCom;																	// ログ作成.
				memset( &s_OpeLogCom, 0x00, sizeof( s_OpeLogCom ) );

				s_OpeLogCom.ul_Code		= JLGE_InspectLogDeleteRestrictionList;					// 操作コード.
				pc_JLG->getNowTime( &s_OpeLogCom.s_Time );										// 操作日時.
				s_OpeLogCom.us_Result	= JLGE_InspectLogResultOK;								// 結果コード.
// 2016/02/01 CQ521285 監査ログHCD-PP対応	Sky平田	Start.
				s_OpeLogCom.us_EventType = getEventTypeByResultCode( s_OpeLogCom.us_Result );
// 2016/02/01 CQ521285 監査ログHCD-PP対応	Sky平田	End.
				s_OpeLogCom.ul_OpeCode	= JLGE_InspectLogOperateIDL_CE;							// 操作者コード.
				s_OpeLogCom.uc_IF		= JLGE_InspectLogIfOperationPanel;						// I/F番号.
				// 監査ログ登録.
				pc_JLG->addOpeLog( &s_OpeLogCom );
			} else {
				// JLGS_OpeLogComの取得に失敗.
				LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
			}
			ss_Select = 0;
			b_OpenAPIVer31 = getOpenAPIVer31();					// OpenAPI3.1以降のバージョンチェック.
		} else if( ss_Select == 0 ) {							// 禁止コードが選択されていない場合.
			MCR_setBuzzerType( PCGE_BuzzerType_InputNg );		// 受付禁止音.
			return;
		}
	} else {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );			// 受付禁止音.
		return;
	}

	setupGamen();
}
/*================================================================================================
// 概要		:サービス・課金設定・OpenAPI認証管理設定・禁止コード設定 : OpenAPI3.1以降のバージョンチェック.
// 戻り値	:なし.
// 備考		:OpenAPIV3.5以降のバージョンチェックに処理内容変更.//【CMS対応】【35_OpenAPI認証管理】【第2電情技_和田】備考欄に追記のみ.
================================================================================================*/
Bool PServiceActionOAPAttestationRestrictionCodeList::getOpenAPIVer31( )
{
	Bool b_ret = False;
	for( int AppNo = 1; AppNo <= TYPD_ExtMaxApplication; AppNo++ ) {
		APIC_ExtSetting* pc_ExtSetting = APIC_ExtSetting::newInstance( AppNo );								// インスタンス生成.
		if( pc_ExtSetting == NULL || pc_ExtSetting->getApplication().e_Entry == TYPE_ExtEntryOff ) {		// インスタンスNULLまたはアプリが登録させていない場合.
//Comment 2016/01/07 HCL_Krithika [ZeusS_ZX0][制御構成変更_No.76-1] Not required case.
//// Comment 2015/11/02 【ZeusS_ZX0】【HCL_Vasu】【制御構成変更_No.76-1】Adding Error Code macro.
//			LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//			if (NULL !=pc_BFW_System){
//				pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x1900650101368401 );
//			}
			continue;
		}
		if( pc_ExtSetting->getApplication().s_Version.ss_Major >= 4 ) {									// メジャーバージョン4以上.
			b_ret = True;
			break;
		} else if( pc_ExtSetting->getApplication().s_Version.ss_Major == 3 ) {								// メジャーバージョン3.
			if( pc_ExtSetting->getApplication().s_Version.ss_Minor >= 5 ) {								// マイナーバージョン１以上.
				b_ret = True;
				break;
			}
		}
	}
	return b_ret;
}
