/*================================================================================================
// 概要		:サービス・課金設定・OpenAPI認証管理設定・Regionコード設定: 初期設定.
// 戻り値	:なし.
// 備考		:
================================================================================================*/
void PServiceActionOAPAttestationRegionCodeList::startGamen()
{
	PServiceActionVendorSetCom::startGamen();	// 親クラスの処理を呼ぶ.
	APIC_LicenseInfoSetting* pc_LicenseInfoSetting = APIC_LicenseInfoSetting::newInstance();	// インスタンス生成.
	if( NULL != pc_LicenseInfoSetting ) {
		uchar* p_RegionCode = pc_LicenseInfoSetting->getRegionCode( e_RegionCodeStatus );			// Regionコード取得.	// 【CMS対応】【35_OpenAPI認証管理】【第2電情技_和田】modify.
		if( NULL == p_RegionCode ) { 
//2019/06/17 Comment [HCLT_Krishnakumar][EagleH][N Rank] Removed unwanted detailed code.
//// 2015/11/05 【HCLT-Dhivya】 【ZeusS_ZX0】 【制御構成変更_No.76-1】Detail macro is passed in API.
//			LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//			if (NULL != pc_BFW_System){
//    			pc_BFW_System->registDetailCode(PNLD_DetailCode_Service_0x1900650101471801);
//			}
			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" ); 
			return; 
		}
		memcpy( uc_RegionCode, p_RegionCode, TYPD_RegionCodeLength + 1 );							// Regionコード設定.
	}
}
/*================================================================================================
// 概要		:サービス・課金設定・OpenAPI認証管理設定・Regionコード設定 : 表示部品のセットアップ.
// 戻り値	:なし.
// 備考		:
================================================================================================*/
void PServiceActionOAPAttestationRegionCodeList::setupGamen( short option )
{
	PServiceActionVendorSetCom::setupGamen();								// 親クラスの処理を呼ぶ.
	APIC_SoftDipSw* pc_SoftDipSw = APIC_SoftDipSw::newInstance();			// DipSw（API）・インスタンス生成.

	// SW 設定でRegionコードが表示不可の場合.
	if( pc_SoftDipSw->getSoftDipSwBit( 17, 3 ) == False ) {
		uchar uc_Code[TYPD_RegionCodeLength + 1];
		memset( &uc_Code, 0x00, TYPD_RegionCodeLength + 1 );				// 初期化.
		memset( &uc_Code , 0x2a, TYPD_RegionCodeLength );					// "*"を設定する.
		Tfd_ServRegionCodeLine.changeASCIIText( ( uchar* ) uc_Code );			// "*"を表示する .
	} else {
		Tfd_ServRegionCodeLine.changeASCIIText( ( uchar* ) uc_RegionCode );	// Regionコードを表示する.
	}

	Key_ServRegionCode2.select( True );		// Regionコードキーを反転.

}
