/*================================================================================================
// 概要		:サービス・課金設定・OapAPI認証管理キーボード入力共通: テンキー.
// 戻り値	:なし
// 備考		:
================================================================================================*/
void PServiceActionOAPAttestationKeyboardcom::proc10Key( uchar option )
{
	char	_sc_Num[ 2 ];
	memset( _sc_Num, 0, sizeof( _sc_Num ) );
	Kbd_ServiceInputKeybord.proc10Key( &option );						// サービス専用キーボード共通テンキー.
	if( option <= 9 ) {
// Comment 2015/10/21【HCLT-Meera】【CQ519679】【ID: 28746, 28747】ABV.GENERAL.
//		sprintf( ( char* )_sc_Num, "%d", option );							// 数値を文字に変換.
        snprintf( ( char* )_sc_Num, sizeof( _sc_Num ), "%d", option );		// 数値を文字に変換.
		c_SlideTextMgr.insertStr( sc_StrKeyboard, ( char* )_sc_Num );		// 文字を追加.
	}
	setupGamen();
}
/*================================================================================================
// 概要		:サービス・課金設定・OapAPI認証管理キーボード入力共通: キーボード.
// 戻り値	:なし.
// 備考		:
================================================================================================*/
void PServiceActionOAPAttestationKeyboardcom::procKeyBoard( uchar option )
{
	char	_sc_keyCode[3];
	memset( _sc_keyCode, '\0', sizeof( _sc_keyCode ) );					// キーコード初期化.
	Kbd_ServiceInputKeybord.getKeyString( option, _sc_keyCode );	// キーコードを取得.

	if( c_SlideTextMgr.getStatus() == True ) {
		c_SlideTextMgr.setStatus( False );		// 入力中状態に変更.
		c_SlideTextMgr.init_CLCD( sc_StrKeyboard, sc_KeyboardWidth, ss_MaxInputNum, pa_DispField, EP_CharSet_USASCII );	// スライド文字列管理クラスの初期化.
	}

	switch( _sc_keyCode[0] ) {
		case PLBD_ArrowLeftKeyCode:	c_SlideTextMgr.selectArrow( True, sc_StrKeyboard );			break;	// ←キー押下：カーソル位置を左に移動.
		case PLBD_ArrowRighKeyCode:	c_SlideTextMgr.selectArrow( False, sc_StrKeyboard );			break;	// →キー押下：カーソル位置を右に移動.
		case PLBD_DeleteKeyCode:	c_SlideTextMgr.deleteStr( sc_StrKeyboard );					break;	// Delキー押下：一文字消去.
		case PLBD_KeyCodeNone:																	break;	// キー入力を無視する(無処理).
		default:
			if( True == PLBC_FuncVersionCheck::isOK_Type3() ) {
				c_SlideTextMgr.insertStr( sc_StrKeyboard, _sc_keyCode, Kbd_ServiceInputKeybord.getConvCharSetNativeToUniCode() );
			} else {
				c_SlideTextMgr.insertStr( sc_StrKeyboard, _sc_keyCode );
			}
	}
// 自クラスで、親クラスのsetupGamen処理を行っているので削除.
	setupGamen();
}
