//================================================================================================.
// 概要 : 60E00001 工場調整モード／SoftwareSwitch : コンストラクタ.
//================================================================================================.
PFactorySoftwareSwitch::PFactorySoftwareSwitch( PDisplayParts** partsTable, short partsNumber, Bool isNoWarningGamen ):
	PServiceToTopMenuCom( partsTable, partsNumber, isNoWarningGamen )
{
	uc_SelectSWNo = 0;
	memset( uc_SwitchVal, 0, sizeof( uc_SwitchVal ) );
}

//================================================================================================.
// 概要 : 60E00001 工場調整モード／SoftwareSwitch : 画面開始処理.
//================================================================================================.
void PFactorySoftwareSwitch::startGamen()
{
	PServiceToTopMenuCom::startGamen();		// 親クラスの処理を呼ぶ.

	uc_SelectSWNo = BTNID_FactorySoftwareSwitchNo_10;	// SW No.10キーを初期値とする.

	// Software Switch の値を取得する.
	APIC_SoftDipSw* pc_SoftDipSw = APIC_SoftDipSw::newInstance();	// DipSw（API）・インスタンス取得.

	// SoftSW 10 の取得.
	uc_SwitchVal[PNLE_FactorySoftwareSwitch_10] = BTNID_FactorySoftwareSwitchVal_1;			// SW 10 = 0x00. Generic一般.
	if( True == pc_SoftDipSw->getSoftDipSwBit( 3, 2 ) ) {
		uc_SwitchVal[PNLE_FactorySoftwareSwitch_10] = BTNID_FactorySoftwareSwitchVal_0;		// SW 10 = 0x02. OWN.
	}
	if( True == pc_SoftDipSw->getSoftDipSwBit( 4, 1 ) ) {
		uc_SwitchVal[PNLE_FactorySoftwareSwitch_10] = BTNID_FactorySoftwareSwitchVal_2;	// SW 10 = 0x04. Generic/Develop.
	}
	if( True == pc_SoftDipSw->getSoftDipSwBit( 4, 2 ) ) {
		uc_SwitchVal[PNLE_FactorySoftwareSwitch_10] = BTNID_FactorySoftwareSwitchVal_3;	// SW 10 = 0x08. Generic/Oce.
	}

	// SoftSW 11 の取得.
	uc_SwitchVal[PNLE_FactorySoftwareSwitch_11] = BTNID_FactorySoftwareSwitchVal_0;			// 起動画面を SoftSW 10 の設定通りとする.
	if( True == pc_SoftDipSw->getSoftDipSwBit( 2, 5 ) ) {
		uc_SwitchVal[PNLE_FactorySoftwareSwitch_11] = BTNID_FactorySoftwareSwitchVal_1;		// 起動画面を強制的にGeneric(宇宙画面)にする.
	}
	if( True == pc_SoftDipSw->getSoftDipSwBit( 3, 3 ) ) {
		uc_SwitchVal[PNLE_FactorySoftwareSwitch_11] = BTNID_FactorySoftwareSwitchVal_2;		// 起動画面を強制的にOWN(ロゴ画面)にする.
	}
	if( True == pc_SoftDipSw->getSoftDipSwBit( 2, 5 )
	    && True == pc_SoftDipSw->getSoftDipSwBit( 3, 3 ) ) {
		uc_SwitchVal[PNLE_FactorySoftwareSwitch_11] = BTNID_FactorySoftwareSwitchVal_0;		// 起動画面を SoftSW 10 の設定通りとする.
	}

	// SoftSW 25 の取得.
	if( ( True == pc_SoftDipSw->getSoftDipSwBit( 19, 2 ) )
	    && ( True == pc_SoftDipSw->getSoftDipSwBit( 19, 1 ) ) ) {
		uc_SwitchVal[PNLE_FactorySoftwareSwitch_25] = BTNID_FactorySoftwareSwitchVal_3;		// DonauBK.
	}
	if( True == b_MmbNeedCount ) {			// 秒数カウントが必要な場合            （CQ.319181_tAppInitのexception回避）.
		uc_MmbCountTime = 0;				// 確定キーを表示するまでの時間を初期化（CQ.319181_tAppInitのexception回避）.
	}										// （CQ.319181_tAppInitのexception回避）.
}

//================================================================================================.
// 概要 : 60E00001 工場調整モード／SoftwareSwitch : 表示画面のセットアップ.
//================================================================================================.
void PFactorySoftwareSwitch:: setupGamen( short option )
{
	PServiceToTopMenuCom::setupGamen();		// 親クラスの処理を呼ぶ.


	switch( uc_SelectSWNo ) {	// 現在選択中のSW番号.
		case BTNID_FactorySoftwareSwitchNo_10:	// SW No.10キー.
			Rbt_FactorySoftwareSWNo.select( 0 );				// SW No.10キー選択.
			Txt_TitleFactorySoftSwNo.changeText( s_KEYSWNo10 );	//「SW No.10」.
			Key_FactorySoftwareSWVal_2.showEnable( True );		//「２」キーを表示.
			Key_FactorySoftwareSWVal_3.showEnable( True );		//「３」キーを表示.
			Rbt_FactorySoftwareSWVal.select( ( short )uc_SwitchVal[PNLE_FactorySoftwareSwitch_10] );	// 値を表すキーの選択.
			break;

		case BTNID_FactorySoftwareSwitchNo_11:	// SW No.11キー.
			Rbt_FactorySoftwareSWNo.select( 1 );				// SW No.11キー選択.
			Txt_TitleFactorySoftSwNo.changeText( s_KEYSWNo11 );	//「SW No.11」
			Key_FactorySoftwareSWVal_2.showEnable( True );		//「２」キーを非表示.
			Key_FactorySoftwareSWVal_3.showEnable( False );		//「３」キーを非表示. CQ.317776 2009/5/25 第1オフィスSW開発 北畑.
			Rbt_FactorySoftwareSWVal.select( ( short )uc_SwitchVal[PNLE_FactorySoftwareSwitch_11] );	// 値を表すキーの選択.
			break;


		default:
			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
			break;
	}
	Bool b_ShowSWFixed = ( ( False == b_MmbNeedCount ) ? True : False );	// 確定キーの表示/非表示切替え（CQ.319181_tAppInitのexception回避）.
	Key_FactorySoftwareSWFixed.showEnable( b_ShowSWFixed );					// （CQ.319181_tAppInitのexception回避）.
}

//================================================================================================.
// 概要 : 60E00001 工場調整モード／SoftwareSwitch : ボタン押下処理.
//================================================================================================.
void PFactorySoftwareSwitch::procButtonOn( uchar option )
{
	APIC_SoftDipSw* pc_SoftDipSw = APIC_SoftDipSw::newInstance();	// DipSw（API）・インスタンス取得.
	if( NULL == pc_SoftDipSw ) { 
//2019/06/17 Comment [HCLT_Krishnakumar][EagleH][N Rank] Removed unwanted detailed code.
//// 2015/11/05 【HCLT-Dhivya】 【ZeusS_ZX0】 【制御構成変更_No.76-1】Detail macro is passed in API.
//		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if (NULL != pc_BFW_System){
//    		pc_BFW_System->registDetailCode(PNLD_DetailCode_Service_0x19000A0112071901);
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" ); 
		return; 
	}

	// SW No.キー, 0,1,2キー押下.
	switch( option ) {
		case BTNID_FactorySoftwareSwitchNo_10:	// SW No.10キー.
		case BTNID_FactorySoftwareSwitchNo_11:	// SW No.11キー.
			uc_SelectSWNo = option;
			break;
		case BTNID_FactorySoftwareSwitchVal_0:	// 0 キー.
		case BTNID_FactorySoftwareSwitchVal_1:	// 1 キー.
		case BTNID_FactorySoftwareSwitchVal_2:	// 2 キー.
		case BTNID_FactorySoftwareSwitchVal_3:	// 3 キー.  CQ.317776 2009/5/25 第1オフィスSW開発 北畑.
			switch( uc_SelectSWNo ) {	// 現在選択中のSW番号.
				case BTNID_FactorySoftwareSwitchNo_10: uc_SwitchVal[PNLE_FactorySoftwareSwitch_10] = option; break;	// SW No.10の値を保存.
				case BTNID_FactorySoftwareSwitchNo_11: uc_SwitchVal[PNLE_FactorySoftwareSwitch_11] = option; break;	// SW No.11の値を保存.
				default: break;
			}
			break;
		case BTNID_FactorySoftwareSWFixed:		// 確定キー.
			switch( uc_SelectSWNo ) {	// 現在選択中のSW番号.
				case BTNID_FactorySoftwareSwitchNo_10:		// SoftSW 10 の保存.
					{
// comment 2016/06/22 SCD2-Sky谷光 [ZeusSBK][CQ528682].
						//pc_SoftDipSw->setSoftDipSwBit( 1, 1, False );
						//pc_SoftDipSw->setSoftDipSwBit( 3, 2, ( BTNID_FactorySoftwareSwitchVal_0 == uc_SwitchVal[PNLE_FactorySoftwareSwitch_10] ) ? True : False );
						//pc_SoftDipSw->setSoftDipSwBit( 4, 1, ( BTNID_FactorySoftwareSwitchVal_2 == uc_SwitchVal[PNLE_FactorySoftwareSwitch_10] ) ? True : False );
						//pc_SoftDipSw->setSoftDipSwBit( 4, 2, ( BTNID_FactorySoftwareSwitchVal_3 == uc_SwitchVal[PNLE_FactorySoftwareSwitch_10] ) ? True : False );
						//ppc_SystemInfo->chkAndSetOwnOrGeneric();		// OwnかGenericかを判定し結果を不揮発領域に書き込む.
						Bool b_SoftDipSwBit3_2 = ( BTNID_FactorySoftwareSwitchVal_0 == uc_SwitchVal[PNLE_FactorySoftwareSwitch_10] ) ? True : False;
						Bool b_SoftDipSwBit4_1 = ( BTNID_FactorySoftwareSwitchVal_2 == uc_SwitchVal[PNLE_FactorySoftwareSwitch_10] ) ? True : False;
						Bool b_SoftDipSwBit4_2 = ( BTNID_FactorySoftwareSwitchVal_3 == uc_SwitchVal[PNLE_FactorySoftwareSwitch_10] ) ? True : False;
						if ( ( False != pc_SoftDipSw->getSoftDipSwBit( 1, 1 ) )
							|| ( b_SoftDipSwBit3_2 != pc_SoftDipSw->getSoftDipSwBit( 3, 2 ) )
							|| ( b_SoftDipSwBit4_1 != pc_SoftDipSw->getSoftDipSwBit( 4, 1 ) )
							|| ( b_SoftDipSwBit4_2 != pc_SoftDipSw->getSoftDipSwBit( 4, 2 ) ) ) {
							pc_SoftDipSw->setSoftDipSwBit( 1, 1, False );
							pc_SoftDipSw->setSoftDipSwBit( 3, 2, b_SoftDipSwBit3_2 );
							pc_SoftDipSw->setSoftDipSwBit( 4, 1, b_SoftDipSwBit4_1 );
							pc_SoftDipSw->setSoftDipSwBit( 4, 2, b_SoftDipSwBit4_2 );
							ppc_SystemInfo->chkAndSetOwnOrGeneric();	// OwnかGenericかを判定し結果を不揮発領域に書き込む.
						}
					}					
					break;
				case BTNID_FactorySoftwareSwitchNo_11:		// SoftSW 11 の保存.
					pc_SoftDipSw->setSoftDipSwBit( 2, 5, ( BTNID_FactorySoftwareSwitchVal_1 == uc_SwitchVal[PNLE_FactorySoftwareSwitch_11] ) ? True : False );	// True:起動画面を強制的にGeneric(宇宙画面)にする.
					pc_SoftDipSw->setSoftDipSwBit( 3, 3, ( BTNID_FactorySoftwareSwitchVal_2 == uc_SwitchVal[PNLE_FactorySoftwareSwitch_11] ) ? True : False );	// True:起動画面を強制的にOWN(ロゴ画面)にする.
					break;
				default:
					LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
					break;
			}
			break;
		default:
			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
			break;
	}
	setupGamen();
}

//================================================================================================.
// 概要 : 60E00001 工場調整モード／SoftwareSwitch : OKキー押下処理.
//================================================================================================.
void PFactorySoftwareSwitch::procOk( uchar option )
{
// comment 2015/03/04 【HCLT-Abhinav】 【MiSBK】 【制御構成変更_No.55】 Modification to support MiSBK and later models.
// Comment 2017/11/29 【HCLT-Vishal】【Eagle】【制御構成変更_No.4】 Removing old function version check and else portion.
	nextGamen = &gp_FactoryAdjustModeTopMenu_MiSBK;
}

void PFactorySoftwareSwitch::procSecond( uchar option )											// （CQ.319181_tAppInitのexception回避）.
{	// （CQ.319181_tAppInitのexception回避）.
	PServiceToTopMenuCom::procSecond( option );													// （CQ.319181_tAppInitのexception回避）.
	if( True == b_MmbNeedCount ) {									// 秒数カウントが必要な場合    （CQ.319181_tAppInitのexception回避）.
		++uc_MmbCountTime;											// 画面開始後の秒数をカウント  （CQ.319181_tAppInitのexception回避）.
		if( PNLE_FactorySoftwareLimitTime == uc_MmbCountTime ) {	// 画面開始後3秒「以上」経過   （CQ.319181_tAppInitのexception回避）.
			b_MmbNeedCount = False;									// 秒数カウント不要にする      （CQ.319181_tAppInitのexception回避）.
			setupGamen();											// 画面表示処理                （CQ.319181_tAppInitのexception回避）.
		}																						// （CQ.319181_tAppInitのexception回避）.
	}																							// （CQ.319181_tAppInitのexception回避）.
}																								// （CQ.319181_tAppInitのexception回避）.

//================================================================================================.
// 概要 : 60XXXXXX システム設定2・FATALの自動解除設定 ： 画面開始処理.
//================================================================================================.
void PServiceSystemFatalReleaseSetting::startGamen()
{
	PServiceToSystemMenu2P2Com::startGamen();	// 親クラスの処理を呼ぶ.
	e_FatalRelease = PnlComGetMachineSetting()->getTroubleCancellationForBRankFATAL();	// BランクFATAL発生時のトラブル解除設定情報.
	e_AutoReboot = PnlComGetMachineSetting()->getRebootSettingForCRankFATAL();			// CランクFATAL発生時のReboot設定情報.
}
//================================================================================================.
// 概要 : 60XXXXXX システム設定2・FATALの自動解除設定 ： 表示画面のセットアップ.
//================================================================================================.
void PServiceSystemFatalReleaseSetting::setupGamen( short option )
{
	// 親クラスの呼び出し.
	PServiceToSystemMenu2P2Com::setupGamen( option );
	Rbt_AutoFatalReleaseSetting.select( ( TYPE_TroubleCancellationTypeCancel == e_FatalRelease ) ? 0:1 );	// する・しない選択キー BランクFATAL.
	Rbt_AutoRebootSetting.select( ( TYPE_RebootSettingTypeReboot == e_AutoReboot ) ? 0:1 );				// する・しない選択キー CランクFATAL.
}
//================================================================================================.
// 概要 : 60XXXXXX システム設定2・FATALの自動解除設定 ： ボタン（押された）.
//================================================================================================.
void PServiceSystemFatalReleaseSetting::procButtonOn( uchar option )
{
	switch( option ) {
		case BTNID_FATALRELEASE_YES:	e_FatalRelease	= TYPE_TroubleCancellationTypeCancel;		break;	// 自動解除する.
		case BTNID_FATALRELEASE_NO:		e_FatalRelease	= TYPE_TroubleCancellationTypeNotCancel;	break;	// 自動解除しない.
		case BTNID_AUTOREBOOT_YES:		e_AutoReboot	= TYPE_RebootSettingTypeReboot;				break;	// リブートする.
		case BTNID_AUTOREBOOT_NO:		e_AutoReboot	= TYPE_RebootSettingTypeNotReboot;			break;	// リブートしない.
		default: break;
	}
	setupGamen();
}
//================================================================================================.
// 概要 : 60XXXXXX システム設定2・FATALの自動解除設定 ： OKキー.
//================================================================================================.
void PServiceSystemFatalReleaseSetting::procOk( uchar option )
{
	PnlComGetMachineSetting()->setTroubleCancellationForBRankFATAL( e_FatalRelease );	// BランクFATAL発生時のトラブル解除設定に反映.
	PnlComGetMachineSetting()->setRebootSettingForCRankFATAL( e_AutoReboot );			// CランクFATAL発生時のReboot設定に反映.
	PServiceToSystemMenu2P2Com::procOk( option );	// 親クラスをCall.
}

//================================================================================================.
// 概要 : 91515 システム設定２／Eco指標表示 : 画面開始処理.
//================================================================================================.
void PServiceSystemEcoIndexDisplay::startGamen()
{
	float	sf_EmissionFactor = 0.0f;
	// 消費電力量表示.
	sc_select = TYPE_PowerConsumptionOn == PnlComGetSystemInfo()->getPowerConsumption() ? 0:1;
	// 排出係数値.
	// 誤差をなくすため、小数点第5位を四捨五入してから求める。.
	sf_EmissionFactor = ( PnlComGetSystemInfo()->getEmissionCoefficient() * 100000.0f + 5.0f ) / 10.0f;
	us_EmissionFactor = ( ushort )sf_EmissionFactor;
	s_nowFigure = 0;
	PServiceToSystemMenu2P2Com::startGamen();					//親クラスを呼ぶ.
}
//================================================================================================.
// 概要 : 91515 システム設定２／Eco指標表示 : 画面開始処理.
//================================================================================================.
void PServiceSystemEcoIndexDisplay::procButtonOn( uchar option )
{
	switch( option ) {
		case BTNID_KEY_ECOINDEXDISPLAY_POWERCONSUMPTION_ON:		// ONキー押下.
			sc_select = 0;
			break;
		case BTNID_KEY_ECOINDEXDISPLAY_POWERCONSUMPTION_OFF:	// OFFキー押下.
			sc_select = 1;
			break;
		default:
			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
			break;
	}
	setupGamen();	// 表示部品のセットアップ.
}
//================================================================================================.
// 概要 : 91515 システム設定２／Eco指標表示 : クリアキー押下処理.
//================================================================================================.
void PServiceSystemEcoIndexDisplay::procClear( uchar option )
{
	// 設定値が0のときにクリアキー押下は受付拒否.
	if( 0 == us_EmissionFactor ) {
		setBuzzerType( PCGE_BuzzerType_InputNg );
	} else {
		us_EmissionFactor = 0;
		s_nowFigure = 0;
		setupGamen( option );	// 表示部品のセットアップ.
	}
}
//================================================================================================.
// 概要 : 91515 システム設定２／Eco指標表示 : テンキー押下処理.
// 備考 : .
//================================================================================================.
void PServiceSystemEcoIndexDisplay::proc10Key( uchar option )
{
	// 4桁入力済み時 または 先頭入力の0は受付拒否.
	if( ( 4 == s_nowFigure ) || ( ( 0 == s_nowFigure ) && ( 0 == option ) ) ) {
		setBuzzerType( PCGE_BuzzerType_InputNg );
	} else {
		// 画面を初めて開いたときは入力済み桁数0で設定値は入力済みなので、その状態でテンキーが押されたときは.
		// クリアキーが押されてから数値を入れたとみなして処理を続行する.
		if( ( 0 == s_nowFigure ) && ( 0 != us_EmissionFactor ) ) {
			us_EmissionFactor = 0;
		} else {	us_EmissionFactor = static_cast<ushort>( us_EmissionFactor * 10 );	}
		us_EmissionFactor = static_cast<ushort>( us_EmissionFactor + option );
		s_nowFigure ++;
		setupGamen( option );		// 表示部品のセットアップ.
	}
}
//================================================================================================.
// 概要 : 91515 システム設定２／Eco指標表示 : 画面開始処理.
//================================================================================================.
void PServiceSystemEcoIndexDisplay::procOk( uchar option )
{
	float	sf_EmissionFactor = 0.0f;

	// 数値が0でないとき.
	if( 0 != us_EmissionFactor ) {
		// 消費電力量表示設定.
		PnlComGetSystemInfo()->setPowerConsumption( 0==sc_select?TYPE_PowerConsumptionOn:TYPE_PowerConsumptionOff );
		sf_EmissionFactor = ( float )us_EmissionFactor / 10000.0f;
		// 排出係数値設定.
		PnlComGetSystemInfo()->setEmissionCoefficient( sf_EmissionFactor );

		PServiceToSystemMenu2P2Com::procOk( option );					//親クラスを呼ぶ.
	} else { setBuzzerType( PCGE_BuzzerType_InputNg ); }
}
//================================================================================================.
// 概要 : 91515 システム設定２／Eco指標表示 : 画面開始処理.
//================================================================================================.
void PServiceSystemEcoIndexDisplay::setupGamen( short option )
{
	float	sf_EmissionFactor = 0.0f;
	// ON／OFFボタン選択.
	Rbt_ServiceSystemEcoIndexDisplay.select( sc_select );
	// 排出係数表示部.
	sf_EmissionFactor = ( float )us_EmissionFactor / 10000.0f;
	Btx_ServiceEcoIndexDisplayEmissionFactor.set( sf_EmissionFactor , False );
	PServiceToSystemMenu2Com::setupGamen( option );							// 親クラスを呼ぶ.
}
//================================================================================================
// 戻り値	:なし.
//================================================================================================
static void ans_comptransMngData( int32_t sl_Result )
{
	if( OK == sl_Result ) {		// データコピー成功時.
		CallBackIndi( TYPE_PNL_CallBack_DataCopyOK );
	} else {							// データコピー失敗時.
		CallBackIndi( TYPE_PNL_CallBack_DataCopyNG );
	}
}

//================================================================================================
//概要  70C25072_ﾏｼﾝ状態／確認／ﾒﾓﾘ／HDD調整／ﾃﾞｰﾀｺﾋﾟｰ : スタート（押された）.
//================================================================================================
void PServiceDataCopy::procStart( uchar option ) {

	if( printStartDisable() == True ) {	// スタートキー赤なら何もしない.
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );		// 拒否音.
		return;
	}
	PnlComGetHddInfo()->transferManageData( ans_comptransMngData );	// データコピー処理をコールする.

	bl_NoAcceptBtnFlag = True;			// ボタン受付不可にする.
	bl_StartOn = True;
	onlyPanel.bl_PowerOffOnMesage = True;
	turnGamen = NULL;
}
//================================================================================================
// 概要  70C25072_ﾏｼﾝ状態／確認／ﾒﾓﾘ／HDD調整／ﾃﾞｰﾀｺﾋﾟｰ : ファンクション終了 (R/L 共通).
//================================================================================================
void PServiceDataCopy::procCallBack( TYPE_PNL_CallBack option )
{
	switch( option ) {
		case TYPE_PNL_CallBack_DataCopyOK:	// データコピー完了 OK.
		case TYPE_PNL_CallBack_DataCopyNG:	// データコピー完了 NG.
			bl_isResultOK = ( TYPE_PNL_CallBack_DataCopyOK == option ) ? True : False;
			_bl_isExecutedFunction1 = True;		// ファンクション１実行完了.
			bl_isFinishDataCopy = True;			// データコピー完了フラグ.
			setupGamen();	// 表示画面のセットアップ.
			break;
		default:
			PServiceMemoryHDDAdjustCom::procCallBack( option );	// 親クラスの呼び出し.
			break;
	}
}
//================================================================================================
//概要  70C25072_ﾏｼﾝ状態／確認／ﾒﾓﾘ／HDD調整／ﾃﾞｰﾀｺﾋﾟｰ : 画面開始処理.
//================================================================================================
void PServiceDataCopy::startGamen() {
	PServiceMemoryHDDAdjustCom::startGamen();
	uc_pageNum = 2; // 2ページ目.
	Txt_ServiceMemoryHddCounterPage.changeText( s_SvcsCounterPage2_2 ) ;			// 表示ページを更新(2/2).
	Rbt_ServiceMemoryHDDAdjustPage2.select( 2 );	// メモリ/ＨＤＤ調整メニュー 2ページ・選択キー・データピー選択.
	bl_StartOn = False;		// スタートキー押された.
	bl_isFinishDataCopy = False;	// フォーマット完了.
	bl_isResultOK = False;	// 実行結果( ＯＫ→True ＮＧ→False ).

}
//================================================================================================
//概要  70C25072_ﾏｼﾝ状態／確認／ﾒﾓﾘ／HDD調整／ﾃﾞｰﾀｺﾋﾟｰ: 表示部品のセットアップ.
//================================================================================================
void PServiceDataCopy::setupGamen( short option ) {

	uchar uc_NowPercent = 0;		// パーセント表示用.

	// 一旦非表示にする.
	Num_ServiceDataCopyPersent.showEnable( False );	// 実行中パーセント.
	Txt_ServiceDataCopy_OKNG.showEnable( False );		// 実行結果表示 OK or NG.
	Txt_ServiceDataCopyDownArrow.showEnable( False );	// ↓ .
	Txt_SDataCopyOKFinishMessage.showEnable( False );	// 必@ず電源OFF/ONしてください.

	// 状態表示.
	if( bl_StartOn  == True && bl_isFinishDataCopy == False ) {	// スタートキー押された、かつ、実行中.
		PnlComGetHddInfo()->getManageDataProcessStat( &uc_NowPercent );
		Num_ServiceDataCopyPersent = uc_NowPercent;	// 実行パーセント.
		Num_ServiceDataCopyPersent.showEnable( True );	// 実行中パーセント・表示.

		// データコピー処理の進行状況によりメッセージの切り替えを行う.
		if( PNLD_DataCopy_HDDFormat >= uc_NowPercent ) {		// 50%を超えていない場合は論理フォーマット中.
			Txt_ServiceDataCopy_OKNG.changeText( s_ITMServiceLogicFormat );		// 「論理フォーマット中」.
		} else {												// 50%を超えている場合はデータコピー中.
			Txt_ServiceDataCopy_OKNG.changeText( s_ITMServiceCopyingData );		// 「データコピー中」.
		}
		Txt_ServiceDataCopy_OKNG.showEnable( True );	// 実行結果表示.
	}

	// パーツの表示/非表示の切り換え.
	if( bl_isFinishDataCopy == True && bl_isResultOK == True ) {
		Num_ServiceDataCopyPersent.showEnable( True );	// 実行中パーセント・表示.
		Txt_ServiceDataCopy_OKNG.changeText( s_ServiceMemoryCheck_OK );	// 実行結果表示 OK.
		Txt_ServiceDataCopy_OKNG.showEnable( True );						// 実行結果表示.
		Txt_ServiceDataCopyDownArrow.showEnable( True );					// ↓ .
		Txt_SDataCopyOKFinishMessage.showEnable( True );					// 必@ず電源OFF/ONしてください.
	} else if( bl_isFinishDataCopy == True && bl_isResultOK == False ) {
		Num_ServiceDataCopyPersent.showEnable( True );	// 実行中パーセント・表示.
		Txt_ServiceDataCopy_OKNG.changeText( s_ServiceMemoryCheck_NG );	// 実行結果表示 NG.
		Txt_ServiceDataCopy_OKNG.showEnable( True );						// 実行結果表示.
		Txt_ServiceDataCopyDownArrow.showEnable( True );					// ↓ .
		Txt_SDataCopyOKFinishMessage.showEnable( True );					// 必@ず電源OFF/ONしてください.
	}

	// HDDの状態を取得.
	Bool           bl_HddInfo;				// ＨＤＤ装着状態.
	TYPE_HddStatus e_HddStatus;				// ＨＤＤ状態.
	bl_HddInfo = PnlComGetHddInfo()->getHddExist(); // ハードディスク装着の設定値を取得
	e_HddStatus = PnlComGetHddInfo()->getHddStatus(); // ＨＤＤ状態を取得.
	// スタートキーの制御.
	if( bl_HddInfo == True				 // ＨＤＤ装着.
	    && e_HddStatus == TYPE_HddStatusFormated ) {	// かつ、HDDフォーマット済みである.
		printLEDControl( True );   // スタートキー緑.
	} else {
		printLEDControl( False );  // スタートキー赤.
	}
	if( bl_StartOn  == True ) { // スタートキー押下後.
		printLEDControl( False );
	}

	APIC_SystemInfo* pc_SystemInfo2 = APIC_SystemInfo::newInstance();	// システム情報のインスタンス生成.
	Bool b_CardLineMode = pc_SystemInfo2->isCardLineMode();	// カードラインモード用が差さっているか.
	if( b_CardLineMode == True ) {							// ラインカードが差さっている場合.
		if( isEmperorInitTaskDone() == False ) {			// Emperor初期化完了していない.
			if( e_HddStatus == TYPE_HddStatusFormated ) {	// HDD　使用可能.
				printLEDControl( False );
			}
		}
	}
	// ライン/OKキー更新のため、ベースクラスをCall.
	PServiceMemoryHDDAdjustCom::setupGamen( option );
}
/*================================================================================================
// 概要		: 80B91010 サービス・プロセス調整・階調補正・最大濃度補正 : コンストラクタ.
================================================================================================*/
PServiceImageAdjustMaximumDensity::PServiceImageAdjustMaximumDensity(
    PDisplayParts** partsTable,
    short partsNumber,
    Bool isNoWarning )
	: PServiceGammaAutoAdjustOutput( partsTable, partsNumber, isNoWarning )
{
	bl_FuncErrSts_Anteika = False;								// ファンクション実行結果(画像安定化)を成功状態で初期化.
	bl_FuncErrSts_Densty = False;								// ファンクション実行結果(最大濃度補正)を成功状態で初期化.
	ss_Selected = BTNID_AUTOADJUSTMAXDST_ANTEIKA;				// 画像安定化キーを選択状態にする.
	ss_SelectPaperSize = -1;									// 用紙キーは非選択状態にする.
}
/*================================================================================================
// 概要		: 80B91010 ﾌﾟﾛｾｽ調整／階調補正／最大濃度補正／ﾃｽﾄﾊﾟﾀｰﾝ出力 : 画面開始処理.
================================================================================================*/
void PServiceImageAdjustMaximumDensity::startGamen()
{
	PServiceGammaAutoAdjustOutput::startGamen();		// ファンクション共通初期設定.

	bl_FuncErrSts_Anteika = False;						// ファンクション実行結果(画像安定化)を成功状態で初期化.
	bl_FuncErrSts_Densty = False;						// ファンクション実行結果(最大濃度補正)を成功状態で初期化.
	ss_SelectPaperSize = -1;								// 用紙キーは非選択状態にする.

	// 補正結果を非表示.
	Txt_ServiceImageAdjustMaximumDensityResultTTL.showEnable( False );
	Txt_ServiceImageAdjustMaximumDensityResult.showEnable( False );

	if( False == getImageStabilization() )	// 画像安定化が実施済み.
	{
		// 画像安定化実施済みになっている場合はパターンの読取り画面から戻った場合に限定されるので.
		// 補正値を表示させるために最大濃度補正キーを選択状態にする.
		ss_Selected = BTNID_AUTOADJUSTMAXDST_MAXDST;
		setFunctionCode( TYPD_FNC_DmaxAutoAdjustPrint );	// コードセット・最大濃度補正.
	} else {
		ss_Selected = BTNID_AUTOADJUSTMAXDST_ANTEIKA;				// 画像安定化キーを選択状態にする.
		setFunctionCode( TYPD_FNC_ErrorDiffusionAutoAdjustStart );	// コードセット・階調補正:階調優先(Gradation)＆解像度優先(Resolution)・自動補正開始(安定化).
	}
}
/*================================================================================================
// 概要		: 80B91010 ﾌﾟﾛｾｽ調整／階調補正／最大濃度補正／ﾃｽﾄﾊﾟﾀｰﾝ出力 : 表示部品のセットアップ.
================================================================================================*/
void PServiceImageAdjustMaximumDensity::setupGamen( short option )
{
	Bool bl_PCallOccur = False;
	// Pコールの発生状態を取得.
	if( PnlComGetPrinterWarning()->isPRTWarning( TYPE_PRTWarningCode_WP5 )	// P-5.
	    || PnlComGetPrinterWarning()->isPRTWarning( TYPE_PRTWarningCode_WP6 )	// P-6.
	    || PnlComGetPrinterWarning()->isPRTWarning( TYPE_PRTWarningCode_WP7 )	// P-7.
	    || PnlComGetPrinterWarning()->isPRTWarning( TYPE_PRTWarningCode_WP8 )	// P-8.
	    || PnlComGetPrinterWarning()->isPRTWarning( TYPE_PRTWarningCode_WP9 )	// P-9.
	    || PnlComGetPrinterWarning()->isPRTWarning( TYPE_PRTWarningCode_WP28 )	// P-28.
	  ) {
		bl_PCallOccur = True;
	}

	PServiceFunctionEnableStartCom::setupGamen( option );			// 親の親をコールする(親で使用しているパーツを本画面でも使用ため).

	Rbt_ServiceProcessAdjustMaximumDensity.select( ss_Selected );			// 画像安定化・最大濃度補正・初期化キーの選択状態の更新.
	Rbt_ServiceProcessAdjustMaximumDensityPaper.select( ss_SelectPaperSize );	// 用紙キーの選択状態の更新.

	Num_ServiceImageAdjustMaximumDensityAdjC = static_cast<float>( PnlComGetPrinterServiceInfo()->getPrinterInfo( TYPE_PrinterInfoDmaxAutoAdjustC ) / 100.0f );	// 補正量シアン.
	Num_ServiceImageAdjustMaximumDensityAdjM = static_cast<float>( PnlComGetPrinterServiceInfo()->getPrinterInfo( TYPE_PrinterInfoDmaxAutoAdjustM ) / 100.0f );	// 補正量マゼンタ.
	Num_ServiceImageAdjustMaximumDensityAdjY = static_cast<float>( PnlComGetPrinterServiceInfo()->getPrinterInfo( TYPE_PrinterInfoDmaxAutoAdjustY ) / 100.0f );	// 補正量イエロー.
	Num_ServiceImageAdjustMaximumDensityAdjB = static_cast<float>( PnlComGetPrinterServiceInfo()->getPrinterInfo( TYPE_PrinterInfoDmaxAutoAdjustK ) / 100.0f );	// 補正量ブラック.

	Txt_ServiceImageAdjustMaximumDensityAnteikaNG.showEnable( bl_PCallOccur || bl_FuncErrSts_Anteika );


	// Pコード(P-9)が出ている場合若しくはファンクション実行中は、スタートLED赤.
	if( bl_PCallOccur || isFunctionWorking() ) {
		printLEDControl( False );	// LED赤.
		if( bl_PCallOccur ) {
			// 補正結果・補正量を非表示.
			Txt_ServiceImageAdjustMaximumDensityResult.showEnable( False );
			Num_ServiceImageAdjustMaximumDensityAdjC.showEnable( False );	// 補正量シアン.
			Num_ServiceImageAdjustMaximumDensityAdjM.showEnable( False );	// 補正量マゼンタ.
			Num_ServiceImageAdjustMaximumDensityAdjY.showEnable( False );	// 補正量イエロー.
			Num_ServiceImageAdjustMaximumDensityAdjB.showEnable( False );	// 補正量ブラック.
		}
	} else {
		switch( ss_Selected ) {
			case BTNID_AUTOADJUSTMAXDST_ANTEIKA:	// 画像安定化.
			case BTNID_AUTOADJUSTMAXDST_INIT:		// 初期化.
				// 補正結果・補正量を非表示.
				Txt_ServiceImageAdjustMaximumDensityResultTTL.showEnable( False );
				Txt_ServiceImageAdjustMaximumDensityResult.showEnable( False );
				Num_ServiceImageAdjustMaximumDensityAdjC.showEnable( False );	// 補正量シアン.
				Num_ServiceImageAdjustMaximumDensityAdjM.showEnable( False );	// 補正量マゼンタ.
				Num_ServiceImageAdjustMaximumDensityAdjY.showEnable( False );	// 補正量イエロー.
				Num_ServiceImageAdjustMaximumDensityAdjB.showEnable( False );	// 補正量ブラック.
				printLEDControl( True );	// LED青.
				break;
			case BTNID_AUTOADJUSTMAXDST_MAXDST:	// 最大濃度補正.
				// 補正結果がNGのときだけ補正結果を表示.
				Txt_ServiceImageAdjustMaximumDensityResultTTL.showEnable( bl_FuncErrSts_Densty );
				Txt_ServiceImageAdjustMaximumDensityResult.showEnable( bl_FuncErrSts_Densty );
				Num_ServiceImageAdjustMaximumDensityAdjC.showEnable( True );	// 補正量シアン.
				Num_ServiceImageAdjustMaximumDensityAdjM.showEnable( True );	// 補正量マゼンタ.
				Num_ServiceImageAdjustMaximumDensityAdjY.showEnable( True );	// 補正量イエロー.
				Num_ServiceImageAdjustMaximumDensityAdjB.showEnable( True );	// 補正量ブラック.
				if( 0 == ss_SelectPaperSize ) {				// A3/11x17.
					searchTray2341A3Paper( option );		// ファンクション画面共通処理(用紙検索).
				} else if( 1 == ss_SelectPaperSize ) {		// A4/Letter.
					searchTray2341A4YOrLetterY( option );	// ファンクション画面共通処理(用紙検索).
				} else {
					printLEDControl( False );	// LED赤.
				}
				break;
			default:
				printLEDControl( False );	// LED赤.
				break;
		}
	}
}
/*================================================================================================
// 概要		: 80B91010 ﾌﾟﾛｾｽ調整／階調補正／最大濃度補正／ﾃｽﾄﾊﾟﾀｰﾝ出力 : ファンクション終了.
================================================================================================*/
void PServiceImageAdjustMaximumDensity::procFunctionEnd( uchar option )
{
	ushort us_func_result = 0;	// ファンクション実行結果.

	bl_NoAcceptBtnFlag = False;	// ファンクション終了をもってボタン受付可能にする.

	switch( ss_Selected ) {
		case BTNID_AUTOADJUSTMAXDST_ANTEIKA:	// 画像安定化.
			us_func_result = pc_SystemControl.getFunctionResult( static_cast<ushort>( toFunctionCode( TYPD_FNC_ErrorDiffusionAutoAdjustStart ) ) );
			if( TYPD_FNC_OK == us_func_result ) {	// 成功の場合.
				bl_FuncErrSts_Anteika = False;		// 実行結果用のエラーフラグを落とす.
				setImageStabilization( False );		// 画像安定化実施済み.
			} else {
				bl_FuncErrSts_Anteika = True;		// 実行結果用のエラーフラグを立てる.
			}
			break;
		case BTNID_AUTOADJUSTMAXDST_MAXDST:		// 最大濃度補正.
			us_func_result = pc_SystemControl.getFunctionResult( static_cast<ushort>( toFunctionCode( TYPD_FNC_DmaxAutoAdjustPrint ) ) );
			if( TYPD_FNC_OK == us_func_result ) {	// 成功の場合.
				bl_FuncErrSts_Densty = False;		// 実行結果用のエラーフラグを落とす.
				nextGamen = &gp_ServiceImageAdjustMaximumDensityScan;	// パターン読込み画面に遷移する.
			} else {
				bl_FuncErrSts_Densty = True;		// 実行結果用のエラーフラグを立てる.
			}
			break;
		case BTNID_AUTOADJUSTMAXDST_INIT:		// 初期化.
			// なにもしない.
			break;
		default:
			break;
	}
	// ファンクション成功.
	setupGamen();
}
/*================================================================================================
// 概要		: 80B91010 ﾌﾟﾛｾｽ調整／階調補正／最大濃度補正／ﾃｽﾄﾊﾟﾀｰﾝ出力 : スタートキー押下処理.
================================================================================================*/
void PServiceImageAdjustMaximumDensity::procStart( uchar option )			// スタートキー.
{
	if( True == printStartDisable() ) { 			// スタートLEDが赤ならなにもしない.
		setBuzzerType( PCGE_BuzzerType_InputNg );	// 拒否音.
		return;
	}

	if( BTNID_AUTOADJUSTMAXDST_ANTEIKA == ss_Selected ) {	// 画像安定化実行.
		setFunctionCode( TYPD_FNC_ErrorDiffusionAutoAdjustStart );	// コードセット・画像安定化.
		PServiceFunctionEnableStartCom::procStart( TYPE_FunctionStartTypeNORMAL );	// エンジンファンクション.
	} else if( BTNID_AUTOADJUSTMAXDST_MAXDST == ss_Selected ) { // 最大濃度補正パターン印刷実行.
		APIC_Job* pc_Job = PnlComGetJobCopy();
		if( NULL == pc_Job ) { 
//2019/06/17 Comment [HCLT_Krishnakumar][EagleH][N Rank] Removed unwanted detailed code.
//// 2015/11/05 【HCLT-Dhivya】 【ZeusS_ZX0】 【制御構成変更_No.76-1】Detail macro is passed in API.
//			LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//			if (NULL != pc_BFW_System){
//    			pc_BFW_System->registDetailCode(PNLD_DetailCode_Service_0x1900280100372001);
//			}
			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" ); 
			return; 
		}
		TYPC_Scan*   pc_Scan   = pc_Job->getJobSpec()->pc_Scan;		// スキャン.
		TYPC_Common* pc_Common = pc_Job->getJobSpec()->pc_Common;	// コピー.
		TYPC_Print*	 pc_Print  = pc_Job->getJobSpec()->pc_Print;	// プリント.
		TYPE_SystemType  e_SystemType = PnlComGetMachineSetting()->getSystemType();		// 仕向けを取得.

		pc_Scan->setAcsOn( False );							// ACS未使用にする.
		pc_Common->setColorMode( TYPE_ColorModeFullColor );	// カラーモードをカラー固定でセット.
		pc_Print->setNumOfCopies( 1 );						// 置数１とする.

		if( 0 == ss_SelectPaperSize ) {	// A3/11X17.
			if( TYPE_SystemType_US == e_SystemType ) {
				pc_Print->c_PaperSize = TYPC_PaperSize( TYPE_SizeCodeLedgerSef );	// 用紙サイズ・11x17SEF.
			} else {
				pc_Print->c_PaperSize = TYPC_PaperSize( TYPE_SizeCodeA3Sef );		// 用紙サイズ・A3SEF.
			}
		} else if( 1 == ss_SelectPaperSize ) {	// A4/Letter.
			if( TYPE_SystemType_US == e_SystemType ) {
				pc_Print->c_PaperSize = TYPC_PaperSize( TYPE_SizeCodeLetterLef );	// 用紙サイズ・LetterSEF.
			} else {
				pc_Print->c_PaperSize = TYPC_PaperSize( TYPE_SizeCodeA4Lef );		// 用紙サイズ・A4LEF.
			}
		}
		setFunctionCode( TYPD_FNC_DmaxAutoAdjustPrint );	// コードセット・最大濃度補正.
		comSystem.cc_Cmode.resetCmode( 3 );	// C-Mode関数を呼び出す.
		PServiceFunctionEnableStartCom::procStart( TYPE_FunctionStartTypePRINTPATTAN ); // プリントファンクション.
	} else if( BTNID_AUTOADJUSTMAXDST_INIT == ss_Selected ) {		// 初期化実行.
		setFunctionCode( TYPD_FNC_MonoGradationAutoAdjustInit );	// コードセット・初期化.
		PServiceFunctionEnableStartCom::procStart( TYPE_FunctionStartTypeNORMAL );	// エンジンファンクション.
	}
	// ファンクション実行出来た場合、ボタン受付禁止にする.
	if( isFunctionWorking() ) {
		bl_NoAcceptBtnFlag = True;					// ボタン受付禁止にする.
	}
}
/*================================================================================================
// 概要		: 80B91010 ﾌﾟﾛｾｽ調整／階調補正／最大濃度補正／ﾃｽﾄﾊﾟﾀｰﾝ出力 : ボタン（押された）.
================================================================================================*/
void PServiceImageAdjustMaximumDensity::procButtonOn( uchar option )
{
	if( BTNID_AUTOADJUSTMAXDST_MAXDST == option		// 最大濃度補正キーを選択.
	    || BTNID_AUTOADJUSTMAXDST_A3_11x17 == option	// A3/11x17キーを選択.
	    || BTNID_AUTOADJUSTMAXDST_A4LTR == option ) {	// A4/Letterキーを選択.
		if( True == getImageStabilization()	// 画像安定化未実施.
		    // Pコード(P-5,P-6,P-7,P-8,P-9,P-28)が出ている場合.
		    || PnlComGetPrinterWarning()->isPRTWarning( TYPE_PRTWarningCode_WP5 )
		    || PnlComGetPrinterWarning()->isPRTWarning( TYPE_PRTWarningCode_WP6 )
		    || PnlComGetPrinterWarning()->isPRTWarning( TYPE_PRTWarningCode_WP7 )
		    || PnlComGetPrinterWarning()->isPRTWarning( TYPE_PRTWarningCode_WP8 )
		    || PnlComGetPrinterWarning()->isPRTWarning( TYPE_PRTWarningCode_WP9 )
		    || PnlComGetPrinterWarning()->isPRTWarning( TYPE_PRTWarningCode_WP28 )
		  ) {
			setBuzzerType( PCGE_BuzzerType_InputNg );	// 拒否音.
			return;
		}
	}
	switch( option ) {
		case BTNID_AUTOADJUSTMAXDST_ANTEIKA:	// 画像安定化キーが押された.
			ss_Selected = option;				// 画像安定化キーを選択状態にする.
			ss_SelectPaperSize = -1;				// 用紙キーは非選択状態にする.
			setFunctionCode( TYPD_FNC_ErrorDiffusionAutoAdjustStart );	// ファンクションコードを画像安定化に変更.
			break;
		case BTNID_AUTOADJUSTMAXDST_MAXDST:		// 最大濃度補正キーが押された.
			ss_Selected = option;				// 最大濃度補正キーを選択状態にする.
			ss_SelectPaperSize = -1;				// 用紙キーは非選択状態にする.
			setFunctionCode( TYPD_FNC_DmaxAutoAdjustPrint );	// ファンクションコードを「Dmax補正用ﾊﾟﾀｰﾝ印字ﾌｧﾝｸｼｮﾝ開始指示」に変更.
			break;
		case BTNID_AUTOADJUSTMAXDST_INIT:		// 初期化キーが押された.
			ss_Selected = option;				// 初期化キーを選択状態にする.
			ss_SelectPaperSize = -1;				// 用紙キーは非選択状態にする.
			setFunctionCode( TYPD_FNC_MonoGradationAutoAdjustInit );	// ファンクションコードを「ﾓﾉｸﾛ階調補正ﾃﾞｰﾀ初期化ﾌｧﾝｸｼｮﾝ開始指示」に変更.
			break;
		case BTNID_AUTOADJUSTMAXDST_A3_11x17:	// A3/11x17キーが押された.
			if( BTNID_AUTOADJUSTMAXDST_MAXDST == ss_Selected ) {	// 最大濃度補正キーが選択状態.
				ss_SelectPaperSize = 0;	// A3/11x17キーを選択状態にする.
			} else {
				setBuzzerType( PCGE_BuzzerType_InputNg );	// 拒否音.
			}
			break;
		case BTNID_AUTOADJUSTMAXDST_A4LTR:		// A4/Letterキーが押された.
			if( BTNID_AUTOADJUSTMAXDST_MAXDST == ss_Selected ) {	// 最大濃度補正キーが選択状態.
				ss_SelectPaperSize = 1;	// A4/Letterキーを選択状態にする.
			} else {
				setBuzzerType( PCGE_BuzzerType_InputNg );	// 拒否音.
			}
			break;
		default: break;
	}
	setupGamen();	// 表示部品のセットアップ
}
/*================================================================================================
// 概要		: 80B91010 ﾌﾟﾛｾｽ調整／階調補正／最大濃度補正／ﾃｽﾄﾊﾟﾀｰﾝ読取り : 画面開始処理.
================================================================================================*/
void PServiceImageAdjustMaximumDensityScan::startGamen()
{
	e_GammaAutoAdjType = PNLE_GammaAutoAdjTypetMaximumDensity;	// 補正の種類をDmax補正量とする.
	PServiceGammaAutoAdjustScan::startGamen();		// 親をコールする.
	setFunctionCode( TYPD_FNC_DmaxAutoAdjustScan );	// Dmax補正用ﾊﾟﾀｰﾝ読取ﾌｧﾝｸｼｮﾝ開始指示.
}


