// @brief	: システム設定２・ユニット交換選択・ﾆｱｴﾝﾌﾟﾃｨｰ表示ﾀｲﾐﾝｸﾞ:クリア.
//-----------------------------------------------------------------------------------------------.
void PServiceSystemNEmptyDispTiming::procClear( uchar )
{
	setPrinterIndi( ss_SelectTable, 0 );		// 選択中テーブルの設定値を0に設定する.
	setupGamen();							// 表示部品のセットアップ.
}

//-----------------------------------------------------------------------------------------------.
// @brief	: システム設定２・ユニット交換選択・ﾆｱｴﾝﾌﾟﾃｨｰ表示ﾀｲﾐﾝｸﾞ:10ｷｰ.
//-----------------------------------------------------------------------------------------------.
void PServiceSystemNEmptyDispTiming::proc10Key( uchar option )
{
	Bool bl_Error = False;
	ushort us_LocalValue = 0;
	for( register ushort i = 0; i < us_PrinterIndiParameter; i++ ) {
		if( ss_SelectTable  == sc_PrinterIndiParameter[ i ].indi ) {	//選択されているテーブルか判定.
			short ss_PreValue = getPrinterIndi( ss_SelectTable ); 	//現在の値を取得.

			us_LocalValue = ( ushort )proc10KeyInput( ss_PreValue, sc_PrinterIndiParameter[ i ].Max, option, False, EP_InputMaxLimitPattern_Refuse, &bl_Error ); //現在の値を判定し、現在値と入力値を結合した値を返す.

			if( ( 0 == us_LocalValue ) || ( True == bl_Error ) )  { 	// クリア状態__で０を押されたら、初期状態にして戻る.
				setBuzzerType( PCGE_BuzzerType_InputNg );
				return;
			}

			setPrinterIndi( ss_SelectTable ,us_LocalValue ); 		//値を反映させる.

			break;
		}
	}
}
