//comment 2019/01/31 HCLT-Shalini [IT6_EagleH] [機器構成変更_No.28] Support for Toner Controller.
//================================================================================================.
void PServiceSystemTonerNearEmpty::procOk( uchar option )
{
// comment 2019/03/20 HCLT-Shalini [EagleH][OP_BTS-3601] Setting the Value based on the Key Selection.
	if( BTNID_SSystemTonerNearEmptyCtrl_Amount == sc_TonerNearEmptyCtrl ){
		PnlComGetPrinterServiceSetting()->setPrinterAdjust( TYPE_PrinterAdjustTonerNearEmptyCtrlChoice, TYPE_PrinterAdjustTonerNearEmptyCtrl_Amount );	// Set the value.
	} else {
		PnlComGetPrinterServiceSetting()->setPrinterAdjust( TYPE_PrinterAdjustTonerNearEmptyCtrlChoice, TYPE_PrinterAdjustTonerNearEmptyCtrl_Days );	// Set the value.
	}
	fixPrinterIndi( TYPE_PrinterAdjustTonerNearEmptyCtrl_Amount );
	fixPrinterIndi( TYPE_PrinterAdjustTonerNearEmptyCtrl_Days );
#ifndef DEF_MonoCus	
	fixPrinterIndi( TYPE_PrinterAdjustNearEmptyTimingCMY );	
	fixPrinterIndi( TYPE_PrinterAdjustTonerNearEmptyDetectDays_C );	
	fixPrinterIndi( TYPE_PrinterAdjustTonerNearEmptyDetectDays_M );	
	fixPrinterIndi( TYPE_PrinterAdjustTonerNearEmptyDetectDays_Y );	
#endif	// DEF_MonoCus	
	fixPrinterIndi( TYPE_PrinterAdjustNearEmptyTimingK );
	fixPrinterIndi( TYPE_PrinterAdjustTonerNearEmptyDetectDays_K );	
	nextGamen = &gp_ServiceSystemUnitR1;
}
