// @brief	: システム設定２・ユニット交換選択・ﾌﾟﾚﾆｱﾆｱｴﾝﾌﾟﾃｨｰ表示ﾀｲﾐﾝｸﾞ:ボタン押し続け.
//-----------------------------------------------------------------------------------------------.
void PServiceSystemPreNearNEmptyDispTiming::procButtonStillOnFast( uchar option )
{
	if( BTNID_SSystemNEmptyDispTiming_Down == option || BTNID_SSystemNEmptyDispTiming_Up == option ) {
		procButtonOn( option );
	}
}
//-----------------------------------------------------------------------------------------------.
// @brief	: システム設定２・ユニット交換選択・ﾌﾟﾚﾆｱﾆｱｴﾝﾌﾟﾃｨｰ表示ﾀｲﾐﾝｸﾞ:ボタン押下.
//-----------------------------------------------------------------------------------------------.
void PServiceSystemPreNearNEmptyDispTiming::procButtonOn( uchar option )
{
	switch( option )
	{
#ifndef DEF_MonoCus	// カラー機.
		case BTNID_SSystemNEmptyDispTiming_CMY:		// [CMY]キー.
			m_sc_SelectKey = BTNID_SSystemNEmptyDispTiming_CMY;		// 選択キーを[CMY]に.
			m_ss_SelectTable = TYPE_PrinterAdjustIUDCPreNearLifeTimingCMY;	// 選択テーブルを[CMY]に.
			setPrinterIndi( TYPE_PrinterAdjustIUDCPreNearLifeTimingCMY );
			break;
#endif	// DEF_MonoCus.
		case BTNID_SSystemNEmptyDispTiming_K:		// [K]キー.
			m_sc_SelectKey = BTNID_SSystemNEmptyDispTiming_K;			// 選択キーを[K]に.
			m_ss_SelectTable = TYPE_PrinterAdjustIUDCPreNearLifeTimingK;	// 選択テーブルを[K]に.
			setPrinterIndi( TYPE_PrinterAdjustIUDCPreNearLifeTimingK );
			break;
		case BTNID_SSystemNEmptyDispTiming_Down:	// [-]キー.
			subIndi();												// 選択中テーブルの設定値を減算.
			break;
		case BTNID_SSystemNEmptyDispTiming_Up:		// [+]キー.
			addIndi();												// 選択中テーブルの設定値を加算.
			break;
		case 60:	// 元に戻すキー
			switch( m_ss_SelectTable ){
#ifndef DEF_MonoCus	// モノクロ機.
				case TYPE_PrinterAdjustIUDCPreNearLifeTimingCMY:			// CMYが選択されている.
					setPrinterIndi( TYPE_PrinterAdjustIUDCPreNearLifeTimingCMY, m_ss_NearEmptyCMY );
					break;
#endif	// DEF_MonoCus.
				case TYPE_PrinterAdjustIUDCPreNearLifeTimingK:			// Kが選択されている.
					setPrinterIndi( TYPE_PrinterAdjustIUDCPreNearLifeTimingK, m_ss_NearEmptyK );
					break;
				default:
					break;
			}
			break;
		default:
			break;
	}
	setupGamen( option );
}

//-----------------------------------------------------------------------------------------------.
// @brief	: システム設定２・ユニット交換選択・ﾌﾟﾚﾆｱﾆｱｴﾝﾌﾟﾃｨｰ表示ﾀｲﾐﾝｸﾞ:設定終了.
//-----------------------------------------------------------------------------------------------.
void PServiceSystemPreNearNEmptyDispTiming::procOk( uchar option )
{
#ifndef DEF_MonoCus	// カラー機.
	fixPrinterIndi( TYPE_PrinterAdjustIUDCPreNearLifeTimingCMY );	// ﾆｱｴﾝﾌﾟﾃｨｰ表示ﾀｲﾐﾝｸﾞ[CMY]設定値の確定.
#endif	// DEF_MonoCus.
	fixPrinterIndi( TYPE_PrinterAdjustIUDCPreNearLifeTimingK );	// ﾆｱｴﾝﾌﾟﾃｨｰ表示ﾀｲﾐﾝｸﾞ[K]設定値の確定.
	nextGamen = &gp_ServiceSystemUnitR1;	// 91536_システム設定／ユニット交換選択に遷移.

}

// comment ▼ 2011/03/15 OS1-mhibino【UV-00812】Internal Web Server.
//================================================================================================.
// 概要 : 80B91519 システム設定２／IWS設定 ： 画面開始処理.
//================================================================================================.
void PServiceSystemIWSSetting::startGamen()
{
	PServiceToSystemMenu2P2Com::startGamen();	// 親クラスの処理を呼ぶ.
	bl_IWSSetting = PnlComGetSystemSetting()->getIWSSettingEnable();	// サービスモードのIWS設定を取得.
	bl_SettingOn = False;	// 確定キー押下状態(OFF).
}
//================================================================================================.
// 概要 : 80B91519 システム設定２／IWS設定 ： 表示画面のセットアップ.
//================================================================================================.
void PServiceSystemIWSSetting::setupGamen( short option )
{
	// 親クラスの呼び出し.
	PServiceToSystemMenu2P2Com::setupGamen( option );
	Rbt_ServiceIWSSetting.select( ( True == bl_IWSSetting ) ? 0:1 );	// IWS設定 有効/無効.
	// 確定状態表示.
	if( bl_SettingOn ) {
		// 確定キー押下後は、確定キーを非表示にしてメッセージを表示.
		Key_ServiceIWSSettingFix.showEnable( False );		// 確定キー.
		Txt_ServiceIWSSettingMessage.showEnable( True );	// 「必ず主電源OFF/ONしてください」.
	} else {
		// メッセージを非表示にして確定キーを表示.
		Txt_ServiceIWSSettingMessage.showEnable( False );	// 「必ず主電源OFF/ONしてください」.
		Key_ServiceIWSSettingFix.showEnable( True );		// 確定キー.
	}
}
//================================================================================================.
// 概要 : 80B91519 システム設定２／IWS設定 ： ボタン（押された）.
//================================================================================================.
void PServiceSystemIWSSetting::procButtonOn( uchar option )
{
	switch( option ) {
		case BTNID_ServiceIWSEffective:		bl_IWSSetting = True;	break;	// IWS設定・有効.
		case BTNID_ServiceIWSInvalid:		bl_IWSSetting = False;	break;	// IWS設定・無効.
		case BTNID_ServiceIWSFix:	// 確定キー.
			PnlComGetSystemSetting()->setIWSSettingEnable( bl_IWSSetting );
			if( False == bl_IWSSetting ) {	// IWS設定を無効にした場合.
				PnlComGetIWSSetting()->factoryReset();		// IWS設定の項目を工場出荷値へリセット.
			}
			bl_SettingOn = True;	// 確定キー押下状態(ON).
			break;
		default: break;
	}
	setupGamen();
}

//================================================================================================
// 概要 : 80B91519 システム設定２／IWS設定 ：タブレット端末切断によりサービスモードを終了する
//================================================================================================
void PServiceSystemIWSSetting::procTabletDisconnect( uchar option )
{
	// 確定ボタン押下されれば、主電源をOFF/ONメッセージは表示されるので、画面遷移しない.
	if( !bl_SettingOn ) {
		PServiceCom::procTabletDisconnect( option );
	}
}
	
