//================================================================================================.
// 概要		：IR||ADFセンサ状態を取得する.
// 戻り値	：Bool : True→センサ動作OK.
// 備考		：該当処理:センサチェック.
// 作成者	：Ｆ鈴木.
//================================================================================================.
Bool PServiceEDHSensorCheck::Check_SensorCondition( ScannerConditionSensor sensor )
{
	APIC_ScannerServiceInfo* pc_ScannerServiceInfo = PnlComGetScannerServiceInfo();

	register short data = 0;
	register short mask = 0;
	if( sensor < ICS_ADFSensorStart ) {			// Scannerセンサの時.
		data = pc_ScannerServiceInfo->getScannerInfo( TYPE_ScannerInfoSensorInfo );		// センサ情報.
	} else if( sensor < ICS_ADFSensor2Start	) {		// ＡＤＦセンサ１の時.
		data = pc_ScannerServiceInfo->getScannerInfo( TYPE_ScannerInfoADFSensor );		// ＡＤＦセンサ情報１.
	} else {										// ＡＤＦセンサ２の時.
//			: 2016/12/18 HCL_Sai	[KRONOSS][CQ-1008510] ADF adjustment sensor state display Start.
#ifdef DEF_KRONOSS_Cus
		data = pc_ScannerServiceInfo->getScannerInfo( TYPE_ScannerInfoADFSensor4 );		// ＡＤＦセンサ情報4.
#else
		data = pc_ScannerServiceInfo->getScannerInfo( TYPE_ScannerInfoADFSensor2 );		// ＡＤＦセンサ情報２.
#endif
//			: 2016/12/18 HCL_Sai	[KRONOSS][CQ-1008510] ADF adjustment sensor state display End.
	}
	mask = sensor % SENSOR_BIT; //各センサの構成要素で割った余り.
	return ( data & ( 0x0001 << mask ) ) ? True : False;
}

Bool PServiceSystemCustomPattern::m_bCallDeleteStatus;
//================================================================================================.
// 概要 : 80B91522 システム設定2／カスタムパターン ： 画面開始処理.
//================================================================================================.
void PServiceSystemCustomPattern::startGamen()
{
	// 親クラスの処理.
	PServiceToSystemMenu2P2Com::startGamen();

	// 初期化
	m_bShowDelete = False;
	m_bShowDecision = False;
	m_eSelectCustomType = 0;
	m_ssDeleteStatus = PNLE_DELSTATUS_Non;
	m_bAnimationFlg = False;
// Comment 2015/07/20 HCLT-Surajit RQ-163[WP 1372] Hide the Import Area(import key, frame, USB NG).
// Comment 2017/11/29 【HCLT-Vishal】【Eagle】【制御構成変更_No.4】 Removing old function version check condition.
	PNLC_USBConnectionPermission c_UsbPermission;
	PNLE_EnableUSBConnectionPermissionForAll e_usbAll = c_UsbPermission.getEnableUSBConnectionPermissionForAll();
	PNLE_EnableUSBConnectionPermissionForService e_usbforService = c_UsbPermission.getEnableUSBConnectionPermissionForService();
	if(( PNLE_EnableUSBConnectionPermissionForAll_Disable == e_usbAll ) || ( PNLE_EnableUSBConnectionPermissionForService_Disable == e_usbforService )) {
		m_bl_USBConnectionPermissionFlag = False;
	} else {
		m_bl_USBConnectionPermissionFlag = True;
	}
	// カスタムパターンファイル名取得
	getCustomPatternFileName();
}

//================================================================================================.
// 概要 : 80B91522 システム設定2／カスタムパターン ： 画面セットアップ.
//================================================================================================.
void PServiceSystemCustomPattern::setupGamen( short option )
{
	// 親クラスの処理.
	PServiceToSystemMenu2P2Com::setupGamen( option );

	// カスタムパターンファイル名の表示.
	Btx_ServiceCustomPattern1.changeTextString( ( uchar* )m_pCustomPatternNameList[0] );
	Btx_ServiceCustomPattern2.changeTextString( ( uchar* )m_pCustomPatternNameList[1] );
	Btx_ServiceCustomPattern3.changeTextString( ( uchar* )m_pCustomPatternNameList[2] );

	// インポートキーの表示.
	APIC_UsbMemDeviceInfo* pc_UsbMemDeviceInfo = APIC_UsbMemDeviceInfo::newInstance();
// Comment 2015/08/17 HCLT-Surajit [RQ-163] [WP 1372] Hide Loadable Driver. To avoid flicker issue.
	uint32_t ui32_UsbStatus = 0;
	if( NULL != pc_UsbMemDeviceInfo ) {
		ui32_UsbStatus = pc_UsbMemDeviceInfo->getStatus();
	}
//	if( 0 == pc_UsbMemDeviceInfo->getStatus() ) {
//		// 「USB NG」メッセージを表示.
//		Key_ServiceCustomPatternImport.showEnable( False );
//		Txt_ServiceCustomPatternUsbNg.showEnable( True );
//	} else {
//		// インポートキーを表示.
//		Key_ServiceCustomPatternImport.showEnable( True );
//		Txt_ServiceCustomPatternUsbNg.showEnable( False );
//	}

	// カスタムパターンキーの選択.
	short select = -1;
	if( 0 < m_eSelectCustomType ) {
		select = static_cast<short>( m_eSelectCustomType - 3 );
	}
	Rbt_ServiceCustomPattern.select( select );

	// 削除キーエリアの表示.
	if( 0 < m_eSelectCustomType &&
	    0 < strlen( m_pCustomPatternNameList[m_eSelectCustomType-3] ) ) {
		m_bShowDelete = True;
	}

	if( True == m_bShowDelete ) {
		Gra_FlameServiceCustomPatternDelete.changeFlameColor( UC_GPARTS_COLOR_BLACK );
		Key_ServiceCustomPatternDelete.showEnable( True );
		Key_ServiceCustomPatternDelete.select( m_bShowDecision );

		// 確定キー表示フラグ.
		if( True == m_bShowDecision ) {
			Key_ServiceCustomPatternDelDicide.showEnable( True );
			if( PNLE_DELSTATUS_Now == m_ssDeleteStatus ||
			    PNLE_DELSTATUS_Ok  == m_ssDeleteStatus ) {
				Key_ServiceCustomPatternDelDicide.select( True );
			} else {
				Key_ServiceCustomPatternDelDicide.select( False );
			}
		} else {
			Key_ServiceCustomPatternDelDicide.showEnable( False );
		}
	} else {
		Gra_FlameServiceCustomPatternDelete.changeFlameColor( UC_GPARTS_COLOR_WHITE );
		Key_ServiceCustomPatternDelete.showEnable( False );
		Key_ServiceCustomPatternDelDicide.showEnable( False );
		Txt_ServiceCustomPatternDelStatus.showEnable( False );
	}

	// メッセージ切換え.
	switch( m_ssDeleteStatus ) {
		case PNLE_DELSTATUS_Now:			// 削除中.
// comment 2016/05/05 【HCLT-Shalini】 【ZeusSBK】 【CQ527667】【NG Fix】 Replaced the symbol ID to fix the Quarter Font issue.
//			Txt_ServiceCustomPatternDelStatus.changeText( s_Deleting );
			Txt_ServiceCustomPatternDelStatus.changeText( s_pDeleting_W128H016I );
			Txt_ServiceCustomPatternDelStatus.showEnable( True );
			break;

		case PNLE_DELSTATUS_Ok:				// 削除成功.
			Txt_ServiceCustomPatternDelStatus.changeText( s_ServiceMemoryCheck_OK );
			Txt_ServiceCustomPatternDelStatus.showEnable( True );
			break;

		case PNLE_DELSTATUS_Ng:				// 削除失敗.
			Txt_ServiceCustomPatternDelStatus.changeText( s_ServiceMemoryCheck_NG );
			Txt_ServiceCustomPatternDelStatus.showEnable( True );
			break;

		default:
			Txt_ServiceCustomPatternDelStatus.showEnable( False );
			break;
	}

	// 削除中アニメ.
	if( PNLE_DELSTATUS_Now == m_ssDeleteStatus ) {
		ushort us_UnInstallingTextId;
		if( m_bAnimationFlg ) {
			us_UnInstallingTextId = s_EXPSlash;
		} else {
			us_UnInstallingTextId = s_EXPBackslash;
		}
		m_bAnimationFlg = !m_bAnimationFlg;
		Txt_ServiceCustomPatternAnimeUnInstalling.changeText( us_UnInstallingTextId );
		Txt_ServiceCustomPatternAnimeUnInstalling.showEnable( True );
	} else {
		Txt_ServiceCustomPatternAnimeUnInstalling.showEnable( False );
	}
// Comment 2015/07/20 HCLT-Surajit RQ-163[WP 1372] Hide the Import Area(import key, frame, USB NG).
// Comment 2017/11/29 【HCLT-Vishal】【Eagle】【制御構成変更_No.4】 Removing old function version check and else portion.
	if( False == m_bl_USBConnectionPermissionFlag ){ 				//USB接続許可設定の[一括設定]または[外部メモリー(サービス)]が[禁止]の場合.
		Key_ServiceCustomPatternImport.showEnable( False );			//インポート, 削除, 確定キー非表示.
	   	Txt_ServiceCustomPatternUsbNg.showEnable( False );			//USB search result status updation(USB NG/File NG)非表示.
    	Gra_FlameServiceCustomPatternImport.showEnable(False);		//Backgroundインポートエリア枠非表示.
	} else {
    	Gra_FlameServiceCustomPatternImport.showEnable(True);		//Backgroundインポートエリア枠表示.
		if( 0 == ui32_UsbStatus ) {
			// 「USB NG」メッセージを表示.
			Key_ServiceCustomPatternImport.showEnable( False );
			Txt_ServiceCustomPatternUsbNg.showEnable( True );		//USB search result status updation(USB NG/File NG)表示.
		} else {
			// インポートキーを表示.
			Key_ServiceCustomPatternImport.showEnable( True );		//インポート, 削除, 確定キー表示.
			Txt_ServiceCustomPatternUsbNg.showEnable( False );
		}
	}
}

//================================================================================================.
// 概要 : 80B91522 システム設定2／カスタムパターン ： ボタン（押された）.
//================================================================================================.
void PServiceSystemCustomPattern::procButtonOn( uchar option )
{
	if( PNLE_DELSTATUS_Now == m_ssDeleteStatus ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}

	switch( option ) {
		case BTNID_ServiceCustomPattern1:							// カスタムパターン1キー.
			m_eSelectCustomType = TYPE_PNLPTN_TYPE_Custom1;
			m_bShowDelete = False;
			m_bShowDecision = False;
			m_ssDeleteStatus = PNLE_DELSTATUS_Non;
			break;

		case BTNID_ServiceCustomPattern2:							// カスタムパターン2キー.
			m_eSelectCustomType = TYPE_PNLPTN_TYPE_Custom2;
			m_bShowDelete = False;
			m_bShowDecision = False;
			m_ssDeleteStatus = PNLE_DELSTATUS_Non;
			break;

		case BTNID_ServiceCustomPattern3:							// カスタムパターン3キー.
			m_eSelectCustomType = TYPE_PNLPTN_TYPE_Custom3;
			m_bShowDelete = False;
			m_bShowDecision = False;
			m_ssDeleteStatus = PNLE_DELSTATUS_Non;
			break;

		case BTNID_ServiceCustomPatternImport:						// インポートキー.
			if( 0 != m_eSelectCustomType ) {
				PServiceSystemCustomPatternFileList::setSelectCustomType( m_eSelectCustomType );
				nextGamen = &gp_ServiceSystemCustomPatternFileList;
				return;
			} else {
				MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
			}
			break;

		case BTNID_ServiceCustomPatternDelete:						// 削除キー.
			m_bShowDecision = True;
			break;

		case BTNID_ServiceCustomPatternDelDecision:					// 確定キー.
			m_ssDeleteStatus = PNLE_DELSTATUS_Now;
			APIC_FuncPatternSetting::newInstance( TYPE_PNLPTN_SETTING_TYPE_Copy )->req_delCustomPattern( m_eSelectCustomType, ans_deleteComplete );
			break;

		default: break;
	}
	setupGamen();
}

