//================================================================================================.
// 概要 : 80B91522 システム設定2／カスタムパターン ： カスタムパターンファイル名取得.
//================================================================================================.
void PServiceSystemCustomPattern::getCustomPatternFileName()
{
	APIC_FuncPatternSetting* p_FuncPatternSettingCopy = APIC_FuncPatternSetting::newInstance( TYPE_PNLPTN_SETTING_TYPE_Copy );

	TYPE_PNLPTN_TYPE e_Type = TYPE_PNLPTN_TYPE_Custom1;

	for( short i = 0; i < PNLD_PATTERN_NUM; i++ ) {
		TYPS_PNLPTN_Copy st_CopyTmp;

		if( True == p_FuncPatternSettingCopy->getDetailPattern( &st_CopyTmp, e_Type ) ) {
			// 取得成功.
			strcpy( m_pCustomPatternNameList[i], ( char* )st_CopyTmp.s_Info.uc_Name );
		} else {
			// 取得失敗.
			strcpy( m_pCustomPatternNameList[i], "" );
		}
		e_Type++;
	}
}

