//================================================================================================.
void PServiceSystemCustomPattern::deleteComplete()
{
	if( True == m_bCallDeleteStatus ) {
		m_ssDeleteStatus = PNLE_DELSTATUS_Ok;
	} else {
		m_ssDeleteStatus = PNLE_DELSTATUS_Ng;
	}
	getCustomPatternFileName();
}

Bool PServiceSystemCustomPatternFileList::m_bCallImportStatus;
TYPE_PNLPTN_TYPE PServiceSystemCustomPatternFileList::m_eImportCustomType;
//================================================================================================.
// 概要 : 80B9153 システム設定2／カスタムパターンファイル一覧 ： 画面開始処理.
//================================================================================================.
void PServiceSystemCustomPatternFileList::startGamen()
{
	// 親クラスの処理.
	PServiceToSystemMenu2P2Com::startGamen();

	// 初期化
	m_ssSelectIndex = -1;
	m_ssImportStatus = PNLE_IMPSTATUS_Non;
	m_ssFileListNum = 0;
	m_ssNowPage = 0;
	m_ssPageNum = 0;
	m_lst_CustomPatternFileList.delAll();

	// ファイル名リスト取得
	getCustomPatternFileList();
	// リストページ数設定
	setPageNum();
	setCustomPatternFileList();
}

//================================================================================================.
// 概要 : 80B9153 システム設定2／カスタムパターンファイル一覧 ： 画面セットアップ.
//================================================================================================.
void PServiceSystemCustomPatternFileList::setupGamen( short option )
{
	// 親クラスの処理.
	PServiceToSystemMenu2P2Com::setupGamen( option );

	// ファイル名の設定.
	for( short i = 0; i < PNLD_PATTERN_LISTNUM; i++ ) {
		if( NULL != m_pFileList[i] ) {
			Btn_ServiceCustomPatternFileList[i].changeExternalText( m_pFileList[i], 24 );
			Btn_ServiceCustomPatternFileList[i].showEnable( True );
		} else {
			Btn_ServiceCustomPatternFileList[i].showEnable( False );
		}
	}

	// 選択位置.
	Rbt_ServiceCustomPatternFileList.select( m_ssSelectIndex );

	// ページ数表示.
	char stPage[10];
	snprintf( stPage, sizeof( stPage ), "%d/%d", m_ssNowPage, m_ssPageNum );
	Tfd_ServiceCustomPatternFileListPage.changeTextString( ( uchar* )stPage );

	// インポート中状態メッセージ.
	switch( m_ssImportStatus ) {
		case PNLE_IMPSTATUS_Now:			// インポート中.
			Txt_ServiceCustomPatternFileListImpStatus.changeText( s_ITMImporting );
			Txt_ServiceCustomPatternFileListImpStatus.showEnable( True );
			break;

		case PNLE_IMPSTATUS_Ok:				// インポート成功.
			Txt_ServiceCustomPatternFileListImpStatus.changeText( s_ServiceMemoryCheck_OK );
			Txt_ServiceCustomPatternFileListImpStatus.showEnable( True );
			break;

		case PNLE_IMPSTATUS_Ng:				// インポート失敗.
			Txt_ServiceCustomPatternFileListImpStatus.changeText( s_ServiceMemoryCheck_NG );
			Txt_ServiceCustomPatternFileListImpStatus.showEnable( True );
			break;

		default:
			Txt_ServiceCustomPatternFileListImpStatus.showEnable( False );
			break;
	}

	// 削除中メッセージ.
	if( PNLE_IMPSTATUS_Now == m_ssImportStatus ) {
		ushort us_InstallingTextId;
		if( m_bAnimationFlg ) {
			us_InstallingTextId = s_EXPSlash;
		} else {
			us_InstallingTextId = s_EXPBackslash;
		}
		m_bAnimationFlg = !m_bAnimationFlg;
		Txt_ServiceCustomPatternFileListAnimeInstalling.changeText( us_InstallingTextId );
		Txt_ServiceCustomPatternFileListAnimeInstalling.showEnable( True );
		printLEDControl( False );
	} else {
		Txt_ServiceCustomPatternFileListAnimeInstalling.showEnable( False );
		if( 0 <= m_ssSelectIndex )
		{
			printLEDControl( True );
		}
		else
		{
			printLEDControl( False );
		}
	}
}

//================================================================================================.
// 概要 : 80B9153 システム設定2／カスタムパターンファイル一覧 ： ボタン（押された）.
//================================================================================================.
void PServiceSystemCustomPatternFileList::procButtonOn( uchar option )
{
	if( PNLE_IMPSTATUS_Now == m_ssImportStatus ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}

	switch( option ) {
		case BTNID_ServiceCustomPatternFileList1:				// カスタムパターンリスト1キー.
			m_ssSelectIndex = 0;
			m_ssImportStatus = PNLE_IMPSTATUS_Non;
			break;

		case BTNID_ServiceCustomPatternFileList2:				// カスタムパターンリスト2キー.
			m_ssSelectIndex = 1;
			m_ssImportStatus = PNLE_IMPSTATUS_Non;
			break;

		case BTNID_ServiceCustomPatternFileList3:				// カスタムパターンリスト3キー.
			m_ssSelectIndex = 2;
			m_ssImportStatus = PNLE_IMPSTATUS_Non;
			break;

		case BTNID_ServiceCustomPatternFileList4:				// カスタムパターンリスト4キー.
			m_ssSelectIndex = 3;
			m_ssImportStatus = PNLE_IMPSTATUS_Non;
			break;

		case BTNID_ServiceCustomPatternFileList5:				// カスタムパターンリスト5キー.
			m_ssSelectIndex = 4;
			m_ssImportStatus = PNLE_IMPSTATUS_Non;
			break;

		case BTNID_ServiceCustomPatternFileListPageUp:			// ↑キー.
			if( m_ssPageNum <= 1 ) {
				return;
			}
			m_ssNowPage--;
			if( 0 >= m_ssNowPage ) {
				m_ssNowPage = m_ssPageNum;
			}
			setCustomPatternFileList();
			m_ssSelectIndex = -1;
			m_ssImportStatus = PNLE_IMPSTATUS_Non;
			break;

		case BTNID_ServiceCustomPatternFileListPageDown:		// ↓キー.
			if( m_ssPageNum <= 1 ) {
				return;
			}
			m_ssNowPage++;
			if( m_ssPageNum < m_ssNowPage ) {
				m_ssNowPage = 1;
			}
			setCustomPatternFileList();
			m_ssSelectIndex = -1;
			m_ssImportStatus = PNLE_IMPSTATUS_Non;
			break;

		default: break;
	}
	setupGamen();
}

