// 概要 : 80B9153 システム設定2／カスタムパターンファイル一覧 ： OKキー押下.
//================================================================================================.
void PServiceSystemCustomPatternFileList::procOk( uchar option )
{
	if( PNLE_IMPSTATUS_Now == m_ssImportStatus ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}

	nextGamen = &gp_ServiceSystemCustomPattern;
}

//================================================================================================.
// 概要 : 80B9153 システム設定2／カスタムパターンファイル一覧 ： スタート押下.
//================================================================================================.
void PServiceSystemCustomPatternFileList::procStart( uchar option )
{
	if( PNLE_IMPSTATUS_Now == m_ssImportStatus ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}

	// インポート開始.
	if( 0 <= m_ssSelectIndex )
	{
		m_ssImportStatus = PNLE_IMPSTATUS_Now;
		APIC_FuncPatternSetting::newInstance( TYPE_PNLPTN_SETTING_TYPE_Copy )->req_setCustomPattern( m_eImportCustomType, ( char* )m_pFileList[m_ssSelectIndex], ans_importComplete );

		setupGamen();
	}
}

