// 概要		:80B91030 サービス・プロセス調整・除電電圧チョイス : ボタン（押された）.
// 戻り値	:なし.
// 備考		:.
//================================================================================================.
void PServiceRemovalElectricityVoltageChoice::procButtonOn( uchar option )
{
	ushort ii = 0;				// ループインデックス.
	switch( option ) {
		case  19:	// マイナスキー.
			subIndi();		// 減算する.
			tbl_SREVCCAdj[m_ss_select].AutoFlag = 1;
			break;
		case  18:	// プラスキー.
			addIndi();		// 加算する.
			tbl_SREVCCAdj[m_ss_select].AutoFlag = 1;
			break;
		case 200:	// 自動キー.
			setPrinterIndi( tbl_SREVCCAdj[m_ss_select].idxAutoAdj, 1 );
			tbl_SREVCCAdj[m_ss_select].AutoFlag = 0;
			break;
		case  60:	// 元に戻すキー.
			setPrinterIndi( tbl_SREVCCAdj[m_ss_select].idxAdj, ss_PrinterAdjustRemobeVoltageAdj[m_ss_select] );	// 手動入力値.
			setPrinterIndi( tbl_SREVCCAdj[m_ss_select].idxAutoAdj, ss_PrinterAdjustRemobeVoltageAutoAdj[m_ss_select] );	// 自動設定値.
			break;
		default:	// 上記以外.
			m_ss_select = 0;
			for( ii = 0; ii < uc_SREVCCAdj; ii++ ) {
				if( tbl_SREVCCAdj[ii].uc_bid == option ) {	// 選択ボタンの特定.
					m_ss_select = ii;		// 選択ボタン設定.
					setPrinterIndi( tbl_SREVCCAdj[ii].idxAdj );	// 選択調整値設定.
					break;
				}
			}
			break;
	}
	//「元に戻す」以外.
	if( 60 != option ) {
		setPrinterIndi( tbl_SREVCCAdj[m_ss_select].idxAutoAdj, tbl_SREVCCAdj[m_ss_select].AutoFlag );
	}
	setupGamen();	// 表示画面のセットアップ.
}
