// 概要		:80B91030 サービス・プロセス調整・除電電圧チョイス : 表示画面のセットアップ.
// 戻り値	:なし.
// 備考		:.
//================================================================================================.
void PServiceRemovalElectricityVoltageChoice::setupGamen( short option )
{
// Comment 2015/02/02 HCLT-Sunil [Compilation Switch ID: 1557] for HeliosL support.
// Comment 2019/07/26 [HCLT_Paul] [IT6_HeliosMLK] [ Seigyu.10 ] Adding the HeliosMLK compiler switch.
#ifndef DEF_HeliosMLKCus
	Rbt_ServiceRemovalElectricityVoltageChoice.select( m_ss_select );	// ボタン選択.
#endif //#ifndef DEF_HeliosCus.
	Key_ServiceRemovalElectricityVoltageChoiceAuto.select( ( 1 == tbl_SREVCCAdj[m_ss_select].AutoFlag )? 0: 1 );	// 自動キー選択状態設定.
	Key_ServiceRemovalElectricityVoltageChoiceAuto.showEnable( True );	// 自動キー表示.
	PServiceNoFunctionCodeCom::setupGamen( option );	// 表示部品のセットアップ.
	// 設定値を表示.
	ushort ii = 0;				// ループインデックス.
	for( ii = 0; ii < uc_SREVCCAdj; ii++ ) {
		Btx_NumSRemovalElectricityVoltageChoice[ii] = ( float )getPrinterIndi( tbl_SREVCCAdj[ii].idxAdj );	// 調整値表示設定.
		tbl_SREVCCAdj[ii].AutoFlag = getPrinterIndi( tbl_SREVCCAdj[ii].idxAutoAdj ); // 調整値「自動」の取得、表示.
		if( 1 != tbl_SREVCCAdj[ii].AutoFlag ) {	// 自動キー選択状態判定.
			Btx_NumSRemovalElectricityVoltageChoice[ii].showEnableAdd( &Inp_SRemovalElectricityVoltageChoice[ii], False );
			Btx_NumSRemovalElectricityVoltageChoice[ii].showEnableAdd( &Txt_SRemovalElectricityVoltageChoiceAuto[ii], True );
		} else {
			Btx_NumSRemovalElectricityVoltageChoice[ii].showEnableAdd( &Txt_SRemovalElectricityVoltageChoiceAuto[ii], False );
			Btx_NumSRemovalElectricityVoltageChoice[ii].showEnableAdd( &Inp_SRemovalElectricityVoltageChoice[ii], True );
		}
	}
}
