//================================================================================================.
// 	PServiceChargeVoltageAdjust : I0B1040000 : Event handling.
//================================================================================================.
void PServiceChargeVoltageAdjust::procButtonOn(uchar option)
{	
	switch( option ){
  		case BTNID_CHARGE_VOLTAGE_ADJUST_MINUS: 
			subPrinterIndi( TYPE_PrinterAdjustElectrifiedVoltage); // Subtract the value by step 1.
			break; 
  		case BTNID_CHARGE_VOLTAGE_ADJUST_PLUS: 
			addPrinterIndi( TYPE_PrinterAdjustElectrifiedVoltage ); // Add the value by step 1.
			break; 
  		case BTNID_CHARGE_VOLTAGE_ADJUST_RESTORE: 
			getPrinterIndiInSystem( TYPE_PrinterAdjustElectrifiedVoltage ); // Restore to previously stored value.
			break;
  		default: 
			break;
 	}
	setupGamen();
}	

