//================================================================================================.
// 概要 : 80B91545 サービス・システム設定1・TPLevel ： 画面開始処理.
//================================================================================================.
void PServiceSystemTPLevelSetting::startGamen()
{
	PServiceToSystemMenuCom::startGamen();
	APIC_MachineSetting* pc_MachineSetting = APIC_MachineSetting::newInstance();
	switch( pc_MachineSetting->getGDPElectrostaticTPAdjust() ) {
		case TYPE_GDPElectrostaticTPAdjust_None:
			sc_TPLevel = 0;
			break;
		case TYPE_GDPElectrostaticTPAdjust_M2:
			sc_TPLevel = -2;
			break;
		case TYPE_GDPElectrostaticTPAdjust_M1:
			sc_TPLevel = -1;
			break;
		case TYPE_GDPElectrostaticTPAdjust_N:
			sc_TPLevel = 0;
			break;
		case TYPE_GDPElectrostaticTPAdjust_P1:
			sc_TPLevel = 1;
			break;
		case TYPE_GDPElectrostaticTPAdjust_P2:
			sc_TPLevel = 2;
			break;
		default:
			sc_TPLevel = 0;
			break;
	}
	m_sc_TPLevelBackup = sc_TPLevel;
}

//================================================================================================.
// 概要 : 80B91545 サービス・システム設定1・TPLevel ： 画面セットアップ.
//================================================================================================.
void PServiceSystemTPLevelSetting::setupGamen( short option )
{
	PServiceToSystemMenuCom::setupGamen();
	Btx_ServiceSystemTPLevelSettingNum = ( float )sc_TPLevel;
}

//================================================================================================.
// 概要 : 80B91545 サービス・システム設定1・TPLevel ： ＯＫキー.
//================================================================================================.
void PServiceSystemTPLevelSetting::procOk( uchar option )
{
	PServiceToSystemMenuCom::procOk( option );

	APIC_MachineSetting* pc_MachineSetting = APIC_MachineSetting::newInstance();
	switch( sc_TPLevel ) {
		case -2:
			pc_MachineSetting->setGDPElectrostaticTPAdjust( TYPE_GDPElectrostaticTPAdjust_M2 );
			break;
		case -1:
			pc_MachineSetting->setGDPElectrostaticTPAdjust( TYPE_GDPElectrostaticTPAdjust_M1 );
			break;
		case 0:
			pc_MachineSetting->setGDPElectrostaticTPAdjust( TYPE_GDPElectrostaticTPAdjust_N );
			break;
		case 1:
			pc_MachineSetting->setGDPElectrostaticTPAdjust( TYPE_GDPElectrostaticTPAdjust_P1 );
			break;
		case 2:
			pc_MachineSetting->setGDPElectrostaticTPAdjust( TYPE_GDPElectrostaticTPAdjust_P2 );
			break;
		default:
			break;
	}
	if( NULL != ppc_PanelHard
	    && False == APIC_SystemInfo::newInstance()->isSlidePanel()
	    && m_sc_TPLevelBackup != sc_TPLevel ) {		// 値が変更されている場合.
		ppc_PanelHard->setSensitivitySlideless( ans_serviceGDPLevelSetting );
		nextGamen = &gp_ServiceGDPLevelSettingWait;
	}
}

//================================================================================================.
// 概要 : 80B91545 サービス・システム設定1・TPLevel ： ボタン（押された）.
//================================================================================================.
void PServiceSystemTPLevelSetting::procButtonOn( uchar option )
{
	switch( option ) {
		case BTNID_ServiceSystemTPLevelSetting_Down:
			if( -2 < sc_TPLevel ) {
				sc_TPLevel--;
			}
			else {
				setBuzzerType( PCGE_BuzzerType_InputNg );
			}
			break;
		case BTNID_ServiceSystemTPLevelSetting_Up:
			if( 2 > sc_TPLevel ) {
				sc_TPLevel++;
			}
			else {
				setBuzzerType( PCGE_BuzzerType_InputNg );
			}
			break;
		default:
			break;
	}
	setupGamen();
}

