// 52C91590_EXT システム設定／指定アプリ変更許可設定：ボタン押下処理.
// ==================================================================.
void PServiceToSystemAppInitialPermission::procButtonOn( uchar option )
{
	switch( option ) {
		case BTNID_AppInitialPermission_Permit:
			// 許可押下時.
			m_b_select = True;
			break;
		case BTNID_AppInitialPermission_Prohibit:
			// 禁止押下時.
			m_b_select = False;
			break;
		default:
			break;
	}

	setupGamen();
}

// ==================================================================.
// 52C91590_EXT システム設定／指定アプリ変更許可設定：OKキー押下処理.
// ==================================================================.
void PServiceToSystemAppInitialPermission::procOk( uchar option )
{
	// 指定アプリ変更許可設定を取得.
	APIC_KIOSKSetting* pc_KIOSKSetting = APIC_KIOSKSetting::newInstance();
	if( NULL == pc_KIOSKSetting ) {
//2019/06/17 Comment [HCLT_Krishnakumar][EagleH][N Rank] Removed unwanted detailed code.
//// 2015/11/05 【HCLT-Dhivya】 【ZeusS_ZX0】 【制御構成変更_No.76-1】Detail macro is passed in API.
//		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if (NULL != pc_BFW_System){
//    		pc_BFW_System->registDetailCode(PNLD_DetailCode_Service_0x1900030100672401);
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}
	// 指定アプリ変更許可設定を設定.
	pc_KIOSKSetting->setKIOSKChangePermissionSetting( m_b_select );

// Comment 2016/12/14 HCLT-Gomathy [IT5_4.1] [機器構成変更_No.6] Changing the nextGamen to support isOK_IT5_Type10().
	//nextGamen = &gp_ServiceSystemMenu2P2_DoAm;		// 91500b-3 システム設定2／メニュー 3P選択時.
// Comment 2017/11/29 【HCLT-Vishal】【Eagle】【制御構成変更_No.4】 Removing old function version check and if portion.
	nextGamen = &gp_ServiceSystemMenu2P3_DoAm;
}
// comment 2015/08/28 HCLT-Ezhil [ZeusS_ZX0][RQ-163] [WP1387] Display condition of Import setting key.
//================================================================================================.
/**
* @brief 	: Screen start processing .
* @note 	: None.
* @param 	: None.
* @return 	: None.
* @author 	: 2015/08/28 HCLT_Ezhil.
*/
//================================================================================================.
void PServiceRemoteFWUpdateMenu::startGamen()
{
	PServiceNoFunctionCodeCom::startGamen();
// Comment 2017/11/29 【HCLT-Vishal】【Eagle】【制御構成変更_No.4】 Removing old function version check condition.
	PNLC_USBConnectionPermission c_UsbPermission;
	PNLE_EnableUSBConnectionPermissionForAll e_usbAll = c_UsbPermission.getEnableUSBConnectionPermissionForAll();
	PNLE_EnableUSBConnectionPermissionForService e_usbforService = c_UsbPermission.getEnableUSBConnectionPermissionForService();
	if(( PNLE_EnableUSBConnectionPermissionForAll_Disable == e_usbAll ) || ( PNLE_EnableUSBConnectionPermissionForService_Disable == e_usbforService )) {
		m_bl_USBConnectionPermissionFlag = False;
	} else {
		m_bl_USBConnectionPermissionFlag = True;
	}
}
//関数------------------------------------------------------------------------------------------------------------------.
//概要    ：画面更新処理.
//備考    ：.
//戻値    ：なし.
//作成者  ：OPS1大西.
//================================================================================================.
// 概要		: PServiceRemoteFWUpdateMenu : 90B94110 本体自動更新設定／メニュー : 画面遷移.
//================================================================================================.
void PServiceRemoteFWUpdateMenu::setupGamen( short option )
{
	PServiceNoFunctionCodeCom::setupGamen( option );

// 2015/03/11 [MAv3][RQ-243] XMPPによるリアルタイム指示 日立 村上(幸).
	Bool bl_ROIMServerUseUnuse;			// 遠隔サービス機能の使用設定（サービス）.
	Bool bl_ROIMServerUseUnuse_Admin;	// 遠隔サービス機能の使用設定（管理者）.
	APIC_RoimWscDataIF *pc_RoimWscDataIF = APIC_RoimWscDataIF::newInstance();
//2019/06/17 Comment [HCLT_Krishnakumar][EagleH][N Rank] Removed unwanted detailed code.
//// 2015/11/05 【HCLT-Dhivya】 【ZeusS_ZX0】 【制御構成変更_No.76-1】Detail macro is passed in API.
//	LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
	if( NULL == pc_RoimWscDataIF ) {
//2019/06/17 Comment [HCLT_Krishnakumar][EagleH][N Rank] Removed unwanted detailed code.
//// 2015/11/05 【HCLT-Dhivya】 【ZeusS_ZX0】 【制御構成変更_No.76-1】Detail macro is passed in API.
//		if (NULL != pc_BFW_System){
//  			 pc_BFW_System->registDetailCode(PNLD_DetailCode_Service_0x1900660100F72501);
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}

	APIC_IISWClient* pc_IISWClient = PnlComGetIISWClient();
	APIC_SystemSetting* pc_SystemSetting = PnlComGetSystemSetting();
	if( NULL == pc_IISWClient ) { 
//2019/06/17 Comment [HCLT_Krishnakumar][EagleH][N Rank] Removed unwanted detailed code.
//// 2015/11/05 【HCLT-Dhivya】 【ZeusS_ZX0】 【制御構成変更_No.76-1】Detail macro is passed in API.
//		if (NULL != pc_BFW_System){
//  			 pc_BFW_System->registDetailCode(PNLD_DetailCode_Service_0x1900660100F72601);
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" ); 
		return; 
	}
	APIC_FWUpdateSetting* pc_FWUpdateSetting = PnlComGetFWUpdateSetting();
	if( NULL == pc_FWUpdateSetting ) { 
//2019/06/17 Comment [HCLT_Krishnakumar][EagleH][N Rank] Removed unwanted detailed code.
//// 2015/11/05 【HCLT-Dhivya】 【ZeusS_ZX0】 【制御構成変更_No.76-1】Detail macro is passed in API.
//		if (NULL != pc_BFW_System){
//   			 pc_BFW_System->registDetailCode(PNLD_DetailCode_Service_0x1900660100F72701);
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" ); 
		return; 
	}

	if( NULL == pc_SystemSetting ) { 
//2019/06/17 Comment [HCLT_Krishnakumar][EagleH][N Rank] Removed unwanted detailed code.
//// 2015/11/05 【HCLT-Dhivya】 【ZeusS_ZX0】 【制御構成変更_No.76-1】Detail macro is passed in API.
//		if (NULL != pc_BFW_System){
//   			 pc_BFW_System->registDetailCode(PNLD_DetailCode_Service_0x1900660100F72801);
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" ); 
		return; 
	}

	Bool bl_UpdateNow = False;

// 2015/03/11 [MAv3][RQ-243] XMPPによるリアルタイム指示 日立 村上(幸).
	pc_RoimWscDataIF->getRemoteServiceEnable( &bl_ROIMServerUseUnuse );				// 遠隔ｻｰﾋﾞｽ機能設定を取得する(サービス）.
	pc_RoimWscDataIF->getWWRemoteServicePermit( &bl_ROIMServerUseUnuse_Admin );		// 遠隔ｻｰﾋﾞｽ機能設定を取得する（管理者）.

// comment 2015.08.12 [CQ516452] No.14 本体自動更新設定_キー非表示対応 日立 井原.
// comment 2015/10/22 [CQ519921] ｻｰﾋﾞｽ設定のリモートサービス設定変更時のみ本体自動更新キーを非表示にする対応 日立 村上(幸).
//	if ( ( True == bl_ROIMServerUseUnuse ) && ( True == bl_ROIMServerUseUnuse_Admin ) ) {
	if ( ( True == bl_ROIMServerUseUnuse ) ) {
		Key_GoToAutoUpdateSettings.showEnable( False );				// 自動更新設定キー非表示.
	} else {
		Key_GoToAutoUpdateSettings.showEnable( True );				// 自動更新設定キー表示.		
	}
	
	// 自動更新設定が「使用する」の場合.
	if( ( True == pc_FWUpdateSetting->getClientFWUpdateSetting() )
	|| ( True == pc_FWUpdateSetting->getClientFWUpdateSetting2() )
// 2015/03/11 [MAv3][RQ-243] XMPPによるリアルタイム指示 日立 村上(幸).
	|| ((True == bl_ROIMServerUseUnuse) && (True == bl_ROIMServerUseUnuse_Admin)) ){
		// FW更新が可能であれば表示する.
		// 取得プロトコルにSMBを選択している時は更新リストに差分がある場合に表示.
		// 取得プロトコルにHTTPを選択している時は更新用ファイルがダウンロード済みの場合に表示.
		if( True == pc_IISWClient->getClientFWUpdateExecute() ) {
			bl_UpdateNow = True;
		}
	}

	// 即時更新キーの表示/非表示.
	Key_GoToUpdateNow.showEnable( bl_UpdateNow );

	Bool bl_GoToServerKey = True;
	if( 0x00 == ( 0x01 & getSwDipSwitch( DEFSOFTWARESW162 ) ) ) {
		bl_GoToServerKey = False;
	}
	APIC_HddInfo* pc_HddInfo = PnlComGetHddInfo();		// ＨＤＤ情報（ＡＰＩ）・インスタンス取得.
	if( NULL == pc_HddInfo ) {
//2019/06/17 Comment [HCLT_Krishnakumar][EagleH][N Rank] Removed unwanted detailed code.
//// 2015/11/05 【HCLT-Dhivya】 【ZeusS_ZX0】 【制御構成変更_No.76-1】Detail macro is passed in API.
//		if (NULL != pc_BFW_System){
//   			 pc_BFW_System->registDetailCode(PNLD_DetailCode_Service_0x1900660100F72901);
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	} else {
		if( False == pc_HddInfo->getHddExist() ) {
			bl_GoToServerKey = False;
		}
	}

// comment 2015/11/10 日立 森本郁 [MAv4][RQ-503]WW指示サーバー運用の拡張対応.
//	Key_GoToRelayServerSettings.showEnable( bl_GoToServerKey );			// 中継ｻｰﾊﾞｰ設定.
	if( ( False == bl_GoToServerKey ) || ( True == bl_ROIMServerUseUnuse ) ) {
		Key_GoToRelayServerSettings.showEnable( False );
	} else {
		Key_GoToRelayServerSettings.showEnable( True );
	}
	Key_GoToSendServerLog.showEnable( bl_GoToServerKey );				// ｻｰﾊﾞｰﾛｸﾞ送信.
	Key_GoToRelayServerLogConfirmation.showEnable( bl_GoToServerKey );	// ｻｰﾊﾞｰﾛｸﾞ表示.
	if( True == pc_SystemSetting->getSecurityLevelUpOn() ) {
		Key_GoToExportMFPsettings.showEnable( False );		//本体設定ｴｸｽﾎﾟｰﾄ表示.
	}
	else {
		Key_GoToExportMFPsettings.showEnable( True );		//本体設定ｴｸｽﾎﾟｰﾄ表示.
	}
// comment 2015/07/15 OPS1-MSE永野 [ZeusS_ZX0][RQ-387]本体設定インポート機能の追加.
// comment 2015/08/28 HCLT-Ezhil [ZeusS_ZX0][RQ-163] [WP1387] Display condition of Import setting key, added condition for RQ-163, also RQ-387 condition corrected as per spec.
//	if ( True == PnlComGetSoftDipSw()->getSoftDipSwBitForPanelSpecNo( 72, 2 ) ) {	// DipSW No.72 bit2が有効の場合.
//		Key_GoToImportMFPsettings.showEnable( True );	// 本体設定インポート表示.
//	} else {
//		Key_GoToImportMFPsettings.showEnable( False );	// 本体設定インポート非表示.
//	}
	if ( ( False == PnlComGetSoftDipSw()->getSoftDipSwBitForPanelSpecNo( 72, 2 ) ) 	// DipSW No.72 bit2が有効の場合.
		|| ( False == m_bl_USBConnectionPermissionFlag ) ) {						//USB接続許可設定の[一括設定]または[外部メモリー(サービス)]が[禁止]の場合.
		Key_GoToImportMFPsettings.showEnable( False );	// 本体設定インポート非表示.
	} else {
		Key_GoToImportMFPsettings.showEnable( True );	// 本体設定インポート表示.
	}
// 2022/04/07 RQ-931 Sky Start.
	if(( False == m_bl_USBConnectionPermissionFlag )			// USB接続許可設定の[一括設定]または[外部メモリー(サービス)]が[禁止]の場合.
	 ||( True == pc_SystemSetting->getSecurityLevelUpOn() )		// セキュリティ強化設定「ON」の場合.
	 ||( False == PLBC_FuncVersionCheck::isOK_IT6_Type4() ) ) {
		Key_GoToMachineSettingsJson.showEnable( False );		// 本体設定JSON形式非表示.
	} else {
		Key_GoToMachineSettingsJson.showEnable( True );		// 本体設定JSON形式表示.
	}
// 2022/04/07 RQ-931 Sky End.
}
//================================================================================================.
// 概要		: PServiceRemoteFWUpdateMenu : 90B94110 本体自動更新設定／メニュー : 画面遷移.
//================================================================================================.
void PServiceRemoteFWUpdateMenu::procGoToPage( uchar option )
{
	PServiceRemoteFWUpdateUSBExportInfo* pc_RemoteFWUpdateUSBExportInfo = PServiceRemoteFWUpdateUSBExportInfo::newInstance();
// 2022/04/07 RQ-931 Sky Start.
	PServiceRemoteFWUpdateMachineSettingsJsonInfo* pc_RemoteFWUpdateMachineSettingsJsonInfo = PServiceRemoteFWUpdateMachineSettingsJsonInfo::newInstance();
// 2022/04/07 RQ-931 Sky End.
	if(( NULL == pc_RemoteFWUpdateUSBExportInfo ) || ( NULL == pc_RemoteFWUpdateMachineSettingsJsonInfo )) {
//2019/06/17 Comment [HCLT_Krishnakumar][EagleH][N Rank] Removed unwanted detailed code.
//// 2015/11/05 【HCLT-Dhivya】 【ZeusS_ZX0】 【制御構成変更_No.76-1】Detail macro is passed in API.
//		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if (NULL != pc_BFW_System){
//    		pc_BFW_System->registDetailCode(PNLD_DetailCode_Service_0x1900020100F73001);
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}
	switch( option ) {
		case	BTNID_KEY_SERV_AUTOUPDATE_AUTOUPDATESETTINGS:	// 自動更新設定キー.
			nextGamen = &gp_ServiceMFPAutoUpdateClientSelectServer;	//E0B9410000 本体自動更新設定／自動更新設定／サーバー選択.
			break ;
		case	BTNID_KEY_SERV_AUTOUPDATE_RELAYSERVERSETTINGS:	// 中継ｻｰﾊﾞｰ設定キー.
			gp_ServiceRemoteFWUpdateServerSetting.setFromMenuFlg( True );
			nextGamen = &gp_ServiceRemoteFWUpdateServerSetting;	// 90B94400 本体自動更新設定／中継ｻｰﾊﾞｰ設定 画面.
			break;
		case	BTNID_KEY_SERV_AUTOUPDATE_SENDUPDATELOG:
			gp_ServiceRemoteFWUpdateClientLogForwardSetting.setFromMenuFlg( True );
			nextGamen = &gp_ServiceRemoteFWUpdateClientLogForwardSetting;
			break;
		case	BTNID_KEY_SERV_AUTOUPDATE_SENDSERVERLOG:
			gp_ServiceRemoteFWUpdateServerLogForwardSetting.setFromMenuFlg( True );
			nextGamen = &gp_ServiceRemoteFWUpdateServerLogForwardSetting;
			break;

		case BTNID_KEY_SERV_AUTOUPDATE_CONFIRMUPDATELOG:		// 更新ログ表示キー.
			nextGamen = &gp_ServiceRemoteFWUpdateLogConfirm;	// 90B95070 本体自動更新設定／更新ログ表示.
			break;
		case BTNID_KEY_SERV_AUTOUPDATE_RELAYSERVERLOGCONFIRM:	// サーバーログ表示キー.
			nextGamen = &gp_ServiceRemoteFWUpdateRelaySeverLogConfirm;	// 90B95080 本体自動更新設定／サーバーログ表示.
			break;
		case BTNID_KEY_SERV_AUTOUPDATE_UPDATENOW:				// 即時更新キー.
			nextGamen = &gp_ServiceRemoteFWUpdateImmediately;	// 90B95090 本体自動更新設定／即時更新.
			break;
// comment 2015/07/15 OPS1-MSE永野 [ZeusS_ZX0][RQ-387]本体設定インポート機能の追加.
		case BTNID_KEY_SERV_AUTOUPDATE_IMPORTMFPSETTINGS:
			pc_RemoteFWUpdateUSBExportInfo->initImportSetting();		// 初期化.
			nextGamen = &gp_ServiceRemoteFWUpdateMainSettingImport;	// K4B9520000 本体自動更新設定／本体設定インポート
			break;
		case BTNID_KEY_SERV_AUTOUPDATE_EXPORTMFPSETTINGS:		// 本体設定エクスポートキー.
			pc_RemoteFWUpdateUSBExportInfo->initExportResult();	// エクスポート結果初期化.
			pc_RemoteFWUpdateUSBExportInfo->initPassword();		// パスワード初期化.
			pc_RemoteFWUpdateUSBExportInfo->setExportStatus( PNLE_RemoteFWUpdateUSBExportPreProc );	// エクスポート状態初期化（実行前）.
			pc_RemoteFWUpdateUSBExportInfo->initExportSetting();		// エクスポート設定初期化 .
			nextGamen = &gp_ServiceRemoteFWUpdateMainSettingExport;		// 90B95100 本体自動更新設定／本体設定ｴｸｽﾎﾟｰﾄ.
			break;
		case BTNID_KEY_SERV_AUTOUPDATE_DECRYPTPASSWORD:				// 複合化パスワードキー.
			nextGamen = &gp_ServiceRemoteFWUpdateDecryptPasswordSelectServer;	// E0B9412000 本体自動更新設定／復号化パスワード設定／サーバー選択.
			break;
// 2022/04/07 RQ-931 Sky Start.
		case BTNID_KEY_SERV_AUTOUPDATE_MACHINESETTINGJSON:
			pc_RemoteFWUpdateMachineSettingsJsonInfo->initSetting();
			pc_RemoteFWUpdateUSBExportInfo->setUSBExportImportMode(PNLE_USBExportImportMode_MachineSettingsJson);
			nextGamen = &gp_ServiceRemoteFWUpdateMachineSettingsJson;	// zcB9530000 本体自動更新設定／本体設定JSON形式.
			break;
// 2022/04/07 RQ-931 Sky Start.
		default:
			break;
	}
}
