// 中継ｻｰﾊﾞｰ設定.
uchar PServiceRemoteFWUpdateServerSettingCom::m_e_RemoteFWUpdateServerSettingGamen = PNLE_RemoteFWUpdateServerSettingGamen_RelayServer;

//================================================================================================.
// 概要		: PServiceRemoteFWUpdateServerSettingCom : 本体自動更新設定／中継ｻｰﾊﾞｰ設定 共通 : 画面更新処理.
//================================================================================================.
void PServiceRemoteFWUpdateServerSettingCom::setupGamen( short option )
{
	// 親クラスを呼ぶ.
	PServiceNoFunctionCodeCom::setupGamen();

	switch( m_e_RemoteFWUpdateServerSettingGamen ) {
		case PNLE_RemoteFWUpdateServerSettingGamen_RelayServer:				// 中継ｻｰﾊﾞｰ.
			Rbt_RelayServerSettingsMenu.select( 0 );
			break;
		case PNLE_RemoteFWUpdateServerSettingGamen_FileRetrievalURL:		// ﾌｧｲﾙ取得設定URL.
			Rbt_RelayServerSettingsMenu.select( 1 );
			Rbt_FileRetrievalSettingMenu.select( 0 );
			break;
		case PNLE_RemoteFWUpdateServerSettingGamen_FileRetrievalLoginName:	// ユーザー名.
			Rbt_RelayServerSettingsMenu.select( 1 );
			Rbt_FileRetrievalSettingMenu.select( 1 );
			break;
		case PNLE_RemoteFWUpdateServerSettingGamen_FileRetrievalPassword:	// パスワード.
			Rbt_RelayServerSettingsMenu.select( 1 );
			Rbt_FileRetrievalSettingMenu.select( 2 );
			break;
		case PNLE_RemoteFWUpdateServerSettingGamen_FileRetrievalProxy:		// Proxy.
			Rbt_RelayServerSettingsMenu.select( 1 );
			Rbt_FileRetrievalSettingMenu.select( 3 );
			break;
		case PNLE_RemoteFWUpdateServerSettingGamen_FileRetrievalTimeout:	// 接続タイムアウト.
			Rbt_RelayServerSettingsMenu.select( 1 );
			Rbt_FileRetrievalSettingMenu.select( 4 );
			break;
		case PNLE_RemoteFWUpdateServerSettingGamen_PollingTime:				// ポーリング間隔.
			Rbt_RelayServerSettingsMenu.select( 2 );
			break;
		case PNLE_RemoteFWUpdateServerSettingGamen_RetryTime:				// リトライ間隔.
			Rbt_RelayServerSettingsMenu.select( 3 );
			break;
		case PNLE_RemoteFWUpdateServerSettingGamen_HTTPAuth:				// HTTP認証HTTP認証.
			Rbt_RelayServerSettingsMenu.select( 5 );
			Rbt_RelayServerHTTPAuthMenu.select( 0 );
			break;
		case PNLE_RemoteFWUpdateServerSettingGamen_HTTPAuthLoginName:		// ユーザー名.
			Rbt_RelayServerSettingsMenu.select( 5 );
			Rbt_RelayServerHTTPAuthMenu.select( 1 );
			break;
		case PNLE_RemoteFWUpdateServerSettingGamen_HTTPAuthPassword:		// パスワード.
			Rbt_RelayServerSettingsMenu.select( 5 );
			Rbt_RelayServerHTTPAuthMenu.select( 2 );
			break;
		case PNLE_RemoteFWUpdateServerSettingGamen_SMBAuth:					// SMB認証SMB認証.
			Rbt_RelayServerSettingsMenu.select( 4 );
			Rbt_RelayServerSMBAuthMenu.select( 0 );
			break;
		case PNLE_RemoteFWUpdateServerSettingGamen_SMBAuthLoginName:		// ユーザー名.
			Rbt_RelayServerSettingsMenu.select( 4 );
			Rbt_RelayServerSMBAuthMenu.select( 1 );
			break;
		case PNLE_RemoteFWUpdateServerSettingGamen_SMBAuthPassword:			// パスワード.
			Rbt_RelayServerSettingsMenu.select( 4 );
			Rbt_RelayServerSMBAuthMenu.select( 2 );
			break;
		case PNLE_RemoteFWUpdateServerSettingGamen_SMBAuthLogStorageFolder:	// ログ保存フォルダ.
			Rbt_RelayServerSettingsMenu.select( 4 );
			Rbt_RelayServerSMBAuthMenu.select( 3 );
			break;
// comment 2016/07/07 MSE寺田 [IT5_3.3][RQ-440][WBS35] 「フォルダー暗号化」キーを選択状態にする.
		case PNLE_RemoteFWUpdateServerSettingGamen_SMBAuthEncryptFolder:	// フォルダの暗号化.
			Rbt_RelayServerSettingsMenu.select( 4 );
			Rbt_RelayServerSMBAuthMenu.select( 4 );
			break;
		default: break;
	}

	PLBC_MFPAutoUpdateServer* pc_MFPAutoUpdateServer = NULL;
	pc_MFPAutoUpdateServer = PLBC_MFPAutoUpdateServer::getInstance();

	if( NULL == pc_MFPAutoUpdateServer ) {
//2019/06/17 Comment [HCLT_Krishnakumar][EagleH][N Rank] Removed unwanted detailed code.
//// 2015/11/05 【HCLT-Dhivya】 【ZeusS_ZX0】 【制御構成変更_No.76-1】Detail macro is passed in API.
//		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if (NULL != pc_BFW_System){
//    		pc_BFW_System->registDetailCode(PNLD_DetailCode_Service_0x1900660100F73101);
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}

	// 共有ライブラリから取得.
	m_b_RelayServerOffOn = pc_MFPAutoUpdateServer->getServerUse();

	Key_RemoteFWUpdateServerSettingFileRetrievalSetting.showEnable( m_b_RelayServerOffOn );
	Key_RemoteFWUpdateServerSettingPollingTime.showEnable( m_b_RelayServerOffOn );
	Key_RemoteFWUpdateServerSettingRetryTime.showEnable( m_b_RelayServerOffOn );
}
