//================================================================================================.
void PServiceRemoteFWUpdateServerSettingCom::notifyendGamen()
{
	setTurnGamenNow();	// 現在の画面を戻り画面にする.
}
//================================================================================================.
// 概要		: PServiceRemoteFWUpdateServerSetting : 90B94400 本体自動更新設定／中継ｻｰﾊﾞｰ設定 : 画面開始処理.
//================================================================================================.
void PServiceRemoteFWUpdateServerSetting::startGamen()
{
	PLBC_MFPAutoUpdateServer* pc_MFPAutoUpdateServer = NULL;
	pc_MFPAutoUpdateServer = PLBC_MFPAutoUpdateServer::getInstance();

	if( NULL == pc_MFPAutoUpdateServer ) {
//2019/06/17 Comment [HCLT_Krishnakumar][EagleH][N Rank] Removed unwanted detailed code.
//// 2015/11/05 【HCLT-Dhivya】 【ZeusS_ZX0】 【制御構成変更_No.76-1】Detail macro is passed in API.
//		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if (NULL != pc_BFW_System){
//   	 		pc_BFW_System->registDetailCode(PNLD_DetailCode_Service_0x1900650100F73301);
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}

	// 親クラスを呼ぶ.
	PServiceRemoteFWUpdateServerSettingCom::startGamen();

	// メニューから呼ばれる場合は不揮発から全設定を読み込む。.
	// 他の関連画面から遷移する場合は共有メモリから各画面で必要なパラメータを読み込みここでは一括で読み込まない。.
	if( True == m_blFromMenu ) {
		pc_MFPAutoUpdateServer->loadService();
		// 設定値を不揮発から読み込み、共有メモリへ反映したので以後共有メモリから参照する。.
		m_blFromMenu = False;
	}
	// 共有メモリから中継ｻｰﾊﾞｰ設定使用OFF/ONを取得する。.
	m_b_RelayServerOffOn = pc_MFPAutoUpdateServer->getServerUse();

	// 中継ｻｰﾊﾞｰ設定の表示画面初期化.
	PServiceRemoteFWUpdateServerSettingCom::m_e_RemoteFWUpdateServerSettingGamen = PNLE_RemoteFWUpdateServerSettingGamen_RelayServer;
}
//================================================================================================.
// 概要		: PServiceRemoteFWUpdateServerSetting : 90B94400 本体自動更新設定／中継ｻｰﾊﾞｰ設定 : 画面更新処理.
//================================================================================================.
void PServiceRemoteFWUpdateServerSetting::setupGamen( short option )
{
	PLBC_MFPAutoUpdateServer* pc_MFPAutoUpdateServer = NULL;
	pc_MFPAutoUpdateServer = PLBC_MFPAutoUpdateServer::getInstance();

	if( NULL == pc_MFPAutoUpdateServer ) {
//2019/06/17 Comment [HCLT_Krishnakumar][EagleH][N Rank] Removed unwanted detailed code.
//// 2015/11/05 【HCLT-Dhivya】 【ZeusS_ZX0】 【制御構成変更_No.76-1】Detail macro is passed in API.
//		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if (NULL != pc_BFW_System){
//   	 		pc_BFW_System->registDetailCode(PNLD_DetailCode_Service_0x1900660100F73401);
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}

	// セキュリティ強化モードがOnの時.
	if( True == PnlComGetSystemSetting()->getSecurityLevelUpOn() ) {
		// 「使用する」キーを非表示.
		Key_RemoteFWUpdateServerSettingRelayServerSettingsSelectOn.showEnable( False );
		// 「使用しない」キーを選択。.
		m_b_RelayServerOffOn = False;
		pc_MFPAutoUpdateServer->setServerUse( m_b_RelayServerOffOn );
	} else {
		// 「使用する」キーを表示.
		Key_RemoteFWUpdateServerSettingRelayServerSettingsSelectOn.showEnable( True );
	}
	Rbt_RelayServerSettingsSelect.select( True == m_b_RelayServerOffOn ? 0 : 1 );	// 使用する/使用しない.

	// 親クラスを呼ぶ.
	// 「使用する」から「使用しない」になったときに左のメニューの表示を変える必要があるためここで行う。.
	PServiceRemoteFWUpdateServerSettingCom::setupGamen( option );
// Comment 2015/09/09 HCLT_Shanmugapriya [ZeusS_ZX0][CQ517443] Changing the key Text.
// Comment 2017/11/29 【HCLT-Vishal】【Eagle】【制御構成変更_No.4】 Removing old function version check and else portion.
	Key_RemoteFWUpdateServerSettingPollingTime.changeText( s_KEYServiceMFPAutoUpdateClientPorlingIntervalPollingSetting );   // Polling Setting.

}
//================================================================================================.
// 概要		: PServiceRemoteFWUpdateServerSetting : 90B94400 本体自動更新設定／中継ｻｰﾊﾞｰ設定 : 画面遷移処理.
//================================================================================================.
void PServiceRemoteFWUpdateServerSetting::procButtonOn( uchar option )
{
	PLBC_MFPAutoUpdateServer* pc_MFPAutoUpdateServer = NULL;
	pc_MFPAutoUpdateServer = PLBC_MFPAutoUpdateServer::getInstance();

	if( NULL == pc_MFPAutoUpdateServer ) {
//2019/06/17 Comment [HCLT_Krishnakumar][EagleH][N Rank] Removed unwanted detailed code.
//// 2015/11/05 【HCLT-Dhivya】 【ZeusS_ZX0】 【制御構成変更_No.76-1】Detail macro is passed in API.
//		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if (NULL != pc_BFW_System){
//   	 		pc_BFW_System->registDetailCode(PNLD_DetailCode_Service_0x19000A0100F73501);
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}

	// 親クラスを呼ぶ.
	PServiceRemoteFWUpdateServerSettingCom::procButtonOn( option );

	switch( option ) {
		// 使用しない.
		case BTNID_RelayServerSettingsMode_OFF:
			// 選択中を「使用しない」にする.
			m_b_RelayServerOffOn = False;
			pc_MFPAutoUpdateServer->setServerUse( m_b_RelayServerOffOn );
			break;
		// 使用する.
		case BTNID_RelayServerSettingsMode_ON:
			// 選択中を「使用する」にする.
			m_b_RelayServerOffOn = True;
			pc_MFPAutoUpdateServer->setServerUse( m_b_RelayServerOffOn );
			break;
		default:
			break;
	}
	setupGamen( option );
}
