void PServiceRelayServerFileRetrievalSettingURLInput::startGamen()
{
	PLBC_MFPAutoUpdateServer* pc_MFPAutoUpdateServer = NULL;
	pc_MFPAutoUpdateServer = PLBC_MFPAutoUpdateServer::getInstance();

	if( NULL == pc_MFPAutoUpdateServer ) {
//2019/06/17 Comment [HCLT_Krishnakumar][EagleH][N Rank] Removed unwanted detailed code.
//// Comment 2015/11/02【HCLT-Juned】【制御構成変更_No.76-1】Adding error code macro.
//		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if (NULL != pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x1900650100F30001 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}

	// URLを共有メモリから取得.
// Comment 2020/01/22 [HCL-Shalini] [EagleZ+] [OP_BTS-19428] strnlen is used instead sizeof().
//// Comment 2019/12/02 [HCL-Taqiuddin] [KLOC ID:106261] [KLOC TYPE:ABV.GENERAL].
//	if ( sizeof( pc_MFPAutoUpdateServer->getFileDownloadURL()) < sizeof (m_sc_StrKeyboard) ) {
//		memcpy( m_sc_StrKeyboard, pc_MFPAutoUpdateServer->getFileDownloadURL(), sizeof( pc_MFPAutoUpdateServer->getFileDownloadURL() ) - 1 );
	if ( strnlen( pc_MFPAutoUpdateServer->getFileDownloadURL(),PNLD_MFPAutoUpdateServerFileDownloadURLSize) < sizeof (m_sc_StrKeyboard) ) {
		memset( m_sc_StrKeyboard, 0, sizeof( m_sc_StrKeyboard ) );
		memcpy( m_sc_StrKeyboard, pc_MFPAutoUpdateServer->getFileDownloadURL(), strnlen( pc_MFPAutoUpdateServer->getFileDownloadURL(),PNLD_MFPAutoUpdateServerFileDownloadURLSize ) );
	} else {
		memcpy( m_sc_StrKeyboard, pc_MFPAutoUpdateServer->getFileDownloadURL(), sizeof( m_sc_StrKeyboard ) - 1 );
	}
	// 表示領域に文字列をセット.
	setKeyboardData( m_sc_StrKeyboard, PNLD_MAX_ServerDownloadForHTTPURLChar , PNLD_ServiceRemoteFWUpdateInputWidth );
	m_b_Password = False;
	m_b_ShowPass = False;

	// 親クラスを呼ぶ.
	PServiceRemoteFWUpdateKeyboardCom::startGamen();
}
