//================================================================================================.
void PServiceRelayServerPollingTime::startGamen()
{
	PLBC_MFPAutoUpdateServer* pc_MFPAutoUpdateServer = NULL;
	pc_MFPAutoUpdateServer = PLBC_MFPAutoUpdateServer::getInstance();

	if( NULL == pc_MFPAutoUpdateServer ) {
//2019/06/17 Comment [HCLT_Krishnakumar][EagleH][N Rank] Removed unwanted detailed code.
//// Comment 2015/11/02【HCLT-Juned】【制御構成変更_No.76-1】Adding error code macro.
//		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if (NULL != pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x1900650100F31501 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}

	// 親クラスを呼ぶ.
	PServiceRemoteFWUpdateServerSettingCom::startGamen();

// Comment 2015/09/08 HCLT_Shanmugapriya [ZeusS_ZX0][CQ518038] Assigning Polling Interval to Polling setting till machine version 5G2.2.
//// Comment 2015/08/24 HCLT_Shanmugapriya [ZeusS_ZX0][CQ517386] Getting the values from Library.
//	m_s_pollingSetting = pc_MFPAutoUpdateServer->getServerPollingSetting();
//	pc_MFPAutoUpdateServer->getServerDownloadPollingTime(&m_e_Week, &m_uc_Hour, &m_uc_Minute);
// Comment 2017/11/29 【HCLT-Vishal】【Eagle】【制御構成変更_No.4】 Removing old function version check and else portion.
	m_s_pollingSetting = pc_MFPAutoUpdateServer->getServerPollingSetting();
	pc_MFPAutoUpdateServer->getServerDownloadPollingTime(&m_e_Week, &m_uc_Hour, &m_uc_Minute);
	// 共有メモリからポーリング間隔を取得する。.
	m_us_PollingInterval = pc_MFPAutoUpdateServer->getFileDownloadPollingInterval();
// Comment 2015/09/22 HCLT_Shanmugapriya [ZeusS_ZX0][CQ517408] Assigning the Hour key as default selection.
	m_polling_time = BTNID_ServiceMFPAutoUpdateClientPorlingHour;
}
//================================================================================================.
// 概要		: PServiceRelayServerPollingTime : 90B94490 本体自動更新設定／中継ｻｰﾊﾞｰ設定／ポーリング間隔 : 画面更新処理.
//================================================================================================.
void PServiceRelayServerPollingTime::setupGamen( short option )
{
	// 親クラスを呼ぶ.
	PServiceRemoteFWUpdateServerSettingCom::setupGamen( option );
// comment 2015/06/25 HCLT_Kshitish [ZeusS_ZX0][機器構成変更_No.64] Display of screen depend upon Type4 models.
// Comment 2017/11/29 【HCLT-Vishal】【Eagle】【制御構成変更_No.4】 Removing old function version check and else portion.
	Key_RemoteFWUpdateServerSettingPollingTime.changeText( s_KEYServiceMFPAutoUpdateClientPorlingIntervalPollingSetting );  // Changing the Key text to Polling setting.
	Ktx_ServiceRelayServerPollingTimeTitle.changeText ( s_TTLServiceMFPAutoUpdateClientPorlingIntervalPollingSetting );   														// Changing the Title text to "Polling Setting".
	Rbt_ServiceRelayServerPollingIntervalTime.select( m_s_pollingSetting );
	if( PNLD_PollingSetting_Interval == m_s_pollingSetting ){
		Btx_ServiceRelayServerPollingTime.set( ( float )m_us_PollingInterval, ( m_us_PollingInterval < 1 ) ? False : True );			
		Rbt_ServiceRelayServerPollingTimeDay.showEnable( False ); 
		Btx_ServiceRelayServerPollingTime.showEnable( True ); 
		Txt_ServiceRelayServerPollingTimeMin.showEnable( True );
		Txt_ServiceRelayServerPollingTimeRange.showEnable( True );
		Btx_ServiceRelayServerPollingTimeInputHour.showEnable( False );
		Btx_ServiceRelayServerPollingTimeInputMinute.showEnable( False );
		Rbt_ServiceRelayServerPollingSetTime.showEnable( False );
	} else {							
		Rbt_ServiceRelayServerPollingTimeDay.select( m_e_Week );															// Day set.
// Comment 2015/09/22 HCLT_Shanmugapriya [ZeusS_ZX0][CQ517408] Changing the Selection value.
// 			Rbt_ServiceRelayServerPollingSetTime.select( m_polling_time );
		Rbt_ServiceRelayServerPollingSetTime.select( static_cast<short>( m_polling_time - BTNID_ServiceMFPAutoUpdateClientPorlingHour ) );
		Btx_ServiceRelayServerPollingTimeInputHour.set(( float )m_uc_Hour, ( m_uc_Hour < 0 ) ? False : True);				// Hour set.
		Btx_ServiceRelayServerPollingTimeInputMinute.set(( float )m_uc_Minute, ( m_uc_Minute < 0 ) ? False : True);			// Min set.
		Rbt_ServiceRelayServerPollingTimeDay.showEnable( True ); 
		Btx_ServiceRelayServerPollingTime.showEnable( False ); 
		Txt_ServiceRelayServerPollingTimeMin.showEnable( False );
		Txt_ServiceRelayServerPollingTimeRange.showEnable( False );
		Btx_ServiceRelayServerPollingTimeInputHour.showEnable( True );
		Btx_ServiceRelayServerPollingTimeInputMinute.showEnable( True );
    	Rbt_ServiceRelayServerPollingSetTime.showEnable( True );
	}
}
