//================================================================================================.
void PServiceRelayServerPollingTime::proc10Key( uchar option )
{
	PLBC_MFPAutoUpdateServer* pc_MFPAutoUpdateServer = NULL;
	pc_MFPAutoUpdateServer = PLBC_MFPAutoUpdateServer::getInstance();

	if( NULL == pc_MFPAutoUpdateServer ) {
//2019/06/17 Comment [HCLT_Krishnakumar][EagleH][N Rank] Removed unwanted detailed code.
//// Comment 2015/11/02【HCLT-Juned】【制御構成変更_No.76-1】Adding error code macro.
//		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if (NULL != pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19002A0100F31801 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}

	Bool b_isError = False;
// comment 2015/06/25 HCLT_Kshitish [ZeusS_ZX0][機器構成変更_No.64] Check for key selection.
	if( PNLD_PollingSetting_Interval == m_s_pollingSetting){
	// ポーリング間隔を更新する.
	m_us_PollingInterval = ( ushort )proc10KeyInput( m_us_PollingInterval, TYPD_MAX_ServerDownloadForHTTPPollingInterval, option, m_b_Direct, EP_InputMaxLimitPattern_Refuse, &b_isError );
	pc_MFPAutoUpdateServer->setFileDownloadPollingInterval( m_us_PollingInterval );
	if( True == b_isError ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );					// ブザー音セット.
	} else {
		if( True == m_b_Direct && 1 > option ) {
			MCR_setBuzzerType( PCGE_BuzzerType_InputNg );				// ブザー音セット.
		} else {
			m_b_Direct = False;
		}
	}
	} else {
		if ( BTNID_ServiceMFPAutoUpdateClientPorlingHour == m_polling_time ){											//Hour key selected.
			m_uc_Hour = ( uchar )proc10KeyInput( m_uc_Hour, 23, option, m_b_Direct, EP_InputMaxLimitPattern_Refuse, &b_isError );
		} else if ( BTNID_ServiceMFPAutoUpdateClientPorlingMin == m_polling_time ) {										//Min key selected.
			m_uc_Minute = ( uchar )proc10KeyInput( m_uc_Minute, 59, option, m_b_Direct, EP_InputMaxLimitPattern_Refuse, &b_isError );
		}
		
		if( True == b_isError ) {
			MCR_setBuzzerType( PCGE_BuzzerType_InputNg );					// ブザー音セット.
		} else {
			if( True == m_b_Direct && 1 > option ) {
				MCR_setBuzzerType( PCGE_BuzzerType_InputNg );				// ブザー音セット.
			} else {
// Comment 2015/08/24 HCLT_Shanmugapriya [ZeusS_ZX0][CQ517386] Set the Value API.
				pc_MFPAutoUpdateServer->setServerDownloadPollingTime( m_e_Week, m_uc_Hour, m_uc_Minute );
				m_b_Direct = False;
			}
		}
	}
	setupGamen( option );															// 画面更新を行う.
}
