void PServiceRelayServerHTTPAuthPasswordInput::startGamen()
{
	PLBC_MFPAutoUpdateServer* pc_MFPAutoUpdateServer = NULL;
	pc_MFPAutoUpdateServer = PLBC_MFPAutoUpdateServer::getInstance();

	if( NULL == pc_MFPAutoUpdateServer ) {
//2019/06/17 Comment [HCLT_Krishnakumar][EagleH][N Rank] Removed unwanted detailed code.
//// Comment 2015/11/02【HCLT-Juned】【制御構成変更_No.76-1】Adding error code macro.
//		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if (NULL != pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x1900650100F33301 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}

	// エラーメッセージをクリア.
	m_us_dispErrMessage = s_Space1;

	// 自クラスのメンバを初期化.
	memset( m_sc_nowPassword, '\0', sizeof( m_sc_nowPassword ) );
	memset( m_sc_newPassword, '\0', sizeof( m_sc_newPassword ) );
	memset( m_sc_StrKeyboard, '\0', sizeof( m_sc_StrKeyboard ) );

	// HTTP認証パスワードを共有メモリから取得.
	memcpy( m_sc_nowPassword, pc_MFPAutoUpdateServer->getHTTPPassword(), sizeof( m_sc_nowPassword ) );

	// 開始画面を設定.
	if( '\0' != m_sc_nowPassword[0] ) {					// パスワード設定済み.
		m_uc_nowPageNum = PNLD_ServiceDecryptPasswordP1;	// 現在のパスワード入力画面.
	} else {												// パスワード未設定.
		m_uc_nowPageNum = PNLD_ServiceDecryptPasswordP2;	// 新しいパスワード入力画面.
	}

	// 表示領域に文字列をセット.
	setKeyboardData( m_sc_StrKeyboard, PNLD_MAX_ServerAccsessForHTTPPasswordChar , PNLD_ServiceRemoteFWUpdateInputWidth );
	m_b_Password = True;
	m_b_ShowPass = False;

	// 親クラスを呼ぶ.
	PServiceRemoteFWUpdateKeyboardCom::startGamen();

	Kbd_ServiceInputKeybord.setKeybord5Country( True );
	Kbd_ServiceInputKeybord.GetCursor( &Btx_PServiceRemoteFWUpdateKeyboardComInput2 );
	Kbd_ServiceInputKeybord.showKeybord();
}

