Bool PServiceMFPAutoUpdateClientCom::m_blFromMenu = False;
PNLE_ServiceRemoteFWUpdateSelectServer PServiceMFPAutoUpdateClientCom::m_e_SelectServer = PNLE_ServiceRemoteFWUpdateSelectServer1;
//================================================================================================.
// 概要		: PServiceMFPAutoUpdateClientCom : 本体自動更新設定／自動更新設定 共通：画面開始処理.
//================================================================================================.
void PServiceMFPAutoUpdateClientCom::startGamen()
{
	PLBC_MFPAutoUpdateClient* pc_MFPAutoUpdateClient = NULL;
	pc_MFPAutoUpdateClient = PLBC_MFPAutoUpdateClient::getInstance();

	if( NULL == pc_MFPAutoUpdateClient ) {
//2019/06/17 Comment [HCLT_Krishnakumar][EagleH][N Rank] Removed unwanted detailed code.
//// Comment 2015/11/02【HCLT-Juned】【制御構成変更_No.76-1】Adding error code macro.
//		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if (NULL != pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x1900650100F34701 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}
	// 選択ｻｰﾊﾞｰが不定の場合は処理なし.
	if( ( PNLE_ServiceRemoteFWUpdateSelectServer1 != m_e_SelectServer )
	    && ( PNLE_ServiceRemoteFWUpdateSelectServer2 != m_e_SelectServer )
	    && ( PNLE_ServiceRemoteFWUpdateSelectServerCom != m_e_SelectServer ) ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	// メニューから呼ばれる場合は不揮発から全設定を読み込む。.
	// 他の関連画面から遷移する場合は共有メモリから各画面で必要なパラメータを読み込みここでは一括で読み込まない。.
	if( True == PServiceMFPAutoUpdateClientCom::m_blFromMenu ) {
		// commonAPIから取得.
		pc_MFPAutoUpdateClient->loadService( m_e_SelectServer );		// 選択したサーバー情報をロードする.
		// 設定値を不揮発から読み込み、共有メモリへ反映したので以後共有メモリから参照する。.
		PServiceMFPAutoUpdateClientCom::m_blFromMenu = False;
	}
	// 親クラスを呼ぶ.
	PServiceNoFunctionCodeCom::startGamen();
}
// 自動更新設定.
uchar PServiceMFPAutoUpdateClientCom::m_e_MFPAutoUpdateClientSettingGamen = PNLE_RemoteFWUpdateServerSettingGamen_RelayServer;
//================================================================================================.
// 概要		: PServiceMFPAutoUpdateClientCom : 本体自動更新設定／自動更新設定 共通 : 画面更新処理.
//================================================================================================.
void PServiceMFPAutoUpdateClientCom::setupGamen( short option )
{
	// 親クラスを呼ぶ.
	PServiceNoFunctionCodeCom::setupGamen();

	switch( m_e_MFPAutoUpdateClientSettingGamen ) {
		case PNLE_MFPAutoUpdateClientSettingGamen_AutoUpdate:		// 自動更新設定.
			Rbt_ServiceMFPAutoUpdateClientMenu.select( 0 );
			break;
		case PNLE_MFPAutoUpdateClientSettingGamen_Protocol:			// 取得プロトコル.
			Rbt_ServiceMFPAutoUpdateClientMenu.select( 1 );
			break;
		case PNLE_MFPAutoUpdateClientSettingGamen_SMBHostName:		// SMB設定 - ホスト名.
			Rbt_ServiceMFPAutoUpdateClientMenu.select( 2 );
			Rbt_ServiceMFPAutoUpdateClientSMBMenu.select( 0 );
			break;
		case PNLE_MFPAutoUpdateClientSettingGamen_SMBFilePath:	// SMB設定 - ファイルパス.
			Rbt_ServiceMFPAutoUpdateClientMenu.select( 2 );
			Rbt_ServiceMFPAutoUpdateClientSMBMenu.select( 1 );
			break;
		case  PNLE_MFPAutoUpdateClientSettingGamen_SMBUserName:		// SMB設定 - ユーザー名.
			Rbt_ServiceMFPAutoUpdateClientMenu.select( 2 );
			Rbt_ServiceMFPAutoUpdateClientSMBMenu.select( 2 );
			break;
		case  PNLE_MFPAutoUpdateClientSettingGamen_SMBPassword:		// SMB設定 - パスワード.
			Rbt_ServiceMFPAutoUpdateClientMenu.select( 2 );
			Rbt_ServiceMFPAutoUpdateClientSMBMenu.select( 3 );
			break;
		case PNLE_MFPAutoUpdateClientSettingGamen_SMBRetryCount:	// SMB設定 - リトライ回数.
			Rbt_ServiceMFPAutoUpdateClientMenu.select( 2 );
			Rbt_ServiceMFPAutoUpdateClientSMBMenu.select( 4 );
			break;
		case PNLE_MFPAutoUpdateClientSettingGamen_HTTPURL:			// HTTP設定 - URL.
			Rbt_ServiceMFPAutoUpdateClientMenu.select( 3 );
			Rbt_ServiceMFPAutoUpdateClientHTTPMenu.select( 0 );
			break;
		case PNLE_MFPAutoUpdateClientSettingGamen_HTTPUserName:		// HTTP設定 - ユーザー名.
			Rbt_ServiceMFPAutoUpdateClientMenu.select( 3 );
			Rbt_ServiceMFPAutoUpdateClientHTTPMenu.select( 1 );
			break;
		case PNLE_MFPAutoUpdateClientSettingGamen_HTTPPassword:		// HTTP設定 - パスワード.
			Rbt_ServiceMFPAutoUpdateClientMenu.select( 3 );
			Rbt_ServiceMFPAutoUpdateClientHTTPMenu.select( 2 );
			break;
		case PNLE_MFPAutoUpdateClientSettingGamen_HTTPProxy:		// HTTP設定 - プロキシ.
			Rbt_ServiceMFPAutoUpdateClientMenu.select( 3 );
			Rbt_ServiceMFPAutoUpdateClientHTTPMenu.select( 3 );
			break;
		case PNLE_MFPAutoUpdateClientSettingGamen_HTTPTimeOut:		// HTTP設定 - 接続ﾀｲﾑｱｳﾄ.
			Rbt_ServiceMFPAutoUpdateClientMenu.select( 3 );
			Rbt_ServiceMFPAutoUpdateClientHTTPMenu.select( 4 );
			break;
		case PNLE_MFPAutoUpdateClientSettingGamen_UpdateTime:		// 更新時刻.
			Rbt_ServiceMFPAutoUpdateClientMenu.select( 4 );
			break;
		case PNLE_MFPAutoUpdateClientSettingGamen_PollingInterval:	// ポーリング間隔.
			Rbt_ServiceMFPAutoUpdateClientMenu.select( 5 );
			break;
		case PNLE_MFPAutoUpdateClientSettingGamen_RetryInterval:		// リトライ時間.
			Rbt_ServiceMFPAutoUpdateClientMenu.select( 6 );
			break;
		default: break;
	}
	PLBC_MFPAutoUpdateClient* pc_MFPAutoUpdateClient = NULL;
	pc_MFPAutoUpdateClient = PLBC_MFPAutoUpdateClient::getInstance();

	if( NULL == pc_MFPAutoUpdateClient ) {
//2019/06/17 Comment [HCLT_Krishnakumar][EagleH][N Rank] Removed unwanted detailed code.
//// Comment 2015/11/02【HCLT-Juned】【制御構成変更_No.76-1】Adding error code macro.
//		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if (NULL != pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x1900660100F34801 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}
	// 共有ライブラリから取得.
	m_b_MFPAutoUpdateClientOffOn = pc_MFPAutoUpdateClient->getClientFWUpdateSetting();

	switch( m_e_SelectServer ) {
		case PNLE_ServiceRemoteFWUpdateSelectServer1:
			Key_ServiceMFPAutoUpdateClientUpdateTime.showEnable( False );
			Key_ServiceMFPAutoUpdateClientPollingInterval.showEnable( False );
			Key_ServiceMFPAutoUpdateClientRetryInterval.showEnable( False );
			Key_ServiceMFPAutoUpdateClientFWUpdateSetting.showEnable( True );
			Key_ServiceMFPAutoUpdateClientDownloadProtocol.showEnable( m_b_MFPAutoUpdateClientOffOn );
			Key_ServiceMFPAutoUpdateClientSMBSetting.showEnable( m_b_MFPAutoUpdateClientOffOn );
			Key_ServiceMFPAutoUpdateClientHTTPSetting.showEnable( m_b_MFPAutoUpdateClientOffOn );
			break;
		case PNLE_ServiceRemoteFWUpdateSelectServer2:
			Key_ServiceMFPAutoUpdateClientUpdateTime.showEnable( False );
			Key_ServiceMFPAutoUpdateClientPollingInterval.showEnable( False );
			Key_ServiceMFPAutoUpdateClientRetryInterval.showEnable( False );
			Key_ServiceMFPAutoUpdateClientDownloadProtocol.showEnable( False );
			Key_ServiceMFPAutoUpdateClientSMBSetting.showEnable( False );
			Key_ServiceMFPAutoUpdateClientFWUpdateSetting.showEnable( True );
			Key_ServiceMFPAutoUpdateClientHTTPSetting.showEnable( m_b_MFPAutoUpdateClientOffOn );
			break;
		case PNLE_ServiceRemoteFWUpdateSelectServerCom:
			Key_ServiceMFPAutoUpdateClientFWUpdateSetting.showEnable( False );
			Key_ServiceMFPAutoUpdateClientDownloadProtocol.showEnable( False );
			Key_ServiceMFPAutoUpdateClientSMBSetting.showEnable( False );
			Key_ServiceMFPAutoUpdateClientHTTPSetting.showEnable( False );
			Key_ServiceMFPAutoUpdateClientUpdateTime.showEnable( True );
			if( True == c_HD_Equip.isOK() ) {				// HDD装着.
				Key_ServiceMFPAutoUpdateClientPollingInterval.showEnable( True );
			} else {										// HDD非装着.
				Key_ServiceMFPAutoUpdateClientPollingInterval.showEnable( False );
			}

			Key_ServiceMFPAutoUpdateClientRetryInterval.showEnable( True );
			break;
		default:
			break;
	}
}
