//================================================================================================.
void PServiceMFPAutoUpdateClientCom::procOk( uchar option )
{
	Bool	bl_ErrorCheckFlg = True;
	PLBC_MFPAutoUpdateClient* pc_MFPAutoUpdateClient = NULL;
	pc_MFPAutoUpdateClient = PLBC_MFPAutoUpdateClient::getInstance();

	if( NULL == pc_MFPAutoUpdateClient ) {
//2019/06/17 Comment [HCLT_Krishnakumar][EagleH][N Rank] Removed unwanted detailed code.
//// Comment 2015/11/02【HCLT-Juned】【制御構成変更_No.76-1】Adding error code macro.
//		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if (NULL != pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x1900030100F34901 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}
	// commonAPIに登録.
	if( PNLE_ServiceRemoteFWUpdateSelectServerCom == m_e_SelectServer ) {
		bl_ErrorCheckFlg = False;
	}
	if( False == pc_MFPAutoUpdateClient->comitService( m_e_SelectServer, bl_ErrorCheckFlg ) ) {
		// 受付け禁止条件の場合、設定を行わない.
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );					// ブザー音セット.
		return;
	};
	// 画面遷移.
	nextGamen = &gp_ServiceMFPAutoUpdateClientSelectServer;	// E0B9410000 本体自動更新設定／自動更新設定/サーバー選択.
}
