void PServiceMFPAutoUpdateClientSelectServer::procGoToPage( uchar option )
{
	// 遷移先に従い、設定対象サーバーを保存しておく.
	switch( option ) {
		case BTNID_ServiceMFPAutoUpdateClientSelectServer_Server1:
			gp_ServiceMFPAutoUpdateClient.setFromMenuFlg( True );
			gp_ServiceMFPAutoUpdateClient.setSelectServer( PNLE_ServiceRemoteFWUpdateSelectServer1 );
			nextGamen = &gp_ServiceMFPAutoUpdateClient;
			break;
		case BTNID_ServiceMFPAutoUpdateClientSelectServer_Server2:
			gp_ServiceMFPAutoUpdateClient.setFromMenuFlg( True );
			gp_ServiceMFPAutoUpdateClient.setSelectServer( PNLE_ServiceRemoteFWUpdateSelectServer2 );
			nextGamen = &gp_ServiceMFPAutoUpdateClient;
			break;
		case BTNID_ServiceMFPAutoUpdateClientSelectServer_Common:
			gp_ServiceMFPAutoUpdateClientUpdateTime.setFromMenuFlg( True );
			gp_ServiceMFPAutoUpdateClientUpdateTime.setSelectServer( PNLE_ServiceRemoteFWUpdateSelectServerCom );
			nextGamen = &gp_ServiceMFPAutoUpdateClientUpdateTime;
			break;
		default:
			break;
	}
}
