void PServiceMFPAutoUpdateClientUpdateTime::procButtonOn( uchar option )
{
	// 親クラスを呼ぶ.
	PServiceMFPAutoUpdateClientCom::procButtonOn( option );

	switch( option ) {
		// 時.
		case BTNID_ServiceMFPAutoUpdateClientProtocol_Hour:
			// 選択中を「時」にする.
			m_blHourMinit = True;
			break;
		// 分.
		case BTNID_ServiceMFPAutoUpdateClientProtocol_Minit:
			// 選択中を「分」にする.
			m_blHourMinit = False;
			break;
		default:
			break;
	}
	setupGamen( option );
}
//================================================================================================.
// 概要		: PServiceMFPAutoUpdateClientUpdateTime : 90B94310_本体自動更新設定／自動更新設定／更新時刻 : テンキー .
//================================================================================================.
void PServiceMFPAutoUpdateClientUpdateTime::proc10Key( uchar option )
{
	PLBC_MFPAutoUpdateClient* pc_MFPAutoUpdateClient = NULL;
	pc_MFPAutoUpdateClient = PLBC_MFPAutoUpdateClient::getInstance();

	if( NULL == pc_MFPAutoUpdateClient ) {
// Comment 2015/11/02【HCLT-Juned】【制御構成変更_No.76-1】Adding error code macro.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if (NULL != pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19002A0100F39501 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}

	// -------------------------.
	// 『時』を更新.
	// -------------------------.
	if( True == m_blHourMinit ) {

		switch( m_ssHourInputDigit ) {

			// 未入力の場合.
			case PNLE_UpdateClientUpdateTime_0_DIGIT:
				if( option <= 2 ) {									// 入力値が0～2の場合は上位桁として受付.
					m_ucHour = option;
					m_ssHourInputDigit = PNLE_UpdateClientUpdateTime_1_DIGIT;
				} else if( option <= 9 ) {							// 入力値が3～9の場合は下位桁として受付.
					m_ucHour = option;
					m_ssHourInputDigit = PNLE_UpdateClientUpdateTime_2_DIGIT;
				}
				break;

			// 上位桁入力済みの場合.
			case PNLE_UpdateClientUpdateTime_1_DIGIT:
			{
				uchar uc_HourCheck = m_ucHour;
				uc_HourCheck = static_cast<uchar>( uc_HourCheck * 10 + option );		// 入力済みの上位桁と入力値を結合.
				if( uc_HourCheck <= 23 ) {						// 結合結果が0～23の場合は受付.
					m_ucHour = uc_HourCheck;
					m_ssHourInputDigit = PNLE_UpdateClientUpdateTime_2_DIGIT;
				} else {										// 範囲外の場合は拒否音.
					setBuzzerType( PCGE_BuzzerType_InputNg );
				}
			}
			break;

			// 入力済みの場合.
			default:
				setBuzzerType( PCGE_BuzzerType_InputNg );
				break;
		}

		// -------------------------.
		// 『分』を更新.
		// -------------------------.
	} else {

		switch( m_ssMinitInputDigit ) {

			// 未入力の場合.
			case PNLE_UpdateClientUpdateTime_0_DIGIT:
				if( option <= 5 ) {									// 入力値が0～5の場合は上位桁として受付.
					m_ucMinit = option;
					m_ssMinitInputDigit = PNLE_UpdateClientUpdateTime_1_DIGIT;
				} else if( option <= 9 ) {							// 入力値が6～9の場合は下位桁として受付.
					m_ucMinit = option;
					m_ssMinitInputDigit = PNLE_UpdateClientUpdateTime_2_DIGIT;
				}
				break;

			// 上位桁入力済みの場合.
			case PNLE_UpdateClientUpdateTime_1_DIGIT:
			{
				uchar uc_MinuteCheck = m_ucMinit;
				uc_MinuteCheck = static_cast<uchar>( uc_MinuteCheck * 10 + option );	// 入力済みの上位桁と入力値を結合.
				if( uc_MinuteCheck <= 59 ) {						// 結合結果が0～59の場合は受付.
					m_ucMinit = uc_MinuteCheck;
					m_ssMinitInputDigit = PNLE_UpdateClientUpdateTime_2_DIGIT;
				} else {										// 範囲外の場合は拒否音.
					setBuzzerType( PCGE_BuzzerType_InputNg );
				}
			}
			break;

			// 入力済みの場合.
			default:
				setBuzzerType( PCGE_BuzzerType_InputNg );
				break;
		}
	}

	// -------------------------.
	// データクラスへ保存.
	// -------------------------.
	pc_MFPAutoUpdateClient->setClientDownloadFWUpdateTime( m_ucHour, m_ucMinit );

	setupGamen( option );											// 画面更新を行う.
}
