// 概要		: PServiceMFPAutoUpdateClientPorlingInterval : 90B94320_本体自動更新設定／自動更新設定／ポーリング間隔 : 画面開始処理 .
//================================================================================================.
void PServiceMFPAutoUpdateClientPorlingInterval::startGamen()
{
	PLBC_MFPAutoUpdateClient* pc_MFPAutoUpdateClient = NULL;
	pc_MFPAutoUpdateClient = PLBC_MFPAutoUpdateClient::getInstance();

	if( NULL == pc_MFPAutoUpdateClient ) {
// Comment 2015/11/02【HCLT-Juned】【制御構成変更_No.76-1】Adding error code macro.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if (NULL != pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x1900650100F39701 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}
	// 親クラスを呼ぶ.
	PServiceMFPAutoUpdateClientCom::startGamen();
// Comment 2015/09/08 HCLT_Shanmugapriya [ZeusS_ZX0][CQ518038] Assigning Polling Interval to Polling setting till machine version 5G2.2.
//// Comment 2015/08/24 HCLT_Shanmugapriya [ZeusS_ZX0][CQ517386] Getting the values from library.
//	m_s_pollingSetting = pc_MFPAutoUpdateClient->getClientPollingSetting();
//  pc_MFPAutoUpdateClient->getClientDownloadPollingTime(&m_e_Week, &m_uc_Hour, &m_uc_Minute);
// Comment 2017/11/29 【HCLT-Vishal】【Eagle】【制御構成変更_No.4】 Removing old function version check and else portion.
	m_s_pollingSetting = pc_MFPAutoUpdateClient->getClientPollingSetting();
    pc_MFPAutoUpdateClient->getClientDownloadPollingTime(&m_e_Week, &m_uc_Hour, &m_uc_Minute);
	
	// 共有メモリからポーリング間隔を取得する。.
	m_usPorlingInterval = pc_MFPAutoUpdateClient->getClientDownloadPollingInterval();

	m_b_Direct  = False;

	// 自動更新設定の表示画面初期化.
	PServiceMFPAutoUpdateClientCom::m_e_MFPAutoUpdateClientSettingGamen = PNLE_MFPAutoUpdateClientSettingGamen_PollingInterval;
// Comment 2015/09/22 HCLT_Shanmugapriya [ZeusS_ZX0][CQ517408] Assigning the Hour key as default selection.
	m_polling_time = BTNID_ServiceMFPAutoUpdateClientPorlingHour;
}
//================================================================================================.
// 概要		: PServiceMFPAutoUpdateClientPorlingInterval : 90B94320_本体自動更新設定／自動更新設定／ポーリング間隔 : 画面更新処理 .
//================================================================================================.
void PServiceMFPAutoUpdateClientPorlingInterval::setupGamen( short option )
{
	// 親クラスを呼ぶ.
	PServiceMFPAutoUpdateClientCom::setupGamen( option );
// comment 2015/06/25 HCLT_Kshitish [ZeusS_ZX0][機器構成変更_No.64] Display of screen depend upon Type4 models.
// Comment 2017/11/29 【HCLT-Vishal】【Eagle】【制御構成変更_No.4】 Removing old function version check and else portion.
	Key_ServiceMFPAutoUpdateClientPollingInterval.changeText( s_KEYServiceMFPAutoUpdateClientPorlingIntervalPollingSetting );              // Changing the Key text to "Polling Setting".
	Ktx_ServiceMFPAutoUpdateClientPorlingIntervalTitle.changeText ( s_TTLServiceMFPAutoUpdateClientPorlingIntervalPollingSetting );   														// Changing the Title text to "Polling Setting".
	Rbt_ServiceMFPAutoUpdateClientPorlingIntervalTime.select( m_s_pollingSetting );
	if( PNLD_PollingSetting_Interval == m_s_pollingSetting ){
		Btx_ServiceMFPAutoUpdateClientPorlingInterval.set( ( float )m_usPorlingInterval, ( m_usPorlingInterval < 1 ) ? False : True );			
		Rbt_ServiceMFPAutoUpdateClientPorlingIntervalDay.showEnable( False ); 
		Btx_ServiceMFPAutoUpdateClientPorlingInterval.showEnable( True ); 
		Txt_ServiceMFPAutoUpdateClientPorlingIntervalTimeMin.showEnable( True );
		Txt_ServiceMFPAutoUpdateClientPorlingIntervalTimeRange.showEnable( True );
		Btx_ServiceMFPAutoUpdateClientPorlingIntervalInputHour.showEnable( False );
		Btx_ServiceMFPAutoUpdateClientPorlingIntervalInputMinute.showEnable( False );
		Rbt_ServiceMFPAutoUpdateClientPorlingSetInterval.showEnable( False );
	} else {							
		Rbt_ServiceMFPAutoUpdateClientPorlingIntervalDay.select( m_e_Week );																// Day set.
// Comment 2015/09/22 HCLT_Shanmugapriya [ZeusS_ZX0][CQ517408] Changing the Selection value.
// 			Rbt_ServiceMFPAutoUpdateClientPorlingSetInterval.select( m_polling_time );
		Rbt_ServiceMFPAutoUpdateClientPorlingSetInterval.select( static_cast<short>( m_polling_time - BTNID_ServiceMFPAutoUpdateClientPorlingHour ) );
		Btx_ServiceMFPAutoUpdateClientPorlingIntervalInputHour.set(( float )m_uc_Hour, ( m_uc_Hour < 0 ) ? False : True);				// Hour set.
		Btx_ServiceMFPAutoUpdateClientPorlingIntervalInputMinute.set(( float )m_uc_Minute, ( m_uc_Minute < 0 ) ? False : True);			// Min set.
		Rbt_ServiceMFPAutoUpdateClientPorlingIntervalDay.showEnable( True ); 
		Btx_ServiceMFPAutoUpdateClientPorlingInterval.showEnable( False ); 
		Txt_ServiceMFPAutoUpdateClientPorlingIntervalTimeMin.showEnable( False );
		Txt_ServiceMFPAutoUpdateClientPorlingIntervalTimeRange.showEnable( False );
		Btx_ServiceMFPAutoUpdateClientPorlingIntervalInputHour.showEnable( True );
		Btx_ServiceMFPAutoUpdateClientPorlingIntervalInputMinute.showEnable( True );
    	Rbt_ServiceMFPAutoUpdateClientPorlingSetInterval.showEnable( True );
	}
}
