void PServiceMFPAutoUpdateClientPorlingInterval::procGoToPage( uchar option )
{
	PLBC_MFPAutoUpdateClient* pc_MFPAutoUpdateClient = NULL;
	pc_MFPAutoUpdateClient = PLBC_MFPAutoUpdateClient::getInstance();

	if( NULL == pc_MFPAutoUpdateClient ) {
// Comment 2015/11/02【HCLT-Juned】【制御構成変更_No.76-1】Adding error code macro.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if (NULL != pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x1900020100F39801 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}

	// 範囲外の場合は画面遷移しない.
	if( m_usPorlingInterval < TYPD_MIN_ClientDownloadPollingInterval || TYPD_MAX_ClientDownloadPollingInterval < m_usPorlingInterval ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );					// ブザー音セット.
		return;
	}
	pc_MFPAutoUpdateClient->setClientDownloadPollingInterval( m_usPorlingInterval );
	// 親クラスを呼ぶ.
	PServiceMFPAutoUpdateClientCom::procGoToPage( option );
}
