// 概要		: PServiceMFPAutoUpdateClientPorlingInterval : 90B94320_本体自動更新設定／自動更新設定／ポーリング間隔 : テンキー .
//================================================================================================.
void PServiceMFPAutoUpdateClientPorlingInterval::proc10Key( uchar option )
{
	PLBC_MFPAutoUpdateClient* pc_MFPAutoUpdateClient = NULL;
	pc_MFPAutoUpdateClient = PLBC_MFPAutoUpdateClient::getInstance();

	if( NULL == pc_MFPAutoUpdateClient ) {
// Comment 2015/11/02【HCLT-Juned】【制御構成変更_No.76-1】Adding error code macro.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if (NULL != pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19002A0100F3A001 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}

	Bool b_isError = False;
// comment 2015/06/25 HCLT_Kshitish [ZeusS_ZX0][機器構成変更_No.64] Check for key selection.
	if( PNLD_PollingSetting_Interval == m_s_pollingSetting){
		// ポーリング間隔を更新する.
		m_usPorlingInterval = ( ushort )proc10KeyInput( m_usPorlingInterval, TYPD_MAX_ClientDownloadPollingInterval, option, m_b_Direct, EP_InputMaxLimitPattern_Refuse, &b_isError );
		pc_MFPAutoUpdateClient->setClientDownloadPollingInterval( m_usPorlingInterval );
		if( True == b_isError ) {
			MCR_setBuzzerType( PCGE_BuzzerType_InputNg );					// ブザー音セット.
		} else {
			if( True == m_b_Direct && 1 > option ) {
				MCR_setBuzzerType( PCGE_BuzzerType_InputNg );				// ブザー音セット.
			} else {
				m_b_Direct = False;
			}
		}
	} else {
		if ( BTNID_ServiceMFPAutoUpdateClientPorlingHour == m_polling_time ) {											//Hour key selected.
			m_uc_Hour = ( uchar )proc10KeyInput( m_uc_Hour, 23, option, m_b_Direct, EP_InputMaxLimitPattern_Refuse, &b_isError );
		} else if ( BTNID_ServiceMFPAutoUpdateClientPorlingMin == m_polling_time ) 	{									//Min key selected.
			m_uc_Minute = ( uchar )proc10KeyInput( m_uc_Minute, 59, option, m_b_Direct, EP_InputMaxLimitPattern_Refuse, &b_isError );	
		}
		
		if( True == b_isError ) {
			MCR_setBuzzerType( PCGE_BuzzerType_InputNg );					// ブザー音セット.
		} else {
			if( True == m_b_Direct && 1 > option ) {
				MCR_setBuzzerType( PCGE_BuzzerType_InputNg );				// ブザー音セット.
			} else {
// Comment 2015/08/24 HCLT_Shanmugapriya [ZeusS_ZX0][CQ517386] Setting the values to library.
				pc_MFPAutoUpdateClient->setClientDownloadPollingTime( m_e_Week, m_uc_Hour, m_uc_Minute );
				m_b_Direct = False;
			}
		}
	}
	setupGamen( option );															// 画面更新を行う.
}
