// 概要		: PServiceMFPAutoUpdateClientPorlingInterval : 90B94320_本体自動更新設定／自動更新設定／ポーリング間隔 : クリアキー .
//================================================================================================.
void PServiceMFPAutoUpdateClientPorlingInterval::procClear( uchar option )
{
	PLBC_MFPAutoUpdateClient* pc_MFPAutoUpdateClient = NULL;
	pc_MFPAutoUpdateClient = PLBC_MFPAutoUpdateClient::getInstance();

	if( NULL == pc_MFPAutoUpdateClient ) {
// Comment 2015/11/02【HCLT-Juned】【制御構成変更_No.76-1】Adding error code macro.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if (NULL != pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19002B0100F3A101 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}
// comment 2015/06/25 HCLT_Kshitish [ZeusS_ZX0][機器構成変更_No.64] Clear values depend upon current screen display.
	if( PNLD_PollingSetting_Interval == m_s_pollingSetting ){
	m_usPorlingInterval = 0;									// ポーリング間隔を0にする.
	pc_MFPAutoUpdateClient->setClientDownloadPollingInterval( m_usPorlingInterval );
	} else {
		switch( m_polling_time ) {
			case BTNID_ServiceMFPAutoUpdateClientPorlingHour:
				m_uc_Hour = 0;
			break;
			case BTNID_ServiceMFPAutoUpdateClientPorlingMin:
				m_uc_Minute = 0;
			break;
			default:
			break;
		}
// Comment 2015/08/24 HCLT_Shanmugapriya [ZeusS_ZX0][CQ517386] Setting the values to library.
		pc_MFPAutoUpdateClient->setClientDownloadPollingTime( m_e_Week, m_uc_Hour, m_uc_Minute );
	}
	m_b_Direct = True;
	setupGamen( option );															// 画面更新を行う.
}
// comment 2015/06/25 HCLT_Kshitish [ZeusS_ZX0][機器構成変更_No.64] Handeling key selection.
//================================================================================================.
// 概要		: PServiceRelayServerPollingTime : 90B94490 本体自動更新設定／中継ｻｰﾊﾞｰ設定／ポーリング間隔 : クリアキー.
//================================================================================================.
void PServiceMFPAutoUpdateClientPorlingInterval::procButtonOn( uchar option )
{

	switch( option ) {
		case BTNID_ServiceRelayServerPollingInterval:
			m_s_pollingSetting = 0;	
			break;
		case BTNID_ServiceRelayServerPollingTime:
			m_s_pollingSetting = 1;	
			break;
		case BTNID_ServiceMFPAutoUpdateClientPorlingSun:	m_e_Week = TYPE_WeekSun; break;
		case BTNID_ServiceMFPAutoUpdateClientPorlingMon:	m_e_Week = TYPE_WeekMon; break;
		case BTNID_ServiceMFPAutoUpdateClientPorlingTue:	m_e_Week = TYPE_WeekTue; break;
		case BTNID_ServiceMFPAutoUpdateClientPorlingWed:	m_e_Week = TYPE_WeekWed; break;
		case BTNID_ServiceMFPAutoUpdateClientPorlingThu:	m_e_Week = TYPE_WeekThr; break;
		case BTNID_ServiceMFPAutoUpdateClientPorlingFri:	m_e_Week = TYPE_WeekFri; break;
		case BTNID_ServiceMFPAutoUpdateClientPorlingSat:	m_e_Week = TYPE_WeekSat; break;
		case BTNID_ServiceMFPAutoUpdateClientPorlingHour:
		case BTNID_ServiceMFPAutoUpdateClientPorlingMin:
			m_polling_time = option;
			Rbt_ServiceMFPAutoUpdateClientPorlingSetInterval.select( static_cast<short>( option - 9 ) );
			break;
		default:
			break;
	}
// Comment 2015/08/24 HCLT_Shanmugapriya [ZeusS_ZX0][CQ517386] Setting the values to library.
	PLBC_MFPAutoUpdateClient* pc_MFPAutoUpdateClient = NULL;
	pc_MFPAutoUpdateClient = PLBC_MFPAutoUpdateClient::getInstance();

	if( NULL == pc_MFPAutoUpdateClient ) {
// Comment 2015/11/02【HCLT-Juned】【制御構成変更_No.76-1】Adding error code macro.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if (NULL != pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19000A0100F3A201 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}
	if ( BTNID_ServiceRelayServerPollingInterval == option || BTNID_ServiceRelayServerPollingTime  == option ){
		pc_MFPAutoUpdateClient->setClientPollingSetting( (TYPE_PollingSetting)m_s_pollingSetting );
	}
		
	if ( option >= BTNID_ServiceMFPAutoUpdateClientPorlingSun && option <= BTNID_ServiceMFPAutoUpdateClientPorlingSat ){
		pc_MFPAutoUpdateClient->setClientDownloadPollingTime( m_e_Week, m_uc_Hour, m_uc_Minute );
	}
	setupGamen( option );	

}
