//================================================================================================.
//	ログ表示共通：定数・型の宣言.
//================================================================================================
//const uchar PNLD_FWUpdateLogLineStrMax = (uchar)52;		// ログ1行分の表示文字数.
const uchar PNLD_FWUpdateLogLineStrMax = ( uchar )50;		// ログ1行分の表示文字数.
const uchar PNLD_FWUpdateLogBufferMax = ( uchar )160;		// ログ格納バッファサイズ.
const uchar PNLD_ExtractionComma = ( uchar )4;		// 抽出カンマ位置.

//================================================================================================.
// 90B95070 本体自動更新設定／更新ログ表示 : 画面更新.
//================================================================================================.
void PServiceRemoteFWUpdateLogConfirm::setupGamen( short option )
{
	PServiceNoFunctionCodeCom::setupGamen( option );

	ushort us_logNo = 0;	// ループカウンタ.

	APIC_FWUpdateLog* pc_FWUpdateLog = APIC_FWUpdateLog::newInstance();
	if( NULL == pc_FWUpdateLog ) {
// Comment 2015/11/02【HCLT-Juned】【制御構成変更_No.76-1】Adding error code macro.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if (NULL != pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x1900660100F3A901 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}

	// ログエリア初期化.
	for( us_logNo = 0; TYPD_FWUpdateLogData_MaximumOfGetData > us_logNo; us_logNo++ ) {
		Tfd_ServiceRemoteFWUpdateLogConfirm1stLine[ us_logNo ].changeExternalText( ( uchar* )"", 0 );
		Tfd_ServiceRemoteFWUpdateLogConfirm2ndLine[ us_logNo ].changeExternalText( ( uchar* )"", 0 );
	}

	char LogExtraction[PNLD_FWUpdateLogBufferMax + 1];						// 抽出用(日付時刻、処理コード、結果、エラーコード).
	char LogDetailExtraction[PNLD_FWUpdateLogBufferMax + 1];				// 抽出用(エラー詳細).
	char AdjustLogExtraction[PNLD_FWUpdateLogBufferMax + 1];				// 調整用(日付時刻、処理コード、結果、エラーコード).
	char AdjustLogDetailExtraction[PNLD_FWUpdateLogBufferMax + 1];			// 調整用(エラー詳細).

	memset( LogExtraction, '\0', sizeof( LogExtraction ) );
	memset( LogDetailExtraction, '\0', sizeof( LogDetailExtraction ) );
	memset( AdjustLogExtraction, '\0', sizeof( AdjustLogExtraction ) );
	memset( AdjustLogDetailExtraction, '\0', sizeof( AdjustLogDetailExtraction ) );

	char* pList[TYPD_FWUpdateLogData_MaximumOfGetData];
	memset( pList, NULL, sizeof( pList ) );
	ushort us_count = pc_FWUpdateLog->getLogData( pList );	// 直近5件分のログ情報取得.

	// ログ情報は文字列として、以下の様に格納されている為、','数で判断し、
	ushort us_CommaCount = 0;
	ushort us_TextLen = 0;

	// ログ情報は文字列として、以下の様に格納されている為、','数で判断し、
	// 「日付時刻、処理コード、結果、エラーコード」と「エラー詳細」を分離させる.
	// YYYY/MM/DD hh:mm:ss, 99, OK, Xxxxxx, XXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX EEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEE ________________\0.
	for( us_logNo = 0; us_count > us_logNo; us_logNo++ ) {
		us_TextLen = (ushort)( strlen( pList[us_logNo] ) );
		us_CommaCount = 0;
		// 1行分のログを1文字ずつ確認し、','数をカウントする.
		for( ushort us_charNumber = 0; us_TextLen >= us_charNumber; us_charNumber++ ) {
			// ','数が4つ目(エラーコード後端)の場合.
			if( PNLD_ExtractionComma == us_CommaCount ) {
				memset( LogExtraction, '\0', sizeof( LogExtraction ) );
				memset( LogDetailExtraction, '\0', sizeof( LogDetailExtraction ) );
				memset( AdjustLogExtraction, '\0', sizeof( AdjustLogExtraction ) );
				memset( AdjustLogDetailExtraction, '\0', sizeof( AdjustLogDetailExtraction ) );
				// 格納先サイズが溢れる場合は処理しない.
// comment 2018/07/23【HCLT-HariBhaskar】【IT6_Eagle】Kloc work Changes ID:1133507 【SV.STRBO.BOUND_COPY.OVERFLOW】.
//				if( ( sizeof( LogExtraction ) < us_charNumber )
//				    || ( sizeof( LogDetailExtraction ) < static_cast<uint>( us_TextLen - us_charNumber ) ) ) {
				if( ( sizeof( LogExtraction ) <= us_charNumber )
				    || ( sizeof( LogDetailExtraction ) < static_cast<uint>( us_TextLen - us_charNumber ) ) ) {
					LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
					return;
				}
				// 文字列分割.
				strncpy( LogExtraction, pList[us_logNo], us_charNumber );
// comment 2018/01/17【HCLT-Jagadeesh】【IT5_4.2】Kloc work Changes ID:382130 【SV.STRBO.BOUND_COPY.OVERFLOW】.
//				strncpy( LogDetailExtraction, &( pList[us_logNo][us_charNumber] ), ( us_TextLen - us_charNumber ) );
				if( ( us_TextLen - us_charNumber ) < sizeof( LogDetailExtraction ) ) {
				strncpy( LogDetailExtraction, &( pList[us_logNo][us_charNumber] ), ( us_TextLen - us_charNumber ) );
				} else {
					strncpy( LogDetailExtraction, &( pList[us_logNo][us_charNumber] ), (sizeof( LogDetailExtraction ) - 1) );				
				}
				// 文字列整形.
				setupInputString( 1, PNLD_FWUpdateLogLineStrMax, LogExtraction, AdjustLogExtraction );
				setupInputString( 2, PNLD_FWUpdateLogLineStrMax, LogDetailExtraction, AdjustLogDetailExtraction );
				// 文字列格納.
				Tfd_ServiceRemoteFWUpdateLogConfirm1stLine[ us_logNo ].changeExternalText( ( uchar* )AdjustLogExtraction, (short)strlen( AdjustLogExtraction ) );
				Tfd_ServiceRemoteFWUpdateLogConfirm2ndLine[ us_logNo ].changeExternalText( ( uchar* )AdjustLogDetailExtraction, (short)strlen( AdjustLogDetailExtraction ) );
				break;
			}
			// ','カウント.
			if( ',' == pList[us_logNo][us_charNumber] ) {
				us_CommaCount++;
			}
		}
	}
}

