//================================================================================================.
// 90B95100 本体自動更新設定／本体設定ｲﾝﾎﾟｰﾄ : 画面更新.
//================================================================================================.
void PServiceRemoteFWUpdateMainSettingImport::setupGamen( short option )
{

	PServiceNoFunctionCodeCom::setupGamen( option );	// 親処理実行.

	PServiceRemoteFWUpdateUSBExportInfo* pc_RemoteFWUpdateUSBExportInfo = PServiceRemoteFWUpdateUSBExportInfo::newInstance();
	if ( NULL == pc_RemoteFWUpdateUSBExportInfo ) {
// Comment 2015/11/02【HCLT-Juned】【制御構成変更_No.76-1】Adding error code macro.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if (NULL != pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x1900660100F3B201 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}
	char	sc_chkPass[ PNLD_USBExportPassMax + 1 ];	// パスワード.
	memset( sc_chkPass, '\0', sizeof( sc_chkPass ) );
	
	pc_RemoteFWUpdateUSBExportInfo->getPassword( sc_chkPass );								// パスワード取得.

	// パスワード表示／非表示.
	char sc_DispPass[ 10 + 1 ];
	memset( sc_DispPass, '\0', sizeof( sc_DispPass ) );
	if( '\0' != sc_chkPass[0] ) {									// パスワードが入力されている時.
// comment 2018/01/18 【HCL-Rajesh】 [IT5_4.2] Klockwork Changes ID: 381859 [SV.STRBO.BOUND_COPY.UNTERM].
//		strncpy( sc_DispPass , "**********", sizeof( sc_DispPass ) );
		strncpy( sc_DispPass , "**********", sizeof( sc_DispPass ) - 1 );
	}
	Btx_RemoteFWUpdateImportPass.changeExternalText( (uchar*)sc_DispPass );
	
	PNLE_USBImportSts e_USBImportSts = pc_RemoteFWUpdateUSBExportInfo->getImportStatus();	// インポート状態取得.
	Key_RemoteFWUpdateImportSelectUSB.select( True );										// USBキー選択.
	Key_RemoteFWUpdateImportSelectUSB.showEnable( True );									// USBキー表示.


	switch( e_USBImportSts ) {
		// 実行前---------------------------------------.
		case PNLE_RemoteFWUpdateUSBImportPreProc:
		{
			// 表示項目.
			// 1.「スタート」キー(条件あり).
			// 2.「USB NG」メッセージ(条件あり).
			// 非表示パーツを制御.
			Txt_RemoteFWUpdateImportProgress.showEnable( False );					// 進行アイコン非表示.
			Txt_RemoteFWUpdateImportOK.showEnable( False );							// OKメッセージ非表示.
			Grp_RemoteFWUpdateImportAllResult.showEnable( False );					// インポート結果非表示.
// comment 2018/09/06 Sky石上 [SecV4][PKI設定の簡易化].
			Txt_RemoteFWUpdateImportConfirmPKICollective.showEnable( False );		// インポート確認(PKI関連設定ファイルあり)メッセージ非表示.
			Key_RemoteFWUpdateImportSelectPKICollectiveYes.showEnable( False );		// PKI関連設定インポート確認「はい」キー非表示.
			Key_RemoteFWUpdateImportSelectPKICollectiveNo.showEnable( False );		// PKI関連設定インポート確認「いいえ」キー非表示.
			
			// 表示パーツを制御.
			//「USB NG」表示であるかチェック.
			if( False == isFWUpdateUsbImport() ) {
				Txt_RemoteFWUpdateImportStatus.showEnable( True );					// インポート状態表示.
				Txt_RemoteFWUpdateImportStatus.changeText( s_ITMServiceUSBN_a );	// インポート状態「USB NG」.
				Key_RemoteFWUpdateImportStart.showEnable( False );					// スタートキー非表示.
			}else{
				Txt_RemoteFWUpdateImportStatus.showEnable( False );					// インポート状態非表示.
				Key_RemoteFWUpdateImportStart.showEnable( True );					// スタートキー表示.
			}
			break;
		}
// comment 2018/09/06 Sky石上 [SecV4][PKI設定の簡易化].
		// PKI関連ファイルインポート確認中--------------..
		case PNLE_RemoteFWUpdateUSBImportConfirm:
		{
			// 表示項目.
			// 1.「スタート」キー(条件あり).
			// 2.インポート確認(PKI関連設定ファイルあり)メッセージ表示
			// 3.PKI関連設定インポート確認「はい/いいえ」キー表示.
			
			// 非表示パーツを制御.
			Txt_RemoteFWUpdateImportProgress.showEnable( False );						// 進行アイコン非表示.
			Txt_RemoteFWUpdateImportOK.showEnable( False );								// OKメッセージ非表示.
			Txt_RemoteFWUpdateImportStatus.showEnable( False );							// インポート状態非表示.
			Grp_RemoteFWUpdateImportAllResult.showEnable( False );						// インポート結果非表示.
			
			// 表示パーツを制御.
			Key_RemoteFWUpdateImportSelectPKICollectiveYes.showEnable( True );			// PKI関連設定インポート確認「はい」キー表示.
			Key_RemoteFWUpdateImportSelectPKICollectiveNo.showEnable( True );			// PKI関連設定インポート確認「いいえ」キー表示.
			Txt_RemoteFWUpdateImportConfirmPKICollective.showEnable( True );			// インポート確認(PKI関連設定ファイルあり)メッセージ表示.
			
			// PKI関連設定インポート確認「はい」キー選択
			if(pc_RemoteFWUpdateUSBExportInfo->getSelectedPKICollectiveYes() == True) {
				Key_RemoteFWUpdateImportSelectPKICollectiveYes.select( True );			// PKI関連設定インポート確認「はい」キー選択.
				Key_RemoteFWUpdateImportSelectPKICollectiveNo.select( False );			// PKI関連設定インポート確認「いいえ」キー非選択.
				Key_RemoteFWUpdateImportStart.showEnable( True );						// スタートキー表示.
			// PKI関連設定インポート確認「いいえ」キー選択
			}else if(pc_RemoteFWUpdateUSBExportInfo->getSelectedPKICollectiveNo() == True ) {
				Key_RemoteFWUpdateImportSelectPKICollectiveYes.select( False );			// PKI関連設定インポート確認「はい」キー非選択.
				Key_RemoteFWUpdateImportSelectPKICollectiveNo.select( True );			// PKI関連設定インポート確認「いいえ」キー選択.
				Key_RemoteFWUpdateImportStart.showEnable( True );						// スタートキー表示.
			// PKI関連設定インポート確認「はい/いいえ」キー未選択
			}else{
				Key_RemoteFWUpdateImportStart.showEnable( False );						// スタートキー非表示.
			}
			break;
		}
		// 実行中---------------------------------------..
		case PNLE_RemoteFWUpdateUSBImportProc:
		{
			// 表示項目.
			// 1.「実行中」メッセージ.
			// 2.「／」「＼」メッセージ.
			// 非表示パーツを制御.
			Key_RemoteFWUpdateImportStart.showEnable( False );						// スタートキー非表示.
			Txt_RemoteFWUpdateImportOK.showEnable( False );							// OKメッセージ非表示.
			Grp_RemoteFWUpdateImportAllResult.showEnable( False );					// インポート結果非表示. 
// comment 2018/09/06 Sky石上 [SecV4][PKI設定の簡易化].
			Txt_RemoteFWUpdateImportConfirmPKICollective.showEnable( False );		// インポート確認(PKI関連設定ファイルあり)メッセージ非表示.
			Key_RemoteFWUpdateImportSelectPKICollectiveYes.showEnable( False );		// PKI関連設定インポート確認「はい」キー非表示.
			Key_RemoteFWUpdateImportSelectPKICollectiveNo.showEnable( False );		// PKI関連設定インポート確認「いいえ」キー非表示.
			
			// 表示パーツを制御.
			//「実行中」メッセージ表示設定.
			Txt_RemoteFWUpdateImportStatus.showEnable( True );						// インポート状態表示.
			Txt_RemoteFWUpdateImportStatus.changeText( s_ITMServiceOperating );		// インポート状態「実行中」.
			//「／」「＼」表示設定.
			// 進行状態表示トグルに応じて表示更新.
			Txt_RemoteFWUpdateImportProgress.showEnable( True );					// 進行アイコン表示.
			if( True == bl_ExecStsToggle ) {
				Txt_RemoteFWUpdateImportProgress.changeText( s_EXPSlash );			// 実行中リストア進行メッセージ表示更新「／」.
				bl_ExecStsToggle = False;
			} else {
				Txt_RemoteFWUpdateImportProgress.changeText( s_EXPBackslash );		// 実行中リストア進行メッセージ表示更新「＼」.
				bl_ExecStsToggle = True;
			}
			break;
		}
		// 正常終了、異常終了、キャンセル---------------------------------------.
		case PNLE_RemoteFWUpdateUSBImportComplete:
		case PNLE_RemoteFWUpdateUSBImportSystemError:
		case PNLE_RemoteFWUpdateUSBImportCancel:
		{
			// 表示項目.
			// 1.「スタート」キー(条件あり).
			// 2.「インポート結果」メッセージ.
			// 非表示パーツを制御.
			Txt_RemoteFWUpdateImportStatus.showEnable( False );						// インポート状態非表示.
			Txt_RemoteFWUpdateImportProgress.showEnable( False );					// 進行アイコン非表示.
// comment 2018/09/06 Sky石上 [SecV4][PKI設定の簡易化].
			Txt_RemoteFWUpdateImportConfirmPKICollective.showEnable( False );		// インポート確認(PKI関連設定ファイルあり)メッセージ非表示.
			Key_RemoteFWUpdateImportSelectPKICollectiveYes.showEnable( False );		// PKI関連設定インポート確認「はい」キー非表示.
			Key_RemoteFWUpdateImportSelectPKICollectiveNo.showEnable( False );		// PKI関連設定インポート確認「いいえ」キー非表示.

			// 表示パーツを制御.
			// 「スタート」キー表示であるかチェック.
			// 1つ以上OKがある場合はスタートキー非表示.
			if( 0x00000000 != (( PNLD_UsbImportTarget_FULL & pc_RemoteFWUpdateUSBExportInfo->getImportResult())
							  |( PNLD_UsbImportTarget_FULL & pc_RemoteFWUpdateUSBExportInfo->getImportResult2nd()))){
				Key_RemoteFWUpdateImportStart.showEnable( False );					// スタートキー非表示.
				Txt_RemoteFWUpdateImportOK.showEnable( True );							// OKメッセージ表示.
			} else {
				Key_RemoteFWUpdateImportStart.showEnable( isFWUpdateUsbImport() );	// スタートキー表示/非表示.
				Txt_RemoteFWUpdateImportOK.showEnable( False );							// OKメッセージ非表示.
			}
			// 「インポート結果」表示設定.
			showFWUpdateImportResult( );											// インポート結果内容の設定.
			Grp_RemoteFWUpdateImportAllResult.showEnable( True );					// インポート結果の表示. 
			break;
		}
		default:
		{
			char c_LogfMessageDef[128] = {};
			snprintf( c_LogfMessageDef, sizeof(c_LogfMessageDef), "default. e_USBImportSts:%d", e_USBImportSts );
			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_INFO, c_LogfMessageDef );
			break;
		}
	}
}

//================================================================================================.
// 90B95100 本体自動更新設定／本体設定ｲﾝﾎﾟｰﾄ : ボタン押下.
// 履歴		:2015/08/28 OPS1-MSE永野 [ZeusS_ZX0][RQ-257][CQ518114]認証カスタマイズの追加.
//================================================================================================.
void PServiceRemoteFWUpdateMainSettingImport::procButtonOn( uchar option )
{
	APIC_UsbImportExportOperation* pc_UsbImportExportOperation = APIC_UsbImportExportOperation::newInstance();
	PServiceRemoteFWUpdateUSBExportInfo* pc_RemoteFWUpdateUSBExportInfo = PServiceRemoteFWUpdateUSBExportInfo::newInstance();
	if ( NULL == pc_UsbImportExportOperation || NULL == pc_RemoteFWUpdateUSBExportInfo ) {
// Comment 2015/11/02【HCLT-Juned】【制御構成変更_No.76-1】Adding error code macro.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if (NULL != pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19000A0100F3B301 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}

	// インポート実行中の場合は受付拒否.
	if ( PNLE_RemoteFWUpdateUSBImportProc == pc_RemoteFWUpdateUSBExportInfo->getImportStatus() ) {
		setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}
	
	pc_RemoteFWUpdateUSBExportInfo->getPassword( sc_Pass );

	
	switch ( option ) {
		// スタートキー.
		case BTNID_RemoteFWUpdateImportStart:
		{
// comment 2019/02/14 【HCL-Naveena】【IT6_EagleH】【OP_BTS-2893 】【KLOC ID:172594,172595】SV.FMT_STR.PRINT_FORMAT_MISMATCH.BAD
// comment 2018/09/06 Sky石上 [SecV4][PKI設定の簡易化].
//			printf("[IT]PServiceRemoteFWUpdateMainSettingImport::procButtonOn() Start isExistAutoSetting:%d CollectiveYes/No %d/%d \n"
//				,pc_UsbImportExportOperation->isExistAutoSetting()
//				,pc_RemoteFWUpdateUSBExportInfo->getSelectedPKICollectiveYes()
//				,pc_RemoteFWUpdateUSBExportInfo->getSelectedPKICollectiveNo());

			// PKI関連設定ファイルあり かつ インポート確認「はい/いいえ」キー未選択の場合
			if ( ( pc_UsbImportExportOperation->isExistAutoSetting() & TYPE_ExistAutoSetting_PKI ) &&
			     ( pc_RemoteFWUpdateUSBExportInfo->getSelectedPKICollectiveYes() == False) && 
			     ( pc_RemoteFWUpdateUSBExportInfo->getSelectedPKICollectiveNo() == False ) )
			{
				// 「インポート確認中」に変更
				pc_RemoteFWUpdateUSBExportInfo->setImportStatus( PNLE_RemoteFWUpdateUSBImportConfirm );
			// PKI関連設定ファイルなし もしくは インポート確認「はい/いいえ」選択済みの場合
			} else {
				pc_RemoteFWUpdateUSBExportInfo->setImportResult( TYPE_UsbImportExportResult_None );		// インポート結果初期化.
				pc_RemoteFWUpdateUSBExportInfo->setImportStatus( PNLE_RemoteFWUpdateUSBImportProc );	// 「実行中」に変更.
				TYPE_UsbImportExportTarget e_UsbImportExportTarget = TYPE_UsbImportExportTarget_None;  // ターゲット無しをデフォルトにする.
				TYPE_UsbImportExportTarget2nd e_UsbImportExportTarget2nd = TYPE_UsbImportExportTarget2nd_None;  // Default value.
// 2019/4/9 sky-tobita 【OP_BTS-4744】メンテナンスモード設定状態判定条件を修正.
//				if( True == pc_RemoteFWUpdateUSBExportInfo->getMaintenanceMode()){
				APIC_SystemInfo* pc_SystemInfo = PnlComGetSystemInfo();
				APIC_SystemSetting* pc_SystemSetting = PnlComGetSystemSetting();
				if( ( ( NULL != pc_SystemInfo ) && ( True == pc_SystemInfo->getEnableMaintenanceMode() ) )
					&& ( ( NULL !=  pc_SystemSetting ) && ( True == pc_SystemSetting->getAllowMaintenanceMode() ) ) ) {
//Comment 2018/06/18 【IT6_DenebMLK】【HCL_Monisha】【AR1049905】 Hide the Remote diagnostic settings Key.
					APIC_SoftDipSw* pc_SoftDipSw = APIC_SoftDipSw::newInstance();
					if( NULL != pc_SoftDipSw ) {
						if(True == pc_SoftDipSw->getSoftDipSwBitForPanelSpecNo( DEFSOFTWARESW153, 3 )){
							e_UsbImportExportTarget = ( TYPE_UsbImportExportTarget_Utility						// 「ユーザー設定」をインポート項目として追加.
												  		| TYPE_UsbImportExportTarget_Service						// 「サービス設定」をインポート項目として追加.
												  		| TYPE_UsbImportExportTarget_Address						// 「アドレス帳」をインポート項目として追加.
												  		| TYPE_UsbImportExportTarget_Authentication				// 「認証関連データ」をインポート項目として追加.
												  		| TYPE_UsbImportExportTarget_Network						// 「ネットワーク設定」をインポート項目として追加.
												  		| TYPE_UsbImportExportTarget_Admin						// 「管理者設定」をインポート項目として追加.
												  		| TYPE_UsbImportExportTarget_TopMenuGadget				// 「画面カスタム設定」をインポート項目として追加.
												  		| TYPE_UsbImportExportTarget_CloudContact					// 「クラウド連携設定」をインポート項目として追加.
// comment 2015/09/01 OPS1-Sky_真田 [ZeusSZX0][RQ-387] インポート項目に「ボックス構成情報」「ユニバーサル設定」を追加.
												  		| TYPE_UsbImportExportTarget_BoxConf						// 「ボックス構成情報」をインポート項目として追加.
												  		| TYPE_UsbImportExportTarget_Universal					// 「ユニバーサル設定」をインポート項目として追加.
												  		| TYPE_UsbImportExportTarget_Custom						// 「カスタム設定」をインポート項目として追加.
// comment 2015/12/08 OPS1-Sky_南 [ZeusSZX0][CQ519395] インポート項目に「宛先ファイル(BOX宛先)」「管理者設定（BOX宛先）」を追加.
												  		| TYPE_UsbImportExportTarget_BoxAddr						// 「宛先ファイル(BOX宛先)」をインポート項目として追加.
												  		| TYPE_UsbImportExportTarget_BoxAdmin );					// 「管理者設定（BOX宛先）」をインポート項目として追加.
						}else{
							e_UsbImportExportTarget = ( TYPE_UsbImportExportTarget_Csrc							// 「遠隔診断設定」をインポート項目として追加.
												  		| TYPE_UsbImportExportTarget_Utility						// 「ユーザー設定」をインポート項目として追加.
												  		| TYPE_UsbImportExportTarget_Service						// 「サービス設定」をインポート項目として追加.
												  		| TYPE_UsbImportExportTarget_Address						// 「アドレス帳」をインポート項目として追加.
												  		| TYPE_UsbImportExportTarget_Authentication				// 「認証関連データ」をインポート項目として追加.
												  		| TYPE_UsbImportExportTarget_Network						// 「ネットワーク設定」をインポート項目として追加.
												  		| TYPE_UsbImportExportTarget_Admin						// 「管理者設定」をインポート項目として追加.
												  		| TYPE_UsbImportExportTarget_TopMenuGadget				// 「画面カスタム設定」をインポート項目として追加.
												  		| TYPE_UsbImportExportTarget_CloudContact					// 「クラウド連携設定」をインポート項目として追加.
// comment 2015/09/01 OPS1-Sky_真田 [ZeusSZX0][RQ-387] インポート項目に「ボックス構成情報」「ユニバーサル設定」を追加.
												  		| TYPE_UsbImportExportTarget_BoxConf						// 「ボックス構成情報」をインポート項目として追加.
												  		| TYPE_UsbImportExportTarget_Universal					// 「ユニバーサル設定」をインポート項目として追加.
												  		| TYPE_UsbImportExportTarget_Custom						// 「カスタム設定」をインポート項目として追加.
// comment 2015/12/08 OPS1-Sky_南 [ZeusSZX0][CQ519395] インポート項目に「宛先ファイル(BOX宛先)」「管理者設定（BOX宛先）」を追加.
												  		| TYPE_UsbImportExportTarget_BoxAddr						// 「宛先ファイル(BOX宛先)」をインポート項目として追加.
												  		| TYPE_UsbImportExportTarget_BoxAdmin );					// 「管理者設定（BOX宛先）」をインポート項目として追加.
						}
					}	
//				e_UsbImportExportTarget2nd = TYPE_UsbImportExportTarget2nd_ExtCertificates;				// 「外部証明書」をインポート項目として追加.
// comment 2018/04/24 [HCLT-Ranjith] [IT6-Eagle] [制御構成変更_No.118] Enum value for CopyProgram Key.
//				e_UsbImportExportTarget2nd = ( TYPE_UsbImportExportTarget2nd_ExtCertificates			// 「外部証明書」をインポート項目として追加.
//											  | TYPE_UsbImportExportTarget2nd_MasterConfigSetting );	// 「認証カスタマイズ」をインポート項目として追加.
// comment 2018/09/06 Sky石上 [SecV4][PKI設定の簡易化].
					// PKI関連設定ファイルあり
					if ( pc_UsbImportExportOperation->isExistAutoSetting() & TYPE_ExistAutoSetting_PKI )
					{
						e_UsbImportExportTarget2nd = ( TYPE_UsbImportExportTarget2nd_ExtCertificates			// 「外部証明書」をインポート項目として追加.
													  | TYPE_UsbImportExportTarget2nd_MasterConfigSetting
													  | TYPE_UsbImportExportTarget2nd_CopyProgramSetting		// Add Copyprogram as import item.
													  | TYPE_UsbImportExportTarget2nd_PKIAutoSetting);			// 「PKI関連設定」をインポート項目として追加
					// PKI関連設定ファイルなし
					} else {
						e_UsbImportExportTarget2nd = ( TYPE_UsbImportExportTarget2nd_ExtCertificates			// 「外部証明書」をインポート項目として追加.
													  | TYPE_UsbImportExportTarget2nd_MasterConfigSetting
													  | TYPE_UsbImportExportTarget2nd_CopyProgramSetting);		// Add Copyprogram as import item.
					}	
				} else {
//Comment 2018/06/18 【IT6_DenebMLK】【HCL_Monisha】【AR1049905】 Hide the Remote diagnostic settings Key.
						APIC_SoftDipSw* pc_SoftDipSw = APIC_SoftDipSw::newInstance();
						if( NULL != pc_SoftDipSw ) {
							if(True == pc_SoftDipSw->getSoftDipSwBitForPanelSpecNo( DEFSOFTWARESW153, 3 )){
								e_UsbImportExportTarget = ( TYPE_UsbImportExportTarget_Utility						// 「ユーザー設定」をインポート項目として追加.
												  			| TYPE_UsbImportExportTarget_Service						// 「サービス設定」をインポート項目として追加.
												  			| TYPE_UsbImportExportTarget_CloudContact );				// 「クラウド連携設定」をインポート項目として追加.
							}else{
								e_UsbImportExportTarget = ( TYPE_UsbImportExportTarget_Csrc								// 「遠隔診断設定」をインポート項目として追加.
												  			| TYPE_UsbImportExportTarget_Utility						// 「ユーザー設定」をインポート項目として追加.
												  			| TYPE_UsbImportExportTarget_Service						// 「サービス設定」をインポート項目として追加.
												  			| TYPE_UsbImportExportTarget_CloudContact );				// 「クラウド連携設定」をインポート項目として追加.
							}
						}
// comment 2018/04/24 [HCLT-Ranjith] [IT6-Eagle] [制御構成変更_No.118] Enum value for CopyProgram Key.
//				e_UsbImportExportTarget2nd = TYPE_UsbImportExportTarget2nd_MasterConfigSetting;			// 「認証カスタマイズ」をインポート項目として追加.
					e_UsbImportExportTarget2nd = ( TYPE_UsbImportExportTarget2nd_MasterConfigSetting		// 「認証カスタマイズ」をインポート項目として追加.
												  | TYPE_UsbImportExportTarget2nd_CopyProgramSetting );		// Add Copyprogram as import item.	
				
				}
				printf("[IT]PServiceRemoteFWUpdateMainSettingImport::procButtonOn() ExportTarget:0x%08x 2nd:0x%08x \n"
					,e_UsbImportExportTarget,e_UsbImportExportTarget2nd);
// comment 2022/12/19 MSCD2G-Sky [SecV6][RQ-904]インポート／エクスポート通知情報の追加.
//				pc_UsbImportExportOperation->req_UsbImportExportStart( TYPE_UsbImportExportKind_Import, e_UsbImportExportTarget, e_UsbImportExportTarget2nd, ans_UsbImport, (uchar*)sc_Pass,JLGE_InspectLogIfOperationPanel, False, JLGE_InspectLogOperateIDL_CE );
// 2023/01/26 MSCD2G-Sky [SecV6][RQ-904]インポート／エクスポート通知有無の追加.
//				pc_UsbImportExportOperation->req_UsbImportExportStart( TYPE_UsbImportExportKind_Import, e_UsbImportExportTarget, e_UsbImportExportTarget2nd, ans_UsbImport, (uchar*)sc_Pass, APIE_NotifyEmailImpExpDev_Usb, JLGE_InspectLogIfOperationPanel, False, JLGE_InspectLogOperateIDL_CE );
				pc_UsbImportExportOperation->req_UsbImportExportStart( TYPE_UsbImportExportKind_Import, e_UsbImportExportTarget, e_UsbImportExportTarget2nd, ans_UsbImport, (uchar*)sc_Pass, APIE_NotifyEmailImpExpDev_Usb, True, JLGE_InspectLogIfOperationPanel, False, JLGE_InspectLogOperateIDL_CE );
			}
			break;
		}
// comment 2018/09/06 Sky石上 [SecV4][PKI設定の簡易化].
		// PKI関連設定インポート確認「はい」キー.
		case BTNID_RemoteFWUpdateImportSelectPKICollectiveYes:
		{
			// PKI一括設定、全データクリア"する"を設定
			pc_UsbImportExportOperation->setAllDataInitialize(True);
			// 「はい」を選択状態に変更(はい/いいえ トグル切り替え).
			pc_RemoteFWUpdateUSBExportInfo->setSelectedPKICollectiveYes(True);
			pc_RemoteFWUpdateUSBExportInfo->setSelectedPKICollectiveNo(False);
			break;
		}
		// PKI関連設定インポート確認「いいえ」キー.
		case BTNID_RemoteFWUpdateImportSelectPKICollectiveNo:
		{
			// PKI一括設定、全データクリア"しない"を設定
			pc_UsbImportExportOperation->setAllDataInitialize(False);
			// 「いいえ」を選択状態に変更(はい/いいえ トグル切り替え).
			pc_RemoteFWUpdateUSBExportInfo->setSelectedPKICollectiveYes(False);
			pc_RemoteFWUpdateUSBExportInfo->setSelectedPKICollectiveNo(True);
			break;
		}
		default: LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); break;
	}
	// 画面更新.
	setupGamen();
}

//================================================================================================.
// 90B95100 本体自動更新設定／本体設定ｲﾝﾎﾟｰﾄ : 画面遷移.
//================================================================================================.
void PServiceRemoteFWUpdateMainSettingImport::procGoToPage( uchar option )
{
	PServiceRemoteFWUpdateUSBExportInfo* pc_RemoteFWUpdateUSBExportInfo = PServiceRemoteFWUpdateUSBExportInfo::newInstance();
	if ( NULL == pc_RemoteFWUpdateUSBExportInfo ) {
// Comment 2015/11/02【HCLT-Juned】【制御構成変更_No.76-1】Adding error code macro.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if (NULL != pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x1900020100F3B401 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}
	
	// インポート実行中の場合は受付拒否.
	if ( PNLE_RemoteFWUpdateUSBImportProc == pc_RemoteFWUpdateUSBExportInfo->getImportStatus() ) {
		setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}

	switch ( option ) {
		// パスワード入力キー.
		case BTNID_RemoteFWUpdateImportPassInput:
		{
			// 1つ以上OKがある場合は受付拒否.
			if( 0x00000000 != (( PNLD_UsbImportTarget_FULL & pc_RemoteFWUpdateUSBExportInfo->getImportResult())
							  |( PNLD_UsbImportTarget_FULL & pc_RemoteFWUpdateUSBExportInfo->getImportResult2nd()))){
				setBuzzerType( PCGE_BuzzerType_InputNg );
				return;
			}
			nextGamen = &gp_ServiceRemoteFWUpdateMainSettingExportInput;	// 90B95101 本体自動更新設定／本体設定ｲﾝﾎﾟｰﾄ／ｲﾝﾎﾟｰﾄﾊﾟｽﾜｰﾄﾞ入力.
			break;
		}
		// 以外.
		default: LOGF_debug_PutEventLog(LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!"); break;
	}
}
