//================================================================================================.
// 90B95100 本体自動更新設定／本体設定ｲﾝﾎﾟｰﾄ : USB使用可能判定.
//================================================================================================.
Bool PServiceRemoteFWUpdateMainSettingImport::isFWUpdateUsbImport()
{
	Bool bl_ret = False;

	APIC_UsbMemDeviceInfo* pc_UsbMemDeviceInfo = APIC_UsbMemDeviceInfo::newInstance();
	if ( NULL == pc_UsbMemDeviceInfo ) {
// Comment 2015/11/02【HCLT-Juned】【制御構成変更_No.76-1】Adding error code macro.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if (NULL != pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x1900660100F3B901 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return False;
	}
	// USBが使用可能.
	if( False == pc_UsbMemDeviceInfo->isWarning( TYPE_UsbMemWarningTwoInsert ) 	// USB複数検知でない.
	 && TYPD_UsbMemStatusConnect == pc_UsbMemDeviceInfo->getStatus()			// USB装着.
	 && False == PnlComGetSystemStatus()->getNotSupportUSBConnectBsp()			// 未対応USB（BSP用）でない.
	 && False == PnlComGetSystemStatus()->getNotSupportUSBConnectSaa() ) {		// 未対応USB（SAA用）でない.
		bl_ret = True;
	}

	return bl_ret;
}

//================================================================================================.
// 90B95100 本体自動更新設定／本体設定ｲﾝﾎﾟｰﾄ : インポート結果を内部ステータスに反映する.
//================================================================================================.
void PServiceRemoteFWUpdateMainSettingImport::reflectionFWUpdateUsbImportResult()
{
	PServiceRemoteFWUpdateUSBExportInfo* pc_RemoteFWUpdateUSBExportInfo = PServiceRemoteFWUpdateUSBExportInfo::newInstance();
	if ( NULL == pc_RemoteFWUpdateUSBExportInfo ) {
// Comment 2015/11/02【HCLT-Juned】【制御構成変更_No.76-1】Adding error code macro.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if (NULL != pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x1900690100F3C001 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}

	PNLE_USBImportSts e_USBImportSts = PNLE_RemoteFWUpdateUSBImportComplete;	// インポート状態.
	TYPE_UsbImportExportResult e_UsbImportExportResult = pc_RemoteFWUpdateUSBExportInfo->getImportResult();	// インポート結果取得.
	TYPE_UsbImportExportResult2nd e_UsbImportExportResult2nd = pc_RemoteFWUpdateUSBExportInfo->getImportResult2nd();	// インポート結果取得.

	// システムエラー／インポート対象ファイルなし.
	TYPE_UsbImportExportTarget e_UsbImportExportTarget = (e_UsbImportExportResult >> 4) & PNLD_UsbImportTarget_FULL;
	TYPE_UsbImportExportTarget2nd e_UsbImportExportTarget2nd = (e_UsbImportExportResult2nd >> 4) & PNLD_UsbImportTarget_FULL;
	if( ( e_UsbImportExportTarget != ( e_UsbImportExportTarget & e_UsbImportExportResult ) )
	 || ( e_UsbImportExportTarget2nd != ( e_UsbImportExportTarget2nd & e_UsbImportExportResult2nd ) ) ) {
		e_USBImportSts = PNLE_RemoteFWUpdateUSBImportSystemError;
	// キャンセル時.
	} else if ( PNLD_UsbImportTarget_CANCEL == ( PNLD_UsbImportTarget_CANCEL & e_UsbImportExportResult ) ) {
		e_USBImportSts = PNLE_RemoteFWUpdateUSBImportCancel;
	// 成功時.
	} else {
		e_USBImportSts = PNLE_RemoteFWUpdateUSBImportComplete;
	}
	
	pc_RemoteFWUpdateUSBExportInfo->setImportStatus( e_USBImportSts );	// インポート状態設定.

}

