//	if( NULL == pc_HddInfo ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); return; }
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//	LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
	if( NULL == pc_SystemInfo ) {
//		if (NULL !=pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x1900020100F50301 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}
	if( NULL == pc_Maintenance ) {
//		if (NULL !=pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x1900020100F50401 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}
	if( NULL == pc_SystemInfo ) {
//		if (NULL !=pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x1900020100F50501 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}
	if( NULL == pc_HddInfo ) {
//		if (NULL !=pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x1900020100F50601 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}
	// メンテナンスモード中かつメンテナンスモード許可設定が許可となっているかの確認を実施し、クラス変数として保存する.
	if( ( True == pc_SystemInfo->getEnableMaintenanceMode() )
	    && ( True == pc_Maintenance->getAllowMaintenanceMode() ) ) {
		// メンテナンスモード中かつメンテナンスモード許可設定が許可の場合.
		m_bl_MaintenanceModeSelect = True;
	} else {
		m_bl_MaintenanceModeSelect = False;
	}
// comment 2019/02/14 【HCL-Naveena】【IT6_EagleH】【OP_BTS-2893 】【KLOC ID:172588,172589,172597】SV.FMT_STR.PRINT_FORMAT_MISMATCH.BAD
