	// エクスポート項目の初期値設定.
	m_bl_RemoteDiagnosisSettingSelelct	= True;					// 「遠隔診断設定」キー選択状態		【選択】.
	m_bl_UserSettingSelelct				= True;					// 「ユーザー設定」キー選択状態		【選択】.
	m_bl_ServiceSettingSelelct			= True;					// 「サービス設定」キー選択状態		【選択】.
