	m_e_USBImportSts = PNLE_RemoteFWUpdateUSBImportPreProc;		// インポート状態を実行前に設定.
	m_e_UsbImportResult = TYPE_UsbImportExportResult_None;		// インポート結果を結果なしに設定.
	m_e_UsbImportResult2nd = TYPE_UsbImportExportResult2nd_None;	// インポート結果を結果なしに設定.
