//================================================================================================.
// 90B95100 本体自動更新設定／本体設定ｴｸｽﾎﾟｰﾄ : 画面開始.
//================================================================================================.
void PServiceRemoteFWUpdateMainSettingExport::startGamen()
{
	PServiceNoFunctionCodeCom::startGamen();	// 親処理実行.
	// 変数初期化.
	bl_ExecStsToggle = False;					// 進行状態表示トグル.
// comment 2015/07/29 HCLT-Ezhil [ZeusS_ZX0][RQ-163][WP1385] Display condition of USB.

// Comment 2017/11/29 【HCLT-Vishal】【Eagle】【制御構成変更_No.4】 Removing old function version check condition.
	PNLC_USBConnectionPermission c_UsbPermission;
	PNLE_EnableUSBConnectionPermissionForAll e_usbAll = c_UsbPermission.getEnableUSBConnectionPermissionForAll();
	PNLE_EnableUSBConnectionPermissionForService e_usbforService = c_UsbPermission.getEnableUSBConnectionPermissionForService();
	if(( PNLE_EnableUSBConnectionPermissionForAll_Disable == e_usbAll ) || ( PNLE_EnableUSBConnectionPermissionForService_Disable == e_usbforService )) {
		m_bl_USBConnectionPermissionFlag = False;
	} else {
		m_bl_USBConnectionPermissionFlag = True;
	}
	// パスワード初期化.
	memset( sc_Pass, '\0', sizeof( sc_Pass ) );
// comment 2018/04/24 [HCLT-Ranjith] [IT6-Eagle] [制御構成変更_No.118] Enable 3rd page.
//	m_uc_TotalPage = PNLD_RemoteFWUpdateExportP2;	// 表示項目ページ数.
	m_uc_TotalPage = PNLD_RemoteFWUpdateExportP3;	// 表示項目ページ数.
// Comment 2015/10/05 HCLT-Binesh [MinervaSBK] [CQ518363] Get the external certificate installation status.
	m_bl_ExtCertStatus = extCertStatus();
}

// comment 2015/04/17 HCLT-Thangachamy [MinervaSBK] [UV-01432] Checking External Certificate availablity.
/**
 * @brief   : Get the External certificate status.
 * @note    : None.
 * @param   : None.
 * @return  : Bool.
 */
Bool PServiceRemoteFWUpdateMainSettingExport::extCertStatus()
{
	TYPC_SslCertList	st_ExtCertList[PNLD_ExternalCertificateListNum];	// External certificates list.
	uint32_t			ui32_CertNum = PNLD_ExternalCertificateListNum;		// No.of certification.
	// Checking External Certificates status.
	if ((( TYPE_SslStatus_SslSuccess ==  PnlComGetSslSetting()->getSslCertList(0, TYPD_CertType_Root,				&ui32_CertNum, &st_ExtCertList[0] )) && ( 0 < ui32_CertNum ))
	  ||(( TYPE_SslStatus_SslSuccess ==  PnlComGetSslSetting()->getSslCertList(0, TYPD_CertType_Intermediate,		&ui32_CertNum, &st_ExtCertList[0] )) && ( 0 < ui32_CertNum ))
	  ||(( TYPE_SslStatus_SslSuccess ==  PnlComGetSslSetting()->getSslCertList(0, TYPD_CertType_Entity,				&ui32_CertNum, &st_ExtCertList[0] )) && ( 0 < ui32_CertNum ))
	  ||(( TYPE_SslStatus_SslSuccess ==  PnlComGetSslSetting()->getSslCertList(0, TYPD_CertType_Untrusted,			&ui32_CertNum, &st_ExtCertList[0] )) && ( 0 < ui32_CertNum ))
	  ||(( TYPE_SslStatus_SslSuccess ==  PnlComGetSslSetting()->getSslCertList(0, TYPD_CertType_Device_Csrc,		&ui32_CertNum, &st_ExtCertList[0] )) && ( 0 < ui32_CertNum ))
	  ||(( TYPE_SslStatus_SslSuccess ==  PnlComGetSslSetting()->getSslCertList(0, TYPD_CertType_Root_Csrc,			&ui32_CertNum, &st_ExtCertList[0] )) && ( 0 < ui32_CertNum ))
	  ||(( TYPE_SslStatus_SslSuccess ==  PnlComGetSslSetting()->getSslCertList(0, TYPD_CertType_Intermediate_Csrc,	&ui32_CertNum, &st_ExtCertList[0] )) && ( 0 < ui32_CertNum ))){
	  	// External Certificate is available.
		return True;
	}
	return False;
}

