//================================================================================================.
// 90B95100 本体自動更新設定／本体設定ｴｸｽﾎﾟｰﾄ : USB使用可能判定.
//================================================================================================.
Bool PServiceRemoteFWUpdateMainSettingExport::isFWUpdateUsbExport()
{
	Bool bl_ret = False;

	APIC_UsbMemDeviceInfo* pc_UsbMemDeviceInfo = APIC_UsbMemDeviceInfo::newInstance();
	if( NULL == pc_UsbMemDeviceInfo ) {
// Comment 2015/11/02 【ZeusS_ZX0】【HCL_Vasu】【制御構成変更_No.76-1】Adding Error Code macro.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//		if (NULL !=pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x1900660100F50F01 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return False;
	}
	// USBが使用可能.
	if( False == pc_UsbMemDeviceInfo->isWarning( TYPE_UsbMemWarningTwoInsert ) 	// USB複数検知でない.
	    && TYPD_UsbMemStatusConnect == pc_UsbMemDeviceInfo->getStatus()			// USB装着.
	    && False == PnlComGetSystemStatus()->getNotSupportUSBConnectBsp()			// 未対応USB（BSP用）でない.
	    && False == PnlComGetSystemStatus()->getNotSupportUSBConnectSaa() ) {		// 未対応USB（SAA用）でない.
		bl_ret = True;
	}

	return bl_ret;
}

//================================================================================================.
// 90B95100 本体自動更新設定／本体設定ｴｸｽﾎﾟｰﾄ : エクスポート結果を内部ステータスに反映する.
//================================================================================================.
void PServiceRemoteFWUpdateMainSettingExport::reflectionFWUpdateUsbExportResult()
{
	APIC_UsbMemDeviceInfo* pc_UsbMemDeviceInfo = APIC_UsbMemDeviceInfo::newInstance();
	PServiceRemoteFWUpdateUSBExportInfo* pc_RemoteFWUpdateUSBExportInfo = PServiceRemoteFWUpdateUSBExportInfo::newInstance();
	if( NULL == pc_UsbMemDeviceInfo || NULL == pc_RemoteFWUpdateUSBExportInfo ) {
// Comment 2015/11/02 【ZeusS_ZX0】【HCL_Vasu】【制御構成変更_No.76-1】Adding Error Code macro.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//		if (NULL !=pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x1900690100F51001 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}

	PNLE_USBExportSts e_USBExportSts = PNLE_RemoteFWUpdateUSBExportComplete;	// エクスポート状態.
	TYPE_UsbImportExportResult e_UsbImportExportResult = pc_RemoteFWUpdateUSBExportInfo->getExportResult();	// エクスポート結果取得.
// comment 2015/04/17 HCLT-Thangachamy [MinervaSBK] [UV-01432] Getting Export result for target2nd items.
	TYPE_UsbImportExportResult2nd e_UsbImportExportResult2nd = pc_RemoteFWUpdateUSBExportInfo->getExportResult2nd();	// gets Export result for target2nd items.

	// エクスポート結果一覧.
	// 全て成功している場合は、0x0000070Fとなる為、PNLD_UsbExportTarget_FULL(0x0000070F)でマスクし、結果判定を行う.
	// ネットワークファイル対象 - 結果NG  (0x00000010).
	// ネットワークファイル対象 - 結果OK  (0x00000011).
	// CSRC対象 - 結果NG                  (0x00000020).
	// CSRC対象 - 結果OK                  (0x00000022).
	// 認証ファイル対象 - 結果NG          (0x00000040).
	// 認証ファイル対象 - 結果OK          (0x00000044).
	// 宛先ファイル対象 - 結果NG          (0x00000080).
	// 宛先ファイル対象 - 結果OK          (0x00000088).
	// ユーティリティ設定対象 - 結果NG    (0x00001000).
	// ユーティリティ設定対象 - 結果OK    (0x00001100).
	// 管理者設定対象 - 結果NG            (0x00002000).
	// 管理者設定対象 - 結果OK            (0x00002200).
	// サービスマン設定対象 - 結果NG      (0x00004000).
	// サービスマン設定対象 - 結果OK      (0x00004400).
	// キャンセル完了通知 - 結果          (0x10000000).

	// エクスポート失敗時.
	TYPE_UsbImportExportTarget e_UsbImportExportTarget = ( e_UsbImportExportResult >> 4 ) & PNLD_UsbExportTarget_FULL;
// comment 2015/04/17 HCLT-Thangachamy [MinervaSBK] [UV-01432] Checking Export status for target2nd items.
	TYPE_UsbImportExportTarget2nd e_UsbImportExportTarget2nd = (e_UsbImportExportResult2nd >> 4) & PNLD_UsbExportTarget_FULL;
	//if( e_UsbImportExportTarget != ( e_UsbImportExportTarget & e_UsbImportExportResult ) ) {
	if( ( e_UsbImportExportTarget != ( e_UsbImportExportTarget & e_UsbImportExportResult ) ) 
	 || ( e_UsbImportExportTarget2nd != ( e_UsbImportExportTarget2nd & e_UsbImportExportResult2nd ) ) ){
		// メモリフルエラー.
		// エクスポート先がUSBかつメモリフルエラーの場合.
		if( ( PNLE_RemoteFWUpdateSelectUSB == pc_RemoteFWUpdateUSBExportInfo->getExportSelect() )
		    && ( True == pc_UsbMemDeviceInfo->isWarning( TYPE_UsbMemWarningMemoryFull ) ) ) {
			e_USBExportSts = PNLE_RemoteFWUpdateUSBExportCapaError;
			// 上記以外のエラー.
		} else {
			e_USBExportSts = PNLE_RemoteFWUpdateUSBExportSystemError;
		}
		// キャンセル時.
// comment 2015/04/17 HCLT-Thangachamy [MinervaSBK] [UV-01432] Checking Export status for target2nd items.
//	} else if ( PNLD_UsbExportTarget_CANCEL == ( PNLD_UsbExportTarget_CANCEL & e_UsbImportExportResult ) ) {	
	} else if ( ( PNLD_UsbExportTarget_CANCEL == ( PNLD_UsbExportTarget_CANCEL & e_UsbImportExportResult ) ) 
	 	     || ( PNLD_UsbExportTarget_CANCEL == ( PNLD_UsbExportTarget_CANCEL & e_UsbImportExportResult2nd ) ) ) {
		e_USBExportSts = PNLE_RemoteFWUpdateUSBExportCancel;
		// 成功時.
	} else {
		e_USBExportSts = PNLE_RemoteFWUpdateUSBExportComplete;
	}

	pc_RemoteFWUpdateUSBExportInfo->setExportStatus( e_USBExportSts );	// エクスポート状態設定.
}
