//================================================================================================.
// zcB9530000 本体自動更新設定／本体設定JSON形式 : USB使用可能判定.
//================================================================================================.
Bool PServiceRemoteFWUpdateMachineSettingsJson::isUSBAvailable()
{
	Bool b_ret = False;

	APIC_UsbMemDeviceInfo* pc_UsbMemDeviceInfo = APIC_UsbMemDeviceInfo::newInstance();
	if ( NULL == pc_UsbMemDeviceInfo ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return False;
	}

	// USBが使用可能.
	if(( False == pc_UsbMemDeviceInfo->isWarning( TYPE_UsbMemWarningTwoInsert ) ) 	// USB複数検知でない.
	 &&( TYPD_UsbMemStatusConnect == pc_UsbMemDeviceInfo->getStatus() )			// USB装着.
	 &&( False == PnlComGetSystemStatus()->getNotSupportUSBConnectBsp() )			// 未対応USB（BSP用）でない.
	 &&( False == PnlComGetSystemStatus()->getNotSupportUSBConnectSaa() )) {		// 未対応USB（SAA用）でない.
		b_ret = True;
	}

	return b_ret;
}
//================================================================================================.
// zcB9530000 本体自動更新設定／本体設定JSON形式 : 本体設定JSON形式結果を内部ステータスに反映する.
//================================================================================================.
void PServiceRemoteFWUpdateMachineSettingsJson::reflectionFWUpdateMachineSettingsJsonManipulationResult()
{
	PServiceRemoteFWUpdateMachineSettingsJsonInfo* pc_RemoteFWUpdateMachineSettingsJsonInfo = PServiceRemoteFWUpdateMachineSettingsJsonInfo::newInstance();
	APIC_UsbMemDeviceInfo* pc_UsbMemDeviceInfo = APIC_UsbMemDeviceInfo::newInstance();
	if ( ( NULL == pc_RemoteFWUpdateMachineSettingsJsonInfo )||( NULL == pc_UsbMemDeviceInfo ) ){
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}

	PNLE_MachineSettingsJsonOperationStatus e_MachineSettingsJsonSts = PNLE_RemoteMachineSettingsJsonComplete;	// 本体設定JSON形式状態.
	TYPE_RmtControlNotifyResult e_RmtControlNotifyResult = pc_RemoteFWUpdateMachineSettingsJsonInfo->getResult();	// 本体設定JSON形式結果取得.
	
	if ( TYPE_RmtControlNotifyResult_Failure == e_RmtControlNotifyResult) {				// 本体設定JSON形式機能実行失敗時.
		if ( True == pc_UsbMemDeviceInfo->isWarning( TYPE_UsbMemWarningMemoryFull ) ) { // USBメモリフルエラーの場合.
			e_MachineSettingsJsonSts = PNLE_RemoteMachineSettingsJsonCapaError;
		}else{
			e_MachineSettingsJsonSts = PNLE_RemoteMachineSettingsJsonSystemError;
		}
	} else {
		e_MachineSettingsJsonSts = PNLE_RemoteMachineSettingsJsonComplete;										// 本体設定JSON形式機能成功.
	}

	pc_RemoteFWUpdateMachineSettingsJsonInfo->setStatus( e_MachineSettingsJsonSts );	// 本体設定JSON形式状態設定.
}
//================================================================================================.
//  zcB9530000 本体自動更新設定／本体設定JSON形式: スタートキーの表示/非表示判定.
//================================================================================================.
Bool PServiceRemoteFWUpdateMachineSettingsJson::isStartKeyEnable()
{
	char	sc_chkPass[ PNLD_USBExportPassMax + 1 ] = {'\0'};	// パスワード.

	PServiceRemoteFWUpdateMachineSettingsJsonInfo* pc_RemoteFWUpdateMachineSettingsJsonInfo = PServiceRemoteFWUpdateMachineSettingsJsonInfo::newInstance();

	if ( NULL == pc_RemoteFWUpdateMachineSettingsJsonInfo ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return False;
	}

	if ( PNLE_RemoteMachineSettingsJsonOperationNone == pc_RemoteFWUpdateMachineSettingsJsonInfo->getMachineSettingsJsonOperationExportImport()){
		// 設定 取得 両方未選択.
		return False;
	}

	pc_RemoteFWUpdateMachineSettingsJsonInfo->getPassword( sc_chkPass );	// パスワード取得.
	// パスワード入力状態であるか確認を実施.
	if ( '\0' == sc_chkPass[0] ) {
		// パスワード未入力時はスタートキー非表示.
		return False;
	}

	// USB接続許可設定が禁止の場合はStartボタン非表示.
	PNLC_USBConnectionPermission c_UsbPermission;
	PNLE_EnableUSBConnectionPermissionForAll e_usbAll = c_UsbPermission.getEnableUSBConnectionPermissionForAll();
	PNLE_EnableUSBConnectionPermissionForService e_usbforService = c_UsbPermission.getEnableUSBConnectionPermissionForService();
	if (( PNLE_EnableUSBConnectionPermissionForAll_Disable == e_usbAll ) || ( PNLE_EnableUSBConnectionPermissionForService_Disable == e_usbforService )) {
		return False;
	}
	
	if ( False == isUSBAvailable() ) {
		// USB選択状態でUSB使用不可の場合はスタートキー非表示.
		return False;
	}
	return True;
}

