//==================================================================================================
// 概要     : 更新ログ送信共通：画面更新処理.
// 引数     : オプション.
// 戻り値   : なし.
// 備考     : なし.
//==================================================================================================
void PServiceRemoteFWUpdateClientLogForwardCom::setupGamen( short option )
{
	// 親クラスをコール.
	PServiceNoFunctionCodeCom::setupGamen( option );

	switch( m_e_RemoteFWUpdateClientLogForwardComGamenType ) {
		case PNLE_RemoteFWUpdateClientLogForwardComGamenType_LogSetting:
			// 更新ログ送信キー選択.
			Rbt_RemoteFWUpdClientLogForwardMenu.select( 0 );
			break;
		case PNLE_RemoteFWUpdateClientLogForwardComGamenType_Protocol:
			// 送信プロトコルキー選択.
			Rbt_RemoteFWUpdClientLogForwardMenu.select( 1 );
			break;
		case PNLE_RemoteFWUpdateClientLogForwardComGamenType_SMB:
			// SMB設定キー選択.
			Rbt_RemoteFWUpdClientLogForwardMenu.select( 2 );
			break;
		case PNLE_RemoteFWUpdateClientLogForwardComGamenType_WebDAV:
			// WebDAV設定キー選択.
			Rbt_RemoteFWUpdClientLogForwardMenu.select( 3 );
			break;
		default:
			break;
	}

	Bool bl_LogForwardEnable = PNLC_RemoteFWUpdateClientLogForwardSetting::newInstance()->getLogForward( );
	// 「送信プロトコル」「SMB設定」「WebDAV設定」の表示/非表示.
	Key_RemoteFWUpdClientLogForwardProtocol.showEnable( bl_LogForwardEnable );
	Key_RemoteFWUpdClientLogForwardSMB.showEnable( bl_LogForwardEnable );
	Key_RemoteFWUpdClientLogForwardWebDAV.showEnable( bl_LogForwardEnable );
}
//==================================================================================================.
// 概要     : 更新ログ送信共通：起動元画面の終了処理を呼び出すための通知.
// 引数     : オプション.
// 戻り値   : なし.
// 備考     : なし.
//==================================================================================================.
void PServiceRemoteFWUpdateClientLogForwardCom::notifyendGamen()
{
	setTurnGamenNow();	// 現在の画面を戻り画面にする.
}
//==================================================================================================
// 概要     : 更新ログ送信共通：左側のメニューのインデックスキー押下.
// 引数     : キーID.
// 戻り値   : なし.
// 備考     : なし.
//==================================================================================================
void PServiceRemoteFWUpdateClientLogForwardCom::procIndexButton( uchar option )
{
	// 親クラスをコール.
	PServiceNoFunctionCodeCom::procIndexButton( option );

	switch( option ) {
		case BTNID_SERV_FWUPD_CLIENTLOGFORWARD_SETTINGS:	// 更新ログ送信.
			nextGamen = &gp_ServiceRemoteFWUpdateClientLogForwardSetting;
			break;
		case BTNID_SERV_FWUPD_CLIENTLOGFORWARD_PROTOCOL:	// 送信プロトコル.
			nextGamen = &gp_ServiceRemoteFWUpdateClientLogForwardProtocol;
			break;
		case BTNID_SERV_FWUPD_CLIENTLOGFORWARD_SMB:			// SMB設定.
			nextGamen = &gp_ServiceRemoteFWUpdateClientLogForwardSMBHostName;
			break;
		case BTNID_SERV_FWUPD_CLIENTLOGFORWARD_WEBDAV:		// WebDAV設定.
			nextGamen = &gp_ServiceRemoteFWUpdateClientLogForwardWebDAVURL;
			break;
		default:
			// 何もしない.
			break;
	}
}
//==================================================================================================
// 概要     : 更新ログ送信共通：OKキー押下処理.
// 引数     : オプション.
// 戻り値   : なし.
// 備考     : なし.
//==================================================================================================
void PServiceRemoteFWUpdateClientLogForwardCom::procOk( uchar option )
{
	// 親クラスをコール.
	PServiceNoFunctionCodeCom::procOk( option );

	if( False == PNLC_RemoteFWUpdateClientLogForwardSetting::newInstance()->commit( True ) ) {
		// 設定値をNV-RAMへ書き込もうとしたが入力不足項目があり書き込みできなかった場合.
		setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}
	nextGamen = &gp_ServiceRemoteFWUpdateMenu;
}

//==================================================================================================
// 概要     : 90B94700 本体自動更新設定／更新ログ送信 : 画面開始処理.
// 引数     : なし.
// 戻り値   : なし.
// 備考     : なし.
//==================================================================================================
void PServiceRemoteFWUpdateClientLogForwardSetting::startGamen()
{
	// 親クラスをコール.
	PServiceRemoteFWUpdateClientLogForwardCom::startGamen();

	if( True == m_blFromMenu ) {
		// メニューからの遷移時のみNV-RAMから設定値を一括ロード.
		PNLC_RemoteFWUpdateClientLogForwardSetting::newInstance()->load();
		m_blFromMenu = False;
	}
}
//==================================================================================================
// 概要     : 90B94700 本体自動更新設定／更新ログ送信 : 画面更新処理.
// 引数     : オプション.
// 戻り値   : なし.
// 備考     : なし.
//==================================================================================================
void PServiceRemoteFWUpdateClientLogForwardSetting::setupGamen( short option )
{
	// 親クラスをコール.
	PServiceRemoteFWUpdateClientLogForwardCom::setupGamen( option );

	if( True == PNLC_RemoteFWUpdateClientLogForwardSetting::newInstance()->getLogForward( ) ) {
		// 「使用する」キー選択.
		Rbt_RemoteFWUpdClientLogForwardSettingsSelect.select( 0 );
	} else {
		// 「使用しない」キー選択.
		Rbt_RemoteFWUpdClientLogForwardSettingsSelect.select( 1 );
	}
}
//==================================================================================================
// 概要     : 90B94700 本体自動更新設定／更新ログ送信 : キー押下処理.
// 引数     : キーID.
// 戻り値   : なし.
// 備考     : なし.
//==================================================================================================
void PServiceRemoteFWUpdateClientLogForwardSetting::procButtonOn( uchar option )
{
	// 親クラスをコール.
	PServiceRemoteFWUpdateClientLogForwardCom::procButtonOn( option );

	switch( option ) {
		case BTNID_SERV_FWUPD_CLIENTLOGFORWARD_SETTINGS_USE:
			PNLC_RemoteFWUpdateClientLogForwardSetting::newInstance()->setLogForward( True );
			break;
		case BTNID_SERV_FWUPD_CLIENTLOGFORWARD_SETTINGS_NOTUSE:
			PNLC_RemoteFWUpdateClientLogForwardSetting::newInstance()->setLogForward( False );
			break;
		default:
			break;
	}
	// 画面更新.
	setupGamen();
}

