void PServiceRemoteFWUpdateClientLogForwardSMBUserPassword::setupGamen( short option )
{
	// 親クラスをコール.
	PServiceRemoteFWUpdateClientLogForwardSMBCom::setupGamen( option );

	// パスワードがセットされていれば「*」を10個セット.
	char sc_LocalPasswordAster[ 10 + 1 ];
	memset( sc_LocalPasswordAster, 0, sizeof( sc_LocalPasswordAster ) );
	// パスワードが設定されているかチェック.
	if( m_scSMBUserPassword[0] != '\0' ) {
		strcpy( sc_LocalPasswordAster, "**********" );
	} else {
		strcpy( sc_LocalPasswordAster, "" );
	}
	// パスワードの表示.
	Btx_RemoteFWUpdClientLogForwardSMBDisp.changeExternalText( ( unsigned char* )sc_LocalPasswordAster );
}
