//==================================================================================================
// 概要     : サーバーログ送信共通：画面更新処理.
// 引数     : オプション.
// 戻り値   : なし.
// 備考     : なし.
//==================================================================================================
void PServiceRemoteFWUpdateServerLogForwardCom::setupGamen( short option )
{
	// 親クラスをコール.
	PServiceNoFunctionCodeCom::setupGamen( option );

	switch( m_e_RemoteFWUpdateServerLogForwardComGamenType ) {
		case PNLE_RemoteFWUpdateServerLogForwardComGamenType_LogSetting:
			// サーバーログ送信キー選択.
			Rbt_RemoteFWUpdServerLogForwardMenu.select( 0 );
			break;
		case PNLE_RemoteFWUpdateServerLogForwardComGamenType_Protocol:
			// 送信プロトコルキー選択.
			Rbt_RemoteFWUpdServerLogForwardMenu.select( 1 );
			break;
		case PNLE_RemoteFWUpdateServerLogForwardComGamenType_SMB:
			// SMB設定キー選択.
			Rbt_RemoteFWUpdServerLogForwardMenu.select( 2 );
			break;
		case PNLE_RemoteFWUpdateServerLogForwardComGamenType_WebDAV:
			// WebDAV設定キー選択.
			Rbt_RemoteFWUpdServerLogForwardMenu.select( 3 );
			break;
		default:
			break;
	}

	Bool bl_LogForwardEnable = PNLC_RemoteFWUpdateServerLogForwardSetting::newInstance()->getLogForward( );
	// 「送信プロトコル」「SMB設定」「WebDAV設定」の表示/非表示.
	Key_RemoteFWUpdServerLogForwardProtocol.showEnable( bl_LogForwardEnable );
	Key_RemoteFWUpdServerLogForwardSMB.showEnable( bl_LogForwardEnable );
	Key_RemoteFWUpdServerLogForwardWebDAV.showEnable( bl_LogForwardEnable );
}
//==================================================================================================.
// 概要     : サーバーログ送信共通：起動元画面の終了処理を呼び出すための通知.
// 引数     : オプション.
// 戻り値   : なし.
// 備考     : なし.
//==================================================================================================.
void PServiceRemoteFWUpdateServerLogForwardCom::notifyendGamen()
{
	setTurnGamenNow();	// 現在の画面を戻り画面にする.
}
//==================================================================================================
// 概要     : サーバーログ送信共通：左側のメニューのインデックスキー押下.
// 引数     : キーID.
// 戻り値   : なし.
// 備考     : なし.
//==================================================================================================
void PServiceRemoteFWUpdateServerLogForwardCom::procIndexButton( uchar option )
{
	// 親クラスをコール.
	PServiceNoFunctionCodeCom::procIndexButton( option );

	switch( option ) {
		case BTNID_SERV_FWUPD_SERVERLOGFORWARD_SETTINGS:	// サーバーログ送信.
			nextGamen = &gp_ServiceRemoteFWUpdateServerLogForwardSetting;
			break;
		case BTNID_SERV_FWUPD_SERVERLOGFORWARD_PROTOCOL:	// 送信プロトコル.
			nextGamen = &gp_ServiceRemoteFWUpdateServerLogForwardProtocol;
			break;
		case BTNID_SERV_FWUPD_SERVERLOGFORWARD_SMB:			// SMB設定.
			nextGamen = &gp_ServiceRemoteFWUpdateServerLogForwardSMBHostName;
			break;
		case BTNID_SERV_FWUPD_SERVERLOGFORWARD_WEBDAV:		// WebDAV設定.
			nextGamen = &gp_ServiceRemoteFWUpdateServerLogForwardWebDAVURL;
			break;
		default:
			// 何もしない.
			break;
	}
}
//==================================================================================================
// 概要     : サーバーログ送信共通：OKキー押下処理.
// 引数     : オプション.
// 戻り値   : なし.
// 備考     : なし.
//==================================================================================================
void PServiceRemoteFWUpdateServerLogForwardCom::procOk( uchar option )
{
	// 親クラスをコール.
	PServiceNoFunctionCodeCom::procOk( option );

	if( False == PNLC_RemoteFWUpdateServerLogForwardSetting::newInstance()->commit( True ) ) {
		// 設定値をNV-RAMへ書き込もうとしたが入力不足項目があり書き込みできなかった場合.
		setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}
	nextGamen = &gp_ServiceRemoteFWUpdateMenu;
}

//==================================================================================================
// 概要     : 90B94900 本体自動更新設定／サーバーログ送信 : 画面開始処理.
// 引数     : なし.
// 戻り値   : なし.
// 備考     : なし.
//==================================================================================================
void PServiceRemoteFWUpdateServerLogForwardSetting::startGamen()
{
	// 親クラスをコール.
	PServiceRemoteFWUpdateServerLogForwardCom::startGamen();

	if( True == m_blFromMenu ) {
		// メニューからの遷移時のみNV-RAMから設定値を一括ロード.
		PNLC_RemoteFWUpdateServerLogForwardSetting::newInstance()->load();
		m_blFromMenu = False;
	}
}
