void PServiceRemoteFWUpdateServerLogForwardWebDAVProxy::procButtonOn( uchar option )
{
	// 親クラスをコール.
	PServiceRemoteFWUpdateServerLogForwardWebDAVCom::procButtonOn( option );

	switch( option ) {
		case BTNID_SERV_FWUPD_SERVERLOGFORWARD_WEBDAV_PROXY_USE:
			PNLC_RemoteFWUpdateServerLogForwardSetting::newInstance()->setWebDAVProxy( True );
			break;
		case BTNID_SERV_FWUPD_SERVERLOGFORWARD_WEBDAV_PROXY_NOTUSE:
			PNLC_RemoteFWUpdateServerLogForwardSetting::newInstance()->setWebDAVProxy( False );
			break;
		default:
			break;
	}
// Comment 2015/12/14 OPS1-Sky後藤 [ZeusS_ZX0][CQ523520] 反応総点検対応.
	setupGamen();
}

