//==================================================================================================
// 概要     : 90B94990 本体自動更新設定／ｻｰﾊﾞｰﾛｸﾞ送信／SMB設定／パスワード入力 : 画面更新処理.
// 引数     : なし.
// 戻り値   : なし.
// 備考     : なし.
//==================================================================================================
void PServiceRemoteFWUpdateServerLogForwardSMBUserPasswordInput::setupGamen( short option )
{
	// 親クラスを呼ぶ.
	PServiceRemoteFWUpdateKeyboardCom::setupGamen( option );

	// 入力禁止文字の非表示.
	APIC_SoftDipSw* pc_SoftDipSw = APIC_SoftDipSw::newInstance();
	if( NULL != pc_SoftDipSw ) {
		if( True == pc_SoftDipSw->getSoftDipSwBitForPanelSpecNo( DEFSOFTWARESW205, 4 ) ) {	// DipSW No.205=0x10.
			Kbd_ServiceInputKeybord.setDisableKeyCharCode( KC_DisableKeyPattern27 );	// パターン27(ユーロ記号) パターン15改.
		} else {
			Kbd_ServiceInputKeybord.setDisableKeyCharCode( KC_DisableKeyPattern15 );	// パターン15("ユーロ記号).
		}
	} else {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
	}
}
