//================================================================================================.
void PServiceRemoteFWUpdateDecryptPasswordSelectServer::startGamen()
{
	APIC_FWUpdateSetting* pc_FWUpdateSetting = APIC_FWUpdateSetting::newInstance();
// Comment 2015/11/02 【ZeusS_ZX0】【HCL_Vasu】【制御構成変更_No.76-1】Adding Error Code macro.
//	if( NULL == pc_FWUpdateSetting ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); return; }
	if( NULL == pc_FWUpdateSetting ) {
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//		if (NULL !=pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x1900650100F51701 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}

	// 親クラスを呼ぶ.
	PServiceNoFunctionCodeCom::startGamen();

	// NVRAMよりｻｰﾊﾞｰ1名称、ｻｰﾊﾞｰ2名称を取得する.
	pc_FWUpdateSetting->getClientServerName( sc_ServerName1 );
	pc_FWUpdateSetting->getClientServerName2( sc_ServerName2 );
}
