//関数------------------------------------------------------------------------------------------------------------------.
//概要    ：コンストラクタ.
//備考    ：.
//戻値    ：なし.
//作成者  ：OPS1佐藤.
//==================================================================================================.
// 概要     : 90B95110/90B95120/90B95130 本体自動更新設定／複合化パスワード : コンストラクタ.
//==================================================================================================.
PServiceRemoteFWUpdateDecryptPassword::PServiceRemoteFWUpdateDecryptPassword( PDisplayParts** partsTable, short partsNumber, Bool isNoWarning, Bool isDispLR )
	: PServiceRemoteFWUpdateKeyboardCom( partsTable, partsNumber, isNoWarning, isDispLR )
	, uc_nowPageNum( PNLD_ServiceDecryptPasswordP1 )
	, us_dispErrMessage( s_Space1 )
{
	// 親クラスメンバにキーボードタイプを設定.
	m_ss_Tx = PNLD_ServiceRemoteFWUpdateKeyboardTx;					// キーボード X座標.
	m_ss_Gy = PNLD_ServiceRemoteFWUpdateKeyboardGy;					// キーボード Y座標.
	m_pc_DispField = &Btx_PServiceRemoteFWUpdateKeyboardComInput;	// キーボード 入力エリアパーツ.
	m_e_CharSet = EP_CharSet_USASCII;								// 文字コード.

	// 自クラスのメンバを初期化.
	memset( sc_nowPassword, '\0', sizeof( sc_nowPassword ) );
	memset( sc_newPassword, '\0', sizeof( sc_newPassword ) );
	m_e_SelectServer = PNLE_ServiceRemoteFWUpdateSelectServer1;
}

//関数------------------------------------------------------------------------------------------------------------------.
//概要    ：画面開始処理.
//備考    ：.
//戻値    ：なし.
//作成者  ：OPS1佐藤.
//==================================================================================================.
// 概要     : 90B95110/90B95120/90B95130 本体自動更新設定／複合化パスワード : 画面開始処理.
//==================================================================================================.
void PServiceRemoteFWUpdateDecryptPassword::startGamen()
{
	// エラーメッセージをクリア.
	us_dispErrMessage = s_Space1;

	// 自クラスのメンバを初期化.
	memset( sc_nowPassword, '\0', sizeof( sc_nowPassword ) );
	memset( sc_newPassword, '\0', sizeof( sc_newPassword ) );

	// NVRAMから現在のパスワードを取得.
	if( PNLE_ServiceRemoteFWUpdateSelectServer1 == m_e_SelectServer ) {
		PnlComGetFWUpdateSetting()->getClientPasswordForDataExport( sc_nowPassword );
	}
	else {
		PnlComGetFWUpdateSetting()->getClientPasswordForDataExport2( sc_nowPassword );
	}

	// 開始画面を設定.
	if( '\0' != sc_nowPassword[0] ) {					// パスワード設定済み.
		uc_nowPageNum = PNLD_ServiceDecryptPasswordP1;	// 現在のパスワード入力画面.
	} else {											// パスワード未設定.
		uc_nowPageNum = PNLD_ServiceDecryptPasswordP2;	// 新しいパスワード入力画面.
	}

	// 表示領域に文字列をセット.
	memset( m_sc_StrKeyboard, '\0', sizeof( m_sc_StrKeyboard ) );
	setKeyboardData( m_sc_StrKeyboard, PNLD_ServiceDecryptPasswordPasswordLen, PNLD_ServiceRemoteFWUpdateInputWidth );
	m_b_Password = True;							// 入力文字「*」表示する.
	m_b_ShowPass = False;							//「*」10個表示しない.

	// 親クラスを呼び、キーボードタイプを設定.
	PServiceRemoteFWUpdateKeyboardCom::startGamen();

	// 本画面固有のキーボードタイプを設定.
	Kbd_ServiceInputKeybord.setKeybord5Country( True );									// ５ヵ国語キーボードに設定.
	Btx_PServiceRemoteFWUpdateKeyboardComInput.setCursorOption( UC_CURSOR_OPTION_OFF );	// ←→キー非表示の為カーソルをOFF.
}

//関数------------------------------------------------------------------------------------------------------------------.
//概要    ：表示部品のセットアップ.
//備考    ：.
//戻値    ：なし.
//作成者  ：OPS1佐藤.
//==================================================================================================.
// 概要     : 90B95110/90B95120/90B95130 本体自動更新設定／複合化パスワード : 表示部品のセットアップ.
//==================================================================================================.
void PServiceRemoteFWUpdateDecryptPassword::setupGamen( short option )
{
	// 親クラスを呼び、ラインキーを処理.
	PServiceRemoteFWUpdateKeyboardCom::setupGamen( option );

	// 表示テキストの変更.
	switch( uc_nowPageNum ) {
		case PNLD_ServiceDecryptPasswordP1: Txt_FWUpdateDecryptPasswordLabel.changeText( s_ITMServiceCurrentPassword );	break;	// 現在のパスワード入力.
		case PNLD_ServiceDecryptPasswordP2: Txt_FWUpdateDecryptPasswordLabel.changeText( s_ITMServiceNewPassword );		break;	// 新しいパスワード入力.
		case PNLD_ServiceDecryptPasswordP3: Txt_FWUpdateDecryptPasswordLabel.changeText( s_ITMServiceReinputPassword );	break;	// 再入力パスワード.
		default: break;
	}
	Txt_FWUpdateDecryptPasswordErrMessage.changeText( us_dispErrMessage );							// エラーメッセージ.
}

//関数------------------------------------------------------------------------------------------------------------------.
//概要    ：画面遷移処理.
//備考    ：.
//戻値    ：なし.
//作成者  ：OPS1佐藤.
//==================================================================================================.
// 概要     : 90B95110/90B95120/90B95130 本体自動更新設定／複合化パスワード : 画面遷移処理.
//==================================================================================================.
void PServiceRemoteFWUpdateDecryptPassword::procGoToPage( uchar option )
{
	switch( option ) {
		case 60:								// キャンセルキー.
			nextGamen = &gp_ServiceRemoteFWUpdateDecryptPasswordSelectServer;
			break;
		default:
			// 親クラスを呼び、ラインキーを処理.
			PServiceRemoteFWUpdateKeyboardCom::procGoToPage( option );
			break;
	}
}

//関数------------------------------------------------------------------------------------------------------------------.
//概要    ：OKキー押下処理.
//備考    ：.
//戻値    ：なし.
//作成者  ：OPS1佐藤.
//==================================================================================================.
// 概要     : 90B95110/90B95120/90B95130 本体自動更新設定／複合化パスワード : OKキー押下処理.
//==================================================================================================.
void PServiceRemoteFWUpdateDecryptPassword::procOk( uchar option )
{
	switch( uc_nowPageNum ) {
		case PNLD_ServiceDecryptPasswordP1:											//【現在のパスワード入力】.
			if( strncmp( sc_nowPassword, m_sc_StrKeyboard, PNLD_ServiceDecryptPasswordPasswordLen ) == 0 ) {
				us_dispErrMessage = s_Space1;										// エラーメッセージをクリア.
				uc_nowPageNum = 2;
			} else {
				us_dispErrMessage = s_SSNowPassWordMissteke;						//「ﾊﾟｽﾜｰﾄﾞが一致しません」.
				setBuzzerType( PCGE_BuzzerType_InputNg );
			}
			// 入力文字列とカーソル位置を初期化.
			memset( m_sc_StrKeyboard, '\0', sizeof( m_sc_StrKeyboard ) );
			m_c_SlideTextMgr.init_CLCD( m_sc_StrKeyboard, m_sc_KeyboardWidth, m_ss_MaxInputNum, m_pc_DispField, getCharSetForPanel() );
			break;

		case PNLD_ServiceDecryptPasswordP2:											//【新しいパスワード入力】.
			if( '\0' != m_sc_StrKeyboard[0] ) {
				strncpy( sc_newPassword , m_sc_StrKeyboard, PNLD_ServiceDecryptPasswordPasswordLen );
				us_dispErrMessage = s_Space1;										// エラーメッセージをクリア.
				uc_nowPageNum = 3;
			} else {
				us_dispErrMessage = s_SSNewPassWordMissteke;						//「入力したﾊﾟｽﾜｰﾄﾞは使用できません」.
				setBuzzerType( PCGE_BuzzerType_InputNg );
			}
			// 入力文字列とカーソル位置を初期化.
			memset( m_sc_StrKeyboard, '\0', sizeof( m_sc_StrKeyboard ) );
			m_c_SlideTextMgr.init_CLCD( m_sc_StrKeyboard, m_sc_KeyboardWidth, m_ss_MaxInputNum, m_pc_DispField, getCharSetForPanel() );
			break;

		case PNLD_ServiceDecryptPasswordP3:											//【再入力パスワード入力】.
			if( 0 == strncmp( sc_newPassword, m_sc_StrKeyboard, PNLD_ServiceDecryptPasswordPasswordLen ) ) {
				if( PNLE_ServiceRemoteFWUpdateSelectServer1 == m_e_SelectServer ) {
					PnlComGetFWUpdateSetting()->setClientPasswordForDataExport( sc_newPassword );
				} else {
					PnlComGetFWUpdateSetting()->setClientPasswordForDataExport2( sc_newPassword );
				}
				nextGamen = &gp_ServiceRemoteFWUpdateDecryptPasswordSelectServer;
			} else {
				// 入力文字列に新しいパスワードを設定し、新しいパスワード入力に戻る.
				strncpy( m_sc_StrKeyboard , sc_newPassword, PNLD_ServiceDecryptPasswordPasswordLen );
				m_c_SlideTextMgr.init_CLCD( m_sc_StrKeyboard, m_sc_KeyboardWidth, m_ss_MaxInputNum, m_pc_DispField, getCharSetForPanel() );
				uc_nowPageNum = 2;
			}
			break;

		default:
			break;
	}
	setupGamen();
}

//関数------------------------------------------------------------------------------------------------------------------.
//概要    ：テンキー押下処理.
//備考    ：.
//戻値    ：なし.
//作成者  ：OPS1佐藤.
//==================================================================================================.
// 概要     : 90B95110/90B95120/90B95130 本体自動更新設定／複合化パスワード : テンキー押下処理.
