// ===============================================================================================.
/**
 * @name	PServiceUsbFirmwareUpdatePasswordInput::procOk().
 * @brief	OKキー押下.
 * @param	uchar uc_Option	オプション値.
 * @author	2017/12/11 SCD2-motohashi サービスモードへのFW更新追加.
 */
// 変更履歴 :2019/10/30 Sky大嶋 [セキュリティ技術v5][RQ824] パスワード規約拡張 API変更.
// ===============================================================================================.
void PServiceUsbFirmwareUpdatePasswordInput::procOk( uchar uc_Option )
{
	if( TYPE_PasswordCheckResult_OK != m_e_PasswordCheckResult ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}

	APIC_SystemSetting* pc_SystemSetting = PnlComGetSystemSetting();
	if( NULL == pc_SystemSetting ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, 3, "Assert Failed!" );
		return; 
	}

	getKeyboardData( m_sc_InputPassword );
//	m_e_PasswordCheckResult = pc_SystemSetting->checkFWUpdatePassword( m_sc_InputPassword );
	m_e_PasswordCheckResult = pc_SystemSetting->verifyFwUpdatePwd( m_sc_InputPassword );
	if( TYPE_PasswordCheckResult_OK == m_e_PasswordCheckResult ) {
		nextGamen = &gp_ServiceUsbFwUpdatePrepare;
	} else {
		// 文字列の初期化.
		memset( m_sc_StrKeyboard, 0, sizeof(m_sc_StrKeyboard) );
		Kbd_ServiceInputKeybord.GetCursor(m_pc_DispField);

		// 入力中状態に変更.
		m_c_SlideTextMgr.setStatus( False );

		// スライド文字列管理クラスの初期化.
		m_c_SlideTextMgr.init_CLCD( m_sc_StrKeyboard, m_sc_KeyboardWidth, m_ss_MaxInputNum, m_pc_DispField, getCharSetForPanel() );

		setupGamen();
	}
}

