// ===============================================================================================.
/**
 * @name	PServiceUsbFirmwareUpdatePasswordInput::procGoToPage().
 * @brief	画面遷移処理.
 * @param	uchar uc_Option	オプション値.
 * @author	2017/12/11 SCD2-motohashi サービスモードへのFW更新追加.
 */
// ===============================================================================================.
void PServiceUsbFirmwareUpdatePasswordInput::procGoToPage( uchar uc_Option )
{
	if( TYPE_PasswordCheckResult_OK != m_e_PasswordCheckResult ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}

	switch( uc_Option ) {
	case 60:		// キャンセルキー. 
		nextGamen = &gp_ServiceUsbFwUpdate;
		break;
	default:
		break;
	}
}

// ===============================================================================================.
/**
 * @name	PServiceUsbFirmwareUpdatePasswordInput::procSecond().
 * @brief	1秒タイマ.
 * @param	uchar uc_Option	オプション値.
 * @author	2017/12/11 SCD2-motohashi サービスモードへのFW更新追加.
 */
// ===============================================================================================.
void PServiceUsbFirmwareUpdatePasswordInput::procSecond( uchar uc_Option )
{
	PServiceNoFunctionCodeCom::procSecond( uc_Option );

	static uchar uc_TimerCount = 0;
	if( TYPE_PasswordCheckResult_OK != m_e_PasswordCheckResult ) {
		uc_TimerCount++;
		if( 5 < uc_TimerCount ) {
			m_e_PasswordCheckResult = TYPE_PasswordCheckResult_OK;
			uc_TimerCount = 0;
		}
	}
}

// ===============================================================================================.
/**
 * @name	PServiceUsbFirmwareUpdatePasswordInput::setKeyboardData().
 * @brief	キーボード設定処理.
 * @param	char*	psc_InputData	キーボード初期値.
 * @param	short	ss_InputMax		最大入力バイト数.
 * @param	char	sc_InputWidth	最大入力幅.
 * @author	2017/12/11 SCD2-motohashi サービスモードへのFW更新追加.
 */
// ===============================================================================================.
void PServiceUsbFirmwareUpdatePasswordInput::setKeyboardData(char* psc_InputData, short ss_InputMax, char sc_InputWidth)
{
	if( NULL == psc_InputData ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, 3, "Assert Failed!" );
		return;
	}
	memset( m_sc_StrKeyboard, 0 ,sizeof( m_sc_StrKeyboard ));
	strncpy( m_sc_StrKeyboard, psc_InputData, ( sizeof( m_sc_StrKeyboard ) - 1 ) );
	m_ss_MaxInputNum = ss_InputMax;
	m_sc_KeyboardWidth= sc_InputWidth;
}

// ===============================================================================================.
/**
 * @name	PServiceUsbFirmwareUpdatePasswordInput::getKeyboardData().
 * @brief	キーボード設定処理.
 * @param	char*	psc_OutputData	文字列格納先バッファ.
 * @author	2017/12/11 SCD2-motohashi サービスモードへのFW更新追加.
 */
// ===============================================================================================.
char* PServiceUsbFirmwareUpdatePasswordInput::getKeyboardData(char* psc_OutputData)
{
	if( NULL == psc_OutputData ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, 3, "Assert Failed!" );
		return psc_OutputData;
	}
	strcpy( psc_OutputData, m_sc_StrKeyboard );

	return psc_OutputData;
}

