{
}

// ===============================================================================================.
/**
 * @name	PServiceUsbFirmwareUpdatePrepare::startGamen().
 * @brief	画面開始.
 * @param	なし.
 * @author	2017/12/11 SCD2-motohashi サービスモードへのFW更新追加.
 */
// ===============================================================================================.
void PServiceUsbFirmwareUpdatePrepare::startGamen()
{
	PServiceNoFunctionCodeCom::startGamen();

	APIC_InternetISW*	pc_InternetISW = APIC_InternetISW::newInstance();
	if( NULL != pc_InternetISW ) {
		if( False == pc_InternetISW->req_FwUpdateFromUsb( ans_FirmwareUpdateFromUsbCallback ) ) {
			CallBackIndi( TYPE_PNL_CallBack_FwUpdateFailed );
			m_bl_UpdateExec = False;
		} else {
			m_bl_UpdateExec = True;
		}
	} else {
		m_bl_UpdateExec = False;
	}

	m_uc_InstallingAnime = 0;
}

// ===============================================================================================.
/**
 * @name	PServiceUsbFirmwareUpdatePrepare::setupGamen().
 * @brief	画面更新.
 * @param	short	ss_Option	オプション値.
 * @author	2017/12/11 SCD2-motohashi サービスモードへのFW更新追加.
 */
// ===============================================================================================.
void PServiceUsbFirmwareUpdatePrepare::setupGamen( short ss_Option )
{
	TEXT_ID us_MsgTextId = 0;

	if( False != m_bl_UpdateExec ) {
		TEXT_ID us_AnimeTextId = ( 0 == m_uc_InstallingAnime )? s_EXPSlash: s_EXPBackslash;
		if( ++m_uc_InstallingAnime > 1 ) { m_uc_InstallingAnime = 0; }
		us_MsgTextId = s_pMSGServiceUsbFwUpdatePrepare_W384H032I;

		Txt_ServiceUsbFwUpdatePrepareUpdateAnime.showEnable( True );
		Txt_ServiceUsbFwUpdatePrepareUpdateAnime.changeText( us_AnimeTextId );
	} else {
		us_MsgTextId = s_pMSGServiceUsbFwUpdateFailed_W384H032I;

		Txt_ServiceUsbFwUpdatePrepareUpdateAnime.showEnable( False );
	}

	Txt_ServiceUsbFwUpdatePrepareMsg.changeText( us_MsgTextId );

	PServiceNoFunctionCodeCom::setupGamen();
}

