// 概要     :サービスモード・拡張ネットワーク設定・設定結果通知クラス : 設定結果結果通知.
void PServiceMioSettingNotifier::notifyMioSettingResult( TYPE_MioSettingResult e_Result,TYPE_MioSettingObjId e_ObjId, APIC_MioSettingNotifier* pc_MioSettingNotifier )
{
	switch( e_ObjId ) {
		case TYPE_MioSettingObjId_IpAddressEx:	// < TCP/IP（拡張）IPv4アドレス設定.
// comment 2015/10/01 OPS1-Sky森山 [MinervaSBK][CQ519158].
		case TYPE_MioSettingObjId_IpAddress:	// < TCP/IP(構成I/Fが「無線のみ」である場合は、メイン側に設定される為、こちらが通知される.
			m_e_MioSettingResult = e_Result;
			m_bl_Waiting = False;
			break;
		default:
			break;
	}
}
PServiceMioSettingNotifier g_c_ServiceMioSettingNotifier;	// サービスモード・拡張ネットワーク設定・設定結果通知オブザーバー.
//================================================================================================.
// 概要		: PServiceNetworkExKeyboardCom : 拡張ネットワークキーボード入力共通クラス.
//================================================================================================.
PServiceNetworkExKeyboardCom::PServiceNetworkExKeyboardCom( PDisplayParts** partsTable, short partsNumber, Bool isNoWarning )
	: PServiceNetWorkEXCom( partsTable, partsNumber, isNoWarning )
{
	// 初期化.
	m_pc_DispField = NULL;
	memset( m_sc_StrKeyboard, 0, sizeof( m_sc_StrKeyboard ) );
	m_sc_KeyboardWidth = 1;
	m_ss_MaxInputNum = 1;
	m_b_Password = False;
	m_b_ShowPass = False;
	m_e_CharSet = EP_CharSet_Non;
	m_ss_Tx = 192;
	m_ss_Gy = 168;
}
//================================================================================================.
// 概要		: PServiceNetworkExKeyboardCom : 拡張ネットワークキーボード入力共通クラス : 画面開始処理.
//================================================================================================.
void PServiceNetworkExKeyboardCom::startGamen()
{
	PBasicMessageProc::startGamen();

	// キーボード表示.
	Kbd_ServiceInputKeybord.setChangeEnlKeybord( PLBD_Enl_KBD_Initial );	// 変換候補最大数の設定.
	Kbd_ServiceInputKeybord = PLBC_ConvertKeybord( PLBD_KBT_ASCII_S, m_ss_Tx, m_ss_Gy, True, True );

	// カーソルクラスへパーツポインタを渡す.
	Kbd_ServiceInputKeybord.GetCursor( m_pc_DispField );
	startGamenKeybordService9E();

	// パス入力選択クラス.
	m_c_SlideTextMgr.setSelectProc( m_b_Password );
	m_c_SlideTextMgr.initStatus( m_sc_StrKeyboard );

	// スライド文字列管理クラスの初期化.
	m_c_SlideTextMgr.init_CLCD( m_sc_StrKeyboard, m_sc_KeyboardWidth, m_ss_MaxInputNum, m_pc_DispField, m_e_CharSet );

	// 変換候補グループの表示位置を調整.
	Grp_Convert.shiftPosition( 0, 8, False );
	Bak_ConvertPageGround.shiftPosition( 0, 8, False );
	Btx_ConvertPageNumber.shiftPosition( 0, 8, False );
}
//================================================================================================.
// 概要		: PServiceNetworkExKeyboardCom : 拡張ネットワークキーボード入力共通クラス : 画面更新処理.
//================================================================================================.
void PServiceNetworkExKeyboardCom::setupGamen( short option )
{
	// 親クラスの画面セットアップをコールする.
	PServiceNetWorkEXCom::setupGamen( option );

	// 変換出来るようのキーボードセットアップ.
	PServiceNoFunctionCodeCom::setupGamenKeybordService9C();

	// キーボードの表示.
	Kbd_ServiceInputKeybord.showKeybord();

	// キーボードの種類を取得する.
	KeybordType ec_KeybordType = Kbd_ServiceInputKeybord.getKeybordType();

	// 日本語入力の場合は未確定文字列表示用にスライド処理を行う.
	m_c_SlideTextMgr.PreStringSlideControl( m_sc_StrKeyboard, ec_KeybordType );
	m_c_SlideTextMgr.drawStr( m_sc_StrKeyboard );

	m_c_SlideTextMgr.setInsertCharLenCheck( TYPE_InsertCharLenStrUTF8 );
}
//================================================================================================.
// 概要		: PServiceNetworkExKeyboardCom : 拡張ネットワークキーボード入力共通クラス : 画面終了処理.
//================================================================================================.
void PServiceNetworkExKeyboardCom::endGamen()
{
	// 変換候補グループの表示位置を元に戻す.
	Grp_Convert.shiftPosition( 0, -8, False );
	Bak_ConvertPageGround.shiftPosition( 0, -8, False );
	Btx_ConvertPageNumber.shiftPosition( 0, -8, False );

	PBasicMessageProc::endGamen();
}
//================================================================================================.
// 概要		: PServiceNetworkExKeyboardCom : 拡張ネットワークキーボード入力共通クラス : テンキー押下処理.
//================================================================================================.
void PServiceNetworkExKeyboardCom::proc10Key( uchar option )
{
	// 10個表示を止める.
	if( ( True == m_b_Password ) && ( True == m_b_ShowPass ) ) {
		m_b_ShowPass = False;
		m_c_SlideTextMgr.setStatus( False );
		if( 0 != strlen( m_sc_StrKeyboard ) )
		{ procClear( 0 ); }
	}

	char _sc_Num[ 3 ];
	memset( _sc_Num, 0, sizeof( _sc_Num ) );
	Kbd_ServiceInputKeybord.proc10Key( &option );

	// 最大入力長まで行っているならば入力しない.
	if( m_ss_MaxInputNum <= ( ushort )strlen( m_sc_StrKeyboard ) ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );					// ブザー音セット.
		return;
	}

	// 入力されたのが0-9キーの時のみ処理を受け付ける.
	if( 9 >= option ) {
// Comment 2015/10/21【HCLT-Meera】【CQ519679】【ID: 28746, 28747】ABV.GENERAL.
//		sprintf( ( char* )_sc_Num, "%d", option );
        snprintf( ( char* )_sc_Num, sizeof( _sc_Num ), "%d", option );
		m_c_SlideTextMgr.insertStr( m_sc_StrKeyboard, ( char* )_sc_Num );
	}

	// 画面セットアップ.
	setupGamen();
}
//================================================================================================.
// 概要		: PServiceNetworkExKeyboardCom : 拡張ネットワークキーボード入力共通クラス : クリアー押下処理.
//================================================================================================.
void PServiceNetworkExKeyboardCom::procClear( uchar option )
{
	// 未確定文字が無い場合.
	if( '\0' == Kbd_ServiceInputKeybord.c_PreString[0] ) {
		if( ( True == m_b_Password ) && ( True == m_b_ShowPass ) ) {
			m_b_ShowPass = False;
			m_c_SlideTextMgr.setStatus( False );
		}

		if( 0 == strlen( m_sc_StrKeyboard ) ) {
			MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
		}

		// 文字列の初期化.
		memset( m_sc_StrKeyboard, 0, sizeof( m_sc_StrKeyboard ) );
		Kbd_ServiceInputKeybord.GetCursor( m_pc_DispField );

		// 入力中状態に変更.
		m_c_SlideTextMgr.setStatus( False );

		// スライド文字列管理クラスの初期化.
		m_c_SlideTextMgr.init_CLCD( m_sc_StrKeyboard, m_sc_KeyboardWidth, m_ss_MaxInputNum, m_pc_DispField, getCharSetForPanel() );
	} else {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
	}

	// 画面セットアップ.
	setupGamen();
}

//================================================================================================.
// 概要		: PServiceNetworkExKeyboardCom : 拡張ネットワークキーボード入力共通クラス : キーボード入力処理.
//================================================================================================.
void PServiceNetworkExKeyboardCom::procKeyBoard( uchar option )
{
	if( ( True == m_b_Password ) && ( True == m_b_ShowPass ) ) {
		m_b_ShowPass = False;
		m_c_SlideTextMgr.setStatus( False );
		if( 0 != strlen( m_sc_StrKeyboard ) )
		{ procClear( 0 ); }
	}

	// カーソルキー一処理.
	Kbd_ServiceInputKeybord.procCursorPosition( ( char* )&m_c_SlideTextMgr, m_sc_StrKeyboard, option, True );

	// 画面セットアップ.
	setupGamen();
}
//================================================================================================.
// 概要		: PServiceNetworkExKeyboardCom : 拡張ネットワークキーボード入力共通クラス : ボタン押下処理.
//================================================================================================.
void PServiceNetworkExKeyboardCom::procButtonOn( uchar option )
{
	// パスワードの初期表示の場合はクリアしてオプションを表示する。.
	if( ( True == m_b_Password ) && ( True == m_b_ShowPass ) ) {
		// 「＊」10個表示を止める。.
		m_b_ShowPass = False;

		// 入力中状態に変更.
		m_c_SlideTextMgr.setStatus( False );
		procClear( 0 );
	}

	procButtonOnKeybordService( option );
	char sc_KeyCode[ PLBD_KBD_BufMax ];
	memset( sc_KeyCode,0, sizeof( sc_KeyCode ) );

	// 無変換または、変換確定の場合、確定文字列を挿入.
	if( True == Kbd_ServiceInputKeybord.setKeybordDecideStr( option, sc_KeyCode ) ) {
		m_c_SlideTextMgr.insertStr( m_sc_StrKeyboard, sc_KeyCode, Kbd_ServiceInputKeybord.getConvCharSetNativeToUniCode() );
	}

	// 画面セットアップ.
	setupGamen();
}
//================================================================================================.
// 概要		: PServiceNetworkExKeyboardCom : 拡張ネットワークキーボード入力共通クラス : 表示領域にデータをセット.
//================================================================================================.
void PServiceNetworkExKeyboardCom::setKeyboardData( const char* psc_InputData, short ss_InputMax, char sc_InputWidth )
{
// Comment 2015/11/02 【ZeusS_ZX0】【HCL_Vasu】【制御構成変更_No.76-1】Adding Error Code macro.
//	if( NULL == psc_InputData ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); return; }
	if( NULL == psc_InputData ) {
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//		if (NULL !=pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x1900650100E51801 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}
	strncpy( m_sc_StrKeyboard, psc_InputData, sizeof( m_sc_StrKeyboard )-1 );
	m_sc_StrKeyboard[sizeof( m_sc_StrKeyboard )-1]='\0';
	m_ss_MaxInputNum = ss_InputMax;
	m_sc_KeyboardWidth= sc_InputWidth;
}
