//================================================================================================.
void PServiceNetWorkEXWepKeyHexInputRetry::startGamen()
{
	// 親クラスを呼ぶ.
	PServiceNetWorkEXHexInputCom::startGamen();

	// 16進数10桁
	if( TYPE_WEPKeyType_Hex10 == m_st_WEPKeyData.e_WEPKeyType ) {
		m_uc_MaxWepKeyHexLen = PNLD_NetWorkEXWepKeyHexMaxLen10;
	}
	// 16進数26桁
	else {
		m_uc_MaxWepKeyHexLen = PNLD_NetWorkEXWepKeyHexMaxLen26;
	}
	memset( m_uc_WepKeyHexRetry, '\0', sizeof( m_uc_WepKeyHexRetry ) );
	m_pc_DispField = &Btx_NetWorkEx_HexInput;
	// カーソルクラスへパーツポインタを渡す.
	Kbd_ServiceInputWepKey.GetCursor( m_pc_DispField );
	// パス入力選択クラス.
	m_c_SlideTextMgr.setSelectProc( True );
	m_c_SlideTextMgr.initStatus( ( char* )m_uc_WepKeyHexRetry );

	// スライド文字列管理クラスの初期化.
	m_c_SlideTextMgr.init_CLCD( ( char* )m_uc_WepKeyHexRetry, PNLD_HexInputComMaxRange, m_uc_MaxWepKeyHexLen, m_pc_DispField, EP_CharSet_USASCII );

}
//================================================================================================.
// 概要		: PServiceNetWorkEXWepKeyHexInputRetry : ネットワーク設定／拡張ﾈｯﾄﾜｰｸ設定／WEPキー : 画面開始処理.
//================================================================================================.
void PServiceNetWorkEXWepKeyHexInputRetry::setupGamen( short option )
{
	switch( m_uc_EditTargetWepKey ) {
		case	PNLD_BTNID_WepKey1Edit :
			Txt_TitleWepKeyHex.changeText( s_TTLServiceWEPKey1_2 );
			break;
		case	PNLD_BTNID_WepKey2Edit :
			Txt_TitleWepKeyHex.changeText( s_TTLServiceWEPKey2_2 );
			break;
		case	PNLD_BTNID_WepKey3Edit :
			Txt_TitleWepKeyHex.changeText( s_TTLServiceWEPKey3_2 );
			break;
		case	PNLD_BTNID_WepKey4Edit :
			Txt_TitleWepKeyHex.changeText( s_TTLServiceWEPKey4_2 );
			break;
		default:
			break;
	}
	PServiceNetWorkEXHexInputCom::setupGamen( option );
	m_c_SlideTextMgr.PreStringSlideControl( ( char* )m_uc_WepKeyHexRetry, PLBD_KBT_ASCII_L );
	m_c_SlideTextMgr.drawStr( ( char* )m_uc_WepKeyHexRetry );

	m_c_SlideTextMgr.setInsertCharLenCheck( TYPE_InsertCharLenStrUTF8 );
}
//================================================================================================.
// 概要		: PServiceNetWorkEXWepKeyHexInputRetry : ネットワーク設定／拡張ﾈｯﾄﾜｰｸ設定／WEPキー : ボタン押下処理.
//================================================================================================.
void PServiceNetWorkEXWepKeyHexInputRetry::procButtonOn( uchar option )
{
	char _sc_Num[ 2 ];
	memset( _sc_Num, '\0', sizeof( _sc_Num ) );
	// 親クラスを呼ぶ.
	PServiceNetWorkEXHexInputCom::procButtonOn( option );
	switch( option ) {
		case PNLD_BTNID_NetWorkEx_HexAKey	:
		case PNLD_BTNID_NetWorkEx_HexBKey	:
		case PNLD_BTNID_NetWorkEx_HexCKey	:
		case PNLD_BTNID_NetWorkEx_HexDKey	:
		case PNLD_BTNID_NetWorkEx_HexEKey	:
		case PNLD_BTNID_NetWorkEx_HexFKey	:
			// 指定桁以上の入力は受け付けない.
			_sc_Num[0] = static_cast<char>( 'a' + ( option - PNLD_BTNID_NetWorkEx_HexAKey ) );
			m_c_SlideTextMgr.insertStr( ( char* )m_uc_WepKeyHexRetry, _sc_Num );
			break;
		case PNLD_BTNID_NetWorkEx_HexLeft	:
			Kbd_ServiceInputWepKey.procCursorPosition( ( char* )&m_c_SlideTextMgr, ( char* )m_uc_WepKeyHexRetry, 149, True );
			break;
		case PNLD_BTNID_NetWorkEx_HexRight	:
			Kbd_ServiceInputWepKey.procCursorPosition( ( char* )&m_c_SlideTextMgr, ( char* )m_uc_WepKeyHexRetry, 150, True );
			break;
		default:
			break;
	}
	setupGamen();
}
