// 概要		: PServiceNetWorkEXWepKeyHexInputRetry : ネットワーク設定／拡張ﾈｯﾄﾜｰｸ設定／WEPキー : クリアキー.
//================================================================================================.
void PServiceNetWorkEXWepKeyHexInputRetry::procClear( uchar option )
{
	if( 0 == strlen( ( char* )m_uc_WepKeyHexRetry ) ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}
	// 文字列の初期化.
	memset( m_uc_WepKeyHexRetry, '\0', sizeof( m_uc_WepKeyHexRetry ) );
	Kbd_ServiceInputWepKey.GetCursor( m_pc_DispField );
	// 入力中状態に変更.
	m_c_SlideTextMgr.setStatus( False );
	// スライド文字列管理クラスの初期化.
	m_c_SlideTextMgr.init_CLCD( ( char* )m_uc_WepKeyHexRetry, PNLD_HexInputComMaxRange, m_uc_MaxWepKeyHexLen, m_pc_DispField, EP_CharSet_USASCII );
}
//================================================================================================.
// 概要		: PServiceNetWorkEXWepKeyHexInputRetry : ネットワーク設定／拡張ﾈｯﾄﾜｰｸ設定／WEPキー : OKキー.
//================================================================================================.
void PServiceNetWorkEXWepKeyHexInputRetry::procOk( uchar option )
{
	if( m_uc_MaxWepKeyHexLen != strlen( ( char* )m_uc_WepKeyHexRetry ) ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}
	// 新しい値と再入力値を比較
	if( True == PServiceNetWorkEXHexInputCom::CheckInput() ) {
		switch( m_uc_EditTargetWepKey ) {
			case	PNLD_BTNID_WepKey1Edit :
				memset( m_st_WEPKeyData.uc_WEPKey1, '\0' , sizeof( m_st_WEPKeyData.uc_WEPKey1 ) );
				strncpy( ( char* )m_st_WEPKeyData.uc_WEPKey1, ( char* )m_uc_WepKeyHexRetry, sizeof( m_st_WEPKeyData.uc_WEPKey1 ) -1 );
				break;
			case	PNLD_BTNID_WepKey2Edit :
				memset( m_st_WEPKeyData.uc_WEPKey2, '\0' , sizeof( m_st_WEPKeyData.uc_WEPKey2 ) );
				strncpy( ( char* )m_st_WEPKeyData.uc_WEPKey2, ( char* )m_uc_WepKeyHexRetry, sizeof( m_st_WEPKeyData.uc_WEPKey2 ) - 1 );
				break;
			case	PNLD_BTNID_WepKey3Edit :
				memset( m_st_WEPKeyData.uc_WEPKey3, '\0' , sizeof( m_st_WEPKeyData.uc_WEPKey3 ) );
				strncpy( ( char* )m_st_WEPKeyData.uc_WEPKey3, ( char* )m_uc_WepKeyHexRetry, sizeof( m_st_WEPKeyData.uc_WEPKey3 ) - 1 );
				break;
			case	PNLD_BTNID_WepKey4Edit :
				memset( m_st_WEPKeyData.uc_WEPKey4, '\0' , sizeof( m_st_WEPKeyData.uc_WEPKey4 ) );
				strncpy( ( char* )m_st_WEPKeyData.uc_WEPKey4, ( char* )m_uc_WepKeyHexRetry, sizeof( m_st_WEPKeyData.uc_WEPKey4 ) - 1 );
				break;
			default:
				break;
		}
		nextGamen = &gp_ServiceNetWorkEXWepKeySetting;
	}
	else {
		// 新しい値と再入力値が一致しない場合
		nextGamen = &gp_ServiceNetWorkEXWepKeyHexInputNew;
	}
}
//================================================================================================.
// 概要		: PServiceNetWorkEXWepKeyHexInputRetry : ネットワーク設定／拡張ﾈｯﾄﾜｰｸ設定／WEPキー : ｷｬﾝｾﾙキー.
//================================================================================================.
void PServiceNetWorkEXWepKeyHexInputRetry::procCancel( uchar option )
{
	// Wepキーの設定画面に遷移する
	nextGamen = &gp_ServiceNetWorkEXWepKeySetting;
}


//============================================================================================.
//
// PServiceNetWorkEXWepKeyASCIIInpuCom : 93B316XX 拡張ネットワーク設定／パスフレーズASCII入力 共通 .
//
//============================================================================================.
uchar						PServiceNetWorkEXWepKeyASCIIInpuCom::m_uc_WEPKeyChangeTemp[ TYPD_WEPKeyMaxLen + 1 ] ;	// WEPキー変更時の再確認用バッファ .


//================================================================================================.
// 概要		: 編集対象となっているWepキーNoを取得 0～ .
//================================================================================================.
uchar	PServiceNetWorkEXWepKeyASCIIInpuCom::getTargetNo()
{
	uchar uc_Result = 0 ;
	switch( m_uc_EditTargetWepKey ) {
		case PNLD_BTNID_WepKey1Edit :	uc_Result = 0 ;	break ;
		case PNLD_BTNID_WepKey2Edit :	uc_Result = 1 ;	break ;
		case PNLD_BTNID_WepKey3Edit :	uc_Result = 2 ;	break ;
		case PNLD_BTNID_WepKey4Edit :	uc_Result = 3 ;	break ;
		default :										break ;
	}
	return uc_Result ;
}

//================================================================================================.
// 概要		: 編集対象となっているWepキーの設定値を取得 .
//================================================================================================.
Bool	PServiceNetWorkEXWepKeyASCIIInpuCom::getTargetWepKeyData( uchar* p_Buffer, short ss_BufferSize )
{
	Bool	bl_Result = True ;

	// 対象一覧 .
	uchar* p_uc_TargetList[] = {
		m_st_WEPKeyData.uc_WEPKey1,
		m_st_WEPKeyData.uc_WEPKey2,
		m_st_WEPKeyData.uc_WEPKey3,
		m_st_WEPKeyData.uc_WEPKey4,
	} ;

	uchar uc_Idx = getTargetNo() ;	// 対象No取得 .

	if( ( NULL != p_Buffer ) && ( ss_BufferSize > 0 ) ) {
		memset( p_Buffer, '\0', ss_BufferSize ) ;
		memcpy( p_Buffer, p_uc_TargetList[uc_Idx], ss_BufferSize - 1 ) ;
	} else {
		bl_Result = False ;
	}

	return bl_Result ;
}

//================================================================================================.
// 概要		: 編集対象となっているWepキーの設定値を設定 .
//================================================================================================.
Bool	PServiceNetWorkEXWepKeyASCIIInpuCom::setTargetWepKeyData( uchar* p_Buffer )
{
	Bool	Result = True ;

	// 対象一覧 .
	uchar* p_uc_TargetList[] = {
		m_st_WEPKeyData.uc_WEPKey1,
		m_st_WEPKeyData.uc_WEPKey2,
		m_st_WEPKeyData.uc_WEPKey3,
		m_st_WEPKeyData.uc_WEPKey4,
	} ;

	// 対象一覧 .
	short ss_TargetSizeList[] = {
		sizeof( m_st_WEPKeyData.uc_WEPKey1 ),
		sizeof( m_st_WEPKeyData.uc_WEPKey2 ),
		sizeof( m_st_WEPKeyData.uc_WEPKey3 ),
		sizeof( m_st_WEPKeyData.uc_WEPKey4 ),
	} ;

	uchar uc_Idx = getTargetNo() ;	// 対象No取得 .

	if( ( NULL != p_Buffer ) && ( ss_TargetSizeList[ uc_Idx ] > 0 ) ) {
		memset( p_uc_TargetList[ uc_Idx ], '\0',		ss_TargetSizeList[ uc_Idx ] ) ;
		memcpy( p_uc_TargetList[ uc_Idx ], p_Buffer,	ss_TargetSizeList[ uc_Idx ] - 1 ) ;
	} else {
		Result = False ;
	}

	return Result ;
}

//================================================================================================.
// 概要		: 入力可能最大文字数の取得 .
//================================================================================================.
short	PServiceNetWorkEXWepKeyASCIIInpuCom::getInputMaxLen()
{
	short	ss_Result = 0 ;

	switch( m_st_WEPKeyData.e_WEPKeyType ) {
		case TYPE_WEPKeyType_Ascii5:	ss_Result = PNLD_NetWorkEXWepKeyASCIIMaxLen05 ;	break ;
		case TYPE_WEPKeyType_Ascii13:	ss_Result = PNLD_NetWorkEXWepKeyASCIIMaxLen13 ;	break ;
		default:			break ;
	}

	return ss_Result ;
}

//================================================================================================.
// 概要		: タイトルの取得 .
//================================================================================================.
ushort	PServiceNetWorkEXWepKeyASCIIInpuCom::getTitle()
{
	ushort us_Result = s_TTLServiceWEPKey1_2 ;

	switch( getTargetNo() ) {
		case 0 : us_Result = s_TTLServiceWEPKey1_2 ;	break ;
		case 1 : us_Result = s_TTLServiceWEPKey2_2 ;	break ;
		case 2 : us_Result = s_TTLServiceWEPKey3_2 ;	break ;
		case 3 : us_Result = s_TTLServiceWEPKey4_2 ;	break ;
	}

	return us_Result ;
}

