void PServiceNetWorkEXWepKeyASCIIInputNew::startGamen()
{

	memset( m_uc_WEPKeyChangeTemp, '\0', sizeof( m_uc_WEPKeyChangeTemp ) ) ;	// Tempをクリア .
	memset( m_sc_StrKeyboard, '\0', sizeof( m_sc_StrKeyboard ) ) ;				// '\0'で初期化 .

	// 表示領域に文字列をセット.
	setKeyboardData( m_sc_StrKeyboard, getInputMaxLen() , PNLD_ServiceNetworkExKeyboardComInputViewLen ) ;

	// パスワード入力 .
	m_b_Password = True ;

	// 事前入力チェック .
	if( strlen( m_sc_StrKeyboard ) > 0 ) {
		m_b_ShowPass = True ;
	} else {
		m_b_ShowPass = False ;
	}

	// 親クラスを呼ぶ.
	PServiceNetWorkEXWepKeyASCIIInpuCom::startGamen();
}
