void PServiceNetWorkEXPassPhraseHexInputRetry::procOk( uchar option )
{
	if( m_uc_MaxPassPhraseHexLen != strlen( ( char* )m_uc_WepKeyHexRetry ) ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}
	// 新しい値と再入力値を比較
	if( True == PServiceNetWorkEXHexInputCom::CheckInput() ) {
		memset( m_uc_PassPhrase, '\0' , sizeof( m_uc_PassPhrase ) );
		strncpy( ( char* )m_uc_PassPhrase, ( char* )m_uc_WepKeyHexRetry, sizeof( m_uc_PassPhrase ) - 1 );
		nextGamen = &gp_ServiceNetWorkEXPassPhraseSetting;
	}
	else {
		// 新しい値と再入力値が一致しない場合
		nextGamen = &gp_ServiceNetWorkEXPassPhraseHexInputNew;
	}
}
