Bool						PServiceNetWorkEXCom::m_bl_NetWorkEXGet;	// 拡張ネットワーク設定取得済みフラグ.
Bool						PServiceNetWorkEXCom::m_bl_Adapter;			// 装着／非装着.
TYPE_ExNetworkAdapter		PServiceNetWorkEXCom::m_e_Adapter;			// アダプタ設定.
TYPE_NetworkIFMode			PServiceNetWorkEXCom::m_e_NetworkIFMode = TYPE_NetworkIFMode_SingleEthernet;		// ネットワークインターフェース構成.
TYPE_NetworkIFMode			PServiceNetWorkEXCom::m_e_NetworkIFModeSys = TYPE_NetworkIFMode_SingleEthernet;		// ネットワークインターフェース構成(システム側の設定値).
TYPE_ExNetworkEncryptAlg	PServiceNetWorkEXCom::m_e_Algorithm;			// 認証・暗号化アルゴリズム.
uchar						PServiceNetWorkEXCom::m_uc_SSID[32+1];		// SSID.
TYPS_WEPKeyData				PServiceNetWorkEXCom::m_st_WEPKeyData;		// WEPキー情報.
TYPE_PassphraseType			PServiceNetWorkEXCom::m_e_PassPhraseType;	// パスフレーズ種別.
uchar						PServiceNetWorkEXCom::m_uc_PassPhrase[PNLD_NetWorkEXPassPhraseHexMaxLen+1];				// パスフレーズ.
Bool						PServiceNetWorkEXCom::m_bl_PassPhraseAutoUpdate;			// パスフレーズ自動更新 する／しない .
ushort						PServiceNetWorkEXCom::m_us_PassPhraseAutoUpdateInterval;	// パスフレーズ自動更新間隔 0:自動更新しない .
Bool						PServiceNetWorkEXCom::m_bl_HzUse;								// 20/40 MHz 共用設定 .
uchar						PServiceNetWorkEXCom::m_uc_EditTargetWepKey ;							// 編集対象のWEPキー .
uchar						PServiceNetWorkEXCom::m_uc_channel;																	// チャンネル設定.
Bool						PServiceNetWorkEXCom::m_bl_ANYConnection;																// ANY接続.
uchar						PServiceNetWorkEXCom::m_uc_MACAddress[APID_ConnectClientMacAdrCount][APID_ConnectClientMacAdrLength];	// MACアドレス.
Bool						PServiceNetWorkEXCom::m_bl_DHCPServerUseSetting;														// DHCPサーバー設定.
uchar						PServiceNetWorkEXCom::m_uc_IPv4LeaseAddressHead[APID_IPv4AddressLength];								// 先頭アドレス.
uchar						PServiceNetWorkEXCom::m_uc_IPv4LeaseAddressLast[APID_IPv4AddressLength];								// 最終アドレス.
uchar						PServiceNetWorkEXCom::m_uc_IPv4SubnetMask[APID_IPv4AddressLength];									// サブネットマスク.
uint32_t					PServiceNetWorkEXCom::m_ul_LeaseLimit;																// リース期限.
TYPE_IpAddress				PServiceNetWorkEXCom::m_e_ipAddress;																	// IPv4確定方法.
Bool						PServiceNetWorkEXCom::m_bl_DHCPSetting;																// DHCP設定.
uchar						PServiceNetWorkEXCom::m_uc_IPv4IPAddress[APID_IPv4AddressLength];									// IPアドレス.
uchar						PServiceNetWorkEXCom::m_uc_IPv4SubnetMaskEx[APID_IPv4AddressLength];									// サブネットマスク.

//================================================================================================.
// 概要		: PServiceNetWorkEX2ndCardSetting : ネットワーク設定／拡張ﾈｯﾄﾜｰｸ設定 共通 : 画面開始処理.
// 履歴		: .
//================================================================================================.
void PServiceNetWorkEXCom::startGamen()
{
	// 親クラスを呼ぶ.
	PServiceNoFunctionCodeCom::startGamen();
	setTurnGamenNow();
	m_bl_Waiting = False;	// 設定待ちをOFFにする.// CQ373070対応.
	// 初回遷移時のみ拡張ネットワーク設定の情報を取得する.
	if( False == m_bl_NetWorkEXGet ) {
		// 拡張ネットワークアダプタ装着状態を取得する.
		APIC_SystemInfo* pc_SystemInfo = APIC_SystemInfo::newInstance();	// システム情報のインスタンス生成.
		m_e_Adapter		= pc_SystemInfo->getExNetworkAdapter();

		// 動作モードを取得する.
		APIC_ExNetworkSetting* pc_ExNetworkSetting = APIC_ExNetworkSetting::newInstance();	// 拡張ネットワーク設定のインスタンス生成.
		if( NULL == pc_ExNetworkSetting ) {
// Comment 2015/11/02 【ZeusS_ZX0】【HCL_Vasu】【制御構成変更_No.76-1】Adding Error Code macro.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//			LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//			if (NULL !=pc_BFW_System){
//				pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x1900650100E51A01 );
//			}
			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
			return;
		}
		m_e_NetworkIFMode		= pc_ExNetworkSetting->getNetworkIFMode();	// ネットワークインタフェース構成取得.
		m_e_NetworkIFModeSys	= m_e_NetworkIFMode ;

		if( TYPE_NetworkIFMode_SingleSta == m_e_NetworkIFModeSys
		    || TYPE_NetworkIFMode_DualEthernetSta == m_e_NetworkIFModeSys
		    || TYPE_NetworkIFMode_DualEthernetWolLimited == m_e_NetworkIFModeSys ) {
			// SSIDを取得する.
			pc_ExNetworkSetting->getStaSSID( m_uc_SSID );
			// 認証・暗号化アルゴリズムを取得する.
			m_e_Algorithm	= pc_ExNetworkSetting->getStaEncryptAlg();
			// WEPキー情報を取得する.
			memset( &m_st_WEPKeyData , 0, sizeof( m_st_WEPKeyData ) );
			pc_ExNetworkSetting->getStaWEPKey( &m_st_WEPKeyData );
			// パスフレーズ情報を取得する.
			m_e_PassPhraseType	= pc_ExNetworkSetting->getStaPassphrase( m_uc_PassPhrase );
			// 20/40 MHz 共用設定 .
			m_bl_HzUse = pc_ExNetworkSetting->getSta2040MHzCoexistence();
		} else {
			// SSIDを取得する.
			pc_ExNetworkSetting->getApSSID( m_uc_SSID );
			// 認証・暗号化アルゴリズムを取得する.
			m_e_Algorithm	= pc_ExNetworkSetting->getApEncryptAlg();
			// WEPキー情報を取得する.
			memset( &m_st_WEPKeyData , 0, sizeof( m_st_WEPKeyData ) );
			pc_ExNetworkSetting->getApWEPKey( &m_st_WEPKeyData );
			// パスフレーズ情報を取得する.
			m_e_PassPhraseType	= pc_ExNetworkSetting->getApPassphrase( m_uc_PassPhrase );
			// 20/40 MHz 共用設定 .
			m_bl_HzUse = pc_ExNetworkSetting->getAp2040MHzCoexistence();
		}

		// パスフレーズ更新間隔取得 .
		m_us_PassPhraseAutoUpdateInterval =  pc_ExNetworkSetting->getApPassphraseInterval() ;

		// パスフレーズ更新間隔を元に自動更新 する／しないを初期化 .
		if( 0 == m_us_PassPhraseAutoUpdateInterval ) {
			m_bl_PassPhraseAutoUpdate = False ;
		} else {
			m_bl_PassPhraseAutoUpdate = True ;
		}

		// 20/40 MHz 共用設定 .

		// 拡張ネットワーク設定の情報を取得済みとする.
		m_bl_NetWorkEXGet = True;

		// チャンネル設定.
		m_uc_channel = pc_ExNetworkSetting->getApChannel();

		// ANY接続.
		m_bl_ANYConnection = pc_ExNetworkSetting->getApAnyConnection();

		TYPS_WlanMacAddressFilteringList st_MACAddress;
		pc_ExNetworkSetting->getApAllowMacAddress( &st_MACAddress );
		for( int i = 0; i < APID_ConnectClientMacAdrCount; i++ ) {
			strncpy( ( char* )m_uc_MACAddress[i], ( char* )&st_MACAddress.uc_MacAddressFiltering[i], APID_ConnectClientMacAdrLength - 1 );
			m_uc_MACAddress[i][APID_ConnectClientMacAdrLength - 1] = '\0';
		}

		// DHCPサーバー設定.
		m_bl_DHCPServerUseSetting = pc_ExNetworkSetting->getApEnableDHCP();

		// IPV4リースアドレス.
		pc_ExNetworkSetting->getApLeaseIPv4AddressStart( m_uc_IPv4LeaseAddressHead );
		pc_ExNetworkSetting->getApLeaseIPv4AddressEnd( m_uc_IPv4LeaseAddressLast );

		// サブネットマスク.
		pc_ExNetworkSetting->getApSubnetMask( m_uc_IPv4SubnetMask );

		// リース期限.
		m_ul_LeaseLimit = pc_ExNetworkSetting->getApLeaseTime();

		// IPv4設定.
		m_e_ipAddress = pc_ExNetworkSetting->getIpAddressEx();
		m_bl_DHCPSetting = pc_ExNetworkSetting->getDHCP_OnEx();
		pc_ExNetworkSetting->getIPAddressEx( m_uc_IPv4IPAddress );
		pc_ExNetworkSetting->getSubnetMaskEx( m_uc_IPv4SubnetMaskEx );

	}
}
//================================================================================================.
// 概要		: PServiceNetWorkEX2ndCardSetting : ネットワーク設定／拡張ﾈｯﾄﾜｰｸ設定 共通 : 画面更新処理.
// 履歴		: .
//================================================================================================.
void PServiceNetWorkEXCom::setupGamen( short option )
{
	Bool		bl_isWEP = False;
	Bool		bl_isWPA = False;
	Bool		bl_showModeSetting			= True ;
	Bool		bl_showSSIDSetting			= True ;
	Bool		bl_showAlgorithmSetting		= True ;
	Bool		bl_showServiceNetWorkExUp	= True ;
	Bool		bl_showServiceNetWorkExDown	= True ;
	Bool		bl_showerviceNetWorkExPage	= True ;

	// 親クラスを呼ぶ.
	PServiceNoFunctionCodeCom::setupGamen( option );

	// 認証・暗号化アルゴリズムの選択による表示の更新 .
	switch( m_e_Algorithm ) {
		case	TYPE_ExNetworkEncryptAlg_WEP :
			bl_isWEP	= True;
			break;
		case	TYPE_ExNetworkEncryptAlg_WPA_PSK_TKIP :
		case	TYPE_ExNetworkEncryptAlg_WPA_PSK_AES :
		case	TYPE_ExNetworkEncryptAlg_WPA2_PSK_TKIP :
		case	TYPE_ExNetworkEncryptAlg_WPA2_PSK_AES :
		case	TYPE_ExNetworkEncryptAlg_WPA_PSK_Auto :
			bl_isWPA	= True;
			break;
		case	TYPE_ExNetworkEncryptAlg_None :
		default:
			break;
	}

	// 非装着の場合 .
	if( TYPE_ExNetworkAdapter_Disable == m_e_Adapter ) {
		bl_isWEP 		= False;
		bl_isWPA 		= False;
		bl_showModeSetting			= False ;
		bl_showSSIDSetting			= False ;
		bl_showAlgorithmSetting		= False ;
		bl_showServiceNetWorkExUp	= False ;
		bl_showServiceNetWorkExDown	= False ;
		bl_showerviceNetWorkExPage	= False ;
	}
// comment 2015/02/26 OPS1-Sky延原 [ZeusSBk][RQ-340] 無線LANオプションのIEEE 802.11 acad サポート.
	// UK-215装着時、ネットワークインターフェース構成以外の機能を設定不可とする.
	else {
		APIC_SystemInfo*  pc_SystemInfo = APIC_SystemInfo::newInstance();
		if ( NULL != pc_SystemInfo) {
			TYPE_ExNetworkWLANDeviceType e_DeviceType = pc_SystemInfo->getWLANDeviceType(); // 装着中無線オプション種別取得.
			if(TYPE_ExNetworkWLANDeviceType_UK215 == e_DeviceType) {
				// UK-215装着時、非表示.
				bl_isWEP 					= False;
				bl_isWPA 					= False;
				bl_showSSIDSetting			= False ;
				bl_showAlgorithmSetting		= False ;
				bl_showServiceNetWorkExUp	= False ;
				bl_showServiceNetWorkExDown	= False ;
				bl_showerviceNetWorkExPage	= False ;
			}
			else if (TYPE_ExNetworkWLANDeviceType_UK212 == e_DeviceType) {
				if ( TYPE_NetworkIFMode_DualEthernetAp != m_e_NetworkIFModeSys ) {
					// UK-212装着時、ネットワークインターフェース構成が「有線I/F＋無線I/F(AP)有効化」以外、非表示.
					bl_isWEP					= False ;
					bl_isWPA					= False ;
					bl_showSSIDSetting			= False ;
					bl_showAlgorithmSetting		= False ;
					bl_showServiceNetWorkExUp	= False ;
					bl_showServiceNetWorkExDown	= False ;
					bl_showerviceNetWorkExPage	= False ;
				}
			}
// comment 2018/03/08 【IT6_Eagle】【HCLT_Pavani】【制御構成変更_No.77-1】【WP 1696】 Addition of UK-XXX wireless adapter.
// comment 2018/06/05 【IT6_Eagle】【HCLT_Pavani】【制御構成変更_No.77-1】【WP 1696】 API change for wireless Adapter.
//			else if (TYPE_ExNetworkWLANDeviceType_UKXXX == e_DeviceType) {
			else if (TYPE_ExNetworkWLANDeviceType_UK221 == e_DeviceType) {
					bl_isWEP					= False ;
					bl_isWPA					= False ;
					bl_showSSIDSetting			= False ;
					bl_showAlgorithmSetting		= False ;
					bl_showServiceNetWorkExUp	= False ;
					bl_showServiceNetWorkExDown	= False ;
					bl_showerviceNetWorkExPage	= False ;
			}
			else {
				// 非装着(物理的に)、又は、初期化中
				bl_isWEP 					= False;
				bl_isWPA 					= False;
				bl_showModeSetting			= False ;
				bl_showSSIDSetting			= False ;
				bl_showAlgorithmSetting		= False ;
				bl_showServiceNetWorkExUp	= False ;
				bl_showServiceNetWorkExDown	= False ;
				bl_showerviceNetWorkExPage	= False ;
			}
		}
		else {
			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		}
	}

// comment 2015/02/26 OPS1-Sky延原 [ZeusSBk][RQ-340] 無線LANオプションのIEEE 802.11 acad サポート.
	// UK-215装着時、ネットワークインターフェース構成以外の機能を設定不可とする.
//	// ネットワークインターフェース構成が「有線I/Fのみ有効化」.
//	if( TYPE_NetworkIFMode_SingleEthernet == m_e_NetworkIFModeSys ) {
//		bl_isWEP					= False ;
//		bl_isWPA					= False ;
//		bl_showSSIDSetting			= False ;
//		bl_showAlgorithmSetting		= False ;
//		bl_showServiceNetWorkExUp	= False ;
//		bl_showServiceNetWorkExDown	= False ;
//		bl_showerviceNetWorkExPage	= False ;
//	}

	Key_WEPKeySetting.showEnable( bl_isWEP );
	Key_PassPhraseSetting.showEnable( bl_isWPA );

	Key_ModeSetting.showEnable( bl_showModeSetting );
	Key_SSIDSetting.showEnable( bl_showSSIDSetting );
	Key_AlgorithmSetting.showEnable( bl_showAlgorithmSetting );
	Key_ServiceNetWorkExUp.showEnable( bl_showServiceNetWorkExUp );
	Key_ServiceNetWorkExDown.showEnable( bl_showServiceNetWorkExDown );
	Txt_erviceNetWorkExPage.showEnable( bl_showerviceNetWorkExPage );

}
//================================================================================================.
// 概要		: PServiceNetWorkEXCom : ネットワーク設定／拡張ﾈｯﾄﾜｰｸ設定 共通 : OKキーボタン押下処理.
// 履歴		: .
//================================================================================================.
void PServiceNetWorkEXCom::procOk( uchar option )
{

	// 拡張ネットワーク設定の可否を判定する.
	Bool bl_isOk = True ;

	if( TYPE_ExNetworkAdapter_Disable != m_e_Adapter ) {
		// パスフレーズチェック .
		if( TYPE_ExNetworkEncryptAlg_WPA_PSK_TKIP == m_e_Algorithm
		    || TYPE_ExNetworkEncryptAlg_WPA_PSK_AES == m_e_Algorithm
		    || TYPE_ExNetworkEncryptAlg_WPA2_PSK_TKIP == m_e_Algorithm
		    || TYPE_ExNetworkEncryptAlg_WPA2_PSK_AES == m_e_Algorithm
		    || TYPE_ExNetworkEncryptAlg_WPA_PSK_Auto == m_e_Algorithm ) {
			if( True == m_bl_PassPhraseAutoUpdate ) {
				if( 0 == m_us_PassPhraseAutoUpdateInterval || m_us_PassPhraseAutoUpdateInterval > 1440 ) {
					bl_isOk = False ;
				}
			}
		}

		// リース期限チェック.
		if( 600 > m_ul_LeaseLimit ) {
			bl_isOk = False ;
		}

		// OK受付判定 .
		if( False == bl_isOk ) {
			MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
			return ;
		}
	}

	// 拡張ネットワークアダプタ装着状態を設定する.
	APIC_SystemInfo* pc_SystemInfo = APIC_SystemInfo::newInstance();	// システム情報のインスタンス生成.
	pc_SystemInfo->setExNetworkAdapter( m_e_Adapter );

	// ネットワークインターフェース構成が「有線I/Fのみ有効化」の場合、下記は反映させない.
	if( TYPE_NetworkIFMode_SingleEthernet != m_e_NetworkIFModeSys ) {

		// 拡張ネットワーク設定のインスタンス生成.
		APIC_ExNetworkSetting* pc_ExNetworkSetting = APIC_ExNetworkSetting::newInstance();

		if( TYPE_NetworkIFMode_SingleSta == m_e_NetworkIFModeSys
		    || TYPE_NetworkIFMode_DualEthernetSta == m_e_NetworkIFModeSys
		    || TYPE_NetworkIFMode_DualEthernetWolLimited == m_e_NetworkIFModeSys ) {
			// SSIDを設定する.
// 2016/02/01 CQ521285 監査ログ HCD-PP対応 Sky大嶋 MOD Start.
			pc_ExNetworkSetting->setStaSSID( m_uc_SSID, JLGE_InspectLogOperateIDL_CE, JLGE_InspectLogIfOperationPanel, False );
			// 認証・暗号化アルゴリズムを設定する.
			pc_ExNetworkSetting->setStaEncryptAlg( m_e_Algorithm, JLGE_InspectLogOperateIDL_CE, JLGE_InspectLogIfOperationPanel, False );
			// WEPキー情報を設定する.
			pc_ExNetworkSetting->setStaWEPKey( &m_st_WEPKeyData, JLGE_InspectLogOperateIDL_CE, JLGE_InspectLogIfOperationPanel, False );
			// パスフレーズを設定する.
			pc_ExNetworkSetting->setStaPassphrase( m_uc_PassPhrase, JLGE_InspectLogOperateIDL_CE, JLGE_InspectLogIfOperationPanel, False );
			// 20/40 MHz 共用設定 .
			pc_ExNetworkSetting->setSta2040MHzCoexistence( m_bl_HzUse, JLGE_InspectLogOperateIDL_CE, JLGE_InspectLogIfOperationPanel, False );
// 2016/02/01 CQ521285 監査ログ HCD-PP対応 Sky大嶋 MOD End.
		} else {
			// SSIDを設定する.
// 2016/02/01 CQ521285 監査ログHCD-PP対応	Sky平田	Start.
			pc_ExNetworkSetting->setApSSID( m_uc_SSID, JLGE_InspectLogOperateIDL_CE, JLGE_InspectLogIfOperationPanel, False );
// 2016/02/01 CQ521285 監査ログHCD-PP対応	Sky平田	End.
// 2016/02/01 CQ521285 監査ログ HCD-PP対応 Sky大嶋 MOD Start.
			// 認証・暗号化アルゴリズムを設定する.
			pc_ExNetworkSetting->setApEncryptAlg( m_e_Algorithm, JLGE_InspectLogOperateIDL_CE, JLGE_InspectLogIfOperationPanel, False );
			// WEPキー情報を設定する.
			pc_ExNetworkSetting->setApWEPKey( &m_st_WEPKeyData, JLGE_InspectLogOperateIDL_CE, JLGE_InspectLogIfOperationPanel, False );
// 2016/02/01 CQ521285 監査ログ HCD-PP対応 Sky大嶋 MOD End.
			// パスフレーズを設定する.
// 2016/02/01 CQ521285 監査ログHCD-PP対応	Sky平田	Start.
			pc_ExNetworkSetting->setApPassphrase( m_uc_PassPhrase, JLGE_InspectLogOperateIDL_CE, JLGE_InspectLogIfOperationPanel, False );
// 2016/02/01 CQ521285 監査ログHCD-PP対応	Sky平田	End.
			// 20/40 MHz 共用設定 .
// 2016/02/01 CQ521285 監査ログ HCD-PP対応 Sky大嶋 MOD Start.
			pc_ExNetworkSetting->setAp2040MHzCoexistence( m_bl_HzUse, JLGE_InspectLogOperateIDL_CE, JLGE_InspectLogIfOperationPanel, False );
// 2016/02/01 CQ521285 監査ログ HCD-PP対応 Sky大嶋 MOD End.
		}

		// パスフレーズ自動更新を設定する .
		if( False == m_bl_PassPhraseAutoUpdate ) {
			m_us_PassPhraseAutoUpdateInterval = 0 ;
		}
// 2016/02/01 CQ521285 監査ログ HCD-PP対応 Sky大嶋 MOD Start.
		pc_ExNetworkSetting->setApPassphraseInterval( m_us_PassPhraseAutoUpdateInterval, JLGE_InspectLogOperateIDL_CE, JLGE_InspectLogIfOperationPanel, False ) ;
// 2016/02/01 CQ521285 監査ログ HCD-PP対応 Sky大嶋 MOD End.

		// 20/40 MHz 共用設定 .

// 2016/02/01 CQ521285 監査ログ HCD-PP対応 Sky大嶋 MOD Start.
		// チャンネル設定.
		pc_ExNetworkSetting->setApChannel(m_uc_channel, JLGE_InspectLogOperateIDL_CE, JLGE_InspectLogIfOperationPanel, False) ;

		// ANY接続.
		pc_ExNetworkSetting->setApAnyConnection(m_bl_ANYConnection, JLGE_InspectLogOperateIDL_CE, JLGE_InspectLogIfOperationPanel, False) ;
// 2016/02/01 CQ521285 監査ログ HCD-PP対応 Sky大嶋 MOD End.

		TYPS_WlanMacAddressFilteringList st_MACAddress;
		pc_ExNetworkSetting->getApAllowMacAddress( &st_MACAddress );
		for( int i = 0; i < APID_ConnectClientMacAdrCount; i++ ) {
			strncpy( ( char* )&st_MACAddress.uc_MacAddressFiltering[i].uc_MacAddress, ( char* )m_uc_MACAddress[i], APID_ConnectClientMacAdrLength - 1 );
			st_MACAddress.uc_MacAddressFiltering[i].uc_MacAddress[APID_ConnectClientMacAdrLength - 1] = '\0';
		}
// 2016/02/01 CQ521285 監査ログ HCD-PP対応 Sky大嶋 MOD Start.
		pc_ExNetworkSetting->setApAllowMacAddress( &st_MACAddress, JLGE_InspectLogOperateIDL_CE, JLGE_InspectLogIfOperationPanel, False );

		// DHCPサーバー設定.
		pc_ExNetworkSetting->setApEnableDHCP(m_bl_DHCPServerUseSetting, JLGE_InspectLogOperateIDL_CE, JLGE_InspectLogIfOperationPanel, False) ;

		// IPV4リースアドレス.
		pc_ExNetworkSetting->setApLeaseIPv4AddressStart( m_uc_IPv4LeaseAddressHead, JLGE_InspectLogOperateIDL_CE, JLGE_InspectLogIfOperationPanel, False ) ;
		pc_ExNetworkSetting->setApLeaseIPv4AddressEnd( m_uc_IPv4LeaseAddressLast, JLGE_InspectLogOperateIDL_CE, JLGE_InspectLogIfOperationPanel, False ) ;
// 2016/02/01 CQ521285 監査ログ HCD-PP対応 Sky大嶋 MOD End.

		// サブネットマスク.
		pc_ExNetworkSetting->setApSubnetMask( m_uc_IPv4SubnetMask ) ;

		// リース期限.
// 2016/02/01 CQ521285 監査ログ HCD-PP対応 Sky大嶋 MOD Start.
		pc_ExNetworkSetting->setApLeaseTime(m_ul_LeaseLimit, JLGE_InspectLogOperateIDL_CE, JLGE_InspectLogIfOperationPanel, False) ;

		// IPv4設定.
		pc_ExNetworkSetting->setIpAddressEx(m_e_ipAddress, JLGE_InspectLogOperateIDL_CE, JLGE_InspectLogIfOperationPanel, False);
		pc_ExNetworkSetting->setDHCP_OnEx(m_bl_DHCPSetting, JLGE_InspectLogOperateIDL_CE, JLGE_InspectLogIfOperationPanel, False);
// 2016/02/01 CQ521285 監査ログ HCD-PP対応 Sky大嶋 MOD End.

		g_c_ServiceMioSettingNotifier.setWaiting( True );																// オブザーバー通知を待つ.
		TYPE_MioSettingResult e_MioSettingResult = TYPE_MioSettingResultOk;												// MIO設定結果.
// 2016/02/01 CQ521285 監査ログ HCD-PP対応 Sky大嶋 MOD Start.
		e_MioSettingResult = pc_ExNetworkSetting->setIPAddressEx( m_uc_IPv4IPAddress, JLGE_InspectLogOperateIDL_CE, JLGE_InspectLogIfOperationPanel, False, &g_c_ServiceMioSettingNotifier );	// IPアドレス設定.
// 2016/02/01 CQ521285 監査ログ HCD-PP対応 Sky大嶋 MOD End.
		m_bl_Waiting = True;																							// 設定待ちをONにする.
		if( TYPE_MioSettingResultOk != e_MioSettingResult ) {															// 設定時にNGだった場合は途中で止まってしまうので、強制的に遷移.
			m_bl_Waiting = False;																						// 設定待ちをOFFにする.
		}
// 2016/02/01 CQ521285 監査ログ HCD-PP対応 Sky大嶋 MOD Start.
		pc_ExNetworkSetting->setSubnetMaskEx( m_uc_IPv4SubnetMaskEx, JLGE_InspectLogOperateIDL_CE, JLGE_InspectLogIfOperationPanel, False );
// 2016/02/01 CQ521285 監査ログ HCD-PP対応 Sky大嶋 MOD End.

	}

	if( False == m_bl_Waiting ) {				// オブザーバー通知を待たない場合.
		nextGamen = &gp_ServiceNetworkMenu ;	// ネットワーク設定へ遷移 .
	}
}
//================================================================================================.
// 概要		: PServiceNetWorkEXSSIDSetting : ネットワーク設定／拡張ﾈｯﾄﾜｰｸ設定 共通 : 拡張ﾈｯﾄﾜｰｸキーボタン押下処理.
//================================================================================================.
void PServiceNetWorkEXCom::procIndexButton( uchar option )
{
	switch( option ) {
		case	PNLD_BTNID_NetWorkEx_Idx_2nd:	// 2ndﾈｯﾄﾜｰｸｶｰﾄﾞ設定
			nextGamen = &gp_ServiceNetWorkEX2ndCardSetting;
			break;
		case	PNLD_BTNID_NetWorkEx_Idx_Ope:	// 動作モード
			nextGamen = &gp_ServiceNetWorkEXOpeModeSetting;
			break;
		case	PNLD_BTNID_NetWorkEx_Idx_SSID:	// SSID
			nextGamen = &gp_ServiceNetWorkEXSSIDSetting;
			break;
		case	PNLD_BTNID_NetWorkEx_Idx_Alg:	// 認証・暗号化アルゴリズム
			nextGamen = &gp_ServiceNetWorkEXAlgorithmSetting;
			break;
		case	PNLD_BTNID_NetWorkEx_Idx_Wep:	// WEPキー
			nextGamen = &gp_ServiceNetWorkEXWepKeySetting;
			break;
		case	PNLD_BTNID_NetWorkEx_Idx_Pass:	// パスフレーズ
			nextGamen = &gp_ServiceNetWorkEXPassPhraseSetting;
			break;
		case	PNLD_BTNID_NetWorkEx_Idx_CH :		// チャンネル設定.
			nextGamen = &gp_ServiceChannelSetting;
			break;
		case	PNLD_BTNID_NetWorkEx_Idx_ANY :			// ANY接続.
			nextGamen = &gp_ServiceANYConnectionSetting;
			break;
		case	PNLD_BTNID_NetWorkEx_Idx_MAC :			// 接続許可子機MACアドレス.
			nextGamen = &gp_ServiceConnectionPermitHandsetMAC;
			break;
		case	PNLD_BTNID_NetWorkEx_Idx_DHCP :			// DHCPサーバー設定.
			nextGamen = &gp_ServiceDHCPServerSetting;
			break;
		case	PNLD_BTNID_NetWorkEx_Idx_TCPIP :			// TCP/IP設定.
			nextGamen = &gp_ServiceExpansionNetworkTCPIP;
			break;
		default:
			break;
	}
}
//================================================================================================.
// 概要		: PServiceNetWorkEX2ndCardSetting : ネットワーク設定／拡張ﾈｯﾄﾜｰｸ設定 共通 : 定期起床.
//================================================================================================.
void PServiceNetWorkEXCom::procTimerWakeUp( uchar uc_Option )
{
	PServiceNoFunctionCodeCom::procTimerWakeUp( uc_Option );
	if( True == m_bl_Waiting && False == g_c_ServiceMioSettingNotifier.isWaiting() ) {	// ネットワーク設定待ち状態且つ、オブザーバー応答有りの場合.
		m_bl_Waiting = False;															// 設定待ちをOFFにする.
		nextGamen = &gp_ServiceNetworkMenu ;											// ネットワーク設定へ遷移 .
	}
}
//================================================================================================.
// 概要		: PServiceNetWorkEX2ndCardSetting : ネットワーク設定／拡張ﾈｯﾄﾜｰｸ設定 共通 : メッセージ・ディスパッチ処理.
//================================================================================================.
void PServiceNetWorkEXCom::messageDispath( Message message, uchar option, MessageType type, int32_t sl_option )
{
	Bool bl_Dispatch = True;
	switch( message ) {
		case MS_GoToFace:							// センサチェック用（サービス限定）.
		case MS_Reset:								// パネルリセット.
		case MS_IndexButton:						// サービスメインメニューキー.
		case MS_GoToColor:							// LIMOSキー(サービス限定）.
		case MS_GoToMag:							// ラインキー.
		case MS_GoToPaper:							// 用紙関係キー.
		case MS_GoToPage:							// 画面移動.
		case MS_Ok:									// 設定終了.
		case MS_Button:								// 通常ボタン.
		case MS_Cancel:								// 設定取消.
		case MS_10Key:								// テンキー.
		case MS_Clear:								// クリアー.
		case MS_Accessibility:						// ユーザ補助キー.
		case MS_ColorMode:							// カラーモード.
		case MS_Service :							// サービスマンモード.
			if( True == m_bl_Waiting ) {			// 以上のメッセージは、オブザーバー待ち中は受け付けない.
				bl_Dispatch = False;
			}
			break;
		default:
			break;
	}
	if( bl_Dispatch == True ) {
		PServiceNoFunctionCodeCom::messageDispath( message, option, type, sl_option );
	} else {
		setBuzzerType( PCGE_BuzzerType_InputNg );	// 受付拒否音.
	}
}
//================================================================================================.
// 概要		: PServiceNetWorkEX2ndCardSetting : ネットワーク設定／拡張ﾈｯﾄﾜｰｸ設定 共通 : 画面更新処理.
//================================================================================================.
void PServiceNetWorkEXCom::ClearInfo( Bool bl_ClearNetWorkEXGet )
{
	m_bl_NetWorkEXGet = bl_ClearNetWorkEXGet;
}
//================================================================================================.
// 概要		: PServiceNetWorkEX2ndCardSetting : ネットワーク設定／拡張ﾈｯﾄﾜｰｸ設定 共通 .
// 概要		: 文字列をＩＰアドレス形式に変換.
//================================================================================================.
void PServiceNetWorkEXCom::CharToIPAddress(
    const char* _sc_CharAddress,		// アドレス文字列.
    uchar* _uc_IPAddress )				//ＩＰアドレス変換後格納用.
{
	memset( _uc_IPAddress, 0, PNLD_MAXInputFaxIPPos );
	register char _sc_Area = 0;
	while( *_sc_CharAddress ) {
		if( *_sc_CharAddress >= '0' && *_sc_CharAddress <= '9' ) {
			// 数字０～９の場合.
			_uc_IPAddress[( uchar )_sc_Area] = static_cast<uchar>( ( _uc_IPAddress[( uchar )_sc_Area] * 10 ) + ( *_sc_CharAddress - '0' ) );
			// 0未満、または、IPアドレス番号MAX値よりも大きい場合は0に丸め込む.
			if( PNLD_MAXInputFaxIPNo < _uc_IPAddress[( uchar )_sc_Area] ) {
				_uc_IPAddress[( uchar )_sc_Area] = 0;
			}
		} else if( '.' == *_sc_CharAddress ) {
			// 「．」の場合.
			_sc_Area++;
			if( _sc_Area > ( PNLD_MAXInputFaxIPPos - 1 ) )	{ break; }
		} else if( ' ' == *_sc_CharAddress ) {
			// スペースの場合.
		} else {
			// その他の文字.
			break;
		}
		_sc_CharAddress++;
	}
}
//============================================================================================.
// 概要		: PServiceNetWorkEX2ndCardSetting : ネットワーク設定／拡張ﾈｯﾄﾜｰｸ設定 共通 .
// 概要		: ＩＰアドレスを文字列形式に変換.
//============================================================================================.
void PServiceNetWorkEXCom::IPAddressToChar(
    const uchar* _uc_IPAddress,		//ＩＰアドレス.
    char* _sc_CharAddress )			// 文字列変換後格納用.
{
	register char _ss_buff[4];
	memset( _ss_buff, 0, sizeof( _ss_buff ) );
	sprintf( _sc_CharAddress, "%d", _uc_IPAddress[0] );
	for( register short i = 1; i < PNLD_ServiceIPv4Address_IPv4Num; i++ ) {
		strcat( _sc_CharAddress, "." );
		snprintf( _ss_buff, sizeof( _ss_buff ), "%d", _uc_IPAddress[i] );
		strcat( _sc_CharAddress, _ss_buff );
	}
}
//================================================================================================.
// 概要		: PServiceNetWorkEX2ndCardSetting : ネットワーク設定／拡張ﾈｯﾄﾜｰｸ設定／2ndﾈｯﾄﾜｰｸｶｰﾄﾞ設定 : 画面開始処理.
//================================================================================================.
void PServiceNetWorkEX2ndCardSetting::startGamen()
{
	// 親クラスを呼ぶ.
	PServiceNetWorkEXCom::startGamen();
	// 「2ndﾈｯﾄﾜｰｸｶｰﾄﾞ設定」を選択状態とする.
	Rbt_ServiceNetWorkExMenu1.select( PNLD_NetWorkEX2ndCard );	// 2ndﾈｯﾄﾜｰｸｶｰﾄﾞ設定.
}
//================================================================================================.
// 概要		: PServiceNetWorkEX2ndCardSetting : ネットワーク設定／拡張ﾈｯﾄﾜｰｸ設定／2ndﾈｯﾄﾜｰｸｶｰﾄﾞ設定 : 画面更新処理.
//================================================================================================.
void PServiceNetWorkEX2ndCardSetting::setupGamen( short option )
{
	// 親クラスを呼ぶ.
	PServiceNetWorkEXCom::setupGamen( option );

	// 選択状態を更新する.
	if( TYPE_ExNetworkAdapter_Disable != m_e_Adapter ) {
		// 「装着」を選択状態とする.
		Rbt_ServiceNetWorkEx2ndCard.select( PNLD_NetWorkEX2ndCardIn );
	}
	else {
		// 「非装着」を選択状態とする.
		Rbt_ServiceNetWorkEx2ndCard.select( PNLD_NetWorkEX2ndCardOut );
	}

// comment 2015/02/26 OPS1-Sky延原 [ZeusSBk][RQ-340] 無線LANオプションのIEEE 802.11 acad サポート.
	APIC_SystemInfo*  pc_SystemInfo = APIC_SystemInfo::newInstance();
	if ( NULL != pc_SystemInfo) {
		Bool bl_ShowEnable_2ndCardOptionType = True;
		// 装着中の無線オプション表示(UK-212／UK-215)を切り替える.
		TYPE_ExNetworkWLANDeviceType e_DeviceType = pc_SystemInfo->getWLANDeviceType(); // 装着中無線オプション種別取得.
		// オプションを判別し、シンボルを切替える/.
		if( TYPE_ExNetworkWLANDeviceType_UK212 == e_DeviceType ) {
			Txt_ServiceNetWorkEx2ndCardOptionType.changeText( s_pITMServiceNetworkAdapter_UK_212_W240H016I ); // UK212装着中.
		} 
		else if( TYPE_ExNetworkWLANDeviceType_UK215 == e_DeviceType ) {
//2016/08/26 CQ533601 sky草柳 A4機用無線LANオプション名称変更対応 start.
#ifndef DEF_A4_Cus
			Txt_ServiceNetWorkEx2ndCardOptionType.changeText( s_pITMServiceNetworkAdapter_UK_215_W240H016I ); // UK215装着中.
#else
			Txt_ServiceNetWorkEx2ndCardOptionType.changeText( s_pNOTITMServiceNetworkAdapter_UK_216_W240H016I ); // UK216装着中.
#endif //DEF_A4_Cus.
//2016/08/26 CQ533601 sky草柳 A4機用無線LANオプション名称変更対応 end.
		}
// comment 2018/03/08 【IT6_Eagle】【HCLT_Pavani】【制御構成変更_No.77-1】【WP 1696】 Addition of UK-XXX wireless adapter.
// comment 2018/06/05 【IT6_Eagle】【HCLT_Pavani】【制御構成変更_No.77-1】【WP 1696】 API change for Wireless Adapter.
//		else if( TYPE_ExNetworkWLANDeviceType_UKXXX == e_DeviceType ) {
		else if( TYPE_ExNetworkWLANDeviceType_UK221 == e_DeviceType ) {
// comment 2018/12/11 【IT6_Eagle】【HCLT_HariBhaskar】【AR1069581】changing the message from UK_XXX to UK_221.
//			Txt_ServiceNetWorkEx2ndCardOptionType.changeText( s_pNOTITMServiceNetworkAdapter_UK_XXX_W240H016I ); // UK-XXX.
			Txt_ServiceNetWorkEx2ndCardOptionType.changeText( s_pNOTITMServiceNetworkAdapter_UK_221_W048H016I ); // UK-221.

		}
		else {
			// 非装着(物理的に)、又は、初期化中は、非表示
			bl_ShowEnable_2ndCardOptionType = False;
		}

		// 装着中無線オプションの表示/非表示を切替える.
		Bool bl_IsExNetworkAdapterExist = pc_SystemInfo->isExNetworkAdapterExist(); // 無線オプション装着状態取得.
		if( False == bl_IsExNetworkAdapterExist || TYPE_ExNetworkAdapter_Disable == m_e_Adapter ) {
			// 無線オプション非装着時、又は、「非装着」キー選択時、非表示.
			bl_ShowEnable_2ndCardOptionType = False;
		}

		Gra_ServiceNetWorkEx2ndCardOptionType.showEnable( bl_ShowEnable_2ndCardOptionType );
		Txt_ServiceNetWorkEx2ndCardOptionTitle.showEnable( bl_ShowEnable_2ndCardOptionType );
		Txt_ServiceNetWorkEx2ndCardOptionType.showEnable( bl_ShowEnable_2ndCardOptionType );
	}
	else {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
	}
}
//================================================================================================.
// 概要		: PServiceNetWorkEX2ndCardSetting : ネットワーク設定／拡張ﾈｯﾄﾜｰｸ設定／2ndﾈｯﾄﾜｰｸｶｰﾄﾞ設定 : ボタン押下処理.
//================================================================================================.
void PServiceNetWorkEX2ndCardSetting::procButtonOn( uchar option )
{
	switch( option ) {
		case	PNLD_BTNID_2ndNetWorkCard_OUT :
			// アダプタを「非装着」とする.
			m_e_Adapter = TYPE_ExNetworkAdapter_Disable;
			break;
		case	PNLD_BTNID_2ndNetWorkCard_IN :
			// アダプタを「装着」とする.
			m_e_Adapter = TYPE_ExNetworkAdapter_Wireless;
			break;
		default:
			break;
	}
	setupGamen();
}
//================================================================================================.
// 概要		: PServiceNetWorkEX2ndCardSetting : ネットワーク設定／拡張ﾈｯﾄﾜｰｸ設定／2ndﾈｯﾄﾜｰｸｶｰﾄﾞ設定 : 拡張ﾈｯﾄﾜｰｸキーボタン押下処理.
//================================================================================================.
void PServiceNetWorkEX2ndCardSetting::procGoToPage( uchar option )
{
	switch( option ) {
		case	PNLD_BTNID_NetWorkEx_Up :
		case	PNLD_BTNID_NetWorkEx_Down :
			nextGamen = &gp_ServiceChannelSetting;
			break;
		default:
			break;
	}
}
//================================================================================================.
// 概要		: PServiceNetWorkEXOpeModeSetting : ネットワーク設定／拡張ﾈｯﾄﾜｰｸ設定／動作モード : 画面開始処理.
//================================================================================================.
void PServiceNetWorkEXOpeModeSetting::startGamen()
{
	// 親クラスを呼ぶ.
	PServiceNetWorkEXCom::startGamen();
	Key_NetworkIFModeDualEthernetWolLimited.showEnable( False );
	Key_NetworkIFModeDualWiFiDirect.showEnable( True );
	Key_NetworkIFModeDualEthernetAp.changePosition( 412, 184 );
	Key_NetworkIFModeSingleEthernet.changeText( s_KEYServiceOnlyWired );
// Comment 2018/01/29 HCLT_Hanuman [IT5_4.2][AR1038061] To improve performance.
//// comment 2018/01/11 HCLT-Rengaraaj [IT5_4.2][AR1034893] Disabling Wireless only when VLAN enabled.
////	Key_NetworkIFModeSingleSta.changeText( s_KEYServiceOnlyRadio );
//	if ( True ==  PnlComGetVlanSetting()->getVlanEnable() ) {
	if ( True ==  PNLC_NetworkLan::getInstance()->getVlanEnableWrapper() ) {
		Key_NetworkIFModeSingleSta.showEnable( False );
	} else {
		Key_NetworkIFModeSingleSta.showEnable( True );
		Key_NetworkIFModeSingleSta.changeText( s_KEYServiceOnlyRadio );
	}
	Key_NetworkIFModeDualEthernetSta.changeText( s_KEYServiceCordlessHandsetMode );
	Key_NetworkIFModeDualEthernetAp.changeText( s_KEYServiceMasterMode );
	// 「動作モード」を選択状態とする.
	Rbt_ServiceNetWorkExMenu1.select( PNLD_NetWorkEXOpeMode );	// 動作モード.
}
//================================================================================================.
// 概要		: PServiceNetWorkEXOpeModeSetting : ネットワーク設定／拡張ﾈｯﾄﾜｰｸ設定／動作モード : 画面更新処理.
// 											  : ネットワーク設定／拡張ﾈｯﾄﾜｰｸ設定／ﾈｯﾄﾜｰｸｲﾝﾀｰﾌｪｰｽ構成 : ボタン押下処理.
// 履歴		: .
//			: 2015/01/20 OPS1-Sky古池	[Poseidon][CQ 509771] WiFiダイレクト Own時はSw170の1bitめ、Generic時は0bitめで有効チェックを実施するよう修正.
//================================================================================================.
void PServiceNetWorkEXOpeModeSetting::setupGamen( short option )
{
	// 親クラスを呼ぶ.
	PServiceNetWorkEXCom::setupGamen( option );

// comment 2014/12/18 OPS1-Sky浜野 [Poseidon][CQ508558] WiFiダイレクト表示対応.
	Bool bl_WiFiDirectShow = False;
// comment 2015/08/24 HCLT-Harish [MinervaSBK][CQ516864] Change the WIFI-Direct key display condition from Function Ver Type3 onwards.
// Comment 2017/11/29 【HCLT-Vishal】【Eagle】【制御構成変更_No.4】 Removing old function version check and else portion.
	TYPE_WfdLicence m_e_WfdLicence  = PnlComGetSystemInfo()->getWfdLicenceStatus();
		if( TYPE_WfdLicence_Enable == m_e_WfdLicence ) {
			bl_WiFiDirectShow = True;
		}
	Key_NetworkIFModeDualWiFiDirect.showEnable( bl_WiFiDirectShow );		// 有線+無線（Wi-Fi Direct)キー.

// comment 2015/02/26 OPS1-Sky延原 [ZeusSBk][RQ-340] 無線LANオプションのIEEE 802.11 acad サポート.
	// UK-215装着時、「有線＋無線（親機モード）」を「有線＋無線（簡易APモード）」に切替える.
	APIC_SystemInfo*  pc_SystemInfo = APIC_SystemInfo::newInstance();
	if ( NULL != pc_SystemInfo) {
		Bool bl_ShowEnable_DualEthernetAp = True;
		TYPE_ExNetworkWLANDeviceType e_DeviceType = pc_SystemInfo->getWLANDeviceType(); // 装着中無線オプション種別取得.
		if(TYPE_ExNetworkWLANDeviceType_UK215 == e_DeviceType) {
			Key_NetworkIFModeDualEthernetAp.changeText( s_pKEYServiceSimpleAPMode_W160H056I );
		}
		else if (TYPE_ExNetworkWLANDeviceType_UK212 == e_DeviceType) {
			Key_NetworkIFModeDualEthernetAp.changeText( s_KEYServiceMasterMode );
		}
// comment 2018/03/09 【IT6_Eagle】【HCLT_Pavani】【制御構成変更_No.77-1】【WP 1696】 Addition of UK-XXX wireless adapter.
// comment 2018/06/05 【IT6_Eagle】【HCLT_Pavani】【制御構成変更_No.77-1】【WP 1696】 API change for Wireless Adapter.
//		else if (TYPE_ExNetworkWLANDeviceType_UKXXX == e_DeviceType) { 
		else if (TYPE_ExNetworkWLANDeviceType_UK221 == e_DeviceType) {
			Key_NetworkIFModeDualEthernetAp.changeText( s_KEYServiceMasterMode );
		}
		else {
			bl_ShowEnable_DualEthernetAp = False;
		}
		Key_NetworkIFModeDualEthernetAp.showEnable( bl_ShowEnable_DualEthernetAp );
	}
	else {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
	}

// comment 2013.05.30 jindo【ZM3rd】【UV-00958/UV-01257】 異なる2つのネットワークに接続したい/無線LANフル規格対応.
//	// 動作モードの選択状態を更新する.
//	if( TYPE_OperationModeForService_WAP == m_e_OpeMode ) {
//		// 「アクセスポイントモード」を選択状態とする.
//		Rbt_ServiceNetWorkExOpeMode.select( PNLD_NetWorkEXOpeModeWireless );
//	}
//	else {
//		// 「しない」を選択状態とする.
//		Rbt_ServiceNetWorkExOpeMode.select( PNLD_NetWorkEXOpeModeDisable );
//	}
	short ss_select = 0;		// ネットワークインターフェース構成・選択値.
	switch( m_e_NetworkIFMode ) {
		case	TYPE_NetworkIFMode_SingleEthernet :			// 有線I/Fのみ有効化.
			ss_select = PNLD_NetworkIFModeSingleEthernet;
			break;
		case	TYPE_NetworkIFMode_SingleSta :				// 無線I/Fのみ有効化.
			ss_select = PNLD_NetworkIFModeSingleSta;
			break;
		case	TYPE_NetworkIFMode_DualEthernetSta :		// 有線I/F＋無線I/F有効化.
			ss_select = PNLD_NetworkIFModeDualEthernetSta;
			break;
		case	TYPE_NetworkIFMode_DualEthernetWolLimited :	// 有線I/F＋無線I/F(ErP復帰限定)有効化.
			ss_select = PNLD_NetworkIFModeDualEthernetWolLimited;
			break;
		case	TYPE_NetworkIFMode_DualEthernetAp :			// 有線I/F＋無線I/F(AP)有効化.
			ss_select = PNLD_NetworkIFModeDualEthernetAp;
			break;
		case	TYPE_NetworkIFMode_DualEthernetWfd :		// 有線+無線（Wi-Fi Direct)
			ss_select = PNLD_NetworkIFModeDualEthernetWfd;
			break;
		default:
			break;
	}

	// ネットワークインターフェース構成の選択状態を更新する.
	Rbt_ServiceNetWorkExOpeMode.select( ss_select );

	// 表示非表示処理 .
	Bool bl_showServiceToLine	= True ; // ラインキー .
	Bool bl_showOkService		= True ; // OKキー .
	Bool bl_showOffOnMessage	= True ; // OFF/ONメッセージ .

	if( True == m_bl_Fixed ) {
		bl_showServiceToLine	= False ;
		bl_showOkService		= False ;
		bl_showOffOnMessage		= True ;
	} else {
		bl_showServiceToLine	= True ;
		bl_showOkService		= True ;
		bl_showOffOnMessage		= False ;
	}

	// ラインキーは非表示条件の時のみ適用させる .
	if( False == bl_showServiceToLine ) {
		Key_ServiceToLine.showEnable( False ) ;	// ラインキー.
	}
	Key_OkService.showEnable( bl_showOkService ); // OKキー.
	Grp_ServiceNetWorkExOffOnMessage.showEnable( bl_showOffOnMessage ) ;	// OFF/ONメッセージ .

}
//================================================================================================.
// 概要		: PServiceNetWorkEXOpeModeSetting : ネットワーク設定／拡張ﾈｯﾄﾜｰｸ設定／動作モード : ボタン押下処理.
// 											  : ネットワーク設定／拡張ﾈｯﾄﾜｰｸ設定／ﾈｯﾄﾜｰｸｲﾝﾀｰﾌｪｰｽ構成 : ボタン押下処理.
// 履歴		: .
//================================================================================================.
void PServiceNetWorkEXOpeModeSetting::procButtonOn( uchar option )
{
	if( True == m_bl_Fixed ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg ) ; // ブザー音セット.
		return ;
	}

	switch( option ) {
		case	BTNID_NetworkIFModeSingleEthernet :			// 有線I/Fのみ有効化.
			m_e_NetworkIFMode = TYPE_NetworkIFMode_SingleEthernet;
			break;
		case	BTNID_NetworkIFModeSingleSta :				// 無線I/Fのみ有効化.
			m_e_NetworkIFMode = TYPE_NetworkIFMode_SingleSta;
			break;
		case	BTNID_NetworkIFModeDualEthernetSta :		// 有線I/F＋無線I/F有効化.
			m_e_NetworkIFMode = TYPE_NetworkIFMode_DualEthernetSta;
			break;
		case	BTNID_NetworkIFModeDualEthernetWolLimited :	// 有線I/F＋無線I/F(ErP復帰限定)有効化.
			m_e_NetworkIFMode = TYPE_NetworkIFMode_DualEthernetWolLimited;
			break;
		case	BTNID_NetworkIFModeDualEthernetAp :			// 有線I/F＋無線I/F(AP)有効化.
			m_e_NetworkIFMode = TYPE_NetworkIFMode_DualEthernetAp;
			break;
		case	BTNID_NetworkIFModeDualWiFiDirect :			// 有線+無線（Wi-Fi Direct)
			m_e_NetworkIFMode = TYPE_NetworkIFMode_DualEthernetWfd;
			break;
		case	PNLD_BTNID_OpeModeFix : {
			m_bl_Fixed = True ;

			// 拡張ネットワークアダプタ装着状態を設定する.
			APIC_SystemInfo* pc_SystemInfo = APIC_SystemInfo::newInstance();	// システム情報のインスタンス生成.
			pc_SystemInfo->setExNetworkAdapter( m_e_Adapter );

			// 動作モードを設定する.
			APIC_ExNetworkSetting* pc_ExNetworkSetting = APIC_ExNetworkSetting::newInstance();	// 拡張ネットワーク設定のインスタンス生成.
			if( NULL == pc_ExNetworkSetting ) {
// Comment 2015/11/02 【ZeusS_ZX0】【HCL_Vasu】【制御構成変更_No.76-1】Adding Error Code macro.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//				LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//				if (NULL !=pc_BFW_System){
//					pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19000A0100E51B01 );
//				}
				LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
				return;
			}
// 2016/02/01 CQ521285 監査ログ HCD-PP対応 Sky大嶋 MOD Start.
				pc_ExNetworkSetting->setNetworkIFMode( m_e_NetworkIFMode, JLGE_InspectLogOperateIDL_CE, JLGE_InspectLogIfOperationPanel, False );
// 2016/02/01 CQ521285 監査ログ HCD-PP対応 Sky大嶋 MOD End.
		}
		break ;
		default:
			break;
	}

	setupGamen();

}
//==============================================================================================.
// 概要		: PServiceNetWorkEXOpeModeSetting : ネットワーク設定／拡張ﾈｯﾄﾜｰｸ設定／動作モード : 拡張ﾈｯﾄﾜｰｸキーボタン押下処理.
// 履歴		: .
//================================================================================================.
void PServiceNetWorkEXOpeModeSetting::procGoToPage( uchar option )
{
	if( True == m_bl_Fixed ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg ) ; // ブザー音セット.
		return ;
	}

	switch( option ) {
		case	PNLD_BTNID_NetWorkEx_Up :
		case	PNLD_BTNID_NetWorkEx_Down :
			nextGamen = &gp_ServiceChannelSetting;
			break;
		default:
			break;
	}
}
