//============================================================================================.
//
// PServiceNetWorkEXSSIDInput : 93B31310 サービス・拡張ネットワーク設定／SSID入力.
//
//============================================================================================.

//================================================================================================.
// 概要		: PServiceNetWorkEXSSIDInput : 93B31310 サービス・拡張ネットワーク設定／SSID入力 .
//================================================================================================.
PServiceNetWorkEXSSIDInput::PServiceNetWorkEXSSIDInput( PDisplayParts** partsTable, short partsNumber, Bool isNoWarning )
	: PServiceNetworkExKeyboardCom( partsTable, partsNumber, isNoWarning )
{
	// 初期化.
	m_ss_Tx = PNLD_ServiceNetworkExKeyboardComTx ;
	m_ss_Gy = PNLD_ServiceNetworkExKeyboardComGy ;
	m_pc_DispField = &Btx_ServiceNewWorkExKeyboardComInput;
	m_e_CharSet = EP_CharSet_USASCII;
}
//================================================================================================.
// 概要		: PServiceNetWorkEXSSIDInput : 93B31310 サービス・拡張ネットワーク設定／SSID入力 : 画面開始処理.
//================================================================================================.
void PServiceNetWorkEXSSIDInput::startGamen()
{
	// '\0'で初期化 .
	memset( m_sc_StrKeyboard, '\0', sizeof( m_sc_StrKeyboard ) ) ;

	// バッファに格納 .
	memcpy( m_sc_StrKeyboard, m_uc_SSID, sizeof( m_sc_StrKeyboard ) - 1 ) ;


	// 表示領域に文字列をセット.
	setKeyboardData( m_sc_StrKeyboard, PNLD_NetWorkEXSSIDMaxLen , PNLD_ServiceNetworkExKeyboardComInputViewLen ) ;

	// 親クラスを呼ぶ.
	PServiceNetworkExKeyboardCom::startGamen();
}

//================================================================================================.
// 概要		: PServiceNetWorkEXSSIDInput : 93B31310 サービス・拡張ネットワーク設定／SSID入力 : キャンセル処理.
//================================================================================================.
void PServiceNetWorkEXSSIDInput::procCancel( uchar option )
{
	nextGamen = &gp_ServiceNetWorkEXSSIDSetting;
}
//================================================================================================.
// 概要		: PServiceNetWorkEXSSIDInput : 93B31310 サービス・拡張ネットワーク設定／SSID入力 : Okキー押下処理.
//================================================================================================.
void PServiceNetWorkEXSSIDInput::procOk( uchar option )
{
	// 一文字も入力されていない場合は受付禁止 .
	if( 0 == strlen( m_sc_StrKeyboard ) ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );					// ブザー音セット.
		return ;
	}

	// '\0'で初期化 .
	memset( m_uc_SSID, '\0', sizeof( m_uc_SSID ) ) ;
	// バッファから反映 .
	memcpy( m_uc_SSID, m_sc_StrKeyboard, sizeof( m_uc_SSID ) - 1 ) ;

	// 画面遷移
	nextGamen = &gp_ServiceNetWorkEXSSIDSetting ;
}



//================================================================================================.
// 概要		: PServiceNetWorkEXAlgorithmSetting : ネットワーク設定／拡張ﾈｯﾄﾜｰｸ設定／認証・暗号化アルゴリズム : 画面開始処理.
//================================================================================================.
void PServiceNetWorkEXAlgorithmSetting::startGamen()
{
	// 親クラスを呼ぶ.
	PServiceNetWorkEXCom::startGamen();
	// 「認証・暗号化アルゴリズム」を選択状態とする.
	Rbt_ServiceNetWorkExMenu1.select( PNLD_NetWorkEXAlgorithm );	// 認証・暗号化アルゴリズム.

	bl_showKey = True;
//  Comment 2015/09/02 【HCLT-Harish】【CQ516586】Hiding Button "WEP" when in FIPSMode or Wired+Wireless (Wi-Fi Direct).
//	if( TYPE_NetworkIFMode_DualEthernetAp == APIC_ExNetworkSetting::newInstance()->getNetworkIFMode()	// ﾈｯﾄﾜｰｸｲﾝﾀｰﾌｪｰｽ構成が有線I/F＋無線I/F(AP)有効化.
//	&& TYPE_FIPSMode_Enable == APIC_FIPSSetting::newInstance()->getFIPSMode() ){						// FIPSモード設定が有効.
	if( TYPE_NetworkIFMode_DualEthernetWfd == APIC_ExNetworkSetting::newInstance()->getNetworkIFMode()	// ﾈｯﾄﾜｰｸｲﾝﾀｰﾌｪｰｽ構有線+無線（Wi-Fi Direct).
	|| TYPE_FIPSMode_Enable == APIC_FIPSSetting::newInstance()->getFIPSMode() ){						// FIPSモード設定が有効.
		bl_showKey = False;
	}

}
//================================================================================================.
// 概要		: PServiceNetWorkEXAlgorithmSetting : ネットワーク設定／拡張ﾈｯﾄﾜｰｸ設定／認証・暗号化アルゴリズム : 画面更新処理.
//================================================================================================.
void PServiceNetWorkEXAlgorithmSetting::setupGamen( short option )
{
	// 親クラスを呼ぶ.
	PServiceNetWorkEXCom::setupGamen( option );

	Key_AlgorithmWep.showEnable( bl_showKey );			// WEPボタン.
	Key_AlgorithmWpaPskTkip.showEnable( False );
	Key_AlgorithmWpa2PskTkip.showEnable( False );
	Key_AlgorithmWpaWpa2Psk.showEnable( False );
	Key_AlgorithmWpaPskAes.changePosition( 224, 192 );
	Key_AlgorithmWpa2PskAes.changePosition( 380, 192 );


	// 認証・暗号化アルゴリズムの選択を更新する
	switch( m_e_Algorithm ) {
		case	TYPE_ExNetworkEncryptAlg_None :
			Rbt_ServiceNetWorkExAlgorithm.select( PNLD_NetWorkEXAlgorithm_None );			// 認証・暗号化なし.
			break;
		case	TYPE_ExNetworkEncryptAlg_WEP :
			Rbt_ServiceNetWorkExAlgorithm.select( PNLD_NetWorkEXAlgorithm_Wep );			// WEP.
			break;
		case	TYPE_ExNetworkEncryptAlg_WPA_PSK_TKIP :
			Rbt_ServiceNetWorkExAlgorithm.select( PNLD_NetWorkEXAlgorithm_WpaPskTkip );		// WPA-PSK(TKIP).
			break;
		case	TYPE_ExNetworkEncryptAlg_WPA_PSK_AES :
			Rbt_ServiceNetWorkExAlgorithm.select( PNLD_NetWorkEXAlgorithm_WpaPskAes );		// WPA-PSK(AES).
			break;
		case	TYPE_ExNetworkEncryptAlg_WPA2_PSK_TKIP :
			Rbt_ServiceNetWorkExAlgorithm.select( PNLD_NetWorkEXAlgorithm_Wpa2PskTkip );	// WPA2-PSK(TKIP).
			break;
		case	TYPE_ExNetworkEncryptAlg_WPA2_PSK_AES :
			Rbt_ServiceNetWorkExAlgorithm.select( PNLD_NetWorkEXAlgorithm_Wpa2PskAes );		// WPA2-PSK(AES).
			break;
		case	TYPE_ExNetworkEncryptAlg_WPA_PSK_Auto :
			Rbt_ServiceNetWorkExAlgorithm.select( PNLD_NetWorkEXAlgorithm_WpaWpa2Psk );		// WPA/WPA2-PSK.
			break;
		default:
			break;
	}
}
//================================================================================================.
// 概要		: PServiceNetWorkEXAlgorithmSetting : ネットワーク設定／拡張ﾈｯﾄﾜｰｸ設定／認証・暗号化アルゴリズム : ボタン押下処理.
//================================================================================================.
void PServiceNetWorkEXAlgorithmSetting::procButtonOn( uchar option )
{
	// 親クラスを呼ぶ.
	PServiceNoFunctionCodeCom::procButtonOn( option );

	// 認証・暗号化アルゴリズムの選択を更新する
	switch( option ) {
		case	PNLD_BTNID_Algorithm_None :
			m_e_Algorithm	= TYPE_ExNetworkEncryptAlg_None;			// 認証・暗号化なし.
			break;
		case	PNLD_BTNID_Algorithm_Wep :
			m_e_Algorithm	= TYPE_ExNetworkEncryptAlg_WEP;				// WEP.
			break;
		case	PNLD_BTNID_Algorithm_WpaPsk_Tkip :
			m_e_Algorithm	= TYPE_ExNetworkEncryptAlg_WPA_PSK_TKIP;	// WPA-PSK(TKIP).
			break;
		case	PNLD_BTNID_Algorithm_WpaPsk_Aes :
			m_e_Algorithm	= TYPE_ExNetworkEncryptAlg_WPA_PSK_AES;		// WPA-PSK(AES).
			break;
		case	PNLD_BTNID_Algorithm_Wpa2Psk_Tkip :
			m_e_Algorithm	= TYPE_ExNetworkEncryptAlg_WPA2_PSK_TKIP;	// WPA2-PSK(TKIP).
			break;
		case	PNLD_BTNID_Algorithm_Wpa2Psk_Aes :
			m_e_Algorithm	= TYPE_ExNetworkEncryptAlg_WPA2_PSK_AES;	// WPA2-PSK(AES)
			break;
		case	PNLD_BTNID_Algorithm_WpaWpa2Psk :
			m_e_Algorithm	= TYPE_ExNetworkEncryptAlg_WPA_PSK_Auto;	// WPA/WPA2-PSK.
			break;
		default:
			break;
	}
	setupGamen();
}
//================================================================================================.
// 概要		: PServiceNetWorkEXAlgorithmSetting : ネットワーク設定／拡張ﾈｯﾄﾜｰｸ設定／認証・暗号化アルゴリズム : 拡張ﾈｯﾄﾜｰｸキーボタン押下処理.
//================================================================================================.
void PServiceNetWorkEXAlgorithmSetting::procGoToPage( uchar option )
{
	switch( option ) {
		case	PNLD_BTNID_NetWorkEx_Up :
		case	PNLD_BTNID_NetWorkEx_Down :
			nextGamen = &gp_ServiceChannelSetting;
			break;
		default:
			break;
	}
}
//================================================================================================.
// 概要		: PServiceNetWorkEXWepKeySetting : ネットワーク設定／拡張ﾈｯﾄﾜｰｸ設定／WEPキー : 画面開始処理.
//================================================================================================.
void PServiceNetWorkEXWepKeySetting::startGamen()
{
	// 親クラスを呼ぶ.
	PServiceNetWorkEXCom::startGamen();
	// 「WEPキー」を選択状態とする.
	Rbt_ServiceNetWorkExMenu1.select( PNLD_NetWorkEXWepKey );	// WEPキー.

}
//================================================================================================.
// 概要		: PServiceNetWorkEXWepKeySetting : ネットワーク設定／拡張ﾈｯﾄﾜｰｸ設定／WEPキー : 画面更新処理.
//================================================================================================.
void PServiceNetWorkEXWepKeySetting::setupGamen( short option )
{
	char 		sc_DummyAsterisk[TYPD_WEPKeyMaxLen+1];
	memset( sc_DummyAsterisk, 0, sizeof( sc_DummyAsterisk ) );

	// WEPキーの選択を更新する
	Rbt_ServiceNetWorkExWepKey.select( static_cast<short>( m_st_WEPKeyData.uc_UseKey - 1 ) );

	// WEPキーの内容を更新する
	if( 0 != strlen( ( char* )m_st_WEPKeyData.uc_WEPKey1 ) ) {
		strcpy( sc_DummyAsterisk, "**********" );
	}
	else {
		strcpy( sc_DummyAsterisk, "\0" );
	}
	Btx_WepKey1Area.changeASCIIText( ( uchar* )sc_DummyAsterisk, ( short )strlen( sc_DummyAsterisk ) );

	if( 0 != strlen( ( char* )m_st_WEPKeyData.uc_WEPKey2 ) ) {
		strcpy( sc_DummyAsterisk, "**********" );
	}
	else {
		strcpy( sc_DummyAsterisk, "\0" );
	}
	Btx_WepKey2Area.changeASCIIText( ( uchar* )sc_DummyAsterisk, ( short )strlen( sc_DummyAsterisk ) );

	if( 0 != strlen( ( char* )m_st_WEPKeyData.uc_WEPKey3 ) ) {
		strcpy( sc_DummyAsterisk, "**********" );
	}
	else {
		strcpy( sc_DummyAsterisk, "\0" );
	}
	Btx_WepKey3Area.changeASCIIText( ( uchar* )sc_DummyAsterisk, ( short )strlen( sc_DummyAsterisk ) );

	if( 0 != strlen( ( char* )m_st_WEPKeyData.uc_WEPKey4 ) ) {
		strcpy( sc_DummyAsterisk, "**********" );
	}
	else {
		strcpy( sc_DummyAsterisk, "\0" );
	}
	Btx_WepKey4Area.changeASCIIText( ( uchar* )sc_DummyAsterisk, ( short )strlen( sc_DummyAsterisk ) );

	// 入力方式の選択を更新する
	switch( m_st_WEPKeyData.e_WEPKeyType ) {
		case	TYPE_WEPKeyType_Ascii5 :	// 半角英数記号 5文字.
			Rbt_ServiceNetWorkExWepKey_InPattern.select( PNLD_NetWorkEXWepKey_InTypeAscii5 );
			break;
		case	TYPE_WEPKeyType_Ascii13 :	// 半角英数記号 13文字.
			Rbt_ServiceNetWorkExWepKey_InPattern.select( PNLD_NetWorkEXWepKey_InTypeAscii13 );
			break;
		case	TYPE_WEPKeyType_Hex10 :		// 16進数10桁.
			Rbt_ServiceNetWorkExWepKey_InPattern.select( PNLD_NetWorkEXWepKey_InTypeHex10 );
			break;
		case	TYPE_WEPKeyType_Hex26 :		// 16進数26桁.
			Rbt_ServiceNetWorkExWepKey_InPattern.select( PNLD_NetWorkEXWepKey_InTypeHex26 );
			break;
		default:
			break;
	}
	// 親クラスを呼ぶ.
	PServiceNetWorkEXCom::setupGamen( option );

}
//================================================================================================.
// 概要		: PServiceNetWorkEXWepKeySetting : ネットワーク設定／拡張ﾈｯﾄﾜｰｸ設定／WEPキー : ボタン押下処理.
//================================================================================================.
void PServiceNetWorkEXWepKeySetting::procButtonOn( uchar option )
{
	// 親クラスを呼ぶ.
	PServiceNoFunctionCodeCom::procButtonOn( option );

	// 認証・暗号化アルゴリズムの選択を更新する
	switch( option ) {
		case	PNLD_BTNID_WepKey1 :			//  WEPキー1.
			m_st_WEPKeyData.uc_UseKey	= PNLD_NetWorkEXWepKey_WepKey1;
			break;
		case	PNLD_BTNID_WepKey2 :			//  WEPキー2.
			m_st_WEPKeyData.uc_UseKey	= PNLD_NetWorkEXWepKey_WepKey2;
			break;
		case	PNLD_BTNID_WepKey3 :			//  WEPキー3.
			m_st_WEPKeyData.uc_UseKey	= PNLD_NetWorkEXWepKey_WepKey3;
			break;
		case	PNLD_BTNID_WepKey4 :			//  WEPキー4.
			m_st_WEPKeyData.uc_UseKey	= PNLD_NetWorkEXWepKey_WepKey4;
			break;
		case	PNLD_BTNID_WepKeyInput_5Char :
			ClearWepKey( TYPE_WEPKeyType_Ascii5 );
			m_st_WEPKeyData.e_WEPKeyType	= TYPE_WEPKeyType_Ascii5;		// 半角英数記号5文字.
			break;
		case	PNLD_BTNID_WepKeyInput_13Char :
			ClearWepKey( TYPE_WEPKeyType_Ascii13 );
			m_st_WEPKeyData.e_WEPKeyType	= TYPE_WEPKeyType_Ascii13;		// 半角英数記号13文字.
			break;
		case	PNLD_BTNID_WepKeyInput16_10Char :
			ClearWepKey( TYPE_WEPKeyType_Hex10 );
			m_st_WEPKeyData.e_WEPKeyType	= TYPE_WEPKeyType_Hex10;		// 16進数10桁.
			break;
		case	PNLD_BTNID_WepKeyInput16_26Char :
			ClearWepKey( TYPE_WEPKeyType_Hex26 );
			m_st_WEPKeyData.e_WEPKeyType	= TYPE_WEPKeyType_Hex26;		// 16進数26桁.
			break;
		default:
			break;
	}
// Comment 2016/01/15 OPS1-Sky大濵 [ZeusS_ZX0][CQ524113] 反応総点検対応.
	setupGamen( option );
}
//================================================================================================.
// 概要		: PServiceNetWorkEXWepKeySetting : ネットワーク設定／拡張ﾈｯﾄﾜｰｸ設定／WEPキー : 拡張ﾈｯﾄﾜｰｸキーボタン押下処理.
//================================================================================================.
void PServiceNetWorkEXWepKeySetting::procGoToPage( uchar option )
{
	switch( option ) {
		case	PNLD_BTNID_WepKey1Edit :
		case	PNLD_BTNID_WepKey2Edit :
		case	PNLD_BTNID_WepKey3Edit :
		case	PNLD_BTNID_WepKey4Edit :
			// 選択WEPキーの保存 .
			m_uc_EditTargetWepKey = option ;

			if( ( TYPE_WEPKeyType_Ascii5  == m_st_WEPKeyData.e_WEPKeyType ) ||
			    ( TYPE_WEPKeyType_Ascii13 == m_st_WEPKeyData.e_WEPKeyType ) ) {
				// Ascii入力
				nextGamen = &gp_ServiceNetWorkEXWepKeyASCIIInputNew ;
			}
			else {
				// 16進入力
				nextGamen = &gp_ServiceNetWorkEXWepKeyHexInputNew;
			}
			break;
		case	PNLD_BTNID_NetWorkEx_Up :
		case	PNLD_BTNID_NetWorkEx_Down :
			nextGamen = &gp_ServiceChannelSetting;
			break;
		default:
			break;
	}
}
//================================================================================================.
// 概要		: PServiceNetWorkEXWepKeySetting : ネットワーク設定／拡張ﾈｯﾄﾜｰｸ設定／WEPキー : Wepキークリア処理.
//================================================================================================.
void PServiceNetWorkEXWepKeySetting::ClearWepKey( TYPE_WEPKeyType e_WepKeyType )
{
	// 入力方式が変更された場合
	if( e_WepKeyType != m_st_WEPKeyData.e_WEPKeyType ) {
		strcpy( ( char* )m_st_WEPKeyData.uc_WEPKey1, "\0" );
		strcpy( ( char* )m_st_WEPKeyData.uc_WEPKey2, "\0" );
		strcpy( ( char* )m_st_WEPKeyData.uc_WEPKey3, "\0" );
		strcpy( ( char* )m_st_WEPKeyData.uc_WEPKey4, "\0" );
	}
}

//================================================================================================.
// 概要		: PServiceNetWorkEXPassPhraseSetting : ネットワーク設定／拡張ﾈｯﾄﾜｰｸ設定／パスフレーズ : 画面開始処理.
//================================================================================================.
void PServiceNetWorkEXPassPhraseSetting::startGamen()
{
	// 親クラスを呼ぶ.
	PServiceNetWorkEXCom::startGamen();
	// 「パスフレーズ」を選択状態とする.
	Rbt_ServiceNetWorkExMenu1.select( PNLD_NetWorkEXPassPhrase );	// パスフレーズ.

}
//================================================================================================.
// 概要		: PServiceNetWorkEXPassPhraseSetting : ネットワーク設定／拡張ﾈｯﾄﾜｰｸ設定／パスフレーズ : 画面更新処理.
//================================================================================================.
void PServiceNetWorkEXPassPhraseSetting::setupGamen( short option )
{
	char 		sc_DummyAsterisk[TYPD_WEPKeyMaxLen+1];
	memset( sc_DummyAsterisk, 0, sizeof( sc_DummyAsterisk ) );

	// 親クラスを呼ぶ.
	PServiceNetWorkEXCom::setupGamen( option );

	// パスフレーズの選択を更新する
	Rbt_ServiceNetWorkExPassPhrase.select( PNLD_NetWorkEXPassPhrase_Key );						// キー値

	// パスフレーズ更新間隔の表示 / 非表示 .
	Bool bl_ShowPassPhraseUpdateIntarval = ( True == m_bl_PassPhraseAutoUpdate )? True : False ;
	Key_PassPhraseUpdate.showEnable( bl_ShowPassPhraseUpdateIntarval ) ;

	// パスフレーズの内容を更新する
	if( 0 != strlen( ( char* )m_uc_PassPhrase ) ) {
		strcpy( sc_DummyAsterisk, "**********" );
	}
	else {
		strcpy( sc_DummyAsterisk, "\0" );
	}
	Btx_PassPhraseKey.changeASCIIText( ( uchar* )sc_DummyAsterisk, ( short )strlen( sc_DummyAsterisk ) );

	// 入力方式の選択を更新する
	switch( m_e_PassPhraseType ) {
		case	TYPE_PassphraseType_ASCII :	// 半角英数記号.
			Rbt_ServiceNetWorkExPassPhrase_InPattern.select( PNLD_NetWorkEXPassPhrase_InTypeAscii );
			break;
		case	TYPE_PassphraseType_HEX :	// 16進数.
			Rbt_ServiceNetWorkExPassPhrase_InPattern.select( PNLD_NetWorkEXPassPhrase_InTypeHex );
			break;
		default:
			break;
	}
}
//================================================================================================.
// 概要		: PServiceNetWorkEXPassPhraseSetting : ネットワーク設定／拡張ﾈｯﾄﾜｰｸ設定／パスフレーズ : ボタン押下処理.
//================================================================================================.
void PServiceNetWorkEXPassPhraseSetting::procButtonOn( uchar option )
{
	// 親クラスを呼ぶ.
	PServiceNoFunctionCodeCom::procButtonOn( option );

	// 認証・暗号化アルゴリズムの選択を更新する
	switch( option ) {
		case	PNLD_BTNID_PhraseKeyInput_Ascii :
			ClearPassPhrase( TYPE_PassphraseType_ASCII );
			m_e_PassPhraseType	= TYPE_PassphraseType_ASCII;		// 半角英数記号.
			break;
		case	PNLD_BTNID_PhraseKeyInput_Hex :
			ClearPassPhrase( TYPE_PassphraseType_HEX );
			m_e_PassPhraseType	= TYPE_PassphraseType_HEX;			// 16進数.
			break;

		default:
			break;
	}
	setupGamen();
}

//================================================================================================.
// 概要		: PServiceNetWorkEXPassPhraseSetting : ネットワーク設定／拡張ﾈｯﾄﾜｰｸ設定／パスフレーズ : パスフレーズセキュリティキー値クリア処理.
//================================================================================================.
void PServiceNetWorkEXPassPhraseSetting::ClearPassPhrase( TYPE_PassphraseType e_PassPhraseType )
{
	// 入力方式が変更された場合
	if( m_e_PassPhraseType != e_PassPhraseType ) {
		memset( m_uc_PassPhrase, '\0' , sizeof( m_uc_PassPhrase ) );
	}
}

//================================================================================================.
// 概要		: PServiceNetWorkEXPassPhraseSetting : ネットワーク設定／拡張ﾈｯﾄﾜｰｸ設定／パスフレーズ : 拡張ﾈｯﾄﾜｰｸキーボタン押下処理.
//================================================================================================.
void PServiceNetWorkEXPassPhraseSetting::procGoToPage( uchar option )
{
	switch( option ) {
		case	PNLD_BTNID_PassPhraseAuto :
			nextGamen = &gp_ServiceNetWorkExAutoUpdateSetting;
			break;
		case	PNLD_BTNID_PassPhraseUpdate :
			nextGamen = &gp_ServiceNetWorkExUpdateIntervalSetting;
			break;
		case	PNLD_BTNID_PassPhraseComSet :
			nextGamen = &gp_ServiceNetWorkExHzSetting;
			break;
		case	PNLD_BTNID_NetWorkEx_Up :
		case	PNLD_BTNID_NetWorkEx_Down :
			nextGamen = &gp_ServiceChannelSetting;
			break;
		case	PNLD_BTNID_PhraseKeyEdit :
			if( TYPE_PassphraseType_ASCII  == m_e_PassPhraseType ) {
				// Ascii入力
				nextGamen = &gp_ServiceNetWorkEXPassPhraseKeyboardInputNew ;
			}
			else {
				// 16進入力
				nextGamen = &gp_ServiceNetWorkEXPassPhraseHexInputNew;
			}
			break;
		case	PNLD_BTNID_PassPhraseKey :
		default:
			break;
	}
}


//============================================================================================.
//
// PServiceNetWorkEXPassPhraseKeyboardInputCom : 93B316XX サービス・拡張ネットワーク設定／パスフレーズASCII入力共通 .
//
//============================================================================================.
uchar						PServiceNetWorkEXPassPhraseKeyboardInputCom::m_uc_PassPhraseChangeTemp[ PNLD_NetWorkEXPassPhraseASCIIMaxLen + 1 ] ;				// パスフレーズ変更用の仮バッファ .


//============================================================================================.
//
// PServiceNetWorkEXPassPhraseKeyboardInputNew : 93B31610 サービス・拡張ネットワーク設定／パスフレーズASCII入力 .
//
//============================================================================================.

//================================================================================================.
// 概要		: PServiceNetWorkEXPassPhraseKeyboardInputNew : 93B31610 サービス・拡張ネットワーク設定／パスフレーズASCII入力 .
//================================================================================================.
PServiceNetWorkEXPassPhraseKeyboardInputNew::PServiceNetWorkEXPassPhraseKeyboardInputNew( PDisplayParts** partsTable, short partsNumber, Bool isNoWarning )
	: PServiceNetWorkEXPassPhraseKeyboardInputCom( partsTable, partsNumber, isNoWarning )
{
	// 初期化.
	m_ss_Tx = PNLD_ServiceNetworkExKeyboardComTx ;
	m_ss_Gy = PNLD_ServiceNetworkExKeyboardComGy ;
	m_pc_DispField = &Btx_ServiceNewWorkExKeyboardComInput;
	m_e_CharSet = EP_CharSet_USASCII;
}
//================================================================================================.
// 概要		: PServiceNetWorkEXPassPhraseKeyboardInputNew : 93B31610 サービス・拡張ネットワーク設定／パスフレーズASCII入力 : 画面開始処理.
//================================================================================================.
void PServiceNetWorkEXPassPhraseKeyboardInputNew::startGamen()
{
	// Tempをクリア .
	memset( m_uc_PassPhraseChangeTemp, '\0', sizeof( m_uc_PassPhraseChangeTemp ) ) ;

	// '\0'で初期化 .
	memset( m_sc_StrKeyboard, '\0', sizeof( m_sc_StrKeyboard ) ) ;

	// 表示領域に文字列をセット.
	setKeyboardData( m_sc_StrKeyboard, PNLD_NetWorkEXPassPhraseASCIIMaxLen , PNLD_ServiceNetworkExKeyboardComInputViewLen ) ;

	// パスワード入力 .
	m_b_Password = True ;

	// 事前入力チェック .
	if( strlen( m_sc_StrKeyboard ) > 0 ) {
		m_b_ShowPass = True ;
	} else {
		m_b_ShowPass = False ;
	}

	// 親クラスを呼ぶ.
	PServiceNetWorkEXPassPhraseKeyboardInputCom::startGamen();
}
//================================================================================================.
// 概要		: PServiceNetWorkEXPassPhraseKeyboardInputNew : 93B31610 サービス・拡張ネットワーク設定／パスフレーズASCII入力 : キャンセル処理.
//================================================================================================.
void PServiceNetWorkEXPassPhraseKeyboardInputNew::procCancel( uchar option )
{
	nextGamen = &gp_ServiceNetWorkEXPassPhraseSetting;
}
//================================================================================================.
// 概要		: PServiceNetWorkEXPassPhraseKeyboardInputNew : 93B31610 サービス・拡張ネットワーク設定／パスフレーズASCII入力 : Okキー押下処理.
//================================================================================================.
void PServiceNetWorkEXPassPhraseKeyboardInputNew::procOk( uchar option )
{
	if( PNLD_NetWorkEXPassPhraseASCIIMinLen > strlen( ( char* )m_sc_StrKeyboard ) ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}
	// '\0'で初期化 .
	memset( m_uc_PassPhraseChangeTemp, '\0', sizeof( m_uc_PassPhraseChangeTemp ) ) ;
	// バッファから反映 .
	memcpy( m_uc_PassPhraseChangeTemp, m_sc_StrKeyboard, sizeof( m_uc_PassPhraseChangeTemp ) - 1 ) ;

	// 画面遷移
	nextGamen = &gp_ServiceNetWorkEXPassPhraseKeyboardInputRetry ;
}

//============================================================================================.
//
// PServiceNetWorkEXPassPhraseKeyboardInputRetry : 93B31630 サービス・拡張ネットワーク設定／パスフレーズASCII再入力 .
//
//============================================================================================.

//================================================================================================.
// 概要		: PServiceNetWorkEXPassPhraseKeyboardInputRetry : 93B31630 サービス・拡張ネットワーク設定／パスフレーズASCII再入力 .
//================================================================================================.
PServiceNetWorkEXPassPhraseKeyboardInputRetry::PServiceNetWorkEXPassPhraseKeyboardInputRetry( PDisplayParts** partsTable, short partsNumber, Bool isNoWarning )
	: PServiceNetWorkEXPassPhraseKeyboardInputCom( partsTable, partsNumber, isNoWarning )
{
	// 初期化.
	m_ss_Tx = PNLD_ServiceNetworkExKeyboardComTx ;
	m_ss_Gy = PNLD_ServiceNetworkExKeyboardComGy ;
	m_pc_DispField = &Btx_ServiceNewWorkExKeyboardComInput ;
	m_e_CharSet = EP_CharSet_USASCII;
}
//================================================================================================.
// 概要		: PServiceNetWorkEXPassPhraseKeyboardInputRetry : 93B31630 サービス・拡張ネットワーク設定／パスフレーズASCII再入力 : 画面開始処理.
//================================================================================================.
void PServiceNetWorkEXPassPhraseKeyboardInputRetry::startGamen()
{
	// '\0'で初期化 .
	memset( m_sc_StrKeyboard, '\0', sizeof( m_sc_StrKeyboard ) ) ;

	// 表示領域に文字列をセット.
	setKeyboardData( m_sc_StrKeyboard, PNLD_NetWorkEXPassPhraseASCIIMaxLen , PNLD_ServiceNetworkExKeyboardComInputViewLen ) ;

	// パスワード入力 .
	m_b_Password = True ;

	// 確認入力は常初期値ブランクなのでパスワード入力済みはなし .
	m_b_ShowPass = False ;

	// 親クラスを呼ぶ.
	PServiceNetWorkEXPassPhraseKeyboardInputCom::startGamen();
}
//================================================================================================.
// 概要		: PServiceNetWorkEXPassPhraseKeyboardInputRetry : 93B31630 サービス・拡張ネットワーク設定／パスフレーズASCII再入力 : キャンセル処理.
//================================================================================================.
void PServiceNetWorkEXPassPhraseKeyboardInputRetry::procCancel( uchar option )
{
	nextGamen = &gp_ServiceNetWorkEXPassPhraseSetting;
}
//================================================================================================.
// 概要		: PServiceNetWorkEXPassPhraseKeyboardInputRetry : 93B31630 サービス・拡張ネットワーク設定／パスフレーズASCII再入力 : Okキー押下処理.
//================================================================================================.
void PServiceNetWorkEXPassPhraseKeyboardInputRetry::procOk( uchar option )
{
	if( PNLD_NetWorkEXPassPhraseASCIIMinLen > strlen( ( char* )m_sc_StrKeyboard ) ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}
	// 遷移先画面 .
	PBasicMessageProc*	p_preNextGamen = NULL ;

	// 1回目の入力と一致しているかチェック .
	if( 0 == strcmp( ( char* )m_uc_PassPhraseChangeTemp, m_sc_StrKeyboard ) ) {
		memcpy( m_uc_PassPhrase, m_uc_PassPhraseChangeTemp, sizeof( m_uc_PassPhrase ) ) ;
		p_preNextGamen = &gp_ServiceNetWorkEXPassPhraseSetting ;			// 一致した場合は上位画面へ抜ける .
	} else {
		p_preNextGamen = &gp_ServiceNetWorkEXPassPhraseKeyboardInputNew ;	// 一致しない場合は最初から入力しなおし .
	}

	// 画面遷移 .
	nextGamen = p_preNextGamen ;
}

