void PServiceNetWorkExAutoUpdateSetting::setupGamen( short option )
{
	// 親クラスを呼ぶ.
	PServiceNetWorkEXCom::setupGamen( option );

	// 固定 .
	Rbt_ServiceNetWorkExMenu1.select( PNLD_NetWorkEXPassPhrase ) ;				// 左方メニュー「パスフレーズ」を選択状態とする.
	Rbt_ServiceNetWorkExPassPhrase.select( PNLD_NetWorkEXPassPhrase_Auto ) ;	// 上方メニュー「自動更新」を選択状態とする

	// 動的に変更 .
	short ss_PassPhraseAutoSelect = ( True == m_bl_PassPhraseAutoUpdate )? 0 : 1 ;
	Rbt_ServiceNetworkExPassPhraseAuto.select( ss_PassPhraseAutoSelect ) ;	// する／しない .

	// パスフレーズ更新間隔の表示 / 非表示 .
	Bool bl_ShowPassPhraseUpdateIntarval = ( True == m_bl_PassPhraseAutoUpdate )? True : False ;
	Key_PassPhraseUpdate.showEnable( bl_ShowPassPhraseUpdateIntarval ) ;
}
