//================================================================================================.
// 概要		: PServiceNetWorkExUpdateIntervalSetting : 拡張ネットワーク設定／パスフレーズ更新間隔 : 10キー入力.
//================================================================================================.
void PServiceNetWorkExUpdateIntervalSetting::proc10Key( uchar option )
{
	Bool b_isError = False;

	// 接続タイムアウトを更新する.
	m_us_PassPhraseAutoUpdateInterval = ( ushort )proc10KeyInput(	m_us_PassPhraseAutoUpdateInterval,
	                                    1440,
	                                    option,
	                                    m_b_Direct,
	                                    EP_InputMaxLimitPattern_Refuse,
	                                    &b_isError ) ;

	if( True == b_isError ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );					// ブザー音セット.
	} else {
		if( True == m_b_Direct && 1 > option ) {
			MCR_setBuzzerType( PCGE_BuzzerType_InputNg );				// ブザー音セット.
		} else {
			m_b_Direct = False;
		}
	}

	setupGamen( option );															// 画面更新を行う.
}

//================================================================================================.
// 概要		: PServiceNetWorkExUpdateIntervalSetting : 拡張ネットワーク設定／パスフレーズ更新間隔 : クリアキー入力.
//================================================================================================.
void PServiceNetWorkExUpdateIntervalSetting::procClear( uchar option )
{
	m_us_PassPhraseAutoUpdateInterval = 0 ;								// 間隔を0にする.
	m_b_Direct = True ;

	setupGamen( option );												// 画面更新を行う.
}


