//============================================================================================.
// PServiceChannelSetting : 93B31700_拡張ネットワーク設定／チャンネル設定.
// 概要		: 画面開始処理.
//============================================================================================.
void PServiceChannelSetting::startGamen()
{
	// 親クラスを呼ぶ.
	PServiceNetWorkEXCom::startGamen();
	Rbt_ServiceNetWorkExMenu2.select( PNLD_NetWorkEXP2_Channel );

	// 現在の無線LAN仕向を取得する.
	TYPE_CountryCode e_WirelessLANDestination = pc_MachineSetting->getWirelessLANDestinationSetting();

	// 範囲表示の切り替え.
	switch( e_WirelessLANDestination ) {
		case TYPE_CountryCode_US:
// comment 2016/04/12 OPS1-Sky竹内 [ZeusSBK][CQ527333] RQ-340_仕様変更対応(チャンネル範囲変更).
// comment 2016/05/16 OPS1-Sky能多 [ZeusSBK][CQ529211] 無線LAN仕向け2.4/5GHz各国チャンネル仕様変更. CA,TWの条件を再活性化.
		case TYPE_CountryCode_CA:
		case TYPE_CountryCode_TW:
			Txt_ChannelSetting1_13.changeText( s_NOTITM1to11 );		// 1 - 11.
			break;
		default:
			Txt_ChannelSetting1_13.changeText( s_NOTITM1to13 );
			break;
	}
}
//============================================================================================.
// PServiceChannelSetting : 93B31700_拡張ネットワーク設定／チャンネル設定.
// 概要		: 画面更新処理.
//============================================================================================.
void PServiceChannelSetting::setupGamen( short option )
{
	// 親クラスを呼ぶ.
	PServiceNetWorkEXCom::setupGamen( option );
	if( 0 == m_uc_channel ) {
		Key_ChannelAuto.select( True );				// 自動キー選択状態.
		Btx_ChannelSetting.showEnableAdd( False );	// 値を表示.
	} else {
		Key_ChannelAuto.select( False );				// 自動キー非選択状態.
		Btx_ChannelSetting.showEnableAdd( True );	// 値を表示.
		Btx_ChannelSetting.set( ( float )m_uc_channel, True );	// 値を表示.
	}
}
//============================================================================================.
// PServiceChannelSetting : 93B31700_拡張ネットワーク設定／チャンネル設定.
// 概要		: ボタン押下処理.
//============================================================================================.
void PServiceChannelSetting::procButtonOn( uchar option )
{
	switch( option ) {
		case PNLD_BTNID_NetWorkEx_Idx_ChannelAuto:			// 自動.
			m_uc_channel = 0;
			break;
		default:
			PServiceNetWorkEXCom::procButtonOn( option );
			break;
	}
	setupGamen();	// 表示部品のセットアップ.
}
//============================================================================================.
// PServiceChannelSetting : 93B31700_拡張ネットワーク設定／チャンネル設定.
// 概要		: ボタン押下処理(画面遷移).
//============================================================================================.
void PServiceChannelSetting::procGoToPage( uchar option )
{
	switch( option ) {
		case	PNLD_BTNID_NetWorkEx_Up :
		case	PNLD_BTNID_NetWorkEx_Down :
			nextGamen = &gp_ServiceNetWorkEX2ndCardSetting;
			break;
		default:
			break;
	}
}
//============================================================================================.
// PServiceChannelSetting : 93B31700_拡張ネットワーク設定／チャンネル設定.
// 概要		: 10キー入力.
//============================================================================================.
void PServiceChannelSetting::proc10Key( uchar option )
{
	Bool b_isError = False;

	// 現在の無線LAN仕向を取得する.
	TYPE_CountryCode e_WirelessLANDestination = pc_MachineSetting->getWirelessLANDestinationSetting();

	// 接続タイムアウトを更新する.
	switch( e_WirelessLANDestination ) {
		case TYPE_CountryCode_US:
// comment 2016/04/12 OPS1-Sky竹内 [ZeusSBK][CQ527333] RQ-340_仕様変更対応(チャンネル範囲変更).
// comment 2016/05/16 OPS1-Sky能多 [ZeusSBK][CQ529211] 無線LAN仕向け2.4/5GHz各国チャンネル仕様変更. CA,TWの条件を再活性化.
		case TYPE_CountryCode_CA:
		case TYPE_CountryCode_TW:
			m_uc_channel = ( uchar )proc10KeyInput(	m_uc_channel,
			                                        11,
			                                        option,
			                                        m_bl_Direct,
			                                        EP_InputMaxLimitPattern_Refuse,
			                                        &b_isError ) ;
			break;
		default:
			m_uc_channel = ( uchar )proc10KeyInput(	m_uc_channel,
			                                        13,
			                                        option,
			                                        m_bl_Direct,
			                                        EP_InputMaxLimitPattern_Refuse,
			                                        &b_isError ) ;
			break;
	}

	if( True == b_isError ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );					// ブザー音セット.
	} else {
		if( True == m_bl_Direct && 1 > option ) {
			MCR_setBuzzerType( PCGE_BuzzerType_InputNg );				// ブザー音セット.
		} else {
			m_bl_Direct = False;
		}
	}

	setupGamen( option );															// 画面更新を行う.
}
