//============================================================================================.
// PServiceInputMACAddressSetting : 93B31910_拡張ネットワーク設定／接続許可子機MACアドレス入力.
// 概要		: 画面開始処理.
//============================================================================================.
void PServiceInputMACAddressSetting::startGamen()
{
	// 親クラスを呼ぶ.
	PServiceNetWorkEXCom::startGamen();
	uchar uc_MACAddress[APID_ConnectClientMacAdrLength];
	memset( uc_MACAddress, 0, sizeof( uc_MACAddress ) );

	m_sc_InputPosition = 0;		// 入力エリア.
	memset(	m_uc_AdressValue, 0, sizeof( m_uc_AdressValue ) );	// MACアドレスス入力値.
	for( register short j = 0 ; j < PNLD_ServiceInputMAC_MACNum ; j++ ) {
		m_bl_Fixed[j] = True;		// MACアドレス確定フラグ.
		m_bl_Direct[j] = True;	// MACアドレスダイレクト入力.
	}
	m_bl_Fixed[0] = False;		// 確定フラグOFF.

	CharToMACAddress( m_uc_MACAddress[m_uc_selectMACNum] , m_uc_AdressValue );
}
//============================================================================================.
// PServiceInputMACAddressSetting : 93B31910_拡張ネットワーク設定／接続許可子機MACアドレス入力.
// 概要		: 画面更新処理.
//============================================================================================.
void PServiceInputMACAddressSetting::setupGamen( short option )
{
	// 親クラスを呼ぶ.
	PServiceNetWorkEXCom::setupGamen( option );
	TEXT_ID textId = s_TTLServiceInputMACAddress1;
	switch( m_uc_selectMACNum ) {
		case 0:
			textId = s_TTLServiceMACAddress1;
			break;
		case 1:
			textId = s_TTLServiceMACAddress2;
			break;
		case 2:
			textId = s_TTLServiceMACAddress3;
			break;
		case 3:
			textId = s_TTLServiceMACAddress4;
			break;
		case 4:
			textId = s_TTLServiceMACAddress5;
			break;
		default:
			break;
	}
	Txt_TitleInputMACAddressSetting.changeText( textId );
	for( register short i = 0 ; i < PNLD_ServiceInputMAC_MACNum ; i++ ) {				// MACアドレスの数値を順に表示&カーソル表示する.
		Btx_InputMACAddressSetting.changeASCIIText( &Tfd_InputMACAddressSetting[i], ( uchar* )m_uc_AdressValue[i], sizeof( m_uc_AdressValue[i] ) );	// 入力で扱うアドレス値を表示.
		Btx_InputMACAddressSetting.showEnableAdd( &Gra_InputMACAddressSetting[i], ( i == m_sc_InputPosition ? True : False ) );						// カーソルの表示（入力選択位置）（左から０～７）.
	}
}
//============================================================================================.
// PServiceInputMACAddressSetting : 93B31910_拡張ネットワーク設定／接続許可子機MACアドレス入力.
// 概要		: ボタン押下処理.
//============================================================================================.
void PServiceInputMACAddressSetting::procButtonOn( uchar option )
{
	uchar uc_StringLen = 0;	// 文字列の長さを測る用.
	switch( option ) {
		case PNLD_BTNID_NetWorkEx_Idx_MACLeft:		// ←キー.
			if( m_sc_InputPosition > 0 ) {
				m_bl_Direct[m_sc_InputPosition] = True;		// ダイレクト入力.
				m_bl_Fixed[ m_sc_InputPosition] = True;		// 確定フラグON.
				m_sc_InputPosition--;
				m_bl_Fixed[ m_sc_InputPosition] = False;	// 確定フラグOFF.
			}
			break;
		case PNLD_BTNID_NetWorkEx_Idx_MACRight:		// →キー.
			if( m_sc_InputPosition < ( PNLD_ServiceInputMAC_MACNum - 1 ) ) {
				m_bl_Direct[m_sc_InputPosition] = True;		// ダイレクト入力.
				m_bl_Fixed[ m_sc_InputPosition] = True;		// 確定フラグON.
				m_sc_InputPosition++;
				m_bl_Fixed[ m_sc_InputPosition] = False;	// 確定フラグOFF.
			}
			break;
		case PNLD_BTNID_NetWorkEx_Idx_MACInputA:	// aキー.
		case PNLD_BTNID_NetWorkEx_Idx_MACInputB:	// bキー.
		case PNLD_BTNID_NetWorkEx_Idx_MACInputC:	// cキー.
		case PNLD_BTNID_NetWorkEx_Idx_MACInputD:	// dキー.
		case PNLD_BTNID_NetWorkEx_Idx_MACInputE:	// eキー.
		case PNLD_BTNID_NetWorkEx_Idx_MACInputF:	// fキー.
			if( True == m_bl_Direct[ m_sc_InputPosition ] ) {	// ダイレクト入力がTrueの場合、エリア内の値をクリアしてから入力.
				memset( m_uc_AdressValue[ m_sc_InputPosition ], 0, sizeof( m_uc_AdressValue[ m_sc_InputPosition ] ) );
			}
			uc_StringLen = ( uchar )strlen( ( char* )m_uc_AdressValue[ m_sc_InputPosition ] );	// 現在エリア内にどれだけ文字列が入力されているか？
			if( uc_StringLen < PNLD_ServiceInputMAC_MACString ) {	// エリア内の文字が2文字に達している場合は受付けない.
				m_uc_AdressValue[ m_sc_InputPosition ][uc_StringLen] = static_cast<uchar>( 'a' + ( option - PNLD_BTNID_NetWorkEx_Idx_MACInputA ) );
				m_bl_Direct[ m_sc_InputPosition ] = False;	// ダイレクト入力解除.
			}
			break;
		default: break;
	}
	setupGamen();
}
//============================================================================================.
// PServiceInputMACAddressSetting : 93B31910_拡張ネットワーク設定／接続許可子機MACアドレス入力.
// 概要		: OKキー押下.
//============================================================================================.
void PServiceInputMACAddressSetting::procOk( uchar option )
{
	Bool bl_inputString = False;
	uchar uc_StringLen = 0;
	for( uchar i = 0; i < PNLD_ServiceInputMAC_MACNum; i++ ) {
		uc_StringLen = ( uchar )strlen( ( char* )m_uc_AdressValue[ i ] );
		if( 0 == uc_StringLen ) {
			m_uc_AdressValue[i][0] = '0';
			m_uc_AdressValue[i][1] = '0';
		} else if( 1 == uc_StringLen ) {
			bl_inputString = True;
			m_uc_AdressValue[i][1] = m_uc_AdressValue[i][0];
			m_uc_AdressValue[i][0] = '0';
		} else {
			bl_inputString = True;
		}
	}
	if( False == bl_inputString ) {
		memset( m_uc_MACAddress[m_uc_selectMACNum], '\0', sizeof( m_uc_MACAddress[m_uc_selectMACNum] ) );
	} else {
		MACAddressToChar( m_uc_AdressValue , m_uc_MACAddress[m_uc_selectMACNum] );
	}
	nextGamen = &gp_ServiceConnectionPermitHandsetMAC;
}
//============================================================================================.
// PServiceInputMACAddressSetting : 93B31910_拡張ネットワーク設定／接続許可子機MACアドレス入力.
// 概要		: 10キー入力.
//============================================================================================.
void PServiceInputMACAddressSetting::proc10Key( uchar option )
{
	char _sc_CharAddress[2];
	memset( _sc_CharAddress, 0, sizeof( _sc_CharAddress ) );
	snprintf( _sc_CharAddress, sizeof(_sc_CharAddress), "%d", option );	// 10キー入力された数値を文字に変換.
	if( True == m_bl_Direct[ m_sc_InputPosition ] ) {	// ダイレクト入力がTrueの場合、エリア内の値をクリアしてから入力.
		memset( m_uc_AdressValue[ m_sc_InputPosition ], 0, sizeof( m_uc_AdressValue[ m_sc_InputPosition ] ) );
	}
	uchar uc_StringLen = static_cast<uchar>( strlen( ( char* )m_uc_AdressValue[ m_sc_InputPosition ] ) );	// 現在エリア内にどれだけ文字列が入力されているか？
	if( uc_StringLen < PNLD_ServiceInputMAC_MACString ) {	// エリア内の文字が4文字に達している場合は受付けない.
		m_uc_AdressValue[ m_sc_InputPosition ][uc_StringLen] = _sc_CharAddress[0];	// 現在の文字列の末尾に文字を追加する.
		m_bl_Direct[ m_sc_InputPosition ] = False;	// ダイレクト入力解除.
		m_bl_Fixed[m_sc_InputPosition] = True;		// 表示を確定表示.
	}
	setupGamen( option );															// 画面更新を行う.
}
//============================================================================================.
// PServiceInputMACAddressSetting : 93B31910_拡張ネットワーク設定／接続許可子機MACアドレス入力.
// 概要		: クリアキー入力.
//============================================================================================.
void PServiceInputMACAddressSetting::procClear( uchar option )
{
	for( uchar i = 0; i < PNLD_ServiceInputMAC_MACString; i++ ) {
		m_uc_AdressValue[m_sc_InputPosition][i] = '\0';	// 入力値.
	}
	m_bl_Direct[ m_sc_InputPosition ] = True;		// ダイレクト入力ON
	m_bl_Fixed[  m_sc_InputPosition ] = False;		// 未確定
	setupGamen( option );															// 画面更新を行う.
}
//============================================================================================.
// PServiceInputMACAddressSetting : 93B31910_拡張ネットワーク設定／接続許可子機MACアドレス入力.
// 概要		: 文字列をMACアドレスに変換.
//============================================================================================.
void PServiceInputMACAddressSetting::CharToMACAddress(
    const uchar* _uc_CharAddress,	// アドレス文字列
    uchar _uc_MACAddress[][PNLD_ServiceInputMAC_MACString + 1]				//ＩＰアドレス変換後格納用
)
{
	short _ss_point = 0;		// 現在のエリアのカウンタ(0～5).
	unsigned char uc_Count = 0;	// 1つのエリア(:～:の間)内のカウンタ (0～3).
	char sc_pre[10];			// 1つのエリア内の文字列仮保存.
	memset( sc_pre, 0, sizeof( sc_pre ) );
	Bool b_loop = True;		// ループを続けるかを判断.
	while( b_loop )
	{
		if( ( *_uc_CharAddress >= 0x30 && *_uc_CharAddress <=0x39 ) || ( *_uc_CharAddress >= 0x61 && *_uc_CharAddress <= 0x66 ) ) {	// 数字０～９、a～fの場合
			sc_pre[uc_Count] = *_uc_CharAddress;	// チェックした文字を仮保存.
			uc_Count++;		// エリア内のカウンタを+する.
			if( uc_Count > PNLD_ServiceInputMAC_MACString ) {	// 1つのエリアに2桁以上の文字列が検知された場合、処理を中止.
				b_loop = False;
			}
		} else if( *_uc_CharAddress == 0x3a || *_uc_CharAddress == 0x00 ) {	// 「：」、「NULL」の場合
			uc_Count = 0;	// エリア内カウンタをクリア.
			strcpy( ( char* )_uc_MACAddress[_ss_point], sc_pre );	// エリア内の文字列を格納先へ渡す
			_ss_point++;		// 現在のエリアを1つ進める.
			memset( sc_pre, 0, sizeof( sc_pre ) );	// 仮保存場所をクリアしておく
			if( _ss_point > 5 ) {	// 現在のエリアが5より大きくなった場合、MACアドレス形式ではないのでloop処理を中止.
				b_loop = False;
			}
		} else {	// 「：」以外の文字が入った場合、MAC形式ではないのでloop処理を中止.
			// その他の文字
			b_loop = False;
		}
		_uc_CharAddress++;	// 変換元の文字列のアドレスを+する.
	}
}
//============================================================================================.
// PServiceInputMACAddressSetting : 93B31910_拡張ネットワーク設定／接続許可子機MACアドレス入力.
// 概要		: MACアドレスを文字列に変換.
//============================================================================================.
void PServiceInputMACAddressSetting::MACAddressToChar(
    const uchar _uc_MACAddress[][PNLD_ServiceInputMAC_MACString + 1],	//ＩＰアドレス
    uchar* _uc_CharAddress			// 文字列変換後格納用
)
{
	memset(	_uc_CharAddress, 0, PNLD_ServiceInputMAC_MACString * PNLD_ServiceInputMAC_MACNum + 6 );		// MACアドレス入力値.
	for( short i = 0; i < PNLD_ServiceInputMAC_MACNum; i++ ) {
		strcat( ( char* )_uc_CharAddress, ( char* )_uc_MACAddress[i] );	// : を末尾につける
		if( i < 5 ) {
			strcat( ( char* )_uc_CharAddress, ":" );					// : を末尾につける
		}
	}
}

