{
	// 親クラスを呼ぶ.
	PServiceNetWorkEXCom::startGamen();
	Rbt_ServiceNetWorkExMenu2.select( PNLD_NetWorkEXP2_DHCP );
	Rbt_ServiceNetWorkExDHCP.select( PNLD_NetWorkEXP2_DHCPIPv4Lease );

	m_uc_select = PNLD_NetWorkEXP2_DHCPIPv4LeaseHead;
	m_sc_InputPositionHead = 0;
	m_sc_InputPositionLast = 0;
	for( register short i = 0 ; i < PNLD_ServiceIPv4Address_IPv4Num ; i++ ) {
		m_bl_FixedHead[i] = True;
		m_bl_FixedLast[i] = True;
		m_bl_DirectHead[i] = True;
		m_bl_DirectLast[i] = True;
	}

	CharToIPAddress( ( char* )m_uc_IPv4LeaseAddressHead, ( uchar* )m_uc_AdressValueHead );	// 取得した文字列をIPアドレス形式に変換.
	CharToIPAddress( ( char* )m_uc_IPv4LeaseAddressLast, ( uchar* )m_uc_AdressValueLast );	// 取得した文字列をIPアドレス形式に変換.
}
//============================================================================================.
// PServiceIPv4LeaseAddressSetting : 93B31A10_拡張ネットワーク設定／DHCPサーバー設定IPv4リースアドレス設定.
// 概要		: 画面更新処理.
//============================================================================================.
void PServiceIPv4LeaseAddressSetting::setupGamen( short option )
{
	// 親クラスを呼ぶ.
	PServiceNetWorkEXCom::setupGamen( option );
	Rbt_IPv4LeaseAddressSetting.select( m_uc_select );
	if( PNLD_NetWorkEXP2_DHCPIPv4LeaseHead ==  m_uc_select ) {
		for( register short i = 0 ; i < PNLD_ServiceIPv4Address_IPv4Num ; i++ ) {				// ＩＰアドレスの数値を順に表示&カーソル表示する
			Btx_IPv4LeaseAddressSettingLastInput.set( &Nmb_IPv4LeaseAddressSettingLast[i], m_uc_AdressValueLast[i], True );						// 入力で扱うアドレス値を表示.
			Btx_IPv4LeaseAddressSettingLastInput.showEnableAdd( &Gra_IPv4LeaseAddressSettingLastCursor[i], False );
			Btx_IPv4LeaseAddressSettingHeadInput.set( &Nmb_IPv4LeaseAddressSettingHead[i], m_uc_AdressValueHead[i], m_bl_FixedHead[i] );						// 入力で扱うアドレス値を表示.
			Btx_IPv4LeaseAddressSettingHeadInput.showEnableAdd( &Gra_IPv4LeaseAddressSettingHeadCursor[i], ( i == m_sc_InputPositionHead ? True : False ) );	// カーソルの表示（入力選択位置）（左から０～３）.
		}
	} else {
		for( register short i = 0 ; i < PNLD_ServiceIPv4Address_IPv4Num ; i++ ) {				// ＩＰアドレスの数値を順に表示&カーソル表示する
			Btx_IPv4LeaseAddressSettingHeadInput.set( &Nmb_IPv4LeaseAddressSettingHead[i], m_uc_AdressValueHead[i], True );										// 入力で扱うアドレス値を表示.
			Btx_IPv4LeaseAddressSettingHeadInput.showEnableAdd( &Gra_IPv4LeaseAddressSettingHeadCursor[i], False );
			Btx_IPv4LeaseAddressSettingLastInput.set( &Nmb_IPv4LeaseAddressSettingLast[i], m_uc_AdressValueLast[i], m_bl_FixedLast[i] );						// 入力で扱うアドレス値を表示.
			Btx_IPv4LeaseAddressSettingLastInput.showEnableAdd( &Gra_IPv4LeaseAddressSettingLastCursor[i], ( i == m_sc_InputPositionLast ? True : False ) );	// カーソルの表示（入力選択位置）（左から０～３）.
		}
	}
}
//============================================================================================.
// PServiceIPv4LeaseAddressSetting : 93B31A10_拡張ネットワーク設定／DHCPサーバー設定IPv4リースアドレス設定.
// 概要		: ボタン押下処理.
//============================================================================================.
void PServiceIPv4LeaseAddressSetting::procButtonOn( uchar option )
{
	switch( option ) {
		case PNLD_BTNID_NetWorkEx_Idx_DHCPHead:
			m_uc_select = PNLD_NetWorkEXP2_DHCPIPv4LeaseHead;
			break;
		case PNLD_BTNID_NetWorkEx_Idx_DHCPLast:
			m_uc_select = PNLD_NetWorkEXP2_DHCPIPv4LeaseLast;
			break;
		case PNLD_BTNID_NetWorkEx_Idx_DHCPHeadAddLeft:			// ←.
			if( m_sc_InputPositionHead > 0 ) {
				m_bl_DirectHead[m_sc_InputPositionHead] = True;		// ダイレクト入力.
				m_bl_FixedHead[ m_sc_InputPositionHead] = True;		// 確定フラグON.
				m_sc_InputPositionHead--;
				m_bl_FixedHead[ m_sc_InputPositionHead] = False;	// 確定フラグOFF.
			}
			break;
		case PNLD_BTNID_NetWorkEx_Idx_DHCPHeadAddRight:			// →.
			if( m_sc_InputPositionHead < ( PNLD_ServiceIPv4Address_IPv4Num - 1 ) ) {
				m_bl_DirectHead[m_sc_InputPositionHead] = True;		// ダイレクト入力.
				m_bl_FixedHead[ m_sc_InputPositionHead] = True;		// 確定フラグON.
				m_sc_InputPositionHead++;
				m_bl_FixedHead[ m_sc_InputPositionHead] = False;	// 確定フラグOFF.
			}
			break;
		case PNLD_BTNID_NetWorkEx_Idx_DHCPLastAddLeft:			// ←.
			if( m_sc_InputPositionLast > 0 ) {
				m_bl_DirectLast[m_sc_InputPositionLast] = True;		// ダイレクト入力.
				m_bl_FixedLast[ m_sc_InputPositionLast] = True;		// 確定フラグON.
				m_sc_InputPositionLast--;
				m_bl_FixedLast[ m_sc_InputPositionLast] = False;	// 確定フラグOFF.
			}
			break;
		case PNLD_BTNID_NetWorkEx_Idx_DHCPLastAddRight:			// →.
			if( m_sc_InputPositionLast < ( PNLD_ServiceIPv4Address_IPv4Num - 1 ) ) {
				m_bl_DirectLast[m_sc_InputPositionLast] = True;		// ダイレクト入力.
				m_bl_FixedLast[ m_sc_InputPositionLast] = True;		// 確定フラグON.
				m_sc_InputPositionLast++;
				m_bl_FixedLast[ m_sc_InputPositionLast] = False;	// 確定フラグOFF.
			}
			break;
		default:
			PServiceNetWorkEXCom::procButtonOn( option );
			break;
	}
	setupGamen();	// 表示部品のセットアップ.
}
