//============================================================================================.
// PServiceIPv4LeaseAddressSetting : 93B31A10_拡張ネットワーク設定／DHCPサーバー設定IPv4リースアドレス設定.
// 概要		: 10キー入力.
//============================================================================================.
void PServiceIPv4LeaseAddressSetting::proc10Key( uchar option )
{
	Bool bl_isError = False;

	if( PNLD_NetWorkEXP2_DHCPIPv4LeaseHead ==  m_uc_select ) {
		m_uc_AdressValueHead[ m_sc_InputPositionHead ] = ( uchar )proc10KeyInput( m_uc_AdressValueHead[ m_sc_InputPositionHead ], 255, option, m_bl_DirectHead[ m_sc_InputPositionHead ], EP_InputMaxLimitPattern_Refuse, &bl_isError );
		if( ( True == m_bl_DirectHead[ m_sc_InputPositionHead ] ) && ( option == 0 ) ) {
			m_uc_AdressValueHead[ m_sc_InputPositionHead ] = 0;	// 0で上書きするようにする.
			m_bl_FixedHead[ m_sc_InputPositionHead ] = True;	// 表示を確定表示.
		}
		m_bl_DirectHead[ m_sc_InputPositionHead ] = False;	// ダイレクト入力OFF
	} else {
		m_uc_AdressValueLast[ m_sc_InputPositionLast ] = ( uchar )proc10KeyInput( m_uc_AdressValueLast[ m_sc_InputPositionLast ], 255, option, m_bl_DirectLast[ m_sc_InputPositionLast ], EP_InputMaxLimitPattern_Refuse, &bl_isError );
		if( ( True == m_bl_DirectLast[ m_sc_InputPositionLast ] ) && ( option == 0 ) ) {
			m_uc_AdressValueLast[ m_sc_InputPositionLast ] = 0;	// 0で上書きするようにする.
			m_bl_FixedLast[ m_sc_InputPositionLast ] = True;	// 表示を確定表示.
		}
		m_bl_DirectLast[ m_sc_InputPositionLast ] = False;	// ダイレクト入力OFF
	}
	if( True == bl_isError ) {
		setBuzzerType( PCGE_BuzzerType_InputNg );
	}
	setupGamen( option );															// 画面更新を行う.
}
//============================================================================================.
// PServiceIPv4LeaseAddressSetting : 93B31A10_拡張ネットワーク設定／DHCPサーバー設定IPv4リースアドレス設定.
// 概要		: クリアキー入力.
//============================================================================================.
void PServiceIPv4LeaseAddressSetting::procClear( uchar option )
{
	if( PNLD_NetWorkEXP2_DHCPIPv4LeaseHead ==  m_uc_select ) {
		m_uc_AdressValueHead[ m_sc_InputPositionHead ] = 0;		// 入力値
		m_bl_DirectHead[ m_sc_InputPositionHead ] = True;		// ダイレクト入力ON
		m_bl_FixedHead[  m_sc_InputPositionHead ] = False;		// 未確定
	} else {
		m_uc_AdressValueLast[ m_sc_InputPositionLast ] = 0;		// 入力値
		m_bl_DirectLast[ m_sc_InputPositionLast ] = True;		// ダイレクト入力ON
		m_bl_FixedLast[  m_sc_InputPositionLast ] = False;		// 未確定
	}

	setupGamen( option );															// 画面更新を行う.
}
