{
	IPAddressToChar( ( uchar* )m_uc_AdressValueHead , ( char* )m_uc_IPv4LeaseAddressHead );
	IPAddressToChar( ( uchar* )m_uc_AdressValueLast , ( char* )m_uc_IPv4LeaseAddressLast );
}
