// PServiceSubnetMaskSetting : 93B31A20_拡張ネットワーク設定／DHCPサーバー設定サブネットマスク.
// 概要		: 画面開始処理.
//============================================================================================.
void PServiceSubnetMaskSetting::startGamen()
{
	// 親クラスを呼ぶ.
	PServiceNetWorkEXCom::startGamen();
	Rbt_ServiceNetWorkExMenu2.select( PNLD_NetWorkEXP2_DHCP );
	Rbt_ServiceNetWorkExDHCP.select( PNLD_NetWorkEXP2_DHCPSubnetMask );
	m_sc_InputPosition = 0;
	for( register short i = 0 ; i < PNLD_ServiceIPv4Address_IPv4Num ; i++ ) {
		m_bl_Fixed[i] = True;
		m_bl_Direct[i] = True;
	}

	CharToIPAddress( ( char* )m_uc_IPv4SubnetMask, ( uchar* )m_uc_AdressValue );	// 取得した文字列をIPアドレス形式に変換.
}
//============================================================================================.
// PServiceSubnetMaskSetting : 93B31A20_拡張ネットワーク設定／DHCPサーバー設定サブネットマスク.
// 概要		: 画面更新処理.
//============================================================================================.
void PServiceSubnetMaskSetting::setupGamen( short option )
{
	// 親クラスを呼ぶ.
	PServiceNetWorkEXCom::setupGamen( option );
	for( register short i = 0 ; i < PNLD_ServiceIPv4Address_IPv4Num ; i++ ) {				// ＩＰアドレスの数値を順に表示&カーソル表示する
		Btx_ServiceSubnetMaskSettingInput.set( &Nmb_ServiceSubnetMaskSetting[i], m_uc_AdressValue[i], m_bl_Fixed[i] );						// 入力で扱うアドレス値を表示.
		Btx_ServiceSubnetMaskSettingInput.showEnableAdd( &Gra_ServiceSubnetMaskSettingCursor[i], ( i == m_sc_InputPosition ? True : False ) );	// カーソルの表示（入力選択位置）（左から０～３）.
	}
}
