//============================================================================================.
void PServiceSubnetMaskSetting::procButtonOn( uchar option )
{
	switch( option ) {
		case PNLD_BTNID_NetWorkEx_Idx_SubnetMaskLeft:			// ←.
			if( m_sc_InputPosition > 0 ) {
				m_bl_Direct[m_sc_InputPosition] = True;		// ダイレクト入力.
				m_bl_Fixed[ m_sc_InputPosition] = True;		// 確定フラグON.
				m_sc_InputPosition--;
				m_bl_Fixed[ m_sc_InputPosition] = False;	// 確定フラグOFF.
			}
			break;
		case PNLD_BTNID_NetWorkEx_Idx_SubnetMaskRight:			// →.
			if( m_sc_InputPosition < ( PNLD_ServiceIPv4Address_IPv4Num - 1 ) ) {
				m_bl_Direct[m_sc_InputPosition] = True;		// ダイレクト入力.
				m_bl_Fixed[ m_sc_InputPosition] = True;		// 確定フラグON.
				m_sc_InputPosition++;
				m_bl_Fixed[ m_sc_InputPosition] = False;	// 確定フラグOFF.
			}
			break;
		default:
			PServiceNetWorkEXCom::procButtonOn( option );
			break;
	}
	setupGamen();	// 表示部品のセットアップ.
}
