// PServiceLeaseLimitSetting : 93B31A30_拡張ネットワーク設定／DHCPサーバー設定リース期限.
// 概要		: 画面開始処理.
//============================================================================================.
void PServiceLeaseLimitSetting::startGamen()
{
	// 親クラスを呼ぶ.
	PServiceNetWorkEXCom::startGamen();
	Rbt_ServiceNetWorkExMenu2.select( PNLD_NetWorkEXP2_DHCP );
	Rbt_ServiceNetWorkExDHCP.select( PNLD_NetWorkEXP2_DHCPLeaseLimit );
}
//============================================================================================.
// PServiceLeaseLimitSetting : 93B31A30_拡張ネットワーク設定／DHCPサーバー設定リース期限.
// 概要		: 画面更新処理.
//============================================================================================.
void PServiceLeaseLimitSetting::setupGamen( short option )
{
	// 親クラスを呼ぶ.
	PServiceNetWorkEXCom::setupGamen( option );
	uchar uc_buff[11];
	memset( uc_buff, 0, sizeof( uc_buff ) );
	if( 0 != m_ul_LeaseLimit ) {
		snprintf( ( char* )uc_buff, sizeof(uc_buff), "%u",m_ul_LeaseLimit );
	}
	Btx_LeaseLimitSetting.changeASCIIText( uc_buff );
}
//============================================================================================.
// PServiceLeaseLimitSetting : 93B31A30_拡張ネットワーク設定／DHCPサーバー設定リース期限.
// 概要		: ボタン押下処理(画面遷移).
//============================================================================================.
void PServiceLeaseLimitSetting::procGoToPage( uchar option )
{
	switch( option ) {
		case	PNLD_BTNID_NetWorkEx_Idx_DHCPServer :			// DHCPサーバー設定.
			nextGamen = &gp_ServiceDHCPServerSetting;
			break;
		case	PNLD_BTNID_NetWorkEx_Idx_IPv4Lease :			// IPv4リースアドレス.
			nextGamen = &gp_ServiceIPv4LeaseAddressSetting;
			break;
		case	PNLD_BTNID_NetWorkEx_Idx_SubnetMask :			// サブネットマスク.
			nextGamen = &gp_ServiceSubnetMaskSetting;
			break;
		case	PNLD_BTNID_NetWorkEx_Up :
		case	PNLD_BTNID_NetWorkEx_Down :
			nextGamen = &gp_ServiceNetWorkEX2ndCardSetting;
			break;
		default:
			break;
	}
}
//============================================================================================.
// PServiceLeaseLimitSetting : 93B31A30_拡張ネットワーク設定／DHCPサーバー設定リース期限.
// 概要		: 10キー入力.
//============================================================================================.
void PServiceLeaseLimitSetting::proc10Key( uchar option )
{
	Bool b_isError = False;

	// 接続タイムアウトを更新する.
	m_ul_LeaseLimit = ( uint32_t )proc10KeyInputUL( m_ul_LeaseLimit,
	                  0xFFFFFFFF,
	                  option,
	                  m_bl_Direct,
	                  EP_InputMaxLimitPattern_Refuse,
	                  &b_isError ) ;

	if( True == b_isError ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );					// ブザー音セット.
	} else {
		if( True == m_bl_Direct && 1 > option ) {
			MCR_setBuzzerType( PCGE_BuzzerType_InputNg );				// ブザー音セット.
		} else {
			m_bl_Direct = False;
		}
	}

	setupGamen( option );															// 画面更新を行う.
}
//============================================================================================.
// PServiceLeaseLimitSetting : 93B31A30_拡張ネットワーク設定／DHCPサーバー設定リース期限.
// 概要		: クリアキー入力.
//============================================================================================.
void PServiceLeaseLimitSetting::procClear( uchar option )
{
	m_bl_Direct = True;
	m_ul_LeaseLimit = 0;
	setupGamen( option );															// 画面更新を行う.
}

//============================================================================================.
// PServiceExpansionNetworkTCPIP		: 93B31B00_拡張ネットワーク設定／TCP／IP設定.
// 										: 93B31B10_拡張ネットワーク設定／TCP／IP設定IPv4設定.
// 										: 93B31B20_拡張ネットワーク設定／TCP／IP設定IPv6設定.
// 概要		: 画面開始処理.
//============================================================================================.
void PServiceExpansionNetworkTCPIP::startGamen()
{
	// 親クラスを呼ぶ.
	PServiceNetWorkEXCom::startGamen();

	Rbt_ServiceNetWorkExMenu2.select( PNLD_NetWorkEXP2_TCPIP );
	m_sc_select = PNLD_NetWorkEXP2_TCPIPv4;

	m_bl_selectIPAddress = True;
	m_sc_InputPositionIPAddress = 0;
	m_sc_InputPositionSubnetMask = 0;
	for( register short i = 0 ; i < PNLD_ServiceIPv4Address_IPv4Num ; i++ ) {
		m_bl_FixedIPAddress[i] = True;
		m_bl_FixedSubnetMask[i] = True;
		m_bl_DirectIPAddress[i] = True;
		m_bl_DirectSubnetMask[i] = True;
	}
	CharToIPAddress( ( char* )m_uc_IPv4IPAddress, ( uchar* )m_uc_AdressValueIPAddress );	// 取得した文字列をIPアドレス形式に変換.
	CharToIPAddress( ( char* )m_uc_IPv4SubnetMaskEx, ( uchar* )m_uc_AdressValueSubnetMask );	// 取得した文字列をIPアドレス形式に変換.
}
//============================================================================================.
// PServiceExpansionNetworkTCPIP		: 93B31B00_拡張ネットワーク設定／TCP／IP設定.
// 										: 93B31B10_拡張ネットワーク設定／TCP／IP設定IPv4設定.
// 										: 93B31B20_拡張ネットワーク設定／TCP／IP設定IPv6設定.
// 概要		: 画面更新処理.
//============================================================================================.
void PServiceExpansionNetworkTCPIP::setupGamen( short option )
{
	// 親クラスを呼ぶ.
	PServiceNetWorkEXCom::setupGamen( option );
	Rbt_ExpansionNetworkTCPIP.select( m_sc_select );
	if( PNLD_NetWorkEXP2_TCPIPv4 == m_sc_select ) {
		Grp_tbl_ExpansionNetworkTCPIPv6.showEnable( False );
		Grp_tbl_ExpansionNetworkTCPIPv4.showEnable( True );
		Grp_ExpansionNetworkTCPIPv4.changeColor( UC_GPARTS_COLOR_BLACK );
		Rbt_ExpansionNetworkTCPIPDecidedMethod.select( TYPE_IpAddressAuto == m_e_ipAddress ? 0 : 1 );
		if( TYPE_IpAddressAuto == m_e_ipAddress ) {
			Grp_tbl_ExpansionNetworkTCPIPAdress.showEnable( False );
			Grp_tbl_ExpansionNetworkTCPIPDHCPSetting.showEnable( True );
			Rbt_ExpansionNetworkTCPIPDHCPUseSetting.select( True == m_bl_DHCPSetting ? 0 : 1 );
		} else {
			Grp_tbl_ExpansionNetworkTCPIPDHCPSetting.showEnable( False );
			Grp_tbl_ExpansionNetworkTCPIPAdress.showEnable( True );
			Rbt_ExpansionNetworkTCPIPDHCPIPAddress.select( True == m_bl_selectIPAddress ? 0 : 1 );
			for( register short i = 0 ; i < PNLD_ServiceIPv4Address_IPv4Num ; i++ ) {				// ＩＰアドレスの数値を順に表示&カーソル表示する
				if( True == m_bl_selectIPAddress ) {
					Btx_ExpansionNetworkTCPIPInput.set( &Nmb_ExpansionNetworkTCPIP[i], m_uc_AdressValueIPAddress[i], m_bl_FixedIPAddress[i] );						// 入力で扱うアドレス値を表示.
					Btx_ExpansionNetworkTCPIPInput.showEnableAdd( &Gra_ExpansionNetworkTCPIPCursor[i], ( i == m_sc_InputPositionIPAddress ? True : False ) );	// カーソルの表示（入力選択位置）（左から０～３）.
				} else {
					Btx_ExpansionNetworkTCPIPInput.set( &Nmb_ExpansionNetworkTCPIP[i], m_uc_AdressValueSubnetMask[i], m_bl_FixedSubnetMask[i] );						// 入力で扱うアドレス値を表示.
					Btx_ExpansionNetworkTCPIPInput.showEnableAdd( &Gra_ExpansionNetworkTCPIPCursor[i], ( i == m_sc_InputPositionSubnetMask ? True : False ) );	// カーソルの表示（入力選択位置）（左から０～３）.
				}
			}
		}
	} else if( PNLD_NetWorkEXP2_TCPIPv6 == m_sc_select ) {
		Grp_tbl_ExpansionNetworkTCPIPv4.showEnable( False );
		Grp_tbl_ExpansionNetworkTCPIPv6.showEnable( True );
		Grp_ExpansionNetworkTCPIPv4.changeColor( UC_GPARTS_COLOR_WHITE );
		uchar uc_ipv6Address[MIO_INET6_ADDRSTRLEN];
		memset( uc_ipv6Address, 0, sizeof( uc_ipv6Address ) );
		APIC_ExNetworkSetting::newInstance()->getIPv6LinkLocalAddressEx( uc_ipv6Address );
		Tfd_ExpansionNetworkTCPIPRinkLocalAddress.changeTextString( ( uchar* )uc_ipv6Address );
	} else {
		Grp_tbl_ExpansionNetworkTCPIPv4.showEnable( False );
		Grp_tbl_ExpansionNetworkTCPIPv6.showEnable( False );
		Grp_ExpansionNetworkTCPIPv4.changeColor( UC_GPARTS_COLOR_WHITE );
	}

}
//============================================================================================.
// PServiceExpansionNetworkTCPIP		: 93B31B00_拡張ネットワーク設定／TCP／IP設定.
// 										: 93B31B10_拡張ネットワーク設定／TCP／IP設定IPv4設定.
// 										: 93B31B20_拡張ネットワーク設定／TCP／IP設定IPv6設定.
// 概要		: ボタン押下処理.
//============================================================================================.
void PServiceExpansionNetworkTCPIP::procButtonOn( uchar option )
{
	switch( option ) {
		case PNLD_BTNID_NetWorkEx_Idx_TCPIPv4:			// IPv4.
			m_sc_select = PNLD_NetWorkEXP2_TCPIPv4;
			break;
		case PNLD_BTNID_NetWorkEx_Idx_TCPIPv6:			// IPv6.
			m_sc_select = PNLD_NetWorkEXP2_TCPIPv6;
			break;
		case PNLD_BTNID_NetWorkEx_Idx_TCPIPv4Auto:			// IPv4自動取得.
			m_e_ipAddress = TYPE_IpAddressAuto;
			break;
		case PNLD_BTNID_NetWorkEx_Idx_TCPIPv4Direct:			// IPv4直接設定.
			m_e_ipAddress = TYPE_IpAddressDirect;
			break;
		case PNLD_BTNID_NetWorkEx_Idx_TCPIPv4Use:			// IPv4DHCP使用する.
			m_bl_DHCPSetting = True;
			break;
		case PNLD_BTNID_NetWorkEx_Idx_TCPIPv4NotUse:			// IPv4DHCP使用しない.
			m_bl_DHCPSetting = False;
			break;
		case PNLD_BTNID_NetWorkEx_Idx_TCPIPv4Address:			// IPv4設定IPアドレス.
			m_bl_selectIPAddress = True;
			break;
		case PNLD_BTNID_NetWorkEx_Idx_TCPIPv4SubnetMask:			// IPv4設定サブネットマスク.
			m_bl_selectIPAddress = False;
			break;
		case PNLD_BTNID_NetWorkEx_Idx_TCPIPv4AddressLeft:			// IPv4設定IPアドレス←.
			if( True == m_bl_selectIPAddress ) {
				if( m_sc_InputPositionIPAddress > 0 ) {
					m_bl_DirectIPAddress[m_sc_InputPositionIPAddress] = True;		// ダイレクト入力.
					m_bl_FixedIPAddress[ m_sc_InputPositionIPAddress] = True;		// 確定フラグON.
					m_sc_InputPositionIPAddress--;
					m_bl_FixedIPAddress[ m_sc_InputPositionIPAddress] = False;	// 確定フラグOFF.
				}
			} else {
				if( m_sc_InputPositionSubnetMask > 0 ) {
					m_bl_DirectSubnetMask[m_sc_InputPositionSubnetMask] = True;		// ダイレクト入力.
					m_bl_FixedSubnetMask[ m_sc_InputPositionSubnetMask] = True;		// 確定フラグON.
					m_sc_InputPositionSubnetMask--;
					m_bl_FixedSubnetMask[ m_sc_InputPositionSubnetMask] = False;	// 確定フラグOFF.
				}
			}
			break;
		case PNLD_BTNID_NetWorkEx_Idx_TCPIPv4AddressRight:			// IPv4設定IPアドレス→.
			if( True == m_bl_selectIPAddress ) {
				if( m_sc_InputPositionIPAddress < ( PNLD_ServiceIPv4Address_IPv4Num - 1 ) ) {
					m_bl_DirectIPAddress[m_sc_InputPositionIPAddress] = True;		// ダイレクト入力.
					m_bl_FixedIPAddress[ m_sc_InputPositionIPAddress] = True;		// 確定フラグON.
					m_sc_InputPositionIPAddress++;
					m_bl_FixedIPAddress[ m_sc_InputPositionIPAddress] = False;	// 確定フラグOFF.
				}
			} else {
				if( m_sc_InputPositionSubnetMask < ( PNLD_ServiceIPv4Address_IPv4Num - 1 ) ) {
					m_bl_DirectSubnetMask[m_sc_InputPositionSubnetMask] = True;		// ダイレクト入力.
					m_bl_FixedSubnetMask[ m_sc_InputPositionSubnetMask] = True;		// 確定フラグON.
					m_sc_InputPositionSubnetMask++;
					m_bl_FixedSubnetMask[ m_sc_InputPositionSubnetMask] = False;	// 確定フラグOFF.
				}
			}
			break;
		default:
			PServiceNetWorkEXCom::procButtonOn( option );
			break;
	}
	setupGamen();	// 表示部品のセットアップ.
}
