//============================================================================================.
// PServiceExpansionNetworkTCPIP		: 93B31B00_拡張ネットワーク設定／TCP／IP設定.
// 										: 93B31B10_拡張ネットワーク設定／TCP／IP設定IPv4設定.
// 										: 93B31B20_拡張ネットワーク設定／TCP／IP設定IPv6設定.
// 概要		: 10キー入力.
//============================================================================================.
void PServiceExpansionNetworkTCPIP::proc10Key( uchar option )
{
	Bool bl_isError = False;

	if( PNLD_NetWorkEXP2_TCPIPv4 == m_sc_select
	    && TYPE_IpAddressDirect == m_e_ipAddress ) {
		if( True == m_bl_selectIPAddress ) {
			m_uc_AdressValueIPAddress[ m_sc_InputPositionIPAddress ] = ( uchar )proc10KeyInput( m_uc_AdressValueIPAddress[ m_sc_InputPositionIPAddress ], 255, option, m_bl_DirectIPAddress[ m_sc_InputPositionIPAddress ], EP_InputMaxLimitPattern_Refuse, &bl_isError );
			if( ( True == m_bl_DirectIPAddress[ m_sc_InputPositionIPAddress ] ) && ( option == 0 ) ) {
				m_uc_AdressValueIPAddress[ m_sc_InputPositionIPAddress ] = 0;	// 0で上書きするようにする.
				m_bl_FixedIPAddress[ m_sc_InputPositionIPAddress ] = True;	// 表示を確定表示.
			}
			m_bl_DirectIPAddress[ m_sc_InputPositionIPAddress ] = False;	// ダイレクト入力OFF
		} else {
			m_uc_AdressValueSubnetMask[ m_sc_InputPositionSubnetMask ] = ( uchar )proc10KeyInput( m_uc_AdressValueSubnetMask[ m_sc_InputPositionSubnetMask ], 255, option, m_bl_DirectSubnetMask[ m_sc_InputPositionSubnetMask ], EP_InputMaxLimitPattern_Refuse, &bl_isError );
			if( ( True == m_bl_DirectSubnetMask[ m_sc_InputPositionSubnetMask ] ) && ( option == 0 ) ) {
				m_uc_AdressValueSubnetMask[ m_sc_InputPositionSubnetMask ] = 0;	// 0で上書きするようにする.
				m_bl_FixedSubnetMask[ m_sc_InputPositionSubnetMask ] = True;	// 表示を確定表示.
			}
			m_bl_DirectSubnetMask[ m_sc_InputPositionSubnetMask ] = False;	// ダイレクト入力OFF
		}
	} else {
		bl_isError = True;				// ブザー音セット.
	}
	if( True == bl_isError ) {
		setBuzzerType( PCGE_BuzzerType_InputNg );
	}
	setupGamen( option );															// 画面更新を行う.
}
//============================================================================================.
// PServiceExpansionNetworkTCPIP		: 93B31B00_拡張ネットワーク設定／TCP／IP設定.
// 										: 93B31B10_拡張ネットワーク設定／TCP／IP設定IPv4設定.
// 										: 93B31B20_拡張ネットワーク設定／TCP／IP設定IPv6設定.
// 概要		: クリアキー入力.
//============================================================================================.
void PServiceExpansionNetworkTCPIP::procClear( uchar option )
{
	if( PNLD_NetWorkEXP2_TCPIPv4 == m_sc_select
	    && TYPE_IpAddressDirect == m_e_ipAddress ) {
		if( True == m_bl_selectIPAddress ) {
			m_uc_AdressValueIPAddress[ m_sc_InputPositionIPAddress ] = 0;		// 入力値
			m_bl_DirectIPAddress[ m_sc_InputPositionIPAddress ] = True;		// ダイレクト入力ON
			m_bl_FixedIPAddress[  m_sc_InputPositionIPAddress ] = False;		// 未確定
		} else {
			m_uc_AdressValueSubnetMask[ m_sc_InputPositionSubnetMask ] = 0;		// 入力値
			m_bl_DirectSubnetMask[ m_sc_InputPositionSubnetMask ] = True;		// ダイレクト入力ON
			m_bl_FixedSubnetMask[  m_sc_InputPositionSubnetMask ] = False;		// 未確定
		}
	} else {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );				// ブザー音セット.
	}
	setupGamen( option );															// 画面更新を行う.
}
