//================================================================================================.
// 概要		 : PServiceSystemDriverInstall : 91518_MiB システム設定／ドライバーインストール.
//			  (PServiceSystemDriverInstall_PKI : TaigaPKI_004_システム設定／ドライバーインストールを流用)
//================================================================================================.
short PServiceSystemDriverInstall::ss_MmbLoadableCheckStatus = PCGD_ServiceLoadableFileCheck_BSY;	// ローダブルドライバーファイルチェック（チェック前）.
short PServiceSystemDriverInstall::ss_MmbLoadableDownloadStatus = PCGD_ServiceLoadableInstall_BSY;	// ローダブルドライバーダウンロードステータス（ダウンロード前）.
TYPE_LoadableDownloadKind PServiceSystemDriverInstall::e_LoadableDownloadKind = TYPE_LoadableDownloadKind_None;	// ローダブルドライバのダウンロード種別.
//================================================================================================.
// 概要		 : PServiceSystemDriverInstall : 91518_MiB システム設定／ドライバーインストール: ラインキー押下.
//			  (PServiceSystemDriverInstall_PKI : TaigaPKI_004_システム設定／ドライバーインストールを流用)
//================================================================================================.
void PServiceSystemDriverInstall::procGoToMag( uchar option )
{
	if( ( PCGD_ServiceLoadableInstall_ING == ss_MmbLoadableDownloadStatus ) || ( PCGD_ServiceLoadableInstall_OK == ss_MmbLoadableDownloadStatus ) ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}
	PServiceToSystemMenu2P2Com::procGoToMag( option );			// 親クラスのラインキー処理（サービス固有）をコール.
}
//================================================================================================.
// 概要		 : PServiceSystemDriverInstall : 91518_MiB システム設定／ドライバーインストール: ボタン押下.
//================================================================================================.
void PServiceSystemDriverInstall::procButtonOn( uchar option )
{
//comment 2018/03/27 HCLT-Haribhaskar [IT6_Eagle] [制御構成変更_No.113] Adding the Reboot functionality.
	if  ( BTNID_GoToDriverInstallReboot !=  option ) {
		if( ( PCGD_ServiceLoadableInstall_ING == ss_MmbLoadableDownloadStatus ) || ( PCGD_ServiceLoadableInstall_OK == ss_MmbLoadableDownloadStatus ) ) {
			MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
			return;
		}
	}
	switch( option ) {
		case BTNID_KEY_SERVICEDRIVERINSTALL_LOADABLEDRIVER:		// ローダブルドライバーキー.
			bl_MmbLoadableSet = ( ( False == bl_MmbLoadableSet ) ? True : False );
			break;
		case BTNID_KEY_SERVICEDRIVERINSTALL_START:				// スタートキー.
			startInstall();										// インストール開始.
			break;
//comment 2018/03/27 HCLT-Haribhaskar [IT6_Eagle] [制御構成変更_No.113] Adding the Reboot functionality.
		case BTNID_GoToDriverInstallReboot:
			Reboot();
			return;
		default:										// その他.
			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
			return;
	}
	setupGamen();		// 表示部品のセットアップ.
}
