{
	if( ( PCGD_ServiceLoadableInstall_ING == ss_MmbLoadableDownloadStatus ) || ( PCGD_ServiceLoadableInstall_OK == ss_MmbLoadableDownloadStatus ) ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}
	PServiceToSystemMenu2P2Com::procOk( option );				// 親クラスの設定終了をコール.
}
