//================================================================================================.
// 概要		 : PServiceSystemDriverInstall : 91518_MiB システム設定／ドライバーインストール: コールバック通知.
//================================================================================================.
void PServiceSystemDriverInstall::procCallBack( TYPE_PNL_CallBack option )
{
	switch( option ) {
		case TYPE_PNL_CallBack_LoadableDLCheck:		// ローダブルドライバーダウンロード用ファイルチェック完了通知（意図的にbreakしない）.
		case TYPE_PNL_CallBack_LoadableDownload:	// ローダブルドライバーインストール完了通知.
			setupGamen();		// 表示部品のセットアップ.
			break;
		default:									// その他.
			PServiceToSystemMenu2P2Com::procCallBack( option );		// 親クラスのコールバック処理をコール.
			return;
	}
}
//================================================================================================.
// 概要		 : PServiceSystemDriverInstall : 91518_MiB システム設定／ドライバーインストール: 定期起床.
//================================================================================================.
void PServiceSystemDriverInstall::procTimerWakeUp( uchar option )
{
	PServiceToSystemMenu2P2Com::procTimerWakeUp( option );		// 親クラスの提起起床をコール.

	// ダウンロード前でファイルチェックがNGの場合は、再度ファイルチェックを行う.
	if( ( PCGD_ServiceLoadableInstall_BSY == ss_MmbLoadableDownloadStatus ) && ( PCGD_ServiceLoadableFileCheck_NG == ss_MmbLoadableCheckStatus ) ) {
		ss_MmbLoadableCheckStatus = PCGD_ServiceLoadableFileCheck_ING;
		if( True == PLBC_FuncPKICheck::isPKI() ) {				// PKI機能が有効の時.
			if( False == PnlComGetAuthDevicePkiCommon()->isAuthLoadableDownloadReady( ans_DownloadReady ) ) {
				ss_MmbLoadableCheckStatus = PCGD_ServiceLoadableFileCheck_NG;
			}
		} else {												// PKI機能が無効の時.
			APIC_AuthLoadableDriver* cp_AuthLoadableDriver = APIC_AuthLoadableDriver::newInstance();
			if( NULL == cp_AuthLoadableDriver ) {
// Comment 2015/11/02 【ZeusS_ZX0】【HCL_Vasu】【制御構成変更_No.76-1】Adding Error Code macro.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//				LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//				if (NULL !=pc_BFW_System){
//					pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x1900680101051C01 );
//				}
				LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
				ss_MmbLoadableCheckStatus = PCGD_ServiceLoadableFileCheck_NG;
				return;
			}
			if( False == cp_AuthLoadableDriver->chkLoadableDownloadReady( ans_LoadableDownloadReady ) ) {
				ss_MmbLoadableCheckStatus = PCGD_ServiceLoadableFileCheck_NG;
			}
		}
	}

	m_bl_UninstallAnime = ( True == m_bl_UninstallAnime )? False : True;		// 「／」⇔「＼」.
}
//================================================================================================.
// 概要		 : PServiceSystemDriverInstall : 91518_MiB システム設定／ドライバーインストール: 画面開始.
//================================================================================================.
void PServiceSystemDriverInstall::startGamen()
{
	PBasicMessageProc::startGamen();

	bl_MmbLoadableSet = False;									//  登録ボタン選択フラグ（未選択）.
	ss_MmbLoadableDownloadStatus = PCGD_ServiceLoadableInstall_BSY;	// ローダブルドライバーダウンロードステータス（ダウンロード前）.
	e_LoadableDownloadKind = TYPE_LoadableDownloadKind_None;

	// ファイルチェック中で無い場合は、USBローダブルファイル有無判定を行う.
	if( PCGD_ServiceLoadableFileCheck_ING != ss_MmbLoadableCheckStatus ) {
		ss_MmbLoadableCheckStatus = PCGD_ServiceLoadableFileCheck_ING;
		if( True == PLBC_FuncPKICheck::isPKI() ) {				// PKI機能が有効の時.
			if( False == PnlComGetAuthDevicePkiCommon()->isAuthLoadableDownloadReady( ans_DownloadReady ) ) {
				ss_MmbLoadableCheckStatus = PCGD_ServiceLoadableFileCheck_NG;
			}
		} else {												// PKI機能が無効の時.
			APIC_AuthLoadableDriver* cp_AuthLoadableDriver = APIC_AuthLoadableDriver::newInstance();
			if( NULL == cp_AuthLoadableDriver ) {
// Comment 2015/11/02 【ZeusS_ZX0】【HCL_Vasu】【制御構成変更_No.76-1】Adding Error Code macro.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//				LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//				if (NULL !=pc_BFW_System){
//					pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x1900650101051D01 );
//				}
				LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
				ss_MmbLoadableCheckStatus = PCGD_ServiceLoadableFileCheck_NG;
				return;
			}
			if( False == cp_AuthLoadableDriver->chkLoadableDownloadReady( ans_LoadableDownloadReady ) ) {
				ss_MmbLoadableCheckStatus = PCGD_ServiceLoadableFileCheck_NG;
			}
		}
	}
// Comment 2015/07/20 HCLT-Surajit RQ-163[WP 1366] Hide Loadable Driver.
// Comment 2017/11/29 【HCLT-Vishal】【Eagle】【制御構成変更_No.4】 Removing old function version check condition.
	PNLC_USBConnectionPermission c_UsbPermission;
	PNLE_EnableUSBConnectionPermissionForAll e_usbAll = c_UsbPermission.getEnableUSBConnectionPermissionForAll();
	PNLE_EnableUSBConnectionPermissionForService e_usbforService = c_UsbPermission.getEnableUSBConnectionPermissionForService();
	if(( PNLE_EnableUSBConnectionPermissionForAll_Disable == e_usbAll ) || ( PNLE_EnableUSBConnectionPermissionForService_Disable == e_usbforService )) {
		m_bl_USBConnectionPermissionFlag = False;
	} else {
		m_bl_USBConnectionPermissionFlag = True;
	}
	// アンインストールキーの表示制御.
	Bool bl_isDriverInstalled = PServiceSystemDriverUninstall::checkDriverInstalled();
	Key_ServiceDriverMenuUninstall.showEnable( bl_isDriverInstalled );
	// インストールを選択.
	Rbt_ServiceDriverMenuInstall.select( BTNID_IDX_SERVICEDRIVERINSTALL_INSTALL );

	// パーツ表示制御.
	CheckShowParts();
}
//================================================================================================.
// 概要		 : PServiceSystemDriverInstall : 91518_MiB システム設定／ドライバーインストール: 画面セットアップ.
//================================================================================================.
void PServiceSystemDriverInstall::setupGamen( short option )
{
	PServiceToSystemMenu2P2Com::setupGamen( option );		// 親クラスの表示部品のセットアップをコール.
// Comment 2015/08/17 HCLT-Surajit RQ-163[WP 1374] [WP 1366] Hide Loadable Driver. To avoid flicker issue.
// Comment 2017/11/29 【HCLT-Vishal】【Eagle】【制御構成変更_No.4】 Removing old function version check variable.
	switch( ss_MmbLoadableDownloadStatus ) {
		case PCGD_ServiceLoadableInstall_BSY:		// ローダブルドライバーダウンロードステータス（ダウンロード前）.
		{
// Comment 2015/08/17 HCLT-Surajit [RQ-163] [WP 1366] Hide Loadable Driver. To avoid flicker issue.
//			Bool b_ShowEntry = ( ( PCGD_ServiceLoadableFileCheck_OK != ss_MmbLoadableCheckStatus ) ? False : True );
			Key_OkService.showEnable( True );										// OKキー表示.
			Txt_ServiceDriverInstallStatus_LoadableDriver.showEnable( False );		// ダウンロード状態非表示.
			Grp_ServiceDriverInstallMsgPowerOffOn.showEnable( False );				// 再起動要求メッセージ非表示.
			Txt_ServiceDriverInstallProgress_LoadableDriver.showEnable( False );	// 「／」「＼」.
// Comment 2015/08/17 HCLT-Surajit [RQ-163] [WP 1366] Hide Loadable Driver. To avoid flicker issue.
//			Key_ServiceDriverInstallLoadableDriver.select( bl_MmbLoadableSet );		// ローダブルドライバーキーの選択状態.
//			Key_ServiceDriverInstallLoadableDriver.showEnable( b_ShowEntry );		// ローダブルドライバーキーの表示/非表示.
		}
		break;
		case PCGD_ServiceLoadableInstall_OK:			// ローダブルドライバーダウンロードステータス（ダウンロード成功）.
			Key_ServiceToLine.showEnable( False );										// ラインキー非表示.
			Key_OkService.showEnable( False );											// OKキー表示.
			Txt_ServiceDriverInstallProgress_LoadableDriver.showEnable( False );		// 「／」「＼」.
			Txt_ServiceDriverInstallStatus_LoadableDriver.changeText( s_Ok );			// ダウンロード状態「OK」に変更.
			Txt_ServiceDriverInstallStatus_LoadableDriver.showEnable( True );			// ダウンロード状態表示.
			Grp_ServiceDriverInstallMsgPowerOffOn.showEnable( True );					// 再起動要求メッセージ表示.
			break;
		case PCGD_ServiceLoadableInstall_NG:			// ローダブルドライバーダウンロードステータス（ダウンロード失敗）.
			Key_OkService.showEnable( True );											// OKキー表示.
			Txt_ServiceDriverInstallProgress_LoadableDriver.showEnable( False );		// 「／」「＼」.
			Grp_ServiceDriverInstallMsgPowerOffOn.showEnable( False );					// 再起動要求メッセージ非表示.
			Txt_ServiceDriverInstallStatus_LoadableDriver.changeText( s_NG );			// ダウンロード状態「NG」に変更.
			Txt_ServiceDriverInstallStatus_LoadableDriver.showEnable( True );			// ダウンロード状態表示.
// Comment 2015/08/17 HCLT-Surajit [RQ-163] [WP 1366] Hide Loadable Driver. To avoid flicker issue.
//			Key_ServiceDriverInstallLoadableDriver.select( bl_MmbLoadableSet );			// ローダブルドライバーキーの選択状態.
			break;
		case PCGD_ServiceLoadableInstall_ING:		// ローダブルドライバーダウンロードステータス（ダウンロード中）.
			Key_ServiceToLine.showEnable( False );										// ラインキー非表示.
			Key_OkService.showEnable( False );											// OKキー表示.
			Grp_ServiceDriverInstallMsgPowerOffOn.showEnable( False );					// 再起動要求メッセージ非表示.
			Txt_ServiceDriverInstallStatus_LoadableDriver.changeText( s_ITMServiceRunning );// ダウンロード状態「実行中」に変更.
			Txt_ServiceDriverInstallStatus_LoadableDriver.showEnable( True );			// ダウンロード状態表示.
			Txt_ServiceDriverInstallProgress_LoadableDriver.changeText( ( m_bl_UninstallAnime )? s_EXPSlash: s_EXPBackslash );
			Txt_ServiceDriverInstallProgress_LoadableDriver.showEnable( True );			// 「／」「＼」.
			break;
		default:
			break;
	}

	// 登録キー選択、かつダウンロード前は、スタートキーを表示する.
	if( ( True == bl_MmbLoadableSet ) && ( PCGD_ServiceLoadableInstall_BSY == ss_MmbLoadableDownloadStatus ) ) {
		// 項目選択時は、確定キー表示.
		Key_ServiceDriverInstallStart.showEnable( True );
	} else {
		Key_ServiceDriverInstallStart.showEnable( False );
	}
// Comment 2015/07/20 HCLT-Surajit RQ-163[WP 1366] Hide Loadable Driver.
// Comment 2017/11/29 【HCLT-Vishal】【Eagle】【制御構成変更_No.4】 Removing old function version check condition.
	if ( True == m_bl_USBConnectionPermissionFlag ) {
		switch( ss_MmbLoadableDownloadStatus ) {
			case PCGD_ServiceLoadableInstall_BSY:		// ローダブルドライバーダウンロードステータス（ダウンロード前）.
			{
				Bool b_ShowEntry = ( ( PCGD_ServiceLoadableFileCheck_OK != ss_MmbLoadableCheckStatus ) ? False : True );
				Key_ServiceDriverInstallLoadableDriver.select( bl_MmbLoadableSet );		// ローダブルドライバーキーの選択状態.
				Key_ServiceDriverInstallLoadableDriver.showEnable( b_ShowEntry );		// ローダブルドライバーキーの表示/非表示.
			}
			break;
			case PCGD_ServiceLoadableInstall_NG:			// ローダブルドライバーダウンロードステータス（ダウンロード失敗）.
			{
				Key_ServiceDriverInstallLoadableDriver.showEnable( bl_MmbLoadableSet );	// ローダブルドライバーキーの選択状態.
			}
			break;
			default: break;
			
		}
// Comment 2017/11/29 【HCLT-Vishal】【Eagle】【制御構成変更_No.4】 Removing old function version check condition.
	} else	{
		Key_ServiceDriverInstallLoadableDriver.showEnable( False );					// ローダブルドライバーキーの非表示.
	}
	printLEDControl( False );		// スタートLED赤.
}
//================================================================================================.
// 概要		 : PServiceSystemDriverInstall : 91518_MiB システム設定／ドライバーインストール: インストール開始.
//================================================================================================.
void PServiceSystemDriverInstall::startInstall()
{
	ss_MmbLoadableDownloadStatus = PCGD_ServiceLoadableInstall_ING;								// ローダブルドライバーダウンロードステータス（ダウンロード中）.
	if( True == PLBC_FuncPKICheck::isPKI() ) {												// PKI機能が有効の時.
		PnlComGetAuthDevicePkiCommon()->reqAuthLoadableDownload( ans_DownloadComplete );	// ダウンロード開始要求.
	} else {																				// PKI機能が無効の時.
		APIC_AuthLoadableDriver* cp_AuthLoadableDriver = APIC_AuthLoadableDriver::newInstance();
		if( NULL == cp_AuthLoadableDriver ) {
// Comment 2015/11/02 【ZeusS_ZX0】【HCL_Vasu】【制御構成変更_No.76-1】Adding Error Code macro.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//			LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//			if (NULL !=pc_BFW_System){
//				pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19000A0101051E01 );
//			}
			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
			ss_MmbLoadableDownloadStatus = PCGD_ServiceLoadableInstall_NG;
			return;
		}
		Bool b_Result = cp_AuthLoadableDriver->reqLoadableDownload( e_LoadableDownloadKind, ans_LoadableDownloadComplete );
		if( False == b_Result ) {
			ss_MmbLoadableDownloadStatus = PCGD_ServiceLoadableInstall_NG;
		}
	}

	m_bl_UninstallAnime = False;														// プログレスを初期化.
}
//================================================================================================.
// 概要		 : PServiceSystemDriverInstall : 91518_MiB システム設定／ドライバーインストール: ダウンロード準備チェック通知(PKI).
//================================================================================================.
void PServiceSystemDriverInstall::ans_DownloadReady( const TYPE_AuthDevPki_Rsult e_Result, void* p_reserved )
{
	// ローダブルドライバーファイルチェックステータスを更新.
	ss_MmbLoadableCheckStatus = ( ( TYPE_AuthDevPki_Rsult_OK == e_Result ) ? PCGD_ServiceLoadableFileCheck_OK : PCGD_ServiceLoadableFileCheck_NG );
	CallBackIndi( TYPE_PNL_CallBack_LoadableDLCheck );
}
//================================================================================================.
// 概要		 : PServiceSystemDriverInstall : 91518_MiB システム設定／ドライバーインストール: ダウンロード完了通知(PKI).
//================================================================================================.
void PServiceSystemDriverInstall::ans_DownloadComplete( const TYPE_AuthDevPki_Rsult e_Result, void* p_reserved )
{
	// ローダブルドライバーダウンロードステータスを更新.
	ss_MmbLoadableDownloadStatus = ( ( TYPE_AuthDevPki_Rsult_OK == e_Result ) ? PCGD_ServiceLoadableInstall_OK : PCGD_ServiceLoadableInstall_NG );
	if( PCGD_ServiceLoadableInstall_OK == ss_MmbLoadableDownloadStatus ) {
		onlyPanel.bl_PowerOffOnMesage = True;									// 主電源OFF/ON画面から遷移させないためのフラグ.
		turnGamen = NULL;
	}
	CallBackIndi( TYPE_PNL_CallBack_LoadableDownload );
}
//================================================================================================.
// 概要		 : PServiceSystemDriverInstall : 91518_MiB システム設定／ドライバーインストール: ダウンロード準備チェック通知.
//================================================================================================.
void PServiceSystemDriverInstall::ans_LoadableDownloadReady( TYPE_LoadableDownloadKind _e_LoadableDownloadKind )
{
	// ローダブルドライバーファイルチェックステータスを更新.
	e_LoadableDownloadKind = _e_LoadableDownloadKind;
	ss_MmbLoadableCheckStatus = ( ( TYPE_LoadableDownloadKind_None != _e_LoadableDownloadKind ) ? PCGD_ServiceLoadableFileCheck_OK : PCGD_ServiceLoadableFileCheck_NG );
	CallBackIndi( TYPE_PNL_CallBack_LoadableDLCheck );
}
//================================================================================================.
// 概要		 : PServiceSystemDriverInstall : 91518_MiB システム設定／ドライバーインストール: ダウンロード完了通知.
//================================================================================================.
void PServiceSystemDriverInstall::ans_LoadableDownloadComplete( Bool b_Result )
{
	// ローダブルドライバーダウンロードステータスを更新.
	ss_MmbLoadableDownloadStatus = ( ( True == b_Result ) ? PCGD_ServiceLoadableInstall_OK : PCGD_ServiceLoadableInstall_NG );
	if( PCGD_ServiceLoadableInstall_OK == ss_MmbLoadableDownloadStatus ) {
		onlyPanel.bl_PowerOffOnMesage = True;									// 主電源OFF/ON画面から遷移させないためのフラグ.
		turnGamen = NULL;
	}
	CallBackIndi( TYPE_PNL_CallBack_LoadableDownload );
}

//================================================================================================.
// 概要		 : PServiceSystemDriverInstall : 91518_MiB システム設定／ドライバーインストール: インデックスボタン押下.
//================================================================================================.
void PServiceSystemDriverInstall::procIndexButton( uchar option )
{
	if( ( PCGD_ServiceLoadableInstall_ING == ss_MmbLoadableDownloadStatus ) || ( PCGD_ServiceLoadableInstall_OK == ss_MmbLoadableDownloadStatus ) ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}

	switch( option ) {
		case BTNID_IDX_SERVICEDRIVERINSTALL_INSTALL:		// インストールキー.
			MCR_setBuzzerType( PCGE_BuzzerType_InputNg );		// ブザー鳴動.
			break;
		case BTNID_IDX_SERVICEDRIVERINSTALL_UNINSTALL:		// アンインストールキー.
			nextGamen = &gp_ServiceSystemDriverUninstall;		// 82B91600 システム設定／ドライバーアンインストール.
			break;
		default:
			break;
	}
}
//================================================================================================
// 概要		 : PServiceSystemDriverInstall : 91518_MiB システム設定／ドライバーインストール: タブレット端末接続通知.
//================================================================================================
void PServiceSystemDriverInstall::procTabletDisconnect( uchar option )
{
	// ダウンロード時、ダウンロード完了時は処理を行わない.
	if( PCGD_ServiceLoadableInstall_OK == ss_MmbLoadableDownloadStatus
	    || PCGD_ServiceLoadableInstall_ING == ss_MmbLoadableDownloadStatus ) {
		return;
	}
	PServiceToSystemMenu2P2Com::procTabletDisconnect( option );

}

PNLS_ServiceDriverUninstall_Info PServiceSystemDriverUninstall::m_st_UninstallInfo[PNLE_ServiceDriverUninstallKindMAX] = {
	{ PNLE_ServiceDriverUninstallKindIC,	False,	False,	PNLE_ServiceDriverUninstallStatusIdle,	&Grp_ServiceDriverUninstallIC },	// IC.
	{ PNLE_ServiceDriverUninstallKindBIO,	False,	False,	PNLE_ServiceDriverUninstallStatusIdle,	&Grp_ServiceDriverUninstallBIO },	// 生体.
	{ PNLE_ServiceDriverUninstallKindPKI,	False,	False,	PNLE_ServiceDriverUninstallStatusIdle,	&Grp_ServiceDriverUninstallPKI },	// PKI.
// comment 2018/11/08 Sky嵯峨山 [特ROM][SPS].
	{ PNLE_ServiceDriverUninstallKindSPS,	False,	False,	PNLE_ServiceDriverUninstallStatusIdle,	&Grp_ServiceDriverUninstallSPS },	// SPS.
};
//comment 2018/03/27 HCLT-Haribhaskar [IT6_Eagle] [制御構成変更_No.113] Adding Reboot Functionality.
//================================================================================================.
// 概要		 : PServiceSystemDriverInstall : 91518_MiB システム設定／ドライバーインストール: タブレット端末接続通知.
//================================================================================================.
void PServiceSystemDriverInstall::Reboot()
{
	if ( PCGD_ServiceLoadableInstall_OK == ss_MmbLoadableDownloadStatus ) {
		nextGamen = &gp_ServiceReboot;
	} else {
		setBuzzerType( PCGE_BuzzerType_InputNg );
	}
}
//================================================================================================.
// PServiceSystemDriverUninstall : 82B91600 システム設定／ドライバーアンインストール: ラインキー押下.
//================================================================================================.
void PServiceSystemDriverUninstall::procGoToMag( uchar option )
{
	if( True == isUninstallStarted() ) {				// 削除実行後.
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}
	PServiceToSystemMenu2P2Com::procGoToMag( option );			// 親クラスのラインキー処理（サービス固有）をコール.
}
//================================================================================================.
// PServiceSystemDriverUninstall : 82B91600 システム設定／ドライバーアンインストール: ボタン押下.
//================================================================================================.
void PServiceSystemDriverUninstall::procButtonOn( uchar option )
{
//comment 2018/03/27 HCLT-Haribhaskar [IT6_Eagle] [制御構成変更_No.113] Adding the Reboot functionality.
	if (BTNID_GoToDriverUnInstallReboot != option ) {
		if( True == isUninstallStarted() ) {				// 削除実行後.
			MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
			return;
		}
	}

	switch( option ) {
		case BTNID_KEY_SERVICEDRIVERUNINSTALL_IC:			// IC.
		case BTNID_KEY_SERVICEDRIVERUNINSTALL_BIO:		// BIO.
		case BTNID_KEY_SERVICEDRIVERUNINSTALL_PKI:		// PKI.
// comment 2018/11/08 Sky嵯峨山 [特ROM][SPS].
		case BTNID_KEY_SERVICEDRIVERUNINSTALL_SPS:		// SPS.
		{
			uchar uc_index = static_cast<uchar>( option - BTNID_KEY_SERVICEDRIVERUNINSTALL_IC );
			m_st_UninstallInfo[uc_index].bl_Selected =
			    ( True == m_st_UninstallInfo[uc_index].bl_Selected )? False : True;	// トグル切り替え.
		}
		break;
		case BTNID_KEY_SERVICEDRIVERUNINSTALL_START:	// スタートキー.
			startUninstall();							// アンインストール開始.
			break;
//comment 2018/03/27 HCLT-Haribhaskar [IT6_Eagle] [制御構成変更_No.113] Adding the Reboot functionality.
		case BTNID_GoToDriverUnInstallReboot:
			Reboot();
			return;
		default:										// その他.
			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
			return;
	}
	setupGamen();		// 表示部品のセットアップ.
}
//================================================================================================.
// PServiceSystemDriverUninstall : 82B91600 システム設定／ドライバーアンインストール: OKキー押下.
//================================================================================================.
void PServiceSystemDriverUninstall::procOk( uchar option )
{
	if( True == isUninstallStarted() ) {				// 削除実行後.
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}
	PServiceToSystemMenu2P2Com::procOk( option );				// 親クラスの設定終了をコール.
}
//================================================================================================.
// PServiceSystemDriverUninstall : 82B91600 システム設定／ドライバーアンインストール: リセットキー押下.
//================================================================================================.
void PServiceSystemDriverUninstall::procReset( uchar option )
{
	if( True == isUninstallStarted() ) {				// 削除実行後.
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}
	PServiceToSystemMenu2P2Com::procReset( option );			// 親クラスのパネルリセットをコール.
}
//================================================================================================.
// PServiceSystemDriverUninstall : 82B91600 システム設定／ドライバーアンインストール: ユーザ補助(Accessibility)押下.
//================================================================================================.
void PServiceSystemDriverUninstall::procAccessibility( uchar option )
{
	if( True == isUninstallStarted() ) {				// 削除実行後.
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}
	PServiceToSystemMenu2P2Com::procAccessibility( option );	// 親クラスのユーザ補助をコール.
}

//================================================================================================.
// PServiceSystemDriverUninstall : 82B91600 システム設定／ドライバーアンインストール: コールバック処理.
//================================================================================================.
void PServiceSystemDriverUninstall::procCallBack( TYPE_PNL_CallBack option )
{
	switch( option ) {
		case TYPE_PNL_CallBack_LoadableDriverUninstallResult: // ローダブルドライバ削除結果通知.
			nextUninstall();	// 次のアンインストール実行.
			// アンインストールがすべて成功していた場合は電源OFF/ON画面フラグを有効にする.
			if( True == isUninstallFinished() ) {
				onlyPanel.bl_PowerOffOnMesage = True;								// 主電源OFF/ON画面から遷移させないためのフラグ.
				turnGamen = NULL;
			}
			setupGamen();		// 表示部品のセットアップ.
			break;
		default:									// その他.
			PServiceToSystemMenu2P2Com::procCallBack( option );		// 親クラスのコールバック処理をコール.
			return;
	}
}
//================================================================================================.
// PServiceSystemDriverUninstall : 82B91600 システム設定／ドライバーアンインストール: 定期起床.
//================================================================================================.
void PServiceSystemDriverUninstall::procTimerWakeUp( uchar option )
{
	PServiceToSystemMenu2P2Com::procTimerWakeUp( option );		// 親クラスの提起起床をコール.

	m_bl_UninstallAnime = ( True == m_bl_UninstallAnime )? False : True;		// 「／」⇔「＼」.
}
//================================================================================================.
// PServiceSystemDriverUninstall : 82B91600 システム設定／ドライバーアンインストール: 定期起床.
//================================================================================================.
void PServiceSystemDriverUninstall::startGamen()
{
	PBasicMessageProc::startGamen();

	// 状態を初期化する.
	for( short ss_index = 0; ss_index < PNLE_ServiceDriverUninstallKindMAX; ss_index++ ) {
		m_st_UninstallInfo[ss_index].bl_Installed = False;							// インストール状態.
		m_st_UninstallInfo[ss_index].bl_Selected = False;							// 選択状態.
		m_st_UninstallInfo[ss_index].e_Status = PNLE_ServiceDriverUninstallStatusIdle;  // アンインストール実行状態.
	}
	m_bl_UninstallAnime = False;

	// インストール状態更新.
	updateInstallStatus();

	// アンインストールを選択.
	Rbt_ServiceDriverMenuInstall.select( BTNID_IDX_SERVICEDRIVERINSTALL_UNINSTALL );

	// パーツ表示制御
	CheckShowParts();
}
//================================================================================================.
// PServiceSystemDriverUninstall : 82B91600 システム設定／ドライバーアンインストール: 画面セットアップ.
//================================================================================================.
void PServiceSystemDriverUninstall::setupGamen( short option )
{
	PServiceToSystemMenu2P2Com::setupGamen( option );		// 親クラスの表示部品のセットアップをコール.

	Bool bl_enableChangeScreen = True;	// 遷移キーの表示.
	Bool bl_messagePowerOffOn = False;	// 主電源OFF/ONメッセージ.
	short ss_index;

	if( True == isUninstallStarted() ) {
		// 削除を開始した場合.
		bl_enableChangeScreen = False;							// 遷移キーを非表示.
		Key_ServiceDriverUninstallStart.showEnable( False );	// 確定キー非表示.
	} else {
		Bool bl_KindSelected = False;							// 項目の選択状態.
		for( ss_index = 0; ss_index < PNLE_ServiceDriverUninstallKindMAX; ss_index++ ) {
			if( True == m_st_UninstallInfo[ss_index].bl_Selected ) {
				bl_KindSelected = True;
			}
		}
		// 項目選択時は、確定キー表示.
		Key_ServiceDriverUninstallStart.showEnable( bl_KindSelected );
	}

	// 各項目のセットアップ.
	for( ss_index = 0; ss_index < PNLE_ServiceDriverUninstallKindMAX; ss_index++ ) {
		setupUninstallInfo( &m_st_UninstallInfo[ss_index] );
	}

	// 電源OFFONメッセージの表示.
	if( True == isUninstallFinished() ) {
		bl_messagePowerOffOn = True;
	}
	Grp_ServiceDriverInstallMsgPowerOffOn.showEnable( bl_messagePowerOffOn );

	// OKキー、ﾗｲﾝキー表示を制御.
	Key_OkService.showEnable( bl_enableChangeScreen );
	if( False == bl_enableChangeScreen ) {
		Key_ServiceToLine.showEnable( False );
	}

	printLEDControl( False );		// スタートLED制御.
}
//================================================================================================.
// 概要		 : PServiceSystemDriverUninstall : 82B91600 システム設定／ドライバーアンインストール: インデックスボタン押下.
//================================================================================================.
void PServiceSystemDriverUninstall::procIndexButton( uchar option )
{
	if( True == isUninstallStarted() ) {				// 削除実行後.
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}

	switch( option ) {
		case BTNID_IDX_SERVICEDRIVERINSTALL_INSTALL:		// インストールキー.
			nextGamen = &gp_ServiceSystemDriverInstall;		// 91518_MiB システム設定／ドライバーインストール.
			break;
		case BTNID_IDX_SERVICEDRIVERINSTALL_UNINSTALL:		// アンインストールキー.
			MCR_setBuzzerType( PCGE_BuzzerType_InputNg );		// ブザー鳴動.
			break;
		default:
			break;
	}
}

//================================================================================================.
// PServiceSystemDriverUninstall : 82B91600 システム設定／ドライバーアンインストール: 表示部品のセットアップ(１データ).
//================================================================================================.
void PServiceSystemDriverUninstall::setupUninstallInfo( PNLS_ServiceDriverUninstall_Info* ps_UninstallInfo )
{
	// NULLチェック.
	if( ( NULL == ps_UninstallInfo ) || ( NULL == ps_UninstallInfo->pc_GroupParts ) ) {
// Comment 2015/11/02 【ZeusS_ZX0】【HCL_Vasu】【制御構成変更_No.76-1】Adding Error Code macro.
		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
		if (NULL !=pc_BFW_System){
			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x1900660101051F01 );
		}
		return;
	}

	PGroupParts* pc_Grp = ps_UninstallInfo->pc_GroupParts;
	if( False == ps_UninstallInfo->bl_Installed ) {	// インストールされていない場合は、非表示.
		pc_Grp->showEnable( False );
		return;
	}

	// パーツのポインタを取得.
	POnOffButton* pc_Kind = dynamic_cast<POnOffButton*>( pc_Grp->getPartsAddress( PNLE_ServiceDriverUninstallPartsKind ) );
	PSinglePartsText* pc_Status = dynamic_cast<PSinglePartsText*>( pc_Grp->getPartsAddress( PNLE_ServiceDriverUninstallPartsStatus ) );
	PSinglePartsText* pc_Progress = dynamic_cast<PSinglePartsText*>( pc_Grp->getPartsAddress( PNLE_ServiceDriverUninstallPartsProgress ) );

	// 種別キーの選択表示.
	if( NULL != pc_Kind ) {
		pc_Kind->select( ps_UninstallInfo->bl_Selected );
	}

	// アンインストール実行後は、状態表示.
	if( True == isUninstallStarted() ) {

		// 削除状態表示.
		if( NULL != pc_Status ) {
			TEXT_ID textId_Status;
			switch( ps_UninstallInfo->e_Status ) {
				case PNLE_ServiceDriverUninstallStatusIdle:		textId_Status = s_Space1;			break;	// ブランク.
				case PNLE_ServiceDriverUninstallStatusWait:		textId_Status = s_Space1;			break;	// ブランク.
				case PNLE_ServiceDriverUninstallStatusExecuting:textId_Status = s_ITMServiceRunning; break;	// 削除中.
				case PNLE_ServiceDriverUninstallStatusFailed:	textId_Status = s_NG;				break;	// NG.
				case PNLE_ServiceDriverUninstallStatusComplete:	textId_Status = s_Ok;				break;	// OK.
				default:										textId_Status = s_Space1;			break;	// ブランク.
			}
			pc_Status->changeText( textId_Status );
		}
		// 「／」「＼」.
		if( NULL != pc_Progress ) {
			if( PNLE_ServiceDriverUninstallStatusExecuting == ps_UninstallInfo->e_Status ) {
				TEXT_ID textId_Progress = ( m_bl_UninstallAnime )? s_EXPSlash: s_EXPBackslash;
				pc_Progress->changeText( textId_Progress );
				pc_Progress->showEnable( True );
			} else {
				pc_Progress->showEnable( False );
			}
		}
	}
}
//================================================================================================.
// PServiceSystemDriverUninstall : 82B91600 システム設定／ドライバーアンインストール: インストール開始.
//================================================================================================.
Bool PServiceSystemDriverUninstall::startUninstall()
{
	for( short ss_index = 0; ss_index < PNLE_ServiceDriverUninstallKindMAX; ss_index++ ) {
		if( m_st_UninstallInfo[ss_index].bl_Selected ) {
			m_st_UninstallInfo[ss_index].e_Status = PNLE_ServiceDriverUninstallStatusWait;	// 待機中.
		}
	}
	return nextUninstall();	// アンインストール開始.

}
//================================================================================================.
// PServiceSystemDriverUninstall : 82B91600 システム設定／ドライバーアンインストール: 次のインストール開始.
//================================================================================================.
Bool PServiceSystemDriverUninstall::nextUninstall()
{
	Bool bl_Result = False;

	for( short ss_index = 0; ss_index < PNLE_ServiceDriverUninstallKindMAX; ss_index++ ) {
		// 実行待ちを検索.
		if( PNLE_ServiceDriverUninstallStatusWait == m_st_UninstallInfo[ss_index].e_Status ) {

			// CommonAPIに削除要求.
			Bool bl_ResultApi = False;	// APIのコール結果.
			TYPE_LoadableDownloadKind e_UninstallKind = TYPE_LoadableDownloadKind_None;
			switch( m_st_UninstallInfo[ss_index].e_Kind ) {
				case PNLE_ServiceDriverUninstallKindIC:	e_UninstallKind = TYPE_LoadableDownloadKind_Icc; break;
				case PNLE_ServiceDriverUninstallKindBIO:e_UninstallKind = TYPE_LoadableDownloadKind_Bio; break;
				case PNLE_ServiceDriverUninstallKindPKI:e_UninstallKind = TYPE_LoadableDownloadKind_PKI; break;
// comment 2018/11/08 Sky嵯峨山 [特ROM][SPS].
				case PNLE_ServiceDriverUninstallKindSPS:e_UninstallKind = TYPE_LoadableDownloadKind_Sps; break;
				default: break;
			}
			if( TYPE_LoadableDownloadKind_None != e_UninstallKind ) {
				// APIコール.
				bl_ResultApi = APIC_AuthLoadableDriver::newInstance()->reqLoadableUninstall( e_UninstallKind, ans_LoadableUninstallResult );
			}
			// 結果.
			if( True == bl_ResultApi ) {	// 要求成功.
				m_st_UninstallInfo[ss_index].e_Status = PNLE_ServiceDriverUninstallStatusExecuting;	// 実行中.
				m_bl_UninstallAnime = False;														// プログレスを初期化.
			} else {						// 要求失敗.
				m_st_UninstallInfo[ss_index].e_Status = PNLE_ServiceDriverUninstallStatusFailed;	// 失敗中.
				CallBackIndi( TYPE_PNL_CallBack_LoadableDriverUninstallResult );
			}

			// 処理を行った場合は、Trueを返す.
			bl_Result = True;
			break;
		}
	}
	return bl_Result;
}
//================================================================================================.
// PServiceSystemDriverUninstall : 82B91600 システム設定／ドライバーアンインストール: インストール状態の更新.
//================================================================================================.
void PServiceSystemDriverUninstall::updateInstallStatus()
{
	for( short ss_index = 0; ss_index < PNLE_ServiceDriverUninstallKindMAX; ss_index++ ) {
		// インストール情報を取得する.
		Bool bl_chkInstalled = False;
		switch( m_st_UninstallInfo[ss_index].e_Kind ) {
			case PNLE_ServiceDriverUninstallKindIC:
				bl_chkInstalled = APIC_AuthLoadableDriver::newInstance()->chkInstallLoadableDriver( TYPE_RomDownloadableDriver1 );
				break;
			case PNLE_ServiceDriverUninstallKindBIO:
				bl_chkInstalled = APIC_AuthLoadableDriver::newInstance()->chkInstallLoadableDriver( TYPE_RomDownloadableDriver2 );
				break;
			case PNLE_ServiceDriverUninstallKindPKI:
				bl_chkInstalled = APIC_AuthLoadableDriver::newInstance()->chkInstallLoadableDriverPKI();
				break;
// comment 2018/11/08 Sky嵯峨山 [特ROM][SPS].
			case PNLE_ServiceDriverUninstallKindSPS:
				bl_chkInstalled = APIC_AuthLoadableDriver::newInstance()->chkInstallLoadableDriverSPS();
				break;
			default:
				break;
		}
		m_st_UninstallInfo[ss_index].bl_Installed = bl_chkInstalled;
	}
}
//================================================================================================.
// PServiceSystemDriverUninstall : 82B91600 システム設定／ドライバーアンインストール: アンインストールの終了チェック.
//================================================================================================.
Bool PServiceSystemDriverUninstall::isUninstallFinished()
{
	Bool bl_Result = True;
	// 開始していない場合、
	if( False == isUninstallStarted() ) {
		bl_Result = False;
	} else {
		// 開始している場合.
		for( short ss_index = 0; ss_index < PNLE_ServiceDriverUninstallKindMAX; ss_index++ ) {
			// 実行待ち、実行中がある場合は、完了しない.
			if( ( PNLE_ServiceDriverUninstallStatusWait == m_st_UninstallInfo[ss_index].e_Status )
			    || ( PNLE_ServiceDriverUninstallStatusExecuting == m_st_UninstallInfo[ss_index].e_Status ) ) {
				bl_Result = False;
				break;
			}
		}
	}
	return bl_Result;
}
//================================================================================================.
// PServiceSystemDriverUninstall : 82B91600 システム設定／ドライバーアンインストール: アンインストール実行後チェック.
//================================================================================================.
Bool PServiceSystemDriverUninstall::isUninstallStarted()
{
	Bool bl_Result = False;
	// ステイタスがアイドル以外の場合は、実行開始後.
	for( short ss_index = 0; ss_index < PNLE_ServiceDriverUninstallKindMAX; ss_index++ ) {
		if( PNLE_ServiceDriverUninstallStatusIdle != m_st_UninstallInfo[ss_index].e_Status ) {
			bl_Result = True;
			break;
		}
	}
	return bl_Result;
}
//================================================================================================.
// PServiceSystemDriverUninstall : 82B91600 システム設定／ドライバーアンインストール: アンインストール結果コールバック通知.
//================================================================================================.
void PServiceSystemDriverUninstall::ans_LoadableUninstallResult( Bool bl_Result )
{
	for( short ss_index = 0; ss_index < PNLE_ServiceDriverUninstallKindMAX; ss_index++ ) {
		// 実行中のものに結果をセット.
		if( PNLE_ServiceDriverUninstallStatusExecuting == m_st_UninstallInfo[ss_index].e_Status ) {
			m_st_UninstallInfo[ss_index].e_Status = ( True == bl_Result )? PNLE_ServiceDriverUninstallStatusComplete: PNLE_ServiceDriverUninstallStatusFailed;
			break;
		}
	}

	// コールバックイベント.
	CallBackIndi( TYPE_PNL_CallBack_LoadableDriverUninstallResult );
}
//================================================================================================.
// PServiceSystemDriverUninstall : 82B91600 システム設定／ドライバーアンインストール:ドライバーのインストール済みチェック.
//================================================================================================.
Bool PServiceSystemDriverUninstall::checkDriverInstalled()
{
	Bool bl_chkInstalled = False;
	for( short ss_index = 0; ss_index < PNLE_ServiceDriverUninstallKindMAX; ss_index++ ) {
		// インストール情報を取得する.
		switch( m_st_UninstallInfo[ss_index].e_Kind ) {
			case PNLE_ServiceDriverUninstallKindIC:
				bl_chkInstalled = APIC_AuthLoadableDriver::newInstance()->chkInstallLoadableDriver( TYPE_RomDownloadableDriver1 );
				break;
			case PNLE_ServiceDriverUninstallKindBIO:
				bl_chkInstalled = APIC_AuthLoadableDriver::newInstance()->chkInstallLoadableDriver( TYPE_RomDownloadableDriver2 );
				break;
			case PNLE_ServiceDriverUninstallKindPKI:
				bl_chkInstalled = APIC_AuthLoadableDriver::newInstance()->chkInstallLoadableDriverPKI();
				break;
			case PNLE_ServiceDriverUninstallKindSPS:
// comment 2018/11/08 Sky嵯峨山 [特ROM][SPS].
				bl_chkInstalled = APIC_AuthLoadableDriver::newInstance()->chkInstallLoadableDriverSPS();
				break;
			default:
				break;
		}
		if( True == bl_chkInstalled ) {
			break;
		}
	}
	return bl_chkInstalled;
}
//================================================================================================
// 概要		 : PServiceSystemDriverUninstall : 82B91600 システム設定／ドライバーアンインストール: タブレット端末接続通知.
//================================================================================================
void PServiceSystemDriverUninstall::procTabletDisconnect( uchar option )
{
	// アンインストール中、アンインストール成功時は処理を行わない.
	if( True == isUninstallFinished() ) {
		return;
	}
	for( short ss_index = 0; ss_index < PNLE_ServiceDriverUninstallKindMAX; ss_index++ ) {
		// 実行待ち、実行中がある場合は、処理しない.
		if( ( PNLE_ServiceDriverUninstallStatusWait == m_st_UninstallInfo[ss_index].e_Status )
		    || ( PNLE_ServiceDriverUninstallStatusExecuting == m_st_UninstallInfo[ss_index].e_Status ) ) {
			return;
		}
	}

	PServiceToSystemMenu2P2Com::procTabletDisconnect( option );

}
//comment 2018/03/27 HCLT-Haribhaskar [IT6_Eagle] [制御構成変更_No.113] Adding the Reboot functionality.
//================================================================================================
// 概要		 : PServiceSystemDriverUninstall : 82B91600 システム設定／ドライバーアンインストール: タブレット端末接続通知.
//================================================================================================
void PServiceSystemDriverUninstall::Reboot()
{
	if( True == isUninstallFinished() ) {
		nextGamen = &gp_ServiceReboot;
	}else {
		setBuzzerType( PCGE_BuzzerType_InputNg );
	}
}
// サービスモード移行コールバック関数
static void ans_setServiceModeOn( Bool b_isServiceModeOn )
{
	if( onlyPanel.isNowModeChangingToService() == True ) {
		onlyPanel.setNowModeChangingToService( False );
	}
}
// ===============================================================================================.
// 概要		: PServiceLogOutput:ログ出力クラス 画面開始処理.
// 戻り値	: なし
// 備考		: .
// ===============================================================================================.
void PServiceLogOutput::startGamen() {
	PBasicMessageProc::startGamen();

	onlyPanel.bl_PowerOffOnMesage = True;	// 主電源OFF/ON画面から遷移させないためのフラグ
	turnGamen = &gp_ServiceLogOutput;		// オートリセットからの戻り画面.

	// システム状態（ＡＰＩ）・インスタンス取得
	APIC_SystemStatus* pc_SystemStatus = APIC_SystemStatus::newInstance();
	if( pc_SystemStatus->getServiceModeOn() != True ) {
		pc_SystemStatus->req_setServiceModeOn( True, ans_setServiceModeOn ); // サービスモード中に設定.
	}
	onlyPanel.bl_ServiceMode = True;	// パネル内部フラグを設定.

	// オートクリアタイマーリセット処理.
	c_autoRestTimer.c_AutoResetAll.resetTimer( False );
	c_autoRestTimer.c_autoResetOffTimer.resetTimer( False );
	// 各ジョブモードタイマー停止（リセット）.
	c_autoRestTimer.stopEachJobAutoResetTimer();

	printLEDControl( False );	// スタートLEDを赤にする.

	// ログ出力状態.
	m_uc_LogOutputStatus = PNLE_LogOutputStatus_No;
}
// ===============================================================================================.
// 概要		: PServiceLogOutput:ログ出力クラス 画面表示のセットアップ.
// 戻り値	: なし
// 備考		: .
// ===============================================================================================.
void PServiceLogOutput::setupGamen( short option ) {
	// ログ出力状態.
	PNLE_LogOutputStatus e_LogOutputStatus = PLBC_LogOutputStatus::getInstance()->getLogOutputStatus();

	// ログ出力中.
	if( PNLE_LogOutputStatus_Output == e_LogOutputStatus ) {
		Txt_PowerOff.showEnable( False );			// 「必ず電源OFF/ONしてください」.
		Txt_LogOutputagain.showEnable( False );		// 「10秒間登録ｷｰ1押下によりﾛｸﾞを再出力できます」.
		Txt_LogOutputting.showEnable( True );		// 「ログ出力中」.
	} else {
		Txt_LogOutputting.showEnable( False );		// 「ログ出力中」.
		Txt_PowerOff.showEnable( True );			// 「必ず電源OFF/ONしてください」.
		Txt_LogOutputagain.showEnable( True );		// 「10秒間登録ｷｰ1押下によりﾛｸﾞを再出力できます」.
	}
}
//================================================================================================.
// 概要		: PServiceLogOutput:ログ出力クラス １秒タイマ.
// 戻り値	: なし
// 備考		: .
//================================================================================================.
void PServiceLogOutput::procSecond( uchar option ) {
	PMessageProcCom::procSecond( option );		// 親クラスの定期起床をコール.

	// ログ出力状態.
	PNLE_LogOutputStatus e_LogOutputStatus = PLBC_LogOutputStatus::getInstance()->getLogOutputStatus();

	// 再出力要求あり.
	if( ( e_LogOutputStatus != m_uc_LogOutputStatus ) && ( PNLE_LogOutputStatus_Output == e_LogOutputStatus ) ) {
		// ログ出力開始.
		startLogOutput();

	}
}
// ===============================================================================================.
// 概要		: PServiceLogOutput:ログ出力クラス コールバック.
// 戻り値	: なし
// 備考		: .
// ===============================================================================================.
extern "C" {
	void panellogout( int, int );
}
void PServiceLogOutput::ans_TroubleLogALL() {

	// ログ出力完了通知[生産Logger].
	CallBackIndi( TYPE_PNL_CallBack_LogOutputComplete );			// コールバックイベント発生
}
// ===============================================================================================.
// 概要		: PServiceLogOutput:ログ出力クラス ログ出力開始.
// 戻り値	: なし
// 備考		: .
// ===============================================================================================.
void PServiceLogOutput::startLogOutput() {
	// ログ出力状態.
	m_uc_LogOutputStatus = PLBC_LogOutputStatus::getInstance()->getLogOutputStatus();

	// ログ出力開始要求.
	APIC_DebugLogSystem::newInstance()->req_TroubleLogALL( ans_TroubleLogALL );
}
//================================================================================================.
// 概要		: PServiceLogOutput:ログ出力クラス コールバック処理.
// 戻り値	: なし
// 備考		: printf()の出力文字はdbg側指示による.
//================================================================================================.
void PServiceLogOutput::procCallBack( TYPE_PNL_CallBack option )
{
	switch( option ) {
		case TYPE_PNL_CallBack_LogOutputComplete:	// ログ出力完了通知[生産Logger].

			printf( "-> panellogout\n" );
			panellogout( 0, 0 );				// panellogout.

			// ログ出力状態遷移(初期状態).
			PLBC_LogOutputStatus::getInstance()->changeLogStatus( PNLE_LogOutputStatus_Output_End );

			// 効果音鳴動.
			setBuzzerType( PCGE_BuzzerType_CommunicationEnd );
			break;
		default:									// その他.
			PServiceCom::procCallBack( option );	// 親クラスのコールバック処理をコール.
			break;
	}
}

