//===================================================================.
/**
* @brief  : procOk.
* @note   : None.
* @param  : [in] uchar.
* @return : None.
*/
//===================================================================.
void PCGC_MaintenanceModeSetting::procOk( uchar option )
{
	TYPE_Language uc_LangSel;

	APIC_SystemInfo* pc_SystemInfo = APIC_SystemInfo::newInstance();
	if( True == m_bl_MaintenanceModeStatus )
	{
		uc_LangSel = PnlComGetMachineSetting()->getLanguage();
		pc_SystemInfo->setEnableMaintenanceMode( m_bl_MaintenanceModeStatus );
		if( m_uc_LanguageSettings != PNLE_LangSettingsNone ) {
// comment 2015/12/01 OPS1-MSE二宮 [ZeusS_ZX0][CQ518783] 言語選択のBMP→プロポーショナルフォント化対応.
//			uc_LangSel = pst_graphic_table[m_uc_LanguageSettings-1]->e_Language;
			uc_LangSel = m_pst_langTable[m_uc_LanguageSettings-1]->e_Language;
		}
		pc_SystemInfo->setMaintenanceModeLanguage( uc_LangSel );
		pc_SystemInfo->setJobRecordClear( m_bl_JobHistoryClear );
	} else {
		pc_SystemInfo->setEnableMaintenanceMode( False );
		uc_LangSel = PnlComGetMachineSetting()->getLanguage();
	}
// comment 2020/10/22 Sky中野 [IT6_2.1][OP_BTS-28575].
//	onlyPanel.e_Language = uc_LangSel;
//	PnlComGetOperationSetting()->setSelectLanguage( onlyPanel.e_Language );
	PnlComSetSelectLanguage( uc_LangSel );
	int iret;
	SHM_TYPE_DATA* p = NULL;
	DivCommon_Shm* p_DivCommon_Shm = DivCommon_Shm::newInstance();
	iret = p_DivCommon_Shm->Shm_attach( ( void* )&p );
	if( iret == 0 )
	{
		p->e_Language_no_Int = onlyPanel.e_Language;
		iret = p_DivCommon_Shm->Shm_detattch( p );
	}
	loadSelectLangType_IOP( uc_LangSel );
// comment 2015/06/19 【HCLT-Ashok】 【MiSBK】 【CQ515230】 Assigned 3rd page Gamen instance for MineraSBk.
// Custom pattern button is moved to 3 page, changed destination when OK pressed in case of Function version 2.2.
//	comment 2015/05/19 【HCLT-Juned】 【MiSBK】 【機器構成変更_No.30】 Assigned 3rd page Gamen instance for MineraSBk.
// #ifdef DEF_MINERVASBK_CUS
// Comment 2017/11/29 【HCLT-Vishal】【Eagle】【制御構成変更_No.4】 Removing old function version check and else portion.
	nextGamen = &gp_ServiceSystemMenu2P3_DoAm;	// Page 3.
// #endif // DEF_MINERVASBK_CUS.
}


//===================================================================.
/**
* @brief  : procButtonOn.
* @note   : None.
* @param  : [in] uchar.
* @return : None.
*/
//===================================================================.
void PCGC_MaintenanceModeSetting::procButtonOn( uchar option )
{
	switch( option )
	{
		case BTNID_MaintenanceModeDisable:
			m_bl_MaintenanceModeStatus = False;
			break;
		case BTNID_MaintenanceModeEnable:
			m_bl_MaintenanceModeStatus = True;
			break;
		case BTNID_MaintenanceModeLanguageOFF:
			m_uc_LanguageSettings = PNLE_LangSettingsNone;
			break;
		case BTNID_MaintenanceModeLanguage1:
			m_uc_LanguageSettings = PNLE_LangSettings1;
			break;
		case BTNID_MaintenanceModeLanguage2:
			m_uc_LanguageSettings = PNLE_LangSettings2;
			break;
		case BTNID_MaintenanceModeLanguage3:
			m_uc_LanguageSettings = PNLE_LangSettings3;
			break;
		case BTNID_MaintenanceModeLanguage4:
			m_uc_LanguageSettings = PNLE_LangSettings4;
			break;
		case BTNID_MaintenanceModeLanguage5:
			m_uc_LanguageSettings = PNLE_LangSettings5;
			break;
		case BTNID_MaintenanceModeLanguage6:
			m_uc_LanguageSettings = PNLE_LangSettings6;
			break;
		case BTNID_MaintenanceModeLanguage7:
			m_uc_LanguageSettings = PNLE_LangSettings7;
			break;
		case BTNID_MaintenanceModeLanguage8:
			m_uc_LanguageSettings = PNLE_LangSettings8;
			break;
		case BTNID_MaintenanceModeLanguage9:
			m_uc_LanguageSettings = PNLE_LangSettings9;
			break;
		case BTNID_MaintenanceModeJobHistoryDisable:
			m_bl_JobHistoryClear = True;
			break;
		case BTNID_MaintenanceModeJobHistoryEnable:
			m_bl_JobHistoryClear = False;
			break;
		default:
			break;
	}
	setupGamen( option );
}

