//				pst_graphic_table[i] = &st_LangGraphicTbl[j];
//				break;
//			}
//		}
//	}
//	sl_LangNum = getLangCount();
//	bl_std = isStandardMSGBinary();
//	if( bl_std == True ) {
//		pst_graphic_table[0] = &st_LangGraphicTbl[1];
//		pst_graphic_table[1] = &st_LangGraphicTbl[3];
//		pst_graphic_table[2] = &st_LangGraphicTbl[4];
//		pst_graphic_table[3] = &st_LangGraphicTbl[2];
//		pst_graphic_table[4] = &st_LangGraphicTbl[9];
//		pst_graphic_table[5] = &st_LangGraphicTbl[0];
//		pst_graphic_table[6] = &st_LangGraphicTbl[17];
