	PNLC_LanguageSelectionLib* pc_LanguageSelectionLib = PNLC_LanguageSelectionLib::newInstance();
	if( NULL == pc_LanguageSelectionLib ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	pc_LanguageSelectionLib->setLangTbl();
	pc_LanguageSelectionLib->getLanguageCount( m_sl_LangNum );
	m_pst_langTable = pc_LanguageSelectionLib->getLangTbl();
	if( NULL == m_pst_langTable ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
