/*================================================================================================
// 概要		:サービス・課金設定・BillingCounter設定: ボタン(押された).
// 戻り値	:なし
// 備考		:
================================================================================================*/
void PServiceBillingCounterSetting::procButtonOn( uchar option )
{
	PLBC_BillingCounterManager* pc_BillingCounterManager = PLBC_BillingCounterManager::getInstance();		// PLBC_BillingCounterManagerインスタンス取得.
	if( NULL == pc_BillingCounterManager ) {
// Comment 2015/11/02 【ZeusS_ZX0】【HCL_Vasu】【制御構成変更_No.76-1】Adding Error Code macro.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//		if (NULL !=pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19000A0101352301 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}
	switch( option ) {
		case BTNID_ServiceBillingCounterSetting_Enable:	// YMC使用設定有効.
			m_e_YmcUseSetup = TYPE_FuncEnable_ON;
			pc_BillingCounterManager->setYmcUseSetting( m_e_YmcUseSetup );
			break;
		case BTNID_ServiceBillingCounterSetting_Disable: // YMC使用設定無効.
			m_e_YmcUseSetup = TYPE_FuncEnable_OFF;
			pc_BillingCounterManager->setYmcUseSetting( m_e_YmcUseSetup );
			break;
		case BTNID_ServiceBillingCounterSetting_SmallSize:
			m_e_paperSize = PNLE_BillingCounterPaperSize_Small;
			break;
		case BTNID_ServiceBillingCounterSetting_A4Size:
			m_e_paperSize = PNLE_BillingCounterPaperSize_A4;
			break;
		case BTNID_ServiceBillingCounterSetting_LargeSize:
			m_e_paperSize = PNLE_BillingCounterPaperSize_Large;
			break;
		case BTNID_ServiceBillingCounterSetting_Banner:
			m_e_paperSize = PNLE_BillingCounterPaperSize_Bunner;
			break;
		default: LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );	break;
	}
	setupGamen( 0 );
}
