	pc_BillingCounterManager->getStartPram( &m_e_colorMode,&m_e_paperSize,&m_uc_divisionNumber );
	PNLE_CovaregeCntSizeOnColors e_covaregRateMode = PNLE_CovaregeCntColorSmall;
	e_covaregRateMode = pc_BillingCounterManager->getCovarageRateKind( m_e_colorMode,m_e_paperSize );
	pc_BillingCounterManager->getCoverageRateData( e_covaregRateMode,&m_s_coverageRateYMCK,&m_s_CoverageRateCoefficient );

	m_uc_InputMode = PNLD_BillingCounterCoverageRateDivisionNum0;	// 選択ボタンの初期化.
	m_bl_UpdateFlg = False;											// 更新中フラグを初期化.
