/*================================================================================================
// 概要		:サービス・課金設定・印字率係数入力: 初期設定.
// 戻り値	:なし
// 備考		:
================================================================================================*/
void PServiceBillingCounterCoverageRateCoefficientSetting::startGamen()
{
	// 起動パラメータを取得
	PLBC_BillingCounterManager* pc_BillingCounterManager = PLBC_BillingCounterManager::getInstance();	// PLBC_BillingCounterManagerインスタンス取得.
	if( NULL == pc_BillingCounterManager ) {
// Comment 2015/11/02 【ZeusS_ZX0】【HCL_Vasu】【制御構成変更_No.76-1】Adding Error Code macro.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//		if (NULL !=pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x1900650101352C01 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}
	pc_BillingCounterManager->getStartPram( &m_e_colorMode,&m_e_paperSize,&m_uc_divisionNumber );
	m_uc_InputMode = ( uchar )( m_uc_divisionNumber - 1 );

	// カバレッジレートの設定値を取得.
	PNLE_CovaregeCntSizeOnColors e_covaregRateMode = PNLE_CovaregeCntColorSmall;
	e_covaregRateMode = pc_BillingCounterManager->getCovarageRateKind( m_e_colorMode,m_e_paperSize );
	pc_BillingCounterManager->getCoverageRateData( e_covaregRateMode,&m_s_coverageRateYMCK,&m_s_CoverageRateCoefficient );

	m_bl_UpdateFlg = False;		// 更新中フラグを初期化.
	m_s_nowFigure = 0;			// 入力中桁数を初期化.
	m_ul_range4 = 0;			// 範囲4を初期化.
	m_ul_range3 = 0;			// 範囲3を初期化.
	m_ul_range2 = 0;			// 範囲2を初期化.
	m_ul_range1 = 0;			// 範囲1を初期化.

	PServiceActionVendorSetCom::startGamen();
}
/*================================================================================================
// 概要		:サービス・課金設定・印字率係数入力: ＯＫキー.
// 戻り値	:なし
// 備考		:
================================================================================================*/
void PServiceBillingCounterCoverageRateCoefficientSetting::procOk( uchar option )
{
	// 入力値チェック
	if( False == inputRangeUpdate( m_uc_InputMode ) ) {
		setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}

	// CommonAPIにYMC／YMCK合計印字率設定.
	PLBC_BillingCounterManager* pc_BillingCounterManager = PLBC_BillingCounterManager::getInstance();	// PLBC_BillingCounterManagerインスタンス取得.
	if( NULL == pc_BillingCounterManager ) {
// Comment 2015/11/02 【ZeusS_ZX0】【HCL_Vasu】【制御構成変更_No.76-1】Adding Error Code macro.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//		if (NULL !=pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x1900030101352D01 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}
	PNLE_CovaregeCntSizeOnColors e_covaregRateMode = PNLE_CovaregeCntColorSmall;
	e_covaregRateMode = pc_BillingCounterManager->getCovarageRateKind( m_e_colorMode,m_e_paperSize );
	pc_BillingCounterManager->setCoverageRateCoefficient( e_covaregRateMode,&m_s_CoverageRateCoefficient );

	pc_BillingCounterManager->setStartPram( m_e_colorMode,m_e_paperSize,m_uc_divisionNumber );
	nextGamen = &gp_PServiceBillingCounterSetting;		//BillingCounter設定画面.
}

//================================================================================================.
// 概要 : サービス・課金設定・印字率係数入力: テンキー押下処理.
// 戻り値	:なし
// 備考		:
//================================================================================================.
void PServiceBillingCounterCoverageRateCoefficientSetting::proc10Key( uchar option )
{
	// 3桁の場合は受付拒否
	if( PNLD_BillingCounterCoverageRateCoefficienMaxInputBeam == m_s_nowFigure ) {
		setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}
	// 小数点計算.
	else {
		PLBC_BillingCounterManager* pc_BillingCounterManager = PLBC_BillingCounterManager::getInstance();	// PLBC_BillingCounterManagerインスタンス取得.
		if( NULL == pc_BillingCounterManager ) {
// Comment 2015/11/02 【ZeusS_ZX0】【HCL_Vasu】【制御構成変更_No.76-1】Adding Error Code macro.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//		if (NULL !=pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19002A0101352E01 );
//		}
			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
			return;
		}
		char uc_StrBuf[PNLD_BillingCounterConvertStrMax];	// 数値変換用文字列.
		memset( &uc_StrBuf[0],'\0',PNLD_BillingCounterConvertStrMax );

		if( PNLD_BillingCounterCoverageRateCoefficienRange4 == m_uc_InputMode ) {
			m_ul_range4 *= PNLD_BillingCounterCoverageRateBeamCalcVal;
			m_ul_range4 += option;
			pc_BillingCounterManager->ulToStrDecpnt( m_ul_range4,&uc_StrBuf[0],PNLD_BillingCounterConvertStrMax );	// 範囲4.
			Bak_SServiceCoverageRateCoefficientSettingRange4.changeTextString( ( const uchar* )uc_StrBuf );
		}
		else if( PNLD_BillingCounterCoverageRateCoefficienRange3 == m_uc_InputMode ) {
			m_ul_range3 *= PNLD_BillingCounterCoverageRateBeamCalcVal;
			m_ul_range3 += option;
			pc_BillingCounterManager->ulToStrDecpnt( m_ul_range3,&uc_StrBuf[0],PNLD_BillingCounterConvertStrMax );	// 範囲4.
			Bak_SServiceCoverageRateCoefficientSettingRange3.changeTextString( ( const uchar* )uc_StrBuf );
		}
		else if( PNLD_BillingCounterCoverageRateCoefficienRange2 == m_uc_InputMode ) {
			m_ul_range2 *= PNLD_BillingCounterCoverageRateBeamCalcVal;
			m_ul_range2 += option;
			pc_BillingCounterManager->ulToStrDecpnt( m_ul_range2,&uc_StrBuf[0],PNLD_BillingCounterConvertStrMax );	// 範囲4.
			Bak_SServiceCoverageRateCoefficientSettingRange2.changeTextString( ( const uchar* )uc_StrBuf );
		}
		else {
			m_ul_range1 *= PNLD_BillingCounterCoverageRateBeamCalcVal;
			m_ul_range1 += option;
			pc_BillingCounterManager->ulToStrDecpnt( m_ul_range1,&uc_StrBuf[0],PNLD_BillingCounterConvertStrMax );	// 範囲4.
			Bak_SServiceCoverageRateCoefficientSettingRange1.changeTextString( ( const uchar* )uc_StrBuf );
		}
		m_s_nowFigure++;
		m_bl_UpdateFlg = True;		// 更新中フラグをTrue.
	}
	setupGamen( 0 );
}
//================================================================================================.
// 概要 : サービス・課金設定・印字率係数入力: クリアキー押下処理.
// 戻り値	:なし
// 備考		:
//================================================================================================.
void PServiceBillingCounterCoverageRateCoefficientSetting::procClear( uchar option )
{
	// クリアーキー押下時に入力位置の値をクリア.
	PLBC_BillingCounterManager* pc_BillingCounterManager = PLBC_BillingCounterManager::getInstance();	// PLBC_BillingCounterManagerインスタンス取得.
	if( NULL == pc_BillingCounterManager ) {
// Comment 2015/11/02 【ZeusS_ZX0】【HCL_Vasu】【制御構成変更_No.76-1】Adding Error Code macro.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//		if (NULL !=pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19002B0101352F01 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}
	char uc_StrBuf[PNLD_BillingCounterConvertStrMax];	// 数値変換用文字列.
	memset( &uc_StrBuf[0],'\0',PNLD_BillingCounterConvertStrMax );
	if( m_uc_InputMode == PNLD_BillingCounterCoverageRateSettingRange4 ) {
		pc_BillingCounterManager->ulToStrDecpnt( PNLD_BillingCounterCoverageRateCoefficientCInitVal,&uc_StrBuf[0],PNLD_BillingCounterConvertStrMax );	// 範囲4.
		Bak_SServiceCoverageRateCoefficientSettingRange4.changeTextString( ( const uchar* )uc_StrBuf );
		m_ul_range4 = 0;
	}
	else if( m_uc_InputMode == PNLD_BillingCounterCoverageRateSettingRange3 ) {
		pc_BillingCounterManager->ulToStrDecpnt( PNLD_BillingCounterCoverageRateCoefficientCInitVal,&uc_StrBuf[0],PNLD_BillingCounterConvertStrMax );	// 範囲3.
		Bak_SServiceCoverageRateCoefficientSettingRange3.changeTextString( ( const uchar* )uc_StrBuf );
		m_ul_range3 = 0;
	}
	else if( m_uc_InputMode == PNLD_BillingCounterCoverageRateSettingRange2 ) {
		pc_BillingCounterManager->ulToStrDecpnt( PNLD_BillingCounterCoverageRateCoefficientCInitVal,&uc_StrBuf[0],PNLD_BillingCounterConvertStrMax );	// 範囲2.
		Bak_SServiceCoverageRateCoefficientSettingRange2.changeTextString( ( const uchar* )uc_StrBuf );
		m_ul_range2 = 0;
	}
	else {
		pc_BillingCounterManager->ulToStrDecpnt( PNLD_BillingCounterCoverageRateCoefficientCInitVal,&uc_StrBuf[0],PNLD_BillingCounterConvertStrMax );	// 範囲1.
		Bak_SServiceCoverageRateCoefficientSettingRange1.changeTextString( ( const uchar* )uc_StrBuf );
		m_ul_range1 = 0;
	}
	m_s_nowFigure = 0;				// 入力桁数をクリア.
	m_bl_UpdateFlg = True;			// 更新中フラグをTrue.
	setupGamen( 0 );
}

/*================================================================================================
// 概要		:サービス・課金設定・印字率係数入力: ボタン(押された).
// 戻り値	:なし
// 備考		:
================================================================================================*/
void PServiceBillingCounterCoverageRateCoefficientSetting::procButtonOn( uchar option )
{
	if( m_uc_InputMode != option ) {
		if( False == inputRangeUpdate( m_uc_InputMode ) ) {		// 入力値更新.
			setBuzzerType( PCGE_BuzzerType_InputNg );
			return;
		}
	}
	switch( option ) {
		case BTNID_ServiceBillingCounterCRCS_Range1:
			m_uc_InputMode = PNLD_BillingCounterCoverageRateCoefficienRange1;
			break;
		case BTNID_ServiceBillingCounterCRCS_Range2:
			m_uc_InputMode = PNLD_BillingCounterCoverageRateCoefficienRange2;
			break;
		case BTNID_ServiceBillingCounterCRCS_Range3:
			m_uc_InputMode = PNLD_BillingCounterCoverageRateCoefficienRange3;
			break;
		case BTNID_ServiceBillingCounterCRCS_Range4:
			m_uc_InputMode = PNLD_BillingCounterCoverageRateCoefficienRange4;
			break;
		default: LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );	break;
	}
	setupGamen( 0 );
}
