//================================================================================================.
// 概要		:PServiceBillingSheetsCounterClear: サービス・課金設定・BillingCounter枚数クリアカウンタ・画面開始処理.
// 戻り値	:なし.
// 備考		:.
//================================================================================================.
void PServiceBillingSheetsCounterClear::startGamen()
{
	// Setキーの選択状態の初期化.
	m_uc_selectSetKeyState = BTNID_ServiceBillingSheetsCounterClearUnSet;
	Rbt_ServiceBillingSheetsCounterClearSetting.select( m_uc_selectSetKeyState );
	PServiceActionVendorSetCom::startGamen();
}
//================================================================================================.
// 概要		:PServiceBillingSheetsCounterClear : サービス・課金設定・BillingCounter枚数クリアカウンタ・ボタン押された.
// 戻り値	:なし.
// 備考		:.
//================================================================================================.
void PServiceBillingSheetsCounterClear::procButtonOn( uchar option )
{
	switch( option ) {
		case BTNID_ServiceBillingSheetsCounterClearSet:	// Setキー.
			m_uc_selectSetKeyState = option;
			Rbt_ServiceBillingSheetsCounterClearSetting.select( m_uc_selectSetKeyState );
			break;
		case BTNID_ServiceBillingSheetsCounterClearUnSet:	// UnSetキー.
			m_uc_selectSetKeyState = option;
			Rbt_ServiceBillingSheetsCounterClearSetting.select( m_uc_selectSetKeyState );
			break;
		default: LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );	break;
	}
	setupGamen();

}
//================================================================================================.
// 概要		:PServiceBillingSheetsCounterClear : サービス・課金設定・BillingCounter枚数クリアカウンタ・OKボタン.
// 戻り値	:なし.
// 備考		:.
//================================================================================================.
void PServiceBillingSheetsCounterClear::procOk( uchar option )
{
	if( BTNID_ServiceBillingSheetsCounterClearSet == m_uc_selectSetKeyState ) {
		APIC_TonerCoverageCnt::newInstance()->clearAll();    //  カウンタクリア.
	}

	nextGamen = &gp_ServiceActionVendorSetMenu;		//サービス・課金設定・メニュー
}

