//================================================================================================.
// 概要		:PServiceBillingCounterDetail/DetailTotal : static変数の初期値設定.
//================================================================================================.
#define PNLD_ServiceBillingCounterMaxPage 2	// ページ移動最大値.
//================================================================================================.
// 概要		:PServiceBillingCounterDetail : サービス・課金設定・BillingCounter詳細・画面開始処理.
// 戻り値	:なし.
// 備考		:.
//================================================================================================.
void PServiceBillingCounterDetail::startGamen()
{
	// ページ初期化(1ページ).
	m_uc_currentPage = 1;
	// タブ選択状態を取得.
	PLBC_BillingCounterManager* pc_BillingCounterManager = PLBC_BillingCounterManager::getInstance();	// PLBC_BillingCounterManagerインスタンス取得.
	if( NULL == pc_BillingCounterManager ) {
// Comment 2015/11/02 【ZeusS_ZX0】【HCL_Vasu】【制御構成変更_No.76-1】Adding Error Code macro.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//		if (NULL !=pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x1900650101353201 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}
	m_e_selectTabStatus = pc_BillingCounterManager->getDetailTabStatus();
#ifdef DEF_MonoCus
	if( BTNID_ServiceBillingCounterMode_Color == m_e_selectTabStatus ) {
		m_e_selectTabStatus = BTNID_ServiceBillingCounterMode_Black;
	}
#endif	// #ifdef DEF_MonoCus.
	Rbt_ServiceBillingCounterMode.select( m_e_selectTabStatus );
	// ページ最大数設定(最大2ページ).
	Inp_ServiceBillingCounterMoveMaxPage = PNLD_ServiceBillingCounterMaxPage;

	PServiceActionVendorSetCom::startGamen();
}
//================================================================================================.
// 概要		:PServiceBillingCounterDetail : サービス・課金設定・BillingCounter詳細・画面移動.
// 戻り値	:なし.
// 備考		:.
//================================================================================================.
void PServiceBillingCounterDetail::procGoToPage( uchar option )
{
	Bool isNeedToUpdate = True;	// 更新必要フラグ.

	// タブ選択状態を保存.
	PLBC_BillingCounterManager* pc_BillingCounterManager = PLBC_BillingCounterManager::getInstance();	// PLBC_BillingCounterManagerインスタンス取得.
	if( NULL == pc_BillingCounterManager ) {
// Comment 2015/11/02 【ZeusS_ZX0】【HCL_Vasu】【制御構成変更_No.76-1】Adding Error Code macro.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//		if (NULL !=pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x1900020101353301 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}
#ifdef DEF_MonoCus
	if( BTNID_ServiceBillingCounterMode_Color == option ) {
		setBuzzerType( PCGE_BuzzerType_Off, True );
		return;
	}
#endif	// #ifdef DEF_MonoCus.
	m_e_selectTabStatus = option;
	pc_BillingCounterManager->setDetailTabStatus( m_e_selectTabStatus );

	switch( option ) {
		case BTNID_ServiceBillingCounterMode_Total:	// Totalキー.
			// Total詳細画面へ(Non break).
			nextGamen = &gp_ServiceBillingCounterDetailTotal;
			isNeedToUpdate = False;
			// タブキー選択切り替え(この時ページ数は1ページに戻す).
			Rbt_ServiceBillingCounterMode.select( m_e_selectTabStatus );
			m_uc_currentPage = 1;
			break;
		case BTNID_ServiceBillingCounterMode_Color:	// Colorキー.
		case BTNID_ServiceBillingCounterMode_Black:	// Blackキー.
			// タブキー選択切り替え(この時ページ数は1ページに戻す).
			Rbt_ServiceBillingCounterMode.select( m_e_selectTabStatus );
			m_uc_currentPage = 1;
			break;
		default: LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );	break;
	}


	if( isNeedToUpdate ) {
		setupGamen();
	}
}

