{
	switch( option ) {
		case BTNID_ServiceBillingCounterGamenMove_Up:	// ↑キー.
		case BTNID_ServiceBillingCounterGamenMove_Down:	// ↓キー.
			m_uc_currentPage = ( 1 == m_uc_currentPage ? 2 : 1 );
			break;
		default: LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );	break;
	}
	setupGamen();

}
