// 概要		:PServiceBillingCounterDetailTotal : サービス・課金設定・BillingCounter詳細・画面移動.
// 戻り値	:なし.
// 備考		:.
//================================================================================================.
void PServiceBillingCounterDetailTotal::procGoToPage( uchar option )
{
	// タブ選択状態を保存.
	PLBC_BillingCounterManager* pc_BillingCounterManager = PLBC_BillingCounterManager::getInstance();	// PLBC_BillingCounterManagerインスタンス取得.
	if( NULL == pc_BillingCounterManager ) {
// Comment 2015/11/02 【ZeusS_ZX0】【HCL_Vasu】【制御構成変更_No.76-1】Adding Error Code macro.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//		if (NULL !=pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x1900020101353601 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}
#ifdef DEF_MonoCus
	if( BTNID_ServiceBillingCounterMode_Color == option ) {
		setBuzzerType( PCGE_BuzzerType_Off, True );
		return;
	}
#endif	// #ifdef DEF_MonoCus.
	m_e_selectTabStatus = option;
	pc_BillingCounterManager->setDetailTabStatus( m_e_selectTabStatus );

	switch( option ) {
		case BTNID_ServiceBillingCounterMode_Color:	// Colorキー.
		case BTNID_ServiceBillingCounterMode_Black:	// Blackキー.
			// Color/Black詳細画面へ(Non break).
			nextGamen = &gp_ServiceBillingCounterDetail;
		case BTNID_ServiceBillingCounterMode_Total:	// Totalキー.
			// タブキー選択切り替え(この時ページ数は1ページに戻す).
			Rbt_ServiceBillingCounterMode.select( m_e_selectTabStatus );
			break;
		default: LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );	break;
	}
}
