// 概要		:E0B9700000 ネットワーク設定コピー画面 : 開始チェック結果応答.
// 戻り値	:なし.
// 備考		:
//================================================================================================
void PCGC_ServiceNetworkSettingDeliver::ans_startGetRequestCode( TYPE_SetUpEnhancementError e_SetUpEnhancementError )
{
	TYPE_SetUpEnhancementEndStatus e_SetUpEnhancementEndStatus;
	// 通知結果によりステータスを切り替え.
	if( TYPE_SetUpEnhancementError_Success == e_SetUpEnhancementError )
	{
		e_SetUpEnhancementEndStatus = TYPE_SetUpEnhancementEndStatus_OK;
	}
	else
	{
		e_SetUpEnhancementEndStatus = TYPE_SetUpEnhancementEndStatus_Error;
	}
	// 配信結果のステータス更新.
	gp_ServiceNetworkSettingDeliver.setNetworkSettingDeliverResultStatus( e_SetUpEnhancementEndStatus, e_SetUpEnhancementError, 0 );

	// コールバック通知.
	CallBackIndi( TYPE_PNL_CallBack_NetworkSettingDeliverStartCheckComplete );
}

//================================================================================================
// 概要		:E0B9700000 ネットワーク設定コピー画面 : 表示部品のセットアップ.
// 戻り値	:なし.
// 備考		:
//================================================================================================
void PCGC_ServiceNetworkSettingDeliver::setupGamen( short option )
{
	PServiceCom::setupGamen( option );

	switch( m_e_NetworkStatus ) {
		case PNLE_ServiceNetworkDeliverStatusInit:				// 初期状態.
			Key_NetworkSetDeliverCheck.showEnable( True );		// 「接続確認」キー表示.
			Key_NetworkSetDeliverSend.showEnable( False );		// 「コピー実行」キー非表示.
			Key_NetworkSettingDeliverStart.showEnable( True );	// 「スタート」キー表示.
			Key_NetworkSettingDeliverStop.showEnable( False );	// 「中止」キー非表示.

			Grp_NetworkSettingDeliverCondition.showEnable( False );	// 進捗表示 非表示.

			Txt_ServiceNetworkSettingDeliverMessage.showEnable( False );	// 動的メッセージ 非表示.

			Grp_NetworkSettingDeliverError.showEnable( False );		// エラー表示 非表示.
			break;

		case PNLE_ServiceNetworkDeliverStatusStartCheck:		// 開始チェック中.
			Key_NetworkSetDeliverCheck.showEnable( True );		// 「接続確認」キー表示.
			Key_NetworkSetDeliverSend.showEnable( False );		// 「コピー実行」キー非表示.
			Key_NetworkSettingDeliverStart.showEnable( False );	// 「スタート」キー非表示.
			Key_NetworkSettingDeliverStop.showEnable( True );	// 「中止」キー表示.

			Grp_NetworkSettingDeliverCondition.showEnable( False );	// 進捗表示 非表示.

			Txt_ServiceNetworkSettingDeliverMessage.showEnable( False );	// 動的メッセージ 非表示.

			Grp_NetworkSettingDeliverError.showEnable( False );		// エラー表示 非表示.
			break;

		case PNLE_ServiceNetworkDeliverStatusChecking:			// 配信先チェック中.
		case PNLE_ServiceNetworkDeliverStatusCheckAborting:		// 配信先チェック中断中.
			Key_NetworkSetDeliverCheck.showEnable( True );		// 「接続確認」キー表示.
			Key_NetworkSetDeliverSend.showEnable( False );		// 「コピー実行」キー非表示.
			Key_NetworkSettingDeliverStart.showEnable( False );	// 「スタート」キー非表示.
			Key_NetworkSettingDeliverStop.showEnable( True );	// 「中止」キー表示.

			// 配信先チェック状況更新.
			Num_ServiceNetworkSettingDeliverOK.set( m_st_NetworkCondition.us_countOK, True );
			Num_ServiceNetworkSettingDeliverComplete.set( static_cast<float>( m_st_NetworkCondition.us_countOK + m_st_NetworkCondition.us_countNG ), True );
			Num_ServiceNetworkSettingDeliverTotal.set( m_st_NetworkCondition.us_countTotal, True );

			Grp_NetworkSettingDeliverCondition.showEnable( True );		// 進捗表示 表示.

			Txt_ServiceNetworkSettingDeliverMessage.showEnable( False );	// 動的メッセージ 非表示.

			Grp_NetworkSettingDeliverError.showEnable( False );			// エラー表示 非表示.
			break;

		case PNLE_ServiceNetworkDeliverStatusCheckAbortEnd:		// 配信先チェック中断完了.
		case PNLE_ServiceNetworkDeliverStatusSendAbortEnd:		// 配信中断完了.
			Key_NetworkSetDeliverCheck.showEnable( True );		// 「接続確認」キー表示.
			Key_NetworkSetDeliverSend.showEnable( False );		// 「コピー実行」キー非表示.
			Key_NetworkSettingDeliverStart.showEnable( True );	// 「スタート」キー表示.
			Key_NetworkSettingDeliverStop.showEnable( False );	// 「中止」キー非表示.

			// 配信先チェック状況更新.
			Num_ServiceNetworkSettingDeliverOK.set( m_st_NetworkCondition.us_countOK, True );
			Num_ServiceNetworkSettingDeliverComplete.set( static_cast<float>( m_st_NetworkCondition.us_countOK + m_st_NetworkCondition.us_countNG ), True );
			Num_ServiceNetworkSettingDeliverTotal.set( m_st_NetworkCondition.us_countTotal, True );

			Grp_NetworkSettingDeliverCondition.showEnable( True );		// 進捗表示 表示.

			// メッセージの表示.
			Txt_ServiceNetworkSettingDeliverMessage.changeText( s_MSGServiceCopyNWSettingResultLogFileCheck );		// 「コピー結果ファイルを確認してください」表示.
			Txt_ServiceNetworkSettingDeliverMessage.showEnable( True );		// 動的メッセージ 表示.

			Grp_NetworkSettingDeliverError.showEnable( False );			// エラー表示 非表示.
			break;

		case PNLE_ServiceNetworkDeliverStatusCheckComplete:		// 配信先チェック完了.
			Key_NetworkSetDeliverCheck.showEnable( True );		// 「接続確認」キー表示.
			Key_NetworkSetDeliverSend.showEnable( True );		// 「コピー実行」キー表示.
			Key_NetworkSettingDeliverStart.showEnable( True );	// 「スタート」キー表示.
			Key_NetworkSettingDeliverStop.showEnable( False );	// 「中止」キー非表示.

			// 配信先チェック状況更新.
			Num_ServiceNetworkSettingDeliverOK.set( m_st_NetworkCondition.us_countOK, True );
			Num_ServiceNetworkSettingDeliverComplete.set( static_cast<float>( m_st_NetworkCondition.us_countOK + m_st_NetworkCondition.us_countNG ), True );
			Num_ServiceNetworkSettingDeliverTotal.set( m_st_NetworkCondition.us_countTotal, True );

			Grp_NetworkSettingDeliverCondition.showEnable( True );		// 進捗表示 表示.

			// 全体台数 > OK台数 の場合、「コピー結果ファイルを確認してください」の表示.
			if( m_st_NetworkCondition.us_countTotal > m_st_NetworkCondition.us_countOK )
			{
				Txt_ServiceNetworkSettingDeliverMessage.changeText( s_MSGServiceCopyNWSettingResultLogFileCheck );		// 「コピー結果ファイルを確認してください」表示.
				Txt_ServiceNetworkSettingDeliverMessage.showEnable( True );		// 動的メッセージ 表示.
			}
			else
			{
				Txt_ServiceNetworkSettingDeliverMessage.showEnable( False );		// 動的メッセージ 非表示.
			}

			Grp_NetworkSettingDeliverError.showEnable( False );			// エラー表示 非表示.
			break;
		case PNLE_ServiceNetworkDeliverStatusSending:			// 配信中.
			Key_NetworkSetDeliverCheck.showEnable( True );		// 「接続確認」キー表示.
			Key_NetworkSetDeliverSend.showEnable( True );		// 「コピー実行」キー表示.
			Key_NetworkSettingDeliverStart.showEnable( False );	// 「スタート」キー非表示.
			Key_NetworkSettingDeliverStop.showEnable( True );	// 「中止」キー表示.

			// 配信状況更新.
			Num_ServiceNetworkSettingDeliverOK.set( m_st_NetworkCondition.us_countOK, True );
			Num_ServiceNetworkSettingDeliverComplete.set( static_cast<float>( m_st_NetworkCondition.us_countOK + m_st_NetworkCondition.us_countNG ), True );
			Num_ServiceNetworkSettingDeliverTotal.set( m_st_NetworkCondition.us_countTotal, True );

			Grp_NetworkSettingDeliverCondition.showEnable( True );		// 進捗表示 表示.
			Txt_ServiceNetworkSettingDeliverMessage.showEnable( False );	// 動的メッセージ 非表示.
			Grp_NetworkSettingDeliverError.showEnable( False );			// エラー表示 非表示.
			break;
		case PNLE_ServiceNetworkDeliverStatusSendAborting:		// 配信中断中.
			Key_NetworkSetDeliverCheck.showEnable( True );		// 「接続確認」キー表示.
			Key_NetworkSetDeliverSend.showEnable( True );		// 「コピー実行」キー表示.
			Key_NetworkSettingDeliverStart.showEnable( False );	// 「スタート」キー非表示.
			Key_NetworkSettingDeliverStop.showEnable( True );	// 「中止」キー表示.

			// 配信状況更新.
			Num_ServiceNetworkSettingDeliverOK.set( m_st_NetworkCondition.us_countOK, True );
			Num_ServiceNetworkSettingDeliverComplete.set( static_cast<float>( m_st_NetworkCondition.us_countOK + m_st_NetworkCondition.us_countNG ), True );
			Num_ServiceNetworkSettingDeliverTotal.set( m_st_NetworkCondition.us_countTotal, True );
			Grp_NetworkSettingDeliverCondition.showEnable( True );		// 進捗表示 表示.

			Txt_ServiceNetworkSettingDeliverMessage.changeText( s_MSGServiceItStops2 );		// 「コピー結果ファイルを確認してください」表示.
			Txt_ServiceNetworkSettingDeliverMessage.showEnable( True );	// 動的メッセージ 表示.
			Grp_NetworkSettingDeliverError.showEnable( False );		// エラー表示 非表示.
			break;
		case PNLE_ServiceNetworkDeliverStatusSendComplete:		// 配信完了.
			Key_NetworkSetDeliverCheck.showEnable( True );		// 「接続確認」キー表示.
			Key_NetworkSetDeliverSend.showEnable( False );		// 「コピー実行」キー非表示.
			Key_NetworkSettingDeliverStart.showEnable( True );	// 「スタート」キー表示.
			Key_NetworkSettingDeliverStop.showEnable( False );	// 「中止」キー非表示.

			// 配信状況更新.
			Num_ServiceNetworkSettingDeliverOK.set( m_st_NetworkCondition.us_countOK, True );
			Num_ServiceNetworkSettingDeliverComplete.set( static_cast<float>( m_st_NetworkCondition.us_countOK + m_st_NetworkCondition.us_countNG ), True );
			Num_ServiceNetworkSettingDeliverTotal.set( m_st_NetworkCondition.us_countTotal, True );

			Grp_NetworkSettingDeliverCondition.showEnable( True );		// 進捗表示 表示.

			// 全体台数 > OK台数 の場合、「コピー結果ファイルを確認してください」の表示.
			if( m_st_NetworkCondition.us_countTotal > m_st_NetworkCondition.us_countOK )
			{
				Txt_ServiceNetworkSettingDeliverMessage.changeText( s_MSGServiceCopyNWSettingResultLogFileCheck );		// 「コピー結果ファイルを確認してください」表示.
				Txt_ServiceNetworkSettingDeliverMessage.showEnable( True );		// 動的メッセージ 表示.
			}
			else
			{
				Txt_ServiceNetworkSettingDeliverMessage.showEnable( False );		// 動的メッセージ 非表示.
			}

			Grp_NetworkSettingDeliverError.showEnable( False );		// エラー表示 非表示.
			break;
		case PNLE_ServiceNetworkDeliverStatusError:				// エラー表示.
			Key_NetworkSetDeliverCheck.showEnable( True );		// 「接続確認」キー表示.
			Key_NetworkSetDeliverSend.showEnable( False );		// 「コピー実行」キー非表示.
			Key_NetworkSettingDeliverStart.showEnable( True );	// 「スタート」キー表示.
			Key_NetworkSettingDeliverStop.showEnable( False );	// 「中止」キー非表示.

			Grp_NetworkSettingDeliverCondition.showEnable( False );		// 進捗表示 非表示.

			Txt_ServiceNetworkSettingDeliverMessage.showEnable( False );	// 動的メッセージ 非表示.

			Grp_NetworkSettingDeliverError.showEnable( True );		// エラー表示 表示.
			break;

		default:
			break;
	}

	// 「接続確認」キー／「コピー実行」キーの選択状態切り替え.
	if( True == m_bl_isSelectCopyExec )
	{
		Key_NetworkSetDeliverCheck.select( False );
		Key_NetworkSetDeliverSend.select( True );
	}
	else
	{
		Key_NetworkSetDeliverCheck.select( True );
		Key_NetworkSetDeliverSend.select( False );
	}

	// 固定要素のUI初期化.
	Key_NetworkSettingCopy.select( True );				// 「設定コピー」キーを選択状態へ.
	Key_NetworkSettingConnectTimeout.select( False );	// 「接続ﾀｲﾑｱｳﾄ」キーを非選択状態へ.
}

//================================================================================================
// 概要		:E0B9700000 ネットワーク設定コピー画面 : キー押下処理.
// 戻り値	:なし.
// 備考		:
//================================================================================================
void PCGC_ServiceNetworkSettingDeliver::procButtonOn( uchar option )
{
	APIC_IISWClient* pc_IISWClient;

	switch( option ) {
		case BTNID_NetworkCheckConnect:		// 接続確認キー押下.
			// 配信先チェック／配信中 以外であれば
			if( False == IsNetworkSettingDeliverProcessing() )
			{
				m_bl_isSelectCopyExec = False;	// 「コピー実行」キー 非選択.
			}
			else
			{
				setBuzzerType( PCGE_BuzzerType_InputNg );	// 拒否音鳴動.
			}
			break;
		case BTNID_NetworkDeliverExec:		// コピー実行キー押下.
			// 配信先チェック／配信中 以外であれば
			if( False == IsNetworkSettingDeliverProcessing() )
			{
				m_bl_isSelectCopyExec = True;				// 「コピー実行」キー 選択.
			}
			else
			{
				setBuzzerType( PCGE_BuzzerType_InputNg );	// 拒否音鳴動.
			}
			break;
		case BTNID_NetworkDeliverStart:		// スタートキー押下.
			// 配信先チェック／配信中 以外であれば
			if( False == IsNetworkSettingDeliverProcessing() )
			{
				pc_IISWClient = APIC_IISWClient::newInstance();	// インスタンスを取得.
				if( NULL == pc_IISWClient ) {
// Comment 2015/11/02 【ZeusS_ZX0】【HCL_Vasu】【制御構成変更_No.76-1】Adding Error Code macro.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//					LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//					if (NULL !=pc_BFW_System){
//						pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19000A0100F53C01 );
//					}
					LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
					return;
				}

				// 「接続確認」選択時.
				if( False == m_bl_isSelectCopyExec )
				{
					// 進捗状況／エラーステータスを初期化.
					m_st_NetworkCondition.us_countOK = 0;
					m_st_NetworkCondition.us_countNG = 0;
					m_st_NetworkCondition.us_countTotal = 0;
					m_e_SetUpEnhancementEndStatus = TYPE_SetUpEnhancementEndStatus_OK;
					m_e_SetUpEnhancementError = TYPE_SetUpEnhancementError_Success;
					m_sl_NetworkError = 0;
					// ログ出力.
					PanelLog( PNLD_LogKind_Service, "APIC_IISWClient::req_StartCheck() ans_startGetRequestCode[%p]", PCGC_ServiceNetworkSettingDeliver::ans_startGetRequestCode, 0, 0, 0, 0, 0 );
					// 開始チェック要求発行.
					pc_IISWClient->req_StartCheck( PCGC_ServiceNetworkSettingDeliver::ans_startGetRequestCode );
					// ステータスを開始チェック中に変更.
					m_e_NetworkStatus = PNLE_ServiceNetworkDeliverStatusStartCheck;
				}
				// 「コピー実行」選択時.
				else
				{
					// NG台数、全体台数は配信先チェック時の値を引き継ぎ、OK台数は0からカウントされるためOK台数のみクリアする.
					m_st_NetworkCondition.us_countOK = 0;
					// ログ出力.
					PanelLog( PNLD_LogKind_Service, "APIC_IISWClient::req_DistributeData()", 0, 0, 0, 0, 0, 0 );
					// 配信開始要求発行.
					pc_IISWClient->req_DistributeData();
					// ステータスを配信中に変更.
					m_e_NetworkStatus = PNLE_ServiceNetworkDeliverStatusSending;
				}
			}
			else
			{
				setBuzzerType( PCGE_BuzzerType_InputNg );	// 拒否音鳴動.
			}
			break;
		case BTNID_NetworkDeliverStop:	// ストップキー押下.
			// 配信ステータスに応じて呼び出すAPIを切り替え.
			switch( m_e_NetworkStatus ) {
				case PNLE_ServiceNetworkDeliverStatusChecking:		// 配信先チェック中.
					pc_IISWClient = APIC_IISWClient::newInstance();	// インスタンスを取得.
					if( NULL == pc_IISWClient ) {
// Comment 2015/11/02 【ZeusS_ZX0】【HCL_Vasu】【制御構成変更_No.76-1】Adding Error Code macro.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//						LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//						if (NULL !=pc_BFW_System){
//							pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19000A0100F53D01 );
//						}
						LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
						return;
					}
					// ログ出力.
					PanelLog( PNLD_LogKind_Service, "APIC_IISWClient::req_DistributeCheckCancel()", 0, 0, 0, 0, 0, 0 );
					// 配信先チェック中止要求.
					pc_IISWClient->req_DistributeCheckCancel();
					// 配信ステータスを配信先チェック中断中に切り替え.
					m_e_NetworkStatus = PNLE_ServiceNetworkDeliverStatusCheckAborting;
					break;

				case PNLE_ServiceNetworkDeliverStatusSending:		// 配信中.
					pc_IISWClient = APIC_IISWClient::newInstance();	// インスタンスを取得.
					if( NULL == pc_IISWClient ) {
// Comment 2015/11/02 【ZeusS_ZX0】【HCL_Vasu】【制御構成変更_No.76-1】Adding Error Code macro.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//						LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//						if (NULL !=pc_BFW_System){
//							pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19000A0100F53E01 );
//						}
						LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
						return;
					}
					// ログ出力.
					PanelLog( PNLD_LogKind_Service, "APIC_IISWClient::req_DistributeDataCancel()", 0, 0, 0, 0, 0, 0 );
					// 配信中止要求.
					pc_IISWClient->req_DistributeDataCancel();
					// 配信ステータスを配信中断中に切り替え.
					m_e_NetworkStatus = PNLE_ServiceNetworkDeliverStatusSendAborting;
					break;

				default:
					break;
			}
			break;
		default:
			break;
	}
	setupGamen();
}

