//================================================================================================
void PCGC_ServiceNetworkSettingDeliver::procGoToPage( uchar option )
{
	switch( option ) {
		case PNLD_BTNID_NetworkSettingCopy:
			// 同じ画面には遷移しない
			setBuzzerType( PCGE_BuzzerType_InputNg );	// 拒否音鳴動.
			break;
		case PNLD_BTNID_NetworkTimeoutSet:
			// 配信先チェック／配信中 以外であれば
			if( False == IsNetworkSettingDeliverProcessing() )
			{
				nextGamen = &gp_ServiceDeliverCheckTimeSetting;	// E0B9710000 ネットワーク設定コピー／接続タイムアウト
			}
			else
			{
				setBuzzerType( PCGE_BuzzerType_InputNg );	// 拒否音鳴動.
			}
			break;
		default: LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );	break;
	}
}

