//================================================================================================
// 概要		:E0B9700000 ネットワーク設定コピー画面 : オブザーバー通知.
// 戻り値	:なし.
// 備考		:
//================================================================================================
void PCGC_ServiceNetworkSettingDeliver::procObserver( TYPE_PNL_Observer option )
{

	switch( option ) {
		case TYPE_PNL_Observer_NetworkSettingDistributeCheckProgress:	// 配信先チェック状況通知.
			break;

		case TYPE_PNL_Observer_NetworkSettingDistributeCheckComplete:	// 配信先チェック完了通知.
			// エラー通知なしの場合.
			if( TYPE_SetUpEnhancementEndStatus_OK == m_e_SetUpEnhancementEndStatus )
			{
				if( TYPE_SetUpEnhancementError_E00014 == m_e_SetUpEnhancementError )
				{
					// 配信中止の場合、中断完了とする.
					m_e_NetworkStatus = PNLE_ServiceNetworkDeliverStatusCheckAbortEnd;
				}
				else
				{
					// 一部NG or 全部成功の場合、配信先チェック完了とする.
					m_e_NetworkStatus = PNLE_ServiceNetworkDeliverStatusCheckComplete;
				}
			}
			else
			{
				// 全台NGの場合エラーコード表示はしないが以降の配信は不可能なため、中断時と同等の扱いとする.
				if( TYPE_SetUpEnhancementError_Success == m_e_SetUpEnhancementError && 0 == m_sl_NetworkError )
				{
					// 中断状態とする.
					m_e_NetworkStatus = PNLE_ServiceNetworkDeliverStatusCheckAbortEnd;
					break;
				}
				// エラーコード通知の場合、エラー状態とする.
				if( TYPE_SetUpEnhancementError_Success != m_e_SetUpEnhancementError )
				{
					// 通常のエラーが発生の場合、エラーコード「E*****」を表示.
					snprintf( m_sc_ErrorCode, sizeof( m_sc_ErrorCode ), "E%05d", ( int )m_e_SetUpEnhancementError );
				}
				else
				{
					// ネットワークエラーが発生している場合、エラーコード「N*****」を表示.
					snprintf( m_sc_ErrorCode, sizeof( m_sc_ErrorCode ), "N%05d", m_sl_NetworkError );
				}
				// エラーコードの表示.
				Txt_ServiceNetworkSettingDeliverErrCode.changeTextString( ( const uchar* )m_sc_ErrorCode );
				// ステータスをエラー発生に変更.
				m_e_NetworkStatus = PNLE_ServiceNetworkDeliverStatusError;
			}
			break;

		case TYPE_PNL_Observer_NetworkSettingDistributeDataProgress:	// 配信状況通知.
			break;

		case TYPE_PNL_Observer_NetworkSettingDistributeDataComplete:	// 配信完了通知.
			// 「接続確認」選択状態へ.
			m_bl_isSelectCopyExec = False;

			// エラー通知なしの場合.
			if( TYPE_SetUpEnhancementEndStatus_OK == m_e_SetUpEnhancementEndStatus )
			{
				if( TYPE_SetUpEnhancementError_E00014 == m_e_SetUpEnhancementError )
				{
					// 配信中止の場合、中断完了とする.
					m_e_NetworkStatus = PNLE_ServiceNetworkDeliverStatusSendAbortEnd;
				}
				else
				{
					// 一部NG or 全部成功の場合、配信先チェック完了とする.
					m_e_NetworkStatus = PNLE_ServiceNetworkDeliverStatusSendComplete;
				}
			}
			else
			{
				// 配信終了ではネットワークエラーは通知されない.
				// 通常のエラーが発生の場合、エラーコード「E*****」を表示.
				snprintf( m_sc_ErrorCode, sizeof( m_sc_ErrorCode ), "E%05d", ( int )m_e_SetUpEnhancementError );
				// エラーコードの表示.
				Txt_ServiceNetworkSettingDeliverErrCode.changeTextString( ( const uchar* )m_sc_ErrorCode );
				// エラー通知の場合、エラー状態とする.
				m_e_NetworkStatus = PNLE_ServiceNetworkDeliverStatusError;
			}
			break;

		default:									// その他.
			PServiceCom::procObserver( option );	// 親クラスのコールバック処理をコール.
			break;
	}
	setupGamen();	// 表示内容更新.
}

//================================================================================================
// 概要		:E0B9700000 ネットワーク設定コピー画面 : コールバック通知
// 戻り値	:なし.
// 備考		:
//================================================================================================
void PCGC_ServiceNetworkSettingDeliver::procCallBack( TYPE_PNL_CallBack option )
{
	switch( option ) {
		case TYPE_PNL_CallBack_NetworkSettingDeliverStartCheckComplete:		// 開始チェック結果通知.
			// 開始チェック成功なら、配信先チェックへ移行.
			if( TYPE_SetUpEnhancementError_Success == m_e_SetUpEnhancementError )
			{
				APIC_IISWClient* pc_IISWClient = APIC_IISWClient::newInstance();	// インスタンスを取得.
				if( NULL == pc_IISWClient ) {
// Comment 2015/11/02 【ZeusS_ZX0】【HCL_Vasu】【制御構成変更_No.76-1】Adding Error Code macro.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//					LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//					if (NULL !=pc_BFW_System){
//						pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x1900690100F53F01 );
//					}
					LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
					return;
				}
				// タイムアウト時間の取得.
				ushort us_NetworkTimeout = PCGC_ServiceNetworkSettingDeliverCom::getNetworkTimeoutValue();
				// ログ出力.
				PanelLog( PNLD_LogKind_Service, "APIC_IISWClient::req_DistributeCheck() us_NetworkTimeout[%d]", us_NetworkTimeout, 0, 0, 0, 0, 0 );
				// 開始チェック要求発行.
				pc_IISWClient->req_DistributeCheck( us_NetworkTimeout );
				// ステータスを配信先チェック中へ変更.
				m_e_NetworkStatus = PNLE_ServiceNetworkDeliverStatusChecking;
			}
			else
			{
				// 通常のエラーが発生の場合、エラーコード「E*****」を表示.
				snprintf( m_sc_ErrorCode, sizeof( m_sc_ErrorCode ), "E%05d", ( int )m_e_SetUpEnhancementError );
				// エラーコードの表示.
				Txt_ServiceNetworkSettingDeliverErrCode.changeTextString( ( const uchar* )m_sc_ErrorCode );
				// ステータスをエラー発生に変更.
				m_e_NetworkStatus = PNLE_ServiceNetworkDeliverStatusError;
			}
			break;

		default:									// その他.
			PServiceCom::procCallBack( option );	// 親クラスのコールバック処理をコール.
			break;
	}
	setupGamen();	// 表示内容更新.
}

//================================================================================================
// 概要		:E0B9700000 ネットワーク設定コピー画面 : 配信中／配信先チェック中の確認.
// 戻り値	:True(配信中または配信先チェック中)／False(配信中または配信先チェック中ではない)
// 備考		:
//================================================================================================
Bool PCGC_ServiceNetworkSettingDeliver::IsNetworkSettingDeliverProcessing()
{
	Bool bl_Ret = True;

	// 配信先チェック／配信中 以外であれば
	switch( m_e_NetworkStatus ) {
		case PNLE_ServiceNetworkDeliverStatusInit:
		case PNLE_ServiceNetworkDeliverStatusCheckComplete:
		case PNLE_ServiceNetworkDeliverStatusSendComplete:
		case PNLE_ServiceNetworkDeliverStatusCheckAbortEnd:
		case PNLE_ServiceNetworkDeliverStatusSendAbortEnd:
		case PNLE_ServiceNetworkDeliverStatusError:
			// 配信中ではない、というステータスを返す.
			bl_Ret = False;
			break;

		default:
			break;
	}

	return bl_Ret;
}

