// 戻り値	:なし.
// 備考		:
//================================================================================================
void PCGC_ServiceDeliverCheckTimeSetting::setupGamen( short option )
{
	PServiceCom::setupGamen( option );

	// 固定要素のUI初期化.
	Key_NetworkSettingCopy.select( False );				// 「設定コピー」キーを非選択状態へ.
	Key_NetworkSettingConnectTimeout.select( True );	// 「接続ﾀｲﾑｱｳﾄ」キーを選択状態へ.

	Btx_NetworkTimeout.set( us_NetworkTimeoutBkup, ( us_NetworkTimeoutBkup < 1 ) ? False : True );
}

//================================================================================================
// 概要		:E0B9710000 ネットワーク設定接続タイムアウト設定画面 : OKキー押下処理.
// 戻り値	:なし.
// 備考		:
//================================================================================================
void PCGC_ServiceDeliverCheckTimeSetting::procOk( uchar option )
{
	// 配信先チェックタイムアウト値確定[1～300].
	if( ( PNLD_ServiceNetworkDeliverTimeoutMin <= us_NetworkTimeoutBkup ) && ( PNLD_ServiceNetworkDeliverTimeoutMax >= us_NetworkTimeoutBkup ) ) {
		// 秒数設定.
		PCGC_ServiceNetworkSettingDeliverCom::setNetworkTimeoutValue( us_NetworkTimeoutBkup );
	}

	nextGamen = &gp_ServiceMFPUpdateMenu;				// 90B94100 本体装置更新設定／メニュー
}
//================================================================================================
// 概要		:E0B9710000 ネットワーク設定接続タイムアウト設定画面 : 10キー押下処理.
// 戻り値	:なし.
// 備考		:
//================================================================================================
void PCGC_ServiceDeliverCheckTimeSetting::proc10Key( uchar option )
{
	Bool bl_Error = False;

	// 入力チェック.
	us_NetworkTimeoutBkup = ( ushort )proc10KeyInput( us_NetworkTimeoutBkup, PNLD_ServiceNetworkDeliverTimeoutMax, option, bl_Direct, EP_InputMaxLimitPattern_Refuse, &bl_Error );

	// エラーの場合.
	if( True == bl_Error ) {
		setBuzzerType( PCGE_BuzzerType_InputNg );	// 拒否音鳴動.
	} else {
		// 一桁目が数値でない場合.
		if( True == bl_Direct && 1 > option ) {
			setBuzzerType( PCGE_BuzzerType_InputNg );	// 拒否音鳴動.
		} else {
			// 二桁目以降入力.
			bl_Direct = False;
		}
	}

	// 画面更新.
	setupGamen();
}

//================================================================================================
// 概要		:E0B9710000 ネットワーク設定接続タイムアウト設定画面 : クリアキー押下処理.
// 戻り値	:なし.
// 備考		:
//================================================================================================
void PCGC_ServiceDeliverCheckTimeSetting::procClear( uchar option )
{
	us_NetworkTimeoutBkup = 0;
	bl_Direct = True;

	setupGamen();	// 表示内容更新.
}

//================================================================================================
// 概要		:E0B9710000 ネットワーク設定接続タイムアウト設定画面 : 画面遷移キー押下処理
// 戻り値	:なし.
// 備考		:
//================================================================================================
void PCGC_ServiceDeliverCheckTimeSetting::procGoToPage( uchar option )
{
	switch( option ) {
		case PNLD_BTNID_NetworkSettingCopy:
			// 配信先チェックタイムアウト値確定[1～300].
			if( ( PNLD_ServiceNetworkDeliverTimeoutMin <= us_NetworkTimeoutBkup ) && ( PNLD_ServiceNetworkDeliverTimeoutMax >= us_NetworkTimeoutBkup ) ) {
				// 秒数設定.
				PCGC_ServiceNetworkSettingDeliverCom::setNetworkTimeoutValue( us_NetworkTimeoutBkup );
			}
			nextGamen = &gp_ServiceNetworkSettingDeliver;	// E0B9700000 ネットワーク設定コピー／設定コピー
			break;
		case PNLD_BTNID_NetworkTimeoutSet:
			// 同じ画面には遷移しない
			setBuzzerType( PCGE_BuzzerType_InputNg );	// 拒否音鳴動.
			break;
		default: LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );	break;
	}
}
