// PServiceChargingAcOutputAdjustment : H0B1030000  Charging AC Output Adjustment.
//================================================================================================.
/**
* @brief  : Screen startup processing.
* @note   : None.
* @param  : None.
* @return : None.
*/
void PServiceChargingAcOutputAdjustment::startGamen()
{
	PBasicMessageProc::startGamen();
	CheckAndExecInit();		//Intializing the Values.
}

/**
* @brief  : Initializing the values.
* @note   : None.
* @param  : None.
* @return : None.
*/
void PServiceChargingAcOutputAdjustment::init_value()
{
// Comment 2015/02/05 【HCLT-Deeparaj】 【ZeusSBK】 【機器構成変更_No.5】 Setting default vlaue Vpp-K for Monochrome model.
#ifdef DEF_MonoCus
	setPrinterIndi( TYPE_PrinterAdjustChargedAcVoltageOutputAdjK ); 	// Set Default Vpp-K.
#else	// DEF_MonoCus.	
	setPrinterIndi( TYPE_PrinterAdjustChargedAcVoltageOutputAdjC );		// Set Default Vpp-C.
#endif // DEF_MonoCus.	
	m_ss_ChargingAcOutputAdjustmentVppC = getPrinterIndiInSystem( TYPE_PrinterAdjustChargedAcVoltageOutputAdjC );		//Intial Value for Vpp-C.
	m_ss_ChargingAcOutputAdjustmentVppM = getPrinterIndiInSystem( TYPE_PrinterAdjustChargedAcVoltageOutputAdjM );		//Intial Value for Vpp-M.
	m_ss_ChargingAcOutputAdjustmentVppY = getPrinterIndiInSystem( TYPE_PrinterAdjustChargedAcVoltageOutputAdjY );		//Intial Value for Vpp-Y.
	m_ss_ChargingAcOutputAdjustmentVppK = getPrinterIndiInSystem( TYPE_PrinterAdjustChargedAcVoltageOutputAdjK );		//Intial Value for Vpp-K.
}

/**
* @brief  : Handling screen display.
* @note   : None.
* @param  : [in] ss_Option - Option.
* @return : None.
*/

void PServiceChargingAcOutputAdjustment::setupGamen( short ss_option )
{
	switch( getIndiSelected() ) {
		case TYPE_PrinterAdjustChargedAcVoltageOutputAdjC:
			m_ss_select = PNLD_ServiceChargingAcOutputAdjVppC;
			break;	// Vpp-C
		case TYPE_PrinterAdjustChargedAcVoltageOutputAdjM:
			m_ss_select = PNLD_ServiceChargingAcOutputAdjVppM;
			break;	// Vpp-M
		case TYPE_PrinterAdjustChargedAcVoltageOutputAdjY:
			m_ss_select = PNLD_ServiceChargingAcOutputAdjVppY;
			break;	// Vpp-Y
		case TYPE_PrinterAdjustChargedAcVoltageOutputAdjK:
			m_ss_select = PNLD_ServiceChargingAcOutputAdjVppK;
			break;	// Vpp-K
		default: break;
	}
// Comment 2015/02/05 【HCLT-Deeparaj】 【ZeusSBK】 【機器構成変更_No.5】Hide Vpp-C,Vpp-M and Vpp-y keys and corresponding text parts.
#ifdef DEF_MonoCus
	Key_ServiceChargingAcOutputAdjVppC.showEnable( False );			// Hide VppC Key.
	Key_ServiceChargingAcOutputAdjVppM.showEnable( False );			// Hide VppM Key.
	Key_ServiceChargingAcOutputAdjVppY.showEnable( False );			// Hide VppY Key.
	Btx_NumSChargingAcOutputAdjustmentC.showEnableAdd( False );		// Disable VppC number field.
	Btx_NumSChargingAcOutputAdjustmentM.showEnableAdd( False );		// Disable VppM number field.
	Btx_NumSChargingAcOutputAdjustmentY.showEnableAdd( False );		// Disable VppK number field.
#endif // DEF_MonoCus.	
	Rbt_ServiceChargingAcOutputAdjustment.select( m_ss_select );
// Comment 2015/02/05 【HCLT-Deeparaj】 【ZeusSBK】 【機器構成変更_No.5】 Disable Number field update for Monochrome Models.
#ifndef DEF_MonoCus
	Btx_NumSChargingAcOutputAdjustmentC = ( float )getPrinterIndi( TYPE_PrinterAdjustChargedAcVoltageOutputAdjC );	// Voltage adjustment for Vpp-C.
	Btx_NumSChargingAcOutputAdjustmentM = ( float )getPrinterIndi( TYPE_PrinterAdjustChargedAcVoltageOutputAdjM );	// Voltage adjustment for Vpp-M.
	Btx_NumSChargingAcOutputAdjustmentY = ( float )getPrinterIndi( TYPE_PrinterAdjustChargedAcVoltageOutputAdjY );	// Voltage adjustment for Vpp-Y.
#endif // DEF_MonoCus.
	Btx_NumSChargingAcOutputAdjustmentK = ( float )getPrinterIndi( TYPE_PrinterAdjustChargedAcVoltageOutputAdjK );	// Voltage adjustment for Vpp-K.
	PServiceChoiceAdjustCom10ToImageAdjustModeMenuCom::setupGamen( ss_option );	// Displaying the component.
}

/**
* @brief  : Handling button clicks.
* @note   : None.
* @param  : [in] uc_Option - Option.
* @return : None.
*/
void PServiceChargingAcOutputAdjustment::procButtonOn( uchar uc_option )
{
	switch( uc_option ) {
		case BTNID_ServiceChargingAcOutputAdjVppC:
			setPrinterIndi( TYPE_PrinterAdjustChargedAcVoltageOutputAdjC );
			m_ss_select = PNLD_ServiceChargingAcOutputAdjVppC;
			break;	// Vpp-C current adjustment value.

		case BTNID_ServiceChargingAcOutputAdjVppM:
			setPrinterIndi( TYPE_PrinterAdjustChargedAcVoltageOutputAdjM );
			m_ss_select = PNLD_ServiceChargingAcOutputAdjVppM;
			break;	// Vpp-M current adjustment value.
		case BTNID_ServiceChargingAcOutputAdjVppY:
			setPrinterIndi( TYPE_PrinterAdjustChargedAcVoltageOutputAdjY );
			m_ss_select = PNLD_ServiceChargingAcOutputAdjVppY;
			break;	// Vpp-Y current adjustment value.
		case BTNID_ServiceChargingAcOutputAdjVppK:
			setPrinterIndi( TYPE_PrinterAdjustChargedAcVoltageOutputAdjK );
			m_ss_select = PNLD_ServiceChargingAcOutputAdjVppK;
			break;	// Vpp-K current adjustment value.

		case BTNID_ServiceChargingAcOutputAdjRestore:	// Restore.
			switch( getIndiSelected() ) {
				case TYPE_PrinterAdjustChargedAcVoltageOutputAdjC:
					setPrinterIndi( TYPE_PrinterAdjustChargedAcVoltageOutputAdjC,		m_ss_ChargingAcOutputAdjustmentVppC );		// Vpp-C current adjustment value.
					break;
				case TYPE_PrinterAdjustChargedAcVoltageOutputAdjM:
					setPrinterIndi( TYPE_PrinterAdjustChargedAcVoltageOutputAdjM,		m_ss_ChargingAcOutputAdjustmentVppM );		// Vpp-M current adjustment value.
					break;
				case TYPE_PrinterAdjustChargedAcVoltageOutputAdjY:
					setPrinterIndi( TYPE_PrinterAdjustChargedAcVoltageOutputAdjY,		m_ss_ChargingAcOutputAdjustmentVppY );		// Vpp-Y current adjustment value.
					break;
				case TYPE_PrinterAdjustChargedAcVoltageOutputAdjK:
					setPrinterIndi( TYPE_PrinterAdjustChargedAcVoltageOutputAdjK,		m_ss_ChargingAcOutputAdjustmentVppK );		// Vpp-K current adjustment value.
					break;
				default: break;
			}
			break;
		case BTNID_ServiceChargingAcOutputAdjUp:	addIndi();	break;	// "+" Key.
		case BTNID_ServiceChargingAcOutputAdjDown:	subIndi();	break;	// "-" Key.
		default:break;
	}
	setupGamen();
}

/**
* @brief  : Handling Ok key.
* @note   : None.
* @param  : [in] uc_Option - Option.
* @return : None.
*/
void PServiceChargingAcOutputAdjustment::procOk( uchar uc_option )
{
	fixPrinterIndi( TYPE_PrinterAdjustChargedAcVoltageOutputAdjC );
	fixPrinterIndi( TYPE_PrinterAdjustChargedAcVoltageOutputAdjM );
	fixPrinterIndi( TYPE_PrinterAdjustChargedAcVoltageOutputAdjY );
	fixPrinterIndi( TYPE_PrinterAdjustChargedAcVoltageOutputAdjK );
	PServiceChoiceAdjustCom10ToImageAdjustModeMenuCom::procOk( uc_option );
}

