/**
 * @brief   Screen display update.
 * @note    None.
 * @param   ss_Option - Option.
 * @return  None.
 */
void PServiceFaxLineStandardSetting1::setupGamen( short ss_Option )
{
	// Base class function call.
	PServiceFaxLineStandardSettingCom::setupGamen( ss_Option );

	Rbt_ServiceFaxLineStandardSettings.select( 0 ); // Select line 1.
	// Select Busy tone detection ON/OFF key.
	Rbt_ServiceFaxLineRXSignalMode.select( ( m_bl_RXSignalDetect == False ) ? 0 : 1 );
	//Select Receive signal detection mode Time/Count key.
	Rbt_ServiceFaxLineBusyTone.select( ( m_bl_BusyToneDetect == False ) ? 0 : 1 );
	// Get and display Busy tone count and RX call rings count.
	Btx_ServiceFaxLineBusyToneCountValue = getFaxIndi( TYPE_FaxAdjustBusyToneCount );
	//Btx_ServiceFaxLineRXCallCountValue    = getFaxIndi( TYPE_FaxRxCallRingsCount );
// comment 2014/12/09 OPS1 大濵 [Zeus5BK][CQ506732].
    APIC_MachineSetting* pc_MachineSetting = APIC_MachineSetting::newInstance();
    if( NULL == pc_MachineSetting ) {
// Comment 2015/11/02 【ZeusS_ZX0】【HCL_Vasu】【制御構成変更_No.76-1】Adding Error Code macro.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//		if (NULL !=pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x1900650100C54001 );
//		}
        LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
        return;
    }
    TYPE_CountryCode e_CountryCode = pc_MachineSetting->getCountryCode();   // FAX仕向け.
	if( True == m_bl_RXSignalDetect ) {
		Txt_TitleServiceFaxLineRXCallCount.changeText( s_TTLServiceReceiveTimeSetting );
		Btx_ServiceFaxLineRXCallCountValue = getFaxIndi( TYPE_FaxRxCallRingsTime );
		Txt_FaxLineRXCallCountUnit.changeText( s_EXPSecond_04 );
// comment 2014/12/09 OPS1 大濵 [Zeus5BK][CQ506732].
//        Txt_FaxLineRXCallCountSExtent0P15.changeText(s_NOTITMService3To14);
// comment 2015/07/23 HCLT_Anusha [MiSBK][CQ513724] Changed the text of "Receive Time" as 3 - 8 for MY.
        switch (e_CountryCode) {
            case TYPE_CountryCode_AU:   // オーストラリア.
                Txt_FaxLineRXCallCountSExtent0P15.changeText( s_NOTITMService3To14 );   // 3 - 14.
                break;
            case TYPE_CountryCode_NZ:   // ニュージーランド(仮).
                Txt_FaxLineRXCallCountSExtent0P15.changeText( s_NOTITMService4To29 );   // 4 - 29.
                break;
            case TYPE_CountryCode_SG:   // シンガポール.
                Txt_FaxLineRXCallCountSExtent0P15.changeText( s_NOTITMServiceFax0To8 ); // 0 - 8.
                break;
            case TYPE_CountryCode_PH:   // フィリピン.
                Txt_FaxLineRXCallCountSExtent0P15.changeText( s_NOTServicePB0To9 );     // 0 - 9.
                break;
            case TYPE_CountryCode_MY:   // Receive Time - Malaysia.
                Txt_FaxLineRXCallCountSExtent0P15.changeText( s_NOTITMServiceFax3To8 );   // 3 - 8.
		break;
            default:                    // 上記以外の国.
                Txt_FaxLineRXCallCountSExtent0P15.changeText( s_NOTITMService0To45 );   // 0 - 45.
                break;
        }
	} else {
		Txt_TitleServiceFaxLineRXCallCount.changeText( s_BellTimesSetting );
		Btx_ServiceFaxLineRXCallCountValue    = getFaxIndi( TYPE_FaxRxCallRingsCount );
		Txt_FaxLineRXCallCountUnit.changeText( s_ServiceCount );
// comment 2014/12/09 OPS1 大濵 [Zeus5BK][CQ506732].
//        Txt_FaxLineRXCallCountSExtent0P15.changeText(s_NOTService0To15);
// comment 2015/07/23 HCLT_Anusha [MiSBK][CQ513724] Changed the text of "Number of RX call Rings" as "2 - 5" for NZ and "2 - 15" for MY.
        switch (e_CountryCode) {
            case TYPE_CountryCode_TW:   // 台湾.
                Txt_FaxLineRXCallCountSExtent0P15.changeText( s_NOTService0To3 );       // 0 - 3.
                break;
            case TYPE_CountryCode_CN:   // 中国.
                Txt_FaxLineRXCallCountSExtent0P15.changeText( s_NOTITMService0To2 );    // 0 - 2.
                break;
            case TYPE_CountryCode_NZ:   // No.of RX call Rings - New Zealand .
                Txt_FaxLineRXCallCountSExtent0P15.changeText( s_NOTITMServiceFax2To5 );   // 2 - 5.
        	break;
            case TYPE_CountryCode_MY:   // No.of RX call Rings - Malaysia.
                Txt_FaxLineRXCallCountSExtent0P15.changeText( s_NOTITMServiceFax2To15 );   // 2 - 15.
                break;
            default:                    // 上記以外の国
                Txt_FaxLineRXCallCountSExtent0P15.changeText(s_NOTService0To15);        // 0 - 15.
                break;
        }
	}
}

/**
 * @brief   Handling key selection.
 * @note    None.
 * @param   uc_Option - Option.
 * @return  None.
 */
void PServiceFaxLineStandardSetting1::procButtonOn( uchar uc_Option )
{
	switch( uc_Option ) {
		//case BTNID_KEY_SERVICEFAXRXSIGNALDETECTTIME:    m_bl_RXSignalDetect = False; break;
		case BTNID_KEY_SERVICEFAXRXSIGNALDETECTTIME:      m_bl_RXSignalDetect = True; break;
		//case BTNID_KEY_SERVICEFAXRXSIGNALDETECTCOUNT:   m_bl_RXSignalDetect = True; break;
		case BTNID_KEY_SERVICEFAXRXSIGNALDETECTCOUNT:     m_bl_RXSignalDetect = False; break;
		case BTNID_KEY_SERVICEFAXBUSYTONEDETECTOFF:       m_bl_BusyToneDetect = True; break;
		case BTNID_KEY_SERVICEFAXBUSYTONEDETECTON:        m_bl_BusyToneDetect = False; break;
		//case BTNID_KEY_SERVICEFAXRXCALLRINGSCOUNTUP:      addFaxIndi( TYPE_FaxRxCallRingsCount ); break;
		case BTNID_KEY_SERVICEFAXRXCALLRINGSCOUNTUP:
			if( True == m_bl_RXSignalDetect ) {
				addFaxIndi( TYPE_FaxRxCallRingsTime );
			} else {
				addFaxIndi( TYPE_FaxRxCallRingsCount );
			}
			break;
		//case BTNID_KEY_SERVICEFAXRXCALLRINGSCOUNTDOWN:    subFaxIndi( TYPE_FaxRxCallRingsCount ); break;
		case BTNID_KEY_SERVICEFAXRXCALLRINGSCOUNTDOWN:
			if( True == m_bl_RXSignalDetect ) {
				subFaxIndi( TYPE_FaxRxCallRingsTime );
			} else {
				subFaxIndi( TYPE_FaxRxCallRingsCount );
			}
			break;
		case BTNID_KEY_SERVICEFAXBUSYTONEDETECTCOUNTUP:   addFaxIndi( TYPE_FaxAdjustBusyToneCount ); break;
		case BTNID_KEY_SERVICEFAXBUSYTONEDETECTCOUNTDOWN: subFaxIndi( TYPE_FaxAdjustBusyToneCount ); break;
		default: break;
	}

	setupGamen(); // Update screen display.
}

//-----------------------------------------------------------------------------
/**
 * class PServiceFaxLineStandardSetting2 : G0B0904610 ファクス設定／回線規格設定2.
 */
//-----------------------------------------------------------------------------

/**
 * @brief   Screen display update.
 * @note    None.
 * @param   ss_Option - Option.
 * @return  None.
 */
void PServiceFaxLineStandardSetting2::setupGamen( short ss_Option )
{
	// Base class function call.
	PServiceFaxLineStandardSettingCom::setupGamen( ss_Option );

	Rbt_ServiceFaxLineStandardSettings.select( 1 ); // Select line 2.
	// Select dial tone detection ON/OFF key.
	Rbt_ServiceFaxLineDialToneDetection.select( ( m_bl_DialToneDetect == False ) ? 0 : 1 );
	// Get and display pause time and response waiting time.
	Btx_ServiceFaxLinePauseTimeValue        = getFaxIndi( TYPE_FaxPauseTime );
//  Btx_ServiceFaxLineResponseWaitTimeValue = getFaxIndi( TYPE_FaxResponseWaitingTime );
	Btx_ServiceFaxLineResponseWaitTimeValue = getFaxIndi( TYPE_FaxAdjustAnswerWait );
//	Key_ServiceFaxLineResponseWaitTimeNoLimit.select( ( 0 == getFaxIndi( TYPE_FaxResponseWaitingTime )) ? True: False );
	Key_ServiceFaxLineResponseWaitTimeNoLimit.select( ( 0 == getFaxIndi( TYPE_FaxAdjustAnswerWait ) ) ? True: False );
}

/**
 * @brief   Handling key selection.
 * @note    None.
 * @param   uc_Option - Option.
 * @return  None.
 */
void PServiceFaxLineStandardSetting2::procButtonOn( uchar uc_Option )
{
	float sf_FaxResponseWaitingTime = 0;
	switch( uc_Option ) {
		case BTNID_KEY_SERVICEFAXDIALTONEDETECTIONON:  m_bl_DialToneDetect = False; break;
		case BTNID_KEY_SERVICEFAXDIALTONEDETECTIONOFF: m_bl_DialToneDetect = True; break;
		case BTNID_KEY_SERVICEFAXPAUSETIMEUP:   addFaxIndi( TYPE_FaxPauseTime ); break;
		case BTNID_KEY_SERVICEFAXPAUSETIMEDOWN: subFaxIndi( TYPE_FaxPauseTime ); break;
		case BTNID_KEY_SERVICEFAXRESPONSEWAITINGTIMEUP:
//    		sf_FaxResponseWaitingTime = getFaxIndi( TYPE_FaxResponseWaitingTime );
			sf_FaxResponseWaitingTime = getFaxIndi( TYPE_FaxAdjustAnswerWait );
			// Minimum is kept 35.
			if( 0 == sf_FaxResponseWaitingTime ) {
				sf_FaxResponseWaitingTime = PNLD_MIN_WAITTIME;
//    			setFaxIndi( TYPE_FaxResponseWaitingTime, sf_FaxResponseWaitingTime );
				setFaxIndi( TYPE_FaxAdjustAnswerWait, sf_FaxResponseWaitingTime );
			} else {
//    			addFaxIndi( TYPE_FaxResponseWaitingTime );
				addFaxIndi( TYPE_FaxAdjustAnswerWait );
			}
			break;
		case BTNID_KEY_SERVICEFAXRESPONSEWAITINGTIMEDOWN:
//    		sf_FaxResponseWaitingTime = getFaxIndi( TYPE_FaxResponseWaitingTime );
			sf_FaxResponseWaitingTime = getFaxIndi( TYPE_FaxAdjustAnswerWait );
			// Minimum is kept 35.
			if( 0 == sf_FaxResponseWaitingTime ) {
				sf_FaxResponseWaitingTime = PNLD_MIN_WAITTIME;
//    			setFaxIndi( TYPE_FaxResponseWaitingTime, sf_FaxResponseWaitingTime );
				setFaxIndi( TYPE_FaxAdjustAnswerWait, sf_FaxResponseWaitingTime );
			} else {
//    			subFaxIndi( TYPE_FaxResponseWaitingTime );
				subFaxIndi( TYPE_FaxAdjustAnswerWait );
			}
			break;
		case BTNID_KEY_SERVICEFAXRESPONSEWAITINGTIMENOLIMIT:
		{
			// Set the responce waiting time.
//    		setFaxIndi( TYPE_FaxResponseWaitingTime, sf_FaxResponseWaitingTime );
//    		return;
			setFaxIndi( TYPE_FaxAdjustAnswerWait, sf_FaxResponseWaitingTime );
		}
		break;
		case BTNID_KEY_SERVICEFAXRESPONSEWAITINGTIMEINITIALIZE:
			// Initialize response waiting time.
// comment 2015/05/29 【HCLT-Anusha】【CQ-513725】 Changing the default value of "Response Waiting Time" for FAX Target accroding to the country code.
// comment 2015/05/29 【HCLT-Kalaiyarasi】【CQ-513725】 Changing the default value of "Response Waiting Time" for FAX Target "JP".
////    		setFaxIndi( TYPE_FaxResponseWaitingTime, 35 );
//   		setFaxIndi( TYPE_FaxAdjustAnswerWait, 35 );
		{
			APIC_MachineSetting* pc_MachineSetting = APIC_MachineSetting::newInstance();
			TYPE_CountryCode e_CountryCode = TYPE_CountryCode_JP;
			if ( NULL != pc_MachineSetting) {
			e_CountryCode = pc_MachineSetting->getCountryCode();	// Get the FAX Destination.
			}
			//if( TYPE_CountryCode_JP == e_CountryCode ) {	// FAX Destination is Japan.
			//	setFaxIndi( TYPE_FaxAdjustAnswerWait, 55 );	
			//} else {
			//	setFaxIndi( TYPE_FaxAdjustAnswerWait, 35 );		// FAX Destination is other than Japan.
			//}
			switch( e_CountryCode ) {
				case TYPE_CountryCode_CH: setFaxIndi( TYPE_FaxAdjustAnswerWait, 85 );	break;	// FAX Destination is Switzerland.
				case TYPE_CountryCode_TW: setFaxIndi( TYPE_FaxAdjustAnswerWait, 115 );	break;	// FAX Destination is Taiwan.
				case TYPE_CountryCode_BR: setFaxIndi( TYPE_FaxAdjustAnswerWait, 64 );	break;	// FAX Destination is Brazil .
				case TYPE_CountryCode_CN: setFaxIndi( TYPE_FaxAdjustAnswerWait, 48 );	break;	// FAX Destination is China.
				default: 				  setFaxIndi( TYPE_FaxAdjustAnswerWait, 55 );	break;	// FAX Destination other than above.
			}
		}
			break;
		default: break;
	}

	setupGamen(); // Update screen display.
}

/**
 * @brief   Return the setting value.
 * @note    None.
 * @param   TYPE_FaxAdjust , float.
 * @return  None.
 */
float PServiceFaxLineStandardSetting2::setFaxIndi( TYPE_FaxAdjust indi,float fax_value )
{
//	if ( ( TYPE_FaxResponseWaitingTime == indi ) && ( 0.00 == fax_value ) ){
	if( ( TYPE_FaxAdjustAnswerWait == indi ) && ( 0.00 == fax_value ) ) {
		// Set the Response wait time as "0".
//		setFaxAdjust( TYPE_FaxResponseWaitingTime, fax_value );
		setFaxAdjust( TYPE_FaxAdjustAnswerWait, fax_value );
		return ( getFaxIndi( indi ) );
	} else {
		return( PServiceFaxCom::setFaxIndi( indi,fax_value ) );
	}
}

//-----------------------------------------------------------------------------
/**
 * class PServiceFaxLineStandardSetting3 : G0B0904620 ファクス設定／回線規格設定3.
 */
//-----------------------------------------------------------------------------

/**
 * @brief   Screen display update.
 * @note    None.
 * @param   ss_Option - Option.
 * @return  None.
 */
void PServiceFaxLineStandardSetting3::setupGamen( short ss_Option )
{
	// Base class function call.
	PServiceFaxLineStandardSettingCom::setupGamen( ss_Option );

// comment 2015/01/29 OPS1嵯峨山 [ZeusS] [CQ506519].
// Comment 2017/11/29 【HCLT-Vishal】【Eagle】【制御構成変更_No.4】 Removing old function version check condition.
	if( APIC_KeyDevice::getKeyMode() == TYPE_KeyModeAdminMachineKM ){
		Txt_TitleServiceFaxLineErrorPageResend.showEnable(False);
		Rbt_ServiceFaxLineErrorPageResend.showEnable(False);
	}else{
		Txt_TitleServiceFaxLineErrorPageResend.showEnable(True);
		Rbt_ServiceFaxLineErrorPageResend.showEnable(True);
	}
	Rbt_ServiceFaxLineStandardSettings.select( 2 ); // Select line 3.
	// Select All Pages / Error Page.
	Rbt_ServiceFaxLineErrorPageResend.select( ( m_bl_ErrorPageRedial == True ) ? 0 : 1 );
	// Select ON/OFF settings.
	Rbt_ServiceFaxLineRXErrorV17.select( ( m_bl_RXErrorV17 == False ) ? 0 : 1 );
	// Get and display page redial count.
	Btx_ServiceFaxLineErrorPageRedialTimeValue = getFaxIndi( TYPE_FaxErrorPageRedialCount );
}

/**
 * @brief   Handling key selection.
 * @note    None.
 * @param   uc_Option - Option.
 * @return  None.
 */
void PServiceFaxLineStandardSetting3::procButtonOn( uchar uc_Option )
{
	APIC_FaxJobSetting* p_FaxJobSetting = PnlComGetFaxJobSetting();
// Comment 2015/11/02 【ZeusS_ZX0】【HCL_Vasu】【制御構成変更_No.76-1】Adding Error Code macro.
//	if( NULL == p_FaxJobSetting ) { return; }
	if( NULL == p_FaxJobSetting ) {
		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
		if (NULL !=pc_BFW_System){
			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19000A0100C54201 );
		}
		return;
	}
	switch( uc_Option ) {
		case BTNID_KEY_SERVICEFAXERRORPAGEREDIALALLPAGE:   m_bl_ErrorPageRedial = False; break;
		case BTNID_KEY_SERVICEFAXERRORPAGEREDIALERRORPAGE: m_bl_ErrorPageRedial = True;  break;
		case BTNID_KEY_SERVICEFAXERRORV17ON: m_bl_RXErrorV17    = False; break;
		case BTNID_KEY_SERVICEFAXRXERRORV17OFF: m_bl_RXErrorV17 = True;  break;
		case BTNID_KEY_SERVICEFAXERRORPAGEREDIALCOUNUP:   addFaxIndi( TYPE_FaxErrorPageRedialCount ); break;
		case BTNID_KEY_SERVICEFAXERRORPAGEREDIALCOUNDOWN: subFaxIndi( TYPE_FaxErrorPageRedialCount ); break;
// comment 2015/06/12 【HCLT-Anusha】【CQ-513725】 Changing the default value of "NUmber of Redial" based on FAX Target.
// comment 2015/05/29 【HCLT-Kalaiyarasi】【CQ-513725】 Changing the default value of "NUmber of Redial" based on FAX Target.
//      case BTNID_KEY_SERVICEFAXRESPONSEWAITINGTIMEINITIALIZE: setFaxIndi( TYPE_FaxErrorPageRedialCount, 0 ); break;
      case BTNID_KEY_SERVICEFAXRESPONSEWAITINGTIMEINITIALIZE:
	  {	
	  		APIC_MachineSetting* pc_MachineSetting = APIC_MachineSetting::newInstance();
	  		TYPE_CountryCode e_CountryCode = TYPE_CountryCode_JP;
			if ( NULL != pc_MachineSetting) {
				e_CountryCode = pc_MachineSetting->getCountryCode();	// Getting the FAX Destination.
			}
			switch(e_CountryCode) {
				//case TYPE_CountryCode_JP:			// FAX Destination is Japan.
				//case TYPE_CountryCode_EU:			// FAX Destination is Europe.
				//	setFaxIndi( TYPE_FaxErrorPageRedialCount, 3 );
				//	break;
				//case TYPE_CountryCode_US:			// FAX Destination is US.
				//	setFaxIndi( TYPE_FaxErrorPageRedialCount, 1 );
				//	break;
				//default:
				//	setFaxIndi( TYPE_FaxErrorPageRedialCount, 0 );
				//	break;
				case TYPE_CountryCode_AU:	    // FAX Destination is Japan.
				case TYPE_CountryCode_TW:		// FAX Destination is Taiwan.
				case TYPE_CountryCode_CN:		// FAX Destination is China.
					setFaxIndi( TYPE_FaxErrorPageRedialCount, 2 );
					break;
				case TYPE_CountryCode_US:		// FAX Destination is America.
				case TYPE_CountryCode_CA:		// FAX Destination is Canada.
				case TYPE_CountryCode_KR:		// FAX Destination is Korea.
				case TYPE_CountryCode_HK:		// FAX Destination is Hong Kong.
					setFaxIndi( TYPE_FaxErrorPageRedialCount, 1 );
					break;
				default:						 // FAX Destination is Other than above.
					setFaxIndi( TYPE_FaxErrorPageRedialCount, 3 );
					break;
			}
	  }
		break;
		default: break;
	}

	setupGamen(); // Update screen display.
}

