		if( False == m_bl_DialToneDetect ) { // ON.
			p_FaxGfpSetting->setC2DialToneDetect( TYPE_ToneDetect_1stDtExist );
		} else { // OFF.
			p_FaxGfpSetting->setC2DialToneDetect( TYPE_ToneDetect_1stDtNotExist );
		}
		// Set pause time.
		p_FaxGfpSetting->setC2PauseTime( ( uchar )sf_PauseTime );
// comment 2014/09/18 【HCLT-Thangachamy】【CQ-503726】Set the Responce waiting time.
