/**
 * @brief      : Button event processing.
 * @note       : None.
 * @param      : [I]  uchar option - option.
 * @return     : void
 */
void PServiceSignalOffHookTest::procButtonOn( uchar option )
{
	PDPC_FaxCommonApi*	cp_FaxCommonApi = NULL;		// Fax API interface class.
	// Get the instance
	cp_FaxCommonApi = PDPC_FaxCommonApi::getInstance();
	// NULL check
	if( NULL == cp_FaxCommonApi ) {
// Comment 2015/11/02 【ZeusS_ZX0】【HCL_Vasu】【制御構成変更_No.76-1】Adding Error Code macro.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//		if (NULL !=pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19000A0100C54E01 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}
	switch( option ) {
		case BTNID_SERVICEFAXOFFHOOKTESTLINE1:		//Line 1.
			if( False == m_bl_HookStatus1 ) {			// If it is currently OnHook.
// comment 2015/01/18 OPS1-Sky酒井(純） [ZeusS_ZX0][CQ523886].	    
				cp_FaxCommonApi->ReceiveOffHook( TYPE_CommLine1 );
				m_bl_HookStatus1 = True;
			} else {
				cp_FaxCommonApi->OnHook( TYPE_CommLine1 );
				m_bl_HookStatus1 = False;
			}
			break;
		case BTNID_SERVICEFAXOFFHOOKTESTLINE2:		//Line 2.
			if( False == m_bl_HookStatus2 ) {			// If it is currently OnHook.
// comment 2015/01/18 OPS1-Sky酒井(純） [ZeusS_ZX0][CQ523886].	    
				cp_FaxCommonApi->ReceiveOffHook( TYPE_CommLine2 );
				m_bl_HookStatus2 = True;
			} else {
				cp_FaxCommonApi->OnHook( TYPE_CommLine2 );
				m_bl_HookStatus2 = False;
			}
			break;
		case BTNID_SERVICEFAXOFFHOOKTESTLINE3:		//Line 3.
			if( False == m_bl_HookStatus3 ) {			// If it is currently OnHook.
// comment 2015/01/18 OPS1-Sky酒井(純） [ZeusS_ZX0][CQ523886].	    
				cp_FaxCommonApi->ReceiveOffHook( TYPE_CommLine3 );
				m_bl_HookStatus3 = True;
			} else {
				cp_FaxCommonApi->OnHook( TYPE_CommLine3 );
				m_bl_HookStatus3 = False;
			}
			break;
		case BTNID_SERVICEFAXOFFHOOKTESTLINE4:		//Line 4.
			if( False == m_bl_HookStatus4 ) {			// If it is currently OnHook.
// comment 2015/01/18 OPS1-Sky酒井(純） [ZeusS_ZX0][CQ523886].	    
				cp_FaxCommonApi->ReceiveOffHook( TYPE_CommLine4 );
				m_bl_HookStatus4 = True;
			} else {
				cp_FaxCommonApi->OnHook( TYPE_CommLine4 );
				m_bl_HookStatus4 = False;
			}
			break;
	}
	setupGamen();
}

/**
 * @brief      : Handling Ok button click.
 * @note       : None.
 * @param      : [I] uchar option.
 * @return     : void.
 */
void PServiceSignalOffHookTest::procOk( uchar option )
{
	if( False == m_bl_HookStatus1 &&		//Line 1 is On Hook.
	    False == m_bl_HookStatus2 &&		//Line 2 is On Hook.
	    False == m_bl_HookStatus3 &&		//Line 3 is On Hook.
	    False == m_bl_HookStatus4 ) {		//Line 4 is On Hook.
		nextGamen = &gp_ServiceFaxTestSelect ;		//Fax Test Screen.
	} else {
		setBuzzerType( PCGE_BuzzerType_InputNg );		// Raise NG buzzer sound.
	}
}

