void PServiceSignalDialTest::procInactivate()
{
	if( PNLD_FaxTestStatusOnRun == c_FaxTestStatus.getFaxTestStatus() ) {	// ファクステスト実行中の場合.
		requestFaxTestStop();	// ファクステストのテスト停止要求を行う.
	}
	PServiceFaxTestMenuCom::procInactivate();	// 親クラスの非アクティブ状態の通知.
}

void PServiceSignalDialTest::procFaxCmdRsKtn( uchar option, TYPE_CommLine e_FaxLineNo, FAXS_CmdRs s_CmdRs )
{
	PServiceFaxTestMenuCom::procFaxCmdRsKtn( option, e_FaxLineNo, s_CmdRs );

	// 正常終了かつ選択した回線と通知の回線が等しい場合.
	if( ( True == s_CmdRs.b_CmdResult ) && ( e_FaxLineNo == c_FaxTestStatus.getFaxTestCommLine() ) ) {
		// OKキー・リセットキー・ラインキーによるファクステスト外への画面遷移中の場合は終了要求を行う.
		if( ( PNLD_ServiceFaxTestChangeScreenOk == m_uc_ChangeScreen )
		    || ( PNLD_ServiceFaxTestChangeScreenReset == m_uc_ChangeScreen )
		    || ( PNLD_ServiceFaxTestChangeScreenLine == m_uc_ChangeScreen ) ) {
			requestFaxTestEnd();	// ファクステストのテスト終了要求を行う.
			// ファクステスト内への画面遷移時は、親クラスの画面遷移処理を実行.
		} else if( PNLD_ServiceFaxTestChangeScreenInside == m_uc_ChangeScreen ) {
			PServiceFaxTestMenuCom::procGoToPage( m_uc_GoToOption );
		}
	}
}

void PServiceSignalDialTest::procGoToMag( uchar uc_Option )
{
// comment 2015/10/19 HCLT_Vishnu [ZeusS_ZX0][CQ519486] Restricting the Screen transition when dialing.
//	if( ( PNLD_FaxTestStatusOnStop == c_FaxTestStatus.getFaxTestStatus() )
//		|| ( PNLD_FaxTestStatusOnRelayOffRun == c_FaxTestStatus.getFaxTestStatus() ) ) {
	if( PNLD_FaxTestStatusOnStop == c_FaxTestStatus.getFaxTestStatus() ) {
// comment 2017/01/10 SCD2-Sky浜野 [IT5_3.4][1008250].
		Bool bl_Ret = PDPC_FaxCommonApi::getInstance()->controlFaxTest( c_FaxTestStatus.getFaxTestCommLine() , PDPE_FaxTestKindStart ); // ダイアルテストの画面から抜ける際は、内部的にテストモードに入ってからの画面遷移状態を設定.
		if( False == bl_Ret ) {		// テスト開始要求NG.
			MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
			return;
		}
		requestFaxTestStop();	// ファクステストのテスト停止要求を行う.
		m_uc_ChangeScreen = PNLD_ServiceFaxTestChangeScreenLine;	// ファクステスト内での画面遷移状態を設定.
		setupGamen();	// 表示部品のセットアップ.
	} else {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
	}
}

void PServiceSignalDialTest::procGoToPage( uchar option )
{
//	if  (  PNLD_FaxTestStatusOnStop == c_FaxTestStatus.getFaxTestStatus() ) {
	if( ( True == m_bl_OnHook ) && ( PNLD_FaxTestStatusOnStop == c_FaxTestStatus.getFaxTestStatus() ) ) {
// comment 2016/01/28 OPS1-MSE馬場 [ZeusS_ZX0][CQ523880] テスト開始要求NG時、ブザーを鳴らし画面遷移を行わないように変更.
		Bool bl_ret = PDPC_FaxCommonApi::getInstance()->controlFaxTest( c_FaxTestStatus.getFaxTestCommLine() , PDPE_FaxTestKindStart ); // Enter the Test Mode.
		if( False == bl_ret ) {		// テスト開始要求NG.
			MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
			return;
		}
		switch( option ) {
			case BTNID_SERVICEFAXSIGNALSENDTEST:
			case BTNID_SERVICEFAXSIGNALRECEIVETEST:
			case BTNID_SERVICEFAXNCUTEST:
			case BTNID_SERVICEFAXDIALTEST:
				PServiceFaxTestMenuCom::procGoToPage( option ); break;	// 画面遷移
			default: LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, ( char* )"Assert Failed!" ); break;
		}
		if( NULL != nextGamen ) {
			m_uc_GoToOption = option;	// オプション値を保存.
			m_uc_ChangeScreen = PNLD_ServiceFaxTestChangeScreenInside;	// ファクステスト内での画面遷移状態を設定.
// comment 2016/01/28 OPS1-MSE馬場 [ZeusS_ZX0][CQ523880] テスト開始要求NG時、ブザーを鳴らし画面遷移を行わないように変更.
//			PDPC_FaxCommonApi::getInstance()->controlFaxTest( c_FaxTestStatus.getFaxTestCommLine() , PDPE_FaxTestKindStart ); // Enter the Test Mode.
		}
	} else {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
	}
}
/**
 * @brief      : Handling OK key click.
 * @note       : None.
 * @param      : Uchar -option.
 * @return     : None.
 */
void PServiceSignalDialTest::procOk( uchar option )
{
// comment 2015/10/19 HCLT_Vishnu [ZeusS_ZX0][CQ519486] Restricting the Screen transition when dialing.
//	if( False == m_bl_OnHook ) { // OffHook mode check.
	if( ( False == m_bl_OnHook ) || ( PNLD_FaxTestStatusOnRun ==  c_FaxTestStatus.getFaxTestStatus() ) ) { // OffHook mode check.
		setBuzzerType( PCGE_BuzzerType_InputNg ); // NG buzzer sound.
	} else {
		PDPC_FaxCommonApi::getInstance()->controlFaxTest( c_FaxTestStatus.getFaxTestCommLine() , PDPE_FaxTestKindStart ); // ダイアルテストの画面から抜ける際は、内部的にテストモードに入ってからの画面遷移状態を設定.
		c_FaxTestStatus.setFaxTestStatus( PNLD_FaxTestStatusOnStop );	// ファクステストのテスト停止要求を行う.
		PServiceFaxTestMenuCom::procOk( option );
	}
}
