// [Class] PServiceSystemCleanUnitSetting : H0B0C00C00 - Service mode / System2 /  Clean Unit Setting.
//=======================================================================================================.
/**
 * @brief      : Screen startup processing.
 * @note       : None.
 * @param      : None.
 * @return     : None.
 */
//=======================================================================================================.
void PServiceSystemCleanUnitSetting::startGamen()
{
	PServiceToSystemMenu2P2Com::startGamen();

// comment 2015/06/16 OPS1-Sky真田 [Poseidon2.0c][機器構成変更No.1]初期化.	
	init_value();
	
// Comment 2015/11/02 【ZeusS_ZX0】【HCL_Vasu】【制御構成変更_No.76-1】Adding Error Code macro.
//	if( NULL == PnlComGetPrinterServiceSetting() ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); return; }
// Comment 2023/08/23 FPT-ThinhND40 [IT6_int] [ 制御構成変更_No.76 ] Supports clean unit OFF when additional tray is installed for model SparrowIII.
	if( NULL == PnlComGetPrinterServiceSetting() || NULL == ppc_FeedTray ) {
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//		if (NULL !=pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x1900650100655701 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return; 
	}
	m_bl_CleanUnitInfo = (0 == PnlComGetPrinterServiceSetting()->getPrinterAdjust( TYPE_PrinterAdjustCleanUnit ) ) ? False : True;				// Get Clean Unit Setting value.
#ifdef DEF_A4_Cus
	if( TYPE_ModelTypeIII == PnlComGetSystemInfo()->getModelType() ){
// Comment 2023/09/13 FPT-ThinhND40 [IT6_2.3] [ 制御構成変更_No.76-2 ] Suppression of clean unit settings when Sparrow's 4th tray is installed.
		if( ppc_FeedTray->getTrayStatus( TYPE_FeedTray4 ) != TYPE_TrayStatusNon ){
			m_bl_CleanUnitInfo = False;
			Key_ServiceSystemCleanUnitSettingInstalled.showEnable( False );
		} else {
			Gra_ServiceSystemCleanUnitSettingInstalled.showEnable( False );
		}
	} else {
		Gra_ServiceSystemCleanUnitSettingInstalled.showEnable( False );
	}
#endif	// DEF_A4_Cus.
}
