{
	PServiceToSystemMenu2P2Com::setupGamen();

// comment 2015/06/16 OPS1-Sky真田 [Poseidon2.0c][機器構成変更No.1]画面更新.
#ifdef DEF_Zeus5BkCus
	showEnableAdjustmentParts( m_bl_CleanUnitInfo == True ? True : False );
	Num_ServiceSystemCleanUnitSettingPersent = (float)getPrinterIndi( TYPE_PrinterAdjustCleanUnitFanSpinTimeChoice );
#else
	showEnableAdjustmentParts( False );
#endif // DEF_Zeus5BkCus.

	Rbt_ServiceSystemCleanUnitSetting.select( m_bl_CleanUnitInfo == True ? 0 : 1 );									// Rotation button selection.
}
//=======================================================================================================.
/**
 * @brief      : Button event processing.
 * @note       : None.
 * @param      : [I]  uchar option.
 * @return     : void
 */
//=======================================================================================================.
void PServiceSystemCleanUnitSetting::procButtonOn( uchar option )
{
// comment 2015/06/16 OPS1-Sky真田 [Poseidon2.0c][機器構成変更No.1]「+」「-」Key押下時の振る舞い.
	switch( option ) {
		case BTNID_ServiceSystemCleanUnitSettingInstalled:   	m_bl_CleanUnitInfo = True; break;						// Installed key press.
		case BTNID_ServiceSystemCleanUnitSettingNotInstalled: 	m_bl_CleanUnitInfo = False; break;						// Not Installed key press.
		case BTNID_ServiceSystemCleanUnitSettingAdjUp: 			addIndi();	break;	//「+」Key.
		case BTNID_ServiceSystemCleanUnitSettingAdjDown: 		subIndi();	break;	//「-」Key.
		default: break;
	}
	setupGamen();
}

