PNLE_ServiceROIMSettingGamen	PServiceROIMServerFunctionSetCom::m_e_ROIMServerFunctionSetGamen = PNLE_ServiceROIMSettingGamen_FunctionSet;
Bool	PServiceROIMServerFunctionSetCom::m_bl_ROIMServerUseUnuse = False;
char	PServiceROIMServerFunctionSetCom::m_sc_ROIMServerURL[TYPD_RoimWscDataIF_WWServer_URLMaxLen] = {0};
char	PServiceROIMServerFunctionSetCom::m_sc_ROIMServerLoginID[TYPD_RoimWscDataIF_WWServer_LoginIDMaxLen] = {0};
char	PServiceROIMServerFunctionSetCom::m_sc_ROIMServerPassword[TYPD_RoimWscDataIF_WWServer_PasswordMaxLen] = {0};
//================================================================================================.
// 概要		: PServiceROIMServerFunctionSetCom : 遠隔ｻｰﾋﾞｽ設定／遠隔ｻｰﾋﾞｽ機能設定 共通 : 画面開始処理 .
// 備考		: なし.
//================================================================================================.
void PServiceROIMServerFunctionSetCom::startGamen()
{
	APIC_RoimWscDataIF *pc_RoimWscDataIF = APIC_RoimWscDataIF::newInstance();
	TYPS_RoimWscDataIF_ServerInfo st_ServerInfo;
	memset(&st_ServerInfo, 0x00, sizeof(TYPS_RoimWscDataIF_ServerInfo));

	if( NULL == pc_RoimWscDataIF ) {
// Comment 2015/11/02 【ZeusS_ZX0】【HCL_Vasu】【制御構成変更_No.76-1】Adding Error Code macro.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//		if (NULL !=pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x1900650100E55C01 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}

	// 親クラスを呼ぶ.
	PServiceNoFunctionCodeCom::startGamen();

	// メニューから呼ばれる場合はCommonAPIから全設定を読み込む。.
	if( True == m_bl_FromMenu ) {
		// 表示中画面のIndexを初期化する.
		m_e_ROIMServerFunctionSetGamen = PNLE_ServiceROIMSettingGamen_FunctionSet;

		// commonAPIから取得.
		pc_RoimWscDataIF->getRemoteServiceEnable( &m_bl_ROIMServerUseUnuse );											// 遠隔ｻｰﾋﾞｽ機能設定.
		pc_RoimWscDataIF->getServerInfo( &st_ServerInfo );
		strncpy(m_sc_ROIMServerURL, st_ServerInfo.m_sc_URL, TYPD_RoimWscDataIF_WWServer_URLMaxLen - 1);					// ｻｰﾊﾞｰ設定URL.
		strncpy(m_sc_ROIMServerLoginID, st_ServerInfo.m_sc_LoginID, TYPD_RoimWscDataIF_WWServer_LoginIDMaxLen - 1);		// ｻｰﾊﾞｰ設定ID.
		strncpy(m_sc_ROIMServerPassword, st_ServerInfo.m_sc_Password, TYPD_RoimWscDataIF_WWServer_PasswordMaxLen - 1);	// ｻｰﾊﾞｰ設定ﾊﾟｽﾜｰﾄﾞ.

		m_bl_FromMenu = False;
	}
}
//================================================================================================.
// 概要		: PServiceROIMServerFunctionSetCom : 遠隔ｻｰﾋﾞｽ設定／遠隔ｻｰﾋﾞｽ機能設定 共通 : 画面更新処理.
// 備考		: なし.
//================================================================================================.
void PServiceROIMServerFunctionSetCom::setupGamen( short option )
{
	// 親クラスを呼ぶ.
	PServiceNoFunctionCodeCom::setupGamen();

	switch( m_e_ROIMServerFunctionSetGamen ) {
		case PNLE_ServiceROIMSettingGamen_FunctionSet:		// 遠隔ｻｰﾋﾞｽ機能設定.
			Rbt_ServiceROIMSetting.select(0);
			break;
		case PNLE_ServiceROIMSettingGamen_ServerURL:		// ｻｰﾊﾞｰ設定URL.
			Rbt_ServiceROIMSetting.select(1);
			Rbt_ServiceROIMServerSettingMenu.select(0);
			break;
		case PNLE_ServiceROIMSettingGamen_ServerID:			// ｻｰﾊﾞｰ設定ID.
			Rbt_ServiceROIMSetting.select(1);
			Rbt_ServiceROIMServerSettingMenu.select(1);
			break;
		case PNLE_ServiceROIMSettingGamen_ServerPassword:	// ｻｰﾊﾞｰ設定ﾊﾟｽﾜｰﾄﾞ.
			Rbt_ServiceROIMSetting.select(1);
			Rbt_ServiceROIMServerSettingMenu.select(2);
			break;
		default:
			break;
	}
}
//================================================================================================.
// 概要		: PServiceROIMServerFunctionSetCom : 遠隔ｻｰﾋﾞｽ設定／遠隔ｻｰﾋﾞｽ機能設定 共通 : インデックスボタン処理.
// 備考		: なし.
