void PServiceROIMServerFunctionSetCom::procIndexButton( uchar option )
{
	switch( option ) {
		// 遠隔ｻｰﾋﾞｽ機能設定.
		case BTNID_ServiceROIMSetting:
			m_e_ROIMServerFunctionSetGamen = PNLE_ServiceROIMSettingGamen_FunctionSet;
			nextGamen = &gp_ServiceROIMSetting;					// K4B0011000_遠隔ｻｰﾋﾞｽ設定／遠隔ｻｰﾋﾞｽ機能設定.
			break;
		// ｻｰﾊﾞｰ設定.
		case BTNID_ServiceROIMServerSetting:
			m_e_ROIMServerFunctionSetGamen = PNLE_ServiceROIMSettingGamen_ServerURL;
			nextGamen = &gp_ServiceROIMServerSetting_URL;		// K4B0011100_遠隔ｻｰﾋﾞｽ設定／ｻｰﾊﾞｰ設定/URL.
			break;
		default:
			break;
	}
}
