void PServiceROIMServerFunctionSetCom::procGoToPage( uchar option )
{
	switch( option ) {
		case BTNID_ServiceROIMServerSetting_URL:					// ｻｰﾊﾞｰ設定URL.
			m_e_ROIMServerFunctionSetGamen = PNLE_ServiceROIMSettingGamen_ServerURL;
			nextGamen = &gp_ServiceROIMServerSetting_URL;
			break;
		case BTNID_ServiceROIMServerSetting_LoginID:				// ｻｰﾊﾞｰ設定ID.
			m_e_ROIMServerFunctionSetGamen = PNLE_ServiceROIMSettingGamen_ServerID;
			nextGamen = &gp_ServiceROIMServerSetting_ID;
			break;
		case BTNID_ServiceROIMServerSetting_Password:				// ｻｰﾊﾞｰ設定ﾊﾟｽﾜｰﾄﾞ.
			m_e_ROIMServerFunctionSetGamen = PNLE_ServiceROIMSettingGamen_ServerPassword;
			nextGamen = &gp_ServiceROIMServerSetting_Password;
			break;
		default:
			break;
	}
}
//================================================================================================.
// 概要		: PServiceROIMServerFunctionSetCom : 遠隔ｻｰﾋﾞｽ設定／遠隔ｻｰﾋﾞｽ機能設定 共通 : Ok押下処理.
// 備考		: なし.
//================================================================================================.
void PServiceROIMServerFunctionSetCom::procOk( uchar option )
{
	TYPS_RoimWscDataIF_ServerInfo st_ServerInfo;
	memset(&st_ServerInfo, 0x00, sizeof(TYPS_RoimWscDataIF_ServerInfo));
	
	APIC_RoimWscDataIF *pc_RoimWscDataIF = APIC_RoimWscDataIF::newInstance();
	if( NULL == pc_RoimWscDataIF ) {
// Comment 2015/11/02 【ZeusS_ZX0】【HCL_Vasu】【制御構成変更_No.76-1】Adding Error Code macro.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//		if (NULL !=pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x1900030100E55D01 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}

	// 遠隔ｻｰﾋﾞｽ機能設定:使用する、且つ、URLまたID名未入力時、画面遷移しない.
	if( (True == m_bl_ROIMServerUseUnuse) && ( ('\0' == m_sc_ROIMServerURL[0]) || ('\0' == m_sc_ROIMServerLoginID[0]) ) ) {
		setBuzzerType( PCGE_BuzzerType_InputNg );	// ブザー音セット.
		return;
	}

// comment 2018/05/18 Sky西村 [IT6_1.0][RQ-752][1046235].
	// CommonAPIに設定.
	if( False == m_bl_ROIMServerUseUnuse ) { // 「使用する」の設定値は証明書インストール成功時にCommonAPIにて設定する.
		pc_RoimWscDataIF->setRemoteServiceEnable( m_bl_ROIMServerUseUnuse );										// 遠隔ｻｰﾋﾞｽ機能設定.
	}

	strncpy(st_ServerInfo.m_sc_URL, m_sc_ROIMServerURL, TYPD_RoimWscDataIF_WWServer_URLMaxLen - 1);					// ｻｰﾊﾞｰ設定URL.
	strncpy(st_ServerInfo.m_sc_LoginID, m_sc_ROIMServerLoginID, TYPD_RoimWscDataIF_WWServer_LoginIDMaxLen - 1);		// ｻｰﾊﾞｰ設定ID.
	strncpy(st_ServerInfo.m_sc_Password, m_sc_ROIMServerPassword, TYPD_RoimWscDataIF_WWServer_PasswordMaxLen - 1);	// ｻｰﾊﾞｰ設定ﾊﾟｽﾜｰﾄﾞ.
	pc_RoimWscDataIF->setServerInfo( &st_ServerInfo );																// ｻｰﾊﾞｰ情報設定.

	// データ変化を通知する.
	pc_RoimWscDataIF->changeParameter();

	// 画面遷移.
	nextGamen = &gp_ServiceROIMMenu;									// 「K4B0010000_ネットワーク設定／遠隔ｻｰﾋﾞｽ設定／メニュー」画面.
}
