//================================================================================================.
// 概要		: PServiceROIMSetting : K4B0011000_遠隔ｻｰﾋﾞｽ設定／遠隔ｻｰﾋﾞｽ機能設定 : 画面開始処理.
// 備考		: なし.
//================================================================================================.
void PServiceROIMSetting::startGamen()
{
	APIC_RoimWscDataIF *pc_RoimWscDataIF = APIC_RoimWscDataIF::newInstance();
	if( NULL == pc_RoimWscDataIF ) {
// Comment 2015/11/02 【ZeusS_ZX0】【HCL_Vasu】【制御構成変更_No.76-1】Adding Error Code macro.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//		if (NULL !=pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x1900650100E55E01 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}
	pc_RoimWscDataIF->getWWRemoteServicePermit( &m_bl_ROIMServerUseUnuse_Admin );	// 遠隔ｻｰﾋﾞｽ機能設定を取得する（管理者）.

// comment 2018/05/18 Sky西村 [IT6_1.0][RQ-752][1046235].
	m_bl_SelectServiceROIMSettingFix = False;	//「確定」非選択.
	
	// 証明書インストール状態を取得する.
	m_c_CertInstallResult = { 0 };
	pc_RoimWscDataIF->getCertInstallationStatus( &m_c_CertInstallResult );
	
	// 証明書インストールが実施済の場合は、前回の結果を表示する.
	if( TYPE_RoimWscDataIF_CertInstallationResult_NONE == m_c_CertInstallResult.m_e_Result ) {
		m_e_CertInstallStatus			= PNLE_CertInstallStatus_None;	// 証明書インストール未実施.
	}
	else {
		m_e_CertInstallStatus			= PNLE_CertInstallStatus_Done;	// 証明書インストール完了.
		
		// 日付表示文字列取得.
		char uc_CertInstallResultTime[ PNLD_CertInstallDateLenMax + 1 ];
		getDayTimeDisplay( uc_CertInstallResultTime, &m_c_CertInstallResult.m_ul_Time );
		
		// 表示文字列変更.
		Tfd_ServiceROICertInstallResultTimeVal.changeExternalText( ( uchar* )uc_CertInstallResultTime, sizeof( uc_CertInstallResultTime ) );
		Tfd_ServiceROICertInstallResultErrorCodeVal.changeExternalText( ( uchar* )m_c_CertInstallResult.m_sc_ErrorCode, sizeof( m_c_CertInstallResult.m_sc_ErrorCode ) );
	}
	
	PServiceROIMServerFunctionSetCom::startGamen();
}
//================================================================================================.
// 概要		: PServiceROIMSetting : K4B0011000_遠隔ｻｰﾋﾞｽ設定／遠隔ｻｰﾋﾞｽ機能設定 : 画面更新処理.
// 備考		: なし.
//================================================================================================.
void PServiceROIMSetting::setupGamen( short option )
{
// comment 2015.08.17 [CQ516452] No.15 ﾘﾓｰﾄｻｰﾋﾞｽ設定_キー非表示条件修正対応 日立 井原. 
//	if( (True == PnlComGetSystemSetting()->getSecurityLevelUpOn())
//	 || (False == m_bl_ROIMServerUseUnuse_Admin) ) {
//		// セキュリティ強化モードON、或は（管理者）遠隔サービス機能設定が禁止の場合は、使用するキー非表示.
//		Key_ServiceROIMSettingUse.showEnable( False );
//	}
//	else {
//		// セキュリティ強化モードOFF且つ遠隔サービス機能設定が許可の場合は、使用するキー表示.
//		Key_ServiceROIMSettingUse.showEnable( True );
//	}

// comment 2018/05/18 Sky西村 [IT6_1.0][RQ-752][1046235].
//	// サーバー設定は機能設定で「使用しない」とした時、表示しない.
//	if( False == m_bl_ROIMServerUseUnuse ) {
//		Key_ServiceROIMServerSetting.showEnable( False );
//	}
//	else {
		Key_ServiceROIMServerSetting.showEnable( True );	// サーバー設定は常に表示する.
//	}

	Rbt_ServiceROIMSettingUseUnuse.select( True == m_bl_ROIMServerUseUnuse ? 0 : 1 );	// 使用する/使用しない.
	PServiceROIMServerFunctionSetCom::setupGamen(option);

// comment 2018/05/18 Sky西村 [IT6_1.0][RQ-752][1046235].
	switch( m_e_CertInstallStatus ) {
		case PNLE_CertInstallStatus_None:		// 証明書ｲﾝｽﾄｰﾙ未実施.
			Txt_ServiceROICertInstall.showEnable( False );								// 「証明書をｲﾝﾎﾟｰﾄする」.
			Txt_ServiceROICertInstallRunning.showEnable( False );						// 「実行中」.
			Txt_ServiceROICertInstallActionSlash.showEnable( False );					// 「／」「＼」.
			Txt_ServiceROICertInstallResultTitle.showEnable( False );					// 「結果」.
			Txt_ServiceROICertInstallResultColon.showEnable( False );					// 「:」.
			Txt_ServiceROICertInstallResultOKNG.showEnable( False );					// 「OK」「NG」.
			Txt_ServiceROICertInstallResultErrorCode.showEnable( False );				// 「ｴﾗｰｺｰﾄﾞ」.
			Txt_ServiceROICertInstallResultErrorColon.showEnable( False );					// 「:」.
			Tfd_ServiceROICertInstallResultErrorCodeVal.showEnable( False );			// エラーコード.
			Tfd_ServiceROICertInstallResultTimeVal.showEnable( False );					// 実施時刻.
			break;
		case PNLE_CertInstallStatus_Running:	// 証明書ｲﾝｽﾄｰﾙ実行中.
			Txt_ServiceROICertInstall.showEnable( True );								// 「証明書をｲﾝﾎﾟｰﾄする」.
			static Bool bl_CertInstallActionSlashNow = False;							// 「／」「＼」の表示状態.
			Txt_ServiceROICertInstallRunning.showEnable( true );						// 「実行中」.
			Txt_ServiceROICertInstallActionSlash.changeText( True == bl_CertInstallActionSlashNow ? s_EXPSlash : s_EXPBackslash );
			Txt_ServiceROICertInstallActionSlash.showEnable( true );					// 「／」「＼」.
			bl_CertInstallActionSlashNow = ( ( True == bl_CertInstallActionSlashNow ) ? False : True );	// 「／」「＼」を交互に表示.
			Txt_ServiceROICertInstallResultTitle.showEnable( False );					//「結果」.
			Txt_ServiceROICertInstallResultColon.showEnable( False );					// 「:」.
			Txt_ServiceROICertInstallResultOKNG.showEnable( False );					// 「OK」「NG」.
			Txt_ServiceROICertInstallResultErrorCode.showEnable( False );				// 「ｴﾗｰｺｰﾄﾞ」.
			Txt_ServiceROICertInstallResultErrorColon.showEnable( False );				// 「:」.
			Tfd_ServiceROICertInstallResultErrorCodeVal.showEnable( False );			// エラーコード.
			Tfd_ServiceROICertInstallResultTimeVal.showEnable( False );					// 実施時刻.
			break;
		case PNLE_CertInstallStatus_Done:		// 証明書ｲﾝｽﾄｰﾙ完了.
			if( TYPE_RoimWscDataIF_CertInstallationResult_OK == m_c_CertInstallResult.m_e_Result ) {	// 証明書ｲﾝｽﾄｰﾙ成功.
					Txt_ServiceROICertInstallResultOKNG.changeText( s_OKService );		// 「OK」に変更.
					Txt_ServiceROICertInstallResultErrorCode.showEnable( False );		// 「ｴﾗｰｺｰﾄﾞ」.
					Txt_ServiceROICertInstallResultErrorColon.showEnable( False );		// 「:」.
					Tfd_ServiceROICertInstallResultErrorCodeVal.showEnable( False );	// エラーコード.
			}
			else if( TYPE_RoimWscDataIF_CertInstallationResult_NG == m_c_CertInstallResult.m_e_Result ) {	// 証明書ｲﾝｽﾄｰﾙ失敗.
					Txt_ServiceROICertInstallResultOKNG.changeText( s_NGService );		// 「NG」に変更.
					Txt_ServiceROICertInstallResultErrorCode.showEnable( True );		// 「ｴﾗｰｺｰﾄﾞ」.
					Txt_ServiceROICertInstallResultErrorColon.showEnable( True );		// 「:」.
					Tfd_ServiceROICertInstallResultErrorCodeVal.showEnable( True );		// エラーコード.
			}
			Txt_ServiceROICertInstall.showEnable( True );								// 「証明書をｲﾝﾎﾟｰﾄする」.
			Txt_ServiceROICertInstallRunning.showEnable( False );						// 「実行中」.
			Txt_ServiceROICertInstallActionSlash.showEnable( False );					// 「／」「＼」.
			Txt_ServiceROICertInstallResultTitle.showEnable( True );					//「結果」.
			Txt_ServiceROICertInstallResultColon.showEnable( True );					// 「:」.
			Txt_ServiceROICertInstallResultOKNG.showEnable( True );						// 「OK」「NG」.
			Tfd_ServiceROICertInstallResultTimeVal.showEnable( True );					// 実施時刻.
			break;
		default:
			break;
	}

	if( True == m_bl_ROIMServerUseUnuse ) {						// 「使用する」選択時.
		if( ( PNLE_CertInstallStatus_None == m_e_CertInstallStatus ) ||		// 未実施.
			( PNLE_CertInstallStatus_Running == m_e_CertInstallStatus ) ||	// 実行中.
			( ( PNLE_CertInstallStatus_Done == m_e_CertInstallStatus ) && ( TYPE_RoimWscDataIF_CertInstallationResult_NG == m_c_CertInstallResult.m_e_Result ) ) ) {	// 完了だが失敗.
			Key_OkService.showEnable( False );					// OKキー.
			Key_ServiceToLine.showEnable( False );				// ラインキー.
		}
		else {
			Key_OkService.showEnable( True );					// OKキー.
		}
		Txt_ServiceROICertInstallDownArrow.showEnable( True );	//「↓」.
		Key_ServiceROIMSettingFix.showEnable( True );			//「確定」.
	}
	else {
		Key_OkService.showEnable( True );						// OKキー.
		Txt_ServiceROICertInstallDownArrow.showEnable( False );	//「↓」.
		Key_ServiceROIMSettingFix.showEnable( False );			//「確定」.
	}
	Key_ServiceROIMSettingFix.select( m_bl_SelectServiceROIMSettingFix );				//「確定」選択状態.

}
//================================================================================================.
// 概要		: PServiceROIMSetting : K4B0011000_遠隔ｻｰﾋﾞｽ設定／遠隔ｻｰﾋﾞｽ機能設定 : ボタン押下処理.
// 備考		: なし.
//================================================================================================.
void PServiceROIMSetting::procButtonOn( uchar option )
{
	switch( option ) {
		// 使用しない.
// comment 2018/05/18 Sky西村 [IT6_1.0][RQ-752][1046235].
//		case BTNID_ServiceROIMSetting_Unuse:	m_bl_ROIMServerUseUnuse = False;	break;	// 選択中を「使用しない」にする.
		case BTNID_ServiceROIMSetting_Unuse:
			if( PNLE_CertInstallStatus_Running != m_e_CertInstallStatus ) {	// 証明書インストール実行中でない.
				m_bl_ROIMServerUseUnuse = False;							// 選択中を「使用しない」にする.
			}
			else {
				setBuzzerType( PCGE_BuzzerType_InputNg );
			}
			break;
		// 使用する.
		case BTNID_ServiceROIMSetting_Use:		m_bl_ROIMServerUseUnuse = True;		break;	// 選択中を「使用する」にする.
// comment 2018/05/18 Sky西村 [IT6_1.0][RQ-752][1046235].
		case BTNID_ServiceROIMSetting_Fix:		// 「確定」キー.
			if( ( PNLE_CertInstallStatus_Running != m_e_CertInstallStatus ) &&	// 証明書インストール実行中でない.
				( '\0' != m_sc_ROIMServerURL[0] ) && 							// ｻｰﾊﾞｰ設定URLが空でない.
				( '\0' != m_sc_ROIMServerLoginID[0] ) ) {						// ｻｰﾊﾞｰ設定IDが空でない.

				// サーバー設定を保存する.
				APIC_RoimWscDataIF *pc_RoimWscDataIF = APIC_RoimWscDataIF::newInstance();
				if( NULL == pc_RoimWscDataIF ) {
					LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
					return;
				}
				TYPS_RoimWscDataIF_ServerInfo st_ServerInfo;
				memset( &st_ServerInfo, 0x00, sizeof( TYPS_RoimWscDataIF_ServerInfo ) );
				strncpy( st_ServerInfo.m_sc_URL, m_sc_ROIMServerURL, ( TYPD_RoimWscDataIF_WWServer_URLMaxLen - 1 ) );					// ｻｰﾊﾞｰ設定URL.
				strncpy( st_ServerInfo.m_sc_LoginID, m_sc_ROIMServerLoginID, ( TYPD_RoimWscDataIF_WWServer_LoginIDMaxLen - 1 ) );		// ｻｰﾊﾞｰ設定ID.
				strncpy( st_ServerInfo.m_sc_Password, m_sc_ROIMServerPassword, ( TYPD_RoimWscDataIF_WWServer_PasswordMaxLen - 1 ) );	// ｻｰﾊﾞｰ設定ﾊﾟｽﾜｰﾄﾞ.
				pc_RoimWscDataIF->setServerInfo( &st_ServerInfo );																		// ｻｰﾊﾞｰ情報設定.
				pc_RoimWscDataIF->changeParameter();	// データ変化を通知する.
				
				// 証明書がインストールされている場合は、取得した結果を表示する.
				if( True == PnlComGetRdsSetting()->getProductCertStatus() ) {
					m_e_CertInstallStatus 				= PNLE_CertInstallStatus_Done;	// 証明書インストール完了.
					m_bl_SelectServiceROIMSettingFix	= False;						//「確定」非選択.
					
					// 証明書インストール結果取得.
					m_c_CertInstallResult = { 0 };
					pc_RoimWscDataIF->getCertInstallationStatus( &m_c_CertInstallResult );
					
					// 日付表示文字列取得.
					char uc_CertInstallResultTime[ PNLD_CertInstallDateLenMax + 1 ];
					getDayTimeDisplay( uc_CertInstallResultTime, &m_c_CertInstallResult.m_ul_Time );
					
					// 表示文字列変更.
					Tfd_ServiceROICertInstallResultTimeVal.changeExternalText( ( uchar* )uc_CertInstallResultTime, sizeof( uc_CertInstallResultTime ) );
					Tfd_ServiceROICertInstallResultErrorCodeVal.changeExternalText( ( uchar* )m_c_CertInstallResult.m_sc_ErrorCode, sizeof( m_c_CertInstallResult.m_sc_ErrorCode ) );
				}
				// 証明書がインストールされていない場合は、証明書インストール中、画面に実行中画面を表示する.
				else {
					m_e_CertInstallStatus = PNLE_CertInstallStatus_Running;				// 証明書インストール実行中.
					m_bl_SelectServiceROIMSettingFix = True;							//「確定」選択.
				}
				pc_RoimWscDataIF->setRemoteServiceEnable( True );		// 遠隔ｻｰﾋﾞｽ機能設定.
			}
			else {
				setBuzzerType( PCGE_BuzzerType_InputNg );
			}
			break;
		default: break;
	}
	setupGamen( option );
}

// comment 2018/05/18 Sky西村 [IT6_1.0][RQ-752][1046235].
//================================================================================================.
// 概要		: PServiceROIMSetting : K4B0011000_遠隔ｻｰﾋﾞｽ設定／遠隔ｻｰﾋﾞｽ機能設定 : Okキー押下処理.
