//================================================================================================.
void PServiceROIMSetting::procOk( uchar option )
{
	// 証明書インストール実行中.
	if( PNLE_CertInstallStatus_Running == m_e_CertInstallStatus ) {
		setBuzzerType( PCGE_BuzzerType_InputNg );
	}
	else {
		PServiceROIMServerFunctionSetCom::procOk( option );
	}
}

