//================================================================================================.
// 概要		: PServiceROIMSetting : K4B0011000_遠隔ｻｰﾋﾞｽ設定／遠隔ｻｰﾋﾞｽ機能設定 : オブザーバー処理.
// 備考		:なし.
//================================================================================================.
void PServiceROIMSetting::procObserver( TYPE_PNL_Observer e_PNL_Observer )
{
	switch( e_PNL_Observer ){
		case TYPE_PNL_Observer_ProductCertificateInstall:	// 証明書インストール完了通知.
		{
			APIC_RoimWscDataIF *pc_RoimWscDataIF = APIC_RoimWscDataIF::newInstance();
			if( NULL == pc_RoimWscDataIF ) {
				LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
				return;
			}
			
			// 証明書インストール結果取得.
			m_c_CertInstallResult = { 0 };
			pc_RoimWscDataIF->getCertInstallationStatus( &m_c_CertInstallResult );

			// 日付表示文字列取得.
			char uc_CertInstallResultTime[ PNLD_CertInstallDateLenMax + 1 ];
			getDayTimeDisplay( uc_CertInstallResultTime, &m_c_CertInstallResult.m_ul_Time );

			// 表示文字列変更.
			Tfd_ServiceROICertInstallResultTimeVal.changeExternalText( ( uchar* )uc_CertInstallResultTime, sizeof( uc_CertInstallResultTime ) );
			Tfd_ServiceROICertInstallResultErrorCodeVal.changeExternalText( ( uchar* )m_c_CertInstallResult.m_sc_ErrorCode, sizeof( m_c_CertInstallResult.m_sc_ErrorCode ) );

			m_e_CertInstallStatus		= PNLE_CertInstallStatus_Done;	// 証明書インストール完了.
			m_bl_SelectServiceROIMSettingFix = False;					//「確定」非選択.

			break;
		}
		default:
			PServiceROIMServerFunctionSetCom::procObserver( e_PNL_Observer );	// 継承元(親)のprocObserverを呼び出す.
			break;
	}
}

//================================================================================================.
// 概要		: PServiceROIMSetting : K4B0011000_遠隔ｻｰﾋﾞｽ設定／遠隔ｻｰﾋﾞｽ機能設定 : 日付表示文字列取得.
// 備考		:なし.
//================================================================================================.
void PServiceROIMSetting::getDayTimeDisplay( char* sc_DateTime, time_t* pc_Date )
{
	if( NULL == sc_DateTime ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}

	if( NULL == pc_Date ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}

	// 日付を整形する.
	struct tm	st_Time = { 0 };
	SYSF_localtime_r( pc_Date, &st_Time );
	st_Time.tm_year += 1900;				
										
	//仕向けにより表示文字列を変更する.
	TYPE_SystemType e_SystemType = PnlComGetMachineSetting()->getSystemType();
	switch( e_SystemType ) {
		case TYPE_SystemType_US:	// MC仕向け.
//Comment 2018/12/06【HCLT-Nasreen】【IT6_Eagle】【AR 1069463】Removed the displayed Time and changed correctly month value.
//		  sprintf( sc_DateTime,"%02d/%02d/%04d %02d:%02d", st_Time.tm_mon,  st_Time.tm_mday, st_Time.tm_year, st_Time.tm_hour, st_Time.tm_min );
		  sprintf( sc_DateTime,"%02d/%02d/%04d", st_Time.tm_mon + 1,  st_Time.tm_mday, st_Time.tm_year);		
			break;
		case TYPE_SystemType_JP:	// 日本仕向け.
//Comment 2018/12/06【HCLT-Nasreen】【IT6_Eagle】【AR 1069463】Removed the displayed Time and changed correctly month value.
//			sprintf( sc_DateTime,"%04d/%02d/%02d %02d:%02d", st_Time.tm_year, st_Time.tm_mon,  st_Time.tm_mday, st_Time.tm_hour, st_Time.tm_min );
		    sprintf( sc_DateTime,"%04d/%02d/%02d", st_Time.tm_year, st_Time.tm_mon + 1,  st_Time.tm_mday);
			break;
		case TYPE_SystemType_EU:	// EU仕向け.
		default:					// その他.
//Comment 2018/12/06 【HCLT-Nasreen】【IT6_Eagle】【AR 1069463】Removed the displayed Time and changed correctly month value.
//			sprintf( sc_DateTime,"%02d/%02d/%04d %02d:%02d", st_Time.tm_mday, st_Time.tm_mon,  st_Time.tm_year, st_Time.tm_hour, st_Time.tm_min );
			sprintf( sc_DateTime,"%02d/%02d/%04d", st_Time.tm_mday, st_Time.tm_mon + 1,  st_Time.tm_year );
			break;
	}
}

