// 遠隔サービス設定／Proxyサーバー設定.
PNLE_ServiceROIMProxySettingGamen	PServiceROIMProxyServerSetCom::m_e_ROIMProxyServerGamen = PNLE_ServiceROIMProxySettingGamen_UseSet;
char	PServiceROIMProxyServerSetCom::m_sc_ProxyServer_URL[TYPD_RoimWscDataIF_ProxyServer_URLMaxLen] = {0};
char	PServiceROIMProxyServerSetCom::m_sc_ProxyServer_UserName[TYPD_RoimWscDataIF_ProxyServer_UserNameMaxLen] = {0};
char	PServiceROIMProxyServerSetCom::m_sc_ProxyServer_Password[TYPD_RoimWscDataIF_ProxyServer_PasswordMaxLen] = {0};
ushort	PServiceROIMProxyServerSetCom::m_us_ProxyServer_PortNumber = 1;
Bool	PServiceROIMProxyServerSetCom::m_bl_ROIMProxyOffOn = False;
Bool	PServiceROIMProxyServerSetCom::m_bl_ROIMWebDAVOffOn = False;
//================================================================================================.
// 概要		: PServiceROIMProxyServerSetCom : コンストラクタ.
// 備考		: なし.
//================================================================================================.
PServiceROIMProxyServerSetCom::PServiceROIMProxyServerSetCom( PDisplayParts** partsTable, short partsNumber, Bool isNoWarning )	// コンストラクタ.
	: PServiceNoFunctionCodeCom( partsTable, partsNumber, isNoWarning )
{
	m_bl_FromMenu = False;
}
//================================================================================================.
// 概要		: PServiceROIMProxyServerSetCom : 遠隔サービス設定／Proxyサーバー設定_共通 :画面開始処理.
// 備考		: なし.
//================================================================================================.
void PServiceROIMProxyServerSetCom::startGamen()
{
// 2015/03/12 [MAv3][RQ-243] XMPPによるリアルタイム指示 日立 村上(幸).
	APIC_RoimWscDataIF *pc_RoimWscDataIF = NULL;
	pc_RoimWscDataIF = APIC_RoimWscDataIF::newInstance();

	if( NULL == pc_RoimWscDataIF ) {
// Comment 2015/11/02 【ZeusS_ZX0】【HCL_Vasu】【制御構成変更_No.76-1】Adding Error Code macro.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//		if (NULL !=pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x1900650100E55F01 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}

	// 親クラスを呼ぶ.
	PServiceNoFunctionCodeCom::startGamen();

	// メニューから呼ばれる場合はCommonAPIから全設定を読み込む。.
	if( True == m_bl_FromMenu ) {
		// 表示中画面のIndexを初期化する.
		m_e_ROIMProxyServerGamen = PNLE_ServiceROIMProxySettingGamen_UseSet;
		// commonAPIから取得.
		pc_RoimWscDataIF->getProxySVR_Enable( &m_bl_ROIMProxyOffOn );							// Proxyサーバー設定機能使用OFF/ON.
		pc_RoimWscDataIF->getProxySVR_LinkWebDAVClient( &m_bl_ROIMWebDAVOffOn );				// WebDAV連動機能連動OFF/ON.
		pc_RoimWscDataIF->getProxySVR_URL( m_sc_ProxyServer_URL );								// Proxyサーバー設定ホスト名.
		pc_RoimWscDataIF->getProxySVR_UserName( m_sc_ProxyServer_UserName );					// Proxyサーバー設定ﾕｰｻﾞｰ名.
		pc_RoimWscDataIF->getProxySVR_Password( m_sc_ProxyServer_Password );					// Proxyサーバー設定ﾊﾟｽﾜｰﾄﾞ.
		pc_RoimWscDataIF->getProxySVR_PortNumber( &m_us_ProxyServer_PortNumber );				// Proxyサーバー設定ﾎﾟｰﾄ番号.

		m_bl_FromMenu = False;
	}
}
//================================================================================================.
// 概要		: PServiceROIMProxyServerSetCom : 遠隔サービス設定／Proxyサーバー設定_共通: メニューからの遷移フラグのセッター処理.
// 備考		: なし.
//================================================================================================.
void PServiceROIMProxyServerSetCom::setFromMenuFlg( Bool bl_FromMenu )
{
	m_bl_FromMenu = bl_FromMenu;
}

//================================================================================================.
// 概要		: PServiceROIMProxyServerSetCom : 遠隔サービス設定／Proxyサーバー設定_共通 : 画面更新処理.
// 備考		: なし.
//================================================================================================.
void PServiceROIMProxyServerSetCom::setupGamen( short option )
{
	// 親クラスを呼ぶ.
	PServiceNoFunctionCodeCom::setupGamen();

	switch( m_e_ROIMProxyServerGamen ) {
		case PNLE_ServiceROIMProxySettingGamen_UseSet:					// 使用設定.
			Rbt_ServiceROIMProxyServerSettingMenu.select( 0 );
			break;
		case PNLE_ServiceROIMProxySettingGamen_WebDAV:					// WebDAV連動.
			Rbt_ServiceROIMProxyServerSettingMenu.select( 1 );
			break;
		case PNLE_ServiceROIMProxySettingGamen_URL:						// Proxyサーバー設定 - ホスト名.
			Rbt_ServiceROIMProxyServerSettingMenu.select( 2 );
			Rbt_ServiceROIMProxyServerSetMenu.select( 0 );
			break;
		case  PNLE_ServiceROIMProxySettingGamen_UserName:				// Proxyサーバー設定 - ユーザー名.
			Rbt_ServiceROIMProxyServerSettingMenu.select( 2 );
			Rbt_ServiceROIMProxyServerSetMenu.select( 1 );
			break;
		case  PNLE_ServiceROIMProxySettingGamen_Password:				// Proxyサーバー設定 - パスワード.
			Rbt_ServiceROIMProxyServerSettingMenu.select( 2 );
			Rbt_ServiceROIMProxyServerSetMenu.select( 2 );
			break;
		case  PNLE_ServiceROIMProxySettingGamen_PortNum:				// Proxyサーバー設定 - ポート番号.
			Rbt_ServiceROIMProxyServerSettingMenu.select( 2 );
			Rbt_ServiceROIMProxyServerSetMenu.select( 3 );
			break;
		default: break;
	}
}

//================================================================================================.
// 概要		: PServiceROIMProxyServerSetCom : 遠隔サービス設定／Proxyサーバー設定_共通：インデックスボタン処理.
// 備考		: なし.
//================================================================================================.
void PServiceROIMProxyServerSetCom::procIndexButton( uchar option )
{
	switch( option ) {
		// 使用設定.
		case BTNID_ServiceROIMProxyServerUseSetting:
			m_e_ROIMProxyServerGamen = PNLE_ServiceROIMProxySettingGamen_UseSet;
			nextGamen = &gp_ServiceROIMProxyServerSetting;			// K4B0013100_遠隔サービス設定／Proxyサーバー設定.
			break;

		// WebDAV連動.
		case BTNID_ServiceROIMWebDAVSetting:
			m_e_ROIMProxyServerGamen = PNLE_ServiceROIMProxySettingGamen_WebDAV;
			nextGamen = &gp_ServiceROIMProxyServer_LinkWebDAVClient;// K4B0013200_遠隔サービス設定／Proxyサーバー設定／WebDAV連動.
			break;

		// Proxyｻｰﾊﾞ.
		case BTNID_ServiceROIMProxyServerSetting:
			m_e_ROIMProxyServerGamen = PNLE_ServiceROIMProxySettingGamen_URL;
			nextGamen = &gp_ServiceROIMProxyServer_URL;				// K4B0013300_遠隔サービス設定／Proxyサーバー設定／ホスト名.
			break;
		default:
			break;
	}
}

//================================================================================================.
// 概要		: PServiceROIMProxyServerSetCom : 遠隔サービス設定／Proxyサーバー設定_共通：画面遷移処理.
// 備考		: なし.
//================================================================================================.
void PServiceROIMProxyServerSetCom::procGoToPage( uchar option )
{
	switch( option ) {
		case BTNID_ServiceROIMProxyServer_URL:						// Proxyサーバー設定ホスト名.
			m_e_ROIMProxyServerGamen = PNLE_ServiceROIMProxySettingGamen_URL;
			nextGamen = &gp_ServiceROIMProxyServer_URL;
			break;

		case BTNID_ServiceROIMProxyServer_UserName:					// Proxyサーバー設定ユーザー名.
			m_e_ROIMProxyServerGamen = PNLE_ServiceROIMProxySettingGamen_UserName;
			nextGamen = &gp_ServiceROIMProxyServer_UserName;
			break;

		case BTNID_ServiceROIMProxyServer_Password:					// Proxyサーバー設定パスワード.
			m_e_ROIMProxyServerGamen = PNLE_ServiceROIMProxySettingGamen_Password;
			nextGamen = &gp_ServiceROIMProxyServer_Password;
			break;

		case BTNID_ServiceROIMProxyServer_PortNumber:				// Proxyサーバー設定ポート番号.
			m_e_ROIMProxyServerGamen = PNLE_ServiceROIMProxySettingGamen_PortNum;
			nextGamen = &gp_ServiceROIMProxyServer_PortNumber;
			break;

		default: break;
	}
}

//================================================================================================.
// 概要		: PServiceROIMProxyServerSetCom : 遠隔サービス設定／Proxyサーバー設定_共通 : Ok押下処理.
// 備考		: なし.
//================================================================================================.
void PServiceROIMProxyServerSetCom::procOk( uchar option )
{
// 2015/03/12 [MAv3][RQ-243] XMPPによるリアルタイム指示 日立 村上(幸).
	APIC_RoimWscDataIF *pc_RoimWscDataIF = NULL;
	pc_RoimWscDataIF = APIC_RoimWscDataIF::newInstance();
	if( NULL == pc_RoimWscDataIF ) {
// Comment 2015/11/02 【ZeusS_ZX0】【HCL_Vasu】【制御構成変更_No.76-1】Adding Error Code macro.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//		if (NULL !=pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x1900030100E56001 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}

// comment 2017/05/22 SCD2-Sky浜野 [IT5_4.1][1022641].
// プロキシ設定なしでWWサーバー接続の運用を可能とするため、未入力の受付禁止条件を削除.
//	// Proxyサーバー設定機能使用する、且つ、WebDAV連動機能連動しない、ホスト名またﾕｰｻﾞｰ名未入力時、画面遷移しない.
//	if( (True == m_bl_ROIMProxyOffOn) && (False == m_bl_ROIMWebDAVOffOn) &&
//	    ( ('\0' == m_sc_ProxyServer_URL[0]) || ('\0' == m_sc_ProxyServer_UserName[0]) ) ) {
//		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );	// ブザー音セット.
//		return;
//	}

	// CommonAPIに設定.
	pc_RoimWscDataIF->setProxySVR_Enable( m_bl_ROIMProxyOffOn );						// Proxyサーバー設定機能使用OFF/ON.
	pc_RoimWscDataIF->setProxySVR_LinkWebDAVClient( m_bl_ROIMWebDAVOffOn );				// WebDAV連動機能連動OFF/ON.
	pc_RoimWscDataIF->setProxySVR_URL( m_sc_ProxyServer_URL );							// Proxyサーバー設定ホスト名.
	pc_RoimWscDataIF->setProxySVR_UserName( m_sc_ProxyServer_UserName );				// Proxyサーバー設定ﾕｰｻﾞｰ名.
	pc_RoimWscDataIF->setProxySVR_Password( m_sc_ProxyServer_Password );				// Proxyサーバー設定ﾊﾟｽﾜｰﾄﾞ.
	pc_RoimWscDataIF->setProxySVR_PortNumber( m_us_ProxyServer_PortNumber );			// Proxyサーバー設定ﾎﾟｰﾄ番号.
	// データ変化を通知する.
	pc_RoimWscDataIF->changeParameter();
	
	// 画面遷移.
	nextGamen = &gp_ServiceROIMMenu;		// 「K4B0010000_ネットワーク設定／遠隔指サービス設定／メニュー」画面.
}
