//================================================================================================.
// 概要		: PServiceROIMProxyServerSetting : K4B0013100_遠隔サービス設定／Proxyサーバー設定 : 画面更新処理.
// 備考		: なし.
//================================================================================================.
void PServiceROIMProxyServerSetting::setupGamen( short option )
{
	// WebDAV連動とProxyｻｰﾊﾞｰキー表示/非表示設定.
	Key_ServiceROIMProxyServerWebDAVSet.showEnable( m_bl_ROIMProxyOffOn );
	if( False == m_bl_ROIMProxyOffOn ) {
		Key_ServiceROIMProxyServer.showEnable( False );
	}
	else {
		// WebDAV連動の選択値によって、Proxyｻｰﾊﾞｰキー表示/非表示設定.
		if( False == m_bl_ROIMWebDAVOffOn ) {
			Key_ServiceROIMProxyServer.showEnable( True );
		}
		else {
			Key_ServiceROIMProxyServer.showEnable( False );
		}
	}
	Rbt_ServiceROIMProxyServerUseSettingsSelect.select( True == m_bl_ROIMProxyOffOn ? 0 : 1 );	// 使用する/使用しない.
	// 親クラスを呼ぶ.
	// 「使用する」から「使用しない」になったときに左のメニューの表示を変える必要があるためここで行う。.
	PServiceROIMProxyServerSetCom::setupGamen( option );
}

//================================================================================================.
// 概要		: PServiceROIMProxyServerSetting : K4B0013100_遠隔サービス設定／Proxyサーバー設定 : 画面遷移処理.
// 備考		: なし.
//================================================================================================.
void PServiceROIMProxyServerSetting::procButtonOn( uchar option )
{
	// 親クラスを呼ぶ.
	PServiceROIMProxyServerSetCom::procButtonOn( option );

	switch( option ) {
		// 使用しない.
		case BTNID_ServiceROIMProxyServer_NotUse:	m_bl_ROIMProxyOffOn = False;	break;
		// 使用する.
		case BTNID_ServiceROIMProxyServer_Use:		m_bl_ROIMProxyOffOn = True;		break;
		default:	break;
	}
	setupGamen( option );
}

//================================================================================================.
// 概要		: PServiceROIMProxyServer_LinkWebDAVClient : K4B0013200_遠隔サービス設定／Proxyサーバー設定／WebDAV連動 : 画面更新処理.
// 備考		: なし.
//================================================================================================.
void PServiceROIMProxyServer_LinkWebDAVClient::setupGamen( short option )
{
	// WebDAV連動する場合、Proxyｻｰﾊﾞｰキー非表示.
	if( True == m_bl_ROIMWebDAVOffOn) {
		Key_ServiceROIMProxyServer.showEnable( False );
	}
	else {
		Key_ServiceROIMProxyServer.showEnable( True );
	}

	Rbt_ServiceROIMWebDAVSettingsSelect.select( True == m_bl_ROIMWebDAVOffOn ? 0 : 1 );	// 連動する/連動しない.
	// 親クラスを呼ぶ.
	// 「連動する」から「連動しない」になったときに左のメニューの表示を変える必要があるためここで行う.
	PServiceROIMProxyServerSetCom::setupGamen( option );
}

//================================================================================================.
// 概要		: PServiceROIMProxyServer_LinkWebDAVClient : K4B0013200_遠隔サービス設定／Proxyサーバー設定／WebDAV連動 : 画面遷移処理.
