{
	// 親クラスを呼ぶ.
	PServiceROIMProxyServerSetCom::procButtonOn( option );

	switch( option ) {
		// 連動しない.
		case BTNID_ServiceROIMWebDAV_Disable:	m_bl_ROIMWebDAVOffOn = False;	break;
		// 連動する.
		case BTNID_ServiceROIMWebDAV_Enable:	m_bl_ROIMWebDAVOffOn = True;	break;
		default:	break;
	}
	setupGamen( option );
}

