// 概要		: PServiceROIMProxyServer_PortNumber : K4B0013600_遠隔サービス設定／Proxyサーバー設定／ポート番号 : 画面遷移処理.
// 備考		: なし.
//================================================================================================.
void PServiceROIMProxyServer_PortNumber::procGoToPage( uchar option )
{
	// 範囲外の場合は画面遷移しない.
	if( m_us_ProxyServer_PortNumber < 1 || 65535 < m_us_ProxyServer_PortNumber ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );					// ブザー音セット.
		return;
	}

	// 親クラスを呼ぶ.
	PServiceROIMProxyServerSetCom::procGoToPage( option );
}

//================================================================================================.
// 概要		: PServiceROIMProxyServer_PortNumber : K4B0013600_遠隔サービス設定／Proxyサーバー設定／ポート番号 : インデックスボタン処理.
// 備考		: なし.
//================================================================================================.
void PServiceROIMProxyServer_PortNumber::procIndexButton( uchar option )
{
	// 範囲外の場合は画面遷移しない.
	if( m_us_ProxyServer_PortNumber < 1 || 65535 < m_us_ProxyServer_PortNumber ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );					// ブザー音セット.
		return;
	}

	// 親クラスを呼ぶ.
	PServiceROIMProxyServerSetCom::procIndexButton( option );
}

//================================================================================================.
// 概要		: PServiceROIMProxyServer_PortNumber : K4B0013600_遠隔サービス設定／Proxyサーバー設定／ポート番号  : テンキー .
// 備考		: なし.
//================================================================================================.
void PServiceROIMProxyServer_PortNumber::proc10Key( uchar option )
{
	Bool bl_isError = False;
	// ポート番号を更新する.
	m_us_ProxyServer_PortNumber = ( ushort )proc10KeyInput( m_us_ProxyServer_PortNumber, 65535, option, m_bl_Direct, EP_InputMaxLimitPattern_Refuse, &bl_isError );

	if( True == bl_isError ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );					// ブザー音セット.
	}
	else {
		if( True == m_bl_Direct && 1 > option ) {
			MCR_setBuzzerType( PCGE_BuzzerType_InputNg );				// ブザー音セット.
		}
		else {
			m_bl_Direct = False;
		}
	}
	setupGamen( option );												// 画面更新を行う.
}

//================================================================================================.
// 概要		: PServiceROIMProxyServer_PortNumber : K4B0013600_遠隔サービス設定／Proxyサーバー設定／ポート番号 : クリアキー .
// 備考		: なし.
//================================================================================================.
void PServiceROIMProxyServer_PortNumber::procClear( uchar option )
{
	m_us_ProxyServer_PortNumber = 0;													// ポート番号を0にする.
	m_bl_Direct = True;
	setupGamen( option );																// 画面更新を行う.
}
//================================================================================================.
// 概要		: PServiceROIMProxyServer_PortNumber : K4B0013600_遠隔サービス設定／Proxyサーバー設定／ポート番号 : OKキー .
// 備考		: なし.
//================================================================================================.
void PServiceROIMProxyServer_PortNumber::procOk( uchar option )
{
	if( m_us_ProxyServer_PortNumber < 1 || 65535 < m_us_ProxyServer_PortNumber ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );					// ブザー音セット.
		return;
	}

	PServiceROIMProxyServerSetCom::procOk( option );
}

