Bool PServiceROIMSetup::m_bl_SetupResult = False;							// 保守設定実行結果:失敗.
char PServiceROIMSetup::m_sc_ErrorCode[TYPD_Roim_ErrorCodeLen_Max] = {0};	// エラーコード.
void PServiceROIMSetup::ans_SetupEnd( TYPS_Roim_Result *pst_Result )
{
	m_bl_SetupResult = pst_Result->m_b_Result;
	strncpy(m_sc_ErrorCode, pst_Result->m_sc_ErrorCode, TYPD_Roim_ErrorCodeLen_Max - 1);
	CallBackIndi( TYPE_PNL_CallBack_ROIMSetupEnd );
}
//================================================================================================.
// 概要		: PServiceROIMSetup : K4B0015100_遠隔ｻｰﾋﾞｽ設定／保守設定 : コールバックイベント.
// 備考		: なし.
//================================================================================================.
void PServiceROIMSetup::procCallBack(TYPE_PNL_CallBack option )
{
	PServiceNoFunctionCodeCom::procCallBack( option );			// 必ず親を呼ぶ.

	switch( option ) {
		case TYPE_PNL_CallBack_ROIMSetupEnd:
			onlyPanel.bl_PowerOffOnMesage = False;
			if( True == m_bl_SetupResult ) {
				m_e_SetupStatus = PNLE_ServiceROIMSetupOK;		// 保守設定実行状態:正常終了.
			}
			else {
				m_e_SetupStatus = PNLE_ServiceROIMSetupNG;		// 保守設定実行状態:異常終了.
			}
			break;
		default:
			break;
	}
}
//================================================================================================.
// 概要		: PServiceROIMSetup : K4B0015100_遠隔ｻｰﾋﾞｽ設定／保守設定 : 画面開始処理.
// 備考		: なし.
//================================================================================================.
void PServiceROIMSetup::startGamen()
{
	APIC_RoimWscDataIF *pc_RoimWscDataIF = APIC_RoimWscDataIF::newInstance();

	if( NULL == pc_RoimWscDataIF ) {
// Comment 2015/11/02 【ZeusS_ZX0】【HCL_Vasu】【制御構成変更_No.76-1】Adding Error Code macro.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//		if (NULL !=pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x1900650100E56101 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}

	PServiceNoFunctionCodeCom::startGamen();						// 親クラスを呼ぶ.

	// メニューから呼ばれる場合はCommonAPIから全設定を読み込む.
	if( True == m_bl_FromMenu ) {
		m_us_ConfigCodeDigit = PNLD_ServiceROIMSetupConfigCode_0_DIGIT;
		m_bl_ExecStsToggle = False;										// 進行状態表示トグル.
		m_e_SetupStatus = PNLE_ServiceROIMSetupIdel;					// 保守設定実行状態:実行前.
		memset(m_sc_OperationName, 0x00, sizeof(m_sc_OperationName));	// オペレータ名は""が初期値.
		memset(m_sc_ConfigCode, '_', sizeof(m_sc_ConfigCode) - 1);		// Configコードは"________"が初期値.
		m_bl_FromMenu = False;
	}
}
//================================================================================================.
// 概要		: PServiceROIMSetup : K4B0015100_遠隔ｻｰﾋﾞｽ設定／保守設定 : 画面更新処理.
// 備考		: なし.
//================================================================================================.
void PServiceROIMSetup::setupGamen( short option )
{
	PServiceNoFunctionCodeCom::setupGamen( option );	// 親クラスを呼ぶ.

	// オペレータ名を表示.
	Btx_ServiceROIMSetupOperatorNameDisp.changeExternalText( (unsigned char*)m_sc_OperationName, sizeof( m_sc_OperationName ) );

	// 識別ｺｰﾄﾞを表示.
	Btx_ServiceROIMSetupConfigCode.changeExternalText( (unsigned char*)m_sc_ConfigCode, sizeof( m_sc_ConfigCode ) );

	ushort us_dispStatusMsg = s_Space1;					// 保守設定実行状態	(初期値：空白).
	ushort us_dispResultMsg = s_Space1;					// 保守設定実行結果	(初期値：空白).
	ushort us_dispProgMsg 	= s_Space1;					// 進行状態		(初期値：空白).
	char sc_ErrorCode[TYPD_Roim_ErrorCodeLen_Max];		// エラーコード	(初期値：空白).
	memset(sc_ErrorCode, 0x00, sizeof(sc_ErrorCode));

	Bool bl_showResultBox	= False;					// 結果表示枠/矢印/実行状態 表示フラグ(初期値：非表示).
	Bool bl_showResult		= False;					// 実行結果 表示フラグ(初期値：非表示).
	Bool bl_showProg		= False;					// 進行状態アイコン 表示フラグ(初期値：非表示).
	Bool bl_showErrCode		= False;					// エラーコード 表示フラグ(初期値：非表示).

	// 保守設定実行状態によって、表示部品をセットアップ.
	switch( m_e_SetupStatus ) {
		case PNLE_ServiceROIMSetupIdel:						// 実行前.
			Key_ServiceROIMSetupStart.select(False);		// 「スタート」キー非選択.
			break;

		case PNLE_ServiceROIMSetupProc:						// 実行中.
			Key_ServiceROIMSetupStart.select(True);			// 「スタート」キー選択.
			bl_showResultBox = True;						// 結果表示枠/矢印/実行状態表示.
			bl_showProg = True;								// 進行状態アイコン表示.
			us_dispStatusMsg = s_ITMServiceOperating;		// 「実行中」.
			// 進行状態表示トグルに応じて表示更新.
			if( True == m_bl_ExecStsToggle ) {
				us_dispProgMsg = s_EXPSlash;				// 「／」.
				m_bl_ExecStsToggle = False;
			}
			else {
				us_dispProgMsg = s_EXPBackslash;			// 「＼」.
				m_bl_ExecStsToggle = True;
			}
			break;

		case PNLE_ServiceROIMSetupOK:						// 正常終了.
			Key_ServiceROIMSetupStart.select(False);		// 「スタート」キー非選択.
			bl_showResultBox = True;						// 結果表示枠/矢印/実行状態表示.
			bl_showResult = True;							// 実行結果表示.
			us_dispStatusMsg = s_SetFaxResult;				// 「結果」.
			us_dispResultMsg = s_ServiceResultOK;			// 「OK」.
			break;

		case PNLE_ServiceROIMSetupNG:						// 異常終了.
			Key_ServiceROIMSetupStart.select(False);		// 「スタート」キー非選択.
			bl_showResultBox = True;						// 結果表示枠/矢印/実行状態表示.
			bl_showResult = True;							// 実行結果表示.
			bl_showErrCode = True;							// エラーコード表示.
			us_dispStatusMsg = s_SetFaxResult;				// 「結果」.
			us_dispResultMsg = s_ServiceResultNG;			// 「NG」.
			strncpy(sc_ErrorCode, m_sc_ErrorCode, TYPD_Roim_ErrorCodeLen_Max - 1);	// 「エラーコード」.
			break;

		default:
			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
			break;
	}

	// 文字列更新.
	Txt_ServiceROIMSetupStatus.changeText( us_dispStatusMsg );			// 実行状態表示更新.
	Txt_ServiceROIMSetupResult.changeText( us_dispResultMsg );			// 実施結果表示更新.
	Txt_ServiceROIMSetupProgress.changeText( us_dispProgMsg );			// 進行状態アイコン表示更新.
	Tfd_ServiceROIMSetupErrorCodeVal.changeExternalText( (unsigned char*)sc_ErrorCode, sizeof( sc_ErrorCode ) );	// エラーコード表示更新.

	// 実行結果表示/非表示
// comment 2015.09.11 [CQ518316] 矢印と結果表示枠は常時表示する 日立 田中.
//	Txt_ServiceROIMSetupResultArrow.showEnable( bl_showResultBox );		// 矢印表示/非表示.
//	Gra_ServiceROIMSetupResult.showEnable( bl_showResultBox );			// 結果表示枠表示/非表示.
	Txt_ServiceROIMSetupStatus.showEnable( bl_showResultBox );			// 進実施状態メッセージ表示/非表示.
	Txt_ServiceROIMSetupResult.showEnable( bl_showResult );				// 実施結果表示/非表示.
	Txt_ServiceROIMSetupProgress.showEnable( bl_showProg );				// 進行状態アイコン表示/非表示.
	Txt_ServiceROIMSetupErrorCode.showEnable( bl_showErrCode );			// エラーコードタイトル表示/非表示.
	Tfd_ServiceROIMSetupErrorCodeVal.showEnable( bl_showErrCode );		// エラーコード表示/非表示.
}
//================================================================================================.
// 概要		: PServiceROIMSetup : K4B0015100_遠隔ｻｰﾋﾞｽ設定／保守設定 : ボタン押下.
// 備考		: なし.
//================================================================================================.
void PServiceROIMSetup::procButtonOn( uchar option )
{
	// 入力した識別ｺｰﾄﾞが範囲外の場合、ブザー音を鳴動.
	if( PNLD_ServiceROIMSetupConfigCode_8_DIGIT != m_us_ConfigCodeDigit ) {
		setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}

	// セットアップ実行中の場合は受付拒否.
	if( PNLE_ServiceROIMSetupProc == m_e_SetupStatus ) {
		setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}

	APIC_Roim* pc_Roim = APIC_Roim::newInstance();
	APIC_RoimWscDataIF *pc_RoimWscDataIF = APIC_RoimWscDataIF::newInstance();

	if( ( NULL == pc_Roim) || ( NULL == pc_RoimWscDataIF ) ) {
// Comment 2015/11/02 【ZeusS_ZX0】【HCL_Vasu】【制御構成変更_No.76-1】Adding Error Code macro.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//		if (NULL !=pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19000A0100E56201 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}

	switch( option ) {
		// スタートキー.
		case BTNID_ServiceROIMSetupStart:
			onlyPanel.bl_PowerOffOnMesage = True;						// 主電源OFF/ON画面から遷移させないためのフラグ.
			turnGamen = NULL;
			m_e_SetupStatus = PNLE_ServiceROIMSetupProc;				// 保守設定実行状態:実行中.
			pc_RoimWscDataIF->setConfigCode(m_sc_ConfigCode);			// 識別ｺｰﾄﾞをCommonAPIに設定.
			pc_RoimWscDataIF->setOperationName( m_sc_OperationName );	// オペレータ名をCommonAPIに設定.
			pc_Roim->SetupRequest( ans_SetupEnd );						// パネルからのセットアップ要求を開始する.
			break;
		default: 
			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
			break;
	}
	// 画面更新.
	setupGamen( option );
}
