// 概要		: PServiceROIMSetup : K4B0015100_遠隔ｻｰﾋﾞｽ設定／保守設定 : テンキー .
// 備考		: なし.
//================================================================================================.
void PServiceROIMSetup::proc10Key( uchar option )
{
	// セットアップ実行中の場合は受付拒否.
	if( PNLE_ServiceROIMSetupProc == m_e_SetupStatus ) {
		setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}

	if( PNLD_ServiceROIMSetupConfigCode_8_DIGIT != m_us_ConfigCodeDigit ) {
		m_sc_ConfigCode[m_us_ConfigCodeDigit] = (char)(option + '0');
		m_us_ConfigCodeDigit++;
	}
	else {
		setBuzzerType( PCGE_BuzzerType_InputNg );
	}
}
