void PServiceXMPPServerSettingCom::startGamen()
{
	APIC_RoimWscDataIF *pc_RoimWscDataIF = NULL;
	pc_RoimWscDataIF = APIC_RoimWscDataIF::newInstance();

	if( NULL == pc_RoimWscDataIF ) {
// Comment 2015/11/02 【ZeusS_ZX0】【HCL_Vasu】【制御構成変更_No.76-1】Adding Error Code macro.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//		if (NULL !=pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x1900650100E56301 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}

	// 親クラスを呼ぶ.
	PServiceNoFunctionCodeCom::startGamen();

	// メニューから呼ばれる場合はCommonAPIから全設定を読み込む。.
	if( True == m_bl_FromMenu ) {
		// 表示中画面のIndexを初期化する.
		m_e_XMPPServerSettingGamen = PNLE_ServiceXMPPServerSettingGamen_FunctionSet;
		// commonAPIから取得.
		pc_RoimWscDataIF->getXMPPIndicateEnable( &m_bl_XMPPServerSettingOffOn );				// XMPP機能設定使用OFF/ON.
		pc_RoimWscDataIF->getXMPPServer_RetryCycle( &m_uc_ConnectServer_RetryCycle );			// 接続先サーバ設定ﾘﾄﾗｲ間隔.
		pc_RoimWscDataIF->getXMPPServer_Timeout( &m_us_ConnectServer_Timeout );					// 接続先サーバ設定接続ﾀｲﾑｱｳﾄ.
		pc_RoimWscDataIF->getXMPPServer_SSL( &m_bl_ConnectServer_SSL );							// 接続先サーバ設定SSL.
		pc_RoimWscDataIF->getXMPPServer_BOSH( &m_bl_ConnectServer_BOSH );						// 接続先サーバ設定BOSH.

		m_bl_FromMenu = False;
	}
}

//================================================================================================.
// 概要		: PServiceXMPPServerSettingCom : 遠隔ｻｰﾋﾞｽ設定／XMPP機能設定_共通:画面更新処理.
// 備考		: なし.
//================================================================================================.
void PServiceXMPPServerSettingCom::setupGamen( short option )
{
	// 親クラスを呼ぶ.
	PServiceNoFunctionCodeCom::setupGamen();

	switch( m_e_XMPPServerSettingGamen ) {
		case PNLE_ServiceXMPPServerSettingGamen_FunctionSet:		// 機能設定.
			Rbt_ServiceXMPPServerSettingMenu.select( 0 );
			break;
		case  PNLE_ServiceXMPPServerSettingGamen_RetryCycle:		// 接続設定 - ﾘﾄﾗｲ間隔.
			Rbt_ServiceXMPPServerSettingMenu.select( 1 );
			Rbt_ServiceXMPPConnectServerSetMenu.select( 0 );
			break;
		case  PNLE_ServiceXMPPServerSettingGamen_TimeOut:			// 接続設定 - 接続ﾀｲﾑｱｳﾄ.
			Rbt_ServiceXMPPServerSettingMenu.select( 1 );
			Rbt_ServiceXMPPConnectServerSetMenu.select( 1 );
			break;
		case  PNLE_ServiceXMPPServerSettingGamen_SSL:				// 接続設定 - SSL.
			Rbt_ServiceXMPPServerSettingMenu.select( 1 );
			Rbt_ServiceXMPPConnectServerSetMenu.select( 2 );
			break;
		case  PNLE_ServiceXMPPServerSettingGamen_BOSH:				// 接続設定 - BOSH.
			Rbt_ServiceXMPPServerSettingMenu.select( 1 );
			Rbt_ServiceXMPPConnectServerSetMenu.select( 3 );
			break;
		case PNLE_ServiceXMPPServerSettingGamen_ConnectServerInfo:	// 接続情報.
			Rbt_ServiceXMPPServerSettingMenu.select( 2 );
			break;
		default: break;
	}
}

//================================================================================================.
// 概要		: PServiceXMPPServerSettingCom : 遠隔ｻｰﾋﾞｽ設定／XMPP機能設定_共通:インデックスボタン処理.
// 備考		: なし.
//================================================================================================.
void PServiceXMPPServerSettingCom::procIndexButton( uchar option )
{
	switch( option ) {
		// 機能設定.
		case BTNID_ServiceXMPPServerSettingFunctionSet:
			m_e_XMPPServerSettingGamen = PNLE_ServiceXMPPServerSettingGamen_FunctionSet;
			nextGamen = &gp_ServiceXMPPServerSetting;				// K4B0012000_遠隔ｻｰﾋﾞｽ設定／XMPP機能設定.
			break;
		// 接続設定.
		case BTNID_ServiceXMPPServerSettingConnectServerSet:
			m_e_XMPPServerSettingGamen = PNLE_ServiceXMPPServerSettingGamen_RetryCycle;
			nextGamen = &gp_ServiceXMPPServerSetting_RetryCycle;	// K4B0012100_遠隔ｻｰﾋﾞｽ設定／XMPP機能設定／接続設定／ﾘﾄﾗｲ間隔.
			break;
		// 接続情報.
		case BTNID_ServiceXMPPServerSettingConnectServerInfo:
			m_e_XMPPServerSettingGamen = PNLE_ServiceXMPPServerSettingGamen_ConnectServerInfo;
			nextGamen = &gp_ServiceXMPPServerSetting_ConnectInfo;	// K4B0012500_遠隔ｻｰﾋﾞｽ設定／XMPP機能設定／接続情報1.
			break;
		default:
			break;
	}
}

