// 備考		: なし.
//================================================================================================.
void PServiceXMPPServerSettingCom::procGoToPage( uchar option )
{
	switch( option ) {
		case BTNID_ServiceXMPPServerSetting_RetryCycle:			// 接続設定-ﾘﾄﾗｲ間隔.
			m_e_XMPPServerSettingGamen = PNLE_ServiceXMPPServerSettingGamen_RetryCycle;
			nextGamen = &gp_ServiceXMPPServerSetting_RetryCycle;
			break;

		case BTNID_ServiceXMPPServerSetting_Timeout:			// 接続設定-接続タイムアウト.
			m_e_XMPPServerSettingGamen = PNLE_ServiceXMPPServerSettingGamen_TimeOut;
			nextGamen = &gp_ServiceXMPPServerSetting_Timeout;
			break;

		case BTNID_ServiceXMPPServerSetting_SSL:				// 接続設定-SSL.
			m_e_XMPPServerSettingGamen = PNLE_ServiceXMPPServerSettingGamen_SSL;
			nextGamen = &gp_ServiceXMPPServerSetting_SSL;
			break;

		case BTNID_ServiceXMPPServerSetting_BOSH:				// 接続設定-BOSH.
			m_e_XMPPServerSettingGamen = PNLE_ServiceXMPPServerSettingGamen_BOSH;
			nextGamen = &gp_ServiceXMPPServerSetting_BOSH;
			break;

		default: break;
	}
}

