void PServiceXMPPServerSetting_SSL::procButtonOn( uchar option )
{
	// 親クラスを呼ぶ.
	PServiceXMPPServerSettingCom::procButtonOn( option );

	switch( option ) {
		// OFF.
		case BTNID_ServiceXMPPServerSetting_SSLDisable:	m_bl_ConnectServer_SSL = False;	break;	// 選択中を「OFF」にする.
		// ON.
		case BTNID_ServiceXMPPServerSetting_SSLEnable:	m_bl_ConnectServer_SSL = True;	break;	// 選択中を「ON」にする.
		default:break;
	}
	setupGamen( option );
}

