//================================================================================================.
// 概要		: PServiceXMPPServerSetting_ConnectInfo : K0B0012500_MAv3_遠隔ｻｰﾋﾞｽ設定／XMPP機能設定／接続情報 共通 : 画面遷移処理 .
// 備考		: なし.
//================================================================================================.
void PServiceXMPPServerSetting_ConnectInfoCom::procGoToPage( uchar option )
{
	switch( option ){
		case BTNID_ServiceXMPPConnectInfoPageUp:												// ↑キー
			m_ss_NowPage--;
			if( m_ss_NowPage < 1 ) {
				m_ss_NowPage = 2;
			}
			break;
		case BTNID_ServiceXMPPConnectInfoPageDown:												// ↓キー
			m_ss_NowPage++;
			if( m_ss_NowPage > 2 ) {
				m_ss_NowPage = 1;
			}
			break;
	}
	switch( m_ss_NowPage ){
		case 1: nextGamen = &gp_ServiceXMPPServerSetting_ConnectInfo; break;	// 接続情報1.
		case 2: nextGamen = &gp_ServiceXMPPServerSetting_ConnectInfo2; break;	// 接続情報2.
		default:break;
	}
}

