{
	APIC_RoimWscDataIF *pc_RoimWscDataIF = NULL;
	pc_RoimWscDataIF = APIC_RoimWscDataIF::newInstance();

	if( NULL == pc_RoimWscDataIF ) {
// Comment 2015/11/02 【ZeusS_ZX0】【HCL_Vasu】【制御構成変更_No.76-1】Adding Error Code macro.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//		if (NULL !=pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x1900660100E56501 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}

	char sc_LocalURL[TYPD_RoimWscDataIF_XMPPServer_URLMaxLen+6];		// URL.
	char sc_LocalID[TYPD_RoimWscDataIF_XMPPServer_LoginIDMaxLen+2];		// ID.
	TYPS_RoimWscDataIF_XMPPServerInfo	st_XMPPServerInfo;				// 接続情報.
	memset( sc_LocalURL, 0x00, sizeof( sc_LocalURL ) );
	memset( sc_LocalID, 0x00, sizeof( sc_LocalID ) );
	memset( &st_XMPPServerInfo , 0x00, sizeof( st_XMPPServerInfo ) );

	// 親クラスを呼ぶ.
	PServiceXMPPServerSetting_ConnectInfoCom::setupGamen( option );


	pc_RoimWscDataIF->getXMPPServerInfo( &st_XMPPServerInfo );		// 接続情報内容を取得する.
	// 接続情報内容の表示.
	setupInputString( 6 , 44 ,(char *)st_XMPPServerInfo.m_sc_URL, (char *)sc_LocalURL );
	Tfd_ServiceXMPPConnectServerInfoURL.changeExternalText( (uchar*)sc_LocalURL, (short)strlen(sc_LocalURL) );					// URL表示.
	setupInputString( 2 , 44 ,(char *)st_XMPPServerInfo.m_sc_LoginID, (char *)sc_LocalID );
	Tfd_ServiceXMPPConnectServerInfoID.changeExternalText( (uchar*)sc_LocalID, (short)strlen(sc_LocalID) );					// ID表示.
}
