void PServiceXMPPServerSetting_ConnectInfo2::setupGamen( short option )
{
	APIC_RoimWscDataIF *pc_RoimWscDataIF = NULL;
	pc_RoimWscDataIF = APIC_RoimWscDataIF::newInstance();

	if( NULL == pc_RoimWscDataIF ) {
// Comment 2015/11/02 【ZeusS_ZX0】【HCL_Vasu】【制御構成変更_No.76-1】Adding Error Code macro.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//		if (NULL !=pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x1900660100E56601 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}

	Bool bl_XMPPServerSettingOffOn;																// XMPP機能設定使用OFF/ON.
	char sc_LocalDomainName[TYPD_RoimWscDataIF_XMPPServer_DomainMaxLen+6];						// ﾄﾞﾒｲﾝ名.
	char sc_ErrorCode[TYPD_RoimWscDataIF_XMPPSessionDetailMaxLen];								// 接続結果(ｴﾗｰｺｰﾄﾞ).
	TYPS_RoimWscDataIF_XMPPServerInfo	st_XMPPServerInfo;										// 接続情報.
	TYPE_RoimWscDataIF_XMPPSessionStatus	e_XMPPSessionStatus = TYPE_RoimWscDataIF_XMPPSessionStatus_Disconnect;	// 接続状態.
	memset( sc_LocalDomainName, 0x00, sizeof( sc_LocalDomainName ) );
	memset( sc_ErrorCode, 0x00, sizeof( sc_ErrorCode ) );
	memset( &st_XMPPServerInfo , 0x00, sizeof( st_XMPPServerInfo ) );

	// 親クラスを呼ぶ.
	PServiceXMPPServerSetting_ConnectInfoCom::setupGamen( option );

	pc_RoimWscDataIF->getXMPPServerInfo( &st_XMPPServerInfo );		// 接続情報内容を取得する.
	// 接続情報内容の表示.
	setupInputString( 6 , 44 ,(char *)st_XMPPServerInfo.m_sc_Domain, (char *)sc_LocalDomainName );
	Tfd_ServiceXMPPConnectServerInfoDomainName.changeExternalText( (uchar*)sc_LocalDomainName, (short)strlen(sc_LocalDomainName) );	// ﾄﾞﾒｲﾝ名表示.
	if ( 0 < st_XMPPServerInfo.m_us_PortNo ) {
		Nfd_ServiceXMPPConnectServerInfoPortNumber = st_XMPPServerInfo.m_us_PortNo;												// ﾎﾟｰﾄ番号表示.
		Nfd_ServiceXMPPConnectServerInfoPortNumber.showEnable( True );															// ﾎﾟｰﾄ番号表示領域・表示.
	}
	else {
		Nfd_ServiceXMPPConnectServerInfoPortNumber.showEnable( False );															// ﾎﾟｰﾄ番号表示領域・表示.
	}
	pc_RoimWscDataIF->getXMPPIndicateEnable( &bl_XMPPServerSettingOffOn );														// XMPP機能設定使用OFF/ON.
// comment 2015/11/6 [CQ519927] XMPP接続状態の表示する文字列を変更する対応 日立 村上(幸).
//	if ( True == bl_XMPPServerSettingOffOn ) {
//		// 接続状態.
//		pc_RoimWscDataIF->getSessionStatus( &e_XMPPSessionStatus, sc_ErrorCode);
//		switch( e_XMPPSessionStatus ) {
//			// 未接続.
//			case TYPE_RoimWscDataIF_XMPPSessionStatus_Disconnect:	Tfd_ServiceXMPPConnectServerStatus.changeText( s_ITMWirelessHandsetConnectFailed_2 );	break;	// 接続失敗表示.
//			// 接続中.
//			case TYPE_RoimWscDataIF_XMPPSessionStatus_Connecting:	Tfd_ServiceXMPPConnectServerStatus.changeText( s_ITMWirelessHandsetConnecting_2 );		break;	// 接続中表示.
//			// 接続完了.
//			case TYPE_RoimWscDataIF_XMPPSessionStatus_Connect:		Tfd_ServiceXMPPConnectServerStatus.changeText( s_ITMServiceXMPPConnectSuccess );		break;	// 接続成功表示.
//			default:break;
//		}
//		// 接続完了以外の状態でエラーコードが格納されている場合は、エラーコード表示を行う.
//		if( ((TYPE_RoimWscDataIF_XMPPSessionStatus_Disconnect == e_XMPPSessionStatus)
//		 || (TYPE_RoimWscDataIF_XMPPSessionStatus_Connecting == e_XMPPSessionStatus))
//		  && (0 < strlen(sc_ErrorCode))) {
//			Tfd_ServiceXMPPConnectServerStatus.changeText( s_ITMWirelessHandsetConnectFailed_2 );	// 接続失敗表示.
//			Txt_ServiceXMPPConnectServerErrorCode.showEnable( True );								// 「ｴﾗｰｺｰﾄﾞ」・表示.
//			Tfd_ServiceXMPPConnectServerErrorCode.showEnable( True );								// ｴﾗｰｺｰﾄﾞ表示領域・表示.
//			Gra_ServiceXMPPConnectInfoLine_ErrorCode.showEnable( True );							// ｴﾗｰｺｰﾄﾞのライン・表示.
//			Tfd_ServiceXMPPConnectServerErrorCode.changeExternalText( (uchar*)sc_ErrorCode, strlen(sc_ErrorCode) );
//		}
//		else {
//			Txt_ServiceXMPPConnectServerErrorCode.showEnable( False );						// 「ｴﾗｰｺｰﾄﾞ」・非表示.
//			Tfd_ServiceXMPPConnectServerErrorCode.showEnable( False );						// ｴﾗｰｺｰﾄﾞ表示領域・非表示.
//			Gra_ServiceXMPPConnectInfoLine_ErrorCode.showEnable( False );					// ｴﾗｰｺｰﾄﾞのライン・非表示.
//		}
//	}
//	else {
//		Tfd_ServiceXMPPConnectServerStatus.changeText( s_ITMWirelessHandsetUnConnect_2 );	// 未接続表示.
//		Txt_ServiceXMPPConnectServerErrorCode.showEnable( False );							// 「ｴﾗｰｺｰﾄﾞ」・非表示.
//		Tfd_ServiceXMPPConnectServerErrorCode.showEnable( False );							// ｴﾗｰｺｰﾄﾞ表示領域・非表示.
//		Gra_ServiceXMPPConnectInfoLine_ErrorCode.showEnable( False );						// ｴﾗｰｺｰﾄﾞのライン・非表示.
//	}
	pc_RoimWscDataIF->getSessionStatus( &e_XMPPSessionStatus, sc_ErrorCode);
	switch( e_XMPPSessionStatus ) {
		case TYPE_RoimWscDataIF_XMPPSessionStatus_Disconnect:			// 未使用または未接続.
			// XMPPサーバーを使用しない場合は未接続を表示.
			// または未接続(ROIMからのキック待ち。XMPPサーバーは接続準備状態)は未接続を表示.
			Tfd_ServiceXMPPConnectServerStatus.changeText( s_ITMWirelessHandsetUnConnect_2 );				// 未接続表示.
			break;
		case TYPE_RoimWscDataIF_XMPPSessionStatus_GetServerInfo:		// 情報取得中.
			// 情報取得中(XMPPサーバーが必要な情報を取得している状態)は情報取得中を表示.
			Tfd_ServiceXMPPConnectServerStatus.changeText( s_ITMServiceRetrieving );						// 情報取得中表示.
			break;
		case TYPE_RoimWscDataIF_XMPPSessionStatus_Connectting:			// 接続中.
			// 接続中(接続の処理を実施している状態).
			Tfd_ServiceXMPPConnectServerStatus.changeText( s_ITMWirelessHandsetConnecting_2 );				// 接続中表示.
			break;
		case TYPE_RoimWscDataIF_XMPPSessionStatus_Connect:				// 接続.
			// 接続(XMPPサーバーとの接続が実施されている状態).
			Tfd_ServiceXMPPConnectServerStatus.changeText( s_ITMWirelessHandsetConnect_2 );					// 接続表示.
			break;
		default: break;
	}
	// エラーが発生している場合は必ず表示.
	if( 0 < strlen(sc_ErrorCode ) ) {							// エラーがある場合.
		Txt_ServiceXMPPConnectServerErrorCode.showEnable( True );						// 「ｴﾗｰｺｰﾄﾞ」・表示.
		Tfd_ServiceXMPPConnectServerErrorCode.showEnable( True );						// ｴﾗｰｺｰﾄﾞ表示領域・表示.
		Gra_ServiceXMPPConnectInfoLine_ErrorCode.showEnable( True );					// ｴﾗｰｺｰﾄﾞのライン・表示.
		Tfd_ServiceXMPPConnectServerErrorCode.changeExternalText( (uchar*)sc_ErrorCode, (short)strlen(sc_ErrorCode) );
	} else {
		Txt_ServiceXMPPConnectServerErrorCode.showEnable( False );						// 「ｴﾗｰｺｰﾄﾞ」・非表示.
		Tfd_ServiceXMPPConnectServerErrorCode.showEnable( False );						// ｴﾗｰｺｰﾄﾞ表示領域・非表示.
		Gra_ServiceXMPPConnectInfoLine_ErrorCode.showEnable( False );					// ｴﾗｰｺｰﾄﾞのライン・非表示.
	}
}

