//================================================================================================.
void PServiceXMPPKeepAliveSettingCom::setupGamen( short option )
{
	// 親クラスを呼ぶ.
	PServiceNoFunctionCodeCom::setupGamen();

	switch( m_e_XMPPKeepAliveSettingGamen ) {
		// メンテナンス時間帯.
		case PNLE_ServiceXMPPKeepAliveSetting_MaintenanceTime:		Rbt_ServiceXMPPKeepAliveSettingsMenu.select( 0 );	break;
		// 生存通知間隔.
		case PNLE_ServiceXMPPKeepAliveSetting_NotifyCycle:			Rbt_ServiceXMPPKeepAliveSettingsMenu.select( 1 );	break;
		// 学習機能.
		case PNLE_ServiceXMPPKeepAliveSetting_LeaningFunction:		Rbt_ServiceXMPPKeepAliveSettingsMenu.select( 2 );	break;
		default: break;
	}
}

