void PServiceXMPPMaintenanceTime::procButtonOn( uchar option )
{
	// 親クラスを呼ぶ.
	PServiceXMPPKeepAliveSettingCom::procButtonOn( option );

	switch( option ) {
		//ﾊﾟﾜｰｾｰﾌﾞ設定に従う．
		case BTNID_ServiceXMPPPowerSavingModeSetting_MFPSetting:		m_st_XMPPKeepAliveSetting.m_e_DeepSleepChangeMode = TYPE_RoimWscDataIF_DeepSleepChangeMode_MFPSetting;		break;	// 選択中を「本体設定に従う」にする.
		//個別設定.
		case BTNID_ServiceXMPPPowerSavingModeSetting_MaintenanceTime:	m_st_XMPPKeepAliveSetting.m_e_DeepSleepChangeMode = TYPE_RoimWscDataIF_DeepSleepChangeMode_Schedule;		break;	// 選択中を「ﾒﾝﾃﾅﾝｽ時間帯に従う」にする.
		// 常時接続.
		case BTNID_ServiceXMPPPowerSavingModeSetting_AlwaysConnect:		m_st_XMPPKeepAliveSetting.m_e_DeepSleepChangeMode = TYPE_RoimWscDataIF_DeepSleepChangeMode_AlwaysConnect;	break;	// 選択中を「常時接続を維持する」にする.
		
		default:break;
	}
	setupGamen( option );
}

