//================================================================================================.
// 概要		: PServiceXMPPMaintenanceTime : K0B0014100_MAv3_遠隔ｻｰﾋﾞｽ設定／常時接続設定／メンテナンス時間帯 : OKキー押下処理.
// 備考		: なし.
//================================================================================================.
void PServiceXMPPMaintenanceTime::procOk( uchar option )
{
	ushort us_TimeZoneSettingCount = 0;
	for( ushort i = 0; i < TYPD_RoimWscDataIF_NoChangeDecisionTimeListCount; i++ ) {
		if( False == m_st_XMPPKeepAliveSetting.m_s_NoChangeDecisionTime[i].m_b_Enable ) {
			us_TimeZoneSettingCount++;
		}
	}

	if( ( TYPE_RoimWscDataIF_DeepSleepChangeMode_Schedule == m_st_XMPPKeepAliveSetting.m_e_DeepSleepChangeMode ) 
		&& ( us_TimeZoneSettingCount == TYPD_RoimWscDataIF_NoChangeDecisionTimeListCount ) ) {
		setBuzzerType( PCGE_BuzzerType_InputNg );											// ブザー音セット.
		return;
	}
	// 親クラスを呼ぶ.
	PServiceXMPPKeepAliveSettingCom::procOk( option );
}
