//================================================================================================.
// 概要		: PServiceXMPPMaintenanceTimeZoneSetting : 画面開始処理 .
//				K4B0014110_遠隔ｻｰﾋﾞｽ設定／常時接続設定／メンテナンス時間帯/時間帯設定1.
//				K4B0014120_遠隔ｻｰﾋﾞｽ設定／常時接続設定／メンテナンス時間帯/時間帯設定2.
//				K4B0014130_遠隔ｻｰﾋﾞｽ設定／常時接続設定／メンテナンス時間帯/時間帯設定3.
//				K4B0014140_遠隔ｻｰﾋﾞｽ設定／常時接続設定／メンテナンス時間帯/時間帯設定4.
// 備考		: なし.
//================================================================================================.
void PServiceXMPPMaintenanceTimeZoneSetting::startGamen()
{
	// 親クラスを呼ぶ.
	PServiceXMPPKeepAliveSettingCom::startGamen();	
	
	m_ss_StartHourInputDigit	= PNLD_ServiceXMPPMaintenanceTime_2_DIGIT;
	m_ss_StartMinuteInputDigit	= PNLD_ServiceXMPPMaintenanceTime_2_DIGIT;
	m_ss_EndHourInputDigit		= PNLD_ServiceXMPPMaintenanceTime_2_DIGIT;
	m_ss_EndMinuteInputDigit	= PNLD_ServiceXMPPMaintenanceTime_2_DIGIT;
	m_uc_TimeSelect				= PNLE_ServiceXMPPMaintenanceTime_StartHour;

	// 共通クラスメンバー変数から時刻を取得.
	m_uc_StartHour				=	m_st_XMPPKeepAliveSetting.m_s_NoChangeDecisionTime[m_e_XMPPMaintenanceTimeNum].m_c_StartTime.sc_Hour;
	m_uc_StartMinute			=	m_st_XMPPKeepAliveSetting.m_s_NoChangeDecisionTime[m_e_XMPPMaintenanceTimeNum].m_c_StartTime.sc_Minute;
	m_uc_EndHour				=	m_st_XMPPKeepAliveSetting.m_s_NoChangeDecisionTime[m_e_XMPPMaintenanceTimeNum].m_c_EndTime.sc_Hour;
	m_uc_EndMinute				=	m_st_XMPPKeepAliveSetting.m_s_NoChangeDecisionTime[m_e_XMPPMaintenanceTimeNum].m_c_EndTime.sc_Minute;
	m_bl_MaintenanceTimeEnable	=	m_st_XMPPKeepAliveSetting.m_s_NoChangeDecisionTime[m_e_XMPPMaintenanceTimeNum].m_b_Enable;
}
//================================================================================================.
// 概要		: PServiceXMPPMaintenanceTimeZoneSetting : 画面更新処理 .
//				K4B0014110_遠隔ｻｰﾋﾞｽ設定／常時接続設定／メンテナンス時間帯/時間帯設定1.
//				K4B0014120_遠隔ｻｰﾋﾞｽ設定／常時接続設定／メンテナンス時間帯/時間帯設定2.
//				K4B0014130_遠隔ｻｰﾋﾞｽ設定／常時接続設定／メンテナンス時間帯/時間帯設定3.
//				K4B0014140_遠隔ｻｰﾋﾞｽ設定／常時接続設定／メンテナンス時間帯/時間帯設定4.
// 備考		: なし.
//================================================================================================.
void PServiceXMPPMaintenanceTimeZoneSetting::setupGamen( short option )
{
	// 親クラスを呼ぶ.
	PServiceXMPPKeepAliveSettingCom::setupGamen( option );

	// タイトルの表示.
	switch( m_e_XMPPMaintenanceTimeNum ) {
		// 時間帯設定1.
		case PNLE_ServiceXMPPTimeZoneSetting_1:
			Txt_TitleServiceXMPPMaintenanceTimeZoneSet.changeText( s_KEY_ServiceXMPPTimeZoneSetting1 );		// 「時間帯設定1表示.
			break;
		// 時間帯設定2.
		case PNLE_ServiceXMPPTimeZoneSetting_2:
			Txt_TitleServiceXMPPMaintenanceTimeZoneSet.changeText( s_KEY_ServiceXMPPTimeZoneSetting2 );		// 「時間帯設定2」表示.
			break;
		// 時間帯設定2.
		case PNLE_ServiceXMPPTimeZoneSetting_3:
			Txt_TitleServiceXMPPMaintenanceTimeZoneSet.changeText( s_KEY_ServiceXMPPTimeZoneSetting3 );		// 「時間帯設定3」表示.
			break;
		// 時間帯設定4.
		case PNLE_ServiceXMPPTimeZoneSetting_4:
			Txt_TitleServiceXMPPMaintenanceTimeZoneSet.changeText( s_KEY_ServiceXMPPTimeZoneSetting4 );		// 「時間帯設定4」表示.
			break;
		default:
			break;
	}

	// 開始時刻の表示.
	Btx_ServiceXMPPMaintenanceStartTimeHour.leftSet( ( float )m_uc_StartHour, m_ss_StartHourInputDigit );
	Btx_ServiceXMPPMaintenanceStartTimeMinute.leftSet( ( float )m_uc_StartMinute, m_ss_StartMinuteInputDigit );
	// 終了時刻の表示.
	Btx_ServiceXMPPMaintenanceEndTimeHour.leftSet( ( float )m_uc_EndHour, m_ss_EndHourInputDigit );
	Btx_ServiceXMPPMaintenanceEndTimeMinute.leftSet( ( float )m_uc_EndMinute, m_ss_EndMinuteInputDigit );

	Rbt_ServiceXMPPMaintenanceTimeSet.select( m_uc_TimeSelect );	// 時/分.
	
	Rbt_ServiceXMPPMaintenanceSelect.select( True == m_bl_MaintenanceTimeEnable ? 1 : 0 );	// 使用する/使用しない.
	// パーツの表示/非表示.
	Txt_ServiceXMPPTimeZoneSettingStartTime.showEnable(m_bl_MaintenanceTimeEnable);
	Txt_ServiceXMPPTimeZoneSettingEndTime.showEnable(m_bl_MaintenanceTimeEnable);
	Rbt_ServiceXMPPMaintenanceTimeSet.showEnable(m_bl_MaintenanceTimeEnable);
	Btx_ServiceXMPPMaintenanceStartTimeHour.showEnable(m_bl_MaintenanceTimeEnable);
	Btx_ServiceXMPPMaintenanceStartTimeMinute.showEnable(m_bl_MaintenanceTimeEnable);
	Btx_ServiceXMPPMaintenanceEndTimeHour.showEnable(m_bl_MaintenanceTimeEnable);
	Btx_ServiceXMPPMaintenanceEndTimeMinute.showEnable(m_bl_MaintenanceTimeEnable);
	Txt_ServiceXMPPMaintenanceStartTimeRangeHour.showEnable(m_bl_MaintenanceTimeEnable);
	Txt_ServiceXMPPMaintenanceStartTimeRangeMinute.showEnable(m_bl_MaintenanceTimeEnable);
	Txt_ServiceXMPPMaintenanceEndTimeRangeHour.showEnable(m_bl_MaintenanceTimeEnable);
	Txt_ServiceXMPPMaintenanceEndTimeRangeMinute.showEnable(m_bl_MaintenanceTimeEnable);
}

//================================================================================================.
// 概要		: PServiceXMPPMaintenanceTimeZoneSetting : OKキー押下処理.
//				K4B0014110_遠隔ｻｰﾋﾞｽ設定／常時接続設定／メンテナンス時間帯/時間帯設定1.
//				K4B0014120_遠隔ｻｰﾋﾞｽ設定／常時接続設定／メンテナンス時間帯/時間帯設定2.
//				K4B0014130_遠隔ｻｰﾋﾞｽ設定／常時接続設定／メンテナンス時間帯/時間帯設定3.
//				K4B0014140_遠隔ｻｰﾋﾞｽ設定／常時接続設定／メンテナンス時間帯/時間帯設定4.
// 備考		: なし.
//================================================================================================.
void PServiceXMPPMaintenanceTimeZoneSetting::procOk( uchar option )
{
	if( True == m_bl_MaintenanceTimeEnable ) {
		// 範囲外、未入力の場合は画面遷移しない.
		if( ( 23 < m_uc_StartHour ) || ( 59 < m_uc_StartMinute )								// 限界値チェック.
			|| ( PNLD_ServiceXMPPMaintenanceTime_2_DIGIT != m_ss_StartHourInputDigit )			// 「時」入力済みチェック.
			|| ( PNLD_ServiceXMPPMaintenanceTime_2_DIGIT != m_ss_StartMinuteInputDigit ) ) {	// 「分」入力済みチェック.
			setBuzzerType( PCGE_BuzzerType_InputNg );											// ブザー音セット.
			return;
		}

		if( ( 23 < m_uc_EndHour ) || ( 59 < m_uc_EndMinute )									// 限界値チェック.
			|| ( PNLD_ServiceXMPPMaintenanceTime_2_DIGIT != m_ss_EndHourInputDigit )			// 「時」入力済みチェック.
			|| ( PNLD_ServiceXMPPMaintenanceTime_2_DIGIT != m_ss_EndMinuteInputDigit ) ) {		// 「分」入力済みチェック.
			setBuzzerType( PCGE_BuzzerType_InputNg );											// ブザー音セット.
			return;
		}

		// 開始時刻>終了時刻、まだは同一時刻(0:00～0:00以外)の場合.
		if( ( m_uc_StartHour > m_uc_EndHour ) || ( ( m_uc_StartHour == m_uc_EndHour ) && ( m_uc_StartMinute > m_uc_EndMinute ) )
		 || ( ( m_uc_StartHour == m_uc_EndHour ) && ( m_uc_StartMinute == m_uc_EndMinute ) && ( ( 0 != m_uc_StartHour ) || ( 0 != m_uc_StartMinute ) ) ) ) {
			setBuzzerType( PCGE_BuzzerType_InputNg );											// ブザー音セット.
			return;
		}
	}

	// 更新した時刻を親クラス(共通画面クラス)メンバー変数へ設定.
	m_st_XMPPKeepAliveSetting.m_s_NoChangeDecisionTime[m_e_XMPPMaintenanceTimeNum].m_c_StartTime.sc_Hour	=	m_uc_StartHour;
	m_st_XMPPKeepAliveSetting.m_s_NoChangeDecisionTime[m_e_XMPPMaintenanceTimeNum].m_c_StartTime.sc_Minute	=	m_uc_StartMinute;
	m_st_XMPPKeepAliveSetting.m_s_NoChangeDecisionTime[m_e_XMPPMaintenanceTimeNum].m_c_EndTime.sc_Hour		=	m_uc_EndHour;
	m_st_XMPPKeepAliveSetting.m_s_NoChangeDecisionTime[m_e_XMPPMaintenanceTimeNum].m_c_EndTime.sc_Minute	=	m_uc_EndMinute;

	// 画面遷移.
	nextGamen = &gp_ServiceXMPPMaintenanceTime;	// K4B0014100_遠隔ｻｰﾋﾞｽ設定／常時接続設定／メンテナンス時間帯.
}
//================================================================================================.
// 概要		: PServiceXMPPMaintenanceTimeZoneSetting : キー押下処理 .
//				K4B0014110_遠隔ｻｰﾋﾞｽ設定／常時接続設定／メンテナンス時間帯/時間帯設定1.
//				K4B0014120_遠隔ｻｰﾋﾞｽ設定／常時接続設定／メンテナンス時間帯/時間帯設定2.
//				K4B0014130_遠隔ｻｰﾋﾞｽ設定／常時接続設定／メンテナンス時間帯/時間帯設定3.
//				K4B0014140_遠隔ｻｰﾋﾞｽ設定／常時接続設定／メンテナンス時間帯/時間帯設定4.
// 備考		: なし.
//================================================================================================.
void PServiceXMPPMaintenanceTimeZoneSetting::procButtonOn( uchar option )
{
	switch( option ) {
		// 使用する.
		case BTNID_ServiceXMPPMaintenance_Use:				m_bl_MaintenanceTimeEnable = True;								break;
		// 使用しない.
		case BTNID_ServiceXMPPMaintenance_NotUse:
// comment 2015/10/22 [CQ519830] 未入力又は入力途中の場合、設定値を保存させない対応 日立 村上(幸).
			if( ( PNLD_ServiceXMPPMaintenanceTime_2_DIGIT != m_ss_StartHourInputDigit ) 
			 || ( PNLD_ServiceXMPPMaintenanceTime_2_DIGIT != m_ss_StartMinuteInputDigit) 
			 || ( PNLD_ServiceXMPPMaintenanceTime_2_DIGIT != m_ss_EndHourInputDigit ) 
			 || ( PNLD_ServiceXMPPMaintenanceTime_2_DIGIT != m_ss_EndMinuteInputDigit ) ) {	// 時、分のどれかが入力途中の場合.
			 	setBuzzerType( PCGE_BuzzerType_InputNg );									// ブザー音セット.
			 } else {
				m_bl_MaintenanceTimeEnable = False;
			}
			break;
		// 開始時刻-時.
		case BTNID_ServiceXMPPMaintenanceStartTime_Hour:	m_uc_TimeSelect = PNLE_ServiceXMPPMaintenanceTime_StartHour;	break;
		// 開始時刻-分.
		case BTNID_ServiceXMPPMaintenanceStartTime_Minute:	m_uc_TimeSelect = PNLE_ServiceXMPPMaintenanceTime_StartMinute;	break;
		// 終了時刻-時.
		case BTNID_ServiceXMPPMaintenanceEndTime_Hour:		m_uc_TimeSelect = PNLE_ServiceXMPPMaintenanceTime_EndHour;		break;
		// 終了時刻-分.
		case BTNID_ServiceXMPPMaintenanceEndTime_Minute:	m_uc_TimeSelect = PNLE_ServiceXMPPMaintenanceTime_EndMinute;	break;
		default:break;
	}
	m_st_XMPPKeepAliveSetting.m_s_NoChangeDecisionTime[m_e_XMPPMaintenanceTimeNum].m_b_Enable = m_bl_MaintenanceTimeEnable;
	setupGamen( option );
}
//================================================================================================.
// 概要		: PServiceXMPPMaintenanceTimeZoneSetting : テンキー .
//				K4B0014110_遠隔ｻｰﾋﾞｽ設定／常時接続設定／メンテナンス時間帯/時間帯設定1.
//				K4B0014120_遠隔ｻｰﾋﾞｽ設定／常時接続設定／メンテナンス時間帯/時間帯設定2.
//				K4B0014130_遠隔ｻｰﾋﾞｽ設定／常時接続設定／メンテナンス時間帯/時間帯設定3.
//				K4B0014140_遠隔ｻｰﾋﾞｽ設定／常時接続設定／メンテナンス時間帯/時間帯設定4.
// 備考		: なし.
//================================================================================================.
void PServiceXMPPMaintenanceTimeZoneSetting::proc10Key( uchar option )
{
	if( False == m_bl_MaintenanceTimeEnable ) {
		setBuzzerType( PCGE_BuzzerType_InputNg );							// ブザー音セット.
		return;
	}

	switch( m_uc_TimeSelect ) {
		// 『開始時刻-時』を更新.
		case PNLE_ServiceXMPPMaintenanceTime_StartHour:		timeUpdate( option, &m_uc_StartHour, &m_ss_StartHourInputDigit, 23, 2 );		break;
		// 『開始時刻-分』を更新.
		case PNLE_ServiceXMPPMaintenanceTime_StartMinute:	timeUpdate( option, &m_uc_StartMinute, &m_ss_StartMinuteInputDigit, 59, 5 );	break;
		// 『終了時刻-時』を更新.
		case PNLE_ServiceXMPPMaintenanceTime_EndHour:		timeUpdate( option, &m_uc_EndHour, &m_ss_EndHourInputDigit, 23, 2 );			break;
		// 『終了時刻-分』を更新.
		case PNLE_ServiceXMPPMaintenanceTime_EndMinute:		timeUpdate( option, &m_uc_EndMinute, &m_ss_EndMinuteInputDigit, 59, 5 );		break;
		default:	break;
	}

	setupGamen( option );														// 画面更新を行う.
}
//================================================================================================.
// 概要		: PServiceXMPPMaintenanceTimeZoneSetting : クリアキー .
//				K4B0014110_遠隔ｻｰﾋﾞｽ設定／常時接続設定／メンテナンス時間帯/時間帯設定1.
//				K4B0014120_遠隔ｻｰﾋﾞｽ設定／常時接続設定／メンテナンス時間帯/時間帯設定2.
//				K4B0014130_遠隔ｻｰﾋﾞｽ設定／常時接続設定／メンテナンス時間帯/時間帯設定3.
//				K4B0014140_遠隔ｻｰﾋﾞｽ設定／常時接続設定／メンテナンス時間帯/時間帯設定4.
// 備考		: なし.
//================================================================================================.
void PServiceXMPPMaintenanceTimeZoneSetting::procClear( uchar option )
{
	if( False == m_bl_MaintenanceTimeEnable ) {
		setBuzzerType( PCGE_BuzzerType_InputNg );							// ブザー音セット.
		return;
	}

	if( PNLE_ServiceXMPPMaintenanceTime_StartHour == m_uc_TimeSelect ) {
		m_uc_StartHour = 0;														// 開始時刻「時」を0にする.
		m_ss_StartHourInputDigit = PNLD_ServiceXMPPMaintenanceTime_0_DIGIT;
	}
	else if( PNLE_ServiceXMPPMaintenanceTime_StartMinute == m_uc_TimeSelect ) {
		m_uc_StartMinute = 0;													// 開始時刻「分」を0にする.
		m_ss_StartMinuteInputDigit = PNLD_ServiceXMPPMaintenanceTime_0_DIGIT;
	}
	else if( PNLE_ServiceXMPPMaintenanceTime_EndHour == m_uc_TimeSelect ) {
		m_uc_EndHour = 0;														// 終了時刻「時」を0にする.
		m_ss_EndHourInputDigit = PNLD_ServiceXMPPMaintenanceTime_0_DIGIT;
	}
	else if( PNLE_ServiceXMPPMaintenanceTime_EndMinute == m_uc_TimeSelect ) {
		m_uc_EndMinute = 0;														// 終了時刻「分」を0にする.
		m_ss_EndMinuteInputDigit = PNLD_ServiceXMPPMaintenanceTime_0_DIGIT;
	}
	else {
		// 何もしない.
	}

	setupGamen( option );														// 画面更新を行う.
}

//================================================================================================.
// 概要		: PServiceXMPPMaintenanceTimeZoneSetting : 時刻更新 .
//				K4B0014110_遠隔ｻｰﾋﾞｽ設定／常時接続設定／メンテナンス時間帯/時間帯設定1.
//				K4B0014120_遠隔ｻｰﾋﾞｽ設定／常時接続設定／メンテナンス時間帯/時間帯設定2.
//				K4B0014130_遠隔ｻｰﾋﾞｽ設定／常時接続設定／メンテナンス時間帯/時間帯設定3.
//				K4B0014140_遠隔ｻｰﾋﾞｽ設定／常時接続設定／メンテナンス時間帯/時間帯設定4.
// 備考		: なし.
//================================================================================================.
void PServiceXMPPMaintenanceTimeZoneSetting::timeUpdate( uchar uc_Option, uchar* puc_Time, short* pss_InputDigit, uchar uc_TimeMax, uchar uc_TimeFirstDigit )
{
	switch( *pss_InputDigit ) {
		// 未入力の場合.
		case PNLD_ServiceXMPPMaintenanceTime_0_DIGIT:
			if( uc_Option <= uc_TimeFirstDigit ) {								// 入力値が0～uc_TimeFirstDigitの場合は上位桁として受付.
				*puc_Time = uc_Option;
				*pss_InputDigit = PNLD_ServiceXMPPMaintenanceTime_1_DIGIT;
			}
			else if( uc_Option <= 9 ) {											// 入力値がuc_TimeFirstDigit+1～9の場合は下位桁として受付.
				*puc_Time = uc_Option;
				*pss_InputDigit = PNLD_ServiceXMPPMaintenanceTime_2_DIGIT;
			}
			else {																// 範囲外の場合は拒否音.
				setBuzzerType( PCGE_BuzzerType_InputNg );
			}
			break;
		// 上位桁入力済みの場合.
		case PNLD_ServiceXMPPMaintenanceTime_1_DIGIT:
			{
				uchar uc_TimeCheck = *puc_Time;
				uc_TimeCheck = static_cast<uchar>( uc_TimeCheck * 10 + uc_Option );					// 入力済みの上位桁と入力値を結合.
				if( uc_TimeCheck <= uc_TimeMax ) {								// 結合結果が0～uc_TimeMaxの場合は受付.
					*puc_Time = uc_TimeCheck;
					*pss_InputDigit = PNLD_ServiceXMPPMaintenanceTime_2_DIGIT;
				}
				else {															// 範囲外の場合は拒否音.
					setBuzzerType( PCGE_BuzzerType_InputNg );
				}
			}
			break;

		// 入力済みの場合.
		default:
			setBuzzerType( PCGE_BuzzerType_InputNg );
			break;
	}
}

