	PServiceXMPPKeepAliveSettingCom::setupGamen( option );
	// 生存通知間隔の表示.
	Btx_ServiceXMPPNotifyCycle.set( ( float )m_st_XMPPKeepAliveSetting.m_us_CycleSpan, ( m_st_XMPPKeepAliveSetting.m_us_CycleSpan < 1 ) ? False : True );
