void PServiceXMPPNotifyCycle::procIndexButton( uchar option )
{
	// 範囲外の場合は画面遷移しない.
	if( ( m_st_XMPPKeepAliveSetting.m_us_CycleSpan < TYPD_RoimWscDataIF_XMPPKeepAliveSetting_CycleSpanMin ) 
	 || ( TYPD_RoimWscDataIF_XMPPKeepAliveSetting_CycleSpanMax < m_st_XMPPKeepAliveSetting.m_us_CycleSpan ) ) {
		setBuzzerType( PCGE_BuzzerType_InputNg );					// ブザー音セット.
		return;
	}

	// 親クラスを呼ぶ.
	PServiceXMPPKeepAliveSettingCom::procIndexButton( option );
}

//================================================================================================.
// 概要		: PServiceXMPPNotifyCycle : K4B0014200_遠隔ｻｰﾋﾞｽ設定／常時接続設定／生存通知間隔 : テンキー .
// 備考		: なし.
//================================================================================================.
void PServiceXMPPNotifyCycle::proc10Key( uchar option )
{
	Bool bl_isError = False;
	// 生存通知間隔を更新する.
	m_st_XMPPKeepAliveSetting.m_us_CycleSpan = ( ushort )proc10KeyInput( m_st_XMPPKeepAliveSetting.m_us_CycleSpan, TYPD_RoimWscDataIF_XMPPKeepAliveSetting_CycleSpanMax, option, m_bl_Direct, EP_InputMaxLimitPattern_Refuse, &bl_isError );

	if( True == bl_isError ) {
		setBuzzerType( PCGE_BuzzerType_InputNg );					// ブザー音セット.
	}
	else {
		if( True == m_bl_Direct && 1 > option ) {
			setBuzzerType( PCGE_BuzzerType_InputNg );				// ブザー音セット.
		}
		else {
			m_bl_Direct = False;
		}
	}
	setupGamen( option );											// 画面更新を行う.
}

