// 備考		: なし.
//================================================================================================.
void PServiceXMPPNotifyCycle::procClear( uchar option )
{
	m_st_XMPPKeepAliveSetting.m_us_CycleSpan = 0;					// 生存通知間隔を0にする.
	m_bl_Direct = True;
	setupGamen( option );											// 画面更新を行う.
}

