// 概要		: PServiceXMPPLeaningFunction : K4B0014300_遠隔ｻｰﾋﾞｽ設定／常時接続設定／学習機能 : 画面更新処理 .
// 備考		: なし.
//================================================================================================.
void PServiceXMPPLeaningFunction::setupGamen( short option )
{
	// 親クラスを呼ぶ.
	PServiceXMPPKeepAliveSettingCom::setupGamen( option );

	Rbt_ServiceXMPPKeepAliveCyclicModeSelect.select( TYPE_RoimWscDataIF_KeepAliveCyclicMode_Variable == m_st_XMPPKeepAliveSetting.m_e_KeepAliveCyclicMode ? 1 : 0 );	// 有効/無効.

	if( TYPE_RoimWscDataIF_KeepAliveCyclicMode_Variable == m_st_XMPPKeepAliveSetting.m_e_KeepAliveCyclicMode ) {	// 学習機能・有効.
		Rbt_ServiceXMPPLeaningFunctionSelect.showEnable( True );		// 学習機能ローテーションボタン・表示.
		Btx_ServiceXMPPLeaningFunctionRange.showEnable( True );			// 調整値・表示.
// comment 2015/11/2 [CQ519871] 上限値は不要のため、上限キーの削除対応 日立 村上(幸).
//		Btx_ServiceXMPPLeaningFunctionMax.showEnable( True );			// 上限値・表示.
		Btx_ServiceXMPPLeaningFunctionMin.showEnable( True );			// 下限値・表示.
		Grp_ServiceXMPPLeaningFunctionItems.showEnable( True );			// 学習機能の範囲・表示.
		// 学習機能の表示.
		Btx_ServiceXMPPLeaningFunctionRange.set( ( float )m_us_VariableRange, ( m_us_VariableRange < 1 ) ? False : True );	// 調整値.
// comment 2015/11/2 [CQ519871] 上限値は不要のため、上限キーの削除対応 日立 村上(幸).
//		Btx_ServiceXMPPLeaningFunctionMax.set( ( float )m_us_VariableMax, ( m_us_VariableMax < 1 ) ? False : True );		// 上限値.
		Btx_ServiceXMPPLeaningFunctionMin.set( ( float )m_us_VariableMin, ( m_us_VariableMin < 1 ) ? False : True );		// 下限値.

		Rbt_ServiceXMPPLeaningFunctionSelect.select( m_sc_Select );	// 調整値/下限値.
	}
	else {	// 学習機能・無効.
		Rbt_ServiceXMPPLeaningFunctionSelect.showEnable( False );		// 学習機能ローテーションボタン・非表示.
		Btx_ServiceXMPPLeaningFunctionRange.showEnable( False );		// 調整値・非表示.
// comment 2015/11/2 [CQ519871] 上限値は不要のため、上限キーの削除対応 日立 村上(幸).
//		Btx_ServiceXMPPLeaningFunctionMax.showEnable( False );			// 上限値・非表示.
		Btx_ServiceXMPPLeaningFunctionMin.showEnable( False );			// 下限値・非表示.
		Grp_ServiceXMPPLeaningFunctionItems.showEnable( False );		// 学習機能の範囲・非表示.
	}
}

//================================================================================================.
// 概要		: PServiceXMPPLeaningFunction : K4B0014300_遠隔ｻｰﾋﾞｽ設定／常時接続設定／学習機能 : キー押下処理 .
// 備考		: なし.
//================================================================================================.
void PServiceXMPPLeaningFunction::procButtonOn( uchar option )
{
	// 親クラスを呼ぶ.
	PServiceXMPPKeepAliveSettingCom::procButtonOn( option );

	switch( option ) {
		// 無効.
		case BTNID_ServiceXMPPLeaningFunction_Disable:																													// 選択中を「無効」にする.
// comment 2015/11/2 [CQ519871] 設定途中は画面遷移及び無効を選択させない対応(他画面と統一) 日立 村上(幸).
			if( ( m_us_VariableRange < TYPD_RoimWscDataIF_XMPPKeepAliveSetting_CycleSpanMin ) || ( TYPD_RoimWscDataIF_XMPPKeepAliveSetting_CycleSpanMax < m_us_VariableRange )
			 || ( m_us_VariableMin < TYPD_RoimWscDataIF_XMPPKeepAliveSetting_CycleSpanMin ) || ( TYPD_RoimWscDataIF_XMPPKeepAliveSetting_CycleSpanMax < m_us_VariableMin ) ) {
				setBuzzerType( PCGE_BuzzerType_InputNg );						// ブザー音セット.
				return;
			}
			m_st_XMPPKeepAliveSetting.m_e_KeepAliveCyclicMode = TYPE_RoimWscDataIF_KeepAliveCyclicMode_Static;	
			m_sc_Select = -1;
			break;
		// 有効.
		case BTNID_ServiceXMPPLeaningFunction_Enable:	m_st_XMPPKeepAliveSetting.m_e_KeepAliveCyclicMode = TYPE_RoimWscDataIF_KeepAliveCyclicMode_Variable;	break;	// 選択中を「有効」にする.
		// 調整値.
		case BTNID_ServiceXMPPLeaningFunctionRange:		m_sc_Select = PNLE_ServiceXMPPLeaningFunctionRange;														break;	// 選択中を「調整値」にする.
// comment 2015/11/2 [CQ519871] 上限値は不要のため、上限キーの削除対応 日立 村上(幸).
//		// 上限値.
//		case BTNID_ServiceXMPPLeaningFunctionMax:		m_sc_Select = PNLE_ServiceXMPPLeaningFunctionMax;														break;	// 選択中を「上限値」にする.
		// 下限値.
		case BTNID_ServiceXMPPLeaningFunctionMin:		m_sc_Select = PNLE_ServiceXMPPLeaningFunctionMin;														break;	// 選択中を「下限値」にする.
		default:break;
	}
	setupGamen( option );
}

