void PServiceRebuild::procStart( uchar )
{
//	if( False == _bl_isPushedStart ) {
//		_bl_isPushedStart = True;			// 画面に入った後、スタート押下済（１回でもファンクション実行したらTrue）.
//		ss_StaticLocalPercent = 0;			// ファンクションのパーセンテージ.
//		Txt_ServiceMemoryCompress_OKNG.showEnable( False );	// 経過の表示/非表示
//		if( False == bl_RebuildStart ) {		//リビルド開始処理に失敗した場合.
//			Txt_ServiceMemoryCompress_OKNG.changeText( s_ServiceMemoryCheck_NG );	// NG表示
//			Txt_ServiceMemoryCompress_OKNG.showEnable( True );	// NG表示
//			_bl_isPushedStart = False;
//		}
// comment 2015/04/02 OPS1-Sky浜野 [ZeusS][CQ510790] 実行結果が表示されない不具合対応.
//	if( False == m_bl_RebuildOn ) {
	if( PNLE_HddRebuildStatus_Processing != onlyPanel.getHddRebuildStatus() ) {
		//リビルド中でなければ受け付ける.
// comment 2015/04/02 OPS1-Sky浜野 [ZeusS][CQ510790] 実行結果が表示されない不具合対応.
//		m_bl_RebuildOn = True;
		onlyPanel.setHddRebuildStatus( PNLE_HddRebuildStatus_Processing );
		Txt_ServiceMemoryCompress_OKNG.showEnable( False );	// 経過の表示/非表示
		APIC_HddInfo* pc_HddInfo = PnlComGetHddInfo();
		if( NULL != pc_HddInfo ) {
			Bool bl_RebuildStart = pc_HddInfo->RebuildStart();		//リビルド処理開始.
			if( False == bl_RebuildStart ) {		//リビルド開始処理に失敗した場合.
// comment 2015/04/02 OPS1-Sky浜野 [ZeusS][CQ510790] 実行結果が表示されない不具合対応.
//				m_bl_RebuildOn = False;
				onlyPanel.setHddRebuildStatus( PNLE_HddRebuildStatus_None );
				Txt_ServiceMemoryCompress_OKNG.changeText( s_ServiceMemoryCheck_NG );	// NG表示
				Txt_ServiceMemoryCompress_OKNG.showEnable( True );	// NG表示
			}
		}
		setupGamen();	// 表示画面のセットアップ.
	} else {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );		// 拒否音.
	}
}


