// 2014/10/30 [MAv3][RQ-251] 指示サーバとの連携によるセットアップ性改善 CSRCの自動初期発信 日立 村上(幸).
//=================================================================================================================================.
// 概要		: PServiceCSRCAutoInitDial : K4B0018100_CS Remote Care／自動初期発信設定 : 画面開始処理.
// 備考		: なし.
//=================================================================================================================================.
void PServiceCSRCAutoInitDial::startGamen()
{
	APIC_SystemSetting *pc_SystemSetting  = APIC_SystemSetting::newInstance();

	if( NULL == pc_SystemSetting ) {
// Comment 2015/11/02 【ZeusS_ZX0】【HCL_Vasu】【制御構成変更_No.76-1】Adding Error Code macro.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//		if (NULL !=pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x1900650100456901 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}

	// 親クラスを呼ぶ.
	PServiceNoFunctionCodeCom::startGamen();

	// CSRC自動初期発信設定を取得.
	m_bl_CSRCAutoInitDialSetting[PNLD_ServiceCSRCAutoInitDialType_Telephony] 	= pc_SystemSetting->getCSRCAutoInitDial_Enable( TYPE_CSRCAutoInitDialType_Telephony );	// モデム.
	m_bl_CSRCAutoInitDialSetting[PNLD_ServiceCSRCAutoInitDialType_Fax]			= pc_SystemSetting->getCSRCAutoInitDial_Enable( TYPE_CSRCAutoInitDialType_Fax );		// ファクス.
	m_bl_CSRCAutoInitDialSetting[PNLD_ServiceCSRCAutoInitDialType_Email]		= pc_SystemSetting->getCSRCAutoInitDial_Enable( TYPE_CSRCAutoInitDialType_Email );		// E-Mail.
	m_bl_CSRCAutoInitDialSetting[PNLD_ServiceCSRCAutoInitDialType_HTTP]		= pc_SystemSetting->getCSRCAutoInitDial_Enable( TYPE_CSRCAutoInitDialType_HTTP );		// http.
}

//=================================================================================================================================.
// 概要		: PServiceCSRCAutoInitDial : K4B0018100_CS Remote Care／自動初期発信設定 : 画面更新処理.
// 備考		: なし.
//=================================================================================================================================.
void PServiceCSRCAutoInitDial::setupGamen( short option )
{
	short	ssSelNo = 0;		// ローテーションボタンの選択ボタン番号.

	// 親クラスを呼ぶ.
	PServiceNoFunctionCodeCom::setupGamen( option );

	// 表する・しないキー選択状態更新.
	// モデム.
	ssSelNo = ( m_bl_CSRCAutoInitDialSetting[PNLD_ServiceCSRCAutoInitDialType_Telephony] ? 0 : 1 );
	Rbt_ServiceCSRCAutoInitDial_Modem.select( ssSelNo );
	// ファクス.
	ssSelNo = ( m_bl_CSRCAutoInitDialSetting[PNLD_ServiceCSRCAutoInitDialType_Fax] ? 0 : 1 );
	Rbt_ServiceCSRCAutoInitDial_Fax.select( ssSelNo );
	// E-Mail.
	ssSelNo = ( m_bl_CSRCAutoInitDialSetting[PNLD_ServiceCSRCAutoInitDialType_Email] ? 0 : 1 );
	Rbt_ServiceCSRCAutoInitDial_Email.select( ssSelNo );
	// http.
	ssSelNo = ( m_bl_CSRCAutoInitDialSetting[PNLD_ServiceCSRCAutoInitDialType_HTTP] ? 0 : 1 );
	Rbt_ServiceCSRCAutoInitDial_Http.select( ssSelNo );
// Comment 2020/01/14 [HCLT-Ranjith] [IT6_HeliosMLK] [OP_BTS-16701] Fax text and Set/ Unset rotation button hide for HeliosMLK china destination.
// //comment 2018/05/22 HCLT-Taqiuddin [Sparrow][機器構成変更_No.206 ] Hiding Fax for SparrowSFP.
// 	if( IsSFP() ) {
	TYPE_MachineType e_MachineType = PnlComGetSystemInfo()->getMachineType();
	if( ( IsSFP() )
		||( TYPE_MachineTypeHeliosMLK3_CN == e_MachineType )
		|| ( TYPE_MachineTypeHeliosMLK2_5_CN == e_MachineType )
		|| ( TYPE_MachineTypeHeliosMLK2_5_CNDF == e_MachineType ) 
		|| ( TYPE_MachineTypeHeliosMLKEmu800_CN == e_MachineType ) 
		|| ( TYPE_MachineTypeHeliosMLK2_CNDF == e_MachineType ) ) {
		Rbt_ServiceCSRCAutoInitDial_Fax.showEnable( False );
		Txt_ServiceCSRCAutoInitDial_Fax.showEnable( False );
	}
}
//================================================================================================.
// 概要		: PServiceCSRCAutoInitDial : K4B0018100_CS Remote Care／自動初期発信設定 : キー押下処理 .
// 備考		: なし.
//================================================================================================.
void PServiceCSRCAutoInitDial::procButtonOn( uchar option )
{
	static const struct ST_BtnIdConv {
		uchar				uc_Type;		// タイプ.
		Bool				bl_TblVal;		// する・しない.
	} tblBtnIdConv[] = {											// ボタンIDからタイプとする・しないを得る.
		{ PNLD_ServiceCSRCAutoInitDialType_Telephony,	True	},	// モデム:する.
		{ PNLD_ServiceCSRCAutoInitDialType_Telephony,	False	},	// モデム:しない.
		{ PNLD_ServiceCSRCAutoInitDialType_Fax,			True	},	// ファクス:する.
		{ PNLD_ServiceCSRCAutoInitDialType_Fax,			False	},	// ファクス:しない.
		{ PNLD_ServiceCSRCAutoInitDialType_Email,		True	},	// E-Mail:する.
		{ PNLD_ServiceCSRCAutoInitDialType_Email,		False	},	// E-Mail:しない.
		{ PNLD_ServiceCSRCAutoInitDialType_HTTP,		True	},	// http:する.
		{ PNLD_ServiceCSRCAutoInitDialType_HTTP,		False	},	// http;しない.
	};
	
	// 内部で保持しているCSRC自動初期発信設定の状態更新.
	if( option < STRUCT_SIZE(tblBtnIdConv) ) {
		m_bl_CSRCAutoInitDialSetting[ tblBtnIdConv[option].uc_Type ] = tblBtnIdConv[ option ].bl_TblVal;
	}

	setupGamen( option );
}

//================================================================================================.
// 概要		: PServiceCSRCAutoInitDial : K4B0018100_CS Remote Care／自動初期発信設定 : OKキー押下処理.
// 備考		: なし.
//================================================================================================.
void PServiceCSRCAutoInitDial::procOk( uchar option )
{
	APIC_SystemSetting *pc_SystemSetting  = APIC_SystemSetting::newInstance();

	if( NULL == pc_SystemSetting ) {
// Comment 2015/11/02 【ZeusS_ZX0】【HCL_Vasu】【制御構成変更_No.76-1】Adding Error Code macro.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//		if (NULL !=pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x1900030100456A01 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}

	// CSRC自動初期発信設定をCommonAPIに設定.
	pc_SystemSetting->setCSRCAutoInitDial_Enable( TYPE_CSRCAutoInitDialType_Telephony,	m_bl_CSRCAutoInitDialSetting[PNLD_ServiceCSRCAutoInitDialType_Telephony] );// モデム.
	pc_SystemSetting->setCSRCAutoInitDial_Enable( TYPE_CSRCAutoInitDialType_Fax,		m_bl_CSRCAutoInitDialSetting[PNLD_ServiceCSRCAutoInitDialType_Fax] );		// ファクス.
	pc_SystemSetting->setCSRCAutoInitDial_Enable( TYPE_CSRCAutoInitDialType_Email,		m_bl_CSRCAutoInitDialSetting[PNLD_ServiceCSRCAutoInitDialType_Email] );	// E-Mail.
	pc_SystemSetting->setCSRCAutoInitDial_Enable( TYPE_CSRCAutoInitDialType_HTTP,		m_bl_CSRCAutoInitDialSetting[PNLD_ServiceCSRCAutoInitDialType_HTTP] );		// http.
	
// comment 2017/06/05 日立 田中 [MAv5-1][RQ-710] CSRA接続.
//	nextGamen = &gp_ServiceCSRemoteCaremMenu;	// 80B93400_CS Remote Care／メニュー.
	nextGamen = &gp_ServiceCSRemoteCareMenu;	// zcB0011000_CS Remote Care／メニュー.
}

