//================================================================================================.
// 概要		: PServiceDataBackupMenu : K4B0020000 セキュリティ設定／ﾃﾞｰﾀﾊﾞｯｸｱｯﾌﾟ : 表示画面セットアップ.
// 戻り値	:なし.
// 備考		:.
//================================================================================================.
void PServiceDataBackupMenu::setupGamen( short option )
{
	// 親クラスを呼ぶ.
	PServiceNoFunctionCodeCom::setupGamen( option );

	m_bl_DataExist = APIC_BackupRestore::newInstance()->checkExistHDDBackupData();
// comment 2018/04/24 [制御構成変更_No.98] [Eagle][HCLT-Sam Sundar]- Hiding HDD Backup and Restore from HDD Key.
	TYPE_StorageConfig e_StorageConfig = TYPE_StorageConfig_None;
	APIC_SystemInfo* pc_SystemInfo = PnlComGetSystemInfo();
	if ( NULL == pc_SystemInfo ) {
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//			if (NULL !=pc_BFW_System){
//			    pc_BFW_System->registDetailCode(PNLD_DetailCode_Service_0x1900660101174101);
//			}
			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
			return;
		} else {
			e_StorageConfig = PnlComGetSystemInfo()->isStorageConfiguration();
		}
	//HDD非装着の場合、「HDDﾊﾞｯｸｱｯﾌﾟ」、「HDDﾘｽﾄｱ」キーは非表示.
	if( False == m_bl_HDDExist ) {
		Key_ServiceDataBackHDDBackup.showEnable( False );
		Key_ServiceDataBackHDDRestore.showEnable( False );
// 2015/12/10 [MAv4][RQ-505] バックアップサーバー設定追加 日立 野口.
		Grp_ServiceDataBackupServerMenu.showEnable( False );
	}
// comment 2018/04/24 [制御構成変更_No.98] [Eagle][HCLT-Sam Sundar]- Hiding HDD Backup and Restore from HDD Key.
	else if ( TYPE_StorageConfig_MicroSD_8GB_SSD_256GB != e_StorageConfig ) {
		Key_ServiceDataBackHDDBackup.showEnable( False );
		Key_ServiceDataBackHDDRestore.showEnable( False );
	} else {
		//HDDﾊﾞｯｸｱｯﾌﾟデータがない場合、「HDDﾘｽﾄｱ」キーは非表示.
		Key_ServiceDataBackHDDRestore.showEnable( m_bl_DataExist );
	}
	// 1TB対応していないMFPも非表示にする TODO.
}

//================================================================================================.
// 概要		: PServiceDataBackupAutoBackupCom : ﾃﾞｰﾀﾊﾞｯｸｱｯﾌﾟ／自動ﾊﾞｯｸｱｯﾌﾟ共通クラス :ボタン押下( K4B0021200画面とK4B0023710画面共用 ).
// 戻り値	:なし.
// 備考		:.
//================================================================================================.
void PServiceDataBackupAutoBackupCom::procButtonOn( uchar option )
{
	// 親クラスを呼ぶ.
	PServiceNoFunctionCodeCom::procButtonOn( option );

	switch( option ) {
		// しない.
		case BTNID_KEY_ServiceBackupSetting_AutoBackupNone:
			// 未入力の場合は画面遷移しない.
			if( ( PNLE_ServiceDataBackupAutoBackupTime_2_DIGIT != m_us_HourInputDigit ) 		// 「時」入力済みチェック.
		    ||	( PNLE_ServiceDataBackupAutoBackupTime_2_DIGIT != m_us_MinuteInputDigit )		// 「分」入力済みチェック.
			||  ( PNLE_ServiceDataBackupAutoBackupTime_0_DIGIT == m_us_CycleInputDigit ) ) {	// 「日」入力済みチェック.
				MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
				return;
			}
			m_e_AutoBackupType = TYPE_BackupRestoreSetting_AutoBackupNone;
			break;
		// する.
		case BTNID_KEY_ServiceBackupSetting_AutoBackupEnable:
			m_e_AutoBackupType = TYPE_BackupRestoreSetting_AutoBackupCycle;
			break;
		// 日周期.
		case BTNID_KEY_ServiceBackupSetting_AutoBackupCycle:
			m_e_AutoBackupType = TYPE_BackupRestoreSetting_AutoBackupCycle;
			break;
		// 週周期.
		case BTNID_KEY_ServiceBackupSetting_AutoBackupWeekday:
			// 未入力の場合は画面遷移しない.
			if( PNLE_ServiceDataBackupAutoBackupTime_0_DIGIT == m_us_CycleInputDigit ) {	// 「日」入力済みチェック.
				MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
				return;
			}
			m_e_AutoBackupType = TYPE_BackupRestoreSetting_AutoBackupWeekday;
			if( 0 == m_uc_SelectInputButton ) {
				// 日周期で「日」を選択した状態で週周期に切り替えた場合は、「時」を選択するにする.
				m_uc_SelectInputButton = 1;
			}
			break;
		// 日周期の日.
		case BTNID_KEY_ServiceBackupSetting_AutoBackupCycleDay:
			m_uc_SelectInputButton = 0;
			break;
		// ﾊﾞｯｸｱｯﾌﾟ時刻・時.
		case BTNID_KEY_ServiceBackupSetting_AutoBackupTimeHour:
			m_uc_SelectInputButton = 1;
			break;
		// ﾊﾞｯｸｱｯﾌﾟ時刻・分.
		case BTNID_KEY_ServiceBackupSetting_AutoBackupTimeMinute:
			m_uc_SelectInputButton = 2;
			break;
		// 週周期の日／月／火／水／木／金／土.
		case BTNID_KEY_ServiceBackupSetting_AutoBackupWeekdaySun:
		case BTNID_KEY_ServiceBackupSetting_AutoBackupWeekdayMon:
		case BTNID_KEY_ServiceBackupSetting_AutoBackupWeekdayTue:
		case BTNID_KEY_ServiceBackupSetting_AutoBackupWeekdayWed:
		case BTNID_KEY_ServiceBackupSetting_AutoBackupWeekdayThu:
		case BTNID_KEY_ServiceBackupSetting_AutoBackupWeekdayFri:
		case BTNID_KEY_ServiceBackupSetting_AutoBackupWeekdaySat:
			getWeekdayType( option );
			getSelectWeekdayBindKey();
			break;
		default:
			break;
	}
	// 画面セットアップ.
	setupGamen( option );
}

//================================================================================================.
// 概要		: PServiceDataBackupAutoBackupCom : ﾃﾞｰﾀﾊﾞｯｸｱｯﾌﾟ／HDDバックアップ ／自動ﾊﾞｯｸｱｯﾌﾟ共通クラス : 表示部品のセットアップ( K4B0021200画面とK4B0023710画面共用 ).
// 戻り値	:なし.
// 備考		:.
//================================================================================================.
void PServiceDataBackupAutoBackupCom::setupGamen( short option )
{
	// 親クラスを呼ぶ.
	PServiceNoFunctionCodeCom::setupGamen( option );

	switch( m_e_AutoBackupType ) {
		case TYPE_BackupRestoreSetting_AutoBackupNone:						// しない.
			Rbt_ServiceDataBackupAutoBackupSelect.select( 0 );
			// 非表示.
			Grp_ServiceDataBackupAutoBackupPeriodParts.showEnableAll( False );
			Grp_ServiceDataBackupAutoBackupCycleParts.showEnableAll( False );
			Grp_ServiceDataBackupAutoBackupWeekdayParts.showEnableAll( False );
			Grp_ServiceDataBackupAutoBackupTimeParts.showEnableAll( False );
			break;
		case TYPE_BackupRestoreSetting_AutoBackupCycle:						// 日周期.
			Rbt_ServiceDataBackupAutoBackupSelect.select( 1 );
			// 表示/非表示.
			Grp_ServiceDataBackupAutoBackupWeekdayParts.showEnableAll( False );
			Grp_ServiceDataBackupAutoBackupPeriodParts.showEnableAll( True );
			Grp_ServiceDataBackupAutoBackupCycleParts.showEnableAll( True );
			Grp_ServiceDataBackupAutoBackupTimeParts.showEnableAll( True );
			// 日周期キー選択.
			Rbt_ServiceDataBackupAutoBackupPeriodSelect.select( 0 );
			// 日周期.
			Btx_ServiceDataBackupAutoBackupCycle.set( ( float )m_us_BackupCycle, ( m_us_CycleInputDigit < 1 ) ? False : True );
			// ﾊﾞｯｸｱｯﾌﾟ時刻.
			Btx_ServiceDataBackupAutoBackupTimeHour.leftSet( ( float )m_sc_BackupTimeHour, m_us_HourInputDigit );
			Btx_ServiceDataBackupAutoBackupTimeMinute.leftSet( ( float )m_sc_BackupTimeMinute, m_us_MinuteInputDigit );
			// 日周期/ ﾊﾞｯｸｱｯﾌﾟ時刻キー選択する.
			Rbt_ServiceDataBackupAutoBackupCycleAndTimeSelect.select( m_uc_SelectInputButton );
			break;
		case TYPE_BackupRestoreSetting_AutoBackupWeekday:					// 週周期.
			Rbt_ServiceDataBackupAutoBackupSelect.select( 1 );
			// 表示/非表示.
			Grp_ServiceDataBackupAutoBackupCycleParts.showEnableAll( False );
			Grp_ServiceDataBackupAutoBackupPeriodParts.showEnableAll( True );
			Grp_ServiceDataBackupAutoBackupWeekdayParts.showEnableAll( True );
			Grp_ServiceDataBackupAutoBackupTimeParts.showEnableAll( True );
			// 週周期キー選択.
			Rbt_ServiceDataBackupAutoBackupPeriodSelect.select( 1 );
			// 週周期の「選択した曜日」を選択状態に設定.
			Rbt_ServiceDataBackupAutoBackupWeekday.select( m_uc_SelectWeekDay );
			// ﾊﾞｯｸｱｯﾌﾟ時刻.
			Btx_ServiceDataBackupAutoBackupTimeHour.leftSet( ( float )m_sc_BackupTimeHour, m_us_HourInputDigit );
			Btx_ServiceDataBackupAutoBackupTimeMinute.leftSet( ( float )m_sc_BackupTimeMinute, m_us_MinuteInputDigit );
			// 日周期/ ﾊﾞｯｸｱｯﾌﾟ時刻キー選択する.
			Rbt_ServiceDataBackupAutoBackupCycleAndTimeSelect.select( m_uc_SelectInputButton );
			break;
		default:
			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
			break;
	}
}

//================================================================================================.
// 概要		: PServiceDataBackupAutoBackupCom : ﾃﾞｰﾀﾊﾞｯｸｱｯﾌﾟ／自動ﾊﾞｯｸｱｯﾌﾟ共通クラス : テンキー( K4B0021200画面とK4B0023710画面共用 ).
// 戻り値	:なし.
// 備考		:.
//================================================================================================.
void PServiceDataBackupAutoBackupCom::proc10Key( uchar option )
{
// comment 2015/10/22 [CQ519830] 「しない」を選択している時は入力させない対応 日立 村上(幸).
	if( TYPE_BackupRestoreSetting_AutoBackupNone == m_e_AutoBackupType ) {
		setBuzzerType( PCGE_BuzzerType_InputNg );							// ブザー音セット.
		return;
	}

	// 「時」を更新.
	if( 1 == m_uc_SelectInputButton ) {
		switch( m_us_HourInputDigit ) {
			// 未入力の場合.
			case PNLE_ServiceDataBackupAutoBackupTime_0_DIGIT:
				if( 2 >= option ) {									// 入力値が0～2の場合は上位桁として受付.
					m_sc_BackupTimeHour = option;
					m_us_HourInputDigit = PNLE_ServiceDataBackupAutoBackupTime_1_DIGIT;
				}
				else if( 9 >= option ) {							// 入力値が3～9の場合は下位桁として受付.
					m_sc_BackupTimeHour = option;
					m_us_HourInputDigit = PNLE_ServiceDataBackupAutoBackupTime_2_DIGIT;
				}
				else {
					// 何もしない.
				}
				break;

			// 上位桁入力済みの場合.
			case PNLE_ServiceDataBackupAutoBackupTime_1_DIGIT:
				{
					uchar uc_HourCheck = m_sc_BackupTimeHour;
					uc_HourCheck = static_cast<uchar>( uc_HourCheck * 10 + option );		// 入力済みの上位桁と入力値を結合.
					if( 23 >= uc_HourCheck ) {						// 結合結果が0～23の場合は受付.
						m_sc_BackupTimeHour = uc_HourCheck;
						m_us_HourInputDigit = PNLE_ServiceDataBackupAutoBackupTime_2_DIGIT;
					}
					else {										// 範囲外の場合は拒否音.
						setBuzzerType( PCGE_BuzzerType_InputNg );
					}
				}
				break;
			// 入力済みの場合.
			default:
				setBuzzerType( PCGE_BuzzerType_InputNg );
				break;
		}
	// 「分」を更新.
	}
	else if( 2 == m_uc_SelectInputButton ) {
		switch( m_us_MinuteInputDigit ) {
			// 未入力の場合.
			case PNLE_ServiceDataBackupAutoBackupTime_0_DIGIT:
				if( 5 >= option ) {									// 入力値が0～5の場合は上位桁として受付.
					m_sc_BackupTimeMinute = option;
					m_us_MinuteInputDigit = PNLE_ServiceDataBackupAutoBackupTime_1_DIGIT;
				}
				else if( 9 >= option ) {							// 入力値が6～9の場合は下位桁として受付.
					m_sc_BackupTimeMinute = option;
					m_us_MinuteInputDigit = PNLE_ServiceDataBackupAutoBackupTime_2_DIGIT;
				}
				else {
					// 何もしない.
				}
				break;
			// 上位桁入力済みの場合.
			case PNLE_ServiceDataBackupAutoBackupTime_1_DIGIT:
				{
					uchar uc_MinuteCheck = m_sc_BackupTimeMinute;
					uc_MinuteCheck = static_cast<uchar>( uc_MinuteCheck * 10 + option );	// 入力済みの上位桁と入力値を結合.
					if( 59 >= uc_MinuteCheck ) {					// 結合結果が0～59の場合は受付.
						m_sc_BackupTimeMinute = uc_MinuteCheck;
						m_us_MinuteInputDigit = PNLE_ServiceDataBackupAutoBackupTime_2_DIGIT;
					}
					else {											// 範囲外の場合は拒否音.
						setBuzzerType( PCGE_BuzzerType_InputNg );
					}
				}
				break;
			// 入力済みの場合.
			default:
				setBuzzerType( PCGE_BuzzerType_InputNg );
				break;
		}
	}
	else if( 0 == m_uc_SelectInputButton ) {
		switch( m_us_CycleInputDigit ) {
			// 未入力の場合.
			case PNLE_ServiceDataBackupAutoBackupTime_0_DIGIT:
				if( ( 0 < option ) && ( 3 >= option ) ) {			// 入力値が1～3の場合は上位桁として受付.
					m_us_BackupCycle = option;
					m_us_CycleInputDigit = PNLE_ServiceDataBackupAutoBackupTime_1_DIGIT;
				}
				else if( ( 9 >= option ) && ( 0 != option ) ) {		// 入力値が4～9の場合は下位桁として受付.
					m_us_BackupCycle = option;
					m_us_CycleInputDigit = PNLE_ServiceDataBackupAutoBackupTime_2_DIGIT;
				}
				else {												// 範囲外の場合は拒否音.
					setBuzzerType( PCGE_BuzzerType_InputNg );
				}
				break;
			// 上位桁入力済みの場合.
			case PNLE_ServiceDataBackupAutoBackupTime_1_DIGIT:
				{
					uchar uc_CycleCheck = static_cast<uchar>( m_us_BackupCycle );
					uc_CycleCheck = static_cast<uchar>( uc_CycleCheck * 10 + option );	// 入力済みの上位桁と入力値を結合.
					if( 30 >= uc_CycleCheck ) {						// 結合結果が1～30の場合は受付.
						m_us_BackupCycle = uc_CycleCheck;
						m_us_CycleInputDigit = PNLE_ServiceDataBackupAutoBackupTime_2_DIGIT;
					}
					else {											// 範囲外の場合は拒否音.
						setBuzzerType( PCGE_BuzzerType_InputNg );
					}
				}
				break;
			// 入力済みの場合.
			default:
				setBuzzerType( PCGE_BuzzerType_InputNg );
				break;
		}
	}
	else {
		// 何もしない.
	}

	// 画面更新を行う.
	setupGamen( option );
}

//================================================================================================.
// 概要		: PServiceDataBackupAutoBackupCom : ﾃﾞｰﾀﾊﾞｯｸｱｯﾌﾟ／自動ﾊﾞｯｸｱｯﾌﾟ共通クラス : クリアキー( K4B0021200画面とK4B0023710画面共用 ) .
// 戻り値	:なし.
// 備考		:.
//================================================================================================.
void PServiceDataBackupAutoBackupCom::procClear( uchar option )
{
// comment 2015/10/22 [CQ519830] 「しない」を選択している時は入力させない対応 日立 村上(幸).
	if( TYPE_BackupRestoreSetting_AutoBackupNone == m_e_AutoBackupType ) {
		setBuzzerType( PCGE_BuzzerType_InputNg );							// ブザー音セット.
		return;
	}

	if( 1 == m_uc_SelectInputButton ) {
		m_sc_BackupTimeHour = 0;		// 「時」を0にする.
		m_us_HourInputDigit = PNLE_ServiceDataBackupAutoBackupTime_0_DIGIT;
	}
	else if( 2 == m_uc_SelectInputButton ) {
		m_sc_BackupTimeMinute = 0;		// 「分」を0にする.
		m_us_MinuteInputDigit = PNLE_ServiceDataBackupAutoBackupTime_0_DIGIT;
	}
	else if( 0 == m_uc_SelectInputButton) {
		m_us_BackupCycle = 0;			// 日周期「日」を0にする.
		m_us_CycleInputDigit = PNLE_ServiceDataBackupAutoBackupTime_0_DIGIT;
	}
	else {
		// 何もしない.
	}

	// 画面更新を行う.
	setupGamen( option );
}

//================================================================================================.
// 概要		: PServiceDataBackupAutoBackupCom : ﾃﾞｰﾀﾊﾞｯｸｱｯﾌﾟ／自動ﾊﾞｯｸｱｯﾌﾟ共通クラス( K4B0021200画面とK4B0023710画面共用 ).
// 戻り値	:なし.
// 備考		:.
//================================================================================================.
void PServiceDataBackupAutoBackupCom::getSelectWeekdayBindKey()
{
	// バックアップ曜日によって、選択した曜日を設定する.
	switch( m_e_Weekday ) {
		// 日曜日.
		case TYPE_BackupRestoreSetting_WeekdaySun:
			m_uc_SelectWeekDay = PNLE_ServiceDataBackupAutoBackupSelectWeekdayKey_Sun;
			break;
		// 月曜日.
		case TYPE_BackupRestoreSetting_WeekdayMon:
			m_uc_SelectWeekDay = PNLE_ServiceDataBackupAutoBackupSelectWeekdayKey_Mon;
			break;
		// 火曜日.
		case TYPE_BackupRestoreSetting_WeekdayTue:
			m_uc_SelectWeekDay = PNLE_ServiceDataBackupAutoBackupSelectWeekdayKey_Tue;
			break;
		// 水曜日.
		case TYPE_BackupRestoreSetting_WeekdayWed:
			m_uc_SelectWeekDay = PNLE_ServiceDataBackupAutoBackupSelectWeekdayKey_Wed;
			break;
		// 木曜日.
		case TYPE_BackupRestoreSetting_WeekdayThu:
			m_uc_SelectWeekDay = PNLE_ServiceDataBackupAutoBackupSelectWeekdayKey_Thu;
			break;
		// 金曜日.
		case TYPE_BackupRestoreSetting_WeekdayFri:
			m_uc_SelectWeekDay = PNLE_ServiceDataBackupAutoBackupSelectWeekdayKey_Fri;
			break;
		// 土曜日.
		case TYPE_BackupRestoreSetting_WeekdaySat:
			m_uc_SelectWeekDay = PNLE_ServiceDataBackupAutoBackupSelectWeekdayKey_Sat;
			break;
		default:
			break;
	}
}

//================================================================================================.
// 概要		: PServiceDataBackupAutoBackupCom : ﾃﾞｰﾀﾊﾞｯｸｱｯﾌﾟ／自動ﾊﾞｯｸｱｯﾌﾟ共通クラス( K4B0021200画面とK4B0023710画面共用 ).
// 戻り値	:なし.
// 備考		:.
//================================================================================================.
void PServiceDataBackupAutoBackupCom::getWeekdayType( uchar option )
{
	// バックアップ曜日設定.
	switch( option ) {
		// 日曜日.
		case BTNID_KEY_ServiceBackupSetting_AutoBackupWeekdaySun:
			m_e_Weekday = TYPE_BackupRestoreSetting_WeekdaySun;
			break;
		// 月曜日.
		case BTNID_KEY_ServiceBackupSetting_AutoBackupWeekdayMon:
			m_e_Weekday = TYPE_BackupRestoreSetting_WeekdayMon;
			break;
		// 火曜日.
		case BTNID_KEY_ServiceBackupSetting_AutoBackupWeekdayTue:
			m_e_Weekday = TYPE_BackupRestoreSetting_WeekdayTue;
			break;
		// 水曜日.
		case BTNID_KEY_ServiceBackupSetting_AutoBackupWeekdayWed:
			m_e_Weekday = TYPE_BackupRestoreSetting_WeekdayWed;
			break;
		// 木曜日.
		case BTNID_KEY_ServiceBackupSetting_AutoBackupWeekdayThu:
			m_e_Weekday = TYPE_BackupRestoreSetting_WeekdayThu;
			break;
		// 金曜日.
		case BTNID_KEY_ServiceBackupSetting_AutoBackupWeekdayFri:
			m_e_Weekday = TYPE_BackupRestoreSetting_WeekdayFri;
			break;
		// 土曜日.
		case BTNID_KEY_ServiceBackupSetting_AutoBackupWeekdaySat:
			m_e_Weekday = TYPE_BackupRestoreSetting_WeekdaySat;
			break;
		default:
			break;
	}
}

