// 概要		: PServiceDataBackupHDDBackupMenu : K4B0021000_データバックアップ／HDDバックアップ:表示画面セットアップ.
// 戻り値	:なし.
// 備考		:.
//================================================================================================.
void PServiceDataBackupHDDBackupMenu::setupGamen( short option )
{
	PServiceNoFunctionCodeCom::setupGamen(option);

	Key_ServiceHDDBackupSetting.showEnable( True );						// ﾊﾞｯｸｱｯﾌﾟ設定キー表示.
	if( False == m_bl_ServerHDDBackupEnable ) {
		Key_ServiceHDDBackupAutoBackup.showEnable( False );				// 自動ﾊﾞｯｸｱｯﾌﾟキー非表示.
		Key_ServiceHDDBackupImmediateBackup.showEnable( False );		// 即時ﾊﾞｯｸｱｯﾌﾟキー非表示.
		Key_ServiceHDDBackupResult.showEnable( False );					// ﾊﾞｯｸｱｯﾌﾟ結果キー非表示.
	}
	else {
		if( True == m_bl_AdminHDDBackupEnable ) {
			Key_ServiceHDDBackupAutoBackup.showEnable( True );			// 自動ﾊﾞｯｸｱｯﾌﾟキー表示.
			Key_ServiceHDDBackupImmediateBackup.showEnable( False );	// 即時ﾊﾞｯｸｱｯﾌﾟキー非表示.
			Key_ServiceHDDBackupResult.showEnable( True );				// ﾊﾞｯｸｱｯﾌﾟ結果キー表示.
		}
		else {
			Key_ServiceHDDBackupAutoBackup.showEnable( True );			// 自動ﾊﾞｯｸｱｯﾌﾟキー表示.
			Key_ServiceHDDBackupImmediateBackup.showEnable( True );		// 即時ﾊﾞｯｸｱｯﾌﾟキー表示.
			Key_ServiceHDDBackupResult.showEnable( True );				// ﾊﾞｯｸｱｯﾌﾟ結果キー表示.
		}
	}
}
