// 2014/11/17 [MAv3][RQ-250] 機能カウンタ拡張 日立 村上(幸) .
// 機能概要: 顧客情報の登録・収集機能追加.
PNLE_ServiceCustomerInfoSetting		PServiceCustomerInfoSettingCom::m_e_CustomerInfoSettingGamen = PNLE_ServiceCustomerInfoSettingFunctionSet;
Bool	PServiceCustomerInfoSettingCom::m_bl_FunctionSetOffOn = False;
uchar	PServiceCustomerInfoSettingCom::m_uc_OrganizationScale = TYPE_OrganizationScaleNone;
uchar	PServiceCustomerInfoSettingCom::m_uc_TypeOfBusiness = TYPE_TypeOfBusinessNone;

//================================================================================================.
// 概要		: PServiceCustomerInfoSettingCom : サービス・セキュリティ設定／顧客情報設定 共通 : 画面開始処理.
// 備考		: なし.
//================================================================================================.
void PServiceCustomerInfoSettingCom::startGamen()
{

	// 親クラスを呼ぶ.
	PServiceNoFunctionCodeCom::startGamen();

	// メニューから呼ばれる場合はCommonAPIから全設定を読み込む。.
	if( True == m_bl_FromMenu ) {
		// 表示中画面のIndexを初期化する.
		m_e_CustomerInfoSettingGamen = PNLE_ServiceCustomerInfoSettingFunctionSet;

		// commonAPIから取得.
		m_uc_OrganizationScale = PnlComGetSystemSetting()->getAdminOrganizationScale();		// 企業規模.
		m_uc_TypeOfBusiness = PnlComGetSystemSetting()->getAdminTypeOfBusiness();			// 業種.

		m_bl_FromMenu = False;
		// 「業種」「従業員数」が"設定なし"の場合は「機能設定」をしないに設定する.
		if( (TYPE_OrganizationScaleNone == m_uc_OrganizationScale) && (TYPE_TypeOfBusinessNone == m_uc_TypeOfBusiness) ) {
			m_bl_FunctionSetOffOn = False;
		}
		else {
			m_bl_FunctionSetOffOn = True;
		}
	}

}
//================================================================================================.
// 概要		: PServiceCustomerInfoSettingCom : サービス・セキュリティ設定／顧客情報設定 共通 : 画面更新処理.
// 備考		: なし.
//================================================================================================.
void PServiceCustomerInfoSettingCom::setupGamen( short option )
{
	// 親クラスを呼ぶ.
	PServiceNoFunctionCodeCom::setupGamen();

	switch( m_e_CustomerInfoSettingGamen ){
		case PNLE_ServiceCustomerInfoSettingFunctionSet:				// 機能設定.
			Rbt_ServiceCustomerInfoSettingMenu.select( BTNID_ServiceCustomerInfoSettingFunctionSet );
			break;
		case PNLE_ServiceCustomerInfoSettingTypeOfBusiness:				// 業種.
			Rbt_ServiceCustomerInfoSettingMenu.select( BTNID_ServiceCustomerInfoSettingTypeOfBusiness );
			break;
		case PNLE_ServiceCustomerInfoSettingOrganizationScale:			// 従業員数.
			Rbt_ServiceCustomerInfoSettingMenu.select( BTNID_ServiceCustomerInfoSettingOrganizationScale );
			break;
		default: break;
	}
}

//================================================================================================.
// 概要		: PServiceCustomerInfoSettingCom : サービス・セキュリティ設定／顧客情報設定 共通：インデックスボタン処理.
// 備考		: なし.
//================================================================================================.
void PServiceCustomerInfoSettingCom::procIndexButton( uchar option )
{
	switch( option ) {
		// 機能設定.
		case BTNID_ServiceCustomerInfoSettingFunctionSet:
			m_e_CustomerInfoSettingGamen = PNLE_ServiceCustomerInfoSettingFunctionSet;
			nextGamen = &gp_ServiceCustomerInfoSettingFunctionSet;		// K4B0041000_セキュリティ設定／顧客情報設定.
			break;

		// 業種.
		case BTNID_ServiceCustomerInfoSettingTypeOfBusiness:
			m_e_CustomerInfoSettingGamen = PNLE_ServiceCustomerInfoSettingTypeOfBusiness;
			nextGamen = &gp_ServiceCustomerInfoSettingTypeOfBusiness;	// K4B0041100_セキュリティ設定／顧客情報設定／業種.
			break;

		// 従業員数.
		case BTNID_ServiceCustomerInfoSettingOrganizationScale:
			m_e_CustomerInfoSettingGamen = PNLE_ServiceCustomerInfoSettingOrganizationScale;
			nextGamen = &gp_ServiceCustomerInfoSettingOrganizationScale;// K4B0041200_セキュリティ設定／顧客情報設定／従業員数.
			break;

		default:
			break;
	}
}

