//================================================================================================.
// 概要		: PServiceCustomerInfoSettingFunctionSet : K4B0041000_セキュリティ設定／顧客情報設定 : 画面更新処理.
// 備考		: なし.
//================================================================================================.
void PServiceCustomerInfoSettingFunctionSet::setupGamen( short option )
{
	PServiceCustomerInfoSettingCom::setupGamen(option);
	Rbt_ServiceCustomerInfoSettingsSelect.select( True == m_bl_FunctionSetOffOn ? 0 : 1 );	// する/しない.

	// 「機能設定」がしないの場合、「業種」/「従業員数」キーを非表示に設定する.
	if( False == m_bl_FunctionSetOffOn ) {
		Key_ServiceCustomerInfoSettingTypeOfBusiness.showEnable( False );
		Key_ServiceCustomerInfoSettingOrganizationScale.showEnable( False );
	}
	// 「機能設定」がするの場合、「業種」/「従業員数」キーを表示に設定する.
	else {
		Key_ServiceCustomerInfoSettingTypeOfBusiness.showEnable( True );
		Key_ServiceCustomerInfoSettingOrganizationScale.showEnable( True );
	}
}

//================================================================================================.
// 概要		: PServiceCustomerInfoSettingFunctionSet : K4B0041000_セキュリティ設定／顧客情報設定 : 画面遷移処理.
// 備考		: なし.
//================================================================================================.
void PServiceCustomerInfoSettingFunctionSet::procButtonOn( uchar option )
{
	switch( option ) {
		// しない.
		case BTNID_ServiceCustomerInfoSettingFunctionSetOff:
			// 「しない」を選択する.
			m_bl_FunctionSetOffOn = False;
			break;

		// する.
		case BTNID_ServiceCustomerInfoSettingFunctionSetOn:
			// 「する」を選択する.
			m_bl_FunctionSetOffOn = True;
			break;

		default:
			break;
	}
	setupGamen( option );
}

//================================================================================================.
// 概要		: PServiceCustomerInfoSettingTypeOfBusiness : K4B0041100_セキュリティ設定／顧客情報設定／業種 : 画面描画処理 .
// 備考		: なし.
//================================================================================================.
void PServiceCustomerInfoSettingTypeOfBusiness::setupGamen( short option )
{
	// 親クラスを呼ぶ.
	PServiceCustomerInfoSettingCom::setupGamen( option );

	short ss_select = -1;											// 選択値.
	switch( m_uc_TypeOfBusiness ) {
		case	TYPE_TypeOfBusinessManufacturing :					// 製造業.
			ss_select = PNLD_ServiceCustomerInfoSettingTypeOfBusinessManufacturing;
			break;
		case	TYPE_TypeOfBusinessIT :								// IT関連業.
			ss_select = PNLD_ServiceCustomerInfoSettingTypeOfBusinessIT;
			break;
		case	TYPE_TypeOfBusinessFinance_Securities_Insurance :	// 金融/証券/保険業.
			ss_select = PNLD_ServiceCustomerInfoSettingTypeOfBusinessFinance_Securities_Insurance;
			break;
		case	TYPE_TypeOfBusinessPublicOffice :					// 官公庁.
			ss_select = PNLD_ServiceCustomerInfoSettingTypeOfBusinessPublicOffice;
			break;
		case	TYPE_TypeOfBusinessDistribution_Service :			// 流通/サービス業.
			ss_select = PNLD_ServiceCustomerInfoSettingTypeOfBusinessDistribution_Service;
			break;
		case	TYPE_TypeOfBusinessOther :							// その他.
			ss_select = PNLD_ServiceCustomerInfoSettingTypeOfBusinessBusinessOther;
			break;
		default:
			break;
	}

	Rbt_ServiceCustomerInfoSettingTypeOfBusinesses.select( ss_select );	// 業種.
}

//================================================================================================.
// 概要		: PServiceCustomerInfoSettingTypeOfBusiness : K4B0041100_セキュリティ設定／顧客情報設定／業種 : キー押下処理 .
// 備考		: なし.
//================================================================================================.
void PServiceCustomerInfoSettingTypeOfBusiness::procButtonOn( uchar option )
{
	// 親クラスを呼ぶ.
	PServiceCustomerInfoSettingCom::procButtonOn( option );

	switch( option ) {
		// 製造業.
		case BTNID_ServiceCustomerInfoSettingTypeOfBusinessManufacturing:
			// 「製造業」を選択する.
			m_uc_TypeOfBusiness = ( TYPE_TypeOfBusinessManufacturing == m_uc_TypeOfBusiness ? TYPE_TypeOfBusinessNone : TYPE_TypeOfBusinessManufacturing );
			break;

		// IT関連業.
		case BTNID_ServiceCustomerInfoSettingTypeOfBusinessIT:
			// 「IT関連業」を選択する.
			m_uc_TypeOfBusiness = ( TYPE_TypeOfBusinessIT == m_uc_TypeOfBusiness ? TYPE_TypeOfBusinessNone : TYPE_TypeOfBusinessIT );
			break;

		// 金融/証券/保険業.
		case BTNID_ServiceCustomerInfoSettingTypeOfBusinessFinance_Securities_Insurance:
			// 「金融/証券/保険業」を選択する.
			m_uc_TypeOfBusiness = ( TYPE_TypeOfBusinessFinance_Securities_Insurance == m_uc_TypeOfBusiness ? TYPE_TypeOfBusinessNone : TYPE_TypeOfBusinessFinance_Securities_Insurance );
			break;

		// 官公庁.
		case BTNID_ServiceCustomerInfoSettingTypeOfBusinessPublicOffice:
			// 「官公庁」を選択する.
			m_uc_TypeOfBusiness = ( TYPE_TypeOfBusinessPublicOffice == m_uc_TypeOfBusiness ? TYPE_TypeOfBusinessNone : TYPE_TypeOfBusinessPublicOffice );
			break;

		// 流通/サービス業.
		case BTNID_ServiceCustomerInfoSettingTypeOfBusinessDistribution_Service:
			// 「流通/サービス業」を選択する.
			m_uc_TypeOfBusiness = ( TYPE_TypeOfBusinessDistribution_Service == m_uc_TypeOfBusiness ? TYPE_TypeOfBusinessNone : TYPE_TypeOfBusinessDistribution_Service );
			break;

		// その他.
		case BTNID_ServiceCustomerInfoSettingTypeOfBusinessOther:
			// 「その他」を選択する.
			m_uc_TypeOfBusiness = ( TYPE_TypeOfBusinessOther == m_uc_TypeOfBusiness ? TYPE_TypeOfBusinessNone : TYPE_TypeOfBusinessOther );
			break;

		default:
			// 上記以外の場合は「設定無し」にする.
			m_uc_TypeOfBusiness = TYPE_TypeOfBusinessNone;
			break;
	}
	setupGamen( option );
}

