			m_uc_OrganizationScale = ( TYPE_OrganizationScale101To500 == m_uc_OrganizationScale ? TYPE_OrganizationScaleNone : TYPE_OrganizationScale101To500 );
			break;
		// 501～1000名.
		case BTNID_ServiceCustomerInfoSettingOrganizationScale501to1000:
