void PServiceCertificateSettingCom::procGoToPage( uchar option )
{
	switch( option ) {
	// 次へキー.
	case BTNID_ServiceSetupWizard_Next:
		nextGamen = &gp_ServiceDateTimeInput;					// 工場調整・日付・時刻データ入力 .
		break;
	// 前へキー.
	case BTNID_ServiceSetupWizard_Back:
		nextGamen = &gp_ServiceListOutput1;						// リスト出力・リスト出力1.
		break;
	// ｻｰﾋﾞｽキー.
	case BTNID_ServiceSetupWizard_Service:
		setSetupWizardMode( False );							// セットアップウィザードモード解除.
		nextGamen = &gp_ServiceMenu;							// サービス・メニュー.
		break;
	default:
		break;
	}
}

