//================================================================================================.
// 概要		: PServiceCertificateSettingImport : サービス・セキュリティ設定／FW証明書設定 インポート: ボタン押下.
// 備考		: なし.
//================================================================================================.
void PServiceCertificateSettingImport::procButtonOn( uchar option )
{
	// 親クラスを呼ぶ.
	PServiceCertificateSettingCom::procButtonOn( option );
	
	switch( option ) {
	case BTNID_ServiceCertificateSettingImportStart:
		if( True == APIC_InternetISW::newInstance()->importCertForFwVerification() ) {		// インポート実施.
			m_e_ImportResult = PNLE_ServiceCertificate_ImportResult_ImportOk;				// 結果OK.
		}
		else {
			m_e_ImportResult = PNLE_ServiceCertificate_ImportResult_ImportNg;				// 結果NG.
		}
		break;
	default:
		break;
	}
	
	// 画面セットアップ.
	setupGamen( option );
}

