//================================================================================================.
// 概要		: PServiceCertificateSettingImport : サービス・セキュリティ設定／FW証明書設定 共通: 画面開始処理.
// 備考		: なし.
//================================================================================================.
void PServiceCertificateSettingImport::startGamen( void )
{
	// 親クラスを呼ぶ.
	PServiceCertificateSettingCom::startGamen();
	
	if( True == getSetupWizardMode() ) {			// セットアップウィザードモード中のとき.
		Key_OkService.showEnable( False );									// 「OK」キー非表示.
		Key_NextSetupWizard.showEnable( True );								// 「次へ」キー表示.
		Key_BackSetupWizard.showEnable( True );								// 「前へ」キー表示.
		Key_ServiceSetupWizard.showEnable( True );							// 「ｻｰﾋﾞｽ」キー表示.
		Txt_ServiceSetupWizard.showEnable( True );							// ｾｯﾄｱｯﾌﾟｳｨｻﾞｰﾄﾞ表示.
		Txt_ServiceServiceCertificateSettingStepNum.showEnable( True );		// Step数表示.
		Gra_ServiceSetupWizardStep.showEnable( True );						// 枠表示.
	}
	else{
		Key_OkService.showEnable( True );									// 「OK」キー表示.
		Key_NextSetupWizard.showEnable( False );							// 「次へ」キー非表示.
		Key_BackSetupWizard.showEnable( False );							// 「前へ」キー非表示.
		Key_ServiceSetupWizard.showEnable( False );							// 「ｻｰﾋﾞｽ」キー非表示.
		Txt_ServiceSetupWizard.showEnable( False );							// ｾｯﾄｱｯﾌﾟｳｨｻﾞｰﾄﾞ非表示.
		Txt_ServiceServiceCertificateSettingStepNum.showEnable( False );	// Step数非表示.
		Gra_ServiceSetupWizardStep.showEnable( False );						// 枠非表示.
	}

	// インポート結果を初期化.
	m_e_ImportResult = PNLE_ServiceCertificate_ImportResult_NonResult;
	
	// 証明書ファイル登録.
	static PServiceUSBFileCheck::USBCheckFile st_usbCheckFiles[] = {
		{ PNLD_ServiceCertificateSettingCom_CertFileID , CERT4FWVERIFICATION , False , False }
	};

	// USBチェック初期化.
	static PDisplayParts* pUSBCheckShowEnableParts[] = {		// スタートキーと矢印を表示切替パーツに指定.
		&Key_ServiceCertificateSettingStart,
		&Ktx_ServiceServiceCertificateSettingDown,
	};
	gp_ServiceUSBFileCheck.setCheckFiles( &st_usbCheckFiles[0], sizeof(st_usbCheckFiles) / sizeof(st_usbCheckFiles[0]) );					// チェックするファイルを指定.
	gp_ServiceUSBFileCheck.setUSBStatusText( &Txt_CertificateSettingImportResult );															// USBの状態表示をするテキストを指定.
	gp_ServiceUSBFileCheck.setShowEnableParts( pUSBCheckShowEnableParts, sizeof( pUSBCheckShowEnableParts )/sizeof( PDisplayParts** ) );	// 表示パーツを指定.
	gp_ServiceUSBFileCheck.setEnableCheckFile( PNLD_ServiceCertificateSettingCom_CertFileID, True );										// ファイルチェックを有効化.
	
	Txt_CertificateSettingImportResult.resetParts();		// インポート結果表示を消す.
}

//================================================================================================.
// 概要		: PServiceCertificateSettingImport : サービス・セキュリティ設定／FW証明書設定 インポート: 画面セットアップ.
// 備考		: なし.
//================================================================================================.
void PServiceCertificateSettingImport::setupGamen( short option )
{
	// 親クラスを呼ぶ.
	PServiceCertificateSettingCom::setupGamen( option );
	
	if( ServiceUSBInfo_Uninsertion == gp_ServiceUSBFileCheck.checkOnly() ){			// USBが抜かれた際にインポート結果が残っていると表示がおかしくなるため.
		m_e_ImportResult = PNLE_ServiceCertificate_ImportResult_NonResult;			// インポート結果を初期化しUSB状態の判定を行う.
	}
	
	switch( m_e_ImportResult ){
	case PNLE_ServiceCertificate_ImportResult_NonResult:						// インポートを実施していないとき.
		gp_ServiceUSBFileCheck.checkAndShow();									// "USB NG","ファイル NG"表示判定および表示.
		break;
	case PNLE_ServiceCertificate_ImportResult_ImportOk:							// インポート結果がOKのとき.
		Txt_CertificateSettingImportResult.changeText( s_ServiceResultOK );		// "OK"表示.
		Txt_CertificateSettingImportResult.showEnable( True );					// USB接続状態ではテキストが非表示になってしまうため表示する.
		break;
	case PNLE_ServiceCertificate_ImportResult_ImportNg:							// インポート結果がNGのとき.
		Txt_CertificateSettingImportResult.changeText( s_ServiceResultNG );		// "NG"表示.
		Txt_CertificateSettingImportResult.showEnable( True );					// USB接続状態ではテキストが非表示になってしまうため表示する.
		break;
	default:
		break;
	}
}

