TYPE_BackupRestoreSettingExt_setBoxDocFormatResult PServiceDataBackupServerBackupMenu::m_e_FormatResult = TYPE_BackupRestoreSettingExt_setBoxDocFormatResult_NotChanged;
//================================================================================================.
// 概要		: PServiceDataBackupServerBackupMenu : K4B0023000_データバックアップ／サーバーバックアップ: 画面開始処理.
// 戻り値	:なし.
// 備考		:.
// comment 2016/ 1/ 5 [MAv4][RQ-505]ﾊﾞｯｸｱｯﾌﾟ機能強化 日立 村上(幸).
//================================================================================================.
void PServiceDataBackupServerBackupMenu::startGamen()
{
	TYPS_BackupRestoreExt_BackupSettingInfo st_SettingInfo;
	APIC_BackupRestoreSetting *pc_BackupRestoreSetting = APIC_BackupRestoreSetting::newInstance();
	APIC_BackupRestoreSettingExt *pc_BackupRestoreSettingExt = APIC_BackupRestoreSettingExt::newInstance();
//	if( NULL == pc_BackupRestoreSetting ) {
	if( ( NULL == pc_BackupRestoreSetting ) || ( NULL == pc_BackupRestoreSettingExt )) {
// Comment 2015/11/02 【ZeusS_ZX0】【HCL_Vasu】【制御構成変更_No.76-1】Adding Error Code macro.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//		if (NULL !=pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x1900650101557601 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" ); 
		return;
	}

// comment 2016/06/27 [MAv4][CQ531735] 1/2以上あいていない場合、ボタン無効化 日立 田中.
	APIC_BackupRestore *pc_BackupRestore = APIC_BackupRestore::newInstance();
	if( NULL == pc_BackupRestore ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "APIC_BackupRestore::newInstance() is NULL" ); 
		return;
	}

	PServiceNoFunctionCodeCom::startGamen();
//	m_bl_ServiceServerBackupEnable = pc_BackupRestoreSetting->getSVR_BackupRestoreSettingEnable( TYPE_BackupRestoreSetting_TypeServiceSetting );
	if( True == m_bl_FromMenu ) {
		m_bl_FromMenu = False;																															// 画面遷移元フラグをFalseに設定.
		// commonAPIから取得.
		m_e_ServerBackupSelect = pc_BackupRestoreSettingExt->getServerBackupSelect();																	// ﾊﾞｯｸｱｯﾌﾟの選択状態を取得.
// comment 2016/ 4/ 5 [MAv4][RQ-505]ﾊﾞｯｸｱｯﾌﾟ機能強化_KMﾌｫｰﾏｯﾄの配置変更 日立 村上(幸).
		m_e_BoxFormatSetting = pc_BackupRestoreSettingExt->getServerBackupBoxDocFormat();																// 現在のﾌｫｰﾏｯﾄの設定値を取得.
	}

// comment 2016/06/27 [MAv4][CQ531735] 1/2以上あいていない場合、KMフォーマットボタン非表示 日立 田中.
	if(	TYPE_BackupRestoreSettingExt_BoxDocFormat_KM != pc_BackupRestoreSettingExt->getServerBackupBoxDocFormat() ){
		m_bl_KMFormatButtonEnabled = pc_BackupRestore->checkIfKmFormatBackupEnable();
	}
	else{
		//KMフォーマット指定時は常に表示.
		m_bl_KMFormatButtonEnabled = True;
	}


	m_bl_Fixed = False;																																	// 確定キーフラグを初期化.
	m_bl_FormatSetting = False;																															// ﾌｫｰﾏｯﾄ設定の実施済みフラグを初期化.
	m_e_FormatResult = TYPE_BackupRestoreSettingExt_setBoxDocFormatResult_NotChanged;																	// 結果通知フラグを初期化.
	m_bl_HDDExist = PnlComGetHddInfo()->getHddExist();
	m_bl_ServiceServerBackupEnable = pc_BackupRestoreSetting->getSVR_BackupRestoreSettingEnable( TYPE_BackupRestoreSetting_TypeServiceSetting );		// ｻｰﾊﾞｰﾊﾞｯｸｱｯﾌﾟの使用設定を取得.
	pc_BackupRestoreSettingExt->getServerBackupSettingInfo(&st_SettingInfo);																			// 拡張ｻｰﾊﾞｰﾊﾞｯｸｱｯﾌﾟのデータ取得.
	m_bl_ServiceServerExtBackupEnable = st_SettingInfo.m_b_Enable;																						// 使用設定をクラス変数へ設定.
}
