void PServiceDataBackupServerBackupMenu::procGoToPage( uchar option )
{
// comment 2016/ 4/ 5 [MAv4][RQ-505]ﾊﾞｯｸｱｯﾌﾟ機能強化_KMﾌｫｰﾏｯﾄの配置変更 日立 村上(幸).
	if( True == m_bl_Fixed ) {						// 確定キー押下状態であれば.
		// ブザー音を鳴動し、return.
		setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}
	switch( option ) {
		case BTNID_KEY_ServiceServerBackup_Setting:									// ﾊﾞｯｸｱｯﾌﾟ設定キー.
			gp_ServiceServerBackupSettingEnableSetting.setFromMenuFlg( True );
			nextGamen = &gp_ServiceServerBackupSettingEnableSetting;				// ﾃﾞｰﾀﾊﾞｯｸｱｯﾌﾟ／ｻｰﾊﾞｰﾊﾞｯｸｱｯﾌﾟ／ﾊﾞｯｸｱｯﾌﾟ設定／機能設定 画面.
			break;
		case BTNID_KEY_ServiceExtServerBackup_Setting:								// ﾊﾞｯｸｱｯﾌﾟ設定キー(拡張ｻｰﾊﾞｰﾊﾞｯｸｱｯﾌﾟ).
			gp_ServiceExtServerBackupSettingEnableSetting.setFromMenuFlg( True );
			nextGamen = &gp_ServiceExtServerBackupSettingEnableSetting;				// M0B0013000_拡張ｻｰﾊﾞｰﾊﾞｯｸｱｯﾌﾟ／ﾊﾞｯｸｱｯﾌﾟ設定／機能設定.
			break;
		case BTNID_KEY_ServiceServerBackup_AutoBackup:								// 自動ﾊﾞｯｸｱｯﾌﾟキー.
			gp_ServiceServerBackupAutoBackup.setFromMenuFlg( True );
			nextGamen = &gp_ServiceServerBackupAutoBackup;							// ﾃﾞｰﾀﾊﾞｯｸｱｯﾌﾟ／ｻｰﾊﾞｰﾊﾞｯｸｱｯﾌﾟ／自動ﾊﾞｯｸｱｯﾌﾟ 画面.
			break;
		case BTNID_KEY_ServiceExtServerBackup_AutoBackup:							// 自動ﾊﾞｯｸｱｯﾌﾟキー(拡張ｻｰﾊﾞｰﾊﾞｯｸｱｯﾌﾟ).
			gp_ServiceExtServerAutoBackupSettingEnableSetting.setFromMenuFlg( True );
			nextGamen = &gp_ServiceExtServerAutoBackupSettingEnableSetting;			// M0B0011000_拡張ｻｰﾊﾞｰﾊﾞｯｸｱｯﾌﾟ／自動ﾊﾞｯｸｱｯﾌﾟ画面.
			break;
		case BTNID_KEY_ServiceServerBackup_ImmediateBackup:							// 即時ﾊﾞｯｸｱｯﾌﾟキー.
			nextGamen = &gp_ServiceServerBackupImmediateBackup;						// ﾃﾞｰﾀﾊﾞｯｸｱｯﾌﾟ／ｻｰﾊﾞｰﾊﾞｯｸｱｯﾌﾟ／即時ﾊﾞｯｸｱｯﾌﾟ 画面.
			break;
		case BTNID_KEY_ServiceServerBackup_Result:									// ﾊﾞｯｸｱｯﾌﾟ結果キー.
			nextGamen = &gp_ServiceServerBackupResult;								// ﾃﾞｰﾀﾊﾞｯｸｱｯﾌﾟ／ｻｰﾊﾞｰﾊﾞｯｸｱｯﾌﾟ／ﾊﾞｯｸｱｯﾌﾟ結果 画面.
			break;
		case BTNID_KEY_ServiceExtServerBackup_Reserve:								// ﾊﾞｯｸｱｯﾌﾟ予約キー.
			nextGamen = &gp_ServiceExtServerBackupReserve;							// M0B0012000_拡張ｻｰﾊﾞｰﾊﾞｯｸｱｯﾌﾟ／ﾊﾞｯｸｱｯﾌﾟ予約画面.
			break;
		case BTNID_KEY_ServiceExtServerBackup_History:								// ﾊﾞｯｸｱｯﾌﾟ履歴キー.
			nextGamen = &gp_ServiceExtServerBackupHistory;							// M0B0013000_拡張ｻｰﾊﾞｰﾊﾞｯｸｱｯﾌﾟ／ﾊﾞｯｸｱｯﾌﾟ履歴画面.
			break;
		default:
			break;
	}
}
