void PServiceDataBackupServerBackupMenu::setupGamen( short option )
{
	PServiceNoFunctionCodeCom::setupGamen(option);
// comment 2016/ 1/ 5 [MAv4][RQ-505]ﾊﾞｯｸｱｯﾌﾟ機能強化 日立 村上(幸).
	PServiceExtServerBackupSettingInfo* pc_ExtBackupSettingInfo = PServiceExtServerBackupSettingInfo::newInstance();
	if( NULL == pc_ExtBackupSettingInfo ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
//	// 機能設定が「使用する」.
//	Key_GoToServerBackupSetting.showEnable( True );					// ﾊﾞｯｸｱｯﾌﾟ設定キー表示.
//
//	if( True == m_bl_ServiceServerBackupEnable ) {
//		Key_GoToServerBackupAutoBackup.showEnable( True );			// 自動ﾊﾞｯｸｱｯﾌﾟキー表示.
//		Key_GoToServerBackupImmediateBackup.showEnable( True );		// 即時ﾊﾞｯｸｱｯﾌﾟキー表示.
//		Key_GoToServerBackupResult.showEnable( True );				// ﾊﾞｯｸｱｯﾌﾟ結果キー表示.
//	}
//	else {
//		Key_GoToServerBackupAutoBackup.showEnable( False );			// 自動ﾊﾞｯｸｱｯﾌﾟキー非表示.
//		Key_GoToServerBackupImmediateBackup.showEnable( False );	// 即時ﾊﾞｯｸｱｯﾌﾟキー非表示.
//		Key_GoToServerBackupResult.showEnable( False );				// ﾊﾞｯｸｱｯﾌﾟ結果キー非表示.
//	}
	if( TYPE_BackupRestoreSelect_None == m_e_ServerBackupSelect ) {							// 使用しないを選択時.
		Grp_ServiceDataBackupServerBackupMenu_SrvBkup.showEnable( False );					// ｻｰﾊﾞｰﾊﾞｯｸｱｯﾌﾟ用のグループパーツ.
		Grp_ServiceDataBackupServerBackupMenu_ExtSrvBkup.showEnable( False );				// 拡張ｻｰﾊﾞｰﾊﾞｯｸｱｯﾌﾟ用のグループパーツ.
		Rbt_ServiceDataBackupServerBackupMode.select( 0 );									// 使用しないを選択状態に変更.
	} else if( TYPE_BackupRestoreSelect_Backup == m_e_ServerBackupSelect ) {				// ｻｰﾊﾞｰﾊﾞｯｸｱｯﾌﾟを選択.
		Grp_ServiceDataBackupServerBackupMenu_ExtSrvBkup.showEnable( False );				// 拡張ｻｰﾊﾞｰﾊﾞｯｸｱｯﾌﾟ用のグループパーツ.
		Grp_ServiceDataBackupServerBackupMenu_SrvBkup.showEnable( True );					// ｻｰﾊﾞｰﾊﾞｯｸｱｯﾌﾟ用のグループパーツ.
		Rbt_ServiceDataBackupServerBackupMode.select( 1 );									// ｻｰﾊﾞｰﾊﾞｯｸｱｯﾌﾟを選択状態に変更.
		// 機能設定が使用しないの時、各キーを非表示.
		Key_GoToServerBackupAutoBackup.showEnable( m_bl_ServiceServerBackupEnable );		// 自動ﾊﾞｯｸｱｯﾌﾟキー表示/非表示.
		Key_GoToServerBackupImmediateBackup.showEnable( m_bl_ServiceServerBackupEnable );	// 即時ﾊﾞｯｸｱｯﾌﾟキー表示/非表示.
		Key_GoToServerBackupResult.showEnable( m_bl_ServiceServerBackupEnable );			// ﾊﾞｯｸｱｯﾌﾟ結果キー表示/非表示.
	} else {																				// その他(拡張ｻｰﾊﾞｰﾊﾞｯｸｱｯﾌﾟを選択).
		Grp_ServiceDataBackupServerBackupMenu_SrvBkup.showEnable( False );					// ｻｰﾊﾞｰﾊﾞｯｸｱｯﾌﾟ用のグループパーツ.
		Grp_ServiceDataBackupServerBackupMenu_ExtSrvBkup.showEnable( True );				// 拡張ｻｰﾊﾞｰﾊﾞｯｸｱｯﾌﾟ用のグループパーツ.
		Rbt_ServiceDataBackupServerBackupMode.select( 2 );									// 拡張ｻｰﾊﾞｰﾊﾞｯｸｱｯﾌﾟを選択状態に変更.
		// 機能設定が使用しないの時、各キーを非表示.
		Key_GoToExtServerBackupAutoBackup.showEnable( m_bl_ServiceServerExtBackupEnable );	// 自動ﾊﾞｯｸｱｯﾌﾟキーを表示/非表示.
		Key_GoToExtServerBackupReserve.showEnable( m_bl_ServiceServerExtBackupEnable );		// ﾊﾞｯｸｱｯﾌﾟ予約キーを表示/非表示.
		Key_GoToExtServerBackupHistory.showEnable( m_bl_ServiceServerExtBackupEnable );		// ﾊﾞｯｸｱｯﾌﾟ履歴キーを表示/非表示.
	}
// comment 2016/ 4/ 5 [MAv4][RQ-505]ﾊﾞｯｸｱｯﾌﾟ機能強化_KMﾌｫｰﾏｯﾄの配置変更 日立 村上(幸).
	// ﾌｫｰﾏｯﾄキー及び確定キーエリアの表示制御.
	setupGamenDisp();
}

// comment 2016/ 4/ 5 [MAv4][RQ-505]ﾊﾞｯｸｱｯﾌﾟ機能強化_KMﾌｫｰﾏｯﾄの配置変更 日立 村上(幸).
//================================================================================================.
// 概要		: PServiceDataBackupServerBackupMenu : K4B0023000_データバックアップ／サーバーバックアップ :確定キーエリア/ﾌｫｰﾏｯﾄキーの表示処理.
// 戻り値	:なし.
// 備考		:.
//================================================================================================.
void PServiceDataBackupServerBackupMenu::setupGamenDisp()
{
	Bool bl_RunningFlg = False;																										// 実行中の表示用フラグ.
	Bool bl_ResultFlg = False;																										// 結果の表示用フラグ.
	Bool bl_AllowFlg = False;																										// 矢印の表示用フラグ.
	Bool bl_OffOnFlg = False;																										// 主電源OFFONメッセージの表示用フラグ.
	// ﾌｫｰﾏｯﾄキーの表示非表示制御.
	if( ( TYPE_BackupRestoreSelect_BackupExt == m_e_ServerBackupSelect )															// 拡張ｻｰﾊﾞｰへﾊﾞｯｸｱｯﾌﾟの場合.
	 && ( True == m_bl_HDDExist ) ) {																								// 且つHDD装着.
		Key_ServiceServerBackup_BoxFormat_KM.showEnable( m_bl_KMFormatButtonEnabled );

	 	Txt_ServiceServerBackup_BoxFormat.showEnable( True );																		// ﾌｫｰﾏｯﾄ_タイトルを表示.
		Rbt_ServiceServerBackup_BoxFormat.showEnable( True );																		// ﾌｫｰﾏｯﾄキーの表示.
		Rbt_ServiceServerBackup_BoxFormat.select( (TYPE_BackupRestoreSettingExt_BoxDocFormat_General == m_e_BoxFormatSetting) ? 0 : 1 );
	} else {
	 	Txt_ServiceServerBackup_BoxFormat.showEnable( False );																		// ﾌｫｰﾏｯﾄ_タイトルを非表示.
		Rbt_ServiceServerBackup_BoxFormat.showEnable( False );																		// ﾌｫｰﾏｯﾄキーの非表示.
	}
	// 確定キーエリアの表示/非表示制御.
	Key_ServiceServerBackup_BoxFormat_Fix.select( m_bl_Fixed );																		// 確定キーの押下状態を更新.

	// それぞれの状態により、各表示用フラグを変更することでキーの表示非表示を実施.
	if( False == m_bl_FormatSetting ) {																								// ﾌｫｰﾏｯﾄ設定の変更実施済みの場合(確定キーを押下済み).
		// 未実施(確定キー押下前).
		bl_RunningFlg	 = False;																									// 実行中を非表示.
		bl_AllowFlg		 = False;																									// 矢印を非表示.
		bl_ResultFlg	 = False;																									// 結果を非表示.
		bl_OffOnFlg		 = False;																									// 主電源メッセージを非表示.
	} else if( True == m_bl_Fixed ){																							// 確定キー押下中.
		// 実施中又は設定変更成功.
		switch( m_e_FormatResult ) {
			case TYPE_BackupRestoreSettingExt_setBoxDocFormatResult_OK:															// 成功.
				// 設定変更成功のため、主電源OFF/ON必須.
				bl_RunningFlg	 = False;																							// 実行中を非表示.
				bl_AllowFlg		 = True;																							// 矢印を表示.
				bl_ResultFlg	 = True;																							// 結果を表示.
				bl_OffOnFlg		 = True;																							// 主電源メッセージを表示.
				Txt_ServiceServerBackup_BoxFormat_Fix_Result.changeText( s_ServiceMemoryCheck_OK );									// OKにメッセージを変更.
				break;
			case TYPE_BackupRestoreSettingExt_setBoxDocFormatResult_NG:															// 失敗.
				// 設定変更失敗のため、主電源OFF/ON必須.
				bl_RunningFlg	 = False;																							// 実行中を非表示.
				bl_AllowFlg		 = True;																							// 矢印を表示.
				bl_ResultFlg	 = True;																							// 結果を表示.
				bl_OffOnFlg		 = True;																							// 主電源メッセージを表示.
				Txt_ServiceServerBackup_BoxFormat_Fix_Result.changeText( s_ServiceMemoryCheck_NG );									// NGを表示.
				break;
			case TYPE_BackupRestoreSettingExt_setBoxDocFormatResult_NotChanged:													// 変更なし.
				bl_RunningFlg	 = True;																							// 実行中を表示.
				bl_AllowFlg		 = True;																							// 矢印を表示.
				bl_ResultFlg	 = False;																							// 結果を非表示.
				bl_OffOnFlg		 = False;																							// 主電源メッセージを非表示.
				Txt_ServiceServerBackup_BoxFormat_Fix_Progress.changeText( True == m_bl_FormatToggle ? s_EXPSlash : s_EXPBackslash );	// 「／」「＼」を交互に表示.
				m_bl_FormatToggle = ( ( True == m_bl_FormatToggle ) ? False : True );													// 切り替えするためにTrue→False→Trueと変更.
				break;
			default:	break;																									// その他.
		}
	} else {
		// "OK"を表示(再起動不要).
		switch( m_e_FormatResult ) {
			case TYPE_BackupRestoreSettingExt_setBoxDocFormatResult_OK:																// 成功.
				break;
			case TYPE_BackupRestoreSettingExt_setBoxDocFormatResult_NotChanged:														// 変更なし.
				// ﾊﾞｯｸｱｯﾌﾟ選択のみを変更した場合.
				bl_RunningFlg	 = False;																							// 実行中を非表示.
				bl_AllowFlg		 = True;																							// 矢印を表示.
				bl_ResultFlg	 = True;																							// 結果を表示.
				bl_OffOnFlg		 = False;																							// 主電源メッセージを非表示.
				Txt_ServiceServerBackup_BoxFormat_Fix_Result.changeText( s_ServiceMemoryCheck_OK );									// OKを表示.
				break;
			case TYPE_BackupRestoreSettingExt_setBoxDocFormatResult_NG:																// 失敗.
				break;
			default:	break;																									// その他.
		}
	}
	Txt_ServiceServerBackup_BoxFormat_Fix_OffOnMsg.showEnable( bl_OffOnFlg );														// 「主電源をOFF/ONしてください」を表示.
	Txt_ServiceServerBackup_BoxFormat_Fix_Result.showEnable( bl_ResultFlg );														// 結果(OK/NG)を表示.
	Txt_ServiceServerBackup_BoxFormat_Fix_Progress.showEnable( bl_RunningFlg );														// 「／」「＼」テキストを表示.
	Txt_ServiceServerBackup_BoxFormat_Fix_ResultArrow.showEnable( bl_AllowFlg );													// 矢印を表示.
}
