// comment 2016/ 1/ 5 [MAv4][RQ-505]ﾊﾞｯｸｱｯﾌﾟ機能強化 日立 村上(幸).
//================================================================================================.
// 概要		: PServiceDataBackupServerBackupMenu : K4B0023000_データバックアップ／サーバーバックアップ: キー押下.
// 戻り値	:なし.
// 備考		:.
//================================================================================================.
void PServiceDataBackupServerBackupMenu::procButtonOn( uchar uc_option)
{
// comment 2016/ 4/ 5 [MAv4][RQ-505]ﾊﾞｯｸｱｯﾌﾟ機能強化_KMﾌｫｰﾏｯﾄの配置変更 日立 村上(幸).
	Bool bl_ret = False;
// comment 2016/3/18 [MAv4][CQ526141]ﾊﾞｯｸｱｯﾌﾟ選択状態を未確定だと、バックアップ予約が「予約済み」にならない 日立 村上(幸).
	APIC_BackupRestoreSettingExt *pc_BackupRestoreSettingExt = APIC_BackupRestoreSettingExt::newInstance();
	if( NULL == pc_BackupRestoreSettingExt ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); 
		return;
	}
	if( True == m_bl_Fixed ) {						// 確定キー押下状態であれば.
		// ブザー音を鳴動し、return.
		setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}
	switch( uc_option ) {
		case BTNID_KEY_ServiceServerBackupMode_UnUse:				// 使用しない.
			m_e_ServerBackupSelect = TYPE_BackupRestoreSelect_None;
			break;
		case BTNID_KEY_ServiceServerBackupMode_SrvBackUp:			// ｻｰﾊﾞｰﾊﾞｯｸｱｯﾌﾟ.
			m_e_ServerBackupSelect = TYPE_BackupRestoreSelect_Backup;
			break;
		case BTNID_KEY_ServiceServerBackup_ExtSrvBackUp:			// 拡張ｻｰﾊﾞｰﾊﾞｯｸｱｯﾌﾟ.
			m_e_ServerBackupSelect = TYPE_BackupRestoreSelect_BackupExt;
			break;
		case BTNID_KEY_ServiceServerBackup_BoxFormat_General:			// 汎用ﾌｫｰﾏｯﾄキー.
			m_e_BoxFormatSetting = TYPE_BackupRestoreSettingExt_BoxDocFormat_General;			// 汎用ﾌｫｰﾏｯﾄに設定.
			break;
		case BTNID_KEY_ServiceServerBackup_BoxFormat_KM:				// KMﾌｫｰﾏｯﾄキー.
			m_e_BoxFormatSetting = TYPE_BackupRestoreSettingExt_BoxDocFormat_KM;				// KMﾌｫｰﾏｯﾄに設定.
			break;
		case BTNID_KEY_ServiceServerBackup_BoxFormat_Fix:				// 確定キー.
			// ﾊﾞｯｸｱｯﾌﾟ選択が"使用しない"/"ｻｰﾊﾞｰﾊﾞｯｸｱｯﾌﾟ"の場合は、"汎用ﾌｫｰﾏｯﾄ"で設定更新を実施.
			// そのため、拡張ｻｰﾊﾞｰﾊﾞｯｸｱｯﾌﾟ且つKMﾌｫｰﾏｯﾄを選択「以外」の時、"汎用ﾌｫｰﾏｯﾄ"に変更して設定更新.
			if( ( TYPE_BackupRestoreSettingExt_BoxDocFormat_KM == m_e_BoxFormatSetting ) 		// KMﾌｫｰﾏｯﾄ選択.
			 && ( TYPE_BackupRestoreSelect_BackupExt == m_e_ServerBackupSelect )				// 且つ拡張ｻｰﾊﾞｰﾊﾞｯｸｱｯﾌﾟの時.
			 ) {
				// KMﾌｫｰﾏｯﾄで設定更新。既に設定済みなので特に何もしない.
			} else {
				// 汎用ﾌｫｰﾏｯﾄで設定更新.
				m_e_BoxFormatSetting = TYPE_BackupRestoreSettingExt_BoxDocFormat_General;
			}
			bl_ret = pc_BackupRestoreSettingExt->setServerBackupBoxDocFormat( m_e_BoxFormatSetting, ans_BoxFormatSetting );
			if( True == bl_ret ) {																// 成功であれば.
				m_bl_Fixed = True;																// 確定キーを押下状態(操作パネル不能状態)に変更.
				m_bl_FormatSetting = True;														// 設定変更フラグを実施済みに変更.
				onlyPanel.bl_PowerOffOnMesage = True;											// 主電源OFF/ON画面から遷移させないためのフラグ.
				// 画面遷移禁止用のフラグをONにした時、警告発生すると強制的にturnGamenへ画面遷移するため、turnGamenをNULLに設定.
				// ｻｰﾋﾞｽの共通クラス(PServiceCom::endGamen)で画面移動時にturnGamenを設定し直すため、Null設定でも問題無し.
				turnGamen = NULL;
			} else {
				// 失敗の時はブザー音を鳴動.
				setBuzzerType( PCGE_BuzzerType_InputNg );
			}
			break;
		default:
			break;
	}

	setupGamen( uc_option );
}
