//================================================================================================.
// 概要		: PServiceDataBackupServerBackupMenu : K4B0023000_データバックアップ／サーバーバックアップ :コールバック処理.
// 戻り値	:なし.
// 備考		:.
//================================================================================================.
void PServiceDataBackupServerBackupMenu::procCallBack( TYPE_PNL_CallBack e_option )
{
	APIC_BackupRestoreSettingExt *pc_BackupRestoreSettingExt = APIC_BackupRestoreSettingExt::newInstance();
	if( NULL == pc_BackupRestoreSettingExt ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); 
		return;
	}

	if( TYPE_PNL_CallBack_BoxFormatChangeResult == e_option ) {
		if( TYPE_BackupRestoreSettingExt_setBoxDocFormatResult_OK == m_e_FormatResult ){					// 成功の場合.
			// 再起動が必要となるため、引き続きパネル操作不能状態とする.
			m_bl_Fixed = True;
			pc_BackupRestoreSettingExt->setServerBackupSelect( m_e_ServerBackupSelect );					// ﾊﾞｯｸｱｯﾌﾟ選択状態を設定.
		} else if( TYPE_BackupRestoreSettingExt_setBoxDocFormatResult_NotChanged == m_e_FormatResult ){		// 変更なしの場合.
			// 再起動が不要のため、パネル操作可能状態に変更.
			m_bl_Fixed = False;
			onlyPanel.bl_PowerOffOnMesage = False;															// 主電源OFF/ON画面から遷移させないためのフラグ.
			pc_BackupRestoreSettingExt->setServerBackupSelect( m_e_ServerBackupSelect );					// ﾊﾞｯｸｱｯﾌﾟ選択状態を設定.
		} else {																							// 失敗.
			// 再起動が必要となるため、引き続きパネル操作不能状態とする.
			m_bl_Fixed = True;
		}
	}
}
//================================================================================================.
// 概要		: PServiceDataBackupServerBackupMenu : K4B0023000_データバックアップ／サーバーバックアップ :フォーマット変更の応答処理.
// 戻り値	:なし.
// 備考		:.
//================================================================================================.
void PServiceDataBackupServerBackupMenu::ans_BoxFormatSetting(TYPE_BackupRestoreSettingExt_setBoxDocFormatResult e_FortmatResult)
{
	m_e_FormatResult = e_FortmatResult;									// 結果を保存.
	CallBackIndi( TYPE_PNL_CallBack_BoxFormatChangeResult );			// コールバックをコール.
}


PNLE_ServiceDataBackupServerBackup	PServiceServerBackupSettingCom::m_e_ServerBackupSettingGamen = PNLE_ServiceDataBackupServerBackup_EnableSetting;
//================================================================================================.
// 概要		: PServiceServerBackupSettingCom : データバックアップ／サーバーバックアップ 共通 : 画面更新処理.
// 戻り値	:なし.
// 備考		:.
//================================================================================================.
void PServiceServerBackupSettingCom::setupGamen( short option )
{
	// 親クラスを呼ぶ.
	PServiceNoFunctionCodeCom::setupGamen();

	switch( m_e_ServerBackupSettingGamen ) {
		case PNLE_ServiceDataBackupServerBackup_EnableSetting:			// 機能設定.
			Rbt_ServiceServerBackupSettingMenu.select( 0 );
			break;
		case PNLE_ServiceDataBackupServerBackup_Protocol:				// 送信ﾌﾟﾛﾄｺﾙ.
			Rbt_ServiceServerBackupSettingMenu.select( 1 );
			break;
		case PNLE_ServiceDataBackupServerBackup_SMBHostName:			// SMB設定 - ホスト名.
			Rbt_ServiceServerBackupSettingMenu.select( 2 );
			Rbt_ServiceServerBackupSettingSMBMenu.select( 0 );
			break;
		case PNLE_ServiceDataBackupServerBackup_SMBFilePath:			// SMB設定 - ファイルパス.
			Rbt_ServiceServerBackupSettingMenu.select( 2 );
			Rbt_ServiceServerBackupSettingSMBMenu.select( 1 );
			break;
		case  PNLE_ServiceDataBackupServerBackup_SMBUserName:			// SMB設定 - ユーザー名.
			Rbt_ServiceServerBackupSettingMenu.select( 2 );
			Rbt_ServiceServerBackupSettingSMBMenu.select( 2 );
			break;
		case  PNLE_ServiceDataBackupServerBackup_SMBPassword:			// SMB設定 - パスワード.
			Rbt_ServiceServerBackupSettingMenu.select( 2 );
			Rbt_ServiceServerBackupSettingSMBMenu.select( 3 );
			break;
		case PNLE_ServiceDataBackupServerBackup_HTTPURL:				// HTTP設定 - URL.
			Rbt_ServiceServerBackupSettingMenu.select( 3 );
			Rbt_ServiceServerBackupSettingHTTPMenu.select( 0 );
			break;
		case PNLE_ServiceDataBackupServerBackup_HTTPUserName:			// HTTP設定 - ユーザー名.
			Rbt_ServiceServerBackupSettingMenu.select( 3 );
			Rbt_ServiceServerBackupSettingHTTPMenu.select( 1 );
			break;
		case PNLE_ServiceDataBackupServerBackup_HTTPPassword:			// HTTP設定 - パスワード.
			Rbt_ServiceServerBackupSettingMenu.select( 3 );
			Rbt_ServiceServerBackupSettingHTTPMenu.select( 2 );
			break;
		case PNLE_ServiceDataBackupServerBackup_HTTPProxy:				// HTTP設定 - プロキシ.
			Rbt_ServiceServerBackupSettingMenu.select( 3 );
			Rbt_ServiceServerBackupSettingHTTPMenu.select( 3 );
			break;
		case PNLE_ServiceDataBackupServerBackup_Target:					// ﾊﾞｯｸｱｯﾌﾟ対象.
			Rbt_ServiceServerBackupSettingMenu.select( 4 );
			break;
		case PNLE_ServiceDataBackupServerBackup_EncryptionPassword:		// 暗号化ﾊﾟｽﾜｰﾄﾞ.
			Rbt_ServiceServerBackupSettingMenu.select( 5 );
			break;
		default: break;
	}
}
