// 概要		: PServiceServerBackupSettingEnableSetting : K4B0023110_サーバーバックアップ／バックアップ設定／機能設定 : 画面開始処理.
// 戻り値	:なし.
// 備考		:.
//================================================================================================.
void PServiceServerBackupSettingEnableSetting::startGamen()
{
	// 親クラスを呼ぶ.
	PServiceServerBackupSettingCom::startGamen();

	PLBC_DataBackupSettings *pc_DataBackupSettings = PLBC_DataBackupSettings::getInstance();

	if( NULL == pc_DataBackupSettings ) {
// Comment 2015/11/02 【ZeusS_ZX0】【HCL_Vasu】【制御構成変更_No.76-1】Adding Error Code macro.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//		if (NULL !=pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x1900650101557801 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}

	// メニューから呼ばれる場合はCommonAPIから全設定を読み込む.
	if( True == m_bl_FromMenu ) {
		// 表示中画面のIndexを初期化する.
		m_e_ServerBackupSettingGamen = PNLE_ServiceDataBackupServerBackup_EnableSetting;
		// commonAPIから取得.
		pc_DataBackupSettings->loadServerBackupSettingService();
		m_bl_FromMenu = False;
	}

	// ｻｰﾊﾞｰバックアップ機能の使用設定を取得.
	m_bl_EnableSettingOffOn = pc_DataBackupSettings->getBackupRestoreSettingEnable();

}

//================================================================================================.
// 概要		: PServiceServerBackupSettingEnableSetting : K4B0023110_サーバーバックアップ／バックアップ設定／機能設定 :  画面更新処理.
// 戻り値	:なし.
// 備考		:.
//================================================================================================.
void PServiceServerBackupSettingEnableSetting::setupGamen( short option )
{
	// 親クラスを呼ぶ.
	PServiceServerBackupSettingCom::setupGamen( option );

	if( True == PnlComGetSystemSetting()->getSecurityLevelUpOn() ) {
		// セキュリティ強化モードONの場合は、使用するキー非表示.
		Key_ServiceServerBackupSettingEnableSelectOn.showEnable( False );
	}
	else {
		// セキュリティ強化モードOFFの場合は、使用するキー表示.
		Key_ServiceServerBackupSettingEnableSelectOn.showEnable( True );
	}

	// 使用する/使用しない.
	Rbt_ServiceServerBackupSettingEnableSelect.select( ( True == m_bl_EnableSettingOffOn ) ? 0 : 1);

	Key_ServiceServerBackupSettingServerProtocol.showEnable( m_bl_EnableSettingOffOn );
	Key_ServiceServerBackupSettingSMBSetting.showEnable( m_bl_EnableSettingOffOn );
	Key_ServiceServerBackupSettingHTTPSetting.showEnable( m_bl_EnableSettingOffOn );
	Key_ServiceServerBackupSettingBackupTarget.showEnable( m_bl_EnableSettingOffOn );
	Key_ServiceServerBackupSettingEncryptionPassword.showEnable( m_bl_EnableSettingOffOn );
}
//================================================================================================.
// 概要		: PServiceServerBackupSettingEnableSetting : K4B0023110_サーバーバックアップ／バックアップ設定／機能設定 :  画面遷移処理.
// 戻り値	:なし.
// 備考		:.
//================================================================================================.
void PServiceServerBackupSettingEnableSetting::procButtonOn( uchar option )
{
	PLBC_DataBackupSettings *pc_DataBackupSettings = PLBC_DataBackupSettings::getInstance();

	if( NULL == pc_DataBackupSettings ) {
// Comment 2015/11/02 【ZeusS_ZX0】【HCL_Vasu】【制御構成変更_No.76-1】Adding Error Code macro.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//		if (NULL !=pc_BFW_System){
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19000A0101557901);
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}

	// 親クラスを呼ぶ.
	PServiceServerBackupSettingCom::procButtonOn( option );

	switch( option ) {
		// 使用する.
		case BTNID_KEY_ServiceServerBackup_EnableSetting_On:
			// 選択中を「使用する」にする.
			m_bl_EnableSettingOffOn = True;
			pc_DataBackupSettings->setBackupRestoreSettingEnable( True );
			break;
		// 使用しない.
		case BTNID_KEY_ServiceServerBackup_EnableSetting_Off:
			// 選択中を「使用しない」にする.
			m_bl_EnableSettingOffOn = False;
			pc_DataBackupSettings->setBackupRestoreSettingEnable( False );
			break;
		default:
			break;
	}

	setupGamen( option );
}

