// 戻り値	:なし.
// 備考		:.
//================================================================================================.
void PServiceServerBackupSettingHttpProxy::procButtonOn( uchar option )
{
	PLBC_DataBackupSettings *pc_DataBackupSettings = PLBC_DataBackupSettings::getInstance();
	if( NULL == pc_DataBackupSettings ) {
//	comment 2015/11/03 HCL_Vinothini [ZeusS_ZX0][制御構成変更_No.76-1] Adding error code.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//		if ( NULL != pc_BFW_System ) {
//    		pc_BFW_System -> registDetailCode(PNLD_DetailCode_Service_0x19000A0101101B01);
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}

	// 親クラスを呼ぶ.
	PServiceServerBackupSettingCom::procButtonOn( option );

	switch( option ) {
		case BTNID_KEY_ServiceServerBackupHttpProxy_On:
			// 選択中を「する」にする.
			m_bl_ProxyOffOn = True;
			pc_DataBackupSettings->setServerBackupForHTTPProxyOffOn( m_bl_ProxyOffOn );
			break;
		case BTNID_KEY_ServiceServerBackupHttpProxy_Off:
			// 選択中を「しない」にする.
			m_bl_ProxyOffOn = False;
			pc_DataBackupSettings->setServerBackupForHTTPProxyOffOn( m_bl_ProxyOffOn );
			break;
		default:
			break;
	}
	setupGamen( option );
}
