void PServiceServerBackupSettingBackupTarget::procGoToPage( uchar option )
{
	Bool bl_selectTargetNone = True;
	for( int i = 0; i < PNLD_ServiceSettingBackupTarget_SelectButtonNum; i++ ) {
		if( m_bl_SelectList[i] == True ) {
			bl_selectTargetNone = False;
		}
	}

	// ﾊﾞｯｸｱｯﾌﾟ対象選択なしの場合は画面遷移しない.
	if( True == bl_selectTargetNone ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );	// ブザー音セット.
		return;
	}

	// 親クラスを呼ぶ.
	PServiceServerBackupSettingCom::procGoToPage( option );
}

