//================================================================================================.
void PServiceServerBackupSettingEncryptionPasswordInput::startGamen()
{
	PLBC_DataBackupSettings *pc_DataBackupSettings = PLBC_DataBackupSettings::getInstance();
	if( NULL == pc_DataBackupSettings ) {
//	comment 2015/11/03 HCL_Vinothini [ZeusS_ZX0][制御構成変更_No.76-1] Adding error code.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//		if ( NULL != pc_BFW_System ) {
//    		pc_BFW_System -> registDetailCode(PNLD_DetailCode_Service_0x1900650101101F01);
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}

// comment 2015/10/13 [CQ518790] 暗号化ﾊﾟｽﾜｰﾄﾞの2度入力対応 日立 村上(幸).
//	// データクラスからパスワードを取得する.
//	memcpy( m_sc_StrKeyboard, pc_DataBackupSettings->getServerBackUpEncryptionPassword(), sizeof( m_sc_StrKeyboard ) );
	memset( m_sc_StrKeyboard, '\0', sizeof( m_sc_StrKeyboard ) ); 	// パスワード入力用文字列をクリア.
	// 表示領域に文字列をセット.
	setKeyboardData( m_sc_StrKeyboard, PNLD_MAX_ServiceDataBackupServerBackupEncryptionPasswordChar , PNLD_ServiceDataBackupServerBackupInputWidth );
	m_bl_Password = True;
	m_bl_ShowPass = True;
// comment 2015/10/13 [CQ518790] 暗号化ﾊﾟｽﾜｰﾄﾞの2度入力対応 日立 村上(幸).
	m_us_dispErrMessage = s_Space1;								// エラーメッセージをクリア.
	m_uc_nowMessage = PNLD_ServiceServerBackupFirstInput;		// 新ﾊﾟｽﾜｰﾄﾞ入力状態に設定.

	// 親クラスを呼ぶ.
	PServiceDataBackupKeyboardCom::startGamen();

	Kbd_ServiceInputKeybord.setKeybord5Country( True );
// comment 2015/10/13 [CQ518790] 暗号化ﾊﾟｽﾜｰﾄﾞの2度入力対応 日立 村上(幸).
//	Kbd_ServiceInputKeybord.GetCursor( &Btx_ServiceDataBackupKeyboardComInput );
	Kbd_ServiceInputKeybord.GetCursor( &Btx_ServiceDataBackupKeyboardComInput2 );
	Kbd_ServiceInputKeybord.showKeybord();
}
//================================================================================================.
// 概要		: PServiceServerBackupSettingEncryptionPasswordInput : K4B0023620_サーバーバックアップ／バックアップ設定／暗号化パスワード入力 :  画面更新処理 .
// 戻り値	:なし.
// 備考		:.
//================================================================================================.
void PServiceServerBackupSettingEncryptionPasswordInput::setupGamen( short ss_option )
{
	// 親クラスを呼ぶ.
	PServiceDataBackupKeyboardCom::setupGamen( ss_option );
// comment 2015/10/13 [CQ518790] 暗号化ﾊﾟｽﾜｰﾄﾞの2度入力対応 日立 村上(幸).
	// 表示メッセージの変更.
	switch( m_uc_nowMessage ) {
		case PNLD_ServiceServerBackupFirstInput:	Txt_ServiceServerBackupSettingPassword.changeText( s_ITMServiceNewPassword ); break;		// 新しいパスワード入力.
		case PNLD_ServiceServerBackupSecondInput:	Txt_ServiceServerBackupSettingPassword.changeText( s_ITMServiceReinputPassword ); break;	// 再入力パスワード.
		default: break;
	}
	Txt_ServiceRelayServerHTTPAuthPasswordErrMessage.changeText( m_us_dispErrMessage );		// エラーメッセージ.

	// 入力禁止文字の非表示.
	Kbd_ServiceInputKeybord.setDisableKeyCharCode( KC_DisableKeyPattern15 );	// パターン15("ユーロ記号).
}
