//================================================================================================.
// 概要		: PServiceServerBackupSettingEncryptionPasswordInput : K4B0023620_サーバーバックアップ／バックアップ設定／暗号化パスワード入力 :  OKキー押下処理 .
// 戻り値	:なし.
// 備考		:.
//================================================================================================.
void PServiceServerBackupSettingEncryptionPasswordInput::procOk( uchar uc_option )
{
	PLBC_DataBackupSettings *pc_DataBackupSettings = PLBC_DataBackupSettings::getInstance();
	if( NULL == pc_DataBackupSettings ) {
//	comment 2015/11/03 HCL_Vinothini [ZeusS_ZX0][制御構成変更_No.76-1] Adding error code.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//		if ( NULL != pc_BFW_System ) {
//    		pc_BFW_System -> registDetailCode(PNLD_DetailCode_Service_0x1900030101102001);
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}

// comment 2015/10/13 [CQ518790] 暗号化ﾊﾟｽﾜｰﾄﾞの2度入力対応 日立 村上(幸).
//	// 暗号化ﾊﾟｽﾜｰﾄﾞ保存.
//	pc_DataBackupSettings->setServerBackUpEncryptionPassword( m_sc_StrKeyboard );
//	nextGamen = &gp_ServiceServerBackupSettingEncryptionPassword;
	switch( m_uc_nowMessage ) {
		case PNLD_ServiceServerBackupFirstInput: // 新しいパスワード入力.
			// 入力されたパスワードをチェックして、以下の条件に当てはまれば使用不可パスワード.
			if( strlen( m_sc_StrKeyboard ) != 0 ) {			// パスワード文字列が0で無ければ OK.
				m_uc_nowMessage = PNLD_ServiceServerBackupSecondInput;						// 再入力状態に変更.
				memset( m_sc_newPassword, '\0', sizeof( m_sc_newPassword ) );
				memcpy( m_sc_newPassword, m_sc_StrKeyboard, sizeof( m_sc_newPassword ) ); 	// 新パスワードを一時保存.
				m_us_dispErrMessage = s_Space1;												//エラーメッセージをクリア.
			} else {
				setBuzzerType( PCGE_BuzzerType_InputNg );
				m_us_dispErrMessage = s_SSNewPassWordMissteke;								//「入力したﾊﾟｽﾜｰﾄﾞは使用できません」.
			}
			memset( m_sc_StrKeyboard, '\0', sizeof( m_sc_StrKeyboard ) ); 					// パスワード入力用文字列をクリア.
			// スライド文字列管理クラスの初期化.
			m_c_SlideTextMgr.init_CLCD( m_sc_StrKeyboard, m_sc_KeyboardWidth, m_ss_MaxInputNum, m_pc_DispField, getCharSetForPanel() );
			break;
		case PNLD_ServiceServerBackupSecondInput: // 再入力パスワード.
			if( strcmp( m_sc_newPassword, m_sc_StrKeyboard ) == 0 ) {							// 1回目の入力とのチェック.
				pc_DataBackupSettings->setServerBackUpEncryptionPassword( m_sc_newPassword );	// 暗号化パスワードを保存.
				nextGamen = &gp_ServiceServerBackupSettingEncryptionPassword;
			} else {
				setBuzzerType( PCGE_BuzzerType_InputNg );
				m_uc_nowMessage = PNLD_ServiceServerBackupFirstInput;							// 新ﾊﾟｽﾜｰﾄﾞ入力状態に設定.
				// 入力文字列に新しいパスワードを設定し、新しいパスワード入力に戻る.
// comment 2015/11/23 【HCL-Surajit】【CQ519679】Klockwork Changes [ID: 33334 ] [ABV.MEMBER].
//				memcpy( m_sc_StrKeyboard, m_sc_newPassword, sizeof( m_sc_StrKeyboard ) );
// comment 2015/12/23 【HCL-Jeevitha】【CQ-519679】Klockwork Changes 【ID:33334】 [ABV.MEMBER].
//				memcpy( m_sc_StrKeyboard, m_sc_newPassword, sizeof( m_sc_StrKeyboard ) -1 );
				memcpy( m_sc_StrKeyboard, m_sc_newPassword, sizeof( m_sc_newPassword ) -1 );
				// スライド文字列管理クラスの初期化.
				m_c_SlideTextMgr.init_CLCD( m_sc_StrKeyboard, m_sc_KeyboardWidth, m_ss_MaxInputNum, m_pc_DispField, getCharSetForPanel() );
			}
			break;
		default: break;
	}
	setupGamen(uc_option);
}

