//================================================================================================.
// 概要		: PServiceServerBackupAutoBackup : K4B0023710_サーバーバックアップ／自動バックアップ: 画面開始処理.
// 戻り値	:なし.
// 備考		:.
//================================================================================================.
void PServiceServerBackupAutoBackup::startGamen()
{
	// 親クラスを呼ぶ.
	PServiceDataBackupAutoBackupCom::startGamen();

	PLBC_DataBackupSettings *pc_DataBackupSettings = PLBC_DataBackupSettings::getInstance();
	if( NULL == pc_DataBackupSettings ) {
//	comment 2015/11/03 HCL_Vinothini [ZeusS_ZX0][制御構成変更_No.76-1] Adding error code.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//		if ( NULL != pc_BFW_System ) {
//    		pc_BFW_System -> registDetailCode(PNLD_DetailCode_Service_0x1900650101102101);
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}

	// メニューから呼ばれる場合はCommonAPIから全設定を読み込む.
	if( True == m_bl_FromMenu ) {
		pc_DataBackupSettings->loadServerAutoBackupService();
		m_bl_FromMenu = False;
	}

	// ﾃﾞｰﾀﾊﾞｯｸｱｯﾌﾟを取得.
	m_e_AutoBackupType = pc_DataBackupSettings->getAutoBackup();

	// バックアップ個別周期を取得.
	m_us_BackupCycle = pc_DataBackupSettings->getAutoBackupCycle();

	// バックアップ曜日を取得.
	m_e_Weekday = pc_DataBackupSettings->getAutoBackupWeekday();

	getSelectWeekdayBindKey();
	// バックアップ時刻を取得.
	pc_DataBackupSettings->getAutoBackupTime( &m_sc_BackupTimeHour, &m_sc_BackupTimeMinute );

	// 時／分／日を入力済みに初期化する.
	m_us_HourInputDigit = PNLE_ServiceDataBackupAutoBackupTime_2_DIGIT;
	m_us_MinuteInputDigit = PNLE_ServiceDataBackupAutoBackupTime_2_DIGIT;
	m_us_CycleInputDigit = PNLE_ServiceDataBackupAutoBackupTime_2_DIGIT;
}

//================================================================================================.
// 概要		: PServiceServerBackupAutoBackup : K4B0023710_サーバーバックアップ／自動バックアップ : Ok押下処理.
// 戻り値	:なし.
// 備考		:.
//================================================================================================.
void PServiceServerBackupAutoBackup::procOk( uchar option )
{
	PLBC_DataBackupSettings *pc_DataBackupSettings = PLBC_DataBackupSettings::getInstance();
	if( NULL == pc_DataBackupSettings ) {
//	comment 2015/11/03 HCL_Vinothini [ZeusS_ZX0][制御構成変更_No.76-1] Adding error code.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//		if ( NULL != pc_BFW_System ) {
//    		pc_BFW_System -> registDetailCode(PNLD_DetailCode_Service_0x1900030101102201);
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}

	if( TYPE_BackupRestoreSetting_AutoBackupNone == m_e_AutoBackupType ) {
		pc_DataBackupSettings->setAutoBackup( m_e_AutoBackupType );
	}
	else if( TYPE_BackupRestoreSetting_AutoBackupCycle == m_e_AutoBackupType ) {
		// 範囲外、未入力の場合は画面遷移しない.
		if( ( PNLE_ServiceDataBackupAutoBackupMaxHour < m_sc_BackupTimeHour )
		||  ( PNLE_ServiceDataBackupAutoBackupMaxMinute < m_sc_BackupTimeMinute )
		||  ( PNLE_ServiceDataBackupAutoBackupMaxCycle < m_us_BackupCycle )				// 限界値チェック.
	    ||	( PNLE_ServiceDataBackupAutoBackupTime_2_DIGIT != m_us_HourInputDigit ) 		//「時」入力済みチェック.
	    ||	( PNLE_ServiceDataBackupAutoBackupTime_2_DIGIT != m_us_MinuteInputDigit )		//「分」入力済みチェック.
	    ||  ( PNLE_ServiceDataBackupAutoBackupTime_0_DIGIT == m_us_CycleInputDigit ) ) {	//「日」入力済みチェック.
			MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
			return;
		}
		pc_DataBackupSettings->setAutoBackup( m_e_AutoBackupType );
		pc_DataBackupSettings->setAutoBackupCycle( m_us_BackupCycle );
		pc_DataBackupSettings->setAutoBackupTime( m_sc_BackupTimeHour, m_sc_BackupTimeMinute );
	}
	else {
		// 範囲外、未入力の場合は画面遷移しない.
		if( ( PNLE_ServiceDataBackupAutoBackupMaxHour < m_sc_BackupTimeHour )
		||  ( PNLE_ServiceDataBackupAutoBackupMaxMinute < m_sc_BackupTimeMinute )			// 限界値チェック.
	    ||	( PNLE_ServiceDataBackupAutoBackupTime_2_DIGIT != m_us_HourInputDigit ) 		//「時」入力済みチェック.
	    ||	( PNLE_ServiceDataBackupAutoBackupTime_2_DIGIT != m_us_MinuteInputDigit ) ) {	//「分」入力済みチェック.
			MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
			return;
		}

		pc_DataBackupSettings->setAutoBackup( m_e_AutoBackupType );
		pc_DataBackupSettings->setAutoBackupWeekday( m_e_Weekday );
		pc_DataBackupSettings->setAutoBackupTime( m_sc_BackupTimeHour, m_sc_BackupTimeMinute );
	}

	// commonAPIに登録.
	pc_DataBackupSettings->comitServerAutoBackupService();

	//「K4B0023000 ﾃﾞｰﾀﾊﾞｯｸｱｯﾌﾟ／ｻｰﾊﾞｰﾊﾞｯｸｱｯﾌﾟ」画面に遷移.
	nextGamen = &gp_ServiceDataBackupServerBackupMenu;
}

