{
	m_bl_FromMenu = bl_FromMenu;
}

//================================================================================================.
// 概要		:PServiceServerBackupImmediateBackup: K4B0023810_サーバーバックアップ／即時バックアップ：画面開始処理 .
// 戻り値	:なし.
// 備考		:なし.
//================================================================================================.
void PServiceServerBackupImmediateBackup::startGamen()
{
	// 親クラスを呼ぶ.
	PServiceNoFunctionCodeCom::startGamen();

	// 記号に初期化する.
	m_bl_start = False;
	m_bl_BackupRequest = False;
	m_bl_ServiceServerBackupEnd = False;
}

//================================================================================================.
// 概要		:PServiceServerBackupImmediateBackup: K4B0023810_サーバーバックアップ／即時バックアップ：キー押下処理.
// 戻り値	:なし.
// 備考		:なし.
//================================================================================================
void PServiceServerBackupImmediateBackup::procButtonOn( uchar option )
{
	if( True == m_bl_start ) {
		setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}

	APIC_BackupRestore *pc_BackupRestore = APIC_BackupRestore::newInstance();
	if( NULL == pc_BackupRestore ) {
//	comment 2015/11/03 HCL_Vinothini [ZeusS_ZX0][制御構成変更_No.76-1] Adding error code.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//		if ( NULL != pc_BFW_System ) {
//    		pc_BFW_System -> registDetailCode(PNLD_DetailCode_Service_0x19000A0101102301);
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" ); 
		return;
	}

	switch(option) {
		case  BTNID_KEY_ServiceHDDBackup_ImmediateBackup_Start:		// ｽﾀｰﾄキー.
			m_bl_start = True;
			onlyPanel.bl_PowerOffOnMesage = True;	// 主電源OFF/ON画面から遷移させないためのフラグ.
			turnGamen = NULL;
			m_bl_BackupRequest = pc_BackupRestore->startServerBackup(TYPE_ServerBackupRestoreModeService);
			if( False == m_bl_BackupRequest ) {
				// 異常ルート.
				m_bl_ServiceServerBackupEnd = True;
			}
			break;
		default:
			break;
	}

	setupGamen();
}

//================================================================================================.
// 概要		:PServiceServerBackupImmediateBackup: K4B0023810_サーバーバックアップ／即時バックアップ：画面更新処理.
// 戻り値	:なし.
// 備考		:なし.
// comment 2015/10/13 [CQ519799] ｻｰﾊﾞｰﾘｽﾄｱ時、NG発生した場合は主電源OFF/ONさせない 日立 村上(幸).
//================================================================================================.
void PServiceServerBackupImmediateBackup::setupGamen( short option )
{
	char	sc_Errorcode[PNLD_ErrorCodeLenMax + 1];

	memset(sc_Errorcode, 0x00, sizeof(sc_Errorcode));
	// 親クラスを呼ぶ.
	PServiceNoFunctionCodeCom::setupGamen();

	TEXT_ID	us_OkOrNgServiceTextId;

	Key_ServiceServerBackupImmediateStart.select( m_bl_start );

	if( False == m_bl_BackupRequest ) {
		if( False == m_bl_ServiceServerBackupEnd ) {
			// スタート未実施.
//			Txt_ServiceServerBackupStartDownArrow.showEnable( False );
			Txt_ServiceServerImmediateBackupActionSlash.showEnable( False );		// 「／」非表示.
			Txt_ServiceServerImmediateBackupResultStatus.showEnable( False );		// 実行中のテキスト非表示.
			Txt_ServiceServerImmediateBackupResultOKNG.showEnable( False );			// OK/NG用の表示テキスト非表示.
			Txt_TitleServiceServerBackupResult.showEnable( False );					// 結果タイトル非表示.
			Txt_ServiceServerBackupErrorCode.showEnable( False );					// エラーコード非表示.
// comment 2015/12/8 [ZeusS_ZX0][CQ522430] ｻｰﾊﾞｰﾘｽﾄｱ時、コロンが表示されない 日立 村上(幸).
			Txt_ServiceeServerBackupColon.showEnable( False );						// コロン非表示.
			Tfd_ServiceServerBackupErrorCodeVal.showEnable( False );				// エラーコード用文字列非表示.
		}
		else {
			// スタート要求が失敗時(異常ルート).
			onlyPanel.bl_PowerOffOnMesage = False;
			Txt_ServiceServerImmediateBackupActionSlash.showEnable( False );
//			Txt_ServiceServerImmediateBackupResultStatus.changeText( s_NGService );			// 「NG」.
//			Txt_ServiceServerBackupStartDownArrow.showEnable( True );
//			Txt_ServiceServerImmediateBackupResultStatus.showEnable( True );
			Txt_TitleServiceServerBackupResult.showEnable( True );						// 結果タイトル表示.
			Txt_ServiceServerImmediateBackupResultOKNG.changeText( s_NGService );		// OK/NG用の表示テキストをNGに変更.
			Txt_ServiceServerImmediateBackupResultOKNG.showEnable( True );				// OK/NG用の表示テキストを表示.
// comment 2015/12/8 [ZeusS_ZX0][CQ522430] ｻｰﾊﾞｰﾘｽﾄｱ時、コロンが表示されない 日立 村上(幸).
			Txt_ServiceeServerBackupColon.showEnable( True );							// コロン表示.
			// 異常ルート時は正常なデータを取得できないため、エラーコードを設定.
			strncpy(sc_Errorcode, "S99999", PNLD_ErrorCodeLenMax );						// 「エラーコード」.
			Txt_ServiceServerBackupErrorCode.showEnable( True );						// エラーコード表示.
			Tfd_ServiceServerBackupErrorCodeVal.changeExternalText(( uchar* )sc_Errorcode, sizeof(sc_Errorcode), getCharSetForPanel() );
			Tfd_ServiceServerBackupErrorCodeVal.showEnable( True );						// エラーコード用文字列表示.
		}
	}
	else {		// スタート要求時.
		if( False == m_bl_ServiceServerBackupEnd ) {
			// 完了待ち.
			static Bool bl_ServerBackupImmediateNow = False;
			Txt_ServiceServerImmediateBackupActionSlash.changeText( True == bl_ServerBackupImmediateNow ? s_EXPSlash : s_EXPBackslash );
			Txt_ServiceServerImmediateBackupActionSlash.showEnable( True );
			bl_ServerBackupImmediateNow = ( ( True == bl_ServerBackupImmediateNow ) ? False : True );	// 「／」「＼」を交互に表示.
//			Txt_ServiceServerImmediateBackupResultStatus.changeText( s_ITMServiceRunning );
			Txt_ServiceServerImmediateBackupResultStatus.showEnable( True );			// 実行中のテキスト表示.
		}
		else {	// 完了.
			Txt_ServiceServerImmediateBackupActionSlash.showEnable( False );
//			Txt_ServiceServerBackupStartDownArrow.showEnable( True );
			Txt_TitleServiceServerBackupResult.showEnable( True );						// 結果タイトル表示.
			Txt_ServiceServerImmediateBackupResultStatus.showEnable( False );			// 実行中のテキストを非表示.
			if( 0 == m_us_LogCount ) {
				us_OkOrNgServiceTextId = s_NGService;
			}
			else {
				// 直近の1件ログ結果を解析.
				// ログ情報は文字列として、以下の様に格納されている為.
				// YYYY/MM/DD hh:mm:ss,OK(NG),Xxxxxx.

				// ログから成功/失敗の判断を行う.
				if( NULL == strstr(m_psc_LogList[0], "OK") ) {	// 解析文字列に"OK"が含まれていない場合.
					// "NG"の場合はｴﾗｰｺｰﾄﾞ取得.
					int    sl_errorCodeCnt = 0;											// エラーコード用のカウント値.
					uchar  uc_CharNumber = 0;											// バックアップ結果用のカウント値.
					uchar  uc_CommaFlag = 0;											// カンマの位置を保持する変数.
					uchar  uc_TextLen = 0;												// ログ情報は文字列の長さ.

					uc_TextLen = (uchar)( strlen( m_psc_LogList[0] ) );
					for( uc_CharNumber = 0; uc_CharNumber < uc_TextLen; uc_CharNumber++ ) {
						// ','カウント.
						if( ',' == m_psc_LogList[0][uc_CharNumber] ) {					// 最新のバックアップ結果([0])をチェック.
							uc_CommaFlag++;
							continue;
						}
						if( PNLD_ServiceServerBackupResult_SecondComma == uc_CommaFlag ) {	// 2個目のカンマ(ｴﾗｰｺｰﾄﾞ)の場合.
							if(PNLD_ErrorCodeLenMax >= sl_errorCodeCnt) {
								sc_Errorcode[sl_errorCodeCnt++] = m_psc_LogList[0][uc_CharNumber];
							}
						}
					}
					us_OkOrNgServiceTextId = s_NGService;
				}
				else {
					us_OkOrNgServiceTextId = s_OKService;
				}
			}
//			Txt_ServiceServerImmediateBackupResultStatus.changeText( us_OkOrNgServiceTextId );	// 「OK/NG」.
			Txt_ServiceServerImmediateBackupResultOKNG.changeText( us_OkOrNgServiceTextId );	// OK/NG用の表示テキストを変更.
			Txt_ServiceServerImmediateBackupResultOKNG.showEnable( True );						// OK/NG用の表示テキストを表示.
			if( 0x00 != sc_Errorcode[0] ) {								// 何かしらデータが入っている場合.
				Txt_ServiceServerBackupErrorCode.showEnable( True );							// エラーコード表示.
// comment 2015/12/8 [ZeusS_ZX0][CQ522430] ｻｰﾊﾞｰﾘｽﾄｱ時、コロンが表示されない 日立 村上(幸).
				Txt_ServiceeServerBackupColon.showEnable( True );								// コロン表示.
				Tfd_ServiceServerBackupErrorCodeVal.changeExternalText(( uchar* )sc_Errorcode, sizeof(sc_Errorcode), getCharSetForPanel() );
				Tfd_ServiceServerBackupErrorCodeVal.showEnable( True );							// エラーコード用文字列表示.
			} else {
				Txt_ServiceServerBackupErrorCode.showEnable( False );							// エラーコード非表示.
// comment 2015/12/8 [ZeusS_ZX0][CQ522430] ｻｰﾊﾞｰﾘｽﾄｱ時、コロンが表示されない 日立 村上(幸).
				Txt_ServiceeServerBackupColon.showEnable( False );								// コロン非表示.
				Tfd_ServiceServerBackupErrorCodeVal.showEnable( False );						// エラーコード用文字列非表示.
			}
		}
//		Txt_ServiceServerBackupStartDownArrow.showEnable( True );
//		Txt_ServiceServerImmediateBackupResultStatus.showEnable( True );
	}
}
//================================================================================================.
// 概要		: PServiceServerBackupImmediateBackup: K4B0023810_サーバーバックアップ／即時バックアップﾟ: Ok押下処理.
// 戻り値	:なし.
// 備考		:.
//================================================================================================.
void PServiceServerBackupImmediateBackup::procOk( uchar option )
{
	if( ( True == m_bl_start ) && ( False == m_bl_ServiceServerBackupEnd ) ) {
		setBuzzerType( PCGE_BuzzerType_InputNg );
	}
	else {
		if( True == m_bl_ServiceServerBackupEnd ) {
			m_bl_ServiceServerBackupEnd = False;
		}

		//「K4B0023000 ﾃﾞｰﾀﾊﾞｯｸｱｯﾌﾟ／ｻｰﾊﾞｰﾊﾞｯｸｱｯﾌﾟ」画面に遷移.
		nextGamen = &gp_ServiceDataBackupServerBackupMenu;
	}
}

//================================================================================================.
// 概要		: PServiceServerBackupImmediateBackup: K4B0023810_サーバーバックアップ／即時バックアップﾟ : リセットキー押下.
// 戻り値	:なし.
// 備考		:.
//================================================================================================.
void PServiceServerBackupImmediateBackup::procReset( uchar option )
{
	// ｽﾀｰﾄキー押下の場合、ブザー音を鳴動.
	if( ( True == m_bl_start ) && ( False == m_bl_ServiceServerBackupEnd ) ) {
		setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}
	else {
		if( True == m_bl_ServiceServerBackupEnd ) {
			m_bl_ServiceServerBackupEnd = False;
		}
	}
	// 親クラスを呼ぶ.
	PServiceNoFunctionCodeCom::procReset( option );
}
//================================================================================================.
// 概要		: PServiceServerBackupImmediateBackup: K4B0023810_サーバーバックアップ／即時バックアップﾟ : オブザーバー処理.
// 戻り値	:なし.
// 備考		:なし.
//================================================================================================.
void PServiceServerBackupImmediateBackup::procObserver( TYPE_PNL_Observer e_PNL_Observer )
{
	switch( e_PNL_Observer ) {
		case TYPE_PNL_Observer_ServiceServerBackupEnd:					// サーバーバックアップ完了.
			m_bl_ServiceServerBackupEnd = True;
			onlyPanel.bl_PowerOffOnMesage = False;
			// サーバーへバックアップ結果のログを取得.
			memset( m_psc_LogList, NULL, sizeof( m_psc_LogList ) );
			m_us_LogCount = APIC_BackupRestore::newInstance()->getLogData( TYPE_ServerBackupRestoreModeService, m_psc_LogList );
			break;
		default:														// その他は何もしない.
			PServiceNoFunctionCodeCom::procObserver( e_PNL_Observer );	// 継承元(親)のprocObserverを呼び出す.
			break;
	}
}

