// 概要		: PServiceServerBackupImmediateBackup: K4B0023810_サーバーバックアップ／即時バックアップﾟ : ラインキー.
// 戻り値	:なし.
// 備考		:なし.
//================================================================================================.
void PServiceServerBackupImmediateBackup::procGoToMag( uchar option )
{
	// ｽﾀｰﾄキー押下の場合、ブザー音を鳴動.
	if( ( True == m_bl_start ) && ( False == m_bl_ServiceServerBackupEnd ) ) {
		setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}
	PServiceNoFunctionCodeCom::procGoToMag( option );
}
//================================================================================================.
// 概要		:PServiceServerBackupResult : K4B0023910_サーバーバックアップ／バックアップ結果 : 初期設定.
// 戻り値	:なし.
// 備考		:.
//================================================================================================.
void PServiceServerBackupResult::startGamen()
{
	// 親クラスを呼ぶ.
	PServiceNoFunctionCodeCom::startGamen();

	APIC_BackupRestoreSetting *pc_BackupRestoreSetting = APIC_BackupRestoreSetting::newInstance();
	APIC_BackupRestore* pc_BackupRestore = APIC_BackupRestore::newInstance();
	if( NULL == pc_BackupRestoreSetting  || NULL == pc_BackupRestore) {
//	comment 2015/11/03 HCL_Vinothini [ZeusS_ZX0][制御構成変更_No.76-1] Adding error code.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//		if ( NULL != pc_BFW_System ) {
//    		pc_BFW_System -> registDetailCode(PNLD_DetailCode_Service_0x1900650101102501);
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" ); 
		return;
	}

	// サーバー最終バックアップ日を取得.
	pc_BackupRestoreSetting->getSVR_LastBackupDate( TYPE_BackupRestoreSetting_TypeServiceSetting, &m_c_timeDate );

	// サーバーバックアップ結果のログを取得.
	memset( m_p_LogList, NULL, sizeof( m_p_LogList ) );
	m_us_LogCount = pc_BackupRestore->getLogData( TYPE_ServerBackupRestoreModeService, m_p_LogList );
	m_ss_CurrentPage	= 1;
	m_ss_MaxPage		= 1;	
	// 総ページ数.
	if( 0 < m_us_LogCount ) {
		short ss_page = m_us_LogCount % PNLD_ServiceServerBackupResult_MaxLogAtPage;
		if( 0 == ss_page ) {
			m_ss_MaxPage = m_us_LogCount / PNLD_ServiceServerBackupResult_MaxLogAtPage;
		}
		else {
			m_ss_MaxPage = static_cast<short>( ( m_us_LogCount / PNLD_ServiceServerBackupResult_MaxLogAtPage ) + 1 );
		}
	}
}

