// 概要		:PServiceServerBackupResult : K4B0023910_サーバーバックアップ／バックアップ結果: 表示画面のセットアップ. 
// 戻り値	:なし.
// 備考		:.
//================================================================================================.
void PServiceServerBackupResult::setupGamen( short option )
{
	// 表示部品のセットアップ.
	PServiceNoFunctionCodeCom::setupGamen( option );

	// 日格納バッファ.
    char sc_DayTime[ PNLE_ServiceDataBackup_DayDisp_Max + 1 ];
    // 日格納バッファ初期化.
    memset( sc_DayTime, 0, sizeof( sc_DayTime ) );

	// 日付表示文字列取得.
	PLBC_DataBackupSettings::getInstance()->getDayTimeDisplay( m_c_timeDate, sc_DayTime );

	//最終バックアップ結果日時を表示.
	Tfd_ServiceServerBackupResultLastTime.changeTextString( ( const uchar* )sc_DayTime );

	// バックアップ結果のログ表示.
	getBackupResultLogDisplay();
}

//================================================================================================.
// 概要		: getBackupResultLogDisplay : K4B0023910_サーバーバックアップ／バックアップ結果 : バックアップ結果のログ表示.
// 戻り値	:なし.
// 備考		:.
// 履歴		: .
//  comment 2015.09.07 [CQ517699] ﾊﾞｯｸｱｯﾌﾟﾛｸﾞ表示データを1行毎の定義からパーツ毎の定義に変更する 日立 田中.
//================================================================================================.
void PServiceServerBackupResult::getBackupResultLogDisplay()
{
	ushort us_logNo = 0;				// ループカウンタ.
	short  ss_DataDispNum = 0;			// ログデータの番号(画面表示用の番号).

	char sc_LogExtraction[ PNLE_ServiceServerBackupResult_LogLineStrMax + 1 ];				// 抽出用(日付時刻、結果、エラーコード).
//	char sc_AdjustLogExtraction[ PNLE_ServiceServerBackupResult_LogBufferMax + 1 ];		// 調整用(日付時刻、結果、エラーコード).
	char sc_LogNumer[ PNLE_ServiceServerBackupResult_NumberChar + 1 ];		// ログ格納用(No).
	char sc_LogDayTime[ PNLE_ServiceServerBackupResult_LogLineStrMax + 1 ];	// ログ格納用(ﾊﾞｯｸｱｯﾌﾟ日時).
	char sc_LogResult[ PNLE_ServiceServerBackupResult_LogLineStrMax + 1 ];	// ログ格納用(結果).
	char sc_LogErrCode[ PNLE_ServiceServerBackupResult_LogLineStrMax + 1 ];	// ログ格納用(ｴﾗｰｺｰﾄﾞ).

	// ログ情報は文字列の
	ushort us_TextLen = 0;

	if( 0 < m_us_LogCount ) {
		// 現在のページのログ件数を取得.
		ushort us_MaxCount = 0;
		if( m_ss_CurrentPage < m_ss_MaxPage ) {
			// 現在のページ < 総ページ数の場合は、5件固定.
			us_MaxCount = PNLD_ServiceServerBackupResult_MaxLogAtPage;
		}
		else {
			us_MaxCount = m_us_LogCount % PNLD_ServiceServerBackupResult_MaxLogAtPage;
			if( 0 == us_MaxCount) {
				us_MaxCount = PNLD_ServiceServerBackupResult_MaxLogAtPage;
			}
		}

		// リスト描画(値設定).
		ushort	us_staIndex = static_cast<ushort>( PNLD_ServiceServerBackupResult_MaxLogAtPage * ( m_ss_CurrentPage - 1 ) );	// 開始位置のインデックス.
		ushort	us_endIndex = static_cast<ushort>( us_staIndex + us_MaxCount - 1 );												// 終了位置のインデックス.
		ushort	us_Pos = 0;																					// 描画対象位置.
		ushort	us_ItemPos = 0;

		// ログ情報は文字列として、以下の様に格納されている為.
		// YYYY/MM/DD hh:mm:ss, OK(NG), Xxxxxx.
		//for( us_logNo = 0; m_us_LogCount > us_logNo; us_logNo++ ) {
		for( us_logNo = us_staIndex; us_logNo < ( us_staIndex + PNLD_ServiceServerBackupResult_MaxLogAtPage ); us_logNo++ ) {
//			Tfd_ServiceServerBackupResultDisplay[ us_Pos ].showEnable( False );
			for( us_ItemPos = 0; us_ItemPos < PNLE_ServiceServerBackupResultDisplayItem_MAX; us_ItemPos++ ) {
				Tfd_ServiceServerBackupResultDisplay[ us_Pos ][ us_ItemPos ].showEnable( False );
			}
			if( us_logNo > us_endIndex ) {
				us_Pos++;
				continue;
			}
			// 格納先サイズが溢れる場合は処理しない.
			if( ( NULL == m_p_LogList[us_logNo] ) || ( strlen( m_p_LogList[us_logNo] )  > ( PNLE_ServiceServerBackupResult_LogLineStrMax - PNLE_ServiceServerBackupResult_NumberChar ) ) ) {
//	comment 2015/11/03 HCL_Vinothini [ZeusS_ZX0][制御構成変更_No.76-1] Adding error code.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//				LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//				if ( NULL != pc_BFW_System ) {
//    				pc_BFW_System ->registDetailCode(PNLD_DetailCode_Service_0x1900660101102601);
//				}
				LOGF_debug_PutEventLog(LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!");
				return;
			}

			ushort us_CharNumber = 0;
			ushort us_StartCharNumber = 0;
//			ushort us_AdjustCharNumber = 0;
			uchar uc_commaCnt = 0;
			ss_DataDispNum = static_cast<short>( us_logNo + 1 );		// 表示するデータの番号.
			memset( sc_LogExtraction, '\0', sizeof(sc_LogExtraction) );
//			memset( sc_AdjustLogExtraction, ' ', sizeof(sc_AdjustLogExtraction) );
			memset( sc_LogNumer, '\0', sizeof(sc_LogNumer) );
			memset( sc_LogDayTime, '\0', sizeof(sc_LogDayTime) );
			memset( sc_LogResult, '\0', sizeof(sc_LogResult) );
			memset( sc_LogErrCode, '\0', sizeof(sc_LogErrCode) );

//			// 番号情報を結合.
//			snprintf( (char*)sc_LogExtraction, sizeof(sc_LogExtraction), "%03d   ",  ss_DataDispNum);
			// 番号情報に文字列格納.
			snprintf( (char*)sc_LogNumer, sizeof(sc_LogNumer), "%03d",  ss_DataDispNum);
			// ログ情報を結合.
			strncat( sc_LogExtraction, m_p_LogList[us_logNo], strlen(m_p_LogList[us_logNo]) );

			// 1行分のログを1文字ずつ確認し、','数をカウントする.
			us_TextLen = ( ushort )strlen( sc_LogExtraction );
			for( ; us_TextLen > us_CharNumber; us_CharNumber++ ) {
				// ','カウント.
//				if( ',' == sc_LogExtraction[us_CharNumber] ) {
//					us_AdjustCharNumber += 6;
//				}
//				else {
//					sc_AdjustLogExtraction[us_AdjustCharNumber] = sc_LogExtraction[us_CharNumber];
//				}
//				us_AdjustCharNumber++;

				if( ',' == sc_LogExtraction[us_CharNumber] ) {
					uc_commaCnt = static_cast<uchar>( uc_commaCnt + 1 );
					sc_LogExtraction[us_CharNumber] = '\0';

					if( 1 == uc_commaCnt ) {
// Comment 2015/10/08【HCLT-Meera】【CQ519679】【ID: 28750】NNTS.MUST.
//						strncpy( sc_LogDayTime, &sc_LogExtraction[us_StartCharNumber], sizeof(sc_LogDayTime) );
                        strncpy( sc_LogDayTime, &sc_LogExtraction[us_StartCharNumber], sizeof( sc_LogDayTime ) - 1 );
						us_StartCharNumber = static_cast<short>( us_CharNumber + 1 );
					} else if( 2 == uc_commaCnt ) {
// Comment 2015/10/08【HCLT-Meera】【CQ519679】【ID: 28758】NNTS.MUST.
//						strncpy( sc_LogResult, &sc_LogExtraction[us_StartCharNumber], sizeof(sc_LogResult) );
                        strncpy( sc_LogResult, &sc_LogExtraction[us_StartCharNumber], sizeof( sc_LogResult ) - 1 );
						us_StartCharNumber = us_CharNumber + 1;
// comment 2018/01/18 【HCL-Rajesh】 [IT5_4.2] Klockwork Changes ID: 381859 [SV.STRBO.BOUND_COPY.UNTERM].
//						strncpy( sc_LogErrCode, &sc_LogExtraction[us_StartCharNumber], sizeof(sc_LogErrCode) );
						strncpy( sc_LogErrCode, &sc_LogExtraction[us_StartCharNumber], sizeof(sc_LogErrCode) - 1 );
					}
				}
			}

//			sc_AdjustLogExtraction[ us_AdjustCharNumber ] = '\0';

			// 文字列格納.
//			Tfd_ServiceServerBackupResultDisplay[ us_Pos ].changeExternalText((uchar*)sc_AdjustLogExtraction, strlen(sc_AdjustLogExtraction) );
			Tfd_ServiceServerBackupResultDisplay[ us_Pos ][PNLE_ServiceServerBackupResultDisplayItem_Number].changeExternalText((uchar*)sc_LogNumer, (short)strlen(sc_LogNumer) );
			Tfd_ServiceServerBackupResultDisplay[ us_Pos ][PNLE_ServiceServerBackupResultDisplayItem_DayTime].changeExternalText((uchar*)sc_LogDayTime, (short)strlen(sc_LogDayTime) );
			Tfd_ServiceServerBackupResultDisplay[ us_Pos ][PNLE_ServiceServerBackupResultDisplayItem_Result].changeExternalText((uchar*)sc_LogResult, (short)strlen(sc_LogResult) );
			Tfd_ServiceServerBackupResultDisplay[ us_Pos ][PNLE_ServiceServerBackupResultDisplayItem_ErrorCode].changeExternalText((uchar*)sc_LogErrCode, (short)strlen(sc_LogErrCode) );
//			Tfd_ServiceServerBackupResultDisplay[ us_Pos ].showEnable( True );
			for( us_ItemPos = 0; us_ItemPos < PNLE_ServiceServerBackupResultDisplayItem_MAX; us_ItemPos++ ) {
				Tfd_ServiceServerBackupResultDisplay[ us_Pos ][ us_ItemPos ].showEnable( True );
			}
			us_Pos++;
		}
	}
	else {	// ログは0件の場合.
		Grp_ServiceServerBackupResultDisplay.showEnable( False );	// ログ非表示.
	}
}

