//================================================================================================.
// 概要		:PServiceServerBackupResult : K4B0023910_サーバーバックアップ／バックアップ結果 : キー押下処理.
// 戻り値	:なし.
// 備考		:なし.
//================================================================================================.
void PServiceServerBackupResult::procButtonOn( uchar uc_Option )
{
	switch(uc_Option) {
		case BTNID_KEY_ServiceServerBackupResultPageUp:		// Upキー.
			//２ページ以上の時.
			if( 1 < m_ss_CurrentPage ) {
				m_ss_CurrentPage--;
			}
			else {
				m_ss_CurrentPage = m_ss_MaxPage;
			}
			break;
		case BTNID_KEY_ServiceServerBackupResultPageDown:	// Downキー.
			if( m_ss_CurrentPage < m_ss_MaxPage ) {
				m_ss_CurrentPage++;
			}
			else {
				m_ss_CurrentPage = 1;
			}
			break;
		default:
			break;
	}
	setupGamen();
}

// comment 2016/01/15 [MAv4][RQ-505]バックアップ機能強化 日立 森本郁.
Bool								PServiceDataBackupServerRestoreMenu::m_bl_FromMenu				= False;
PNLE_ServiceExtServerRestoreSelect	PServiceDataBackupServerRestoreMenu::m_e_ServerRestoreSelect	= PNLD_ServiceExtServerRestore_None;
//================================================================================================.
// 概要    :K4B0024000_MAv4_データバックアップ／サーバーからリストア : 画面開始処理.
//================================================================================================.
void PServiceDataBackupServerRestoreMenu::startGamen()
{
	// 親クラスを呼ぶ.
	PServiceNoFunctionCodeCom::startGamen();
	
	if( True == m_bl_FromMenu ) {
		// ﾘｽﾄｱ選択状態を「なし」に設定.
		m_e_ServerRestoreSelect = PNLD_ServiceExtServerRestore_None;
		m_bl_FromMenu = False;
	}
}

// comment 2015.8.12 [CQ516452] No.4 ｻｰﾊﾞｰﾘｽﾄｱ画面のレイアウト変更 日立 村上(幸).
//================================================================================================.
// 概要		: PServiceDataBackupServerRestoreMenu : K4B0024000_ﾃﾞｰﾀﾊﾞｯｸｱｯﾌﾟ／ｻｰﾊﾞｰﾘｽﾄｱ: 画面表示セットアップ.
// 戻り値	:なし.
// 備考		:.
//================================================================================================.
void PServiceDataBackupServerRestoreMenu::setupGamen( short option )
{
	// 親クラスを呼ぶ.
// comment 2016/01/15 [MAv4][RQ-505]バックアップ機能強化 日立 森本郁.
//	PServiceNoFunctionCodeCom::setupGamen();
	PServiceNoFunctionCodeCom::setupGamen( option );

	// ﾘｽﾄｱ選択状態を設定.
	switch( m_e_ServerRestoreSelect ) {
		case PNLD_ServiceExtServerRestore_ServerRestore:			// ｻｰﾊﾞｰからﾘｽﾄｱを選択状態に設定.
			Rbt_ServiceDataRestoreServerRestoreMode.select( 0 );
			Grp_ServiceDataBackupServerRestoreMenu_SrvRestore.showEnable( True );
			Grp_ServiceDataBackupServerRestoreMenu_ExtSrvRestore.showEnable( False );
			break;
		case PNLD_ServiceExtServerRestore_ExtServerRestore:			// 拡張ｻｰﾊﾞｰからﾘｽﾄｱを選択状態に設定.
			Rbt_ServiceDataRestoreServerRestoreMode.select( 1 );
			Grp_ServiceDataBackupServerRestoreMenu_SrvRestore.showEnable( False );
			Grp_ServiceDataBackupServerRestoreMenu_ExtSrvRestore.showEnable( True );
			break;
		case PNLD_ServiceExtServerRestore_None:						// 何れのキーも非選択状態に設定.
		default:
			Rbt_ServiceDataRestoreServerRestoreMode.select( -1 );
			Grp_ServiceDataBackupServerRestoreMenu_SrvRestore.showEnable( False );
			Grp_ServiceDataBackupServerRestoreMenu_ExtSrvRestore.showEnable( False );
			break;
	}

	if( True == PnlComGetSystemSetting()->getSecurityLevelUpOn() ) {
		// セキュリティ強化モードONの場合は、ﾘｽﾄｱ設定キー非表示.
		Key_GoToServerRestoreBackupSetting.showEnable(False);
// comment 2016/01/15 [MAv4][RQ-505]バックアップ機能強化 日立 森本郁.
		Key_GoToExtServerRestoreBackupSetting.showEnable(False);
	} else {
		// セキュリティ強化モードOFFの場合は、ﾘｽﾄｱ設定キー表示.
		Key_GoToServerRestoreBackupSetting.showEnable(True);
// comment 2016/01/15 [MAv4][RQ-505]バックアップ機能強化 日立 森本郁.
		Key_GoToExtServerRestoreBackupSetting.showEnable(True);
	}
}

