// comment 2015.8.12 [CQ516452] No.4 ｻｰﾊﾞｰﾘｽﾄｱ画面のレイアウト変更 日立 村上(幸).
//PNLE_ServiceDataBackupServerRestore	PServiceServerRestoreSettingCom::m_e_ServerRestoreSettingGamen = PNLE_ServiceDataBackupServerRestore_Restore;
PNLE_ServiceDataBackupServerRestore	PServiceServerRestoreSettingCom::m_e_ServerRestoreSettingGamen = PNLE_ServiceDataBackupServerRestore_ServerSetting;
Bool PServiceServerRestoreSettingCom::m_bl_SelectRestoreSettingType = True;
//================================================================================================.
// 概要		: PServiceServerRestoreSettingCom : ﾃﾞｰﾀﾊﾞｯｸｱｯﾌﾟ／ｻｰﾊﾞｰﾘｽﾄｱ／ﾘｽﾄｱ設定 共通 : 画面更新処理.
// 戻り値	:なし.
// 備考		:.
// comment 2015.8.12 [CQ516452] No.4 ｻｰﾊﾞｰﾘｽﾄｱ画面のレイアウト変更 日立 村上(幸).
//================================================================================================.
void PServiceServerRestoreSettingCom::setupGamen( short option )
{
	// 親クラスを呼ぶ.
	PServiceNoFunctionCodeCom::setupGamen();

	switch( m_e_ServerRestoreSettingGamen ) {
//		case PNLE_ServiceDataBackupServerRestore_Restore:				// ﾘｽﾄｱ.
		case PNLE_ServiceDataBackupServerRestore_ServerSetting:			// サーバー設定.
			Rbt_ServiceServerRestoreSettingMenu.select( 0 );
			break;
		case PNLE_ServiceDataBackupServerRestore_Protocol:				// 取得ﾌﾟﾛﾄｺﾙ.
			Rbt_ServiceServerRestoreSettingMenu.select( 1 );
			break;
		case PNLE_ServiceDataBackupServerRestore_SMBHostName:			// SMB設定 - ホスト名.
			Rbt_ServiceServerRestoreSettingMenu.select( 2 );
			Rbt_ServiceServerRestoreSettingSMBMenu.select( 0 );
			break;
		case PNLE_ServiceDataBackupServerRestore_SMBFilePath:			// SMB設定 - ファイルパス.
			Rbt_ServiceServerRestoreSettingMenu.select( 2 );
			Rbt_ServiceServerRestoreSettingSMBMenu.select( 1 );
			break;
		case  PNLE_ServiceDataBackupServerRestore_SMBUserName:			// SMB設定 - ユーザー名.
			Rbt_ServiceServerRestoreSettingMenu.select( 2 );
			Rbt_ServiceServerRestoreSettingSMBMenu.select( 2 );
			break;
		case  PNLE_ServiceDataBackupServerRestore_SMBPassword:			// SMB設定 - パスワード.
			Rbt_ServiceServerRestoreSettingMenu.select( 2 );
			Rbt_ServiceServerRestoreSettingSMBMenu.select( 3 );
			break;
		case PNLE_ServiceDataBackupServerRestore_HTTPURL:				// HTTP設定 - URL.
			Rbt_ServiceServerRestoreSettingMenu.select( 3 );
			Rbt_ServiceServerRestoreSettingHTTPMenu.select( 0 );
			break;
		case PNLE_ServiceDataBackupServerRestore_HTTPUserName:			// HTTP設定 - ユーザー名.
			Rbt_ServiceServerRestoreSettingMenu.select( 3 );
			Rbt_ServiceServerRestoreSettingHTTPMenu.select( 1 );
			break;
		case PNLE_ServiceDataBackupServerRestore_HTTPPassword:			// HTTP設定 - パスワード.
			Rbt_ServiceServerRestoreSettingMenu.select( 3 );
			Rbt_ServiceServerRestoreSettingHTTPMenu.select( 2 );
			break;
		case PNLE_ServiceDataBackupServerRestore_HTTPProxy:				// HTTP設定 - プロキシ.
			Rbt_ServiceServerRestoreSettingMenu.select( 3 );
			Rbt_ServiceServerRestoreSettingHTTPMenu.select( 3 );
			break;
		case PNLE_ServiceDataBackupServerRestore_EncryptionPassword:	// 暗号化ﾊﾟｽﾜｰﾄﾞ.
			Rbt_ServiceServerRestoreSettingMenu.select( 4 );
			break;
		case PNLE_ServiceDataBackupServerRestore_Restore:				// ﾘｽﾄｱ.
			Rbt_ServiceServerRestoreSettingMenu.select( 5 );
			break;
		default: break;
	}

	Key_ServiceServerRestoreSettingServerProtocol.showEnable( ( True == m_bl_SelectRestoreSettingType ) ? False : True );
	Key_ServiceServerRestoreSettingSMBSetting.showEnable( ( True == m_bl_SelectRestoreSettingType ) ? False : True );
	Key_ServiceServerRestoreSettingHTTPSetting.showEnable( ( True == m_bl_SelectRestoreSettingType ) ? False : True );
	Key_ServiceServerRestoreSettingEncryptionPassword.showEnable( ( True == m_bl_SelectRestoreSettingType ) ? False : True );
}
//================================================================================================.
// 概要		: PServiceServerRestoreSettingCom : ﾃﾞｰﾀﾊﾞｯｸｱｯﾌﾟ／ｻｰﾊﾞｰﾘｽﾄｱ／ﾘｽﾄｱ設定 共通 : インデックスボタン処理.
// 戻り値	:なし.
// 備考		:.
// comment 2015.8.12 [CQ516452] No.4 ｻｰﾊﾞｰﾘｽﾄｱ画面のレイアウト変更 日立 村上(幸).
//================================================================================================.
void PServiceServerRestoreSettingCom::procIndexButton( uchar option )
{
	switch( option ) {
		// ｻｰﾊﾞｰ設定.
		case BTNID_KEY_ServiceServerRestore_ServerSetting:
			m_e_ServerRestoreSettingGamen = PNLE_ServiceDataBackupServerRestore_ServerSetting;
			nextGamen = &gp_ServiceServerRestoreSettingServerSetting;			// ｻｰﾊﾞｰﾊﾞｯｸｱｯﾌﾟ／ﾘｽﾄｱ設定／ｻｰﾊﾞｰ設定.
			break;
		// 取得ﾌﾟﾛﾄｺﾙ.
		case BTNID_KEY_ServiceServerRestore_Protocol:
			m_e_ServerRestoreSettingGamen = PNLE_ServiceDataBackupServerRestore_Protocol;
			nextGamen = &gp_ServiceServerRestoreSettingServerProtocol;	// ｻｰﾊﾞｰﾊﾞｯｸｱｯﾌﾟ／ﾘｽﾄｱ設定／送信ﾌﾟﾛﾄｺﾙ.
			break;
		// SMB設定.
		case BTNID_KEY_ServiceServerRestore_SMBSetting:
			m_e_ServerRestoreSettingGamen = PNLE_ServiceDataBackupServerRestore_SMBHostName;
			nextGamen = &gp_ServiceServerRestoreSettingSMBHostName;		// ｻｰﾊﾞｰﾊﾞｯｸｱｯﾌﾟ／ﾘｽﾄｱ設定／SMB設定／ホスト名.
			break;
		// HTTP設定.
		case BTNID_KEY_ServiceServerRestore_HTTPSetting:
			m_e_ServerRestoreSettingGamen = PNLE_ServiceDataBackupServerRestore_HTTPURL;
			nextGamen = &gp_ServiceServerRestoreSettingHttpURL;			// ｻｰﾊﾞｰﾊﾞｯｸｱｯﾌﾟ／ﾘｽﾄｱ設定／HTTP設定／URL.
			break;
		// 暗号化ﾊﾟｽﾜｰﾄﾞ.
		case BTNID_KEY_ServiceServerRestore_EncryptionPassword:
			m_e_ServerRestoreSettingGamen = PNLE_ServiceDataBackupServerRestore_EncryptionPassword;
			nextGamen = &gp_ServiceServerRestoreSettingEncryptionPassword;	// ｻｰﾊﾞｰﾊﾞｯｸｱｯﾌﾟ／ﾘｽﾄｱ設定／HTTP設定／暗号化ﾊﾟｽﾜｰﾄﾞ.
			break;
		// ﾘｽﾄｱ.
		case BTNID_KEY_ServiceServerRestore_Start:
			m_e_ServerRestoreSettingGamen = PNLE_ServiceDataBackupServerRestore_Restore;
			nextGamen = &gp_ServiceServerRestoreSettingRestore;			// ｻｰﾊﾞｰﾊﾞｯｸｱｯﾌﾟ／ﾘｽﾄｱ設定／ﾘｽﾄｱ.
			break;
		default:
			break;
	}
}
