void PServiceServerRestoreSettingCom::procGoToPage( uchar option )
{
	switch( option ) {
		case BTNID_KEY_ServiceServerRestore_SMBHostName:	// SMB設定ホスト名.
			m_e_ServerRestoreSettingGamen = PNLE_ServiceDataBackupServerRestore_SMBHostName;
			nextGamen = &gp_ServiceServerRestoreSettingSMBHostName;
			break;
		case BTNID_KEY_ServiceServerRestore_SMBFilePath:	// SMB設定ファイルパス.
			m_e_ServerRestoreSettingGamen = PNLE_ServiceDataBackupServerRestore_SMBFilePath;
			nextGamen = &gp_ServiceServerRestoreSettingSMBFilePath;
			break;
		case BTNID_KEY_ServiceServerRestore_SMBUserName:	// SMB設定ユーザー名.
			m_e_ServerRestoreSettingGamen = PNLE_ServiceDataBackupServerRestore_SMBUserName;
			nextGamen = &gp_ServiceServerRestoreSettingSMBUserName;
			break;
		case BTNID_KEY_ServiceServerRestore_SMBPassword:	// SMB設定パスワード.
			m_e_ServerRestoreSettingGamen = PNLE_ServiceDataBackupServerRestore_SMBPassword;
			nextGamen = &gp_ServiceServerRestoreSettingSMBPassword;
			break;
		case BTNID_KEY_ServiceServerRestore_HTTPURL:		// HTTP設定URL.
			m_e_ServerRestoreSettingGamen = PNLE_ServiceDataBackupServerRestore_HTTPURL;
			nextGamen = &gp_ServiceServerRestoreSettingHttpURL;
			break;
		case BTNID_KEY_ServiceServerRestore_HTTPUserName:	// HTTP設定ユーザー名.
			m_e_ServerRestoreSettingGamen = PNLE_ServiceDataBackupServerRestore_HTTPUserName;
			nextGamen = &gp_ServiceServerRestoreSettingHttpUserName;
			break;
		case BTNID_KEY_ServiceServerRestore_HTTPPassword:	// HTTP設定パスワード.
			m_e_ServerRestoreSettingGamen = PNLE_ServiceDataBackupServerRestore_HTTPPassword;
			nextGamen = &gp_ServiceServerRestoreSettingHttpPassword;
			break;
		case BTNID_KEY_ServiceServerRestore_HTTPProxy:		// HTTP設定プロキシ.
			m_e_ServerRestoreSettingGamen = PNLE_ServiceDataBackupServerRestore_HTTPProxy;
			nextGamen = &gp_ServiceServerRestoreSettingHttpProxy;
			break;
		default: break;
	}
}
