void PServiceServerRestoreSettingServerSetting::startGamen()
{
	// 親クラスを呼ぶ.
	PServiceServerRestoreSettingCom::startGamen();

	if( True == m_bl_FromMenu ) {
		// 表示中画面のIndexを初期化する.
		m_e_ServerRestoreSettingGamen = PNLE_ServiceDataBackupServerRestore_ServerSetting;

		// commonAPIから取得.
		PServiceServerRestoreSettingCom::m_bl_SelectRestoreSettingType = True;
		m_bl_FromMenu = False;
		// CommonAPIからの取得「サーバーバックアップ」.
		PLBC_DataBackupSettings::getInstance()->loadServerBackupSettingService();
	}

}

