void PServiceServerRestoreSettingServerSetting::setupGamen( short option )
{
	// 親クラスを呼ぶ.
	PServiceServerRestoreSettingCom::setupGamen( option );

	// True :ﾊﾞｯｸｱｯﾌﾟから取得 False :ﾘｽﾄｱ先編集.
	Rbt_ServiceServerRestoreSettingSelect.select( ( True == PServiceServerRestoreSettingCom::m_bl_SelectRestoreSettingType ) ? 0 : 1 );
	// ﾘｽﾄｱ先編集の説明メッセージ(ｻｰﾊﾞｰﾊﾞｯｸｱｯﾌﾟの設定内容を一時的に変更することができます)の表示/非表示.
	Txt_ServiceServerRestoreChangeSettingPermitMsg.showEnable( ( True == PServiceServerRestoreSettingCom::m_bl_SelectRestoreSettingType ) ? False : True );
}
