void PServiceServerRestoreSettingServerSetting::procButtonOn( uchar option )
{
	// 親クラスを呼ぶ.
	PServiceServerRestoreSettingCom::procButtonOn( option );

	switch( option ) {
		// ﾊﾞｯｸｱｯﾌﾟから取得キー.
		case BTNID_KEY_ServiceServerRestore_GetBackupSetting:
			PServiceServerRestoreSettingCom::m_bl_SelectRestoreSettingType = True;
			break;
		// ﾘｽﾄｱ先編集キー.
		case BTNID_KEY_ServiceServerRestore_EditRestoreSetting:
			PServiceServerRestoreSettingCom::m_bl_SelectRestoreSettingType = False;
			break;
		default:
			break;
	}

	setupGamen( option );
}

