//================================================================================================.
void PServiceServerRestoreSettingServerProtocol::setupGamen( short option )
{
	PLBC_DataBackupSettings *pc_DataBackupSettings = PLBC_DataBackupSettings::getInstance();
	if( NULL == pc_DataBackupSettings ) {
//	comment 2015/11/03 HCL_Vinothini [ZeusS_ZX0][制御構成変更_No.76-1] Adding error code.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//		if ( NULL != pc_BFW_System ) {
//    		pc_BFW_System -> registDetailCode(PNLD_DetailCode_Service_0x1900660101102801);
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}

	// 親クラスを呼ぶ.
	PServiceServerRestoreSettingCom::setupGamen( option );

	// SMB/HTTP.
	Rbt_ServiceServerRestoreSettingServerProtocol.select( TYPE_BackupRestoreSetting_ServerSMB == pc_DataBackupSettings->getServerBackupDestinationServer() ? 0 : 1 );
}
//================================================================================================.
// 概要		: PServiceServerRestoreSettingServerProtocol : K4B0024210_ｻｰﾊﾞｰﾊﾞｯｸｱｯﾌﾟ／ﾘｽﾄｱ設定／取得プロトコル :  画面遷移処理 .
// 戻り値	:なし.
// 備考		:.
//================================================================================================.
void PServiceServerRestoreSettingServerProtocol::procButtonOn( uchar option )
{
	PLBC_DataBackupSettings *pc_DataBackupSettings = PLBC_DataBackupSettings::getInstance();
	if( NULL == pc_DataBackupSettings ) {
//	comment 2015/11/03 HCL_Vinothini [ZeusS_ZX0][制御構成変更_No.76-1] Adding error code.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//		if ( NULL != pc_BFW_System ) {
//    		pc_BFW_System -> registDetailCode(PNLD_DetailCode_Service_0x19000A0101102901);
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}

	// 親クラスを呼ぶ.
	PServiceServerRestoreSettingCom::procButtonOn( option );

	switch( option ) {
		case BTNID_KEY_ServiceServerRestoreProtocol_SMB:
			// 選択中を「SMB」にする.
			pc_DataBackupSettings->setServerBackupDestinationServer( TYPE_BackupRestoreSetting_ServerSMB );
			break;
		case BTNID_KEY_ServiceServerRestoreProtocol_HTTP:
			// 選択中を「HTTP」にする.
			pc_DataBackupSettings->setServerBackupDestinationServer( TYPE_BackupRestoreSetting_ServerHTTP );
			break;
		default:
			break;
	}
	setupGamen( option );
}
