//================================================================================================.
// 概要		: PServiceServerRestoreSettingSMBHostNameInput : K4B0024320_ｻｰﾊﾞｰﾊﾞｯｸｱｯﾌﾟ／ﾘｽﾄｱ設定／SMB設定／ホスト名入力 :画面開始処理 .
// 戻り値	:なし.
// 備考		:.
//================================================================================================.
void PServiceServerRestoreSettingSMBHostNameInput::startGamen()
{
	PLBC_DataBackupSettings *pc_DataBackupSettings = PLBC_DataBackupSettings::getInstance();
	if( NULL == pc_DataBackupSettings ) {
//	comment 2015/11/03 HCL_Vinothini [ZeusS_ZX0][制御構成変更_No.76-1] Adding error code.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//		if ( NULL != pc_BFW_System ) {
//    		pc_BFW_System -> registDetailCode(PNLD_DetailCode_Service_0x1900650101102B01);
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}

	// データクラスからSMBホスト名を取得する.
// Comment 2020/01/22 [HCL-Shalini] [EagleZ+] [OP_BTS-19428] strnlen is used instead sizeof().
//// Comment 2019/12/02 [HCL-Taqiuddin] [KLOC ID:106287] [KLOC TYPE:ABV.GENERAL].
//	if ( sizeof( pc_DataBackupSettings->getServerBackupForSMBHostName()) < sizeof (m_sc_StrKeyboard) ) {
//		memcpy( m_sc_StrKeyboard, pc_DataBackupSettings->getServerBackupForSMBHostName(), sizeof( pc_DataBackupSettings->getServerBackupForSMBHostName() ) - 1 );
	if ( strnlen( pc_DataBackupSettings->getServerBackupForSMBHostName(),TYPD_BackupRestoreSetting_SMB_HostNameMaxLen) < sizeof (m_sc_StrKeyboard) ) {
		memset( m_sc_StrKeyboard, 0, sizeof( m_sc_StrKeyboard ) );
		memcpy( m_sc_StrKeyboard, pc_DataBackupSettings->getServerBackupForSMBHostName(), strnlen( pc_DataBackupSettings->getServerBackupForSMBHostName() ,TYPD_BackupRestoreSetting_SMB_HostNameMaxLen) );
	} else {
		memcpy( m_sc_StrKeyboard, pc_DataBackupSettings->getServerBackupForSMBHostName(), sizeof( m_sc_StrKeyboard ) - 1 );
	}
	// 表示領域に文字列をセット.
	setKeyboardData( m_sc_StrKeyboard, PNLD_MAX_ServiceDataBackupServerRestoreSMBHostNameChar , PNLD_ServiceDataBackupServerRestoreInputWidth );
	m_bl_Password = False;
	m_bl_ShowPass = False;

	// 親クラスを呼ぶ.
	PServiceDataBackupKeyboardCom::startGamen();
}
