	PServiceServerRestoreSettingCom::setupGamen( option );

	char sc_LocalPassword[ TYPD_BackupRestoreSetting_EncryptionPasswordMaxLen ];
	memset( sc_LocalPassword, '\0', sizeof( sc_LocalPassword ) );
