void PServiceServerRestoreSettingEncryptionPasswordInput::startGamen()
{
	PLBC_DataBackupSettings *pc_DataBackupSettings = PLBC_DataBackupSettings::getInstance();
	if( NULL == pc_DataBackupSettings ) {
//	comment 2015/11/03 HCL_Vinothini [ZeusS_ZX0][制御構成変更_No.76-1] Adding error code.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//		if ( NULL != pc_BFW_System ) {
//    		pc_BFW_System -> registDetailCode(PNLD_DetailCode_Service_0x1900650101104201);
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}

	// データクラスからパスワードを取得する.
// Comment 2020/01/22 [HCL-Shalini] [EagleZ+] [OP_BTS-19428] strnlen is used instead sizeof().
//// Comment 2019/12/02 [HCL-Taqiuddin] [KLOC ID:106294] [KLOC TYPE:ABV.GENERAL].
//	if ( sizeof( pc_DataBackupSettings->getServerBackUpEncryptionPassword()) < sizeof (m_sc_StrKeyboard) ) {
//		memcpy( m_sc_StrKeyboard, pc_DataBackupSettings->getServerBackUpEncryptionPassword(), sizeof( pc_DataBackupSettings->getServerBackUpEncryptionPassword() ) - 1 );
	if ( strnlen( pc_DataBackupSettings->getServerBackUpEncryptionPassword(),TYPD_BackupRestoreSetting_EncryptionPasswordMaxLen) < sizeof (m_sc_StrKeyboard) ) {
		memset( m_sc_StrKeyboard, 0, sizeof( m_sc_StrKeyboard ) );
		memcpy( m_sc_StrKeyboard, pc_DataBackupSettings->getServerBackUpEncryptionPassword(), strnlen( pc_DataBackupSettings->getServerBackUpEncryptionPassword(),TYPD_BackupRestoreSetting_EncryptionPasswordMaxLen ) );
	} else {
		memcpy( m_sc_StrKeyboard, pc_DataBackupSettings->getServerBackUpEncryptionPassword(), sizeof( m_sc_StrKeyboard ) - 1 );
	}
	// 表示領域に文字列をセット.
	setKeyboardData( m_sc_StrKeyboard, PNLD_MAX_ServiceDataBackupServerRestoreEncryptionPasswordChar , PNLD_ServiceDataBackupServerRestoreInputWidth );
	m_bl_Password = True;
	m_bl_ShowPass = True;

	// 親クラスを呼ぶ.
	PServiceDataBackupKeyboardCom::startGamen();

	Kbd_ServiceInputKeybord.setKeybord5Country( True );
	Kbd_ServiceInputKeybord.GetCursor( &Btx_ServiceDataBackupKeyboardComInput );
	Kbd_ServiceInputKeybord.showKeybord();
}
