//================================================================================================.
// 概要		: PServiceServerRestoreSettingRestore : K4B0024610_ｻｰﾊﾞｰﾊﾞｯｸｱｯﾌﾟ／ﾘｽﾄｱ設定／ﾘｽﾄｱ : 画面開始処理.
// 戻り値	:なし.
// 備考		:.
//================================================================================================.
void PServiceServerRestoreSettingRestore::startGamen()
{
	// 親クラスを呼ぶ.
	PServiceServerRestoreSettingCom::startGamen();

	// 状態初期化.
// comment 2017/02/03 SCD2-Sky西村 [IT5_3.4][1013299].
//	m_bl_Restorestart = False;
//	m_bl_RestoreRequest = False;
//	m_bl_ServiceServerRestoreEnd = False;
	switch( m_e_RestoreStatus ) {
		case PNLE_RestoreStatus_None:		// リストア未実施.	
			m_bl_Restorestart = False;										// ｽﾀｰﾄキー押下.
			m_e_RestoreResult = TYPE_ServerRestoreResultNG;					// サーバーリストア結果.
			memset(m_sc_Errorcode, 0x00, sizeof(m_sc_Errorcode));			// エラーコード保存用の配列.
			break;
		case PNLE_RestoreStatus_Running:	// リストア実行中.
			onlyPanel.bl_PowerOffOnMesage = True;							// 主電源OFF/ON画面から遷移させないためのフラグ.
			break;
		case PNLE_RestoreStatus_Done:		// リストア完了.
			onlyPanel.bl_PowerOffOnMesage = True;							// 主電源OFF/ON画面から遷移させないためのフラグ.
			//リストア結果を取得.
			m_e_RestoreResult = APIC_BackupRestore::newInstance()->getServerRestoreResult(TYPE_ServerBackupRestoreModeService, m_sc_Errorcode);
			if( TYPE_ServerRestoreResultNG2 == m_e_RestoreResult ) {		// ネットワーク関連又はパスワード不正によるNGの場合.
				onlyPanel.bl_PowerOffOnMesage = False;						// 主電源OFF/ON画面から遷移させないためのフラグ.
				m_bl_Restorestart = False;									// ｽﾀｰﾄキー押下.
			}
			break;
		default:
			break;
	}
}

//================================================================================================.
// 概要		: PServiceServerRestoreSettingRestore : K4B0024610_ｻｰﾊﾞｰﾊﾞｯｸｱｯﾌﾟ／ﾘｽﾄｱ設定／ﾘｽﾄｱ : 画面更新処理.
// 戻り値	:なし.
// 備考		:.
// comment 2015/10/13 [CQ519799] ｻｰﾊﾞｰﾘｽﾄｱ時、NG発生した場合は主電源OFF/ONさせない.
//================================================================================================.
void PServiceServerRestoreSettingRestore::setupGamen( short option )
{
	// 親クラスを呼ぶ.
	PServiceServerRestoreSettingCom::setupGamen( option );

	Key_ServiceServerRestoreSettingRestoreStart.select( m_bl_Restorestart );		// キーの選択状態を設定.

// comment 2017/02/03 SCD2-Sky西村 [IT5_3.4][1013299].
	switch( m_e_RestoreStatus ) {
		case PNLE_RestoreStatus_None:		// リストア未実施.
			Txt_ServiceServerRestoreActionSlash.showEnable( False );				// 「／」を非表示.
			Txt_ServiceServerRestoreResultStatus.showEnable( False );				// 「実行中」を非表示.
			Txt_ServiceServerRestoreErrorCode.showEnable( False );					// エラーコードタイトルを非表示.
			Txt_ServiceServerRestoreColon.showEnable( False );						// コロンを非表示.
			Tfd_ServiceServerRestoreErrorCodeVal.showEnable( False );				// エラーコードを非表示.
			Txt_TitleServiceServerRestoreResult.showEnable( False );				// 結果タイトルを非表示.
			Txt_ServiceServerRestoreResultOKNG.showEnable( False );					// 「OK」/「NG」を非表示.
			Txt_ServiceServerRestoreMsgPowerOffOn.showEnable( False );				// 「必ず電源OFF/ONしてください」を非表示.
			break;
		case PNLE_RestoreStatus_Running:	// リストア実行中.
			static Bool bl_RestoreNow = False;
			Txt_TitleServiceServerRestoreResult.showEnable( False );				// 結果タイトルを非表示.
			Txt_ServiceServerRestoreErrorCode.showEnable( False );					// エラーコードタイトルを非表示.
			Txt_ServiceServerRestoreColon.showEnable( False );						// コロンを非表示.
			Tfd_ServiceServerRestoreErrorCodeVal.showEnable( False );				// エラーコードを非表示.
			Txt_ServiceServerRestoreResultOKNG.showEnable( False );					// 「OK」/「NG」を非表示.
			Txt_ServiceServerRestoreMsgPowerOffOn.showEnable( False );				//「必ず電源OFF/ONしてください」非表示.
			Txt_ServiceServerRestoreActionSlash.changeText( True == bl_RestoreNow ? s_EXPSlash : s_EXPBackslash );
			Txt_ServiceServerRestoreActionSlash.showEnable( True );					// 「／」を非表示.
			bl_RestoreNow = ( ( True == bl_RestoreNow ) ? False : True );			// 「／」「＼」を交互に表示.
			Txt_ServiceServerRestoreResultStatus.showEnable( True );				// 「実行中」を表示.
			break;
		case PNLE_RestoreStatus_Done:		// リストア完了.
			Txt_ServiceServerRestoreActionSlash.showEnable( False );				// 「／」を非表示.
			Txt_ServiceServerRestoreResultStatus.showEnable( False );				// 「実行中」を非表示.
			switch( m_e_RestoreResult ) {
				case TYPE_ServerRestoreResultOK:	// リストア成功.
					Txt_ServiceServerRestoreResultOKNG.changeText( s_OKService );	// 「OK」に変更.
					Txt_ServiceServerRestoreMsgPowerOffOn.showEnable( True );		//「必ず電源OFF/ONしてください」表示.
					Txt_ServiceServerRestoreColon.showEnable( False );				// コロンを非表示.
					Tfd_ServiceServerRestoreErrorCodeVal.showEnable( False );		// エラーコードを非表示.
					Txt_ServiceServerRestoreErrorCode.showEnable( False );			// エラーコードタイトルを非表示.
					break;
				case TYPE_ServerRestoreResultNG:	// リストア失敗(主電源OFF/ON必要).
					Txt_ServiceServerRestoreResultOKNG.changeText( s_NGService );	// 「NG」に変更.
					Txt_ServiceServerRestoreMsgPowerOffOn.showEnable( True );		//「必ず電源OFF/ONしてください」表示.
					Txt_ServiceServerRestoreColon.showEnable( True );				// コロンを表示.
					Tfd_ServiceServerRestoreErrorCodeVal.changeExternalText(( uchar* )m_sc_Errorcode, sizeof(m_sc_Errorcode), getCharSetForPanel() );
					Tfd_ServiceServerRestoreErrorCodeVal.showEnable( True );		// エラーコードを表示.
					Txt_ServiceServerRestoreErrorCode.showEnable( True );			// エラーコードタイトルを表示.
					break;
				case TYPE_ServerRestoreResultNG2:	// リストア失敗(主電源OFF/ON不要。ネットワークエラー、ﾊﾟｽﾜｰﾄﾞ不一致の要因で失敗).
					Txt_ServiceServerRestoreResultOKNG.changeText( s_NGService );	// 「NG」に変更.
					Txt_ServiceServerRestoreMsgPowerOffOn.showEnable( False );		//「必ず電源OFF/ONしてください」非表示.
					Txt_ServiceServerRestoreColon.showEnable( True );				// コロンを表示.
					Tfd_ServiceServerRestoreErrorCodeVal.changeExternalText(( uchar* )m_sc_Errorcode, sizeof(m_sc_Errorcode), getCharSetForPanel() );
					Tfd_ServiceServerRestoreErrorCodeVal.showEnable( True );		// エラーコードを表示.
					Txt_ServiceServerRestoreErrorCode.showEnable( True );			// エラーコードタイトルを表示.
					break;
				default:
					break;
			}
			Txt_TitleServiceServerRestoreResult.showEnable( True );					// 結果タイトルを表示.
			Txt_ServiceServerRestoreResultOKNG.showEnable( True );					// 「OK」/「NG」を表示.
			Key_ServiceServerRestoreSettingRestoreStart.select( True );				// ﾘｽﾄｱ実施後は成功／失敗に関わらず、選択状態.
			break;
		default:
			break;
	}
}
//================================================================================================.
// 概要		: PServiceServerRestoreSettingRestore : K4B0024610_ｻｰﾊﾞｰﾊﾞｯｸｱｯﾌﾟ／ﾘｽﾄｱ設定／ﾘｽﾄｱ : 画面遷移処理.
// 戻り値	:なし.
// 備考		:.
//================================================================================================.
void PServiceServerRestoreSettingRestore::procButtonOn( uchar option )
{

	TYPS_ServerRestoreInfo st_ServerRestoreInfo;

	// ｽﾀｰﾄキー押下の場合、ブザー音を鳴動.
	if( True == m_bl_Restorestart ) {
		setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}

	PLBC_DataBackupSettings *pc_DataBackupSettings = PLBC_DataBackupSettings::getInstance();
	if( NULL == pc_DataBackupSettings ) {
//	comment 2015/11/03 HCL_Vinothini [ZeusS_ZX0][制御構成変更_No.76-1] Adding error code.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
//		if ( NULL != pc_BFW_System ) {
//    		pc_BFW_System -> registDetailCode(PNLD_DetailCode_Service_0x19000A0101104401);
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}

	// 親クラスを呼ぶ.
	PServiceServerRestoreSettingCom::procButtonOn( option );

	switch( option ) {
		// ｽﾀｰﾄキー.
		case BTNID_KEY_ServiceServerRestore:
			m_bl_Restorestart = True;				// ｽﾀｰﾄキー押下状態に設定.
			onlyPanel.bl_PowerOffOnMesage = True;	// 主電源OFF/ON画面から遷移させないためのフラグ.
			turnGamen = NULL;
			if( True == PServiceServerRestoreSettingCom::m_bl_SelectRestoreSettingType ) {
				pc_DataBackupSettings->loadServerBackupSettingService();
			}
			PServiceServerRestoreSettingCom::setServiceServerRestoreInfo( &st_ServerRestoreInfo );														// 現在のｻｰﾊﾞｰﾘｽﾄｱの設定値を取得.
// comment 2017/02/03 SCD2-Sky西村 [IT5_3.4][1013299].
//			m_bl_RestoreRequest = APIC_BackupRestore::newInstance()->startServerRestore(TYPE_ServerBackupRestoreModeService, &st_ServerRestoreInfo );	// ｻｰﾊﾞｰﾘｽﾄｱを開始するAPI.
//			if( False == m_bl_RestoreRequest ) {
//				m_bl_ServiceServerRestoreEnd = True;
//			}
			if( True == APIC_BackupRestore::newInstance()->startServerRestore(TYPE_ServerBackupRestoreModeService, &st_ServerRestoreInfo ) ) {
				m_e_RestoreStatus = PNLE_RestoreStatus_Running;
			}
			else {
				m_e_RestoreStatus = PNLE_RestoreStatus_Done;
			}
			break;
		default:
			break;
	}

	setupGamen( option );
}

