//		PnlComGetPrinterServiceSetting()->setPrinterAdjust(TYPE_PrinterAdjustTonerPatchFreqChoice, TYPE_TonerPatchFreqChoice_Off ); 
//		break;
//	case BTNID_KEY_ServicePatchHandedAdjustLow:			// Low Key.
