//		PnlComGetPrinterServiceSetting()->setPrinterAdjust(TYPE_PrinterAdjustTonerPatchFreqChoice, TYPE_TonerPatchFreqChoice_1_5 );
//		break;
//	case BTNID_KEY_ServicePatchHandedAdjustSlightlyLow:	// Slightly Low Key.
//		m_ss_PatchCountNumber = TYPE_TonerPatchFreqChoice_2_5;
//		PnlComGetPrinterServiceSetting()->setPrinterAdjust(TYPE_PrinterAdjustTonerPatchFreqChoice, TYPE_TonerPatchFreqChoice_2_5 );
//		break;
//	case BTNID_KEY_ServicePatchHandedAdjustSlightlyHigh:	// slightly High Key.
//		m_ss_PatchCountNumber = TYPE_TonerPatchFreqChoice_3_5;
//		PnlComGetPrinterServiceSetting()->setPrinterAdjust(TYPE_PrinterAdjustTonerPatchFreqChoice, TYPE_TonerPatchFreqChoice_3_5 );
