//		PnlComGetPrinterServiceSetting()->setPrinterAdjust(TYPE_PrinterAdjustTonerPatchFreqChoice, TYPE_TonerPatchFreqChoice_5_0 );
//		break;
	case BTNID_KEY_ServicePatchHandedAdjustClear: 			// clear key selection.
		if ( True == m_bl_ClearOn ){
			m_bl_ClearOn = False;
		} else {
			m_bl_ClearOn = True;
		}
		break;
	case BTNID_KEY_ServicePatchHandedAdjustFix: 			// Apply Key Selection.
		PnlComGetCoverageCnt()->resetAverageCoverageRate();
