/**
* @brief  : To Handle selection of Keys processing.
* @note   : PServicePurgeControlChoiceSetting : Changes are applicable only for MinervaSBk.
* @param  : uchar.
* @return : None.
* @author : 2015/04/16 【HCLT-Juned】 【MiSBK】 【機器構成変更_No.30】.
*/
//====================================================================================================================.
void PServicePurgeControlChoiceSetting::procButtonOn( uchar option )
{
	switch( option ){
		case BTNID_KEY_PURGECONTROLCHOICE_MODE_YES:		// Yes key is pressed.
			m_ss_PurgeControlChoice = TYPE_RemainPaperOutput_ON;	//Set Purge Control to ON.
			break;
		case BTNID_KEY_PURGECONTROLCHOICE_MODE_NO:		// No Key is pressed.
			m_ss_PurgeControlChoice = TYPE_RemainPaperOutput_OFF;	//Set Purge Control to OFF.
			break;
		default:
			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
			return;
	}
	setupGamen();	// 表示部品のセットアップ.
}
