/**
* @brief  : To Handle Screen Display processing.
* @note   : PServiceFinisherZFold2ndSpeedAdj : J3B9330330_フィニッシャ-調整／FS-FN調整／Z折り第2折り速度調整.
* @param  : short.
* @author : 2015/07/03 【HCLT_Harish】【MinervaSBK】【機器構成変更_No.50】FS 537 support when ZU609 is available.
*/
//====================================================================================================================.
void PServiceFinisherZFold2ndSpeedAdj::setupGamen( short option )
{
	short m_ss_LocalData = 0;							// ローカルデータ.
	// 親クラスの呼出し.
	PServiceFinisherAdjCom::setupGamen( option );
// comment 2015/12/15 OPS1-MSE長谷川 [ZeusS_ZX0][CQ524154] CQ523208の対応で追加されたパーツに値を渡す.
//// comment 2015/12/15 OPS1-MSE長谷川 [ZeusS_ZX0][CQ522931] 調整範囲の値から表示用の値に変更.
////	Bak_ServiceFNSZFoldNowValueAreaALL 		= 	(float)getPrinterIndi( TYPE_FS537_AD_ZFold2ndFoldSpeed_PaperTypeAll		);	// 現在値表示エリア(All).
////	Bak_ServiceFNSZFoldNowValueAreaPlain 	= 	(float)getPrinterIndi( TYPE_FS537_AD_ZFold2ndFoldSpeed_PaperTypeNormal	);	// 現在値表示エリア(Plain).
////	Bak_ServiceFNSZFoldNowValueAreaThin 	= 	(float)getPrinterIndi( TYPE_FS537_AD_ZFold2ndFoldSpeed_PaperTypeThin	);	// 現在値表示エリア(Thin).
////	Bak_ServiceFNSZFoldNowValueAreaRecylce 	= 	(float)getPrinterIndi( TYPE_FS537_AD_ZFold2ndFoldSpeed_PaperTypeRecycle	);	// 現在値表示エリア(Recycle).
//	Bak_ServiceFNSZFoldNowValueAreaALL 		= 	(float)getPrinterIndi( TYPE_FS537_AD_ZFold2ndFoldSpeed_PaperTypeAll		) * 10.0f;	// 現在値表示エリア(All).
//	Bak_ServiceFNSZFoldNowValueAreaPlain 	= 	(float)getPrinterIndi( TYPE_FS537_AD_ZFold2ndFoldSpeed_PaperTypeNormal	) * 10.0f;	// 現在値表示エリア(Plain).
//	Bak_ServiceFNSZFoldNowValueAreaThin 	= 	(float)getPrinterIndi( TYPE_FS537_AD_ZFold2ndFoldSpeed_PaperTypeThin	) * 10.0f;	// 現在値表示エリア(Thin).
//	Bak_ServiceFNSZFoldNowValueAreaRecylce 	= 	(float)getPrinterIndi( TYPE_FS537_AD_ZFold2ndFoldSpeed_PaperTypeRecycle	) * 10.0f;	// 現在値表示エリア(Recycle).
	Bak_ServiceFNSZFoldNowValueAreaALL_mmps 		= 	(float)getPrinterIndi( TYPE_FS537_AD_ZFold2ndFoldSpeed_PaperTypeAll		) * 10.0f;	// 現在値表示エリア(All).
	Bak_ServiceFNSZFoldNowValueAreaPlain_mmps 		= 	(float)getPrinterIndi( TYPE_FS537_AD_ZFold2ndFoldSpeed_PaperTypeNormal	) * 10.0f;	// 現在値表示エリア(Plain).
	Bak_ServiceFNSZFoldNowValueAreaThin_mmps 		= 	(float)getPrinterIndi( TYPE_FS537_AD_ZFold2ndFoldSpeed_PaperTypeThin	) * 10.0f;	// 現在値表示エリア(Thin).
	Bak_ServiceFNSZFoldNowValueAreaRecylce_mmps 	= 	(float)getPrinterIndi( TYPE_FS537_AD_ZFold2ndFoldSpeed_PaperTypeRecycle	) * 10.0f;	// 現在値表示エリア(Recycle).

	switch( getIndiSelected() ){
	case TYPE_FS537_AD_ZFold2ndFoldSpeed_PaperTypeAll:		m_ss_LocalData = getPrinterIndi( TYPE_FS537_AD_ZFold2ndFoldSpeed_PaperTypeAll		);	break;
	case TYPE_FS537_AD_ZFold2ndFoldSpeed_PaperTypeNormal:	m_ss_LocalData = getPrinterIndi( TYPE_FS537_AD_ZFold2ndFoldSpeed_PaperTypeNormal		);	break;
	case TYPE_FS537_AD_ZFold2ndFoldSpeed_PaperTypeThin:		m_ss_LocalData = getPrinterIndi( TYPE_FS537_AD_ZFold2ndFoldSpeed_PaperTypeThin		);	break;
	case TYPE_FS537_AD_ZFold2ndFoldSpeed_PaperTypeRecycle:	m_ss_LocalData = getPrinterIndi( TYPE_FS537_AD_ZFold2ndFoldSpeed_PaperTypeRecycle	);	break;
	default: LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); break;
	}
// comment 2015/12/15 OPS1-MSE長谷川 [ZeusS_ZX0][CQ522931] 調整範囲の値から表示用の値に変更.
//	Inp_ServiceFNSZFoldAdjValue = m_ss_LocalData;
	Inp_ServiceFNSZFoldAdjValue = m_ss_LocalData * 10.0f;
	// キーを選択表示.
// comment 2015/12/15 OPS1-MSE長谷川 [ZeusS_ZX0][CQ524154] CQ523208の対応で追加されたパーツを選択状態にする.
//	Rbt_ServiceFNSZFoldPaperKind.select( m_ss_select );
	Rbt_ServiceFNSZFoldPaperKind_mmps.select( m_ss_select );
}
//====================================================================================================================.
/**
* @brief  : To Handle selection of Keys processing.
* @note   : PServiceFinisherZFold2ndSpeedAdj : J3B9330330_フィニッシャ-調整／FS-FN調整／Z折り第2折り速度調整.
* @param  : uchar.
* @author : 2015/07/03 【HCLT_Harish】【MinervaSBK】【機器構成変更_No.50】FS 537 support when ZU609 is available.
*/
//====================================================================================================================.
void PServiceFinisherZFold2ndSpeedAdj::procButtonOn( uchar option )
{
	switch( option ){
	case BTNID_KEY_SERV_NFNS_Z_FOLD_KEY_ALL:
		setPrinterIndi( TYPE_FS537_AD_ZFold2ndFoldSpeed_PaperTypeAll );	 	// All.
		m_ss_select = 0;
		break;
	case BTNID_KEY_SERV_NFNS_Z_FOLD_KEY_PLAIN:
		setPrinterIndi( TYPE_FS537_AD_ZFold2ndFoldSpeed_PaperTypeNormal );	// Plain.
		m_ss_select = 1;
		break;
	case BTNID_KEY_SERV_NFNS_Z_FOLD_KEY_THIN:
		setPrinterIndi( TYPE_FS537_AD_ZFold2ndFoldSpeed_PaperTypeThin );	// Thin.
		m_ss_select = 2;
		break;
	case BTNID_KEY_SERV_NFNS_Z_FOLD_KEY_RECYCLE:
		setPrinterIndi( TYPE_FS537_AD_ZFold2ndFoldSpeed_PaperTypeRecycle);	// Recycle.
		m_ss_select = 3;
		break;
	case BTNID_KEY_SERV_ADDINDI:	addIndi();	break;	// +キー.
	case BTNID_KEY_SERV_SUBINDI:	subIndi();	break;	// -キー.
	case BTNID_KEY_SERV_BACKUP:	// 元に戻すキー.
		switch( getIndiSelected() ){
		case TYPE_FS537_AD_ZFold2ndFoldSpeed_PaperTypeAll:			setPrinterIndi( TYPE_FS537_AD_ZFold2ndFoldSpeed_PaperTypeAll, m_ss_BakFinisherZFold2ndSpeedAdjAll );			break;
		case TYPE_FS537_AD_ZFold2ndFoldSpeed_PaperTypeNormal:		setPrinterIndi( TYPE_FS537_AD_ZFold2ndFoldSpeed_PaperTypeNormal, m_ss_BakFinisherZFold2ndSpeedAdjPlain );		break;
		case TYPE_FS537_AD_ZFold2ndFoldSpeed_PaperTypeThin:			setPrinterIndi( TYPE_FS537_AD_ZFold2ndFoldSpeed_PaperTypeThin, m_ss_BakFinisherZFold2ndSpeedAdjThin );		break;
		case TYPE_FS537_AD_ZFold2ndFoldSpeed_PaperTypeRecycle:		setPrinterIndi( TYPE_FS537_AD_ZFold2ndFoldSpeed_PaperTypeRecycle, m_ss_BakFinisherZFold2ndSpeedAdjRecycle );	break;
		default:		break;
		}
		break;
	default: LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); break;
	}
	setupGamen();
}
