/**
* @brief  : To Handle Screen Display processing.
* @note   : PServiceFinisherZFoldFirstAdjFS537 : 93307_MiSBK_フィニッシャ-調整／FSｰFN調整／第1Z折り位置調整.
* @param  : short.
* @author : 2015/07/03 【HCLT_Harish】【MinervaSBK】【機器構成変更_No.50】FS 537 support when ZU609 is available.
*/
//====================================================================================================================.
void PServiceFinisherZFoldFirstAdjFS537::setupGamen( short option )
{
	short m_ss_LocalData = 0;							// ローカルデータ.
	// 親クラスの呼出し.
	PServiceFinisherAdjCom::setupGamen( option );
	Bak_ServiceFNSZFoldNowValueAreaALL 		= 	(float)getPrinterIndi( TYPE_FS537_AD_ZFold1stPosAdj_PaperTypeAll		) / 10.0f;	// 現在値表示エリア(All).
	Bak_ServiceFNSZFoldNowValueAreaPlain 	= 	(float)getPrinterIndi( TYPE_FS537_AD_ZFold1stPosAdj_PaperTypeNormal		) / 10.0f;	// 現在値表示エリア(Plain).
	Bak_ServiceFNSZFoldNowValueAreaThin 	= 	(float)getPrinterIndi( TYPE_FS537_AD_ZFold1stPosAdj_PaperTypeThin		) / 10.0f;	// 現在値表示エリア(Thin).
	Bak_ServiceFNSZFoldNowValueAreaRecylce 	= 	(float)getPrinterIndi( TYPE_FS537_AD_ZFold1stPosAdj_PaperTypeRecycle	) / 10.0f;	// 現在値表示エリア(Recycle).
	switch( getIndiSelected() ){
	case TYPE_FS537_AD_ZFold1stPosAdj_PaperTypeAll:			m_ss_LocalData = getPrinterIndi( TYPE_FS537_AD_ZFold1stPosAdj_PaperTypeAll		);	break;
	case TYPE_FS537_AD_ZFold1stPosAdj_PaperTypeNormal:		m_ss_LocalData = getPrinterIndi( TYPE_FS537_AD_ZFold1stPosAdj_PaperTypeNormal	);	break;
	case TYPE_FS537_AD_ZFold1stPosAdj_PaperTypeThin:		m_ss_LocalData = getPrinterIndi( TYPE_FS537_AD_ZFold1stPosAdj_PaperTypeThin		);	break;
	case TYPE_FS537_AD_ZFold1stPosAdj_PaperTypeRecycle:		m_ss_LocalData = getPrinterIndi( TYPE_FS537_AD_ZFold1stPosAdj_PaperTypeRecycle	);	break;
	default: LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); break;
	}
	Inp_ServiceFNSZFoldAdjValue = m_ss_LocalData / 10.0f;
	// キーを選択表示.
	Rbt_ServiceFNSZFoldPaperKind.select( m_ss_select );
}
//====================================================================================================================.
/**
* @brief  : To Handle selection of Keys processing.
* @note   : PServiceFinisherZFoldFirstAdjFS537 : 93307_MiSBK_フィニッシャ-調整／FSｰFN調整／第1Z折り位置調整.
* @param  : uchar.
* @author : 2015/07/03 【HCLT_Harish】【MinervaSBK】【機器構成変更_No.50】FS 537 support when ZU609 is available.
*/
//====================================================================================================================.
void PServiceFinisherZFoldFirstAdjFS537::procButtonOn( uchar option )
{
	switch( option ){
	case BTNID_KEY_SERV_NFNS_Z_FOLD_KEY_ALL:
		setPrinterIndi( TYPE_FS537_AD_ZFold1stPosAdj_PaperTypeAll );	// All.
		m_ss_select = 0;
		break;
	case BTNID_KEY_SERV_NFNS_Z_FOLD_KEY_PLAIN:
		setPrinterIndi( TYPE_FS537_AD_ZFold1stPosAdj_PaperTypeNormal );	// Plain.
		m_ss_select = 1;
		break;
	case BTNID_KEY_SERV_NFNS_Z_FOLD_KEY_THIN:
		setPrinterIndi( TYPE_FS537_AD_ZFold1stPosAdj_PaperTypeThin );	// Thin.
		m_ss_select = 2;
		break;
	case BTNID_KEY_SERV_NFNS_Z_FOLD_KEY_RECYCLE:
		setPrinterIndi( TYPE_FS537_AD_ZFold1stPosAdj_PaperTypeRecycle);	// Recycle.
		m_ss_select = 3;
		break;
	case BTNID_KEY_SERV_ADDINDI:	addIndi();	break;	// +キー.
	case BTNID_KEY_SERV_SUBINDI:	subIndi();	break;	// -キー.
	case BTNID_KEY_SERV_BACKUP:	// 元に戻すキー.
		switch( getIndiSelected() ){
		case TYPE_FS537_AD_ZFold1stPosAdj_PaperTypeAll:			setPrinterIndi( TYPE_FS537_AD_ZFold1stPosAdj_PaperTypeAll, m_ss_BakFinisherZFoldFirstAll );			break;
		case TYPE_FS537_AD_ZFold1stPosAdj_PaperTypeNormal:		setPrinterIndi( TYPE_FS537_AD_ZFold1stPosAdj_PaperTypeNormal, m_ss_BakFinisherZFoldFirstPlain );		break;
		case TYPE_FS537_AD_ZFold1stPosAdj_PaperTypeThin:		setPrinterIndi( TYPE_FS537_AD_ZFold1stPosAdj_PaperTypeThin, m_ss_BakFinisherZFoldFirstThin );		break;
		case TYPE_FS537_AD_ZFold1stPosAdj_PaperTypeRecycle:		setPrinterIndi( TYPE_FS537_AD_ZFold1stPosAdj_PaperTypeRecycle, m_ss_BakFinisherZFoldFirstRecycle );	break;
		default:		break;
		}
		break;
	default: LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); break;
	}
	setupGamen();
}
