/**
* @Class  	  : PServiceSystemAuthenticationFunctionEnabledActivation::I2BOD10000.
* @brief      : Page event.
* @note       : None.
* @param      : [I]  uchar option - Rotation button press value.
* @return     : void
*/
//=======================================================================================================.
void PServiceSystemAuthenticationFunctionEnabledActivation::procGoToPage(uchar option)
{
	switch( option ){
    	case BTNID_AUTHENTICATIONFUNCTIONENABLED_FUNCTIONCODE1:
			// Launch the Keyboard screen.
			nextGamen = &gp_ServiceSystemAuthenticationFunctionEnabledFunctionCodeInput; // I2BOD11000.
			break;
		default:
			break;
	}
}

//=======================================================================================================.
/**
* @Class  	  : PServiceSystemAuthenticationFunctionEnabledActivation::I2BOD10000.
* @brief      : Button event.
* @note       : None.
* @param      : [I]  uchar option - Rotation button press value.
* @return     : void
*/
//=======================================================================================================.
void PServiceSystemAuthenticationFunctionEnabledActivation::procButtonOn(uchar option)
{
	APIC_Enabler* pc_Enabler = APIC_Enabler::newInstance(); // APIC_Enabler is used here for Enabling Licenses.
	if ( NULL == pc_Enabler ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	
	switch( option ){
    	case BTNID_AUTHENTICATIONFUNCTIONENABLED_FUNCTIONCODE:	//「機能ｺｰﾄﾞ」Key.
			// Enable function code
			m_uc_FunctionCodeUSB = 0;
			break;
		case BTNID_AUTHENTICATIONFUNCTIONENABLED_USB:			//「USB」Key.
			// Enable USB.
			m_uc_FunctionCodeUSB = 1;
			break;
		case BTNID_AUTHENTICATIONFUNCTIONENABLED_APPLY:			//「確定」Key.
			// Enable Apply Button.
			bl_NoAcceptBtnFlag = True; // Set the Flag to True for Blocking all the Key Events when Apply Key is Pressed.
			m_bl_Apply = True;
			if ( 0 == m_uc_FunctionCodeUSB ) {
				// Call the API for Function Code Enable.
				pc_Enabler->req_LicenceFunctionEnable((uchar*) m_uc_AuthenticationFunctionCode, True, ans_LicenseFunctionEnable);
			} else if ( 1 == m_uc_FunctionCodeUSB ) {
				//Call the API for USB Function Code Import Enable.
				pc_Enabler->req_LicenceFunctionCodeImport( ans_LicenseFunctionCodeImport);
			}
			break;
		default:
			break;
	}
	setupGamen(); // Call the SetupGamen for refresh immediately.
}

