/**
* @Class  	  : PServiceSystemAuthenticationFunctionEnabledActivation::I2BOD10000.
* @brief      : Answer function.
* @note       : None.
* @param      : [I]  TYPE_LicenceFunctionEnable e_Result Callback result value.
* @return     : void
*/
//=======================================================================================================.
void PServiceSystemAuthenticationFunctionEnabledActivation::ans_LicenseFunctionCodeImport( TYPE_LicenceFunctionEnable e_Result )
{
	// Set the Callback type for USB Function Code Import Enabler.
	CallBackIndi( TYPE_PNL_CallBack_AuthenticationFunctionEnabled_USBCodeImport );
// comment 2015/06/09 OPS1 Sky東島 [Helios][CQ514281].
	m_e_result = e_Result;
}
	
//=======================================================================================================.
/**
* @Class  	  : PServiceSystemAuthenticationFunctionEnabledActivation::I2BOD10000.
* @brief      : Callback key.
* @note       : None.
* @param      : [I] TYPE_PNL_CallBack.
* @return     : void
*/
//=======================================================================================================.
void PServiceSystemAuthenticationFunctionEnabledActivation::procCallBack(TYPE_PNL_CallBack e_PNL_CallBack)
{
	switch( e_PNL_CallBack ){
		case TYPE_PNL_CallBack_AuthenticationFunctionEnabled_FunctionCode:
			m_uc_FunctionCodeUSB = 0;	// Enable Function Code Area.
			m_bl_Apply = False; 		// To Hide Left Arrow and Apply Message.
			// To Clear the function code input field.
			// comment [2015/09/10] [OSP1金子] [MinervaSBK] [CQ514592] 入力失敗時にクリアしないようにする
			//memset(m_uc_AuthenticationFunctionCode, 0, sizeof(m_uc_AuthenticationFunctionCode));
			if( ( TYPE_LicenceFunctionEnable_OK_Reboot == m_e_result ) || ( TYPE_LicenceFunctionEnable_OK_NoReboot == m_e_result ) ){
				memset(m_uc_AuthenticationFunctionCode, 0, sizeof(m_uc_AuthenticationFunctionCode));
			}		
			PNLC_AuthenticationFunctionCodeSettingLib::getInstance()->setAuthenticationFunctionCode( (char*)m_uc_AuthenticationFunctionCode );
			bl_NoAcceptBtnFlag = False; // Revert Back the No Accept Button Flag for Accepting Events.
			break;
		case TYPE_PNL_CallBack_AuthenticationFunctionEnabled_USBCodeImport:
			m_uc_FunctionCodeUSB = 1;	// Enable USB Code Area.
			m_bl_Apply = False;			// To Hide Left Arrow and Apply Message.
			bl_NoAcceptBtnFlag = False;// Revert Back the No Accept Button Flag for Accepting Events.
			break;
		default:
			PServiceFunctionEnableStartCom::procCallBack(e_PNL_CallBack);
			break;
	}
	setupGamen(); // Refresh Immediately.
}

