//=======================================================================================================.
/**
* @Class  	  : PServiceSystemAuthenticationFunctionEnabledActivation::I2BOD10000.
* @brief      : Index Button key.
* @note       : None.
* @param      : [I]  uchar option.
* @return     : void
*/	
//=======================================================================================================.
void PServiceSystemAuthenticationFunctionEnabledActivation::procIndexButton(uchar option)
{
	APIC_SystemInfo* pc_SystemInfo = APIC_SystemInfo::newInstance();
	if (NULL == pc_SystemInfo) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	
	switch( option ){
		case BTNID_AUTHENTICATIONFUNCTIONENABLED_LIST:
			// IF NONE of the function list are available then raise NG Sound.
			if (True == m_bl_FunctionListNone) {
				MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
			} else {
				nextGamen = &gp_ServiceSystemAuthenticationFunctionEnabled_List;	// I2BOD20000.
			}
			break;
		default:
			PServiceFunctionEnableStartCom::procIndexButton(option);
			break;
	}
}

//comment 2015/03/18 HCLT-Suresh [Helios][KRQ-101] Authentication Function Enabled Function Code Input Screen I2BOD11000.
//======================================================================================================================.
/**
* @Class  :	PServiceSystemAuthenticationFunctionEnabledFunctionCodeInput I2BOD11000.
* @brief  : Screen startup processing.
* @note   : None.
* @param  : None.
* @return : None.
*/
//======================================================================================================================.
void PServiceSystemAuthenticationFunctionEnabledFunctionCodeInput::startGamen()
{
	PServiceRDModeNtKeybordCom::startGamen();						// Base class call.
	
	char sc_FuntionCodeInput[ TYPD_FunctionCodeMaxSize ];			// Used to Fetch the Function code from library.
	memset(sc_FuntionCodeInput, 0, sizeof(sc_FuntionCodeInput));	// Initialization.
	
	// Get the Current Function Code from Library.
	PNLC_AuthenticationFunctionCodeSettingLib::getInstance()->getAuthenticationFunctionCode( (char*)sc_FuntionCodeInput, sizeof(sc_FuntionCodeInput) );
	
	// Assign the length of the input field
	setKeyboardData((char*)sc_FuntionCodeInput, (TYPD_FunctionCodeMaxSize-1), 64 );
	Kbd_ServiceInputKeybord.setChangeEnlKeybord( PLBD_Enl_KBD_Initial );
	
	// Set the keyboard type as Email.
	Kbd_ServiceInputKeybord = PLBC_ConvertKeybord( PLBD_KBT_EMail, 72, 124, True, True );
	Kbd_ServiceInputKeybord.GetCursor(NULL);
	Kbd_ServiceInputKeybord.showKeybord();
	
	// Assign the background part.
	pa_DispField = &Btx_AuthenticationFunctionEnabledFunctionCodeKeybordInput;
	
	// Initialize the Cursor.
	c_SlideTextMgr.init_CLCD( sc_StrKeyboard, sc_KeyboardWidth, ss_MaxInputNum, pa_DispField, EP_CharSet_USASCII );
	pa_DispField->setCursorPosition( ( short )strlen(sc_StrKeyboard) );
	
	// Set the Keyboard Type.
	Kbd_ServiceInputKeybord.setKeybordType(PLBD_KBT_EMail);
}

//======================================================================================================================.
/**
* @Class  	  :	PServiceSystemAuthenticationFunctionEnabledFunctionCodeInput I2BOD11000.
* @brief      : OK key.
* @note       : None.
* @param      : [I]  uchar option - Ok key press value.
* @return     : void
*/
//======================================================================================================================.
void PServiceSystemAuthenticationFunctionEnabledFunctionCodeInput::procOk(uchar option)
{
	// Set the entered function code to the library.
	PNLC_AuthenticationFunctionCodeSettingLib::getInstance()->setAuthenticationFunctionCode( (char*)sc_StrKeyboard );
	// Launch the Activation Screen.
	nextGamen = &gp_ServiceSystemAuthenticationFunctionEnabled_Activation; // I2BOD10000.
}
//======================================================================================================================.
/**
* @Class  	  :	PServiceSystemAuthenticationFunctionEnabledFunctionCodeInput I2BOD11000.
* @brief      : Cancel key.
* @note       : None.
* @param      : [I]  uchar option - Cancel key press value.
* @return     : void
*/
//======================================================================================================================.
void PServiceSystemAuthenticationFunctionEnabledFunctionCodeInput::procGoToPage(uchar option)
{
	// Cancel Key Event is Handled here.
	switch (option) {
		case 60:
			// Launch the Activation Screen.
			nextGamen = &gp_ServiceSystemAuthenticationFunctionEnabled_Activation;	//I2BOD10000.
			break;
		default:
			break;
	}
}

//comment 2015/03/18 HCLT-Suresh [Helios][KRQ-101] Authentication Function Enabled Function List Screen I2BOD20000.
//======================================================================================================================.
/**
* @Class  : PServiceSystemAuthenticationFunctionEnabledList I2BOD20000.
* @brief  : Screen startup processing.
* @note   : None.
* @param  : None.
* @return : None.
*/
//======================================================================================================================.
void PServiceSystemAuthenticationFunctionEnabledList::startGamen() 
{
	PServiceToSystemMenu2P2Com::startGamen(); //Base class call.
	// comment 2016/03/14 HCLT-Krishna [ZeusSBK][CQ525643] Getting the values from API.
	APIC_SystemInfo* pc_SystemInfo = APIC_SystemInfo::newInstance();
	if ( NULL == pc_SystemInfo) {
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if (NULL !=pc_BFW_System) {
//			pc_BFW_System ->registDetailCode(PNLD_DetailCode_Admin_0x1900660010D98501);
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}
	ushort k = 0;
	for ( k = 0; k < PNLD_AUTHENTICATIONFUNCTIONENABLEDLISTMAX; k++ )	{
		switch ( st_authFunctionEnabledfunctionCodeListTbl[k].e_ApplicationId )	{
			case PNLE_APPLICATION_AIRPRINT:
				{			
					char sc_AirprintLicenceVersion[TYPE_AirPrintLicenceVer_Size];														//Buffer to store Airprint License.
					memset ( sc_AirprintLicenceVersion, 0 , sizeof( sc_AirprintLicenceVersion ) );					
					TYPE_AirPrintLicence e_AirPrintLicence = pc_SystemInfo->getAirPrintLicenceVersion( sc_AirprintLicenceVersion );		// To get the Airprint enable status.
					
					if ( TYPE_AirPrintLicence_None != e_AirPrintLicence ) {
						char sc_ApplicationName_Airprint[PNLD_ApplicationName_License_Max];
						memset( sc_ApplicationName_Airprint , 0 , sizeof( sc_ApplicationName_Airprint ) );					
						memset( st_authFunctionEnabledfunctionCodeListTbl[k].sc_ApplicationNameAndLicenseVer, 0 ,
							sizeof( st_authFunctionEnabledfunctionCodeListTbl[k].sc_ApplicationNameAndLicenseVer ) );
						
						st_authFunctionEnabledfunctionCodeListTbl[k].bl_Installed = True;
						LIBF_ConvertToUTF8( (LIBE_CharSet)getCharSetForPanel(),
							(char*)getTextPartsPointer( st_authFunctionEnabledfunctionCodeListTbl[k].text_id_serv ),
							sc_ApplicationName_Airprint, sizeof( sc_ApplicationName_Airprint ));										// Convert Application Name to UTF8 format.
						snprintf( st_authFunctionEnabledfunctionCodeListTbl[k].sc_ApplicationNameAndLicenseVer ,
							sizeof( st_authFunctionEnabledfunctionCodeListTbl[k].sc_ApplicationNameAndLicenseVer ) ,
							"%s %s" , sc_ApplicationName_Airprint , sc_AirprintLicenceVersion );										// Appending Application Name and license.
					} else {
						st_authFunctionEnabledfunctionCodeListTbl[k].bl_Installed = False;
					}
				}
				break;	
			case PNLE_APPLICATION_MOPRIA:
				{		
					char sc_MopriaLicenceVersion[TYPE_MopriaLicenceVer_Size];													//Buffer to store Mopria License.
					memset ( sc_MopriaLicenceVersion, 0 , sizeof( sc_MopriaLicenceVersion ) );					
// comment 2019/02/26 HCLT-Shalini [EagleH][制御構成変更_No.64_Mopria1.3対応] Addition of API info. for Mopria Scan Version .
					char sc_MopriaLicenceVersion_Scan[TYPE_MopriaLicenceVer_Size];																//Buffer to store Mopria Scan License.
					memset( sc_MopriaLicenceVersion_Scan, 0 , sizeof( sc_MopriaLicenceVersion_Scan ) );					
					TYPE_MopriaLicence e_MopriaLicence = pc_SystemInfo->getMopriaLicenceVersion( sc_MopriaLicenceVersion );						// To get the Mopria enable status.	
					TYPE_MopriaScanLicence e_MopriaScanLicence =  pc_SystemInfo-> getMopriaScanLicenceVersion( sc_MopriaLicenceVersion_Scan );	// To get the Mopria Scan enable status.
					if ( TYPE_MopriaLicence_None != e_MopriaLicence && TYPE_MopriaScanLicence_None != e_MopriaScanLicence) {
						char sc_ApplicationName_Mopria[PNLD_ApplicationName_License_Max];
						memset( sc_ApplicationName_Mopria , 0 , sizeof( sc_ApplicationName_Mopria ) );
						char sc_ApplicationName_MopriaScan[PNLD_ApplicationName_License_Max];
						memset( sc_ApplicationName_MopriaScan , 0 , sizeof( sc_ApplicationName_MopriaScan ) );
						char sc_ApplicationName_MopriaClose[PNLD_ApplicationName_License_Max];
						memset( sc_ApplicationName_MopriaClose , 0 , sizeof( sc_ApplicationName_MopriaClose ) );
						memset( st_authFunctionEnabledfunctionCodeListTbl[k].sc_ApplicationNameAndLicenseVer, 0 ,
							sizeof( st_authFunctionEnabledfunctionCodeListTbl[k].sc_ApplicationNameAndLicenseVer ) );
						
						st_authFunctionEnabledfunctionCodeListTbl[k].bl_Installed = True;
// comment 2019/05/23 HCLT-Shalini [EagleH][OP_BTS-5062] Changing the getCharSetForPanel() to getCharSetForCAPI() .
//						LIBF_ConvertToUTF8( (LIBE_CharSet)getCharSetForPanel(),
						LIBF_ConvertToUTF8( (LIBE_CharSet)getCharSetForCAPI(),
							(char*)getTextPartsPointer( st_authFunctionEnabledfunctionCodeListTbl[k].text_id_serv ),
							sc_ApplicationName_Mopria, sizeof( sc_ApplicationName_Mopria ));											// Convert Application Name to UTF8 format.
// comment 2019/02/26 HCLT-Shalini [EagleH][制御構成変更_No.64_Mopria1.3対応] Addition of API info. for Mopria Scan Version .
//						LIBF_ConvertToUTF8( (LIBE_CharSet)getCharSetForPanel(),
//							(char*)getTextPartsPointer( s_pNOTITMDotScan_W056H016I ),
						LIBF_ConvertToUTF8( (LIBE_CharSet)getCharSetForCAPI(),
							(char*)getTextPartsPointer( s_pITMDotScan_W056H016I ),
							 sc_ApplicationName_MopriaScan, sizeof( sc_ApplicationName_MopriaScan));									// Convert Application Name to UTF8 format.
//						LIBF_ConvertToUTF8( (LIBE_CharSet)getCharSetForPanel(),
						LIBF_ConvertToUTF8( (LIBE_CharSet)getCharSetForCAPI(),
							(char*)getTextPartsPointer( s_pNOTITMRightbracket_W016H016I ),
							 sc_ApplicationName_MopriaClose, sizeof( sc_ApplicationName_MopriaClose));									// Convert Application Name to UTF8 format.
//						snprintf( st_authFunctionEnabledfunctionCodeListTbl[k].sc_ApplicationNameAndLicenseVer ,
//							sizeof( st_authFunctionEnabledfunctionCodeListTbl[k].sc_ApplicationNameAndLicenseVer ) ,
//							"%s %s" , sc_ApplicationName_Mopria , sc_MopriaLicenceVersion );									// Appending Application Name and license.
// comment 2019/03/14 HCLT-Shalini [EagleH][OP_BTS-4093] Changing the Display version of Mopria.
						if ( strncmp( sc_MopriaLicenceVersion, TYPE_MopriaLicenceVer2_0_1_Str, TYPE_MopriaLicenceVer_Size ) == 0 ) {
							snprintf( ( char* )sc_MopriaLicenceVersion, sizeof( sc_MopriaLicenceVersion ),TYPE_MopriaLicenceVer2_0_Str);
						}						
						snprintf( st_authFunctionEnabledfunctionCodeListTbl[k].sc_ApplicationNameAndLicenseVer ,
							sizeof( st_authFunctionEnabledfunctionCodeListTbl[k].sc_ApplicationNameAndLicenseVer ) ,		
							"%s%s %s%s%s" , sc_ApplicationName_Mopria , sc_MopriaLicenceVersion , sc_ApplicationName_MopriaScan, sc_MopriaLicenceVersion_Scan ,sc_ApplicationName_MopriaClose );									// Appending Application Name and license.
					} else {
						st_authFunctionEnabledfunctionCodeListTbl[k].bl_Installed = False;
					}
				}	
				break;
			case PNLE_APPLICATION_WIFIDIRECT:
				{					
					TYPE_WfdLicence e_WfdLicence = PnlComGetSystemInfo()->getWfdLicenceStatus();											// To get the Wi-fi Direct enable status.
					
					if ( TYPE_WfdLicence_Disable != e_WfdLicence ) {
						char sc_ApplicationName_wifi[PNLD_ApplicationName_License_Max];
						memset( sc_ApplicationName_wifi , 0 , sizeof( sc_ApplicationName_wifi ) );
						memset( st_authFunctionEnabledfunctionCodeListTbl[k].sc_ApplicationNameAndLicenseVer, 0 ,
							sizeof( st_authFunctionEnabledfunctionCodeListTbl[k].sc_ApplicationNameAndLicenseVer ) );
						
						st_authFunctionEnabledfunctionCodeListTbl[k].bl_Installed = True;
						LIBF_ConvertToUTF8( (LIBE_CharSet)getCharSetForPanel(),
							(char*)getTextPartsPointer( st_authFunctionEnabledfunctionCodeListTbl[k].text_id_serv ),
							 sc_ApplicationName_wifi, sizeof( sc_ApplicationName_wifi ));													// Convert Application Name to UTF8 format.
						strncpy( st_authFunctionEnabledfunctionCodeListTbl[k].sc_ApplicationNameAndLicenseVer , sc_ApplicationName_wifi,
							sizeof( st_authFunctionEnabledfunctionCodeListTbl[k].sc_ApplicationNameAndLicenseVer ) -1 );					// Appending Application Name and license.
					} else {
						st_authFunctionEnabledfunctionCodeListTbl[k].bl_Installed = False;
					}
				}
				break;
			default: LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, ( char* )"Assert Failed!" );	break;
		}
	}			
}
