//======================================================================================================================.
/**
* @Class  : PServiceSystemAuthenticationFunctionEnabledList I2BOD20000.
* @brief  : Screen setup processing.
* @note   : None.
* @param  : [I]short option.
* @return : None.
* @author : 2016/03/14 HCLT_Krishna[ZeusSBK][CQ525643].	
*/
//======================================================================================================================.
void PServiceSystemAuthenticationFunctionEnabledList::setupGamen( short option ) 
{
	PServiceToSystemMenu2P2Com::setupGamen(); 					// Base Class Call.
	Rbt_ServiceAuthenticationFunctionEnabledMenu.select(1);		// Selecting the Function List Button.
	ushort us_ExistRow = 0;										// Number of Existing Licenses.
	short ss_Cnt = 0;
	for ( ss_Cnt = 0; ss_Cnt < PNLD_AUTHENTICATIONFUNCTIONENABLEDLISTMAX; ss_Cnt++ ) {
	    if ( True == st_authFunctionEnabledfunctionCodeListTbl[ss_Cnt].bl_Installed ) {
			Tfd_ServiceAuthenticationFunctionEnabledFunctionCodeList[us_ExistRow].changeExternalText( (uchar*)st_authFunctionEnabledfunctionCodeListTbl[ss_Cnt].sc_ApplicationNameAndLicenseVer ,
				sizeof( st_authFunctionEnabledfunctionCodeListTbl[ss_Cnt].sc_ApplicationNameAndLicenseVer ) , getCharSetForPanel() );
			Tfd_ServiceAuthenticationFunctionEnabledFunctionCodeList[us_ExistRow].showEnable( True );
			us_ExistRow++;		
   	    }
	}
	for ( ss_Cnt = (PNLD_AUTHENTICATIONFUNCTIONENABLEDLISTMAX-1) ; ss_Cnt >= us_ExistRow ; ss_Cnt-- ) {
		Tfd_ServiceAuthenticationFunctionEnabledFunctionCodeList[ss_Cnt].showEnable( False );
	}
}

//======================================================================================================================.
/**
* @Class      : PServiceSystemAuthenticationFunctionEnabledList I2BOD20000.
* @brief      : OK key.
* @note       : None.
* @param      : [I]  uchar option - Ok key press value.
* @return     : void
*/
//======================================================================================================================.
void PServiceSystemAuthenticationFunctionEnabledList::procOk(uchar option) 
{
	// Launch the page 3 screen.
	nextGamen = &gp_ServiceSystemMenu2P3_DoAm; // 91500b.
}

//=======================================================================================================.
/**
* @Class  	  : PServiceSystemAuthenticationFunctionEnabledActivation::I2BOD10000.
* @brief      : Index Button key.
* @note       : None.
* @param      : [I]  uchar option.
* @return     : void
*/	
//=======================================================================================================.
void PServiceSystemAuthenticationFunctionEnabledList::procIndexButton(uchar option)
{
	APIC_SystemInfo* pc_SystemInfo = APIC_SystemInfo::newInstance();
	if (NULL == pc_SystemInfo) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	
	switch( option ){
		case BTNID_AUTHENTICATIONFUNCTIONENABLED_ACTIVATION:
			nextGamen = &gp_ServiceSystemAuthenticationFunctionEnabled_Activation;	// I2BOD10000.
			break;
		default:
			PServiceToSystemMenu2P2Com::procIndexButton(option);
			break;
	}
}
// 2015/12/10 [MAv4][RQ-505] バックアップサーバー設定追加 日立 野口.
PNLE_ServiceBackupServerSetting	 PServiceBackupServerSettingCom::m_e_BackupServerSettingGamen = PNLE_ServiceBackupServerSetting_Enable;
//================================================================================================.
// 概要    :共通_バックアップサーバー設定共通 : コンストラクタ.
//================================================================================================.
PServiceBackupServerSettingCom::PServiceBackupServerSettingCom( PDisplayParts** partsTable, short partsNumber, Bool isNoWarning )
	 : PServiceNoFunctionCodeCom( partsTable, partsNumber, isNoWarning )
{
	m_bl_FromMenu = False;
	m_pc_SettingInfo = PServiceBackupServerSettingData::getInstance();
}
//================================================================================================.
// 概要    :共通_バックアップサーバー設定共通 : 画面開始処理.
//================================================================================================.
void PServiceBackupServerSettingCom::startGamen()
{
	PServiceNoFunctionCodeCom::startGamen();
	
	// メニューから遷移したときのみ処理を実施する.
	if( True == m_bl_FromMenu ){
		m_pc_SettingInfo->loadSettings();											// CommonAPIから設定値を取得する.
		m_e_BackupServerSettingGamen = PNLE_ServiceBackupServerSetting_Enable;		// インデックスキーの選択状態を機能設定に変更する.
		m_bl_FromMenu = False;
	}
}
//================================================================================================.
// 概要    :共通_バックアップサーバー設定共通 : 表示部品のセットアップ.
//================================================================================================.
void PServiceBackupServerSettingCom::setupGamen( short ss_option )
{
	PServiceNoFunctionCodeCom::setupGamen( ss_option );
	
	switch( m_e_BackupServerSettingGamen ){
		case PNLE_ServiceBackupServerSetting_Enable:				// 機能設定.
			Rbt_ServiceBackupServer_Setting.select( 0 );
			break;
		case PNLE_ServiceBackupServerSetting_UserName:				// ﾕｰｻﾞｰ名.
			Rbt_ServiceBackupServer_Setting.select( 1 );
			Rbt_ServiceBackupServer_ServerSetting.select( 0 );
			break;
		case PNLE_ServiceBackupServerSetting_Password:				// ﾊﾟｽﾜｰﾄﾞ.
			Rbt_ServiceBackupServer_Setting.select( 1 );
			Rbt_ServiceBackupServer_ServerSetting.select( 1 );
			break;
		default: break;
	}
	
	// 機能設定が「使用しない」の場合は、サーバー設定は非表示.
	Key_ServiceBackupServer_ServerSetting.showEnable( m_pc_SettingInfo->getUseSetOffOn() );
}
//================================================================================================.
// 概要    :共通_バックアップサーバー設定共通 : OKキー押下処理.
//================================================================================================.
void PServiceBackupServerSettingCom::procOk( uchar uc_option )
{
	// 設定値をチェックし、必要事項が欠けているいる場合は拒否する.
	if( False == m_pc_SettingInfo->checkSettings()){
		setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}
	m_pc_SettingInfo->commitSettings();							// CommonAPIへ設定値を設定する.
	// セキュリティー設定／ﾃﾞｰﾀﾊﾞｯｸｱｯﾌﾟ／メニュー画面に遷移.
	nextGamen = &gp_ServiceDataBackupMenu;
}
