PServiceBackupServerSettingData::PServiceBackupServerSettingData()
{
	clear();
}
//================================================================================================.
// 概要    :共通_バックアップサーバー設定データクラス : インスタンス取得.
//================================================================================================.
PServiceBackupServerSettingData* PServiceBackupServerSettingData::getInstance()
{
	static PServiceBackupServerSettingData pc_BackupServerSettings;
	return &pc_BackupServerSettings;
}
//================================================================================================.
// 概要    :共通_バックアップサーバー設定データクラス : 設定の読み込み処理.
//================================================================================================.
void PServiceBackupServerSettingData::loadSettings()
{
	TYPS_BackupServerSettingInfo	s_SettingInfo;				// バックアップサーバー設定.

	APIC_BackupServerSetting* pc_BackupServerSettingInfo = APIC_BackupServerSetting::newInstance();
	if (NULL == pc_BackupServerSettingInfo) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	// クラス変数データを初期化する.
	clear();
	// バックアップサーバー設定 取得.
	pc_BackupServerSettingInfo->getSetting( &s_SettingInfo );
	// クラス変数へデータを保持する.
	m_bl_UseSetOffOn = s_SettingInfo.m_b_Enable;									// 機能設定.
// comment 2018/02/16 【HCL-Ajit】 [IT5_4.2] Klockwork Changes ID: 381859 [SV.STRBO.BOUND_COPY.UNTERM].
//	strncpy( m_sc_UserName , s_SettingInfo.m_sc_UserID , sizeof(m_sc_UserName));	// ユーザー名.
//	strncpy( m_sc_Password , s_SettingInfo.m_sc_Password , sizeof(m_sc_Password));	// パスワード.
	strncpy( m_sc_UserName , s_SettingInfo.m_sc_UserID , sizeof(m_sc_UserName) - 1);	// ユーザー名.
	strncpy( m_sc_Password , s_SettingInfo.m_sc_Password , sizeof(m_sc_Password) - 1);	// パスワード.
}
//================================================================================================.
// 概要    :共通_バックアップサーバー設定データクラス : 設定の読み込み処理.
//================================================================================================.
void PServiceBackupServerSettingData::commitSettings()
{
	TYPS_BackupServerSettingInfo	s_SettingInfo;				// バックアップサーバー設定.
	
	APIC_BackupServerSetting* pc_BackupServerSettingInfo = APIC_BackupServerSetting::newInstance();
	if (NULL == pc_BackupServerSettingInfo) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	// バックアップサーバー設定 取得.
	pc_BackupServerSettingInfo->getSetting( &s_SettingInfo );
	
	// クラス変数データを設定する.
	s_SettingInfo.m_b_Enable = m_bl_UseSetOffOn;													// 機能設定.
// comment 2018/02/16 【HCL-Ajit】 [IT5_4.2] Klockwork Changes ID: 381859 [SV.STRBO.BOUND_COPY.UNTERM].
//	strncpy( s_SettingInfo.m_sc_UserID , m_sc_UserName , sizeof(s_SettingInfo.m_sc_UserID));		// ユーザー名.
//	strncpy( s_SettingInfo.m_sc_Password , m_sc_Password , sizeof(s_SettingInfo.m_sc_Password));	// パスワード.
	strncpy( s_SettingInfo.m_sc_UserID , m_sc_UserName , sizeof(s_SettingInfo.m_sc_UserID) - 1);		// ユーザー名.
	strncpy( s_SettingInfo.m_sc_Password , m_sc_Password , sizeof(s_SettingInfo.m_sc_Password) - 1);	// パスワード.

	// バックアップサーバー設定 取得.
	pc_BackupServerSettingInfo->setSetting( &s_SettingInfo );
}
//================================================================================================.
// 概要    :共通_バックアップサーバー設定データクラス : 設定データのクリア処理.
//================================================================================================.
void PServiceBackupServerSettingData::clear()
{
	m_bl_UseSetOffOn = False;										// 機能設定.
	memset( m_sc_UserName , 0x00 , sizeof(m_sc_UserName));			// ユーザー名.
	memset( m_sc_Password , 0x00 , sizeof(m_sc_Password));			// パスワード.
}
//================================================================================================.
// 概要    :共通_バックアップサーバー設定データクラス : 設定の読み込み処理.
//================================================================================================.
Bool PServiceBackupServerSettingData::checkSettings()
{
	// 機能設定が「使用する」かつ、ﾕｰｻﾞｰ名またはﾊﾟｽﾜｰﾄﾞが0文字.
	if(( True == m_bl_UseSetOffOn ) && ( '\0' == m_sc_UserName[0] || '\0' == m_sc_Password[0] )){
		return False;
	}
	return True;
}
//================================================================================================.
// 概要    :共通_バックアップサーバー設定データクラス : ユーザー名設定処理.
//================================================================================================.
void PServiceBackupServerSettingData::setUserName( const char* sc_UserID )
{
	if( NULL == sc_UserID ){
		return;
	}
// comment 2018/02/16 【HCL-Ajit】 [IT5_4.2] Klockwork Changes ID: 381859 [SV.STRBO.BOUND_COPY.UNTERM].
//	strncpy(m_sc_UserName,sc_UserID,TYPD_BackupServerSetting_UserIDMaxLen);
	strncpy(m_sc_UserName,sc_UserID, sizeof( m_sc_UserName ) - 1 );
};
//================================================================================================.
// 概要    :共通_バックアップサーバー設定データクラス : パスワード設定処理.
//================================================================================================.
void PServiceBackupServerSettingData::setPassword( const char* sc_Password )
{
	if( NULL == sc_Password ){
		return;
	}
// comment 2018/02/16 【HCL-Ajit】 [IT5_4.2] Klockwork Changes ID: 381859 [SV.STRBO.BOUND_COPY.UNTERM].
//	strncpy(m_sc_Password,sc_Password,TYPD_BackupServerSetting_PasswordMaxLen);
	strncpy(m_sc_Password,sc_Password, sizeof( m_sc_Password ) - 1 );
};


