//================================================================================================.
void PServiceBackupServerEnableSetting::procButtonOn( uchar uc_option )
{
	switch( uc_option ){
		case BTNID_KEY_ServiceBackupServer_EnableSetting_On:	m_pc_SettingInfo->setUseSetOffOn(True);		break;			// 使用する.
		case BTNID_KEY_ServiceBackupServer_EnableSetting_Off:	m_pc_SettingInfo->setUseSetOffOn(False);	break;			// 使用しない.
		default:																							break;
	}
	setupGamen( 0 );
}
