//================================================================================================.
// 概要    :M0B0031100_バックアップサーバー設定／サーバー設定／ユーザー名入力 : 画面開始処理.
//================================================================================================.
void PServiceBackupServerUserNameInput::startGamen()
{
	// データクラスからユーザー名を取得する.
// Comment 2020/01/22 [HCL-Shalini] [EagleZ+] [OP_BTS-19428] strnlen is used instead sizeof().
//// Comment 2019/12/02 [HCL-Taqiuddin] [KLOC ID:106296] [KLOC TYPE:ABV.GENERAL].
//	if ( sizeof( m_pc_SettingInfo->getUserName()) < sizeof (m_sc_StrKeyboard) ) {
//		memcpy( m_sc_StrKeyboard, m_pc_SettingInfo->getUserName(), sizeof( m_pc_SettingInfo->getUserName() ) - 1 );
	if ( strnlen( m_pc_SettingInfo->getUserName(),TYPD_BackupServerSetting_UserIDMaxLen) < sizeof (m_sc_StrKeyboard) ) {
		memset( m_sc_StrKeyboard, 0, sizeof( m_sc_StrKeyboard ) );
		memcpy( m_sc_StrKeyboard, m_pc_SettingInfo->getUserName(), strnlen( m_pc_SettingInfo->getUserName(),TYPD_BackupServerSetting_UserIDMaxLen )  );
	} else {
		memcpy( m_sc_StrKeyboard, m_pc_SettingInfo->getUserName(), sizeof( m_sc_StrKeyboard ) - 1 );
	}
	// 表示領域に文字列をセット.
	setKeyboardData( m_sc_StrKeyboard, PNLD_MAX_BackupServerUserNameLen , PNLD_ServiceDataBackupServerBackupInputWidth );
	m_bl_Password = False;
	m_bl_ShowPass = False;

	PServiceDataBackupKeyboardCom::startGamen();
}
