// 概要    :M0B0032100_バックアップサーバー設定／サーバー設定／パスワード入力 : コンストラクタ.
//================================================================================================.
PServiceBackupServerPasswordInput::PServiceBackupServerPasswordInput( PDisplayParts** partsTable, short partsNumber, Bool isNoWarning )
	 : PServiceDataBackupKeyboardCom( partsTable, partsNumber, isNoWarning )
	, m_uc_nowPageNum( PNLD_ServiceDecryptPasswordP1 )
	, m_us_dispErrMessage( s_Space1 )
{
	// 初期化.
	m_ss_Tx = PNLD_ServiceDataBackupServerBackupKeyboardTx;
	m_ss_Gy = PNLD_ServiceDataBackupServerBackupKeyboardGy;
	m_pc_DispField = &Btx_ServiceDataBackupKeyboardComInput2;
	m_e_CharSet = EP_CharSet_USASCII;

	// データクラスのインスタンス取得.
	m_pc_SettingInfo = PServiceBackupServerSettingData::getInstance();

	// 自クラスのメンバを初期化.
	memset( m_sc_nowPassword, '\0', sizeof( m_sc_nowPassword ) );
	memset( m_sc_newPassword, '\0', sizeof( m_sc_newPassword ) );
}
//================================================================================================.
// 概要    :M0B0032100_バックアップサーバー設定／サーバー設定／パスワード入力 : 画面開始処理.
//================================================================================================.
void PServiceBackupServerPasswordInput::startGamen()
{
	// エラーメッセージをクリア.
	m_us_dispErrMessage = s_Space1;

	// 自クラスのメンバを初期化.
	memset( m_sc_nowPassword, '\0', sizeof( m_sc_nowPassword ) );
	memset( m_sc_newPassword, '\0', sizeof( m_sc_newPassword ) );
	memset( m_sc_StrKeyboard, '\0', sizeof( m_sc_StrKeyboard ) );

	// アクセス用パスワードを共有メモリから取得.
	memcpy( m_sc_nowPassword, m_pc_SettingInfo->getPassword(), sizeof( m_sc_nowPassword ) );

	// 開始画面を設定.
	if( '\0' != m_sc_nowPassword[0] ) {						// パスワード設定済み.
		m_uc_nowPageNum = PNLD_ServiceDecryptPasswordP1;	// 現在のパスワード入力画面.
	} else {												// パスワード未設定.
		m_uc_nowPageNum = PNLD_ServiceDecryptPasswordP2;	// 新しいパスワード入力画面.
	}

	// 表示領域に文字列をセット.
	setKeyboardData( m_sc_StrKeyboard, PNLD_MAX_BackupServerPasswordLen , PNLD_ServiceDataBackupServerBackupInputWidth );
	m_bl_Password = True;
	m_bl_ShowPass = False;		// 初期状態での「**********」表示はしないため不要.

	PServiceDataBackupKeyboardCom::startGamen();
	Kbd_ServiceInputKeybord.setKeybord5Country( True );
	Kbd_ServiceInputKeybord.GetCursor( &Btx_ServiceDataBackupKeyboardComInput2 );
	Kbd_ServiceInputKeybord.showKeybord();
}
//================================================================================================.
// 概要    :M0B0032100_バックアップサーバー設定／サーバー設定／パスワード入力 : 表示部品のセットアップ.
//================================================================================================.
void PServiceBackupServerPasswordInput::setupGamen( short ss_option )
{
	// 親クラスをコール.
	PServiceDataBackupKeyboardCom::setupGamen( ss_option );
	// 入力禁止文字の非表示.
	Kbd_ServiceInputKeybord.setDisableKeyCharCode( KC_DisableKeyPattern15 );	// パターン15("ユーロ記号).

	// 表示テキストの変更.
	switch( m_uc_nowPageNum ) {
		case PNLD_ServiceDecryptPasswordP1: Txt_ServiceBackupServer_Password.changeText( s_ITMServiceCurrentPassword );	break;	// 現在のパスワード.
		case PNLD_ServiceDecryptPasswordP2: Txt_ServiceBackupServer_Password.changeText( s_ITMServiceNewPassword );		break;	// 新しいパスワード.
		case PNLD_ServiceDecryptPasswordP3: Txt_ServiceBackupServer_Password.changeText( s_ITMServiceReinputPassword );	break;	// 再入力パスワード.
		default: break;
	}
	Txt_ServiceBackupServer_PasswordErrMessage.changeText( m_us_dispErrMessage );		// エラーメッセージ.

}
//================================================================================================.
// 概要    :M0B0032100_バックアップサーバー設定／サーバー設定／パスワード入力 : OKキー押下処理.
// 変更履歴:2019/10/30 Sky大嶋 [セキュリティ技術v5][RQ824] パスワード規約拡張 API変更.
//================================================================================================.
void PServiceBackupServerPasswordInput::procOk( uchar uc_option )
{
	switch( m_uc_nowPageNum ) {
		case PNLD_ServiceDecryptPasswordP1:											//【現在のパスワード入力】.
			if( 0 == strncmp( m_sc_nowPassword, m_sc_StrKeyboard, TYPD_BackupServerSetting_PasswordMaxLen ) ) {
				m_us_dispErrMessage = s_Space1;										// エラーメッセージをクリア.
				m_uc_nowPageNum = PNLD_ServiceDecryptPasswordP2;
			} else {
				m_us_dispErrMessage = s_SSNowPassWordMissteke;						//「ﾊﾟｽﾜｰﾄﾞが一致しません」.
				setBuzzerType( PCGE_BuzzerType_InputNg );
			}
			// 入力文字列とカーソル位置を初期化.
			memset( m_sc_StrKeyboard, '\0', sizeof( m_sc_StrKeyboard ) );
			m_c_SlideTextMgr.init_CLCD( m_sc_StrKeyboard, m_sc_KeyboardWidth, m_ss_MaxInputNum, m_pc_DispField, getCharSetForPanel() );
			setupGamen( 0 );
			break;

		case PNLD_ServiceDecryptPasswordP2:											//【新しいパスワード入力】.
			// 入力パスワードの文字列チェックとパスワードエラーチェックが共にOKの場合次の処理に進む.
			if( ( '\0' != m_sc_StrKeyboard[0] )
//			    && ( True == APIC_BackupServerSetting::newInstance()->checkServerAccsessPassword( m_sc_StrKeyboard, m_sc_nowPassword ) ) ) {
			    && ( TYPE_CheckPwdRuleResult_Ok == APIC_BackupServerSetting::newInstance()->checkServerAccessPwdRule( m_sc_StrKeyboard) ) ) {
				memset( m_sc_newPassword, '\0', sizeof( m_sc_newPassword ) );
				strncpy( m_sc_newPassword , m_sc_StrKeyboard, sizeof( m_sc_newPassword ) -1 );
				m_us_dispErrMessage = s_Space1;										// エラーメッセージをクリア.
				m_uc_nowPageNum = PNLD_ServiceDecryptPasswordP3;
			} else {
				m_us_dispErrMessage = s_SSNewPassWordMissteke;						//「入力したﾊﾟｽﾜｰﾄﾞは使用できません」.
				setBuzzerType( PCGE_BuzzerType_InputNg );
			}
			// 入力文字列とカーソル位置を初期化.
			memset( m_sc_StrKeyboard, '\0', sizeof( m_sc_StrKeyboard ) );
			m_c_SlideTextMgr.init_CLCD( m_sc_StrKeyboard, m_sc_KeyboardWidth, m_ss_MaxInputNum, m_pc_DispField, getCharSetForPanel() );
			setupGamen( 0 );
			break;

		case PNLD_ServiceDecryptPasswordP3:											//【再入力パスワード入力】.
			if( 0 == strncmp( m_sc_newPassword, m_sc_StrKeyboard, TYPD_BackupServerSetting_PasswordMaxLen ) ) {
				// 共有メモリに新しいパスワードを設定し、元の画面に戻る.
				m_pc_SettingInfo->setPassword( m_sc_newPassword );
				nextGamen = &gp_ServiceBackupServerPassword;
			} else {
				// 入力文字列に新しいパスワードを設定し、新しいパスワード入力に戻る.
				strncpy( m_sc_StrKeyboard , m_sc_newPassword, TYPD_BackupServerSetting_PasswordMaxLen );
				m_c_SlideTextMgr.init_CLCD( m_sc_StrKeyboard, m_sc_KeyboardWidth, m_ss_MaxInputNum, m_pc_DispField, getCharSetForPanel() );
				setBuzzerType( PCGE_BuzzerType_InputNg );							// 拒否音を鳴動する.
				m_uc_nowPageNum = PNLD_ServiceDecryptPasswordP2;
				setupGamen( 0 );
			}
			break;
		default:
			break;
	}

}
//================================================================================================.
// 概要    :M0B0032100_バックアップサーバー設定／サーバー設定／パスワード入力 : 画面遷移処理.
//================================================================================================.
void PServiceBackupServerPasswordInput::procGoToPage( uchar uc_option )
{
	switch( uc_option ) {
		case 60:	nextGamen = &gp_ServiceBackupServerPassword;	break;		// キャンセルキー.
		default: 													break;
	}
}
