	memset( m_sc_UserName,	 	'\0', sizeof(m_sc_UserName));								// ﾕｰｻﾞｰ名.
	memset( m_sc_Password,	 	'\0', sizeof(m_sc_Password));								// ﾊﾟｽﾜｰﾄﾞ.
	m_bl_ProxyEnable			 = False;													// ﾌﾟﾛｷｼ.
	memset( m_sc_EncPassword,	'\0', sizeof(m_sc_EncPassword));							// 暗号化ﾊﾟｽﾜｰﾄﾞ.
	m_us_HoldPeriod				 = TYPD_BackupRestoreSettingExt_BackupDataHoldPeriodMin;	// データ保持時間(最小値で初期化).
	m_bl_FullBackupEnable		 = False;													// ﾌﾙﾊﾞｯｸｱｯﾌﾟ設定.
	m_e_FullBackupCycle			 = TYPE_BackupRestoreSettingExt_FullBackupCycle_Day;		// ﾌﾙﾊﾞｯｸｱｯﾌﾟ周期.
	m_uc_FullBackupCycleDay		 = TYPD_BackupRestoreSettingExt_FullBackupCycleDayMin;		// ﾌﾙﾊﾞｯｸｱｯﾌﾟ日周期(最小値で初期化).
	m_e_FullBackupWeekday		 = TYPE_BackupRestoreSettingExt_Weekday_Sun;				// ﾌﾙﾊﾞｯｸｱｯﾌﾟ曜日.
	m_uc_FullBackupHour			 = 0;														// ﾌﾙﾊﾞｯｸｱｯﾌﾟ時.
	m_uc_FullBackupMinute		 = 0;														// ﾌﾙﾊﾞｯｸｱｯﾌﾟ分.
	m_bl_DiffBackupEnable		 = False;													// 差分ﾊﾞｯｸｱｯﾌﾟ設定.
	m_e_DiffBackupCycle			 = TYPE_BackupRestoreSettingExt_DiffBackupCycle_Interval;	// 差分ﾊﾞｯｸｱｯﾌﾟ周期.
	m_uc_DiffBackupCycleTime	 = TYPD_BackupRestoreSettingExt_DiffBackupIntervalMin;		// 差分ﾊﾞｯｸｱｯﾌﾟ時間間隔(最小値で初期化).
	m_uc_DiffBackupHour			 = 0;														// 差分ﾊﾞｯｸｱｯﾌﾟ時.
	m_uc_DiffBackupMinute		 = 0;														// 差分ﾊﾞｯｸｱｯﾌﾟ分.
	m_e_ExtRestoreSettingServerSetting = PNLD_ServiceExtServerRestore_SelectBackupSetting;				// リストア設定／サーバー設定.
	memset( m_sc_ExtRestoreSettingURL,			'\0',	sizeof( m_sc_ExtRestoreSettingURL ) );			// リストア設定／WebDAV設定／URL.
	memset( m_sc_ExtRestoreSettingUserName,		'\0',	sizeof( m_sc_ExtRestoreSettingUserName ) );		// リストア設定／WebDAV設定／ユーザー名.
	memset( m_sc_ExtRestoreSettingPassword,		'\0',	sizeof( m_sc_ExtRestoreSettingPassword ) );		// リストア設定／WebDAV設定／パスワード.
	m_bl_ExtRestoreSettingProxy = False;																// リストア設定／WebDAV設定／プロキシ.
	memset( m_sc_ExtRestoreSettingEncPassword,	'\0',	sizeof( m_sc_ExtRestoreSettingEncPassword ) );	// リストア設定／暗号化パスワード.
	m_e_ExtRestoreTarget = TYPE_BackupRestoreSettingExt_Target_None;									// ﾘｽﾄｱ対象.
