//================================================================================================.
void PServiceExtServerBackupSettingInfo::loadServiceExtServerBackupSetting()
{
	TYPS_BackupRestoreExt_BackupSettingInfo st_SettingInfo;
	APIC_BackupRestoreSettingExt *pc_BackupRestoreSettingExt = APIC_BackupRestoreSettingExt::newInstance();
	if( NULL == pc_BackupRestoreSettingExt ) {
// comment 2017/1/6 [IT5-4.0] WP-903 RQ-505_新詳細コード対応 日立 村上幸.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
// 		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
// 		if ( NULL != pc_BFW_System ) {
// 			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19007001014E0001 );
// 		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}
	clear();
	pc_BackupRestoreSettingExt->getServerBackupSettingInfo(&st_SettingInfo);							// CommonAPIからデータ取得.
	// 取得したデータをLocalUIの一時領域へ設定(取得時は全データを取得).
	// ﾊﾞｯｸｱｯﾌﾟ設定の設定値をLocalUIの一時領域へ保存.
	m_bl_ExtServerSettingEnable			 = st_SettingInfo.m_b_Enable;									// 拡張サーバー設定_使用する／使用しない.
	m_bl_BoxFormatEnable				 = st_SettingInfo.m_b_BoxDocEnable;								// ﾎﾞｯｸｽ文書設定_対象／非対象.
	m_bl_ProxyEnable					 = st_SettingInfo.m_s_ServerInfo.m_b_ProxyEnable;				// ﾌﾟﾛｷｼ.
	m_us_HoldPeriod						 = st_SettingInfo.m_us_HoldPeriod;								// データ保持時間.
	memcpy( m_sc_URL,			 st_SettingInfo.m_s_ServerInfo.m_sc_URL,		 sizeof(m_sc_URL) );			// URL.
	memcpy( m_sc_UserName,		 st_SettingInfo.m_s_ServerInfo.m_sc_UserID,		 sizeof(m_sc_UserName));		// ﾕｰｻﾞｰ名.
	memcpy( m_sc_Password,		 st_SettingInfo.m_s_ServerInfo.m_sc_Password,	 sizeof(m_sc_Password));		// ﾊﾟｽﾜｰﾄﾞ.
	memcpy( m_sc_EncPassword,	 st_SettingInfo.m_sc_Password,					 sizeof(m_sc_EncPassword));		// 暗号化ﾊﾟｽﾜｰﾄﾞ.
	// 自動ﾊﾞｯｸｱｯﾌﾟの設定値を更新.
	m_bl_FullBackupEnable	 = st_SettingInfo.m_s_AutoBackupInfo.m_b_Enable;							// ﾌﾙﾊﾞｯｸｱｯﾌﾟ設定.
	m_e_FullBackupCycle		 = st_SettingInfo.m_s_AutoBackupInfo.m_e_FullBackupCycle;					// ﾌﾙﾊﾞｯｸｱｯﾌﾟ周期.
	m_uc_FullBackupCycleDay	 = st_SettingInfo.m_s_AutoBackupInfo.m_uc_FullBackupCycleDay;				// ﾌﾙﾊﾞｯｸｱｯﾌﾟ日周期.
	m_e_FullBackupWeekday	 = st_SettingInfo.m_s_AutoBackupInfo.m_e_FullBackupWeekday;					// ﾌﾙﾊﾞｯｸｱｯﾌﾟ曜日.
	m_uc_FullBackupHour		 = st_SettingInfo.m_s_AutoBackupInfo.m_uc_FullBackupHour;					// ﾌﾙﾊﾞｯｸｱｯﾌﾟ時.
	m_uc_FullBackupMinute	 = st_SettingInfo.m_s_AutoBackupInfo.m_uc_FullBackupMinute;					// ﾌﾙﾊﾞｯｸｱｯﾌﾟ分.
	m_bl_DiffBackupEnable	 = st_SettingInfo.m_s_AutoBackupInfo.m_b_DiffBackupEnable;					// 差分ﾊﾞｯｸｱｯﾌﾟ設定.
	m_e_DiffBackupCycle		 = st_SettingInfo.m_s_AutoBackupInfo.m_e_DiffBackupCycle;					// 差分ﾊﾞｯｸｱｯﾌﾟ周期.
	m_uc_DiffBackupCycleTime = st_SettingInfo.m_s_AutoBackupInfo.m_uc_DiffBackupCycleTime;				// 差分ﾊﾞｯｸｱｯﾌﾟ時間間隔.
	m_uc_DiffBackupHour		 = st_SettingInfo.m_s_AutoBackupInfo.m_uc_DiffBackupHour;					// 差分ﾊﾞｯｸｱｯﾌﾟ時.
	m_uc_DiffBackupMinute	 = st_SettingInfo.m_s_AutoBackupInfo.m_uc_DiffBackupMinute;					// 差分ﾊﾞｯｸｱｯﾌﾟ分.
}

