void PServiceExtServerBackupSettingInfo::loadServiceExtServerRestoreSetting()
{
	TYPS_BackupRestoreExt_BackupSettingInfo st_SettingInfo;
	APIC_BackupRestoreSettingExt *pc_BackupRestoreSettingExt = APIC_BackupRestoreSettingExt::newInstance();
	if( NULL == pc_BackupRestoreSettingExt ) {
// comment 2017/1/6 [IT5-4.0] WP-903 RQ-505_新詳細コード対応 日立 村上幸.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
// 		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
// 		if ( NULL != pc_BFW_System ) {
// 			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19007001014E0201 );
// 		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}
	clear();
	pc_BackupRestoreSettingExt->getServerBackupSettingInfo(&st_SettingInfo);							// CommonAPIからデータ取得.
	// 取得したデータをLocalUIの一時領域へ設定(取得時は全データを取得).
	// バックアップ設定の設定値をバックアップ設定保持用メンバーに格納.
	m_bl_ProxyEnable					 = st_SettingInfo.m_s_ServerInfo.m_b_ProxyEnable;															// バックアップ設定／WebDAV設定／プロキシ.
	memcpy( m_sc_URL,			 st_SettingInfo.m_s_ServerInfo.m_sc_URL,		 sizeof(m_sc_URL)			);										// バックアップ設定／WebDAV設定／URL.
	memcpy( m_sc_UserName,		 st_SettingInfo.m_s_ServerInfo.m_sc_UserID,		 sizeof(m_sc_UserName)		);										// バックアップ設定／WebDAV設定／ユーザー名.
	memcpy( m_sc_Password,		 st_SettingInfo.m_s_ServerInfo.m_sc_Password,	 sizeof(m_sc_Password)		);										// バックアップ設定／WebDAV設定／パスワード.
	memcpy( m_sc_EncPassword,	 st_SettingInfo.m_sc_Password,					 sizeof(m_sc_EncPassword)	);										// バックアップ設定／暗号化パスワード.
	// 取得したバックアップ設定をリストア設定保持用メンバに設定.
	m_bl_ExtRestoreSettingProxy = st_SettingInfo.m_s_ServerInfo.m_b_ProxyEnable;																	// リストア設定／WebDAV設定／プロキシ設定.
	memcpy( m_sc_ExtRestoreSettingURL,			st_SettingInfo.m_s_ServerInfo.m_sc_URL,			sizeof( m_sc_ExtRestoreSettingURL )			);		// リストア設定／WebDAV設定／URL.
	memcpy( m_sc_ExtRestoreSettingUserName,		st_SettingInfo.m_s_ServerInfo.m_sc_UserID,		sizeof( m_sc_ExtRestoreSettingUserName )	);		// リストア設定／WebDAV設定／ユーザー名.
	memcpy( m_sc_ExtRestoreSettingPassword,		st_SettingInfo.m_s_ServerInfo.m_sc_Password,	sizeof( m_sc_ExtRestoreSettingPassword )	);		// リストア設定／WebDAV設定／パスワード.
	memcpy( m_sc_ExtRestoreSettingEncPassword,	st_SettingInfo.m_sc_Password,					sizeof( m_sc_ExtRestoreSettingEncPassword )	);		// リストア設定／暗号化パスワード.
}

