Bool PServiceExtServerBackupSettingInfo::commitServiceExtServerBackupSetting()
{
	TYPS_BackupRestoreExt_BackupSettingInfo st_SettingInfo;
	APIC_BackupRestoreSettingExt *pc_BackupRestoreSettingExt = APIC_BackupRestoreSettingExt::newInstance();
	Bool bl_ret = False;
	if( NULL == pc_BackupRestoreSettingExt ) {
// comment 2017/1/6 [IT5-4.0] WP-903 RQ-505_新詳細コード対応 日立 村上幸.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
// 		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
// 		if ( NULL != pc_BFW_System ) {
// 			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19007001014E0301 );
// 		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return bl_ret;
	}
	if( True == checkSettingsBackupSetting() ) {						// ﾊﾞｯｸｱｯﾌﾟ設定の全設定が範囲内の時.
		pc_BackupRestoreSettingExt->getServerBackupSettingInfo(&st_SettingInfo);													// CommonAPIからデータ取得.
		// ﾊﾞｯｸｱｯﾌﾟ設定の設定値のみを更新.
		st_SettingInfo.m_b_Enable		 				 = m_bl_ExtServerSettingEnable;												// 拡張サーバー設定_使用する／使用しない.
		st_SettingInfo.m_b_BoxDocEnable	 				 = m_bl_BoxFormatEnable;													// ﾎﾞｯｸｽ文書設定_対象／非対象.
		st_SettingInfo.m_s_ServerInfo.m_b_ProxyEnable	 = m_bl_ProxyEnable;														// ﾌﾟﾛｷｼ.
		st_SettingInfo.m_us_HoldPeriod					 = m_us_HoldPeriod;															// データ保持時間(最小値で初期化).
		memcpy( st_SettingInfo.m_s_ServerInfo.m_sc_URL,	 m_sc_URL, sizeof(st_SettingInfo.m_s_ServerInfo.m_sc_URL));					// URL.
		memcpy( st_SettingInfo.m_s_ServerInfo.m_sc_UserID,	 m_sc_UserName, sizeof(st_SettingInfo.m_s_ServerInfo.m_sc_UserID));		// ﾕｰｻﾞｰ名.
		memcpy( st_SettingInfo.m_s_ServerInfo.m_sc_Password, m_sc_Password, sizeof(st_SettingInfo.m_s_ServerInfo.m_sc_Password));	// ﾊﾟｽﾜｰﾄﾞ.
		memcpy( st_SettingInfo.m_sc_Password,				 m_sc_EncPassword, sizeof(m_sc_EncPassword));							// 暗号化ﾊﾟｽﾜｰﾄﾞ.
		// LocalUI内で設定した値をCommonAPIへ保存.
		pc_BackupRestoreSettingExt->setServerBackupSettingInfo(&st_SettingInfo);													// CommonAPIへデータ設定.
		bl_ret = True;
	}
	return bl_ret;
}

