//================================================================================================.
// 概要    :共通_拡張サーバーへバックアップ／バックアップ設定データクラス : 時間設定(YYYY/MM/DD hh:mm)の共通設定制御.
// 引数     : c_Date		(input)		時刻.
//			　sc_DateTime	(output)	取得した時間を文字列化(仕向け毎に変更).
// 備考     : なし.
//================================================================================================.
void PServiceExtServerBackupSettingInfo::getDayTimeDisplay( const TYPC_Time& c_Date, char* sc_DateTime )
{
	if( NULL == sc_DateTime ) {
// comment 2017/1/6 [IT5-4.0] WP-903 RQ-505_新詳細コード対応 日立 村上幸.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
// 		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
// 		if ( NULL != pc_BFW_System ) {
// 			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19007001014E0601 );
// 		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}

	TYPE_SystemType e_SystemType = PnlComGetMachineSetting()->getSystemType();		//現在の仕向け設定.
	if( ( 0 != c_Date.ss_Year ) && ( 0 != c_Date.sc_Month ) && ( 0 != c_Date.sc_Day ) ) {
		//仕向けにより表示文字列を変更する.
		switch( e_SystemType ) {
			case TYPE_SystemType_US: 	// ＭＣ仕向け.
// comment 2016/11/7 [IT5_4.0][AR1007016]日立 森本 コーディング規約違反修正対応.
//				sprintf( sc_DateTime, "%02d/%02d/%04d %02d:%02d", c_Date.sc_Month, c_Date.sc_Day, c_Date.ss_Year, c_Date.sc_Hour, c_Date.sc_Minute );
				snprintf( sc_DateTime, PNLD_ServiceExtSrvBackupReserve_MaxDayTime, "%02d/%02d/%04d %02d:%02d", c_Date.sc_Month, c_Date.sc_Day, c_Date.ss_Year, c_Date.sc_Hour, c_Date.sc_Minute );
				break;
			case TYPE_SystemType_JP: 	// 日本仕向け.
// comment 2016/11/7 [IT5_4.0][AR1007016]日立 森本 コーディング規約違反修正対応.
//				sprintf(sc_DateTime, "%04d/%02d/%02d %02d:%02d", c_Date.ss_Year, c_Date.sc_Month, c_Date.sc_Day, c_Date.sc_Hour, c_Date.sc_Minute );
				snprintf(sc_DateTime, PNLD_ServiceExtSrvBackupReserve_MaxDayTime, "%04d/%02d/%02d %02d:%02d", c_Date.ss_Year, c_Date.sc_Month, c_Date.sc_Day, c_Date.sc_Hour, c_Date.sc_Minute );
				break;
			case TYPE_SystemType_EU:    // ＥＵ仕向け.
			// EU仕向時はdefaultと同一とする.
			default: 
// comment 2016/11/7 [IT5_4.0][AR1007016]日立 森本 コーディング規約違反修正対応.
//				sprintf(sc_DateTime, "%02d/%02d/%04d %02d:%02d", c_Date.sc_Day, c_Date.sc_Month, c_Date.ss_Year, c_Date.sc_Hour, c_Date.sc_Minute );
				snprintf(sc_DateTime, PNLD_ServiceExtSrvBackupReserve_MaxDayTime, "%02d/%02d/%04d %02d:%02d", c_Date.sc_Day, c_Date.sc_Month, c_Date.ss_Year, c_Date.sc_Hour, c_Date.sc_Minute );
				 break;
		}
	}
	else {
		switch( e_SystemType ) {
			case TYPE_SystemType_US:	// ＭＣ仕向け.
// comment 2016/11/7 [IT5_4.0][AR1007016]日立 森本 コーディング規約違反修正対応.
//				sprintf(sc_DateTime, "%s", "--/--/---- --:--");
				snprintf(sc_DateTime, PNLD_ServiceExtSrvBackupReserve_MaxDayTime, "%s", "--/--/---- --:--");
				break;
			case TYPE_SystemType_JP:	// 日本仕向け.
// comment 2016/11/7 [IT5_4.0][AR1007016]日立 森本 コーディング規約違反修正対応.
//				sprintf(sc_DateTime, "%s", "----/--/-- --:--");
				snprintf(sc_DateTime, PNLD_ServiceExtSrvBackupReserve_MaxDayTime, "%s", "----/--/-- --:--");
				break;
			case TYPE_SystemType_EU:	// ＥＵ仕向け.
			// EU仕向時はdefaultと同一とする.
			default:
// comment 2016/11/7 [IT5_4.0][AR1007016]日立 森本 コーディング規約違反修正対応.
//				sprintf(sc_DateTime, "%s", "--/--/---- --:--");
				snprintf(sc_DateTime, PNLD_ServiceExtSrvBackupReserve_MaxDayTime, "%s", "--/--/---- --:--");
				break;
		}
	}
}

