// 概要    :共通_拡張サーバーへバックアップ／バックアップ設定共通 : 表示部品のセットアップ.
//================================================================================================.
void PServiceExtServerBackupSettingCom::setupGamen( short ss_option )
{
	// 親クラスをコール.
	PServiceNoFunctionCodeCom::setupGamen(ss_option);
	switch( m_e_ExtServerBackupSettingShow ){
		case PNLE_ServiceExtServerBackup_Enable:						// 機能設定.
			Rbt_ServiceExtSrvBackupSettingMenu.select( 0 );
			break;
		case PNLE_ServiceExtServerBackup_WebDAV_URL:					// WebDAV設定_URL.
			Rbt_ServiceExtSrvBackupSettingMenu.select( 1 );
			Rbt_ServiceExtSrvBackup_WebDavSettingMenu.select( 0 );
			break;
		case PNLE_ServiceExtServerBackup_WebDAV_UserName:				// WebDAV設定_ﾕｰｻﾞｰ名.
			Rbt_ServiceExtSrvBackupSettingMenu.select( 1 );
			Rbt_ServiceExtSrvBackup_WebDavSettingMenu.select( 1 );
			break;
		case PNLE_ServiceExtServerBackup_WebDAV_Password:				// WebDAV設定_ﾊﾟｽﾜｰﾄﾞ.
			Rbt_ServiceExtSrvBackupSettingMenu.select( 1 );
			Rbt_ServiceExtSrvBackup_WebDavSettingMenu.select( 2 );
			break;
		case PNLE_ServiceExtServerBackup_WebDAV_Proxy:					// WebDAV設定_ﾌﾟﾛｷｼ.
			Rbt_ServiceExtSrvBackupSettingMenu.select( 1 );
			Rbt_ServiceExtSrvBackup_WebDavSettingMenu.select( 3 );
			break;
		case PNLE_ServiceExtServerBackup_EncryptionPassword:			// 暗号化ﾊﾟｽﾜｰﾄﾞ.
			Rbt_ServiceExtSrvBackupSettingMenu.select( 2 );
			break;
		case PNLE_ServiceExtServerBackup_DataHoldPeriod:				// データ保持時間.
			Rbt_ServiceExtSrvBackupSettingMenu.select( 3 );
			break;
		default: break;
	}

}
