//================================================================================================.
// 概要    :M0B0010000_拡張サーバーへバックアップ／バックアップ設定／機能設定 : 表示部品のセットアップ.
//================================================================================================.
void PServiceExtServerBackupSettingEnableSetting::setupGamen( short ss_option )
{
	PServiceExtServerBackupSettingInfo* pc_ExtBackupSettingInfo = PServiceExtServerBackupSettingInfo::newInstance();
	if( NULL == pc_ExtBackupSettingInfo ) {
// comment 2017/1/6 [IT5-4.0] WP-903 RQ-505_新詳細コード対応 日立 村上幸.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
// 		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
// 		if ( NULL != pc_BFW_System ) {
// 			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19006601014E0901 );
// 		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}
	// 親クラスを呼ぶ.
	PServiceExtServerBackupSettingCom::setupGamen( ss_option );

	if( True == PnlComGetSystemSetting()->getSecurityLevelUpOn() ) {
		// セキュリティ強化モードONの場合は、使用するキー非表示.
		Key_ServiceExtSrvBackup_EnableSelectOn.showEnable( False );
	} else {
		// セキュリティ強化モードOFFの場合は、使用するキー表示.
		Key_ServiceExtSrvBackup_EnableSelectOn.showEnable( True );
	}
	// 使用する／使用しないを選択状態に変更(True：使用するを選択(0)、False：使用しないを選択(1)).
	Rbt_ServiceExtSrvBackup_EnableSelect.select( (True == pc_ExtBackupSettingInfo->getExtBackupSettingEnable()) ? 0 : 1 );
	Rbt_ServiceExtSrvBackup_BoxDocument.select( (True == pc_ExtBackupSettingInfo->getExtBackupSettingDocEnable()) ? 0 : 1 );
	
	// 機能設定の使用する/使用しないを取得し、表示/非表示を実施.
	Key_ServiceExtSrvBackupSetting_WebDavSetting.showEnable( pc_ExtBackupSettingInfo->getExtBackupSettingEnable() );				// HTTP設定キーの表示/非表示.
	Key_ServiceExtSrvBackupSetting_EncryptPassword.showEnable( pc_ExtBackupSettingInfo->getExtBackupSettingEnable() );				// 暗号化ﾊﾟｽﾜｰﾄﾞキーの表示/非表示.
	Key_ServiceExtSrvBackupSetting_DataHoldPeriod.showEnable( pc_ExtBackupSettingInfo->getExtBackupSettingEnable() );				// データ保持期間キーの表示/非表示.
	Bool	bl_BoxDocumentEnable = True;
//2018/09/04 HCLT-Sarada [Sparrow][AR1056795 ] Removed HDD condition for user Box Document key for Sparrow AIO model.
//comment 2018/05/20 HCLT-Taqiuddin [Sparrow][機器構成変更_No.206] Hiding UserBox document for Sparrow AIO&SFP.
#ifdef DEF_SparrowAIOSFPCus
//comment 2018/07/17 HCLT-Basker [Sparrow][制御構成変更_No.206 ] Remove the unneccessary functions from SparrowSFP models.
	if ( IsSFP() ) {
		bl_BoxDocumentEnable = False;
	} else {
		//AIO.
		if( ( False == pc_ExtBackupSettingInfo->getExtBackupSettingEnable() ) ) {
			bl_BoxDocumentEnable = False;
		}
	}
#else
	if( ( False == pc_ExtBackupSettingInfo->getExtBackupSettingEnable() ) ||
    	( False == PnlComGetHddInfo()->getHddExist() ) ) {
		//機能設定：使用しない設定時、またはHDD非装着時はボックス文書をタイトル毎非表示にする.
		bl_BoxDocumentEnable = False;
	}
#endif	//#ifdef DEF_SparrowAIOSFPCus.
	Txt_ServiceExtSrvBackup_BoxDocument.showEnable( bl_BoxDocumentEnable );															// ﾎﾞｯｸｽ文書タイトルの表示/非表示.
	Rbt_ServiceExtSrvBackup_BoxDocument.showEnable( bl_BoxDocumentEnable );															// ローテーションボタンの表示/非表示.
}
