// 概要    :M0B0010000_拡張サーバーへバックアップ／バックアップ設定／機能設定 : キー押下処理.
//================================================================================================.
void PServiceExtServerBackupSettingEnableSetting::procButtonOn( uchar uc_option )
{
	PServiceExtServerBackupSettingInfo* pc_ExtBackupSettingInfo = PServiceExtServerBackupSettingInfo::newInstance();
	if( NULL == pc_ExtBackupSettingInfo ) {
// comment 2017/1/6 [IT5-4.0] WP-903 RQ-505_新詳細コード対応 日立 村上幸.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
// 		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
// 		if ( NULL != pc_BFW_System ) {
// 			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19000A01014E0A01 );
// 		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}
	// 親クラスを呼ぶ.
	PServiceExtServerBackupSettingCom::procButtonOn( uc_option );
	
	switch( uc_option ) {
		case BTNID_KEY_ServiceExtSrvBackup_EnableSelectOn:
			// ﾊﾞｯｸｱｯﾌﾟ設定を使用するに設定.
			pc_ExtBackupSettingInfo->setExtBackupSettingEnable( True );
			break;
		case BTNID_KEY_ServiceExtSrvBackup_EnableSelectOff:
			// ﾊﾞｯｸｱｯﾌﾟ設定を使用しないに設定.
			pc_ExtBackupSettingInfo->setExtBackupSettingEnable( False );
			break;
		case BTNID_KEY_ServiceExtSrvBackup_BoxDocTarget:
			// ﾎﾞｯｸｽ文書を対象に設定.
			pc_ExtBackupSettingInfo->setExtBackupSettingDocEnable( True );
			break;
		case BTNID_KEY_ServiceExtSrvBackup_BoxDocNotTarget:
			// ﾎﾞｯｸｽ文書を非対象に設定.
			pc_ExtBackupSettingInfo->setExtBackupSettingDocEnable( False );
			break;
		default:	break;
	}
	setupGamen(uc_option);
}

