//================================================================================================.
// 概要    :M0B0010110_拡張サーバーへバックアップ／バックアップ設定／WebDAV設定／URL入力 : 画面開始処理.
//================================================================================================.
void PServiceExtServerBackupSettingWebDavURLInput::startGamen()
{
	PServiceExtServerBackupSettingInfo* pc_ExtBackupSettingInfo = PServiceExtServerBackupSettingInfo::newInstance();
	if( NULL == pc_ExtBackupSettingInfo ) {
// comment 2017/1/6 [IT5-4.0] WP-903 RQ-505_新詳細コード対応 日立 村上幸.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
// 		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
// 		if ( NULL != pc_BFW_System ) {
// 			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19006501014E0C01 );
// 		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}
	// データクラスからURLを取得し、キーボード共通クラスのクラス変数に保存.
// Comment 2020/01/22 [HCL-Shalini] [EagleZ+] [OP_BTS-19428] strnlen is used instead sizeof().
//// Comment 2019/12/02 [HCL-Taqiuddin] [KLOC ID:106297] [KLOC TYPE:ABV.GENERAL].
//	if ( sizeof( pc_ExtBackupSettingInfo->getExtBackupSettingWebDAVURL()) < sizeof (m_sc_StrKeyboard) ) {
//		memcpy( m_sc_StrKeyboard, pc_ExtBackupSettingInfo->getExtBackupSettingWebDAVURL(), sizeof( pc_ExtBackupSettingInfo->getExtBackupSettingWebDAVURL() ) - 1);
	if ( strnlen( pc_ExtBackupSettingInfo->getExtBackupSettingWebDAVURL(),TYPD_BackupRestoreSettingExt_ServerInfo_URLMaxLen) < sizeof (m_sc_StrKeyboard) ) {
		memset( m_sc_StrKeyboard, 0, sizeof( m_sc_StrKeyboard ) );
		memcpy( m_sc_StrKeyboard, pc_ExtBackupSettingInfo->getExtBackupSettingWebDAVURL(), strnlen( pc_ExtBackupSettingInfo->getExtBackupSettingWebDAVURL(),TYPD_BackupRestoreSettingExt_ServerInfo_URLMaxLen ) );
	} else {
		memcpy( m_sc_StrKeyboard, pc_ExtBackupSettingInfo->getExtBackupSettingWebDAVURL(), sizeof( m_sc_StrKeyboard ) - 1 );
	}
	// 表示領域に文字列をセット.
	setKeyboardData( m_sc_StrKeyboard, PNLD_MAX_ServiceDataBackupServerBackupHTTPURLChar , PNLD_ServiceDataBackupServerBackupInputWidth );
	m_bl_Password = False;
	m_bl_ShowPass = False;

	// 親クラスを呼ぶ.
	PServiceDataBackupKeyboardCom::startGamen();
}
