//================================================================================================.
// 概要    :M0B0010510_拡張サーバーへバックアップ／バックアップ設定／暗号化パスワード新入力 : 表示部品のセットアップ.
//================================================================================================.
void PServiceExtServerBackupSettingEncryptionPasswordInput::setupGamen( short ss_option )
{
	// 親クラスを呼ぶ.
	PServiceDataBackupKeyboardCom::setupGamen( ss_option );
	
	// 表示メッセージの変更.
	switch( m_uc_nowMessage ) {
		case PNLD_ServiceServerBackupFirstInput:	Txt_ServiceExtSrvBackupSettingPassword.changeText( s_ITMServiceNewPassword ); break;		// 新しいパスワード入力.
		case PNLD_ServiceServerBackupSecondInput:	Txt_ServiceExtSrvBackupSettingPassword.changeText( s_ITMServiceReinputPassword ); break;	// 再入力パスワード.
		default: break;
	}
	Txt_ServiceRelayServerHTTPAuthPasswordErrMessage.changeText( m_us_dispErrMessage );		// エラーメッセージ.

	// 入力禁止文字の非表示.
	Kbd_ServiceInputKeybord.setDisableKeyCharCode( KC_DisableKeyPattern15 );	// パターン15("ユーロ記号).
}
//================================================================================================.
// 概要    :M0B0010510_拡張サーバーへバックアップ／バックアップ設定／暗号化パスワード新入力 : OKキー押下処理.
//================================================================================================.
void PServiceExtServerBackupSettingEncryptionPasswordInput::procOk( uchar uc_option )
{
	PServiceExtServerBackupSettingInfo* pc_ExtBackupSettingInfo = PServiceExtServerBackupSettingInfo::newInstance();
	if( NULL == pc_ExtBackupSettingInfo ) {
// comment 2017/1/6 [IT5-4.0] WP-903 RQ-505_新詳細コード対応 日立 村上幸.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
// 		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
// 		if ( NULL != pc_BFW_System ) {
// 			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19000301014E1701 );
// 		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}
	
	switch( m_uc_nowMessage ) {
		case PNLD_ServiceServerBackupFirstInput: // 新しいパスワード入力.
			// 入力されたパスワードをチェックして、以下の条件に当てはまれば使用不可パスワード.
			if( 0 != strlen( m_sc_StrKeyboard ) ) {			// パスワード文字列が0で無ければ OK.
				m_uc_nowMessage = PNLD_ServiceServerBackupSecondInput;								// 再入力状態に変更.
				memset( m_sc_newPassword, '\0', sizeof( m_sc_newPassword ) );
				memcpy( m_sc_newPassword, m_sc_StrKeyboard, sizeof( m_sc_newPassword ) ); 			// 新パスワードを一時保存.
				m_us_dispErrMessage = s_Space1;														//エラーメッセージをクリア.
			} else {
				setBuzzerType( PCGE_BuzzerType_InputNg );
				m_us_dispErrMessage = s_SSNewPassWordMissteke;										//「入力したﾊﾟｽﾜｰﾄﾞは使用できません」.
			}
			memset( m_sc_StrKeyboard, '\0', sizeof( m_sc_StrKeyboard ) ); 							// パスワード入力用文字列をクリア.
			// スライド文字列管理クラスの初期化.
			m_c_SlideTextMgr.init_CLCD( m_sc_StrKeyboard, m_sc_KeyboardWidth, m_ss_MaxInputNum, m_pc_DispField, getCharSetForPanel() );
			break;
		case PNLD_ServiceServerBackupSecondInput: // 再入力パスワード.
// comment 2016/11/7 [IT5_4.0][AR1007016]日立 森本 コーディング規約違反修正対応.
//			if( 0 == strcmp( m_sc_newPassword, m_sc_StrKeyboard ) ) {								// 1回目の入力とのチェック.
			if( 0 == strncmp( m_sc_newPassword, m_sc_StrKeyboard, sizeof( m_sc_newPassword ) ) ) {	// 1回目の入力とのチェック.
				pc_ExtBackupSettingInfo->setExtBackupSettingEncryptionPassword( m_sc_newPassword );	// 暗号化パスワードを保存.
				nextGamen = &gp_ServiceExtServerBackupSettingEncryptionPassword;					// M0B0010500_拡張サーバーへバックアップ／バックアップ設定／暗号化パスワード..
			} else {
				setBuzzerType( PCGE_BuzzerType_InputNg );
				m_uc_nowMessage = PNLD_ServiceServerBackupFirstInput;								// 新ﾊﾟｽﾜｰﾄﾞ入力状態に設定.
				// 入力文字列に新しいパスワードを設定し、新しいパスワード入力に戻る.
				// Comment 2017/02/20 HCL_Sasaki IT5_4.0 Klockwork Changes ID:75369.
//				memcpy( m_sc_StrKeyboard, m_sc_newPassword, sizeof( m_sc_StrKeyboard ) );
				memset( m_sc_StrKeyboard, '\0', sizeof(m_sc_StrKeyboard) );
				memcpy( m_sc_StrKeyboard, m_sc_newPassword, sizeof( m_sc_newPassword ) );
				// スライド文字列管理クラスの初期化.
				m_c_SlideTextMgr.init_CLCD( m_sc_StrKeyboard, m_sc_KeyboardWidth, m_ss_MaxInputNum, m_pc_DispField, getCharSetForPanel() );
			}
			break;
		default: break;
	}
	setupGamen(uc_option);
}
