// 概要    :M0B0010700_拡張サーバーへバックアップ／バックアップ設定／データ保持期間 : テンキー押下処理.
//================================================================================================.
void PServiceExtServerBackupSettingDataHoldPeriod::proc10Key( uchar uc_option )
{
	Bool	bl_isError = False;
	ushort	us_DataHoldPeriodSetting = 0;
	
	PServiceExtServerBackupSettingInfo* pc_ExtBackupSettingInfo = PServiceExtServerBackupSettingInfo::newInstance();
	if( NULL == pc_ExtBackupSettingInfo ) {
// comment 2017/1/6 [IT5-4.0] WP-903 RQ-505_新詳細コード対応 日立 村上幸.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
// 		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
// 		if ( NULL != pc_BFW_System ) {
// 			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19002A01014E1B01 );
// 		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}
	
	us_DataHoldPeriodSetting = pc_ExtBackupSettingInfo->getExtBackupSettingHoldPeriod();
	
	// ﾃﾞｰﾀ保持期間を更新する.
	us_DataHoldPeriodSetting = ( ushort )proc10KeyInput( us_DataHoldPeriodSetting, TYPD_BackupRestoreSettingExt_BackupDataHoldPeriodMax, uc_option, m_bl_Direct, EP_InputMaxLimitPattern_Refuse, &bl_isError );
	pc_ExtBackupSettingInfo->setExtBackupSettingHoldPeriod( us_DataHoldPeriodSetting );
	
	if( True == bl_isError ) {
		setBuzzerType( PCGE_BuzzerType_InputNg );					// ブザー音セット.
	}
	else {
		if( True == m_bl_Direct && 1 > uc_option ) {
			setBuzzerType( PCGE_BuzzerType_InputNg );				// ブザー音セット.
		}
		else {
			m_bl_Direct = False;
		}
	}
	setupGamen( uc_option );										// 画面更新を行う.
}
