// 概要    :共通_拡張サーバーへバックアップ／自動バックアップ設定共通 : 表示部品のセットアップ.
//================================================================================================.
void PServiceExtServerAutoBackupSettingCom::setupGamen( short ss_option )
{
	// 親クラスをコール.
	PServiceNoFunctionCodeCom::setupGamen(ss_option);
	PServiceExtServerBackupSettingInfo* pc_ExtBackupSettingInfo = PServiceExtServerBackupSettingInfo::newInstance();
	if( NULL == pc_ExtBackupSettingInfo ) {
// comment 2017/1/6 [IT5-4.0] WP-903 RQ-505_新詳細コード対応 日立 村上幸.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
// 		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if ( NULL != pc_BFW_System ) {
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19006601014E1F01 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}
	switch( m_e_ExtServerAutoBackupShow ){
		case PNLE_ServiceExtServerAutoBkup_EnableSetting:						// 機能設定.
			Rbt_ServiceExtSrvAutoBkup_Setting.select( 0 );
			break;
		case PNLE_ServiceExtServerAutoBkup_FullBackup:							// ﾌﾙﾊﾞｯｸｱｯﾌﾟ.
			Rbt_ServiceExtSrvAutoBkup_Setting.select( 1 );
			break;
		case PNLE_ServiceExtServerAutoBkup_DiffBackup:							// 差分ﾊﾞｯｸｱｯﾌﾟ.
			Rbt_ServiceExtSrvAutoBkup_Setting.select( 2 );
			break;
		default:
			break;
	}

	// 自動バックアップ「使用しない」選択時、ﾌﾙﾊﾞｯｸｱｯﾌﾟ／差分ﾊﾞｯｸｱｯﾌﾟ インデックスキーを非表示.
	if( True == pc_ExtBackupSettingInfo->getExtBackupSettingAutoBackupFullBackupEnable() ) {									// 自動バックアップが使用するの場合.
		Key_ServiceExtSrvAutoBkup_FullBackup.showEnable( True );																// ﾌﾙﾊﾞｯｸｱｯﾌﾟキーを表示.
// comment 2017/01/18 【MAv5】RQ-668-01-01_KMフォーマット選択時の差分バックアップキー表示非表示条件の変更 日立村上幸.
//		// KMﾌｫｰﾏｯﾄ選択時は差分ﾊﾞｯｸｱｯﾌﾟキーを非表示.
//		if( TYPE_BackupRestoreSettingExt_BoxDocFormat_KM == m_e_BoxFormat ) {												// ﾎﾞｯｸｽ文書使用する且つKMﾌｫｰﾏｯﾄ選択時.
//			Key_ServiceExtSrvAutoBkup_DiffBackup.showEnable( False );															// 差分ﾊﾞｯｸｱｯﾌﾟキーを非表示.
//		} else {																												// それ以外.
//			Key_ServiceExtSrvAutoBkup_DiffBackup.showEnable( True );															// 差分ﾊﾞｯｸｱｯﾌﾟキーを表示.
//		}
		Key_ServiceExtSrvAutoBkup_DiffBackup.showEnable( True );																// 差分ﾊﾞｯｸｱｯﾌﾟキーを表示.
	} else {																													// その他(自動ﾊﾞｯｸｱｯﾌﾟが使用しない).
		Key_ServiceExtSrvAutoBkup_DiffBackup.showEnable( False );																// 差分ﾊﾞｯｸｱｯﾌﾟキーを非表示.
		Key_ServiceExtSrvAutoBkup_FullBackup.showEnable( False );																// ﾌﾙﾊﾞｯｸｱｯﾌﾟキーを非表示.
	}
}

