//================================================================================================.
// 概要    :共通_拡張サーバーへバックアップ／自動バックアップ設定共通 : 自動ﾊﾞｯｸｱｯﾌﾟの共通10キー入力制御.
//================================================================================================.
int32_t PServiceExtServerAutoBackupSettingCom::proc10KeyAutoBackupInput( int32_t sl_NowValue,			// 現在値.
																	   int32_t sl_MinValue,			// 最小値.
																	   int32_t sl_MaxValue,			// 最大値.
																	   short ss_option,				// 入力値.
																	   uchar* sc_digit,				// 現在の入力桁数.
																	   Bool* pbl_isError)			// 範囲外のデータかの結果を格納 True;範囲外のデータ.
{
	int32_t i32_returnValue = sl_NowValue;									// 戻り値の初期値は現在値とする.
	int32_t i32_Valuecheck = 0;												// チェック用の変数.
	if( NULL == pbl_isError ) {											// Nullが入っている場合は、何もせず返す.
// comment 2017/1/6 [IT5-4.0] WP-903 RQ-505_新詳細コード対応 日立 村上幸.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
// 		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if ( NULL != pc_BFW_System ) {
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19002A01014E2101 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return 0;
	}

	switch( *sc_digit ) {
		case PNLD_ServiceExtBackupAutoBackup_0_DIGIT:	// 未入力(初期入力)の場合.
			if( sl_MinValue <= ss_option ) {									// 最小値以上の場合.
				if( sl_MaxValue / 10 >= ss_option ) {							// 上位桁以下の場合.
					i32_returnValue = ss_option;									// 入力値を戻り値に設定.
					*sc_digit = PNLD_ServiceExtBackupAutoBackup_1_DIGIT;		// 入力状態を更新(上位桁入力済み).
				} else {														// 上位桁を超えた場合.
					i32_returnValue = ss_option;									// 入力値を戻り値に設定.
					*sc_digit = PNLD_ServiceExtBackupAutoBackup_2_DIGIT;		// 入力状態を更新(入力済み).
				}
			} else {
				*pbl_isError = True;											// エラーを設定.
			}
			break;
		case PNLD_ServiceExtBackupAutoBackup_1_DIGIT:	// 1桁目入力の場合.
			i32_Valuecheck = sl_NowValue * 10 + ss_option;						// 現在の値と入力した値で計算.
			if( ( sl_MaxValue < i32_Valuecheck )									// 最大値を超えた場合.
			 || ( sl_MinValue > i32_Valuecheck )									// 又は最小値より小さい場合.
			) {
				*pbl_isError = True;											// エラーを設定.
				i32_returnValue = sl_NowValue;									// 現在の値を戻り値に設定.
			} else {
				*sc_digit = PNLD_ServiceExtBackupAutoBackup_2_DIGIT;			// 入力状態を更新(上位桁入力済み).
				i32_returnValue = i32_Valuecheck;									// 計算した値を戻り値にを設定.
			}
			break;
		case PNLD_ServiceExtBackupAutoBackup_2_DIGIT:	// 入力済みの場合.
		// 入力済みはエラーを返すため、defaultと同一とする.
		default:
			*pbl_isError = True;												// エラーを設定.
			i32_returnValue = sl_NowValue;										// 現在の値を戻り値に設定.
			break;
	}

	return i32_returnValue;
}
