//================================================================================================.
// 概要    :M0B0011100_拡張サーバーへバックアップ／自動バックアップ／フルバックアップ周期 : 表示部品のセットアップ.
//================================================================================================.
void PServiceExtServerAutoBackupSettingFullBackupSetting::setupGamen( short ss_option )
{
	// 親クラスを呼ぶ.
	PServiceExtServerAutoBackupSettingCom::setupGamen( ss_option );

	PServiceExtServerBackupSettingInfo* pc_ExtBackupSettingInfo = PServiceExtServerBackupSettingInfo::newInstance();
	if( NULL == pc_ExtBackupSettingInfo ) {
// comment 2017/1/6 [IT5-4.0] WP-903 RQ-505_新詳細コード対応 日立 村上幸.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
// 		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if ( NULL != pc_BFW_System ) {
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19006601014E2401 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}
	switch( pc_ExtBackupSettingInfo->getExtBackupSettingAutoBackupFullBackupCycle() ) {
		case TYPE_BackupRestoreSettingExt_FullBackupCycle_Day:				// 日周期.
			Grp_ServiceExtSrvAutoBkupFull_WeekdayParts.showEnable( False );				// 週周期のグループパーツを非表示.
			Grp_ServiceExtSrvAutoBkupFull_CycleParts.showEnable( True );				// 日周期のグループパーツを表示.
			Rbt_ServiceExtSrvAutoBkupFull_PeriodSelect.select( 0 );						// 日周期/週周期キーの日周期を選択.
			// 日周期の設定(未入力(m_bl_DirectDayがTrue)の場合は「__」を表示).
			Btx_ServiceExtSrvAutoBkupFull_Cycle.set( ( float )pc_ExtBackupSettingInfo->getExtBackupSettingAutoBackupFullBackupCycleDay(),( m_bl_DirectDay == True ) ? False : True );
			break;
		case TYPE_BackupRestoreSettingExt_FullBackupCycle_Weekday:			// 週周期.
			Grp_ServiceExtSrvAutoBkupFull_CycleParts.showEnable( False );				// 日周期のグループパーツを非表示.
			Grp_ServiceExtSrvAutoBkupFull_WeekdayParts.showEnable( True );				// 週周期のグループパーツを表示.
			Rbt_ServiceExtSrvAutoBkupFull_PeriodSelect.select( 1 );						// 日周期/週周期キーの週周期を選択.
			// 週周期の「選択した曜日」を選択状態に設定.
			switch(pc_ExtBackupSettingInfo->getExtBackupSettingAutoBackupFullBackupWeekDay()) {
				case TYPE_BackupRestoreSettingExt_Weekday_Sun:	Rbt_ServiceExtSrvAutoBkupFull_Weekday.select( 0 );	break;	// 日.
				case TYPE_BackupRestoreSettingExt_Weekday_Mon:	Rbt_ServiceExtSrvAutoBkupFull_Weekday.select( 1 );	break;	// 月.
				case TYPE_BackupRestoreSettingExt_Weekday_Tue:	Rbt_ServiceExtSrvAutoBkupFull_Weekday.select( 2 );	break;	// 火.
				case TYPE_BackupRestoreSettingExt_Weekday_Wed:	Rbt_ServiceExtSrvAutoBkupFull_Weekday.select( 3 );	break;	// 水.
				case TYPE_BackupRestoreSettingExt_Weekday_Thu:	Rbt_ServiceExtSrvAutoBkupFull_Weekday.select( 4 );	break;	// 木.
				case TYPE_BackupRestoreSettingExt_Weekday_Fri:	Rbt_ServiceExtSrvAutoBkupFull_Weekday.select( 5 );	break;	// 金.
				case TYPE_BackupRestoreSettingExt_Weekday_Sat:	Rbt_ServiceExtSrvAutoBkupFull_Weekday.select( 6 );	break;	// 土.
				default:	break;
			}
			break;
		default:
			break;
	}
	// 共通部の表示非表示処理.
	// ﾊﾞｯｸｱｯﾌﾟ時刻の設定.
	Btx_ServiceExtSrvAutoBkupFull_TimeHour.leftSet( ( float )pc_ExtBackupSettingInfo->getExtBackupSettingAutoBackupFullBackupHour(), m_uc_HourInputDigit );
	Btx_ServiceExtSrvAutoBkupFull_TimeMinute.leftSet( ( float )pc_ExtBackupSettingInfo->getExtBackupSettingAutoBackupFullBackupMinute(), m_uc_MinuteInputDigit );
	// 日周期/ ﾊﾞｯｸｱｯﾌﾟ時刻キー選択する.
	Rbt_ServiceExtSrvAutoBkupFull_CycleAndTimeSelect.select( m_sc_Inputselect );
}
//================================================================================================.
// 概要    :M0B0011100_拡張サーバーへバックアップ／自動バックアップ／フルバックアップ周期 : キー押下処理.
//================================================================================================.
void PServiceExtServerAutoBackupSettingFullBackupSetting::procButtonOn( uchar uc_option )
{
	// 親クラスを呼ぶ.
	PServiceExtServerAutoBackupSettingCom::procButtonOn( uc_option );

	PServiceExtServerBackupSettingInfo* pc_ExtBackupSettingInfo = PServiceExtServerBackupSettingInfo::newInstance();
	if( NULL == pc_ExtBackupSettingInfo ) {
// comment 2017/1/6 [IT5-4.0] WP-903 RQ-505_新詳細コード対応 日立 村上幸.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
// 		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if ( NULL != pc_BFW_System ) {
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19000A01014E2501 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}

	switch( uc_option ) {
		case BTNID_KEY_ServiceExtSrvAutoBkupFull_Cycle:						// 日周期.
			pc_ExtBackupSettingInfo->setExtBackupSettingAutoBackupFullBackupCycle( TYPE_BackupRestoreSettingExt_FullBackupCycle_Day );
			break;
		case BTNID_KEY_ServiceExtSrvAutoBkupFull_Weekday:					// 週周期.
			if( True == m_bl_DirectDay ) { 									// 日キーが入力途中の場合.
			 	// 拒否音を鳴動.
				setBuzzerType( PCGE_BuzzerType_InputNg );
				return;
			}
			pc_ExtBackupSettingInfo->setExtBackupSettingAutoBackupFullBackupCycle( TYPE_BackupRestoreSettingExt_FullBackupCycle_Weekday );
			if( 0 == m_sc_Inputselect ) {
				// 日周期で「日」を選択した状態で週周期に切り替えた場合は、「時」を選択状態にする.
				m_sc_Inputselect = 1;
			}
			break;
		case BTNID_KEY_ServiceExtSrvAutoBkupFull_WeekdaySun:				// 日.
			pc_ExtBackupSettingInfo->setExtBackupSettingAutoBackupFullBackupWeekDay(TYPE_BackupRestoreSettingExt_Weekday_Sun);
			break;
		case BTNID_KEY_ServiceExtSrvAutoBkupFull_WeekdayMon:				// 月.
			pc_ExtBackupSettingInfo->setExtBackupSettingAutoBackupFullBackupWeekDay(TYPE_BackupRestoreSettingExt_Weekday_Mon);
			break;
		case BTNID_KEY_ServiceExtSrvAutoBkupFull_WeekdayTue:				// 火.
			pc_ExtBackupSettingInfo->setExtBackupSettingAutoBackupFullBackupWeekDay(TYPE_BackupRestoreSettingExt_Weekday_Tue);
			break;
		case BTNID_KEY_ServiceExtSrvAutoBkupFull_WeekdayWed:				// 水.
			pc_ExtBackupSettingInfo->setExtBackupSettingAutoBackupFullBackupWeekDay(TYPE_BackupRestoreSettingExt_Weekday_Wed);
			break;
		case BTNID_KEY_ServiceExtSrvAutoBkupFull_WeekdayThu:				// 木.
			pc_ExtBackupSettingInfo->setExtBackupSettingAutoBackupFullBackupWeekDay(TYPE_BackupRestoreSettingExt_Weekday_Thu);
			break;
		case BTNID_KEY_ServiceExtSrvAutoBkupFull_WeekdayFri:				// 金.
			pc_ExtBackupSettingInfo->setExtBackupSettingAutoBackupFullBackupWeekDay(TYPE_BackupRestoreSettingExt_Weekday_Fri);
			break;
		case BTNID_KEY_ServiceExtSrvAutoBkupFull_WeekdaySat:				// 土.
			pc_ExtBackupSettingInfo->setExtBackupSettingAutoBackupFullBackupWeekDay(TYPE_BackupRestoreSettingExt_Weekday_Sat);
			break;
		case BTNID_KEY_ServiceExtSrvAutoBkupFull_CycleDay:					// 日.
			m_sc_Inputselect = 0;														// 日／時／分キーの選択状態を更新.
			break;
		case BTNID_KEY_ServiceExtSrvAutoBkupFull_TimeHour:					// 時.
			m_sc_Inputselect = 1;														// 日／時／分キーの選択状態を更新.
			break;
		case BTNID_KEY_ServiceExtSrvAutoBkupFull_TimeMinute:				// 分.
			m_sc_Inputselect = 2;														// 日／時／分キーの選択状態を更新.
			break;
		default:
			break;
	}
	setupGamen(uc_option);
}
