// 概要    :M0B0011100_拡張サーバーへバックアップ／自動バックアップ／フルバックアップ周期 : インデックスキー押下処理.
//================================================================================================.
void PServiceExtServerAutoBackupSettingFullBackupSetting::procIndexButton( uchar uc_option )
{
	if( ( PNLD_ServiceExtBackupAutoBackup_2_DIGIT != m_uc_HourInputDigit )
	 || ( PNLD_ServiceExtBackupAutoBackup_2_DIGIT != m_uc_MinuteInputDigit )
	 || ( True == m_bl_DirectDay ) ) {											// どれかが入力中の場合.
	 	// 拒否音を鳴動して、何もしない.
		setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	 }
	
	// 親クラスを呼ぶ.
	PServiceExtServerAutoBackupSettingCom::procIndexButton( uc_option );
}
//================================================================================================.
// 概要    :M0B0011100_拡張サーバーへバックアップ／自動バックアップ／フルバックアップ周期 : クリアキー押下処理.
//================================================================================================.
void PServiceExtServerAutoBackupSettingFullBackupSetting::procClear( uchar uc_option )
{
	PServiceExtServerBackupSettingInfo* pc_ExtBackupSettingInfo = PServiceExtServerBackupSettingInfo::newInstance();
	if( NULL == pc_ExtBackupSettingInfo ) {
// comment 2017/1/6 [IT5-4.0] WP-903 RQ-505_新詳細コード対応 日立 村上幸.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
// 		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if ( NULL != pc_BFW_System ) {
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19000401014E2601 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}

	if( 0 == m_sc_Inputselect ) {															// 日を選択時.
		pc_ExtBackupSettingInfo->setExtBackupSettingAutoBackupFullBackupCycleDay( 0 );		// 日を0に初期化.
		m_bl_DirectDay= True;																// 未入力に変更.
	} else if( 1 == m_sc_Inputselect ) {													// 時を選択時.
		pc_ExtBackupSettingInfo->setExtBackupSettingAutoBackupFullBackupHour( 0 );			// 時を0に初期化.
		m_uc_HourInputDigit = PNLD_ServiceExtBackupAutoBackup_0_DIGIT;						// 未入力に変更.
	} else if( 2 == m_sc_Inputselect ) {													// 分を選択時.
		pc_ExtBackupSettingInfo->setExtBackupSettingAutoBackupFullBackupMinute( 0 );		// 分を0に初期化.
		m_uc_MinuteInputDigit=PNLD_ServiceExtBackupAutoBackup_0_DIGIT;						// 未入力に変更.
	} else {
		// 何もしない.
	}
}
//================================================================================================.
// 概要    :M0B0011100_拡張サーバーへバックアップ／自動バックアップ／フルバックアップ周期 : テンキー押下処理.
//================================================================================================.
void PServiceExtServerAutoBackupSettingFullBackupSetting::proc10Key( uchar uc_option )
{
	uchar	uc_retValue = 0;
	int32_t	i32_MinValue = 0;
	int32_t	i32_MaxValue = 0;
	Bool	bl_ErrorFlg = False;
	PServiceExtServerBackupSettingInfo* pc_ExtBackupSettingInfo = PServiceExtServerBackupSettingInfo::newInstance();
	if( NULL == pc_ExtBackupSettingInfo ) {
// comment 2017/1/6 [IT5-4.0] WP-903 RQ-505_新詳細コード対応 日立 村上幸.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
// 		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if ( NULL != pc_BFW_System ) {
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19002A01014E2701 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}
	// 現在の選択状態に従い、10キー入力した値を設定.
	if( 0 == m_sc_Inputselect ) {									// 日を選択時.
		uc_retValue = ( uchar )proc10KeyInput( (int32_t)pc_ExtBackupSettingInfo->getExtBackupSettingAutoBackupFullBackupCycleDay(), TYPD_BackupRestoreSettingExt_FullBackupCycleDayMax, uc_option, m_bl_DirectDay, EP_InputMaxLimitPattern_Refuse, &bl_ErrorFlg );
	} else if( 1 == m_sc_Inputselect ) {							// 時を選択時.
		i32_MinValue = 0;
		i32_MaxValue = 23;
		uc_retValue = ( uchar )PServiceExtServerAutoBackupSettingCom::proc10KeyAutoBackupInput( (int32_t)(pc_ExtBackupSettingInfo->getExtBackupSettingAutoBackupFullBackupHour()), i32_MinValue, i32_MaxValue, (short)uc_option, &m_uc_HourInputDigit, &bl_ErrorFlg );
	} else if( 2 == m_sc_Inputselect ) {							// 分を選択時.
		i32_MinValue = 0;
		i32_MaxValue = 59;
		uc_retValue = ( uchar )PServiceExtServerAutoBackupSettingCom::proc10KeyAutoBackupInput( (int32_t)(pc_ExtBackupSettingInfo->getExtBackupSettingAutoBackupFullBackupMinute()), i32_MinValue, i32_MaxValue, (short)uc_option, &m_uc_MinuteInputDigit, &bl_ErrorFlg );
	} else {
		// 何もしない.
	}
	if( True == bl_ErrorFlg ) { 									// エラーフラグがTrueの場合.
	// 拒否音を鳴動.
		setBuzzerType( PCGE_BuzzerType_InputNg );
	} else {
		if( 0 == m_sc_Inputselect ) {																		// 日を選択時.
			if( ( True == m_bl_DirectDay ) && ( 1 > uc_option ) ) {
				setBuzzerType( PCGE_BuzzerType_InputNg );													// ブザー音セット.
			} else {
				pc_ExtBackupSettingInfo->setExtBackupSettingAutoBackupFullBackupCycleDay( uc_retValue );	// 日を設定.
				m_bl_DirectDay	= False;
			}
		} else if( 1 == m_sc_Inputselect ) {																// 時を選択時.
			pc_ExtBackupSettingInfo->setExtBackupSettingAutoBackupFullBackupHour( uc_retValue );			// 時を設定.
		} else if( 2 == m_sc_Inputselect ) {																// 分を選択時.
			pc_ExtBackupSettingInfo->setExtBackupSettingAutoBackupFullBackupMinute( uc_retValue );			// 分を設定.
		} else {
			// 何もしない.
		}
	}
}

//================================================================================================.
// 概要    :M0B0011100_拡張サーバーへバックアップ／自動バックアップ／フルバックアップ周期 : OKキー押下処理.
//================================================================================================.
void PServiceExtServerAutoBackupSettingFullBackupSetting::procOk( uchar uc_option )
{
	if( ( PNLD_ServiceExtBackupAutoBackup_2_DIGIT != m_uc_HourInputDigit )
	 || ( PNLD_ServiceExtBackupAutoBackup_2_DIGIT != m_uc_MinuteInputDigit )
	 || ( True == m_bl_DirectDay ) ) {											// どれかが入力中の場合.
	 	// 拒否音を鳴動して、何もしない.
		setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	 }
	
	// 親クラスを呼ぶ.
	PServiceExtServerAutoBackupSettingCom::procOk( uc_option );
}
// comment 2016/ 5/9 [MAv4][CQ528171]クリアキー押下後の時間表示がおかしい 日立 村上(幸).
//================================================================================================.
// 概要    :M0B0011100_拡張サーバーへバックアップ／自動バックアップ／フルバックアップ周期 : 画面開始処理.
//================================================================================================.
void PServiceExtServerAutoBackupSettingFullBackupSetting::startGamen()
{
	// 親クラスの制御をコール.
	PServiceExtServerAutoBackupSettingCom::startGamen();
	PServiceExtServerBackupSettingInfo* pc_ExtBackupSettingInfo = PServiceExtServerBackupSettingInfo::newInstance();
	if( NULL == pc_ExtBackupSettingInfo ) {
// comment 2017/1/6 [IT5-4.0] WP-903 RQ-505_新詳細コード対応 日立 村上幸.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
// 		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if ( NULL != pc_BFW_System ) {
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19006501014E2801 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}

	// 時／分／日を入力済みに初期化する.
	m_uc_HourInputDigit = PNLD_ServiceExtBackupAutoBackup_2_DIGIT;
	m_uc_MinuteInputDigit = PNLD_ServiceExtBackupAutoBackup_2_DIGIT;
	m_bl_DirectDay = False;

	if( TYPE_BackupRestoreSettingExt_FullBackupCycle_Weekday == pc_ExtBackupSettingInfo->getExtBackupSettingAutoBackupFullBackupCycle() ) {
		// 週周期の場合は、「時」を選択状態にする.
		m_sc_Inputselect = 1;
	} else {
		// 日周期の場合は、「日」を選択状態にする.
		m_sc_Inputselect = 0;
	}
}

//================================================================================================.
// 概要    :M0B0011200_拡張サーバーへバックアップ／自動バックアップ／差分バックアップ周期 : コンストラクタ.
//================================================================================================.
PServiceExtServerAutoBackupSettingDiffBackupSetting::PServiceExtServerAutoBackupSettingDiffBackupSetting( PDisplayParts** partsTable, short partsNumber, Bool isNoWarning )
	 : PServiceExtServerAutoBackupSettingCom( partsTable, partsNumber, isNoWarning )
{
	m_uc_HourInputDigit = PNLD_ServiceExtBackupAutoBackup_2_DIGIT;
	m_uc_MinuteInputDigit = PNLD_ServiceExtBackupAutoBackup_2_DIGIT;
	m_bl_DirectInterval = False;
	m_sc_Inputselect = 0;
}
//================================================================================================.
// 概要    :M0B0011200_拡張サーバーへバックアップ／自動バックアップ／差分バックアップ周期 : 表示部品のセットアップ.
//================================================================================================.
void PServiceExtServerAutoBackupSettingDiffBackupSetting::setupGamen( short ss_option )
{
	// 親クラスを呼ぶ.
	PServiceExtServerAutoBackupSettingCom::setupGamen( ss_option );

	PServiceExtServerBackupSettingInfo* pc_ExtBackupSettingInfo = PServiceExtServerBackupSettingInfo::newInstance();
	if( NULL == pc_ExtBackupSettingInfo ) {
// comment 2017/1/6 [IT5-4.0] WP-903 RQ-505_新詳細コード対応 日立 村上幸.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
// 		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if ( NULL != pc_BFW_System ) {
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19006601014E2901 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}
	if( True == pc_ExtBackupSettingInfo->getExtBackupSettingAutoBackupDiffBackupEnable() ) {
		switch( pc_ExtBackupSettingInfo->getExtBackupSettingAutoBackupDiffBackupCycle() ) {
			case TYPE_BackupRestoreSettingExt_DiffBackupCycle_Interval:				// 時間指定.
				Rbt_ServiceExtSrvAutoBkupDiff_PeriodSelect.select( 1 );
				Rbt_ServiceExtSrvAutoBkupDiff_TimePointsSelect.showEnable( False );						// 時刻キーを非表示.
				Grp_ServiceExtSrvAutoBkupDiff_TimePointsParts.showEnable( False );						// 時刻指定のグループキーを非表示.
				Grp_ServiceExtSrvAutoBkupDiff_TimeIntervalsParts.showEnable( True );					// 時間指定のグループキーを表示.
				// 時間の設定.
				Btx_ServiceExtSrvAutoBkupDiff_TimeInterval.set( ( float )pc_ExtBackupSettingInfo->getExtBackupSettingAutoBackupDiffBackupCycleTime(), ( m_bl_DirectInterval == True ) ? False : True );
				break;
			case TYPE_BackupRestoreSettingExt_DiffBackupCycle_Time:					// 時刻指定.
				Rbt_ServiceExtSrvAutoBkupDiff_PeriodSelect.select( 2 );
				Rbt_ServiceExtSrvAutoBkupDiff_TimePointsSelect.showEnable( True );						// 時刻キーを表示.
				Rbt_ServiceExtSrvAutoBkupDiff_TimePointsSelect.select( m_sc_Inputselect );				// ﾊﾞｯｸｱｯﾌﾟ時刻キーの選択.
				Grp_ServiceExtSrvAutoBkupDiff_TimeIntervalsParts.showEnable( False );					// 時間指定のグループキーを非表示.
				Grp_ServiceExtSrvAutoBkupDiff_TimePointsParts.showEnable( True );						// 時刻指定のグループキーを表示.
				// ﾊﾞｯｸｱｯﾌﾟ時刻の設定.
				Btx_ServiceExtSrvAutoBkupDiff_TimeHour.leftSet( ( float )pc_ExtBackupSettingInfo->getExtBackupSettingAutoBackupDiffBackupHour(), m_uc_HourInputDigit );
				Btx_ServiceExtSrvAutoBkupDiff_TimeMinute.leftSet( ( float )pc_ExtBackupSettingInfo->getExtBackupSettingAutoBackupDiffBackupMinute(), m_uc_MinuteInputDigit );
				break;
			default:
				break;
		}
	} else {
		Rbt_ServiceExtSrvAutoBkupDiff_PeriodSelect.select( 0 );
		Rbt_ServiceExtSrvAutoBkupDiff_TimePointsSelect.showEnable( False );								// 時刻キーを非表示.
		Grp_ServiceExtSrvAutoBkupDiff_TimePointsParts.showEnable( False );								// 時刻指定のグループキーを非表示.
		Grp_ServiceExtSrvAutoBkupDiff_TimeIntervalsParts.showEnable( False );							// 時間指定のグループキーを非表示.
	}
}
//================================================================================================.
// 概要    :M0B0011200_拡張サーバーへバックアップ／自動バックアップ／差分バックアップ周期 : キー押下処理.
//================================================================================================.
void PServiceExtServerAutoBackupSettingDiffBackupSetting::procButtonOn( uchar uc_option )
{
	// 親クラスを呼ぶ.
	PServiceExtServerAutoBackupSettingCom::procButtonOn( uc_option );

	PServiceExtServerBackupSettingInfo* pc_ExtBackupSettingInfo = PServiceExtServerBackupSettingInfo::newInstance();
	if( NULL == pc_ExtBackupSettingInfo ) {
// comment 2017/1/6 [IT5-4.0] WP-903 RQ-505_新詳細コード対応 日立 村上幸.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
// 		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if ( NULL != pc_BFW_System ) {
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19000A01014E2A01 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}

	switch( uc_option ) {
		case BTNID_KEY_ServiceExtSrvAutoBkupDiff_Disable:					// 使用しない.
			if( ( PNLD_ServiceExtBackupAutoBackup_2_DIGIT != m_uc_HourInputDigit )
			 || ( PNLD_ServiceExtBackupAutoBackup_2_DIGIT != m_uc_MinuteInputDigit )
			 || ( True == m_bl_DirectInterval ) ) {										// どれかが入力中の場合.
			 	// 拒否音を鳴動して、何もしない.
				setBuzzerType( PCGE_BuzzerType_InputNg );
				return;
			 }
			pc_ExtBackupSettingInfo->setExtBackupSettingAutoBackupDiffBackupEnable( False );
			break;
		case BTNID_KEY_ServiceExtSrvAutoBkupDiff_TimeIntervalDesignate:		// 時間指定.
			if( ( PNLD_ServiceExtBackupAutoBackup_2_DIGIT != m_uc_HourInputDigit )
			 || ( PNLD_ServiceExtBackupAutoBackup_2_DIGIT != m_uc_MinuteInputDigit ) ) {				// 時刻指定が入力中の場合.
			 	// 拒否音を鳴動して、何もしない.
				setBuzzerType( PCGE_BuzzerType_InputNg );
				return;
			 }
			pc_ExtBackupSettingInfo->setExtBackupSettingAutoBackupDiffBackupEnable( True );
			pc_ExtBackupSettingInfo->setExtBackupSettingAutoBackupDiffBackupCycle( TYPE_BackupRestoreSettingExt_DiffBackupCycle_Interval );
			break;
		case BTNID_KEY_ServiceExtSrvAutoBkupDiff_TimePointsDesignate:		// 時刻指定.
			if( True == m_bl_DirectInterval ) {															// 時間指定が入力中の場合.
			 	// 拒否音を鳴動して、何もしない.
				setBuzzerType( PCGE_BuzzerType_InputNg );
				return;
			 }
			pc_ExtBackupSettingInfo->setExtBackupSettingAutoBackupDiffBackupEnable( True );
			pc_ExtBackupSettingInfo->setExtBackupSettingAutoBackupDiffBackupCycle( TYPE_BackupRestoreSettingExt_DiffBackupCycle_Time );
			break;
		case BTNID_KEY_ServiceExtSrvAutoBkupDiff_TimeHour:												// 時.
			m_sc_Inputselect = 0;
			break;
		case BTNID_KEY_ServiceExtSrvAutoBkupDiff_TimeMinute:											// 分.
			m_sc_Inputselect = 1;
			break;
		case BTNID_KEY_ServiceExtSrvAutoBkupDiff_TimeIntervalHour:										// 時(時間指定).
		default:
			break;
	}
	setupGamen( uc_option );
}
//================================================================================================.
// 概要    :M0B0011200_拡張サーバーへバックアップ／自動バックアップ／差分バックアップ周期 : クリアキー押下処理.
//================================================================================================.
void PServiceExtServerAutoBackupSettingDiffBackupSetting::procClear( uchar uc_option )
{
	PServiceExtServerBackupSettingInfo* pc_ExtBackupSettingInfo = PServiceExtServerBackupSettingInfo::newInstance();
	if( NULL == pc_ExtBackupSettingInfo ) {
// comment 2017/1/6 [IT5-4.0] WP-903 RQ-505_新詳細コード対応 日立 村上幸.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
// 		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if ( NULL != pc_BFW_System ) {
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19000401014E2B01 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}
	
	if( False == pc_ExtBackupSettingInfo->getExtBackupSettingAutoBackupDiffBackupEnable() ) {	// ﾊﾞｯｸｱｯﾌﾟ周期「しない」選択時.
		// 拒否音を鳴動して、何もしない.
		setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}
	
	switch( pc_ExtBackupSettingInfo->getExtBackupSettingAutoBackupDiffBackupCycle() ) {
		case TYPE_BackupRestoreSettingExt_DiffBackupCycle_Interval:				// 時間指定.
			pc_ExtBackupSettingInfo->setExtBackupSettingAutoBackupDiffBackupCycleTime( 0 );		// 時(時間指定)を0に初期化.
			m_bl_DirectInterval = True;															// 未入力に変更.
			break;
		case TYPE_BackupRestoreSettingExt_DiffBackupCycle_Time:					// 時刻指定.
			if( 0 == m_sc_Inputselect ) {														// 時を選択時.
				pc_ExtBackupSettingInfo->setExtBackupSettingAutoBackupDiffBackupHour( 0 );		// 時を0に初期化.
				m_uc_HourInputDigit = PNLD_ServiceExtBackupAutoBackup_0_DIGIT;					// 未入力に変更.
			} else if( 1 == m_sc_Inputselect ) {												// 分を選択時.
				pc_ExtBackupSettingInfo->setExtBackupSettingAutoBackupDiffBackupMinute( 0 );	// 分を0に初期化.
				m_uc_MinuteInputDigit=PNLD_ServiceExtBackupAutoBackup_0_DIGIT;					// 未入力に変更.
			} else {
				// 何もしない.
			}
			break;
		default:
			break;
	}
}
