//================================================================================================.
// 概要    :M0B0012000_拡張サーバーへバックアップ／バックアップ予約 : ﾊﾞｯｸｱｯﾌﾟ予約の応答処理.
//================================================================================================.
void PServiceExtServerBackupReserve::ans_BackupReserve( Bool bl_result )
{
	m_bl_BackupReserveResult = bl_result;
	CallBackIndi( TYPE_PNL_CallBack_BackupReserve_Result );
}
//================================================================================================.
// 概要    :M0B0012000_拡張サーバーへバックアップ／バックアップ予約 : コールバック処理.
//================================================================================================.
void PServiceExtServerBackupReserve::procCallBack( TYPE_PNL_CallBack e_option )
{
	switch( e_option ) {
		case TYPE_PNL_CallBack_BackupReserve_Result:		// ﾊﾞｯｸｱｯﾌﾟ予約完了通知.
			m_bl_BackupReserveFix = False;						// 確定キーを非選択状態に変更.
			if( False == m_bl_BackupReserveResult ) {			// 結果が失敗の時.
			 	// 拒否音を鳴動.
				setBuzzerType( PCGE_BuzzerType_InputNg );
			} else {
				// 正常音を鳴動.
				setBuzzerType( PCGE_BuzzerType_InputOk );
			}
			break;
		default:
			break;
	}
}

