//================================================================================================.
// 概要    :共通_拡張サーバーからリストア設定/リストア設定共通 : 表示部品のセットアップ.
//================================================================================================.
void PServiceExtServerRestoreSettingCom::setupGamen( short ss_option )
{
	// 親クラスをコール.
	PServiceNoFunctionCodeCom::setupGamen(ss_option);
	
	// キーの選択状態を設定.
	switch( m_e_ExtServerRestoreSettingShow ) {
		case PNLD_ServiceExtServerRestore_ServerSetting:				// ｻｰﾊﾞｰ設定.
			Rbt_ServiceExtSrvRestoreSettingMenu.select( 0 );
			break;
		case PNLD_ServiceExtServerRestore_WebDAV_URL:					// WebDav設定／URL.
			Rbt_ServiceExtSrvRestoreSettingMenu.select( 1 );
			Rbt_ServiceExtSrvRestore_WebDavSettingMenu.select( 0 );
			break;
		case PNLD_ServiceExtServerRestore_WebDAV_UserName:				// WebDav設定／ﾕｰｻﾞｰ名.
			Rbt_ServiceExtSrvRestoreSettingMenu.select( 1 );
			Rbt_ServiceExtSrvRestore_WebDavSettingMenu.select( 1 );
			break;
		case PNLD_ServiceExtServerRestore_WebDAV_Password:				// WebDav設定／ﾊﾟｽﾜｰﾄﾞ.
			Rbt_ServiceExtSrvRestoreSettingMenu.select( 1 );
			Rbt_ServiceExtSrvRestore_WebDavSettingMenu.select( 2 );
			break;
		case PNLD_ServiceExtServerRestore_WebDAV_Proxy:					// WebDav設定／ﾌﾟﾛｷｼ.
			Rbt_ServiceExtSrvRestoreSettingMenu.select( 1 );
			Rbt_ServiceExtSrvRestore_WebDavSettingMenu.select( 3 );
			break;
		case PNLD_ServiceExtServerRestore_EncryptionPassword:			// 暗号化ﾊﾟｽﾜｰﾄﾞ.
			Rbt_ServiceExtSrvRestoreSettingMenu.select( 2 );
			break;
		case PNLD_ServiceExtServerRestore_RestoreDataSelect:			// ﾘｽﾄｱﾃﾞｰﾀ選択.
			Rbt_ServiceExtSrvRestoreSettingMenu.select( 3 );
			break;
		default:
			break;
	}
	
	PServiceExtServerBackupSettingInfo* pc_ExtServerSettingInfo = PServiceExtServerBackupSettingInfo::newInstance();
	if( NULL == pc_ExtServerSettingInfo ) {
// comment 2017/1/6 [IT5-4.0] WP-903 RQ-505_新詳細コード対応 日立 村上幸.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if ( NULL != pc_BFW_System ) {
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19006601014E3301 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}
	
	if( PNLD_ServiceExtServerRestore_SelectBackupSetting == pc_ExtServerSettingInfo->getExtRestoreSettingServerSetting() ) {
		// ｻｰﾊﾞｰ設定：ﾊﾞｯｸｱｯﾌﾟから取得選択時は、WebDAV設定キー、暗号化ﾊﾟｽﾜｰﾄﾞキーを非表示.
		Key_ServiceExtSrvRestoreSetting_WebDavSetting.showEnable( False );
		Key_ServiceExtSrvRestoreSetting_EncryptPassword.showEnable( False );
	} else {
		// ｻｰﾊﾞｰ設定：ﾊﾞｯｸｱｯﾌﾟから取得選択時は、WebDAV設定キー、暗号化ﾊﾟｽﾜｰﾄﾞキーを表示.
		Key_ServiceExtSrvRestoreSetting_WebDavSetting.showEnable( True );
		Key_ServiceExtSrvRestoreSetting_EncryptPassword.showEnable( True );
	}
}
