//================================================================================================.
// 概要    :M0B0020600_拡張サーバーからリストア／リストア設定／リストアデータ選択 : コンストラクタ.
//================================================================================================.
PServiceExtServerRestoreSettingRestoreDataSelect::PServiceExtServerRestoreSettingRestoreDataSelect( PDisplayParts** partsTable, short partsNumber, Bool isNoWarning )
	 : PServiceExtServerRestoreSettingCom( partsTable, partsNumber, isNoWarning )
{
	m_bl_RestoreStsToggle	 = False;
	m_uc_NowPage			 = 0;
	m_uc_MaxPage			 = 0;
	m_uc_RestoreStatus		 = PNLD_ExtServerRestore_Connectting;
	m_uc_RestoreDataAllNum	 = 0;
	memset( m_psc_MFPFolderData, '\0', sizeof( m_psc_MFPFolderData ) );
	memset( m_sc_RestoreErrorCode, '\0', sizeof( m_sc_RestoreErrorCode ) );
}
//================================================================================================.
// 概要    :M0B0020600_拡張サーバーからリストア／リストア設定／リストアデータ選択 : 画面開始処理.
//================================================================================================.
void PServiceExtServerRestoreSettingRestoreDataSelect::startGamen()
{
	APIC_BackupRestore *pc_BackupRestore = APIC_BackupRestore::newInstance();
	if( NULL == pc_BackupRestore ) {
// comment 2017/1/6 [IT5-4.0] WP-903 RQ-505_新詳細コード対応 日立 村上幸.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if ( NULL != pc_BFW_System ) {
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19006501014E4501 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" ); 
		return;
	}
	// 親クラスをコール.
	PServiceExtServerRestoreSettingCom::startGamen();
	if( True == m_bl_FromRestore ) {
		pc_BackupRestore->clearExtServerRestoreFolderList();
		// 他インデックスキー(ｻｰﾊﾞｰ設定/WebDAV設定/暗号化ﾊﾟｽﾜｰﾄﾞ)からﾘｽﾄｱﾃﾞｰﾀ選択画面に入ってきた時のみリストのダウンロードを実施.
		pc_BackupRestore->downloadExtServerRestoreFolderList( ans_ExtServerRestoreMFPdata, -1 );
		m_bl_FromRestore = False;													// 以降の画面ではダウンロード不要となるため、Falseに変更.
		m_uc_NowPage = 0;															// 初期表示の時は現ページを初期化.
		m_uc_RestoreStatus = PNLD_ExtServerRestore_Connectting;						// 現在の状態を「接続中」とする.
	} else {
		short ss_NowList;
		// 表示しているリスト番号を設定(現ページ×1ページで表示するリスト数).
		ss_NowList = m_uc_NowPage * PNLD_ExtServerRestore_RestoreData_MaxListAtPage;
		// 1ページ表示する最大数分(7件)のﾘｽﾄｱﾃﾞｰﾀ(1階層目)を取得.
		pc_BackupRestore->getExtServerRestoreFolderList( ss_NowList, PNLD_ExtServerRestore_RestoreData_MaxListAtPage, m_psc_MFPFolderData, -1 );
	}
}
