void PServiceExtServerRestoreSettingRestoreDataSelect::procOk( uchar uc_option )
{
	if( PNLD_ExtServerRestore_Connectting == m_uc_RestoreStatus ) {
	 	// 拒否音を鳴動.
		setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}
	// 親クラスをコール.
	PServiceExtServerRestoreSettingCom::procOk(uc_option);
}
//================================================================================================.
// 概要    :M0B0020600_拡張サーバーからリストア／リストア設定／リストアデータ選択 : キー押下処理.
//================================================================================================.
void PServiceExtServerRestoreSettingRestoreDataSelect::procButtonOn( uchar uc_option )
{
	short ss_NowList;																						// 現在の表示している先頭のリスト番号.
	APIC_BackupRestore *pc_BackupRestore = APIC_BackupRestore::newInstance();
	if( NULL == pc_BackupRestore ) {
// comment 2017/1/6 [IT5-4.0] WP-903 RQ-505_新詳細コード対応 日立 村上幸.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if ( NULL != pc_BFW_System ) {
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19000A01014E4601 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" ); 
		return;
	}

	if( PNLD_ExtServerRestore_Connectting == m_uc_RestoreStatus ) {
	 	// 拒否音を鳴動.
			setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}
	switch( uc_option ) {
		case BTNID_ServiceExtSrvRestore_RestoreDataSelectPageUp:											// 上キー.
			if( 0 != m_uc_NowPage ) {																		// 0ページ目でなければ.
				m_uc_NowPage--;
			} else {																						// 0ページ目であれば.
				m_uc_NowPage = m_uc_MaxPage;
			}
			break;
		case BTNID_ServiceExtSrvRestore_RestoreDataSelectPageDown:											// 下キー.
			if( m_uc_NowPage < m_uc_MaxPage ) {																// 現ページが最大ページより小さければ.
				m_uc_NowPage++;
			} else {																						// 最大ページ以上であれば.
				m_uc_NowPage = 0;
			}
			break;
		default: break;
	}
	// 表示しているリスト番号を設定(現ページ×1ページで表示するリスト数).
	ss_NowList = m_uc_NowPage * PNLD_ExtServerRestore_RestoreData_MaxListAtPage;
	// 1ページ表示する最大数分(7件)のﾘｽﾄｱﾃﾞｰﾀ(1階層目)を取得.
	pc_BackupRestore->getExtServerRestoreFolderList( ss_NowList, PNLD_ExtServerRestore_RestoreData_MaxListAtPage, m_psc_MFPFolderData, -1 );
}
//================================================================================================.
// 概要    :M0B0020600_拡張サーバーからリストア／リストア設定／リストアデータ選択 : 画面遷移処理.
//================================================================================================.
void PServiceExtServerRestoreSettingRestoreDataSelect::procGoToPage( uchar uc_option )
{
	short ss_RestoredataSelect = -1;																						// 選択したﾘｽﾄｱﾃﾞｰﾀキー.
	if( PNLD_ExtServerRestore_Connectting == m_uc_RestoreStatus ) {
	 	// 拒否音を鳴動.
		setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}
	// 何番目のﾘｽﾄｱﾃﾞｰﾀを選択したかを保存.
	switch( uc_option ) {
		case BTNID_KEY_ServiceExtSrvRestore_RestoreDataSelect1:	ss_RestoredataSelect = 0;	break;						// 1番目のキーを押下した場合.
		case BTNID_KEY_ServiceExtSrvRestore_RestoreDataSelect2:	ss_RestoredataSelect = 1;	break;						// 2番目のキーを押下した場合.
		case BTNID_KEY_ServiceExtSrvRestore_RestoreDataSelect3:	ss_RestoredataSelect = 2;	break;						// 3番目のキーを押下した場合.
		case BTNID_KEY_ServiceExtSrvRestore_RestoreDataSelect4:	ss_RestoredataSelect = 3;	break;						// 4番目のキーを押下した場合.
		case BTNID_KEY_ServiceExtSrvRestore_RestoreDataSelect5:	ss_RestoredataSelect = 4;	break;						// 5番目のキーを押下した場合.
		case BTNID_KEY_ServiceExtSrvRestore_RestoreDataSelect6:	ss_RestoredataSelect = 5;	break;						// 6番目のキーを押下した場合.
		case BTNID_KEY_ServiceExtSrvRestore_RestoreDataSelect7:	ss_RestoredataSelect = 6;	break;						// 7番目のキーを押下した場合.
		default:	break;
	}
	if( ( ss_RestoredataSelect != -1 )
	 && ( NULL != m_psc_MFPFolderData[ss_RestoredataSelect] ) ) {
		memset(m_sc_RestoreName_First, '\0', sizeof( m_sc_RestoreName_First ) );
		m_us_RestoreNum_First = m_uc_NowPage * PNLD_ExtServerRestore_RestoreData_MaxListAtPage + ss_RestoredataSelect;	// 選択したMFPフォルダの番号を保存.
		memcpy( m_sc_RestoreName_First, m_psc_MFPFolderData[ss_RestoredataSelect], sizeof( m_sc_RestoreName_First ) );	// 選択したMFPフォルダの名称を保存.
	}
	nextGamen = &gp_ServiceExtServerRestoreSettingRestoreData;															// M0B0020700_拡張サーバーからリストア／リストア設定／リストアデータ.
}
