//================================================================================================.
// 概要    :M0B0020600_拡張サーバーからリストア／リストア設定／リストアデータ選択 : コールバック通知.
//================================================================================================.
void PServiceExtServerRestoreSettingRestoreDataSelect::procCallBack( TYPE_PNL_CallBack e_option )
{
	APIC_BackupRestore *pc_BackupRestore = APIC_BackupRestore::newInstance();
	if( NULL == pc_BackupRestore ) {
// comment 2017/1/6 [IT5-4.0] WP-903 RQ-505_新詳細コード対応 日立 村上幸.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if ( NULL != pc_BFW_System ) {
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19006901014E4701 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" ); 
		return;
	}
	if( TYPE_PNL_CallBack_ExtServerRestore1_Result == e_option ) {										// ｻｰﾊﾞｰ接続完了通知.
		if( PNLD_ExtServerRestore_Connect == m_uc_RestoreStatus ) {										// ｻｰﾊﾞｰ接続成功の場合のみ動作.
			m_uc_NowPage = 0;																			// 現在のページ数を初期化(0番目からデータを取得するため).
			// 1ページ表示する最大数分(7件)のﾘｽﾄｱﾃﾞｰﾀ(1階層目)を取得 (初期取得のため、必ず0番目から取得).
			pc_BackupRestore->getExtServerRestoreFolderList( 0, PNLD_ExtServerRestore_RestoreData_MaxListAtPage, m_psc_MFPFolderData, -1 );
		}
	}
}
//================================================================================================.
// 概要    :M0B0020600_拡張サーバーからリストア／リストア設定／リストアデータ選択 : コールバック応答.
//================================================================================================.
void PServiceExtServerRestoreSettingRestoreDataSelect::ans_ExtServerRestoreMFPdata( Bool bl_Result, char *psc_Errorcode, short ss_Count)
{
	if( True == bl_Result ) {																// 成功の場合.
		m_uc_RestoreStatus = PNLD_ExtServerRestore_Connect;									// 結果を保存.
	} else {																				// 失敗の場合.
		m_uc_RestoreStatus = PNLD_ExtServerRestore_ConnectError;							// 結果を保存.
	}
	m_uc_RestoreDataAllNum = ( uchar )ss_Count;												// ﾃﾞｰﾀ数を保存.
// comment 2018/02/16 【HCL-Ajit】 [IT5_4.2] Klockwork Changes ID: 381859 [SV.STRBO.BOUND_COPY.UNTERM].
//	strncpy(m_sc_RestoreErrorCode, psc_Errorcode, PNLD_ErrorCodeLenMax + 1); 				// ｴﾗｰｺｰﾄﾞを保存.
	strncpy(m_sc_RestoreErrorCode, psc_Errorcode, sizeof( m_sc_RestoreErrorCode ) - 1 ); 				// ｴﾗｰｺｰﾄﾞを保存.
	CallBackIndi( TYPE_PNL_CallBack_ExtServerRestore1_Result );								// コールバック通知.
}

