	m_bl_RestoreStsToggle		 = False;
	m_ss_NowPage				 = 0;
	m_ss_MaxPage				 = 0;
	m_uc_RestoreStatus_2		 = PNLD_ExtServerRestore_Connectting;
	m_ss_RestoreDataAllNum_2	 = 0;
	memset( m_psc_DataFolderData, '\0', sizeof( m_psc_DataFolderData ) );
