// 概要    :M0B0020700_拡張サーバーからリストア／リストア設定／リストアデータ : コールバック通知.
//================================================================================================.
void PServiceExtServerRestoreSettingRestoreData::procCallBack( TYPE_PNL_CallBack e_option )
{
// comment 2016/10/11[IT5_4.0][WP-810]仕向けに応じて日にちの表示形式を変更する対応 日立 森本郁.
//	APIC_BackupRestore *pc_BackupRestore = APIC_BackupRestore::newInstance();
//	if( NULL == pc_BackupRestore ) {
//		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); 
//		return;
//	}
	if( TYPE_PNL_CallBack_ExtServerRestore2_Result == e_option ) {									// ｻｰﾊﾞｰ接続完了通知.
		if( PNLD_ExtServerRestore_Connect == m_uc_RestoreStatus_2 ) {								// ｻｰﾊﾞｰ接続成功の場合のみ動作.
			m_ss_NowPage = 0;																		// 現在のページ数を初期化(0番目からデータを取得するため).
			// 1ページ表示する最大数分(7件)のﾘｽﾄｱﾃﾞｰﾀ(2階層目)を取得 (初期取得のため、必ず0番目から取得).
// comment 2016/10/11[IT5_4.0][WP-810]仕向けに応じて日にちの表示形式を変更する対応 日立 森本郁.
//			pc_BackupRestore->getExtServerRestoreFolderList( 0, PNLD_ExtServerRestore_RestoreData_MaxListAtPage2, m_psc_DataFolderData, m_us_RestoreNum_First );
			// リストアデータ格納フォルダ名とリストアデータ日時表示用文字列を取得.
			getRestoreDataDispName( 0 );
		}
	}
}
//================================================================================================.
// 概要    :M0B0020700_拡張サーバーからリストア／リストア設定／リストアデータ : コールバック応答.
//================================================================================================.
void PServiceExtServerRestoreSettingRestoreData::ans_ExtServerRestoreFiledata( Bool bl_Result, char *psc_Errorcode, short ss_Count)
{
	if( True == bl_Result ) {																// 成功の場合.
		m_uc_RestoreStatus_2 = PNLD_ExtServerRestore_Connect;								// 結果を保存.
	} else {																				// 失敗の場合.
		m_uc_RestoreStatus_2 = PNLD_ExtServerRestore_ConnectError;							// 結果を保存.
	}
	m_ss_RestoreDataAllNum_2 = ss_Count;													// ﾃﾞｰﾀ数を保存.
// comment 2018/02/16 【HCL-Ajit】 [IT5_4.2] Klockwork Changes ID: 381859 [SV.STRBO.BOUND_COPY.UNTERM].
//	strncpy(m_sc_RestoreErrorCode_2, psc_Errorcode, PNLD_ErrorCodeLenMax + 1); 				// ｴﾗｰｺｰﾄﾞを保存.
	strncpy(m_sc_RestoreErrorCode_2, psc_Errorcode, sizeof( m_sc_RestoreErrorCode_2 ) - 1 ); 				// ｴﾗｰｺｰﾄﾞを保存.
	CallBackIndi( TYPE_PNL_CallBack_ExtServerRestore2_Result );								// コールバック通知.
}

// comment 2016/10/11[IT5_4.0][WP-810]仕向けに応じて日にちの表示形式を変更する対応 日立 森本郁.
//================================================================================================.
// 概要    :M0B0020700_拡張サーバーからリストア／リストア設定／リストアデータ :  仕向け毎の表示日時文字列取得.
//================================================================================================.
void PServiceExtServerRestoreSettingRestoreData::getRestoreDataDispName( short ss_NowList )
{
	APIC_BackupRestore *pc_BackupRestore = APIC_BackupRestore::newInstance();
	char*	psc_RestoreData[PNLD_ExtServerRestore_FolderDataMax];
	ushort	us_roopCnt = 0;
	
	if( NULL == pc_BackupRestore ) {
// comment 2017/1/6 [IT5-4.0] WP-903 RQ-505_新詳細コード対応 日立 村上幸.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if ( NULL != pc_BFW_System ) {
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19007001014E4901 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" ); 
		return;
	}
	
	memset( psc_RestoreData, '\0', sizeof( psc_RestoreData ) );
	memset( m_psc_DataFolderData, '\0', sizeof( m_psc_DataFolderData ) );
	
	// リストアデータフォルダ名一覧取得.
	pc_BackupRestore->getExtServerRestoreFolderList( ss_NowList, PNLD_ExtServerRestore_RestoreData_MaxListAtPage2, psc_RestoreData, m_us_RestoreNum_First );
	
	for( us_roopCnt = 0; us_roopCnt < PNLD_ExtServerRestore_RestoreData_MaxListAtPage2; us_roopCnt++ ) {
		if( NULL != psc_RestoreData[us_roopCnt] ) {
			// 仕向け毎の日時表示形式取得.
			TYPE_SystemType e_SystemType = PnlComGetMachineSetting()->getSystemType();		// 現在の仕向け設定.
			
			char*	psc_RestoreDataFolderNameTmp;											// フォルダ名格納ポインタ作業用変数.
			char	sc_Year[PNLD_ExtServerRestore_RestoreData_YearCharMax + 1];				// 「年」格納用一時変数.
			char	sc_Month[PNLD_ExtServerRestore_RestoreData_MonthCharMax + 1];			// 「月」格納用一時変数.
			char	sc_Day[PNLD_ExtServerRestore_RestoreData_DayCharMax + 1];				// 「日」格納用一時変数.
			char	sc_Hour[PNLD_ExtServerRestore_RestoreData_HourCharMax + 1];				// 「時」格納用一時変数.
			char	sc_Minute[PNLD_ExtServerRestore_RestoreData_MinuteCharMax + 1];			// 「分」格納用一時変数.
			
			// CommonAPIから取得したデータを一次関数にコピー.
			psc_RestoreDataFolderNameTmp = psc_RestoreData[us_roopCnt];
			
			// 各種一時変数を初期化.
			memset( sc_Year,	'\0',	sizeof( sc_Year   ) );
			memset( sc_Month,	'\0',	sizeof( sc_Month  ) );
			memset( sc_Day,		'\0',	sizeof( sc_Day    ) );
			memset( sc_Hour,	'\0',	sizeof( sc_Hour   ) );
			memset( sc_Minute,	'\0',	sizeof( sc_Minute ) );
			
			// 取得したフォルダ名は「YYYYMMDDHHmm」の順に並んでいる為、順番に取得する.
			strncpy( sc_Year,	&psc_RestoreDataFolderNameTmp[PNLD_ExtServerRestore_RestoreData_YearPtr],	PNLD_ExtServerRestore_RestoreData_YearCharMax   );		// 「年」取得.
			strncpy( sc_Month,	&psc_RestoreDataFolderNameTmp[PNLD_ExtServerRestore_RestoreData_MonthPtr],	PNLD_ExtServerRestore_RestoreData_MonthCharMax  );		// 「月」取得.
			strncpy( sc_Day,	&psc_RestoreDataFolderNameTmp[PNLD_ExtServerRestore_RestoreData_DayPtr],	PNLD_ExtServerRestore_RestoreData_DayCharMax    );		// 「日」取得.
			strncpy( sc_Hour,	&psc_RestoreDataFolderNameTmp[PNLD_ExtServerRestore_RestoreData_HourPtr],	PNLD_ExtServerRestore_RestoreData_HourCharMax   );		// 「時」取得.
			strncpy( sc_Minute,	&psc_RestoreDataFolderNameTmp[PNLD_ExtServerRestore_RestoreData_MinutePtr],	PNLD_ExtServerRestore_RestoreData_MinuteCharMax );		// 「分」取得.
			
			switch( e_SystemType ) {
				case TYPE_SystemType_JP:		// 日本仕向け.
					snprintf( m_psc_DataFolderData[us_roopCnt], PNLD_ExtServerRestore_RestoreDataDispName_CharMax + 1, "%s/%s/%s %s:%s", sc_Year, sc_Month, sc_Day, sc_Hour, sc_Minute );
					break;
				case TYPE_SystemType_US:		// MC仕向け.
					snprintf( m_psc_DataFolderData[us_roopCnt], PNLD_ExtServerRestore_RestoreDataDispName_CharMax + 1, "%s/%s/%s %s:%s", sc_Month, sc_Day, sc_Year, sc_Hour, sc_Minute );
					break;
				case TYPE_SystemType_EU:		// EU/その他仕向け.
				default:
					snprintf( m_psc_DataFolderData[us_roopCnt], PNLD_ExtServerRestore_RestoreDataDispName_CharMax + 1, "%s/%s/%s %s:%s", sc_Day, sc_Month, sc_Year, sc_Hour, sc_Minute );
					break;
			}
		}
	}
}

uchar PServiceExtServerRestoreSettingRestoreExecute::m_uc_RestoreStartStatus = 0;										// ﾘｽﾄｱ状況.
char  PServiceExtServerRestoreSettingRestoreExecute::m_sc_RestoreResult[PNLD_ExtServerRestoreResultLogMax + 1] = {0};	// ﾘｽﾄｱ結果.
//================================================================================================.
// 概要    :M0B0020800_拡張サーバーからリストア／リストア設定／リストア実行 : コンストラクタ.
//================================================================================================.
PServiceExtServerRestoreSettingRestoreExecute::PServiceExtServerRestoreSettingRestoreExecute( PDisplayParts** partsTable, short partsNumber, Bool isNoWarning )
	 : PServiceExtServerRestoreSettingCom( partsTable, partsNumber, isNoWarning )
{
	m_uc_RestoreTargetNum = 0;
	m_uc_TargetNowPage = 0;
	// Comment 2017/02/20 HCL_Sasaki IT5_4.0 Klockwork Changes ID:75405.
	m_uc_TargetMaxPage = 0;
	m_uc_RestoreStartStatus = PNLD_ExtServerRestoreStart_None;
	memset( m_sc_RestoreResult, '\0', sizeof( m_sc_RestoreResult ) );
	memset( &m_st_RestoreTarget, 0, sizeof( m_st_RestoreTarget ) );
}
//================================================================================================.
// 概要		:エクスポート対象項目を設定する.
// 戻り値	:なし.
// 備考		:項目を追加する際は、以下のテーブル(st_ExportTargetAll[])へ表示順に従い追加する.
//			 機能拡張の違いなどによる表示を詰める処理はfor文内に追加する.
//================================================================================================.
void PServiceExtServerRestoreSettingRestoreExecute::setRestoreTarget()
{
	uchar uc_Cnt = 0;
	m_uc_RestoreTargetNum = 0;
	memset( &m_st_RestoreTarget, 0, sizeof( m_st_RestoreTarget ) );

	// エクスポート項目名.
	const PNLS_RestoreTarget st_RestoreTargetAll[PNLD_ExtServerRestoreTarget_MaxItem] = {
		{ s_KEYRemoteDiagnosisSettingService,	 TYPE_BackupRestoreSettingExt_Target_RemoteDiagnosis	},	// 遠隔診断設定.
		{ s_KEYUserSettingService,				 TYPE_BackupRestoreSettingExt_Target_User				},	// ユーザー設定.
		{ s_KEYServiceSettingService,			 TYPE_BackupRestoreSettingExt_Target_Service			},	// サービス設定.
		{ s_ITMServiceCustomizeAuthentication,	 TYPE_BackupRestoreSettingExt_Target_AuthCustom			},	// 認証カスタマイズ.
		{ s_KEYAddressBookService,				 TYPE_BackupRestoreSettingExt_Target_Address			},	// アドレス帳.
		{ s_KEYAuthRelatedDataService,			 TYPE_BackupRestoreSettingExt_Target_AuthRelation		},	// 認証関連データ.
		{ s_KEYNetworkSettingService,			 TYPE_BackupRestoreSettingExt_Target_Network			},	// ネットワーク設定.
		{ s_KEYServiceUniversalSetting,			 TYPE_BackupRestoreSettingExt_Target_Universal			},	// ユニバーサル設定.
		{ s_KEYAdministratorSettingService,		 TYPE_BackupRestoreSettingExt_Target_Admin				},	// 管理者設定.
		{ s_KEYServiceCloudContact,				 TYPE_BackupRestoreSettingExt_Target_CloudContact		},	// ｸﾗｳﾄﾞ連携.
		{ s_KEYServiceTopMenuSetting,			 TYPE_BackupRestoreSettingExt_Target_ScreenCustom		},	// 画面カスタム設定.
		{ s_KEYExternalCertificate,				 TYPE_BackupRestoreSettingExt_Target_ExternalCertificate},	// 外部証明書.
		{ s_KEYServiceExtServerRestoreOrginal,	 TYPE_BackupRestoreSettingExt_Target_ModelUniqueValue	},	// 機種固有設定.
		{ s_KEYServiceExtServerRestoreBoxFormat, TYPE_BackupRestoreSettingExt_Target_BoxDoc				},	// ﾎﾞｯｸｽ文書.
	};
	for(uc_Cnt = 0; uc_Cnt < PNLD_ExtServerRestoreTarget_MaxItem; uc_Cnt++ ) {
		m_st_RestoreTarget[m_uc_RestoreTargetNum] = st_RestoreTargetAll[uc_Cnt];
		m_uc_RestoreTargetNum++;
	}
}
//================================================================================================.
// 概要    :M0B0020800_拡張サーバーからリストア／リストア設定／リストア実行 : 画面開始処理.
//================================================================================================.
void PServiceExtServerRestoreSettingRestoreExecute::startGamen()
{
	// 2つ上の親クラスをコール.
	PServiceNoFunctionCodeCom::startGamen();

	PServiceExtServerBackupSettingInfo* pc_ExtServerSettingInfo = PServiceExtServerBackupSettingInfo::newInstance();
	if( NULL == pc_ExtServerSettingInfo ) {
// comment 2017/1/6 [IT5-4.0] WP-903 RQ-505_新詳細コード対応 日立 村上幸.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if ( NULL != pc_BFW_System ) {
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19006501014E4A01 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}
	if( ( PNLD_ExtServerRestoreStart_Running != m_uc_RestoreStartStatus ) 
	  &&( PNLD_ExtServerRestoreStart_RestoreOK != m_uc_RestoreStartStatus )
	  &&( PNLD_ExtServerRestoreStart_RestoreNG != m_uc_RestoreStartStatus ) )
	  {																								// 実行中または再起動必要ではない場合.
		// ﾘｽﾄｱ成功せずに他画面から遷移してきた時は、ﾘｽﾄｱ状況を未実施に設定(初期化).
		m_uc_RestoreStartStatus = PNLD_ExtServerRestoreStart_None;
		pc_ExtServerSettingInfo->setExtRestoreSettingTarget( 0 );									// 共通データクラスのリストア設定を初期化.
	}
	// ﾘｽﾄｱ対象項目を設定.
	setRestoreTarget();
	// 現在のページ数を初期化.
	m_uc_TargetNowPage = 0;
	// 最大のページ数を設定.
	if( 0 == m_uc_RestoreTargetNum % PNLD_ExtServerRestoreTarget_MaxItemPage ) {					// 現在、登録しているﾘｽﾄｱ対象の項目数/1ページ表示数で割り切れる場合.
		m_uc_TargetMaxPage = m_uc_RestoreTargetNum / PNLD_ExtServerRestoreTarget_MaxItemPage - 1;
	} else {
		m_uc_TargetMaxPage = m_uc_RestoreTargetNum / PNLD_ExtServerRestoreTarget_MaxItemPage;
	}
}
//================================================================================================.
// 概要    :M0B0020800_拡張サーバーからリストア／リストア設定／リストア実行 : 表示部品のセットアップ.
//================================================================================================.
void PServiceExtServerRestoreSettingRestoreExecute::setupGamen( short ss_option )
{
	uchar	uc_Cnt = 0;																	// カウンタ用変数.
	uchar	uc_RestoreNum = 0;															// ﾘｽﾄｱ対象の番号.
	uint32_t	ui32_Restore_Done;														// ﾘｽﾄｱ実行中のﾘｽﾄｱ完了ファイル数.
	uint32_t	ui32_Restore_Total;														// ﾘｽﾄｱ実行中の全ファイル数.
	char	sc_RestoreProcessDone[PNLD_RestoreExecuteResultlogAll];						// ﾘｽﾄｱ実行中を表示するための文字列.
	char	sc_RestoreProcessAll[PNLD_RestoreExecuteResultlogAll];						// ﾘｽﾄｱ実行中を表示するための文字列.
	char	sc_RestoreData[PNLD_ServiceExtServerRestore_RestoreNameFirst_Max + PNLD_ServiceExtServerRestore_RestoreNameSecond_Max + 4] = {0};
	char	sc_RestorePage[PNLD_RestoreExecuteRestoreTargetPage] = {0};					// ﾘｽﾄｱ対象のページ数("X / X"のため、最大5文字).
	TYPE_BackupRestoreSettingExt_Target e_Target;
	PSelectButton* const ptr_TargetKey[PNLD_ExtServerRestoreTarget_MaxItemPage] = {		// ﾘｽﾄｱ対象のキーパーツ群.
		&Key_ServiceExtSrvRestoreExecuteRestoreTarget1,
		&Key_ServiceExtSrvRestoreExecuteRestoreTarget2,
		&Key_ServiceExtSrvRestoreExecuteRestoreTarget3,
		&Key_ServiceExtSrvRestoreExecuteRestoreTarget4,
		&Key_ServiceExtSrvRestoreExecuteRestoreTarget5,
		&Key_ServiceExtSrvRestoreExecuteRestoreTarget6,
	};
	// 2つ上の親クラスをコール.
	PServiceNoFunctionCodeCom::setupGamen(ss_option);
	PServiceExtServerBackupSettingInfo* pc_ExtServerSettingInfo = PServiceExtServerBackupSettingInfo::newInstance();
	if( NULL == pc_ExtServerSettingInfo ) {
// comment 2017/1/6 [IT5-4.0] WP-903 RQ-505_新詳細コード対応 日立 村上幸.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if ( NULL != pc_BFW_System ) {
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19006601014E4B01 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}
	APIC_BackupRestore *pc_BackupRestore = APIC_BackupRestore::newInstance();
	if( NULL == pc_BackupRestore ) {
// comment 2017/1/6 [IT5-4.0] WP-903 RQ-505_新詳細コード対応 日立 村上幸.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if ( NULL != pc_BFW_System ) {
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19006601014E4C01 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" ); 
		return;
	}

	memset( sc_RestoreProcessDone, '\0', sizeof( sc_RestoreProcessDone ) );
	memset( sc_RestoreProcessAll, '\0', sizeof( sc_RestoreProcessAll ) );
	memset( sc_RestoreData, '\0', sizeof( sc_RestoreData ) );
	memset( sc_RestorePage, '\0', sizeof( sc_RestorePage ) );

	// タイトル部分の表示.
// comment 2016/10/11[IT5_4.0][WP-810]仕向けに応じて日にちの表示形式を変更する対応 日立 森本郁.
//	sprintf( (char*)sc_RestoreData, "%s / %s", m_sc_RestoreName_First, m_sc_RestoreName_Second );							// 選択したﾘｽﾄｱﾃﾞｰﾀを表示(1階層+2階層).
//	Tfd_ServiceExtSrvRestoreExecuteRestoreData.changeExternalText( (uchar*)sc_RestoreData, strlen( sc_RestoreData ) );		// 名称をﾘｽﾄｱﾃﾞｰﾀに変更.
	Tfd_ServiceExtSrvRestoreExecuteSelectMachine.changeExternalText( (uchar*)m_sc_RestoreName_First, ( short )strlen( m_sc_RestoreName_First ) );		// 選択ﾏｼﾝの表示.
	Tfd_ServiceExtSrvRestoreExecuteTitleDataDateTime.changeExternalText( (uchar*)m_sc_RestoreName_Second, ( short )strlen( m_sc_RestoreName_Second ) );	// ﾃﾞｰﾀ日時の表示.
	// ﾘｽﾄｱ対象部分の表示(ページ).
// comment 2016/11/7 [IT5_4.0][AR1007016]日立 森本 コーディング規約違反修正対応.
//	sprintf( (char*)sc_RestorePage, "%d / %d", (m_uc_TargetNowPage+1), (m_uc_TargetMaxPage+1) );							// ページ数の設定.
	snprintf( (char*)sc_RestorePage, sizeof(sc_RestorePage), "%d / %d", (m_uc_TargetNowPage+1), (m_uc_TargetMaxPage+1) );	// ページ数の設定.
	Tfd_ServiceExtSrvRestoreExecutePageNum.changeExternalText( (uchar*)sc_RestorePage, ( short )strlen( sc_RestorePage ) );			// ページ数を表示.
	// ﾘｽﾄｱ対象部分の表示.
	e_Target = pc_ExtServerSettingInfo->getExtRestoreSettingTarget();														// 現在設定しているﾘｽﾄｱ対象を取得.
	for( uc_Cnt = 0;uc_Cnt < PNLD_ExtServerRestoreTarget_MaxItemPage; uc_Cnt++) {
		uc_RestoreNum = (m_uc_TargetNowPage*PNLD_ExtServerRestoreTarget_MaxItemPage)+uc_Cnt;								// 何番目のﾘｽﾄｱ対象かを保存.
		if( m_uc_RestoreTargetNum <= uc_RestoreNum ) {																		// 登録した最大個数を超えた場合.
			ptr_TargetKey[uc_Cnt]->showEnable( False );																		// キーを非表示.
		} else {
			ptr_TargetKey[uc_Cnt]->showEnable( True );																		// キーを表示.
			// キーパーツのテキストを変更.
			ptr_TargetKey[uc_Cnt]->changeText( m_st_RestoreTarget[uc_RestoreNum].us_TitleID );
			// 現在のﾘｽﾄｱ対象の選択状態とor計算(フラグをチェック)し、フラグがONであれば、選択状態に表示.
			ptr_TargetKey[uc_Cnt]->select( (e_Target & m_st_RestoreTarget[uc_RestoreNum].e_Target) != 0x00 ? True : False );
		}
	}
	if( 0 == e_Target ) {																									// 未選択の時(全ビットが0).
		Key_ServiceExtSrvRestoreExecuteStart.showEnable( False );															// スタートキーを非表示.
	} else {
		Key_ServiceExtSrvRestoreExecuteStart.showEnable( True );															// スタートキーを表示.
	}
	switch( m_uc_RestoreStartStatus ) {
		case PNLD_ExtServerRestoreStart_None:																						// 未実施.
			Grp_ServiceExtSrvRestoreExecuteRestoreRunning.showEnable( False );														// 実行中関連のグループパーツを非表示.
			Grp_ServiceExtSrvRestoreExecuteResult.showEnable( False );																// ﾘｽﾄｱの結果関連のグループパーツを非表示.
			Grp_ServiceExtSrvRestoreExecuteErrorCode.showEnable( False );															// ｴﾗｰｺｰﾄﾞのグループパーツを非表示.
			Grp_ServiceExtSrvRestoreExecuteResultBoxFormat_Total.showEnable( False );												// ﾎﾞｯｸｽ文書_結果のグループパーツを非表示.
			Txt_ServiceExtSrvRestoreExecutePowerOffMessage.showEnable( False );														// 「主電源OFF/ONしてください」を非表示.
			break;
		case PNLD_ExtServerRestoreStart_Running:																					// 実行中.
			Grp_ServiceExtSrvRestoreExecuteResult.showEnable( False );																// ﾘｽﾄｱの結果関連のグループパーツを非表示.
			Grp_ServiceExtSrvRestoreExecuteErrorCode.showEnable( False );															// ｴﾗｰｺｰﾄﾞのグループパーツを非表示.
			Grp_ServiceExtSrvRestoreExecuteResultBoxFormat_Total.showEnable( False );												// ﾎﾞｯｸｽ文書_結果のグループパーツを非表示.
			Txt_ServiceExtSrvRestoreExecutePowerOffMessage.showEnable( False );														// 「主電源OFF/ONしてください」を非表示.
			Grp_ServiceExtSrvRestoreExecuteRestoreRunning.showEnable( True );														// 実行中関連のグループパーツを表示.
			// 実施中処理.
			if( True == pc_BackupRestore->getExtServerRestoreProgress( &ui32_Restore_Done, &ui32_Restore_Total ) ) {
// comment 2016/11/7 [IT5_4.0][AR1007016]日立 森本 コーディング規約違反修正対応.
//				sprintf( (char*)sc_RestoreProcessDone, "%u", ui32_Restore_Done );																			// ﾘｽﾄｱ実行中を表示(ﾘｽﾄｱ済みﾌｧｲﾙ).
//				sprintf( (char*)sc_RestoreProcessAll, "%u", ui32_Restore_Total );																			// ﾘｽﾄｱ実行中を表示(全ファイル).
				snprintf( (char*)sc_RestoreProcessDone, sizeof(sc_RestoreProcessDone), "%u", ui32_Restore_Done );											// ﾘｽﾄｱ実行中を表示(ﾘｽﾄｱ済みﾌｧｲﾙ).
				snprintf( (char*)sc_RestoreProcessAll, sizeof(sc_RestoreProcessAll), "%u", ui32_Restore_Total );											// ﾘｽﾄｱ実行中を表示(全ファイル).
				Tfd_ServiceExtSrvRestoreExecuteRestoreProgressDone.changeExternalText( (uchar*)sc_RestoreProcessDone, ( short )strlen( sc_RestoreProcessDone ) );	// テキストを変更.
				Tfd_ServiceExtSrvRestoreExecuteRestoreProgressTotal.changeExternalText( (uchar*)sc_RestoreProcessAll, ( short )strlen( sc_RestoreProcessAll ) );		// テキストを変更.
			} else {
// comment 2016/10/14 [IT5_4.0][AccuRev1005392]_全体数が確定していなくても完了数を表示させる対応 村上幸.
//				Tfd_ServiceExtSrvRestoreExecuteRestoreProgressDone.changeText( s_Minus );																	// 完了数に"-"を表示.
				snprintf( (char*)sc_RestoreProcessDone, sizeof(sc_RestoreProcessDone), "%u", ui32_Restore_Done );											// ﾘｽﾄｱ実行中を表示(ﾘｽﾄｱ済みﾌｧｲﾙ).
				Tfd_ServiceExtSrvRestoreExecuteRestoreProgressDone.changeExternalText( (uchar*)sc_RestoreProcessDone, ( short )strlen( sc_RestoreProcessDone ) );	// テキストを変更.
				Tfd_ServiceExtSrvRestoreExecuteRestoreProgressTotal.changeText( s_Minus );																	// 全体数に"-"を表示.
			}
			break;
		case PNLD_ExtServerRestoreStart_RestoreOK:																					// 成功.
			Grp_ServiceExtSrvRestoreExecuteErrorCode.showEnable( False );															// ｴﾗｰｺｰﾄﾞのグループパーツを非表示.
			Grp_ServiceExtSrvRestoreExecuteRestoreRunning.showEnable( False );														// 実行中関連のグループパーツを非表示.
			Grp_ServiceExtSrvRestoreExecuteResult.showEnable( True );																// ﾘｽﾄｱの結果関連のグループパーツを表示.
			Txt_ServiceExtSrvRestoreExecutePowerOffMessage.showEnable( True );														// 「主電源OFF/ONしてください」を表示.
			// ﾘｽﾄｱ結果の解析及び表示.
			setupRestoreResult();
			break;
		case PNLD_ExtServerRestoreStart_RestoreNG:																					// 失敗(再起動必要).
			Grp_ServiceExtSrvRestoreExecuteRestoreRunning.showEnable( False );														// 実行中関連のグループパーツを非表示.
			Grp_ServiceExtSrvRestoreExecuteResult.showEnable( True );																// ﾘｽﾄｱの結果関連のグループパーツを表示.
			Grp_ServiceExtSrvRestoreExecuteErrorCode.showEnable( True );															// ｴﾗｰｺｰﾄﾞのグループパーツを非表示.
			Txt_ServiceExtSrvRestoreExecutePowerOffMessage.showEnable( True );														// 「主電源OFF/ONしてください」を表示.
			// ﾘｽﾄｱ結果の解析及び表示.
			setupRestoreResult();
			break;
		case PNLD_ExtServerRestoreStart_RestoreNG2:																					// 失敗(再起動不要).
			Grp_ServiceExtSrvRestoreExecuteRestoreRunning.showEnable( False );														// 実行中関連のグループパーツを非表示.
			Txt_ServiceExtSrvRestoreExecutePowerOffMessage.showEnable( False );														// 「主電源OFF/ONしてください」を非表示.
			Grp_ServiceExtSrvRestoreExecuteErrorCode.showEnable( True );															// ｴﾗｰｺｰﾄﾞのグループパーツを表示.
			Grp_ServiceExtSrvRestoreExecuteResult.showEnable( True );																// ﾘｽﾄｱの結果関連のグループパーツを表示.
			// ﾘｽﾄｱ結果の解析及び表示.
			setupRestoreResult();
			break;
		case PNLD_ExtServerRestoreStart_RestoreOK2:																					// 成功(再起動不要).
			Grp_ServiceExtSrvRestoreExecuteRestoreRunning.showEnable( False );														// 実行中関連のグループパーツを非表示.
			Txt_ServiceExtSrvRestoreExecutePowerOffMessage.showEnable( False );														// 「主電源OFF/ONしてください」を非表示.
			Grp_ServiceExtSrvRestoreExecuteErrorCode.showEnable( False );															// ｴﾗｰｺｰﾄﾞのグループパーツを非表示.
			Grp_ServiceExtSrvRestoreExecuteResult.showEnable( True );																// ﾘｽﾄｱの結果関連のグループパーツを表示.
			// ﾘｽﾄｱ結果の解析及び表示.
			setupRestoreResult();
			break;
		default:	break;
	}
//comment 2018/05/17 HCLT-Basker [Sparrow][制御構成変更_No.206 ] Remove the unneccessary functions from SparrowSFP models.
	if ( IsSFP() ) {
//comment 2018/07/17 HCLT-Basker [Sparrow][制御構成変更_No.206 ] Remove the unneccessary functions from SparrowSFP models.
		if ( m_uc_TargetNowPage == PNLD_RemoteFWUpdateExportP0 ) {
			Key_ServiceExtSrvRestoreExecuteRestoreTarget5.showEnable( False );
		} else if ( m_uc_TargetNowPage == PNLD_RemoteFWUpdateExportP2 ) {
			Key_ServiceExtSrvRestoreExecuteRestoreTarget2.showEnable( False );
		}
	}
//Comment 2018/06/26 【IT6_DenebMLK】【HCL_Monisha】【AR1049905】 Hide the Remote diagnostic settings Key .
	APIC_SoftDipSw* pc_SoftDipSw = APIC_SoftDipSw::newInstance();
		if( NULL != pc_SoftDipSw ) {
			if ( m_uc_TargetNowPage == 0 ) {
				if( True == pc_SoftDipSw->getSoftDipSwBitForPanelSpecNo( DEFSOFTWARESW153, 3 ) ) {	
					Key_ServiceExtSrvRestoreExecuteRestoreTarget1.showEnable(False);
				} else {
					Key_ServiceExtSrvRestoreExecuteRestoreTarget1.showEnable(True);
				}
			}
		}
		if( NULL != pc_SoftDipSw ) {
				if( True == pc_SoftDipSw->getSoftDipSwBitForPanelSpecNo( DEFSOFTWARESW153, 3 ) ) {	
					Txt_ServiceExtSrvRestoreExecuteTargetRemoteControl.showEnable(False);
					Txt_ServiceExtSrvRestoreExecuteResultRemoteControl.showEnable(False);
				} else {
					Txt_ServiceExtSrvRestoreExecuteTargetRemoteControl.showEnable(True);
					Txt_ServiceExtSrvRestoreExecuteResultRemoteControl.showEnable(True);
				}
		}


}
//================================================================================================.
// 概要    :M0B0020800_拡張サーバーからリストア／リストア設定／リストア実行 : ﾘｽﾄｱ結果の解析処理.
//================================================================================================.
void PServiceExtServerRestoreSettingRestoreExecute::setupRestoreResult()
{
	uchar	uc_Cnt = 0;																		// カウンタ用変数.
	ushort	us_CharNumber = 0;																// リストア結果の文字数カウンタ用.
	ushort	us_TextLen = 0;																	// リストア結果の文字列長を格納.
	uchar	uc_commaCnt = 0;																// 何個目のカンマかを格納.
	ushort	us_StartCharNumber	= 0;														// 各格納用の文字列に入れ替えするための変数.
	char	sc_LogDetailCode[ PNLD_ServiceExtSrvBackupHistory_DetailCodeChar ]={0};			// 詳細コード用の配列.
	char	sc_LogBoxFormat[ PNLD_RestoreExecuteResultlogAll ]={0};							// ボックス文書の形式用の配列.
	char	sc_LogKMFormatResult[ PNLD_ServiceExtSrvBackupHistory_BackupResultChar ]={0};	// KMﾌｫｰﾏｯﾄ時の結果用の配列.
	char	sc_LogBoxFormatTotal[ PNLD_RestoreExecuteResultlogAll ]={0};					// 汎用ﾌｫｰﾏｯﾄ時の結果(総数)用の配列.
	char	sc_LogBoxFormatSuccess[ PNLD_RestoreExecuteResultlogAll ]={0};					// 汎用ﾌｫｰﾏｯﾄ時の結果(成功数)用の配列.
	char	sc_ResultTarget[ PNLD_ServiceExtSrvBackupHistory_BackupResultChar ]={0};		// パネル表示用の配列(ﾘｽﾄｱ対象の結果).
	char	sc_buf[PNLD_ExtServerRestoreResultLogMax + 1]={0};								// 一時的に保存するバッファ.
	// ﾘｽﾄｱ結果の内容を下記.
	// 結果の表示を行う項目を"○"、表示に必要ない項目を"×".
		//    1. ログファイル名				×.
		//    2. 開始時間					×.
		//    3. 実施時間					×.
		//    4. 結果						×.
		//    5. 詳細コード					○.
		//    6. URL						×.
		//    7. ﾘｽﾄｱ対象ファイル			×.
		//    8. 文書ﾌｫｰﾏｯﾄ(なし/汎用/KM)	○(Box文書の表示に必要).
		//    9. KM文書_リストア結果		○(Box文書の表示に必要).
		//   10. 汎用文書総数				○(Box文書の表示に必要).
		//   11. 汎用文書成功数				○(Box文書の表示に必要).
		//   12. 結果数						×.
		// 13～. ﾘｽﾄｱ対象(13項目)			○(ﾎﾞｯｸｽ文書除く).

	PNLS_RestoreResultDetail st_ResultDetail[PNLD_ExtServerRestoreTarget_MaxItem] = {				// ﾘｽﾄｱ対象の結果ログ.
		{ &Txt_ServiceExtSrvRestoreExecuteResultRemoteControl,			TYPE_ServerBackupExtBackupConfigTypeCsrc			},			// 遠隔診断設定.
		{ &Txt_ServiceExtSrvRestoreExecuteResultUser,					TYPE_ServerBackupExtBackupConfigTypeUtility			},			// ユーザー設定.
		{ &Txt_ServiceExtSrvRestoreExecuteResultService,				TYPE_ServerBackupExtBackupConfigTypeService			},			// サービス設定.
		{ &Txt_ServiceExtSrvRestoreExecuteResultAuthCostom,				TYPE_ServerBackupExtBackupConfigTypeAuthCustom		},			// 認証カスタマイズ.
		{ &Txt_ServiceExtSrvRestoreExecuteResultAddress,				TYPE_ServerBackupExtBackupConfigTypeAddress			},			// アドレス帳.
		{ &Txt_ServiceExtSrvRestoreExecuteResultAuthData,				TYPE_ServerBackupExtBackupConfigTypeAuth			},			// 認証関連データ.
		{ &Txt_ServiceExtSrvRestoreExecuteResultNetwork,				TYPE_ServerBackupExtBackupConfigTypeNetwork			},			// ネットワーク設定.
		{ &Txt_ServiceExtSrvRestoreExecuteResultUniversal,				TYPE_ServerBackupExtBackupConfigTypeUniversal		},			// ユニバーサル設定.
		{ &Txt_ServiceExtSrvRestoreExecuteResultAdmin,					TYPE_ServerBackupExtBackupConfigTypeAdmin			},			// 管理者設定.
		{ &Txt_ServiceExtSrvRestoreExecuteResultCloudContact,			TYPE_ServerBackupExtBackupConfigTypeCloud			},			// ｸﾗｳﾄﾞ連携.
		{ &Txt_ServiceExtSrvRestoreExecuteResultTopMenuGadget,			TYPE_ServerBackupExtBackupConfigTypeTopMenu			},			// 画面カスタム設定.
		{ &Txt_ServiceExtSrvRestoreExecuteResultExternalCertificate,	TYPE_ServerBackupExtBackupConfigTypeExtCertificates	},			// 外部証明書.
		{ &Txt_ServiceExtSrvRestoreExecuteResultOrginal,				TYPE_ServerBackupExtBackupConfigTypeMFPSetting		},			// 機種固有設定.
	};
	us_TextLen = ( ushort )strlen( m_sc_RestoreResult );
	memcpy( sc_buf, m_sc_RestoreResult, sizeof(sc_buf) );
	for( us_CharNumber = 0; us_CharNumber < us_TextLen; us_CharNumber++ ) {												// 文字列長分ループ.
		// ﾘｽﾄｱ結果を1文字ずつ確認し、','数をカウント.
		if( ',' == m_sc_RestoreResult[us_CharNumber] ) {																// カンマを発見した場合.
			uc_commaCnt += 1;																							// カンマ用カウンタをインクリメント.
			if( PNLD_RestoreExecuteResultlogDetailCode == uc_commaCnt ){
				sc_buf[us_CharNumber] = '\0';
				// 詳細コードのデータ解析処理.
				strncpy( sc_LogDetailCode, &sc_buf[us_StartCharNumber], sizeof( sc_LogDetailCode ) - 1 );				// 現在のデータの先頭から文字列分をコピー.
				// 詳細コードのテキストフィールドに取得したデータを設定.
				Tfd_ServiceExtSrvRestoreExecuteErrorCode.changeExternalText( (uchar*)sc_LogDetailCode, ( short )strlen( sc_LogDetailCode ) );
			} else if( PNLD_RestoreExecuteResultlogBoxFormat == uc_commaCnt ) {
				// ","を"\0"に変換し、文字列の開始位置(us_StartCharNumber)から文字列コピー.
				// strncpy()は"\0"までをコピーするので、","(ログの区切り)までをコピーする.
				sc_buf[us_CharNumber] = '\0';
				// ﾎﾞｯｸｽ文書ﾌｫｰﾏｯﾄのデータ解析処理(KM/汎用の判定用のデータを取得).
				strncpy( sc_LogBoxFormat, &sc_buf[us_StartCharNumber], sizeof( sc_LogBoxFormat ) - 1 );					// 現在のデータの先頭から文字列分をコピー.
			} else if( PNLD_RestoreExecuteResultlogKMFormatResult == uc_commaCnt ) {
				sc_buf[us_CharNumber] = '\0';
				// KMﾌｫｰﾏｯﾄ時の結果のデータ解析処理(上記の「sc_LogBoxFormat」の条件で制御変更).
				strncpy( sc_LogKMFormatResult, &sc_buf[us_StartCharNumber], sizeof( sc_LogKMFormatResult ) - 1 );		// 現在のデータの先頭から文字列分をコピー.
				if( PNLD_RestoreExecuteResultBoxFormat_None == atoi( sc_LogBoxFormat ) ) {
					// 不明(0)は未実施(-)を表示(XXXX / XXXXは表示しない).
					Txt_ServiceExtSrvRestoreExecuteResultBoxFormat.changeText( s_Minus );
					Grp_ServiceExtSrvRestoreExecuteResultBoxFormat_Total.showEnable( False );
				} else if( PNLD_RestoreExecuteResultBoxFormat_KM == atoi(sc_LogBoxFormat ) ){
					// KMﾌｫｰﾏｯﾄ(1)はOK/NG/-を表示(XXXX / XXXXは表示しない).
					if( strstr( sc_LogKMFormatResult, "OK" ) ) {														// OKを含んでいる場合.
						Txt_ServiceExtSrvRestoreExecuteResultBoxFormat.changeText( s_ServiceMemoryCheck_OK );			// 結果に「OK」を表示.
					} else if(strstr( sc_LogKMFormatResult, "NG" )) {													// NGを含んでいる場合.
						Txt_ServiceExtSrvRestoreExecuteResultBoxFormat.changeText( s_ServiceMemoryCheck_NG );			// 結果に「NG」を表示.
					} else {																							// その他(-の場合).
						Txt_ServiceExtSrvRestoreExecuteResultBoxFormat.changeText( s_Minus );							// 結果に「-」を表示.
					}
					Grp_ServiceExtSrvRestoreExecuteResultBoxFormat_Total.showEnable( False );							// ﾎﾞｯｸｽ文書_結果のグループパーツを非表示.
				} else {
					// それ以外(汎用ﾌｫｰﾏｯﾄ)の場合はXXXX / XXXXの表示となるため、テキストを非表示.
					Txt_ServiceExtSrvRestoreExecuteResultBoxFormat.showEnable( False );
					Grp_ServiceExtSrvRestoreExecuteResultBoxFormat_Total.showEnable( True );							// ﾎﾞｯｸｽ文書_結果のグループパーツを非表示.
				}
			} else if( PNLD_RestoreExecuteResultlogBoxFormatTotal == uc_commaCnt ) {
				// 汎用ﾌｫｰﾏｯﾄのデータ解析処理(XXXX / XXXXの表示).
				sc_buf[us_CharNumber] = '\0';
// comment 20/02/2018 【HCLT-Vishal】【IT6_Eagle】Klockwork Changes ID:1133513 [SV.STRBO.BOUND_COPY.UNTERM].
//				strncpy( sc_LogBoxFormatTotal, &sc_buf[us_StartCharNumber], sizeof(sc_LogBoxFormatTotal) );				// 現在のデータの先頭からNULL終端までをコピー.
				strncpy( sc_LogBoxFormatTotal, &sc_buf[us_StartCharNumber], sizeof(sc_LogBoxFormatTotal) -1 );				// 現在のデータの先頭からNULL終端までをコピー.
				// 全体数のテキストフィールドに取得したデータを設定.
				Tfd_ServiceExtSrvRestoreExecuteResultBoxFormatTotal.changeExternalText( (uchar*)sc_LogBoxFormatTotal, ( short )strlen( sc_LogBoxFormatTotal ) );
			} else if( PNLD_RestoreExecuteResultlogBoxFormatSuccess == uc_commaCnt ) {
				// 汎用ﾌｫｰﾏｯﾄのデータ解析処理(XXXX / XXXXの表示).
				sc_buf[us_CharNumber] = '\0';
// comment 20/02/2018 【HCLT-Vishal】【IT6_Eagle】Klockwork Changes ID:1133503 [SV.STRBO.BOUND_COPY.UNTERM].
//				strncpy( sc_LogBoxFormatSuccess, &sc_buf[us_StartCharNumber], sizeof(sc_LogBoxFormatSuccess) );			// 現在のデータの先頭からNULL終端までをコピー.
				strncpy( sc_LogBoxFormatSuccess, &sc_buf[us_StartCharNumber], sizeof(sc_LogBoxFormatSuccess) -1);			// 現在のデータの先頭からNULL終端までをコピー.
				// 成功数のテキストフィールドに取得したデータを設定.
				Tfd_ServiceExtSrvRestoreExecuteResultBoxFormatDone.changeExternalText( (uchar*)sc_LogBoxFormatSuccess, ( short )strlen( sc_LogBoxFormatSuccess ) );
			} else if( PNLD_RestoreExecuteResultlogRestoreTarget <= uc_commaCnt ){										// ﾘｽﾄｱ対象以降のカンマであれば.
				sc_buf[us_CharNumber] = '\0';
				// 結果ログに保存しているﾘｽﾄｱ対象の結果の順番を判別.
				for(uc_Cnt=0;uc_Cnt<PNLD_ExtServerRestoreTarget_MaxItem; uc_Cnt++) {
					// 現在のログの順番と保存順番を比較し、一致した時.
					if( (uc_commaCnt - PNLD_RestoreExecuteResultlogRestoreTarget) == st_ResultDetail[uc_Cnt].ss_Tartget ) {
						strncpy( sc_ResultTarget, &sc_buf[us_StartCharNumber], sizeof( sc_ResultTarget ) - 1  );		// 現在のデータの先頭からNULL終端までをコピー.
						// 取得した結果ログをOK/NG/-(未実施)の判別.
						if( strstr( sc_ResultTarget, "OK" ) ) {															// OKを含んでいる場合.
							st_ResultDetail[uc_Cnt].ptr_Text->changeText( s_ServiceMemoryCheck_OK );					// 結果に「OK」を表示.
						} else if(strstr( sc_ResultTarget, "NG" )) {													// NGを含んでいる場合.
							st_ResultDetail[uc_Cnt].ptr_Text->changeText( s_ServiceMemoryCheck_NG );					// 結果に「NG」を表示.
						} else {																						// その他(-の場合).
							st_ResultDetail[uc_Cnt].ptr_Text->changeText( s_Minus );									// 結果に「-」を表示.
						}
						break;
					}
				}
			}
			us_StartCharNumber = us_CharNumber + 1;																		// 次の文字列の先頭位置を保存.
		}
	}
}

//================================================================================================.
// 概要    :M0B0020800_拡張サーバーからリストア／リストア設定／リストア実行 : OKキー押下処理.
//================================================================================================.
void PServiceExtServerRestoreSettingRestoreExecute::procOk( uchar uc_option )
{
	if( ( PNLD_ExtServerRestoreStart_Running == m_uc_RestoreStartStatus ) 
	  ||( PNLD_ExtServerRestoreStart_RestoreOK == m_uc_RestoreStartStatus )
	  ||( PNLD_ExtServerRestoreStart_RestoreNG == m_uc_RestoreStartStatus ) )
	  {		// 実行中または再起動必要な場合.
	 	// 拒否音を鳴動.
		setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}
	nextGamen = &gp_ServiceExtServerRestoreSettingRestoreData;								// M0B0020700_拡張サーバーからリストア／リストア設定／リストアデータ.
}
//================================================================================================.
// 概要    :M0B0020800_拡張サーバーからリストア／リストア設定／リストア実行 : キー押下処理.
//================================================================================================.
void PServiceExtServerRestoreSettingRestoreExecute::procButtonOn( uchar uc_option )
{
	if( ( PNLD_ExtServerRestoreStart_Running == m_uc_RestoreStartStatus ) 
	  ||( PNLD_ExtServerRestoreStart_RestoreOK == m_uc_RestoreStartStatus )
	  ||( PNLD_ExtServerRestoreStart_RestoreNG == m_uc_RestoreStartStatus ) )
	  {		// 実行中または再起動必要な場合.
	 	// 拒否音を鳴動.
		setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}
	char sc_TargetSelect = -1;																	// 選択したﾘｽﾄｱ対象キー.
	uchar uc_TargetNum = 0;																		// ﾘｽﾄｱ対象の番号.
	Bool bl_RestoreStart;																		// ﾘｽﾄｱ実施処理の成功/失敗フラグ.
	TYPE_BackupRestoreSettingExt_Target e_Target;
	APIC_BackupRestore *pc_BackupRestore = APIC_BackupRestore::newInstance();
	if( NULL == pc_BackupRestore ) {
// comment 2017/1/6 [IT5-4.0] WP-903 RQ-505_新詳細コード対応 日立 村上幸.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if ( NULL != pc_BFW_System ) {
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19000A01014E4D01 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" ); 
		return;
	}
	PServiceExtServerBackupSettingInfo* pc_ExtServerSettingInfo = PServiceExtServerBackupSettingInfo::newInstance();
	if( NULL == pc_ExtServerSettingInfo ) {
// comment 2017/1/6 [IT5-4.0] WP-903 RQ-505_新詳細コード対応 日立 村上幸.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if ( NULL != pc_BFW_System ) {
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19000A01014E4E01 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}
	e_Target = pc_ExtServerSettingInfo->getExtRestoreSettingTarget();								// 共通データクラスから現在設定しているﾘｽﾄｱ対象を取得.
	switch( uc_option ) {
		case BTNID_ServiceExtSrvRestoreExecuteRestoreTarget1:	sc_TargetSelect = 0;	break;		// ﾘｽﾄｱ対象キー(左上).
		case BTNID_ServiceExtSrvRestoreExecuteRestoreTarget2:	sc_TargetSelect = 1;	break;		// ﾘｽﾄｱ対象キー(中上).
		case BTNID_ServiceExtSrvRestoreExecuteRestoreTarget3:	sc_TargetSelect = 2;	break;		// ﾘｽﾄｱ対象キー(右上).
		case BTNID_ServiceExtSrvRestoreExecuteRestoreTarget4:	sc_TargetSelect = 3;	break;		// ﾘｽﾄｱ対象キー(左下).
		case BTNID_ServiceExtSrvRestoreExecuteRestoreTarget5:	sc_TargetSelect = 4;	break;		// ﾘｽﾄｱ対象キー(中下).
		case BTNID_ServiceExtSrvRestoreExecuteRestoreTarget6:	sc_TargetSelect = 5;	break;		// ﾘｽﾄｱ対象キー(右下).
		case BTNID_ServiceExtSrvRestoreExecutePageUp:
			if( 0 != m_uc_TargetNowPage ) {															// 0ページ目でなければ.
				m_uc_TargetNowPage--;
			} else {																				// 0ページ目であれば.
				m_uc_TargetNowPage = m_uc_TargetMaxPage;
			}
			break;
		case BTNID_ServiceExtSrvRestoreExecutePageDown:
			if( m_uc_TargetNowPage < m_uc_TargetMaxPage ) {											// 現ページが最大ページより小さければ.
				m_uc_TargetNowPage++;
			} else {																				// 最大ページ以上であれば.
				m_uc_TargetNowPage = 0;
			}
			break;
		case BTNID_ServiceExtSrvRestoreExecuteStart:
			pc_ExtServerSettingInfo->commitServiceExtServerRestoreSetting();						// 設定した値をCommonAPIへ設定.
			// 拡張ｻｰﾊﾞｰからﾘｽﾄｱを開始.
			bl_RestoreStart = pc_BackupRestore->startExtServerRestore( ans_ExtServerRestoreStart, m_us_RestoreNum_First, m_us_RestoreNum_Second );
			m_uc_RestoreStartStatus = PNLD_ExtServerRestoreStart_Running;
			if( False == bl_RestoreStart ){															// ﾘｽﾄｱ開始のAPIコールで失敗した場合.
				// 異常ルート(通常ありえない).
				m_uc_RestoreStartStatus = PNLD_ExtServerRestoreStart_RestoreNG;
			}
			break;
		default:	break;
	}

	uc_TargetNum = (m_uc_TargetNowPage*PNLD_ExtServerRestoreTarget_MaxItemPage) + sc_TargetSelect;	// 選択しているﾘｽﾄｱ対象を設定.
	if( -1 != sc_TargetSelect ) {																	// ﾘｽﾄｱ対象キーを選択していれば.
		// 現在の設定値が「未選択」の状態であれば、選択状態に変更.
		if( (e_Target & m_st_RestoreTarget[uc_TargetNum].e_Target) == 0x00 ) {						// 未選択状態の場合.
			e_Target = (e_Target | m_st_RestoreTarget[uc_TargetNum].e_Target);						// 選択状態に変更(指定の項目以外は選択状態を更新しない).
		} else {
			e_Target = (e_Target & ~m_st_RestoreTarget[uc_TargetNum].e_Target);						// 未選択状態に変更(指定の項目以外は選択状態を更新しない)
		}
		pc_ExtServerSettingInfo->setExtRestoreSettingTarget(e_Target);								// 共通データクラスへ設定したﾘｽﾄｱ対象を設定.
	}
	setupGamen(uc_option);
}
