void PServiceExtServerRestoreSettingRestoreExecute::procReset( uchar uc_option )
{
	if( ( PNLD_ExtServerRestoreStart_Running == m_uc_RestoreStartStatus ) 
	  ||( PNLD_ExtServerRestoreStart_RestoreOK == m_uc_RestoreStartStatus )
	  ||( PNLD_ExtServerRestoreStart_RestoreNG == m_uc_RestoreStartStatus ) )
	  {		// 実行中または再起動必要な場合.
	 	// 拒否音を鳴動.
		setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}
	// 親クラスをコール.
	PServiceNoFunctionCodeCom::procReset(uc_option);
}
