Bool PServiceExtServerRestoreHistory::m_bl_USBResult = False;										// USB保存の結果.
//================================================================================================.
// 概要    :M0B0021000_拡張サーバーからリストア／リストア履歴 : コンストラクタ.
//================================================================================================.
PServiceExtServerRestoreHistory::PServiceExtServerRestoreHistory( PDisplayParts** partsTable, short partsNumber, Bool isNoWarning )
	 : PServiceNoFunctionCodeCom( partsTable, partsNumber, isNoWarning )
{
	m_bl_RunningToggle = False;
	m_ss_select = -1;
	m_us_RestoreLogTotal = 0;
	m_uc_USBStatus = PNLD_ExtServerRestoreDetailLogToUSB_None;
	m_bl_USBResult = False;
	memset( m_psc_RestoreLogResult, '\0', sizeof( m_psc_RestoreLogResult ) );
	m_bl_FromMenu = False;	
// Comment 2017/02/20 HCL_Sasaki IT5_4.0 Klockwork Changes ID:75367.
	m_bl_USBConnectionPermissionFlag = False;
}
//================================================================================================.
// 概要    :M0B0021000_拡張サーバーからリストア／リストア履歴 : メニューからの遷移フラグのセッター処理.
//================================================================================================.
void PServiceExtServerRestoreHistory::setFromMenuFlg( Bool bl_FromMenu )
{
	m_bl_FromMenu = bl_FromMenu;
}
//================================================================================================.
// 概要    :M0B0021000_拡張サーバーからリストア／リストア履歴 : 画面開始処理.
//================================================================================================.
void PServiceExtServerRestoreHistory::startGamen()
{
	// 親クラスをコール.
	PServiceNoFunctionCodeCom::startGamen();

	APIC_BackupRestore *pc_BackupRestore = APIC_BackupRestore::newInstance();
	if( NULL == pc_BackupRestore ) {
// comment 2017/1/6 [IT5-4.0] WP-903 RQ-505_新詳細コード対応 日立 村上幸.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if ( NULL != pc_BFW_System ) {
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19006501014E5001 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" ); 
		return;
	}
	if( True == m_bl_FromMenu ) {
		m_bl_FromMenu = False;
		m_uc_USBStatus = PNLD_ExtServerRestoreDetailLogToUSB_None;									// USB保存状態を未実施に設定.
		m_us_RestoreLogTotal = pc_BackupRestore->getExtServerRestoreLog(m_psc_RestoreLogResult);	// ﾘｽﾄｱ結果のログを取得.
		m_ss_select = -1;																			// 選択状態を初期化.
	}
// comment 2016/10/11 [IT5-4.0][WP747]USB接続許可設定が"禁止"の時は、何も表示させない 日立 村上.
	PNLC_USBConnectionPermission c_UsbPermission;
	PNLE_EnableUSBConnectionPermissionForAll e_UsbAll = c_UsbPermission.getEnableUSBConnectionPermissionForAll();					// 全使用者(ﾕｰｻﾞｰ/ｻｰﾋﾞｽ/管理者)の許可/禁止設定を取得.
	PNLE_EnableUSBConnectionPermissionForService e_usbforService = c_UsbPermission.getEnableUSBConnectionPermissionForService();	// ｻｰﾋﾞｽの許可/禁止設定を取得.
	if( ( PNLE_EnableUSBConnectionPermissionForAll_Disable == e_UsbAll )															// 全使用者の設定が禁止の時.
	 || ( PNLE_EnableUSBConnectionPermissionForService_Disable == e_usbforService )) {												// 又は、ｻｰﾋﾞｽの設定が禁止の時.
	 	// USB接続状態フラグをFalse(使用不可)とする.
		m_bl_USBConnectionPermissionFlag = False;
	} else {
	 	// USB接続状態フラグをTrue(使用可)とする.
		m_bl_USBConnectionPermissionFlag = True;
	}
}
//================================================================================================.
// 概要    :M0B0021000_拡張サーバーからリストア／リストア履歴 : 表示部品のセットアップ.
//================================================================================================.
void PServiceExtServerRestoreHistory::setupGamen( short ss_option )
{
	Bool	bl_LEDFlg = False;												// スタートLED用のフラグ.
	uchar	uc_Cnt = 0;														// カウンタ用変数.
	ushort	us_CharNumber = 0;												// リストア結果の文字数カウンタ用.
	ushort	us_TextLen = 0;													// リストア結果の文字列長を格納.
	uchar	uc_commaCnt = 0;												// 何個目のカンマかを格納.
	ushort	us_StartCharNumber	= 0;										// 各格納用の文字列に入れ替えするための変数.
	char	sc_buf[PNLD_ExtServerRestoreResultLogMax + 1];					// 一時的に保存するバッファ.
	char	sc_LogTime[PNLD_RestoreExecuteResultTimeChar_Max];				// 時間用の配列.
	char	sc_LogResult[PNLD_RestoreExecuteResultResultChar_Max];			// 結果用の配列.

	const struct {
		PSelectButtonAdd*	Key;							// キー.
		PTextField*			TxtField_Time;					// テキスト.
		PTextField*			TxtField_Result;				// ナンバー.
	}
	ptr_RestoreHistoryList[PNLD_ExtServerRestoreDetailLog_MaxItem] = {
		{ &Key_ServiceExtSrvRestoreHistoryList1,	&Tfd_ServiceExtSrvRestoreHistoryDate1,	&Tfd_ServiceExtSrvRestoreHistoryResult1  },
		{ &Key_ServiceExtSrvRestoreHistoryList2,	&Tfd_ServiceExtSrvRestoreHistoryDate2,	&Tfd_ServiceExtSrvRestoreHistoryResult2  },
		{ &Key_ServiceExtSrvRestoreHistoryList3,	&Tfd_ServiceExtSrvRestoreHistoryDate3,	&Tfd_ServiceExtSrvRestoreHistoryResult3  },
		{ &Key_ServiceExtSrvRestoreHistoryList4,	&Tfd_ServiceExtSrvRestoreHistoryDate4,	&Tfd_ServiceExtSrvRestoreHistoryResult4  },
		{ &Key_ServiceExtSrvRestoreHistoryList5,	&Tfd_ServiceExtSrvRestoreHistoryDate5,	&Tfd_ServiceExtSrvRestoreHistoryResult5  },
		{ &Key_ServiceExtSrvRestoreHistoryList6,	&Tfd_ServiceExtSrvRestoreHistoryDate6,	&Tfd_ServiceExtSrvRestoreHistoryResult6  },
		{ &Key_ServiceExtSrvRestoreHistoryList7,	&Tfd_ServiceExtSrvRestoreHistoryDate7,	&Tfd_ServiceExtSrvRestoreHistoryResult7  },
		{ &Key_ServiceExtSrvRestoreHistoryList8,	&Tfd_ServiceExtSrvRestoreHistoryDate8,	&Tfd_ServiceExtSrvRestoreHistoryResult8  },
		{ &Key_ServiceExtSrvRestoreHistoryList9,	&Tfd_ServiceExtSrvRestoreHistoryDate9,	&Tfd_ServiceExtSrvRestoreHistoryResult9  },
		{ &Key_ServiceExtSrvRestoreHistoryList10,	&Tfd_ServiceExtSrvRestoreHistoryDate10,	&Tfd_ServiceExtSrvRestoreHistoryResult10 },
	};

	// 親クラスをコール.
	PServiceNoFunctionCodeCom::setupGamen(ss_option);
	APIC_UsbMemDeviceInfo* pc_UsbMemDeviceInfo = APIC_UsbMemDeviceInfo::newInstance();
	if( NULL == pc_UsbMemDeviceInfo ) {
// comment 2017/1/6 [IT5-4.0] WP-903 RQ-505_新詳細コード対応 日立 村上幸.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if ( NULL != pc_BFW_System ) {
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19006601014E5101 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}
	memset( sc_buf, '\0', sizeof( sc_buf ) );
	memset( sc_LogTime, '\0', sizeof( sc_LogTime ) );
	memset( sc_LogResult, '\0', sizeof( sc_LogResult ) );

// ﾘｽﾄｱ履歴キーの表示/非表示制御.
	if( 0 < m_us_RestoreLogTotal ){																				// ﾘｽﾄｱ履歴の総数が0より大きければ.
		Rbt_ServiceExtSrvRestoreHistoryList.showEnable( True );													// 全ﾘｽﾄｱ履歴キーを表示.
// comment 2016/8/29 [MAv4][RQ-505]リストア履歴がない場合のメッセージ表示 日立 田中.
		Txt_ServiceExtSrvRestoreHistoryNoneMessage.showEnable( False );											// ﾘｽﾄｱ履歴がありませんを非表示.
		// 各キーの表示/非表示及びテキスト領域へ文字列を投入する制御.
		for(uc_Cnt=0;uc_Cnt<PNLD_ExtServerRestoreDetailLog_MaxItem;uc_Cnt++) {									// 各キー分の表示非表示を実施.
			uc_commaCnt = 0;																					// 次の文字列に移動のため、カンマの位置を初期化.
			if( uc_Cnt < m_us_RestoreLogTotal ) {																// 取得したリストア履歴の総数を超えない場合.
				ptr_RestoreHistoryList[uc_Cnt].Key->showEnable( True );											// キーを表示.
				// ﾘｽﾄｱ結果の内容を下記.
				// 結果の表示を行う項目を"○"、表示に必要ない項目を"×".
				//    1: ログファイル名				×.
				//    2: 開始時間					○.
				//    3: 実施時間					×.
				//    4: 結果						○.
				//    5: 詳細コード					×.
				//    6: URL						×.
				//    7: ﾘｽﾄｱ対象ファイル			×.
				//    8: 文書ﾌｫｰﾏｯﾄ(なし/汎用/KM)	×.
				//    9: 汎用文書数					×.
				//   10: 成功数						×.
				//   11: 結果数						×.
				// 12～: ﾘｽﾄｱ対象(14項目)			×.
				memcpy( sc_buf, m_psc_RestoreLogResult[uc_Cnt], sizeof(sc_buf) );								// uc_Cnt番目のﾘｽﾄｱ結果ログの先頭ポインタを保存.
				us_TextLen = ( ushort )strlen( sc_buf );																	// uc_Cnt番目の文字列長を取得.
				// 文字列解析用の処理.
				for( us_CharNumber = 0; us_CharNumber < us_TextLen; us_CharNumber++ ) {							// 文字列長分ループ.
					if( ',' == sc_buf[us_CharNumber] ) {
						uc_commaCnt += 1;																				// カンマ用カウンタをインクリメント.
						sc_buf[us_CharNumber] = '\0';
						if( PNLD_RestoreExecuteResultlogTime == uc_commaCnt ) {											// 開始時間(2番目のカンマ)の場合.
							strncpy( sc_LogTime, &sc_buf[us_StartCharNumber], sizeof( sc_LogTime ) - 1  );				// 文字列の先頭からNULL終端までをコピー.
						} else if( PNLD_RestoreExecuteResultlogResult == uc_commaCnt ) {								// 結果(4番目のカンマ)の場合.
							strncpy( sc_LogResult, &sc_buf[us_StartCharNumber], sizeof( sc_LogResult ) - 1  );			// 文字列の先頭からNULL終端までをコピー.
							break;
						} else {}
						us_StartCharNumber = us_CharNumber + 1;															// 次の文字列の先頭位置を保存.
					}
				}
				// 解析を行った文字列を各パーツへ表示.
				ptr_RestoreHistoryList[uc_Cnt].Key->changeExternalText( ptr_RestoreHistoryList[uc_Cnt].TxtField_Time, (uchar*)sc_LogTime, sizeof( sc_LogTime ) );		// 開始時間用テキスト(左上側)のテキスト変更.
				ptr_RestoreHistoryList[uc_Cnt].Key->changeExternalText( ptr_RestoreHistoryList[uc_Cnt].TxtField_Result,(uchar*)sc_LogResult, sizeof( sc_LogResult ) );	// 結果用テキスト(右下)のテキスト変更.
			} else {
				ptr_RestoreHistoryList[uc_Cnt].Key->showEnable( False );										// キーを非表示.
			}
		}
		Rbt_ServiceExtSrvRestoreHistoryList.select( m_ss_select );												// ﾘｽﾄｱ履歴キーを選択状態を更新.
	} else {
		Rbt_ServiceExtSrvRestoreHistoryList.showEnable( False );												// 全ﾘｽﾄｱ履歴キーを非表示.
// comment 2016/8/29 [MAv4][RQ-505]リストア履歴がない場合のメッセージ表示 日立 田中.
		Txt_ServiceExtSrvRestoreHistoryNoneMessage.showEnable( True );											// ﾘｽﾄｱ履歴がありませんを表示.
	}
// スタートLEDの表示状態(実行中は強制で赤点灯).
	if( ( -1 != m_ss_select )																					// 何かしらキーを選択.
	 && ( TYPD_UsbMemStatusConnect == pc_UsbMemDeviceInfo->getStatus() ) ) {									// 且つUSB装着時.
	 	bl_LEDFlg = True;																						// スタートLEDを青に点灯.
	} else {
	 	bl_LEDFlg = False;																						// スタートLEDを赤に点灯.
	}

// comment 2016/10/11 [IT5-4.0][WP747]USB接続許可設定が"禁止"の時は、何も表示させない 日立 村上.
	if( False == m_bl_USBConnectionPermissionFlag ) {
		Gra_ServiceExtSrvRestoreHistoryCSVOutPutBox.showEnable( False );											// CSV出力結果枠を非表示.
		Txt_ServiceExtSrvRestoreHistorySubTitleCSVOutPut.showEnable( False );										// タイトル：CSV出力結果を非表示.
		Txt_ServiceExtSrvRestoreHistoryCSVOutPutSlash.showEnable( False );											// 「／」「＼」を非表示.
		Txt_ServiceExtSrvRestoreHistoryCSVOutPutResult.showEnable( False );											// 結果を非表示.
		Txt_ServiceExtSrvRestoreHistoryCSVOutPutStatus.showEnable( False );											// 状態に何も表示させない.
		bl_LEDFlg = False;																							// スタートLEDは必ず赤に点灯.
	} else {
// USB保存処理の状態の表示/非表示制御.
		switch( m_uc_USBStatus ) {
			case PNLD_ExtServerRestoreDetailLogToUSB_None:															// 未実施.
				Txt_ServiceExtSrvRestoreHistoryCSVOutPutSlash.showEnable( False );									// 「／」「＼」を非表示.
				Txt_ServiceExtSrvRestoreHistoryCSVOutPutResult.showEnable( False );									// 結果を非表示.
				if( TYPD_UsbMemStatusConnect == pc_UsbMemDeviceInfo->getStatus() ) {								// USB装着時.
					Txt_ServiceExtSrvRestoreHistoryCSVOutPutStatus.changeText( s_Space1 );							// 状態に何も表示させない(スペースを表示).
				} else {
					Txt_ServiceExtSrvRestoreHistoryCSVOutPutStatus.changeText( s_ITMServiceUSBN_a );				// 状態の表示内容を「USB NG」に変更.
				}
				break;
			case PNLD_ExtServerRestoreDetailLogToUSB_Running:														// 実行中.
				Txt_ServiceExtSrvRestoreHistoryCSVOutPutResult.showEnable( False );									// 結果を非表示.
				Txt_ServiceExtSrvRestoreHistoryCSVOutPutSlash.showEnable( True );									// 「／」「＼」を表示.
				Txt_ServiceExtSrvRestoreHistoryCSVOutPutStatus.changeText( s_ITMServiceSaving );					// 状態の表示内容を「保存中」に変更.
				// スタートLEDの表示状態(実行中は強制で赤点灯).
				bl_LEDFlg = False;																					// スタートLEDを赤に点灯.
				// 「／」「＼」の切り替え制御.
				Txt_ServiceExtSrvRestoreHistoryCSVOutPutSlash.changeText( True == m_bl_RunningToggle ? s_EXPSlash : s_EXPBackslash );	// 「／」「＼」を交互に表示.
				m_bl_RunningToggle = ( ( True == m_bl_RunningToggle ) ? False : True );													// 切り替えするためにTrue→False→Trueと変更.
				break;
			case PNLD_ExtServerRestoreDetailLogToUSB_OK:															// 成功.
				Txt_ServiceExtSrvRestoreHistoryCSVOutPutSlash.showEnable( False );									// 「／」「＼」を非表示.
				Txt_ServiceExtSrvRestoreHistoryCSVOutPutResult.showEnable( True );									// 結果を表示.
				Txt_ServiceExtSrvRestoreHistoryCSVOutPutStatus.changeText( s_ServiceMemoryHDDAdjustResult );		// 状態の表示内容を「結果」に変更.
				Txt_ServiceExtSrvRestoreHistoryCSVOutPutResult.changeText( s_ServiceMemoryCheck_OK );				// 結果を表示.
				break;
			case PNLD_ExtServerRestoreDetailLogToUSB_NG:															// 失敗.
				Txt_ServiceExtSrvRestoreHistoryCSVOutPutSlash.showEnable( False );									// 「／」「＼」を非表示.
				Txt_ServiceExtSrvRestoreHistoryCSVOutPutResult.showEnable( True );									// 結果を表示.
				Txt_ServiceExtSrvRestoreHistoryCSVOutPutStatus.changeText( s_ServiceMemoryHDDAdjustResult );		// 状態の表示内容を「結果」に変更.
				Txt_ServiceExtSrvRestoreHistoryCSVOutPutResult.changeText( s_ServiceMemoryCheck_NG );				// 結果を表示.
				break;
			default:	break;
		}
	}
	printLEDControl( bl_LEDFlg );																				// 状態に応じて、スタートLEDを点灯.
}
//================================================================================================.
// 概要    :M0B0021000_拡張サーバーからリストア／リストア履歴 : OKキー押下処理.
//================================================================================================.
void PServiceExtServerRestoreHistory::procOk( uchar uc_option )
{
	if( PNLD_ExtServerRestoreDetailLogToUSB_Running == m_uc_USBStatus ) {
	 	// 拒否音を鳴動.
		setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}
	nextGamen = &gp_ServiceDataBackupServerRestoreMenu;									// K4B0024000_データバックアップ／サーバーからリストア.
}
//================================================================================================.
// 概要    :M0B0021000_拡張サーバーからリストア／リストア履歴 : キー押下処理.
//================================================================================================.
void PServiceExtServerRestoreHistory::procButtonOn( uchar uc_option )
{
	if( PNLD_ExtServerRestoreDetailLogToUSB_Running == m_uc_USBStatus ) {
	 	// 拒否音を鳴動.
		setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}
	
	short	ss_select_backup = m_ss_select;		// 選択済みのキー種別を保存.

	switch( uc_option ) {
		case BTNID_ServiceExtSrvRestoreHistoryList1:	m_ss_select = 0;	break;		// 1番目のキー(左上からN並び).
		case BTNID_ServiceExtSrvRestoreHistoryList2:	m_ss_select = 1;	break;		// 2番目のキー.
		case BTNID_ServiceExtSrvRestoreHistoryList3:	m_ss_select = 2;	break;		// 3番目のキー.
		case BTNID_ServiceExtSrvRestoreHistoryList4:	m_ss_select = 3;	break;		// 4番目のキー.
		case BTNID_ServiceExtSrvRestoreHistoryList5:	m_ss_select = 4;	break;		// 5番目のキー.
		case BTNID_ServiceExtSrvRestoreHistoryList6:	m_ss_select = 5;	break;		// 6番目のキー.
		case BTNID_ServiceExtSrvRestoreHistoryList7:	m_ss_select = 6;	break;		// 7番目のキー.
		case BTNID_ServiceExtSrvRestoreHistoryList8:	m_ss_select = 7;	break;		// 8番目のキー.
		case BTNID_ServiceExtSrvRestoreHistoryList9:	m_ss_select = 8;	break;		// 9番目のキー.
		case BTNID_ServiceExtSrvRestoreHistoryList10:	m_ss_select = 9;	break;		// 10番目のキー.
		default:	break;
	}
	if( ss_select_backup == m_ss_select ) {
		setBuzzerType( PCGE_BuzzerType_InputNg );	// キー種別が同じ(キー2度押し)の場合、拒否音を鳴動.
	}

	setupGamen(uc_option);
}
//================================================================================================.
// 概要    :M0B0021000_拡張サーバーからリストア／リストア履歴 : リセットキー押下処理.
//================================================================================================.
void PServiceExtServerRestoreHistory::procReset( uchar uc_option )
{
	if( PNLD_ExtServerRestoreDetailLogToUSB_Running == m_uc_USBStatus ) {
	 	// 拒否音を鳴動.
		setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}
	// 親クラスをコール.
	PServiceNoFunctionCodeCom::procReset(uc_option);
}
//================================================================================================.
// 概要    :M0B0021000_拡張サーバーからリストア／リストア履歴 : ラインキー押下処理.
//================================================================================================.
void PServiceExtServerRestoreHistory::procGoToMag( uchar uc_option )
{
	if( PNLD_ExtServerRestoreDetailLogToUSB_Running == m_uc_USBStatus ) {
	 	// 拒否音を鳴動.
		setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}
	// 親クラスをコール.
	PServiceNoFunctionCodeCom::procGoToMag(uc_option);

}
//================================================================================================.
// 概要    :M0B0021000_拡張サーバーからリストア／リストア履歴 : コールバック通知.
//================================================================================================.
void PServiceExtServerRestoreHistory::procCallBack( TYPE_PNL_CallBack e_option )
{
	if( TYPE_PNL_CallBack_ExtRestoreUSBOutputEnd == e_option ) {
		if( True == m_bl_USBResult ) {												// ﾘｽﾄｱの出力結果を判断.
			m_uc_USBStatus = PNLD_ExtServerRestoreDetailLogToUSB_OK;			// 成功であれば、状態をOKに変更.
		} else {
			m_uc_USBStatus = PNLD_ExtServerRestoreDetailLogToUSB_NG;			// 失敗であれば、状態をNGに変更.
		}
	}
}
//================================================================================================.
// 概要    :M0B0021000_拡張サーバーからリストア／リストア履歴 : スタートキー押下.
//================================================================================================.
void PServiceExtServerRestoreHistory::procStart( uchar uc_option )
{
// comment 2016/10/11 [IT5-4.0][WP747]USB接続許可設定が"禁止"の時、スタートキー押下を禁止とする 日立 村上.
	if( False == m_bl_USBConnectionPermissionFlag ) {							// USB接続許可設定が"禁止"の時.
	 	// 拒否音を鳴動.
		setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}

	if( PNLD_ExtServerRestoreDetailLogToUSB_Running == m_uc_USBStatus ) {
	 	// 拒否音を鳴動.
		setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}
	Bool bl_ret = True;
	APIC_BackupRestore *pc_BackupRestore = APIC_BackupRestore::newInstance();
	if( NULL == pc_BackupRestore ) {
// comment 2017/1/6 [IT5-4.0] WP-903 RQ-505_新詳細コード対応 日立 村上幸.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if ( NULL != pc_BFW_System ) {
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19002801014E5201 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" ); 
		return;
	}
	APIC_UsbMemDeviceInfo* pc_UsbMemDeviceInfo = APIC_UsbMemDeviceInfo::newInstance();
	if( NULL == pc_UsbMemDeviceInfo ) {
// comment 2017/1/6 [IT5-4.0] WP-903 RQ-505_新詳細コード対応 日立 村上幸.
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
//		if ( NULL != pc_BFW_System ) {
//			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19002801014E5301 );
//		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}
	if( ( -1 != m_ss_select )													// ﾘｽﾄｱ履歴キーを選択している状態.
	 && ( TYPD_UsbMemStatusConnect == pc_UsbMemDeviceInfo->getStatus() ) ) {	// 且つUSB接続状態.
		bl_ret = pc_BackupRestore->saveExtServerRestoreDetailLogToUSB( m_ss_select, ans_ExtServerRestoreeDetailLogToUSB );
		if( bl_ret == False ) {
			// 異常ルート.
			m_uc_USBStatus = PNLD_ExtServerRestoreDetailLogToUSB_NG;			// 異常ルートの場合はNGに変更.
		} else {
			m_uc_USBStatus = PNLD_ExtServerRestoreDetailLogToUSB_Running;		// USB保存処理の状態を(実行中に)更新.
		}
	} else {
	 	// 拒否音を鳴動.
		setBuzzerType( PCGE_BuzzerType_InputNg );
	}
}
//================================================================================================.
// 概要    :M0B0020800_拡張サーバーからリストア／リストア設定／リストア実行 : コールバック応答.
//================================================================================================.
void PServiceExtServerRestoreHistory::ans_ExtServerRestoreeDetailLogToUSB( Bool bl_Result)
{
	m_bl_USBResult = bl_Result;
	CallBackIndi( TYPE_PNL_CallBack_ExtRestoreUSBOutputEnd );				// コールバック通知.
}

