//================================================================================================.
// 概要    :zcB0011000_CS Remote Care／メニュー : 表示部品のセットアップ.
//================================================================================================.
void PServiceCSRemoteCareMenu::setupGamen( short ss_option )
{
	PServiceNoFunctionCodeCom::setupGamen( ss_option );	// 親クラスをコール.

	APIC_Rds*			pc_Rds = PnlComGetRds();
	TYPS_RdsCommResult	st_RdsCommResult;				// RDS通信結果（構造体）.
	uchar				uc_RdsStatNo[5] = {0};
	pc_Rds->getRdsCommResult( &st_RdsCommResult.e_RdsDispCode, &st_RdsCommResult.ul_StatNo );		// RDSの通信結果を受け取る.
// comment 2018/03/22 静的解析指摘修正 日立 田中.
//	snprintf( reinterpret_cast<char*>(uc_RdsStatNo), sizeof( uc_RdsStatNo ), "%04lX", st_RdsCommResult.ul_StatNo );
	snprintf( reinterpret_cast<char*>(uc_RdsStatNo), sizeof( uc_RdsStatNo ), "%04X", st_RdsCommResult.ul_StatNo );

	Bool	bl_showStatNo = True;						// ステータスNo.を表示するか否かのフラグ.
	if( 0 == st_RdsCommResult.ul_StatNo ) {				// ステータスNo.が0の時は非表示.
		bl_showStatNo = False;
	} else {
		bl_showStatNo = True;
	}
	// メッセージ部に通信結果内容を表示する.
	for( ushort i = 0; i < us_dtResultCodeSize; i++ ) {
		if( st_RdsCommResult.e_RdsDispCode == tbl_dtResultCode[ i ].code ) {
			Txt_SRdsMessage.changeText( tbl_dtResultCode[ i ].msg );	// RDS通信結果文字列表示.
			Tfd_SRdsStatusNo.changeASCIIText( uc_RdsStatNo );			// 通信結果ステータスNo.
			Tfd_SRdsStatusNo.showEnable( bl_showStatNo );				// 通信結果ステータスNo.表示状態.
			break;
		}
	}

	// ｻｰﾊﾞｰ設定キー 表示/非表示判定.
	uchar	uc_ServiceID[ DEF_SizeRDServiceID + 1 ];
	clearString( uc_ServiceID, DEF_SizeRDServiceID );			 		// IDコードクリア(ローカル値).
	PnlComGetRdsSetting()->getServiceID( uc_ServiceID );				// IDコード取得.
	Num_CSRemoteCareMenuIDCode.changeASCIIText( uc_ServiceID );			// IDコード表示.

	TYPE_RdsMode	e_RdsMode = TYPE_RdsModeTelephony;
	e_RdsMode = PnlComGetRdsSetting()->getRdsMode();					// 現在のシステム選択値を取得する.
	// KMRDS/システム選択ボタン・選択状態.
	switch( e_RdsMode ) {
		case TYPE_RdsModeMail:				// E-mail選択時.
			Txt_CSRemoteCareSystemSettingType.changeText( s_KEYServiceCSRCE2EMail1 );
			Key_GoToServerSettings.showEnable( True );	// 表示・ｻｰﾊﾞｰ設定キー.
			break;
		case TYPE_RdsModeMailForOne:		// E-mail2選択時.
			Txt_CSRemoteCareSystemSettingType.changeText( s_KEYServiceCSRCE2EMail2 );
			Key_GoToServerSettings.showEnable( True );	// 表示・ｻｰﾊﾞｰ設定キー.
			break;
		case TYPE_RdsModeHttp:				// http1,2選択時.
			if( True == PnlComGetRdsSetting()->getCsrcCommunicationMethod() ) {	// 双方向(True)の場合、http1.
				Txt_CSRemoteCareSystemSettingType.changeText( s_KEYServiceHttp1 );
			} else {	// 片方向(False)の場合、 http2.
				Txt_CSRemoteCareSystemSettingType.changeText( s_KEYServiceHttp2 );
			}
			Key_GoToServerSettings.showEnable( True );	// 表示・ｻｰﾊﾞｰ設定キー.
			break;
		case TYPE_RdsModeTelephony:			// モデム選択時.
			Txt_CSRemoteCareSystemSettingType.changeText( s_SRdsSystemModem );
			Key_GoToServerSettings.showEnable( False );	// 非表示・ｻｰﾊﾞｰ設定キー.
			break;
		case TYPE_RdsModeFax:				// Fax選択時.
			Txt_CSRemoteCareSystemSettingType.changeText( s_SRdsSystemFax );
			Key_GoToServerSettings.showEnable( False );	// 非表示・ｻｰﾊﾞｰ設定キー.
			break;
		default:							// 未選択.
			Txt_CSRemoteCareSystemSettingType.showEnable( False );
			Key_GoToServerSettings.showEnable( False );	// 非表示・ｻｰﾊﾞｰ設定キー.
			break;
	}
	// ﾒﾝﾃﾅﾝｽ開始キー 表示/非表示判定.
	TYPE_HostStat 	e_HostStat = PnlComGetRdsSetting()->getHostStat();  // 登録状態を取得する.
	// 管理システム統合化開発 要求仕様2-b 2021/03/03 Sky 大橋 START.
	// CSRAデータ送付設定情報を取得する.
	// CSRA双方向.
	TYPS_CSRASetting s_CsraSetting = {};
	PnlComGetCSRASetting()->getCSRASetting( &s_CsraSetting );
	// CSRA片方向.
	TYPS_CSRASetting s_OneWayCsraSetting = {};
	PnlComGetCSRASetting()->getCSRASetting( &s_OneWayCsraSetting, TYPE_CSRASettingComMode_OneWay );
	// 管理システム統合化開発 要求仕様2-b 2021/03/03 Sky 大橋 END.
	if( ( False == pc_Rds->isNowTrans( TYPE_RdsTrgKindIni ) )
	    && ( ( e_HostStat == TYPE_HostStatRgst )  						// 初期発信終了かつ登録完了.
		// 管理システム統合化開発 要求仕様2-b 2021/03/03 Sky 大橋 START.
		||   ( True == s_CsraSetting.m_b_Enable )						// 初期発信終了かつCSRA双方向有効.
		||   ( True == s_OneWayCsraSetting.m_b_Enable ) ) ) {			// 初期発信終了かつCSRA片方向有効.
		// 管理システム統合化開発 要求仕様2-b 2021/03/03 Sky 大橋 END.
		Key_GoToMaintenanceDefaultSettings.showEnable( False );			// ﾒﾝﾃﾅﾝｽ/初期設定非表示.
		Key_GoToMaintenanceStart.showEnable( True );					// ﾒﾝﾃﾅﾝｽ開始キー表示.
	} else {
		Key_GoToMaintenanceDefaultSettings.showEnable( True );			// ﾒﾝﾃﾅﾝｽ/初期設定表示.
		Key_GoToMaintenanceStart.showEnable( False );					// ﾒﾝﾃﾅﾝｽ開始キー非表示.
	}
	if( True == PnlComGetRdsSetting()->getMaintStat() ) {				// ﾒﾝﾃﾅﾝｽ中.
		Grp_ServiceCSRemoteCareEndTime.showEnable( True );
		Key_GoToMaintenanceStart.changeText( s_RDModeMaintenanceEnd );
		Num_CSRemoteCareMenuIDCode.showEnable( True );
		Key_GoToDetailSettings.showEnable( True );
		TYPC_Time c_Time;
		PnlComGetRdsSetting()->getMaintEndScheduleTime( &c_Time );
		Nfd_CSRemoteCareHour = c_Time.sc_Hour;
		Nfd_CSRemoteCareMinute = c_Time.sc_Minute;
	} else {
		Grp_ServiceCSRemoteCareEndTime.showEnable( False );
		Key_GoToMaintenanceStart.changeText( s_KEYMaintenanceStart );
		Num_CSRemoteCareMenuIDCode.showEnable( False );
		Key_GoToDetailSettings.showEnable( False );
	}
}
//================================================================================================.
// 概要    :zcB0011000_CS Remote Care／メニュー : OKキー押下処理.
//================================================================================================.
void PServiceCSRemoteCareMenu::procOk( uchar uc_option )
{
	nextGamen = &gp_ServiceCSRemoteMenu;			// zcB0010000_CS Remote／メニュー.
}
//================================================================================================.
// 概要    :zcB0011000_CS Remote Care／メニュー : 画面遷移処理.
//================================================================================================.
void PServiceCSRemoteCareMenu::procGoToPage( uchar uc_option )
{
	TYPE_RdsMode e_RdsMode = PnlComGetRdsSetting()->getRdsMode();	// 現在のシステム選択値を取得する.
	switch( uc_option ) {
		case  BTNID_KEY_MaintenanceDefaultSettings:	// ﾒﾝﾃﾅﾝｽ/初期設定.
			nextGamen = &gp_ServiceRDModeSystem;	// 93500_CS Remote Care／ID入力.
			break;
		case  BTNID_KEY_ServerSettings:				// ｻｰﾊﾞｰ設定.
			switch( e_RdsMode ) {
				case TYPE_RdsModeMail:				// E-mail1選択時.
				case TYPE_RdsModeMailForOne:		// E-mail2選択時.
					PServiceRDModeNetworkcom::ep_RDModeNowGamen = EP_RDModeNetworkGamen_POP3Server;
					nextGamen = &gp_ServiceRDModeNtPOP3Server;	// 93532_CS Remote Care／受信用サーバ／POP3サーバ.
					break;
				case TYPE_RdsModeHttp:				// Http選択時.
					PServiceRDModeNetworkcom::ep_RDModeNowGamen = EP_RDModeNetworkGamen_HTTPUrlAddress;
					nextGamen = &gp_ServiceRDModeNtHttpUrlAdd;	// 50B00100_CS Remote Care／httpサーバー設定URLアドレス.
					break;
				default:break;
			}
			break;
		case  BTNID_KEY_ProductAuthSettings:		// ﾌﾟﾛﾀﾞｸﾄ認証設定.
			nextGamen = &gp_ServiceRDModePcSetting;	// 80B93500_CS Remote Care／ﾌﾟﾛﾀﾞｸﾄ認証設定／ﾌﾟﾛﾀﾞｸﾄ認証.
			break;
		case  BTNID_KEY_MaintenanceStart:			// ﾒﾝﾃﾅﾝｽ開始.
			if( True == PnlComGetRdsSetting()->getMaintStat() ) {		// ﾒﾝﾃﾅﾝｽ中.
				PnlComGetRds()->indTrg( TYPE_RdsTrgKindMnteEnd );		// メンテナンス終了メッセージ発信.
				nextGamen = &gp_ServiceMenu;							// サービスメニュー.
			} else {
				nextGamen = &gp_ServiceCSRemoteCaremMaintenanceStart;	// 80B93680_CS Remote Care／ﾒﾝﾃﾅﾝｽ時間設定.
			}
			break;
		case  BTNID_KEY_DetailSettings:				// 詳細設定.
			switch( e_RdsMode ) {
				case TYPE_RdsModeMail:			nextGamen = &gp_ServiceRDModeDTSettingE1;		break;	// 基本設定(e-mail)両方向通信対応.
				case TYPE_RdsModeTelephony:	// モデムモード.↓
				case TYPE_RdsModeFax:			nextGamen = &gp_ServiceRDModeDTSettingDtCtID;	break;	// 基本設定(モデム/Fax).
				case TYPE_RdsModeMailForOne:	nextGamen = &gp_ServiceRDModeDTSettingE2;		break;	// 基本設定(e-mail2).
				case TYPE_RdsModeHttp:			nextGamen = &gp_ServiceRDModeDTSettingHttpCtID;	break;	// 基本設定(http).
				default: break;
			}
			break;
		case  BTNID_KEY_ImpExpSettings:				// ｴｸｽﾎﾟｰﾄ/ｲﾝﾎﾟｰﾄ設定.
			nextGamen = &gp_ServiceCSRemoteCareForImportExportWebDavUrlAdd;	// 80B93600_CS Remote Care／ｴｸｽﾎﾟｰﾄｲﾝﾎﾟｰﾄ設定／URLアドレス.
			break;
		case  BTNID_KEY_AutoInitDialSettings:		// 自動初期発信設定.
			nextGamen = &gp_ServiceCSRCAutoInitDial;	// K4B0018100_CS Remote Care／自動初期発信設定.
			break;	
		default: break;
	}
}

//================================================================================================.
// 概要    :zcB0012000_CS Remote Analysis／メニュー : コンストラクタ.
//================================================================================================.
PServiceCSRemoteAnalysisMenu::PServiceCSRemoteAnalysisMenu( PDisplayParts** partsTable, short partsNumber, Bool isNoWarning )
	 : PServiceNoFunctionCodeCom( partsTable, partsNumber, isNoWarning )
{
	m_bl_ServiceCSRemoteAnalysisEnable = False;
// comment 2017/06/28 日立 田中 [MAv5-1][RQ-710][WP110] CSRA接続 通信履歴.
	m_bl_USBConnectionPermissionFlag = False;
}
//================================================================================================.
// 概要    :zcB0012000_CS Remote Analysis／メニュー : 画面開始処理.
//================================================================================================.
void PServiceCSRemoteAnalysisMenu::startGamen()
{
	PServiceNoFunctionCodeCom::startGamen();	// 親クラスをコール.
	TYPS_CSRASetting st_CsraSetting;
	APIC_CSRASetting *pc_CSRASetting = APIC_CSRASetting::newInstance();
	if( NULL == pc_CSRASetting ) {
		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
		if( NULL != pc_BFW_System ) {
			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19006501004E0001 );
		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" ); 
		return;
	}
	memset( &st_CsraSetting , 0x00, sizeof( st_CsraSetting ) );
	// CSRAデータ送付設定情報 取得.
	pc_CSRASetting->getCSRASetting( &st_CsraSetting );

// comment 2020/09/29 HCL_Hemachander [RQ-776] Addition of CWH 1-way communication method.
		// CSRAデータ送付機能の使用設定を保持.
// comment 2020/10/09 HCL_Hemachander [RQ-776] Function Version Check Removal.
//	if( True == PLBC_FuncVersionCheck::isOK_IT6_Type2() ) {

		TYPS_CSRASetting st_CsraOneWaySetting;
		pc_CSRASetting->getCSRASetting( &st_CsraOneWaySetting , TYPE_CSRASettingComMode_OneWay);
// Comment 2021/10/14 FPT-LinhNV46【IT6_2.2_MR1】【制御構成変更_No.38】RQ-776 CWH 1-way通信　BCN対応.
		if(( TYPE_CSRASettingComMode_OneWay    == pc_CSRASetting->getCSRASettingComMode() ) ||
		   ( TYPE_CSRASettingComMode_OneWay_CN == pc_CSRASetting->getCSRASettingComMode() )) {
			m_bl_ServiceCSRemoteAnalysisEnable = st_CsraOneWaySetting.m_b_Enable;
		}else if( TYPE_CSRASettingComMode_TwoWay == pc_CSRASetting->getCSRASettingComMode() ) {
			m_bl_ServiceCSRemoteAnalysisEnable = st_CsraSetting.m_b_Enable;
// comment 2020/10/06 HCL_Hemachander [OP_BTS-28184] Reset Member variable in CSRemote Analysis Menu.
//		}
		} else {
			m_bl_ServiceCSRemoteAnalysisEnable = False;
		}
//	}else{
//			m_bl_ServiceCSRemoteAnalysisEnable = st_CsraSetting.m_b_Enable;
//	}

// comment 2017/06/28 日立 田中 [MAv5-1][RQ-710][WP110] CSRA接続 通信履歴.
	PNLC_USBConnectionPermission c_UsbPermission;
	PNLE_EnableUSBConnectionPermissionForAll e_UsbAll = c_UsbPermission.getEnableUSBConnectionPermissionForAll();					// 全使用者(ﾕｰｻﾞｰ/ｻｰﾋﾞｽ/管理者)の許可/禁止設定を取得.
	PNLE_EnableUSBConnectionPermissionForService e_usbforService = c_UsbPermission.getEnableUSBConnectionPermissionForService();	// ｻｰﾋﾞｽの許可/禁止設定を取得.
	if( ( PNLE_EnableUSBConnectionPermissionForAll_Disable == e_UsbAll )															// 全使用者の設定が禁止の時.
	 || ( PNLE_EnableUSBConnectionPermissionForService_Disable == e_usbforService ) ) {												// 又は、ｻｰﾋﾞｽの設定が禁止の時.
	 	// USB接続許可状態フラグをFalse(禁止)とする.
		m_bl_USBConnectionPermissionFlag = False;
	} else {
	 	// USB接続許可状態フラグをTrue(許可)とする.
		m_bl_USBConnectionPermissionFlag = True;
	}
}
//================================================================================================.
// 概要    :zcB0012000_CS Remote Analysis／メニュー : 表示部品のセットアップ.
//================================================================================================.
void PServiceCSRemoteAnalysisMenu::setupGamen( short ss_option )
{
	PServiceNoFunctionCodeCom::setupGamen( ss_option );	// 親クラスをコール.
	// 機能設定が「使用する」の場合.
	if( True == m_bl_ServiceCSRemoteAnalysisEnable ) {
		// 送信設定キー表示.
		Key_GoToServiceCSRemoteAnalysisSendSetting.showEnable( True );
// comment 2017/06/28 日立 田中 [MAv5-1][RQ-710][WP110] CSRA接続 通信履歴.
		if( ( False == m_bl_USBConnectionPermissionFlag ) || ( True == PnlComGetSystemSetting()->getSecurityLevelUpOn() ) ) {
			// USB接続許可設定が「禁止」または、セキュリティ強化モード「ON」の場合.
			// 通信履歴出力キー非表示.
			Key_GoToServiceCSRemoteAnalysisHistoryOutput.showEnable( False );
		} else {
			// 通信履歴出力キー表示.
			Key_GoToServiceCSRemoteAnalysisHistoryOutput.showEnable( True );
		}
	} else {
		// 送信設定キー非表示.
		Key_GoToServiceCSRemoteAnalysisSendSetting.showEnable( False );
		// 通信履歴出力キー非表示.
		Key_GoToServiceCSRemoteAnalysisHistoryOutput.showEnable( False );
	}
}
//================================================================================================.
// 概要    :zcB0012000_CS Remote Analysis／メニュー : OKキー押下処理.
//================================================================================================.
void PServiceCSRemoteAnalysisMenu::procOk( uchar uc_option )
{
	nextGamen = &gp_ServiceCSRemoteMenu;			// zcB0010000_CS Remote／メニュー.
}
//================================================================================================.
// 概要    :zcB0012000_CS Remote Analysis／メニュー : 画面遷移処理.
//================================================================================================.
void PServiceCSRemoteAnalysisMenu::procGoToPage( uchar uc_option )
{
// comment 2020/09/22 HCL_Sowndarya [RQ-776] Addition of CWH 1-way communication method.
	APIC_CSRASetting *pc_CSRASetting = APIC_CSRASetting::newInstance();
	if( NULL == pc_CSRASetting ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" ); 
		return;
	}
	switch( uc_option ) {
		case BTNID_GOTO_ServiceCSRemoteAnalysis_FuncSetting:				// 機能設定.
			gp_ServiceCSRemoteAnalysisEnableSetting.setFromMenuFlg( True );
			nextGamen = &gp_ServiceCSRemoteAnalysisEnableSetting;			// zcB0012100_CS Remote Analysis／機能設定.
			break;
		case BTNID_GOTO_ServiceCSRemoteAnalysis_SendSetting:				// 送信設定.
// comment 2020/10/09 HCL_Hemachander [RQ-776] Function Version Check Removal.
// comment 2020/09/22 HCL_Sowndarya [RQ-776] Addition of CWH 1-way communication method.
// comment 2020/10/06 HCL_Hemachander [OP_BTS-28184] Adding Function Version Check.
//			if( TYPE_CSRASettingComMode_OneWay == pc_CSRASetting->getCSRASettingComMode()) {
//			if( ( True == PLBC_FuncVersionCheck::isOK_IT6_Type2() )
//				&& (TYPE_CSRASettingComMode_OneWay == pc_CSRASetting->getCSRASettingComMode() ) ){
// Comment 2021/10/14 FPT-LinhNV46【IT6_2.2_MR1】【制御構成変更_No.38】RQ-776 CWH 1-way通信　BCN対応.
			if( TYPE_CSRASettingComMode_OneWay == pc_CSRASetting->getCSRASettingComMode()
				|| TYPE_CSRASettingComMode_OneWay_CN == pc_CSRASetting->getCSRASettingComMode() ) {
				gp_ServiceCSRemoteAnalysisSendScheduleSetting.setFromMenuFlg( True );
   				nextGamen = &gp_ServiceCSRemoteAnalysisSendScheduleSetting;  //zcB0012210_CS Remote Analysis／送信設定／スケジュール設定.
			} else {
				gp_ServiceCSRemoteAnalysisSendScheduleUpdate.setFromMenuFlg( True );
				nextGamen = &gp_ServiceCSRemoteAnalysisSendScheduleUpdate;		// zcB0012200_CS Remote Analysis／送信設定／スケジュール更新.
			}
			break;
// comment 2017/06/28 日立 田中 [MAv5-1][RQ-710][WP110] CSRA接続 通信履歴.
		case BTNID_GOTO_ServiceCSRemoteAnalysis_HistoryOutput:				// 通信履歴出力.
			nextGamen = &gp_ServiceCSRemoteAnalysisConnectionHistoryOutput;	// zcB0012300_CS Remote Analysis／通信履歴出力.
			break;
		default: break;
	}
}

