//================================================================================================.
void PServiceCSRemoteAnalysisSettingInfo::clearCSRemoteAnalysisFuncSetting()
{
	m_bl_CSRemoteAnalysisEnable = False;						// 機能設定.
	memset( m_sc_UrlAdd,	'\0',	sizeof(m_sc_UrlAdd) );		// ｻｰﾊﾞｰ設定_URLｱﾄﾞﾚｽ.
	memset( m_sc_Account,	'\0',	sizeof(m_sc_Account) );		// ｻｰﾊﾞｰ設定_ｱｶｳﾝﾄ.
	memset( m_sc_Password,	'\0',	sizeof(m_sc_Password) );	// ｻｰﾊﾞｰ設定_ﾊﾟｽﾜｰﾄﾞ.
	m_us_PortNumber = 0;										// ｻｰﾊﾞｰ設定_ﾎﾟｰﾄ番号.
// comment 2017/06/12 [MAv5-1]RQ-710 CSRA接続機能追加 日立 森本郁.
	m_us_SalesCompanyCode = 0;									// 販社ｺｰﾄﾞ.
// comment 2020/09/29 HCL_Hemachander [RQ-776] Addition of CWH 1-way communication method.
	m_e_CSRemoteAnalysisEnable = PNLE_CSRADisable;						// 機能設定.
	memset( &m_st_CsraSettingOneWay , 0x00, sizeof( m_st_CsraSettingOneWay ) );
	memset( &m_st_CSRASendInfoOneWay , 0x00, sizeof( m_st_CSRASendInfoOneWay) );
}
//================================================================================================.
// 概要    :共通_CS Remote Analysis設定データクラス : 送信設定の初期化処理.
//================================================================================================.
void PServiceCSRemoteAnalysisSettingInfo::clearCSRemoteAnalysisSendSetting()
{
	Bool bl_SendingOKPeriodInit[TYPD_CSRAPrecheck_TimePeriodNum] = { False, False, False, False, False, False };
	
	m_bl_SettingOverwrite		= True;										// 上書き可否設定.
	m_uc_CycleDay				= TYPD_CSRASetting_CycleDay_Min;			// ｽｹｼﾞｭｰﾙ1_日周期_日.
	m_e_CycleWday				= TYPE_CSRAPrecheckCycleWdat_Sun;			// ｽｹｼﾞｭｰﾙ2(毎月)_曜日指定.
	m_uc_CycleMonth				= TYPD_CSRASetting_CycleMonth_Min;			// ｽｹｼﾞｭｰﾙ3(毎月)_日付指定.
	m_e_PrecheckPeriodSetting	= TYPE_CSRAPrecheckPeriodSetting_Period;	// 時間枠/時刻選択設定.
	m_uc_PrecheckTime_Hour		= 0;										// 時刻指定_時刻_時.
	m_uc_PrecheckTime_Minute	= 0;										// 時刻指定_時刻_分.
	m_us_TimeoutSetting			= TYPD_CSRASetting_Timeout_Min;				// 送信タイムアウト設定.
	memcpy( m_bl_SendingOKPeriod, bl_SendingOKPeriodInit, sizeof( m_bl_SendingOKPeriod ) );		// 各時間枠発信可否.
// comment 2020/09/29 HCL_Hemachander [RQ-776] Addition of CWH 1-way communication method.
	memset( &m_st_CsraSettingOneWay , 0x00, sizeof( m_st_CsraSettingOneWay ) );
}
//================================================================================================.
// 概要    :共通_CS Remote Analysis設定データクラス : 機能設定の一括取得処理.
//================================================================================================.
void PServiceCSRemoteAnalysisSettingInfo::loadCSRemoteAnalysisFuncSetting()
{
	TYPS_CSRASetting			st_CsraSetting;
	TYPS_CSRAPrecheckServerInfo	st_PrecheckServerInfo;
	APIC_CSRASetting *pc_CSRASetting = APIC_CSRASetting::newInstance();
	if( NULL == pc_CSRASetting ) {
		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
		if( NULL != pc_BFW_System ) {
			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19007001004E0101 );
		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" ); 
		return;
	}
	memset( &st_CsraSetting , 0x00, sizeof( st_CsraSetting ) );
	memset( &st_PrecheckServerInfo , 0x00, sizeof( st_PrecheckServerInfo ) );
	// クラス変数初期化.
	clearCSRemoteAnalysisFuncSetting();
	// CSRAデータ送付設定情報 取得.
	pc_CSRASetting->getCSRASetting( &st_CsraSetting );
	// CSRAプレチェックサーバー情報 取得.
	pc_CSRASetting->getCSRAPrecheckServerInfoSetting( &st_PrecheckServerInfo );
// comment 2020/09/29 HCL_Hemachander [RQ-776] Addition of CWH 1-way communication method.
// comment 2020/10/09 HCL_Hemachander [RQ-776] Function Version Check Removal.
//	if( True == PLBC_FuncVersionCheck::isOK_IT6_Type2()  ) {
		TYPS_CSRASetting			st_CsraSettingOneWay;
		TYPS_CSRASendInfo			st_CSRASendInfoOneWay;
		pc_CSRASetting->getCSRASetting( &st_CsraSettingOneWay,TYPE_CSRASettingComMode_OneWay );
		pc_CSRASetting->getCSRASendInfo( &st_CSRASendInfoOneWay,TYPE_CSRASettingComMode_OneWay );
// comment 2020/11/09 HCL_Madhavi [IT6_2.1] [OP_BTS-28903] Using correct communication Mode check.
//		if( True == st_CsraSetting.m_b_Enable){
		if( TYPE_CSRASettingComMode_TwoWay == pc_CSRASetting->getCSRASettingComMode() ){
			m_e_CSRemoteAnalysisEnable	= PNLE_CSRAEnableTwoWay;
// comment 2020/11/09 HCL_Madhavi [IT6_2.1] [OP_BTS-28903] Using correct communication Mode check.
//		}else if( True == st_CsraSettingOneWay.m_b_Enable ){
		}else if( TYPE_CSRASettingComMode_OneWay == pc_CSRASetting->getCSRASettingComMode() ){
			m_e_CSRemoteAnalysisEnable	= PNLE_CSRAEnableOneWay;
// Comment 2021/10/14 FPT-LinhNV46【IT6_2.2_MR1】【制御構成変更_No.38】RQ-776 CWH 1-way通信　BCN対応.
		} else if( TYPE_CSRASettingComMode_OneWay_CN == pc_CSRASetting->getCSRASettingComMode() ) {
			m_e_CSRemoteAnalysisEnable	= PNLE_CSRAEnableOneWay_CN;
		} else {
			m_e_CSRemoteAnalysisEnable	= PNLE_CSRADisable;
		}
		memcpy(  &m_st_CsraSettingOneWay, &st_CsraSettingOneWay, sizeof (st_CsraSettingOneWay));
		memcpy(  &m_st_CSRASendInfoOneWay, &st_CSRASendInfoOneWay, sizeof (st_CSRASendInfoOneWay) );
//	}
	// 設定値をクラス変数に格納.
	m_bl_CSRemoteAnalysisEnable	= st_CsraSetting.m_b_Enable;										// 機能設定.
	memcpy( m_sc_UrlAdd,	st_PrecheckServerInfo.m_sc_ServerAddress,	sizeof(m_sc_UrlAdd)		);	// URLｱﾄﾞﾚｽ.
	memcpy( m_sc_Account,	st_PrecheckServerInfo.m_sc_UserName,		sizeof(m_sc_Account)	);	// ｱｶｳﾝﾄ.
	memcpy( m_sc_Password,	st_PrecheckServerInfo.m_sc_Password,		sizeof(m_sc_Password)	);	// ﾊﾟｽﾜｰﾄﾞ.
	m_us_PortNumber				= st_PrecheckServerInfo.m_us_PortNo;								// ﾎﾟｰﾄ番号.
// comment 2017/06/12 [MAv5-1]RQ-710 CSRA接続機能追加 日立 森本郁.
	m_us_SalesCompanyCode		= st_CsraSetting.m_us_SalesCompanyID;								// 販社ｺｰﾄﾞ.
}
//================================================================================================.
// 概要    :共通_CS Remote Analysis設定データクラス : 送信設定の一括取得処理.
//================================================================================================.
void PServiceCSRemoteAnalysisSettingInfo::loadCSRemoteAnalysisSendSetting()
{
	TYPS_CSRASetting			st_CsraSetting;
	APIC_CSRASetting *pc_CSRASetting = APIC_CSRASetting::newInstance();
	if( NULL == pc_CSRASetting ) {
		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
		if( NULL != pc_BFW_System ) {
			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19007001004E0201 );
		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" ); 
		return;
	}
	// クラス変数初期化.
	clearCSRemoteAnalysisSendSetting();
// comment 2020/09/29 HCL_Hemachander [RQ-776] Addition of CWH 1-way communication method.
// comment 2020/10/09 HCL_Hemachander [RQ-776] Function Version Check Removal.
//	if( True == PLBC_FuncVersionCheck::isOK_IT6_Type2()  ) {
		TYPS_CSRASetting			st_CsraSettingOneWay;
		pc_CSRASetting->getCSRASetting( &st_CsraSettingOneWay,TYPE_CSRASettingComMode_OneWay );
// comment 2020/10/06 HCL_Hemachander [OP_BTS-28184] MemCopy Member variable in CSRemote Analysis Menu.
//		memcpy(  &st_CsraSettingOneWay, &m_st_CsraSettingOneWay, sizeof (m_st_CsraSettingOneWay));
		memcpy(  &m_st_CsraSettingOneWay, &st_CsraSettingOneWay, sizeof (st_CsraSettingOneWay));
//	}
	
	// CSRAデータ送付設定情報 取得.
	pc_CSRASetting->getCSRASetting( &st_CsraSetting );
	// 設定値をクラス変数に格納.
	m_bl_SettingOverwrite		= st_CsraSetting.m_b_SettingOverwrite;								// 上書き可否設定.
	m_uc_CycleDay				= st_CsraSetting.m_uc_CycleDay;										// ｽｹｼﾞｭｰﾙ1_日周期_日.
	m_e_CycleWday				= st_CsraSetting.m_e_CycleWday;										// ｽｹｼﾞｭｰﾙ2(毎週)_曜日指定.
	m_uc_CycleMonth				= st_CsraSetting.m_uc_CycleMonth;									// ｽｹｼﾞｭｰﾙ3(毎月)_日付指定.
	m_e_PrecheckPeriodSetting	= st_CsraSetting.m_e_PrecheckPeriodSetting;							// 時間枠/時刻選択設定.
	m_uc_PrecheckTime_Hour		= st_CsraSetting.m_c_PrecheckTime.sc_Hour;							// 時刻指定_時刻_時.
	m_uc_PrecheckTime_Minute	= st_CsraSetting.m_c_PrecheckTime.sc_Minute;						// 時刻指定_時刻_分.
	m_us_TimeoutSetting			= st_CsraSetting.m_us_Timeout;										// 送信タイムアウト設定.
	memcpy( m_bl_SendingOKPeriod, st_CsraSetting.m_b_SendingOKPeriod, sizeof(m_bl_SendingOKPeriod) );		// 各時間枠発信可否.
}
