//================================================================================================.
// 概要    :共通_CS Remote Analysis設定データクラス : 送信設定の一括設定処理.
//================================================================================================.
Bool PServiceCSRemoteAnalysisSettingInfo::commitCSRemoteAnalysisSendSetting()
{
	TYPS_CSRASetting			st_CsraSetting;
	APIC_CSRASetting *pc_CSRASetting = APIC_CSRASetting::newInstance();
	if( NULL == pc_CSRASetting ) {
		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
		if( NULL != pc_BFW_System ) {
			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19007001004E0401 );
		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" ); 
		return False;
	}

	// 管理システム統合化開発 RQ-893 [OP_BTS-32147] 2021/03/26 Sky大橋 START.
	if ( True == PnlComGetRdsSetting()->getMaintStat() ) {
		return False;
	}
	// 管理システム統合化開発 RQ-893 [OP_BTS-32147] 2021/03/26 Sky大橋 END.
	
	// CSRAデータ送付設定情報 取得.
	pc_CSRASetting->getCSRASetting( &st_CsraSetting );

	// クラス変数の値をセット.
	st_CsraSetting.m_b_SettingOverwrite			= m_bl_SettingOverwrite;							// 上書き可否設定.
	st_CsraSetting.m_uc_CycleDay				= m_uc_CycleDay;									// ｽｹｼﾞｭｰﾙ1_日周期_日.
	st_CsraSetting.m_e_CycleWday				= m_e_CycleWday;									// ｽｹｼﾞｭｰﾙ2(毎月)_曜日指定.
	st_CsraSetting.m_uc_CycleMonth				= m_uc_CycleMonth;									// ｽｹｼﾞｭｰﾙ3(毎月)_日付指定.
	st_CsraSetting.m_e_PrecheckPeriodSetting	= m_e_PrecheckPeriodSetting;						// 時間枠/時刻選択設定.
	st_CsraSetting.m_c_PrecheckTime.sc_Hour		= m_uc_PrecheckTime_Hour;							// 時刻指定_時刻_時.
	st_CsraSetting.m_c_PrecheckTime.sc_Minute	= m_uc_PrecheckTime_Minute;							// 時刻指定_時刻_分.
	st_CsraSetting.m_us_Timeout					= m_us_TimeoutSetting;								// 送信タイムアウト設定.
	memcpy( st_CsraSetting.m_b_SendingOKPeriod, m_bl_SendingOKPeriod, sizeof(st_CsraSetting.m_b_SendingOKPeriod) );		// 各時間枠発信可否.
	// CSRAデータ送付設定情報 設定.
	pc_CSRASetting->setCSRASetting( st_CsraSetting );

	return True;
}

Bool								PServiceCSRemoteAnalysisFuncCom::m_bl_FromMenu = False;
PNLE_CSRemoteAnalysisFuncSetting	PServiceCSRemoteAnalysisFuncCom::m_e_CSRemoteAnalysisFuncSettingShow = PNLE_CSRemoteAnalysisFuncSetting_Enable;
//================================================================================================.
// 概要    :共通_CS Remote Analysis機能設定共通 : コンストラクタ.
//================================================================================================.
PServiceCSRemoteAnalysisFuncCom::PServiceCSRemoteAnalysisFuncCom( PDisplayParts** partsTable, short partsNumber, Bool isNoWarning )
	 : PServiceNoFunctionCodeCom( partsTable, partsNumber, isNoWarning )
{
	m_bl_FromMenu = False;
	m_e_CSRemoteAnalysisFuncSettingShow = PNLE_CSRemoteAnalysisFuncSetting_Enable;
	m_pc_SettingInfo = PServiceCSRemoteAnalysisSettingInfo::newInstance();
	if( NULL == m_pc_SettingInfo ) {
		printf("PServiceCSRemoteAnalysisFuncCom::PServiceCSRemoteAnalysisFuncCom() Instance is NULL!\n");
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}
}
//================================================================================================.
// 概要    :共通_CS Remote Analysis機能設定共通 : 画面開始処理.
//================================================================================================.
void PServiceCSRemoteAnalysisFuncCom::startGamen()
{
	PServiceNoFunctionCodeCom::startGamen();	// 親クラスをコール.

	if( True == m_bl_FromMenu ) {				// メニュー画面からの遷移の場合.
		m_e_CSRemoteAnalysisFuncSettingShow = PNLE_CSRemoteAnalysisFuncSetting_Enable;	// 表示画面フラグを初期値(機能設定画面)に設定する.
		m_bl_FromMenu = False;															// 上位画面から画面遷移後は処理を実施させない.
		m_pc_SettingInfo->loadCSRemoteAnalysisFuncSetting();							// CommonAPIから設定値を取得する.
	}
}
//================================================================================================.
// 概要    :共通_CS Remote Analysis機能設定共通 : 表示部品のセットアップ.
//================================================================================================.
void PServiceCSRemoteAnalysisFuncCom::setupGamen( short ss_option )
{
	PServiceNoFunctionCodeCom::setupGamen( ss_option );	// 親クラスをコール.
// comment 2020/10/09 HCL_Sowndarya [RQ-776] Hide CheckConnection key.
	if( PNLE_CSRAEnableTwoWay == m_pc_SettingInfo->getCSRemoteAnalysisSettingEnableOneTwoWay() ) { 
		Key_ServiceCSRemoteAnalysisConnectionCheck.showEnable( True );	// 接続確認.
	} else {
		Key_ServiceCSRemoteAnalysisConnectionCheck.showEnable( False );	// 接続確認.
	}
	switch( m_e_CSRemoteAnalysisFuncSettingShow ) {
		case PNLE_CSRemoteAnalysisFuncSetting_Enable:				// 機能設定.
			Rbt_ServiceCSRemoteAnalysisEnableSettingMenu.select( 0 );
			break;
		case PNLE_CSRemoteAnalysisFuncSetting_Server_UrlAdd:		// ｻｰﾊﾞｰ設定_URLｱﾄﾞﾚｽ.
			Rbt_ServiceCSRemoteAnalysisEnableSettingMenu.select( 1 );
			Rbt_RDReceiveSeverHttpMenu.select( 0 );
			break;
		case PNLE_CSRemoteAnalysisFuncSetting_Server_Account:		// ｻｰﾊﾞｰ設定_ｱｶｳﾝﾄ.
			Rbt_ServiceCSRemoteAnalysisEnableSettingMenu.select( 1 );
			Rbt_RDReceiveSeverHttpMenu.select( 1 );
			break;
		case PNLE_CSRemoteAnalysisFuncSetting_Server_Password:		// ｻｰﾊﾞｰ設定_ﾊﾟｽﾜｰﾄﾞ.
			Rbt_ServiceCSRemoteAnalysisEnableSettingMenu.select( 1 );
			Rbt_RDReceiveSeverHttpMenu.select( 2 );
			break;
		case PNLE_CSRemoteAnalysisFuncSetting_Server_PortNumber:	// ｻｰﾊﾞｰ設定_ﾎﾟｰﾄ番号.
			Rbt_ServiceCSRemoteAnalysisEnableSettingMenu.select( 1 );
			Rbt_RDReceiveSeverHttpMenu.select( 3 );
			break;
// comment 2017/07/21 日立 森本 [MAv5-1][RQ-710] CSRA接続 販社設定追加対応.
		case PNLE_CSRemoteAnalysisFuncSetting_SalesCompanyCode:		// 販社ｺｰﾄﾞ.
			Rbt_ServiceCSRemoteAnalysisEnableSettingMenu.select( 2 );
			break;
		case PNLE_CSRemoteAnalysisFuncSetting_ConnectionCheck:		// 接続確認.
// comment 2017/07/21 日立 森本 [MAv5-1][RQ-710] CSRA接続 販社設定追加対応.
//			Rbt_ServiceCSRemoteAnalysisEnableSettingMenu.select( 2 );
			Rbt_ServiceCSRemoteAnalysisEnableSettingMenu.select( 3 );
			break;
		default: break;
	}
}
//================================================================================================.
// 概要    :共通_CS Remote Analysis機能設定共通 : OKキー押下処理.
//================================================================================================.
void PServiceCSRemoteAnalysisFuncCom::procOk( uchar uc_option )
{
	// 設定値をCommonAPIへ設定する.
	if( False == m_pc_SettingInfo->commitCSRemoteAnalysisFuncSetting() ) {
		setBuzzerType( PCGE_BuzzerType_InputNg );	// ブザー音セット.
		return;
	}
	nextGamen = &gp_ServiceCSRemoteAnalysisMenu;	// zcB0012000_CS Remote Analysis／メニュー.
}
//================================================================================================.
// 概要    :共通_CS Remote Analysis機能設定共通 : 画面遷移処理.
//================================================================================================.
void PServiceCSRemoteAnalysisFuncCom::procGoToPage( uchar uc_option )
{
	switch( uc_option ) {
		case 0:	// URLｱﾄﾞﾚｽ.
			m_e_CSRemoteAnalysisFuncSettingShow = PNLE_CSRemoteAnalysisFuncSetting_Server_UrlAdd;
			nextGamen = &gp_ServiceCSRemoteAnalysisUrlAdd;		// zcB0012110_CS Remote Analysis／サーバー設定／URLアドレス.
			break;
		case 1:	// ｱｶｳﾝﾄ.
			m_e_CSRemoteAnalysisFuncSettingShow = PNLE_CSRemoteAnalysisFuncSetting_Server_Account;
			nextGamen = &gp_ServiceCSRemoteAnalysisAccount;		// zcB0012130_CS Remote Analysis／サーバー設定／アカウント.
			break;
		case 2:	// ﾊﾟｽﾜｰﾄﾞ.
			m_e_CSRemoteAnalysisFuncSettingShow = PNLE_CSRemoteAnalysisFuncSetting_Server_Password;
			nextGamen = &gp_ServiceCSRemoteAnalysisPassword;	// zcB0012140_CS Remote Analysis／サーバー設定／パスワード.
			break;
		case 3:	// ﾎﾟｰﾄ番号.
			m_e_CSRemoteAnalysisFuncSettingShow = PNLE_CSRemoteAnalysisFuncSetting_Server_PortNumber;
			nextGamen = &gp_ServiceCSRemoteAnalysisPortNumber;	// zcB0012150_CS Remote Analysis／サーバー設定／ポート番号.
			break;
		default: break;
	}
}
