//================================================================================================.
void PServiceCSRemoteAnalysisFuncCom::procIndexButton( uchar uc_option )
{
	// 設定値をCommonAPIへ設定する.
	if( False == m_pc_SettingInfo->commitCSRemoteAnalysisFuncSetting() ) {
		setBuzzerType( PCGE_BuzzerType_InputNg );	// ブザー音セット.
		return;
	}
	switch( uc_option ) {
		case BTNID_INDEX_ServiceCSRemoteAnalysis_EnableSetting:		// 機能設定.
			m_e_CSRemoteAnalysisFuncSettingShow = PNLE_CSRemoteAnalysisFuncSetting_Enable;
			nextGamen = &gp_ServiceCSRemoteAnalysisEnableSetting;	// zcB0012100_CS Remote Analysis／機能設定.
			break;
		case BTNID_INDEX_ServiceCSRemoteAnalysis_ServerSetting:		// ｻｰﾊﾞｰ設定.
			m_e_CSRemoteAnalysisFuncSettingShow = PNLE_CSRemoteAnalysisFuncSetting_Server_UrlAdd;
			nextGamen = &gp_ServiceCSRemoteAnalysisUrlAdd;			// zcB0012110_CS Remote Analysis／サーバー設定／URLアドレス.
			break;
// comment 2017/07/21 日立 森本 [MAv5-1][RQ-710] CSRA接続 販社設定追加対応.
		case BTNID_INDEX_ServiceCSRemoteAnalysis_SalesCompanyCode:	// 販社ｺｰﾄﾞ.
			m_e_CSRemoteAnalysisFuncSettingShow = PNLE_CSRemoteAnalysisFuncSetting_SalesCompanyCode;
			nextGamen = &gp_ServiceCSRemoteAnalysisSalesCompanyCode;	// zcB0012170_CS Remote Analysis／販社コード.
			break;
		case BTNID_INDEX_ServiceCSRemoteAnalysis_ConnectionCheck:	// 接続確認.
			m_e_CSRemoteAnalysisFuncSettingShow = PNLE_CSRemoteAnalysisFuncSetting_ConnectionCheck;
			nextGamen = &gp_ServiceCSRemoteAnalysisConnectionCheck;	// zcB0012160_CS Remote Analysis／接続確認.
			break;
		default: break;
	}
}
