//================================================================================================.
// 概要    :zcB0012100_CS Remote Analysis／機能設定 : キー押下処理.
//================================================================================================.
void PServiceCSRemoteAnalysisEnableSetting::procButtonOn( uchar uc_option )
{
	PServiceCSRemoteAnalysisFuncCom::procButtonOn( uc_option );	// 親クラスをコール.

// comment 2020/10/09 HCL_Sowndarya [RQ-776] Function Version Check Removal.
	switch( uc_option ) {
//		case BTNID_KEY_ServiceCSRemoteAnalysis_EnableSelectOn:
			// 機能設定を使用するに設定.
//			m_pc_SettingInfo->setCSRemoteAnalysisSettingEnable( True );
//			break;
//		case BTNID_KEY_ServiceCSRemoteAnalysis_EnableSelectOff:
			// 機能設定を使用しないに設定.
//			m_pc_SettingInfo->setCSRemoteAnalysisSettingEnable( False );
//			break;
// comment 2020/09/29 HCL_Hemachander [RQ-776] Addition of CWH 1-way communication method.
		case BTNID_KEY_ServiceCSRemoteAnalysis_EnableSelectOnOneway:
			m_pc_SettingInfo->setCSRemoteAnalysisSettingEnableOneTwoWay( PNLE_CSRAEnableOneWay );
			m_pc_SettingInfo->setCSRemoteAnalysisSettingEnable( True );
// Comment 2021/10/14 FPT-SaoVT【IT6_2.2_MR1】【制御構成変更_No.38】RQ-776 CWH 1-way通信　BCN対応.
			setDefaultCSRASetting( TYPE_CSRASettingComMode_OneWay );
			break;
// Comment 2021/10/14 FPT-SaoVT【IT6_2.2_MR1】【制御構成変更_No.38】RQ-776 CWH 1-way通信　BCN対応.
		case BTNID_KEY_ServiceCSRemoteAnalysis_EnableSelectOnOnewayCN:
			m_pc_SettingInfo->setCSRemoteAnalysisSettingEnableOneTwoWay( PNLE_CSRAEnableOneWay_CN );
			m_pc_SettingInfo->setCSRemoteAnalysisSettingEnable( True );
			setDefaultCSRASetting( TYPE_CSRASettingComMode_OneWay_CN );
			break;
		case BTNID_KEY_ServiceCSRemoteAnalysis_EnableSelectOnTwoway:
			m_pc_SettingInfo->setCSRemoteAnalysisSettingEnableOneTwoWay( PNLE_CSRAEnableTwoWay );
			m_pc_SettingInfo->setCSRemoteAnalysisSettingEnable( True );
			break;
		case BTNID_KEY_ServiceCSRemoteAnalysis_EnableSelectDisable:
			// 管理システム統合化開発 RQ-893 [OP_BTS-32147] 2021/03/26 Sky大橋 START.
			// CSRCメンテナンス中であれば、[機能設定：使用しない]への変更を拒否し、同時に拒否音を鳴らす.
			if ( True == PnlComGetRdsSetting()->getMaintStat() ) {
				setBuzzerType( PCGE_BuzzerType_InputNg );	// 拒否音.
				break;
			}
			// 管理システム統合化開発 RQ-893 [OP_BTS-32147] 2021/03/26 Sky大橋 END.
			m_pc_SettingInfo->setCSRemoteAnalysisSettingEnableOneTwoWay( PNLE_CSRADisable );
			m_pc_SettingInfo->setCSRemoteAnalysisSettingEnable( False );
			break;

		default:	break;
	}
	setupGamen( uc_option );
}

// Comment 2021/10/14 FPT-LinhNV46【IT6_2.2_MR1】【制御構成変更_No.38】RQ-776 CWH 1-way通信　BCN対応.
//================================================================================================.
// 概要    :zcB0012100_CS Remote Analysis／機能設定 : set default CSRA.
//================================================================================================.
void PServiceCSRemoteAnalysisEnableSetting::setDefaultCSRASetting( TYPE_CSRASettingComMode e_CSRASettingComMode )
{
	if( TYPE_CSRASettingComMode_OneWay == e_CSRASettingComMode ){
		m_pc_SettingInfo->setCSRemoteAnalysisSettingServerUrlAddress( NVDC_CSRARemoteAnalysisForOneWay_URL_US );
		m_pc_SettingInfo->setCSRemoteAnalysisSettingServerAccount( NVDC_CSRARemoteAnalysisForOneWay_UserName_US );
		m_pc_SettingInfo->setCSRemoteAnalysisSettingServerPassword( NVDC_CSRARemoteAnalysisForOneWay_Password_US );
		m_pc_SettingInfo->setCSRemoteAnalysisSettingSalesCompanyCode( TYPD_SalesCompanyIDForOneWay_US );
		m_pc_SettingInfo->setTimeoutSetting( TYPD_TimeoutForOneWay_US );
	} else if( TYPE_CSRASettingComMode_OneWay_CN == e_CSRASettingComMode ){
		m_pc_SettingInfo->setCSRemoteAnalysisSettingServerUrlAddress( NVDC_CSRARemoteAnalysisForOneWay_URL_CN );
		m_pc_SettingInfo->setCSRemoteAnalysisSettingServerAccount( NVDC_CSRARemoteAnalysisForOneWay_UserName_CN );
		m_pc_SettingInfo->setCSRemoteAnalysisSettingServerPassword( NVDC_CSRARemoteAnalysisForOneWay_Password_CN );
		m_pc_SettingInfo->setCSRemoteAnalysisSettingSalesCompanyCode( TYPD_SalesCompanyIDForOneWay_CN );
		m_pc_SettingInfo->setTimeoutSetting( TYPD_TimeoutForOneWay_CN );
	}
}

// Comment 2021/10/27 FPT-LinhNV46【IT6_2.2_MR1】[OP_BTS-36129]「Reset」を押下した後に「使用する(片方向: CN」の「送信設定」画面が正しく表示されていない.
//================================================================================================.
// 概要    :zcB0012100_CS Remote Analysis／機能設定 :リセットキー押下処理.
//================================================================================================.
void PServiceCSRemoteAnalysisEnableSetting::procReset( uchar uc_option )
{
	APIC_CSRASetting *pc_CSRASetting = APIC_CSRASetting::newInstance();
	if( NULL == pc_CSRASetting ) {
		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
		if( NULL != pc_BFW_System ) {
			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19007001004E0101 );
		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" ); 
		return;
	}
	
	if( TYPE_CSRASettingComMode_TwoWay == pc_CSRASetting->getCSRASettingComMode() ){
		m_pc_SettingInfo->setCSRemoteAnalysisSettingEnableOneTwoWay( PNLE_CSRAEnableTwoWay );
	} else if( TYPE_CSRASettingComMode_OneWay == pc_CSRASetting->getCSRASettingComMode() ){
		m_pc_SettingInfo->setCSRemoteAnalysisSettingEnableOneTwoWay( PNLE_CSRAEnableOneWay );
	} else if( TYPE_CSRASettingComMode_OneWay_CN == pc_CSRASetting->getCSRASettingComMode() ) {
		m_pc_SettingInfo->setCSRemoteAnalysisSettingEnableOneTwoWay( PNLE_CSRAEnableOneWay_CN );
	} else {
		m_pc_SettingInfo->setCSRemoteAnalysisSettingEnableOneTwoWay( PNLE_CSRADisable );
	}
	PServiceCSRemoteAnalysisFuncCom::procReset( uc_option );	// 親クラスをコール.
}

// Comment 2021/10/27 FPT-LinhNV46【IT6_2.2_MR1】[OP_BTS-36129]「Reset」を押下した後に「使用する(片方向: CN」の「送信設定」画面が正しく表示されていない.
