// 概要    :共通_CS Remote Analysisサーバー設定・IP入力共通 : コンストラクタ.
// 備考    :PServiceRDModeNtIPInputcom::PServiceRDModeNtIPInputcomの流用.
//================================================================================================.
PServiceCSRemoteAnalysisIPInputCom::PServiceCSRemoteAnalysisIPInputCom( PDisplayParts** partsTable, short partsNumber, Bool isNoWarning )
	 : PServiceCSRemoteAnalysisFuncCom( partsTable, partsNumber, isNoWarning )
{
	// 変数の初期化.
	m_ss_InputPosition = -1;		// 入力エリア.
	m_bl_InputIPAddress = False;	// 入力形式. True→IPアドレス形式、False→FQDN形式.
	memset( m_uc_Address, '\0', sizeof( m_uc_Address ) );

	for( uchar j = 0; j < 4; j++ ) {
		m_uc_AdressValue[j] = NULL;	// IPアドレス値.
		m_bl_Fixed[j] = False;		// 確定フラグ.
		m_bl_Direct[j] = False;		// ダイレクト入力.
	}
}
//================================================================================================.
// 概要    :共通_CS Remote Analysisサーバー設定・IP入力共通 : 画面開始処理.
// 備考    :PServiceRDModeNtIPInputcom::startGamen()の流用.
//================================================================================================.
void PServiceCSRemoteAnalysisIPInputCom::startGamen()
{
	PBasicMessageProc::startGamen();

	m_ss_InputPosition = 0;	// 入力エリア.
	for( short i = 0 ; i < 4 ; i++ ) {
		m_uc_AdressValue[i] = 0x00;				// IPアドレス値.
		m_bl_Fixed[i] = True;					// 確定フラグ.
		m_bl_Direct[i] = True;					// ダイレクト入力.
	}
	m_bl_Fixed[0] = False;	// 確定フラグOFF.
	memset( m_uc_Address, '\0', sizeof( m_uc_Address ) );

	// パーツ表示制御.
	CheckShowParts();
}
//================================================================================================.
// 概要    :共通_CS Remote Analysisサーバー設定・IP入力共通 : 表示部品のセットアップ.
// 備考    :PServiceRDModePcIPInputCom::setupGamen()の流用.
//================================================================================================.
void PServiceCSRemoteAnalysisIPInputCom::setupGamen( short ss_option )
{
	PServiceCSRemoteAnalysisFuncCom::setupGamen( ss_option );		// 親クラスをコール.

	// 現在の入力形式に応じてパーツを表示する.
	if( True == m_bl_InputIPAddress ) {	// IPｱﾄﾞﾚｽ形式の場合.
		Bak_ServiceIpAdressInput.showEnable( True );				// IP表示領域.
		Grp_ServiceInputIPAdressParts.showEnable( True );			// IPｱﾄﾞﾚｽ入力用パーツ群(矢印).
		Grp_ServiceInputIPAdress.showEnable( True );				// IPｱﾄﾞﾚｽの入力値.
		Grp_ServiceCursorIPAdress.showEnable( True );				// 入力カーソル.
		Key_SRdsServerSettingPOP3ServerIPAddress.select( True );	// IPｱﾄﾞﾚｽ入力キー.
		for( short i = 0 ; i < 4 ; i++ ) {							// IPｱﾄﾞﾚｽの数値を順に表示&カーソル表示する.
			Inp_ServiceNetworkIPAdress[i].set( m_uc_AdressValue[i] , m_bl_Fixed[i] );			// 入力で扱うアドレス値を表示.
			Gra_ServiceCursorIPAdress[i].showEnable( i == m_ss_InputPosition ? True : False );	// カーソルの表示（入力選択位置）（左から０～３）.
		}
		//不要パーツを非表示.
		Btx_RDReceiveSeverHttpFQDNDisp.showEnable( False );			// FQDN表示領域.
		Key_SRdsServerSettingPOP3ServerFQDNInput.select( False );	// FQDN入力キー.
	} else {							// FQDN形式の場合.
		Btx_RDReceiveSeverHttpFQDNDisp.showEnable( True );			// FQDN表示領域.
		Key_SRdsServerSettingPOP3ServerFQDNInput.select( True );	// FQDN入力キー.
		uchar uc_LocalString[ DEF_CSRA_FQDNSizeMax + 5 ] = {0};		// +5 は改行と'\0'のぶん.
		setupInputString( 5, 52, reinterpret_cast<char*>(m_uc_Address), reinterpret_cast<char*>(uc_LocalString), 0, EP_CharSet_USASCII );
		Btx_RDReceiveSeverHttpFQDNDisp.changeExternalText( uc_LocalString );
		//不要パーツを非表示.
		Bak_ServiceIpAdressInput.showEnable( False );				// IP表示領域.
		Grp_ServiceInputIPAdressParts.showEnable( False );			// IPｱﾄﾞﾚｽ入力用パーツ群.
		Grp_ServiceInputIPAdress.showEnable( False );				// IPｱﾄﾞﾚｽの入力値.
		Grp_ServiceCursorIPAdress.showEnable( False );				// 入力カーソル.
		Key_SRdsServerSettingPOP3ServerIPAddress.select( False );	// IPｱﾄﾞﾚｽ入力キー.
	}
}
//================================================================================================.
// 概要    :共通_CS Remote Analysisサーバー設定・IP入力共通 : アドレスがIPアドレスか否かを判定する.
// 戻り値  :True：IPアドレス、False：IPアドレスでない.
// 備考    :数字(3桁まで).数字(3桁まで).数字(3桁まで).数字(3桁まで)の場合のみIPアドレスとみなす.
//         :PServiceRDModeNtIPInputcom::isIPAddress()の流用.
//================================================================================================.
Bool PServiceCSRemoteAnalysisIPInputCom::isIPAddress(
    const char* _uc_Address,		// アドレス.
    const ushort _us_CharLength )
{
	Bool	bl_isIPAddress = True;
	short	ss_ipaddress[4] = { 0, 0, 0, 0};
	Bool	bl_isAreaOK[4] = { False, False, False, False };
	char	sc_area = 0;
	for( short i = 0; i < _us_CharLength; i++ ) {
		if( '\0' == _uc_Address[i] ) {
			if( ( 3 == sc_area ) && ( True == bl_isAreaOK[3] ) ) {
				// IPアドレスとして確定.
				break;
			} else {
				// 予期しない位置にNULLがあればIPアドレスではない.
				bl_isIPAddress = False;
				break;
			}
		}
		if( ( '0' <= _uc_Address[i] ) && ( '9' >= _uc_Address[i] ) ) {
			bl_isAreaOK[static_cast<uchar>(sc_area)] = True;
			ss_ipaddress[static_cast<uchar>(sc_area)] = static_cast<short>(10 * ss_ipaddress[static_cast<uchar>(sc_area)] + ( _uc_Address[i] - '0' ));	// 数字であればIPアドレス（候補）とする.
			if( 255 < ss_ipaddress[static_cast<uchar>(sc_area)] ) {
				// いずれかの値が255より大きければIPアドレスではない.
				bl_isIPAddress = False;
				break;
			}
		} else if( '.' == _uc_Address[i] ) {
			sc_area++;		// 次のエリアへ移動.
			if( 3 < sc_area ) {
				// ピリオドが4つ以上検知された場合にはIPアドレスではないので探索終了.
				bl_isIPAddress = False;
				break;
			}
		} else {
			// 数字・ピリオド以外の値が含まれていたらIPアドレスではないので探索終了.
			bl_isIPAddress = False;
			break;
		}
	}
	return( bl_isIPAddress );
}
//================================================================================================.
// 概要    :共通_CS Remote Analysisサーバー設定・IP入力共通 : 文字列をIPアドレス形式に変換.
// 備考    :PServiceRDModeNtIPInputcom::CharToIPAddress()の流用.
//================================================================================================.
void PServiceCSRemoteAnalysisIPInputCom::CharToIPAddress(
    const char* _sc_CharAddress,		// アドレス文字列.
    uchar* _uc_IPAddress )				// IPアドレス変換後格納用.
{
	memset( _uc_IPAddress, 0, 4 );
	short ss_point = 0, ss_tmpNum = 0;
	while( *_sc_CharAddress ) {
		if( ( 0x30 <= *_sc_CharAddress ) && ( 0x39 >= *_sc_CharAddress ) ) {
			// 数字0～9の場合.
			ss_tmpNum = _uc_IPAddress[ss_point];
			ss_tmpNum = static_cast<short>(( ss_tmpNum * 10 ) + *_sc_CharAddress - 0x30);
			// 255よりも大きい場合は255に丸め込む.
			if( 255 < ss_tmpNum )	{ ss_tmpNum = 255; }
			_uc_IPAddress[ss_point] = static_cast<uchar>(ss_tmpNum);
		} else if( 0x2e == *_sc_CharAddress ) {
			// 「．」の場合.
			ss_point++;
			if( 3 < ss_point )	{ break; }
		} else if( 0x20 == *_sc_CharAddress ) {
			// スペースの場合.
		} else {
			// その他の文字.
			break;
		}
		_sc_CharAddress++;
	}
}
//================================================================================================.
// 概要    :共通_CS Remote Analysisサーバー設定・IP入力共通 : ＩＰアドレスを文字列形式に変換.
// 備考    :PServiceRDModeNtIPInputcom::IPAddressToChar()の流用.
//================================================================================================.
void PServiceCSRemoteAnalysisIPInputCom::IPAddressToChar(
    const uchar* _uc_IPAddress,		// IPアドレス.
    char* _sc_CharAddress )			// 文字列変換後格納用.
{
	char ss_buff[4];
	memset( ss_buff, 0, sizeof( ss_buff ) );
	snprintf( ss_buff, sizeof( ss_buff ), "%d", _uc_IPAddress[0] );
	strncpy( _sc_CharAddress, ss_buff, sizeof( ss_buff ) );
	for( short i = 1; i < 4; i++ ) {
		strcat( _sc_CharAddress, "." );
		snprintf( ss_buff, sizeof( ss_buff ), "%d", _uc_IPAddress[i] );
		strcat( _sc_CharAddress, ss_buff );
	}
}
//================================================================================================.
// 概要    :共通_CS Remote Analysisサーバー設定・IP入力共通 : キー押下処理.
// 備考    :PServiceRDModeNtIPInputcom::procButtonOn()の流用.
//================================================================================================.
void PServiceCSRemoteAnalysisIPInputCom::procButtonOn( uchar uc_option )
{
	switch( uc_option ) {
		case 0:		// ←キー.
			if( 0 < m_ss_InputPosition ) {
				m_bl_Direct[ m_ss_InputPosition ] = True;		// ダイレクト入力.
				m_bl_Fixed[ m_ss_InputPosition ] = True;		// 確定フラグON.
				m_ss_InputPosition--;
				m_bl_Fixed[ m_ss_InputPosition ] = False;		// 確定フラグOFF.
			} else {
				MCR_setBuzzerType( PCGE_BuzzerType_InputNg );	// 拒否音.
			}
			break;
		case 1:		// →キー.
			if( 3 > m_ss_InputPosition ) {
				m_bl_Direct[ m_ss_InputPosition ] = True;		// ダイレクト入力.
				m_bl_Fixed[ m_ss_InputPosition ] = True;		// 確定フラグON.
				m_ss_InputPosition++;
				m_bl_Fixed[ m_ss_InputPosition ] = False;		// 確定フラグOFF.
			} else {
				MCR_setBuzzerType( PCGE_BuzzerType_InputNg );	// 拒否音.
			}
			break;
		case 10: m_bl_InputIPAddress = True; break;				// IPｱﾄﾞﾚｽ入力キー.
		default: break;
	}
	setupGamen();
}
//================================================================================================.
// 概要    :共通_CS Remote Analysisサーバー設定・IP入力共通 : クリアキー押下処理.
// 備考    :PServiceRDModeNtIPInputcom::procClear()の流用.
//================================================================================================.
void PServiceCSRemoteAnalysisIPInputCom::procClear( uchar uc_option )
{
	m_uc_AdressValue[ m_ss_InputPosition ] = 0;	// 入力値.
	m_bl_Direct[ m_ss_InputPosition ] = True;	// ダイレクト入力ON.
	m_bl_Fixed[ m_ss_InputPosition ] = False;	// 未確定.
	setupGamen();
}
//================================================================================================.
// 概要    :共通_CS Remote Analysisサーバー設定・IP入力共通 : テンキー押下処理.
// 備考    :PServiceRDModeNtIPInputcom::proc10Key()の流用.
//================================================================================================.
void PServiceCSRemoteAnalysisIPInputCom::proc10Key( uchar uc_option )
{
	Bool bl_Error = False;
	m_uc_AdressValue[ m_ss_InputPosition ] = static_cast<uchar>(proc10KeyInput( m_uc_AdressValue[ m_ss_InputPosition ], 255, uc_option, m_bl_Direct[ m_ss_InputPosition ], EP_InputMaxLimitPattern_Refuse, &bl_Error ));
	if( True == bl_Error ) {
		setBuzzerType( PCGE_BuzzerType_InputNg );
	}

	if( ( True == m_bl_Direct[ m_ss_InputPosition ] ) && ( 0 == uc_option ) ) {
		m_uc_AdressValue[ m_ss_InputPosition ] = 0;	// 0で上書きするようにする.
		m_bl_Fixed[ m_ss_InputPosition ] = True;	// 表示を確定表示.
	}

	m_bl_Direct[ m_ss_InputPosition ] = False;		// ダイレクト入力OFF.
	setupGamen();
}

//================================================================================================.
// 概要    :zcB0012110_CS Remote Analysis／サーバー設定／URLアドレス : 画面開始処理.
//================================================================================================.
void PServiceCSRemoteAnalysisUrlAdd::startGamen()
{
	PServiceCSRemoteAnalysisIPInputCom::startGamen();	// 親クラスをコール.

	// データクラスからURLｱﾄﾞﾚｽを取得.
// comment 2018/03/22 静的解析指摘修正 日立 田中.
//	memcpy( m_uc_Address, m_pc_SettingInfo->getCSRemoteAnalysisSettingServerUrlAddress(), sizeof( m_uc_Address ) );
//Comment [2020/10/14][HCL_Hemachander][OP_BTS-28426]Memset the URL member variable.
//	strncpy( reinterpret_cast<char*>(m_uc_Address), m_pc_SettingInfo->getCSRemoteAnalysisSettingServerUrlAddress(), sizeof( m_uc_Address ) - 1 );
	strncpy( reinterpret_cast<char*>(m_uc_Address), m_pc_SettingInfo->getCSRemoteAnalysisSettingServerUrlAddress(), ( TYPD_CSRAServerInfo_URLMaxLen - 1 ) );

//	if( isIPAddress( reinterpret_cast<char*>(m_uc_Address), strlen( reinterpret_cast<char*>(m_uc_Address) ) ) ) {
	if( isIPAddress( reinterpret_cast<char*>(m_uc_Address), static_cast<ushort>( strlen( reinterpret_cast<char*>(m_uc_Address) ) ) ) ) {
		m_bl_InputIPAddress = True;
		CharToIPAddress( reinterpret_cast<char*>(m_uc_Address), m_uc_AdressValue );	// 取得した文字列をIPアドレス形式に変換.
	} else {
		m_bl_InputIPAddress = False;
	}
// comment 2020/09/22 HCL_Sowndarya [RQ-776] Addition of CWH 1-way communication method.
// Comment 2021/10/14 FPT-LinhNV46【IT6_2.2_MR1】【制御構成変更_No.38】RQ-776 CWH 1-way通信　BCN対応.
	if( PNLE_CSRAEnableOneWay == m_pc_SettingInfo->getCSRemoteAnalysisSettingEnableOneTwoWay()
		|| PNLE_CSRAEnableOneWay_CN == m_pc_SettingInfo->getCSRemoteAnalysisSettingEnableOneTwoWay() ) {
		Key_GoToRDModeReceiveSeverHttpPortNo.showEnable( False );
	} else {
		Key_GoToRDModeReceiveSeverHttpPortNo.showEnable( True );
	}	

}
