short PServiceCSRemoteAnalysisKeybordInputcom::m_ss_PassInsertPos	= -1;
//================================================================================================.
// 概要    :共通_CS Remote Analysisサーバ設定・キーボード入力共通 : コンストラクタ.
// 備考    :PServiceRDModeNtKeybordInputcom::PServiceRDModeNtKeybordInputcomの流用.
//================================================================================================.
PServiceCSRemoteAnalysisKeybordInputcom::PServiceCSRemoteAnalysisKeybordInputcom( PDisplayParts** partsTable, short partsNumber, Bool isNoWarning )
	 : PServiceCSRemoteAnalysisFuncCom( partsTable, partsNumber, isNoWarning )
{
	m_ss_MaxString = 130 + 1;		// 最大入力文字数.
	m_ss_Max1LineString = 70;		// 1行に表示できる文字数.
	memset( m_uc_LocalString, '\0', sizeof( m_uc_LocalString ) );
	m_ss_CursorPos = 0;				// 入力カーソルの指す文字位置.
	m_bl_Password = False;			// パスワード表示フラグ.
	m_bl_ShowPass = False;			// パスワード変更フラグ.
}
//================================================================================================.
// 概要    :共通_CS Remote Analysisサーバ設定・キーボード入力共通 : 画面開始処理.
// 備考    :PServiceRDModeNtKeybordInputcom::startGamen()の流用.
//================================================================================================.
void PServiceCSRemoteAnalysisKeybordInputcom::startGamen()
{
	PBasicMessageProc::startGamen();

	m_ss_MaxString = 130 + 1;		// 最大入力文字数
	m_ss_Max1LineString = 70;		// 1行に表示できる文字数.
	clearString( m_uc_LocalString, m_ss_MaxString );
	m_ss_CursorPos = 0;				// 入力カーソルの指す文字位置.
	// キーボード表示.
	Kbd_ServiceInputKeybord.setChangeEnlKeybord( PLBD_Enl_KBD_Initial );
	Kbd_ServiceInputKeybord = PLBC_ConvertKeybord( PLBD_KBT_EMail, 184, 206, True, True );	// キーボード種類、配置位置設定(矢印あり、削除ｷｰあり).
	// カーソルクラスへパーツポインタを渡す.
	Kbd_ServiceInputKeybord.GetCursor( NULL );
	startGamenKeybordService9E();
	Kbd_ServiceInputKeybord.showKeybord();	// キーボード表示.
	// 削除キー位置設定.
	Key_ServiceKeybordDelete.changePosition( 34, 103, 0, 0 );
}
//================================================================================================.
// 概要    :共通_CS Remote Analysisサーバ設定・キーボード入力共通 : 表示部品のセットアップ.
// 備考    :PServiceRDModeNtKeybordInputcom::setupGamen()の流用.
//================================================================================================.
void PServiceCSRemoteAnalysisKeybordInputcom::setupGamen( short ss_option )
{
	PServiceCSRemoteAnalysisFuncCom::setupGamen( ss_option );	// 親クラスをコール.
	short	ss_Xpos =  8;	// 入力カーソルＸ座標.
// comment 2017/07/18 [MAv5][AR1026050]日立 田中 アカウントとパスワードでカーソル位置を揃える.
//	short	ss_Ypos = 76;	// 入力カーソルＹ座標.
	short	ss_Ypos = 72;	// 入力カーソルＹ座標.
	// キーボード表示.
	setupGamenKeybordService();
	Kbd_ServiceInputKeybord.showKeybord();	// 変換用キーボードの表示.
	// 入力文字列の表示.
	uchar	uc_LocalString[ DEF_CSRA_KeyboardInputMax + 2 ] = {0};		// +2 は改行と'\0'のぶん.
	setupInputString( 2, m_ss_Max1LineString, reinterpret_cast<char*>(m_uc_LocalString), reinterpret_cast<char*>(uc_LocalString), 0, EP_CharSet_USASCII );
	Tfd_ServiceKeybordInputArea.changeExternalText( uc_LocalString );	// 入力フィールド.
	// パスワード表示.
	if( True == m_bl_Password ) {
		char	sc_Password[ DEF_CSRA_KeyboardInputMax + 2 ];			// +2 は改行と'\0'のぶん.
		memset( sc_Password, 0, sizeof( sc_Password )/sizeof( sc_Password[0] ) );
		if( True == m_bl_ShowPass ) {					// パスワード変更あり.
			if( '\0' != uc_LocalString[0] ) {			// パスワードが設定されている時.
				strcpy( sc_Password , "**********" );	// 「*」を10個表示する.
			} else {									// パスワードが設定されていない時.
				strcpy( sc_Password , "\0" );
			}
		} else {
			ushort i = 0;
			for( i = 0; i < strlen( reinterpret_cast<char*>(uc_LocalString) ); i++ ) {
				// パスワード入力文字を表示する場合.
				if( 0 <= m_ss_PassInsertPos ) {
					// 入力文字は、そのまま表示する.
					if( i == m_ss_PassInsertPos ) {
						strncpy( &sc_Password[i], reinterpret_cast<char*>(&uc_LocalString[i]), 1 );
						continue;
					}
				}
				sc_Password[ i ] = '*';
			}
			sc_Password[ i ] = '\0';
		}
		Tfd_ServiceKeybordInputArea.changeExternalText( reinterpret_cast<uchar*>(sc_Password) );		// 入力フィールド.
	}
	// カーソルの指す文字位置が表示している文字列内に収まるように補正(念のため).
	if( m_ss_MaxString <= m_ss_CursorPos ) {
		m_ss_CursorPos = static_cast<short>(m_ss_MaxString - 1);
	}
	if( 0 > m_ss_CursorPos ) {
		m_ss_CursorPos = 0;
	}
	// カーソルの指す文字位置により、カーソル位置を移動.
// comment 2018/03/22 静的解析指摘修正 日立 田中.
//	if( ( 0 <= m_ss_CursorPos ) && ( m_ss_CursorPos < m_ss_Max1LineString ) && ( m_ss_CursorPos < m_ss_MaxString ) ) {	// 0～(1行目の最大文字数) のとき.
	if( ( m_ss_CursorPos < m_ss_Max1LineString ) && ( m_ss_CursorPos < m_ss_MaxString ) ) {	// 0～(1行目の最大文字数) のとき.
//Comment [2020/10/14][HCL_Hemachander][OP_BTS-28426]Multiplier value update.
//		ss_Xpos = static_cast<short>(8 + ( m_ss_CursorPos * 8 ));
		ss_Xpos = static_cast<short>(8 + ( m_ss_CursorPos * PNLD_CURSOR_POSITION_MULTIPLIER ));
		ss_Ypos = 72;
	} else if( ( m_ss_Max1LineString <= m_ss_CursorPos ) && ( m_ss_CursorPos <= m_ss_MaxString ) ) {
//Comment [2020/10/14][HCL_Hemachander][OP_BTS-28426]Multiplier value update.
//		ss_Xpos = static_cast<short>(8 + ( ( m_ss_CursorPos - m_ss_Max1LineString ) * 8 ));
		ss_Xpos = static_cast<short>(8 + ( ( m_ss_CursorPos - m_ss_Max1LineString ) * PNLD_CURSOR_POSITION_MULTIPLIER ));
		ss_Ypos = 88;
	}
	if( (True == m_bl_Password) && (True == m_bl_ShowPass) ) {	// 「*」を10個表示する状態.
		if( '\0' != uc_LocalString[0] ) {						// パスワードが設定されている時.
//Comment [2020/10/14][HCL_Hemachander][OP_BTS-28426]Multiplier value update.
//			ss_Xpos = 8 + ( 10 * 8 );							// 8 は先頭座標＋「*」10個分.
			ss_Xpos = 8 + ( 10 * PNLD_CURSOR_POSITION_MULTIPLIER );							// 8 は先頭座標＋「*」10個分.
		} else {												// パスワードが設定されていない時.
			ss_Xpos = 8;										// 8 は先頭座標.
		}
// comment 2017/07/18 [MAv5][AR1026050]日立 田中 アカウントとパスワードでカーソル位置を揃える.
//		ss_Ypos = 76;
		ss_Ypos = 72;
	}
	Gra_SRdsServerSettingCursor.changePosition( ss_Xpos, ss_Ypos );	// 入力カーソル位置移動.
}
