//================================================================================================.
// 概要    :共通_CS Remote Analysisサーバ設定・キーボード入力共通 : パスワード入力表示開始処理.
// 備考    :PServiceRDModeNtKeybordInputcom::judgePassInsert()の流用.
//================================================================================================.
void PServiceCSRemoteAnalysisKeybordInputcom::judgePassInsert( short ss_InsertPos )
{
	// パスワード入力文字表示設定が有効かチェック.
	if( False == PnlComCheckPassTimerDispSetting() ){
		return;
	}
	// パスワード入力の場合.
	if( True == m_bl_Password ) {
		m_ss_PassInsertPos = ss_InsertPos;
		PNLC_KeyboardTimerControlLib::newInstance()->startTimer( fixPassInput );
	}
}
//================================================================================================.
// 概要    :共通_CS Remote Analysisサーバ設定・キーボード入力共通 : パスワード入力表示文字位置更新.
// 備考    :PServiceRDModeNtKeybordInputcom::adjustPassInsert()の流用.
//================================================================================================.
void PServiceCSRemoteAnalysisKeybordInputcom::adjustPassInsert( short ss_DeletePos, short ss_DeleteSize )
{
	// パスワード入力の場合.
	if( True == m_bl_Password ) {
		// 削除位置と同じなら入力表示を終了する.
		if( ss_DeletePos == m_ss_PassInsertPos ) {
			fixPassInput();
		// 削除位置が入力表示位置より前なら表示位置を更新する.
		} else if( ss_DeletePos < m_ss_PassInsertPos ) {
			m_ss_PassInsertPos = static_cast<short>(m_ss_PassInsertPos - ss_DeleteSize);
		}
	}
}
//================================================================================================.
// 概要    :共通_CS Remote Analysisサーバ設定・キーボード入力共通 : パスワード入力表示解除.
// 備考    :PServiceRDModeNtKeybordInputcom::fixPassInput()の流用.
//================================================================================================.
void PServiceCSRemoteAnalysisKeybordInputcom::fixPassInput()
{
	m_ss_PassInsertPos = -1;
	PNLC_KeyboardTimerControlLib::newInstance()->cancelTimer();
}
//================================================================================================.
// 概要    :共通_CS Remote Analysisサーバ設定・キーボード入力共通 : キー押下処理.
// 備考    :PServiceRDModeNtKeybordInputcom::procButtonOn()の流用.
//================================================================================================.
void PServiceCSRemoteAnalysisKeybordInputcom::procButtonOn( uchar uc_option )
{
	// サービス・キーボード共通ボタン押下処理.
	procButtonOnKeybordService( uc_option );
	setupGamen();
}
//================================================================================================.
// 概要    :共通_CS Remote Analysisサーバ設定・キーボード入力共通 : クリアキー押下処理.
// 備考    :PServiceRDModeNtKeybordInputcom::procClear()の流用.
//================================================================================================.
void PServiceCSRemoteAnalysisKeybordInputcom::procClear( uchar uc_option )
{
	// パスワード入力＋「*」を10個表示状態の場合.
	if( ( True == m_bl_Password) && (True == m_bl_ShowPass) ) {
		m_bl_ShowPass = False;		// 「*」10個表示を止める.
	}

	// 文字列の初期化.
	clearString( m_uc_LocalString, m_ss_MaxString );

	fixPassInput();

	m_ss_CursorPos = 0;	// 入力カーソル位置.
	setupGamen();
}
//================================================================================================.
// 概要    :共通_CS Remote Analysisサーバ設定・キーボード入力共通 : キーボード処理.
// 備考    :PServiceRDModeNtKeybordInputcom::procKeyBoard()の流用.
//================================================================================================.
void PServiceCSRemoteAnalysisKeybordInputcom::procKeyBoard( uchar uc_option )
{
	if( (True == m_bl_Password) && (True == m_bl_ShowPass) ) {
		m_bl_ShowPass = False;	// 「*」10個表示を止める.
		// 入力中状態に変更.
// comment 2017/07/14 [MAv5][AR1026049]日立 田中 m_uc_LocalStringに文字列がある場合のみクリアする.
		if( 0 != strlen( reinterpret_cast<char*>(m_uc_LocalString) ) ) {
			procClear( 0 );			// 表示をクリアする.
		}
	}
	char	sc_keyCode[3];
	memset( sc_keyCode, 0x00, sizeof( sc_keyCode ) );
	// キーコードを取得.
	Kbd_ServiceInputKeybord.getKeyString( uc_option, sc_keyCode );
	switch( sc_keyCode[0] ) {
		case PLBD_ArrowLeftKeyCode:			// ←キー押下：カーソル位置を左に移動.
			if( 0 < m_ss_CursorPos ) {
				m_ss_CursorPos--;									// カーソルの指す文字位置を移動.
			} else {
				MCR_setBuzzerType( PCGE_BuzzerType_InputNg );		// 拒否音.
				break;
			}
			if( '\n' == m_uc_LocalString[ m_ss_CursorPos ] ) {		// 改行文字は飛ばす.
				m_ss_CursorPos--;
			}
			break;
		case PLBD_ArrowRighKeyCode:			// →キー押下：カーソル位置を右に移動.
// comment 2017/07/14 [MAv5][AR1026049]日立 田中 最大文字数のカーソル位置で→キー入力した場合は拒否音を鳴らす.
//			if( '\0' != m_uc_LocalString[ m_ss_CursorPos ] ) {
			// カーソル位置に文字あり　かつ　カーソル位置が最大文字数の位置ではない.
			if( ( '\0' != m_uc_LocalString[ m_ss_CursorPos ] ) && ( m_ss_MaxString > ( m_ss_CursorPos + 1 ) ) ) {
				m_ss_CursorPos++;
			} else {
				MCR_setBuzzerType( PCGE_BuzzerType_InputNg );		// 拒否音.
				break;
			}
			if( '\n' == m_uc_LocalString[ m_ss_CursorPos ] ) {		// 改行文字は飛ばす.
				m_ss_CursorPos++;
			}
			break;
		case PLBD_DeleteKeyCode:			// Delキー押下：一文字消去.
			if( '\0' == m_uc_LocalString[ m_ss_CursorPos ] ) {		// 文字列の最後尾の場合.
				// カーソルを一つ戻して一文字クリア.
				if( 0 < m_ss_CursorPos ) {
					m_ss_CursorPos--;
				} else {
					MCR_setBuzzerType( PCGE_BuzzerType_InputNg );	// 拒否音.
					break;
				}
				m_uc_LocalString[ m_ss_CursorPos ] = '\0';
			} else {	// 文字列の最後尾でない場合.
				// 現在位置の文字をクリアする(一文字ずつ前に詰める).
				for( short i = m_ss_CursorPos; m_uc_LocalString[i] != '\0'; i++ ) {
					m_uc_LocalString[ i ] = m_uc_LocalString[ i + 1 ];
				}
			}
			// パスワード入力表示位置を更新.
			{
				short	ss_strptr = LIBF_getUTF8ByteCount( reinterpret_cast<char*>(&m_uc_LocalString[m_ss_CursorPos]) );
				adjustPassInsert( m_ss_CursorPos, ss_strptr );
// comment 2018/03/22 静的解析指摘修正 日立 田中.
//				break;
			}
				break;
		default:							// その他のキー押下：入力文字列表示.
			if( m_ss_CursorPos == static_cast<short>(strlen( reinterpret_cast<char*>(m_uc_LocalString) )) ) {	// 現在位置が最後尾の場合.
				setStringWithCheck( m_uc_LocalString, sc_keyCode[0], m_ss_MaxString );
				// パスワード入力表示開始.
				judgePassInsert( m_ss_CursorPos );
				// カーソルを一つ進める.
				m_ss_CursorPos++;
			} else {
				// 入力された文字を現在位置に挿入.
				if( True == setStringInMedium( m_uc_LocalString, m_ss_CursorPos, sc_keyCode[0], m_ss_MaxString, m_ss_Max1LineString ) ) {
					// カーソルを一つ進める.
					m_ss_CursorPos++;
				}
// comment 2017/07/14 [MAv5][AR1026049]日立 田中 最大文字数以上入力した場合は拒否音を鳴らす.
				else {
					MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
				}
			}
			break;
	}
	setupGamen();
}
//================================================================================================.
// 概要    :共通_CS Remote Analysisサーバ設定・キーボード入力共通 : テンキー押下処理.
// 備考    :PServiceRDModeNtKeybordInputcom::proc10Key()の流用.
//================================================================================================.
void PServiceCSRemoteAnalysisKeybordInputcom::proc10Key( uchar uc_option )
{
	if( (True == m_bl_Password) && (True == m_bl_ShowPass) ) {
		m_bl_ShowPass = False;	// 「*」10個表示を止める.
		// 入力中状態に変更.
// comment 2017/07/14 [MAv5][AR1026049]日立 田中 m_uc_LocalStringに文字列がある場合のみクリアする.
		if( 0 != strlen( reinterpret_cast<char*>(m_uc_LocalString) ) ) {
			procClear( 0 );			// 表示をクリアする.
		}
	}
	if( 9 >= uc_option ) {
		// 入力された文字を現在位置に挿入.
		if( True == setStringInMedium( m_uc_LocalString, m_ss_CursorPos, static_cast<uchar>(uc_option + '0'), m_ss_MaxString, m_ss_Max1LineString ) ) {
			// カーソルを一つ進める.
			m_ss_CursorPos++;
		}
// comment 2017/07/14 [MAv5][AR1026049]日立 田中 最大文字数以上入力した場合は拒否音を鳴らす.
		else {
			MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
		}
	}
	setupGamen();
}
//================================================================================================.
// 概要    :共通_CS Remote Analysisサーバ設定・キーボード入力共通 : 文字挿入.
// 戻り値  :Bool (True:挿入できた  False:挿入できなかった).
// 備考    :PServiceRDModeNtKeybordInputcom::setStringInMedium()の流用.
//================================================================================================.
Bool PServiceCSRemoteAnalysisKeybordInputcom::setStringInMedium( uchar* puc_string, short ss_insertPos, uchar uc_input, short ss_stringMaxSize, short ss_Max1LineString )
{
	Bool bl_Result = False; // 文字を挿入できたか返すための変数.
	short ss_strLength = static_cast<short>(strlen( reinterpret_cast<char*>(puc_string) ));
	if( ( ( ss_strLength <= ss_Max1LineString ) && ( ss_strLength < ss_stringMaxSize ) )
	 || ( ( ss_Max1LineString < ss_strLength )  && ( ss_strLength < ss_stringMaxSize ) ) ) { // 一文字分以上、空きがある場合.
		// 現在位置以降の文字列を一文字分後ろにずらす.
		for( short i = static_cast<short>(strlen( reinterpret_cast<char*>(puc_string) )); i >= ss_insertPos; i-- ) {
			puc_string[ i ] = puc_string[ i-1 ];
		}
		// 現在位置に入力された文字を入れる.
		puc_string[ ss_insertPos ] = uc_input;
		// パスワード入力表示開始.
		judgePassInsert( ss_insertPos );
		bl_Result = True; // 文字を挿入できた.
	} else {
		bl_Result = False; // 文字を挿入できなかった.
	}
	return( bl_Result );
}

//================================================================================================.
// 概要    :zcB0012130_CS Remote Analysis／サーバー設定／アカウント : 画面開始処理.
//================================================================================================.
void PServiceCSRemoteAnalysisAccount::startGamen()
{
	m_bl_Password = False;		// パスワード表示フラグ.
	m_bl_ShowPass = False;		// パスワード変更フラグ.

	PServiceCSRemoteAnalysisKeybordInputcom::startGamen();	// 画面開始処理（1行に表示できる文字数と最大表示行数の決定）.
	m_ss_MaxString = 63;		// 最大文字数.

	// データクラスからｱｶｳﾝﾄを取得.
// comment 2018/03/13 静的解析指摘修正 日立 田中.
//	memcpy( m_uc_LocalString, m_pc_SettingInfo->getCSRemoteAnalysisSettingServerAccount(), sizeof( m_uc_LocalString ) );
	strncpy( reinterpret_cast<char*>(m_uc_LocalString), m_pc_SettingInfo->getCSRemoteAnalysisSettingServerAccount(), sizeof( m_uc_LocalString ) - 1 );

	// カーソルを最後尾に移動.
//	m_ss_CursorPos = strlen( reinterpret_cast<char*>(m_uc_LocalString) );
	m_ss_CursorPos = static_cast<short>( strlen( reinterpret_cast<char*>(m_uc_LocalString) ) );

// comment 2020/09/22 HCL_Sowndarya [RQ-776] Addition of CWH 1-way communication method.
// Comment 2021/10/14 FPT-LinhNV46【IT6_2.2_MR1】【制御構成変更_No.38】RQ-776 CWH 1-way通信　BCN対応.
	if( PNLE_CSRAEnableOneWay == m_pc_SettingInfo->getCSRemoteAnalysisSettingEnableOneTwoWay()
		|| PNLE_CSRAEnableOneWay_CN == m_pc_SettingInfo->getCSRemoteAnalysisSettingEnableOneTwoWay() ) {
		Key_GoToRDModeReceiveSeverHttpPortNo.showEnable( False );
	} else {
		Key_GoToRDModeReceiveSeverHttpPortNo.showEnable( True );
	}
}
