//================================================================================================.
// 概要    :共通_CS Remote Analysisサーバ設定・１０キー入力共通 : コンストラクタ.
//================================================================================================.
PServiceCSRemoteAnalysis10KeyInputcom::PServiceCSRemoteAnalysis10KeyInputcom( PDisplayParts** partsTable, short partsNumber, Bool isNoWarning )
	 : PServiceCSRemoteAnalysisFuncCom( partsTable, partsNumber, isNoWarning )
{
	m_us_MaxValue		= 0;
	m_us_MinValue		= 0;
	m_us_LocalValue		= 0;
	m_bl_Direct			= False;
	m_bl_Fixed			= False;
	m_Inp_10KeyInput	= NULL;
	m_Btx_10KeyInput	= NULL;
}
//================================================================================================.
// 概要    :共通_CS Remote Analysisサーバ設定・１０キー入力共通 : 画面開始処理.
// 備考    :PServiceRDModeNt10KeyInputcom::startGamen()の流用.
//================================================================================================.
void PServiceCSRemoteAnalysis10KeyInputcom::startGamen()
{
	PBasicMessageProc::startGamen();

	m_bl_Direct = True;		// ダイレクト入力ON.
	m_bl_Fixed  = True;		// 確定フラグON.

	// パーツ表示制御.
	CheckShowParts();
}
//================================================================================================.
// 概要    :共通_CS Remote Analysisサーバ設定・１０キー入力共通 : 表示部品のセットアップ.
// 備考    :PServiceRDModeNt10KeyInputcom::setupGamen()の流用.
//================================================================================================.
void PServiceCSRemoteAnalysis10KeyInputcom::setupGamen( short ss_option )
{
	PServiceCSRemoteAnalysisFuncCom::setupGamen( ss_option );
	m_Inp_10KeyInput->set( static_cast<float>(m_us_LocalValue), m_bl_Fixed );
	m_Btx_10KeyInput->show();
}
//================================================================================================.
// 概要    :共通_CS Remote Analysisサーバ設定・１０キー入力共通 : クリアキー押下処理.
// 備考    :PServiceRDModeNt10KeyInputcom::procClear()の流用.
//================================================================================================.
void PServiceCSRemoteAnalysis10KeyInputcom::procClear( uchar uc_option )
{
	m_us_LocalValue	= 0;		// 現在値.
	m_bl_Direct		= True;		// ダイレクト入力ON.
	m_bl_Fixed		= False;	// 確定フラグOFF.
	setupGamen();
}
//================================================================================================.
// 概要    :共通_CS Remote Analysisサーバ設定・１０キー入力共通 : テンキー押下処理.
// 備考    :PServiceRDModeNt10KeyInputcom::proc10Key()の流用.
//================================================================================================.
void PServiceCSRemoteAnalysis10KeyInputcom::proc10Key( uchar uc_option )
{
	if( ( True == m_bl_Direct ) && ( 0 == uc_option ) ) {	// 最初入力が０を押されたら．
		if( 0 == m_us_LocalValue )  {
			if( 0 == m_us_MinValue ) {
				m_bl_Fixed  = True;
			}
			else {
				setBuzzerType( PCGE_BuzzerType_InputNg );
			}
			return;
		} else {
			setBuzzerType( PCGE_BuzzerType_InputNg );
		}
	}

	Bool bl_Error = False;
	m_us_LocalValue = static_cast<ushort>(proc10KeyInput( m_us_LocalValue, m_us_MaxValue, uc_option, m_bl_Direct, EP_InputMaxLimitPattern_Refuse, &bl_Error ));
	if( True == bl_Error ) {
		setBuzzerType( PCGE_BuzzerType_InputNg );
	}
	m_bl_Direct = False;
	m_bl_Fixed  = False;	// 確定フラグOFF.
	setupGamen();
}

//================================================================================================.
// 概要    :zcB0012150_CS Remote Analysis／サーバー設定／ポート番号 : 画面開始処理.
//================================================================================================.
void PServiceCSRemoteAnalysisPortNumber::startGamen()
{
	PServiceCSRemoteAnalysis10KeyInputcom::startGamen();	// 親クラスをコール.

	m_us_MaxValue   = 65535;	// 最大入力値.
	m_us_MinValue   = 1;		// 最小入力値.

	// データクラスからﾎﾟｰﾄ番号を取得.
	m_us_LocalValue = m_pc_SettingInfo->getCSRemoteAnalysisSettingServerPortNumber();

	m_Inp_10KeyInput = &Nfd_ServiceCSRemoteAnalysisPortNumber;
	m_Btx_10KeyInput = &Btx_ServiceCSRemoteAnalysisPortNumber;
}
//================================================================================================.
// 概要    :zcB0012150_CS Remote Analysis／サーバー設定／ポート番号 : OKキー押下処理.
//================================================================================================.
void PServiceCSRemoteAnalysisPortNumber::procOk( uchar uc_option )
{
	if( ( m_us_LocalValue < m_us_MinValue ) || ( m_us_MaxValue < m_us_LocalValue ) ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );	// ブザー音セット.
		return;
	}
	setRegistData(); // データ登録処理.
	PServiceCSRemoteAnalysis10KeyInputcom::procOk( uc_option );	// 親クラスをコール.
}
//================================================================================================.
// 概要    :zcB0012150_CS Remote Analysis／サーバー設定／ポート番号 : 画面遷移処理.
//================================================================================================.
void PServiceCSRemoteAnalysisPortNumber::procGoToPage( uchar uc_option )
{
	if( ( m_us_LocalValue < m_us_MinValue ) || ( m_us_MaxValue < m_us_LocalValue ) ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );	// ブザー音セット.
		return;
	}
	setRegistData(); // データ登録処理.
	PServiceCSRemoteAnalysis10KeyInputcom::procGoToPage( uc_option );	// 親クラスをコール.
}
//================================================================================================.
// 概要    :zcB0012150_CS Remote Analysis／サーバー設定／ポート番号 : インデックスキー押下処理.
//================================================================================================.
void PServiceCSRemoteAnalysisPortNumber::procIndexButton( uchar uc_option )
{
	if( ( m_us_LocalValue < m_us_MinValue ) || ( m_us_MaxValue < m_us_LocalValue ) ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );	// ブザー音セット.
		return;
	}
	setRegistData(); // データ登録処理.
	PServiceCSRemoteAnalysis10KeyInputcom::procIndexButton( uc_option );	// 親クラスをコール.
}
