//================================================================================================.
void PServiceCSRemoteAnalysisPortNumber::setRegistData()
{
	// データクラスにﾎﾟｰﾄ番号を設定.
	m_pc_SettingInfo->setCSRemoteAnalysisSettingServerPortNumber( m_us_LocalValue );
}

// comment 2017/06/12 [MAv5-1]RQ-710 CSRA接続機能追加 日立 森本郁.
//================================================================================================.
// 概要    :zcB0012170_CS Remote Analysis／販社コード : コンストラクタ.
//================================================================================================.
PServiceCSRemoteAnalysisSalesCompanyCode::PServiceCSRemoteAnalysisSalesCompanyCode( PDisplayParts** partsTable, short partsNumber, Bool isNoWarning )
	 : PServiceCSRemoteAnalysisFuncCom( partsTable, partsNumber, isNoWarning )
{
	m_us_SalesCompanyCode		= 0;
	m_uc_SalesCompanyCodeDigit	= PNLD_ServiceCSRASalesCompanyCode_0_DIGIT;
	m_bl_SalesCompanyCodeFixed	= False;
}
//================================================================================================.
// 概要    :zcB0012170_CS Remote Analysis／販社コード : 画面開始処理.
//================================================================================================.
void PServiceCSRemoteAnalysisSalesCompanyCode::startGamen()
{
	// 親クラスをコール.
	PServiceCSRemoteAnalysisFuncCom::startGamen();
	
	// データクラスから設定値を取得.
	m_us_SalesCompanyCode = m_pc_SettingInfo->getCSRemoteAnalysisSettingSalesCompanyCode();
// comment 2020/09/29 HCL_Hemachander [RQ-776] Addition of CWH 1-way communication method.
	uchar uc_SalesCompanyCode[4] = {0};													// ﾎﾟｰﾄ番号表示用.
// comment 2020/10/09 HCL_Hemachander [RQ-776] Function Version Check Removal.
//	if( ( True == PLBC_FuncVersionCheck::isOK_IT6_Type2()) 
//		&& ( PNLE_CSRAEnableOneWay == m_pc_SettingInfo->getCSRemoteAnalysisSettingEnableOneTwoWay() )  ) {
// Comment 2021/10/14 FPT-LinhNV46【IT6_2.2_MR1】【制御構成変更_No.38】RQ-776 CWH 1-way通信　BCN対応.
	if( PNLE_CSRAEnableOneWay == m_pc_SettingInfo->getCSRemoteAnalysisSettingEnableOneTwoWay()
		|| PNLE_CSRAEnableOneWay_CN == m_pc_SettingInfo->getCSRemoteAnalysisSettingEnableOneTwoWay() ) {
		snprintf( reinterpret_cast<char*>(uc_SalesCompanyCode), sizeof(uc_SalesCompanyCode), "%d", m_us_SalesCompanyCode );
		Tfd_ServiceCSRemoteAnalysisSalesCompanyCode.showEnable( True );
		Tfd_ServiceCSRemoteAnalysisSalesCompanyCode.changeExternalText( uc_SalesCompanyCode );
	} else{
		Tfd_ServiceCSRemoteAnalysisSalesCompanyCode.showEnable( False );
	}
	// 販社ｺｰﾄﾞ桁数・確定状態を初期化.
	if( 0 == m_us_SalesCompanyCode ) {
		m_uc_SalesCompanyCodeDigit = PNLD_ServiceCSRASalesCompanyCode_0_DIGIT;
	} else {
		m_uc_SalesCompanyCodeDigit = PNLD_ServiceCSRASalesCompanyCode_3_DIGIT;
	}
	
	// 画面遷移可能な状態に設定する.
	//   True :		画面遷移可.
	//   False :	画面遷移不可 .
	m_bl_SalesCompanyCodeFixed = True;
}
//================================================================================================.
// 概要    :zcB0012170_CS Remote Analysis／販社コード : 表示部品のセットアップ.
//================================================================================================.
void PServiceCSRemoteAnalysisSalesCompanyCode::setupGamen( short ss_option )
{
	// 親クラスをコール.
	PServiceCSRemoteAnalysisFuncCom::setupGamen( ss_option );
	
	// 販社ｺｰﾄﾞを再描画する.
// comment [MAv5][AR1027095]日立 森本 販社ｺｰﾄﾞを「00X」の形式で入力した場合、最初に「0」が表示されない.
//	if( 0 !=  m_us_SalesCompanyCode ) {
	if( PNLD_ServiceCSRASalesCompanyCode_0_DIGIT !=  m_uc_SalesCompanyCodeDigit ) {
//		// 「0」以外の値が設定されている場合は、現在の設定状態を再描画する.
		// 0桁以外の場合は、現在の設定状態を再描画する.
		Nfd_ServiceCSRemoteAnalysisSalesCompanyCode.showEnable(True);
		Btx_ServiceCSRemoteAnalysisSalesCompanyCode.leftSet( static_cast<float>(m_us_SalesCompanyCode), m_uc_SalesCompanyCodeDigit );
	} else {
		// 設定値が「0」(工場出荷値、クリアキー押下直後)の場合は設定値を表示しない.
		Nfd_ServiceCSRemoteAnalysisSalesCompanyCode.showEnable(False);
	}
// comment 2020/09/22 HCL_Sowndarya [RQ-776] Addition of CWH 1-way communication method.
// Comment 2021/10/14 FPT-LinhNV46【IT6_2.2_MR1】【制御構成変更_No.38】RQ-776 CWH 1-way通信　BCN対応.
	if( PNLE_CSRAEnableOneWay == m_pc_SettingInfo->getCSRemoteAnalysisSettingEnableOneTwoWay()
		|| PNLE_CSRAEnableOneWay_CN == m_pc_SettingInfo->getCSRemoteAnalysisSettingEnableOneTwoWay() ) {
		Txt_ServiceCSRemoteAnalysisSalesCompanyCode_Range.showEnable( False );
		Btx_ServiceCSRemoteAnalysisSalesCompanyCode.showEnable( False );
	} else {
		Txt_ServiceCSRemoteAnalysisSalesCompanyCode_Range.showEnable( True );
		Btx_ServiceCSRemoteAnalysisSalesCompanyCode.showEnable( True );
	}

}
