// 概要    :zcB0012170_CS Remote Analysis／販社コード : クリアキー押下処理.
//================================================================================================.
void PServiceCSRemoteAnalysisSalesCompanyCode::procClear( uchar uc_option )
{
// comment 2020/09/29 HCL_Hemachander [RQ-776] Addition of CWH 1-way communication method.
// Comment 2021/10/14 FPT-LinhNV46【IT6_2.2_MR1】【制御構成変更_No.38】RQ-776 CWH 1-way通信　BCN対応.
	if( PNLE_CSRAEnableOneWay == m_pc_SettingInfo->getCSRemoteAnalysisSettingEnableOneTwoWay()
		|| PNLE_CSRAEnableOneWay_CN == m_pc_SettingInfo->getCSRemoteAnalysisSettingEnableOneTwoWay() ) {
		setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}
	m_us_SalesCompanyCode		= 0;
	m_uc_SalesCompanyCodeDigit	= PNLD_ServiceCSRASalesCompanyCode_0_DIGIT;
	// 画面遷移可能な状態に設定する.
	//   True :		画面遷移可.
	//   False :	画面遷移不可 .
	m_bl_SalesCompanyCodeFixed	= True;
	
	// データクラス設定値を更新.
	m_pc_SettingInfo->setCSRemoteAnalysisSettingSalesCompanyCode( m_us_SalesCompanyCode );
	
	// 画面を再描画.
	setupGamen(uc_option);
}
//================================================================================================.
// 概要    :zcB0012170_CS Remote Analysis／販社コード : テンキー押下処理.
//================================================================================================.
void PServiceCSRemoteAnalysisSalesCompanyCode::proc10Key( uchar uc_option )
{
	// 販社ｺｰﾄﾞが確定状態なら、データクラス設定値を更新.
// comment 2020/09/29 HCL_Hemachander [RQ-776] Addition of CWH 1-way communication method.
// Comment 2021/10/14 FPT-LinhNV46【IT6_2.2_MR1】【制御構成変更_No.38】RQ-776 CWH 1-way通信　BCN対応.
	if( PNLE_CSRAEnableOneWay == m_pc_SettingInfo->getCSRemoteAnalysisSettingEnableOneTwoWay()
		|| PNLE_CSRAEnableOneWay_CN == m_pc_SettingInfo->getCSRemoteAnalysisSettingEnableOneTwoWay() ) {
		setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}
	if( True == InputCheck( uc_option ) ) {
		if( True == m_bl_SalesCompanyCodeFixed ) {
			m_pc_SettingInfo->setCSRemoteAnalysisSettingSalesCompanyCode( m_us_SalesCompanyCode );
		}
	}
	
	// 画面を再描画.
	setupGamen(uc_option);
}
//================================================================================================.
// 概要    :zcB0012170_CS Remote Analysis／販社コード : 数値入力チェック処理.
//================================================================================================.
Bool PServiceCSRemoteAnalysisSalesCompanyCode::InputCheck( uchar uc_option )
{
	ushort	us_result = 0;
	uchar	uc_digit = 0;
	
	// 既に3桁入力済みの場合は拒否音鳴動.
	if( PNLD_ServiceCSRASalesCompanyCode_3_DIGIT == m_uc_SalesCompanyCodeDigit ) {
		setBuzzerType( PCGE_BuzzerType_InputNg );
		return False;
	}
	
	us_result = ( m_us_SalesCompanyCode * 10 ) + uc_option;
	uc_digit = m_uc_SalesCompanyCodeDigit;
	uc_digit = uc_digit + 1;
	
	// 入力を受け付けた結果、入力桁数が3桁に到達した場合は販社ｺｰﾄﾞは確定.
	if( PNLD_ServiceCSRASalesCompanyCode_3_DIGIT == uc_digit ) {
		// 入力範囲チェック(この時点で最大値を超えるケースはないが念のため).
		if( ( TYPD_CSRASetting_SalesCompanyID_Min > us_result ) ||
			( TYPD_CSRASetting_SalesCompanyID_Max < us_result ) ) {
			setBuzzerType( PCGE_BuzzerType_InputNg );
			return False;
		} else {
			// 入力受付けたため、販社ｺｰﾄﾞの入力情報を更新(3桁なので確定状態).
			m_us_SalesCompanyCode		=	us_result;
			m_uc_SalesCompanyCodeDigit	=	uc_digit;
			m_bl_SalesCompanyCodeFixed	=	True;
		}
	} else {
		// 入力受付けたため、販社ｺｰﾄﾞの入力情報を更新(3桁未満の場合は未確定状態).
		m_us_SalesCompanyCode 		=	us_result;
		m_uc_SalesCompanyCodeDigit	=	uc_digit;
		m_bl_SalesCompanyCodeFixed	= 	False;
	}
	
	return True;
}

uint32_t PServiceCSRemoteAnalysisConnectionCheck::m_ui_ResultCode = 0;		// 接続確認結果.
//================================================================================================.
// 概要    :zcB0012160_CS Remote Analysis／接続確認 : コンストラクタ.
//================================================================================================.
PServiceCSRemoteAnalysisConnectionCheck::PServiceCSRemoteAnalysisConnectionCheck( PDisplayParts** partsTable, short partsNumber, Bool isNoWarning )
	 : PServiceCSRemoteAnalysisFuncCom( partsTable, partsNumber, isNoWarning )
{
	m_bl_SerialNo		= False;
	m_e_ConnectCheckSts	= PNLE_CSRemoteAnalysisConnctionCheckSts_None;
	m_ui_ResultCode		= 0;
	m_bl_StsToggle		= True;
// comment 2017/07/24 日立 田中 [MAv5-1][RQ-710] CSRA接続 販社設定追加対応.
	memset( m_sc_SalesCompanyName, 0, sizeof( m_sc_SalesCompanyName ) );
}
//================================================================================================.
// 概要    :zcB0012160_CS Remote Analysis／接続確認 : 画面開始処理.
//================================================================================================.
void PServiceCSRemoteAnalysisConnectionCheck::startGamen()
{
	uchar	uc_MachineID[ DEF_SizeRDMachineID + 1] = { '\0' };		// マシンID.
	Bool	bl_AllZeroMachineID = True;								// マシンIDオール0フラグ.

	PServiceCSRemoteAnalysisFuncCom::startGamen();					// 親クラスをコール.

	PnlComGetRdsSetting()->getMachineID( uc_MachineID );			// マシンID取得.
	// マシンIDオール0チェック.
	for( short i = 0; i < DEF_SizeRDMachineID; i++ ) {
		if( '0' != uc_MachineID[ i ] ) {
			bl_AllZeroMachineID = False;	// オール０でない.
		}
	}
	if( ( DEF_SizeRDMachineID != strlen( reinterpret_cast<char*>(uc_MachineID) ) ) || ( True == bl_AllZeroMachineID ) ) {
		// シリアル番号が13桁設定されていない、または、オール0(初期値)の場合.
		m_bl_SerialNo = False;	// シリアル番号未設定.
	} else {
		// シリアル番号が13桁設定されている.
		m_bl_SerialNo = True;	// シリアル番号設定済み.
	}

	m_e_ConnectCheckSts = PNLE_CSRemoteAnalysisConnctionCheckSts_None;	// 接続確認実行状態：「未実施」に設定.
	m_bl_StsToggle		= True;											// 進行状態表示トグルの初期化.
}
//================================================================================================.
// 概要    :zcB0012160_CS Remote Analysis／接続確認 : 表示部品のセットアップ.
//================================================================================================.
void PServiceCSRemoteAnalysisConnectionCheck::setupGamen( short ss_option )
{
	uchar uc_UrlAddDisp[ TYPD_CSRASetting_ServerInfo_AddressMaxLen + 6 ];			// URLｱﾄﾞﾚｽ表示用.
	memset( uc_UrlAddDisp, 0, sizeof( uc_UrlAddDisp ) );
	setupInputString( 6, DEF_SizeRDMail2_LineMax_Transmission, m_pc_SettingInfo->getCSRemoteAnalysisSettingServerUrlAddress(), reinterpret_cast<char*>(uc_UrlAddDisp), 0, EP_CharSet_USASCII );	// 6行にする.
	Tfd_ServiceCSRAConnectionCheckUrlAdd.changeExternalText( uc_UrlAddDisp );		// URLｱﾄﾞﾚｽ表示.

	uchar uc_AccountDisp[ TYPD_CSRASetting_ServerInfo_UserNameMaxLen + 6 ];			// ｱｶｳﾝﾄ表示用.
	memset( uc_AccountDisp, 0, sizeof( uc_AccountDisp ) );
	setupInputString( 2, DEF_SizeRDMail2_LineMax_Transmission, m_pc_SettingInfo->getCSRemoteAnalysisSettingServerAccount(), reinterpret_cast<char*>(uc_AccountDisp), 0, EP_CharSet_USASCII );	// 2行にする.
	Tfd_ServiceCSRAConnectionCheckAccount.changeExternalText( uc_AccountDisp );		// ｱｶｳﾝﾄ表示.

	uchar uc_PortNumDisp[6] = {0};													// ﾎﾟｰﾄ番号表示用.
	snprintf( reinterpret_cast<char*>(uc_PortNumDisp), sizeof(uc_PortNumDisp), "%d", m_pc_SettingInfo->getCSRemoteAnalysisSettingServerPortNumber() );
	Tfd_ServiceCSRAConnectionCheckPortNumber.changeExternalText( uc_PortNumDisp );	// ﾎﾟｰﾄ番号表示.

	uchar uc_ErrorCode[5] = {0};													// エラーコード表示用.
	if( PNLE_CSRemoteAnalysisConnctionCheckSts_Exec == m_e_ConnectCheckSts ) {
		// 接続確認実行中.
		Key_ServiceCSRAConnectionCheck.select( True );								// キー押下状態.
		// 進行状態表示トグルに応じて表示更新.
		Txt_ServiceCSRAConnectionCheckSlash.changeText( True == m_bl_StsToggle ? s_EXPSlash : s_EXPBackslash );	// 「／」「＼」を交互に表示.
		m_bl_StsToggle = ( ( True == m_bl_StsToggle ) ? False : True );				// 切り替えるためにTrue→False→Trueと変更.
		Txt_ServiceCSRAConnectionCheckSlash.showEnable( True );						// 実行中記号「／」表示.
		Txt_SRdsMessage.changeText( s_MSGServiceConnected );						// 通信中.
		Tfd_SRdsStatusNo.showEnable( False );										// エラーコード非表示.
// comment 2017/07/24 日立 田中 [MAv5-1][RQ-710] CSRA接続 販社設定追加対応.
		Tfd_ServiceCSRAConnectionCheckSalesCompanyName.showEnable( False );			// 販社名非表示.
	} else {
		// 接続確認未実施.
		Key_ServiceCSRAConnectionCheck.select( False );								// キー未押下.
		Txt_ServiceCSRAConnectionCheckSlash.showEnable( False );					// 実行中記号「／」非表示.
		if( PNLE_CSRemoteAnalysisConnctionCheckSts_Comp == m_e_ConnectCheckSts ) {
			// 接続確認完了時は結果を表示.
			if( 0 == m_ui_ResultCode ) {
				// 接続確認成功.
				Txt_SRdsMessage.changeText( s_MSGServiceEndNormal );				// 正常終了.
				Tfd_SRdsStatusNo.showEnable( False );								// エラーコード非表示.
			} else {
				// 接続確認失敗.
				snprintf( reinterpret_cast<char*>(uc_ErrorCode), sizeof( uc_ErrorCode ), "%04X", m_ui_ResultCode );
				Txt_SRdsMessage.changeText(s_pMSGServiceConnectionError_W288H016I);	// ｻｰﾊﾞｰとの通信異常.
				Tfd_SRdsStatusNo.changeASCIIText( uc_ErrorCode );					// エラーコード4桁.
				Tfd_SRdsStatusNo.showEnable( True );								// エラーコード表示.
			}
// comment 2017/07/24 日立 田中 [MAv5-1][RQ-710] CSRA接続 販社設定追加対応.
			Tfd_ServiceCSRAConnectionCheckSalesCompanyName.changeExternalText( reinterpret_cast<uchar*>(m_sc_SalesCompanyName) );
			Tfd_ServiceCSRAConnectionCheckSalesCompanyName.showEnable( True );		// 販社名表示.
		} else {
			Txt_SRdsMessage.changeText( s_MessageBlank );							// 表示なし.
			Tfd_SRdsStatusNo.showEnable( False );									// エラーコード非表示.
// comment 2017/07/24 日立 田中 [MAv5-1][RQ-710] CSRA接続 販社設定追加対応.
			Tfd_ServiceCSRAConnectionCheckSalesCompanyName.showEnable( False );		// 販社名非表示.
		}
	}
	Key_ServiceCSRAConnectionCheck.showEnable( m_bl_SerialNo );						// 接続確認キー.
	
// comment 2020/09/29 HCL_Hemachander [RQ-776] Addition of CWH 1-way communication method.
// comment 2020/10/09 HCL_Sowndarya [RQ-776] Check Connection key hidden for One-way.
//	if( PNLE_CSRAEnableOneWay == m_pc_SettingInfo->getCSRemoteAnalysisSettingEnableOneTwoWay()) {
//		Txt_ServiceCSRAConnectionCheckPortNumber.showEnable( False );
//		Txt_ServiceCSRAConnectionCheckSalesCompanyName.showEnable( False );
//		Tfd_ServiceCSRAConnectionCheckSalesCompanyName.showEnable(  False );
//		Tfd_ServiceCSRAConnectionCheckPortNumber.showEnable( False );
//		Gra_ServiceCSRAConnectionCheckLine3.showEnable( False );
//		Gra_ServiceCSRAConnectionCheckLine4.showEnable( False );
//	} else {
//		Txt_ServiceCSRAConnectionCheckPortNumber.showEnable( True );
//		Txt_ServiceCSRAConnectionCheckSalesCompanyName.showEnable( True );
//		Tfd_ServiceCSRAConnectionCheckSalesCompanyName.showEnable(  True );
//		Tfd_ServiceCSRAConnectionCheckPortNumber.showEnable( True );
//		Gra_ServiceCSRAConnectionCheckLine3.showEnable( True );
//		Gra_ServiceCSRAConnectionCheckLine4.showEnable( True );
//	}
	
	PServiceCSRemoteAnalysisFuncCom::setupGamen( ss_option );						// 親クラスをコール.
}
