//================================================================================================.
// 概要    :zcB0012160_CS Remote Analysis／接続確認 : キー押下処理.
//================================================================================================.
void PServiceCSRemoteAnalysisConnectionCheck::procButtonOn( uchar uc_option )
{
	APIC_Csra *pc_Csra = APIC_Csra::newInstance();
	if( NULL == pc_Csra ) {
		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
		if( NULL != pc_BFW_System ) {
			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19000A01004E0701 );
		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" ); 
		return;
	}
	if( PNLE_CSRemoteAnalysisConnctionCheckSts_Exec == m_e_ConnectCheckSts ) {
	 	// 拒否音を鳴動.
		setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}

	PServiceCSRemoteAnalysisFuncCom::procButtonOn( uc_option );	// 親クラスをコール.

	switch( uc_option ) {
		case BTNID_KEY_ServiceCSRAConnectionCheck:
			m_ui_ResultCode		= 0;											// 接続確認結果初期化.
			m_e_ConnectCheckSts	= PNLE_CSRemoteAnalysisConnctionCheckSts_Exec;	// 接続確認実行中.
			pc_Csra->requestCsraConnectCheck( ans_requestCsraConnectCheck );	// 接続確認実施.
			break;
		default:	break;
	}
	setupGamen( uc_option );
}
