void PServiceCSRemoteAnalysisConnectionCheck::procCallBack( TYPE_PNL_CallBack e_option )
{
// comment 2017/07/24 日立 田中 [MAv5-1][RQ-710] CSRA接続 販社設定追加対応.
	APIC_CSRASetting *pc_CSRASetting = APIC_CSRASetting::newInstance();
	if( NULL == pc_CSRASetting ) {
		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
		if( NULL != pc_BFW_System ) {
			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19006901004E0801 );
		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" ); 
		return;
	}

	if( TYPE_PNL_CallBack_CsraConnectionCheck == e_option ) {
		m_e_ConnectCheckSts = PNLE_CSRemoteAnalysisConnctionCheckSts_Comp;	// 接続確認完了.

		memset( m_sc_SalesCompanyName, 0, sizeof( m_sc_SalesCompanyName ) );
		// 販社名を取得する.
		pc_CSRASetting->getSalesCompanyName( m_sc_SalesCompanyName );
	}
}
