//================================================================================================.
// 概要    :共通_CS Remote Analysis／送信設定共通 : 画面開始処理.
//================================================================================================.
void PServiceCSRemoteAnalysisSendSettingCom::startGamen()
{
	PServiceNoFunctionCodeCom::startGamen();	// 親クラスをコール.
	
	// メニューからの遷移の場合.
	if( True == m_bl_FromMenu ){
		m_pc_SettingInfo->loadCSRemoteAnalysisSendSetting();								// CommonAPIから設定値を取得.
// comment 2020/09/29 HCL_Hemachander [RQ-776] Addition of CWH 1-way communication method.
// Comment 2021/10/14 FPT-LinhNV46【IT6_2.2_MR1】【制御構成変更_No.38】RQ-776 CWH 1-way通信　BCN対応.
	if( PNLE_CSRAEnableOneWay == m_pc_SettingInfo->getCSRemoteAnalysisSettingEnableOneTwoWay()
		||  PNLE_CSRAEnableOneWay_CN == m_pc_SettingInfo->getCSRemoteAnalysisSettingEnableOneTwoWay() ) {
		m_e_ExtServerCSRASendSettingShow = PNLE_ServiceCSRASendSetting_ScheduleSetting;		// 表示中画面を「ｽｹｼﾞｭｰﾙ更新」画面に設定.
	}else{
		m_e_ExtServerCSRASendSettingShow = PNLE_ServiceCSRASendSetting_ScheduleUpdate;		// 表示中画面を「ｽｹｼﾞｭｰﾙ更新」画面に設定.
	}
		m_bl_FromMenu = False;																// 画面遷移元フラグ(メニューからの遷移)を初期化.
	}
}
//================================================================================================.
// 概要    :共通_CS Remote Analysis／送信設定共通 : 表示部品のセットアップ.
//================================================================================================.
void PServiceCSRemoteAnalysisSendSettingCom::setupGamen( short ss_option )
{
	PServiceNoFunctionCodeCom::setupGamen( ss_option );	// 親クラスをコール.

	switch( m_e_ExtServerCSRASendSettingShow ) {
		case PNLE_ServiceCSRASendSetting_ScheduleUpdate:	Rbt_ServiceCSRASendSetting_Setting.select( 0 );		break;		// ｽｹｼﾞｭｰﾙ更新.
		case PNLE_ServiceCSRASendSetting_ScheduleSetting:	Rbt_ServiceCSRASendSetting_Setting.select( 1 );		break;		// ｽｹｼﾞｭｰﾙ設定.
		case PNLE_ServiceCSRASendSetting_PrecheckTime:		Rbt_ServiceCSRASendSetting_Setting.select( 2 );		break;		// 時刻指定.
		case PNLE_ServiceCSRASendSetting_TimeoutSetting:	Rbt_ServiceCSRASendSetting_Setting.select( 3 );		break;		// ﾀｲﾑｱｳﾄ設定.
		default:																								break;
		}
// comment 2020/09/29 HCL_Hemachander [RQ-776] Addition of CWH 1-way communication method.
// Comment 2021/10/14 FPT-LinhNV46【IT6_2.2_MR1】【制御構成変更_No.38】RQ-776 CWH 1-way通信　BCN対応.
	if( PNLE_CSRAEnableOneWay == m_pc_SettingInfo->getCSRemoteAnalysisSettingEnableOneTwoWay() 
		|| PNLE_CSRAEnableOneWay_CN == m_pc_SettingInfo->getCSRemoteAnalysisSettingEnableOneTwoWay() ) {
		Key_ServiceCSRASendSetting_ScheduleUpdate.showEnable( False );
		Key_ServiceCSRASendSetting_PrecheckTime.showEnable( False );
	} else {
		Key_ServiceCSRASendSetting_ScheduleUpdate.showEnable( True );
		Key_ServiceCSRASendSetting_PrecheckTime.showEnable( True );
	}
}
