			m_e_ExtServerCSRASendSettingShow = PNLE_ServiceCSRASendSetting_ScheduleSetting;
			nextGamen = &gp_ServiceCSRemoteAnalysisSendScheduleSetting;			// zcB0012210_CS Remote Analysis／送信設定／スケジュール設定.
