//================================================================================================.
// 概要    :共通_CS Remote Analysis／送信設定共通 : 数値入力チェック処理.
//================================================================================================.
void PServiceCSRemoteAnalysisSendSettingCom::inputDigit( const uchar uc_option, RDModeSettingRangeShort* pst_source )
{
	short ss_result = 0;
 	if( 1 > pst_source->nowDigit ) {													// 現在の桁数が0,-1のとき.
 		if( ( pst_source->min <= uc_option ) && ( uc_option <= pst_source->max ) ) {
 			pst_source->nowDigit = 1;													// 桁数を1にして.
 			pst_source->nowValue = uc_option;											// 入力数値を入れる.
 			pst_source->fixed = True;													// 数値を確定する.
 		} else {
 			setBuzzerType( PCGE_BuzzerType_InputNg );
 		}
 	} else if( pst_source->nowDigit != calcDigit( pst_source->max ) ) {
 		ss_result = pst_source->nowValue * 10 + uc_option;
 		if( ( pst_source->min <= ss_result ) && ( ss_result <= pst_source->max ) ) {
 			pst_source->nowDigit++;
 			pst_source->nowValue = ss_result;
 			pst_source->fixed = True;													// 数値を確定する.
 		} else {
 			setBuzzerType( PCGE_BuzzerType_InputNg );
 		}
 	} else {
 		setBuzzerType( PCGE_BuzzerType_InputNg );
 	}
}

