PServiceCSRemoteAnalysisSendScheduleSetting::PServiceCSRemoteAnalysisSendScheduleSetting( PDisplayParts** partsTable, short partsNumber, Bool isNoWarning )
	 : PServiceCSRemoteAnalysisSendSettingCom( partsTable, partsNumber, isNoWarning )
{
	m_e_SelectedDayKey = PNLE_ServiceCSRAScheduleSettingDaySelect_Schedule1;
	initSettingRangeInfo();
}
//================================================================================================.
// 概要    :zcB0012210_CS Remote Analysis／送信設定／スケジュール設定 : 画面開始処理.
//================================================================================================.
void PServiceCSRemoteAnalysisSendScheduleSetting::startGamen()
{
	// 親クラスの処理実行.
	PServiceCSRemoteAnalysisSendSettingCom::startGamen();
	// 日キーの選択状態をｽｹｼﾞｭｰﾙ1 日周期 日キーに設定.
	m_e_SelectedDayKey = PNLE_ServiceCSRAScheduleSettingDaySelect_Schedule1;
	// ｽｹｼﾞｭｰﾙ1 日周期／ｽｹｼﾞｭｰﾙ3(毎月) 日付指定の入力範囲情報初期化.
// comment 2020/09/22 HCL_Sowndarya [RQ-776] Addition of CWH 1-way communication method.
// comment 2020/10/09 HCL_Hemachander [RQ-776] Function Version Check Removal.
//	if( ( True == PLBC_FuncVersionCheck::isOK_IT6_Type2()) 
//		&& ( PNLE_CSRAEnableOneWay == m_pc_SettingInfo->getCSRemoteAnalysisSettingEnableOneTwoWay() )  ) {
// Comment 2021/10/14 FPT-LinhNV46【IT6_2.2_MR1】【制御構成変更_No.38】RQ-776 CWH 1-way通信　BCN対応.
	if( PNLE_CSRAEnableOneWay == m_pc_SettingInfo->getCSRemoteAnalysisSettingEnableOneTwoWay()
		|| PNLE_CSRAEnableOneWay_CN == m_pc_SettingInfo->getCSRemoteAnalysisSettingEnableOneTwoWay() ) {
        uchar uc_Day[2]={0};
       snprintf( reinterpret_cast<char*>(uc_Day), sizeof(uc_Day), "%d", m_pc_SettingInfo->getScheduleCycleDay() );
		Tfd_ServiceCSRASendSetting_ScheduleSetting_Daily_Cycle.showEnable( True );
		Tfd_ServiceCSRASendSetting_ScheduleSetting_Daily_Cycle.changeExternalText( uc_Day );
	}else{
		Tfd_ServiceCSRASendSetting_ScheduleSetting_Daily_Cycle.showEnable( False );
	}
	initSettingRangeInfo();
}
//================================================================================================.
// 概要    :zcB0012210_CS Remote Analysis／送信設定／スケジュール設定 : 表示部品のセットアップ.
//================================================================================================.
void PServiceCSRemoteAnalysisSendScheduleSetting::setupGamen( short ss_option )
{
	// 親クラスの処理実行.
	PServiceCSRemoteAnalysisSendSettingCom::setupGamen( ss_option );
	
	// 日キーの選択状態を描画.
	Rbt_ServiceCSRASendSetting_ScheduleSetting_Day.select( m_e_SelectedDayKey );
	
	// 曜日指定キーの選択状態描画.
	switch( m_pc_SettingInfo->getScheduleCycleWDay() ) {
		case TYPE_CSRAPrecheckCycleWdat_Sun:	Rbt_ServiceCSRASendSetting_ScheduleSetting_Weekly.select( 0 );	break;	// 日.
		case TYPE_CSRAPrecheckCycleWdat_Mon:	Rbt_ServiceCSRASendSetting_ScheduleSetting_Weekly.select( 1 );	break;	// 月.
		case TYPE_CSRAPrecheckCycleWdat_Tue:	Rbt_ServiceCSRASendSetting_ScheduleSetting_Weekly.select( 2 );	break;	// 火.
		case TYPE_CSRAPrecheckCycleWdat_Wed:	Rbt_ServiceCSRASendSetting_ScheduleSetting_Weekly.select( 3 );	break;	// 水.
		case TYPE_CSRAPrecheckCycleWdat_Thu:	Rbt_ServiceCSRASendSetting_ScheduleSetting_Weekly.select( 4 );	break;	// 木.
		case TYPE_CSRAPrecheckCycleWdat_Fri:	Rbt_ServiceCSRASendSetting_ScheduleSetting_Weekly.select( 5 );	break;	// 金.
		case TYPE_CSRAPrecheckCycleWdat_Sat:	Rbt_ServiceCSRASendSetting_ScheduleSetting_Weekly.select( 6 );	break;	// 土.
		default:																								break;
	}
	
	// ｽｹｼﾞｭｰﾙ1 日周期／ｽｹｼﾞｭｰﾙ3(毎月) 日付指定を設定.
	Btx_ServiceCSRASendSetting_ScheduleSetting_Daily_Cycle.set( static_cast<float>(m_st_DailySettingRangeInfo.nowValue), m_st_DailySettingRangeInfo.fixed, m_st_DailySettingRangeInfo.nowDigit );
	Btx_ServiceCSRASendSetting_ScheduleSetting_Monthly_Cycle.set( static_cast<float>(m_st_MonthlySettingRangeInfo.nowValue), m_st_MonthlySettingRangeInfo.fixed, m_st_MonthlySettingRangeInfo.nowDigit );
	
// comment 2020/09/22 HCL_Sowndarya [RQ-776] Addition of CWH 1-way communication method.
// Comment 2021/10/14 FPT-LinhNV46【IT6_2.2_MR1】【制御構成変更_No.38】RQ-776 CWH 1-way通信　BCN対応.
	if( PNLE_CSRAEnableOneWay == m_pc_SettingInfo->getCSRemoteAnalysisSettingEnableOneTwoWay()
		|| PNLE_CSRAEnableOneWay_CN == m_pc_SettingInfo->getCSRemoteAnalysisSettingEnableOneTwoWay() ) {
		Rbt_ServiceCSRASendSetting_ScheduleSetting_Day.showEnable( False );
		Rbt_ServiceCSRASendSetting_ScheduleSetting_Weekly.showEnable( False );
		Btx_ServiceCSRASendSetting_ScheduleSetting_Daily_Cycle.showEnable( False );
		Btx_ServiceCSRASendSetting_ScheduleSetting_Monthly_Cycle.showEnable( False );
		Txt_ServiceCSRASendSetting_ScheduleSetting_Daily_Range.showEnable( False );
		Txt_ServiceCSRASendSetting_ScheduleSetting_Monthly_Range.showEnable( False );
		Txt_ServiceCSRASendSetting_ScheduleSetting_Weekly.showEnable( False );
		Txt_ServiceCSRASendSetting_ScheduleSetting_Monthly.showEnable( False );
		Txt_ServiceCSRASendSetting_ScheduleSetting_Schedule2.showEnable( False );
		Txt_ServiceCSRASendSetting_ScheduleSetting_Schedule3.showEnable( False );	
	} else {
		Rbt_ServiceCSRASendSetting_ScheduleSetting_Day.showEnable( True );
		Rbt_ServiceCSRASendSetting_ScheduleSetting_Weekly.showEnable( True );
		Btx_ServiceCSRASendSetting_ScheduleSetting_Daily_Cycle.showEnable( True );
		Btx_ServiceCSRASendSetting_ScheduleSetting_Monthly_Cycle.showEnable( True );
		Txt_ServiceCSRASendSetting_ScheduleSetting_Daily_Range.showEnable( True );
		Txt_ServiceCSRASendSetting_ScheduleSetting_Monthly_Range.showEnable( True );
		Txt_ServiceCSRASendSetting_ScheduleSetting_Weekly.showEnable( True );
		Txt_ServiceCSRASendSetting_ScheduleSetting_Monthly.showEnable( True );
		Txt_ServiceCSRASendSetting_ScheduleSetting_Schedule2.showEnable( True );
		Txt_ServiceCSRASendSetting_ScheduleSetting_Schedule3.showEnable( True );	
	}

}
