// 概要    :zcB0012210_CS Remote Analysis／送信設定／スケジュール設定 : OKキー押下処理.
//================================================================================================.
void PServiceCSRemoteAnalysisSendScheduleSetting::procOk( uchar uc_option )
{
	// ｽｹｼﾞｭｰﾙ1 日周期／ｽｹｼﾞｭｰﾙ3(毎月) 日付指定のどちらか一方でも入力不完全な場合は、拒否音を鳴動するのみ.
	if( ( False == m_st_DailySettingRangeInfo.fixed ) || ( False == m_st_MonthlySettingRangeInfo.fixed ) ) {
		setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}
	
	// 親クラスの処理実行.
	PServiceCSRemoteAnalysisSendSettingCom::procOk( uc_option );
}
//================================================================================================.
// 概要    :zcB0012210_CS Remote Analysis／送信設定／スケジュール設定 : キー押下処理.
//================================================================================================.
void PServiceCSRemoteAnalysisSendScheduleSetting::procButtonOn( uchar uc_option )
{
	// 親クラスを呼ぶ.
	PServiceCSRemoteAnalysisSendSettingCom::procButtonOn( uc_option );
	
	switch( uc_option ) {
		case BTNID_KEY_ServiceCSRASend_ScheduleSetting_Daily_Day:	// ｽｹｼﾞｭｰﾙ1 日周期 日キー.
			m_e_SelectedDayKey = PNLE_ServiceCSRAScheduleSettingDaySelect_Schedule1;
			break;
		case BTNID_KEY_ServiceCSRASend_ScheduleSetting_Weekly_Day:	// ｽｹｼﾞｭｰﾙ3(毎月) 日付指定 日キー.
			m_e_SelectedDayKey = PNLE_ServiceCSRAScheduleSettingDaySelect_Schedule3;
			break;
		case BTNID_KEY_ServiceCSRASend_Weekly_WeekdaySun:		// ｽｹｼﾞｭｰﾙ2(毎週) 曜日指定 日キー.
			m_pc_SettingInfo->setScheduleCycleWDay( TYPE_CSRAPrecheckCycleWdat_Sun );
			break;
		case BTNID_KEY_ServiceCSRASend_Weekly_WeekdayMon:		// ｽｹｼﾞｭｰﾙ2(毎週) 曜日指定 月キー.
			m_pc_SettingInfo->setScheduleCycleWDay( TYPE_CSRAPrecheckCycleWdat_Mon );
			break;
		case BTNID_KEY_ServiceCSRASend_Weekly_WeekdayTue:		// ｽｹｼﾞｭｰﾙ2(毎週) 曜日指定 火キー.
			m_pc_SettingInfo->setScheduleCycleWDay( TYPE_CSRAPrecheckCycleWdat_Tue );
			break;
		case BTNID_KEY_ServiceCSRASend_Weekly_WeekdayWed:		// ｽｹｼﾞｭｰﾙ2(毎週) 曜日指定 水キー.
			m_pc_SettingInfo->setScheduleCycleWDay( TYPE_CSRAPrecheckCycleWdat_Wed );
			break;
		case BTNID_KEY_ServiceCSRASend_Weekly_WeekdayThu:		// ｽｹｼﾞｭｰﾙ2(毎週) 曜日指定 木キー.
			m_pc_SettingInfo->setScheduleCycleWDay( TYPE_CSRAPrecheckCycleWdat_Thu );
			break;
		case BTNID_KEY_ServiceCSRASend_Weekly_WeekdayFri:		// ｽｹｼﾞｭｰﾙ2(毎週) 曜日指定 金キー.
			m_pc_SettingInfo->setScheduleCycleWDay( TYPE_CSRAPrecheckCycleWdat_Fri );
			break;
		case BTNID_KEY_ServiceCSRASend_Weekly_WeekdaySat:		// ｽｹｼﾞｭｰﾙ2(毎週) 曜日指定 土キー.
			m_pc_SettingInfo->setScheduleCycleWDay( TYPE_CSRAPrecheckCycleWdat_Sat );
			break;
		default:	break;
	}
	
	// 画面を再描画.
	setupGamen(uc_option);
}
