void PServiceCSRemoteAnalysisSendScheduleSetting::procClear( uchar uc_option )
{
// comment 2020/09/29 HCL_Hemachander [RQ-776] Addition of CWH 1-way communication method.
// Comment 2021/10/14 FPT-LinhNV46【IT6_2.2_MR1】【制御構成変更_No.38】RQ-776 CWH 1-way通信　BCN対応.
	if( PNLE_CSRAEnableOneWay == m_pc_SettingInfo->getCSRemoteAnalysisSettingEnableOneTwoWay()
		|| PNLE_CSRAEnableOneWay_CN == m_pc_SettingInfo->getCSRemoteAnalysisSettingEnableOneTwoWay() ) {
		setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}

	switch( m_e_SelectedDayKey ) {
		case PNLE_ServiceCSRAScheduleSettingDaySelect_Schedule1:	// ｽｹｼﾞｭｰﾙ1 日周期.
			m_st_DailySettingRangeInfo.nowDigit		= PNLD_ServiceCSRASendSetting_notFixed;
			m_st_DailySettingRangeInfo.nowValue		= 0;
			m_st_DailySettingRangeInfo.fixed		= False;
			break;
		case PNLE_ServiceCSRAScheduleSettingDaySelect_Schedule3:	// ｽｹｼﾞｭｰﾙ3(毎月) 日時指定.
			m_st_MonthlySettingRangeInfo.nowDigit	= PNLD_ServiceCSRASendSetting_notFixed;
			m_st_MonthlySettingRangeInfo.nowValue	= 0;
			m_st_MonthlySettingRangeInfo.fixed		= False;
			break;
		default:	break;
	}
	
	// 画面を再描画.
	setupGamen(uc_option);
}
//================================================================================================.
// 概要    :zcB0012210_CS Remote Analysis／送信設定／スケジュール設定 : テンキー押下処理.
//================================================================================================.
void PServiceCSRemoteAnalysisSendScheduleSetting::proc10Key( uchar uc_option )
{
// comment 2020/09/29 HCL_Hemachander [RQ-776] Addition of CWH 1-way communication method.
// Comment 2021/10/14 FPT-LinhNV46【IT6_2.2_MR1】【制御構成変更_No.38】RQ-776 CWH 1-way通信　BCN対応.
	if( PNLE_CSRAEnableOneWay == m_pc_SettingInfo->getCSRemoteAnalysisSettingEnableOneTwoWay()
		|| PNLE_CSRAEnableOneWay_CN == m_pc_SettingInfo->getCSRemoteAnalysisSettingEnableOneTwoWay() ) {
		setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}
	switch( m_e_SelectedDayKey ) {
		case PNLE_ServiceCSRAScheduleSettingDaySelect_Schedule1:	// ｽｹｼﾞｭｰﾙ1 日周期.
			// 入力範囲チェック(範囲外入力時は拒否音鳴動).
			inputDigit( uc_option, &m_st_DailySettingRangeInfo );
			// データクラス設定値を更新.
			m_pc_SettingInfo->setScheduleCycleDay( m_st_DailySettingRangeInfo.nowValue );
			break;
		case PNLE_ServiceCSRAScheduleSettingDaySelect_Schedule3:	// ｽｹｼﾞｭｰﾙ3(毎月) 日時指定.
			// 入力範囲チェック(範囲外入力時は拒否音鳴動).
			inputDigit( uc_option, &m_st_MonthlySettingRangeInfo );
			// データクラス設定値を更新.
			m_pc_SettingInfo->setScheduleCycleMonth( m_st_MonthlySettingRangeInfo.nowValue );
			break;
		default:	break;
	}
	
	// 画面を再描画.
	setupGamen(uc_option);
}
//================================================================================================.
// 概要    :zcB0012210_CS Remote Analysis／送信設定／スケジュール設定 : 入力範囲情報初期化処理.
//================================================================================================.
void PServiceCSRemoteAnalysisSendScheduleSetting::initSettingRangeInfo()
{
	// ｽｹｼﾞｭｰﾙ1 日周期の入力範囲情報設定.
	m_st_DailySettingRangeInfo.maxDigit			= PNLD_ServiceCSRASendSetting_1_DIGIT;					// 最大桁数.
	m_st_DailySettingRangeInfo.min				= TYPD_CSRASetting_CycleDay_Min;						// 最小入力値.
	m_st_DailySettingRangeInfo.max				= TYPD_CSRASetting_CycleDay_Max;						// 最大入力値.
	m_st_DailySettingRangeInfo.nowValue			= m_pc_SettingInfo->getScheduleCycleDay();				// 現在の設定値.
	m_st_DailySettingRangeInfo.nowDigit			= calcDigit( m_st_DailySettingRangeInfo.nowValue );		// 現在の桁数.
	m_st_DailySettingRangeInfo.fixed			= True;													// 数値の確定・不確定フラグ.
	
	// ｽｹｼﾞｭｰﾙ3(毎月) 日付指定の入力範囲情報設定.
	m_st_MonthlySettingRangeInfo.maxDigit		= PNLD_ServiceCSRASendSetting_2_DIGIT;					// 最大桁数.
	m_st_MonthlySettingRangeInfo.min			= TYPD_CSRASetting_CycleMonth_Min;						// 最小入力値.
	m_st_MonthlySettingRangeInfo.max			= TYPD_CSRASetting_CycleMonth_Max;						// 最大入力値.
	m_st_MonthlySettingRangeInfo.nowValue		= m_pc_SettingInfo->getScheduleCycleMonth();			// 現在の設定値.
	m_st_MonthlySettingRangeInfo.nowDigit		= calcDigit( m_st_MonthlySettingRangeInfo.nowValue );	// 現在の桁数.
	m_st_MonthlySettingRangeInfo.fixed			= True;													// 数値の確定・不確定フラグ.
}

//================================================================================================.
// 概要    :zcB0012220_CS Remote Analysis／送信設定／時刻指定 : コンストラクタ.
//================================================================================================.
PServiceCSRemoteAnalysisSendPrecheckTime::PServiceCSRemoteAnalysisSendPrecheckTime( PDisplayParts** partsTable, short partsNumber, Bool isNoWarning )
	 : PServiceCSRemoteAnalysisSendSettingCom( partsTable, partsNumber, isNoWarning )
{
	m_uc_CurrentPageNum = 1;
	m_e_SelectedTimeKey = PNLE_ServiceCSRAPrecheckTimeSelect_Hour;
	initSettingRangeInfo();
}
//================================================================================================.
// 概要    :zcB0012220_CS Remote Analysis／送信設定／時刻指定 : 画面開始処理.
//================================================================================================.
void PServiceCSRemoteAnalysisSendPrecheckTime::startGamen()
{
	// 親クラスの処理実行.
	PServiceCSRemoteAnalysisSendSettingCom::startGamen();
	// 時間帯選択時の現在のページ数を初期化.
	m_uc_CurrentPageNum = 1;
	// 時／分キーの選択状態を時キーに設定.
	m_e_SelectedTimeKey = PNLE_ServiceCSRAPrecheckTimeSelect_Hour;
	// 時／分の入力範囲情報初期化.
	initSettingRangeInfo();
}
//================================================================================================.
// 概要    :zcB0012220_CS Remote Analysis／送信設定／時刻指定 : 表示部品のセットアップ.
//================================================================================================.
void PServiceCSRemoteAnalysisSendPrecheckTime::setupGamen( short ss_option )
{
	// 親クラスの処理実行.
	PServiceCSRemoteAnalysisSendSettingCom::setupGamen( ss_option );
	
	// 時間帯／時刻キーの選択状態.
	Rbt_ServiceCSRASendSetting_PrecheckTime_Setting.select( TYPE_CSRAPrecheckPeriodSetting_Period == m_pc_SettingInfo->getPrecheckPeriodSetting() ? 0 : 1 );
	
	// 時刻指定の各ページ表示処理.
	if( TYPE_CSRAPrecheckPeriodSetting_Period == m_pc_SettingInfo->getPrecheckPeriodSetting() ) {
		if( 1 == m_uc_CurrentPageNum ) {	// 時間帯設定１ページ目表示処理.
			showTimeZoneSetting1P();
		} else {							// 時間帯設定２ページ目表示処理.
			showTimeZoneSetting2P();
		}
	} else {								// 時刻設定表示処理.
		showTimeSetting();
	}
}
//================================================================================================.
// 概要    :zcB0012220_CS Remote Analysis／送信設定／時刻指定 : 時間帯設定１ページ目表示処理.
//================================================================================================.
void PServiceCSRemoteAnalysisSendPrecheckTime::showTimeZoneSetting1P()
{
	Bool bl_OKPeriod_00_03 = False;								// 時間帯：00-03 許可設定取得結果.
	Bool bl_OKPeriod_04_07 = False;								// 時間帯：04-07 許可設定取得結果.
	Bool bl_OKPeriod_08_11 = False;								// 時間帯：08-11 許可設定取得結果.
	
	// 時間帯１ページ目用のパーツ表示制御.
	Grp_ServiceCSRASendSetting_PrecheckTime_TimeZone_1PParts.showEnable( True );
	Grp_ServiceCSRASendSetting_PrecheckTime_TimeZone_2PParts.showEnable( False );
	Grp_ServiceCSRASendSetting_PrecheckTime_TimeZone_PageParts.showEnable( True );
	Grp_ServiceCSRASendSetting_PrecheckTime_TimeParts.showEnable( False );
	
	if( False == m_pc_SettingInfo->getSendingOKPeriod( TYPD_CSRAPrecheck_TimePeriod_Index_00_03, &bl_OKPeriod_00_03 ) ) {
		bl_OKPeriod_00_03 = False;
	}
	if( False == m_pc_SettingInfo->getSendingOKPeriod( TYPD_CSRAPrecheck_TimePeriod_Index_04_07, &bl_OKPeriod_04_07 ) ) {
		bl_OKPeriod_04_07 = False;
	}
	if( False == m_pc_SettingInfo->getSendingOKPeriod( TYPD_CSRAPrecheck_TimePeriod_Index_08_11, &bl_OKPeriod_08_11 ) ) {
		bl_OKPeriod_08_11 = False;
	}
	
	// 時間帯：00:00 - 03:59 開始／終了時分を設定(2桁表示固定).
	Nfd_ServiceCSRASendSetting_PrecheckTime_StartHour[0].set	(  0, True, PNLD_ServiceCSRASendSetting_2_DIGIT );
	Nfd_ServiceCSRASendSetting_PrecheckTime_StartMinute[0].set	(  0, True, PNLD_ServiceCSRASendSetting_2_DIGIT );
	Nfd_ServiceCSRASendSetting_PrecheckTime_EndHour[0].set		(  3, True, PNLD_ServiceCSRASendSetting_2_DIGIT );
	Nfd_ServiceCSRASendSetting_PrecheckTime_EndMinute[0].set	( 59, True, PNLD_ServiceCSRASendSetting_2_DIGIT );
	// 時間帯：04:00 - 07:59 開始／終了時分を設定(2桁表示固定).
	Nfd_ServiceCSRASendSetting_PrecheckTime_StartHour[1].set	(  4, True, PNLD_ServiceCSRASendSetting_2_DIGIT );
	Nfd_ServiceCSRASendSetting_PrecheckTime_StartMinute[1].set	(  0, True, PNLD_ServiceCSRASendSetting_2_DIGIT );
	Nfd_ServiceCSRASendSetting_PrecheckTime_EndHour[1].set		(  7, True, PNLD_ServiceCSRASendSetting_2_DIGIT );
	Nfd_ServiceCSRASendSetting_PrecheckTime_EndMinute[1].set	( 59, True, PNLD_ServiceCSRASendSetting_2_DIGIT );
	// 時間帯：08:00 - 11:59 開始／終了時分を設定(2桁表示固定).
	Nfd_ServiceCSRASendSetting_PrecheckTime_StartHour[2].set	(  8, True, PNLD_ServiceCSRASendSetting_2_DIGIT );
	Nfd_ServiceCSRASendSetting_PrecheckTime_StartMinute[2].set	(  0, True, PNLD_ServiceCSRASendSetting_2_DIGIT );
	Nfd_ServiceCSRASendSetting_PrecheckTime_EndHour[2].set		( 11, True, PNLD_ServiceCSRASendSetting_2_DIGIT );
	Nfd_ServiceCSRASendSetting_PrecheckTime_EndMinute[2].set	( 59, True, PNLD_ServiceCSRASendSetting_2_DIGIT );
	
	// 時間帯：00:00 - 03:59の許可／禁止キー選択状態.
	Rbt_ServiceCSRASendSetting_PrecheckTime_TimeZone_00_03.select( True == bl_OKPeriod_00_03 ? 0 : 1 );
	// 時間帯：04:00 - 07:59の許可／禁止キー選択状態.
	Rbt_ServiceCSRASendSetting_PrecheckTime_TimeZone_04_07.select( True == bl_OKPeriod_04_07 ? 0 : 1 );
	// 時間帯：08:00 - 11:59の許可／禁止キー選択状態.
	Rbt_ServiceCSRASendSetting_PrecheckTime_TimeZone_08_11.select( True == bl_OKPeriod_08_11 ? 0 : 1 );
	
	// ページ数表示処理.
	Nfd_ServiceCSRASendSetting_PrecheckTime_CurrentPageNum = m_uc_CurrentPageNum;
	Nfd_ServiceCSRASendSetting_PrecheckTime_MaxPageNum = PNLD_ServiceCSRAPrecheckTimeZone_MaxPage;
}
//================================================================================================.
// 概要    :zcB0012220_CS Remote Analysis／送信設定／時刻指定 : 時間帯設定２ページ目表示処理.
