	Nfd_ServiceCSRASendSetting_PrecheckTime_EndHour[3].set		( 15, True, PNLD_ServiceCSRASendSetting_2_DIGIT );
	Nfd_ServiceCSRASendSetting_PrecheckTime_EndMinute[3].set	( 59, True, PNLD_ServiceCSRASendSetting_2_DIGIT );
	// 時間帯：16:00 - 19:59 開始／終了時分を設定(2桁表示固定).
	Nfd_ServiceCSRASendSetting_PrecheckTime_StartHour[4].set	( 16, True, PNLD_ServiceCSRASendSetting_2_DIGIT );
	Nfd_ServiceCSRASendSetting_PrecheckTime_StartMinute[4].set	(  0, True, PNLD_ServiceCSRASendSetting_2_DIGIT );
	Nfd_ServiceCSRASendSetting_PrecheckTime_EndHour[4].set		( 19, True, PNLD_ServiceCSRASendSetting_2_DIGIT );
