	// 時間帯：20:00 - 23:59 開始／終了時分を設定(2桁表示固定).
	Nfd_ServiceCSRASendSetting_PrecheckTime_StartHour[5].set	( 20, True, PNLD_ServiceCSRASendSetting_2_DIGIT );
	Nfd_ServiceCSRASendSetting_PrecheckTime_StartMinute[5].set	(  0, True, PNLD_ServiceCSRASendSetting_2_DIGIT );
	Nfd_ServiceCSRASendSetting_PrecheckTime_EndHour[5].set		( 23, True, PNLD_ServiceCSRASendSetting_2_DIGIT );
	Nfd_ServiceCSRASendSetting_PrecheckTime_EndMinute[5].set	( 59, True, PNLD_ServiceCSRASendSetting_2_DIGIT );
	
	// 時間帯：12:00 - 15:59の許可／禁止キー選択状態.
	Rbt_ServiceCSRASendSetting_PrecheckTime_TimeZone_12_15.select( True == bl_OKPeriod_12_15 ? 0 : 1 );
	// 時間帯：16:00 - 19:59の許可／禁止キー選択状態.
	Rbt_ServiceCSRASendSetting_PrecheckTime_TimeZone_16_19.select( True == bl_OKPeriod_16_19 ? 0 : 1 );
