//================================================================================================.
// 概要    :zcB0012230_CS Remote Analysis／送信設定／タイムアウト設定 : 画面開始処理.
//================================================================================================.
void PServiceCSRemoteAnalysisSendTimeoutSetting::startGamen()
{
	// 親クラスの処理実行.
	PServiceCSRemoteAnalysisSendSettingCom::startGamen();
	// ﾀｲﾑｱｳﾄ設定の入力範囲情報初期化.
// comment 2020/09/22 HCL_Sowndarya [RQ-776] Addition of CWH 1-way communication method.
// comment 2020/10/09 HCL_Sowndarya [RQ-776] Function Version Check Removal.
//	if( ( True == PLBC_FuncVersionCheck::isOK_IT6_Type2()) 
//		&& ( PNLE_CSRAEnableOneWay == m_pc_SettingInfo->getCSRemoteAnalysisSettingEnableOneTwoWay() )  ) {
// Comment 2021/10/14 FPT-LinhNV46【IT6_2.2_MR1】【制御構成変更_No.38】RQ-776 CWH 1-way通信　BCN対応.
	if( PNLE_CSRAEnableOneWay == m_pc_SettingInfo->getCSRemoteAnalysisSettingEnableOneTwoWay()
		|| PNLE_CSRAEnableOneWay_CN == m_pc_SettingInfo->getCSRemoteAnalysisSettingEnableOneTwoWay() ) {
		uchar uc_Timeout[3]={0};
		snprintf( reinterpret_cast<char*>(uc_Timeout), sizeof(uc_Timeout), "%d", m_pc_SettingInfo->getTimeoutSetting() );
		Tfd_ServiceCSRASendSetting_TimeoutSetting.showEnable( True );
		Tfd_ServiceCSRASendSetting_TimeoutSetting.changeExternalText( uc_Timeout );
	}else{
		Tfd_ServiceCSRASendSetting_TimeoutSetting.showEnable( False );
	}
	initSettingRangeInfo();
}
//================================================================================================.
// 概要    :zcB0012230_CS Remote Analysis／送信設定／タイムアウト設定 : 表示部品のセットアップ.
//================================================================================================.
void PServiceCSRemoteAnalysisSendTimeoutSetting::setupGamen( short ss_option )
{
	// 親クラスの処理実行.
	PServiceCSRemoteAnalysisSendSettingCom::setupGamen( ss_option );
	
	// ﾀｲﾑｱｳﾄ設定入力値設定.
	Btx_ServiceCSRASendSetting_TimeoutSetting.set( static_cast<float>(m_st_TimeoutSettingRangeInfo.nowValue), m_st_TimeoutSettingRangeInfo.fixed, m_st_TimeoutSettingRangeInfo.nowDigit );
// comment 2020/09/22 HCL_Sowndarya [RQ-776] Addition of CWH 1-way communication method.
// Comment 2021/10/14 FPT-LinhNV46【IT6_2.2_MR1】【制御構成変更_No.38】RQ-776 CWH 1-way通信　BCN対応.
	if( PNLE_CSRAEnableOneWay == m_pc_SettingInfo->getCSRemoteAnalysisSettingEnableOneTwoWay()
		|| PNLE_CSRAEnableOneWay_CN == m_pc_SettingInfo->getCSRemoteAnalysisSettingEnableOneTwoWay() ) {
			Btx_ServiceCSRASendSetting_TimeoutSetting.showEnable( False );
			Txt_ServiceCSRASendSetting_TimeoutSetting_Range.showEnable( False );
	} else {
			Btx_ServiceCSRASendSetting_TimeoutSetting.showEnable( True );
			Txt_ServiceCSRASendSetting_TimeoutSetting_Range.showEnable( True );
	}
	
}
