//================================================================================================.
// 概要    :zcB0012230_CS Remote Analysis／送信設定／タイムアウト設定 : クリアキー押下処理.
//================================================================================================.
void PServiceCSRemoteAnalysisSendTimeoutSetting::procClear( uchar uc_option )
{
// comment 2020/09/29 HCL_Hemachander [RQ-776] Addition of CWH 1-way communication method.
// Comment 2021/10/14 FPT-LinhNV46【IT6_2.2_MR1】【制御構成変更_No.38】RQ-776 CWH 1-way通信　BCN対応.
	if( PNLE_CSRAEnableOneWay == m_pc_SettingInfo->getCSRemoteAnalysisSettingEnableOneTwoWay()
		|| PNLE_CSRAEnableOneWay_CN == m_pc_SettingInfo->getCSRemoteAnalysisSettingEnableOneTwoWay() ) {
		setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}
	m_st_TimeoutSettingRangeInfo.nowDigit		= PNLD_ServiceCSRASendSetting_notFixed;
	m_st_TimeoutSettingRangeInfo.nowValue		= 0;
	m_st_TimeoutSettingRangeInfo.fixed			= False;
	
	// 画面を再描画.
	setupGamen(uc_option);
}
//================================================================================================.
// 概要    :zcB0012230_CS Remote Analysis／送信設定／タイムアウト設定 : テンキー押下処理.
//================================================================================================.
void PServiceCSRemoteAnalysisSendTimeoutSetting::proc10Key( uchar uc_option )
{
	// 入力範囲チェック(範囲外入力時は拒否音鳴動).
// comment 2020/09/29 HCL_Hemachander [RQ-776] Addition of CWH 1-way communication method.
// Comment 2021/10/14 FPT-LinhNV46【IT6_2.2_MR1】【制御構成変更_No.38】RQ-776 CWH 1-way通信　BCN対応.
	if( PNLE_CSRAEnableOneWay == m_pc_SettingInfo->getCSRemoteAnalysisSettingEnableOneTwoWay()
		|| PNLE_CSRAEnableOneWay_CN == m_pc_SettingInfo->getCSRemoteAnalysisSettingEnableOneTwoWay() ) {
		setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}
	inputDigit( uc_option, &m_st_TimeoutSettingRangeInfo );
	
	// データクラス設定値を更新.
	m_pc_SettingInfo->setTimeoutSetting( m_st_TimeoutSettingRangeInfo.nowValue );
	
	// 画面を再描画.
	setupGamen(uc_option);
}
//================================================================================================.
// 概要    :zcB0012230_CS Remote Analysis／送信設定／タイムアウト設定 : 入力範囲情報初期化処理.
//================================================================================================.
void PServiceCSRemoteAnalysisSendTimeoutSetting::initSettingRangeInfo()
{
	// 入力範囲情報の設定.
	m_st_TimeoutSettingRangeInfo.maxDigit		= PNLD_ServiceCSRASendSetting_3_DIGIT;					// 最大桁数.
	m_st_TimeoutSettingRangeInfo.min			= 1;													// 最小入力値.
	m_st_TimeoutSettingRangeInfo.max			= TYPD_CSRASetting_Timeout_Max;							// 最大入力値.
	m_st_TimeoutSettingRangeInfo.nowValue		= m_pc_SettingInfo->getTimeoutSetting();				// 現在の設定値.
	m_st_TimeoutSettingRangeInfo.nowDigit		= calcDigit( m_st_TimeoutSettingRangeInfo.nowValue );	// 現在の桁数.
	m_st_TimeoutSettingRangeInfo.fixed			= True;													// 数値の確定・不確定フラグ.
}
