uint32_t PServiceCSRemoteAnalysisConnectionHistoryOutput::m_ui_ResultCode = 0;		// USB保存結果.
//================================================================================================.
// 概要    :zcB0012300_CS Remote Analysis／通信履歴出力 : コンストラクタ.
//================================================================================================.
PServiceCSRemoteAnalysisConnectionHistoryOutput::PServiceCSRemoteAnalysisConnectionHistoryOutput( PDisplayParts** partsTable, short partsNumber, Bool isNoWarning )
	 : PServiceNoFunctionCodeCom( partsTable, partsNumber, isNoWarning )
{
	m_e_UsbSaveSts	= PNLE_CSRemoteAnalysisUsbSaveSts_None;
	m_ui_ResultCode	= 0;
	m_bl_StsToggle	= True;
}
//================================================================================================.
// 概要    :zcB0012300_CS Remote Analysis／通信履歴出力 : 画面開始処理.
//================================================================================================.
void PServiceCSRemoteAnalysisConnectionHistoryOutput::startGamen()
{
	PServiceNoFunctionCodeCom::startGamen();					// 親クラスをコール.

	m_e_UsbSaveSts	= PNLE_CSRemoteAnalysisUsbSaveSts_None;
	m_ui_ResultCode	= 0;
	m_bl_StsToggle	= True;

}
//================================================================================================.
// 概要    :zcB0012300_CS Remote Analysis／通信履歴出力 : 表示部品のセットアップ.
//================================================================================================.
void PServiceCSRemoteAnalysisConnectionHistoryOutput::setupGamen( short ss_option )
{
	APIC_UsbMemDeviceInfo* pc_UsbMemDeviceInfo = APIC_UsbMemDeviceInfo::newInstance();
	if( NULL == pc_UsbMemDeviceInfo ) {
		LAPC_BFW_System *pc_BFW_System = LAPC_BFW_System::newInstance();
		if ( NULL != pc_BFW_System ) {
			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19006601004E0901 );
		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" );
		return;
	}
	if( TYPD_UsbMemStatusConnect == pc_UsbMemDeviceInfo->getStatus() ) {					// USB装着時.
		Key_ServiceCSRemoteAnalysisUsbSave.showEnable( True );								// USB保存キー表示.
	} else {																				// USB未挿入.
		Key_ServiceCSRemoteAnalysisUsbSave.showEnable( False );								// USB保存キー非表示.
		m_e_UsbSaveSts = PNLE_CSRemoteAnalysisUsbSaveSts_None;								// キー非表示の場合は、ステータスも非表示とする.
	}
	switch( m_e_UsbSaveSts ) {
		case PNLE_CSRemoteAnalysisUsbSaveSts_None:											// USB保存未実施.
			Key_ServiceCSRemoteAnalysisUsbSave.select( False );								// USB保存キー未押下状態.
			Txt_ServiceCSRemoteAnalysisCSVOutputArrow.showEnable( False );					// CSV出力・「→」非表示.
			Txt_ServiceCSRemoteAnalysisCSVOutputStatus.showEnable( False );					// CSV出力・ステータス非表示.
			Txt_ServiceCSRemoteAnalysisCSVOutputSlash.showEnable( False );					// CSV出力・「／」非表示.
			break;
		case PNLE_CSRemoteAnalysisUsbSaveSts_Exec:											// USB保存実行中.
			Key_ServiceCSRemoteAnalysisUsbSave.select( True );								// USB保存キー押下状態.
			Txt_ServiceCSRemoteAnalysisCSVOutputArrow.showEnable( True );					// CSV出力・「→」表示.
			Txt_ServiceCSRemoteAnalysisCSVOutputStatus.changeText( s_ITMServiceSaving );	// 保存中.
			Txt_ServiceCSRemoteAnalysisCSVOutputStatus.showEnable( True );					// CSV出力・ステータス表示.
			Txt_ServiceCSRemoteAnalysisCSVOutputSlash.changeText( True == m_bl_StsToggle ? s_EXPSlash : s_EXPBackslash );	// 「／」「＼」を交互に表示.
			m_bl_StsToggle = ( ( True == m_bl_StsToggle ) ? False : True );					// 切り替えるためにTrue→False→Trueと変更.
			Txt_ServiceCSRemoteAnalysisCSVOutputSlash.showEnable( True );					// CSV出力・「／」表示.
			break;
		case PNLE_CSRemoteAnalysisUsbSaveSts_Comp:											// USB保存完了.
			Key_ServiceCSRemoteAnalysisUsbSave.select( False );								// USB保存キー未押下状態.
			Txt_ServiceCSRemoteAnalysisCSVOutputArrow.showEnable( True );					// CSV出力・「→」表示.
			Txt_ServiceCSRemoteAnalysisCSVOutputStatus.changeText( ( 0 == m_ui_ResultCode ) ? s_OKService : s_NGService );	// OK/NG.
			Txt_ServiceCSRemoteAnalysisCSVOutputStatus.showEnable( True );					// CSV出力・ステータス表示.
			Txt_ServiceCSRemoteAnalysisCSVOutputSlash.showEnable( False );					// CSV出力・「／」非表示.
			break;
		default:	break;
	}

	PServiceNoFunctionCodeCom::setupGamen( ss_option );										// 親クラスをコール.
}
//================================================================================================.
// 概要    :zcB0012300_CS Remote Analysis／通信履歴出力 : OKキー押下処理.
//================================================================================================.
void PServiceCSRemoteAnalysisConnectionHistoryOutput::procOk( uchar uc_option )
{
	if( PNLE_CSRemoteAnalysisUsbSaveSts_Exec == m_e_UsbSaveSts ) {
	 	// 拒否音を鳴動.
		setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}
	nextGamen = &gp_ServiceCSRemoteAnalysisMenu;	// zcB0012000_CS Remote Analysis／メニュー.
}
//================================================================================================.
// 概要    :zcB0012300_CS Remote Analysis／通信履歴出力 : キー押下処理.
//================================================================================================.
void PServiceCSRemoteAnalysisConnectionHistoryOutput::procButtonOn( uchar uc_option )
{
	APIC_Csra *pc_Csra = APIC_Csra::newInstance();
	if( NULL == pc_Csra ) {
		LAPC_BFW_System *pc_BFW_System=LAPC_BFW_System::newInstance();
		if( NULL != pc_BFW_System ) {
			pc_BFW_System->registDetailCode( PNLD_DetailCode_Service_0x19000A01004E0A01 );
		}
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_FATAL, "Assert Failed!" ); 
		return;
	}
	if( PNLE_CSRemoteAnalysisUsbSaveSts_Exec == m_e_UsbSaveSts ) {
	 	// 拒否音を鳴動.
		setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}

	PServiceNoFunctionCodeCom::procButtonOn( uc_option );						// 親クラスをコール.

	switch( uc_option ) {
		case BTNID_KEY_ServiceCSRAUsbSave:
			m_ui_ResultCode	= 0;												// USB保存結果初期化.
			m_e_UsbSaveSts	= PNLE_CSRemoteAnalysisUsbSaveSts_Exec;				// USB保存実行中.
			pc_Csra->saveCsraConnectLogToUSB( ans_saveCsraConnectLogToUSB );	// CSRA通信履歴USB保存を実行.
			break;
		default:	break;
	}
	setupGamen( uc_option );
}
