// 概要    :zcB0012300_CS Remote Analysis／通信履歴出力 : リセットキー押下処理.
//================================================================================================.
void PServiceCSRemoteAnalysisConnectionHistoryOutput::procReset( uchar uc_option )
{
	if( PNLE_CSRemoteAnalysisUsbSaveSts_Exec == m_e_UsbSaveSts ) {
	 	// 拒否音を鳴動.
		setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}
	PServiceNoFunctionCodeCom::procReset( uc_option );	// 親クラスをコール.
}
