//================================================================================================.
//	PServiceRebootInProgress : P0B3000240
//================================================================================================.
void PServiceReboot::procSecond( uchar option )
{
	if( PNLD_EnablerWaitTime >= m_uc_enablerWaitTime ) {
		++m_uc_enablerWaitTime;
	}
	if( PNLD_EnablerWaitTime == m_uc_enablerWaitTime ) {
		APIC_SystemServiceFunction::newInstance()->reboot();
	}
}

