// ===============================================================================================.
/**
 * @name	PServiceOSSUpdate::startGamen().
 * @brief	画面開始処理.
 * @author	2017/03/03 motohashi RQ-676 OSS単独更新	新規作成.
 */
// 2018/11/09 SCD2-Sky Kawanishi [SecV4][EagleH][RQ-676]AR1066658/1066878 結果NG表示追加.
// ===============================================================================================.
void PServiceOSSUpdate::startGamen()
{
	PServiceNoFunctionCodeCom::startGamen();

	APIC_InternetISW*	pc_InternetISW = APIC_InternetISW::newInstance();
	if( NULL == pc_InternetISW ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, 3, "Assert Failed!" ); 
		return;
	}

	m_bl_UpdateStart = False;
	m_bl_UpdateFailured = False;

	// USBチェック初期化.
	static char	sc_FilePath[4][TYPD_MAX_OSSUPDATE_FILE_NAME_SIZE];
	pc_InternetISW->getOSSUpdateFileName( TYPE_RomOSS_OSL, sc_FilePath[0], sizeof( sc_FilePath[0] ) );
	pc_InternetISW->getOSSUpdateFileName( TYPE_RomOSS_CHR, sc_FilePath[1], sizeof( sc_FilePath[1] ) );
	pc_InternetISW->getOSSUpdateFileName( TYPE_RomOSS_NDJ, sc_FilePath[2], sizeof( sc_FilePath[2] ) );
	pc_InternetISW->getOSSUpdateFileName( TYPE_RomOSS_UPL, sc_FilePath[3], sizeof( sc_FilePath[3] ) );
	uchar i = 0, j = 0;
	for( i=0; i<(sizeof(sc_FilePath)/sizeof(sc_FilePath[0])); i++ ) {
		for( j=0; j<strlen( sc_FilePath[i] ); j++ ) {
			sc_FilePath[i][j] = ( char )tolower( sc_FilePath[i][j] );
		}
	}
	static PServiceUSBFileCheck::USBCheckFile st_usbCheckFiles[] = {
		{ 0, sc_FilePath[0], True, True },
		{ 0, sc_FilePath[1], True, True },
		{ 0, sc_FilePath[2], True, True },
		{ 0, sc_FilePath[3], True, True },
	};
	static PDisplayParts* pc_USBCheckShowEnableParts[] ={
		&Key_ServiceOSSUpdateStart,
		&Txt_ServiceOSSUpdateDownArrow,
	};
	gp_ServiceUSBFileCheck.setCheckFiles( st_usbCheckFiles, sizeof(st_usbCheckFiles) / sizeof(st_usbCheckFiles[0]), False );
	gp_ServiceUSBFileCheck.setUSBStatusText(&Txt_ServiceOSSUpdateDispMsg);
	gp_ServiceUSBFileCheck.setShowEnableParts( pc_USBCheckShowEnableParts, sizeof(pc_USBCheckShowEnableParts)/sizeof(PDisplayParts*) );

	turnGamen = &gp_ServiceMFPUpdateMenu;
}

// ===============================================================================================.
/**
 * @name	PServiceOSSUpdate::setupGamen().
 * @brief	表示部品のセットアップ.
 * @param	short ss_Option		オプション値.
 * @author	2017/03/03 motohashi RQ-676 OSS単独更新	新規作成.
 */
// 2018/11/09 SCD2-Sky Kawanishi [SecV4][EagleH][RQ-676]AR1066658/1066878 結果NG表示追加.
// ===============================================================================================.
void PServiceOSSUpdate::setupGamen( short ss_Option )
{
	PServiceNoFunctionCodeCom::setupGamen( ss_Option );

	if( False != m_bl_UpdateStart ) {
		if ( False == m_bl_UpdateFailured ) {
			Txt_ServiceOSSUpdateDispMsg.changeText( s_MSG_ServINetIswDownloadRestartX60Y4 );
		} else {
			Txt_ServiceOSSUpdateDispMsg.changeText( s_ServiceResultNG );
		}
		Txt_ServiceOSSUpdateDispMsg.showEnable( True );
	} else {
		gp_ServiceUSBFileCheck.checkAndShow();
	}
}

// ===============================================================================================.
/**
 * @name	PServiceOSSUpdate::procButtonOn().
 * @brief	ボタン押下処理.
 * @param	short ss_Option		オプション値.
 * @author	2017/03/03 motohashi RQ-676 OSS単独更新	新規作成.
 */
// ===============================================================================================.
void PServiceOSSUpdate::procButtonOn( uchar uc_Option )
{
	if( False != m_bl_UpdateStart ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}

	if( BTNID_SERV_OSSUPDATE_START == uc_Option ) {
		APIC_InternetISW*	pc_InternetISW = APIC_InternetISW::newInstance();
		if( NULL == pc_InternetISW ) {
			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, 3, "Assert Failed!" ); 
			return;
		}

		if( False != pc_InternetISW->req_OSSUpdate(ans_OSSUpdate) ) {
			Key_ServiceOSSUpdateStart.select( True );
			m_bl_UpdateStart = True;
		} else {
			MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
		}
	} else {
		PServiceNoFunctionCodeCom::procButtonOn( uc_Option );
	}
}

