// APIC_InternetISW::req_OSSUpdate()のコールバック関数.
// 2018/11/09 SCD2-Sky Kawanishi [SecV4][EagleH][RQ-676]AR1066658/1066878 結果NG表示追加.
void PServiceOSSUpdate::ans_OSSUpdate(Bool bl_result)
{
	// 仕様上、結果OKでコールバックが返ってくることはない.
	if (False == bl_result) {
		CallBackIndi(TYPE_PNL_CallBack_req_OSSUpdateFailed);
	}
}

// コールバック処理.
// 2018/11/09 SCD2-Sky Kawanishi [SecV4][EagleH][RQ-676]AR1066658/1066878 結果NG表示追加.
void PServiceOSSUpdate::procCallBack(TYPE_PNL_CallBack e_option)
{
	if (TYPE_PNL_CallBack_req_OSSUpdateFailed == e_option) {
		m_bl_UpdateFailured = True;
		setupGamen();
	}
}

