/**
 * @name	PServiceOSSUpdatePasswordInput::~PServiceOSSUpdatePasswordInput().
 * @brief	デストラクタ.
 * @param	なし.
 * @author	2017/03/03 motohashi RQ-676 OSS単独更新	新規作成.
 */
// ===============================================================================================.
PServiceOSSUpdatePasswordInput::~PServiceOSSUpdatePasswordInput()
{
}

// ===============================================================================================.
/**
 * @name	PServiceOSSUpdatePasswordInput::startGamen().
 * @brief	画面開始.
 * @param	なし.
 * @author	2017/03/03 motohashi RQ-676 OSS単独更新	新規作成.
 */
// ===============================================================================================.
void PServiceOSSUpdatePasswordInput::startGamen()
{
	PServiceNoFunctionCodeCom::startGamen();

	// 変数の初期化.
	m_e_PasswordCheckResult = TYPE_PasswordCheckResult_OK;
	memset( m_sc_InputPassword, 0, sizeof(m_sc_InputPassword) );

	// 表示領域に文字列をセット..
	setKeyboardData(m_sc_InputPassword, (TYPD_EnableFWUpdateUSBPasswordMaxLen - 1), PNLD_ServiceOSSUpdatePasswordInputWidth );
	m_b_Password = True;

	// キーボード表示.
	Kbd_ServiceInputKeybord.setChangeEnlKeybord( PLBD_Enl_KBD_Initial );
// comment 2019/03/11 【HCLT-Tarun】【IT6_EagleH】【 OP_BTS-1848 】	Disabling arrow key.
//	Kbd_ServiceInputKeybord = PLBC_ConvertKeybord( PLBD_KBT_ASCII_S, 32, 192, True, True );
	Kbd_ServiceInputKeybord = PLBC_ConvertKeybord( PLBD_KBT_ASCII_S, 32, 192, False, True );

	// カーソルクラスへパーツポインタを渡す.
	Kbd_ServiceInputKeybord.GetCursor( m_pc_DispField );
	startGamenKeybordService9E();
	
// comment 2019/03/11 【HCLT-Tarun】【IT6_EagleH】【 OP_BTS-1848 】	hiding extra key display in japaneesh language.
	Kbd_ServiceInputKeybord.setKeybord5Country( True );

	// パス入力選択クラス.
	m_c_SlideTextMgr.setSelectProc( m_b_Password );
	m_c_SlideTextMgr.initStatus(m_sc_StrKeyboard);
	m_c_SlideTextMgr.setStatus( False );

	// スライド文字列管理クラスの初期化.
	m_c_SlideTextMgr.init_CLCD( m_sc_StrKeyboard, m_sc_KeyboardWidth, m_ss_MaxInputNum, m_pc_DispField, m_e_CharSet );

	turnGamen = &gp_ServiceMFPUpdateMenu;
}

// ===============================================================================================.
/**
 * @name	PServiceOSSUpdatePasswordInput::setupGamen().
 * @brief	画面更新.
 * @param	short ss_Option	オプション値.
 * @author	2017/03/03 motohashi RQ-676 OSS単独更新	新規作成.
 */
// ===============================================================================================.
void PServiceOSSUpdatePasswordInput::setupGamen( short ss_Option )
{
	// 親クラスの画面セットアップをコールする.
	PServiceNoFunctionCodeCom::setupGamen( ss_Option );

	// キーボードセットアップ.
	PServiceNoFunctionCodeCom::setupGamenKeybordService();

	// キーボードの表示.
	Kbd_ServiceInputKeybord.showKeybord();

	// キーボードの種類を取得する.
	KeybordType ec_KeybordType = Kbd_ServiceInputKeybord.getKeybordType();

	// 日本語入力の場合は未確定文字列表示用にスライド処理を行う.
	m_c_SlideTextMgr.PreStringSlideControl( m_sc_StrKeyboard, ec_KeybordType );
	m_c_SlideTextMgr.drawStr(m_sc_StrKeyboard);

	m_c_SlideTextMgr.setInsertCharLenCheck( TYPE_InsertCharLenStrUTF8 );

	switch( m_e_PasswordCheckResult ) {
	case TYPE_PasswordCheckResult_NG_Mismach:
		Txt_ServiceOSSUpdatePasswordInputMsg.changeText( s_SSCEAttestMisstakeMessage );
		break;
	case TYPE_PasswordCheckResult_NG_Agreement:
		Txt_ServiceOSSUpdatePasswordInputMsg.changeText( s_SSNewPassWordMissteke );
		break;
	default:
		Txt_ServiceOSSUpdatePasswordInputMsg.changeText( s_SSCEAttestMessage );
		break;
	}
}

// ===============================================================================================.
/**
 * @name	PServiceOSSUpdatePasswordInput::procReset().
 * @brief	Resetキー押下.
 * @param	uchar uc_Option	オプション値.
 * @author	2018/11/13 SCD2-motohashi [RQ-676][AR1066611] Resetキーは5秒間ペナルティ中は受付禁止.
 */
// ===============================================================================================.
void PServiceOSSUpdatePasswordInput::procReset( uchar uc_Option )
{
	if( TYPE_PasswordCheckResult_OK != m_e_PasswordCheckResult ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );					// ブザー音セット.
		return;
	}

	PServiceNoFunctionCodeCom::procReset( uc_Option );
}

// ===============================================================================================.
/**
 * @name	PServiceOSSUpdatePasswordInput::proc10Key().
 * @brief	テンキー押下.
 * @param	uchar uc_Option	オプション値.
 * @author	2017/03/03 motohashi RQ-676 OSS単独更新	新規作成.
 */
// ===============================================================================================.
void PServiceOSSUpdatePasswordInput::proc10Key( uchar uc_Option )
{
	if( TYPE_PasswordCheckResult_OK != m_e_PasswordCheckResult ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );					// ブザー音セット.
		return;
	}

	char _sc_Num[ 3 ];
	memset( _sc_Num, 0, sizeof(_sc_Num) );
	Kbd_ServiceInputKeybord.proc10Key( &uc_Option );

	// 最大入力長まで行っているならば入力しない.
	if ( m_ss_MaxInputNum <= (ushort)strlen( m_sc_StrKeyboard ) ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );					// ブザー音セット.
		return;
	}

	// 入力されたのが0-9キーの時のみ処理を受け付ける.
	if ( 9 >= uc_Option ) {
		sprintf((char*)_sc_Num, "%d", uc_Option);
		m_c_SlideTextMgr.insertStr( m_sc_StrKeyboard, (char*)_sc_Num );
	}

	// 画面セットアップ.
	setupGamen();
}

// ===============================================================================================.
/**
 * @name	PServiceOSSUpdatePasswordInput::procShrp().
 * @brief	＃キー押下.
 * @param	uchar uc_Option	オプション値.
 * @author	2018/11/13 SCD2-motohashi [RQ-676][AR1066611] Sharp/Asterキーは受付.
 */
// ===============================================================================================.
void PServiceOSSUpdatePasswordInput::procShrp( uchar uc_Option )
{
	if( TYPE_PasswordCheckResult_OK != m_e_PasswordCheckResult ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );					// ブザー音セット.
		return;
	}

	// 最大入力長まで行っているならば入力しない.
	if ( m_ss_MaxInputNum <= (ushort)strlen( m_sc_StrKeyboard ) ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );					// ブザー音セット.
		return;
	}

	// アルファベットの時は受け付けない.
	if( True == Kbd_ServiceInputKeybord.b_KeybordAlphabetMode ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );					// ブザー音セット.
		return;
	}

	char	sc_Key[ 3 ];
	snprintf( sc_Key, sizeof(sc_Key), "#" );
	m_c_SlideTextMgr.insertStr( m_sc_StrKeyboard, sc_Key );

	// 画面セットアップ.
	setupGamen();
}

