// ===============================================================================================.
/**
 * @name	PServiceOSSUpdatePasswordInput::procClear().
 * @brief	クリアキー押下.
 * @param	uchar uc_Option	オプション値.
 * @author	2017/03/03 motohashi RQ-676 OSS単独更新	新規作成.
 */
// ===============================================================================================.
void PServiceOSSUpdatePasswordInput::procClear( uchar uc_Option )
{
	if( TYPE_PasswordCheckResult_OK != m_e_PasswordCheckResult ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}

	// 未確定文字が無い場合.
	if ( NULL == Kbd_ServiceInputKeybord.c_PreString[0] ) {
		if( 0 == strlen(m_sc_StrKeyboard) ) {	
			MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
		}

		// 文字列の初期化.
		memset( m_sc_StrKeyboard, 0, sizeof(m_sc_StrKeyboard) );
		Kbd_ServiceInputKeybord.GetCursor(m_pc_DispField);

		// 入力中状態に変更.
		m_c_SlideTextMgr.setStatus( False );

		// スライド文字列管理クラスの初期化.
		m_c_SlideTextMgr.init_CLCD( m_sc_StrKeyboard, m_sc_KeyboardWidth, m_ss_MaxInputNum, m_pc_DispField, getCharSetForPanel() );
	} else {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
	}

	// 画面セットアップ.
	setupGamen();
}

// ===============================================================================================.
/**
 * @name	PServiceOSSUpdatePasswordInput::procKeyBoard().
 * @brief	キーボードキー押下.
 * @param	uchar uc_Option	オプション値.
 * @author	2017/03/03 motohashi RQ-676 OSS単独更新	新規作成.
 */
// ===============================================================================================.
void PServiceOSSUpdatePasswordInput::procKeyBoard( uchar uc_Option )
{
	if( TYPE_PasswordCheckResult_OK != m_e_PasswordCheckResult ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}

	// カーソルキー一処理.
	Kbd_ServiceInputKeybord.procCursorPosition( (char *)&m_c_SlideTextMgr, m_sc_StrKeyboard, uc_Option, True );

	// 画面セットアップ.
	setupGamen();
}

// ===============================================================================================.
/**
 * @name	PServiceOSSUpdatePasswordInput::procButtonOn().
 * @brief	ボタン押下.
 * @param	uchar uc_Option	オプション値.
 * @author	2017/03/03 motohashi RQ-676 OSS単独更新	新規作成.
 */
// ===============================================================================================.
void PServiceOSSUpdatePasswordInput::procButtonOn( uchar uc_Option )
{
	if( TYPE_PasswordCheckResult_OK != m_e_PasswordCheckResult ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}

	procButtonOnKeybordService( uc_Option );

	// 画面セットアップ.
	setupGamen();
}

// ===============================================================================================.
/**
 * @name	PServiceOSSUpdatePasswordInput::procOk().
 * @brief	OKキー押下.
 * @param	uchar uc_Option	オプション値.
 * @author	2017/03/03 motohashi RQ-676 OSS単独更新	新規作成.
 */
// 変更履歴 :2019/10/30 Sky大嶋 [セキュリティ技術v5][RQ824] パスワード規約拡張 API変更.
// ===============================================================================================.
void PServiceOSSUpdatePasswordInput::procOk( uchar uc_Option )
{
	if( TYPE_PasswordCheckResult_OK != m_e_PasswordCheckResult ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}

	APIC_SystemSetting* pc_SystemSetting = PnlComGetSystemSetting();
	if( NULL == pc_SystemSetting ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, 3, "Assert Failed!" );
		return; 
	}

	getKeyboardData( m_sc_InputPassword );
//	m_e_PasswordCheckResult = pc_SystemSetting->checkFWUpdatePassword( m_sc_InputPassword );
	m_e_PasswordCheckResult = pc_SystemSetting->verifyFwUpdatePwd( m_sc_InputPassword );
	if( TYPE_PasswordCheckResult_OK == m_e_PasswordCheckResult ) {
		nextGamen = &gp_ServiceOSSUpdate;
	} else {
		// 文字列の初期化.
		memset( m_sc_StrKeyboard, 0, sizeof(m_sc_StrKeyboard) );
		Kbd_ServiceInputKeybord.GetCursor(m_pc_DispField);

		// 入力中状態に変更.
		m_c_SlideTextMgr.setStatus( False );

		// スライド文字列管理クラスの初期化.
		m_c_SlideTextMgr.init_CLCD( m_sc_StrKeyboard, m_sc_KeyboardWidth, m_ss_MaxInputNum, m_pc_DispField, getCharSetForPanel() );

		setupGamen();
	}
}

// ===============================================================================================.
/**
 * @name	PServiceOSSUpdatePasswordInput::procGoToMag().
 * @brief	ラインキー押下.
 * @param	uchar uc_Option	オプション値.
 * @author	2017/03/03 motohashi RQ-676 OSS単独更新	新規作成.
 */
// ===============================================================================================.
void PServiceOSSUpdatePasswordInput::procGoToMag( uchar uc_Option )
{
	if( TYPE_PasswordCheckResult_OK != m_e_PasswordCheckResult ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}

	PServiceNoFunctionCodeCom::procGoToMag( uc_Option );
}

// ===============================================================================================.
/**
 * @name	PServiceOSSUpdatePasswordInput::procGoToPage().
 * @brief	画面遷移処理.
 * @param	uchar uc_Option	オプション値.
 * @author	2017/03/03 motohashi RQ-676 OSS単独更新	新規作成.
 */
// ===============================================================================================.
void PServiceOSSUpdatePasswordInput::procGoToPage( uchar uc_Option )
{
	if( TYPE_PasswordCheckResult_OK != m_e_PasswordCheckResult ) {
		MCR_setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}

	switch( uc_Option ) {
	case 60:		// キャンセルキー. 
		nextGamen = &gp_ServiceMFPUpdateMenu;
		break;
	default:
		break;
	}
}

// ===============================================================================================.
/**
 * @name	PServiceOSSUpdatePasswordInput::procSecond().
 * @brief	1秒タイマ.
 * @param	uchar uc_Option	オプション値.
 * @author	2017/03/03 motohashi RQ-676 OSS単独更新	新規作成.
 */
// ===============================================================================================.
void PServiceOSSUpdatePasswordInput::procSecond( uchar uc_Option )
{
	PServiceNoFunctionCodeCom::procSecond( uc_Option );

	static uchar uc_TimerCount = 0;
	if( TYPE_PasswordCheckResult_OK != m_e_PasswordCheckResult ) {
		uc_TimerCount++;
		if( 5 < uc_TimerCount ) {
			m_e_PasswordCheckResult = TYPE_PasswordCheckResult_OK;
			uc_TimerCount = 0;
		}
	}
}

// ===============================================================================================.
/**
 * @name	PServiceOSSUpdatePasswordInput::setKeyboardData().
 * @brief	キーボード設定処理.
 * @param	char*	psc_InputData	キーボード初期値.
 * @param	short	ss_InputMax		最大入力バイト数.
 * @param	char	sc_InputWidth	最大入力幅.
 * @author	2017/03/03 motohashi RQ-676 OSS単独更新	新規作成.
 */
// ===============================================================================================.
void PServiceOSSUpdatePasswordInput::setKeyboardData(char* psc_InputData, short ss_InputMax, char sc_InputWidth)
{
	if( NULL == psc_InputData ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, 3, "Assert Failed!" );
		return;
	}
	memset( m_sc_StrKeyboard, 0 ,sizeof( m_sc_StrKeyboard ));
	strncpy( m_sc_StrKeyboard, psc_InputData, ( sizeof( m_sc_StrKeyboard ) - 1 ) );
	m_ss_MaxInputNum = ss_InputMax;
	m_sc_KeyboardWidth= sc_InputWidth;
}

// ===============================================================================================.
/**
 * @name	PServiceOSSUpdatePasswordInput::getKeyboardData().
 * @brief	キーボード設定処理.
 * @param	char*	psc_OutputData	文字列格納先バッファ.
 * @author	2017/03/03 motohashi RQ-676 OSS単独更新	新規作成.
 */
// ===============================================================================================.
char* PServiceOSSUpdatePasswordInput::getKeyboardData(char* psc_OutputData)
{
	if( NULL == psc_OutputData ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, 3, "Assert Failed!" );
		return psc_OutputData;
	}
	strcpy( psc_OutputData, m_sc_StrKeyboard );

	return psc_OutputData;
}

