// comment 2022/10/31 FPT.DungDV14 [IT6_2.3] [RQ-942] Get record of Media Detection History.
#define SIZE_MediaDetectData 110	// データを一件表示するのに必要な文字列の大きさ.
#define SIZE_MediaDetectDataMax 20  // 時系列データの最大件数.
// Comment 2023/03/22 FPT-LinhNV46【IT6_2.3】【OP_BTS-42439】アクティブ検知履歴に再生紙が表示されない.
static TEXT_ID PaperTypeCode2Text( TYPE_PaperType e_PaperType, TYPE_CustomPaperType e_CustomPaperType )
{
	switch( e_PaperType ) {
		case TYPE_PaperPostCard:			return	s_KEYServicePostCard ;						// はがき.
		case TYPE_PaperTypeColor:			return	s_pKEYServiceColoredPaper_W080H016I ;		// 色紙.
		case TYPE_PaperTypeEnvelope:		return	s_KEYServiceEnvelope ;						// 封筒.
		case TYPE_PaperTypeGloss1:			return	s_ITMServiceGloss1 ;						// 光沢紙1.
		case TYPE_PaperTypeGloss1Plus:		return	s_ITMServiceGloss1Plus ;					// 光沢紙1+.
		case TYPE_PaperTypeGloss2:			return	s_ITMServiceGloss2 ;						// 光沢紙2.
		case TYPE_PaperTypeIndex:			return	s_pITMServiceIndexPaper_W128H016I ;			// インデックス紙.
		case TYPE_PaperTypeLabel:			return	s_ITMServiceLabel ;							// ﾗﾍﾞﾙ紙.
		case TYPE_PaperTypeLetterHead:		return	s_ITMServiceLetterHead ;					// レターヘッド紙.
		case TYPE_PaperTypeNormal:
		case TYPE_PaperTypeNormal_2nd:
			if( e_CustomPaperType == TYPE_CustomPaperType20 ){
				return s_pRecyclePaper_W128H016I;												// 再生紙.
			} else {
				return s_pPaperNormal_W096H016I;												// 普通紙.
			}
		case TYPE_PaperTypeNormalPlus:
		case TYPE_PaperTypeNormalPlus_2nd:	return	s_pITMServiceNormalPaperPlus_W056H016I ; 	// 普通紙+.
		case TYPE_PaperTypeOHP:				return	s_OHP ;										// OHPフィルム.
		case TYPE_PaperTypeSpecial1:		return	s_pITMServiceSpecialPaper_W128H016I ;		// 特殊紙.
		case TYPE_PaperTypeThick1:
		case TYPE_PaperTypeThick1_2nd:		return	s_HeavyStock1 ;					// 厚紙1.
		case TYPE_PaperTypeThick1Plus:
		case TYPE_PaperTypeThick1Plus_2nd:	return	s_KEYServiceThick1Plus ;		// 厚紙1+.
		case TYPE_PaperTypeThick2:
		case TYPE_PaperTypeThick2_2nd:		return	s_HeavyStock2 ;					// 厚紙2.
		case TYPE_PaperTypeThick3:
		case TYPE_PaperTypeThick3_2nd:		return	s_HeavyStock3 ;					// 厚紙3.
		case TYPE_PaperTypeThick4:
		case TYPE_PaperTypeThick4_2nd:		return	s_KEYHeavyStock4 ;				// 厚紙4.
		case TYPE_PaperTypeThin_2nd:
		case TYPE_PaperTypeThin1:			return	s_pLightPaper_W128H016I ;		// 薄紙.
		case TYPE_PaperTypeUser1:
		case TYPE_PaperTypeUser1_2nd:		return	s_KEYUserPaper1X10Y1 ;			// ユーザー紙1.
		case TYPE_PaperTypeUser2:
		case TYPE_PaperTypeUser2_2nd:		return	s_KEYUserPaper2X10Y1 ; 			// ユーザー紙2.
		case TYPE_PaperTypeUser3:
		case TYPE_PaperTypeUser3_2nd:		return	s_KEYUserPaper3X10Y1 ; 			// ユーザー紙3.
		case TYPE_PaperTypeUser4:
		case TYPE_PaperTypeUser4_2nd:		return	s_KEYUserPaper4X10Y1 ;			// ユーザー紙4.
		case TYPE_PaperTypeUser5:
		case TYPE_PaperTypeUser5_2nd:		return	s_KEYUserPaper5X10Y1 ;			// ユーザー紙5.
		case TYPE_PaperTypeUser6:
		case TYPE_PaperTypeUser6_2nd:		return	s_KEYUserPaper6X10Y1 ;			// ユーザー紙6.
		case TYPE_PaperTypeUser7:
		case TYPE_PaperTypeUser7_2nd:		return	s_pKEYUserPaper7_W080H016I ;	// ユーザー紙7.
		default:							return	s_ServiceResultBlank ;			// 未選択.
	}
	return	s_ServiceResultBlank ;	// 未選択.
}

// トレイの文字列取得関数.
static TEXT_ID FeedTrayCode2Text( TYPE_FeedTray e_FeedTray )
{
	switch( e_FeedTray ) {
		case TYPE_FeedTrayManual:	return	s_ManService ;			// 手差し.
		case TYPE_FeedTray1:		return	s_1stService ;			// トレイ1.
		case TYPE_FeedTray2:		return	s_2ndService ;			// トレイ2.
		case TYPE_FeedTray3:		return	s_3rdService ;			// トレイ3.
		case TYPE_FeedTray4:		return	s_4thService ;			// トレイ4.
#ifndef DEF_DenebMLKCus
		case TYPE_FeedTray5:		return	s_EXPServiceLCT ;		// LCT.
#else
		case TYPE_FeedTray5:		return	s_pKEY5thService1_W056H016I ;		// トレイ4.
#endif //DEF_DenebMLKCus.
		case TYPE_FeedTrayPI1:		return	s_PI1TrayService ;		// PIトレイ１	FS110m/FS210m/FS120mフィニッシャーに、オプションのPI110カバーシートフィーダが装着されている時有効.
		case TYPE_FeedTrayPI2:		return	s_PI2TrayService ;		// PIトレイ２	FS110m/FS210m/FS120mフィニッシャーに、オプションのPI110カバーシートフィーダが装着されている時有効.
		case TYPE_FeedTrayUnselect:
		default:					return	s_ServiceResultBlank ;	// 未選択.
	}
	return	s_ServiceResultBlank ;	// 未選択.
}
// ===============================================================================================.
/**
 * @name	PP3B9290000.
 * @brief	初期設定.
 * @author	2022/10/06 FPT.DungDV14 [IT6_2.3][RQ-942]紙種自動検知.
 */
// ===============================================================================================.
void PP3B9290000::startGamen()
{
	PServiceToStateConfirmMenuCom::startGamen();	// カウンタ共通初期化.
	ss_MaxDataAmountInPage = 7;	// １ページに表示できるデータ数.
	ss_PageNumMax = static_cast<short>( ( SIZE_MediaDetectDataMax / ss_MaxDataAmountInPage ) + 2 );	// 最大ページ数.
	ss_PageNum = 1;		// 最初は1ページ目.
	ss_TotalDataNum = 0; // 時系列データの最新データ番号.
// comment 2022/11/26 FPT.ThanhLH11 [IT6_2.3][ALL MACHINE][Klocwork]NPD.GEN.MIGHT.
	// TYPS_MediaDetectionHistoryRecords* ps_MediaDetectionHistoryRecords = NULL;
	// ss_TotalDataNum = PnlComGetSystemSetting()->getMediaDetectionHistory( ps_MediaDetectionHistoryRecords );
	ss_TotalDataNum = PnlComGetSystemSetting()->getMediaDetectionHistory( &m_s_MediaDetectionHistoryRecords );

	// 最終ページを計算で求める.
	if( ss_TotalDataNum < SIZE_MediaDetectDataMax ) {
		if( ( ( ss_TotalDataNum % ss_MaxDataAmountInPage ) == 0 ) && ( ss_TotalDataNum != 0 ) ) {
			ss_PageNumMax = static_cast<short>( ( ss_TotalDataNum / ss_MaxDataAmountInPage ) + 1 );	// 最大ページ数.
		} else {
			ss_PageNumMax = static_cast<short>( ( ss_TotalDataNum / ss_MaxDataAmountInPage ) + 2 );	// 最大ページ数.
		}	
	}
	
}

// ===============================================================================================.
/**
 * @name	PP3B9290000.
 * @brief	ボタン（押された）.
 * @author	2022/10/06 FPT.DungDV14 [IT6_2.3][RQ-942]紙種自動検知.
 */
// ===============================================================================================.
void PP3B9290000::procButtonOn( uchar option )
{
	switch( option ) {
		case 20:  // 「↑」キー.
			if( 1 < ss_PageNum ) {
				ss_PageNum--;		// 前ページにする.
			} else {
				ss_PageNum = ss_PageNumMax;	//最終ページにする.
			}
			break;
		case 21:  // 「↓」キー.
			if( ss_PageNum < ss_PageNumMax ) {
				ss_PageNum++;	// 次ページにする.
			} else {
				ss_PageNum = 1;	// 1ページ目にする.
			}
			break;
		default:
			break;
	}
}

